(window.GIM_TP=window.GIM_TP||{})["Z.Introduction.0"]={"from":0,"a":[[["רִבִּי חִזְקִיָּה פָּתַח, כְּתִיב, (שיר השירים ב׳:ב׳) (פנחס רלג, ופ' תשא קפט) כְּשׁוֹשַׁנָּה בֵּין הַחוֹחִים. מָאן שׁוֹשַׁנָּה, דָּא כְּנֶסֶת יִשְׂרָאֵל. (בגין דאית שושנה ואית שושנה), מַה שּׁוֹשַׁנָּה דְּאִיהִי בֵּין הַחוֹחִים אִית בַּהּ סוּמָק וְחִוָּר, אוּף כְּנֶסֶת יִשְׂרָאֵל אִית בַּהּ דִּין וְרַחֲמֵי. מַה שּׁוֹשַׁנָּה אִית בַּהּ תְּלֵיסַר עָלִין, אוּף כְּנֶסֶת יִשְׂרָאֵל אִית בַּהּ תְּלֵיסַר מְכִילָן דְּרַחֲמֵי דְּסַחֲרִין לַהּ מִכָּל סִטְרָהָא. אוּף אֱלהִים דְּהָכָא (נשא דף קלא ב, וקלח, וקמז) (שמות קפו א) מִשַׁעְתָּא דְּאִדְכַּר אַפִּיק תְּלֵיסַר תֵּיבִין לְסַחֲרָא לִכְנְסֶת יִשְׂרָאֵל וּלְנַטְרָא לַהּ.","וּלְבָתַר אִדְכַּר זִמְנָא אָחֳרָא. אַמַּאי אִדְכַּר זִמְנָא אָחֳרָא. בְּגִין לְאַפְקָא חָמֵשׁ עָלִין תַּקִּיפִין דְּסַחֲרִין לְשּׁוֹשַׁנָּה. (פנחס רלג וצ\"ע בקז א), וְאִנּוּן חָמֵשׁ אִקְרוּן יְשׁוּעוֹת. וְאִנּוּן חָמֵשׁ [חַמְשין] תַּרְעִין. וְעַל רָזָא דָא כְּתִיב (תהילים קט״ז:י״ג) (תרומה קס\"ט) כּוֹס יְשׁוּעוֹת אֶשָּׂא דָּא כּוֹס שֶׁל בְּרָכָה. כּוֹס שֶׁל בְּרָכָה אִצְטְרִיךְ לְמֶהֱוֵי עַל חָמֵשׁ אֶצְבְּעָן וְלָא יַתִּיר. כְּגַוְונָא דְּשׁוֹשַׁנָּה דְּיָתְבָא עַל חָמֵשׁ עָלִין תַּקִּיפִין דּוּגְמָא דְחָמֵשׁ אֶצְבְּעָן. וְשׁוֹשַׁנָּה דָא אִיהִי (תרומה קלא) כּוֹס שֶׁל בְּרָכָה. מֵאֱלהִים תִּנְיָנָא עַד אֱלהִים תְּלִיתָאָה חָמֵשׁ תֵּיבִין. מִכָּאן וּלְהָלְאָה אוֹר דְּאִתְבְּרֵי וְאִתְגְּנִיז וְאִתְכְּלִיל בְּבְּרִית הַהוּא דְּעָאל בְּשּׁוֹשַׁנָּה (ס\"א דא) וְאַפִּיק בַּהּ זַרְעָא. וְדָא אִקְרֵי עֵץ עוֹשֶׂה (סב ב) פְּרִי אֲשֶׁר זַרְעוֹ בוֹ. וְהַהוּא זֶרַע קַיָּימָא בְּאוֹת בְּרִית מַמָּשׁ.","וּכְמָה דְדִיּוּקְּנָא דִבְרִית אִזְדְּרַע בְּאַרְבְּעִין וּתְרֵין זִוּוּגִין הַהוּא (נ\"א דההוא) זַרְעָא, כָּךְ אִזְדְּרַע שְׁמָא גְלִיפָא מְפָרַשׁ בְּאַרְבְּעִין וּתְרֵין אַתְוָן דְּעוֹבָדָא דִּבְרֵאשִׁית.","בְּרֵאשִׁית, רִבִּי שִׁמְעוֹן פָּתַח (שיר השירים ב׳:י״ב) (צז א, לט ע\"ב, ויקרא ד ב, לקמן ה) הַנִּצָּנִים נִרְאוּ בָאָרֶץ. הַנִּצָּנִים, דָּא עוֹבָדָא דִּבְרֵאשִׁית, נִרְאוּ בָאָרֶץ אֵימָתַי, בַּיּוֹם הַשְּׁלִישִׁי, דִּכְתִיב וַתּוֹצֵא הָאָרֶץ כְּדֵין נִרְאוּ בָאָרֶץ. עֵת הַזָּמִיר הִגִּיעַ, דָּא יוֹם רְבִיעִי דְּהֲוָה בֵּיהּ זְמִיר עָרִיצִים, מְאֹרֹת חָסֵר. וְקוֹל הַתּוֹר, דָּא יוֹם חֲמִישִׁי, דִּכְתִיב יִשְׁרְצוּ הַמַּיִם וְגו' לְמֶעְבַּד תּוֹלָדוֹת. נִשְׁמַע, דָּא יוֹם שִׁשִּׁי דִּכְתִיב נַעֲשֶׂה אָדָם. דְּהֲוָה עָתִיד לְמִקְדַּם עֲשִׂיָּה לִשְׁמִיעָה, דִּכְתִיב הָכָא נַעֲשֶׂה אָדָם, וּכְתִיב הָתָם נַעֲשֶׂה וְנִשְׁמַע. בְּאַרְצֵנוּ, דָּא יוֹם שַׁבָּת דְּאִיהוּ דּוּגְמַת אֶרֶץ הַחַיִּים."],[[0,"","א) \u0003ר' חזקיה פתח\u0004 וכו': ר' חזקיה פתח, כתוב, כשושנה בין החוחים. שואל מהי שושנה. ומשיב, זו היא כנסת ישראל. שהיא מלכות. משום שיש שושנה ויש שושנה. מה שושנה בין החוחים יש בה אדום ולבן אף כנסת ישראל יש בה דין ורחמים. מה שושנה יש בה י\"ג עלים, כך כנסת ישראל יש בה י\"ג מדות הרחמים המסבבות אותה מכל צדדיה. אף אלקים, שבמקרא שבכאן דהיינו בראשית ברא \u0003אלקים\u0004, משעה שנזכר, הוציא י\"ג מלים לסבב את כנסת ישראל ולשמרה. שהן: את, השמים, ואת, הארץ, והארץ, היתה, תהו, ובהו, וחשך, על, פני, תהום, ורוח. דהיינו עד אלקים מרחפת וגו'."],[0,"","ביאור הדברים, עשר ספירות הן, כתר, חכמה, בינה, חסד, גבורה, תפארת, נצח, הוד, יסוד ומלכות. ועיקרן הוא רק חמש, כתר, חכמה, בינה, תפארת ומלכות, משום שספירת התפארת כוללת בתוכה שש ספירות חג\"ת נה\"י. והן נעשו חמש פרצופין: א\"א, ואו\"א, וזו\"ן. הכתר נק' בשם אריך אנפין. חכמה ובינה נק' בשם אבא ואמא. ת\"ת ומלכות, נק' בשם זעיר אנפין ונוקבא. (ביאורן של עשר הספירות עי' בפתיחה לחכמת הקבלה אות ה')."],[0,"","ודע, שסוד ז' ימי בראשית ה\"ס ב' הפרצופין ז\"א ונוקבא דאצילות, שיש בהם ז' ספירות חג\"ת נה\"י ומלכות, כנ\"ל. אשר באלו הכתובים דמעשה בראשית מתבאר, איך אבא ואמא, שהם חו\"ב, האצילו אותם מתחילת התהוותם עד סוף הגדלות, שנוהג בהם בהמשך שתא אלפי שני. וענין זה מתבאר והולך כאן בזוהר בראשית."],[0,"","ור' חזקיה פתח בביאור הנוקבא דז\"א, לבאר סדר אצילותה מאמא, שהיא הבינה הנק' בשם אלהים. וזהו שפתח בביאור השושנה, שהיא הנוקבא דז\"א. והנוקבא דז\"א בעת גדלותה נקראת בשם כנסת ישראל, כמ\"ש להלן, וזהו שאומר, \u0003מָאן שׁוֹשַׁנָּה, דָּא כְּנֶסֶת יִשְׂרָאֵל\u0004 (מהי שושנה, זו היא כנסת ישראל)."],[0,"","ויש בשושנה זו ב' מצבים: מצב של קטנות, דהיינו של תחלת התהוותה, שאז אין בה אלא ספי' אחת כתר, שבתוכה מלובש אור הנפש שלה, וט' הספירות התחתונות שלה נבחנות כנופלות לבר מאצילות. והן בעולם הבריאה. ועוד בה מצב של גדלות, שאז מתעלות ט\"ס התחתונות שלה מן עולם הבריאה אל עולם האצילות, והיא נבנית עמהן לפרצוף שלם בעשר ספירות. ואז עולה עם ז\"א בעלה לקומה שוה עם או\"א דאצילות ומלבישים אותם. ואז נק' ז\"א, בשם ישראל. שהוא אותיות לי ראש, והנוקבא נק' בשם כנסת ישראל, על שם שכונסת בתוכה כל האורות של ישראל בעלה שהיא משפעת אותם אל התחתונים."],[0,"","והמצב של הקטנות נק' בשם שושנה בין החוחים, משום שט\"ס התחתונות שלה נתרוקנו מאור האצילות, ונשארו כחוחים. והמצב של הגדלות נק' בשם שושנה סתם, או כנסת ישראל. וזה \u0003אמרו אִית שׁוֹשַׁנָּה וְאִית שׁוֹשַׁנָּה\u0004 (יש שושנה ויש שושנה)."],[0,"","והנה גוון סומק מורה שיש שם אחיזה לחיצונים,ולקליפות לינק ממנה, וזהו בזמן המצב של הקטנות, שט\"ס התחתונות שלה הן בבריאה, ויש בה ג\"כ בחינת חוור, דהיינו בכלי דכתר שלה, שאין שם אחיזה לחיצונים. וז\"ש \u0003מַה שּׁוֹשַׁנָּה דְּאִיהִי בֵּין הַחוֹחִים אִית בַּהּ סוּמָק וְחִוָּור, אוּף כְּנֶסֶת יִשְׂרָאֵל אִית בַּהּ דִּין וְרַחֲמֵי\u0004 (מה שושנה בין החוחים יש בה אדום ולבן אף כנסת ישראל יש בה דין ורחמים), להורות כי גם בגדלותה בעת שנקראת כנסת ישראל, אע\"פ שעולה אז ומלבישה את הבינה במצב גדלותה כנ\"ל, מ\"מ נשארת בה בחינת דין, כי היא נצרכת לסוד המסך המתוקן בה לצורך הזווג דהכאה, שמסבת הדין שבמסך, הוא מכה על האור העליון ומחזירו לאחוריו, ומעלה עי\"ז ע\"ס דאור חוזר הנקרא אור של דין, וממשיך בתוכן ע\"ס דאור ישר, הנקרא אור של רחמים. (עי' בפתיחה לחכמת הקבלה אות י\"ד) וע\"כ גם בכנסת ישראל אית בה דין ורחמי כנגד הסומק והחוור שיש לשושנה בין החוחים."],[0,"","וז\"ס הים שעשה שלמה, העומד על שני עשר בקר. כי אלו טה\"ס התחתונות שלה שנפלו לבריאה, כנ\"ל, נתתקנו שם בסוד שני עשר בקר, ונקודת הכתר שנשארה באצילות ה\"ס הים העומד עליהם מלמעלה, וכללותם יחד נק' תליסר \u0003עלין דשושנה\u0004. וענין ההתחלקות הזו של עה\"ס שלה לסוד י\"ג מתבאר להלן במראות הסולם."],[0,"","והנה המוחין דגדלות של הנוקבא, שיש בהם מהארת החכמה, הם נמשכים מסוד י\"ג השמות הנק' י\"ג מדות הרחמים. וז\"ש \u0003אוּף כְּנֶסֶת יִשְׂרָאֵל אִית בַּהּ תְּלֵיסַר מְכִילִין דְּרַחֲמֵי\u0004 (כך כנסת ישראל יש בה י\"ג מדות הרחמים). והעיקר מה שבא ר' חזקיה להורות בהשואה הזו משושנה דבין החוחים לכנסת ישראל, הוא ללמדנו, שכל שיש לנוקבא במצב גדלותה צריך להמצא בה כנגדן בחי' הכנה והכשר עוד בתחילת הויתה דהיינו במצב הקטנות. וז\"ש, שכנגד חוור וסומק דקטנות יוצא בה דין ורחמי בגדלות, וכנגד י\"ג עלין דקטנות יוצא בה י\"ג מדות הרחמים בגדלות. והוא מביא זאת כאן, בכדי ללמדנו איך הכתובים שלפנינו מבארים אותם ב' הסדרים דקטנות וגדלות, הנוהגים באצילות הנוקבא, כמו שממשיך והולך, אוף אלהים דהכא וכו'."],[0,"","וז\"ש, \u0003אוּף אֱלֹהִים דְּהָכָא מִשַׁעְתָּא דְּאִדְכַּר אַפִּיק תְּלֵיסַר תֵּיבִין\u0004 (אף אלקים, שבמקרא שבכאן, משעה שנזכר, הוציא י\"ג מלים): מורה, שאלהים שבמקרא דהכא בראשית ברא אלהים, שה\"ס הבינה המאצלת לנוקבא דז\"א, אפיק י\"ג מלים שהן: את השמים ואת הארץ והארץ היתה תוהו ובוהו וחושך על פני תהום ורוח, דהיינו עד אלהים תנינא, שאלו י\"ג תיבין רומזים על אותם י\"ג עלין של שושנה בין החוחים בסוד הים העומד על שני עשר בקר, כנ\"ל, שהם הכנה והכשר לכנסת ישראל שתקבל י\"ג מכילן דרחמי. וז\"ש, \u0003לְסַחֲרָא לִכְנֶסֶת יִשְׂרָאֵל וּלְנַטְרָא לַה (\u0004לסבב את כנסת ישראל ולשמרה), כי י\"ג מדות הרחמים, שהן המוחין השלמים דנוקבא, נבחנות שהן מסבבות ומאירות אליה מכל הצדדים סביב סביב, ונשמרת על ידיהן ממגע החיצונים, כי כל זמן שאין בה המוחין הגדולים בהארת החכמה מי\"ג מדות, יש בה יניקה לחיצונים."],[1,"ולבתר אדכר","וכו': ואח\"כ נזכר שם אלקים פעם אחרת, דהיינו \u0003אלקים\u0004 מרחפת וגו'. ולמה נזכר פעם אחרת. הוא כדי להוציא חמשה עלים קשים המסבבים את השושנה. ואלו חמשת העלים נקראים ישועות, והם חמשה שערים, ועל סוד זה כתוב כוס ישועות אשא, זו היא כוס של ברכה. כוס של ברכה צריכה להיות על חמש אצבעות ולא יותר, כמו השושנה היושבת על חמשה עלים קשים, שהם כנגד חמש אצבעות. ושושנה זו היא כוס של ברכה. מהשם אלקים השני עד שם אלקים השלישי חמש מלים. שהן: מרחפת על פני המים ויאמר. שהן כנגד ה' עלים הנ\"ל. מכאן ולהלאה, שנאמר, אלקים יהי אור וגו', הוא האור שנברא ונגנז ונכלל בברית ההוא שנכנס בשושנה והוציא בה זרע, וזה נקרא עץ עושה פרי אשר זרעו בו. והזרע ההוא נמצא באות ברית ממש."],[1,"","ביאור הדברים, \u0003חמש עלין תקיפין\u0004: ה\"ס ה\"ג של הנוקבא, שהן ע\"ס דאו\"ח, שהנוקבא מעלה על ידי זווג דהכאה באור העליון, הנק' אור של דין, (כנ\"ל ד\"ה סומק) כי עה\"ס דאור ישר נק' ה' חסדים חג\"ת נ\"ה, והן מתלבשות בה' גבורות חג\"ת נ\"ה דאו\"ח, ואלו חמש עלין תקיפין הן, כחות הדין שבמסך, המעכב את האור העליון מהתלבש ממסך ולמטה."],[1,"","וע\"כ נק' עתה רק ה' עלין תקיפין, כי עוד אינה ראויה לזווג עליהם. ובזמן הגדלות כשהמסך בא בזווג עם האור העליון הם נק' ה' גבורות. כנ\"ל."],[1,"","ואלו ה' עלין תקיפין ה\"ס ה' תיבות שיש מאלקים תנינא עד אלהים תליתאה, שהן: מרחפת על פני המים ויאמר. וז\"ש \u0003אמאי אדכר זמנא אחרא\u0004, שמשמע שיש כאן פעולה חדשה, ואומר, שהוא כדי להוציא מהנוקבא ה' עלין תקיפין אלו, שהם הכנה לזווג בזמן הגדלות."],[1,"","ומה שאלו ע\"ס דאו\"ח נקראות ה\"ג שהן חג\"ת נ\"ה ואינן נקראות כח\"ב תו\"מ, כנ\"ל. הענין הוא, מפני שאינן ממשיכות אלא אור חסדים לבד, ולכן ירדו כח\"ב ממעלתם ונקראים חג\"ת, ות\"ת ומלכות נק' בשם נו\"ה."],[1,"","וז\"ש, \u0003חמש תרעין וכו' כוס ישועות\u0004: היינו בעת הגדלות, שה' עלין תקיפין נעשו לה' גבורות, אז הם נבחנים לחמש תרעין, שהם שערים פתוחים לקבל ה' החסדים דאור ישר. וכן הם נקראים ישועות מטעם זה. ואז נק' הנוקבא \u0003כוס ישועות\u0004 או \u0003כוס של ברכה\u0004, כי בסגולתן נעשית הנוקבא כלי מחזיק הברכה, שהיא ה\"ח הנ\"ל."],[1,"","והנה מספר הספי' הן בב' בחי' או במספר עשר, שעיקרן הן חמש בחי' כנ\"ל. או במספר י\"ג, כמו י\"ג מדות הרחמים. וההבדל ביניהם הוא, שהמספר עשר מורה על ספירת זו\"ן שיש בהן רק אור חסדים לבד. והמספר י\"ג מורה על המוחין דהארת החכמה המקובלת לזו\"ן. וענין זה מתבאר להלן במראות הסולם."],[1,"","ואומר, \u0003שכוס של ברכה\u0004 המורה על המשכת ה' חסדים תוך ה' גבורות שלה, כנ\"ל. \u0003אצטריך למהוי על חמש אצבען\u0004, דהיינו רק במספר עשר, שהן חג\"ת נ\"ה כנ\"ל \u0003ולא יתיר\u0004, דהיינו לאפוקי ממספר י\"ג. והטעם הוא, כי אין הנוק' ראויה לקבל חכמה מסוד הי\"ג, זולת בדרך התלבשות החכמה בחסדים. ולפיכך אצטריך מקודם להמשיך ברכה, שהם ה' חסדים על ידי ה' אצבען דוקא, שהן ה' הגבורות, ואז יכולה לקבל גם מי\"ג."],[1,"","ומשמע, שהכונה היא על ה' אצבען דיד שמאל, שהן ה\"ג, כי ה' אצבען דיד ימין ה\"ס ה\"ח. ולפיכך צריכים להגביה את הכוס של ברכה בב' ידים, דהיינו גם עם ה' אצבען דיד שמאל, כדי לרמז על הכונה הנ\"ל דה\"ג. אמנם אח\"ז בתחילת הברכה צריכים להשאיר את הכוס על ה' אצבען דיד ימין בלבד, כי אין לעורר אחיזה לס\"א היונקת משמאל."],[1,"","וז\"ש, \u0003מכאן ולהלאה אור\u0004: כלומר, אלהים תליתאה אדכר במאמר יהי אור וכו' שהוא להאציל בחינת הגדלות דנוקבא, שה\"ס ה\"ח וי\"ג מכילן דרחמי, אשר ה' החסדים ה\"ס ה' פעמים אור שבמאמר, שהן: יהי אור, ויהי אור, האור כי טוב, בין האור, לאור יום. והי\"ג מכילן דרחמי מרומזין בכתוב ויהי ערב ויהי בוקר יום אחד. כי אחד ה\"ס י\"ג והוא גם בגי' י\"ג. (ועי' בתי\"ז תיקון כ\"ו).וה' האורות הללו, ה\"ס משחז\"ל האור שברא הקב\"ה ביום א' היה אדם צופה בו מסוף העולם עד סופו כיון שנסתכל הקב\"ה בדור המבול ובדור הפלגה וראה שמעשיהם מקולקלים, עמד וגנזו מהם, (חגיגה י\"ב) וזה אמרו \u0003דאתברי ואתגניז\u0004."],[1,"","וז\"ש, \u0003ואתכליל בברית ההוא דעאל בשושנה\u0004: כלומר שה' החסדים הללו נכללו מקודם ביסוד דז\"א, ולא באו ישר מבינה, הנק' אלהים, אל הנוקבא. והברית היא יסוד דז\"א דעאל בשושנה ונתן אותם אליה. והטעם יתבאר בסמוך."],[1,"","והנה אלו ה\"ח היוצאים על ה\"ג, כנ\"ל, הם נק' זרע, גם תדע, שעיקר תוקף הדין והגבורות שבמסך, שבכחם מכה על האור העליון ומחזירו לאחוריו, הנה הוא נמצא רק בעטרת היסוד דז\"א, שהוא ממשיך אותם ממזל ונקה שבדיקנא, והנוקבא מקבלת ממנו רק הארה וענף בלבד. ולפיכך עיקר הזווג שעל המסך, המעלה ה\"ג הממשיכות והמלבישות את ה\"ח שהם ה' אורות הנ\"ל, הנה הוא נעשה ביסוד דז\"א, והוא הנותן אותם לנוק'. וזה שמדייק להשמיענו, \u0003דההוא זרעא\u0004, שהם ה\"ח וה\"ג, \u0003קיימא באות ברית ממש\u0004, כי באות ברית שהיא עטרת יסוד דז\"א, נמצאת ממשיות הגבורות הממשיכות ה' החסדים הנק' זרע, אבל יסוד הנוק' מקבל רק בחינת דיוקנא של הגבורות שלו. וע\"כ נק' יסוד הנוקבא רק בשם דיוקנא דברית."],[2,"","ג) \u0003וכמה דדיוקנא דברית\u0004 וכו': וכמו שצורת הברית נזרעה במ\"ב זווגים מאותו הזרע, כך השם החקוק והמפורש נזרע במ\"ב אותיות של מעשה בראשית."],[2,"","ביאור הדברים, סוד שם מ\"ב אתוון, הוא הוי\"ה פשוטה, והוי\"ה במילוי, והוי\"ה במילוי דמילוי, שיש בהן מ\"ב אותיות. וענינן יתבאר במראות הסולם. וההוא זרעא דקיימא באות ברית, שהן ה\"ח וה\"ג, כנ\"ל, הוא נמשך מהשם מ\"ב."],[2,"","וזה אמרו \u0003וּכְמָה דְדִיּוּקְּנָא דִבְרִית\u0004 (וכמו שצורת הברית) שהיא הנוקבא, \u0003אִזְדְּרַע בְּאַרְבְּעִין וּתְרֵין זִוּוּגִין דְּהַהוּא זַרְעָא, כָּךְ אִזְדְּרַע שְׁמָא גְלִיפָא מְפָרַשׁ, בְּאַרְבְּעִין וּתְרֵין אַתְוָון דְּעוֹבָדָא דִּבְרֵאשִׁית\u0004 (נזרעה במ\"ב זווגים מאותו הזרע, כך השם החקוק והמפורש נזרע במ\"ב אותיות של מעשה בראשית) פי' כי ב' בחי' יש להבחין בנוקבא: א' היא בנין פרצופה, שהיא נבנית ע\"י הבינה, המתבאר כאן בעובדא דבראשית. הב' היא ענין הזדווגותה עם הז\"א, הנקראת רזא דיחודא. וזה אמרו, \u0003וּכְמָה דְדִיּוּקְּנָא דִבְרִית\u0004 (וכמו שצורת הברית) שהיא יסוד הנוקבא, \u0003אִזְדְּרַע בְּאַרְבְּעִין וּתְרֵין זִוּוּגִין דְּהַהוּא זַרְעָא\u0004 (נזרעה במ\"ב זווגים מאותו הזרע), דאות ברית, שהבחן זה הוא ברזא דיחודא, דהיינו בסוד הזווג, הנה כך תקיש לסדר אצילות בנינה של הנוקבא ע\"י הבינה הנק' עובדא דבראשית, שהיתה ג\"כ בסוד שם מ\"ב."],[2,"","וכבר ידעת שיש ב' מצבים בבנין הנוקבא, שהם קטנות וגדלות. הנה הקטנות נק' בשם גליפא, שפירושו חקיקה לבית קבול לאורות של זמן הגדלות, כי כל המקובל לנוקבא בזמן הגדלות צריכה להכנה ולהכשרה להם מימי הקטנות (כנ\"ל אות א' בד\"ה והנה המוחין) וע\"כ נק' בשם גליפא, ובחינת הגדלות שלה נק' בשם מפרש, כי כל הסתום בעת הקטנות מתפרש ונודע בעת הגדלות. וזה אמרו \u0003כָּךְ אִזְדְּרַע שְׁמָא גְלִיפָא מְפָרַשׁ\u0004 (כך השם החקוק והמפורש נזרע) הנוקבא נק' שם, גליפא היא הקטנות שלה, \u0003מפרש\u0004 הוא הגדלות שלה. וגם הם אזדרעו ונבנו במ\"ב אתוון, כמו המ\"ב זווגין שברזא דיחודא באות ברית. וז\"ש \u0003בְּאַרְבְּעִין וּתְרֵין אַתְוָון דְּעוֹבָדָא דִּבְרֵאשִׁית\u0004 (במ\"ב אותיות של מעשה בראשית) שהן מ\"ב האותיות המובאות כאן מבראשית עד הב' של ובהו."],[3,"","ד) \u0003בראשית ר' שמעון\u0004 וכו': בראשית. ר\"ש פתח, הנצנים נראו בארץ. \u0003הנצנים\u0004, זה הוא מעשה בראשית. \u0003נראו בארץ\u0004, מתי. הוא ביום השלישי, שכתוב ותוצא הארץ, אז נראו בארץ. \u0003עת הזמיר הגיע\u0004, זה הוא יום רביעי, שהיה בו זמיר עריצים. שע\"כ כתוב בו יהי מארת חסר ו' שהוא לשון קללה. \u0003וקול התור\u0004, זה הוא יום חמישי, שכתוב בו, ישרצו המים וגו' לעשות תולדות. \u0003נשמע\u0004, זה הוא יום ששי, שכתוב בו, נעשה אדם, שהוא עתיד להקדים עשיה לשמיעה, כי כתוב כאן נעשה אדם, וכתוב שם, נעשה ונשמע. \u0003בארצנו\u0004, זה הוא יום שבת. שהוא כמו ארץ החיים. שהוא עולם הבא."],[3,"","ביאור הדברים, \u0003הנצנים דא עובדא דבראשית\u0004: כלומר, ששת ימים דמעשה בראשית, שהם ו' קצוות חג\"ת נה\"י דז\"א שמהם נבנים ע\"ס דפרצוף הנוקבא דז\"א. כי הנוקבא לית לה מגרמה ולא מידי, וכל בנינה הוא ממה שהז\"א נותן לה. והולך ומפרש כאן איך הנוק' נבנית והולכת מהו\"ק דז\"א. ואומר, נראו בארץ, אימתי, ביום ג', כי הנוק' נקראת ארץ, ואומר שהנצנים שהם ספירות הז\"א, נתקבלו ונראו בנוקבא, הנק' ארץ, ביום ג' דמעשה בראשית. והנה נראו משמע שנראו פעם כך ועתה נראה באופן אחר. וזה ששואל אימתי היה זה, ומשיב שזה היה ביום ג', שהוא ת\"ת. וביאור הדברים הוא, כי תחילה נאצלה בסוד ב' מאורות הגדולים, ואז היתה שוה לת\"ת דז\"א. ונמצא שנאצלה ביום ג' בשוה עם ת\"ת דז\"א, הנק' יום ג' דמעשה בראשית. וז\"ש \u0003כדין נראו בארץ\u0004: כלומר, כיון שהמצב הזה לא היה מתקיים בנוקבא, כמו שאומר להלן, לכן אומר הכתוב \u0003נראו בארץ\u0004, דהיינו שנראו פעם כך. ואח\"כ \u0003עת הזמיר הגיע\u0004."],[3,"דא יום ד' דהוה ביה זמיר עריצים",": כי ביום ד' נתמעטה הלבנה שהיא הנוקבא דז\"א, כמו שאמרו חז\"ל שקטרגה הלבנה ואמרה אי אפשר לב' מלכים שישתמשו בכתר אחד, ואמר לה הקב\"ה לכי ומעטי את עצמך. (חולין ס:) ואז ירד לבחי' נקודה תחת היסוד דז\"א, וט\"ת שלה נפלו לבריאה. ולא נשאר לה באצילות זולת נקודת הכתר שלה, ועמדה תחת היסוד, ומעתה הולכת ונבנית ע\"י נצח והוד ז\"א, כמו שמבאר והולך. ונקרא זה, \u0003זמיר עריצים\u0004, מפני שהמיעוט נעשה הכנה ובית קבול לקבלת מוחין דחיה, אשר מוחין אלו מכריתין כל הקליפות הנאחזות בנוקבא. וזמיר לשון כריתה, \u0003ועריצים\u0004 הם החיצונים והקליפות הסובבים את השושנה."],[3,"","וז\"ש, \u0003וקול התור דא יום חמישי\u0004: התור, הוא נצח דז\"א וקול התור, הוא הוד דז\"א, והוא יום חמישי דמעשה בראשית. ובשביל שהיא מקבלת מההוד הכלול בנצח דז\"א, ע\"כ נקרא קבלתה זו, בשם קול התור."],[3,"","וז\"ש, \u0003נשמע דא יום ששי\u0004: כלומר שקול התור אינו מקובל אל הנוקבא רק באמצעות יום ו', שהוא יסוד דז\"א הכולל נו\"ה יחד, והוא משפיע אותם לנוקבא. וז\"ש, שנשמע אל הנוקבא רק ביום הששי. וזה הכלל שאין הנוקבא מקבלת רק מהקו האמצעי דז\"א, שהוא דת\"י או מדעת, או מת\"ת, או מיסוד."],[3,"דכתיב נעשה אדם דהוה עתיד למקדם עשיה לשמיעה",": שמיעה ה\"ס בינה כי ראיה ושמיעה הם חכמה ובינה. עשיה ה\"ס המלכות, ונודע, שבסוד התיקון דצמצום ב', שה\"ת עלתה לנקבי העינים, כדי לשתף אותה במדת הרחמים, שהיא בינה עילאה, הנה אבא הוציא אמא לחוץ ואבא עצמו אתתקן כעין דכר ונוקבא. כי עינים ה\"ס אבא, וע\"י עלית ה\"ת אליו נתתקן הזווג של ראש בה\"ת, שנקראת נקבי העינים, ואמא שהיא בינה יצאה משום זה מהראש אל הגוף. שז\"ס שאין בא\"א אלא כו\"ח בראשו ובינה יצאה לגוף."],[3,"","ונמצא עתה שהעשיה שהיא ה\"ת מלכות, קודמת לשמיעה, שהיא בינה. וז\"ס מ\"ש בתיקונים תי ' ס\"ט,אני ישנה שניה ודאי לחכמה, ע\"ש. כי אבא נתתקן בנוק' הנק' אני, ונעשתה הנוקבא כמו אבא, לספירה שניה לכתר, ודורש, כי ישנה היא אותיות שניה ואני ישנה כמו אני שניה. ע\"ש."],[3,"","ומחמת עלית המלכות לנקבי העינים נמתקה שם מאד, ונעשתה ראויה אח\"כ לעלות ולהלביש או\"א עילאין, ולקבל מוחין שהם מוחין דחיה כמו אמא עילאה. וה\"ס סיהרא באשלמותא. ולפיכך במתן תורה הקדימו ישראל נעשה לנשמע, והקדימו עשיה לשמיעה, שבזה זכו לקבלת התורה.(שבת פח:)כי העשיה שהיא מלכות עלתה והלבישה את או\"א עילאין ונגלה סוד היובל, שער הנון."],[3,"","וזה אמרו כאן, שלכן היתה השמיעה ביום הששי, כי בו נעשה התיקון הזה להקדים עשיה לשמיעה. כמו במתן תורה, וע\"כ נעשתה המלכות בשבת בראשית בבחינת ארץ החיים, שה\"ס אמא עילאה. כמו שמבאר והולך. וענין זה עמוק מאד, ועי' כאן במראות הסולם, שהרחבנו ענין זה."],[3,"בארצנו דא יום שבת, דאיהו דוגמת ארץ החיים",": אמא עילאה נק' ארץ החיים. וע\"י השפעת יום הששי, עלתה הנוקבא ביום שבת דמעשה בראשית עד אמא עלאה, ונעשתה גם הנוקבא דוגמת ארץ החיים. כי זה הכלל אם התחתון עולה לעליון ממנו נעשה כמוהו ממש."]],[[0,"","רִבִּי חִזְקִיָּה (נ\"א רבי אלעזר) פָּתַח, כָּתוּב (שיר השירים ב) כְּשׁוֹשַׁנָּה בֵּין הַחוֹחִים. מִי הַשּׁוֹשַׁנָּה זוֹ כְּנֶסֶת יִשְׂרָאֵל (משום שיש שושנה ויש שושנה). מָה הַשּׁוֹשַׁנָּה שֶׁהִיא בֵּין הַחוֹחִים יֵשׁ בָּהּ אָדֹם וְלָבָן - אַף כְּנֶסֶת יִשְׂרָאֵל יֵשׁ בָּהּ דִּין וְרַחֲמִים. מַה שּׁוֹשַׁנָּה יֵשׁ בָּהּ שְׁלֹשָׁה עָשָׂר עָלִים - אַף בִּכְנֶסֶת יִשְׂרָאֵל יֵשׁ שְׁלֹשׁ עֶשְׂרֵה מִדּוֹת רַחֲמִים שֶׁמַּקִּיפוֹת אוֹתָהּ מִכָּל צְדָדֶיהָ. אַף אֱלֹהִים שֶׁל כָּאן, מִשָּׁעָה שֶׁנִּזְכַּר, הוֹצִיא שְׁלֹשׁ עֶשְׂרֵה תֵבוֹת לְהַקִּיף אֶת כְּנֶסֶת יִשְׂרָאֵל וְלִשְׁמֹר אוֹתָהּ."],[1,"","וְאַחַר כָּךְ נִזְכַּר פַּעַם אַחֶרֶת. לָמָּה נִזְכַּר בְּפַעַם אַחֶרֶת כְּדֵי לְהוֹצִיא חֲמִשָּׁה עָלִים חֲזָקִים שֶׁסּוֹבְבִים אֶת הַשּׁוֹשַׁנָּה. וְאוֹתָם הַחֲמִשָּׁה נִקְרָאִים יְשׁוּעוֹת, וְהֵם (חמשה) (חמשים) שְׁעָרִים. וְעַל זֶה הַסּוֹד כָּתוּב (תהלים קטז) כּוֹס יְשׁוּעוֹת אֶשָּׂא, זוֹ כּוֹס שֶׁל בְּרָכָה. הַכּוֹס שֶׁל בְּרָכָה צְרִיכָה לִהְיוֹת עַל חָמֵשׁ אֶצְבָּעוֹת וְלֹא יוֹתֵר, כְּמוֹ שֶׁהַשּׁוֹשַׁנָּה שֶׁיּוֹשֶׁבֶת עַל חֲמִשָּׁה עָלִים חֲזָקִים בְּדֻגְמָא שֶׁל חָמֵשׁ אֶצְבָּעוֹת. וְהַשּׁוֹשַׁנָּה הַזּוֹ הִיא כּוֹס שֶׁל בְּרָכָה. מֵ\"אֱלֹהִים\" הַשֵּׁנִי עַד \"אֱלֹהִים\" הַשְּׁלִישִׁי - חָמֵשׁ תֵּבוֹת. מִכָּאן וָהָלְאָה הָאוֹר שֶׁנִּבְרָא וְנִגְנַז וְנִכְלַל בַּבְּרִית הַהוּא שֶׁנִּכְנַס בַּשּׁוֹשַׁנָּה (ס\"א זו) וְהוֹצִיא בָהּ זֶרַע, וְזֶה נִקְרָא עֵץ עֹשֶׂה פְּרִי אֲשֶׁר זַרְעוֹ בוֹ. וְאוֹתוֹ הַזֶּרַע קַיָּם בְּאוֹת הַבְּרִית מַמָּשׁ."],[2,"","וּכְמוֹ שֶׁדְּמוּת הַבְּרִית נִזְרַע בְּאַרְבָּעִים וּשְׁנַיִם זִוּוּגִים (של אותו) הַזֶּרַע הַהוּא, כָּךְ נִזְרַע הַשֵּׁם הֶחָקוּק מְפֹרָשׁ בְּאַרְבָּעִים וּשְׁתַּיִם אוֹתִיּוֹת שֶׁל מַעֲשֵׂה בְרֵאשִׁית."],[3,"","בְּרֵאשִׁית, רַבִּי שִׁמְעוֹן פָּתַח, (שיר ב) הַנִּצָּנִים נִרְאוּ בָאָרֶץ. הַנִּצָּנִים - זֶה מַעֲשֵׂה בְרֵאשִׁית. מָתַי נִרְאוּ בָאָרֶץ בַּיּוֹם הַשְּׁלִישִׁי, שֶׁכָּתוּב וַתּוֹצֵא הָאָרֶץ, אָז נִרְאוּ בָאָרֶץ. עֵת הַזָּמִיר הִגִּיעַ - זֶה הַיּוֹם הָרְבִיעִי שֶׁהָיָה בּוֹ זְמִיר עָרִיצִים, מְאֹרֹת חָסֵר. וְקוֹל הַתּוֹר - זֶה הַיּוֹם הַחֲמִישִׁי, שֶׁכָּתוּב יִשְׁרְצוּ הַמַּיִם וְגוֹ', לַעֲשׂוֹת תּוֹלָדוֹת. נִשְׁמַע - זֶה הַיּוֹם הַשִּׁשִּׁי, שֶׁכָּתוּב נַעֲשֶׂה אָדָם, שֶׁהָיָה עָתִיד לְהַקְדִּים עֲשִׂיָּה לִשְׁמִיעָה, שֶׁכָּתוּב כָּאן נַעֲשֶׂה אָדָם, וְכָתוּב שָׁם נַעֲשֶׂה וְנִשְׁמָע. בְּאַרְצֵנוּ - זֶה יוֹם הַשַּׁבָּת, שֶׁהוּא דֻגְמַת אֶרֶץ הַחַיִּים."]]],[["(שהוא עולם הבא. עולם הנשמות עולם הנחמות). (נ\"א דבר אחר) הַנִּצָּנִים אִלֵּין אִנּוּן אֲבָהָן דְּעָאלוּ בַּמַּחֲשָׁבָה וְעָאלוּ בְּעָלְמָא דְּאָתֵי וְאִתְגְּנִיזוּ תַּמָּן. וּמִתַּמָּן נָפְקוּ בִּגְנִיזוּ וְאִטָּמִירוּ גוֹ (נ\"א בהו) נְבִיאֵי קְשׁוֹט. אִתְיְלִיד יוֹסֵף וְאִטָּמִירוּ בֵּיהּ, עָאל יוֹסֵף בְּאַרְעָא קַדִּישָׁא וּנְצִיב לוֹן תַּמָּן, וּכְדֵין נִרְאוּ בָאָרֶץ וְאִתְגָּלוּ תַּמָּן. וְאֵימָתַי אִתְחָזוּן, בְּשַׁעֲתָא דְּאִתְגְּלֵי קֶשֶׁת בְּעָלְמָא. דְּהָא בְּשַׁעֲתָא דְּקֶשֶׁת אִתְחֲזֵי כְּדֵין אִתְגַּלְּיָן אִנּוּן, וּבְהַהִיא שַׁעֲתָא עֵת הַזָּמִיר הִגִּיעַ עִדָּן לְקַצֵּץ חַיָּבִין מֵעָלְמָא. אַמַּאי אִשְׁתְּזִיבוּ, בְּגִין דְּהַנִּצָּנִים נִרְאוּ בָאָרֶץ, וְאִלְמָלֵא דְנִרְאוּ לָא אִשְׁתָּאֲרוּן בְּעָלְמָא, וְעָלְמָא לָא אִתְקַיָּם.","וּמָאן מְקַיֵּם עָלְמָא וְגָרִים לַאֲבָהָן דְּאִתְגַּלְּיָן, קַל יְנוֹקֵי דְּלָעָאן בְּאוֹרַיְתָא, וּבְגִין אִנּוּן רַבְיָין דְּעָלְמָא, עָלְמָא אִשְׁתְּזִיב. לְקָבְלֵיהוֹן, (שיר השירים א׳:י״א) תּוֹרֵי זָהָב נַעֲשֶׂה לָךְ, אִלֵּין אִנּוּן יְנוֹקֵי רַבְיָין עוּלְמִין דִּכְתִיב, (שמות כ״ה:י״ח) וְעָשִׂיתָ שְׁנַיִם כְּרוּבִים זָהָב.","בְּרֵאשִׁית רִבִּי אֶלְעָזָר פָּתַח (ישעיהו מ׳:כ״ו) שְׂאוּ (דף ל' א) מָרוֹם עֵינֵיכֶם וּרְאוּ מִי בָרָא אֵלֶּה. שְׂאוּ מָרוֹם עֵינֵיכֶם לְאָן אֲתַר, לְאֲתַר דְּכָל עַיְינִין תָּלְיָאן לֵיהּ. וּמָאן אִיהוּ, פֶּתַח עֵינַיִם. וְתַמָּן תִּנְדְּעוּן דְּהַאי סָתִים עַתִּיקָא דְקַיְמָא לַשְּׁאֵלָה. בָּרָא אֵלֶּה. וּמָאן אִיהוּ. מִ\"י. הַהוּא (שמות ק\"מ א) דְאִקְרֵי מִקְצֵה הַשָּׁמַיִם לְעֵילָּא. דְּכֹלָא קַיְּמָא בִּרְשׁוּתֵיהּ. וְעַל דְּקַיְמָא לַשְּׁאֵלָה וְאִיהוּ בְּאֹרַח סָתִים וְלָא אִתְגַּלְיָא, אִקְרֵי מִ\"י, דְּהָא לְעֵילָּא לֵית תַּמָּן שְׁאֵלָה. וְהַאי קְצֵה הַשָּׁמַיִם אִקְרֵי מִ\"י.","וְאִית אָחֳרָא לְתַתָּא וְאִקְרֵי מַ\"ה. מַה בֵּין הַאי לְהַאי, אֶלָּא קַדְמָאָה סְתִימָאָה דְּאִקְרֵי מִ\"י קַיְּמָא (תרומה קל\"ח א', ויקהל רי\"א, בהעלותך קמ\"ח ב', ולהלן ט' א', י\"ו, קס\"ז א', שמות קנ\"ז) לַשְּׁאֵלָה, כֵיוָן דְּשָׁאַל בַּר נָשׁ וּמְפַשְׁפֵּשׁ לְאִסְתַּכְּלָא וּלְמִנְדַע מִדַּרְגָּא לְדַרְגָּא עַד סוֹף כָּל דַּרְגִּין, כֵּיוָן דְּמָטֵי תַּמָּן, מַ\"ה. מַה יָּדַעְתָּ, מַה אִסְתָּכַּלְתָּא, מַה פִּשְׁפַּשְׁתָּא, הָא כֹּלָא סָתִים כִּדְקַדְמִיתָא.","וְעַל רָזָא דְּנָא כְּתִיב, (איכה ב) מָה אֲעִידֵךְ מָה אֲדַמֶּה לָךְ. כַּד אִתְחְרִיב בֵּי מַקְדְּשָׁא נָפַק קָלָא וַאֲמַר מָה אֲעִידֵךְ (נ\"א ומה [מה] אדמה לך, בההוא מ\"ה אעידך) בְּכָל יוֹמָא וְיוֹמָא, [וְהָא] אַסְהִידַת בָּךְ מִיּוֹמִין קַדְמָאִין דִּכְתִיב, (דברים ל) הַעִדֹתִי בָכֶם הַיּוֹם אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ. וּמָה אֲדַמֶּה לָךְ בְּהַהוּא גַוְנָא מַמָּשׁ עֲטָרִית לָךְ בְּעִטְרִין קַדִּישִׁין עֲבָדִית לָךְ שָׁלְטָנוּ עַל עָלְמָא דִּכְתִיב, (איכה ב) הֲזֹאת\" הָעִיר\" שֶׁיֹּאמְרוּ\" כְּלִילַת\" יפִי\" וְגו' קָרֵינָא לָךְ (תהלים קכ\"ב) יְרוּשָׁלַיִם הַבְּנוּיָה כְּעִיר שֶׁחֻבְּרָה לָּהּ. (איכה ב) מָה אַשְׁוֶה לָּךְ. כְּגַוְונָא דְּאַנְתְּ יָתְבָה, הָכִי הוּא כִּבְיָכוֹל לְעֵילָא. כְּגַוְונָא דְּלָא עָאלִין הַשְׁתָּא בָּךְ עַמָּא קַדִּישָׁא בְּסִדְּרִין קַדִּישִׁין, הָכִי אוֹמֵינָא לָךְ דְּלָא אֵיעוֹל אֲנָא לְעֵילָא עַד דְּיֵעֲלוּן בָּךְ אֻכְלוֹסָךְ לְתַתָּא. וְדָא אִיהוּ נֶחָמָה דִילָךְ הוֹאִיל דְּדַרְגָא דָא אַשְׁוֶה לָךְ בְּכֹלָא. וְהַשְׁתָּא דְּאַנְתְּ הָכָא גָּדוֹל כַּיָּם שִׁבְרֵךְ. וְאִי תֵימָא דְּלֵית לָךְ קַיָּימָא וְאַסְוָתָא, מִ\"י (שמות רל\"ז ב) יִרְפָּא לָךְ, וַדַּאי הַהוּא דַרְגָּא סְתִימָאָה עִלָּאָה דְכֹלָא קַיְּימָא בֵּיהּ יִרְפָּא לָךְ וְיוֹקִים לָךְ.","מִ\"י קְצֵה הַשָּׁמַיִם לְעֵילָא, מַ\"ה וְעַד קְצֵה הַשָּׁמַיִם לְתַתָּא (קצה השמים לתתא). וְדָא יָרִית יַעֲקֹב דְּאִיהוּ מַבְרִיחַ מִן הַקָּצֶה אֶל הַקָּצֶה, מִן הַקָּצֶה קַדְמָאָה דְּאִיהוּ מִ\"י, אֶל הַקָּצֶה בַּתְרָאָה דְּאִיהוּ מַ\"ה, בְּגִין דְּקָאִים בְּאֶמְצָעִיתָא. וְעַל דָּא מִי בָּרָא אֵלֶּה.","אָמַר רִבִּי שִׁמְעוֹן, אֶלְעָזָר בְּנִי פְּסוֹק מִילָךְ וְיִתְגְּלֵי סְתִימָא דְרָזָא עִלָּאָה דִּבְנֵי עָלְמָא לָא יָדְעִין. שָׁתִיק רִבִּי אֶלְעָזָר. בָּכָה רִבִּי שִׁמְעוֹן וְקָאִים רִגְעָא (נ\"א שְׁעָתָא) חָדָא. אָמַר רִבִּי שִׁמְעון, אֶלְעָזָר מַאי אֵלֶּה. אִי תֵימָא כֹּכְבַיָא וּמַזָּלֵי, הָא אִתְחֲזָאָן תַּמָּן תָּדִיר. וּבְמָּ\"ה אִתְבְּרִיאוּ כְּמָא דְאַתְּ אָמֵר, (תהילים ל״ג:ו׳) בִּדְבַר יְיָ שָׁמַיִם נַעֲשׂוּ. אִי עַל מִלִּין סְתִימִין לָא לִכְתּוב אֵלֶּה דְּהָא אִיתְגַּלְּיָא אִיהוּ.","אֶלָּא רָזָא דָא לָא אִתְגַּלְּיָא בַּר יוֹמָא חַד דַּהֲוֵינָא עַל כֵּיף יַמָּא, וְאָתָא אֵלִיָּהוּ וְאָמַר לִי רִבִּי, יָדַעְתְּ מַה הוּא, מִי בָּרָא אֵלֶּה. אֲמִינָא לֵיהּ אִלֵּין שְׁמַיָּא וְחֵילֵהון עובָדָא דְקוּדְשָׁא בְּרִיךְ הוּא דְּאִית לֵיהּ לְבַר נָשׁ לְאִסְתַּכְּלָא בְּהוּ וּלְבָרְכָא לֵיהּ דִּכְתִיב, (תהילים ח׳:ב׳) כִּי אֶרְאֶה שָׁמֶיךְ מַעֲשֵׂה אֶצְבְּעוֹתֶיךְ וְגו' יְיָ אֲדוֹנֵינוּ מָה אַדִּיר שִׁמְךְ בְּכָל הָאָרֶץ."],[[0,"","ה) \u0003ד\"א הנצנים אלין\u0004 וכו': פירוש אחר. \u0003הנצנים\u0004, אלו הם האבות שנכנסו במחשבה, ונכנסו בעולם הבא, שהוא בינה, ונגנזו שם. ומשם יצאו בגניזו, ונסתרו תוך נביאי האמת. נולד יוסף ונסתרו בו. נכנס יוסף בארץ הקדושה, והקים אותם שם, ואז \u0003נראו בארץ\u0004 ונגלו שם. ומתי הם נראים. היינו בשעה שהקשת נראית בעולם. כי בשעה שהקשת נראית, אז הם מתגלים. ובאותה שעה, \u0003עת הזמיר הגיע\u0004, היינו, עת לקצץ את הרשעים מן העולם. למה נצולו. היינו משום שהנצנים נראו בארץ. ואם לא היו נראים מכבר, לא היו נשארים בעולם, והעולם לא היה מתקיים."],[0,"","ביאור הדברים, כאן מבאר את הכתוב הנ\"ל, על בחינת השגת מוחין דחיה של ז\"א גופיה. ואומר, שהנצנים סובבים על חג\"ת דז\"א, שנק' אבהן, כי הנה\"י דז\"א נק' בנין, והם ב' פרצופין, הנחלקין על החזה של הז\"א, כי חג\"ת נק' זו\"ן הגדולים, ונה\"י נק' זו\"ן הקטנים. וע\"כ מדייק להשמיענו שהוא מז\"א הגדול, וע\"כ אומר, \u0003אבהן\u0004. ונק' בשם \u0003נצנים\u0004, שפירושו נטיעות, הוא, מפני שהולכים וגדלים כדרך נטיעות. שמתחילה היתה מדתם כמו נה\"י, ואח\"כ ביניקה נעשו חג\"ת, ואח\"כ בגדלות א', נעשו חב\"ד של נשמה. ואח\"כ בגדלות ב', נעשו חב\"ד דחיה."],[0,"","וז\"ש \u0003דעאלו במחשבה ועאלו בעלמא דאתי\u0004: הכונה היא על עיבורו של ז\"א, כי בעת עיבורו הוא עולה לאו\"א הנק' מחשבה ועלמא דאתי, אבא נק' מחשבה, ואמא נק' עלמא דאתי, ושם ראשית בנינו של הז\"א בבחינת ג' גו ג', שפירושו שהחג\"ת מלובשים תוך הנה\"י. וז\"ס הנטיעות כקרני חגבים היו, עקרן משם ושתלן במקום אחר והגדילו. הנטיעות הן אבהן כנ\"ל, שהן חג\"ת משרשן, וע\"י עליתן לעיבור לחו\"ב, דהיינו ששתלן במקום אחר, והשיגו שם את המלכות הממותקת הראויה למוחין לעת גדלות. הנה עי\"ז גדלו לאט לאט, ע\"י העיבור, אח\"כ ע\"י יניקה אח\"כ ע\"י גדלות א' ולבסוף ע\"י הגדלות הב', כמו שמבאר והולך. וז\"ש \u0003ומתמן נפקו בגניזו\u0004: שאחר שקבלו החג\"ת כל המוחין דעיבור, הם נולדים ויוצאים מאו\"א למקומם למטה, \u0003ונפקי בגניזו\u0004, כי גם אחר יציאתם מאו\"א למקומם נשארו עוד בגניזו, דהיינו באור מועט."],[0,"","וז\"ש \u0003ואטמירו גו נביאי קשוט\u0004: כלומר, על ידי השגת מוחין דיניקה, נמשך האור המיוחד אל ספי' נה\"י דז\"א, הנק' \u0003נביאי קשוט\u0004, ואז נתפשטו להם החג\"ת מתוך הנה\"י, והשיג ו\"ק, ועכ\"ז הם עוד בטמירו, כי נמצאים עוד בהעלם מוחין דראש, ואין להם אלא נפש רוח בלבד. וז\"ש \u0003ואטמירו גו נביאי קשוט\u0004 נביאי קשוט, הם נו\"ה שהשיגו על ידי היניקה, אבל אטמירו בהם, כי האור שלהם נעלם עוד ואינו נגלה. ודע שיש תמיד ערך הפוך מכלים לאורות, כי בהתחשב עם בחינת האורות, משיגים ע\"י יניקה, אור דחג\"ת שהוא רוח, ובהתחשב עם בחי' הכלים, משיגים ביניקה כלים דנו\"ה, ואור הנפש שהיה בחג\"ת, יורד בהם. וכן במוחין דגדלות שמבחי' האורות, נבחן, שהם משיגין אור דחב\"ד, ומבחי' הכלים נבחן שהשיגו כלי היסוד דגדלות, כמ\"ש להלן."],[0,"","וז\"ש, \u0003אתיליד יוסף ואטמירו ביה\u0004: כי אחר תשלום המוחין דיניקה עולה ז\"א לעיבור ב' למוחין דגדלות א', שע\"י מוחין אלו נעשו החג\"ת שלו לבחינת חב\"ד וראש, ונה\"י שקנה ע\"י היניקה נעשו לו לחג\"ת, ונולדים לו נה\"י חדשים המכונים נה\"י של מוחין דגדלות, ואלו נה\"י מכונים בשם יוסף, שהוא יסוד דגדלות הכולל נו\"ה דגדלות. וז\"ש \u0003אתיליד יוסף\u0004, דהיינו היסוד דגדלות."],[0,"","ואומר \u0003ואטמירו ביה\u0004, להשמיענו שעדיין אין להם לחג\"ת האורות דגדלות בשלימות, ועדיין הם בהעלם, כי בגדלות א' הוא משיג רק המוחין דנשמה, שהם נבחנים עוד לבחינת אחורים אצל הז\"א, וע\"כ אומר \u0003ואטמירו ביה\u0004, כלומר, עוד הם בהעלם."],[0,"","וז\"ש, \u0003עאל יוסף בארעא קדישא ונציב לון\u0004: כי אחר מוחין דגדלות א' מתחיל הז\"א לקבל מוחין דגדלות ב' שהוא מוחין דחיה, ואז ננסרת הנוקבא ממנו ונבנית לפרצוף שלם במוחין דחיה, ואז נקראת הנוקבא \u0003ארעא קדישא\u0004 כי המוחין דחיה נק' קודש. והוא שאומר \u0003עאל יוסף\u0004 שהוא יסוד דגדלות של הז\"א \u0003בארעא קדישא\u0004 שהיא הנוקבא פב\"פ עם הז\"א בקומה שוה. וז\"ש, \u0003ונציב לון תמן\u0004: בארעא קדישא דייקא, כי אין המוחין דחיה, שה\"ס חכמה, נמשכים רק בעת הזווג, שהזו\"ן ברזא דאחד, והם נשארים רק ברשות הנוקבא, כי רק על ידה נמשכו בעת הזווג, וז\"ש ונציב לון תמן, דהיינו בביתא דידה. והטעם כי ערך ז\"א כלפי הנוק' כערך או\"א עי' כלפי ישסו\"ת, וע\"כ אין מוחין דחיה שה\"ס חכמה, נגלית אלא בנוק' שהוא בחי' ישסו\"ת. וז\"ש להלן \u0003וכדין נראו בארץ ואתגלו תמן\u0004 כלומר, עתה נתגלו במדת הגדלות כראוי, אבל עד עתה נחשבים לטמירין ונעלמים."],[0,"","ואומר עוד \u0003ואימתי אתחזון\u0004 וכו'. ואין לשאול הלא כבר ביאר זאת לעיל שהם מתגלים בשעתא דעאל יוסף בארעא קדישא, דהיינו בעת הזווג, גם השמיענו שמקום ההתגלות הוא בנוקבא, וא\"כ מאי שואל עוד הפעם \u0003אימתי אתחזון\u0004. הענין הוא כי גם בעת הזווג ישנן ב' הבחנות, כי יש התכללות שמאלא בימינא דהיינו בסוד ה' חסדים שבזכר, ויש התכללות ימינא בשמאלא בסוד ה' גבורות שבנוקבא. וע\"כ שואל אימתי אתחזון, אם בסוד התכללות ימינא בשמאלא, אם בסוד התכללות שמאלא בימינא."],[0,"","ומשיב. \u0003בשעתא דאתגלי קשת בעלמא: קשת\u0004, היא יסוד דז\"א, \u0003בעלמא\u0004, הוא הנוקבא, שהיא בחינת התכללות ימינא בשמאלא בעת הזווג, בסוד את קשתי נתתי בענן וכו'. ואומר שרק מבחינה זו נמשכין המוחין העילאין. וז\"ש, \u0003כדין אתגליין אינון\u0004, דהיינו רק מבחינת התכללות ימינא בשמאלא."],[0,"","וז\"ש, \u0003ובההיא שעתא עת הזמיר הגיע עדן לקצץ חייבין בעלמא\u0004: כלומר בעת שמתרבין הרשעים בעולם, שמחמתם נעשו אחיזה מרובה לקליפות והס\"א, ע\"ד שהיה בזמן דור המבול, שנמחה מחמת זה כל היקום, הנה אז אין לבני העולם תקנה אלא על ידי הגילוי של מוחין עילאין הנ\"ל, שהם המוחין דחיה. כמ\"ש והולך. וז\"ש, \u0003אמאי אשתזיבו, בגין דהנצנים נראו\u0004: פירוש, למה בני העולם מוצלים מכליה, כמו שהיה בימי המבול, הוא משום דהנצנים נראו בארץ. כי גילוי המוחין דחיה מעביר את הקליפות מהארץ שהיא המלכות, ואינן יכולות להאחז בה עוד. שז\"ס הכתוב וראיתיה לזכור ברית עולם."],[0,"","וז\"ש, \u0003ואלמלא דנראו לא אשתארון בעלמא\u0004 כו': יש כאן סוד גדול. כי תחלה נבנית הנוקבה בסוד ב' המאורות הגדולים, שיש לה לנוקבא קומה שוה עם ז\"א, אלא שעומדת באחוריו של ז\"א, שבשביל זה קטרג הירח שאין ב' מלכים משתמשים בכתר אחד, וע\"כ נבחנים אלו המוחין מוחין דאחור, וכן נקראים מוחין דו\"ק דנוקבא, שהם מוחין שבשעת קטנותה, כלומר מתחילת התהוותה. ואז נבחנים הזו\"ן לאפי זוטרי, ונק' ינוקי רביין עולמין. אלא אחר שהיא משתלמת עם המוחין הללו, חוזרת לעיבור ב' לאו\"א עילאין, ואז נבנית בנין גדול, במוחין דפב\"פ עם הז\"א. ואז הם נק' אפי רברבי, ונודע, שאין שינוי או העדר ברוחני, ואלו המוחין דאחור, אפי זוטרי, נשארים בה גם בעת המוחין דגדלות. ולא עוד אלא שסבת המשכת המוחין דחיה הנ\"ל הם בעיקר בכלים דמוחין דאחור בסוד אפי זוטרי. וז\"ש, \u0003ואלמלא דנראו לא אשתארון בעלמא\u0004 כלומר, דאלמלא דנראו בנוקבא אותם הנצנים כבר מזמן בעת קטנותה, דהיינו בבנין האחורים שלה כנ\"ל, הנה לא אשתארון בה המוחין דחיה גם בעת גדלות, כי לא היו לה כלים במה לקבלם."],[1,"","ו) \u0003ומאן מקיים עלמא\u0004 וכו': ומי הוא המקיים את העולם וגורם לאבות שיתגלו. היינו קול הילדים העוסקים בתורה, ובשביל ילדי עולם אלו, העולם ניצל. כנגדם כתוב, תורי זהב נעשה לך. אלו הם ילדים, נערים, עלמים, שכתוב, ועשית שנים כרובים זהב."],[1,"","ביאור הדברים \u0003רביין דעלמא\u0004 הם בחי' מוחין דאחור הנ\"ל בדיבור הסמוך, הנקרא \u0003אפי זוטרי\u0004, וכן \u0003רביין דעלמא\u0004 וכן \u0003ינוקי רביין עולמין\u0004 ובחי' הזווג שלהם במצב זה, נקרא \u0003קל ינוקי דלעאן באורייתא\u0004. וה\"ס \u0003תורי זהב\u0004 וה\"ס \u0003ב' הכרובים\u0004, דאינון אפי זוטרי, אשר אלו המוחין דחיה הנמשכים בסוד התכללות ימינא בשמאלא, לא היו מקובלים כלל בנוקבא זולתם, כמ\"ש כל זה לעיל בדיבור הסמוך. וז\"ש, \u0003ומאן מקיים עלמא\u0004, דהיינו בעת ריבוי הקלי' שיש להן כח להחריב עולם כבימי המבול, הנה אין תקנה זולת בהמשכת מוחין דחיה בסוד קשת בענן, כנ\"ל, שעי\"ז \u0003עלמא אשתזיב\u0004 ומי הוא המקיים והמציל את העולם בעת ההיא, וגרם \u0003לאבהן דאתגליין\u0004 שגורמים לגילוי החג\"ת בסוד מוחין דראש, שהחג\"ת נעשו אז לחב\"ד דחיה. ואומר, שהגורם לכל זה הוא, \u0003קל ינוקי דלעאן באורייתא\u0004, דהיינו המוחין דאחור כנ\"ל. שה\"ס קל ינוקי ותורי זהב."],[2,"","ז) \u0003בראשית ר' אלעזר\u0004 וכו': בראשית. ר\"א פתח, שאו מרום עיניכם וראו מי ברא אלה. \u0003שאו מרום עיניכם\u0004, שואל, לאיזה מקום. ומשיב, למקום שכל העינים תלויות אליו. ומי הוא. הוא פתח עינים, שהוא מלכות דראש א\"א, ושם תדעו, שעתיקא הסתום הזה, שנוהגת בו שאלה, \u0003ברא אלה\u0004, ומי הוא. הוא הנקרא \u0003מ\"י\u0004, שהוא ז\"ת דבינה, אותו הנקרא מקצה השמים למעלה, שהכל עומד ברשותו, ובשביל שנוהגת בו שאלה, והוא בדרך סתום שאינו מגולה, נקרא \u0003מ\"י\u0004. שהוא לשון שאלה. כי למעלה ממנו, אין שאלה נוהגת שם. וקצה השמים הזה, שנוהגת שם שאלה נקרא \u0003מ\"י\u0004."],[2,"","ביאור הדברים \u0003ר' אלעזר פתח\u0004. הוא בא לבאר הפירוש של בריאת שמים וארץ שבמקרא דבראשית. כי שמים וארץ הם הכלל דז' ימי בראשית, שהם הזו\"ן דאצילות, ואם כן למה כתוב ברא שהיא בריאה ולא אצילות, והיה צ\"ל האציל. ואומר, \u0003ומאן איהו פתח עינים\u0004, המלכות דראש א\"א דאצילות מכונה פתח עינים, כי ספירת החכמה של ע\"ס דראש נק' עינים. ונודע שאין בראש א\"א אלא כתר חכמה בלבד, וע\"כ המלכות שלו נק' פתח עינים, כי בפתיחתה מושפעים המוחין דחכמה מראש א\"א, לכל פרצופי אצילות. וז\"ש, \u0003לאתר דכל עיינין תליאן ליה\u0004 כי מוחין דחכמה נק' עיינין, ואין מוחין דחכמה בכלהו פרצופי אצילות, זולת ע\"י פתיחתה של המלכות דראש א\"א."],[2,"ותמן תנדעון",", היינו בפתח עינים, שהוא המלכות דראש דא\"א, שם תנדעון הסוד הזה, איך שהבינה בראה את הזו\"ן. כי המלה ברא, פירושה לבר ממדרגת אצילות, ומתוך שהבינה עצמה יצאה לבר ממדרגת הראש דא\"א, ונעשתה משום זה לבחינת בריאה בערך הראש דא\"א, ע\"כ היא בראה בהכרח גם את הזו\"ן, ונעשה הז\"א בבחינת יצירה, כי היוצא מבחינת בריאה נק' יצירה, והנוקבא נעשתה בחינת עשיה, כי כל היוצא מיצירה, נק' עשיה. אמנם אין להשוותם לבי\"ע ממש שמאחורי הפרסא דאצילות, כי אלו הבינה וזו\"ן עומדים למעלה מפרסא דהיינו בעולם אצילות, אלא הכוונה היא בערך הראש דא\"א לבד, וע\"כ יש ב' מיני בי\"ע, הא' הוא בי\"ע דפרודא, שנפרדו מכל בחינת אצילות ע\"י הפרסא, שהוא הקרקע דעולם האצילות העומדת עליהם מלמעלה. והב' הם הבי\"ע דעולם אצילות גופיה, שהם הבינה וז\"א ונוקביה שהם לבר מהראש דא\"א בלבד, ועדיין הם אצילות, אלא שהפרסא שבגוי מעוהי דא\"א, שבמקום החזה שלו, עומדת עליהם מלמעלה, שמשום זה הם נבדלים מבחינת ראש דא\"א, ונחשבים לבחינת גוף בלי ראש, כלומר למחוסרי מוחין דחכמה, הנק' ראש מבחי' עולם אצילות, כי בדרך כלל נבחן עולם האצילות לבחינת חכמה, דכללות ד' עולמות אבי\"ע, וע\"כ המחוסר חכמה, נבחן שם לגוף בלי ראש. ויתבאר עוד להלן."],[2,"","וז\"ש, \u0003דהאי סתים עתיקא\u0004 וכו' \u0003ברא אלה\u0004, הבינה שיצאה מהראש דא\"א, מכח הנוקבא שעלתה לחכמה דא\"א, וסיימה שם בחינת הראש דא\"א, שמשום זה יצאה לבחינת בריאה וגוף דא\"א, כנ\"ל, הנה היא נחלקה משום זה לב' בחינות: ג\"ר בפ\"ע, וז\"ת בפ\"ע, מטעם, כי הבינה ממקורה בע\"ס דאור ישר, אין מטבעה לקבל חכמה כלל, אלא רק אור חסדים בלבד, בסו\"ה כי חפץ חסד הוא ולא חכמה, ((עי' בפתיחה לחכמת הקבלה אות ה') ולפיכך אין יציאתה לגוף פוגמתה כלל, שהרי אפילו בעת שהיא נמצאת בראש א\"א, אינה מקבלת ממנו חכמה, ולפיכך אין לה שום פחיתות של משהו מחמת עמידתה למטה ממלכות דראש דא\"א, ונחשבת גם עתה לבחינת ראש גמור, וכאלו לא יצאה כלל מהראש דא\"א דמיא. והיא נתקנת בסוד או\"א עילאין המלבישין לא\"א מפה עד החזה. ובחינה הב' שהיא הז\"ת דבינה, הנה הן מבחינת התכללות הזו\"ן בבינה, שהם שרשים של הזו\"ן הנמצאים בבינה, ולפיכך הם צריכים להארת חכמה בשביל הזו\"ן, וע\"כ הם נפגמו מחמת מציאותם בגוף דא\"א, שנעשו למחוסרי חכמה, והם נחשבים לבריאה, ולו\"ק בלי ראש. ועליהם נאמר אבא הוציא אמא לחוץ, דהיינו לבר מהראש דא\"א, והם נק' ישסו\"ת, ומלבישין לא\"א מחזה עד הטבור, והבנים שלהם שהם הזו\"ן, הם מלבישים מטבור ולמטה, דא\"א עד סיום עולם האצילות. וז\"ס הפרסא שבגוי מעוהי דא\"א העומדת בחזה שלו, כי היא כח המלכות שבראש דא\"א המוציא את הז\"ת דבינה לבר מראש, ומפריעתם מלקבל חכמה, כי אע\"פ שמסך הזה עומד בפה דראש א\"א, מ\"מ שם אינו פועל כלום, כי שם עומדים או\"א עילאין, שהם בחי' הג\"ר דבינה, הנחשבים עוד לבחי' ראש א\"א מטעם הנ\"ל, ונמצא כי רק במקום החזה דהיינו ממעל הז\"ת דבינה שולט כח המסך להוציא הז\"ת דבינה שמתחתיו לבר מראש דא\"א, וזכור זה."],[2,"","ולפיכך הג\"ר דבינה, נק' בשם האי סתים עתיקה, כי הראש דא\"א נק' עתיקא קדישא, וכיון שהג\"ר דבינה אע\"פ שהם מפה ולמטה דא\"א נבחנים כאלו עומדים עוד בראש דא\"א, ע\"כ נקראים גם הם בשם עתיקא כמו הראש דא\"א, אלא משום המצאם בגוף א\"א נק' בשם סתים עתיקא."],[2,"","וזה אמרו \u0003דהאי סתים עתיקא דקיימא לשאלה ברא אלה\u0004 כלומר, רק הז\"ת של האי סתים עתיקא הנק' ישסו\"ת שהם בחי' \u0003קיימא לשאלה\u0004, דהיינו לקבל בתוכם את הזו\"ן ע\"י עלית מ\"ן, כי שאלה פירושו עלית מ\"ן מלשון שואלין על הגשמים. (ריש תענית) ואומר שרק הז\"ת דהאי סתים עתיקא הנק' ישסו\"ת שהן קיימות לשאלה, דהיינו לקבל מ\"ן להמשכת אור החכמה, להיותן מחוסרי חכמה, שלפני זה הן נחשבות לבחינת בריאה, וע\"כ \u0003ברא אלה\u0004, שהם הזו\"ן הנק' אלה. ונבראו גם הם בכחם במחוסרי ראש כמהו. כי המלה ברא מורה על חסרון ראש מבחי' אצילות. וז\"ש \u0003ומאן איהו מ\"י\u0004: הז\"ת דבינה שהן עומדות לשאלה, הן הנק' מ\"י,ועליהן נופלת לשון ברא, כנ\"ל, כי הן עצמן נעשו בחינת בריאה, מחמת הפרסא שבחזה דא\"א המבדלת אותן מהארת ראש דא\"א. כנ\"ל. וז\"ש \u0003מקצה השמים לעילא דכלא קיימא ברשותיה\u0004, הז\"ת דבינה, שהן נק' ישסו\"ת ונק' מ\"י הן בחי' \u0003קצה השמים לעילא\u0004, כי השמים הם ז\"א, והוא מקבל רק מישסו\"ת הנק' \u0003מ\"י\u0004, וע\"כ נק' המ\"י \u0003קצה השמים לעילא, דכלא קיימא ברשותיה\u0004, כי השמים והארץ שהם זו\"ן וכן הג' עלמין בי\"ע התחתונים כולם מקבלים מישסו\"ת הזה הנקרא מ\"י, וע\"כ כלא קיימא ברשותיה."],[2,"","וז\"ש, \u0003לעילא לית תמן שאלה והאי קצה השמים אקרי מ\"י\u0004: כלומר, לעילא דהיינו הג\"ר דבינה, שהן או\"א עלאין, \u0003לית תמן שאלה\u0004, כי הם אינם מקבלים מ\"ן להמשכת חכמה, להיותם בעצם רק בחינת אור חסדים ואינם מחוסרי חכמה, וע\"כ אינם נק' מ\"י, גם אינם בחי' \u0003קצה השמים\u0004, כי הם אינם נזקקים לזו\"ן הצריכים להארת החכמה. ורק הז\"ת שהן ישסו\"ת שהם קיימין לשאלה, דהיינו לקבל מ\"ן מהזו\"ן ולעלות לראש דא\"א לקבל בשבילם הארת חכמה, ע\"כ נבחנים לקצה השמים לעילא, משום שהז\"א הנק' שמים מקבל מהם."],[3,"","ח) \u0003ואית אחרא לתתא\u0004 וכו': ויש אחר למטה, ונקרא \u0003מ\"ה\u0004. מה בין זה לזה. ומשיב, אלא הראשון הסתום, שנקרא \u0003מ\"י\u0004, נוהגת בו שאלה, כיון ששאל האדם וחקר להסתכל ולדעת ממדרגה למדרגה עד סוף כל המדרגות, שהוא מלכות, אחר שהגיע שמה, הוא \u0003מ\"ה\u0004. שפירושו, מה ידעת, מה הסתכלת, מה חקרת, הלא הכל סתום כבתחילה. \u0003מפשפש\u0004 פירושו חקר. כי חקר, מתרגם פשפש (איוב ח' ח')."],[3,"","ביאור הדברים, הנוקבא דז\"א, בהיותה עם הז\"א פב\"פ, נקראת גם הנוקבא בשם \u0003מ\"ה\u0004, כמו הז\"א, והיא נבחנת לבחינת קצה שמים דלתתא, כי היא סוף כל דרגין ומסיימת את האצילות, ונמצא הז\"א הנק' שמים עומד בין הישסו\"ת הנק' קצה השמים לעילא, ובין הנוק' הנק' קצה השמים לתתא. וז\"ש \u0003כיון דשאל בר נש ומפשפש לאסתכלא: לאסתכלא\u0004 היינו הזווג דאו\"א הנק' הסתכלות או\"א זה בזה ע\"י עליתם לראש דא\"א, שאז הבינה חוזרת לקבל הארת החכמה בשביל הזו\"ן, כי אפילו ישסו\"ת שהם הז\"ת דבינה אינם צריכים להארת החכמה לצורך עצמם, כי מבחינת עצמם דומים הז\"ת דבינה אל הג\"ר שלהם, ואינם נזקקים לקבל חכמה. אלא בעת שהזו\"ן עולים למ\"ן לישסו\"ת, מתעוררים הישסו\"ת בשבילם לעלות לראש דא\"א ולקבל חכמה. אבל גם הזו\"ן אינם עולים למ\"ן לישסו\"ת רק ע\"י העלאת מ\"ן מבני אדם התחתונים אל הזו\"ן. באופן שנשמות בני אדם עולות למ\"ן אל הזו\"ן, ואז עולים הזו\"ן למ\"ן אל הישסו\"ת, ואז עולים הישסו\"ת לא\"א ונעשים שם פרצוף אחד עם או\"א עילאין, ואז מסתכלים או\"א זה בזה וממשיכים חכמה בשביל הזו\"ן."],[3,"","וזה אמרו \u0003כיון דשאל בר נש\u0004 דהיינו שמעלה מ\"ן, \u0003ומפשפש\u0004 היינו שמפשפש במעשיו. כדי להעלות הזו\"ן לזווג או\"א, דהיינו \u0003לאסתכלא\u0004 בכדי שאו\"א יסתכלו זה בזה וימשיכו חכמה. \u0003ולמנדע מדרגא לדרגא עד סוף כל דרגין\u0004, כי הארת החכמה הנמשכת ע\"י עלית מ\"ן וזווג כנ\"ל, נק' בשם ידיעה, או נק' חכמה ע\"י הדעת, כי הזו\"ן העולים למ\"ן נבחנים שם לבחי' דעת לאו\"א, כי המה הגורמים לזווג שלהם, והזווג נק' בשם ידיעה, מלשון, וידע אדם את חוה אשתו. וז\"ש \u0003ולמנדע\u0004 דהיינו להמשיך המוחין בסוד הדעת \u0003מדרגא לדרגא\u0004 מדעת של מדרגת או\"א אל המוחין דמדרגת הז\"א, \u0003עד סוף כל דרגין\u0004 דהיינו מהז\"א אל הנוקבא הנק' סוף כל דרגין. וענין עלית מ\"ן )עי' בפתיחה לחכמת הקבלה אות צ\"ד וצ\"ה(. כי הבינה עומדת אב\"א עם החכמה להיותה רק בחי' חסדים, וחוזרת פב\"פ עם החכמה רק לצורך הזו\"ן. ע\"ש."],[3,"","וז\"ש \u0003כיון דמטי תמן מ\"ה\u0004: כיון שהמוחין מטי תמן אל הנוקבא דז\"א, אז נקראת הנוקבא בשם מ\"ה. ונק' כן מטעם המבואר בזוהר (תרומה דף קכ\"ז ע\"א). וז\"ל, \"\u0003דרגא תתאה דאיהו רזא דעלמא תתאה אקרי מ\"ה, ותנינן: אל תקרי מ\"ה אלא מאה\u0004,(מנחות מג:) \u0003בגין דכל דרגין עילאין באשלמותהון הכא אינון\u0004\" עכ\"ל. הרי שע\"כ נק' מ\"ה להורות שכל השלימות הגדולה של המוחין ההם באה רק אחר דמטי המוחין לנוקבא. ואומרו, \u0003מה ידעת מה אסתכלתא מה פשפשתא הא כלא סתים כדקדמיתא\u0004: גם זה מבואר בזוהר תרומה הנ\"ל, וז\"ל \u0003תו, אמאי אקרי מ\"ה, אלא אע\"ג דמשיכו עילאה דאתמשך לא אתגליא עד דאשתלים הכא, דאיהו אתר סופא דכל דרגין, סופא דאמשכותא דכולא, וקיימא באתגליא, ואע\"ג דאתגליא יתיר מכולא קיימא לשאלה, מ\"ה, מה חמית, מה ידעת, כמא דאת אמרת, כי לא ראיתם כל תמונה\u0004 עכ\"ל."],[3,"","והנך רואה דברי הזוהר, שאע\"פ שכבר נמשכו לה המוחין העליונים ע\"י העלאת מ\"ן וכבר נשלמה בהן, מ\"מ איהי קיימא לשאלה כמו שישסו\"ת היו מטרם העלאת מ\"ן. וזהו ג\"כ דברי ר' אלעזר כאן \u0003מה ידעת מה אסתכלתא מה פשפשתא הא כלא סתים כדקדמיתא\u0004, דהיינו ג\"כ כמו בזוהר תרומה, אשר אחר העלאת המ\"ן והמשכת המוחין עוד הכל סתום בנוקבא כמו מטרם העלאת מ\"ן, דהיינו דקיימא עוד לשאלה, שפירושו העלאת מ\"ן. )(כנ\"ל אות ז' בד\"ה וז\"ש לעילא. לית תמן שאלה(."],[3,"","ויש להבין הדברים, א\"כ מה מועילים התחתונים בהעלאת מ\"ן, וכן למה נמשכו אליה המוחין כיון שאינם נגלים כלל. ועוד, שהרי אומרים שם בזוהר תרומה בטעם הא' למה נקראת הנוקבא מ\"ה, משום שה\"ס, אל תקרי מ\"ה אלא מאה (מנחות מג:), שה\"ס מאה ברכות, שהנוקבא משפעת לתחתונים. ולפי\"ז איך יתכן לומר שעוד נשארת הנוקבא בבחינת קיימא לשאלה, והכל סתים כדקדמיתא."],[3,"","והענין הוא: כי יש ב' בחינות מוחין דגדלות בנוקבא, הנק' גדלות א' וגדלות ב'. אשר בגדלות א', עולים רק או\"א עילאין לראש דא\"א ולא הישסו\"ת, ואע\"פ שנעשו לפרצוף אחד, מ\"מ נשארו הישסו\"ת בגוף א\"א, אלא שנתעלו למקום או\"א שמקודם לכן, דהיינו שמלבישין מפה עד החזה דא\"א ולפיכך מצד אחד נעשו הישסו\"ת בחי' ראש א\"א, שהרי נעשו פרצוף אחד עם או\"א עילאין העומדים עתה בראש א\"א, וכן עלו למעלה מפרסא דחזה דא\"א ששם מאיר הראש דא\"א, ע\"ד שנתבאר (עי' לעיל אות ז' ד\"ה וז\"ש דהאי סתים)( באו\"א גופייהו שהיו עומדים שם מטרם העלאת מ\"ן. ומשום זה הם משפיעים מוחין שלמים דג\"ר אל הז\"א, והז\"א אל הנוקבא, והנוקבא נעשית בסוד מאה ברכות כנ\"ל, כי ע\"י מוחין אלו מתעלים הזו\"ן ועולים למקום הישסו\"ת שמקודם העלאת מ\"ן, דהיינו מחזה עד הטבור דא\"א, ונמצאת הנוק' במקום אמא, וע\"כ נעשית הנוקבא בסוד מאה כמו אמא, כי בחי' מאה היא באמא ואלפים היא באבא, והתחתון העולה לעליון נעשה כמוהו, כנודע."],[3,"","אמנם מצד אחר, דומה הנוקבא רק לבחינת מ\"י דקיימא לשאלה, דהיינו ממש לגמרי כמו שהישסו\"ת היו מטרם העלאת המ\"ן והמשכת המוחין. והוא מטעם הלבשתה את מקום הישסו\"ת דקטנות, דהיינו מהחזה עד הטבור דא\"א ונמצאת עומדת למטה מפרסא שבגוי מעוהי דא\"א, שבחינת הארת ראש דא\"א נפסק למעלה מפרסא זו, כנ\"ל(אות ז' ד\"ה וז\"ש דהאי עש\"ה).( וע\"כ מבחינה זו לא הרויחה הנוקבא את המוחין וראש א\"א, שכל העלאת המ\"ן היו לזה, והכל סתים כדקדמיתא כמטרם העלאת מ\"ן. אמנם מבחינה אחרת, הרי הרויחה הנוקבא בחינת אמא, כי עלתה למקום ישסו\"ת, שנק' אמא, שז\"ס שנעשתה בסוד מאה ברכות כנ\"ל."],[3,"","ומשום זה נבחנים אלו המוחין רק לבחינת ו\"ק דגדלות, כי לא תוכל לקבל בחינת ראש דגדלות, להיותה נמצאת למטה מפרסא דחזה דא\"א, כנ\"ל, אבל מדרגתה עתה שוה כמו הישסו\"ת בעת היותו בחינת ו\"ק, דהיינו מטרם העלאת מ\"ן, שהיה עומד שם מחזה עד הטבור דא\"א. שזה ודאי גדלות גדולה בשביל הנוקבא, אלא שהיא ו\"ק דגדלות, אבל עוד חסר ג\"ר דגדלות, והשגת ג\"ר דגדלות נק' גדלות ב' של הנוק' וזה יתבאר להלן במאמר מי ברא אלה דאליהו."],[3,"","עתה תבין היטב כוונת הזוהר תרומה הנ\"ל בב' הטעמים שאומר, על מה שנק' הנוקבא בשם מ\"ה. אשר בטעם הא' מבאר המוחין העליונים שהשיגה הנוק' הנק' מאה ברכות, שע\"כ אמרו אל תקרי מ\"ה אלא מאה, והיינו ע\"י עליתה למקום ישסו\"ת בכח אלו המוחין וטעם ב' מדגיש לבאר, אשר עכ\"ז, כיון שעלתה רק למקום הישסו\"ת דקטנות, דהיינו בעוד שהיה קיימא לשאלה, שהוא מהחזה עד הטבור דא\"א הרי גם המוחין דנוק' דומים לגמרי כמוהו, ונעשית גם הנוק' בבחינת קיימא לשאלה, שפירושו ו\"ק בלי ג\"ר, אלא הרווח אמנם גדול מאוד, מפני שהוא ו\"ק דאו\"א עילאין, דהיינו ו\"ק דגדלות. וכן גם כאן במאמר הזה, שאומר מה ידעת ומה וכו' הכל סתים כדקדמיתא, אין הפירוש של כדקדמיתא, כמו שהנוקבא היתה מטרם העלאת מ\"ן. אלא הפירוש הוא, כמו שהישסו\"ת היו מטרם העלאת מ\"ן. אבל הנוקבא הרויחה הרבה ע\"י העלאת מ\"ן שהרי קבלה עתה בחינת אמא שה\"ס מאה ברכות, אלא שהן ו\"ק דגדלות, ונמצאת עוד קיימא לשאלה כמו הישסו\"ת מטרם העלאת מ\"ן. והבן זה היטב."],[4,"","ט) \u0003ועל רזא דנא\u0004 וכו': ועל סוד זה כתוב, מה אעידך ומה אדמה לך. כי כשחרב בית המקדש, יצא קול ואמר \u0003מה\u0004 אעידך \u0003ומה\u0004 אדמה לך, דהיינו ב\u0003מ\"ה\u0004 ההוא אעידך. שבכל יום ויום העידותי בך מימים קדמונים, שכתוב, העידותי בכם היום את השמים ואת הארץ. \u0003מה\u0004 אדמה לך, באותו אפן ממש, העטרתי לך בעטרות קדושות, ועשיתי אותך ממשלה על העולם. שכתוב, הזאת העיר שיאמרו כלילת יופי וגו'. קראתי אותך, ירושלים הבנויה כעיר שחוברה לה. \u0003מה\u0004 אשוה לך, כעין שאת יושבת, כך הוא כביכול למעלה דהיינו בירושלים של מעלה. כמו שעתה אין נכנסים בך העם הקדוש בסדרים הקדושים, כך אני נשבע לך, שלא אכנוס אני למעלה עד שיכנסו בך צבאותיך למטה. וזו היא הנחמה שלך, מאחר שאני משוה לך מדרגה זו, דהיינו ירושלים של מעלה, שהיא המלכות, בכל. ועתה שאת כאן, \u0003גדול כים שברך\u0004. ואם תאמרי, שאין לך קיום ורפואה. מי ירפא לך, דהיינו אותה מדרגה הסתומה העליונה, הנקראת \u0003מ\"י\u0004, שהכל מתקיים על ידיה, שהיא בינה, תרפאך ותקים אותך. \u0003אכלוסך\u0004 פירושו גדודיך צבאותיך, כי גדוד, מתרגם אוכלסא (איוב י\"ט י\"ב)."],[4,"","ביאור הדברים, כי חורבן ביהמ\"ק היה מחמת שחטאו ישראל בע\"ז ולא רצו להעלות מ\"ן לזווג זו\"ן אלא שרצו להמשיך השפע לס\"א הנק' אלהים אחרים, שמסבה זו נפרד הזווג הנ\"ל דזו\"ן ונתבטלו מאה הברכות מן הנוקבא ונחרב ביהמ\"ק."],[4,"","וזה אמרו \u0003נפק קלא ואמר מה אעידך\u0004 וכו' \u0003בכל יומא ויומא אסהידת בך מיומין קדמאין\u0004 אלו הו\"ק דגדלות שהנוקבא מקבלת בסוד \u0003מ\"ה\u0004 כנ\"ל, נק' יומין קדמאין, וה\"ס הכתוב כי שאל נא לימים ראשונים וגו' ולמקצה השמים ועד קצה השמים וגו' (דברים ד' ל\"ב) ונק' כן להיותם ו\"ק דאו\"א, כי הישסו\"ת הוא ז\"ת דאו\"א, כנ\"ל (אות ז' ד\"ה וז\"ש דהאי ע\"ש(. וז' הימים של או\"א הם ראשונים אל ז' הימים דזו\"ן דכתיב \u0003העידותי בכם היום את השמים ואת הארץ\u0004 כי שם באותה פרשה (דברים ד' כ\"ו) כתוב פסוק זה, שפירושו על זווג זו\"ן שהם נק' שמים וארץ, שהזהיר הכתוב לשמור ולקיים את הזווג, ואם לא, מזהיר הכתוב, כי אבד תאבדון מהר מעל הארץ וכו'. וז\"ס מ\"ה אעידך, על אלו מאה ברכות הזהרתי אותך לשמרם ולעשותם, ואתה עברת עליהם לכן נתקיים בכם ח\"ו כי אבד תאבדון מהר מעל הארץ וכו'."],[4,"","וז\"ש, \u0003מ\"ה אדמה לך בההוא גוונא ממש עטרית לך בעטרין קדישין\u0004 וכו' \u0003כעיר שחוברה לה יחדיו\u0004 כי אלו מאה הברכות שהנוקבא מקבלת מהז\"א בזווג. דמ\"ה, הן בסוד עליתם לישסו\"ת, ונעשה הז\"א לבחי' ישראל סבא, והנוק' נעשתה לבחי' תבונה, ואז נעשים האורות שלה בסוד מאה ברכות כמו האורות דתבונה כנ\"ל, וע\"ז אומר הכתוב, \u0003כעיר שחוברה לה יחדיו\u0004, כי הנוק' הנק' עיר, נתחברה עם התבונה יחדיו ונעשתה הנוקבא לבחינת התבונה. והיא מקבלת משם המוחין דתבונה הנק' עטרין קדישין, ואז נק' כלילת יופי משוש כל הארץ, ומקבלת \u0003שלטנו על עלמא\u0004."],[4,"","וז\"ש, \u0003מ\"ה אשוה לך כגוונא דאנת יתבא\u0004, כלומר, שבסבת חטאם של ישראל שנחרב ביהמ\"ק ונגלו מעל אדמתם, גרמו בזה גם פירוד לנוקבא כי ט\"ס התחתוניות שלה נפלו לקליפות והיא חזרה לנקודה תחת היסוד. וז\"ש \u0003מ\"ה אשוה לך\u0004 וכו'. וז\"ש \u0003מ\"י ירפא לך\u0004: היינו אם ישובו בני ישראל בתשובה ויתקנו מעשיהם ויעלו מ\"ן לזו\"ן, הנה אז שוב ימשכו המוחין עילאין אל הזו\"ן ושוב תעלה הנוקבא לישסו\"ת הנק' \u0003מ\"י\u0004, ואז תהיה לך רפואה."],[5,"","י) \u0003מי קצה השמים\u0004 וכו': \u0003מ\"י\u0004 פירושו קצה השמים למעלה שהוא ישסו\"ת, \u0003מ\"ה\u0004, פירושו קצה השמים למטה. שהוא המלכות. וזה ירש יעקב שהוא ז\"א, שהוא מבריח מן הקצה אל הקצה. מן הקצה הראשון שהוא \u0003מ\"י\u0004, עד הקצה האחרון, שהוא \u0003מ\"ה\u0004. משום שהוא עומד באמצע בין ישסו\"ת למלכות. ועל כן, מי ברא אלה. שישסו\"ת שנקראו \u0003מ\"י\u0004 בראו את ז\"א ומלכות הנקראים \u0003אל\"ה\u0004."],[5,"","ביאור הדברים, כי לכאורה היה לו להכתוב לומר מראש השמים ועד קצה השמים, ולמה אומר מקצה ועד קצה, דהיינו מסוף עד סוף, שאין כאן כל משמעות. וז\"ש \u0003מ\"י קצה השמים לעילא\u0004, דהיינו ישסו\"ת דקיימא לשאלה המלביש מהחזה עד הטבור דא\"א. \u0003מ\"ה\u0004 היינו הנוקבא שמטרם העלאה מ\"ן שהיא סוף כל דרגין מחזה דז\"א ולמטה. וביניהם עומד יעקב, הוא ז\"א המתחיל להלביש ממקום הטבור דא\"א עד הנוקבא, ואז הוא מבריח מקצה ד\u0003מ\"י\u0004 עד הקצה ד\u0003מ\"ה\u0004. כי ה\u0003מ\"י\u0004 מסתיים בטבור דא\"א, ושם מתחיל יעקב כנ\"ל, והנוקבא שהיא \u0003מ\"ה\u0004 עומדת בסיומו כנ\"ל."],[5,"","אמנם הכתוב מדבר כבר אחר המשכת המוחין אל הזו\"ן, כמ\"ש, ברישא דקרא, שאל נא לימים הראשונים וכו', שהפירוש הוא בעת שהזו\"ן עולים ומקבלים המוחין דישסו\"ת, הנק' ימים ראשונים, כנ\"ל, שאז נמצא, שקצה השמים דלתתא שהוא \u0003מ\"ה\u0004 דהיינו הנוקבא, עלתה והלבישה על קצה השמים לעילא, דהיינו על ה\u0003מ\"י\u0004 שהוא ישסו\"ת, ונמצאים שניהם במקום אחד ממש. וע\"כ אומר הכתוב מקצה עד הקצה, שהרי עתה נעשו שניהם בחי' קצה השמים אחד. כי הימים הראשונים מקבל הז\"א, שהם ו\"ק מישראל סבא שהם חג\"ת נה\"י, והנוק' נוטלת התבונה, שהיא המלכות דבינה, הנמצאת עתה בקצה דז\"א, הנק' שמים, אלא בערך הקודם למוחין, נבחנת לראש השמים."],[5,"","ויש עוד פי' ב', אשר השמים דלעילא הוא יש\"ס, הכולל ו' הימים הראשונים, שהם חג\"ת נה\"י דבינה. וקצה השמים דלעילא הוא התבונה, שהיא המלכות דבינה. ויהיה שיעור הכתוב מהקצה דיש\"ס, עד הקצה דז\"א הנק' שמים דלתתא."],[5,"","וז\"ש \u0003ועל דא מ\"י ברא אלה\u0004: כלומר, על אלו המוחין אומר הכתוב \u0003מ\"י ברא אלה\u0004 כי \u0003מ\"י\u0004 הוא ישסו\"ת העומד במקום בריאה דא\"א, דהיינו מחזה עד הטבור, למטה מפרסא שבגוי מעוהי דא\"א, ששם אינה מגיעה עוד הארת ראש דא\"א, (כנ\"ל אות ז' ד\"ה וז\"ש דהאי, ע\"ש). דע\"כ נבחן לבריאה דהיינו לבר מראש דא\"א, וע\"כ הוא קיימא לשאלה, כנ\"ל. ונמצא אחר שהזו\"ן משיגים אלו המוחין שהם עולים ומלבישים את המ\"י הזה ונוטלים מקומו מהחזה עד הטבור דא\"א, הרי גם המוחין שלהם עתה רק בבחינת בריאה דא\"א, וז\"ש הכתוב, \u0003מ\"י ברא אלה\u0004 שהם הזו\"ן, כלומר הזו\"ן נטלו מוחין דבריאה מן ה\u0003מ\"י\u0004."],[6,"","יא) \u0003אמר ר\"ש\u0004 וכו': אמר ר' שמעון: אלעזר בני, עמוד מלדבר, ותתגלה סתימת הסוד העליון, שבני העולם אינם יודעים אותו. שתק ר' אלעזר. בכה ר\"ש, ועמד רגע אחד. א\"ר שמעון: אלעזר, מהו \u0003אל\"ה\u0004. אם תאמר, שהוא הכוכבים והמזלות, הלא תמיד הם נראים. ובמ\"ה, שהיא מלכות, נבראו. כמו שאתה אומר, בדבר ה' שמים נעשו. דהיינו, במלכות הנקראת דבר ה', נעשו השמים. ואם אל\"ה נאמר על הדברים הסתומים, לא היה צריך שיכתוב \u0003אל\"ה\u0004, שהרי ככבים ומזלות גלויים הם."],[6,"","ביאור הדברים, כי ר' אלעזר לא גילה כאן אלא בחינת המוחין דגדלות א', ור\"ש היה רוצה לגלות סוד המוחין דגדלות ב', שהוא מוחין עילאין דחיה. ע\"כ צוה לו לפסוק דבריו, ויגלה לו סתימא דרזא עילאה דבני עלמא לא ידעין ליה, כי עוד לא היו נגלים מוחין אלו בעולם ור\"ש גילה אותם כאן."],[6,"","וזה אמרו, \u0003מאי אלה, אי תימא ככביא ומזלי\u0004 וכו', ר\"ש שאל לו, מאי אלה, איזה חידוש משמיענו הכתוב במ\"י ברא אלה, שהם הזו\"ן, אי תימא ככביא ומזלי, דהיינו על המוחין דו\"ק דגדלות שהשיגו, וע\"ז סובב הכתוב מ\"י ברא אלה, כי מוחין דו\"ק נק' ככביא ומזלי. ע\"ז הקשה, איזה חידוש הוא, \u0003הא מתחזי תמן תדיר\u0004, כלומר, הלא הם המוחין הרגילים של הזו\"ן, שאפשר להמשיכם תמיד, דהיינו אפי' בימות החול, ואינם חידוש כל כך שעליהם יראה הכתוב \u0003מ\"י\u0004 ברא אלה."],[6,"","ואין לפרש שהמוחין האלו נוהגים תדיר בלי הפסק, כי זה אינו כן, שהרי בקביעות אין לז\"א אלא ו\"ק בלי ראש, ורק על ידי העלאת מ\"ן ותפלה ממשיכים אלו המוחין. אלא הפירוש הוא כנ\"ל, שאפשר להמשיכם תדיר, היינו אפילו בימות החול. כי כן הם נמשכים בכל יום בעת תפילת שחרית. ועוד מקשה לו \u0003ובמ\"ה אתבריאו\u0004 כי אלו המוחין אינם מיוחסים לבינה אלא לזו\"ן דאצילות הנק' \u0003מ\"ה\u0004, שמהם יצאו, כמ\"ש \u0003בדבר ה'\u0004 שהוא ז\"א ונוקביה, הז\"א נק' \u0003ה'\u0004, והנוק' \u0003דבר\u0004."],[7,"","יב) \u0003אלא רזא דא\u0004 וכו': אלא סוד זה לא נתגלה, אלא ביום אחד שהייתי על חוף הים, ובא אליהו ואמר לי: רבי, הידעת מהו \u0003מי ברא אלה\u0004. אמרתי לו, אלו הם, השמים וצבאם, מעשה הקב\"ה, שיש לבני אדם להסתכל בהם ולברך אותו. שכתוב, כי אראה שמיך מעשה אצבעותיך וגו', ה' אדוננו מה אדיר שמך בכל הארץ."]],[[0,"","(שהוא עולם הבא, עולם הנשמות, עולם הנחמות). (נ\"א: דבר אחר) הַנִּצָּנִים - אֵלּוּ הֵם הָאָבוֹת שֶׁנִּכְנְסוּ בַּמַּחֲשָׁבָה וְנִכְנְסוּ לָעוֹלָם הַבָּא וְנִגְנְזוּ שָׁם, וּמִשָּׁם יָצְאוּ בִּגְנִיזוּת וְנִסְתְּרוּ בְּתוֹךְ נְבִיאֵי הָאֱמֶת. נוֹלַד יוֹסֵף וְנִטְמְנוּ בוֹ. נִכְנַס יוֹסֵף לָאָרֶץ הַקְּדוֹשָׁה וְהִצִּיב אוֹתָם שָׁם, וְאָז נִרְאוּ בָאָרֶץ וְנִגְלוּ שָׁם. וּמָתַי הֵם נִרְאוּ בְּשָׁעָה שֶׁהִתְגַּלְּתָה הַקֶּשֶׁת בָּעוֹלָם. שֶׁהֲרֵי בְּשָׁעָה שֶׁנִּרְאֵית הַקֶּשֶׁת, אָז הֵם מִתְגַּלִּים, וּבַשָּׁעָה הַהִיא עֵת הַזָּמִיר הִגִּיעַ לְקַצֵּץ אֶת הָרְשָׁעִים מִן הָעוֹלָם. לָמָּה נִצְּלוּ מִשּׁוּם שֶׁהַנִּצָּנִים נִרְאוּ בָאָרֶץ, וְאִלְמָלֵא שֶׁנִּרְאוּ, לֹא הָיוּ נִשְׁאָרִים בָּעוֹלָם, וְהָעוֹלָם לֹא הָיָה מִתְקַיֵּם."],[1,"","וּמִי מְקַיֵּם אֶת הָעוֹלָם וְגוֹרֵם לָאָבוֹת לְהִתְגַּלּוֹת קוֹל הַתִּינוֹקוֹת שֶׁעוֹסְקִים בַּתּוֹרָה. וּבִגְלַל אוֹתָם הַתִּינוֹקוֹת שֶׁל הָעוֹלָם, הָעוֹלָם נִצָּל. כְּנֶגְדָּם (שיר א) תּוֹרֵי זָהָב נַעֲשֶׂה לָּךְ, אֵלּוּ הֵם תִּינוֹקוֹת יְלָדִים עֲלָמִים, שֶׁכָּתוּב (שמות כה) וְעָשִׂיתָ שְׁנַיִם כְּרֻבִים זָהָב."],[2,"","בְּרֵאשִׁית, רַבִּי אֶלְעָזָר פָּתַח, (ישעיה מ) שְׂאוּ מָרוֹם עֵינֵיכֶם וּרְאוּ מִי בָרָא אֵלֶּה. שְׂאוּ מָרוֹם עֵינֵיכֶם, לְאֵיזֶה מָקוֹם לַמָּקוֹם שֶׁכָּל הָעֵינַיִם תְּלוּיִים בּוֹ, וּמִי הוּא פֶּתַח עֵינַיִם, וְשָׁם תֵּדְעוּ שֶׁהַסָּתוּם הָעַתִּיק הַזֶּה שֶׁעוֹמֵד לַשְּׁאֵלָה בָּרָא אֵלֶּה. וּמִי הוּא \"מִי\", הַהוּא שֶׁנִּקְרָא מִקְצֵה הַשָּׁמַיִם לְמַעְלָה, שֶׁהַכֹּל עוֹמֵד בִּרְשׁוּתוֹ. וְעַל שֶׁהוּא עוֹמֵד לַשְּׁאֵלָה וְהוּא בְּדֶרֶךְ נִסְתָּר וְלֹא גָלוּי נִקְרָא \"מִי\", שֶׁהֲרֵי לְמַעְלָה אֵין שָׁם שְׁאֵלָה. וּקְצֵה הַשָּׁמַיִם הַזֶּה נִקְרָא \"מִי\"."],[3,"","וְיִשִׁ אַחֵר לְמַטָּה שֶׁנִּקְרָא \"מָה\". מַה בֵּין זֶה לָזֶה אֶלָּא הָרִאשׁוֹן הַנִּסְתָּר שֶׁנִּקְרָא \"מִי\" עוֹמֵד לַשְּׁאֵלָה. כֵּיוָן שֶׁשּׁוֹאֵל אָדָם וּמְפַשְׁפֵּשׁ לְהִסְתַּכֵּל וְלָדַעַת מִדַּרְגָּה לְדַרְגָּה עַד סוֹף כָּל הַדְּרָגוֹת, כֵּיוָן שֶׁמַּגִּיעַ לְשָׁם - \"מָה\". מַה יָּדַעְתָּ מַה הִסְתַּכַּלְתָּ מַה פִּשְׁפַּשְׁתָּ הֲרֵי הַכֹּל נִסְתָּר כְּבָרִאשׁוֹנָה."],[4,"","וְעַל הַסּוֹד הַזֶּה כָּתוּב (איכה ב) מָה אֲעִידֵךְ מָה אֲדַמֶּה לָּךְ. כְּשֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ, יָצָא קוֹל וְאָמַר, מָה אֲעִידֵךְ (נ\"א: (ומה) מה אדמה לך, באותו מ\"ה אעידך) בְּכָל יוֹם וָיוֹם, (והרי) הַעִידתִי בָּךְ מִיָּמִים רִאשׁוֹנִים, שֶׁכָּתוּב (דברים ל) הַעִדתִי בָכֶם הַיּוֹם אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ. וּמָה אֲדַמֶּה לָּךְ, בְּאוֹתוֹ גָוֶן מַמָּשׁ עִטַּרְתִּי אוֹתָךְ בַּעֲטָרוֹת קְדוֹשׁוֹת, עָשִׂיתִי לָךְ שִׁלְטוֹן עַל הָעוֹלָם, שֶׁכָּתוּב (איכה ב) הֲזֹאת\" הָעִיר\" שֶׁיֹּאמְרוּ\" כְּלִילַת\" יֹפִי\" וְגוֹ'. קָרָאתִי לָךְ (תהלים קכב) יְרוּשָׁלַיִם הַבְּנוּיָה כְּעִיר שֶׁחֻבְּרָה לָּהּ. (איכה ב) מָה אַשְׁוֶה לָּךְ - כְּמוֹ שֶׁאַתְּ יוֹשֶׁבֶת כָּךְ, כָּךְ הוּא כִּבְיָכוֹל לְמַעְלָה. כְּמוֹ שֶׁלֹּא נִכְנָסִים בָּךְ עַכְשָׁו הָעָם הַקָּדוֹשׁ בִּסְדָרִים קְדוֹשִׁים, כָּךְ נִשְׁבַּעְתִּי לָךְ שֶׁאֵינִי נִכְנָס לְמַעְלָה עַד שֶׁיִּכָּנְסוּ בָךְ אוּכְלוּסַיִךְ לְמַטָּה. וְזוֹהִי נֶחָמָתֵךְ, הוֹאִיל שֶׁהַדַּרְגָּה הַזּוֹ אַשְׁוֶה לָךְ בַּכֹּל. וְעַכְשָׁו שֶׁאַתְּ כָּאן, גָּדוֹל כַּיָּם שִׁבְרֵךְ. וְאִם תֹּאמַר שֶׁאֵין לְךְ קִיּוּם וּרְפוּאָה - מִ\"י יִרְפָּא לָךְ. וַדַּאי שֶׁאוֹתָהּ הַדַּרְגָּה הַנִּסְתֶּרֶת הָעֶלְיוֹנָה שֶׁהַכֹּל עוֹמֵד בָּהּ, תִּרְפָּא לְךְ וְתָקִים אוֹתְךְ."],[5,"","מִ\"י - קְצֵה הַשָּׁמַיִם לְמַעְלָה, מָ\"ה - וְעַד קְצֵה הַשָּׁמַיִם לְמַטָּה (קצה השמים למטה). וְזֶה יָרַשׁ יַעֲקֹב, שֶׁהוּא מַבְרִיחַ מִן הַקָּצֶה אֶל הַקָּצֶה. מֵהַקָּצֶה הָרִאשׁוֹן שֶׁהוּא מִ\"י, אֶל הַקָּצֶה הָאַחֲרוֹן שֶׁהוּא מָ\"ה, מִשּׁוּם שֶׁעוֹמֵד בָּאֶמְצַע. וְעַל זֶה מִי בָרָא אֵלֶּה."],[6,"","אָמַר רַבִּי שִׁמְעוֹן, אֶלְעָזָר (בני), פְּסֹק דְּבָרֶיךְ וְיִתְגַּלֶּה הַסֵּתֶר שֶׁל הַסּוֹד הָעֶלְיוֹן שֶׁאֵין בְּנֵי אָדָם יוֹדְעִים. שָׁתַק רַבִּי אֶלְעָזָר. בָּכָה רַבִּי שִׁמְעוֹן וְעָמַד רֶגַע (נ\"א: שעה) אֶחָד. אָמַר רַבִּי שִׁמְעוֹן, אֶלְעָזָר, מַה זֶּה \"אֵלֶּה\" אִם תֹּאמַר כּוֹכָבִים וּמַזָּלוֹת - הֲרֵי הֵם תָּמִיד נראיּם שָּם, וּבְמָּ\"ה נבְרְאוּ כְּמוֹ שֶׁנֶּאֱמַר (תהלים לג) בִּדְבַר ה' שָׁמַיִם נַעֲשׂוּ. אִם עַל דְּבָרִים נִסְתָּרִים, שֶׁלֹּא יִכְתֹּב אֵלֶּה, שֶׁהֲרֵי הוּא גָּלוּי!"],[7,"","אֶלָּא זֶה הַסּוֹד לֹא הִתְגַּלָּה רַק יוֹם אֶחָד שֶׁהָיִיתִי עַל חוֹף הַיָּם, וּבָא אֵלִיָּהוּ וְאָמַר לִי, רַבִּי, יָדַעְתָּ מַה זֶּה \"מִי בָרָא אֵלֶּה\" אָמַרְתִּי לוֹ, אֵלּוּ הַשָּׁמַיִם וְצִבְאוֹתָם, הַמַּעֲשֶׂה שֶׁל הַקָּדוֹשׁ- בָּרוּךְ-הוּא שֶׁיֵּשׁ לָאָדָם לְהִסְתַּכֵּל בָּהֶם וּלְבָרֵךְ אוֹתוֹ, שֶׁכָּתוּב (שם ח) כִּי אֶרְאֶה שָׁמֶיךְ מַעֲשֵׂה אֶצְבְּעֹתֶיךְ וְגוֹ', ה' אֲדנֵנוּ מָה אַדִּיר שִׁמְךְ בְּכָל הָאָרֶץ."]]],[["אָמַר לִי רִבִּי מִלָּה סְתִימָא הֲוָה קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְגָלֵי בִּמְתִיבְתָּא עִלָּאָה וְדָא הוּא. בְּשַׁעְתָּא דִּסְתִימָא דְכָל סְתִימִין בָּעָא לְאִתְגַּלְּיָא, עֲבַד בְּרֵישָׁא נְקוּדָ\"ה (להלן ט\"ו א', משפטים ק\"ה א', ט' ב', שמות רכ\"ו ב', רכ\"ח א) חֲדָא, וְדָא סָלִיק לְמֶהוֵי מַחֲשָׁבָה. צִיֵּיר בָּהּ כָּל צִיּוּרִין. חָקַק בָּהּ כָּל גְּלִיפִין.","וְאַגְלִיף גּוֹ בּוֹצִינָא קַדִּישָׁא סְתִימָא גְּלִיפוּ דְּחַד צִיּוּרָא סְתִימָאָה קֹדֶשׁ קַדִּישִׁין בִּנְיָינָא עֲמִיקָא דְּנָפַק מִגּוֹ מַחֲשָׁבָה וְאִקְרֵי מִ\"י שֵׁירוּתָא (נ\"א ראשיתא) לְבִנְיָנָא. קַיָּימָא וְלָא קַיָּימָא. עָמִיק וְסָתִים בִּשְׁמָא. לָא אִקְרֵי אֶלָּא מִ\"י. בָּעָא לְאִתְגַּלְיָיא וּלְאִתְקְרֵי בִּשְׁמָא (דא) וְאִתְלַבַּשׁ בִּלְבוּשׁ יְקָר דְּנָהִיר וּבָרָא אֵלֶּה, וְסָלִיק אֵלֶּ\"ה בִּשְׁמָא. אִתְחַבְּרוּן אַתְוָון אִלֵּין בְּאִלֵּין וְאִשְׁתְּלִים בִּשְׁמָא אֱלֹהִים. וְעַד לָא בָרָא אֵלֶּה לָא סָלִיק בִּשְׁמָא אֱלֹהִים. וְאִנּוּן דְּחָבוּ בְּעֶגְלָא (נ\"א בעלמא). עַל רָזָא דְנָא אָמְרוּ (שמות לכ) אֵלֶּה אֱלֹהֶיךָ יִשְׂרָאֵל.","וּכְמָה דְּאִשְׁתַּתַּף מִ\"י בְּאֵלֶּה, הָכִי הוּא שְׁמָא דְּאִשְׁתַּתַּף תָּדִיר. וּבְרָזָא דָא אִתְקַיֵּים עָלְמָא. וּפְרַח אֵלִיָּהוּ וְלָא חָמֵינָא לֵיהּ. וּמִנֵּיהּ יְדַעְנָא מִלָּה (דא) דְאוֹקִימְנָא (וקאימנא) עַל רָזָא וְסִתְרָא דִילָהּ. אֲתָא רִבִּי אֶלְעָזָר וְכֻלְהוּ חַבְרַיָיא וְאִשְׁתְּטָחוּ קַמֵּיהּ. בָּכוּ וְאָמְרוּ אִלְמָלֵא לָא אֲתֵינָא לְעָלְמָא אֶלָּא לְמִשְׁמַע דָּא דַּיַּי.","אָמַר רִבִּי שִׁמְעוֹן עַל דָּא שְׁמַיָא וְחֵילֵיהוֹן בְּמָּ\"ה אִתְבְּרִיאוּ, דִּכְתִיב (תהלים שם) כִּי אֶרְאֶה שָׁמֶיךָ מַעֲשֵׂה אֶצְבְּעוֹתֶיךָ וְגו' וּכְתִיב, (תהלים שם) מָ\"ה אַדִּיר שִׁמְךָ בְּכָל הָאָרֶץ אֲשֶׁר תְּנָה\" הוֹדְךָ\" עַל\" הַשָּׁמָיִם\", עַל הַשָּׁמַיִם אִיהוּ לְסַלְקָא בִּשְׁמָא. בְּגִין דְּבָרָא נְהוֹרָא לִנְהוֹרֵיהּ וְאִתְלַבַּשׁ דָּא בְדָא וְסָלִיק בִּשְׁמָא עִלָּאָה. וְעַל דָּא בְּרֵאשִׁית בָּרָא אֱלהִים, דָּא אֱלֹהִים עִלָּאָה, דְּהָא מָ\"ה לָא הֲוֵי הָכִי וְלָא אִתְבְּנֵי.","אֶלָּא בְּשַׁעֲתָא דְּאִתְמַשְּׁכָן אַתְוָון אִלֵּין (מאילין) אֵלֶּ\"ה מִלְּעֵילָא לְתַתָּא. וְאִמָּא אוֹזִיפַת לִבְרָתָא מֵאנַּהָא, וְקַשֵּׁיטָא לָהּ בְּקִישׁוּטְהָא. וְאֵימָתַי קַשֵּׁיטָא לָהּ בְּקִישּׁוּטְהָא כְּדַקָּא חַזֵי. בְּשַׁעֲתָא דְּאִתְחֲזוֹן קָמָהּ כָּל דְּכוֹרָא, דִּכְתִיב אֶל פְּנֵי הָאָדוֹן יְיָ, וְדָא אִקְרֵי אָדוֹן כְּמָא דְאַתְּ אָמֵר, (יהושע ג׳:י״א) הִנֵּה אֲרוֹן הַבְּרִית אֲדוֹן כָּל הָאָרֶץ. כְּדֵין נַפְקַת ה' וְאָעִילַת י', וְאִתְקַשִּׁיטַת בְּמָאנֵי דְכוּרָא לְקָבְלֵיהוֹן דְּכָל דְּכַר בְּיִשְׂרָאֵל.","וְאַתְוָון אָחֳרָנִין מָשְׁכָן לוֹן יִשְׂרָאֵל מֵעֵילָא לְגַבֵּי אֲתַר דָּא (תהילים מ״ב:ה׳) אֵלֶּה אֶזְכְּרָה. אַדְכַּרְנָא בְּפוּמָאי וְשָׁפִיכְנָא דִּמְעָאי (ברעות נפשי בגין לאמשכא אתוון אלין) וּכְדֵין אֱדַדֵּם מֵעֵילָא עַד בֵּית אֱלֹהִים, לְמֶהֱוֵי אֱלהִים כְּגַוְונָא דִילֵיהּ. וּבְמַאי, (תהילים מ״ב:ה׳) בְּקוֹל רִנָּה וְתוֹדָה הָמוֹן חוֹגֵג. אָמַר רִבִּי אֶלְעָזָר שְׁתִיקָא דִילִי בְּנָא מַקְדְּשָׁא לְעֵילָא וּבְנָא מַקְדְּשָׁא לְתַתָּא. וּבְוַדַּאי מִלָּה בְּסֶלַע מִשְׁתּוֹקָא בִּתְרֵין. מִלָּה בְּסֶלַע מַה דְּאָמַרְנָא וְאִתְעַרְנָא בֵּיהּ, מִשְׁתּוֹקָא בִּשְׁתַּיִם מַה דְּשָׁתִיקְנָא דְּאִבְרוּ וְאִיבְנוּ תְּרִין עָלְמִין כְּחֲדָא.","אֲמַר רִבִּי שִׁמְעוֹן מִכָּאן וּלְהָלְאָה שְׁלִימוּ דִקְרָא, דִּכְתִיב, (ישעיהו מ׳:כ״ו) הַמּוֹצִיא בְּמִסְפָּר צְבָאָם, תְּרֵין דַּרְגִּין אִנּוּן דְּאִיצְטְרִיךְ לְמֶהֱוֵי רְשִׁים כָּל חַד מִינַיְיהוּ. חַד דָּא דְּאִתָּמַר מָ\"ה. וְחַד מִ\"י. דָא עִלָּאָה וְדָא תַתָּאָה. דָּא עִלָּאָה רָשִׁים וְאָמַר (שמות קסח ב', וקלח ב) הַמּוֹצִיא בְּמִסְפַּר צְבָאָם, הַמּוֹצִיא הַהוּא דְּאִשְׁתְּמוֹדַע וְלֵית כַּוָּותֵיהּ. כְּגַוְונָא דָא הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ. הַמּוֹצִיא הַהוּא דְאִשְׁתְּמוֹדְעָא דָּא דַרְגָא תַתָּאָה, וְכֹלָא חַד. בְּמִסְפַּר שִׁתִּין רִבּוֹא אִנּוּן דְּקַיָּימִין כְּחֲדָא, וְאַפִּיקוּ חֵילִין לְזִינַיְיהוּ דְּלֵית לוֹן חֻשְׁבְּנָא.","(נ\"א כגוונא דא) לְכֻלָּם, בֵּין אִנּוּן שִׁתִּין, בֵּין כָּל חֵילִין דִּילְהוֹן, בְּשֵׁם יִקְרָא. מַאי בְּשֵׁם יִקְרָא. אִי תֵימָא דְּקָרָא לוֹן בִּשְׁמָהַתְהוֹן, לָאו הָכִי הוּא, דְאִם כֵּן בִּשְׁמוֹ מִבָּעֵי לֵיהּ. אֶלָּא בְּזִמְנָא דְדַרְגָא דָא לָא סָלִיק בִּשְׁמָא (לעילא) וְאִקְרֵי מִ\"י, לָא אוֹלִיד וְלָא אַפִּיק טְמִירִין לְזִינֵיהּ אַף עַל גַּב דְּכֻלְהוּ הֲווּ טְמִירִין בֵּיהּ. כֵּיוָן דְּבָרָא אֵלֶּ\"ה וְאִסְתַּלַּק בִּשְׁמֵיהּ וְאִקְרֵי אֱלֹהִים, כְּדֵין בְּחֵילָא דִּשְׁמָא דָא אַפִּיק לוֹן בִּשְׁלִימוּ, וְדָא הוּא בְּשֵׁם יִקְרָא, בְּהַהוּא שֵׁם דִּילֵיהּ קְרָא וְאַפִּיק כָּל זִינָא וְזִינָא לְאִתְקַיְימָא בִּשְׁלִימוּתֵיהּ. כְּגַוְונָא דָא (שמות ל״א:ב׳) רְאֵה קָרָאתִי בְשֵׁם. אַדְכַּרְנָא שְׁמִי לְאִתְקְיָימָא בְּצַלְאֵל עַל קִיּוּם אַשְׁלָמוּתֵיהּ."],[[0,"","יג) \u0003א\"ל רבי\u0004 וכו': אמר לי: רבי, דבר סתום היה לפני הקב\"ה, וגילה אותו בישיבה של מעלה, וזה הוא. בשעה שהסתום מכל סתומים רצה להתגלות, עשה בתחילה נקודה אחת, שהיא מלכות, וזו עלתה להיות מחשבה, שהיא בינה, כלומר שהמלכות עלתה ונכללה בבינה. צייר בה את כל הציורים, חקק בה כל החקיקות."],[0,"","ביאור הדברים, פרצוף עתיק הוא הראש הא' של עולם האצילות, והוא נק' סתימא דכל סתימין. ועליו אמרו באדרא רבא (אות קע\"ד ) \u0003כל רישא דעמא דלא אתתקן הוא בקדמיתא לית עמא מתתקנא. מנא לן. מעתיק יומין, דעד דלא אתתקן הוא בתיקונוי לא אתתקנו כל אינון דבעי לאתתקנא, וכלהו עלמין אחרבו\u0004. וכן איתא באדרא זוטא (אות ע\"ד ). \u0003תאנא, בשעתא דעתיקא קדישא סתימא דכל סתימין בעא לאתתקנא, כלא אתקין כעין דכר ונוקבא\u0004 וכו' \u0003דהאי חכמה אתפשט ואפיק מיניה בינה, ואשכח דכר ונוקבא\u0004 וה\"ס התיקון דצמצום ב'."],[0,"","וזהו שמבאר כאן ואמר \u0003בשעתא דסתימא דכל סתימין בעא לאתגלייא עבד ברישא נקודה חדא\u0004. שבעת שעתיקא קדישא רצה להתגלות לעולמות, בכח התיקון דאתתקן בצמצום ב', הוא \u0003עבד ברישא\u0004 דא\"א, דהיינו בחכמה שלו \u0003נקודה חדא\u0004, דהיינו שהעלה המלכות הנק' נקודה לבחי' רישא דא\"א, ושם נתתקנה הנוק' המעלה או\"ח להלביש ע\"ס דראש א\"א, ונסתיים הראש דא\"א בספי' החכמה סתימתה, \u0003ואשתכח\u0004 החכמה \u0003כדו\"נ\u0004 ובינה וזו\"ן דראש א\"א יצאו לבר מהראש דהיינו למדרגת הגוף דא\"א. וז\"ס \u0003חכמה אתפשט ואפיק מיניה בינה\u0004 דהיינו שחכמה הוציאה לבחינת גוף."],[0,"","וז\"ש, \u0003ודא סליק למהוי מחשבה\u0004: כלומר, נקודת המלכות הזו אשר עלתה לחכמה והחכמה נתקנה על ידה כדכר ונוקבא, היא עלתה משום זה ונעשתה למחשבה דהיינו לבחי' בינה הנקראת מחשבה. והטעם הוא פשוט, כי כיון שעומדת בזווג עם חכמה, היא מקבלת מחכמה, והמקבל מחכמה נבחן לבינה, ולא למלכות. ונמצא שאעפ\"י שמשורשה היא מלכות ובחי' נקודה, הרי נעשתה, מחמת העליה לבחי' בינה. וז\"ש \u0003ודא סליק למהוי מחשבה\u0004 שזה גרם אל הנקודה למהוי בינה הנקראת מחשבה."],[0,"","ודע, כי לפעמים נק' בזוהר, השם מחשבה על החכמה ופעמים על הבינה, והענין הוא, כי מחשבה, פירושה, הנוק' דחכמה, וע\"כ יש לכנותה בשם חכמה, כי היא הנוק' דחכמה, אמנם מעצם בחינתה הנה היא בינה ולא חכמה, כנ\"ל. אכן אין הבינה נקראת בשם מחשבה רק בהיותה בחינת ראש ביחד עם החכמה. וזכור זה."],[0,"","וז\"ש, \u0003צייר בה כל ציורין חקק בה כל גליפין\u0004, כי בהאי נקודה דסליק למהוי מחשבה צייר וחקק כל ה' פרצופי אצילות, שהם א\"א או\"א וזו\"ן. וז\"ש, \u0003צייר בה, וחקק בה\u0004, רומז בזה לענין רב, כי \u0003צייר בה\u0004 פירושו, שנאצל על ידה כלהו ציורין, שהם ה\"פ אצילות דהיינו ע\"י הזווג שנעשה על המסך דהאי נקודה דסלקא למהוי מחשבה, יצאו קומת ו\"ק דאו\"ח ואו\"י בכלים דכתר וחכמה בכל פרצוף ופרצוף. אבל \u0003חקק בה כל גליפין\u0004, פירושו ענין חסרון, דהיינו שעם עלית הנקודה למהוי מחשבה, נעשו חסרונות וחקיקות, שהם הכנות לבחי' בית קבול על האורות בכלהו פרצופי אצילות. ומתוך שענין זה הוא יסוד כל המוחין דאצילות, יש לבארו היטב."],[0,"","והענין הוא, כי עלית הנקודה לבחינת מחשבה שהיא בינה, נמצא בזה שנעשה סיום חדש בע\"ס דכל מדרגה, כי הנקודה, שה\"ס המלכות עם המסך שבה, שהיתה עומדת לזווג במקום מלכות של ע\"ס דראש הנק' פה, וסיימה שם, בחי' הראש, עלתה עתה למקום הבינה של ראש הנק' נקבי עינים, דהיינו נוקבא דחכמה שהיא בינה, ונעשה הזווג על המסך שלה, שם במקום נקבי עינים וסיימה שם את הראש, וג' הספירות בינה ז\"א ומלכות של הראש הנק' אח\"פ, ירדו מתחת מקום הסיום של הראש, דהיינו למדרגת גוף. ועד\"ז נעשה בהכרח גם בע\"ס דגוף, אשר המלכות המסיימת את הגוף של הפרצוף, שהיתה עומדת מקודם לכן במקום הנקודה האמצעית שהיא המלכות דע\"ס דגוף, הנק' סיום רגלין, עלתה עתה למקום בינה של הגוף, הנקראת ת\"ת, כי חג\"ת דגוף הם כח\"ב, וסיימה את הגוף שם בת\"ת במקום החזה, ואלו ג' הספירות בינה וזו\"ן דגוף הנק' תנהי\"ם. יצאו מבחינת אצילות ונפלו לבחי' בי\"ע דפרודא."],[0,"","הרי שבסבת עלית הנקודה למהוי מחשבה נבקעה כל מדרגה לב' חצאים שחציו העליון, שהם כתר חכמה נשארו במדרגה, והבינה וז\"א ונוקבא דכל מדרגה נאבדו ממנה וירדו למדרגה שמתחתיה. וז\"ס ענין התחלקות של השם אלהים על \u0003מ\"י אל\"ה\u0004, כי מדרגה שלמה בע\"ס כח\"ב זו\"ן נק' בשם קדוש אלהים, שבו ה' אותיות נגד ה' ספי' כח\"ב זו\"ן, ש\u0003אל\"ה\u0004 הן כח\"ב, \u0003י\"ם\u0004 הן זו\"ן, ועתה אחר שנחלקה כל מדרגה לב' חצאים, שכתר וחכמה נשארו, ובינה וזו\"ן נפלו ממנה, כנ\"ל, נמצא כי לא נשארו בכל מדרגה, זולת ב' האותיות \u0003מ\"י\u0004, וג' אותיות \u0003אל\"ה\u0004 נפלו מכל מדרגה למדרגה שמתחתיה."],[0,"","ואין לשאול, כי לפי\"ז היו צריכות להשאר ב' אותיות \u0003א\"ל\u0004 במדרגה, ו\u0003הי\"מ\u0004 היו צריכות לנפול ממנה להמדרגה התחתונה. והענין הוא שיש תמיד ערך הפוך בין הכלים לאורות. כי זה הכלל, בכלים באים העליונים מתחלה, דהיינו תחלה בא הכלי דכתר ואח\"כ הכלי דחכמה וכו' עד כלי המלכות לבסוף. והיפוכו הוא באורות שבהם באים התחתונים תחילה מתחילה בא אור המלכות, ואח\"כ אור הז\"א, ואח\"כ אור הבינה, וכו' עד אור הכתר לבסוף. ולפיכך אם אין מבחינה הכלים אלא ב' הכלים של כתר ושל חכמה, הרי אין בהם אלא ב' האורות, אור המלכות ואור הז\"א, הנק' ו\"ק. ולפיכך אנו מבחינים שרק ב' האותיות מ\"י נשארו, במדרגה שה\"ס אור המלכות ואור הז\"א של השם אלהים, אבל ג' אותיות \u0003אל\"ה\u0004 נפלו מהם, וע\"כ נעשתה כל מדרגה מחוסרת ג\"ר שבה."],[0,"","וזה אמרו \u0003צייר בה כל ציורין חקק בה כל גליפין\u0004 שרומזין בזה על התחלקות כל מדרגה לב' חצאים מכח סליקת הנקודה למהוי מחשבה, \u0003צייר בה כל ציורין\u0004 היינו על ב' האותיות מ\"י שנשארים בכל המדרגה צייר הציור דאו\"י. \u0003חקק בה כל גליפין\u0004 היינו ג' האותיות \u0003אל\"ה\u0004 שנפלו מכל מדרגה ונחסרה מהם, כי מסבת חסרונן לא נשאר במדרגה זולת אור המלכות ואור הז\"א, וג' האורות דכח\"ב חסרים מהן, כי אין אור בלי כלי. באופן שאם שוב ישיגו הכלים דבינה וזו\"ן תיכף ישיגו גם ג\"ר דאורות. כי זה תלוי בזה. וזכור דברים האלו המבוארים כאן, כי הם יסוד כל החכמה."],[1,"","יד) \u0003ואגליף גו בוצינא\u0004 וכו': וחקק בתוך הנר הקדוש הסתום, שהיא המלכות שנכללה בבינה, חקיקה של ציור סתום אחד, קדש קדשים, שהוא בנין עמוק היוצא מתוך המחשבה, שה\"ס ג\"ר, ונקרא \u0003מ\"י\u0004, שהוא התחלה אל הבנין. והוא עומד ואינו עומד, הוא עמוק וסתום בשם אלקים, ועוד אינו נקרא אלא \u0003מ\"י\u0004 דאלקים, דהיינו שחסרות אותיות \u0003אלה\u0004 מהשם אלקים. רצה להתגלות ולהקרא בשם זה אלקים, הוא התלבש בלבוש יקר המאיר, שהוא אור החסדים. וברא \u0003אל\"ה\u0004, ועלו אותיות \u0003אל\"ה\u0004 בשם אלקים, שנתחברו אותיות אלו באלו, דהיינו אותיות \u0003מ\"י\u0004 באותיות \u0003אל\"ה\u0004, ונשלם השם \u0003אלהים\u0004. וכל עוד שלא ברא \u0003אל\"ה\u0004, לא עלה בשם \u0003אלהים\u0004. ואלו שחטאו בעגל, אמרו על סוד זה \u0003אל\"ה\u0004 אלהיך ישראל."],[1,"","ביאור הדברים, כי על ידי עלית מ\"ן מתחתונים נמשך אור חדש מע\"ב ס\"ג דא\"ק, שבהיות האור הזה מע\"ב ס\"ג דא\"ק, שלמעלה מצמצום ב' הנ\"ל, הבוקע כל מדרגה לשתים, ע\"כ בעת שנמשך האור הזה לראש א\"א, הוא חוזר ומוריד את הנקודה מתוך המחשבה שהיא מקום הבינה, חזרה למקומה, למקום המלכות של הראש, כמו שהי' לפני צמצום ב', וג' הספירות בינה, ז\"א ומלכות שנפלו מהראש, נמצאות חוזרות לבחינת ראש, שהרי הזווג נעשה במקום המלכות שלמטה מהן. ונבחן שהשם אלהים חזר ונתגלה, כי ג' האותיות \u0003אל\"ה\u0004 חזרו ונתחברו אל ה\u0003מ\"י\u0004 במדרגה אחת, ונשלם שם אלהים במדרגה. וכיון שחזרו בינה וזו\"ן דכלים חזרו גם ג\"ר דאורות כנ\"ל, ונתלבשו כח\"ב זו\"ן דאורות בה' אותיות דשם אלהים: אורות כח\"ב ב\u0003אל\"ה\u0004, אורות זו\"ן ב\u0003י\"ם\u0004."],[1,"","וזכור זאת היטב ש\u0003אל\"ה\u0004 הנפולים הם בחי' כלי בינה וזו\"ן החסרים למדרגה, אבל בעת ש\u0003אל\"ה\u0004 מתחברות בשם אלהים הן נעשות אורות כח\"ב, שהוא מטעם הערך ההפוך שבין הכלים לאורות כנ\"ל. וזה אמרו \u0003ואגליף גו בוצינא קדישא סתימא\u0004, היינו שנחקק מסך ומקום זווג מחדש במלכות דראש א\"א, הנק' בוצינא קדישא סתימא. והיא \u0003גליפו דחד ציורא סתימאה קדש קדישין\u0004 אשר הגליפו החדשה הזו ממשיך חד ציורא דהיינו קומה של ע\"ס, שהוא קדש קדישין, והוא קומת ג\"ר הנק' קדש קדישין. והוא משום \u0003דנפק מגו מחשבה\u0004, משום דהאי נקודה דסלקא להיות מחשבה, הנה עתה חזרה ונפק מגו מחשבה, ובאה למקומה האמיתי למקום המלכות דראש. וע\"כ ג' הכלים בינה ז\"א ונוק' שהם \u0003אל\"ה\u0004, חזרו עתה למדרגה של הראש, ונשתלם שם אלהים. ומה שמכנה את הקומה הזו דג\"ר בשם \u0003ציורא סתימאה\u0004, יתבאר בהמשך."],[1,"","וז\"ש, \u0003ואקרי מ\"י שירותא לבנינא\u0004: כלומר, אע\"פ שכבר התחברו \u0003אל\"ה\u0004 ב\u0003מ\"י\u0004 ונעשה השם \u0003אלהים\u0004 כנ\"ל, מ\"מ עדיין נק' רק \u0003מ\"י\u0004 והוא שירותא לבנינא, הוא התחלה לבנין השם אלהים, כי הבנין עוד לא נשלם, כמו שמפרש והולך."],[1,"","וז\"ש, \u0003קיימא ולא קיימא\u0004, כלומר מצד אחד כבר קיימא בנינא בכל השלימות, שהרי מקום הזווג חזר למקומו בפה דראש, ובינה וזו\"ן חזרו למדרגה, וכן ג\"ר דאורות, והשם אלהים נשלם. אמנם מצד ב' \u0003לא קיימא\u0004 עוד בנינא דשמא, כי הוא \u0003עמיק וסתים בשמא\u0004 כלומר שהאורות של השם אלהים הם עוד עמוקים וסתומים ואינם מאירים ב\u0003אל\"ה\u0004, שהם בינה וזו\"ן שעלו למקום הראש. והוא מטעם, כי מחמת עליתם לראש א\"א, ששם מאירה החכמה בלבדה, הנה אין בקומה הזו אלא אור החכמה, וכיון שהם ז\"ת, וז\"ת שעלו אינן יכולות לקבל החכמה בלי התלבשות תוך חסדים, וחסדים אין להם שם, ע\"כ אינם יכולים לקבל גם החכמה. ולפיכך נבחן שהשם \u0003עמיק וסתים\u0004 ואינו מתפשט עוד בג' אותיות אל\"ה. ומטעם זה נבחן עוד בנין קומה זו בבחי' \u0003לא קיימא\u0004 ועדיין \u0003אל\"ה\u0004 אינם מגולים בה. וזה אמרו שלפני זה \u0003לא אקרי אלא מי\u0004 כי האותיות \u0003אל\"ה\u0004 עוד סתומות בשמא דאלהים, ואין שם רק \u0003מ\"י\u0004."],[1,"","וז\"ש, \u0003בעא לאתגלייא ולאתקרי בשמא\u0004 כיון דכבר נשלם השם, כי כבר עלו אל\"ה לראש, ועכ\"ז אינן מאירות כלל, כנ\"ל, וזה אמרו, \u0003בעא לאתגלייא ולאתקרי בשמא אלהים. אתלבש בלבוש יקר דנהיר\u0004. פירוש, כיון דכל הסיתום של השם שאינו יכול להאיר ב\u0003אל\"ה\u0004 הוא מחמת חסרון הלבוש דחסדים, שאין ז\"ת יכולות לקבל אור חכמה בלי חסדים, כנ\"ל. ע\"כ חזר ועשה הזווג דקטנות, כבעת היותו בגוף דא\"א, והמשיך קומת החסדים, והקומה דחכמה נתלבשה באור החסדים שהמשיכה, והאור ההוא נעשה אל הקומה \u0003לבוש יקר דנהיר\u0004 אשר דרך הלבוש הזה דחסדים, הוא יכול להאיר את אור החכמה בז\"ת שהן אל\"ה."],[1,"","וזהו אמרו, \u0003אתלבש בלבוש יקר דנהיר\u0004. \u0003וברא אל\"ה וסליק אל\"ה בשמא\u0004, היינו על ידי הלבוש היקר הנ\"ל שהוא קומת החסדים, שקבל מבחינת זווג הגוף, שלמטה מחזה הנק' בריאה, \u0003ברא אלה\u0004, דהיינו שהשפיע האור ההוא לאל\"ה, ועי\"כ \u0003סליק אל\"ה בשמא\u0004 כי מאחר שכבר יש להם לבוש יקר מחסדים הן יכולות לקבל בו גם חכמה, ואז נגלו \u0003אל\"ה\u0004 בשמא אלהים כי עתה מאירים בו הבינה וזו\"ן בתכלית השלמות שבהם, ונבחן, כי עתה נשתלם ונתגלה שמא דאלהים. וזה אמרו \u0003אתחברן אתוון אלין באלין\u0004 היינו \u0003מ\"י באל\"ה. ואשתלים בשמא אלהים\u0004 כי עתה מקבלות אל\"ה קומת החכמה מפאת שהשיגו לבוש דחסדים, וכל ה' אותיות אלהים מאירות בשלמותן. וזה אמרו, \u0003ועד דלא ברא אל\"ה לא סליק בשמא אלהים\u0004, כי מטרם שה\u0003מ\"י\u0004 השפיע להם אור החסדים ללבוש, לא היו \u0003אל\"ה\u0004 יכולות לקבל כלום ממ\"י ולא האיר באלהים אלא \u0003מ\"י\u0004 בלבד. כנ\"ל. וז\"ש, \u0003דחבו בעגלא\u0004 וכו' \u0003אלה אלהיך ישראל\u0004: כי הם פגמו בהאי לבוש יקר דנהיר הנ\"ל, וע\"כ ה\u0003מ\"י\u0004 נפרד מן \u0003אל\"ה\u0004 ולכן אמרו \u0003אל\"ה אלהיך\u0004, ויצא השפע לאלהים אחרים."],[2,"","טו) \u0003וכמה דאשתתף\u0004 וכו': וכמו שנתחברו \u0003מ\"י באל\"ה\u0004 והיו לשם אלקים, ע\"י לבוש יקר המאיר שהוא אור החסדים, כך השם מתחבר תמיד, ע\"י לבוש יקר המאיר. ובסוד זה מתקיים העולם, שהסו\"ה עולם חסד יבנה. ואליהו פרח, ולא ראיתי אותו. וממנו ידעתי הדבר, שעמדתי על הסוד והסתר שלו. בא ר' אלעזר, וכל החברים, והשתטחו לפניו. בכו ואמרו, אם לא היינו באים לעולם, אלא לשמוע את זה, היה די לנו."],[2,"","פירוש, באותו הדרך שנתבאר \u0003דלא סליק בשמא אלהים\u0004 עד דקומת החכמה אתלבש בלבוש יקר דנהיר ואז אשתתף \u0003מ\"י באל\"ה\u0004 וסליק בשמא אלהים \u0003הכי הוא שמא דאשתתף תדיר\u0004 כן הוא קיים לעד לנצחיות, ולא סליק בשמא בלאו הכי. \u0003וברזא דא אתקיים עלמא\u0004, גם עלמא תתאה שהיא הנוקבא הנק' \u0003מ\"ה\u0004, מקבל המוחין בדרך זה של שיתוף \u0003מ\"י\u0004 ב\u0003אלה\u0004 ואשתלים לגמרי כמו עלמא עילאה, כמו שר' שמעון הולך ומבאר. וזהו, לאפוקי מר' אלעזר שאמר על עלמא תתאה, \u0003כיון דמטי תמן מ\"ה, מ\"ה ידעת וכו' הא כלא סתים כדקדמיתא\u0004, ע\"ש. נמצא לדבריו דלא אתקיים עלמא תתאה כמו עלמא עילאה. וז\"ש \u0003וברזא דא אתקיים עלמא\u0004 כגוונא דעלמא עילאה. וע\"כ פסק ר\"ש דבריו לעיל. והנה אליהו לא פירש אלא סדר המוחין, ובנין שמא אלקים באו\"א לבד, אבל לא ביאר כלום, איך סדר בנין אלקים הוא בנוקבא, וזהו שמפרש ר\"ש בעצמו עד סוף המאמר."],[3,"","טז) \u0003א\"ר שמעון\u0004 וכו': אר\"ש, על כן השמים וצבאם נבראו ב\u0003מ\"ה\u0004 שהוא המלכות. כי כתוב, כי אראה שמיך מעשה אצבעותיך וגו'. ומקודם לכן כתוב, \u0003מ\"ה\u0004 אדיר שמך בכל הארץ אשר תנה הודך על השמים. הרי השמים נבראו בשם מ\"ה, שהוא המלכות והכתוב, \u0003על השמים\u0004, המורה על הבינה הנקראת \u0003מ\"י\u0004, שהוא מעל ז\"א. הנקרא שמים, הפירוש הוא, שעולה בשם אלקים. פירוש. \u0003מ\"ה\u0004, שהוא מלכות, עולה ונכלל בבינה הנקראת אלקים, אחר שברא אור לאורו, דהיינו אחר שברא אור חסדים ללבוש יקר אל אור החכמה שבשם \u0003מ\"י\u0004 (כנ\"ל אות י\"ד) שאז נתלבשו זה בזה, והמלכות עלתה בשם העליון אלקים. שהוא שם הבינה. שהמלכות נכללת בה. וע\"כ, בראשית ברא אלקים. היינו אלקים העליון, שהוא בינה, ולא מלכות. כי \u0003מ\"ה\u0004, שהוא מלכות, אינו כך ולא נבנה בסוד מ\"י אל\"ה, שאמרנו."],[3,"","פירוש, כיון דעלמא תתאה, \u0003מ\"ה\u0004 ממשיך המוחין בשמא אלהים בעלמא עילאה, ע\"כ היתה היכולת שיבראו שמים וחיליהון ע\"י מ\"ה, כי אין תולדות בלי מוחין עילאין הנ\"ל, שהם מוחין דחיה. וזה אמרו, \u0003ועל דא\u0004 משום שגם עלמא תתאה \u0003מ\"ה\u0004, אתקיים בשמא אלהים מעלמא עילאה, \u0003שמיא וחיליהון במ\"ה אתבריאו\u0004 היה כח ל\u0003מ\"ה\u0004 לאפיק תולדות אלו \u0003שמיא וחיליהון\u0004."],[3,"","ולכן אומר הכתוב, אשר תנה הודך על השמים, להשמיענו, שהמוחין נמשכים משם אלהים דישסו\"ת ע\"י השיתוף ד\u0003מ\"י\u0004 ב\u0003אל\"ה\u0004 שהן ממעל השמים שהם ז\"א. וז\"ש \u0003על השמים איהו לסלקא בשמא\u0004, שההוד שהוא המוחין, הוא על השמים מעל לז\"א, שהוא ישסו\"ת, שבו סליק בשמא אלהים, שהוא \u0003מ\"י ברא אל\"ה\u0004. כנ\"ל. אבל בשמים עצמו, שהם ז\"א אין שם \u0003מ\"י\u0004 רק \u0003מ\"ה\u0004. כנ\"ל."],[3,"","והנה אחר שנמשכה קומת החכמה מחמת הנקודה דחזר ונפיק מגו מחשבה, חזר ועשה זווג דו\"ק להמשכת אור חסדים, ואתלבש אור חכמה באור חסדים, ואז \u0003מ\"י\u0004 נהיר ב\u0003אל\"ה\u0004. כנ\"ל. וז\"ש \u0003בגין דברא נהורא לנהוריה\u0004 דהיינו אור חסדים אל אור החכמה \u0003ואתלבש דא בדא וסליק בשמא עילאה\u0004 ונתלבש אור החכמה באור החסדים, וע\"כ הגיעו המוחין מ\u0003מ\"י\u0004 ל\u0003אל\"ה\u0004, ואתחברו אתוון אלו באלו וסליק בשמא אלהים. כנ\"ל. והוא \u0003בשמא עילאה\u0004, דהיינו מעל השמים, מישסו\"ת שבהם \u0003מ\"י\u0004, אבל לא בשמים שהוא \u0003מ\"ה\u0004."],[3,"","וז\"ש, \u0003מ\"ה לא הוי הכי ולא אתבני\u0004, כי \u0003מ\"י\u0004 שהיא בינה, אשר מעת צמצום א' לא היה בה שום צמצום כלל, כי הצמצום לא היה שם אלא על הנקודה האמצעית לבדה, שהיא המלכות, שנצטמצמה שלא לקבל בה אור, ונתתקנה בסוד הזווג דהכאה להעלות או\"ח, אבל ט\"ס הראשונות היו נקיות מכל צמצום, והיו ראויות לקבל אור החכמה, אלא רק בצמצם הב', כדי להמתיק המלכות במדת הרחמים, סליק המלכות לאבא, ואבא אתתקן בה כעין דכר ונוקבא, וקבלה המלכות מקום בינה, והנקודה שהיא מלכות סליק למהוי מחשבה, בינה, ומאז נצטמצמה גם הבינה ונתתקנה במסך שלא לקבל אור החכמה בתוכה, כדי לקבל הזווג דהכאה ולהעלות או\"ח, כנ\"ל."],[3,"","הרי שהבינה ממקורה ראויה לקבל חכמה בלי שום צמצום, ומה שקבלה בתוכה הצמצום והמסך, לא היה אלא להמתיק המלכות. ולפיכך ע\"י העלאת מ\"ן מתחתונים, נמשך אור חדש מע\"ב ס\"ג דא\"ק, המוריד בחזרה את הנקודה ממקום בינה למקומה, למלכות, כמו שהיה בצמצום א', ונפק הנקודה ממחשבה. שע\"י זה נטהרת הבינה מכל צמצום וחוזרת ומקבלת אור חכמה כמ\"ש לעיל. ואחר שקומת החכמה מתלבשת בחסדים מאירה \u0003מ\"י\u0004 ב\u0003אל\"ה\u0004 ומתגלה שם אלהים. והנה כל הבנין הזה דשמא אלהים לא יתכן כלל ב\u0003מ\"ה\u0004, כי המ\"ה היא קצה השמים לתתא, דהיינו המלכות עצמה, שעליה היה הצמצום ממקורה גם בצמצום א' ואינה ראויה לקבל בתוכה שום הארת חכמה, וז\"ש \u0003מ\"ה לא הוי הכי ולא אתבני\u0004, כי רק במ\"י שייך כל הבנין של שם אלהים, ע\"י דחזר ונפיק מגו מחשבה, ולא במ\"ה."],[4,"","יז) \u0003אלא בשעתא דאתמשכן\u0004 וכו': אלא בשעה שאותיות אלו \u0003אל\"ה\u0004 נמשכות ממעלה, מבינה, למטה, למלכות, כי האם משאלת בגדיה לבת ומקשטת אותה בקישוטיה. אז נמשך השם אלקים מבינה שהיא האם למלכות שהיא הבת. ומתי מקשטת אותה בקישוטיה כראוי. היינו, בשעה שנראה לפניה כל זכר. שאז כתוב עליה, אל פני \u0003האדון\u0004 ה'. כי אז נקראת המלכות \u0003אדון\u0004, שהוא לשון זכר. כמו שאתה אומר, הנה ארון הברית \u0003אדון\u0004 כל הארץ. הרי הכתוב קורא את המלכות המכונה ארון הברית בשם אדון כל הארץ. שהוא שם זכר. והיינו משום שקבלה את הכלים המכונים בגדים, והמוחין המכונים קישוטין, מהאם שהיא בינה. כי אז יוצאת ה\u0003ה'\u0004 מן מ\"ה ובמקומה נכנסת \u0003י'\u0004, ונקראת המלכות \u0003מ\"י\u0004 כמו הבינה. ואז היא מתקשטת בבגדי זכר, דהיינו בגדים דבינה כנ\"ל, כנגד כל זכר בישראל."],[4,"","ביאור הדברים, כמו שנתבאר )לעיל אות י\"ג) , דאחר \u0003דעבד ברישא\u0004 דא\"א \u0003נקודה חדא ודא סליק למהוי מחשבה\u0004, כי החכמה נתקנה בה כעין דכר ונוקבא, הנה אז \u0003צייר בה כל ציורין\u0004, שכל הקומות דה\"פ אצילות נצטיירו בה, באופן שאין יותר מכתר חכמה בכל קומה, בא\"א ואו\"א וזו\"ן, \u0003וחקק בה כל גליפין\u0004, שבכחה נפרדו ג' ספירות בינה וז\"א ומלכות מכל קומה למדרגה שמתחתיה: כי בינה ז\"א ומלכות דא\"א נפלו לאו\"א, ובינה ז\"א ומלכות דאו\"א נפלו לזו\"ן, ובינה ז\"א ומלכות דזו\"ן נפלו לבי\"ע. ע\"ש."],[4,"","ונתבאר שם בהסולם, שאלו ב' הספירות שנשארו במדרגה, שהן כתר וחכמה הן נק' \u0003מ\"י\u0004. ואלו ג' ספירות שנפרדו מכל מדרגה, הן נק' ג' אותיות \u0003אל״ה\u0004"],[4,"","וזה אמרו, \u0003בשעתא דאתמשכן אתוון אלין אל\"ה מלעילא לתתא\u0004, דהיינו בעת דנקודה סלקא למהוי מחשבה, כנ\"ל, שאז נפרדו ג' האותיות \u0003אל\"ה\u0004 מאו\"א ונפלו למדרגה שמתחתיהם שהם הזו\"ן, כנ\"ל. כי אז נבחן ש\u0003אל\"ה\u0004 דאו\"א שהן בזו\"ן נמשכו מלעילא לתתא ונתלבשו תוך הזו\"ן, כי \u0003אל\"ה\u0004 דאבא שהוא יש\"ס נמשך לז\"א. ו\u0003אל\"ה\u0004 דאמא שהיא תבונה נמשכה לנוקבא."],[4,"","וז\"ש, ו\u0003אמא אוזיפת לברתא מאנהא וקשיטא לה בקישוטהא\u0004, היינו בעת ביאת המוחין דגדלות המבוארים לעיל בדברי ר\"ש, שנמשך \u0003גליפו דחד ציורא סתימאה קדש קדשין, בניינא עמיקא דנפיק מגו מחשבה\u0004. שפירושו, שהנקודה חזר ונפיק מגו מחשבה למקומה, למלכות, שבזה הוחזרו ג' הכלים בינה וזו\"ן למדרגה, ונמשכו ג' האורות דכח\"ב הנק' \u0003קדש קדשין\u0004, ע\"ש."],[4,"","ותדע, כי בעת שהוחזרו הכלים בינה וזו\"ן מהגוף אל ראש דא\"א, נמשכו עמהם גם או\"א המלבישים עליהם, ועלו גם הם לראש דא\"א, וקבלו שם אותם המוחין דקדש קדשין שבראש א\"א. והטעם הוא, כי זה הכלל, העליון היורד לתחתון נעשה כמוהו, וכן התחתון העולה לעליון נעשה כמוהו. ולפיכך במצב הקטנות, שבינה וזו\"ן נפרדו מהראש דא\"א ונפלו לגוף שלו שהם מלובשים באו\"א מפה ולמטה, נעשו הבינה וזו\"ן דא\"א לבחי' או\"א ממש. וע\"כ במצב הגדלות שחזרו הבינה וזו\"ן דא\"א למדרגת הראש שלו, הנה לוקחים עמהם גם האו\"א, כי כבר נעשו למדרגה אחת בשעת הקטנות, ונמצאים משום זה גם בגדלות, שאו\"א עלו עתה עמהם לראש דא\"א, שנעשו ג\"כ שוים כמוהו ומקבלים אותם המוחין שבראש דא\"א הנק' \u0003קדש קדשין\u0004."],[4,"","ועד\"ז ממש, עלו הזו\"ן לאו\"א, כי אחר שאו\"א קבלו המוחין שבראש א\"א, נפיק גם בהם הנקודה מגו מחשבה למקום המלכות, שבזה הוחזרו הבינה וזו\"ן שלהם אל מדרגתם דאו\"א כנ\"ל בא\"א. והנה בה בעת, שהכלים בינה וזו\"ן חזרו ועלו לאו\"א, לקחו עמהם גם את הזו\"ן המלבישים עליהם, ועולים גם הזו\"ן לאו\"א ומקבלים המוחין \u0003דקדש קדשין\u0004 אשר שם."],[4,"","וזה אמרו \u0003ואמא אוזיפת לברתא מאנהא וקשיטא לה בקישוטהא\u0004, כלומר, כיון דג' אותיות \u0003אל\"ה\u0004 דאמא נמשכו אל הנוקבא במצב הקטנות, כנ\"ל, שזה נבחן \u0003דאמא אוזיפת לברתא מאנהא\u0004, כי עי\"ז שג' הכלים בינה וזו\"ן שהם \u0003אל\"ה\u0004, נפרדו מאמא ונפלו לנוקבא, הרי הן נעשו לבחינת נוק' ממש, כי העליון היורד לתחתון נעשה כמוהו. ונבחן שאמא השאילה כלים אל\"ה שלה לברתא שהיא הנוקבא, כי עתה משמשת עמהם הנוק'. ועם זה נמצא ג\"כ דקשיט לה בקישוטהא, היינו לעת גדלות, שג' הכלים \u0003אל\"ה\u0004 בינה וזו\"ן דאמא חוזרים לאמא, הנה אז עולה עמהם גם הנוקבא לאמא, כנ\"ל. ואז מקבלת הנוקבא המוחין דקדש קדשין שבאמא, כי התחתון העולה לעליון נעשה כמוהו, כנ\"ל. ונמצא עתה, שמתוך שאמא אוזיפת מאנהא \u0003אל\"ה\u0004 לברתא בעת הקטנות, ע\"כ קשיט לה, בקישוטהא, שהם המוחין, בעת הגדלות, ונמצאת מתקשטת בקישוטין דאמא."],[4,"ואימתי קשיטא לה בקישוטהא כדקא חזי",", כי יש ב' מיני קישוטין מאמא אל הנוקבא, שהם המוחין דג\"ר: או מאמא תתאה הנקראת תבונה העומדת מחזה ולמטה דא\"א, או מאמא עילאה העומדת מחזה ולמעלה דא\"א. וכשהנוקבא עולה לתבונה והתבונה מקשטת לה בקישוטהא דילה, נבחן שעדיין הקישוטין האלו אינם כדקא חזי, משום, שאז עוד נמצאת הנוקבא בבחינת קיימא לשאלה, כמו התבונה שמטרם עלית מ\"ן כנ\"ל (אות ח' ד\"ה והנך), וע\"כ אינן כדקא חזי. אלא בעת שהנוקבא עולה למקום אמא עילאה שמחזה ולמעלה דא\"א, ואמא עילאה מקשטת לנוקבא בקישוטין דילה, אז נבחן שהקישוטין הם כדקא חזי, כמו שמפרש והולך."],[4,"בשעתא דאתחזון קמה כל דכורא","וכו' \u0003ודא אקרי אדון\u0004: בעת שהנוקבא עולה לתבונה ומקבלת המוחין ממנה. הנה אז עוד הקישוטין אינם כדקא חזי, כי היא עוד קיימא לשאלה, שפירושו, שצריכה עוד להעלאת מ\"ן מן התחתונים כדי להשתלם לגמרי, כנ\"ל. ואז נבחן, שהזכרים שבישראל מקבלים מן ז\"א שעלה לישראל סבא, אבל בעת שנוקבא עולה לאמא עילאה, הרי היא נשלמת לגמרי ואינה קיימת עוד לשאלה, דהיינו לקבל מ\"ן, ואז היא נחשבת לדכורא, והזכרים שבישראל מקבלים ממנה."],[4,"","וז\"ש \u0003בשעתא דאתחזון קמה כל דכורא\u0004, דהיינו שכל הזכרים בישראל מתראים לפניה ומקבלים ממנה. \u0003ודא אקרי אדון\u0004 כלומר, שאז אינה נקראת בשם אדנ\"י שהיא בחי' נקבה, אלא בשם אדון שהוא זכר. והוא מפני שאינה קיימא לשאלה עוד, כי אין ענין עלית מ\"ן נוהג עוד בה, וע\"כ נחשבת לזכר. וז\"ש, \u0003הנה ארון הברית אדון כל הארץ\u0004: ארון נק' הנוקבא, כי היסוד דז\"א הנק' ברית עייל בה. הרי שהכתוב מכנה את הנוקבא בשם \u0003אדון כל הארץ\u0004, שהוא שם זכר. וז\"ש, \u0003כדין נפקת ה' ואעילת י'\u0004: היינו \u0003ה' דמ\"ה\u0004 נפקת ממנה, כי \u0003ה'\u0004 זו ד\u0003מ\"ה\u0004 מורה שהיא קיימא לשאלה, כנ\"ל, שפירושה \u0003מ\"ה ידעת\u0004 וכו' \u0003הא כלא סתים כדקדמיתא\u0004, ע\"ש. הרי ש\u0003ה' דמ\"ה\u0004 מורה על קיימא לשאלה. ואומר ד\u0003ה'\u0004 זו ד\u0003מ\"ה\u0004 נפקת ממנה ואעילת \u0003י'\u0004 במקום \u0003ה'\u0004 ונק' \u0003מ\"י\u0004 כמו אמא. ואז אתבניאת בשמא אלהים כמו אמא."],[5,"","יח) \u0003ואתוון אחרנין\u0004 וכו': והאותיות האחרות, דהיינו \u0003אל\"ה\u0004, ממשיכות להם ישראל מלמעלה, מן הבינה. אל מקום זה, דהיינו אל המלכות הנקראת עתה בשם מ\"י כמו הבינה. \u0003אל\"ה אזכרה\u0004. פירושו, הנני מזכיר אותיות \u0003אל\"ה\u0004 בפי, ואני שופך דמעות ברצון נפשי, כדי להמשיך אותיות אלו אל\"ה, מן הבינה. ואז \u0003אדדם\u0004 מלמעלה מבינה, \u0003עד בית אלקים\u0004, שהוא המלכות. כדי שהמלכות תהיה נקראת אלקים כעין הבינה שנקראת אלקים. ובמה אמשיך אותן. היינו, \u0003בקול רנה ותודה המון חוגג\u0004."],[5,"","פירוש, אחר דנפקת \u0003ה'\u0004 מ\u0003מ\"ה\u0004 ואעילת \u0003י'\u0004 אל ה\u0003מ'\u0004 ונק' \u0003מ\"י\u0004 אז ממשיכים לה ישראל ע\"י עלית מ\"ן אותיות אחרות \u0003אל\"ה\u0004, לגבי אתר דא, דהיינו \u0003מ\"י\u0004, והנוקבא סלקא בשמא אלהים. וענין המשכה זו כבר נתבאר לעיל. ד\u0003אל\"ה\u0004 דעליון נופלות לתחתון בעת קטנות, וע\"כ הן נמשכות לתחתון בעת הגדלות, כי בעת שהבינה ותו\"מ דעליון, שהם אתוון אל\"ה, חוזרים לראש דעליון, הם לוקחים עמהם גם התחתון, והתחתון קונה את אתוון אל\"ה ואת המוחין שבהם, מחמת היותו עמהם יחד בראש דעליון. כי התחתון העולה לעליון נעשה כמוהו(. כנ\"ל אות י\"ז ד\"ה וז\"ש ואמא.("],[5,"","וז\"ש, \u0003ואתוון אחרנין\u0004 וכו' \u0003אל\"ה אזכרה\u0004 וכו' \u0003בגין לאמשכא אתוון\u0004, ה\"ס העלאת מ\"ן דישראל מעלין מ\"ן כדי להמשיך המוחין דגדלות ע\"י המשכת אותיות \u0003אל\"ה\u0004 דאמא עילאה אל הנוקבא. וז\"ש \u0003אל\"ה אזכרה\u0004, היינו להמשיך אותם, לכן \u0003אדכרנא בפומאי ושפיכנא דמעאי ברעות נפשי\u0004, היינו התפלה בשערי דמעות שאינן חוזרות ריקם, וכדין היינו אחר שהעלה המ\"ן \u0003אדדם מעילא\u0004 אמשיך לאותיות \u0003אל\"ה\u0004 מעילא, מאו\"א, עד בית אלהים היינו עד הנוקבא שנק' \u0003בית אלהי\"ם\u0004, ואחר המשכת האותיות \u0003אל\"ה\u0004 היא נקראת בעצמה אלהים. וז\"ש \u0003למהוי אלקים כגוונא דיליה\u0004, דהיינו כמו אמא."],[5,"","וז\"ש, \u0003מלה בסלע משתוקא בתרין\u0004, כי מאמר דר' אלעזר העלה את הנוקבא עד התבונה שהיא למטה מחזה דא\"א, שאז עוד נק' קיימא לשאלה, כנ\"ל, ונק' \u0003סלע\u0004. וז\"ש \u0003מלה בסלע\u0004. אבל במה דשתיק ר\"א ונתן מקום לר\"ש שיגלה המוחין דחיה, שהיא ע\"י עלית הנוקבא לאמא עילאה, הרי נבנו תרין עלמין כהדא. כי עלמא תתאה שהיא הנוקבא נעשית אחד עם עלמא עילאה, וז\"ש \u0003משתוקא בתרין, דאברו ואבנו תרין עלמין כחדא\u0004. כי הנוקבא עלתה לאמא ונעשית דכר כמו אמא עלאה."],[6,"","יט) \u0003אמר רבי שמעון\u0004 וו': אר\"ש, מכאן ולהלאה, שלמות המקרא, שכתוב, המוציא במספר צבאם. כי שתי מדרגות הן, שכל אחת מהן צריכה להיות רשומה. דהיינו מצוינת, אחת היא שנאמר עליה \u0003מ\"ה\u0004, ואחת שהיא \u0003מ\"י\u0004. זה מ\"י, היא עליונה, וזו, מ\"ה, היא תחתונה, המדרגה העליונה רושמת ואומרת המוציא במספר צבאם, אשר \u0003ה'\u0004 הידיעה של \u0003ה\u0004מוציא רומזת על אותה שנודעת ואין כמוה. דהיינו מ\"י. כעין זה, המוציא לחם מן הארץ,הנה ה' הידיעה של המוציא רומזת על אותה שנודעת, שזו מדרגה התחתונה, דהיינו מ\"ה. והכל אחד. ששתיהן הן במדרגה אחת שהיא מלכות, אלא העליונה היא מ\"י דמלכות והתחתונה היא מ\"ה דמלכות. המוציא במספר. פירושו, כי מספר ששים רבוא הם הכוכבים העומדים יחד, והם מוציאים צבאות למיניהם שאין להם מספר."],[6,"","ביאור הדברים, כי אחר שהכתוב רמז לנו, בשאו מרום עיניכם וראו \u0003מ\"י\u0004 ברא \u0003אל\"ה\u0004, להתבונן על בנין הנוקבא בשמא אלהים, שהיא ממשכת מאו\"א עילאין, שעל ידי כן אמא עילאה מקשטת לה בקישוטין דילה, כנ\"ל, הנה הוא ממלא ומשלים את הביאור הזה בהמשך של הכתוב המוציא במספר צבאם לכלם בשם יקרא מרוב אונים ואמיץ כח איש לא נעדר. כמו שר\"ש מבאר והולך."],[6,"","וז\"ש, \u0003תרין דרגין אינון דאיצטריך למהוי רשים כל חד מינייהו\u0004, רשים פי' מצוין, בה' הידיעה. שב' מדרגות צריכות להיות מצוינות בנוקבא שהן מדרגת \u0003מ\"י\u0004 ומדרגת \u0003מ\"ה\u0004, אשר המוחין דג\"ר שמקבלת ע\"י עליתה והלבשתה לעלמא עילאה, שאז נעשית הנוקבא כמו עלמא עילאה עצמה, זו היא הנקראת \u0003מ\"י\u0004, כי אפקת \u0003ה' דמ\"ה\u0004 ואעלית \u0003י'\u0004 במקומה, ונקראת גם הנוקבא \u0003מ\"י\u0004 כעלמא עלאה, דאתקשטת במאני דכורא, כנ\"ל. אמנם יחד עם זה, אין מדרגתה הקודמת שהיא \u0003מ\"ה\u0004 נחסרת ממנה, אלא גם ה\u0003מ\"ה\u0004 צריך להמצא בה כמקודם לכן. והטעם הוא כמו שמבאר לפנינו, אשר דרגא ד\u0003מ\"י\u0004 אצטריך כדי להמשיך השלימות ובחי' קדש קדשין אל התולדות. אבל הולדת הבנים והפריה והרביה רק בשם \u0003מ\"ה\u0004 תלויים. ולפיכך אם תחסר חד דרגא מהן לנוקבא, אינה ראויה להוליד."],[6,"","וז\"ש, \u0003עלאה רשים ואמר המוציא במספר צבאם\u0004 כלומר, דרגא ד\u0003מ\"י\u0004 שהנוקבא יורשת מעלמא עילאה, עליה אומר הכתוב, המוציא במספר צבאם. כי ה' הידיעה של המוציא רומזת על המוחין השלמים שמקבלת מאו\"א עלאין, שהם בהי' הקשוטין במאני דכורא הנ\"ל, דאפיק ה' ועייל \u0003י'\u0004. וז\"ש \u0003המוציא, ההוא דאשתמודע ולית כוותיה\u0004 כי אלו הם תכלית גבהם של המוחין הנוהגים בנוקבא במשך שתא אלפי שני. וז\"ש, \u0003המוציא לחם\u0004 וכו' \u0003דא דרגא תתאה וכלא חד\u0004: כלומר, גם ה' הידיעה של המוציא לחם רומזת על מוחין דג\"ר, דהיינו \u0003ההוא דאשתמודע\u0004, אלא הם מוחין דישסו\"ת שהנוקבא מקבלת ואשתמודעית בהם והוא דרגא דמ\"ה, כמו שביאר ר\"א למעלה. כי גם דרגא זו צריכה להיות רשים בנוקבא, וז\"ש \u0003וכלא חד\u0004 כלומר שהן שתיהן, מ\"י ומ\"ה, כלולות יחד בנוקבא לבחינת פרצוף אחד: זו עלאה, וזו תתאה."],[6,"","ואין להקשות ממ\"ש הזוהר פרשת תרומה (אות תשע\"א), שהמוציא במספר צבאם, וכן בכל מקום שכתוב ה' הידיעה, היא מעלמא תתאה דאתגליא יתיר, וכאן אומר שהיא מעלמא עילאה. והענין הוא כמ\"ש לעיל, שגם כאן היא הכוונה על עלמא דאתגליא, שהיא הנוקבא דז\"א, ומה שקורא לה עילאה, הפירוש הוא, על מדרגת מ\"י של הנוקבא, שאינה מקבלתה זולת בעת שעולה ומלבשת את עלמא עילאה שהיא אמא עילאה, ועל שם זה קורא לה עילאה, ולמדרגת \u0003מ\"ה\u0004 של עלמא דאתגליא קורא תתאה. כמ\"ש לעיל. ומ\"ש שם בתרומה, כל מילין דאינון מרזא דעלמא עלאה, סתירא אסתתרא ה' מתמן: הכוונה היא, בעת שעלמא דאתגליא אינה עולה ומלבשת לעלמא עילאה, שאז עלמא עילאה בסתירא, ואיננה מאירה לתחתונים, וע\"כ אינו כתוב בה' הידיעה, כי נסתר הוא. עש\"ה."],[6,"","וז\"ש, \u0003במספר שתין רבוא אינון, דקיימין כחדא, ואפיקו חילין לזינייהו דלית לון חושבנא\u0004: מספר, פירושו תכלית השלימות. בסו\"ה השמים מספרים כבוד אל וכו' (תהלים יט), כמ\"ש בזוהר ((תרומה אות קפ\"ה) מאי מספרים וכו' אלא דנהרין ונצצין בנציצו דנהורא עילאה, וסליקין בשמא דכליל בנהירו דשלימו עילאה וכו', ובגין כך סלקין בשמא שלים, ונהירין בנהירו שלים, ונצצי בנציצו שלים. וכו' עש\"ה. הרי שמספר, מורה על הארת השלימות הגמורה. ומכאן תבין שההארה הבלתי שלמה נבחנת, לבלי מספר או דלית ליה חושבנא להורות שהם מחוסרי השלימות הנק' \u0003מספר\u0004."],[6,"","ותדע דאלו המוחין דאו\"א עילאין הנ\"ל שהז\"א משפיע אותם לנוקבא, הוא סו\"ה השמים מספרים כבוד אל וכו' כי השמים ה\"ס ז\"א, כבוד אל, הוא נוקביה דז\"א, מספרים, הם שפע המוחין דאו\"א עילאין. ומוחין אלו נבחנים לסוד ששים רבוא, כי מדרגות דנוקבא נבחנות ליחידות, דז\"א לעשרות, דישסו\"ת למאות, דאו\"א עילאין, לאלפים, ודא\"א לרבבות. ויש לאו\"א עילאין ב' הבחנות, או מבחינתם עצמם, שאז נבחנים לאלפים. או מבחינת מוחין דחכמה, שמקבלים מן הראש דא\"א, שאז נבחנים גם הם לרבבות כמוהו, אלא רק לו\"ק דא\"א, להיותם מלבישים מפה ולמטה דא\"א, וע\"כ הם ביחס הזה רק בחי' ו\"ק דא\"א, שהיא רבבות, וו\"ק הם ששים, וע\"כ ה\"ס ששים רבוא. ולפיכך בעת שהנוקבא עולה ומלבשת לאו\"א עילאין, היא מקבלת מספר שלם שהם ששים רבוא: ששים, פירושם ו\"ק, כי עדיין חסרה גם אז לבחינת הראש דא\"א, ורבוא מורה על מדרגות דא\"א, המאירות תוך או\"א, דהיינו תוך הו\"ק שלו, המתלבשים באו\"א, וע\"כ יש לה לנוקבא מספר ששים רבוא."],[6,"","וזה אמרו, \u0003במספר שתין רבוא אינון דקיימא כחדא, ואפיקו חילין לזינייהו דלית לון חושבנא\u0004 כי נתבאר דב' דרגין \u0003מ\"י\u0004 ו\u0003מ\"ה\u0004 רשימין בנוקבא, אשר \u0003מ\"י\u0004 ה\"ס או\"א עילאין המתלבשים בנוקבא, ונעשית בזה לבחינת עלמא עילאה. ואז יש לה מבחינה זו סוד מספר דשתין רבוא. ובחינת \u0003מ\"ה\u0004 שבנוקבא, ה\"ס ישסו\"ת המתלבשים בנוקבא בבחינת קיימא לשאלה מ\"ה, כנ\"ל, ומבחינה זו ה\"ס עלמא תתאה, ואלו ב' דרגין \u0003מ\"י\u0004 ו\u0003מ\"ה\u0004 האמורים, נעשות בה בבחינת פרצוף אחד, אשר מחזה ולמעלה שלה היא מלבשת לאו\"א עילאין, ומחזה ולמטה שבה היא מלבשת לישסו\"ת. והם פרצוף אחד בה, כמ\"ש לעיל דכלא חד, ולפיכך, נבחנות גם בתולדות של הנוק' אלו ב' דרגין, כי מצד עלמא עילאה \u0003מ\"י\u0004 שבה, ה\"ס המוציא במספר צבאם דהיינו \u0003במספר שתין רבוא\u0004 ומצד עלמא תתאה מ\"ה שבה נבחנות התולדות שהן מבחינת בלי מספר. וז\"ש \u0003ואפיקו חילין לזינייהו דלית לון חושבנא\u0004 דהיינו שמוציאה התולדות למיניהן לבלי מספר, כלומר, שאין בהן אותן המוחין דמספר מאו\"א עילאין, אלא מישסו\"ת שהם בלי מספר."],[6,"","ושמא תאמר, א\"כ נמצאות התולדות שלה מחוסרי השלימות להיותן בחסרון המספר. לזה אומר במספר \u0003שתין רבוא אינון דקיימין כחדא ואפיקו חילין\u0004 וכו', כלומר, דאלו ב' דרגין שבה, שהן: מספר ובלי מספר, הן קיימין בה כחדא, שמחוברות בה בבחי' מדרגה אחת ממש, וע\"כ נמצאות גם בתולדות שלה אינון ב' דרגין כחדא: שמצד אחד נבחנות התולדות שלה שהן במספר שתין רבוא, ומצד הב' הן בלי מספר. וכיון שכן, נבחנת בהן הבלי מספר, לתוספות שלמות בלבד, ולא כלום למשהו חסרון."],[6,"","וטעם הדבר, כי הברכה והפריה ורביה דזרע תלויות לגמרי בבחינת עלמא תתאה מ\"ה, הנבחנת לבלי מספר. שז\"ס ברכת הזרע המובא בכתוב הבט נא השמימה וספור הככבים אם תוכל לספור אותם, ויאמר לו כה יהיה זרעך (בראשית ט\"ו), הרי שברכת הזרע באה רק בבלי מספר, דהיינו משם \u0003מ\"ה\u0004. ולפיכך אחר כל השלימות של המוחין דמספר שהשיגה מאו\"א עילאין \u0003מ\"י\u0004, יש לה תוספת לברכה מן \u0003מ\"ה\u0004 בסוד בלי מספר, \u0003דלית לון חושבנא\u0004, ויש לה גם ברכה, ושתיהן נכללות בנשמות ובתולדות."],[7,"","כ) \u0003לכלם בין אינון\u0004 וכו': לכלם בין לששים רבוא אלו, ובין לכל צבאותיהם, שאין להם מספר, \u0003בשם יקרא\u0004. מהו, בשם יקרא. אם תאמר, שקורא אותם בשמותיהם, אינו כן, כי אם היה כן, היה צריך לומר בשמו יקרא. אלא בזמן שמדרגה זו אינה עולה בשם אלקים, אלא נקראת \u0003מ\"י\u0004 (כנ\"ל אות י\"ד) אינה מולידה, ואינה מוציאה את הגנוזים בה, למיניהם, אע\"פ שכולם היו נסתרים בה, דהיינו אע\"פ שכבר עלו אותיות אל\"ה, אלא שעוד הן חסרות לבוש היקר של חסדים, שאז הן נסתרות, ואינן עולות בשם אלקים (כנ\"ל אות י\"ד בהסולם) כיון שברא אותיות \u0003אל\"ה\u0004, ועלו בשמו, דהיינו שנתלבשו בלבוש היקר דחסדים, שאז מתחברים אל\"ה עם מ\"י, ונקרא \u0003אלהים\u0004, כנ\"ל. אז בכח השם הזה הוציא אותם בשלמות, וזהו \u0003בשם יקרא\u0004, שפירושו, באותו שם שלו קרא והוציא כל מין ומין שיתקיים בשלמותו. ואז כתוב, המוציא במספר צבאם לכולם \u0003בשם\u0004 יקרא. דהיינו בשם השלם אלקים. כעין זה, כתוב, ראה קראתי \u0003בשם\u0004, שפירושו, אני מזכיר את שמי, כדי שבצלאל יתקיים במלוא קיומו."],[7,"","ביאור הדברים, הוא כנ\"ל בדבור הסמוך, שהשלימות הגדולה של המוחין, שה\"ס שמא דאלהים, שורה על הנשמות והתולדות שלה בב' דרגותיה כחדא, דהיינו הן על דרגת שתין רבוא שבה. והן על דרגת כל חילין דלית לון חושבנא, על שתיהן שורה השם. שעל זה רומז הכתוב, \u0003לכלם בשם יקרא\u0004. וז\"ש, \u0003מ\"י לא אוליד\u0004 וכו' \u0003כיון דברא אלה\u0004 וכו' \u0003בחילא דשמא דא אפיק לון בשלימו\u0004 כי נתבאר לעיל בסמוך, שברכת הזרע תלויה לגמרי בשם \u0003מ\"ה\u0004 שהיא בחינת דלית להון חושבנא. והפירוש הוא, כי המוחין דמספר הם הארת החכמה. שהיא סוד השם השלם, וכל בחינותיה הן בתכלית השלימות. והמוחין דבלי מספר הבאים דוקא משם מ\"ה, הם המוחין דחסדים לבד. ונתבאר לעיל במאמר אליהו לר\"ש, שהארת החכמה אינה מקובלת בלי לבוש יקר דחסדים, שמטרם זה, אע\"פ שאותיות \u0003אל\"ה\u0004 עלו ל\u0003מ\"י\u0004, מ\"מ לא סליק בשמא \u0003אלהי\"ם\u0004, שז\"ס \u0003מ\"י\u0004 ברא \u0003אל\"ה\u0004, שפירושו, דברא נהורא דחסדים לנהוריה דחכמה, \u0003ואתלבש דא בדא, וסליק בשמא עילאה\u0004."],[7,"","וזה אמרו כאן: \u0003מ\"י לא אוליד ולא אפיק טמירין לזיניה אע\"ג דכלהו הוו טמירין ביה\u0004, דהיינו כנ\"ל, דאע\"ג דכבר \u0003נפיק\u0004 הנקודה \u0003מגו מחשבה\u0004 למקומה למלכות, והיתה לגליפו דחד ציורא קדש קדשין, כי חזרו בה בינה וזו\"ן דכלים וגה\"ר דאורות, ועכ\"ז כלא טמירא ביה, ועוד נשארים \u0003אל\"ה עמיק וסתים בשמא\u0004, מטעם שהם אינם יכולים לקבל הארת חכמה בלי חסדים."],[7,"","אלא \u0003כיון דברא אל\"ה\u0004, היינו אחר שהוסיף ונזדווג על מסך ד\u0003מ\"ה\u0004 שהוא בחי' עלמא תתאה, והוציא עליו קומת מוחין של חסדים הנק' \u0003בלי מספר\u0004, והשפיע אותה ל\u0003אל\"ה\u0004, שה\"ס \u0003ברא אל\"ה\u0004, דהיינו שנתן בהם הלבוש של חסדים הנק' \u0003ברא\u0004 הנה אז \u0003ואסתליק בשמיה ואקרי אלהים\u0004, כי עתה אחר שהשיגו קומת חסדים יכולים לקבל הארת חכמה שהם המוחין דמספר שתין רבוא, ואז אתחברון אתוון אלין באלין ואסתלק בשמיה ואקרי אלקים. \u0003כדין בחילא דשמא דא אפיק לון בשלימו\u0004, לכן גם על הנשמות והתולדות שיצאו משם אלהים, נמצאת בהן אותה השלימות של השם, שהיא התלבשות החכמה בחסדים. \u0003ודא הוא בשם יקרא\u0004 שהשם נקרא על התולדות \u0003בההוא שם דיליה קרא ואפיק כל זינא וזינא לאתקיימא בשלימותיה\u0004, שבשם הזה הוציא התולדות הן במין \u0003דששים רבוא\u0004 והן במין \u0003דלית לון חושבנא\u0004, כדי שיתקיימו שבשלימותה של השם, דהיינו שיתלבשו זה בזה כמו שהם מלובשים בהשם. ומ\"ש ראה קראתי בשם וכו': מביא ראיה מהכתוב, שהמלים קריאה בשם, מורות על קיום ושלימות."]],[[0,"","אָמַר לִי, רַבִּי, דָּבָר נִסְתָּר הָיָה לִפְנֵי הַקָּדוֹשׁ-בָּרוּךְ-הוּא וְגִלָּה בַּיְשִׁיבָה הָעֶלְיוֹנָה, וְזֶה הוּא. בְּשָׁעָה שֶׁנִּסְתַּר כָּל הַנִּסְתָּרִים רָצָה לְהִתְגַּלּוֹת, עָשָׂה בָּרֹאשׁ נְקֻדָּ\"ה אַחַת, וְזוֹ עָלְתָה לִהְיוֹת מַחֲשָׁבָה. צִיֵּר בָּהּ אֶת כָּל הַצִּיּוּרִים, חָקַק בָּהּ כָּל הַחִקּוּקִים."],[1,"","וְחָקַק בְּתוֹךְ הַמָּאוֹר הַקָּדוֹשׁ הַנִּסְתָּר חֲקִיקָה שֶׁל צִיּוּר אֶחָד נִסְתָּר, קֹדֶשׁ קָדָשִׁים, בִּנְיָן עָמֹק שֶׁיָּצָא מִתּוֹךְ הַמַּחֲשָׁבָה וְנִקְרֵאת מִ\"י תְּחִלָּה (נ\"א: ראשית) לַבִּנְיָן. עוֹמֵד וְלֹא עוֹמֵד. עָמֹק וְנִסְתָּר בַּשֵּׁם. לֹא נִקְרָא אֶלָּא מִ\"י. רָצָה לְהִתְגַּלּוֹת וּלְהִקָּרֵא בַּשֵּׁם (הזה), וְהִתְלַבֵּשׁ בִּלְבוּשׁ יְקָר שֶׁמֵּאִיר וּבָרָא אֵלֶּה, וְעָלָה אֵלֶּה בַּשֵּׁם. הִתְחַבְּרוּ הָאוֹתִיּוֹת אֵלּוּ בְּאֵלּוּ, וְנִשְׁלְמוּ בַּשֵּׁם אֱלֹהִים (מ\"י-אלה). וְטֶרֶם שֶׁבָּרָא אֵלֶּה, לֹא עָלָה בַּשֵּׁם אֱלֹהִים, וְהֵם שֶׁחָטְאוּ בָּעֵגֶל (נ\"א בעולם), וְעַל סוֹד זֶה אָמְרוּ (שמות לב) אֵלֶּה אֱלֹהֶיךְ יִשְׂרָאֵל."],[2,"","וּכְמוֹ שֶׁמִּשְׁתַּתֵּף מִ\"י בְּאֵלֶּה, כָּךְ הוּא הַשֵּׁם שֶׁמִּשְׁתַּתֵּף תָּמִיד, וּבַסּוֹד הַזֶּה הִתְקַיֵּם הָעוֹלָם. וּפָרַח אֵלִיָּהוּ וְלֹא רָאִיתִי אוֹתוֹ, וּמִמֶּנּוּ יָדַעְתִּי הַדָּבָר (הזה) (שהעמדתי) עַל הַסּוֹד וְהַסֵּתֶר שֶׁלָּהּ. בָּא רַבִּי אֶלְעָזָר וְכָל הַחֲבֵרִים וְהִשְׁתַּטְּחוּ לְפָנָיו. בָּכוּ וְאָמְרוּ, אִלְמָלֵא לֹא בָאנוּ לָעוֹלָם אֶלָּא לִשְׁמֹעַ אֶת זֶה - דַּי."],[3,"","אָמַר רַבִּי שִׁמְעוֹן, עַל זֶה הַשָּׁמַיִם וּצְבָאָם נִבְרְאוּ בְּמָ\"ה, שֶׁכָּתוּב (תהלים ח) כִּי אֶרְאֶה שָׁמֶיךְ מַעֲשֵׂה אֶצְבְּעֹתֶיךְ וְגוֹ'. וְכָתוּב (שם) מָ\"ה אַדִּיר שִׁמְךְ בְּכָל הָאָרֶץ אֲשֶׁר תְּנָה\" הוֹדְךְ\" עַל\" הַשָּׁמָיִם\". עַל הַשָּׁמַיִם הוּא לַעֲלוֹת בַּשֵּׁם, מִשּׁוּם שֶׁבָּרָא אוֹר לְאוֹרוֹ וְהִתְלַבֵּשׁ זֶה בָּזֶה וְעָלָה בְּשֵׁם עֶלְיוֹן. וְעַל כֵּן בְּרֵאשִׁית בָּרָא אֱלֹהִים - זֶה אֱלֹהִים הָעֶלְיוֹן, שֶׁהֲרֵי מָ\"ה לֹא הָיָה כָּךְ וְלֹא נִבְנָה."],[4,"","אֶלָּא, בְּשָׁעָה שֶׁנִּמְשְׁכוּ הָאוֹתִיּוֹת הַלָּלוּ (מאלו) אֵלֶּ\"ה מִלְמַעְלָה לְמַטָּה. וְהָאֵם הִלְוְתָה לַבַּת בְּגָדֶיהָ וְקִשְּׁטָה אוֹתָהּ בְּתַכְשִׁיטֶיהָ. וּמָתַי קִשְּׁטָה אוֹתָהּ בְּתַכְשִׁיטֶיהָ כָּרָאוּי בְּשָׁעָה שֶׁנִּרְאוּ לְפָנֶיהָ כָּל זָכָר, שֶׁכָּתוּב (שמות כג) אֶל פְּנֵי הָאָדוֹן ה'. וְזֶה נִקְרָא אָדוֹן, כְּמוֹ שֶׁנֶּאֱמַר (יהושע ג) הִנֵּה אֲרוֹן הַבְּרִית אֲדוֹן כָּל הָאָרֶץ. וְאָז יָצְאָה ה' וְנִכְנְסָה י', וְהִתְקַשְּׁטָה בְּכֵלִים שֶׁל זָכָר כְּנֶגְדָּם שֶׁל כָּל זָכָר בְּיִשְׂרָאֵל."],[5,"","וְאוֹתִיּוֹת אֲחֵרוֹת מוֹשְׁכִים אוֹתָם יִשְׂרָאֵל מִלְמַעְלָה לַמָּקוֹם הַזֶּה. (תהלים מב) אֵלֶּה אֶזְכְּרָה. אַזְכִּיר בְּפִי וְאֶשְׁפֹּךְ דִּמְעוֹתַי (ברצון נפשי כדי להמשיך האותיות הללו), וְאָז אֶדַּדֵּם מִלְמַעְלָה עַד בֵּית אֱלֹהִים, שֶׁיִּהְיֶה אֱלֹהִים כְּמוֹ שֶׁהוּא. וּבַמֶּה (שם) בְּקוֹל רִנָּה וְתוֹדָה הָמוֹן חוֹגֵג. אָמַר רַבִּי אֶלְעָזָר, הַשְּׁתִיקָה שֶׁלִּי בָּנְתָה מִקְדָּשׁ לְמַעְלָה וּבָנְתָה מִקְדָּשׁ לְמַטָּה, וּבְוַדַּאי דִּבּוּר בְּסֶלַע וּשְׁתִיקָה בִּשְׁתַּיִם. מִלָּה בְּסֶלַע - מַה שֶּׁאָמַרְתִּי וְהִתְעוֹרַרְתִּי בוֹ, שְׁתִיקָה בִּשְׁתַּיִם - מַה שֶּׁשָּׁתַקְתִּי שֶׁנִּבְרְאוּ וְנִבְנוּ שְׁנֵי עוֹלָמוֹת יַחַד."],[6,"","אָמַר רַבִּי שִׁמְעוֹן, מִכָּאן וָהָלְאָה שְׁלֵמוּת הַכָּתוּב, שֶׁכָּתוּב (ישעיה מ) הַמּוֹצִיא בְמִסְפָּר צְבָאָם. שְׁתֵּי דְרָגוֹת הֵן שֶׁצָּרִיךְ לִהְיוֹת רְשׁוּמָה כָּל אַחַת מֵהֶן. אַחַת זֶה שֶׁנֶּאֱמַר מָ\"ה, וְאַחַת מִ\"י. זוֹ עֶלְיוֹנָה וְזוֹ תַּחְתּוֹנָה. זוֹ הָעֶלְיוֹנָה רְשׁוּמָה, וְאוֹמֵר הַמּוֹצִיא בְמִסְפָּר צְבָאָם. הַמּוֹצִיא - אוֹתוֹ הַנּוֹדָע וְאֵין כְּמוֹתוֹ. כְּמוֹ זֶה הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ. הַמּוֹצִיא - הַהוּא שֶׁנּוֹדָע. זוֹ הַדַּרְגָּה הַתַּחְתּוֹנָה, וְהַכֹּל אֶחָד. בְּמִסְפָּר - שִׁשִּׁים רִבּוֹא הֵם שֶׁעוֹמְדִים יַחַד, וְהוֹצִיאוּ צְבָאוֹת לְמִינֵיהֶם שֶׁאֵין לָהֶם חֶשְׁבּוֹן."],[7,"","(נ\"א: כמו זה). לְכֻלָּם - בֵּין אוֹתָם הַשִּׁשִּׁים, בֵּין כָּל צִבְאוֹתָם - בְּשֵׁם יִקְרָא. מַה זֶּה בְּשֵׁם יִקְרָא אִם תֹּאמַר שֶׁקָּרָא לָהֶם בִּשְׁמוֹתֵיהֶם - זֶה אֵינוֹ כָּךְ, שֶׁאִם כָּךְ, הָיָה צָרִיךְ לִהְיוֹת בִּשְׁמוֹ. אֶלָּא בִּזְמַן שֶׁהַדַּרְגָּה הַזּוֹ לֹא עוֹלָה בַּשֵּׁם (למעלה) וְנִקְרֵאת מִ\"י, לֹא מוֹלִידָה וְלֹא מוֹצִיאָה נִסְתָּרִים לְמִינָהּ, אַף עַל גַּב שֶׁכֻּלָּם הָיוּ טְמוּנִים בָּהּ. כֵּיוָן שֶׁבָּרָא אֵלֶּה וְהִתְעַלָּה בִשְׁמוֹ וְנִקְרָא אֱלֹהִים, אָז בְּכֹחַ הַשֵּׁם הַזֶּה הוֹצִיא אוֹתָם בִּשְׁלֵמוּת. וְזֶה הוּא בְּשֵׁם יִקְרָא, בְּאוֹתוֹ הַשֵּׁם שֶׁלּוֹ קָרָא וְהוֹצִיא כָּל מִין וּמִין שֶׁיִּתְקַיְּמוּ בִשְׁלֵמוּתוֹ. כְּמוֹ זֶה (שמות לא) רְאֵה קָרָאתִי בְשֵׁם. הִזְכַּרְתִּי שְׁמִי שֶׁיִּתְקַיֵּם בְּצַלְאֵל עַל קִיּוּם שְׁלֵמוּתוֹ."]]],[["מֵרוֹב אוֹנִים, (ישעיהו מ׳:כ״ו) מַאי מֵרוֹב אוֹנִים, דָּא (פקודי רל\"א ב) רִישׁ דַּרְגִּין, דִּסְלִיקוּ בֵּיהּ כָּל רְעוּתִין וְאִסְתַּלָּקוּ בֵּיהּ בְאֹרַח סָתִים. וְאַמִּיץ כֹּחַ דָּא רָזָא דְּעָלְמָא עִלָּאָה דְּאִסְתַּלַּק בְּשֵׁם אֱלהִים כִּדְקָאַמְרָן. אִישׁ לא נְעְדָּר מֵאִנּוּן שִׁתִּין רִבּוֹא דְּאֲפִיק בְּחֵילָא דִשְׁמָא. וּבְגִין דְּאִישׁ לא נֶעְדָּר, בְּכָל אֲתַר דְּמִיתוּ יִשְׂרָאֵל וְאִתְעֲנָשׁוּ בְּחוֹבַיְיהוֹ אִתְמְנוּן וְלָא אַעֲדַר מֵאִנּוּן (קנ\"ז א', שמות כ\"ב א) שִׁתִּין רִבּוֹא אֲפִילוּ חָד. בְּגִין לְמֶהֱוֵי כֹּלָא דִיוּקְנָא חֲדָא. כְּמָה דְּאִישׁ לָא נֶעְדַּר לְעֵילָא, אוּף הָכִי לָא נֶעְדַּר לְתַתָּא.","בְּרֵאשִׁית, רַב הַמְנוּנָא סָבָא אָמַר, אַשְׁכְּחָן אַתְוָון בְּהִפּוּכָא. בֵּי\"ת בְּקַדְמִיתָא וּלְבָתַר. ב' בְּקַדְמִיתָא הַיְינוּ בְּרֵאשִׁית. בָּרָא לְבָתַר. אל\"ף בְּקַדְמִיתָא וּלְבָתַר. אל\"ף בְּקַדְמִיתָא הַיְינוּ אֱלֹהִים. אֶת לְבָתָר. אֶלָּא כַּד בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבַּד עָלְמָא, כָּל אָתְוָון הֲווּ סְתִימִין, וּתְרֵין אַלְפִין שְׁנִין עַד דְּלָא בְּרָא עָלְמָא הֲוָה מִסְתַּכֵּל קוּדְשָׁא בְּרִיךְ הוּא וְאִשְׁתַּעְשַׁע בְּהוּ.","כַּד בְּעָא לְמִבְרֵי עָלְמָא, אָתוּ (מקץ ר\"ד א', ויגש ר\"ה ב) כָּל אַתְוָון קַמֵּיהּ מִסּוֹפָא אֲרֵישַׁיְיהוּ. שָׁרִיאַת אָת \u0001ת\u0002 לְמֵיעַל בְּרִישָׁא, אָמְרָה, רִבּוֹן עָלְמִין נִיחָא קַמָּךְ לְמִבְרֵי בִּי עָלְמָא, דְּאֲנָא חוֹתְמָא דְגוּשְׁפַּנְקָא דִילָךְ אֱמֶ\"ת, וְאַתְּ אִתְקְרִיאַת אֱמֶ\"ת, יָאוֹת לְמַלְכָּא (אמת) לְמִשְׁרֵי בְּאוֹת אֱמֶ\"ת וּלְמִבְרֵי בִּי עָלְמָא. אָמַר לָהּ קוּדְשָׁא בְּרִיךְ הוּא, יָאוֹת אַנְתְּ וְזַכָּאָה אַנְתְּ, אֶלָּא לֵית אַנְתְּ כְּדַאי לְמִבְרֵי בָּךְ עָלְמָא, הוֹאִיל וְאַנְתְּ זַמִּינָא לְמֶהֱוֵי רָשִׁים עַל מִצְחִין דְּגוּבְרִין מְהֵימְנִין דְּקִיְּימוּ אוֹרַיְתָא מֵאל\"ף וְעַד תי\"ו, וּבִרְשִׁימוּ דִילָךְ יְמוּתוּן. וְעוֹד דְּאַנְתְּ חוֹתָמָא דְמָוֶת. הוֹאִיל וְאַנְתְּ כָּךְ, לֵית אַנְתְּ כְּדַאי לְמִבְרֵי בָּךְ עָלְמָא. מִיָּד נָפְקַת.","עָאלַת אָת \u0001ש\u0002 קַמֵּיהּ, אָמְרָה קַמֵּיהּ, רִבּוֹן עָלְמִין, נִיחָא קַמָּךְ לְמִבְרֵי בִּי עָלְמָא, דְּבִי אִתְקְרֵי שְׁמָךְ שַׁדַּ\"י, וְיָאוֹת לְמִבְרֵי עָלְמָא בִּשְׁמָא קַדִּישָׁא. אָמַר לָהּ, יָאוֹת אַנְתְּ, וְטַב אַנְתְּ וּקְשׁוֹט אַנְתְּ, אֲבָל הוֹאִיל וְאָתְוָון דְּזִיּוּפָא נָטְלִין לָךְ לְמֶהֱוֵי עִמְּהוֹן, לָא בָעֵינָא לְמִבְרֵי בָּךְ עָלְמָא, דִּבְגִין דְּלָא יִתְקַיַּים שִׁקְרָא, אֶלָּא אִי יִטְלוּן לָךְ \u0001ק\"ר\u0002","מִכָּאן מָאן דְּבָעֵי לְמֵימַר שִׁקְרָא (ויקהל רט\"ו ב) יִטּוֹל יְסוֹדָא דִקְשׁוֹט בְּקַדְמִיתָא וּלְבָתַר יוֹקִים לֵיהּ שִׁקְרָא, דְּהָא אָת אָת קְשׁוֹט אִיהוּ, אָת קְשׁוֹט דַּאֲבָהָתָן דְּאִתְיַיחֲדוּ בַהּ. \u0001ק\"ר\u0002 (פקודי רס\"ד א', תרומה קמ\"ח ב) אָתְוָון דְּאִתְחֲזִיאוּ עַל סִטְרָא בִישָׁא אִנּוּן וּבְגִין לְאִתְקַיָּימָא נָטְלֵי אָת \u0001ש\u0002 בְּגַוַּוייהוּ וַהֲוֵי קֶשֶׁר. כֵּיוָן דְּחָמַאת הָכִי נָפְקַת מִקַּמֵּיהּ.","עָאלַת אָת \u0001צ\u0002 אָמְרָה קַמֵּיהּ, רִבּוֹן עָלְמָא נִיחָא קַמָּךְ לְמִבְרֵי בִּי עָלְמָא דְּאֲנָא (ס\"א דבי) בִּי חֲתִימִין צַדִּיקִים, וְאַנְתְּ דְּאִתְקְרִיאַת צַדִּיק, בִּי רָשִׁים דִּכְתִיב, (תהילים י״א:ז׳) כִּי צַדִּיק יְיָ צְדָקוֹת אָהֵב, וּבִי יָאוֹת לְמִבְרֵי עָלְמָא. אָמַר לָהּ צַדִּי, צַדִּיק אַנְתְּ, וְצַדִּיק אַנְתְּ אִתְקְרִיאַת, אֲבָל אַנְתְּ צָרִיךְ לְמֶהוֵי טְמִירָא, לֵית אַנְתְּ צָרִיךְ לְאִתְגַּלְּיָא כָּל כָּךְ בְּגִין דְּלָא לְמֵיהַב פִּתְחוֹן פֶּה לְעָלְמָא. מַאי טַעְמָא \u0001נ\u0002 אִיהִי, אַתְיָא י' דִּשְׁמָא דִבְרִית קַדִּישָׁא וְרָכִיב עֲלָהּ (ואתאחד) (ואתאחיד) בַּהֲדָהּ. וְרָזָא דָא כַּד בְּרָא קוּדְשָׁא בְּרִיךְ הוּא לְאָדָם הָרִאשׁוֹן דוּ פַּרְצוּפִין בְּרָאוֹ. וּבְגִין כָּךְ אַנְפּוֹי דְּיוּ\"ד מְהַדַּר לַאֲחוֹרָא כְּגַוְונָא דָא [חסר ציור] וְלָא אִתְהַדְּרוּ אַנִפִּין בְּאַנְפִּין כְּגַוְונָא דָא [חסר ציור], אִסְתַּכַּל לְעֵילָא כְּגַוְונָא דָא [חסר ציור], אִסְתַּכָּלַת לְתַתָּא כְּגַוְונָא דָא [חסר ציור], אָמַר לָהּ קוּדְשָׁא בְּרִיךְ הוּא (תוב) (תו), דְּאֲנָא זַמִּין לְנַסְרָא לָךְ וּלְמֶעְבַּד לָךְ אַפִּין בְּאַפִּין אֲבָל בְּאַתְרָא אָחֳרָא תִּסְתַּלַּק. נָפְקַת מִקַּמֵיהּ וְאֲזָלַת.","עָאלַת אָת \u0001פ\u0002 אָמְרָה קַמֵּיהּ, רִבּוֹן עָלְמִין נִיחָא קַמָּךְ לְמִבְרֵי בִּי עָלְמָא דְּהָא פּוּרְקָנָא דְּאַנְתְּ זַמִּין לְמֶעְבַּד בְּעָלְמָא בִּי רְשִׁים, וְדָא הוּא פְּדוּת. וּבִי יָאוֹת לְמִבְרֵי עָלְמָא. אָמַר לָהּ יָאוֹת אַנְתְּ, אֲבָל בָּךְ אִתְרְשִׁים פֶּשַׁע בִּטְמִירוּ, כְּגַוְונָא דְּחִיוְיָא דְּמָחֵי וְאָעִיל רֵישֵׁיהּ בֵּין גּוּפֵיהּ, הָכִי מַאן דְּחָב כָּפִיף רֵישֵׁיהּ וְאַפִּיק יְדוֹי. וְכֵן \u0001ע\u0002 עָוֹן, אַף עַל גַּב דְּאָמְרָה דְּאִית בֵּיה עֲנָוָה, אָמַר לָהּ קוּדְשָׁא בְּרִיךְ הוּא, לָא אִיבְרֵי בָךְ עָלְמָא. נָפְקַת מִקַּמֵּיהּ."],[[0,"","כא) \u0003מרוב אונים\u0004: שואל, מהו, מרוב אונים. ומשיב, זהו ראש המדרגות, שכל הרצונות עולים בו, ומתעלים בו בדרך סתום. \u0003ואמיץ כח\u0004, זהו סוד העולם העליון, הנקרא מ\"י, שנתעלה בשם \u0003אלקים\u0004, כמו שאמרנו. \u0003איש לא נעדר\u0004, היינו מאותם ששים רבוא שהוציא בכח השם הזה. ומשום שאיש לא נעדר ממספר ששים רבוא, ע\"כ בכל מקום שמתו ישראל ונענשו בחטאותיהם, נמנו אח\"כ, ולא נעדר מאלו ששים רבוא אף אחד, כדי שיהיה הכל בצורה אחת, הן למעלה והן למטה, וכמו שאיש לא נעדר ממספר ששים רבוא, למעלה, כך לא נעדר איש ממספר זה למטה."],[0,"","ביאור הדברים, \u0003מרוב אונים\u0004, רומז לכתר דאו\"א עילאין, שהוא \u0003ריש דרגין\u0004 של המוחין הללו, שה\"ס בינה דא\"א שנעשה כתר לאו\"א, ששם \u0003סליקו דכל רעותין\u0004, שכל המדרגות מקבלות ממנה. ועכ\"ז \u0003ואסתלקו ביה בארח סתים\u0004, כי ה\"ס אוירא דלא אתידע שהי' לא נפיק מאוירא דיליה, כי הוא בסוד כי חפץ חסד הוא, וע\"כ הוא בתכלית השלימות (כנ\"ל במראות הסולם ד\"ה והוא) וע\"כ נק' אוירא דכיא, ומשמיענו, שאע\"פ שקומת החסדים המכונה אויר היא יוצאת על בחי' עלמא תתאה, שהיא \u0003מ\"ה\u0004, מ\"מ היא בתכלית השלימות, משום שהאור הזה נמשך מבחינת ג\"ר דבינה דא\"א, שהיא ריש כל דרגין דאצילות, שהן או\"א וישסו\"ת וזו\"ן. ולפיכך נבחנת גם קומת החסדים שבה לבחינת אוירא דכיא כמו בג\"ר דבינה דא\"א."],[0,"","וז\"ש, \u0003ואמיץ כח, דא רזא דעלמא עלאה\u0004: דהיינו בחינת מ\"י שבנוקבא, שמשם נמשך המספר דשתין רבוא. כי היא מלבשת לעלמא עילאה, שהיא או\"א עילאין כנ\"ל. וזה אמרו \u0003איש לא נעדר, מאינון שתין רבוא דאפיק בחילא דשמא\u0004, כי משם משגת המוחין דמספר שתין רבוא, כנ\"ל. וז\"ש, \u0003כמא דאיש לא נעדר לעילא אוף הכי לא נעדר לתתא\u0004: כיון שהנוקבא הלבישה לאו\"א עילאין, בסוד \u0003אמא, אוזיפת לברתא מאנהא וקשיט לה בקישוטהא\u0004, כנ\"ל, ע\"כ נעשית לגמרי כמו או\"א עילאין, וכמו שמוחין דאו\"א עילאין הם שלמים בסוד מספר שיתין רבוא. ואיש מהם לא נעדר, כן הנוקבא שלימה במספר הזה, ואיש לא נעדר."],[1,"","כב) \u0003בראשית, רב המנונא\u0004 וכו': בראשית. רב המנונא סבא אמר, מצאנו במלים בראשית ברא אלקים את, סדר האותיות שבהן, בהפך. שמתחילה כתוב \u0003ב'\u0004 ואחר כך \u0003ב'\u0004, דהיינו בראשית ברא. ואח\"כ כתוב \u0003א'\u0004 בתחילה ואחר כך \u0003א'\u0004, דהיינו \u0003א\u0004לקים א\u0003ת\u0004. ומשיב, כאשר רצה הקב\"ה לעשות את העולם, כל האותיות היו עוד סתומות. ואלפיים שנה מטרם שנברא העולם, היה הקב\"ה מסתכל ומשתעשע באותיות."],[1,"","ביאור הדברים, שתי קושיות מקשה, א) למה באו \u0003האותיות א\"ב בהפוכא\u0004 בהתחלת התורה, מתחילה ב' ואח\"כ א'. ב) למה נכפלו אותן האותיות, שמתחילה ב' ביתין דשתי המלות \u0003בראשית ברא\u0004, ואח\"כ ב' אלפין דשתי המלות \u0003אלהים את\u0004."],[1,"","ומשיב, \u0003כד בעא קב\"ה למעבד עלמא\u0004, בעת שהקב\"ה, שהוא בינה, רצה להוציא את הזו\"ן שהם נק' עולם, היו עוד האותיות, שהן הכלים של זו\"ן, שנקראים אותיות, \u0003סתימין\u0004 שהיו נכללות בגה\"ר שהן או\"א, ולא היו נודעים. וחכמה ובינה נק' ב' אלפין שנין, ומטרם דברא עלמא, היו האותיות דזו\"ן כלולות בחו\"ב, ע\"כ מכונה התכללות זו דזו\"ן שבתוך חו\"ב, אשר \u0003ב' אלפין שנין, עד דלא ברא עלמא, הוה מסתכל קב\"ה ואשתעשע בהו\u0004, כי אז היו הזו\"ן לבחינת מ\"ן בהב' אלפין שנין, שהם חו\"ב, והמ\"ן גורמים תמיד שעשועים לעליון, וז\"ש, שבעת ההיא שהיו למ\"ן בחו\"ב \u0003הוה מסתכל קב\"ה ואשתעשע בהו\u0004."],[2,"","כג) \u0003כד בעא למברי\u0004 וכו': כשרצה לברוא את העולם, באו כל האותיות לפניו מסופן לראשן, והתחילה אות \u0003ת'\u0004 להכנס בתחילה. אמרה רבון העולמים: טוב לפניך, לברוא בי את העולם, כי אני חותמת הטבעת שלך שהיא אמ\u0003ת\u0004, כלומר, אות אחרונה שבמלה אמ\u0003ת\u0004. ואתה נקרא בשם אמת. יפה למלך להתחיל באות אמת, ולברוא בי את העולם. אמר לה הקב\"ה: יפה את, וישרה את, אבל אין את ראויה לברוא בך את העולם, משום שאת עתידה להיות רשומה על מצחותיהם של אנשי האמונה, שקיימו את התורה מן \u0003א'\u0004 עד \u0003ת'\u0004, וברשימתך ימותו (כמ\"ש שבת נ\"ה.) ועוד, שאת חותם המו\u0003ת\u0004, כלומר ש\u0003ת'\u0004 היא אות אחרונה גם במלה מו\u0003ת\u0004. ומשום שאת כך, אין את ראויה לברוא בך את העולם. מיד יצאה."],[2,"","ביאור הדברים, בעת שהתחיל לברר את הזו\"ן הנק' עולם, בכדי למברי אותם, באו כל האותיות דזו\"ן קמיה דקב\"ה, החל ב\u0003ת'\u0004 שהיא סופא דכלהו אתוון ומסיים ב\u0003א'\u0004 שהיא רישא דכלהו אתוון. וענין ביאתן מסופא ארישייהו ולא כסדרן בא\"ב, הוא משום שבאו בסוד מ\"ן, שבהם מסודרים כן בסוד תשר\"ק וכו'. וסדר אב\"ג בסדרן הוא רק בסוד מ\"ד, שהם ממעלה למטה. אבל המ\"ן, סדרן הפוך תמיד מהמ\"ד, להיותו ממטה למעלה. (כמ\"ש בז\"ח שה\"ש אות רפ\"ד)."],[2,"","והנה הדרוש הזה של האותיות הוא עמוק מכל עמוק, ובכדי לבארו באפס מה, אתן לך הקדמה קצרה על הקפו של הדרוש הזה. והוא: כי בריאת העולם פירושו, שכלול וקיום, באופן שיוכל העולם להתקיים ולגמור הכונה שעליה נברא. ונודע שזה לעומת זה עשה אלהים. שפירושו שכנגד כל כח שיש בקדושה, עשה הקב\"ה כח שקול בס\"א כנגד הקדושה, כמו שיש ד' עולמות אבי\"ע דקדושה, כן יש ד' עולמות אבי\"ע דטומאה כנגדם, וע\"כ בעולם עשיה לא יוכר בין עובד אלקים ללא עבדו, שפירושו, שאין בירור כלל בין קדושה לטומאה (ע\"ח ש' מ\"ג בהקדמה) ולפי\"ז קשה מאד, איך אפשר לעולם שיתקיים, כי איך נדע להבדיל בין טוב לרע, בין קדושה לטומאה."],[2,"","אמנם יש בירור אחד חשוב מאד, והוא: כי אל אחר אסתרס ולא עביד פירי, וע\"כ הנכשלים בו ללכת בדרכי אבי\"ע דטומאה, מתייבש מקורם ואין להם שום פירות רוחניות לברכה, והם נובלים והולכים עד שנסתמים לגמרי. והפוכו הם הדבקים בקדושה שזוכים לברכה במעשה ידיהם, \u0003כעץ שתול על פלגי מים אשר פריו יתן בעתו ועלהו לא יבול וכל אשר יעשה יצליח\u0004. (תהלים א') והוא הבירור היחיד שבעולם העשיה, לדעת אם הוא קדושה, או ח\"ו להיפך. וז\"ס הכתוב, \u0003ובחנוני נא בזאת אמר ה' צבאות, אם לא אפתח לכם את ארובות השמים והריקותי לכם ברכה עד בלי די\u0004. ואחר כך כתוב, \u0003ושבתם וראיתם בין צדיק לרשע בין עובד אלהים ללא עבדו\u0004. (מלאכי ג'). הרי מפורש, שאין להבחין כלל בין עובד אלהים ללא עבדו, רק בסוד הברכה בלבד ולא בשום דבר, כי ע\"כ כתוב, ובחנוני נא בזאת."],[2,"","וזהו הקוטב של כל הדרוש הזה של האותיות, כי באו כל האותיות כולן אף אחת מהן לא תחסר, בכדי לברוא העולם בהוראת מדרגתה בקדושה המיוחדת לאותה האות, כי כ\"ב אותיות, הן פרטות כל ראשי המדרגות הנמצאות בד' העולמות אבי\"ע, וכל אות מהן היתה חושבת את מעלת מדרגתה, להורות, שעל ידי השגת מדרגתה, יוכלו בני העולם להגביר את הקדושה על הקליפות, בכדי להגיע אל גמר התיקון הנרצה. והקב\"ה השיב לכל אחת מהן, שיש כנגדה אותו הכח גם בקליפות, ועל כן לא ישיגו בני העולם על ידה שום בירור, עד שבאה ה\u0003ב'\u0004, שהוראת מדרגתה היא הברכה, שכנגדה אין שום לעומת בקלי', כי אל אחר אסתרס ולא עביד פרי כנ\"ל. ואז \u0003אמר לה הקב\"ה, הא ודאי בך אברי עלמא\u0004 וכו'. כי בה לבד יש בירור והבחן לדעת בין עובד ה' ללא עבדו, משום שלא נמצא לה לעומת בס\"א. וע\"כ, בה ודאי יתקיים עלמא לברר ולהגביר את הקדושה על מרכבות הטומאה עד שיבולע המות לנצח. ויבואו לגמר התיקון."],[2,"","גם יש לדעת בכלל, ענין התחלקות כ\"ב האותיות לג' מדרגות בדרך כלל, שהן: בינה, ז\"א, מלכות. כי למעלה מבינה אין כלים, שהם האותיות. וכ\"ב האותיות שבבינה נק' אתוון רברבין, וכ\"ב האותיות שבז\"א הן אתוון סתם, וכ\"ב האותיות שבמלכות הן אתוון זעירין. ועד\"ז הן מתחלקות בדרך פרט לג' מדרגות: בינה, ז\"א, ומלכות. כי בכ\"ב אותיות שבבינה יש בינה, ז\"א ומלכות, וכן בכ\"ב שבז\"א, וכן בכ\"ב שבמלכות. כי ע\"כ כ\"ב האותיות עצמן מתחלקות לג' דרגות: ליחידות, לעשרות ולמאות. שהיחידות מא' עד אות ט', הן ט\"ס דבינה, והעשרות מיו\"ד עד אות צ', הן ט\"ס דז\"א והמאות הן מהנוקבא. ולכן אין במלכות כי אם ד' אותיות קרש\"ת, כי אינה תופסת רק ד' ספי' של הז\"א שמחזה שלו ולמטה, שהן נהי\"ם, \u0003ק\"ר\u0004 הן נו\"ה, \u0003ש\"ת\u0004 הן יסוד ומלכות."],[2,"","ואין להקשות, הרי נודע, שיחידות הן בנוקבא, ועשרות בז\"א ומאות באמא. והענין הוא: כי תמיד יש ערך הפוך בין האורות לכלים, שבכלים נבחן, שהעליונים באים בתחילה, והפוכו באורות, שבהם התחתונים באים תחילה. באופן שאם אין שם אלא יחידות דכלים, שהם מ\u0003א'\u0004 עד \u0003י'\u0004, אין שם אלא בחינת מלכות דאורות. ואם באות גם העשרות דכלים, בא גם אור הז\"א דאורות. ואם נשלמות גם המאות דכלים \u0003קרש\"ת\u0004, באים האורות של הבינה, שהם מאות. וע\"כ נבחנות המאות לבינה, והעשרות לז\"א, והיחידות למלכות. אמנם מבחי' הכלים לבדן הוא בהיפוך, שיחידות באמא, ועשרות בז\"א, ומאות בנוקבא."],[2,"","וז\"ש, \u0003שריאת את ת' למיעל\u0004 וכו'. פירוש, כי ידעת שכל אות ואות מהא\"ב, יש לה מדרגה מיוחדת בשליטתה. ולפיכך טענה ה\u0003ת'\u0004 שהיא יותר ראויה לשכלול העולם מכל האותיות כולן, לפי שבה שליטת האמת, והיא חותמא דגושפנקא דמלכא."],[2,"","והענין הוא, כי נודע שאין הסטרא אחרא מתקיים אלא ממה שהקדושה מאירה לו נהירו דקיק, שה\"ס \u0003ורגליה יורדות מות\u0004, וה\"ס \u0003ומלכותו בכל משלה\u0004. וז\"ס רגל ה\u0003ק'\u0004 הנמשכת למטה משורת האותיות, הרומזת על נהירו דקיק שהמלכות נותנת לס\"א. וע\"כ לא תמצא בכל כ\"ב האותיות יציאת רגל למטה רק ב\u0003ק'\u0004, שהיא שייכת לאותיות המלכות, כי \u0003קרש\"ת\u0004 הן במלכות כנ\"ל. אמנם בתחילה היתה הרגל השמאלית של ה\u0003ת'\u0004 מתחלת להמשך למטה מהשורה, וראה הקב\"ה שתהיה אחיזתו של הס\"א חזקה יותר מדאי, ע\"כ הפסיק אותה הקב\"ה, והחזיר רגלה להסתיים בשוה עם השורה דקדושה, ולכן נתעבתה הרגל השמאלית שלה, כי החלק הנמשך לחוץ שהחזירה, נתכפל עליה שם, ומחמת זה לא מגיעה ממנה שום הארה אל הקלי' וס\"א, ולא עוד, אלא שנתתקנה להיות חותמא דגושפנקא, השומר על הקליפות שלא להתקרב לינק דרך שם מן הקדושה, וכל הנוגע בה ימות. וענין ההארה הדקיקה הנצרכת לקיום הקלי' נעשה באות \u0003ק'\u0004, כי מצד היותה האות היותר גבוהה שבמלכות, ורחוקה מהקלי' והס\"א, ע\"כ אין פחד מאחיזה יתירה אל הקלי'. ומטעם זה נק' \u0003קוף\u0004, להורות שממנה באה תחילת הכח אל הס\"א והקלי', הנק' אדם בליעל, להדמות אל פרצופי הקדושה בסוד \u0003זה לעומת זה\u0004, כמו הקוף הדומה לאדם, וטועים בני אדם אחריהן, והן משקרין בשמא דקודשא ב\"ה."],[2,"","וזה שטענה ה\u0003ת'\u0004, כיון \u0003דאנא חותמא דגושפנקא דילך\u0004, שאנכי עומדת בסיום כל פרצוף, ואיני נותנת לקליפות להתקרב ולינק מהקדושה ולשקר בשמא דילך, לפיכך מהראוי שיברא בי העולם, ועל ידי יהיו כל הבירורים בין הס\"א לקדושה, ויובטחו בני העולם לתעודתם."],[2,"","וזה אמרו \u0003ואת אתקריאת אמת יאות למלכא למשרי באת אמת ולמברי בי עלמא\u0004, פי' כיון שהשם שלך אמת, שמורה שאי אפשר להדבק בך זולת ע\"י השגת מדת האמת, לכן יאות למלכא למשרי באות אמת, ולמברי בי עלמא, כי במדתי ירחיקו בני העולם את הס\"א והקליפות, ויתדבקו בך, ואז יהיו בני העולם מובטחים לגמר התיקון. וזה שאיתא בזוהר: \u0003קרוב ה' לכל קוראיו, למאן קרוב, חזר ואמר, לכל אשר יקראוהו באמת, וכי אית מאן דיקרי ליה בשקרא, אמר ר' אבא, אין, ההוא מאן דקרי ולא ידע למאן דקרי. מנלן, דכתיב לכל אשר יקראוהו באמת, מאי באמת, בחותמא דגושפנקא דמלכא דהוא שלימא דכולא.\u0004 (האזינו אות ר\"י)."],[2,"","והשיב לה הקב\"ה, כי היא אינה ראויה למברי בה עלמא, משום שבכוחה יהיו הדינים קשים יותר מדאי, שהרי אפילו צדיקים גמורים שכבר זכו לרשימו דחותמא שלה, וקיימו את התורה מ\u0003א'\u0004 עד \u0003ת'\u0004, מ\"מ נענשין מכחה קשה, משום שלא מיחו ברשעים. כמ\"ש במ' שבת (דף נ\"ה ע\"א). ועוד שהיא ג\"כ חותמא דמות, שמכחה נתהוה המות בעולם, כי לא נתקבצו בני האדם למיתה, אלא משום שהנחש זייף החותם שלה והחטיא לאדה\"ר בעץ הדעת. כמ\"ש בתקונים (תקון כ\"ב) ולפיכך אי אפשר שיוכל העולם להתקיים על ידה."],[3,"","כד) \u0003עאלת את ש'\u0004 וכו': נכנסה לפניו אות \u0003ש'\u0004. אמרה לפניו: רבון העולמים, טוב לפניך לברוא בי את העולם, כי בי נקרא שמך \u0003ש\u0004די, ויפה לברוא את העולם בשם קדוש. אמר לה: יפה את, וטובה את, ואמיתית את, אבל משום שאותיות שקר לקחו אותך להיות עמהן, איני רוצה לברוא את העולם בך, כי לא יתקיים \u0003ש\u0004קר, אלא אם האותיות \u0003ק' ר'\u0004 יקחו אותך."],[3,"","ביאור הדברים, ב' סיומין יש לה לנוקבא. הא' נק' מלכות דמלכות, והיא ה\u0003ת'\u0004, וסיום הב' נק' יסוד דמלכות, והוא ה\u0003ש'\u0004. והענין הוא, כי בהיותה בלי בנין מאו\"א, נבחנת ה\u0003ת'\u0004 לסיומא, שהיא דינא קשיא, כמ\"ש לעיל בדיבור הסמוך. ובהיותה בבנין פרצוף ע\"י או\"א עילאין, נעשית בסיום שלה אות \u0003ש'\u0004, אשר ג' הראשים של ה\u0003ש'\u0004 מורים על הארת חג\"ת דאמא, שמקבלת ע\"י הז\"א, בנקודת הסיום שלה. בסו\"ה באר חפרוה שרים וגו' (במדבר כ\"א). כי ע\"י הארה זו נעשית כלי לקבל מאה ברכות מז\"א, בסוד אין האשה כורתת ברית אלא למי שעשאה כלי (סנהדרין כ\"ב.), כי נעשית בזה לבית קבול, לקבל מאה ברכאן מהיסוד דז\"א. וע\"כ נקרא הסיום הזה בשם \u0003נקודה האמצעית דישובא\u0004, כי כל ישוב העולם ממנה בא, ונק' ג\"כ בשם יסוד הנוקבא."],[3,"","ולפיכך נק' אות \u0003ש'\u0004 אות אמת כמו ה\u0003ת'\u0004, וכן נק' חותמא דמלכא כמוה. כי מלת חותם היא רבת משמעות. הא', מורה על סיום הפרצוף, כמו חותם המלך, הבא בסיום הכתב, הנכתב בשם המלך. והב' הוא, כי חותם המלך הוא כמו המלך עצמו כמ\"ש בתקונים (תקון כ\"ב), \u0003הכי דחילין מרשימו דחותמא דמלכא כאילו הוי מלכא\u0004. ומטעם זה נקרא החותם אות אמת, כי ע\"כ כל האמתיות ניכרת מתוך החותם. אמנם עולה מעלת ה\u0003ש'\u0004 על ה\u0003ת'\u0004, כי ה\u0003ש'\u0004 נק' בסוד השם \u0003שד\"י\u0004. שפירושו: שאמר לעולמו די ואל תתפשט יותר (חגיגה י\"ב.). ומורה בזה על בנין העולם מבחינת הישוב שנסתיים רק ב\u0003ש'\u0004, ובה אמר לעולמו די, ואל תתפשט בבחינת ה\u0003ת'\u0004. וע\"כ נקראת נקודת הסיום ד\u0003ש'\u0004 בשם נקודה אמצעית דישובא."],[3,"","וזו טענת ה\u0003ש', ניחא קמך למברי בי עלמא, דבי אתקרי שמך שד\"י\u0004 כי אחר שראתה שדחה ה\u0003ת'\u0004 משום מדת הדין הקשה שבה, חשבה ה\u0003ש'\u0004 בעצמה, שהקב\"ה יבחר את מדתה למברי בה עלמא, שהרי יש לה כל המעלות של ה\u0003ת'\u0004, כי גם היא חותם המלך, וגם היא אות אמת. ועוד לה מעלה נוספת, כי בה נק' השם \u0003שד\"י\u0004, כי היא נבחרת לסיומא דנוקבא לבחי' ישוב העולם, ולא ה\u0003ת'\u0004, ע\"כ מצאה עוז בעצמה לבא לפני הקב\"ה שיברא העולם במדתה."],[3,"","השיב לה הקב\"ה, ל\u0003ש'\u0004, אע\"פ שמעלתך גדולה מאד, כמו שאמרת, הנה דוקא משום זאת, הלעומת שלך בקליפה מתחזק ביותר. כי לא היה מתקיים שקרא בעולם, אם לא היו \u0003נטלין לך\u0004 ב' האותיות דזיוף ושקר של הקלי', שהם \u0003ק' ר'\u0004. פי', כי ב' מקורות הן אל הס\"א ולכל הקלי': האחד הוא בחינת הארה דקיק, שהקדושה בעצמה מאירה להן כדי להיות לה קיום, שלא תתבטלנה כל זמן שיש צורך בהן להעניש את הרשעים. ומצד זה אין בנינן גדול כי ההארה מועטת מאד, והוא רק כדי חיותן בלבד, שהזכר דקלי' הוא בבחי' ו\"ק בלי ראש, והנוק' רק בבחינת נקודה בלי התפשטות כלל. וכבר ידעת שהארה דקיק זו נמשכת להן ע\"י אות \u0003ק'\u0004, שבזה התחלת כחן להדמות אל האדם דבי\"ע דקדושה, כקוף בפני אדם. שה\"ס זה לעומת זה עשה אלהים (קהלת ז'). ומקור ב' אל הס\"א, הוא מחמת קלקול התחתונים. שע\"י מעשיהם הרעים מוציאים אורות דקדושה אל הקליפות, שהקלקול הראשון היה בחטא דעצה\"ד, שמכח זה נעשה להן בנין גדול בה' פרצופין ובאבי\"ע, כמו שיש לקדושה."],[3,"","והמקור הב' הזה הוא אות \u0003ר'\u0004, שזה מורה שעולות ומתאחזות עד הבינה דמלכות שהיא אות \u0003ד'\u0004, כי נתבאר לעיל שכ\"ב האותיות של המלכות נחלקות בה, לבינה ז\"א מלכות, שהיחידות בינה, והעשרות ז\"א, והמאות מלכות. ונמצאת ה\u0003ד'\u0004 של כ\"ב אותיות דמלכות עומדת בהתחלת ז\"ת דבינה שלה, כי \u0003אב\"ג\u0004 הן ג\"ר ומה\u0003ד'\u0004 ואילך עד ה\u0003ט'\u0004 הן ו\"ק דבינה שבמלכות."],[3,"","וסוד ה\u0003ד'\u0004 זו מורה על בחינת העוני והמסכנות שבמלכות בכללה, כי \u0003לית לה\u0004 למלכות \u0003מגרמה ולא מידי, אלא ממה דיהיב לה בעלה\u0004 ז\"א, כנודע. ומדתה זו נרשמת בסוד ה\u0003ד'\u0004 שלה. כי במילואה היא \u0003דל\"ת\u0004 מלשון דלות וריקנית, ויש לה ל\u0003ד'\u0004 בחי' זוית בולטת בגגה, שזה מורה על בליטת החסדים שבה, שה\u0003ד'\u0004 לוקחת מן ה\u0003ג'\u0004 שמלפניה, ש\u0003ג'\u0004 זו היא מג\"ר דבינה שלה, המקבלת מבחי' שכנגדה בז\"א, והוא מבחינה שכנגדה בבינה, ששם החסדים בשפע גדול. וע\"כ נק' \u0003ג'\u0004 מלשון גומל חסדים, (שבת ק\"ד). כי הוא גומל חסד עם הד' דלית לה מגרמה ולא מידי ומשפעת לה חסדים בשפע. ובליטת חסדים זו, נרמזה בזויות שבגגה של ה\u0003ד'\u0004."],[3,"","אמנם הלעומת של המלכות דקדושה, הוא נרגן מפריד אלוף, שה\"ס \u0003דל גאה\u0004 ואינה רוצה להיות מקבלת מה\u0003ג'\u0004 ולהיות נכנעת אליה, אלא שמתיימרת להיות ראש בגאוה גדולה, וע\"י פגם זה נמחקה הזוית מן ה\u0003ד'\u0004, שהיא בליטת חסדים שבה, ונעשתה \u0003דל ורש\u0004, כי מחיקת הזוית מן ה\u0003ד'\u0004 עושה אותה צורת \u0003ר'\u0004 דהיינו \u0003רש\u0004, שז\"ס גם במלכותו נולד רש (קהלת ד'). והיחוד של הז\"א ונוקבא דקדושה הוא בסוד \u0003אח\"ד\u0004, כי \u0003א\"ח\u0004 הוא ט\"ס דז\"א, והוא משפיע מן \u0003ג'\u0004 דבינה אל \u0003ג'\u0004 דמלכות, שעי\"ז נעשית המלכות בסוד \u0003ד'\u0004 בזוית בולטת בחסדים בשפע, ועי\"ז נעשים הזו\"ן לבשר \u0003אחד\u0004 ביחוד גמור. ונמצא בעת שהתחתונים מקלקלים מעשיהם נותנים כח למלכות דס\"א להתאחז ב\u0003ד'\u0004 שהיא המלכות. למחוק הזוית הבולטת בחסדים, ולעשותה \u0003ר'\u0004, ואז נעשה מ\u0003אח\"ד אח\"ר\u0004, ואלהים אחרים נאחזים בזו\"ן דקדושה. שז\"ס ונרגן מפריד אלוף (משלי ט\"ז)."],[3,"","ואז נבחן ש\u0003ק\"ר\u0004 דס\"א הנ\"ל חומסות להן את חותם ה\u0003ש'\u0004, שהיא אות אמת, ויסוד הנוקבא, שהיא בית הקבול של יסוד דז\"א, כנ\"ל, הנה עתה הגיע זה לאל אחר דס\"א, כי נבנה ב\u0003ש'\u0004 זו בחי' יסוד אל הנוקבא דס\"א, וגדל ע\"כ הס\"א בע\"ס שלמות עם ראש, ובחינת ה\u0003ש'\u0004 שעשקה נעשית לה לנקודה דחורבא, כי מחורבן הקדושה נבנה הס\"א, ומכאן נבנו האבי\"ע דאדם בליעל. והנה נתבאר, איך \u0003ק\"ר\u0004 הן ב' מקורות של הס\"א, וע\"כ נק' אתוון דזיופי, כי הס\"א זייף אותן על דרך הנ\"ל, כדי להחריב הבנין ויחוד דקדושה, כדי להבנות מחורבן הקדושה, כנ\"ל, והוא בעיקר, ע\"י שהמשיכה להן את ה\u0003ש'\u0004, שהיא צורת היסוד דנוק', אל חלקן ורשותן ע\"י הזיוף של ה\u0003ד'\u0004 ל\u0003ר'\u0004, שזייפו אחד לאחר, ונעשה בנין לפרצופי אלהים אחרים. הרי שלא היו מתקיימים שקרא וזיוף בבנין גדול כל כך, אם לא היו \u0003ק\"ר\u0004 דס\"א חומסות להן את ה\u0003ש'\u0004."],[3,"","וזה שהשיב לה הקב\"ה ל\u0003ש', יאות אנת וטב אנת וקשוט אנת, אבל הואיל ואתוון דזיופא נטלין לך למהוי עמהון לא בעינא למברי בך עלמא, דבגין דלא יתקיים שקרא אלא אי יטלון לך ק\"ר\u0004 דהיינו כמבואר, שלא היה בנין לזיוף ולשקר דס\"א אם לא היו חומסות להן את ה\u0003ש'\u0004, ולפיכך אין לברוא את העולם על ידי מדתה, כי הלעומת שלה שקולה כנגדה, ואין גמר התיקון בטוח על ידה."],[4,"","כה) \u0003מכאן מאן דבעי\u0004 וכו': מכאן נשמע, שכל מי הרוצה לומר שקר, יקח בתחילתו יסוד אמת, ואחר כך יקיים לו השקר. כי אות \u0003ש'\u0004, אות אמת היא, אות אמת שבה נתיחדו האבות, כי ג' הקוים שב\u0003ש'\u0004 רומזים על ג' אבות שהם חג\"ת. ו\u0003ק' ר'\u0004 הן אותיות הנראות על צד הרע, כי הסטרא אחרא היא \u0003קר\u0004, בלי חום שהיא חיות, מפני שהוא יונק מן המלכות בעת שהיא ימא דקאפו (כנ\"ל בראשית א' דף מ\"ז ד\"ה ימא דקאפו) וכדי שיתקיימו, הן לוקחות אות \u0003ש'\u0004 בתוכן, ונעשה, הצירוף, קשר, שהוא לשון חיזוק וקיום. כיון שה\u0003ש'\u0004 ראתה כן, יצאה מלפניו."],[4,"","פירוש. כמ\"ש לעיל, שהארת חג\"ת דבינה המושפעין לה ע\"י יסוד דז\"א, בנתה את נקודת הסיום של הנוקבא, לבחינת כלי ובית קבול למאה ברכאן מהז\"א. והחג\"ת נק' אבות, וז\"ש \u0003דאבהתן אתיחדו בה\u0004, ומשום זה נקרא אות אמת, כנ\"ל ע\"ש."],[4,"ק\"ר אתוון דאתחזיאו על סטרא בישא",": כבר נתבאר זה לעיל בסמוך כי הן ב' המקורות של הס\"א ע\"ש. וז\"ש, \u0003נטלי את ש' בגווייהו הוי קשר\u0004: כי על ידי מחיקתן את הזוית של הד' דאחד, הן חומסות לתוכן את היסוד דנוקבא דקדושה שהיא \u0003ש'\u0004, ונבנה היסוד דנוקבא דקלי' באות ה\u0003ש'\u0004 שע\"י זה נעשה להן אחיזה גדולה ביותר בקדושה, הנק' \u0003קשר\u0004. כי קשר מורה שהאחיזה חזקה מאד וקשה לנתק אותה."],[5,"","כו) \u0003עאלת את צ'\u0004 וכו': נכנסה אות \u0003צ'\u0004. אמרה לפניו: רבון העולם, טוב לך לברוא בי את העולם, שבי חתומים צדיקים, ואתה שנקרא \u0003צ\u0004דיק, אתה רשום בי, שכתוב, כי צדיק ה' צדקות אהב, וראוי לברוא בי את העולם. אמר לה: צדי, צדי את וצדיק את, אבל את צריכה להיות נסתרת, אין את צריכה להתגלות כל כך, להתחיל בך בריאת העולם, בשביל שלא לתת פתחון פה לעולם. מהו הטעם שצריכה להיות נסתרת, הוא מפני ש\u0003נ'\u0004 היתה, ובאה הי' של השם, שהוא ברית הקדוש, ורכבה על ה\u0003נ'\u0004 ונתאחדת עמה. ונעשתה \u0003צ'\u0004. וסוד הדבר הוא, כי כשברא הקב\"ה את אדם הראשון, שה\"ס ז\"א, ב' פרצופין בראו, דהיינו פרצוף זכר ופרצוף נקבה דבוקים זה לזה באחוריהם. ומשום זה פניה של ה\u0003י'\u0004 מוחזרת לאחור, מן ה\u0003נ'\u0004, כעין זה, \u0003צ'\u0004, שה\u0003י'\u0004, פניה לצד זה, וה\u0003נ'\u0004, פניה לצד אחר, ואינם מוחזרים פנים בפנים, כעין זה \u0003צ\u0004 אלא ה\u0003י'\u0004 מסתכלת למעלה כעין זה \u0003צ\u0004, וה\u0003נ'\u0004 מסתכלת למטה כעין זה \u0003צ'\u0004. עוד אמר לה הקב\"ה: אני עתיד לנסור אותך, דהיינו להפריד דבקות אחור באחור שבך, ולעשות אותך בחיבור של פנים בפנים, אבל במקום אחר תתעלה להיות כן, ולא מיד, בהתחלת בריאת העולם. שצריכה אז להיות אחור באחור, שיורה שהארתה נסתרת. וע\"כ אין לברוא בה את העולם. יצאה אות \u0003צ'\u0004 מלפניו, והלכה לה."],[5,"","ביאור הדברים, כי אחר שראתה הצ\u0003ד\u0004י' שה\u0003ת'\u0004 נדחתה מפני הדינין הקשים שבה, וה\u0003ש'\u0004 מפני אחיזת הס\"א שבה. מצאה עוז לחשוב שהיא ודאי ראויה למברי בה עלמא, כי גם לה מעלת החותם כמותן, ונוסף עליהם, שאין בה שום אחיזה אל הס\"א. וז\"ש \u0003בי חתימין צדיקים\u0004, דהיינו חותם אות ברית קודש, ע\"י מילה ופריעה, הדוחה כל החיצונים. \u0003ואנת דאתקריאת צדיק בי רשים\u0004, כי גם הקב\"ה שהוא הבינה, נתקנה בסוד צדיק וצדק כמו הז\"א, שהם ג\"ר דבינה שנתתקנו באו\"א, בסוד האי שביל דאבא, בהאי נתיב דאמא יתיב. ובסוד כתרין רחימין דמתחבקין תדיר בזווג דלא פסיק לעלמין. דכתיב \u0003צדיק ה' צדקות אהב\u0004, צדיק, רומז על יסוד דאבא. צדקות, רומז על יסוד דאמא, שהיא בחינת נצח והוד הנקראים צדקות ה', ומשום שהצדיק צדקות אהב, ע\"כ זווגייהו לא פסיק לעלמין. וע\"כ אמרה: אני ראויה למברי בי עלמא, ועל ידי מדתי יתקיים העולם בדרך בטוח אל גמר התיקון."],[5,"","וז\"ש, \u0003אמר לה, צדי, צדי אנת, וצדיק אנת\u0004: אות צדי היא יסוד דז\"א, וכשהיסוד כלול יחד עם הנוקבא נק' צדיק. כי ט\"ס דז\"א הן מ\u0003י'\u0004 עד \u0003צדי\u0004, וה\u0003ק'\u0004 היא התחלת הנוק', כנ\"ל, וכשהנוקבא דבוקה ביסוד, הרי ה\u0003ק'\u0004 דבוקה בצדי, ונק' אז היסוד, צדיק. וזה ששיבח אותה הקב\"ה, \u0003צדי אנת\u0004, במקומך ביסוד ז\"א. \u0003וצדי אנת\u0004 במקומי, כי את רשומה בי, בזווג דלא פסיק, כדברך. וגם \u0003צדיק אנת\u0004, כי גם הנוקבא כלולה בך, בסוד \u0003ק'\u0004 של אחר הצדי. ועכ\"ז אינך ראויה למברי בך עלמא. כמ\"ש והולך."],[5,"","וז\"ש, \u0003אנת צריך למהוי טמירא לית אנת צריך לאתגליא כל כך\u0004 וכו' \u0003מ\"ט נ' איהי\u0004: פי' כי היסוד דז\"א כולל עמו הנוקבא, שהיא ה\u0003ק'\u0004 בסוד צדיק, כמו שרמז לה הקב\"ה, \u0003צדיק אנת\u0004. וכשהנוקבא כלולה בו בציור ה\u0003צ'\u0004, היא מצטיירת בו כאות \u0003נ'\u0004. כי ה\u0003נ'\u0004 היא בחינת גבורה דז\"א, כי \u0003י' כ' ל'\u0004 הן ג\"ר כח\"ב, ו\u0003מ' נ'\u0004 הן חסד וגבורה. ועל \u0003נ'\u0004 זו נאמר אני בינה לי גבורה (משלי ח). כי בגדלות בעת שהחג\"ת נעשים לחב\"ד כנודע, נעשית גבורה זו לבינה. ובעת קטנות שאבא הוציא אמא לחוץ, נעשית הבינה לגבורה ל\u0003נ'\u0004, וע\"כ רמיז בה נפילה, כי נופלת מבחינת ג\"ר לו\"ק מכח אבא שהוציא בינה וזו\"ן לחוץ מהראש."],[5,"","וזה אמרו \u0003לית אנת צריך לאתגליא כל כך, בגין דלא למיהב פתחון פה לעלמא מ\"ט נ' איהי, אתיא י' דשמא דברית קדישא רכיב עלה ואתאחד בהדה\u0004, כלומר, הנוקבא הכלולה ב\u0003צ'\u0004 היא ציור אות \u0003נ'\u0004 שבה, שהיא גבורה מבחינת בינה הנופלת, וה\u0003י'\u0004 שבה היא יסוד דז\"א עצמו, שהוא שמא דברית קדש. והן עומדות בציור אחור באחור, אשר אחוריהן דבוקים זו בזו ופניהן מגולים לצד חוץ, כי פני הי' מסתכלת לחוץ ולא לצד ה\u0003נ'\u0004, וכן פני ה\u0003נ'\u0004 מסתכלת לצד חוץ ולא לצד ה\u0003י'\u0004, שזה רומז שיש אחיזה באחוריים שלהן, וע\"כ צריכים אחוריהן להיות נסתרים, בסו\"ה \u0003ואחוריהם ביתה\u0004 (מלכים ז'), כדי שלא יתאחזו בהן החיצונים. וז\"ש \u0003לית אנת צריך לאתגליא כל כך בגין דלא למיהב פתחון פה לעלמא\u0004, כי מתוך שיש חסרון באחוריים שלך, הנך צריכה להיות בהסתר, כדי שלא לתת פתחון פה אל החיצונים להתאחז שם בין הדבקים, וע\"כ אינך ראויה למברי בך עלמא, כי גם בך תצויר בחי' אחיזה לקלי', ומכח \u0003צ'\u0004 זו, שהיסוד והמלכות הם בה אב\"א, יצא גם אדה\"ר אב\"א, בסוד דו פרצופין, וז\"ש \u0003ורזא דא כד ברא קב\"ה לאדם הראשון דו פרצופין בראו\u0004."],[5,"","וז\"ש, \u0003תו דאנא זמין לנסרא לך ולמעבד לך אפין באפין אבל באתרא אחרא תסתלק\u0004: פירוש, שמא תאמר, אפשר לי למברי בך עלמא בבחינת פב\"פ, כמו שאנא זמין לנסרא לך אח\"כ ולעשותך פב\"פ. גם זו אינה טענה, כי גם בעת שאתקן לך פב\"פ עם הנוקבא, הנה גם אז לא יהיה זה במקומך למטה, אלא רק על ידי עליה למקומי למקום או\"א עלאין, וכיון שהפב\"פ לא יתוקן במקומך, הרי גם אז תהיה אחיזה לקלי' בדרגתך, וע\"כ אינך ראויה למברי בך עלמא. וז\"ש, תו, עוד יותר מזה, \u0003דאנא זמין לנסרא לך ולמעבר אפין באפין\u0004 אמת הוא שאני עתיד לנסרא לך ולעשותך פב\"פ, אכן לא תהיה זאת במקומך \u0003אבל באתרא אחרא תסתלק\u0004 זה יהיה במקום אחר, דהיינו במקום או\"א, כי אז תעלה ותלביש לאו\"א, אבל במקומך עצמך לא יתוקן זה עד לגמר התיקון. ואיך אברא בך העולם, בעוד שגם בך יש אחיזה לחיצונים."],[6,"","כז) \u0003עאלת את פ'\u0004 וכו': נכנסה אות \u0003פ'\u0004 אמרה לפניו: רבון העולמים, טוב לפניך לברוא בי את העולם, כי הגאולה שאתה עתיד לעשות בעולם רשומה בי, כי זה הוא \u0003פ\u0004דות. כלומר, שהגאולה היא פדות מצרינו. והיא מתחלת באות פ', וע\"כ בי ראוי לברוא את העולם. אמר לה: יפה את, אבל בך נרשם \u0003פ\u0004שע שבסתר, כעין הנחש שמכה ומביא ראשו לתוך גופו. כך מי שחוטא, כופף ראשו, כלומר שמעלים עצמו מעין רואה, ומוציא את ידיו, לחטוא. והיינו כמו צורתה של ה\u0003פ'\u0004 שראשה כפופה לתוכה. וכן אמר לאות \u0003ע'\u0004, שבה נרשם \u0003ע\u0004ון. ואע\"פ שאמרה: שיש בי \u0003ע\u0004נוה. אמר לה הקב\"ה, לא אברא בך את העולם. יצאה מלפניו."],[6,"","ביאור הדברים, פורקנא פירושו גאולה, ואמרה ה\u0003פ'\u0004 כי הגאולה העתידה להיות בעולם רשומה בה, וע\"כ היא ראויה שיברא בה העולם. כי הגלות והגאולה הנוהגים בעולם, הן תלויות בנוקבא, כי בעת שהנוקבא מחוסרת בנין ג\"ר, הנק' מוחין, הנה אז גלו ישראל מעל אדמתם, ארץ ישראל. כי א\"י של מטה מכוונת נגד ארץ ישראל של מעלה, שהיא הנוקבא דז\"א. וכמו שיש פירוד למעלה בין הז\"א שנק' ישראל, לנוקבא שהיא ארצו. כן ישראל שלמטה נפרדים מארצם. וכשבני ישראל מטיבים מעשיהם, גורמים שישראל של מעלה משפיע בנוקביה, שהיא ארצו, ובונה אותה עם מוחין ומתיחד עמה פב\"פ, ואז גם בני ישראל שלמטה זוכים לגאולה וגם הם שבים לאדמתם."],[6,"","ואלו המוחין דג\"ר של הנוקבא, שהז\"א בונה אותה, הם באים אליה מלובשים תוך הנצח וההוד של ז\"א, שמוח החכמה של הנוקבא מלובש בנצח, ומוח הבינה מלובש בהוד. כנודע. והאותיות \u0003ע' פ'\u0004 הן נצח והוד דז\"א, כנ\"ל. וזוהי טענת ה\u0003פ'\u0004 שהיא הוד דז\"א, פ\u0003ורקנא דאנת זמין למעבד בעלמא בי רשים\u0004. כי המוחין דנוקבא המביאים הגאולה לעולם מתלבשים בי, ולכן אם תברא העולם במדתי הרי בלי ספק שיוכשרו לבא לגמר התיקון."],[6,"","ומה שה\u0003פ'\u0004 חשבה את עצמה ראויה למדת בריאת העולם יותר מן ה\u0003ע'\u0004, שהרי המוחין דנוקבא מתלבשים בשניהם בנו\"ה, שהם \u0003ע' פ'\u0004 ועיקרם בנצח שהוא ה\u0003ע'\u0004, וא\"כ למה חשבה ה\u0003פ'\u0004 את עצמה ראויה יותר מן ה\u0003ע'\u0004. וז\"ש \u0003ודא הוא פדות\u0004, כי הפדות היא רק במדת ההוד, שהוא ה\u0003פ'\u0004. וענין הפדות הוא, שאמא פודה תחילה את הנוקבא מן הדינין, ואז הנוקבא ראויה לגאולה. וה\"ס הכתוב כנשר יעיר קנו על גוזליו ירחף וגו' (דברים ל\"ב). ודרשו רז\"ל, הנשר הזה רחמני הוא על בניו וכו', ואומר \u0003מוטב שיכנס החץ בי ואל יכנס בבני\u0004 (עי' רש\"י דברים ל\"ב י\"א)."],[6,"","פירוש, כי נתבאר לעיל אשר המ\"ה אינו ראוי למוחין זולת ע\"י התיקון, \u0003דאמא אוזיפת לבריתא מאנהא\u0004, כי הנוקבא בהיותה ממקורה מצומצמת שלא לקבל האור, דהיינו מעת צמצום א', לא היתה יכולה לקבל שום מוחין, אלא משום שיצאה אמא חוץ מהראש דא\"א, ונעשה ו\"ק בלי ראש, אז נמשכו אתוון \u0003אל\"ה\u0004 שלה אל הנוקבא, ואתבני גם הנוקבא בשמא אלהים. (עי' לעיל אות י\"ז ד\"ה וזה) ואמא נק' \u0003נשר\u0004, שהוא רחמן על בניו זו\"ן, וע\"כ יצאה לחוץ, ונחצית קומתה לו\"ק בלי ראש, דהיינו בחי' \u0003חץ\u0004, שה\"ס שאמרה, מוטב שיכנס החץ בי, שע\"י כן פדתה את הבנים מן הדינים ונעשו ראויים לקבל מוחין בהמאנין שלה \u0003אל\"ה\u0004 כנ\"ל. וז\"ס פדות ופדיון, שאמא פודה את הנוקבא מדינין שלה, שלולא זה, לא היתה ראויה למוחין. ופדות הזו, שורה בעיקר על קו שמאל של הנוקבא ששמה הדינין, וכן על הוד דז\"א, שהוא אות \u0003פ'\u0004. ולפיכך חשבה ה\u0003פ'\u0004 שהיא ראויה יותר מה\u0003ע'\u0004, כי הפדות הזו מאמא מלובשת רק בה ולא ב\u0003ע'\u0004 משום שהדינין הם בקו שמאל, ולא בקו ימין."],[6,"","וז\"ש, \u0003יאות אנת אבל בך אתרשים פשע בטמירו\u0004: כי כל הגאולות הנוהגות בשתא אלפי שני, אינן אלא בבחינת ו\"ק דמוחין דחיה, כי בחינת ג\"ר דמוחין אלו, ה\"ס או\"א הפנימים ששמשו בנקודים, והמה נגנזו, ולא יתגלו זולת בגמר התיקון. דהיינו אחר שיתקן החטא דעצה\"ד, שאדה\"ר חטא והמשיך המוחין עילאין למקום בי\"ע דפרודא שלמטה מפרסא, שאין שם המאנין דאמא, אלא בחינת מלכות המצומצמת, שה\"ס הפרסא שתחת האצילות ששם עומדת עתה ה\"ת דצמצום א', ומסיימת האורות דאצילות, שלא יתפשטו ממנה ולמטה. וע\"י זה, שהמשיך השפע למטה מפרסא דאצילות אתרשים פשע בנוקבא, שה\"ס בא הנחש על חוה והטיל בה זוהמא, (שבת קמ\"ו.) אשר זוהמא זו לא תתוקן אלא בגמר התיקון בסו\"ה \u0003בלע המות לנצח ומחה אדני ה' דמעה מעל כל פנים\u0004. (ישעיה כ\"ה) כי החסרון של המוחין דאו\"א הפנימים שנגנזו, נק' בשם דמעות, שה\"ס ב' דמעות שמוריד ה' לים הגדול, שהן כנגד ב' עיינין, חו\"ב אלו הפנימיים, שנגנזו ואינם. כי עינים ה\"ס חו\"ב, ודמעות הן בחינת חסרון שבהם, מכח הזוהמא שנתערבה ונדמעה ע\"י חטא עצה\"ד, וזה גרם החורבן של ב' מקדשין. (עי' זהר בראשית א' אות רנ\"ד) ואומר הכתוב שאין הדמעות האלו נמחות מהפנים של הנוקבא, זולת בעת שיבולע המות לנצח. דהיינו שיתוקן חטא עצה\"ד לגמרי, כי יתוקן הפשע, שהוא המות לעולם, ואז יאירו גה\"ר של מוחין דחיה, שהם חו\"ב הפנימים ונמצא שמחה אדני ה' דמעה וכו'."],[6,"","וזה אמרו, \u0003יאות אנת, אבל בך אתרשים פשע בטמירו\u0004 כי אע\"פ שיש בך פדות ע\"י אמא, שע\"י כן את מביאה גאולה לעולם, שהיא המוחין דחיה, שכל הגאולות באות על ידיה, ועכ\"ז הרי הגאולות אלו מחוסרי השלימות, כי חזרו ונגלו מעל אדמתם, וב' המקדשין חזרו ונחרבו, והוא מטעם כי \u0003בך אתרשים פשע בטמירו\u0004, כי הפדות דאמא עוד אין ביכלתה למחות הפשע דחטא עצה\"ד, לגמרי, וע\"כ יש בך עוד אחיזה לקלי', כי ע\"כ אין המוחין אלא מבחינת ו\"ק דחיה, והם חסרים בחי' ראש דמוחין דחיה. ולפי שיש בך אחיזה לקלי', אינך ראויה שיברא העולם על ידיך."],[6,"","וז\"ש, \u0003כגוונא דחיויא דמחי ואעיל רישיה בין גופיה\u0004: כי הפשע הזה להיותו בטמירו, נמצא כח הנחש, דמחי לבני עלמא והביא מיתה לעולם, עודו בכל תוקפו, ואי אפשר להעביר אותו. בדומה לנחש הנושך לאדם, ותיכף מכניס ראשו לגופו, שאז אי אפשר להורגו, כי אין הנחש נהרג אלא אם פוגעין בראשו. וזה שגרם לאדם \u0003דחב\u0004 בעצה\"ד, ולבניו, \u0003דכפיף רישיה ואפיק ידוי\u0004. כלומר, שגם המוחין הנמשכים ע\"י הפדות דאמא, הם בבחי' כפיפת ראש, ורק ידוי, שהן חג\"ת מתגלים במוחין ההם. הרי שאחיזת הנחש עוד נמצאת בפ', וע\"כ אינה ראויה למברי בה עלמא, כי לא תהיה ראויה לגמר התיקון. כמבואר."],[6,"","וז\"ש, \u0003וכן ע' עון, אע\"ג דאמרה דאית בי ענוה\u0004 וכו': אמא עילאה נקראת ענוה. ונודע שבהיות הנצח דז\"א, שהוא \u0003ע'\u0004, מתלבש עם המוחין בנוקבא, היא עולה ומלבשת לאמא עילאה, ואמא מקשטת לה בקישוטהא, כנ\"ל. וזהו שאמרה דאית בי \u0003ענוה\u0004, כי אמא שנק' ענוה מתלבשת בי. אמנם בשביל האי פשע הנ\"ל בדיבור הסמוך, דאית בהו, בנצח הוד אלו, בטמירו, לכן אמר לה קב\"ה ל\u0003ע'\u0004, לא אברי בך עלמא."],[6,"","ומה שמכנה כאן הפשע בלשון עון, ולא פשע כנ\"ל ב\u0003פ'\u0004, הוא כי עיקר הפשע אתרשים בהוד, שהוא \u0003פ'\u0004, מפני שההוד דז\"א הוא מהתכללות המלכות בו, שבה נאחזו הקליפות מכח החטא דעצה\"ד כנ\"ל. אבל נצח דז\"א כבר הוא מדת עצמו דז\"א, שלפי האמת אין אחיזה לקלי' בו, אלא בסוד בהדי הוצא לקי כרבא (ב\"ק צ\"ב) נאחזו הקלי' גם בנצח. כנודע. ולכן נבחן בו זה הקלקול בשם עון, להורות כי באמת ישר הוא אלא שנתעוות מכח חיבורו עם ההוד. (עי' בתלמוד עשר ספירות חלק י\"ג אות ר\"ו ד\"ה אבל, ובאו\"פ)."],[6,"","ומה שאינו אומר באות \u0003ע', עאלת אות ע'\u0004, כמו שאומר בכל האותיות, אלא שכללה יחד עם ה\u0003פ'\u0004, הוא מפני שנצח והוד הם תרי פלגי דגופא, ולפיכך עלו באמת שתיהן כאחת, אלא שהזוהר מבאר טעם כל אחת לחוד, בזו אחר זו."]],[[0,"","(ישעיה מ) מֵרֹב אוֹנִים. מַה זֶּה מֵרֹב אוֹנִים זֶה רֹאשׁ הַדְּרָגוֹת, שֶׁעוֹלִים בּוֹ כָּל הָרְצוֹנוֹת וַעֲלִיָּתָם בוֹ בְּדֶרֶךְ נִסְתָּר. וְאַמִּיץ כֹּחַ - זֶה סוֹד הָעוֹלָם הָעֶלְיוֹן שֶׁהִתְעַלָּה בַשֵּׁם אֱלֹהִים כְּמוֹ שֶׁאָמַרְנוּ. אִישׁ לֹא נֶעְדָּר - מֵאוֹתָם שִׁשִּׁים רִבּוֹא שֶׁהוֹצִיא בְּכֹחַ הַשֵּׁם. וּמִשּׁוּם שֶׁאִישׁ לֹא נֶעְדָּר, בְּכָל מָקוֹם שֶׁמֵּתוּ יִשְׂרָאֵל וְנֶעֶנְשׁוּ בַּחֲטָאֵיהֶם, נִמְנוּ וְלֹא נֶעְדַּר מֵאוֹתָם שִׁשִּׁים רִבּוֹא אֲפִלּוּ אֶחָד כְּדֵי לִהְיוֹת הַכֹּל צוּרָה אַחַת. כְּמוֹ שֶׁאִישׁ לֹא נֶעְדַּר לְמַעְלָה, אַף כָּךְ לֹא נֶעְדַּר לְמַטָּה."],[1,"","בְּרֵאשִׁית, רַב הַמְנוּנָא הַזָּקֵן אָמַר, מָצָאנוּ אוֹתִיּוֹת בְּהִפּוּךְ. בֵּי\"ת בַּהַתְחָלָה וְאַחַר כָּךְ. ב' בַּהַתְחָלָה - הַיְנוּ בְּרֵאשִׁית. בָּרָא לְאַחַר מִכֵּן. אָלֶ\"ף בַּהַתְחָלָה וְאַחַר כָּךְ. אָלֶ\"ף בַּהַתְחָלָה - הַיְנוּ אֱלֹהִים, אֶת לְאַחַר מִכֵּן. אֶלָּא כְּשֶׁרָצָה הַקָּדוֹשׁ-בָּרוּךְ-הוּא לַעֲשׂוֹת אֶת הָעוֹלָם, כָּל הָאוֹתִיּוֹת הָיוּ נִסְתָּרוֹת. וְאַלְפַּיִם שָׁנָה טֶרֶם שֶׁבָּרָא אֶת הָעוֹלָם הָיָה מִסְתַּכֵּל הַקָּדוֹשׁ-בָּרוּךְ-הוּא וּמִשְׁתַּעֲשֵׁעַ בָּהֶם."],[2,"","כְּשֶׁרָצָה לִבְרֹא אֶת הָעוֹלָם, בָּאוּ לְפָנָיו כָּל הָאוֹתִיּוֹת מִסּוֹפָם לְרֹאשָׁם. הִתְחִילָה הָאוֹת ת' לְהִכָּנֵס בָּרֹאשׁ. אָמְרָה: רִבּוֹן הָעוֹלָמִים, נוֹחַ לְפָנֶיךְ לִבְרֹא בִּי אֶת הָעוֹלָם, שֶׁאֲנִי תַּשְׁלוּם חוֹתָם שֶׁלְּךְ אֱמֶ\"ת, וְאַתָּה נִקְרֵאתָ אֱמֶ\"ת, רָאוּי לְמֶלֶךְ (אמת) לְהַתְחִיל בְּאוֹת אֱמֶ\"ת וְלִבְרֹא בִּי אֶת הָעוֹלָם. אָמַר לָהּ הַקָּדוֹשׁ-בָּרוּךְ-הוּא: רְאוּיָה אַתְּ וְזַכָּאִית אַתְּ, אֶלָּא שֶׁאֵינֵךְ כְּדָאִית לִבְרֹא בָּךְ אֶת הָעוֹלָם, הוֹאִיל וְאַתְּ עֲתִידָה לִהְיוֹת רְשׁוּמָה עַל מִצְחֵי הָאֲנָשִׁים הַנֶּאֱמָנִים שֶׁקִּיְּמוּ אֶת הַתּוֹרָה מֵאָלֶ\"ף וְעַד תָּי\"ו, וּבָרֹשֶׁם שֶׁלָּךְ יָמוּתוּ. וְעוֹד, שֶׁאַתְּ חוֹתַם הַמָּוֶת. וְהוֹאִיל וְאַתְּ כָּךְ, אֵינֵךְ כְּדָאִית לִבְרֹא בָּךְ אֶת הָעוֹלָם. מִיָּד יָצְאָה."],[3,"","נִכְנְסָה הָאוֹת ש' לְפָנָיו. אָמְרָה לְפָנָיו: רִבּוֹן הָעוֹלָמִים, נוֹחַ לְפָנֶיךְ לִבְרֹא בִּי אֶת הָעוֹלָם, שֶׁבִּי נִקְרֵאתָ שִׁמְךְ שַׁדַּי, וְרָאוּי לִבְרֹא אֶת הָעוֹלָם בְּשֵׁם קָדוֹשׁ. אָמַר לָהּ: רְאוּיָה אַתְּ וְטוֹבָה אַתְּ וֶאֱמֶת אַתְּ, אֲבָל הוֹאִיל וְהָאוֹתִיּוֹת שֶׁל הַזִּיּוּף נוֹטְלִים אוֹתָךְ לִהְיוֹת עִמָּהֶם, אֵינִי רוֹצֶה לִבְרֹא בָּךְ אֶת הָעוֹלָם, שֶׁכְּדֵי שֶׁלֹּא יִתְקַיֵּם הַשֶּׁקֶר אֶלָּא אִם יִטְלוּ אוֹתָךְ ק ר."],[4,"","מִכָּאן, שֶׁמִּי שֶׁרוֹצֶה לוֹמַר שֶׁקֶר, יִטֹּל יְסוֹד שֶׁל אֱמֶת בַּהַתְחָלָה וְאַחַר כָּךְ יְקַיֵּם אֶת הַשֶּׁקֶר. שֶׁהֲרֵי הָאוֹת ש' הִיא אוֹת אֱמֶת, אוֹת הָאֱמֶת שֶׁהִתְיַחֲדוּ בָהּ הָאָבוֹת. ק' ר' הָאוֹתִיּוֹת שֶׁנִּרְאוּ עַל הַצַּד הָרָע הֵם, וּכְדֵי לְהִתְקַיֵּם נָטְלוּ אֶת הָאוֹת ש' בְּתוֹכָן וְנִהְיָה קֶשֶׁר. כֵּיוָן שֶׁרָאֲתָה כָּךְ, יָצְאָה מִלְּפָנָיו."],[5,"","נִכְנְסָה הָאוֹת צ'. אָמְרָה לְפָנָיו: רִבּוֹן הָעוֹלָם, נוֹחַ לְפָנֶיךְ לִבְרֹא בִּי אֶת הָעוֹלָם, שֶׁאֲנִי (נ\"א: שבי) חֲתוּמִים הַצַּדִּיקִים, וְאַתָּה שֶׁנִּקְרֵאתָ צַדִּיק רָשׁוּם בִּי, שֶׁכָּתוּב (תהלים יא) כִּי צַדִּיק ה' צְדָקוֹת אָהֵב, וּבִי רָאוּי לִבְרֹא אֶת הָעוֹלָם. אָמַר לָהּ: צָדִי, צָדִי אַתְּ וצַּדּיּק אַת, אֲבָל אַתְּ צְרִיכָה לִהְיוֹת טְמוּנָה, אֵינֵךְ צְרִיכָה לְהִתְגַּלּוֹת כָּל כָּךְ כְּדֵי שֶׁלֹּא לָתֵת פִּתְחוֹן פֶּה לָעוֹלָם. מַהוּ הַטַּעַם נ' הִיא. בָּאָה הַי' שֶׁל הַשֵּׁם שֶׁל הַבְּרִית הַקָּדוֹשׁ וְרוֹכֵב עָלֶיהָ ונאחָז עִמָּהּ. וְזֶה הַסּוֹד, כְּשֶׁבָּרָא הַקָּדוֹשׁ-בָּרוּךְ-הוּא אֶת אָדָם הָרִאשׁוֹן, בָּרָא אוֹתוֹ דּוּ פַּרְצוּפִים, וּמִשּׁוּם כָּךְ הַפָּנִים שֶׁל יוֹ\"ד חוֹזֵר לְאָחוֹר כְּמוֹ זֶה: (ציור למעלה) וְלֹא חוֹזְרִים פָּנִים בְּפָנִים כְּמוֹ זֶה: מִסְתַּכֵּל לְמַעְלָה כְּמוֹ זֶה: (ציור למעלה) מִסְתַּכֵּל לְמַטָּה כְּמוֹ זֶה: (ציור למעלה) אָמַר לָהּ הַקָּדוֹשׁ-בָּרוּךְ- הוּא עוֹד, שֶׁאֲנִי עָתִיד לְנַסֵּר אוֹתָךְ וְלַעֲשׂוֹת אוֹתָךְ פָּנִים בְּפָנִים, אֲבָל בְּמָקוֹם אַחֵר תִּתְעַלִּי. יָצְאָה מִלְּפָנָיו וְהָלְכָה."],[6,"","נִכְנְסָה הָאוֹת פ'. אָמְרָה לְפָנָיו: רִבּוֹן הָעוֹלָמִים, נוֹחַ לְפָנֶיךְ לִבְרֹא בִּי אֶת הָעוֹלָם, שֶׁהֲרֵי הַפְּדוּת שֶׁאַתָּה עָתִיד לַעֲשׂוֹת בָּעוֹלָם רְשׁוּמָה בִי, וְזוֹ הִיא פְדוּת, וּבִי רָאוּי לִבְרֹא אֶת הָעוֹלָם. אָמַר לָהּ: רְאוּיָה אַתְּ, אֲבָל בָּךְ רָשׁוּם פֶּשַׁע בַּסֵּתֶר. כְּמוֹ שֶׁהַנָּחָשׁ שֶׁמַּכֶּה וּמַכְנִיס רֹאשׁוֹ בֵּין גּוּפוֹ, כָּךְ מִי שֶׁחוֹטֵא, כּוֹפֵף רֹאשׁוֹ וּמוֹצִיא יָדָיו. וְכֵן ע' עָוֹן, אַף עַל גַּב שֶׁאָמְרָה שֶׁיֵּשׁ בָּהּ עֲנָוָה, אָמַר לָהּ הַקָּדוֹשׁ- בָּרוּךְ-הוּא: לֹא אֶבְרָא בָּךְ אֶת הָעוֹלָם. יָצְאָה מִלְּפָנָיו."]]],[["עָאלַת אָת \u0001ס\u0002 אָמְרָה קַמֵּיהּ, רִבּוֹן עָלְמִין, נִיחָא קַמָּךְ לְמִבְרֵי בִּי עָלְמָא, דְּאִית בִּי סְמִיכָא לַנֹפְלִין דִּכְתִיב, (תהילים קמ״ה:י״ד) סוֹמֵךְ יְיָ לְכָל הַנּוֹפְלִים. אָמַר לָהּ, עַל דָּא אַנְתְּ צָרִיךְ לְאַתְרָךְ וְלָא תָזוּז מִנֵּיהּ, אִי אַתְּ נָפִיק מֵאַתְרָךְ מַה תְּהֵא עֲלַיְיהוּ (ו' ע\"א) דְּאִנּוּן נְפִילִין הוֹאִיל וְאִנּוּן סְמִיכִין עֲלָךְ. מִיָּד נָפְקַת מִקַּמֵּיהּ.","עָאלַת אָת \u0001נ\u0002 אָמְרָה קַמֵּיהּ, רִבּוֹן עָלְמָא, נִיחָא קַמָּךְ לְמִבְרֵי בִּי עָלְמָא, דְּבִי כְּתִיב נוֹרָא תְהִלּוֹת וּתְהִלָּה דְּצַדִּיקִים נָאוָה תְהִלָּה. אָמַר לָהּ, נוּ\"ן תּוּב לְאַתְרָךְ, דְּהָא בְגִינָךְ תָּבַת סַמֶ\"ךְ לְאַתְרָהּ וְהֲוֵי סָמִיךְ עֲלָהּ. מִיָּד תָּבַת לְאַתְרָהּ וְנָפְקַת מִקַּמֵּיהּ.","עָאלַת אָת \u0001מ\u0002 אָמְרָה קַמֵּיהּ רִבּוֹן עָלְמָא, נִיחָא קַמָּךְ לְמִבְרֵי בִּי עָלְמָא, דְּבִי אִתְקְרִיאַת מֶלֶךְ. אָמַר לָהּ הָכִי הוּא וַדַּאי, אֲבָל לָא אִבְרֵי בָּךְ עָלְמָא בְּגִין דְּעָלְמָא אִצְטְרִיךְ לְמֶלֶךְ תּוּב לְאַתְרָךְ, אַנְתְּ וְ-\u0001ל\u0002 וְ-\u0001ך\u0002 דְּהָא לָא יָאוֹת לְעָלְמָא לְמֵיקַם בְּלָא מֶלֶךְ.","בְּהַהִיא שַׁעֲתָא נָחֲתָא \u0001כ\u0002 מִן קֳדָמוֹהִי אָת מֵעַל כּוּרְסֵי יְקָרֵיהּ אִזְדַעְזְעַת וְאָמְרָה קַמֵּיהּ, רִבּוֹן עָלְמָא, נִיחָא קַמָּךְ לְמִבְרֵי בִּי עָלְמָא דְּאֲנָא כְּבוֹדָךְ. וְכַד נָחֲתַת \u0001כ\u0002 מֵעַל כּוּרְסֵי יְקָרֵיהּ אִזְדַּעְזְעוּ מָאתָן (ח ב') אֶלֶף עָלְמִין וְאִזְדַּעְזַע כֻּרְסְיָיא וְכֻלְהוּ עָלְמִין אִזְדַּעְזָעוּ לְמִנְפַּל. אָמַר לָהּ קוּדְשָׁא בְּרִיךְ הוּא כָ\"ף כָ\"ף, מָה אַתְּ עָבִיד הָכָא, דְּלָא אִבְרֵי בָּךְ עָלְמָא. תּוּב לְאַתְרָךְ דְּהָא בָּךְ כְּלָיָה (ישעיהו י׳:כ״ג) כָּלָה וְנֶחרָצָה אִשְׁתְּמַע, תּוּב לְכָרְסְיָיךְ וְהֲוֵי תַמָּן. בְּהַהִיא שַׁעֲתָא נָפְקַת מִקַּמֵּיהּ וְתָבַת לְדוּכְתָּהּ.","עָאְלַת אָת \u0001י\u0002 אָמְרָה קַמֵּיהּ, רִבּוֹן עָלְמָא, נִיחָא קַמָּךְ לְמִבְרֵי בִּי עָלְמָא דְּאֲנָא שֵׁירוּתָא דִשְׁמָא קַדִּישָׁא וְיָאוֹת לָךְ לְמִבְרֵי בִּי עָלְמָא. אָמַר לָהּ, דַּי לָךְ דְּאַנְתְּ חָקִיק בִּי, וְאַנְתְּ רָשִׁים בִּי, וְכָל רְעוּתָא דִילִי בָּךְ סָלִיק, לֵית אַנְתְּ יָאוֹת לְאִתְעַקָּרָא מִן שְׁמִי.","עָאלַת אָת \u0001ט\u0002 (תרומה קנ\"ב ע\"א) אָמְרָה קַמֵּיהּ רִבּוֹן עָלְמָא נִיחָא קַמָּךְ לְמִבְרֵי בִּי עָלְמָא דְּאַנְתְּ בִּי אִתְקְרִיאַת טוֹב וְיָשָׁר. אָמַר לָהּ לָא אִבְרֵי בָּךְ עָלְמָא דְּהָא טוּבָךְ סָתִים בְּגַוָּוךְ, וְצָפוּן בְּגַוָּוךְ, הֲדָא הוּא דִכְתִיב, (תהילים ל״א:כ׳) מָה רַב טוּבְךָ אֲשֶׁר צָפַנְתָּ לִירֵאֶיךָ הוֹאִיל וְגָנִיז בְּגַוָּוךְ לֵית בֵּיהּ חוּלָקָא לְעָלְמָא דָא דְּאֲנָא בָּעֵי לְמִבְרֵי, אֶלָּא בְּעָלְמָא (שמות קנ\"ב א) דְּאֲתֵי. וְתוּ דְּעַל דְּטוּבָךְ גָּנִיז בְּגַוָּוךְ יִטְבְּעוּן תַּרְעֵי דְהֵיכָלָא. הֲדָא הוּא דִכְתִיב, (איכה ב׳:ט׳) טָבְעוּ בָאָרֶץ שְׁעָרֶיהָ. וְתוּ דְ\u0001ח\u0002 לְקִבְלָךְ וְכַד תִּתְחַבְּרוּן כְּחֲדָא הָא \u0001ח\"ט\u0002, וְעַל דָּא אָתְוָון אִלֵּין לָא רְשִׁימִין בְּשִׁבְטִין קַדִּישִׁין. מִיָּד נָפְקַת מִקַּמֵּיהּ.","עָאלַת \u0001ז\u0002 אָת אָמְרָה קַּמֵּיהּ רִבּוֹן עָלְמָא, נִיחָא קַמָּךְ לְמִבְרֵי בִּי עָלְמָא, דְּבִי נָטְרִין בְּנָיךְ שַׁבָּת דִּכְתִיב, (שמות כ׳:ח׳) זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ. אָמַר לָהּ לָא אִבְרֵי בָּךְ עָלְמָא דְּאַנְתְּ אִית בָּךְ קְרָבָא וְחַרְבָּא דְּשִׁנְנָא וְרוֹמָחָא דִקְרָבָא כְּגַוְונָא דְנוּן. מִיָּד נָפְקַת מִקַּמֵּיהּ.","עָאלַת אָת \u0001ו\u0002 אָמְרָה קַמֵּיהּ רִבּוֹן עָלְמָא, נִיחָא קַמָּךְ לְמִבְרֵי בִּי עָלְמָא, דְּאֲנָא אָת מִשְּׁמָךְ. אָמַר לָהּ וָאו אַנְתְּ וְ דַי לְכוֹן דְּאַתּוּן אָתְוָון דִּשְׁמִי דְּאַתּוּן בְּרָזָא דִשְׁמִי וְחֲקִיקִין וּגְלִיפִין בִּשְׁמִי וְלָא אִבְרֵי בָּכוּ עַלְמָא.","עָאלַת אָת \u0001ד\u0002 וְאָת \u0001ג\u0002 אָמְרוּ אוּף הָכִי, אָמַר אוּף לוֹן דַּי לְכוֹן לְמֶהוֵי דָּא עִם דָּא דְּהָא מִסְכְּנִין לָא יִתְבַּטְּלוּן מִן עָלְמָא וּצְרִיכִין לִגְמוֹל עִמְּהוֹן טִיבוּ. דָּלֶ\"ת אִיהוּ מִסְכְּנָא, גִימְ\"ל גְּמוֹל לָהּ טִיבוּ, לָא תִתְפָּרְשׁוּן דָּא מִן דָּא וְדַי לְכוֹן לְמֵיזַן דָּא לְדֵין.","עָאלַת אָת \u0001ב\u0002 אָמְרָה לֵיהּ, רִבּוֹן עָלְמָא, נִיחָא קַמָּךְ לְמִבְרֵי בִּי עָלְמָא, דְּבִי מְבָרְכָאן לָךְ לְעֵילָא וְתַתָּא. אָמַר לָהּ קוּדְשָׁא בְּרִיךְ הוּא, הָא וַדַּאי בָּךְ אִבְרֵי עָלְמָא וְאַתְּ תְּהֵא שֵׁירוּתָא לְמִבְרֵי עָלְמָא.","קָיְימָא אָת \u0001א\u0002 לָא עָאלַת. אָמַר לָהּ קוּדְשָׁא בְּרִיךְ הוּא אָלֶ\"ף אָלֶ\"ף לָמָּה לֵית אַנְתְּ עָאלַת קַמָּאי כִּשְׁאָר כָּל אָתְוָון. אָמְרָה קַמֵּיהּ רִבּוֹן עָלְמָא בְּגִין דַּחֲמֵינָא דְכָל אָתְוָון נָפְקוּ מִן קַמָּךְ בְּלָא תוֹעַלְתָּא מָה אֲנָא אַעֲבִיד תַּמָּן. וְתוּ דְּהָא יְהִיבְתָּא לְאָת בֵּי\"ת נְבַזְבְּזָא רַבְרְבָא דָא, וְלָא יָאוֹת לְמַלְכָּא עִלָּאָה לְאַעֲבָרָא נְבַזְבְּזָא דְּיָהַב לְעַבְדוֹ וּלְמֵיהַב לְאָחֲרָא. אָמַר לָהּ קוּדְשָׁא בְּרִיךְ הוּא אָלֶ\"ף אָלֶ\"ף אַף עַל גַּב דְּאָת בֵי\"ת בַּהּ אִבְרֵי עָלְמָא, אַתְּ תְּהֵא רֵישׁ לְכָל אָתְוָון, לֵית בִּי יִחוּדָא אֶלָּא בָּךְ. בָּךְ יִשְׁרוּן כָּל חוּשְׁבָּנִין וְכָל עוֹבָדֵי דְעָלְמָא, וְכָל יִחוּדָא לָא הֲוֵי אֶלָּא בְּאָת אָלֶ\"ף."],[[0,"","כח) \u0003עאלת את ס'\u0004 וכו': נכנסה אות \u0003ס'\u0004, אמרה לפניו: רבון העולמים, טוב לפניך לברוא בי את העולם. כי יש בי \u0003ס\u0004מיכה לנופלים, שכתוב, סומך ה' לכל הנופלים. אמר לה: משום זה את צריכה למקומך, ואל תזוזי ממנו, שאם את יוצאת ממקומך, שבמלה סמך, אלו הנופלים מה יהיה עליהם, מאחר שהם סמוכים עליך. מיד יצאה מלפניו."],[0,"","ביאור הדברים, אות \u0003ס'\u0004 היא ת\"ת דז\"א, והיא בחינת בינה דגופא, כי הכח\"ב שנעשו בז\"א לחסדים נשתנו שמייהו לחג\"ת, כנודע, והנה הבינה נחלקה לב' בחינות ג\"ר וז\"ת, שהג\"ר שבה נעשו לאו\"א עילאין ומלבישין מחזה ולמעלה דא\"א, ונחשבין עוד לבחינת ראש דא\"א אע\"פ שעומדים בגוף שלו, להיותם אור חסדים, בסוד כי חפץ חסד הוא (סוף מיכה). ולפי שאינם מקבלים אור חכמה גם בהיותם בראש א\"א, ע\"כ אין היציאה מהראש ממעטת אותם כלל, ונחשבים עוד לבחי' ראש א\"א. והם נק' \u0003ס'\u0004, מפני שאלו ג\"ר דבינה נתקנו לאו\"א, ומתפשטות בהן שש ספירות חב\"ד חג\"ת עד החזה. אבל ז\"ת דבינה, שהן מבחינת התכללות הזו\"ן בבינה, ואינן עצם הבינה, הנה נתחלקו מהבינה, ונעשו לפרצוף ישסו\"ת, המלבישים לד' ספירות תנה\"י דאו\"א, שהם מחזה דאו\"א ולמטה, והם צריכים להארת חכמה, בכדי להשפיע לזו\"ן, וכיון שיצאו מהראש דא\"א לבחינת גוף, והם מחוסרי חכמה, לכן נפגמו מחמת יציאתן, ונעשו ו\"ק חסר ראש, והן נק' \u0003ם'\u0004 סתומה, מטעם שהם תופסים רק ד' ספירות תנה\"י דאו\"א. שהם מלבישים שם כנ\"ל. (ועי' במראות הסולם אות ב' ד\"ה והוא)."],[0,"","והנה התחלקות הבינה ל\u0003ס'\u0004 ו\u0003ם'\u0004 האמורים, זה נעשה בבינה דא\"א שיצאה לבר מהראש דא\"א, ונתפשטה בחג\"ת שלו עד שליש תחתון דת\"ת שבו. והם המשפיעים כל המוחין לזו\"ן."],[0,"","אמנם לא כל העתים שוות. כי בעת שהתחתונים מטיבים מעשיהם ומעלים מ\"ן לזו\"ן והזו\"ן לאו\"א, הנה אז נעשים או\"א וישסו\"ת פרצוף אחד, ועולים לא\"א, ומשפיעים מוחין שלימים בהארת חכמה מא\"א אל הז\"א, והז\"א אל הנוקבא בסוד מאה ברכות, כי ה\u0003ס'\u0004 שהיא או\"א עילאין, נעשתה אחת עם ה\u0003ם'\u0004 שהם ישסו\"ת שעולים יחד למספר מאה. אכן בעת שהתחתונים חוזרים ומקלקלים מעשיהם, נמצאים המוחין מסתלקים מהזו\"ן וחוזרים לבחינת ו\"ק ונקודה. וגם או\"א וישסו\"ת מתחלקים זה מזה ואו\"א עי' נעשים שוב ל\u0003ס'\u0004 שהיא שש ספירות חב\"ד חג\"ת לבד, שכל אחת כלולה מיו\"ד, וישסו\"ת שוב נעשים ל\u0003ם'\u0004 סתומה, שהיא תנה\"י דאו\"א לבד. כנ\"ל."],[0,"","ובעת שהזו\"ן הם במצב הזה של הקטנות דו\"ק ונקודה, יש פחד מאחיזת הקליפות. שאז היו נופלים מאצילות לבי\"ע דפירודא. לכן משפיעים להם או\"א עילאין מבחי' ה\u0003ס'\u0004 שלהם, אשר אלו האורות אע\"פ שהם רק אור חסדים, מ\"מ הם נחשבים לאוירא דכיא ולבחי' ראש. כנ\"ל, וע\"כ אין לשום קליפה אחיזה בזו\"ן גם בעת הקטנות, כי אלו האורות ד\u0003ס'\u0004 מגינים עליהם. ולכן נק' אורות אלו בשם סמך, להיותם סומכים לזו\"ן שלא יפלו מאצילות בעת היותם בקטנות בבחינת ו\"ק בלי ראש. כמבואר."],[0,"","וזה אמרו \u0003עאלת את ס'\u0004 וכו' \u0003דאית בי סמיכא לנפלין דכתיב סומך ה' לכל הנופלים\u0004 דהיינו כדאמרן, שחשבה את עצמה יותר מוכשרת מכל האותיות שקדמו לה משום שהאורות של ה\u0003ס'\u0004 יכולים להאיר אל הזו\"ן גם בעת קטנותם, בהיותם רק אור חסדים, ואין באורות החסדים האלו שום אחיזה של משהו לקלי', כי החיצונים בורחים מהאורות של ג\"ר דבינה, ולפיכך היא חשבה את מדתה ראויה ביותר למברי בה עלמא, כי יכולה להגן על בני העולם גם כשמעשיהם מקולקלים. כנ\"ל. וגם אז לא תהיה אחיזה לקלי'."],[0,"","וז\"ש, \u0003א\"ל על דא אנת צריך לאתרך ולא תזוז מניה\u0004: כלומר, כיון שהמקום שלך הוא לסמוך את הנופלים, להגן עליהם בעת קלקולם של בני העולם, הנה משום זה את צריכה להיות רק במקום הזה ולא לזוז מניה, כי אם יברא בך העולם, ותהי מדתך לשליטה מספקת תמידית, נמצא שאלו הנופלים שהם זו\"ן ישארו תמיד בקטנות ולא יתעוררו התחתונים להעלות מ\"ן ולא יתגלו כל המוחין הגדולים שצריכים להביא לגמר התיקון. אלא את צריכה להמצא באתרך בלבד, לבחי' מקום תיקון בעת שהתחתונים אינם כדאיים. אבל כשיהיו זכאים יוכלו להמשיך המוחין הגדולים מכל הקומה בסוד מאה ברכות."],[0,"","וזה אמרו \u0003אי את נפיק מאתרך מה תהא עלייהו דאינון נפילין\u0004 כי אז ישארו תמיד בבחי' נופלים, הצריכים תמיד לסמיכא דידך. וז\"ש \u0003הואיל ואינון סמיכין עלך\u0004 כלומר, כיון שהם רק סמיכין עלך, ואין להם שלימות לזו\"ן לעמידה בפני עצמם. ע\"כ אינך ראויה לברא העולם במדתך."],[1,"","כט) \u0003עאלת את נ'\u0004 וכו': נכנסה אות \u0003נ'\u0004. אמרה לפניו: רבון העולם, טוב לפניך לברוא בי את העולם, שבי כתוב, \u0003נ\u0004ורא תהלות. וכן בתהלה של צדיקים כתוב, \u0003נ\u0004אוה תהלה. אמר לה: נון, שובי למקומך כי בשבילך חזרה האות \u0003ס'\u0004 למקומה, והיי סמוכה עליה. כלומר, ה\u0003נ'\u0004 רשומה במלה \u0003נ\u0004פילה, שהסמך, שה\"ס סומך ה' לכל הנופלים, חזרה בשבילם למקומה לסמוך אותם, כנ\"ל בדבור הסמוך. מיד חזרה למקומה, ויצאה מלפניו."],[1,"","פירוש. אחר שה\u0003נ'\u0004 ראתה את האות \u0003ס'\u0004 נדחית, מטעם שאינה משמשת רק בעת קטנות, דהיינו רק לבחינת סמיכה בלבד. כנ\"ל. חשבה ה\u0003נ'\u0004 בעצמה, שהיא ודאי ראויה לבריאת העולם, להיות בה כל מעלת ה\u0003ס'\u0004 וגם נוסף עליה שהיא משמשת גם במוחין דגדלות, וע\"כ אין לה אותו החסרון שמפניו נדחתה ה\u0003ס'\u0004. וז\"ש \u0003דבי כתיב נורא תהלות\u0004. כי הגבורה דז\"א נקראת \u0003נ'\u0004, מטעם היותה כולה נמתקת במדת הרחמים של הבינה הנק' \u0003נ'\u0004 שערי בינה. ומכח זו הגבורה נקרא הז\"א \u0003נורא תהלות\u0004, כי אמא עילאה נק' תהלה, וכיון שהגבורה שלו נמשכת מבינה, ע\"כ נקרא נורא תהלות ו\u0003נ'\u0004 זו דז\"א משמשת ביסוד דגדלות דז\"א בעת הזווג עם הנוקבא שלו, שאז נק' מכחו גם הנוקבא בשם תהלה כמו אמא עילאה. ונמצא הז\"א אחיד בתהלה עילאה ותהלה תתאה כאחד."],[1,"","וזה אמרו \u0003עאלת את נ'\u0004 וכו' \u0003דבי כתיב נורא תהלות\u0004 כי בזה שאני נמצא לבחינת גבורה וקו שמאל בז\"א, הריני ממשכת החסדים היוצאים מאות \u0003ס'\u0004 שהיא תהלה עילאה ונמצא הז\"א הנק' בסבתי נורא תהלות, כנ\"ל, וע\"כ יש בי כל מעלות ה\u0003ס'\u0004, כי החסדים הנמשכים על ידה, הם מבחינת ג\"ר ומרחיקים החיצונים לגמרי מכל אחיזה שהיא, הכל כמעלת ה\u0003ס'\u0004. ועוד בי מעלה נוספת \u0003ותהלה דצדיקים נאוה תהלה\u0004 שהרי אני משמשת גם ביסוד דגדלות דז\"א, כנ\"ל באות \u0003צ'\u0004 שאומר שם ד\u0003נ'\u0004 איהי ואות \u0003י'\u0004 רכיב עלה, עש\"ה, ש\u0003נ'\u0004 זו נבחנת לתהלה דצדיקים, כי נתבאר שם, שאפילו בעת הגדלות שהזו\"ן עולים לאו\"א, משמשת גם אז \u0003נ'\u0004 זו ביסוד דז\"א בבחינת אב\"א, אלא שממשכת אוירא דכיא מאו\"א עי' שהם סוד \u0003ס'\u0004 הנ\"ל, ואז נק' ה\u0003נ'\u0004 בשם תהלה דצדיקים. כי הי' שהיא צדיק יסוד עולם רכיב עלה. ואז נקראת נאוה תהלה, להיותה ממשכת מוחין דגדלות למלכות, ונמצא שכל היופי של המלכות מקובל מן \u0003נ'\u0004 זו שביסוד דז\"א. ולכן טענה ה\u0003נ'\u0004 שבה ראוי העולם למברי, כי בהארתה נוספו גם המוחין דגדלות הנותנים עמידה וקיום לזו\"ן מעצמם, ולא רק בחינת סמיכה לבד כמו ה\u0003ס'\u0004."],[1,"אמר לה, נון תוב לאתרך דהא בגינך תבת סמך לאתרה",": אמר לה הקב\"ה: לא כמו שאת חושבת את מדתך לתיקון השלם שאין בו עוד אחיזה לקלי', אלא גם מדתך צריכה סמיכה מן ה\u0003ס'\u0004, כי ע\"כ את נמצאת עוד בבחי' אב\"א ואורות ה\u0003ס'\u0004 מגולים כלפי חוץ לשמרך מפני החיצונים. ונמצא כי גם בגינך תבת ה\u0003ס'\u0004 לאתרה לסמוך אותך, ועוד אין זה תיקון השלם. ולכן לא אברי בך עלמא. וז\"ש \u0003והוי סמיך עלה\u0004 כלומר, שגם מדתך היא רק סמיכא לבד."],[2,"","ל) \u0003עאלת את מ'\u0004 וכו', נכנסה אות \u0003מ'\u0004. אמרה לפניו: רבון העולם, טוב לפניך לברוא בי את העולם, כי בי נקראת מלך. אמר לה: כך הוא ודאי, אבל לא אברא בך את העולם, משום שהעולם צריך למלך. שובי למקומך, את, וה\u0003ל'\u0004, וה\u0003כ'\u0004, כי לא יפה לעולם לעמוד בלא מלך."],[2,"","פירוש. ה\u0003מ'\u0004 היא חסד דז\"א המקבל מהבחינה שכנגדו מחסד דבינה שה\"ס יומם יצוה ה' חסדו (תהלים מ\"ב), דהיינו יומא דאזיל עם כלהו יומין. ובעת השגת המוחין אל הז\"א, נעשו החג\"ת שלו לבחינת חב\"ד, ונמצא החסד דז\"א עולה ונעשה לחכמה, ואז נגלה אור פני מלך חיים מן הז\"א."],[2,"","וזו היא טענת ה\u0003מ'\u0004 למברי בה עלמא, מבחינה זו \u0003דבי אתקריאת מלך\u0004 וכיון שיתגלה אור פני מלך בעולם, ודאי לא תהיה עוד אחיזה לחיצונים, וגמר התיקון יהיה מובטח בעולם."],[2,"לא אברי בך עלמא בגין דעלמא אצטריך למלך",": כלומר, אי אפשר לגלות אור זה בעולם משום שהעולם צריך שיתלבש האור הגדול הזה רק בג' האותיות \u0003מל\"ך\u0004. וז\"ש \u0003תוב לאתרך אנת ול' וך', דהא לא יאות לעלמא למיקם בלא מלך\u0004, כלומר, שובי למקומך והתחברי עם האותיות \u0003ל'\u0004 ו\u0003ך'\u0004, ואז תהיה מציאות שיתגלה האור הגדול הזה בעולם. והוא מטעם \u0003דהא לא יאות לעלמא למיקם בלא מלך\u0004 כלומר, שאין העולם יכול לעמוד ולהתקיים בלא התלבשות בסדר ג' האותיות \u0003מל\"ך\u0004."],[2,"","וביאור הדברים הוא, כי ה\u0003מ'\u0004 דמלך ה\"ס החסד הגדול, בסוד יומם יצוה ה' חסדו (תהלים מ\"ב) שהוא יומא דאזיל עם כלהו יומי, שז\"ס \u0003מ'\u0004 פתוחה בהרוחה גדולה. וה\u0003ל'\u0004 דמלך ה\"ס מגדל הפורח באויר, שהיא בינה שנעשית חכמה בראש א\"א ומתפשטת לז\"א. וה\u0003ך'\u0004 דמל\u0003ך\u0004 ה\"ס המלכות, שהיא הנוקבא דז\"א, כי אין מלך בלא מלכות. ולא עוד, אלא שכל הגדלות של אלו המוחין הגבוהים אינם מתגלים זולת ע\"י המלכות \u0003וברשותא דידה\u0004."],[2,"","ובעת הזאת נבחנת המלכות שהיא מאירה לו אל הז\"א בג' מקומות: א) שהיא נעשתה לכסא לו, בסוד \u0003המלך\u0004 יושב על \u0003כסא\u0004 רם ונשא: כי מדת זו ה\"ס ישת חושך סתרו, וכסא הוא לשון כסוי והעלם, וע\"כ נקראת כ' כפופה. ב) שהיא נעשתה לו ללבוש, כי אין המוחין הגדולים האלו מתראים רק על ישראל בלבד, וע\"כ המלכות נעשית לו לבחינת לבושא דקדרותא, שבעת גילוי מלכותו הוא מתפשט מלבושא דקדרותא זה, וזריק אותו על האומות עובדי כוכבים ומזלות, ואור פניו מתפשט ומתגלה על ישראל. ולעת ההיא אמרו חז\"ל עתיד הקב\"ה לעשות מחול לצדיקים וכל אחד ואחד מראה באצבעו ואומר הנה אלהינו זה וכו' (סוף תענית). ובחינת ההתפשטות הזו מלבושא דקדרותא ה\"ס \u0003ך'\u0004 פשוטא ואריכא. ג) שהמלכות נעשית לו עטרה על רישיה, בסו\"ה צאנה וראנה בנות ציון במלך שלמה בעטרה שעטרה לו אמו ביום חתונתו וביום שמחת לבו (שיר ג'). וז\"ס שה\u0003כ'\u0004 היא כתר. והנה נתבארו ג' האותיות \u0003מ' ל' ך'\u0004. והבן היטב."],[3,"","לא) \u0003בההיא שעתא נחתא\u0004 וכו': באותה שעה ירדה מלפניו אות \u0003כ'\u0004 מעל \u0003כ\u0004סא כבודו. נזדעזעה ואמרה לפניו: רבון העולם, טוב לפניך לברוא בי את העולם, כי כבודך אני. כשירדה אות \u0003כ'\u0004 מעל כסא כבודו, נזדעזעו מאתים אלף עולמות ונזדעזע הכסא, וכל העולמות נזדעזעו לנפול. אמר לה הקב\"ה \u0003כ\"ף כ\"ף\u0004, מה את עושה כאן, לא אברא בך את העולם, שובי למקומך, כי בך \u0003כ\u0004ליה, ובך נשמעה \u0003כ\u0004לה ונחרצה, שובי לכסאך והיי שם. באותה שעה יצאה מלפניו וחזרה למקומה."],[3,"","פי', \u0003בההיא שעתא\u0004 שהיתה המ' נושאת ונותנת עם קב\"ה למברי בה עלמא מבחינת גילוי אור פני מלך בעולם כנ\"ל, גרם זה לירידת ה\u0003כ'\u0004 מעל כסא הכבוד, שהיא עולם הבריאה \u0003ואזדעזעת ואמרה\u0004 וכו' \u0003דאנא כבודך\u0004. ואז \u0003אזדעזעו ר' אלף עלמין\u0004 הנמשכים מחו\"ב דבריאה. שהיא כח\"ב דבריאה. \u0003ואזדעזע כורסייא, וכלהו עלמין\u0004 שמשם ולמטה \u0003אזדעזעו למנפל\u0004."],[3,"","ביאור הדברים. כי אלו הטענות של האותיות לפני הקב\"ה למברי בהו עלמא, הן כמו עלית מ\"ן לקבל מקב\"ה מ\"ד לאותה הקומה השייכת למדתה של האות, ותהיה הנהגת הזו\"ן שהם המשפיעים של העולם, בבחינת קומת מ\"ד המושפעת על אותה האות. וכן ענין תשובתו של הקב\"ה לכל אות ואות מכ\"ב האותיות דזו\"ן, הוא בחינת הורדת מ\"ד ויציאת קומת האור לשעתו, בשיעור המ\"ן שהעלתה כל אות ואות וכשקומת האור התחילה לגלות הנהגתה בעולם, הנה אז נשמעה תשובתו של הקב\"ה לאותה האות, כי נגלתה אי יכלתה להנהיג העולם מחמת האחיזה של הקליפה במדתה, בסוד, זה לעומת זה עשה אלהים, ובזה נסתלקה לה כל אות ואות והלכה לה למקומה. שז\"ס השעשועים של הקב\"ה עם כל אות ואות של כ\"ב האותיות, מתוך נתינת מקום לכל אחת ואחת לגלות שליטתה כרצונו, עד שיתבררו מאליהן מתוך חפצן עצמן, מי מהן זכאית להנהגת העולם על ידה. וז\"ש לעיל \u0003ותרין אלפין שנין עד דלא ברא עלמא הוה מסתכל קב\"ה ואשתעשע בהו\u0004."],[3,"","ועם זה תבין שבעת שהתחילה ה\u0003מ'\u0004 לגלות האור הגדול שלה בעולם, גרמה ל\u0003כ'\u0004 לירד מעל כסא הכבוד. כי סוד הכסא הוא בב' בחינות: א) שהוא מכסה על המלך, בסוד ישת חושך סתרו (תהלים י\"ח), ומשום זה נק' כסא מלשון כיסוי. ב) היא מגלה כבוד המלכות בעולמות, בסו\"ה ועל הכסא דמות כמראה אדם (יחזקאל א') והוא על ידי צירוף ג' האותיות \u0003מל\"ך\u0004 שאז אותה המלכות שנעשתה כסא המלך, ומכסה עליו, בסוד ישת חושך סתרו, עולה למעלה ונעשית \u0003ך'\u0004 פשוטה שה\"ס לבוש אל המלך עצמו, שהמלך עצמו, שהוא ז\"א מתגלה על ידה כנ\"ל, גם נעשתה עטרה על ראש המלך כנ\"ל."],[3,"","אבל בעת שה\u0003מ'\u0004 התחילה לגלות אור פני מלך בעולמות בלא לבוש \u0003ך'\u0004, הנה אז ירדה ג\"כ ה\u0003כ'\u0004 מעל כסא הכבוד, כלומר, שהפסיקה פעולתה לכסות על המלך, וגם היא אמרה \u0003ניחא קמך למברי בי עלמא דאנא כבודך\u0004 דהיינו שהנהגת גילוי כבוד המלך תשלוט בה בלבד, בלי שום כיסוי, דהיינו כרצונה של ה\u0003מ'\u0004. וז\"ש \u0003בההיא שעתא\u0004 ואינו אומר שה\u0003כ'\u0004 עאלת ואמרה קמיה ניחא וכו', כמו שאיתא בכל האותיות, והוא משום שהיא לא נתעוררה מעצמה, אלא עם שליטתה של ה\u0003מ'\u0004, כי שליטת ה\u0003מ'\u0004 לשעתה, הורידה גם את ה\u0003כ'\u0004 מעל כסא הכבוד שבעולם הבריאה כמבואר."],[3,"","וז\"ש, \u0003אזדעזעת ואמרה ניחא\u0004 וכו' כי בעת ירידתה מעל הכסא נזדעזעה היא ו\u0003ר' אלף עלמין\u0004 שהם העולמות הנמשכים מחו\"ב שבבריאה וכן \u0003וכלהו עלמין אזדעזעו למנפל\u0004. והענין הוא, כי כל הקשר בין עליון לתחתון, מראש המדרגות עד סופן, הוא ע\"י מלכות דעליון שנעשתה כתר לתחתון וסוד הכ' ה\"ס התלבשות המלכות דעליון בתחתון. וג' בחי' יש בכסא. א) נק' \u0003שש מעלות לכסא\u0004, שהן וה\"ק של התחתון הנקראים חג\"ת נה\"י. ב) הן \u0003ד' רגלי הכסא\u0004, והן המוחין כחב\"ד של התחתון. ג) היא המלכות של העליון היורדת מהעליון לתחתון ומתלבשת בו, שבדרכה של המלכות באים כל האורות מהעליון ומאירים בתחתון."],[3,"","ולפיכך, בעת ירידת ה\u0003כ'\u0004 מכסא הכבוד נפסק הקשר של אצילות עם כסא הכבוד שהוא עולם הבריאה. כי הכ' היא מלכות דאצילות המלובשת בכחב\"ד דבריאה, ומשפעת לעולם הבריאה הנק' כסא הכבוד, את כל אורותיה וכיון שה\u0003כ'\u0004 ירדה משם, נתבטל הקשר עם האצילות, ונזדעזעה ה\u0003כ'\u0004, כי נפסק כחה מלהשפיע לבריאה, ונזדעזעו \u0003מאתן אלף עלמין\u0004, שהם חו\"ב, הכוללים את כחב\"ד דבריאה. וכן כל העולמות \u0003אזדעזעו למנפל\u0004. כי אבדה מהם כל חיותם והשפעתם מעולם האצילות."],[3,"","וכן עד\"ז יש לפרש ביחס של הקב\"ה שהוא בינה עם הזו\"ן דאצילות, כי המלכות של הבינה המתלבשת בז\"א היא ה\u0003כ'\u0004 ונמצאה ה\u0003כ'\u0004 הזאת שהיא הכסא של הקב\"ה השורה על הז\"א, כי הקב\"ה הוא בינה, שהוא העליון דז\"א, והז\"א נעשה כסא לבינה. ונמצא שנפסק בירידת הקשר של הבינה עם הז\"א, כי ה\u0003כ'\u0004 ה\"ס מלכות הבינה המתלבשת בז\"א ומשפעת לו כל אורותיה. ולפיכך נזדעזעה היא עצמה, דהיינו שנפסקה יכלתה להשפיע אל הז\"א, וכן \u0003אזדעזעו מאתן אלף עלמין\u0004, שהם המוחין של הז\"א הנק' חו\"ב, וכן נק' כחב\"ד, שהם ד' רגלי הכסא כנ\"ל, כי כל השפע שלהם נפסק וכן \u0003כלהו עלמין אזדעזעו למנפל\u0004, שהם וה\"ק דז\"א, חג\"ת נה\"י, שהם כוללים כל העולמות שמתחתיו, כי נאבד מהם כל שפע הבינה, וכיון שנתרוקנו מאורות אצילות נזדעזעו ליפול לבי\"ע דפירודא ולהחרב."],[3,"","וז\"ש, \u0003אמר לה קב\"ה\u0004 וכו' \u0003כלה ונחרצה אשתמע, תוב לכרסייך\u0004: היינו כנ\"ל, שמסבת ירידת ה\u0003כ'\u0004 מעל כסא הכבוד \u0003אזדעזעו\u0004 גה\"ר דז\"א וכלהו עלמין אזדעזעו ליפול ולהחרב דהיינו שנשמע \u0003כלה ונחרצה\u0004, שפירושו כליון חרוץ לבלי תקומה עוד. ולכן את מוכרחה לשוב לבחינת הכסא כנ\"ל."],[3,"","וז\"ש, \u0003בההיא שעתא נפקת מקמיה\u0004: מדגיש שוב לומר \u0003בההיא שעתא\u0004 להורות כי ענין חזרתה למקומה לבחי' כסא, באה יחד עם התשובה של הקב\"ה ל\u0003מ', דלא יאות לעלמא למיקם בלא מלך\u0004, כלומר, שענין הזעזועים שנתגלו בכ' בעת ירידתה מעל כסא הכבוד, דכלהו עלמא אזדעזעו ליפול, וענין התשובה של הקב\"ה אל ה\u0003מ' דלא יאות לעלמא למיקם בלא מלך\u0004, הנה ב' אלו באו בבת אחת, והבן."],[4,"","לב) \u0003עאלת את י'\u0004 וכו': נכנסה אות \u0003י'\u0004. אמרה לפניו: רבון העולם, טוב לפניך לברוא בי את העולם, כי אני התחלת השם הקדוש, ויפה לך לברוא בי את העולם. אמר לה: די לך, שאת חקוקה בי, ואת רשומה בי, וכל חפצי בך, עלי, לא יפה לך להיות נעקרת משמי."],[4,"","פירוש. כיון שה\u0003י'\u0004 היא אות ראשונה של שם הוי\"ה, דהיינו תחילת הגילוי ובחי' עליונה של האור הזה הקדוש, לכן טענה, שיברא העולם במדתה ויהיה גמר התיקון בטוח."],[4,"","וז\"ש, \u0003אמר לה, די לך דאנת חקיק בי ואנת רשים בי\u0004 וכו': כבר ידעת, שענין השאלה והתשובה של האותיות, הוא ענין השעשועים דקב\"ה עם האותיות, שהשאלה היא בחי' מ\"ן, והתשובה היא המ\"ד של האור העליון. ועם זה תבין שהמלה \u0003די לך\u0004 ה\"ס תיקון גבול, בסוד שאמר לה \u0003די לך\u0004 ואל תתפשטי יותר. כמ\"ש לעיל בשם קדוש \u0003שד\"י\u0004. כי אחר שה\u0003י'\u0004 התחילה להתפשט באור הגדול והקדוש הזה, הפסיק אותה הקב\"ה, ולא נתן לה להתפשט עד ה\u0003ת'\u0004 אלא רק בסוד ה\u0003ש'\u0004 (כנ\"ל אות כ\"ד ד\"ה ולפיכך) כי אמר לה, די לך ואל תתפשטי יותר. וז\"ש, \u0003סליק, לית אנת יאות לאתעקרא מן שמי\u0004, כי אם תתפשטי יותר לא תוכלי להיות עוד קבועה בשם הוי\"ה."],[4,"","וביאור הדברים, כי אמרו חז\"ל לא כשאני נכתב אני נקרא, כי נכתב אני ב\u0003הוי\"ה\u0004 ונקרא ב\u0003אדנ\"י\u0004 (פסחים נ.) פירוש, כי שם הוי\"ה אין לו שינוי לעולם. בסוד הכתוב אני \u0003הוי\"ה\u0004 לא שניתי (מלאכי ג'). וכיון שבימי עולם נוהג קלקול ותיקון, הרי יש שם שינוי, לפיכך קודם גמר התיקון הוא נקרא באדני, שבשם הזה יתכן שינוי, ולא בשם הוי\"ה, שבו אין שינוי ח\"ו. אלא לעתיד אחר גמר התיקון, יהיה נקרא כמו שהוא נכתב, בסו\"ה ושם העיר מיום הוי\"ה שמה. (בסיום יחזקאל) וז\"ש לה: \u0003סליק, לית אנת יאות לאתעקרא מן שמי\u0004 כי אם יארע בך איזה קלקול, את נמצאת נעקרת משמי, כי בשמי הוי\"ה אינו נוהג קלקול ותיקון כמבואר. ולפיכך אינך ראויה למברי בך עלמא."],[4,"","ואמרו, \u0003דאנת חקיק בי ואנת רשים בי וכל רעותא דילי בך\u0004, מורה על ג' מדרגות שב\u0003י'\u0004 דשם הוי\"ה: חקיק בחכמה דז\"א רשים בחכמה דאו\"א עילאין, \u0003וכל רעותא דילי בך\u0004, הוא בחכמה דא\"א הנק' חכמה סתימאה."],[5,"","לג) \u0003עאלת את ט'\u0004 וגו': נכנסה אות \u0003ט'\u0004. אמרה לפניו: רבון העולם, טוב לפניך לברוא בי את העולם, כי בי אתה נקרא טוב וישר. אמר לה: לא אברא בך את העולם, כי טובך סתום בתוכך, וגנוז בתוכך. ז\"ש, מה רב טובך אשר צפנת ליראך. וכיון שהטוב גנוז בתוכך הרי אין בו חלק לעולם הזה שאני רוצה לברוא, אלא בעולם הבא. ועוד, משום שטובך גנוז בתוכך, יטבעו שערי ההיכל. ז\"ש טבעו בארץ שעריה. ועוד, כי ה\u0003ח'\u0004 כנגדך, וכשתתחברנה יחד, תהיינה \u0003ח\"ט\u0004. דהיינו חטא. וע\"כ לא נרשמו אותיות אלו בשבטים הקדושים. מיד יצאה מלפניו."],[5,"","ביאור הדברים, ה\u0003ט'\u0004 היא יסוד דז\"א מבחינת פנימיותו. כי ה\u0003צ'\u0004 היא תשיעית לבחי' אותיות הז\"א, שהוא המזדווג עם הנוקבא בסוד \u0003צדיק\u0004. כנ\"ל. אבל הט' היא תשיעית לאותיות בינה דז\"א. והיא פנימיות יסוד הז\"א. והוא נק' \u0003טוב\u0004, בסו\"ה אמרו צדיק כי \u0003טוב\u0004. (ישעי' ג') ובהיותו בחינת נשמת היסוד, שאין בו שום אחיזה לקליפות, ע\"כ טענה ה\u0003ט'\u0004 שיברא בה העולם."],[5,"","וז\"ש, \u0003דהא טובך סתים בגווך וצפון בגווך\u0004 וכו': ה\"ס מ\"ש רז\"ל (חגיגה יב.) האור שברא הקב\"ה ביום ראשון אדם צופה ומביט בו מסוף העולם ועד סופו כיון שנסתכל הקב\"ה בדור המבול ובדור הפלגה וראה שמעשיהם מקולקלים עמד וגנזו וכו' לצדיקים לעתיד לבוא, שנאמר (בראשית א') וירא אלהים את האור כי טוב, ואין טוב אלא צדיק שנאמר אמרו צדיק כי טוב. פירוש, כיון שראה הקב\"ה שהרשעים יקלקלו מעשיהם ויתנו באור הזה אחיזה לקליפות, לכן גנזו בצדיק וצדק העליונים דאו\"א, ומצדיק וצדק דאו\"א נמשך האור הזה בגניזו לפנימיות היסוד דז\"א שהוא ה\u0003ט'\u0004. ובסוד התיקון הזה השיב לה הקב\"ה ל\u0003ט' דהא טובך סתים בגווך וצפון בגווך\u0004 וכו' \u0003הואיל וגניז בגווך לית ביה חולקא לעלמא דא, דאנא בעי למברי, אלא בעלמא דאתי\u0004, כלומר, כיון שאני צריך להסתיר אותך מהרשעים, ואינך ראויה אלא לצדיקים הראויים לקבל מעלמא דאתי, הרי שאין לך חלק לתקן את העולם הזה שה\"ס זו\"ן, משום שיש בך אחיזה לחיצונים."],[5,"","וז\"ש, \u0003ותו, דעל דטובך גניז בגווך יטבעון תרעי דהיכלא\u0004: כי מתוך שאין האור הזה מאיר רק בפנימיות היסוד בגניזו, כן לא תוכל הנוקבא לקבל מן האור הזה בשעריה רק דרך גניזו בפנימיותה, שמחמת זה נטבעים שערי הנוקבא לתוך פנימיות היסוד שלה, שעי\"ז נשמרים ממגע החיצונים, ותהיה בטוחה שלא ישלטו החיצונים בשעריה, שבזמן החורבן לא שלטו האויבים בשערי ההיכל, אלא שנטבעו בארץ, כדרשת חז\"ל (סוטה ט. ועי\"ש ברש\"י). ומתוך שאנת צריכה לשמירה כל כך, אינך ראויה למברי בך עלמא."],[5,"","וז\"ש, \u0003ותו, דח' לקבלך, וכד תתחברון כחדא הא ח\"ט\u0004: כי \u0003ח'\u0004 היא הוד, דהיינו המלכות הכלולה בז\"א, וה\"ס הצנור השמאלי שביסוד דז\"א. כי ב' צנורות הם ביסוד דז\"א, א) להולדת נשמות, והוא הימני. ב) לדחית פסולת לחיצונים, והוא השמאלי, הנק' \u0003ח'\u0004, והענין הוא, כי הוא מבחינת ה\u0003ק'\u0004 הנכללת ביסוד (כנ\"ל אות כ\"ד ד\"ה השיב) שממנה יוצא הנהירו דקיק לחיצונים, שמתוך זה קונים החיצונים כח להדמות לצדם דקדושה, כקוף בפני אדם, בסוד, זה לעומת זה עשה אלהים. כי אלו ב' הצנורות קרובים זה לזה, ואין ביניהם אלא כקליפת השום ולכן יש כח לצנור השמאלי, שיתגבר על הצנור הימני, ואז נעשה \u0003ח\"ט\u0004. וז\"ס ש\u0003ח\"ט\u0004 בגי' \u0003טו\"ב,\u0004 דהיינו זה לעומת זה."],[5,"","כי בהתגבר הימין שהוא \u0003ט'\u0004, אז בגי' \u0003טו\"ב\u0004, בסו\"ה אמרו צדיק כי טוב. (ישעיה ג'). ואם ח\"ו מתגבר הצנור השמאלי שהוא \u0003ח'\u0004 על ה\u0003ט'\u0004 אז בגי' \u0003ח\"ט\u0004."],[5,"","וזה אמרו \u0003ותו דח' לקבלך\u0004 כלומר, כי יש כח לצנור השמאלי שהוא \u0003ח'\u0004 להתגבר עלך ואז \u0003וכד תתחברון כחדא הא ח\"ט\u0004, דהיינו שתוכלנה הקליפות להוציא השפע דקדושה אליהן, שמשם יש שליטה לכל החטאים, וזה אמרו \u0003ועל דא, אתוון אלין, לא רשימין בשבטין קדישין\u0004. כי זה הטעם שאין בשמות של השבטים האותיות, \u0003ח' ט'\u0004, להורות שהם גבוהים ונפרשים מבחינת ה\u0003ח'\u0004 הזו, שהיא שורש כח הלעומת, שז\"ס, שיעקב מטתו שלימה, ולא יצאה ממנו שום פסולת לחיצונים, כמו מאברהם ויצחק, כדברי חז\"ל (פסחים נו.)."],[6,"","לד) \u0003עאלת את ז'\u0004 וכו': נכנסה אות \u0003ז'\u0004. אמרה לו: רבון העולם, טוב לפניך לברוא בי את העולם, כי בי ישמרו בניך שבת, שכתוב \u0003ז\u0004כור את יום השבת לקדשו. אמר לה: לא אברא בך את העולם, כי יש בך מלחמה, דהיינו חרב שנונה ורומח שעושים בהם מלחמה, שהם נקראים כלי \u0003זיין\u0004. ואת כעין ה\u0003נ'\u0004, שלא נברא בה העולם, משום שיש בה \u0003נ\u0004פילה, (כנ\"ל אות כ\"ט) מיד יצאה מלפניו."],[6,"ביאור הדברים",", כי סוד ה\u0003ז'\u0004 היא \u0003י'\u0004 על \u0003ו'\u0004, שזה מורה על גדלות המוחין של הנוקבא בסו\"ה, אשת חיל עטרת בעלה. (משלי י\"ב), כי היא נכללת בעולם הזכר, והוא \u0003ו'\u0004. ואז נעשתה עטרה על ראשו, שה\"ס ה\u0003י'\u0004 שעל ה\u0003ו'\u0004 ובעלה מתעטר בה. וז\"ס, \u0003זכור את יום השבת לקדשו\u0004 שעי\"ז שמעלים את \u0003יום השבת\u0004, שהוא הנוקבא, למעלה לעטרה על הז\"א, שהיא נכללת אז בסוד \u0003זכור\u0004, נקראת הנוקבא \u0003קודש\u0004. וטענה ה\u0003ז'\u0004: כיון שאור זה הוא גדול וקדוש בסוד המנוחה, ושם השבתת כל הקליפות, ע\"כ אני ראויה שיברא העולם במדתי."],[6,"","וז\"ש, \u0003אמר לה לא אברי\u0004 וכו': פי', כי ה\u0003ז'\u0004 היא נצח דז\"א, כי \u0003ז' ח' ט'\u0004 הן נה\"י דז\"א. וכשהנוקבא נכללת בז' שהיא נצח, משגת כח לעלות עם הז\"א לאו\"א עילאין, ושם נעשית עטרה לראשו, ובעלה מתעטר בסוד \u0003השבת\u0004, כנ\"ל."],[6,"","אמנם כיון שכל התיקון הזה, הוא רק ע\"י התכללות בזכר ועליה לאו\"א, ולא במקומה עצמה למטה, במקום עמידתה תמיד עם הז\"א, ע\"כ אין תיקונה שלם בשתא אלפי שני, כי בימות החול כשחוזרת למקומה, נבחנת אז התכללותה ב\u0003ז'\u0004, לבחינת כלי זיין, עד שממנה נחשבות כל המלחמות עם הס\"א, בסוד ימות החול המכינים לשבת, ובסוד \u0003מאן דנצח לקרבא יהבין ליה ברתא דמלכא\u0004. שבימות החול צריך כל אחד ואחד לנצח בקרבא עם הס\"א והחיצונים, ואז הוא זוכה \u0003לבת מלך\u0004, שהיא \u0003השבת\u0004. הרי, שאין עוד הארת השבת שבשתא אלפי שני מספקת להשבתת הקליפות בשלמות, כי ע\"כ חוזרים וסובבים עליה ימות החול, עד לגמר התיקון לע\"ל, שאז יהיה יום שכולו שבת ומנוחה לחיי העולמים."],[6,"","וזה אמרו \u0003לא אברי בך עלמא דאנת אית בך קרבא, וחרבא דשננא, ורומחא דקרבא\u0004 דהיינו כמבואר, כי עדיין אין הארתך שלמה, להיותך למטה במקומך בלתי שלמה וצריכים לזכות בך רק ע\"י מלחמות עם הס\"א. \u0003וקרבא\u0004, מורה, על מלחמות התחתונים עם הס\"א. \u0003וחרבא דשננא\u0004, מורה, על מדת המלכות בעת התכללותה בנצח בימות החול, שאז היא חרב שנונה לעומת הקליפות הרוצות להאחז בה. \u0003ורומחא דקרבא\u0004, מורה, על הז\"א עצמו הנק' רומח, שהוא בציורא דאות \u0003ו'\u0004, שהוא כעין רומח לדקור במדתו את הס\"א. וזה אמרו, \u0003כגוונא דנו\"ן\u0004, הוא כי גבורות הזכר הן מבחי' בינה שהיא \u0003נ'\u0004. כנ\"ל."],[7,"","לה) \u0003עאלת אות ו'\u0004 וכו': נכנסה אות \u0003ו'\u0004. אמרה לפניו: רבון העולם, טוב לפניך לברוא בי את העולם, שאני אות משמך הויה. אמר לה: \u0003וא\"ו\u0004, את ו\u0003ה'\u0004 די לכן, שאתן אותיות משמי, הויה, שאתן בסוד שמי, וחקוקות ומפותחות בשמי, לא אברא בכן את העולם."],[7,"","פירוש, כי אע\"פ דכבר בקשה זאת ה\u0003י'\u0004 לעיל ונדחית, אעפ\"כ חשבה ה\u0003ו'\u0004 שה\u0003י'\u0004 נדחית מטעם קומתה הגבוהה יותר מדאי, וטענה ה\u0003ו'\u0004 שיברא העולם במדתה, דהיינו בקומת \u0003ו\"ה\u0004 שבשם שהיא מוחין דאמא."],[7,"אמר לה: ואו, אנת וה', די לכון דאתון אתוון דשמי","וכו': השיב להן אותה התשובה שהשיב ל\u0003י'\u0004 לעיל, ע\"ש, כי הגביל גם אותה, בסוד שאמר לה \u0003די\u0004 ואל תתפשטו רק לבחי' ה\u0003ש'\u0004, כדי שלא תאחזנה בכן הקליפות וע\"כ אינכן ראויות למברי בכו עלמא. כי גם אתן צריכות שמירה מהקליפות."],[8,"","לו) \u0003עאלת את ד'\u0004 וכו': נכנסו אות \u0003ד'\u0004 ואות \u0003ג'\u0004. אמרו אף הן כך. אמר גם להן, די לכן להיות זו עם זו, שהרי לא יחדלו אביונים מן הארץ, וצריכים ל\u0003ג\u0004מול עמהם חסד. ה\u0003ד'\u0004 היא עניה, כי נקראת דלת מלשון \u0003ד\u0004לות. ה\u0003ג',\u0004 גומלת לה חסד, לדלת. וע\"כ אל תתפרדנה זו מזו. ודי לכן, לזון זו את זו."],[8,"","ביאור הדברים, בחי' ה\u0003ד'\u0004 כבר נתבארה (לעיל אות כ\"ד ד\"ה וזה ע\"ש). ונתבאר שם שאע\"פ שה\u0003ד'\u0004 מקבלת שפע מה\u0003ג'\u0004, והזוית שלה שעל גגה בולטת בחסדים, מ\"מ יש כח לס\"א להאחז בה להפרידה ולזייף בה אות \u0003רי\"ש\u0004, ושוב נעשתה \u0003ריש ומסכן\u0004, ע\"ש. וז\"ש, \u0003די לכון למהוי דא עם דא\u0004 כלומר, אתן צריכות לשמירה יתירה שתוכלנה \u0003למהוי דא עם דא\u0004 וה\u0003ג'\u0004 תשפיע ל\u0003ד', דהא מסכנין לא יתבטלון מן עלמא\u0004 כי יש כח בלעומת להפריד ביניכן ולהשיב המלכות, הנק' עולם, לבחינת ריש ומסכנותא \u0003וצריכין לגמול עמהון טיבו\u0004, שאז צריכים לאתערותא דלתתא, ליתן צדקה למסכני, כדי להחזיר את הד' לקבל מן הג'. ולפיכך, \u0003ודי לכון למיזן דא לדא\u0004, כי די לכן, אם תוכלנה להחזיק לעצמכן בזווגא למיזן זו לזו, ולא תשלוטנה בכן הקליפות וע\"כ לא אברי בכו עלמא."],[9,"","לז) \u0003עאלת את ב'\u0004 וכו': נכנסה אות \u0003ב'\u0004. אמרה לו: רבון העולם, טוב לפניך לברוא בי את העולם, כי בי מ\u0003ב\u0004רכים אותך למעלה ולמטה. כי ב' היא \u0003ב\u0004רכה. אמר לה הקב\"ה: ודאי בך אברא את העולם, ואת תהי ההתחלה, לברוא בך את העולם."],[9,"","פירוש. האות \u0003ב'\u0004 ה\"ס חכמה, והיינו חסד דחכמה בסוד נקודה בהיכליה, כי אור החסדים הם היכל לאור החכמה, והוא ברכה, בסו\"ה והריקותי לכם ברכה וגו' (מלאכי ג'). ואור זה אינו מתמעט כלום בהיותו עובר ומשתלשל דרך המדרגות, וכמו שהוא בראש המדרגות המקבל מא\"ס ב\"ה, כן הוא בכל גדלו ושבחו בעולם אצילות, וכן עד סוף עשיה, ואינו מתעבה כלום מחמת כל אלו המסכים שהוא עובר דרכם. וזהו שטענה אות \u0003ב': ניחא קמך, למברי בי עלמא, דבי מברכאן לך לעילא ותתא\u0004. כלומר, כי אור הברכה שלי הוא בשוה לעילא ולתתא בלי שום הפרש, ושום מסך ועביות לא יוכל לפגום משהו בהארותי, ולכן מדתי מוכשרת לבריאת העולם, כי לא תהיה שום אחיזה בי לקליפות. כי אין הקליפות נאחזות רק במקום שיש איזה חסרון, וכיון שאין בי שום חסרון, לא תהיה בי שום אחיזה."],[9,"א\"ל קב\"ה: הא ודאי בך אברי עלמא, ואת תהא שירותא למברי עלמא",": כי הסכים עמה שמדתה ראויה לבריאת העולם, וה\"ס הכתוב, כי אמרתי עולם חסד יבנה (תהלים פ\"ט). ומלת \u0003יבנה\u0004 פירושו בנין והבנה, כי קבע אותה לבירור מספיק, להבדיל בין הדבקים בקדושה לבין הסרים מאחרי ה' להדבק באל אחר. בסו\"ה ובחנוני נא בזאת אמר ה' צבאות, אם לא אפתח לכם את ארובות השמים והריקותי לכם ברכה עד בלי די (מלאכי ג'), אבל בעוד שהם נוטים לאל אחר, הם מחוסרי ברכה, כי אל אחר אסתרס ולא עביד פירי. וזה שמסיים שם הנביא, ושבתם וראיתם בין צדיק לרשע, בין עובד אלהים ללא עבדו, הרי שהעולם חסד יבנה."],[9,"","וז\"ש, \u0003שירותא למברי עלמא\u0004: שירותא פירושו, התחלה, ומורה בזה, כי לא קבע את אור הברכה לשלימות העולם, אלא להתחלה טובה ומספקת להביא את העולם לכלל השלימות. והטעם הוא כי אור זה דחסדים הוא בחינת ו\"ק בחסר ראש, ועדיין אינו מספיק להולדת נשמות לפריה ורביה, כי אין הולדה לשום פרצוף מטרם שישיג ג\"ר הנקראים ראש. וע\"כ הוא עוד מחוסר השלמה. וענין הקביעות שקבע את ה\u0003ב'\u0004 והברכה \u0003למברי\u0004 בה \u0003עלמא\u0004 היינו לבחינת \u0003עיקר\u0004 כל פרצוף, כלומר, שזה לא יחסר משום פרצוף דקדושה, וענין ההשלמה של גה\"ר הנצרך למוחין דהולדה, כבר אינו עיקר בפרצוף, אלא נבחן לבחינת תוספות בלבד. דהיינו התלוי במעשיהם הטובים של התחתונים אבל בחינת ו\"ק לא תחסר לעולם."],[10,"","לח) \u0003קיימא את א' וכו'\u0004: עמדה אות \u0003א'\u0004 ולא נכנסה. אמר לה הקב\"ה: \u0003אלף אלף\u0004, למה אין את נכנסת לפני כשאר כל האותיות. אמרה לפניו: רבון העולם, כי ראיתי שכל האותיות יצאו מלפניך בלי תועלת, מה אעשה שם אני. ועוד, כי כבר נתת לאות \u0003ב'\u0004 את המתנה הגדולה הזו, ואין ראוי למלך העליון, שיעביר את המתנה שנתן לעבדו, ולתת אותה לאחר. אמר לה הקב\"ה, \u0003אלף אלף\u0004, אע\"פ שבאות \u0003ב'\u0004, נברא העולם, את תהי ראש לכל האותיות, אין בי יחוד אלא בך, בך יתחילו כל החשבונות, וכל מעשי בני העולם. וכל היחוד אינו אלא באות \u0003א'\u0004."],[10,"","פירוש, כי כבר ידעת שכל אלו השאלות של האותיות, הן העלאת מ\"ן של האותיות, והתשובות הן סוד ירידת המ\"ד, כנ\"ל. והנה השלימות הגדולה הזו שבאות \u0003א'\u0004, לא תתכן בה אתעדל\"ת אלא רק בכח אתעדל\"ע לבד. כמ\"ש בזוהר (ויקרא אות פ\"א), על הכתוב נפלה לא תוסיף קום בתולת ישראל. דלא תוסיף קום מעצמה אלא קב\"ה יוקים לה. ע\"ש. ולפיכך הן בהתחלת האצילות של המוחין דג\"ר, דהיינו בעודם בסוד שעשועים בהיכל או\"א, שבזה עוסק הזהר בדרוש שלפנינו, והן בגמר התיקון, לא תתעורר האות \u0003א'\u0004 בהעלאת מ\"ן מתתא לעילא, כדרך יציאת המוחין דג\"ר במשך שתא אלפי שני, אלא הכל יהיה בסוד אתערותא דלעילא בלבד. שז\"ס \u0003לא תוסיף קום מעצמה אלא קב\"ה יוקים לה\u0004. וזהו שאומר כאן, \u0003קיימא אות א' לא עאלת אמר לה קב\"ה, א' א' למה לית אנת עאלת\u0004. מורה, כי ה\u0003א'\u0004 לא נתעוררה כלל בהעלאת מ\"ן כמו שאר האותיות עד \u0003דאמר לה קב\"ה\u0004, שז\"ס, \u0003קב\"ה יוקים לה\u0004. ע\"ש היטב בהזוהר. ואמרו, \u0003א', א'\u0004, פעמים, הוא להורות על ב\"פ הנ\"ל, הראשונה היא בעת שהיו האותיות בסוד השעשועים, והשניה רומזת על גמר התיקון, כי אז ג\"כ \u0003קב\"ה מעצמו יוקים לה\u0004."],[10,"","וז\"ש, \u0003בגין דחמינא כל אתוון נפקו מן קמך בלא תועלתא\u0004: כי הטעם שלא הרהיבה ה\u0003א'\u0004 להעלות מ\"ן מעצמה, הוא, משום שראתה שכל האותיות יצאו בלי תועלת, כי נתברר שיש בכל הקומות בחינת זה לעומת זה, לפיכך חשבה שגם היא אינה טובה מהן, וגם כנגדה יש לעומת. וזהו שאמרה \u0003מה אנא אעביד תמן\u0004 כי ראיתי שאיני טובה יותר מהן."],[10,"","וז\"ש, \u0003ותו דהא יהיבתא לאת ב' נבזבזא רברבא דא ולא יאות למלכא עילאה לאעברא\u0004 וכו': וטעם ב' שלא הרהבתי לעלות מ\"ן, הוא משום שראיתי שכבר קבעת עיקר בנין כל פרצוף במדתה של האות \u0003ב'\u0004 בסוד הכתוב \u0003עולם חסד יבנה\u0004, כנ\"ל, ע\"כ לא היה לי ספק שיהיה עוד אפשר איזה שינוי בזה, כי אין מדרך המלך להעביר מתנה שנתן לעבד זה וליתן אותה לעבד אחר."],[10,"","וז\"ש, \u0003א\"ל קב\"ה א' א' אע\"ג דאת ב' בה אברי עלמא את תהא ריש לכל אתוון\u0004: פירוש, כי הן אמת שכבר נברא העולם באות \u0003ב'\u0004 וגם זה אמת שלא אעביר מתנתה לאחר. אמנם לא נברא במדתה אלא בחי' ו\"ק בלי ראש כנ\"ל, וא\"כ עדיין האתוון חסרות ראש, כי לא יכשרו לפריה ורביה זולתו, לכן \u0003את תהא\u0004 משמשת להמשכת ה\u0003ראש לכל אתוון\u0004, דהיינו בחינת המוחין דג\"ר, שהם המוחין דפב\"פ והולדה."],[10,"","וז\"ש, \u0003לית בי יחודא אלא בך, בך ישרון כל חושבנין וכל עובדי דעלמא\u0004: כלומר, כי אין היחוד שלי מתגלה בעולם אלא במדתך, ועוד נוסף, כי כל ענין שכר, עונש, ותשובה, שעליהם יתגלה גמר התיקון, לא יהיו אלא \u0003בך\u0004, כי בחינת ה\u0003ב'\u0004 קבעתי רק לעיקר הפרצוף, שלא יהיה תלוי כלום במעשה התחתונים, ואפילו אם יריעו מעשיהם לא יגיע מזה שום שינוי באלו המוחין כנ\"ל, אמנם המוחין שבך תלויים לגמרי במעשה התחתונים, אם יריעו מעשיהם יסתלקו המוחין דג\"ר שבך, ואם יחזרו בתשובה, ימשיכו שוב המוחין דג\"ר."],[10,"","וזה אמרו \u0003בך ישרון כל חושבנין וכל עובדי דעלמא\u0004. חושבנין, מורה אם יקלקלו מעשיהם, בסוד הכתוב אשר עשה אלקים את האדם ישר והמה בקשו חשבונות רבים, (קהלת ז'). כי אז יסתלקו המוחין דג\"ר. \u0003ועובדי דעלמא\u0004, מורה, על העלאת מ\"ן ע\"י מעשים טובים, כי אז יחזרו וימשיכו המוחין דג\"ר. \u0003וכל יחודא לא הוי אלא באת א'\u0004, זה רומז על היחוד הגדול של גמר התיקון, יהיה ג\"כ \u0003באת א'\u0004."]],[[0,"","נִכְנְסָה הָאוֹת ס'. אָמְרָה לְפָנָיו: רִבּוֹן הָעוֹלָמִים, נוֹחַ לְךְ לִבְרֹא בִּי אֶת הָעוֹלָם, שֶׁיֵּשׁ בִּי סְמִיכָה לַנּוֹפְלִים, שֶׁכָּתוּב (תהלים קמה) סוֹמֵךְ ה' לְכָל הַנּוֹפְלִים. אָמַר לָהּ: עַל כֵּן אַתְּ צְרִיכָה אֶת מְקוֹמֵךְ וְאַל תָּזוּזִי מִמֶּנּוּ. אִם אַתְּ יוֹצֵאת מִמְּקוֹמֵךְ, מַה יִּהְיֶה עַל אוֹתָם הַנּוֹפְלִים, הוֹאִיל וְהֵם סוֹמְכִים עָלַיִךְ מִיָּד יָצְאָה מִלְּפָנָיו."],[1,"","נִכְנְסָה הָאוֹת נ'. אָמְרָה לְפָנָיו: רִבּוֹן הָעוֹלָם, נוֹחַ לְפָנֶיךְ לִבְרֹא בִּי אֶת הָעוֹלָם, שֶׁבִּי כָּתוּב נוֹרָא תְהִלֹּת וּתְהִלָּה לַצַּדִּיקִים נָאוָה תְהִלָּה. אָמַר לָהּ: נוּ\"ן שׁוּבִי לִמְקוֹמֵךְ, שֶׁהֲרֵי בִּשְׁבִילֵךְ שָׁבָה סָמֶ\"ךְ לִמְקוֹמָהּ וְתִהְיִי סְמוּכָה עָלֶיהָ. מִיָּד שָׁבָה לִמְקוֹמָהּ וְיָצְאָה מִלְּפָנָיו."],[2,"","נִכְנְסָה הָאוֹת מ'. אָמְרָה לְפָנָיו: רִבּוֹן הָעוֹלָם, נוֹחַ לְפָנֶיךְ לִבְרֹא בִּי אֶת הָעוֹלָם, שֶׁבִּי נִקְרֵאתָ מֶלֶךְ. אָמַר לָהּ: כָּךְ הוּא וַדַּאי, אֲבָל לֹא אֶבְרָא בָּךְ אֶת הָעוֹלָם, מִשּׁוּם שֶׁהָעוֹלָם צָרִיךְ מֶלֶךְ. שׁוּבִי לִמְקוֹמֵךְ אַתְּ וְל' וְךָּ', שֶׁהֲרֵי לֹא רָאוּי לָעוֹלָם לַעֲמֹד בְּלִי מֶלֶךְ."],[3,"","בְּאוֹתָהּ שָׁעָה יָרְדָה מִלְּפָנָיו הָאוֹת כ' מעַל כּסּא כבודו, הִזְדַּעְזְעָה וְאָמְרָה לְפָנָיו: רִבּוֹן הָעוֹלָם, נוֹחַ לְפָנֶיךְ לִבְרֹא בִּי אֶת הָעוֹלָם, שֶׁאֲנִי כְּבוֹדְךְ. וּכְשֶׁיָּרְדָה כ' מֵעַל כִּסֵּא כְבוֹדוֹ, הִזְדַּעְזְעוּ מָאתַיִם אֶלֶף עוֹלָמוֹת, וְהִזְדַּעְזַע הַכִּסֵּא, וְכָל הָעוֹלָמוֹת הִזְדַּעְזְעוּ לִפֹּל. אָמַר לָהּ הַקָּדוֹשׁ- בָּרוּךְ- הוּא: כָּ\"ף כָּ\"ף, מָה אַתְּ עוֹשָׂה כָּאן שֶׁלֹּא אֶבְרָא בָּךְ אֶת הָעוֹלָם. שׁוּבִי לִמְקוֹמֵךְ, שֶׁהֲרֵי בָּךְ כְּלָיָה, כָּלָה וְנֶחֱרָצָה (ישעיה י) נִשְׁמָע. שׁוּבִי לְכִסְאֵךְ וְתִהְיִי שָׁם. בְּאוֹתָהּ שָׁעָה יָצְאָה מִלְּפָנָיו וְשָׁבָה לִמְקוֹמָהּ."],[4,"","נִכְנְסָה הָאוֹת י'. אָמְרָה לְפָנָיו: רִבּוֹן הָעוֹלָם, נוֹחַ לְפָנֶיךְ לִבְרֹא בִּי אֶת הָעוֹלָם, שִּאַניּ ראשּיּת הַשּם הַקָּדוֹשׁ, וְרָאוּי לְךְ לִבְרֹא בִּי אֶת הָעוֹלָם. אָמַר לָהּ: דַּי לָךְ שֶׁאַתְּ חֲקוּקָה בִּי וְאַתְּ רְשׁוּמָה בִּי, וְכָל רְצוֹנִי עוֹלֶה בָּךְ. אֵינֵךְ רְאוּיָה לְהֵעָקֵר מִשְּׁמִי."],[5,"","נִכְנְסָה הָאוֹת ט'. אָמְרָה לְפָנָיו: רִבּוֹן הָעוֹלָם, נוֹחַ לְפָנֶיךְ לִבְרֹא בִּי אֶת הָעוֹלָם, שֶׁאַתָּה נִקְרֵאתָ בִּי טוֹב וְיָשָׁר. אָמַר לָהּ: לֹא אֶבְרָא בָּךְ אֶת הָעוֹלָם, שֶׁהֲרֵי טוּבֵךְ נִסְתָּר בְּתוֹכֵךְ וְצָפוּן בְּתוֹכֵךְ, זֶהוּ שֶׁכָּתוּב (תהלים לא) מָה רַב טוּבְךְ אֲשֶׁר צָפַנְתָּ לִּירֵאֶיךְ. הוֹאִיל וְגָנוּז בְּתוֹכֵךְ, אֵין בּוֹ חֵלֶק לָעוֹלָם הַזֶּה שֶׁאֲנִי רוֹצֶה לִבְרֹא, אֶלָּא בָּעוֹלָם הַבָּא. וְעוֹד, שֶׁעַל שֶׁטּוּבֵךְ גָּנוּז בְּתוֹכֵךְ, יִטְבְּעוּ שַׁעֲרֵי הַהֵיכָל, זֶהוּ שֶׁכָּתוּב (איכה ב) טָבְעוּ בָאָרֶץ שְׁעָרֶיהָ. וְעוֹד, שֶׁח' כְּנֶגְדֵּךְ, וּכְשֶׁתִּתְחַבְּרוּ יַחַד הִנֵּה ח\"ט, וְעַל כֵּן הָאוֹתִיּוֹת הַלָּלוּ לֹא רְשׁוּמוֹת בַּשְּׁבָטִים הַקְּדוֹשִׁים. מִיָּד יָצְאָה מִלְּפָנָיו."],[6,"","נִכְנְסָה הָאוֹת ז'. אָמְרָה לוֹ: רִבּוֹן הָעוֹלָם, נוֹחַ לְפָנֶיךְ לִבְרֹא בִּי אֶת הָעוֹלָם, שֶׁבִּי שׁוֹמְרִים בָּנֶיךְ אֶת הַשַּׁבָּת, שֶׁכָּתוּב (שמות כ) זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ. אָמַר לָהּ: לֹא אֶבְרָא בָּךְ אֶת הָעוֹלָם, שֶׁבָּךְ יֵשׁ קְרָב, וְחֶרֶב שְׁנוּנָה, וְרֹמַח שֶׁל קְרָב כְּמוֹ שֶׁלַּנּוּן. מִיָּד יָצְאָה מִלְּפָנָיו."],[7,"","נִכְנְסָה הָאוֹת ו'. אָמְרָה לְפָנָיו: רִבּוֹן הָעוֹלָם, נוֹחַ לְפָנֶיךְ לִבְרֹא בִּי אֶת הָעוֹלָם, שֶׁאֲנִי אוֹת מִשִּׁמְךְ. אָמַר לָהּ: וָא\"ו, אַתְּ וְה' דַּי לָכֶם שֶׁאַתֶּן אוֹתִיּוֹת שֶׁל שְׁמִי, שֶׁאַתֶּן בַּסּוֹד שֶׁל שְׁמִי וַחֲקוּקוֹת וּגְלוּפוֹת בִּשְׁמִי, וְלֹא אֶבְרָא בָכֶן אֶת הָעוֹלָם."],[8,"","נִכְנְסָה הָאוֹת ד' וְהָאוֹת ג', אָמְרוּ אַף כָּךְ. אָמַר אַף לָהֶן: דַּי לָכֶן לִהְיוֹת זוֹ עִם זוֹ, שֶׁהֲרֵי הָעֲנִיִּים לֹא יִתְבַּטְּלוּ מִן הָעוֹלָם, וּצְרִיכִים לִגְמֹל עִמָּהֶם חֶסֶד. דָּלֶ\"ת הוּא הֶעָנִי (דל), גִּימֶל גּוֹמֶלֶת לָהּ חֶסֶד. אַל תִּפָּרְדוּ זוֹ מִזּוֹ, וְדַי לָכֶן לָזוּן זוֹ אֶת זוֹ."],[9,"","נִכְנְסָה הָאוֹת ב'. אָמְרָה לוֹ: רִבּוֹן הָעוֹלָם, נוֹחַ לְפָנֶיךְ לִבְרֹא בִּי אֶת הָעוֹלָם, שֶׁבִּי מְבָרְכִים אוֹתְךְ לְמַעְלָה וּלְמַטָּה. אָמַר לָהּ הַקָּדוֹשׁ-בָּרוּךְ-הוּא: הֲרֵי וַדַּאי שֶׁבָּךְ אֶבְרָא אֶת הָעוֹלָם, וְאַתְּ תִּהְיִי הָרֵאשִׁית לִבְרֹא אֶת הָעוֹלָם."],[10,"","עָמְדָה הָאוֹת א' וְלֹא נִכְנְסָה. אָמַר לָהּ הַקָּדוֹשׁ-בָּרוּךְ-הוּא: אָלֶ\"ף אָלֶ\"ף, לָמָּה אֵינֵךְ נִכְנֶסֶת לְפָנַי כִּשְׁאָר כָּל הָאוֹתִיּוֹת אָמְרָה לְפָנָיו: רִבּוֹן הָעוֹלָם, מִשּׁוּם שֶׁרָאִיתִי שֶׁכָּל הָאוֹתִיּוֹת יָצְאוּ מִלְּפָנֶיךְ בְּלִי תוֹעֶלֶת, מָה אֲנִי אֶעֱשֶׂה שָׁם וְעוֹד, שֶׁהֲרֵי נָתַתָּ לָאוֹת ב' אוֹצָר גָּדוֹל זֶה, וְלֹא רָאוּי לְמֶלֶךְ עֶלְיוֹן לְהַעֲבִיר אוֹצָר שֶׁנָּתַן לְעַבְדּוֹ וְלָתֵת לְאַחֵר. אָמַר לָהּ הַקָּדוֹשׁ- בָּרוּךְ-הוּא: אָלֶ\"ף אָלֶ\"ף, אַף עַל גַּב שֶׁאֶבְרָא אֶת הָעוֹלָם בָּאוֹת בֵּי\"ת, אַתְּ תִּהְיִי הָרֹאשׁ לְכָל הָאוֹתִיּוֹת. אֵין בִּי יִחוּד אֶלָּא בָּךְ. בָּךְ יַתְחִילוּ כָּל הַחֶשְׁבּוֹנוֹת וְכָל מַעֲשֵׂי הָעוֹלָם, וְכָל יִחוּד לֹא יִהְיֶה אֶלָּא בָּאוֹת אָלֶ\"ף."]]],[["וְעֲבַד קוּדְשָׁא בְּרִיךְ הוּא אָתְוָון עִלָּאִין רַבְרְבָן, וְאָתְוָון תַּתָּאִין זְעִירִין. וּבְגִין כָּךְ בֵּי\"ת בֵּי\"ת בְּרֵאשִׁית בָּרָא. אָלֶ\"ף אָלֶ\"ף אֱלהִים אֶת. אָתְוָון מִלְּעֵילָא וְאָתְוָון מִתַּתָּא, וְכֻלְהוּ כְּחֲדָא הֲווּ מֵעָלְמָא עִלָּאָה וּמֵעָלְמָא תַּתָּאָה.","בְּרֵאשִׁית רִבִּי יוּדָאי אָמַר מַאי בְּרֵאשִׁי\"ת, בְּחָכְמָ\"ה, דָּא חָכְמָ\"ה, דְּעָלְמָא קָיְימָא עֲלָהּ, לְעָאלָא גוֹ רָזִין סְתִימִין עִלָּאִין. (בראשית מ ע\"ב) וְהָכָא אִגְלִיפוּ שִׁית סִטְרִין רַבְרְבִין עִלָּאִין דְּמִנְהוֹן נָפִיק כֹּלָא, דְּמִנְהוֹן אִתְעֲבִידוּ שִׁית מְקוֹרִין וְנַחֲלִין, לְעָאלָא גוֹ יַמָּא רַבָּא. וְהַיְנוּ בָּרָא שִׁית מֵהָכָא אִתְבְּרִיאוּ. מַאן בָּרָא לוֹן, הַהוּא דְּלָא אִדְכַּר הַהוּא סָתִים דְּלָא יְדִיעַ.","רִבִּי חִיָּיא וְרִבִּי יוֹסֵי הֲווּ אָזְלֵי בְּאָרְחָא, כַּד מָטוּ לְחַד בֵּי חֲקַל, אָמַר לֵיהּ רִבִּי חִיָּיא לְרִבִּי יוֹסֵי הָא דְאַמְרִיתוּ בָּרָא שִׁית וַדַּאי הָכִי הוּא, בְּגִין דְּשִׁית יוֹמִין עִלָּאִין גַּבֵּי אוֹרַיְיתָא וְלָא יַתִּיר. אָחֳרָנִין סְתִימִין אִנּוּן.","אֲבָל חָמֵינָן גּוֹ סִטְרֵי בְּרֵאשִׁית דְּאָמַר הָכִי. גְּלִיפֵי (גליפו) אַגְלִיף הַהוּא סְתִימָאָה קַדִּישָׁא גּוֹ מְעוֹי דְּחַד טְמִירוּ דְנָקִיט (דנקיד) בִּנְקוּדָה דְּנָעִיץ. הַהוּא גְּלִיפֵי (גליפו) אַגְלִיף וְטָמִיר בֵּיהּ כְּמַאן דְּגָנִיז כֹּלָּא תְּחוֹת מַפְתְּחָא חָדָא, וְהַהוּא מַפְתְּחָא גָּנִיז כֹּלָּא בְּהֵיכָלָא חָדָא, וְאַף עַל גַּב דְּכֹלָא גָּנִיז בְּהַהוּא הֵיכָלָא, עִקְּרָא דְּכֹלָא בְּהַהוּא מַפְתְּחָא הֲוֵי. הַהוּא מַפְתְּחָא סָגִיר וּפָתַח.","בְּהַהוּא הֵיכָלָא אִית בֵּיהּ גְּנִיזִין סְתִימִין סַגִּיאִין אִלֵּין עַל אִלֵּין. בְּהַהוּא הֵיכָלָא אִית תַּרְעִין עוֹבַד סְתִימוּ וְאִנּוּן חַמְשִׁין. אִגְלִיפוּ לְאַרְבַּע סִטְרִין וְהֲווּ אַרְבְּעִין (ס\"י ותשע). חַד תַּרְעָא לֵית לֵיהּ סִטְרָא, לָא יְדִיעַ אִי הוּא לְעֵילָא, אִי הוּא לְתַתָּא (ס\"י איהו לעילא איהי לתתא). וּבְגִין כָּךְ הַהוּא תַּרְעָא סָתִים.","גּוֹ אִנּוּן תַּרְעִין אִית מַנְעוּלָא חָדָא, וְחַד אֲתַר דַּקִּיק לְעָאלָא הַהוּא מַפְתְּחָא בֵּיהּ, וְלָא אִתְרְשִׁים אֶלָּא בִּרְשִׁימוּ דְּמַפְתְּחָא, לָא יָדְעִין בֵּיהּ אֶלָּא הַהוּא מַפְתְּחָא (ס\"י דפתחא) בִּלְחוֹדוֹי. וְעַל רָזָא דְנָא בְּרֵאשִׁית בָּרָא אֱלהִים. בְּרֵאשִׁית דָּא מַפְתְּחָא דְּכֹלָא סָתִים בֵּיהּ, וְהוּא סָגִיר וּפָתַח, וְשִׁית תַּרְעִין כְּלִילָן בֵּיהּ. בְּהַהוּא מַפְתְּחָא דְּסָגִיר וּפָתַח. כַּד סָגִיר אִנּוּן תַּרְעִין וְכָלִיל לוֹן בְּגַוֵּיהּ (נ\"א וכלה בגויה) כְּדֵין וַדַּאי כְּתִיב בְּרֵאשִׁית מִלָּה גַלְיָא בִּכְלַל מִלָּה סְתִימָאָה. וּבְכָל אֲתַר בָּרָ\"א מִלָּא סְתִימָאָה אִיהוּ. סָגִיר וְלָא פָתַח.","אָמַר רִבִּי יוֹסֵי וַדַּאי הָכִי הוּא, וְשָׁמַעְנָא לְבּוּצִינָא קַדִּישָׁא דְּאָמַר הָכִי, דְּמִלָּה סְתִימָאָה אִיהוּ בָּרָא סָגִיר וְלָא פָתַח. וּבְעוֹד דְּהֲוָה סָגִיר בְּמִלָּה דְבָרָא, עָלְמָא לָא הֲוֵי וְלָא אִתְקְיַּים, וְהֲוָה חָפֵי עַל כֹּלָּא תֹּה\"וּ, וְכַד שָׁלְטָא הַאי תֹּה\"וּ, עָלְמָא לָא הֲוָה, וְלָא אִתְקְיַּים.","אֵימָתַי הַהוּא מַפְתְּחָא פָּתַח תַּרְעִין וְאִזְדַּמַּן לְשִׁמּוּשָׁא וּלְמֶעְבַּד תּוֹלְדִין כַּד אֲתָא אַבְרָהָם דִּכְתִיב אֵלֶּה תּוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם וְתָנִינָן בְּאַבְרָהָם. וּמַה דְּהֲוָה כֹּלָּא סָתִים בְּמִלַּת בָּרָא, אִתְהַדְּרוּ אָתְוָון לְשִׁמּוּשָׁא, וְנָפַק עַמּוּדָא דְּעֲבַד תּוֹלְדִין, אֵבֶר יְסוֹדָא קַדִּישָׁא דְּעָלְמָא קַיְימָא עֲלֵיהּ.","כַּד הַאי אֵבֶר אִתְרְשִׁים בְּמִלַּת בָּרָא כְּדֵין רְשִׁים סְתִימָאָה עִילָאָה (נ\"א קדישא לגלאה) רְשִׁימוּ אָחֳרָא לִשְׁמֵיהּ וְלִיקָרֵיהּ. וְדָא אִיהוּ מִ\"י. וּבָרָא אֵלֶּה וְגַם כֵּן שְׁמָא קַדִּישָׁא דְּאִתְבָּרְכָא דְּאִיהוּ מַ\"ה אִתְרְשִׁים. וְאַפִּיק מִן בָּרָא אֵבֶר. וְהוּא רְשִׁים בְּאֵלֶּה מִסִּטְרָא דָא וְאֵבֶר מִסִּטְרָא דָא. סְתִימָאָה קַדִּישָׁא. אֵלֶּה קַיָּימָא. אֵבֶר קַיָּימָא. כַּד אִשְׁתְּלִים דָּא אִשְׁתְּלִים דָּא. גָּלִיף לְהַאי אֵבֶר גָּלִיף לְהַאי אֵלֶּה."],[[0,"","לט) \u0003ועבד קב\"ה אתוון\u0004 וכו': ועשה הקב\"ה אותיות עליונות גדולות, הרומזות על ספירות הבינה, ואותיות תחתונות קטנות, הרומזות על ספירות המלכות, ומשום זה כתוב \u0003ב' ב'\u0004, דהיינו \u0003ב\u0004ראשית \u0003ב\u0004רא, וכן \u0003אלף אלף\u0004, דהיינו \u0003א\u0004לקים \u0003א\u0004ת שה\u0003א'\u0004 וה\u0003ב'\u0004 הראשונות הן אותיות מלמעלה, מבינה. וה\u0003א'\u0004 וה\u0003ב'\u0004 השניות הן אותיות מלמטה, ממלכות. וכולן הן ביחד, מעולם העליון, שהוא בינה, ומעולם התחתון, שהוא מלכות. כדי שישפיעו זו בזו."],[0,"","ביאור הדברים, \u0003אתוון רברבן\u0004 הן מבחינת הבינה, \u0003ואתוון תתאין זעירין\u0004 הן בזו\"ן. והנה כשהעליון רוצה להשפיע בתחתון הוא צריך להתלבש בתחתון וז\"ס שתי הביתי\"ן ד\u0003ב\u0004ראשית \u0003ב\u0004רא, ושני האלפי\"ן ד\u0003א\u0004לקים \u0003א\u0004ת: כי \u0003ב'\u0004 הראשונה היא של העליון, שהיא בינה, וה\u0003ב'\u0004 השניה היא של התחתון ז\"א אשר ה\u0003ב'\u0004 הראשונה התלבשה בו. וכן ה\u0003א'\u0004 הראשונה היא דבינה, שהיא התלבשה ב\u0003א'\u0004 השניה של ז\"א, כדי להשפיע אליו. וזה אמרו \u0003וכלהו כחדא הוו, מעלמא עלאה ומעלמא תתאה\u0004 כלומר, ששני הביתי\"ן הן ענין אחד, וכן שני האלפי\"ן הן ענין אחד, אלא הראשונות הן מעלמא עלאה והשניות הן מעלמא תתאה, והן אחת, כי מתלבשות זו בזו, כדרך העליון הרוצה להשפיע בתחתון, וה\u0003ב' דעלמא עלאה\u0004 התלבשת ב\u0003ב' דעלמא תתאה\u0004, וכן ה\u0003א' דעלמא עלאה\u0004 התלבשה ב\u0003א' דעלמא תתאה\u0004."],[1,"","מ) \u0003בראשית, רבי יודאי\u0004 וכו': בראשית, ר' יודאי אמר, מהו בראשית. היינו בחכמה. וזו היא חכמה, שהעולם שה\"ס ז\"א, עומד עליה, להכנס תוך סודות הסתומים העליונים. דהיינו באורות הבינה. וכאן נחקקו ששה קצוות הגדולים העליונים, שהם ו\"ק דבינה, שמהם יוצא הכל, ומהם נעשו ששה מקורים ונחלים, שהם ו\"ק דז\"א, להביאם תוך הים הגדול, שהוא מלכות. והיינו \u0003ברא שית\u0004, הרמוז באותיות בראשית, כי ששת הקצוות נבראו מכאן. מי ברא אותם. היינו אותו שלא נזכר, אותו הסתום שאינו ידוע, שהוא א\"א."],[1,"","ביאור הדברים, יש ב' חכמות בעולם האצילות: א) היא חכמה קדומה, שהיא חכמה דא\"א הנק' חכמה סתימאה. ב) היא החכמה דל\"ב נתיבות, שהיא הבינה העולה לראש דא\"א ונעשית שמה חכמה כדי להשפיע אל הז\"א. וזה אמרו \u0003מאי בראשית, בחכמה\u0004. כי ראשית, הוא שם החכמה, אבל לא החכמה הקדומה דא\"א, אלא \u0003דא חכמה דעלמא קיימא עלה\u0004 היינו החכמה דל\"ב נתיבות, דעלמא שהוא זו\"ן \u0003קיימא עלה\u0004, שמקבל ממנה ומתקיים בה, משא\"כ החכמה דא\"א עצמו, אין ז\"א יכול לקבל ממנה כלום, ולא נברא העולם על ידה. וע\"כ \u0003בראשית ברא\u0004, הכוונה היא על החכמה דל\"ב נתיבות, שהיא בינה החוזרת להיות חכמה ע\"י עליתה לראש א\"א."],[1,"","וז\"ש, \u0003לעאלא גו רזין סתימין עלאין\u0004: כי בעת שהזו\"ן, הנק' עולם, מקבלים מן החכמה דל\"ב נתיבות, הם עולים לאו\"א עלאין, ואו\"א נק' רזין סתימין עלאין. וז\"ש, \u0003דא חכמה דעלמא קיימא עלה לאעלא גו רזין סתימין עלאין. קיימא\u0004 פירושו, השגת מוחין, ואומר, \u0003דא חכמה\u0004, היא החכמה, \u0003דעלמא\u0004 זו\"ן \u0003קיימא עלה\u0004, שע\"י המוחין שמקבל ממנה, זו\"ן מתקיימין, ועולים ע\"י ל\u0003רזין סתימין עלאין\u0004 שהם או\"א ומלבישים אותם, דהיינו שהם נעשים כמוהם. כי תחתון העולה לעליון נעשה כמוהו."],[1,"","וז\"ש, \u0003והכא אגליפו שית סיטרין רברבין עי'\u0004 וכו' \u0003והיינו בר\"א שי\"ת\u0004: כי \u0003בראשית\u0004 נוטריקון \u0003בר\"א שי\"ת, ושית סיטרין\u0004 פירושו, ו' קצוות. ואמר, שבחכמה זו נחקקו ששה קצוות \u0003רברבין עלאין\u0004, שהכל נאצלים ויוצאים מהם. בסו\"ה כולם בחכמה עשית. (תהלים ק\"ד) כי \u0003חכמה\u0004 זו, פירושה, בינה שיצאה מראש דא\"א, בסוד אבא הוציא אמא לחוץ אודות הבנים, ואבא עצמו אתתקן כעין דכר ונוקבא, שפירושו, שחכמה דא\"א, וכן אבא דאצילות, נתקנו בעצמם כעין דו\"נ, ע\"י המלכות שעלתה להם במקום בינה, ונמצא שהבינה עצמה יצאה מבחינת ראש דא\"א ומאבא, ונעשתה לבחינת גוף דא\"א חסר ראש, כי בעמדה בגוף דא\"א אינה יכולה לקבל מבחינת ג\"ר דא\"א, ונעשתה לבחינת ו' קצוות חסרת ג\"ר. (עי' לעיל במראות הסולם אות ב' ד\"ה ונודע) הרי שהבינה נחקקה ונעשתה \u0003שית סטרין\u0004 בלי ראש. וזה אמרו \u0003והכא אגליפו שית סטרין רברבין עלאין דמנהון נפיק כלא\u0004 כי בחכמה דל\"ב נתיבות שהיא בינה, נחקקו בה ו\"ק בחסר ג\"ר מפאת יציאתה מראש דא\"א. ואח\"כ ע\"י מ\"ן מתחתונים, חוזרת לראש דא\"א ומקבלת ג\"ר דחכמה מא\"א, והיא משפעת לזו\"ן, שהם משפיעים השפע לכל העולמות. הרי, שמאלו \u0003שית סטרין\u0004 שנחקקו בבינה יוצאים כל העולמות. ומה שקורא אותם ו\"ק \u0003רברבין עלאין\u0004, הוא משום שהם מבינה, ע\"ד האותיות דבינה, הנק' \u0003אתוון רברבין\u0004."],[1,"","וז\"ש, \u0003דמנהון אתעבידו שית מקורין ונחלין לעאלא גו ימא רבא\u0004: כי החקיקה \u0003דשית סטרין\u0004 בעת היות הבינה לבר מראש דא\"א, נקראות \u0003שית מקורין\u0004, להיותן רק מקורין אל המוחין דז\"א. ואח\"כ בעת חזרתה לראש דא\"א, הן נעשות למוחין דג\"ר הנק' \u0003נחלין\u0004 אל הז\"א, ואז הם נעשים \u0003לשית נחלין\u0004. בס\"ה מנחל בדרך ישתה על כן ירים ראש. (תהלים ק\"י) ואז הז\"א משפיע אותם \u0003לימא רבא\u0004, דהיינו אל הנוקבא שלו. וז\"ש \u0003דמנהון\u0004 מו\"ק \u0003רברבין עלאין\u0004 דבינה \u0003אתעבידו שית מקורין\u0004, הם ו\"ק דז\"א דקטנות. \u0003ונחלין\u0004 הם המוחין דז\"א. \u0003לעאלא\u0004 היינו להשפיע, גו \u0003ימא רבא\u0004 היינו לנוקבא. ומה שו\"ק דקטנות דבינה נק' מקורין למוחין, הוא משום שלא יצאה הבינה לחוץ לבחי' ו\"ק דקטנות, אלא כדי להעשות למקור להשפיע מוחין לזו\"ן. ולולא יצאה הבינה לחוץ לא היו ראויים לשום מוחין כנ\"ל."],[1,"","וז\"ש, \u0003והיינו ברא שית מהכא אתברהאו: ברא\u0004, מורה על ו\"ק סטרין בלי ראש, כי מלת \u0003ברא\u0004 פירושו, סיתום, כמ\"ש להלן. ולפיכך ב' ענינים מרומזים כאן במלת \u0003בראשית\u0004: א) על חכמה, כי \u0003ראשית\u0004, מורה חכמה. ב) \u0003ברא שית\u0004, להורות כי מחכמה נבראו ונחקקו \u0003שית סטרין\u0004 בלי ראש, שהם המקורין למוחין לזו\"ן שהם נק' עולם, והם ז' ימי בראשית."],[1,"","וז\"ש, \u0003מאן ברא לון, ההוא דלא אדכר, ההוא סתים דלא ידיע\u0004: כיון דמלת \u0003ברא\u0004 היא ב\u0003ברא\u0004שית עצמו, א\"כ מי הוא ש\u0003ברא\u0004 זה, ע\"ז אומר שהוא \u0003ההוא סתים דלא ידיע\u0004, דהיינו חכמה סתימאה דא\"א. כי הוא הוציא הבינה מהראש שלו ועשה אותה לבחינת ו\"ק, שהוא \u0003ברא שית סטרין רברבין\u0004 אלו הנרמזים בבראשית."],[2,"","מא) \u0003רבי חייא ורבי\u0004 וכו': ר\"ח ור' יוסי היו הולכים בדרך. כשהגיעו לשדה אחד, אמר לו ר' חייא לר' יוסי: מה שאתם אמרים \u0003ברא שית\u0004, שמרומז בבראשית, ודאי כך הוא, משום שששת ימים עליונים, דהיינו רק הו\"ק דבינה, הם משפיעים אל התורה, שהיא ז\"א, ולא יותר. האחרים, דהיינו הג\"ר דבינה, הם סתומים."],[2,"","ביאור הדברים, אורייתא היינו ז\"א המכונה בשם אורייתא. שית יומין עלאין, הם ו\"ק של הבינה, שהם לעילא מן הז\"א. ואומר, שע\"כ נרמז במלת בראשית \u0003בר\"א שי\"ת\u0004, כי בראשית מורה על הבינה שחזרה להיות חכמה, כדי להשפיע אל הז\"א. ומתוך שהז\"א אינו מקבל ממנה ג\"ר דחכמה, אלא ו\"ק דחכמה בלבד, ע\"כ מרומזות בחכמה זו שבבראשית האותיות \u0003בר\"א שי\"ת\u0004, להורות שאין לו לז\"א ממנה אלא ו\"ק דחכמה בלבד. וזה אמרו \u0003אבל אחרנין סתימין אינון\u0004, כי ג\"ר של החכמה נשארות סתומות לז\"א ואינו משיג אותן."],[2,"","וטעם הדבר הוא, כי נודע שעתיק אתתקן בצמצום ב', דהיינו שהעלה ה' תתאה לנקבי העינים שלו, כדי להאציל לפרצוף א\"א (כנ\"ל אות י\"ג ד\"ה וזהו). ולכן נחלק הכתר לשני חצאין, שגולגלתא עינים ונקבי עינים נשארו בנוקבא דעתיק. ומחצית הכתר התחתון, שהוא אזן, חוטם פה, נתקן לפרצוף א\"א. ונבחן שה\"ת משמשת בנקבי עינים בעתיק, ויה\"ו באח\"פ שהן א\"א, כי ה\"ת דהוי\"ה חסרה בא\"א, וע\"כ אין בא\"א אלא ט\"ס ראשונות בחוסר מלכות. ורק עטרת יסוד דא\"א משלימתו לע\"ס, כנודע. והמלכות נגנזה בנקבי עינים דעתיק. ומהם נחתמו כל פרצופי האצילות, וכל הפרצופין נחלקו בעצמם לב' חצאים: גו\"ע ונקבי עינים לחוד, ואח\"פ לחוד. כי הבינה נחלקה לב' פרצופין, שגו\"ע ונקבי עינים שבה, נתקנו לאו\"א עלאין, ואח\"פ שבה לישסו\"ת."],[2,"","ונמצאת ה\"ת בנקבי עינים דאו\"א, ויה\"ו בחוסר ה\"ת בישסו\"ת, והם חסרים מלכות, כי המלכות שלהם נשארה בנקבי עינים דאו\"א עלאין, ע\"ד הנ\"ל בעתיק וא\"א. וכן בזו\"ן נתתקנו גו\"ע לבחינת זו\"ן הגדולים, ואח\"פ בזו\"ן הקטנים. והמלכות נשארה בנקבי עינים דזו\"ן הגדולים, וזו\"ן הקטנים אין להם אלא ט\"ס ראשונות בחוסר מלכות, ורק עטרת יסוד משלימה למלכות שלהם, ע\"ד הנ\"ל בעתיק וא\"א. הרי, כמו שנחלק הכתר לב' חצאים ג\"ר וז\"ת, כן נחלקה גם הבינה וגם הזו\"ן, שה\"ת נשארה בג\"ר של כל אחד, ובז\"ת אין שם רק \u0003יה\"ו\u0004 בחוסר ה\"ת, רק עטרת יסוד דמלכות משלימתם במקום מלכות."],[2,"","ולפיכך, נשארה מחציתה העליונה של כל מדרגה, בבחינת לא אתידע. כמו פרצוף עתיק, שפירושו, שה\"ת אינה חוזרת ויורדת מנקבי העינים שלהם גם בעת הגדלות, כי הגם שבעת הגדלות הם מחזירים אליהם, האח\"פ דכלים החסרים להם, אמנם אינם ממשיכים ג\"ר דאורות, שהוא מטעם ה\"ת הגנוזה בהם, שעליה היה צמצום א' שלא לקבל חכמה, ולכן נשארים תמיד באור חסדים, בסוד אוירא דכיא. אלא רק מחציתה התחתונה של כל מדרגה ממשכת לעת גדלות את ג\"ר דאורות, בסוד הי' דנפיק מאויר שלהם וחזרו להיות אור חכמה, וג\"ר."],[2,"","ומכח זה נבחן שכל פרצופי ג\"ר הנמשכים בה\"פ אצילות הם רק בחי' ו\"ק דחכמה ונשארים חסרים ג\"ר דחכמה. והוא משום שג\"ר דכל פרצוף אינן מקבלות חכמה אלא ו\"ק דכל פרצוף, ולכן אין באלו המוחין אלא ו\"ק דחכמה."],[2,"","וזה אמרו \u0003דשית יומין עלאין גבי אורייתא ולא יתיר\u0004 דהיינו כמבואר, שאין אל הז\"א ממוחין עלאין אלא שית יומין, שהם ו\"ק של המוחין, אבל \u0003אחרנין סתימין אינון\u0004 אבל ג\"ר של המוחין הן נעלמות, שהרי אפילו בפרצופין העליונים ממנו הן נעלמות, כי אין מוחין אלא לבחינת ו\"ק של הפרצופין העלאין."],[3,"","מב) \u0003אבל חמינן גו\u0004 וכו', אבל ראינו בסתרי בראשית, שאומר כך אותו הסתום הקדוש, חקק חקיקה תוך מעיו, שה\"ס בינה, של נסתר אחד, שה\"ס נוקבא דעתיק, הנקוד בנקודה הנעוצה. שה\"ס נקודת המלכות דצמצום א', שעלתה לבינה, והוציאה אח\"פ דא\"א לחוץ מראש שלו. אותה החקיקה, שנחקקה בבינה, נחקקה ונסתרה בה, כמי שגונז הכל תחת מפתח אחד, ואותו המפתח כולו גנוז בהיכל אחד. ואע\"פ שהכל גנוז באותו ההיכל, עיקר הכל, באותו המפתח הוא, כי אותו המפתח הוא סוגר ופותח."],[3,"","ביאור הדברים, \u0003גליפי\u0004 היינו החקיקה דחסרון אח\"פ דכלים, \u0003סתימאה קדישא\u0004 היינו א\"א הנק' חכמה סתימאה קדישא, \u0003דחד טמירו\u0004 היינו נוקבא דעתיק, \u0003גו מעוי דחד טמירו,\u0004 פירושו, בפנימיות הנוקבא דעתיק, \u0003נקיד\u0004 פירושו תיקון המסך לסוד הזווג. \u0003בנקודה דנעץ\u0004, פירושו, בנקודה דנעיץ בעזקא, שהיא המלכות דצמצום א' הנקראת נקודה אמצעית, שעליה היה הצמצום הא', וזהו לאפוקי מהמסך המתוקן עם עטרת יסוד, כנהוג בו\"ק דכלהו פרצופין, כנ\"ל בדיבור הסמוך. כי מסך זה דעטרת יסוד, נק' בשם נקודה דישובא, ולא בשם נקודה אמצעית."],[3,"","ושיעור הדברים, הוא כי א\"א נחקק ונחסר מג\"ר שלו ע\"י פנימיות העליון שלו שהוא נוקבא דעתיק, שהיא מתוקנת בה\"ת בנקבי עינים שלה כנ\"ל."],[3,"","וז\"ש, \u0003ההוא גליפי אגליף וטמיר ביה, כמאן דגניז כלא תחות מפתחא חדא: מפתחא\u0004, פירושו בחינת המלכות דעטרת יסוד, המתוקנת בכלהו ו\"ק דפרצופי אצילות, כנ\"ל בדיבור הסמוך. כי נתבאר שם שבפרצופי ו\"ק נפיק \u0003י'\u0004 מאויר שלהם ונעשים אור. שפירושו שהמסך יורד מנקבי עינים שלהם אל הפה, ומחזירים אח\"פ למדרגה, ואז אחר שיש להם אח\"פ דכלים קונים גם ג\"ר דאורות. וע\"כ נבחן המסך שבנקבי עינים בשם \u0003מפתחא\u0004, כי הוא סוגר את הפרצוף מהארת ג\"ר בעת שהוא בנקבי עינים, והוא פותח אותו בחזרה עם אורות דג\"ר בעת ירידתו בחזרה למקומו לפה. ומטעם זה הוא מכונה ג\"כ \u0003פתח עינים\u0004. (כנ\"ל אות ז' ובהסולם ד\"ה ותמן)."],[3,"","וזה אמרו \u0003וטמיר ביה כמאן דגניז כלא תחות מפתחא חדא\u0004 כלומר, כי אע\"פ שעתיק עצמו נחקק בה\"ת כנ\"ל, מ\"מ האי גליפי וחקיקה שנעשה בא\"א מכח עתיק, אינו, דומה לחקיקה דעתיק עצמו, כי א\"א נחקק ע\"י \u0003מפתחא\u0004, שהוא עטרת יסוד, כי הוא חסר מלכות, כנ\"ל. ונמצא שבנקבי עינים דא\"א שולטת רק עטרת יסוד ולא ה\"ת. ולפיכך אוירא דא\"א אתיידע, להיותו מתוקן במפתחא דא, משא\"כ אוירא דעתיק לא אתיידע, כי המלכות דנקודה אמצעית בו, שאינה ממשכת בו ג\"ר כנ\"ל. ולא יקשה לך מה שאנו אומרים כאן שיש בא\"א גו\"ע, ולעיל אמרנו שאין בו אלא אח\"פ, שהם מחצית הכתר התחתון. כי כלפי עתיק אין לו אלא אח\"פ, אמנם כלפי עצמו הוא גו\"ע וחסר אח\"פ. כמבואר, (בספרי פתיחה לחכמת הקבלה דף כ\"ה ד\"ה וע\"ז)."],[3,"","וז\"ש, \u0003וההוא מפתחא גניז כלא בהיכלא חדא\u0004: כי א\"א האציל לאו\"א עילאין וחקק גם לאו\"א בחסרון ג\"ר דאורות ואח\"פ דכלים, והם \u0003ההיכל\u0004, שבו נגנזו כל האורות דג\"ר, הן ג\"ר דנשמה, והן ג\"ר דחיה והן ג\"ר דיחידה. ואמרו \u0003דגניז כלא\u0004. הכוונה הוא, שא\"א המשיך גם בחי' ה\"ת דעתיק להיכלא דא, וגם בחינת עצמו, שהוא \u0003המפתחא\u0004."],[3,"","וז\"ש, \u0003ואע\"ג דכלא גניז בההוא היכלא עקרא דכלא בההוא מפתחא הוי\u0004: היכלא הוא הבינה שהיא היכל לחכמה, שבה ג\"ר וו\"ק, שבג\"ר שלה שולטת ה\"ת, ובו\"ק שלה שולט \u0003המפתחא\u0004, שהוא עטרת היסוד, וז\"ש \u0003ואע\"ג דכלא גניז בההוא היכלא\u0004, דהיינו גם בחי' ה\"ת מעתיק, מ\"מ \u0003עקרא דכלא בההוא מפתחא הוי\u0004 היינו רק בעטרת יסוד, כי ו\"ק דבינה הנק' ישסו\"ת, רק בהם נבחן הגניזו שפירושו ו\"ק מחוסרי ראש דג\"ר, משא\"כ בג\"ר דבינה שהם או\"א, ששם ה\"ת בנקבי עינים, שם אינו חסר כלל ג\"ר, כי החסדים של או\"א עלאין חשובים כמו חכמה וג\"ר. (כנ\"ל במראות הסולם אות ב' ד\"ה והוא)."],[3,"","וז\"ש, \u0003ההוא מפתחא סגיר ופתח\u0004: ואף ע\"פ שהסגירו ופתיחו נעשים ע\"י ה\"ת שבנקבי העינים: שבהיותה עולה לנקבי עינים היא סוגרת המוחין דג\"ר, כי אז נשאר הפרצוף בחסרון אח\"פ דכלים ובחוסר ג\"ר דאורות. ובהיותה יורדת מנקבי עינים בחזרה לפה, היא פותחת המוחין דג\"ר שיאירו בפרצוף. כי אז מחזרת האח\"פ דכלים וג\"ר דאורות לפרצוף. הרי שרק ה\"ת עצמה היא הפותחת והסוגרת. עכ\"ז כיון שפתיחת מוחין אינם בג\"ר אלא רק בז\"ת, שבהן אינה שולטת ה\"ת אלא עטרת היסוד הנק' \u0003מפתחא\u0004, וג\"ר דכל מדרגה שבהן שולטת ה\"ת נשארות תמיד בבחינת אוירא דלא אתיידע, כנ\"ל. לפיכך מיוחסות הסגירה והפתיחה על המפתחא, ולא על ה\"ת."],[4,"","מג) \u0003בההוא היכלא אית\u0004 וכו': באותו היכל יש אוצרות סתומים ומרובים, אלו על אלו. באותו ההיכל יש שערים עשוים לסתימה, כלומר שנעשו כדי לסתום את האורות, והם חמשים. נחקקו לד' רוחות, והיו למ\"ט שערים, כי שער אחד אין לו צד, ואינו ידוע אם הוא למעלה או הוא למטה. ומשום זה נשאר השער ההוא סתום."],[4,"","פירוש, כי יש הרבה מיני ג\"ר, שיש ג\"ר דנשמה, ג\"ר דחיה, וג\"ר דיחידה, ובכל אחת מאלו ג' מיני ג\"ר יש הרבה פרטים לאין קץ. וז\"ש, \u0003גניזין סתימין סגיאין אלין על אלין\u0004. ובעת שה\"ת שוכנת בנקבי עינים, נמצאות כל אלו המדרגות בגניזו ובלתי נודעות."],[4,"","וז\"ש, \u0003תרעין עובד סתימו ואינון חמשין\u0004: תרעין פירושו שערים, דהיינו בית קבול לאורות. ויש בהם, ב' בחינות א) כשהם עוד ב\u0003סתימו\u0004, שהשערים סגורים וסתומים ואינם מקבלים כלום. ב) בעת שהשערים פתוחים ומקבלים האורות מהעליון. וז\"ש \u0003תרעין עובד סתימו ואינון חמשין\u0004 שבעת ששערי ההיכל הם בסתימו הם במספר חמשים. אבל מבחינת פתיחת השערים אינם אלא ארבעים ותשע, כמ\"ש להלן. וענין המספר חמשים, הוא, כי ע\"ס הן בעיקר רק ה' ספירות, שהן כח\"ב תו\"מ, אלא הת\"ת כוללת ו\"ק והן עשר. ולפיכך כשכל אחת בה' ספירות כוללת עשר, הן חמשים."],[4,"אגליפו לארבע סטרין והוו ארבעין ותשע",": כי מביא לעיל שהסגירו ופתיחו אינו נעשה ב\u0003ה\"ת\u0004 רק \u0003בהאי מפתחא\u0004, שהוא עטרת. ונמצא שבחינת הגליפו דהיינו החקיקות הראויות לקבלה לא נעשו בכל ה' הספירות כח\"ב תו\"מ, רק בד\"ס לבד שהן כח\"ב ת\"ת, ולא במלכות. וד\"פ עשר הם ארבעים. אמנם גם המלכות כוללת עשר ספירות שהן כח\"ב תו\"מ, ונמצאת שגם היא יכולה לקבל מהמפתחא אל ט\"ס הראשונות שלה, דהיינו עד עטרת יסוד שלה, לכן יש כאן חקיקה ל\u0003ארבעין ותשע\u0004 ספירות: \u0003ארבעים\u0004 מד' הספירות כח\"ב ת\"ת, שכל אחת מהן כלולה מעשר. ותשע הספירות הראשונות מהמלכות שכוללת עשר. ונמצא שאינו חסר אלא המלכות דמלכות."],[4,"חד תרעא לית ליה סטרא, לא ידיע אי הוא לעילא אי הוא לתתא ובגין כך ההוא תרעא סתים",": היינו המלכות דמלכות, שהיא השער הנו\"ן, שהוא עצם ה\"ת היורדת מעינים לפה בעת גדלות כנ\"ל. ונתבאר לעיל, שאע\"פ שה\"ת יורדת מנקבי עינים דאו\"א עלאין אל הפה, ואח\"פ שלהם עם ישסו\"ת המלבישים עליהם מתחברים למדרגת או\"א לפרצוף אחד, שאז נמשכין בהם ג\"ר דאורות, עכ\"ז אין או\"א מקבלים כלום מהאורות דג\"ר, ונשארים בבחי' אוירא דכיא בלבד, ודומים כמו שה\"ת עוד לא ירדה כלל מנקבי העינים שלהם. והנה לפי\"ז נמצא, כי ביחס ג\"ר דבינה שהן או\"א עלאין, לא נודע אם ה\"ת עוד עומדת בנקבי העינים שלהם לעילא, שהרי עדיין נמצאים באור חסדים לבד כמקודם לכן. או שהיא ירדה מנקבי עינים לתתא אל מקום הפה, שהרי העלו לכלים דאח\"פ שלהם עם ישסו\"ת ומשפיעים המוחין דג\"ר דאורות אל ישסו\"ת, נמצא בהכרח שה\"ת ירדה לתתא לפה. באופן שאם אנו מסתכלים ביחס או\"א עי' נדמה לנו שה\"ת היא לעילא בנקבי עינים. ואם אנו מסתכלים ביחס ישסו\"ת רואים אנו אותה לתתא בפה."],[4,"","וז\"ש \u0003חד תרעא לית ליה סטרא\u0004 היינו המלכות דמלכות שהיא עצם ה\"ת. \u0003לא ידיע אי הוא לעילא אי הוא לתתא\u0004 כי ביחס או\"א היא לעילא, וביחס ישסו\"ת היא לתתא \u0003ובגין כך ההוא תרעא סתים\u0004 ונמצא משום זה, שהאי מלכות דמלכות לא נפתחה כלל, והיא סתומה כמזמן הקטנות, דהיינו כמטרם ירידתה לפה, כי פתיחת השערים נעשתה רק בישסו\"ת שבהם חסרה ה\"ת, ועטרת היסוד משמשת בהם במקומה, אבל באו\"א עלאין שבהם משמשת ה\"ת, הם נשארו סתימין מג\"ר כמקודם לכן."],[4,"","וז\"ש, \u0003בגין כך ההוא תרעא סתים\u0004. ותשכיל אמנם, כי אע\"פ ששער הנו\"ן הוא המלכות דמלכות, כנ\"ל, הנה זהו רק ביחס לכלים, אמנם ביחס לאורות הוא נבחן לג\"ר של המוחין, שהרי מחמתה נשארו או\"א עי' באור חסדים בלי ג\"ר וכן כל העליונים (כנ\"ל בד\"ה וטעם הדבר באות מ\"א). הרי שסתימת השער הנון גורמת חסרון ג\"ר דמוחין מכלהו מדרגות ואין בהן רק ו\"ק דמוחין. ובזה תבין מה שאמרו חז\"ל (נדרים ל\"ח ע\"א) שחמשים שערי בינה כולן ניתנו למשה חסר אחד, והוא סוד חסרון ג\"ר דמוחין, כנ\"ל, כי ג\"ר אלו דמוחין לא יאירו בעולמות רק בגמר התיקון."],[5,"","מד) \u0003גו אינון תרעין\u0004 וכו': בתוך אותם השערים, יש מנעול אחד, ומקום צר אחד להכניס בו אותו המפתח, ואינו נרשם וניכר רק לפי הרשימה של המפתח, שאינם יודעים בו, במקום הצר, אלא במפתח ההוא בלבד. ועל סוד זה כתוב, \u0003בראשית ברא אלקים\u0004. בראשית, זהו המפתח שהכל סתום בו, והוא הסוגר והפותח. וששה שערים כלולים בו במפתח ההוא הסוגר והפותח. כשסוגר אותם השערים, וכולל אותם בתוכו, אז ודאי כתוב \u0003בראשית\u0004, מלה גלויה בכלל מלה סתומה. \u0003ברא\u0004, בכל מקום שהוא, היא מלה סתומה, שמורה, שהמפתח סוגר ואינו פותח."],[5,"","ביאור הדברים, הה\"ת שבנקבי עינים נק' \u0003מנעולא\u0004 בהיותה נועלת את האורות דג\"ר שאינם יכולים להאיר בפרצוף כל עוד שהיא עומדת לעילא בנקבי עינים. וז\"ש \u0003גו אינון תרעין אית מנעולא חדא, ובהאי מנעולא יש חד אתר דקיק\u0004 היינו היסוד שבה' תתאה שהיא השער המ\"ט דכלים, כי עצם ה' תתאה היא מלכות דמלכות שער הנון, ויסוד דמלכות הוא שער מ\"ט, \u0003לעאלא ההוא מפתחא\u0004 כי ביסוד של ה\"ת נכנס \u0003המפתחא\u0004, שהוא בחינת עטרת יסוד של המוחין המוריד את ה\"ת מנקבי העינים לפה ונפתח הפרצוף באורות דג\"ר. וע\"כ נק' עטרת היסוד בשם \u0003מפתחא\u0004."],[5,"","וז\"ש, \u0003ולא אתרשים אלא ברשימו דמפתחא, לא ידעין ביה אלא ההוא מפתחא בלחודוי\u0004: המפתחא הוא עטרת היסוד של המוחין, והוא נכנס בבחינה שכנגדו שבה\"ת, שהיא יסוד דמלכות כנ\"ל, המנעולא שהיא ה\"ת לא אתרשים לגנוז ולנעול את ג\"ר \u0003אלא ברשימו דמפתחא\u0004 השולט בז\"ת דבינה שהן ישסו\"ת. אבל לא בבחינת עצמו, שהוא ה\"ת השולטת בג\"ר דבינה, שהן או\"א עילאין הנחשבים תמיד לג\"ר גמורות. וכמו כן המנעולא לא אתרשים להפתח אלא ביסוד דמוחין."],[5,"","ובזה נמצא \u0003לא ידעין ביה אלא ההוא מפתחא בלחודוי\u0004 ידיעה, פירושו המשכת מוחין ואומר כי לא נמשכו המוחין אלא בבחינת המפתחא בלבד, דהיינו בז\"ת של הבינה. ששם משמשת המפתחא, עטרת יסוד, אבל במקום או\"א עלאין שהם ג\"ר דבינה ששם אינה משמשת המפתחא אלא ה\"ת עצמה, שם נשארו בבחינת לא אתיידע. ובזה נתבאר היטב, שאע\"פ שבבחינת עצם ה\"ת \u0003לא ידיע אי הוא לעילא, אי הוא לתתא\u0004, כנ\"ל, עכ\"ז מספיק להיות ידיע בשביל ישסו\"ת כי נפתח על ידה במוחין דג\"ר. והוא כי אין בישסו\"ת רק \u0003יה\"ו\u0004 בחוסר מלכות, ועטרת יסוד משמשת בו למסך במקום המלכות. וגם המוחין המורידים את ה\"ת מנקבי העינים לפה, משמשים ג\"כ רק בבחינת מסך דעטרת יסוד, כי בה\"ת לא היתה כלל סגירה וחסרון ג\"ר שתהיה צריכה להפתח. שהרי היא משמשת באו\"א שהם תמיד בבחי' ג\"ר כנ\"ל."],[5,"","ולפי שכל הגניזו והסגירה לא היו אלא בבחינת עטרת יסוד המשמשת בישסו\"ת, נמצא משום זה, שעטרת היסוד דמוחין היא לבדה המפתחא להוריד ה\"ת מהעינים לפה, דהיינו רק בכלים הדקים הנעשים בכח המסך דעטרת יסוד כמוהם. וזה שמסיק \u0003לא ידעין ביה אלא ההוא מפתחא בלחודוי\u0004 כלומר, שאין המוחין מגיעים אלא לכלים דישסו\"ת היוצאים מבחי' המפתחא, שהוא עטרת יסוד. ולא לאו\"א שהם בחי' ה\"ת שהיא המלכות דמלכות, ועצם המנעולא."],[5,"","וז\"ש, \u0003בראשית דא מפתחא\u0004 וכו': כלומר, כי המלה בראשית שהיא החכמה, כוללת בתוכה רק בחינת המפתחא הנ\"ל, שהיא רק עטרת יסוד, שער מ\"ט דכלים, ואינה כוללת את שער הנון דכלים שהוא מלכות דמלכות, וז\"ש \u0003בראשית דא מפתחא, דכלא סתים ביה\u0004 כלומר שעמו נעשה הסתימו דכלא בעת הקטנות \u0003והוא סגיר ופתח\u0004, כי הוא סוגר כל המוחין בעת הקטנות בעוד הה\"ת בעינים, ופותח אותם בעת הגדלות להוריד הה\"ת מנקבי עינים לפה. והנפקא מינה בזה הוא, כי ע\"כ אין פתיחת החכמה הרמוזה במלה בראשית, אלא להו\"ק של המדרגות, שהן מבחינת הכלים \u0003דההוא מפתחא\u0004 (כמ\"ש לעיל אות מ\"א ד\"ה וטעם הדבר ע\"ש), אבל לג\"ר של הפרצופין, אין המוחין דבראשית מאירים להן. כי הכלים שלהן אינם מבחינת \u0003המפתחא\u0004 אלא מבחי' \u0003ה\"ת\u0004 כנ\"ל."],[5,"","וזה אמרו \u0003ושית תרעין כלילן ביה בההוא מפתחא דסגיר ופתח\u0004, כי ג\"ר של המוחין חסרות בו, ואינו פותח אלא ז\"ת של המוחין, שכל אחת מז\"ת אין בה אלא ו\"ק, והן ז\"פ ו\"ק, ונמצא \u0003המפתחא\u0004 שהוא הספירה הז', דהיינו עטרת יסוד, שהוא כולל בתוכו רק שית תרעין. וז\"ש \u0003ושית תרעין כלילן ביה בההוא מפתחא דסגיר ופתח\u0004 ומורה בזה, שאינו ממשיך אלא ו\"ק דמוחין."],[5,"","וז\"ש, \u0003בראשית, מלה גליא בכלל מלה סתימאה, ובכל אתר, בר\"א מלה סתימאה איהו\u0004: כלומר, \u0003בראשית\u0004 מורה על חכמה, שהיא \u0003מלה גליא\u0004, אבל אומרו בראשית ברא, המשמעות היא שהחכמה נעלמה ונסתמה. וז\"ש \u0003בראשית מלה גליא בכלל מלה סתימאה\u0004 שהוא משום שכתובה אחריה המלה \u0003ברא, ובכל אתר בר\"א, מלה סתימאה איהו\u0004 הרי שבראשית ברא פירושו שהחכמה נסתמה. ונמצא כי המשמעות היא \u0003סגיר ולא פתח\u0004 שהחכמה נסגרה, ועוד לא נפתחה."],[6,"","מה) \u0003אמר ר' יוסי\u0004 וכו': אר\"י, ודאי כך הוא. ושמעתי ממאור הקדוש שהוא רבי שמעון, שאמר כך, אשר \u0003ברא\u0004 היא מלה סתומה שמורה, שהמפתח סוגר ואינו פותח. ובעוד שהמפתח סוגר במלה \u0003ברא\u0004, לא היה העולם, ולא נתקיים, ותהו היה מחפה על הכל. וכשתהו זה שלט, לא היה העולם, ולא נתקיים."],[7,"","מו) \u0003אימתי ההוא מפתחא\u0004 וכו': ומתי פתח מפתח ההוא את השערים, והוכן לשמוש ולעשות תולדות. הוא כשבא אברהם, שה\"ס חסד, שכתוב, אלה תולדות השמים והארץ בהבראם, ולמדנו, אל תקרא בהבראם, אלא באברהם. ואז, מה שהיה סתום הכל במלת \u0003ברא\u0004, כנ\"ל, חזרו האותיות, שהם הכלים, ונפתחו לשמוע, ויצא העמוד העושה תולדות, אבר יסוד קדוש, שהעולם עומד עליו. כי ברא הוא אותיות אבר."],[7,"","ביאור הדברים, ששואל, \u0003אימתי ההוא מפתחא פתח תרעין, ואזדמן לשמושא, ולמעבד תולדין\u0004 ויש בשאלה הזו ג' דברים: א) \u0003פתח תרעין\u0004, והוא ענין ירידת ה\"ת מנקבי עינים לפה, שאז נפתחו מ\"ט שערים במוחין דחכמה כנ\"ל. ב) \u0003ואזדמן לשמושא\u0004, והוא ענין התלבשות החכמה באור חסדים שמטרם התלבשות אור החכמה באור דחסדים, לא יוכלו האח\"פ לקבל המוחין דחכמה, אע\"פ שכבר נתחברו בגו\"ע למדרגה אחת. (כמ\"ש לעיל אות ט\"ז), כי בלי לבוש דחסדים עוד \u0003מ\"י\u0004 לא נהיר ב\u0003אלה\u0004, ואל\"ה עוד סתים בשמא, ע\"ש. ונבחן שעוד המוחין לא אזדמנו לשמושא בתחתון. ג) \u0003ולמעבד תולדין\u0004, שפירושו הוא הולדת נשמות, כי אחר שהז\"א מקבל המוחין האלו בשלימות הוא מזדווג בנוקבא ומוליד נשמות הצדיקים."],[7,"","ומשיב \u0003כד אתא אברהם וכו' מה דהוה כלא סתים במלת ברא אתהדרו אתוון לשמושא\u0004, אברהם ה\"ס חסד דז\"א דגדלות שאז נעשה החסד חכמה, כמ\"ש בזוהר (שמות אות רמ\"ט). ומטרם שבא אברהם היה הכל סתים במלת \u0003ברא\u0004, ושלטא תוהו על עלמא שהם זו\"ן ולא היה לזו\"ן אז, לא חסדים ולא חכמה, \u0003וכד אתא אברהם\u0004, שהוא אור החסד המושפע בז\"א, הנה אז נפתחו השערים בשפע החכמה, כי ה\"ת ירדה מעינים לפה וישסו\"ת נתחברו עם או\"א למדרגה אחת ונמשכו לישסו\"ת ג\"ר דאורות, שהן אור החכמה. וכיון שכבר היה לו לז\"א אור חסדים מבחינת \u0003אברהם\u0004, הנה נתלבשו אור חכמה באור חסדים, ואז \u0003נתחברו אתוון אל\"ה במ\"י ונשלם שמא אלהים\u0004, והמוחין נתלבשו בז\"א."],[7,"","וז\"ש \u0003כד אתא אברהם\u0004 וכו' \u0003אתהדרון אתוון לשמושא\u0004 שנמשכו מוחין דחכמה תוך החסדים ונתלבשו בז\"א \u0003ונפק עמודא דעבד תולדין\u0004, כי אז ירדה ה\"ת מנקבי עינים דז\"א לפה שלו, והשיג גם הוא בינה וז\"א ונוקבא שהיו חסרים לו, שהם נקראים אצלו נה\"י חדשים, עם יסוד דגדלות הנקרא \u0003אבר יסודא קדישא, דעלמא קיימא עליה\u0004, כי דרך אבר זה הוא משפיע לנוקבא, הנק' עלמא תתאה, ומוליד נשמות הצדיקים. וזהו בדרך כלל. אבל איך הוא הסדר של המשכת המוחין בפרטות, מבאר אח\"כ."],[8,"","מז) \u0003כד האי אבר\u0004 וכו': כשה\u0003אבר\u0004 הזה נרשם במלת \u0003ברא\u0004, אז רשם הסתום העליון, רושם אחר לשמו ולכבודו, וזה הוא \u0003מ\"י\u0004, וברא \u0003אל\"ה\u0004. וגם השם הקדוש המבורך שהוא מ\"ה, נרשם והוציא מן \u0003ברא, אבר\u0004. והוא רשום באלה מצד זה, ובאבר מצד זה. הסתום הקדוש \u0003אל\"ה\u0004 קיים, ואבר קיים. כשנשלם זה, נשלם זה. חקק לאבר הזה אות \u0003ה'\u0004, וחקק ל\u0003אל\"ה\u0004 הזה אות \u0003י'.\u0004"],[8,"","ביאור הדברים, עתה מבאר בפרט, ענין המוחין דז\"א, שהביא מקודם בדרך כלל. ואומר, שבעת שה\u0003אב\"ר\u0004 נרשם במלת \u0003בר\"א, רשים סתימאה עילאה רשימו אחרא\u0004 שהיא \u0003מ\"י\u0004. פי', כי \u0003אב\"ר\u0004 הוא יסוד ועטרה, ו\u0003ברא\u0004, מורה על הסגירו של ג\"ר מכח עלית ה\"ת לנקבי עינים כנ\"ל. ואומר, שהאי עטרה של ה\u0003אבר אתרשים\u0004 בה\"ת שבנקבי עינים, דהיינו כמו שאמר ר' חייא לעיל, \u0003דהאי מנעולא\u0004 שהוא ה\"ת, \u0003אתרשים ברשימא דמפתחא\u0004, שהיא עטרת יסוד, ע\"ש. וזה נבחן דהאי \u0003סתימא עלאה\u0004, שהם או\"א עילאין, הנרשמין בה\"ת, עשו עתה \u0003רשימו אחרא\u0004 בהאי \u0003מנעולא\u0004 שלהם, דהיינו הרשימא של \u0003המפתחא\u0004, שהיא עטרה דהאי \u0003אב\"ר\u0004. ואז אקרי \u0003מ\"י דקיימא לשאלה\u0004, דהיינו הראוי לקבל מ\"ן, ולהוריד ה\"ת מעינים, ולהעלות להם אתוון \u0003אלה\u0004, שהן אח\"פ, שעמהן נמשכות ג\"ר דאורות. משא\"כ מטרם שהה\"ת אתרשים ברשימא ד\u0003אב\"ר\u0004, לא היתה שום מציאות להמשכת גה\"ר, כי ה\"ת עצמה ה\"ס שער הנון, שאינו נפתח בג\"ר, כנ\"ל, וע\"כ מטרם דאתרשים בהאי \u0003מפתחא דאבר\u0004, אינם נק' מ\"י כי לא קיימא לשאלה."],[8,"","וזה אמרו \u0003כד האי אב\"ר אתרשים במלת בר\"א\u0004, בעת שה\"ת שבמלת \u0003ברא\u0004 קבלה הרשימה \u0003דאבר\u0004, שהיא \u0003המפתחא. כדין רשים סתימאה עילאה רשימו אחרא לשמיה וליקריה ודא איהו מ\"י,\u0004 הנה אז רשים או\"א את ה\u0003מפתחא\u0004 בה\"ת שבנקבי עינים שלהם, שתהיה ראויה להקרא \u0003מ\"י דקיימא לשאלה\u0004 ולהמשיך מוחין דג\"ר כנ\"ל. כי אין המוחין נמשכים אלא רק \u0003ברשימא דהאי מפתחא\u0004."],[8,"","וז\"ש, \u0003וברא אלה\u0004: דהיינו אחר שנתרשם האי \u0003מנעולא\u0004 שבמלת \u0003ברא\u0004 עם \u0003הרשימו דמפתחא\u0004, שהוא ה\u0003אבר\u0004, ונעשה בסוד \u0003מ\"י\u0004, כנ\"ל, הנה אז \u0003מ\"י ברא אלה\u0004, כלומר, שירדה ה\"ת מנקבי עינים לפה והעלה אח\"פ שהם אתוון \u0003אל\"ה\u0004 אל הראש, ונמשכו ג\"ר כנ\"ל. ומה שאומר \u0003ברא אל\"ה\u0004, שהוא לשון של סתימו, הוא מפני שעדיין אין בהם לבוש החסדים, ונמצאים אתוון \u0003אל\"ה\u0004 שעלו, שעוד הן \u0003סתימין בשמא\u0004, (כנ\"ל אות י\"ד ד\"ה קיימא), ואינן יכולות להתגלות בלי לבוש החסדים."],[8,"","וז\"ש, וג\"כ \u0003שמא קדישא דאתברכא דאיהו מ\"ה אתרשים ואפיק מן ברא אב\"ר\u0004: המלכות שירדה מעינים לפה נק' \u0003מ\"ה\u0004 כי עלמא תתאה נק' \u0003מ\"ה\u0004 (כנ\"ל אות ח', ע\"ש), וזה המסך שהיה מקודם בנקבי עינים ירד עתה לפה ונעשה הזווג עליה והוציאה קומת חסדים, שהיא אור של ברכה, (כנ\"ל אות י\"ד ד\"ה וז\"ש בעא). וע\"י זה אפיק סתימא של מלת \u0003בר\"א\u0004 ועשה אותו ל\u0003אבר\u0004, שהוא יסוד המשפיע חסדים. וז\"ש, דאחר דגם \u0003שמא קדישא דאתברכא דאיהו מ\"ה אתרשים, ואפיק מן ברא אב\"ר\u0004, כי היה חסר עוד באתוון ד\u0003אל\"ה\u0004 אור של חסדים לאתלבשא בהו, וע\"כ היו עוד \u0003אל\"ה סתימין בשמא\u0004, וע\"י אור של ברכה ד\u0003מ\"ה\u0004 נפתח הסתימו ד\u0003ברא\u0004 ונעשה ל\u0003אב\"ר\u0004 משפיע."],[8,"","וז\"ש, \u0003והוא רשים באלה מסטרא דא, ואבר מסטרא דא\u0004: כלומר, עתה נבחנו בהם ב' מדרגות זה כנגד זה. כי \u0003אל\"ה\u0004 שהן אח\"פ עם המוחין דחכמה שעודם בחוסר חסדים בסטרא דא. ו\u0003אבר\u0004 שהוא היסוד שקבל קומת חסדים מן ה\u0003מ\"ה\u0004 עומד כנגדו מסטרא דא, בחוסר חכמה. וזה אמרו \u0003סתימאה קדישא אל\"ה קיימא, אבר קיימא\u0004. כי \u0003אלה\u0004 שהשיגו המוחין דחכמה הנק' \u0003קדש\u0004, קיימא בסתימו בפרצוף מסטרא דא, וכנגדו עומד \u0003אב\"ר\u0004 בקומת החסדים בפרצוף. וזה אמרו \u0003כד אשתלים דא אשתלים דא\u0004, כי שניהם יצאו על ידי ירידת ה\"ת מנקבי עינים לפה, כי ה\u0003אבר\u0004 יצא מכח ה\u0003מ\"ה\u0004 שבפה וכן \u0003אל\"ה\u0004 שהן אח\"פ, עלו למעלה מכח ביאת המלכות מתחתיהם לפה. ונמצא \u0003כד אשתלים דא אשתלים דא\u0004 כי באים בבת אחת."],[8,"גליף להאי אבר ה', גליף להאי אלה י'",": כי \u0003ה'\u0004 מורה על המסך המוציא רק קומת חסדים בלי חכמה, להיותה בחינת מלכות שאינה ראויה לקבל חכמה רק חסדים. ו\u0003י'\u0004 מורה, על מסך דזכר הראוי לקבל חכמה. וזה שאמר \u0003גליף להאי אבר ה'\u0004, דהיינו עם המסך \u0003מ\"ה\u0004 הממשיך רק חסדים בלי חכמה. וגליף \u0003להאי אל\"ה י'\u0004, דהיינו עם מסך דזכר הממשיך חכמה ולא חסדים."]],[[0,"","וְעָשָׂה הַקָּדוֹשׁ-בָּרוּךְ-הוּא אוֹתִיּוֹת עֶלְיוֹנוֹת גְּדוֹלוֹת, וְאוֹתִיּוֹת תַּחְתּוֹנוֹת קְטַנּוֹת. וּמִשּׁוּם כָּךְ בֵּי\"ת בֵּי\"ת - בְּרֵאשִׁית בָּרָא. אָלֶ\"ף אָלֶ\"ף - אֱלֹהִים אֵת. אוֹתִיּוֹת מִלְמַעְלָה וְאוֹתִיּוֹת מִלְּמַטָּה, וְכֻלָּן יַחַד הֵם מֵהָעוֹלָם הָעֶלְיוֹן וּמֵהָעוֹלָם הַתַּחְתּוֹן."],[1,"","בְּרֵאשִׁית, רַבִּי יוּדַאי אָמַר, מַה זֶּה בְּרֵאשִׁי\"ת בְּחָכְמָ\"ה. זוֹ הַחָכְמָ\"ה שֶׁהָעוֹלָם עוֹמֵד עָלֶיהָ, לְהִכָּנֵס לְתוֹךְ סוֹדוֹת נִסְתָּרִים עֶלְיוֹנִים. וְכָאן נֶחְקְקוּ שִׁשָּׁה צְדָדִים גְּדוֹלִים עֶלְיוֹנִים שֶׁמֵּהֶם הַכֹּל יוֹצֵא, שֶׁמֵּהֶם נַעֲשׂוּ שִׁשָּׁה מְקוֹרוֹת וּנְחָלִים לְהִכָּנֵס לְתוֹךְ הַיָּם הַגָּדוֹל. וְהַיְנוּ בָּרָא שִׁית מִכָּאן נִבְרְאוּ. מִי בָרָא אוֹתָם הַהוּא שֶׁלֹּא נִזְכָּר, הַהוּא הַנִּסְתָּר שֶׁאֵינוֹ יָדוּעַ."],[2,"","רַבִּי חִיָּיא וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים בַּדֶּרֶךְ. כְּשֶׁהִגִּיעוּ לְשָׂדֶה אֶחָד, אָמַר רַבִּי חִיָּיא לְרַבִּי יוֹסֵי, זֶה שֶׁאֲמַרְתֶּם בָּרָא שִׁית - וַדַּאי זֶה כָּךְ, מִשּׁוּם שֶׁשִּׁשָּׁה יָמִים עֶלְיוֹנִים אֵצֶל הַתּוֹרָה וְלֹא יוֹתֵר. הָאֲחֵרִים הֵם נִסְתָּרִים."],[3,"","אֲבָל רָאִינוּ בְּתוֹךְ צִדְדֵי בְרֵאשִׁית שֶׁאָמַר כָּךְ. חֲקִיקוֹת חָקַק אוֹתוֹ הַנִּסְתָּר הַקָּדוֹשׁ בְּתוֹךְ מֵעָיו שֶׁל סֵתֶר אֶחָד שֶׁנָּקוּד בַּנְּקֻדָּה שֶׁנָּעַץ. הַהוּא חָקַק חִקּוּקִים וְנִסְתָּר בּוֹ, כְּמִי שֶׁגּוֹנֵז הַכֹּל תַּחַת מַפְתֵּחַ אֶחָד, וְאוֹתוֹ הַמַּפְתֵּחַ גּוֹנֵז הַכֹּל בְּהֵיכָל אֶחָד. וְאַף עַל גַּב שֶׁהַכֹּל גָּנוּז בַּהֵיכָל הַהוּא - הָעִקָּר שֶׁל הַכֹּל הוּא בְּאוֹתוֹ הַמַּפְתֵּחַ. אוֹתוֹ הַמַּפְתֵּחַ סוֹגֵר וּפוֹתֵחַ."],[4,"","בְּאוֹתוֹ הַהֵיכָל יֵשׁ גְּנָזִים נִסְתָּרִים רַבִּים אֵלּוּ עַל אֵלּוּ. בְּאוֹתוֹ הַהֵיכָל יֵשׁ שְׁעָרִים מַעֲשֵׂה סֵתֶר, וְהֵם חֲמִשִּׁים. נֶחְקְקוּ לְאַרְבָּעָה צְדָדִים וְהָיוּ לְאַרְבָּעִים (ס\"א ותשעה). לְשַׁעַר אֶחָד אֵין צַד, לֹא יָדוּעַ אִם הוּא לְמַעְלָה אִם הוּא לְמַטָּה (ס\"י הוא למעלה הוא למטה). וּמִשּׁוּם כָּךְ אוֹתוֹ הַשַּׁעַר סָתוּם."],[5,"","בְּתוֹךָ אוֹתָם הַשְּׁעָרִים יֵשׁ מַנְעוּל אֶחָד, וּמָקוֹם אֶחָד קָטָן לְהַכְנִיס אוֹתוֹ הַמַּפְתֵּחַ בּוֹ, וְאֵינוֹ נִרְשָׁם אֶלָּא בָּרֹשֶׁם שֶׁל הַמַּפְתֵּחַ. אֵין יוֹדְעִים בּוֹ אֶלָּא אוֹתוֹ הַמַּפְתֵּחַ (ס\"י של הפתח) לְבַדּוֹ. וְעַל זֶה הַסּוֹד בְּרֵאשִׁית בָּרָא אֱלֹהִים. בְּרֵאשִׁית זֶה הַמַּפְתֵּחַ שֶׁהַכֹּל נִסְתָּר בּוֹ, וְהוּא סוֹגֵר וּפוֹתֵחַ, וְשִׁשָּׁה שְׁעָרִים כְּלוּלִים בּוֹ בְּאוֹתוֹ הַמַּפְתֵּחַ שֶׁסּוֹגֵר וּפוֹתֵחַ. כְּשֶׁסּוֹגֵר אֶת אוֹתָם הַשְּׁעָרִים וְכוֹלֵל אוֹתָם בְּתוֹכוֹ (נ\"א וכולא בתוכו), אָז וַדַּאי כָּתוּב בְּרֵאשִׁית, דָּבָר גָּלוּי בִּכְלָל דָּבָר נִסְתָּר. וּבְכָל מָקוֹם בר\"א - זֶה דָּבָר נִסְתָּר. סוֹגֵר וְלֹא פּוֹתֵחַ."],[6,"","אָמַר רַבִּי יוֹסֵי, וַדַּאי זֶה כָּךְ, וְשָׁמַעְתִּי אֶת הַמָּאוֹר הַקָּדוֹשׁ (רשב\"י) שֶׁאוֹמֵר כָּךְ, שֶׁדָּבָר נִסְתָּר הוּא בָּרָא, סוֹגֵר וְלֹא פוֹתֵחַ. וּבְעוֹד שֶׁהָיָה סוֹגֵר בְּמִלַּת בָּרָא, לֹא הָיָה הָעוֹלָם וְלֹא הִתְקַיֵּם, וְהָיָה מְכַסֶּה עַל הַכֹּל תֹּה\"וּ. וּכְשֶׁשּׁוֹלֵט הַתֹּה\"וּ הַזֶּה, אֵין עוֹלָם וְלֹא מִתְקַיֵּם."],[7,"","מָתַי אוֹתוֹ הַמַּפְתֵּחַ פּוֹתֵחַ שְׁעָרִים וּמִזְדַּמֵּן לְשִׁמּוּשׁ וְלַעֲשׂוֹת תּוֹלָדוֹת כְּשֶׁבָּא אַבְרָהָם, שֶׁכָּתוּב אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, וְשָׁנִינוּ בְּאַבְרָהָם. וּמַה שֶּׁהַכֹּל הָיָה סָתוּם בְּמִלַּת בָּרָא - חָזְרוּ הָאוֹתִיּוֹת לְשַׁמֵּשׁ, וְיָצָא עַמּוּד שֶׁעָשָׂה תוֹלָדוֹת, אֵבַר הַיְסוֹד הַקָּדוֹשׁ שֶׁהָעוֹלָם עוֹמֵד עָלָיו."],[8,"","כְּשֶׁהָאֵבָר הַזֶּה נִרְשַׁם בְּמִלַּת בָּרָא, אָז רָשַׁם הַנִּסְתָּר הָעֶלְיוֹן (נ\"א: הקדוש לגלות) רֹשֶׁם אַחֵר לִשְׁמוֹ וְלִכְבוֹדוֹ. וְזֶה הוּא מִ\"י. בָּרָא אֵלֶּה, וְגַם כֵּן הַשֵּׁם הַקָּדוֹשׁ שֶׁמִּתְבָּרֵךְ שֶׁהוּא מָ\"ה שֶׁנִּרְשַׁם. וְהוֹצִיא מִן בָּרָא אֵבֶר, וְהוּא רָשׁוּם בְּאֵלֶּה מִצַּד זֶה וְאֵבֶר מִצַּד זֶה. הַנִּסְתָּר הַקָּדוֹשׁ. אֵלֶּה עוֹמֵד. אֵבֶר עוֹמֵד. כְּשֶׁנִּשְׁלָם זֶה - נִשְׁלָם זֶה. חוֹקֵק לָאֵבֶר הַזֶּה ה', וְחוֹקֵק לָ\"אֵלֶּה\" הַזֶּה י'."]]],[["אִתְעָרוּ אָתְוָון לְאַשְׁלָמָא לְהַאי סִטְרָא וּלְהַאי סִטְרָא, כְּדֵין אַפִּיק מ\"ם. נָטִיל חַד לְהַאי סִטְרָא וְחַד לְהַאי סִטְרָא, אִשְׁתְּלִים שְׁמָא קַדִּישָׁא וְאִתְעֲבִיד אֱלֹהִים גַּם כֵּן שְׁמָא דְּאַבְרָהָם. כַּד אִשְׁתְּלִים דָּא אִשְׁתְּלִים דָּא. וְיֵשׁ אוֹמְרִים דְּנָטַל קוּדְשָׁא בְּרִיךְ הוּא מִי וְשָׁדֵי בְּאֵלֶּה וְאִתְעֲבִיד אֱלהִים. וְנָטַל קוּדְשָׁא בְּרִיךְ הוּא מַה וְשָׁדֵי בְּאֵבֶר וְאִתְעֲבִיד אַבְרָהָ\"ם. (ומלת מ\"י רומז לחמשים שערי בינה ואית בה יו\"ד אות קדמאה דשמא קדישא. ומלת מ\"ה רומז למנינא דשמא קדישא, ואית ביה אות תניינא דשמא קדישא יהוה. כמא דאת אמר, (תהילים קמ״ד:ט״ו) אשרי העם שככה לו וגו' (איוב כ״ו:ז׳) תולה ארץ על בלי מ\"ה. וכדין אתקיימו תרין עלמין. ביו\"ד עלמא דאתי, ובה\"א עלמא דא. כלומר במ\"י ברא עולם הבא ובמ\"ה ברא עולם הזה. ודין הוא רמז עילא ותתא). וּכְדֵין עָבִיד תּוֹלְדוֹת וְנָפַק שְׁמָא שְׁלִים מַה דְּלָא הֲוָה קֳדָם דְּנָא, הֲדָא הוּא דִכְתִיב אֵלֶּה תּוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, כֻּלְהוּ הֲווּ תַּלְיָין עַד דְּאִתְבְּרֵי שְׁמֵיהּ דְּאַבְרָהָם. כֵּיוָן דְּאִשְׁתְּלִים שְׁמָא דָא דְּאַבְרָהָם, שְׁמָא קַדִּישָׁא אִשְׁתְּלִים. הֲדָא הוּא דִכְתִיב בְּיוֹם עֲשׂוֹת יְיָ אֱלֹהִים אֶרֶץ וְשָׁמָיִם.","אִשְׁתַּטַּח רִבִּי חִיָּיא בְּאַרְעָא וּנְשַׁק לְעַפְרָא, וּבְכָה וְאָמַר עַפְרָא עַפְרָא כַּמָּה אַתְּ קְשֵׁי קְדַל, כַּמָּה אַתְּ בַּחֲצִיפוּ. דְּכָל מַחֲמַדֵּי עֵינָא יִתְבְּלוּן בָּךְ, כָּל עַמּוּדֵי נְהוֹרִין דְּעָלְמָא תֵּיכוּל וְתֵידוּק. כַּמָּה אַתְּ חֲצִיפָא, בּוֹצִינָא קַדִּישָׁא דְּהֲוָה נָהִיר עָלְמָא, שַׁלִּיטָא רַבְרְבָא מְמַנָּא דִּזְכוּתֵיהּ מְקַיֵּים עָלְמָא אִתְבְּלֵי בָּךְ. רִבִּי שִׁמְעוֹן נְהִירוּ דְּבוּצִינָא נְהִירוּ דְּעָלְמִין אַנְתְּ בָּלֵי בְּעַפְרָא וְאַנְתְּ קַיַּים וְנָהֵג עָלְמָא. אִשְׁתּוֹמֵם רִגְעָא חָדָא, וְאָמַר עַפְרָא עַפְרָא לָא תִתְגָּאֵי דְּלָא יִתְמַסְּרוּן בָּךְ עַמּוּדִין דְּעָלְמָא דְּהָא רִבִּי שִׁמְעוֹן לָא אִתְבְּלֵי בָּךְ.","קָם רִבִּי חִיָּיא וְהֲוָה בָּכֵי. אֲזַל וְרִבִּי יוֹסֵי עִמֵּיהּ. מֵהַהוּא יוֹמָא אִתְעַנֵּי אַרְבְּעִין יוֹמִין לְמֶחמֵי לְרִבִּי שִׁמְעוֹן. אָמְרוּ לֵיהּ לֵית אַנְתְּ רַשַּׁאי לְמֶחֱמֵי לֵיהּ. בְּכָה וְאִתְעַנִּי אַרְבְּעִין יוֹמִין אַחֲרִינִין. אַחֲזִיאוּ לֵיהּ בְּחֶזְוָוא לְרִבִּי שִׁמְעוֹן וְרִבִּי אֶלְעָזָר בְּרֵיהּ, דְּהֲווּ לָעָאן בְּמִלָּה דָא דְּאָמַר רִבִּי יוֹסֵי, וְהֲווּ כַּמָּה אַלְפִין צַיְיתִין לְמִלּוּלֵיהּ.","אַדְהָכִי חֲמָא כַּמָּה גַדְפִין רַבְרְבִין עִלָּאִין וּסְלִיקוּ עֲלַייהוּ רִבִּי שִׁמְעוֹן וְרִבִּי אֶלְעָזָר בְּרֵיהּ וּסְלִיקוּ לִמְתִיבְתָּא דִרְקִיעָא, וְכָל אִלֵּין גַּדְפִין הֲווּ מְחַכָּאן לְהוּ. חֲמָא דְמִתְהַדְּרָן וּמִתְחַדְּשָׁן בְּזִיווֹן וּנְהִירוּ יַתִּיר מִנְהוֹרָא דְזִיוָא דְשִׁמְשָׁא.","פָּתַח רִבִּי שִׁמְעוֹן וְאָמַר יִיִעוּל רִבִּי חִיָּיא וְלֶיחמֵי בְּכְּמָה דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְחַדְתָּא אַנְפֵּי צַדִּיקַיָּיא לְזִמְנָא דְּאֲתֵי. זַכָּאָה אִיהוּ מַאן דְּעָאל הָכָא בְּלָא כִסּוּפָא, וְזַכָּאָה מַאן דְּקָאִים בְּהַהוּא עָלְמָא כְּעַמּוּדָא תַּקִּיף בְּכֹלָא. וְחֲמָא דְּהֲוָה עָאל, וְהֲוָה קָם רִבִּי אֶלְעָזָר וּשְׁאָר עַמּוּדִין דְּיָתְבִין תַּמָּן. וְהוּא הֲוָה כְּסִיף וְאַשְׁמִיט גַרְמֵיהּ וְעָאל וְיָתִיב לְרַגְלוֹי דְרִבִּי שִׁמְעוֹן.","קָלָא נָפַק וְאָמַר מָאִיךְ עֵינָךְ. לָא תִזְקוֹף רֵישָׁךְ, וְלָא תִסְתַּכַּל. מָאִיךְ עֵינוֹי וְחֲמָא נְהוֹרָא דְּהֲוָה נָהִיר לְמֵרָחוֹק. קָלָא אַהֲדַר כְּמִלְקַדְּמִין וְאָמַר עִלָּאִין טְמִירִין סְתִימִין פְּקִיחֵי עֵינָא אִנּוּן דִּמְשָׁטְטִין בְּכָל עָלְמָא אִסְתְּכָּלוּ וְחֲמוּ. תַּתָּאִין (נ\"א תנאין) דְּמִיכִין סְתִימִין בְּחוֹרֵיכוֹן אִתְעָרוּ.","מָאן מִנְכוֹן דִּי חֲשׁוֹכָא מְהַפְּכָן לִנְהוֹרָא וְטָעֲמִין מְרִירָא לְמִתְקָא עַד לָא יֵיתוֹן הָכָא. מָאן מִנְּכוֹן דִּמְחַכָּאן בְּכָל יוֹמָא לִנְהוֹרָא דְנָהִיר בְּשַׁעֲתָא דְמַלְכָּא פָּקִיד (ויקהל קצ\"ו ע\"א) לְאַיַּלְתָּא וְאִתְיַיקַר וְאִתְקְרֵי מַלְכָּא מִכָּל מַלְכִין דְּעָלְמָא. מָאן דְּלָא מְצַפֶּה דָא בְּכָל יוֹמָא בְּהַהוּא עָלְמָא, לֵית לֵיהּ חוּלָקָא הָכָא.","אַדְּהָכִי חֲמָא כַּמָּה מִן חַבְרַיָיא סַחֲרָנֵיהּ כָּל אִנּוּן עַמּוּדִין דְּקַיָּימִין. וְחֲמָא דִסְלִיקוּ לוֹן לִמְתִיבְתָּא דִרְקִיעָא. אִלֵּין סַלְקִין וְאִלֵּין נָחֲתִין, וְעֵילָא דְּכוּלְהוּ חֲמָא מָארֵי דְגַדְפֵי דְּהֲוָה אָתֵי","וְהוּא אוֹמֵי אוֹמָאָה דְּשָׁמַע מֵאֲחוֹרֵי פַּרְגּוֹדָא דְּמַלְכָּא מַפְקַד בְּכָל יוֹמָא וּדְכִיר לְאַיַּלְתָּא דִי שְׁכִיבַת לְעַפְרָא, וּבְעַט בְּעִיטִין בְּהַהוּא שַׁעֲתָא בִּתְלַת (שמות מ\"ב) מְאָה וְתִשְׁעִין רְקִיעִין, וְכֻלְהוּ מְרַתְּתִין וְזָעִין קַמֵּיהּ. וְאוֹרִיד דִּמְעִין עַל דָּא, וְנָפְלֵי אִנּוּן דִּמְעִין רְתִיחִין כְּאֶשָׁא לְגוֹ יַמָּא רַבָּא, וּמְאִנּוּן דִּמְעִין קָאִים הַהוּא מְמַנָּא דְיַמָּא וְאִתְקְיַּים וְקָדִישׁ שְׁמֵיהּ דְּמַלְכָּא קַדִּישָׁא וְקָבִּיל עֲלֵיהּ לְמִבְלַע כָּל מֵימוֹי דִּבְרֵאשִׁית וְיִכְנוֹשׁ לְהוּ לְגַוֵּיהּ בְּשַׁעְתָּא דְיִתְכַּנְשׁוּן כָּל עַמְמַיָּא עַל עַמָּא קַדִּישָׁא, וִינַגְבוֹן מַיָּא, וְיַעַבְרוּן בִּנְגִיבוּ."],[[0,"","מח) \u0003אתערו אתוון לאשלמא\u0004 וכו': ומפרש דבריו, כי כאשר התעוררו האותיות, אבר ה' ואותיות אלה י', להשלים לצד זה ולצד זה, אז הוציא אות \u0003ם'\u0004. לקח אחד את ה\u0003ם'\u0004 לצד זה, דהיינו לצד אותיות אלה\"י, ואחד לקח את ה\u0003ם'\u0004 לצד זה, דהיינו לצד האותיות אבר\"ה, ונשלם השם הקדוש ונעשה הצירוף אלקים. ונשלם ג\"כ השם \u0003אברהם\u0004. וזה מ\"ש לעיל, כשנשלם זה נשלם גם זה. ויש אומרים, שלקח הקב\"ה את האותיות \u0003מ\"י\u0004 ונתנן באותיות \u0003אל\"ה\u0004, ונעשה הצירוף \u0003אלקים.\u0004 ולקח הקב\"ה אותיות מ\"ה ונתנן ב\u0003אב\"ר\u0004 ונעשה הצירוף אברהם. והמלה \u0003מ\"י\u0004 רומזת לחמשים שערי בינה, ויש בה במלה מ\"י אות \u0003י'\u0004, שהיא אות ראשונה של השם הקדוש. והמלה \u0003מ\"ה\u0004 רומזת למספר השם הקדוש, כי הויה במילוי אלפין, הוא בגימטריא מ\"ה, ויש בה, במלה מ\"ה, אות השניה של השם הקדוש הויה. שהיא \u0003ה'\u0004. כמ\"ש, אשרי העם וגו' שהויה אלקיו. וכתוב תולה ארץ על בלי\u0003מה\u0004. שרומז על מספר הויה במילוי אלפין, שהוא בגי' \u0003מ\"ה\u0004. ואז נתקיימו ב' עולמות, ב\u0003י'\u0004 העולם הבא, וב\u0003ה'\u0004 העולם הזה (כלומר, ב\u0003מ\"י\u0004 ברא את העולם הבא, ובמ\"ה ברא את העולם הזה. וזהו רומז למעלה ולמטה) ואז עשה תולדות, ויצא השם שלם, מה שלא היה מקודם לכן. זהו שנאמר אלה תולדות השמים והארץ \u0003בהבראם\u0004, שהוא אותיות באברהם, כי כל התולדות היו תלויות בלי שלמות, עד שנברא שמו של \u0003אברהם\u0004. כיון שנשלם השם הזה של אברהם נשלם השם הקדוש. זהו שכתוב, ביום עשות הויה אלקים ארץ ושמים. כי ביום עשות, פירושו ביום שנשלמו, ע\"י השם אברהם, ואז נזכר השם הויה, מה שלא נזכר עד כאן השם הויה בתורה."],[0,"","פירוש, שאלו ב' הקומות: אור חכמה ש\u0003באל\"ה\u0004, ואור החסדים שב\u0003מ\"ה\u0004, נתעוררו להשלים זה על זה, דהיינו להתלבש זה בזה, ואז אחר שנתלבשה החכמה בחסדים \u0003אפיק מ\"ם\u0004 דהיינו המלכות המקבלת מאלו ב' הקומות יחדיו."],[0,"","וז\"ש, \u0003נטיל חד להאי סטרא וחד להאי סטרא אשתלים שמא קדישא ואתעביד אלהים, גם כן שמא דאברהם\u0004: פי' כי נתבאר מקודם, \u0003דגליף להאי אל\"ה\u0004 י', וא\"כ יש עתה ד' אתוון \u0003אלה\"י\u0004. וכן \u0003גליף להאי אב\"ר ה'\u0004, ויש שם ד' אתוון \u0003אבר\"ה\u0004. ונמצא עתה אחר שהשלימו אתוון זו על זו, דהיינו שנתלבשו ב' הקומות חכמה וחסדים זה בזה, ואפיק \u0003מ\"ם\u0004, שהיא המלכות המקבלת מכולם, כנ\"ל. הנה אז \u0003נטיל חד\u0004 אותה \u0003המ\"ם להאי סטרא דידה, וחד נטיל המ\"ם להאי סטרא\u0004 דידיה. \u0003וחד נטיל המ\"ם להאי סטרא\u0004 דידה כי אותיות אלה\"י נטלי ה\u0003ם' אשתלים שמא קדישא ואתעביד אלהים\u0004. וכן אותיות \u0003אבר\"ה\u0004 נטלי את ה\u0003ם'\u0004 ונשלם גם כן \u0003שמא דאברהם\u0004."],[0,"","ו\u0003י\"א דנטיל קב\"ה מ\"י\u0004: מכאן עד המלות, רמז עילא ותתא, המוקפים אינן מדברי הזוהר."],[0,"כיון דאשתלים שמא דא דאברהם שמא קדישא אשתלים","וכו': כי הם ב' קומות חכמה וחסדים הצריכות זו לזו כנ\"ל. וע\"כ לא נשלם \u0003שמא קדישא\u0004 מטרם שנשלם \u0003שמא דאברהם\u0004."],[1,"","מט) \u0003אשתטח ר' חייא\u0004 וכו': השתטח ר' חייא על הארץ, ונשק את העפר, ובכה ואמר, עפר עפר, כמה אתה קשה עורף, כמה אתה בעזות, אשר כל מחמדי העין יהיו בלים בך, כל עמודי האור שבעולם תאכל ותטחון. כמה אתה חצוף, המאור הקדוש שהיה מאיר לעולם, השליט הגדול, הממונה על העולם, שזכותו מקיים את העולם, נבלה בך: רבי שמעון, אור המאור, אור העולמות, אתה בלה בעפר, ואתה קיים ומנהיג את העולם. השתומם רגע אחד, ואמר, עפר עפר, אל תתגאה, כי עמודי העולם לא יהיו נמסרים לך, שהרי רבי שמעון לא נבלה בך."],[1,"","יש להבין היטב ענין ההשתטחות הזאת דר\"ח. והענין הוא כי תמצא במאמר דר\"ח לר' יוסי, שעיקר העסק שלהם בהאי אורחא דאזלי יחד, היה \u0003בהאי תרעא סתים\u0004, שהיא המלכות דמלכות שאינה מקבלת כלום מכל אלו המוחין העלאין שבשתא אלפי שני מטרם גמר התיקון. כמ\"ש מפורש היטב במאמר דר\"ח. ור' יוסי השיב לו בשם ר' שמעון, \u0003דודאי הכי הוא\u0004, שהשער הזה נשאר סתום וכל השלימות היא רק בסוד המפתחא, כנ\"ל. וזה שהציק להם מאד, עד שבא ר' חייא להתעוררות גדולה, \u0003ואשתטח בארעא ונשק לעפרא ובכה ואמר עפרא עפרא כמה את קשי קדל\u0004, וכו'."],[1,"","וז\"ש, \u0003דכל מחמדי עינא יתבלון בך\u0004: כי ע\"י חטאו של אדה\"ר נשרו כל הנשמות ממנו ונפלו בשביה אל הקליפות, שהן כוללות כל הנשמות שבעולם. ואדה\"ר בתשובתו תיקן רק את חלקו בלבד, וגם זה לא בשלימות הגמורה. ואחריו הן הנשמות המתבררות בכל דור ע\"י תשובה ומע\"ט עד גמר התיקון. ונמצא שכל אלו הנשמות הגבוהות מבחינת יחידה וג\"ר דחיה, שהן תלויות בהברור ובהזווג על המלכות דמלכות, שהיא השער הסתום שאין לה בירור וזווג כנ\"ל, הנה כל הנשמות ההן מתבלות בעפרא שהוא הקליפות, וה\"ס דמעת העשוקים ואין להם מנחם (קהלת ד'), כי קליפת העפר שולטת עליהם בחוצפה ובקשיות עורף, בהיותה בטוחה בכחה שאין מי שיוכל להציל אותם מידה. וזה שבכה ר' חייא ואמר לעפרא שהוא הקליפות \u0003כמה את קשי קדל כמה את בחציפו דכל מחמדי עינא יתבלון בך\u0004 כי כל אלו הנשמות הגבוהות מכולם, שהן \u0003מחמדי עינא\u0004 נרקבות בך בלי תקוה להצילן מידך."],[1,"","וז\"ש, \u0003כל עמודי נהורין דעלמא תיכול ותידוק\u0004: היינו כל צדיקי העולם המאירים את העולם, נמצאים גם הם חסרים מהשלמתם מסבת השביה של אלו הנשמות הגבוהות. משום שכל הנשמות כלולות זו מזו. ולפיכך נמצא שגם הם נאכלים ונדקים בכח החוצפה של האי עפרא."],[1,"","וז\"ש, \u0003בוצינא קדישא\u0004 וכו' \u0003ר\"ש לא אתבלי בך\u0004: תחילה רצה לומר שגם ר\"ש אתבלי בהאי עפרא, והוא כי שמע מר' יוסי שגם הוא הסכים ששער זה סתום ואין לגלותו, ואח\"ז תמה ואמר \u0003ר\"ש נהירו דבוצינא\u0004 וכו' \u0003ואנת קיים ונהג עלמא\u0004, כלומר, כיון שהוא המקיים כל העולמות ומנהיג אותם איך אפשר שלא יהיה שלם בכל שלמותו. אח\"ז \u0003אשתומם רגעא חדא\u0004, כלומר, שהתישב בדעתו, ואמר בהחלט \u0003שר\"ש לא אתבלי בך\u0004. כי הוא ודאי בתכלית השלימות אלא שלא יכול להבין האפשרות הזו."],[2,"","נ) \u0003קם רבי חייא\u0004 וכו': קם ר' חייא, והיה הולך ובוכה, ור' יוסי עמו. התענה ארבעים יום מאותו היום, לראות את ר' שמעון. אמרו לו: אינך ראוי לראות אותו. בכה והתענה ארבעים יום אחרים. הראו לו במחזה, את רבי שמעון ורבי אלעזר בנו, שהיו עוסקים במלה זו שאמר ר' יוסי משמו של ר\"ש. לעיל (אות מ\"ה) וכמה אלפים היו מקשיבים לדבריו."],[2,"","פירוש, מתוך מצוקתו על האי שופרא דבלי בעפרא, הנ\"ל, התאוה מאד לראות מדרגתו של ר\"ש. כי החליט לעיל, ש\u0003רבי שמעון לא אתבלי בעפרא. במלה דא דאמר רבי יוסי\u0004: היינו במאמר הנ\"ל שר\"י אמר לר\"ח משמיה דר\"ש. שממנו הגיע לכל התעוררותו זו."],[3,"","נא) \u0003אדהכי חמא כמה\u0004 וכו': בתוך כך, ראה כמה כנפים גדולות ועליונות, ורבי שמעון ורבי אלעזר בנו עלו עליהן, ועלו אל הישיבה של הרקיע. וכל אלו הכנפים היו מחכות להם. ראה, שר\"ש ור\"א, חוזרים ומתחדשים בזיוום, והאירו יותר מאור זיו השמש."],[3,"","פירוש, \u0003מתיבתא דרקיעא\u0004: היינו מתיבתא ד\u0003מט\"ט\u0004. כמ\"ש בזוהר דמתיבתא עלאה היא מתיבתא דקב\"ה. ומתיבתא דרקיעא היא מתיבתא דמט\"ט. (עי' בז\"ח יתרו דל\"ו ע\"א ובז\"ח עם פירוש הסולם הוא ביתרו אות רנה)."],[3,"","וז\"ש, \u0003וכל אלין גדפין הוו מחכאן להו: גדפין\u0004 הם המלאכים המסייעים לנשמות להעלותן ממדרגה למדרגה. וכשם שהנשמה צריכה לסיוע הגדפין אל העליה, כן צריכה לסיוע שלהם להחזרתם למקומה. וז\"ש \u0003שהגדפין הוו מחכאן להו\u0004, דהיינו להחזירן."],[3,"","וז\"ש, \u0003חמא דמתהדרן, ומתחדשן בזיוון\u0004 וכו': ראה אותם חוזרים ממתיבתא דרקיע למקומם, דהיינו למתיבתא דר\"ש. ונתחדשו בזיו אור פניהם והאירו יותר מהאור של השמש."],[4,"","נב) \u0003פתח ר\"ש ואמר\u0004 וכו': פתח ר' שמעון ואמר, יכנס ר' חייא ויראה, בכמה עתיד הקב\"ה לחדש פני הצדיקים לעולם הבא. אשרי הוא, מי שבא לכאן בלי בושה, ואשרי הוא, מי שעומד באותו העולם כעמוד חזק בכל. וראה ר' חייא את עצמו שהיה נכנס, ורבי אלעזר היה קם, וכן שאר עמודי העולם שהיו יושבים שם היו קמים מפני ר' חייא. והוא, ר\"ח, היה מתבייש ונכנס, והשמיט את עצמו וישב למרגלותיו של רבי שמעון."],[4,"","פירוש, ר\"ש רמיז ליה \u0003זכאה איהו מאן דעאל הכא בלא כסופא\u0004. וכן ראה את \u0003ר\"א ושאר עמודין דיתבין תמן, שהיו בלא כסופא\u0004. אבל הוא בעצמו היה ב\u0003כסופא\u0004 מחמת האי שופרא דבלי בעפרא, ואין לו כח להתגבר עליהם, כנ\"ל. וז\"ש \u0003כסיף ואשמיט גרמיה\u0004 וכו'."],[5,"","נג) \u0003קלא נפק ואמר\u0004 וכו': יצא קול ואמר, השפל עיניך, אל תזקוף ראשך, ואל תסתכל. השפיל את עיניו, וראה אור, שהיה מאיר למרחוק. חזר הקול כבתחילה, ואמר, עליונים הנסתרים והסתומים, פקוחי העינים המשוטטות בכל העולם, הסתכלו וראו. תחתונים, הישנים, ואור עיניכם סתום בחורי עיניכם, הקיצו."],[5,"קלא אהדר כמלקדמין","היינו, אחר שציית להשפיל עיניו למטה ולא לזקוף רישיה, זכה לשמוע הכרוז הזה שבגללו השיג כל מבוקשו. כמ\"ש להלן."],[5,"","וז\"ש, \u0003עלאין, טמירין סתימין, פקיחי עינא אינון דמשטטין בכל עלמא, אסתכלו וחמו: תתאין, דמיכין סתימין בחוריכון אתערו\u0004: הכרוז עורר אלו הנשמות, דהוו צייתין למלוליה דר\"ש, דהוו תמן, וגם אלו דלא הוו תמן. והיו בהם ב' כתות כמ\"ש להלן."],[5,"","וז\"ש, \u0003עלאין טמירין\u0004 וכו' \u0003אסתכלו וחמו, תתאין דמיכין\u0004 וכו' \u0003אתערו\u0004: הכרוז יצא לכל נשמות הצדיקים, וחלק אותם לב' כתות: כת א' היא קדישי עליונים \u0003טמירין סתימין\u0004, שזכו לפקיחות עינים ולשוטט בכל עלמא, להם קרא שיסתכלו ויראו, כלומר שימשיכו האורות העליונים, דהיינו בצוותא חדא עם הכת הב', שהיא כל אינון משריין דאזלין מתתרכין בתר קב\"ה ושכינתיה ואזלין מתתרכין משכינתיה, ומכנה אותם \u0003תתאין דמיכין סתימין בחוריכון\u0004 שהם דמיכין ישנים ואור עיניהם סתים בחורי העינים, ולהם קרא שיתעוררו."],[6,"","נד) \u0003מאן מנכון די\u0004 וכו': מי מכם, אשר הפך חשך לאור, והמר יטעם לו כמתוק, עוד מטרם שבא לכאן, דהיינו בעודו בחיים בעולם הזה. מי מכם, אשר בכל יום הוא מצפה לאור, המאיר בשעה שהמלך פוקד את האילה, שאז מתגדל כבוד המלך, ונקרא מלך על כל מלכי העולם. ומי שאינו מצפה לזה בכל יום בעודו באותו העולם, דהיינו בעולם הזה, אין לו חלק כאן."],[6,"","פירוש, הכרוז מדגיש לכל כתה את עיקר המעלה הרצויה בכל אחת מהן: למעלת הכתה הא' אומר, \u0003מאן מנכון די חשוכא מהפכן לנהורא, וטעמין מרירא למתקא\u0004. והם הנשמות דאצילות. כי בבי\"ע, זה לעומת זה עשה אלהים, חושך לעומת אור, ומר לעומת מתוק. ולפיכך באורייתא דבי\"ע יש כשר ופסול, טמא וטהור, איסור והתר, קודש וחול. משא\"כ באורייתא דאצילות שם כל התורה כולה שמותיו של הקב\"ה ואין ח\"ו שום חול שם. כי שם נבחן, לבן הארמי לשם קדוש, וכן פרעה וכל השמות, שבבי\"ע הם קליפות וטומאה, המה שמה רק שמות קדושים נשגבים. ונמצא שאלו הנשמות שזכו לאור האצילות, מהפכות כל חושך להיות אור, וכל מר למתוק."],[6,"","ולמעלת כתה ב' אמר \u0003מאן מנכון דמחכאן בכל יומא לנהורא דנהיר בשעתא דמלכא פקיד לאילתא\u0004 וכו' \u0003מאן דלא מצפה דא בכל יומא בההוא עלמא לית ליה חולקא הכא\u0004, דהיינו אלו דמנדדין אחר שכינתא דיתבא בדד, ומצפין תמיד לקב\"ה דיוקים שכינתא מעפרא. אבל לאחרים זולתם \u0003לית ליה חולקא הכא\u0004."],[7,"","נה) \u0003אדהכי חמא כמה\u0004 וכו': בתוך כך ראה הרבה מן החברים מסביב כל העמודים העומדים, וראה שמעלים אותם לישיבה של הרקיע, אלו עולים ואלו יורדים, ולמעלה מכולם, ראה את בעל הכנפים, שהוא מטטרון, שהיה בא."],[7,"","פירוש. בעוד שהכרוז קרא, הוא ראה כמה מן הנשמות הצדיקים השייכות לאותן ב' כתות הנ\"ל, מסביב \u0003כל אינון עמודין דקיימין\u0004, הן נשמות הצדיקים שכבר היו ב\u0003מתיבתא דרבי שמעון\u0004 וראה אותן עולות \u0003למתיבתא דרקיע\u0004, מהן עלו ומהן ירדו. כי כתה א' עלתה וכתה ב' ירדה וז\"ש \u0003אלין סלקין ואלין נחתין\u0004. כי כן הם מסייעין זל\"ז, כפי קריאת הכרוז, שלכתה א' אמר \u0003אסתכלו וחמו\u0004 ולכתה ב' אמר \u0003אתערו\u0004."],[7,"","וראה כי מהתעוררותן של כל אלו הנשמות, דהיינו מכח ב' כתות יחד, ירד \u0003מט\"ט\u0004 ממתיבתא דיליה למתיבתא דר\"ש ונשבע השבועה דלקמן וז\"ש \u0003ועילא דכלהו, חמא מארי דגדפי דהוה אתי והוא אומי אומאה כי ועילא דכלהו\u0004 פירושו, כמו מכח כולם. \u0003ומארי דגדפי\u0004, הוא מט\"ט."],[8,"","נו) \u0003והוא אומי אומאה\u0004 וכו': והוא, המלאך מטטרון, נשבע שבועה, ששמע מאחורי המסך, שהמלך מפקד בכל יום וזוכר את האילה השוכבת לעפר, ובאותה שעה בועט בעיטות בשלש מאות ותשעים רקיעים, וכולם חרדים ונבהלים מלפניו. והוא, המלך, מוריד דמעות על זה, שהשכינה בעפר, והדמעות, הרותחות כאש, נופלות לתוך הים הגדול. ומכח הדמעות האלו עומד ומתקיים אותו הממונה שעל הים, שנקרא רהב, ומקדש את שם המלך הקדוש, ומקבל עליו, לבלוע כל מימי בראשית, ויאספם לתוכו, בשעה שכל העמים יתאספו על העם הקדוש, והמים יתיבשו, ויעברו ביבשה."],[8,"","פירוש. הוא נשבע שבועה, שהמלך פוקד וזוכר בכל יום \u0003לאילתא די שכיבת לעפרא\u0004, שהיא השכינה הקדושה. אמנם אין הכוונה על כללות השכינה הק', כי על זה לא היה צריך לישבע השבועה, כי דבר גלוי לכל הוא אלא הכוונה היא על מלכות דמלכות, דסבר ר' חייא שהיא שבויה בין הקליפות, ונעזבה לגמרי, ש\u0003בכה ואמר עפרא עפרא\u0004 וכו' \u0003דכל מחמדי עינא יתבלון בך\u0004 וכו'. ולפיכך היא מכונה \u0003אילתא די שכיבת לעפרא\u0004, וכאן נגלה לו לר' חייא הסוד הגדול הזה ע\"י מט\"ט שבא למתיבתא דר\"ש, כי \u0003מלכא מפקד בכל יומא ודכיר לאילתא די שכיבת לעפרא\u0004. אלא באותו הדרך שמט\"ט הולך ומבאר לפנינו."],[8,"","וז\"ש, \u0003ובעט בעיטין בההוא שעתא בתלת מאה ותשעין רקיעין\u0004 וכו': הזווג דהכאה של האור העליון על המסך נבחן שהאור העליון \u0003בעט בעיטין\u0004 במסך, כלומר, שהאור העליון בועט ורוצה להכנס למטה מהגבול שבמסך, והמסך מעכב אותו ומחזיר את האור העליון לאחוריו, שהחזרה זו, ה\"ס או\"ח העולה מהמסך ממטה למעלה ומלביש את האור העליון. וענין זה כבר נתבאר היטב (בהפתיחה לחכמת הקבלה דף ד' אות י\"ד עש\"ה)."],[8,"","וענין \u0003תלת מאה ותשעין רקיעין\u0004 הוא, כי המסך נק' רקיע המבדיל, והוא כולל בתוכו ד' בחינות, שהן חו\"ב תו\"מ, שהן ד' אותיות הוי\"ה. ומתוך שהמלכות נמתקת בבינה, נמצא המסך בבחינת בינה, כנ\"ל, וספירת הבינה מרומזת במאות, כנודע. ונמצא שאלו ד' הבחינות שבמסך: חו\"ב תו\"מ עולות לד' מאות, אמנם נתבאר לעיל, שעל המלכות דה\"ת אין זווג נעשה עליה, כי ה\"ס השער הסתום, ולפיכך נבחנת בהמאה דספירת המלכות, שהיא ה\"ת, שחסרה שם עשר של המלכות דמלכות, ואין בה אלא ט\"ס ראשונות שעולות לתשעים. וזהו הרמז, שבמסך הנק' רקיע, שהאור העליון מזדווג עליו בזווג דהכאה, שהיא בעיטה, אין שם ד' מאות, אלא ש\"צ, וחסרה י', שהיא מלכות דמלכות. וע\"כ מכונה הרקיע בשם ש\"צ רקיעין, וז\"ש \u0003בעט בעיטין, בתלת מאה ותשעין רקיעין\u0004, בכל יומא, בעת הזווג עם שכינתיה. דהיינו לאפוקי מה\u0003אילתא די שכיבת לעפרא\u0004, שמבחינת הזווג הזה היא חסרה שם, כי היא סוד העשר החסרות מארבע מאות."],[8,"וכלהו מרתתין וזעין קמיה",": סוד הכאת המסך באור העליון הוא בסוד רתת וזיע, דהיינו מתוך יראה שלא יקבל יותר מגבולו."],[8,"","וז\"ש, \u0003ואוריד דמעין על דא\u0004: המוחין דקומת חכמה מכונים עינים, כי ה' הספירות דראש נק' גלגלתא, עינים, ואח\"פ. וכמו שאלו הטפות שהעינים פולטות אותן מהן ולחוץ. נק' דמעות, כן אלו הטפות שקומת חכמה פולטתן ממנה ולחוץ מכונות דמעות. וענין פליטת טפין אלו, הוא כי נתבאר לעיל בסמוך (בד\"ה בעט בעיטין), בסוד הזווג דהכאה, כי האור העליון הנמשך לתחתון ופוגע במסך הוא בועט ומכה בו, שפירושו שרוצה להמשך למטה מהגבול שבמסך, אלא שתיכף ומיד המסך מתחזק עליו ודוחה אותו לאחוריו, כי אינו נותן לו לעבור גבולו, ע\"ש."],[8,"","אמנם בינתיים, היינו מטרם שהמסך דחה אותו לאחוריו, היו נמשכות בהכרח איזה טפות קטנות מאד, מהאור העליון, למטה מגבולו של המסך, שהמסך עם כל זריזותו לא הספיק לדחותן ממנו ולמעלה. ותדע, שאלו הטפות לא תוכלנה להכלל בקומת החכמה שיצאה בתחתון, להיותן בלי לבוש של או\"ח, והן נפלטות ויוצאות לחוץ מן פרצוף החכמה, והן המכונות דמעות."],[8,"","וז\"ס שבעת שהאדם הגשמי מתמלא רחמים ואהבה על חבירו הוא מוריד דמעות מעיניו, כי זה נמשך משורש הדמעות הרוחניות האמורות, כי כל דבר רוחני הנוהג בעליונים מכה ומוציא לו ענף בבריות הגשמיות כנודע. כי מה שהאור העליון בועט ומכה על המסך לעבור גבולו, הוא משום שהאור העליון נמשך תמיד רק מא\"ס ב\"ה שלמעלה מעולם הצמצום, שאינו נבחן שם שום גבול ח\"ו."],[8,"","ומתוך שהאור העליון חושק ומתאוה להתפשט, ע\"ד שאמרו חז\"ל נתאוה הקב\"ה לדור בתחתונים, וכן שכינה בתחתונים צורך גבוה. ע\"כ, הוא בועט ומכה על הגבול שבמסך להמשך למטה מגבולו והמסך מחזירו לאחוריו בסוד או\"ח. אשר בינתיים נפלטו דמעות לחוץ כנ\"ל. הרי שהדמעות האלו באו מתוך הרחמים והאהבה אל התחתון. ולכן גם בענף הגשמי נפלטו תמיד דמעות בעת שמעיו הומים ומתעוררים באהבה וברחמים על חבירו. אבל הדמעות הרוחניות אינן נאבדות כמו הגשמיות, כמ\"ש להלן."],[8,"","וז\"ש, \u0003ונפלי אינון דמעין רתיחין כאשא לגו ימא רבא\u0004: וה\"ס הכתוב, כי עזה כמות אהבה קשה כשאול קנאה רשפיה רשפי אש שלהבת יה (שה\"ש ח'), כי נתבאר שאלו הדמעות באות מתוך רחמים ואהבה מהאור העליון אל התחתון. וכמו שתמצא בענף הגשמי בעת שהאדם נכמרו מעיו באהבה ורחמים על חבירו נמצאות הדמעות רותחות כפי מדת כמידת מעיו עליו. כן הוא בדמעות האמורות שהן רותחות מאד כאש, בסוד רשפיה רשפי אש שלהבת י\"ה. וזה אמרו \u0003דמעין רתיחין כאשא לגו ימא רבא\u0004 ומדת המלכות מצד החכמה נק' \u0003ימא רבא\u0004, כי ממנה נמשכים מים רבים אדירים משברי ים."],[8,"","וז\"ש, \u0003ומאינון דמעין קאים ההוא ממנא דומא ואתקיים\u0004: היינו אותו השר של הים שנהרג בעת בריאת העולם. כמ\"ש חז\"ל (ב\"ב ע\"ד) על הפסוק ובתבונתו מחץ רהב, שבעת שנאמר לו יקוו המים אל מקום אחד (בראשית א'). לא רצה לבלוע מימי בראשית, ואומר, שמאלו הדמעות הנופלות \u0003לימא רבא\u0004, הוא \u0003קאים ואתקיים\u0004, שהולך ע\"י ושב לתחיה."],[8,"","וז\"ש, \u0003וקדיש שמיה דמלכא קדישא וקביל עליה למבלע כל מימוי דבראשית\u0004: כי בעת בריאת העולם לא הגיע שום תיקון אל המלכות דמלכות, כי המאציל תיקן את העולמות אבי\"ע בסוד מ\"ן דבינה, ולא במ\"ן דמלכות שזה הספיק רק לט\"ר דמלכות ולא למלכות דמלכות, כנ\"ל."],[8,"","וז\"ס מ\"ש חז\"ל על הפסוק עמי אתה (ישעיה נא), עמי אתם בשותפות, אני התחלתי העולמות ואתם גומרים אותם כי המלכות דמלכות כל תיקונה מוטל רק על התחתונים. ולפיכך כשנאמר לו לשר הים, יקוו המים אל מקום אחד (בראשית א'), סירב ולא רצה לבלוע כל מימי בראשית, כי הקליפות היו גוברות עליו מחמת חסרון התיקון של המלכות דמלכות, וע\"כ נהרג. אמנם אלו הדמעות הנ\"ל, הן המבררות והמתקנות את המלכות דמלכות, וע\"כ נותנות חיות לשרו של ים, שיוכל לעמוד \u0003לקדש שמיה דמלכא קדישא\u0004, דהיינו לקיים ציוויה דמאריה \u0003ולמבלע כל מימוי דבראשית\u0004, כי אז תתבטלנה כל הקליפות שבעולם, וכל כחות הרשע, ויקוו כולם אל מקום אחד, שה\"ס אצילות, כי עולם האצילות יתפשט בשוה עם רגלי א\"ק עד לעולם הזה, ויהיה גמר התיקון, כי ישוב הבי\"ע להיות אצילות. וז\"ש \u0003ומאינון דמעין קאים ההוא ממנא דימא ואתקיים וקדיש שמיה דמלכא קדישא, וקביל עליה למבלע כל מימוי דבראשית\u0004."],[8,"","וז\"ש, \u0003בשעתא דיתכנשון כל עממיא על עמא קדישא\u0004: כי זה יהיה לעתיד בגמר התיקון, שאז כל אומות העולם תתקבצנה בבת אחת להשמיד את ישראל ח\"ו, ואז יתגלה זה, ששרו של ים יבלע כל \u0003מימוי דבראשית. וינגבון מיא ויעברון בנגיבו\u0004, שיתיבשו המים וב\"י יעברו ביבשה. שז\"ס כימי צאתך מארץ מצרים אראנו נפלאות (מיכה ז'). אבל אז היתה רק התחלה, כי לא היה אלא בים סוף, ורק לשעתו, אבל בגמר התיקון יבולע המות לנצח."],[8,"","ובזה, ביאר מט\"ט היטב את השבועה שלו, שנשבע, \u0003דמלכא מפקד בכל יומא ודכיר לאילתא די שכיבת לעפרא\u0004, כי הגם שהזווג שעושה בכל יום עם שכינתיה, הוא רק בבחי' \u0003ש\"צ רקיעין\u0004, שהוא רק בט\"ר דמלכות, והמלכות דמלכות נשארה \u0003שכיבת בעפרא\u0004, שנדמה לנו, שאין המלך זוכר אותה כלל, הנה אינו כן, אלא שפוקד אותה עם כל זווג וזווג, כי בכל זווג נפלטות דמעות לחוץ מכח הבעיטין דבעיט בש\"צ רקיעין, ואינן נאבדות אלא נופלות \u0003לימא רבא\u0004 שה\"ס המלכות דמלכות הנ\"ל, המקבלת תיקונה ע\"י הדמעות הללו לאט לאט, שבשיעור הזה הולך וקם לתחיה שרו של ים, עד שמתקבצות הדמעות לשיעורן המספיק לברר המלכות כולה, שזה יהיה בעת שתתקבצנה כל האומות שבעולם בבת אחת על ישראל, ואז יקום שרו של ים לתחיה ויבלע כל \u0003מימוי דבראשית\u0004 כי המלכות דמלכות תקבל תיקונה משלם. הרי שהמלך פוקד ל\u0003אילתא\u0004 בכל יום ויום, עד שתקבל תיקונה משלם. וכאן נגלו לרבי חייא כל משאלותיו, כי ראה ששום דבר אינו מתבלה ח\"ו בעפרא אלא להיפך, שיש עליו זווג בכל יום ויום, כמו שנשבע לו מט\"ט."]],[[0,"","מִתְעוֹרְרוֹת הָאוֹתִיּוֹת לְהַשְׁלִים אֶת הַצַּד הַזֶּה וְאֶת הַצַּד הַזֶּה, וְאָז מוֹצִיא מֵ\"ם. נוֹטֵל אֶחָד לַצַּד הַזֶּה וְאֶחָד לַצַּד הַזֶּה. נִשְׁלָם הַשֵּׁם הַקָּדוֹשׁ וְנַעֲשֶׂה אֱלֹהִים גַּם כֵּן הַשֵּׁם שֶׁל אַבְרָהָם. כְּשֶׁנִּשְׁלָם זֶה - נִשְׁלָם זֶה. וְיִשִׁ אוֹמְרִים שֶׁנָּטַל הַקָּדוֹשׁ- בָּרוּךְ-הוּא מִ\"י וְזָרַק בְּאֵלֶּה וְנַעֲשָׂה אֱלֹהִים. וְנָטַל הַקָּדוֹשׁ- בָּרוּךְ-הוּא מָ\"ה וְזָרַק בְּאֵבָר וְנַעֲשָׂה אַבְרָהָם. (ומלת מ\"י רומזת לחמשים שערי בינה, ויש בה יו\"ד, האות הראשונה של השם הקדוש. ומלת מ\"ה רומזת למנין השם הקדוש, ויש בה האות השניה של השם הקדוש יהו\"ה, כמו שגאמר (תהלים קמד) אשרי העם שככה לו וגו', (איוב כו) תולה ארץ על בלי מ\"ה. ואז התקימו שני עולמות. ביו\"ד העולם הבא, ובה\"א העולם הזה. כלומר במ\"י ברא את העולם הבא, ובמ\"ה ברא את העולם הזה. וזהו רמז מעלה ומטה). וְאָז עָשָׂה תוֹלָדוֹת וְיָצָא שֵׁם שָׁלֵם מַה שֶּׁלֹּא הָיָה מִקֹּדֶם לָכֵן. זֶהוּ שֶׁכָּתוּב (בראשית ב) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם. כֻּלָּם הָיוּ תְלוּיִם עַד שֶׁנִּבְרָא שְׁמוֹ שֶׁל אַבְרָהָם. כֵּיוָן שֶׁנִּשְׁלַם הַשֵּׁם הַזֶּה שֶׁל אַבְרָהָם, נִשְׁלַם הַשֵּׁם הַקָּדוֹשׁ. זֶהוּ שֶׁכָּתוּב בְּיוֹם עֲשׂוֹת ה' אֱלֹהִים אֶרֶץ וְשָׁמָיִם."],[1,"","הִשְׁתַּטַח רַבִּי חִיָּיא בָּאָרֶץ וְנִשֵּׁק אֶת הֶעָפָר, וּבָכָה וְאָמַר: עָפָר, עָפָר, כַּמָּה אַתָּה קְשֵׁה עֹרֶף, כַּמָּה אַתָּה בְּחֻצְפָּה, שֶׁכָּל מַחְמַדֵּי הָעַיִן יִרְקְבוּ בְךְ, כָּל עַמּוּדֵי אוֹרוֹת הָעוֹלָם תֹּאכַל וְתִשְׁחָק. כַּמָּה אַתָּה חָצוּף, הַמָּאוֹר הַקָּדוֹשׁ (רשב\"י) שֶׁהָיָה מֵאִיר אֶת הָעוֹלָם, הַשַּׁלִּיט הַגָּדוֹל שֶׁמְּמֻנֶּה, שֶׁזְּכוּתוֹ מַעֲמִידָה אֶת הָעוֹלָם, יִרְקַב בְּךְ. רַבִּי שִׁמְעוֹן, אוֹר הַמָּאוֹר, אוֹר הָעוֹלָמוֹת, אַתָּה נִרְקָב בֶּעָפָר וְאַתָּה מְקַיֵּם וּמַנְהִיג אֶת הָעוֹלָם. הִשְׁתּוֹמֵם רֶגַע אֶחָד, וְאָמַר: עָפָר, עָפָר, אַל תִּתְגָּאֶה, שֶׁלֹּא יִמָּסְרוּ בְךְ עַמּוּדֵי הָעוֹלָם, שֶׁהֲרֵי רַבִּי שִׁמְעוֹן לֹא יֵרָקֵב בְּךְ."],[2,"","קָם רַבִּי חִיָּיא וְהָיָה בוֹכֶה. הָלַךְ וְרַבִּי יוֹסֵי עִמּוֹ. מֵאוֹתוֹ הַיּוֹם הִתְעַנָּה אַרְבָּעִים יָמִים לִרְאוֹת אֶת רַבִּי שִׁמְעוֹן. אָמְרוּ לוֹ, אֵינְךְ רַשַּׁאי לִרְאוֹת אוֹתוֹ. בָּכָה וְהִתְעַנָּה אַרְבָּעִים יָמִים אֲחֵרִים, הֶרְאוּ לוֹ בַּמַּחֲזֶה אֶת רַבִּי שִׁמְעוֹן וְרַבִּי אֶלְעָזָר בְּנוֹ שֶׁהָיוּ עוֹסְקִים בַּדָּבָר הַזֶּה שֶׁאָמַר רַבִּי יוֹסֵי, וְהָיוּ כַּמָּה אֲלָפִים שׁוֹמְעִים לְדִבּוּרוֹ."],[3,"","בֵּינְתַיִם רָאָה כַּמָּה כְנָפַיִם גְּדוֹלוֹת עֶלְיוֹנוֹת, וּמַעֲלִים עֲלֵיהֶם אֶת רַבִּי שִׁמְעוֹן וְאֶת רַבִּי אֶלְעָזָר בְּנוֹ, וְעוֹלִים לִישִׁיבַת הָרָקִיעַ, וְכָל אֵלּוּ הַכְּנָפַיִם הָיוּ מְחַכּוֹת לָהֶם. רָאָה שֶׁחוֹזְרִים וּמִתְחַדְּשִׁים וּמְאִירִים יוֹתֵר מֵהָאוֹר שֶׁל זִיו הַשֶּׁמֶשׁ."],[4,"","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, יִכָּנֵס רַבִּי חִיָּיא וְיִרְאֶה בְּמַה שֶּׁעָתִיד הַקָּדוֹשׁ-בָּרוּךְ-הוּא לְחַדֵּשׁ אֶת פְּנֵי הַצַּדִּיקִים לֶעָתִיד לָבא. אַשְׁרֵי הוּא מִי שֶׁנִּכְנָס לְכָאן בְּלִי בוּשָׁה, וְאַשְׁרֵי מִי שֶׁעוֹמֵד בְּאוֹתוֹ הָעוֹלָם כְּעַמּוּד חָזָק בַּכֹּל. וְרָאָה שֶׁהָיָה נִכְנָס וְעוֹמֵד רַבִּי אֶלְעָזָר, וּשְׁאָר הָעַמּוּדִים שֶׁיּוֹשְׁבִים שָׁם. וְהוּא הָיָה מִתְבַּיֵּשׁ, וְהִשְׁמִיט אֶת עַצְמוֹ, וְנִכְנַס וְיָשַׁב לְרַגְלֵי רַבִּי שִׁמְעוֹן."],[5,"","יָצָא קוֹל וְאָמַר: הַנְמֵךְ עֵינֶיךְ וְאַל תָּרִים רֹאשְׁךְ וְאַל תִּסְתַּכֵּל. הִנְמִיךְ עֵינָיו וְרָאָה אוֹר שֶׁמֵּאִיר לְמֵרָחוֹק. חָזַר הַקּוֹל כְּמִקֹּדֶם וְאָמַר: עֶלְיוֹנִים טְמוּנִים נִסְתָּרִים, פְּקוּחֵי הָעַיִן, אוֹתָם שֶׁמְּשׁוֹטְטִים בְּכָל הָעוֹלָם, הִסְתַּכְּלוּ וּרְאוּ! תַּחְתּוֹנִים (נ\"א: תנאים) יְשֵׁנִים נִסְתָּרִים בְּחוֹרֵיכֶם הִתְעוֹרְרוּ!"],[6,"","מִי מִכֶּם שֶׁהוֹפְכִים חֹשֶׁךְ לְאוֹר וְטוֹעֲמִים מַר לְמָתוֹק טֶרֶם בּוֹאָם לְכָאן מִי מִכֶּם שֶׁמְּחַכִּים בְּכָל יוֹם לָאוֹר שֶׁמֵּאִיר בְּשָׁעָה שֶׁהַמֶּלֶךְ פּוֹקֵד אֶת הָאַיָּלָה, וּמִתְכַּבֵּד וְנִקְרָא מֶלֶךְ מִכָּל מַלְכֵי הָעוֹלָם מִי שֶׁלֹּא מְצַפֶּה לָזֶה בְּכָל יוֹם בְּאוֹתוֹ הָעוֹלָם - אֵין לוֹ כָּאן חֵלֶק!"],[7,"","בֵּינְתַיִם רָאָה כַּמָּה מִן הַחֲבֵרִים סְבִיבוֹ, כָּל אוֹתָם הָעַמּוּדִים שֶׁקַּיָּמִים, וְרָאָה שֶׁמַּעֲלִים אוֹתָם לִישִׁיבַת הָרָקִיעַ. אֵלּוּ עוֹלִים וְאֵלּוּ יוֹרְדִים. וּמֵעַל כֻּלָּם רָאָה בַּעַל הַכְּנָפַיִם שֶׁהָיָה בָּא,"],[8,"","וְהוּא נִשְׁבַּע שְׁבוּעָה שֶׁשָּׁמַע מֵאֲחוֹרֵי הַפַּרְגּוֹד, שֶׁהַמֶּלֶךְ פּוֹקֵד בְּכָל יוֹם וְזוֹכֵר אֶת הָאַיָּלָה שֶׁשּׁוֹכֶבֶת לֶעָפָר, וּבוֹעֵט בְּעִיטוֹת בְּאוֹתָהּ שָׁעָה בִּשְׁלֹשׁ מֵאוֹת וְתִשְׁעִים רְקִיעִים, וְכֻלָּם מְפַחֲדִים וְרוֹעֲדִים לְפָנָיו. וּמוֹרִיד עַל זֶה דְּמָעוֹת, וְנוֹפְלוֹת אוֹתָן הַדְּמָעוֹת הָרוֹתְחוֹת כָּאֵשׁ לְתוֹךְ הַיָּם הַגָּדוֹל, וּמֵאוֹתָן הַדְּמָעוֹת עוֹמֵד אוֹתוֹ הַמְמֻנֶּה שֶׁל הַיָּם, וּמִתְקַיֵּם וּמְקַדֵּשׁ אֶת שְׁמוֹ שֶׁל הַמֶּלֶךְ הַקָּדוֹשׁ, וּמְקַבֵּל עָלָיו לִבְלֹעַ אֶת כָּל מֵימֵי בְרֵאשִׁית וְכוֹנֵס אוֹתָם לְתוֹכוֹ בְּשָׁעָה שֶׁיִּתְקַבְּצוּ כָּל הָעַמִּים עַל הָעָם הַקָּדוֹשׁ, וְיִתְיַבְּשׁוּ הַמַּיִם, וְיַעַבְרוּ בְיֹבֶשׁ."]]],[["אַדְהָכִי שָׁמַע קָלָא דְּאָמַר פַּנּוּן אֲתַר, פַּנּוּן אֲתַר דְּהָא מַלְכָּא מְשִׁיחָא אָתֵי לִמְתִיבְתָּא דְרִבִּי שִׁמְעוֹן בְּגִין דְּכָל צַדִּיקַיָּיא דְּתַמָּן רֵישֵׁי מְתִיבְתָּא וְאִנּוּן מְתִיבְתֵּי דְתַמָּן רְשִׁימִין אִנּוּן. וְכָל אִנּוּן חַבְרִין דִּי בְּכָל מְתִיבְתָּא סַלְקֵי (סלקין) מִמְּתִיבְתָּא דְּהָכָא לִמְתִיבְתָּא דִרְקִיעָא. וּמָשִׁיחַ אָתֵי בְּכָל אִנּוּן מְתִיבְתֵּי וְחָתִים אוֹרַיְיתָא מִפּוּמַיְיהוּ דְרַבָּנָן. וּבְהַהִיא שַׁעֲתָא אָתֵי מָשִׁיחַ מִתְעַטֵּר מִן (נ\"א רישי) רֵיחֵי מְתִיבְתֵּי בְּעִטְרִין עִלָּאִין.","בְּהַהוּא שַׁעֲתָא קָמוּ כָּל אִנּוּן חַבְרַיָיא וְקָם רִבִּי שִׁמְעוֹן וְהֲוָה סָלִיק נְהוֹרֵיהּ עַד רוּם רָקִיעַ, אָמַר לֵיהּ רִבִּי זַכָּאָה אַנְתְּ דְּאוֹרַיְיתָךְ סָלְקָא בִּתְלַת מְאָה וְשִׁבְעִין נְהוֹרִין, וְכָל נְהוֹרָא וּנְהוֹרָא אִתְפַּרְשַׁת לְשִׁית מְאָה וּתְלֵיסַר טַעֲמִין סָלְקִין וְאִסְתַחְיָין בְּנַהֲרֵי אֲפַרְסְמוֹנָא דַכְיָא. וְקוּדְשָׁא בְּרִיךְ הוּא אִיהוּ חָתִים אוֹרַיְיתָא מִמְּתִיבְתָּךְ וּמִמְתִיבְתָּא דְּחִזְקִיָּה מֶלֶךְ יְהוּדָה וּמִגּוֹ מְתִיבְתָּא דְּאֲחִיָּה הַשִּׁילוֹנִי.","וְאֲנָא לָא אָתֵינָא לְמִחְתַּם מִמְתִיבְתָּךְ, אֶלָא) מָארֵי דְגַדְפִין אָתֵי הָכָא, דְּהָא יְדַעְנָא דְלָא יֵיעוּל גּוֹ מְתִיבְתֵּי אַחְרִיתִּי אֶלָּא בִּמְתִיבְתָּךְ. בְּהַהִיא שַׁעֲתָא סָח לֵיהּ רִבִּי שִׁמְעוֹן הַהוּא אוֹמָאָה דְּאוֹמֵי מָארֵי דְגַדְּפִין. כְּדֵין אִזְדַּעְזַע מָשִׁיחַ וְאָרִים קָלֵיהּ וְאִזְדַּעְזְעוּ רְקִיעִין וְאִזְדַּעְזַע יַמָּא רַבָּא וְאִזְדַּעְזַע לִוְיָתָן וְחָשִׁיב עָלְמָא לְאִתְהַפְּכָא. אַדְהָכִי חָמָא לְרִבִּי חִיָּיא לְרַגְלוֹי דְרִבִּי שִׁמְעוֹן. אָמַר מָאן יָהִיב הָכָא בַּר נָשׁ לָבִישׁ מַדָּא דְהַהוּא עָלְמָא. אָמַר (ליה) רִבִּי שִׁמְעוֹן דָּא אִיהוּ רִבִּי חִיָּיא נְהִירוּ דְבוּצִינָא דְאוֹרַיְיתָא. אָמַר לֵיהּ יִתְכַּנֵּשׁ הוּא וּבְנוֹי וְלֶיהֱווֹן מִמְתִיבְתָּא דִילָךְ. אָמַר רִבִּי שִׁמְעוֹן זִמְנָא יִתְיְיהִיב לֵיהּ.","יָהֲבוּ לֵיהּ זִמְנָא וְנָפַק מִתַּמָּן מִזְדַּעְזַע וְזָלְגָן עֵינוֹי דִמְעִין. אִזְדַּעְזַע רִבִּי חִיָּיא וּבְכָה וְאָמַר זַכָּאָה חוּלַקְהוֹן דְּצַדִּיקַיָיא בְּהַהוּא עָלְמָא, וְזַכָּאָה חוּלָקֵיהּ דְּבַר יוֹחָאי דְּזָכָה לְכָךְ. עֲלֵיהּ כְּתִיב, (משלי ח׳:כ״א) לְהַנְחִיל אוֹהֲבַי יֵשׁ וְאוֹצְרוֹתֵיהֶם אֲמַלֵּא.","בְּרֵאשִׁית רִבִּי שִׁמְעוֹן פָּתַח (ישעיהו נ״א:ט״ז) וָאָשִׂים דְּבָרַי בְּפִיךָ. כַּמָּה אִית לֵיהּ לְבַר נָשׁ לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא יְמָמָא וְלֵילְיָא, בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא צַיִּית לְקָלְהוֹן דְּאִנּוּן דְּמִתְעַסְּקֵי בְּאוֹרַיְיתָא, וּבְכָל מִלָּה דְאִתְחַדָּשׁ בְּאוֹרַיְיתָא עַל יְדָא דְהַהוּא דְּאִשְׁתַּדַּל בְּאוֹרַיְתָא, עָבִיד רְקִיעָא חָדָא.","תְּנַן בְּהַהִיא שַׁעֲתָא דְּמִלָּה דְּאוֹרַיְיתָא אִתְחַדְּשַׁת מִפּוּמֵיהּ דְּבַר נָשׁ, הַהִיא מִלָּה סַלְקָא וְאִתְעַתְּדַת קַמֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא. וְקוּדְשָׁא בְּרִיךְ הוּא נָטִיל לְהַהִיא מִלָּה וְנָשִׁיק לָהּ וְעַטַּר לָהּ בְּשִׁבְעִין עִטְרִין גְּלִיפִין וּמְחַקְּקָן. וּמִלָּה דְּחָכְמְתָא דְּאִתְחַדְּשָׁא, סַלְקָא וְיַתְבָא עַל רֵישָׁא דְּצַדִּיק חַי עַלְמִין. וְטָסָא מִתַּמָּן וְשָׁטָא בְּשִׁבְעִין אֶלֶף עַלְמִין וּסְלִיקַת לְגַבֵּי עַתִּיק יוֹמִין. וְכָל מִלִּין דְּעַתִּיק יוֹמִין מִלִּין דְּחָכְמְתָא אִנּוּן בְּרָזִין סְתִימִין עִלָּאִין.","וְהַהִיא מִלָּה סְתִימָא דְחָכְמְתָא דְּאִתְחַדְּשַׁת הָכָא כַּד סַלְקָא אִתְחַבְּרַת בְּאִנּוּן מִלִּין (דרזין) דְּעַתִּיק יוֹמִין וְסַלְקָא וְנַחְתָא בַּהֲדַיְיהוּ וְעָאלַת בְּתַמְנֵיסַר עָלְמִין גְּנִיזִין (ישעיהו ס״ד:ג׳) דְּעַיִן לא רָאֲתָה אֱלהִים זוּלָתֶךָ. נַפְקֵי מִתַּמָּן וְשָׁטָאן וְאַתְיָין מְלֵיאָן וּשְׁלֵמִין וְאִתְעַתָּדוּ קַמֵּי עַתִּיק יוֹמִין. בְּהַהִיא שַׁעֲתָא אָרַח עַתִּיק יוֹמִין בְּהַאי מִלָּה וְנִיחָא קַמֵּיהּ מִכֹּלָא. נָטִיל לְהַהִיא מִלָּה וְאַעְטַר לָהּ (שמות י\"ד) בִּתְלַת מְאָה וְשִׁבְעִין אֶלֶף עִטְרִין. הַהִיא מִלָּה טָסַת וְסַלְקָא וְנַחְתָא וְאִתְעֲבִידָא רְקִיעָא חָדָא.","וְכֵן כָּל מִלָּה וּמִלָּה דְּחָכְמְתָא (ס\"א אתעבדין) (ס\"א רקיעין) קַיָּימִין בְּקִיּוּמָא שְׁלִים קַמֵּי עַתִּיק יוֹמִין. וְהוּא קָרֵי לוֹן שָׁמַיִם חֲדָשִׁים, שָׁמַיִם מְחוּדָשִׁים, סְתִימִין דְּרָזִין דְּחָכְמְתָא עִלָּאָה. וְכָל אִנּוּן שְׁאָר מִלִּין דְּאוֹרַיְיתָא דְּמִתְחַדְּשִׁין קַיָּימִין קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא וְסָלְקִין וְאִתְעֲבִידוּ אַרְצוֹת הַחַיִּים. וְנַחְתִין וּמִתְעַטְּרִין לְגַבֵּי אֶרֶץ חַד, וְאִתְחַדַּשׁ וְאִתְעֲבִיד כֹּלָא אֶרֶץ חֲדָשָׁה מֵהַהִיא מִלָּה דְּאִתְחַדַּשׁ בְּאוֹרַיְיתָא."],[[0,"","נז) \u0003אדהכי שמע קלא\u0004 וכו': בתוך כך שמע קול שאמר, פנו מקום פנו מקום, כי מלך המשיח בא לישיבתו של ר' שמעון. משום שכל הצדיקים שם הם ראשי ישיבות שאותן הישיבות ידועות הן שם. וכל אלו החברים שבכל ישיבה, עולים מישיבה שבכאן לישיבה שברקיע, ומשיח בא בכל אלו הישיבות, וחותם תורה מפיהם של החכמים. ובשעה ההיא בא המשיח, לישיבתו של ר' שמעון, מעוטר מן ראשי הישיבות בעטרות עליונות."],[0,"","פירוש. כי מכח הגילוי הגדול הזה, שבשבועת מט\"ט, שהוא בחינת גילוי הקץ, נתעלו מאד כל אלו הצדיקים שהיו במתיבתא דר\"ש, ומכ\"ש אלו ב' כתות הצדיקים שהם היו הגורמים לביאת מט\"ט ושבועתו, שעי\"ז השיגו מעלות נפלאות ביותר, ונתעטרו כולם והגיעו למדרגות \u0003רישי מתיבתא\u0004. כי בכל מתיבתא ומתיבתא יש חברי המתיבתא, ויש עלייהו רישי מתיבתא, וההפרש ביניהם, כמבחינת ו\"ק של המדרגה, לבחינת ג\"ר של המדרגה."],[0,"","וז\"ש \u0003אדהכי שמע קלא דאמר פנון אתר, פנון אתר, דהא מלכא משיחא אתי\u0004, שבעת שגילה מט\"ט סוד הקץ, יצא קול ואמר פנו מקום, פנו מקום, כי המלך המשיח בא, כי ענין הקץ קשור בענין מלך המשיח. ונותן טעם על מה שזכו לזה כל הצדיקים שבמתיבתא דר\"ש, שהוא \u0003בגין דכל צדיקייא דתמן, רישי מתיבתא\u0004 כי לזכות לקבל פניו של המשיח, צריכים להשואת הצורה עמו. וסוד מלך המשיח ה\"ס אור יחידה כנודע. ולפיכך, לולא שזכו כל החברים להשיג בחינת \u0003רישי מתיבתא\u0004, לא היו זוכין לקבל פניו של המשיח. וז\"ש \u0003בגין דכל צדיקייא דתמן רישי מתיבתא\u0004."],[0,"","וז\"ש, \u0003ואינון מתיבתי דתמן רשימין אינון\u0004 וכו', \u0003סלקי ממתיבתא דהכא למתיבתא דרקיעא\u0004: משמיענו, שלא לחשוב שבחינת \u0003רישי מתיבתא\u0004 הוא ג\"ר של מדרגות נמוכות. לזה אומר, \u0003ואינון מתיבתי דתמן\u0004 היו במדרגות גבוהות מאוד נעלות, עד שהחברים כולם של אלו המתיבתות זכו לעלות משם \u0003למתיבתא דרקיעא\u0004. ועתה זכו כל אלו החברים לבחינת רישא דאלו המתיבתות. וזה אמרו \u0003ואינון מתיבתי דתמן רשימין אינון\u0004 שהם רשימין במדרגות גבוהות מאד נעלות, עד \u0003וכל אינון חברין די בכל מתיבתא, סלקי ממתיבתא דהכא למתיבתא דרקיעא\u0004 שכל החברים משם היו זוכין לעלות משם \u0003למתיבתא דרקיעא\u0004, ולא עוד אלא גם \u0003משיח אתי בכל אינון מתיבתי וחתים אורייתא מפומייהו דרבנן\u0004 כלומר, כל כך גבהה מעלת חברי המתיבתות האלו, עד שהמשיח בא בכל אלו המתיבתות להתעטר מחידושי תורתם של חברי המתיבתא, ועתה זכו כל אלו חברי המתיבתות להיות בדרגת \u0003רישי מתיבתי\u0004 לאותם המתיבתות."],[0,"","וזהו שמסיק \u0003בההיא שעתא אתי משיח מתעטר מן רישי מתיבתי, בעטרין עלאין\u0004, אמנם עתה אחר שכל אלו חברי המתיבתות זכו למדרגת \u0003רישי מתיבתי\u0004, נמצא \u0003שמשיח נתעטר\u0004 מאורייתא \u0003דרישי מתיבתות\u0004, ונמצא \u0003מתעטר מן רישי מתיבתי בעטרין עילאין\u0004 ביותר."],[1,"","נח) \u0003בההוא שעתא קמו\u0004 וכו': באותה שעה קמו כל החברים, וקם ר' שמעון, ואורו היה עולה עד רום הרקיע. אמר לו, המשיח: רבי, אשרי לך, שתורתך עולה בשלש מאה ושבעים אורות, וכל אור ואור מתפרש לשש מאות ושלשה עשר טעמים, עולים וטובלים בנהרי האפרסמון הטהור. והקב\"ה, הוא חותם תורה מישיבתך, ומישיבת חזקיה מלך יהודה, ומתוך ישיבת אחיה השלוני."],[1,"","פירוש. שבעת שנגלה להם המשיח, ובא \u0003למתיבתא דר\"ש\u0004, אז קמו כל החברים ור\"ש קם באותה המדרגה עד והוא \u0003סליק נהוריה עד רום רקיע\u0004. וזה רומז שר\"ש השיג לאותו האור של עשרת הרקיעין החסרים מחמת השער הסתום של המלכות דמלכות. וז\"ש \u0003והוה סליק נהוריה עד רום רקיע\u0004. שה\"ס אור יחידה."],[1,"","וז\"ש, \u0003דאורייתך סלקא בתלת מאה ושבעין נהורין, וכל נהורא ונהורא אתפרשת לתרי\"ג טעמין\u0004 וכו' \u0003דאפרסמונא דכיא\u0004: כלומר, דאורייתא דיליה סלקת לעתיק יומין, שבו כל ספירה סלקא עד מאה אלף, וד' הספירות חו\"ב תו\"מ, הן בו ד' מאה אלף. כי יחידות בנוקבא, ועשרות בז\"א, ומאות באמא, ואלפים באבא, ורבוא בא\"א, ומאה אלף בעתיק."],[1,"","אמנם לפי\"ז היה לו לומר, דאוריתך סלקא בד' מאה נהורין דכל נהורא סלקא לאלף טעמין, דהיינו ד' מאה אלף. אלא רמז לו, כי מבחינת האורות שהם מאמא אינו משמש בד' מאות אפי' בהשלמות, רק בש\"ע, שה\"ס מן השלשים הכי נכבד ואל השלשה לא בא (שמואל ב' כ\"ג). כי אע\"ג \u0003דנהוריה סלקא עד רום רקיעא\u0004 כמ\"ש לעיל, מ\"מ אל ג\"ר של המאה העליון של הי' לא בא, ונמצא לו רק \u0003ש\"ע נהורין\u0004 חסר הל' העליונים, ועד\"ז מבחינת האלפים, שהן אורות דאבא אינו משמש בג\"ר ממש דכל אלף, אלא רק בו\"ק דכל אחד, שהן שש מאות, ובמקום ג\"ר דכל אלף הוא משמש בי\"ג, שהם בחי' חכמה דל\"ב נתיבות, (כנ\"ל במראות הסולם אות ב' ד\"ה ועם זה ע\"ש). כי סוד י\"ג הם חכמה דל\"ב נתיבות הנק' \u0003אפרסמונא דכיא\u0004."],[1,"","וזה שאמר לו \u0003דאורייתך סלקא בש\"ע נהורין, וכל נהורא ונהורא אתפרשת לתרי\"ג טעמין, סלקין ואסתחיין בנהרי אפרסמונא דכיא\u0004, אשר בד' המאות דאמא חסרים השלשים דחכמה עליונה ואין בה רק ש\"ע. ובכל אלף חסרות ד' המאות העליונות שהן מחכמה קדומה. ובמקומן משמש י\"ג \u0003נהרי דאפרסמונא דכיא\u0004, ואין בכל אלף רק \u0003תרי\"ג\u0004, כי כן הם העולים כל רזין סתימין עלאין ממתיבתא דר\"ש."],[1,"וקב\"ה איהו חתים אורייתא ממתיבתך","וכו': כי אומר לעיל דמשיח \u0003חתים אורייתא מפומייהו דרבנן\u0004, כי הוא מתגדל ומתעטר ע\"י חדושי התורה של כל הצדיקים. ונודע מ\"ש חז\"ל (סנהדרין צט. ), שכל הנביאים לא נבאו אלא לימות המשיח, אבל לע\"ל עין לא ראתה אלהים זולתך ישעיה ס\"ד). כי אז כבר תתוקנה כל המדרגות השייכות לימות המשיח, וכלהו רזין דאורייתא יהיו בבחי' עין לא ראתה וכו'. ואז נבחן \u0003דקב\"ה חתים אורייתא\u0004. וכיון דאורייתא דאילין ג' ראשי נשמות היא מבחינת לאחר ימות המשיח, דהיינו מבחינת עין לא ראתה וכו' לכן א\"ל משיח, כי \u0003קב\"ה חתים אורייתא ממתיבתך, וממתיבתא דחזקיה מלך יהודה, ומגו מתיבתא דאחיה השילוני\u0004, כי אלו הג' זכו לרזין דאורייתא דעין לא ראתה אלקים זולתך, \u0003וקב\"ה\u0004 עצמו \u0003חתים אורייתא\u0004 מפומייהו."],[2,"","נט) \u0003ואנא לא אתינא\u0004 וכו': ואני לא באתי לחתום תורה מישיבתך, אלא משום שבעל הכנפים יבא כאן, כי אני יודע שלא יכנס לישיבה אחרת אלא לישיבתך, באותה שעה, סיפר לו ר' שמעון אותה השבועה, שנשבע בעל הכנפים. אז נזדעזע המשיח, והרים קולו, ונזדעזעו הרקיעים, ונזדעזע ים הגדול, ונזדעזע הלויתן, והעולם חשב להתהפך. בתוך כך ראה את ר' חייא למרגלותיו של ר' שמעון. אמר, מי נתן כאן אדם לבוש בגד עולם ההוא. דהיינו בגוף מעולם הזה. א\"ר שמעון זה הוא ר' חייא, אור מאור התורה. אמר לו, יאספו הוא ובניו, כלומר שיפטרו מן העולם הזה, ויהיו מן הישיבה שלך. אמר ר' שמעון, זמן ינתן לו. נתנו לו זמן."],[2,"","פירוש, משיח א\"ל כי לא בא \u0003למחתם\u0004 אלא משום \u0003דמארי דגדפין\u0004אתא למתיבתא שלו, הרוצה לדעת מה שאמר לו. ומה שאמר \u0003דהא ידענא דלא ייעול גו מתיבתי אחריתי\u0004, היינו לאפוקי \u0003ממתיבתא דחזקיה מלך יהודה ואחיה השלוני\u0004."],[2,"","וז\"ש, \u0003אזדעזע משיח וארים קליה\u0004 וכו': כי מחמת גילוי הקץ שגילה מט\"ט, שבעת ההיא יהיו צרות נוראות על ישראל, שיזדעזעו הרקיעין, וכן ימא רבא, ועלמא יתהפכא, בסוד וחד חרוב (סנהדרין צז) ע\"כ \u0003ארים קליה\u0004 כי רצה להמתיק כל אלו הזעזועין."],[2,"","וז\"ש, \u0003מאן יהב הכא בר נש לביש מדא דההוא עלמא\u0004: המשיח התפלא על רבי חייא על היותו מלובש בגוף הגשמי של העולם הזה, דהיינו, \u0003מדא דההוא עלמא\u0004. כי אחר שזכה להיות הכא, וזכה להאי גילוי דמט\"ט ולשבועתו, נמצא שכבר תיקן כל בחינת הרע (כנ\"ל אות נ\"ו ד\"ה בשעתא דיתכנשון. ע\"ש). וכן זכה לקבל פני המשיח. נמצא שגמר כל עבודתו בעוה\"ז, ואין לו מה לעשות עוד בעוה\"ז, א\"כ הוא צריך להסתלק וליכנס למתיבתא דר\"ש בג\"ע. ולמה לו להיות עוד בעוה\"ז בחנם."],[2,"","וז\"ש, \u0003אמר ר\"ש זימנא יתייהב ליה\u0004: כלומר, ר\"ש הוכיח לו שיש ליתן לו \u0003זמנא\u0004 מחדש, כי הוא צריך עוד לחיות בהאי עלמא ולעסוק בתיקונים חדשים. ואז \u0003יהבו ליה זמנא\u0004 כלומר, שהמשיח ור\"ש הודיעו לו מה שיש לו עוד לעשות בעוה\"ז."],[3,"","ס) \u0003ונפק מתמן מזדעזע\u0004 וכו': ויצא המשיח משם כשהוא מזדעזע, ועיניו זולגות דמעות. נזדעזע ר' חייא, ובכה, ואמר, אשרי חלקם של הצדיקים בעולם ההוא, ואשרי חלקו של בן יוחאי שזכה לכך. עליו כתוב, להנחיל אוהבי יש ואוצרותיהם אמלא."],[3,"","פירוש, כי המשיח נפק ממתיבתא דר\"ש \u0003וזלגין עינוי דמעין\u0004 מרוב הגעגועים לגאולה השלמה. ומהאי טעמא \u0003אזדעזע גם רבי חייא\u0004."],[4,"","סא) \u0003בראשית, ר' שמעון פתח\u0004 וכו': בראשית: ר\"ש פתח, ואשים דברי בפיך. כמה יש לו לבן אדם לעמול בתורה יום ולילה, כי הקב\"ה מקשיב לקול העוסקים בתורה, ובכל מלה המתחדשת בתורה, על ידי האדם ההוא העמל בתורה, עושה רקיע אחד."],[4,"","פירוש, השי\"ת נתן את כח הדיבור שלו בפיהם של הצדיקים, כמו שמסיק \u0003עמי אתה, למהוי שותפא עמי. מה אנא במלולא דילי עבדית שמים וארץ כד\"א בדבר ה' שמים נעשה, אוף הכי את.\u0004 כן הצדיקים יבראו שמים בכח הדיבור שלהם. ובזה פתח ר\"ש את המקרא \u0003בראשית ברא אלהים את השמים ואת הארץ, וברא\u0004 לשון סתימא הוא, לישנא \u0003דסגיר ולא פתח\u0004. כנ\"ל, ויש להבין למה עשה אותם בסתימו, ואומר שעשה כן בכדי לשים גמר תיקונם של שמים וארץ בדיבור דצדיקים, ולעשותם שותפים עמו ית' בבריאת שמים וארץ. וזה שמביא הכתוב \u0003ואשים דברי בפיך\u0004."],[4,"","ומבאר לפנינו, שיש בזה ב' בחינות של חידוש שמים וארץ, שנתן בפיהם של הצדיקים:"],[4,"","א) לתקן חטאו של אדם הראשון, כי המאציל עשה התיקון שמים וארץ באופן הנעלה קודם חטאו של אדם הראשון, כמו שהכתובים מבארים לנו במעשה בראשית, אשר הזו\"ן דאצילות עלו לא\"א ואו\"א עלאין, ואדם הראשון עלה והלביש את ישסו\"ת וזו\"ן דאצילות, והיה לו לאדה\"ר נר\"ן דאצילות הנק' \u0003זיהרא עלאה\u0004 עד שעקבו של אדה\"ר היה מכהה גלגל חמה (עיין ב\"ב נח. ), ואחר החטא דעצה\"ד ירד עד לעוה\"ז הגשמי (עיין חגיגה יב. ), והנר\"ן שלו באים לו עתה מג' עלמין דבי\"ע דפרודא. ושמים וארץ דאצילות ירדו בסבתו לבחינת ו\"ק ונקודה מטבור דא\"א ולמטה. ומוטל על הצדיקים תיקון זה לתקן כל הפגמים שנעשו ע\"י החטא, ולחזור ולחדש את השמים ואת הארץ דאצילות שהם זו\"ן ולהעלותם לא\"א ולאו\"א כמו שהיו לפני החטא, והצדיקים עצמם יקבלו בחזרה את הזהרא עלאה של אדה\"ר שהיא נר\"ן מעולם האצילות."],[4,"","ב) כי גם אדה\"ר קודם החטא לא היתה לו כל השלמות שרצה המאציל להעניק לו, וע\"כ אחר שהצדיקים יתקנו החטא דעצה\"ד, וישיגו השלמות דנר\"ן דאצילות שהיתה לו לאדה\"ר קודם החטא, מוטלת עליהם עבודה מחדש, דהיינו להמשיך כל המוחין העליונים, שעוד לא היו בעולם לגמרי, שה\"ס עין לא ראתה אלהים זולתך."],[4,"","ואלו העולמות דעין לא ראתה שישלימו הצדיקים, נק' \u0003שמים חדשים וארץ חדשה\u0004 כי הם חדשים ממש שעוד לא היו במציאות לגמרי. משא\"כ אלו שמים וארץ שהצדיקים מחדשים ומחזירים אותם כמו שהיה במעשה בראשית קודם החטא דאדה\"ר, אינם נקראים שמים וארץ \u0003חדשים\u0004 ממש, שהרי היו פעם בעולם, כי כבר המאציל תיקן אותם מעצמו קודם החטא, אלא שהם \u0003מחודשים\u0004 כי לאחר שנפגמו ונתבטלו חזרו ונתחדשו."],[4,"","וע\"כ אין הצדיקים האלו נחשבים עוד לשותפים עמו ית'. הרי שהמקרא \u0003ואשים דברי בפיך\u0004 שמביא ר\"ש כוונתו הוא על המוחין העלאין שגם אדה\"ר היה חסר מהם, שאלו נתחדשו ממש ע\"י הצדיקים, כי לא יצאו עוד מהמאציל, וע\"כ נחשבים הצדיקים בהם לשותפים ממש."],[4,"","וז\"ש, \u0003קב\"ה ציית לקלהון דאינון דמתעסקי באורייתא ובכל מלה דאתחדש באורייתא\u0004 וכו': ז\"א נקרא קול, ונוקבא שלו נקראת דיבור, וכשהצדיק עוסק בתורה מעלה מ\"ן לזו\"ן, בקול ודיבור דאורייתא שלו, שהקול עולה לז\"א, והדיבור לנוקבא. וז\"ש \u0003קב\"ה ציית לקלהון דאינון דמתעסקי באורייתא\u0004, כי קול התורה עולה למ\"ן לז\"א, הנק' \u0003קב\"ה. ובכל מלה דאתחדש באורייתא\u0004 וכו' \u0003עביד רקיעא חדא, מלה\u0004 פירושו דיבור, וכל דיבור ודיבור המתחדש \u0003באורייתא\u0004 של העוסק בתורה עולה למ\"ן לנוקבא הנק' בשם מלה ודיבור. שעי\"ז נעשה \u0003רקיעא חדא\u0004, רקיע, ה\"ס המסך שעליו נעשה הזווג דקב\"ה ושכינתיה, שזה נעשה ע\"י המ\"ן, שהצדיקים מעלים בעסק תורתם."],[4,"","וענין החידוש שאומר בה\u0003מלה דאורייתא\u0004 ואינו אומר חידוש ב\u0003הקול דאורייתא\u0004. הוא משום שהנוקבא צריכה לכל זווג בנין יסודה מחדש, כי אחר כל זווג חוזרת להיות בתולה, וע\"י המ\"ן דצדיקים מתחדש בה תמיד בחינת היסוד שלה, דהיינו בית הקבול לאורות דז\"א. ולפיכך אומר \u0003ובכל מלה דאתחדש באורייתא\u0004 כי ה\u0003מלה\u0004 שהיא מלכות מתחדשת ממש ע\"י דבר תורה של הצדיק. כי אחר כל זווג חוזר ונעלם בית הקבול שלה. כמבואר."],[5,"","סב) \u0003תנן בההיא שעתא\u0004 וכו': למדנו. באותה שעה שדבר תורה מתחדש מפי האדם, הדבר ההוא עולה והועד לפני הקב\"ה. והקב\"ה לוקח אותו הדבר ונושק אותו, ועוטר אותו בשבעים עטרות מפותחות ומחוקקות. ודבר החכמה שנתחדש, עולה ויושב על ראש צדיק חי העולמים, ומשם עף ושט בשבעים אלף עולמות, ועולה לעתיק יומין, שהוא ספירת הכתר. וכל דברי עתיק יומין, הם דברי חכמה בסודות הסתומים העליונים."],[5,"","פירוש, \u0003ההיא מלה סלקא\u0004 וכו': כלומר, בעת שהאדם מעלה מ\"ן בדבר תורה שלו, אז \u0003ההיא מלה\u0004 עליונה שהיא הנוקבא דז\"א \u0003סלקא ואתעתדת קמיה דקב\"ה\u0004 לזווגא עמו."],[5,"","וז\"ש, \u0003וקב\"ה נטיל לההיא מלה ונשיק לה ועטר לה\u0004 וכו': ב' בחינות נוהגות בכל זווג זו\"ן, הנק' זווג דנשיקין, וזווג דיסודות. כי נתבאר (לעיל במאמר אמא אוזיפת אות ט\"ז), כי לא אשתלים שמא עד דברא \u0003נהורא לנהוריה ואתלבש דא בדא\u0004, עש\"ה. שפירושו, שמלבד קומת חכמה, צריך זווג ב' לקומת חסדים שתתלבש קומת החכמה בקומת החסדים, לפיכך, כל זווג כולל ב' זווגים: א) לקומת החכמה, וזווג זה נקרא זווג דנשיקין שהוא בפה דראש, דהיינו לקומת ראש וג\"ר. ב) לקומת חסדים, וזווג זה נק' זווג היסודות, דהיינו לקומת חסדים. וז\"ש \u0003וקב\"ה נטיל לההיא מלה\u0004 דהיינו להנוקבא \u0003ונשיק לה\u0004 היינו זווג דנשיקין לקומת ג\"ר, \u0003ועטר לה\u0004 היינו זווג היסודות לקומת חסדים, שאז מתלבשת החכמה בחסדים והנוקבא מתעטרת במוחין שלמים."],[5,"","וז\"ש, \u0003בשבעין עטרין גליפין ומחקקן\u0004: המוחין השלמים של הנוקבא נק' \u0003שבעין עטרין\u0004. כי הנוקבא היא היום השביעי, וכשמקבלת מז\"א, שהוא בסוד עשרות, נעשית \u0003שבעים\u0004, ובחי' המוחין נק' \u0003עטרין\u0004, וע\"כ נק' \u0003שבעין עטרין\u0004. ואומר שהם \u0003גליפין ומחקקן\u0004, כלומר, שע\"י המ\"ן דצדיקים הם נעשים לבית קבול \u0003לשבעין עטרין\u0004 הללו."],[5,"","וז\"ש, \u0003ומלה דחכמתא דאתחדשא סלקא ויתבא על רישא דצדיק ח\"י עלמין\u0004: נתבאר לעיל שיש ב' בחינות חידושין דשמים וארץ, שהם זו\"ן, א) להחזיר העטרה ליושנה כמו שהיתה מטרם חטאו של אדה\"ר, ותדע שמבחינת החידוש הזה נק' הנוקבא בשם \u0003מלה דאורייתא\u0004, והיינו שביאר ר\"ש עד הנה. ב) חידוש שמים וארץ בבחינת מוחין עלאין שאפילו אדה\"ר לא השיג אותם, ומבחינה זו נק' הנוקבא בשם \u0003מלה דחכמתא\u0004. וחידושה הולך עתה ומבאר לפנינו."],[5,"","ואומר \u0003ומלה דחכמתא דאתחדשא סלקא ויתבא על רישא דצדיק ח\"י עלמין\u0004, דהיינו בסוד שאמרו רז\"ל צדיקים יושבים ועטרותיהם בראשיהם. (ברכות יז'. ) כי ע\"י המ\"ן של הצדיקים, השלמים כבר בזהרא עילאה דאדה\"ר, כמו ר\"ש וחבריו, עולה הנוקבא דז\"א להיות עטרה לראש צדיק, שהוא הז\"א מבחינת היסוד שלו, שה\"ס ח\"י עלמין. פירוש, אור החכמה נק' אור חיה, והואיל שאי אפשר לז\"א להמשיך אור חיה זולת ע\"י הנוקבא (כנ\"ל אות ה' ד\"ה ונציב ע\"ש). נבחן שאינו \u0003ח\"י\u0004 רק כשהוא בזווג עם הנוקבא, הנק' \u0003עלמא\u0004, ע\"כ נק' אז \u0003ח\"י עלמין\u0004. וכן נבחן, שהנוקבא היא עטרה על ראשו, כלומר, שהמוחין הנק' עטרה הם מבחינת הנוקבא, שלא היה זוכה בהם זולתה. גם זה סוד שלא זז מחבבה עד שקראה אמי, (מדרש שה\"ש ספ\"ג) כי המסובב נבחן לבן הסבה שלו, ומתוך שהנוקבא היתה סבה לאור החיה דז\"א, הרי מבחינה זו נעשית הנוקבא לאמו."],[5,"","וז\"ש, \u0003וטסא מתמן ושטא בשבעין אלף עלמין\u0004: אחר שנזדווגה עם הז\"א בסוד עטרה על ראש צדיק, היא מעופפת ועולה עוד למעלה, דהיינו לא\"א, ושם מתקנות ז' הספירות שלה בסוד ז' רבוא עלמין, שהם ע' אלף. כי הספירות דא\"א הן בסוד רבוא כנ\"ל. ומשם היא עולה יותר עד עתיק יומין. וז\"ש \u0003וסליקת לגבי עתיק יומין\u0004 כי מא\"א עולה עד עתיק יומין. והוא חושב העליות של זו\"ן בזה אחר זה עד \u0003עתיק יומין\u0004, הנעשה מכח המ\"ן של הצדיקים השלמים. כי בחינת הזווג דעטרה על ראש הצדיק, הוא ע\"י עליה לאו\"א עי', ומשם עולה לא\"א בסוד ע' אלף עלמין, ומשם לעתיק, שהוא תכלית הגובה."],[5,"","וז\"ש, \u0003וכל מלין דעתיק יומין מלין דחכמתא, אינון ברזין סתימין עלאין\u0004: מפרש מעלת המוחין המושפעין לנוקבא ע\"י עליתה לעתיק יומין. ואומר וכל מלין דעתיק יומין, דהיינו כל הקומות המקובלות מעתיק יומין, הן \u0003מלין דחכמתא ברזין סתימין עלאין\u0004 כלומר, שהם בחינת ג\"ר דחכמה, כי \u0003מלין דחכמתא\u0004 מורה על קומת החכמה, \u0003ורזין סתימין עלאין\u0004 היינו ג\"ר דחכמה. והן אינן מתגלות זולת ע\"י עליה למקום \u0003עתיק יומין\u0004 ולא למטה ממנו."],[6,"","סג) \u0003וההיא מלה סתימא\u0004 וכו': ואותו דבר החכמה הסתום שנתחדש כאן, בעולם הזה, כשהוא עולה, הוא מתחבר באלו הדברים של עתיק יומין, ועולה ויורד עמהם, ונכנס בשמונה עשר עולמות צפונים, אשר עין לא ראתה אלקים זולתך. ויוצאים משם ומשוטטים, ובאים מלאים ושלמים ונועדים לפני עתיק יומין. באותה שעה, עתיק יומין מריח באותו הדבר, ורצוי לפניו יותר מכל. אז, לוקח את הדבר ההוא, ומעטר אותו בשלש מאה ושבעים אלף עטרות. ודבר חידושי התורה ההוא משוטט ועולה ויורד, ונעשה ממנו רקיע אחד."],[6,"","פירוש, כי בעת עלית הנוקבא ל\u0003עתיק יומין\u0004, היא נכללת בזווג אשר שם, והיא מעלה או\"ח וממשכת או\"י מבחינת עתיק יומין. \u0003וסלקא\u0004 פירוש שמעלה או\"ח ממטה למעלה. \u0003ונחתא\u0004 פירוש, שממשיכה או\"י ממעלה למטה. שאז מקבלת החכמתא ברזין סתימין עלאין הנ\"ל. ואמרו \u0003בהדייהו\u0004 מורה שנכללת עם האו\"ח ואו\"י שבעתיק עצמו."],[6,"","וז\"ש, \u0003ועאלת בתמניסר עלמין גניזין דעין לא ראתה אלהים זולתך\u0004: כי הזווג הזה הנעשה בעתיק, הוא ג\"כ על היסוד דעתיק אשר שם, והוא ג\"כ \u0003צדיק ח\"י עלמין\u0004 כמו יסוד דז\"א בעת עליתו לאו\"א עלאין כנ\"ל. אלא ההפרש הוא, כי היסוד הזה דעתיק \u0003עין לא ראתה אלהים זולתך\u0004. כי הזווג של היסוד נעשה על המסך בסוד ההכאה, המעלה או\"ח כדי להלביש את האו\"י, כנודע. והנה למטה באו\"א נבחן המסך לבחינת כנפים המכסות על האור העליון בעת שדוחים אותו לאחוריו, וזה מורה שיש בהם כח הדין, שז\"ס שכל או\"ח נק' אור דין."],[6,"","משא\"כ ביסוד עתיק הנ\"ל, ששם נאמר לא יכנף עוד מוריך וגו', (ישעיה ל') כי אע\"פ שהמסך מעלה או\"ח ממטה למעלה, מ\"מ אין בו בחינת כנפים. וע\"כ הוא מכונה \u0003ח\"י עלמין גניזין דעין לא ראתה אלהים זולתך\u0004. כלומר, שאין שם עוד בחינת כנפים המכסות מעין זר, כי אין שם שום דינים אלא \u0003עין לא ראתה אלהים זולתך\u0004. והבן היטב. כי הבחינה שממטה למעלה נקראת גניזין אמנם היא בבחינת \u0003עין לא ראתה\u0004 וכו'."],[6,"","וזה אמרו \u0003נפקי מתמן ושאטן ואתיין מליאן ושלמין\u0004 כי \u0003נפקי מתמן\u0004 היינו מסוד הזווג על המסך הנק' \u0003ח\"י עלמין גניזין דעין לא\u0004 וכו' \u0003ושטאן\u0004 היינו שמעלה או\"ח ממטה למעלה. ואתיין היינו שממשכת האו\"י ממעלה למטה ואז הם \u0003מליאן ושלמין\u0004 מלאים באו\"י \u0003מחכמתא ברזין סתימין עלאין\u0004. ושלמים בבחינת או\"ח שאין בו שום דין אלא כולו רחמים גמורים בשוה עם האו\"י. ואז \u0003ואתעתדו קמי עתיק יומין\u0004 שהם מוכנים להלביש את העתיק יומין."],[6,"","וז\"ש, \u0003בההיא שעתא ארח עתיק יומין בהאי מלה וניחא קמיה מכלא\u0004: ארח ה\"ס נייחא דרוחא, כי הזווג הגדול והנשגב הזה גורם נייחא דרוחא מאד נעלה לעתיק יומין. והוא משום שכל העולמות כולם וכל שבחם נכללים אז בנוקבא. וז\"ש \u0003וניחא קמיה מכלא\u0004, כי זה הנייחא דרוחא מגיע לו \u0003מכלא\u0004 מכל העולמות כולם בבת אחת, להיותה תכלית השלמות והגובה שעליה נבראו העולמות."],[6,"","וז\"ש, \u0003נטיל לההיא מלה ואעטר לה בתלת מאה ושבעין אלף עטרין\u0004: פירוש, כי אז משפיע לה המוחין הנשגבים דעתיק עצמו, שהם חו\"ב תו\"מ, שכל אחת עולה מאה אלף, כי ספירות דעתיק, הן כל אחת מבחינת מאה אלף כנ\"ל. אלא ההפרש הוא כי בשלשים העליונים של החכמה, ששם סוד משלשים הכי נכבד ואל השלשה לא בא (ש\"ב כ\"ג), כלומר, שאף על פי שהיא מקבלת ונכבדת גם מג\"ר דחכמה דעתיק שהן שלשים אלף העליונים, כמו שאומר לעיל, עכ\"ז אל השלשים אלף עצמם לא תוכל הנוקבא לעלות ולהלביש ממש. והטעם הוא כי אם היתה מלבשת גם שלשים אלף אלו, היתה הנוקבא מתבטלת בו, כנר בפני אבוקה. לכן אינה מקבלת מעתיק רק \u0003ש\"ע אלף עטרין\u0004 דהיינו ד' מאות אלף פחות שלשים אלף מטעם האמור."],[6,"","וז\"ש, \u0003ההיא מלה טסת וסלקא ונחתא ואתעבידא רקיעא חדא: טסת\u0004 פירושו, מעופפת למעלה, ו\u0003טסת וסלקא\u0004, היינו שהיא מעלה או\"ח ממטה למעלה. \u0003ונחתא\u0004 שע\"י האו\"ח שהיא מעלה יורדת עם אור ישר ממעלה למטה. \u0003ואתעבידא רקיעא חדא\u0004 שע\"י הלבשת או\"ח לאו\"י נעשה שם רקיע אחד. כי אותו המסך שנתקן במלכות כדי להעלות או\"ח, שהוא הגיע לנוקבא ע\"י מע\"ט והמ\"ן, שהעלו כדי להשפיע נ\"ר ליוצרם כנ\"ל. הנה אחר הזווג שנעשה עליו, הוא נעשה רקיע, שדרך בו משיגים הצדיקים אותה קומת הזווג שנעשה עליו. והענין הוא, כשהמדרגה יורדת לצדיקים דרך הרקיע, נמצאת מתלבשת בלבוש הנמשך \u0003מהרקיעא\u0004 ההוא, שהוא בחינת או\"ח, המתהפך מהרקיע ולמטה, עם האו\"י שמרקיע ולמעלה, וכן היא באה להשגת הצדיקים המלובשים זה בזה."],[6,"","וביאור הדברים הוא, כי אלו הצדיקים שזכו לשלמות ההיא, להעלות מ\"ן לזווג הגבוה הזה, הנה כבר אין בהם מבחינת קבלה לצרכם עצמם ולא כלום, ומ\"ן שהעלו היו רק כדי להשפיע ולא לקבל, ולפיכך הם מתקנים עם המע\"ט והמ\"ן, בחינת המסך לנוקבא, ומכשירים אותה לזווג הגדול הזה, שההכשר עצמו הוא סוד או\"ח העולה מהמסך של הנוקבא ולמעלה, כי כל העולה ממטה למעלה, ה\"ס השפעה ודחית הקבלה לעצמו, ואז נעשה הזווג דהכאה עם האור העליון, והאור העליון מתלבש בלבוש של או\"ח העולה."],[6,"","והנה האור היורד ממעלה למטה ומתלבש באו\"ח, הרי הוא בא לקבלת התחתון דהיינו לאותו צדיק שהעלה המ\"ן, כי כל הבא מלמעלה למטה פירושו שבא לקבלה. וכיון שהאור העליון עובר לתחתון דרך הרקיע, נמצא נוטל עמו בחינת הלבוש דאו\"ח מהרקיע, והתחתון מקבל האור העליון תוך לבושו זה. והפירוש הוא, כי גם אחר שבאה הקומה להשגת התחתון, אינו נהנה במשהו מן האור העליון היורד אליו, אלא לפי מדת השפעת נ\"ר ליוצרו, דהיינו במדת הלבוש של או\"ח המלביש על האור העליון. וזה נבחן למקבל על מנת להשפיע, ואינו מקבל משהו אם לא תמצא בו השפעה ליוצרו. וע\"כ הקבלה מלובשת תוך ההשפעה, או\"י באו\"ח. וזהו שמדייק ומדגיש \u0003ההיא מלה טסת וסלקא ונחתא ואתעבידא רקיעא חדא\u0004 כלומר, שאינו מקובל לתחתונים רק דרך הרקיע, דהיינו בבחינת לבושו עמו כנ\"ל."],[7,"","סד) \u0003וכן כל מלה\u0004 וכו': וכן כל דבר ודבר של חכמה נעשים רקיעים עומדים בקיום שלם לפני עתיק יומין, והוא קורא אותם, שמים חדשים. כלומר, שמים מחודשים, שהם סתומים של סודות החכמה העליונה. וכל שאר דברי תורה המתחדשים, שאינם מבחינת חכמה עליונה, עומדים לפני הקב\"ה, ועולים ונעשים ארצות החיים, ויורדים ומתעטרים אל ארץ אחת. ונתחדש ונעשה הכל ארץ חדשה, מכח דבר ההוא שנתחדש בתורה."],[7,"","פירוש, כי כן הולכים הצדיקים ומעלים מ\"ן תמיד וממשיכים המדרגות הנשגבות ההן מעתיק יומין ע\"י אותם הרקיעים שנעשו ע\"י הזווג העליון. ומאלו הרקיעים נעשו סוד ה\u0003שמים חדשים\u0004, שהם מתחדשים במדרגת עתיק יומין כנ\"ל. וע\"כ נק' אלו ההשגות הגבוהות בשם \u0003סתימין דרזין דחכמתא עלאה\u0004 דהיינו על שבאות מלובשות בלבוש הנמשך מהרקיעין."],[7,"","וז\"ש, \u0003שאר מלין דאורייתא\u0004 וכו' \u0003לגבי ארץ חד ואתחדש ואתעביד כלא ארץ חדשה\u0004: כי בכל קומה יש חו\"ב תו\"מ, ועד כאן היה המדובר רק מבחינת \u0003רזין דחכמתא\u0004 לבדה, ולא מבינה וז\"א ומלכות שבכל קומה. וז\"ש, \u0003ואתעבידו ארצות החיים\u0004 שנעשים כולם לבחינת בינה, הנק' ארץ החיים. ונחתין \u0003ומתעטרין לגבי ארץ חד\u0004 היינו להמלכות הנקראת \u0003ארץ\u0004 סתם \u0003ואתחדש ואתעביד כלא ארץ חדשה\u0004 כי המלכות נתעטרה וקבלה כל המדרגות דארצות החיים, שהן בינה, וע\"י זה עלתה המלכות להיות בינה."],[7,"","ונק' עתה \u0003ארץ חדשה\u0004, כי מה שהיתה מקודם לכן בחינת מלכות, היא עתה בחינת בינה. וז\"ס עתיד הב\"ן להיות ס\"ג, והמ\"ה להיות ע\"ב. כי בחינת שמים הם ז\"א, ועתה במדרגת עתיק יומין הם ב\u0003רזין דחכמתא עלאה\u0004, הרי שהמ\"ה שהוא ז\"א נעשה לבחינת ע\"ב שהיא חכמה. ובחינת ארץ שהיא נוקבא דז\"א נעשה לבחינת ס\"ג שהיא בינה. ונמצא שסוד \u0003שמים חדשים וארץ חדשה\u0004 הם מ\"ה וב\"ן שנתבטלו ונעשו לע\"ב ס\"ג."]],[[0,"","בֵּין כָּךְ שָׁמַע קוֹל שֶׁאוֹמֵר: פַּנּוּ מָקוֹם, פַּנּוּ מָקוֹם, שֶׁהִנֵּה הַמֶּלֶךְ הַמָּשִׁיחַ בָּא לִישִׁיבַת רַבִּי שִׁמְעוֹן, הֱיוֹת שֶׁכָּל הַצַּדִּיקִים שֶׁשָּׁם וְרָאשֵׁי הַיְשִׁיבָה, וְאוֹתָן יְשִׁיבוֹת שֶׁשָּׁם הֵן רְשׁוּמוֹת, וְכָל אוֹתָם חֲבֵרִים שֶׁבְּכָל יְשִׁיבָה עוֹלִים מֵהַיְשִׁיבָה שֶׁל כָּאן לִישִׁיבַת הָרָקִיעַ, וְהַמָּשִׁיחַ בָּא בְּכָל אוֹתָן הַיְשִׁיבוֹת וְחוֹתֵם תּוֹרָה מִפִּי הַחֲכָמִים. וּבְאוֹתָהּ הַשָּׁעָה בָּא הַמָּשִׁיחַ מִתְעַטֵּר (נ\"א: מראש) מֵרֵיחוֹת הַיְשִׁיבוֹת בַּעֲטָרוֹת עֶלְיוֹנוֹת."],[1,"","בְּאוֹתָהּ שָׁעָה קָמוּ כָּל אוֹתָם הַחֲבֵרִים, וְקָם רַבִּי שִׁמְעוֹן, וְהָיָה עוֹלֶה אוֹרוֹ עַד רוּם (הרקיע). אָמַר לוֹ, רַבִּי, אַשְׁרֶיךְ שֶׁתּוֹרָתְךְ עוֹלָה בִּשְׁלֹשׁ מֵאוֹת וְשִׁבְעִים אוֹרוֹת, וְכָל אוֹר וְאוֹר נִפְרָד לְשֵׁשׁ מֵאוֹת וּשְׁלֹשָׁה עָשָׂר טְעָמִים שֶׁעוֹלִים וְרוֹחֲצִים בְּנַהֲרוֹת אֲפַרְסְמוֹן טָהוֹר. וְהַקָּדוֹשׁ-בָּרוּךְ-הוּא מְאַשֵּׁר תּוֹרָה מִישִׁיבָתְךְ, וּמִישִׁיבָתוֹ שֶׁל חִזְקִיָּהוּ מֶלֶךְ יְהוּדָה, וּמִתּוֹךְ יְשִׁיבָתוֹ שֶׁל אֲחִיָּה הַשִּׁילֹנִי."],[2,"","וַאֲנִי לֹא בָאתִי לְאַשֵּׁר מִישִׁיבָתְךְ, אֶלָּא בַּעַל הַכְּנָפַיִם בָּא לְכָאן, שֶׁהֲרֵי יָדַעְתִּי שֶׁלֹּא יִכָּנֵס לְתוֹךְ הַיְשִׁיבוֹת הָאֲחֵרוֹת אֶלָּא לִישִׁיבָתְךְ. בְּאוֹתָהּ שָׁעָה סִפֵּר לוֹ רַבִּי שִׁמְעוֹן אוֹתָהּ הַשְּׁבוּעָה שֶׁנִּשְׁבַּע בַּעַל הַכְּנָפַיִם. אָז הִזְדַּעֲזַע הַמָּשִׁיחַ וְהֵרִים קוֹלוֹ, וְהִזְדַּעְזְעוּ הָרְקִיעִים, וְהִזְדַּעֲזַע הַיָּם הַגָּדוֹל, וְהִזְדַּעֲזַע הַלִּוְיָתָן, וְחָשַׁב הָעוֹלָם לְהִתְהַפֵּךְ. בֵּין כָּךְ רָאָה אֶת רַבִּי חִיָּיא לְרַגְלֵי רַבִּי שִׁמְעוֹן. אָמַר, מִי נָתַן כָּאן אָדָם שֶׁלָּבוּשׁ מַדֵּי אוֹתוֹ הָעוֹלָם אָמַר לוֹ רַבִּי שִׁמְעוֹן, זֶה הוּא רַבִּי חִיָּיא, הָאוֹר שֶׁל מְאוֹר הַתּוֹרָה. אָמַר לוֹ, יִתְכַּנֵּס הוּא וּבָנָיו וְיִהְיוּ מֵהַיְשִׁיבָה שֶׁלְּךְ. אָמַר רַבִּי שִׁמְעוֹן, זְמַן יִנָּתֵן לוֹ."],[3,"","נָתְנוּ לוֹ זְמַן, וְיָצָא מִשָּׁם מְזֻעְזָע וְעֵינָיו זוֹלְגוֹת דְּמָעוֹת. הִזְדַּעֲזַע רַבִּי חִיָּיא וּבָכָה, וְאָמַר, אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים בְּאוֹתוֹ הָעוֹלָם, וְאַשְׁרֵי חֶלְקוֹ שֶׁל בַּר יוֹחַאי שֶׁזָּכָה לְכָךְ. עָלָיו כָּתוּב (משלי ח) לְהַנְחִיל אֹהֲבַי יֵשׁ וְאֹצְרֹתֵיהֶם אֲמַלֵּא."],[4,"","בְּרֵאשִׁית, רַבִּי שִׁמְעוֹן פָּתַח, (ישעיה נא) וָאָשִׂם דְּבָרַי בְּפִיךְ. כַּמָּה יֵשׁ לָאָדָם לְהִשְׁתַּדֵּל בַּתּוֹרָה יוֹמָם וָלַיְלָה, מִשּׁוּם שֶׁהַקָּדוֹשׁ-בָּרוּךְ- הוּא מַקְשִׁיב לְקוֹלוֹת אוֹתָם שֶׁמִּתְעַסְּקִים בַּתּוֹרָה. וּבְכָל דָּבָר שֶׁמִּתְחַדֵּשׁ בַּתּוֹרָה עַל יְדֵי אוֹתוֹ שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, עוֹשֶׂה רָקִיעַ אֶחָד."],[5,"","שָׁנִינוּ, בַּשָּׁעָה הַהִיא שֶׁדְּבַר תּוֹרָה מִתְחַדֵּשׁ מִפִּי אָדָם, הַדָּבָר הַהוּא עוֹלֶה וּמִזְדַּמֵּן לִפְנֵי הַקָּדוֹשׁ- בָּרוּךְ-הוּא, וְהַקָּדוֹשׁ-בָּרוּךְ-הוּא נוֹטֵל אֶת אוֹתוֹ הַדָּבָר (תורה) וּמְנַשֵּׁק אוֹתוֹ, וּמְעַטֵּר אוֹתוֹ בְּשִׁבְעִים עֲטָרוֹת גְּלוּפוֹת וּמְחֻקָּקוֹת. וּדְבַר חָכְמָה שֶׁהִתְחַדֵּשׁ, עוֹלֶה וְיוֹשֵׁב עַל רֹאשׁ הַצַּדִּיק חַי הָעוֹלָמִים, וְטָס מִשָּׁם וּמְשׁוֹטֵט בְּשִׁבְעִים אֶלֶף עוֹלָמוֹת וְעוֹלֶה אֶל עַתִּיק הַיָּמִים. וְכָל הַדְּבָרִים שֶׁל עַתִּיק הַיָּמִים, דִּבְרֵי חָכְמָה הֵם בְּסוֹדוֹת נִסְתָּרִים עֶלְיוֹנִים."],[6,"","וְאוֹתוֹ הַדָּבָר הַנִּסְתָּר שֶׁל חָכְמָה שֶׁהִתְחַדֵּשׁ כָּאן, כְּשֶׁהוּא עוֹלֶה, מִתְחַבֵּר עִם אוֹתָם הַדְּבָרִים שֶׁל עַתִּיק הַיָּמִים, וְעוֹלֶה וְיוֹרֵד עִמָּהֶם וְנִכְנָס בִּשְׁמוֹנָה עָשָׂר עוֹלָמוֹת גְּנוּזִים שֶׁעַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ (שם סד). יוֹצְאִים מִשָּׁם וּמְשׁוֹטְטִים וְהוֹלְכִים מְלֵאִים וּשְׁלֵמִים וּמִזְדַּמְּנִים לִפְנֵי עַתִּיק הַיָּמִים. בְּאוֹתָהּ הַשָּׁעָה מֵרִיחַ עַתִּיק הַיָּמִים אֶת הַדָּבָר הַזֶּה, וְזֶה נוֹחַ לְפָנָיו מִן הַכֹּל. נוֹטֵל אֶת אוֹתוֹ הַדָּבָר, וּמְעַטֵּר אוֹתוֹ בִּשְׁלֹשׁ מֵאוֹת וְשִׁבְעִים אֶלֶף עֲטָרוֹת. אוֹתוֹ הַדָּבָר טָס וְעוֹלֶה וְיוֹרֵד, וְנַעֲשֶׂה רָקִיעַ אֶחָד."],[7,"","וְכֵן כָּל דָּבָר וְדָבָר שֶׁל חָכְמָה (ס\"א נעשים) (ס\"א רקיעים) עוֹמְדִים בְּקִיּוּם שָׁלֵם לִפְנֵי עַתִּיק הַיָּמִים. וְהוּא קוֹרֵא לָהֶם שָׁמַיִם חֲדָשִׁים, שָׁמַיִם מְחֻדָּשִׁים, נִסְתָּרִים שֶׁל סוֹדוֹת שֶׁל חָכְמָה עֶלְיוֹנָה. וְכָל אוֹתָם שְׁאָר דִּבְרֵי הַתּוֹרָה שֶׁמִּתְחַדְּשִׁים, עוֹמְדִים לִפְנֵי הַקָּדוֹשׁ-בָּרוּךְ-הוּא, וְעוֹלִים וְנַעֲשִׂים אַרְצוֹת הַחַיִּים, וְיוֹרְדִים וּמִתְעַטְּרִים לְאֶרֶץ אַחַת, וּמִתְחַדֵּשׁ וְנַעֲשֶׂה הַכֹּל אֶרֶץ חֲדָשָׁה מֵאוֹתוֹ הַדָּבָר שֶׁהִתְחַדֵּשׁ בַּתּוֹרָה."]]],[["וְעַל דָּא כְּתִיב, (ישעיהו ס״ו:כ״ב) כִּי כַּאֲשֶׁר הַשָּׁמַיִם הַחֲדָשִׁים וְהָאָרֶץ הַחֲדָשָׁה אֲשֶׁר אֲנִי עוֹשֶׂה עוֹמְדִים לְפָנַי וְגו'. עָשִׂיתִי לָא כְּתִיב אֶלָּא עוֹשֶׂה, דְּעֲבִיד תָּדִיר מֵאִנּוּן חִדּוּשִׁין וְרָזִין דְּאוֹרַיְיתָא. וְעַל דָּא כְּתִיב, (ישעיהו נ״א:ט״ז) וָאָשִׂים דְּבָרַי בְּפִיךָ וּבְצֵל יָדִי כִּסִּיתִיךָ לִנְטֹעַ שָׁמַיִם וְלִיסוֹד אָרֶץ. הַשָּׁמַיִם לָא כְּתִיב אֶלָּא שָׁמָיִם.","אָמַר רִבִּי אֶלְעָזָר מַהוּ וּבְצֵל יָדִי כִּסִּיתִיךָ. אָמַר לֵיהּ בְּשַׁעֲתָא דְאִתְמָסַר אוֹרַיְיתָא לְמשֶׁה, אָתוּ כַּמָּה רִבּוֹא דְּמַלְאֲכֵי עִלָּאִין לְאוֹקְדָא לֵיהּ בְּשַׁלְהוֹבָא דְפוּמְהוֹן, עַד דְּחֲפָא עֲלֵיהּ קוּדְשָׁא בְּרִיךְ הוּא. וְהַשְׁתָּא דְהַאי מִלָּה סָלְקָא וְאִתְעַטְּרַת וְקָיְימָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, אִיהוּ חָפֵי עַל הַהִיא מִלָּה וְכַסֵּי עַל הַהוּא בַּר נָשׁ דְּלָא יִשְׁתְּמוֹדַע לְגַבַּיְיהוּ אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא. וְלָא יְקַנְּאוּן לְגַבֵּיהּ עַד דְּאִתְעֲבִיד מֵהַהִיא מִלָּה שָׁמַיִם חֲדָשִׁים וְאֶרֶץ חֲדָשָׁה הֲדָא הוּא דִכְתִיב וּבְצֵל יָדִי כִּסִּיתִיךָ לִנְטוֹעַ שָׁמַיִם וְלִיסוֹד אָרֶץ. מִכָּאן דְּכָל מִלָּה דְסָתִים מֵעֵינָא סָלְקָא לְתוֹעַלְתָּא עִלָּאָה הֲדָא הוּא דִכְתִיב, (ישעיהו נ״א:ט״ז) וּבְצֵל יָדִי כִּסִּיתִיךָ. וְאַמַּאי אִתְחֲפֵי וְאִתְכַּסֵּי מֵעֵינָא, בְּגִין לְתוֹעַלְתָּא עִלָּאָה. הֲדָא הוּא דִכְתִיב לִנְטוֹעַ שָׁמַיִם וְלִיסוֹד אָרֶץ כְּמָה דְּאִתְּמָר.","וְלֵאמֹר לְצִיּוֹן עַמִּי אָתָּה. וְלֵאמֹר לְאִנּוּן תַּרְעִין וּמִלִּין דִּמְצוּיָינִין אִלֵּין עַל אִלֵּין עַמִּי אָתָּה. אַל תִּקְרֵי (בתיקון יח דף לה ב) עַמִּי אָתָּה, אֶלָּא עִמִּי אָתָּה לְמֶהוֵי שׁוּתָּפָא עִמִּי, מָה אֲנָא בְּמִלּוּלָא דִילִי עֲבָדִית שָׁמַיִם וָאָרֶץ כְּמָא דְאַתְּ אָמֵר, (תהילים ל״ג:ו׳) בִּדְבַר יְיָ שָׁמַיִם נַעַשִׂוּ, אוּף הָכִי אַתְּ. זַכָּאִין אִנּוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא. וְאִי תֵימָא דְּמִלָּה דְכָל בַּר נָשׁ דְּלָא יָדַע עָבִיד דָּא.","תָּא חֲזֵי, הַהוּא דְּלָאו אָרְחֵיהּ (יתרו פ\"ז א) בְּרָזִין דְּאוֹרַיְיתָא וְחִדֵּשׁ מִלִּין דְּלָא יְדַע עַל בּוּרְיֵיהוֹן כְּדְקָא יְאוּת, הַהִיא מִלָּה סַלְקָא וְנָפִיק לְגַבֵּי הַהִיא מִלָה (משלי ט״ז:כ״ח) אִישׁ תַּהְפּוּכוֹת לְשׁוֹן שָׁקֶר, מִגּוֹ נוּקְבָא דִתְהוֹמָא רַבָּא וְדָלִיג חֲמֵשׁ מְאָה פַּרְסֵי לְקַבְּלָא לְהַהִיא מִלָּה וְנָטִיל לָהּ וְאָזִיל בְּהַהִיא מִלָּה לְגוֹ נוּקְבֵיהּ וְעָבִיד בָּהּ רְקִיעָא דְשָׁוְא דְּאִקְרֵי תֹּהוּ.","וְטָס בְּהַהוּא רְקִיעָא הַהוּא אִישׁ תַּהְפּוּכוֹת שִׁיתָּא אַלְפֵי פַּרְסֵי בְּזִמְנָא חָדָא. כֵּיוָן דְּהַאי רְקִיעָא דְשָׁוְא קָאִים נָפְקַת מִיָּד (פקודי ער\"ה) אֵשֶׁת זְנוּנִים וְאַתְקִיף בְּהַהוּא רְקִיעָא דְשָׁוְא (נ\"א היא) (נ\"א ואיש תהפוכות) וְאִשְׁתַּתְּפַת בֵּיהּ וּמִתַּמָּן נָפְקַת וְקָטְלַת כַּמָּה אֲלָפִין וְרִבְוָון, בְּגִין דְּכַד קָיְימַת בְּהַהוּא רְקִיעָא אִית לָהּ רְשׁוּ וִיכָלְתָּא לְמֶהֱוֵי טָס כָּל עָלְמָא בְּרִגְעָא חֲדָא.","וְעַל דָּא כְּתִיב, (ישעיהו ה׳:י״ח) הוֹי מוֹשְׁכֵי הֶעָוֹן בְּחַבְלֵי הַשְּׁוָא. הֶעָוֹן דָּא דְכוּרָא. וְכַעֲבוֹת הָעֲגָלָה חַטָּאָה. מַאן חַטָּאָה, דָּא נוּקְבָא דְאִקְרֵי חַטָּאָה. אִיהוּ מָשִׁיךְ הַהוּא דְאִקְרֵי עָוֹן בְּאִנּוּן חַבְלֵי הַשָּׁוְא. וּלְבָתַר כַּעֲבוֹת הָעֲגָלָה חַטָּאָה, לְהַהִיא נוּקְבָא דְאִקְרֵי חַטָּאָה, דְּתַמָּן אִתְתַּקְפַת לְמֶהוֵי טָס לְקַטְלָא בְּנֵי נָשָׁא. וְעַל דָּא (משלי ז׳:כ״ו) כִּי רַבִּים חֲלָלִים הִפִּילָה, מַאן הִפִּילָה, דָּא הַהִיא חַטָּאָה דְּקָטְלִית בְּנֵי נְשָׁא. מָאן גָּרִים דָּא, תַּלְמִיד חָכָם דְּלָא מָטֵי לְהוֹרָאָה וּמוֹרֶה, רַחֲמָנָא לִשֵּׁזְבָן.","אָמַר רִבִּי שִׁמְעוֹן לְחַבְרַיָא בְּמָטוּתָא מִנַּיְיכוֹ דְּלָא תַפְקוּן מִפּוּמַיְיכוּ מִלָּה דְאוֹרַיְיתָא דְלָא (יתרו פ\"ז א') יְדַעְתּוּן וְלָא שְׁמַעְתּוּן מֵאִילָנָא רַבְרְבָא כְּדְקָא יְאוּת, בְּגִין דְּלָא תֶהווֹן גָּרְמִין לְהַהוּא חַטָּאָה לְקַטְלָא אֻכְלוֹסִין דְּבַּר נָשׁ לְמַגָּנָא. פָּתְחוּ כֻּלְהוֹן וְאָמְרוּ רַחֲמָנָא לִשֵּׁזְבָן, רַחֲמָנָא לִשֵּׁזְבָן.","תָּא חֲזֵי, בְּאוֹרַיְיתָא בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא, וְהָא אוּקְמוּהָ דִּכְתִיב, (משלי ח׳:ל׳) וָאֶהְיֶה אֶצְלוֹ אָמוֹן וָאֶהְיֶה שַׁעֲשׁוּעִים יוֹם יוֹם וְאִיהוּ אִסְתַּכַּל בָּהּ זִמְנָא וּתְרֵין וּתְלָתָא וְאַרְבַּע זִמְנִין, וּלְבָתַר אָמַר לוֹן, וּלְבָתַר עָבִיד בָּהּ עֲבִידְתָּא. לְאוּלְפָא לִבְנֵי נָשָׁא דְּלָא יִיִתוֹן לְמִטְעֵי בָּהּ. כְּמָא דְאַתְּ אָמֵר, (איוב כ״ח:כ״ז-כ״ח) אָז רָאָהּ וַיְסַפְּרָהּ הכִינָהּ וְגַם חֲקָרָהּ וַיֹּאמֶר לָאָדָם.","וְלָקֳבֵיל אַרְבַּע זִמְנִין אִנּוּן דִּכְתִיב, אָז רָאָהּ, וַיְסַפְּרָהּ, הכִינָהּ, וְגַם חֲקָרָהּ, בָּרָא קוּדְשָׁא בְּרִיךְ הוּא מַה דְּבָרָא. וְעַד לָא אַפִּיק עֲבִידְתֵּיהּ, אָעִיל אַרְבַּע תֵּבִין בְּקַדְמִיתָא דִּכְתִיב בְּ'רֵאשִׁית בָּ'רָא אֱ'לֹהִים אֶ'ת, הָא אַרְבַּע. וּלְבָתַר הַשָּׁמַיִם. אִנּוּן לָקֳבֵיל אַרְבַּע זִמְנִין דְּאִסְתַּכַּל קוּדְשָׁא בְּרִיךְ הוּא בְּאוֹרַיְתָא עַד לָא יָפִּיק עֲבִידְתֵּיהּ לְאוּמְנוּתֵיהּ.","רִבִּי אֶלְעָזָר הֲוָה אָזִיל לְמֶחמֵי לְרִבִּי יוֹסֵי בְּרִבִּי שִׁמְעוֹן בֶּן לָקוֹנְיָא חֲמוֹי וְרִבִּי אַבָּא בַּהֲדֵיהּ, וְהֲוָה טָעִין חַד גַּבְרָא אֲבַּתְרַיְיהוּ. אָמַר רִבִּי אַבָּא נִפְתַּח פִּתְחִין דְּאוֹרַיְיתָא דְּהָא שַׁעֲתָא וְעִדָּנָא הוּא לְאִתְתַּקָּנָא בְאָרְחָן."],[[0,"","סה) \u0003ועל דא כתיב\u0004 וכו': ועל זה כתוב, כי כאשר השמים החדשים והארץ החדשה אשר אני \u0003עושה\u0004 עומדים לפני וגו'. עשיתי לא כתוב, אלא \u0003עושה\u0004, לשון הוה, משום שעושה תמיד, שמים וארץ חדשים, מאלו החידושים והסודות של התורה. ועל זה כתוב, ואשים דברי בפיך ובצל ידי כסיתיך לנטוע שמים וליסוד ארץ. השמים לא כתוב, אלא שמים. בלי ה' הידיעה מפני שאינו סובב על השמים ממש, אלא על שמים המחודשים שנעשו מדברי תורה."],[0,"","פירוש, \u0003עשיתי לא כתיב אלא עושה\u0004, וכו' מורה בזה, שלא לטעות בפירוש הכתוב \u0003דשמים חדשים וארץ חדשה\u0004, שהוא כמו ענין של תיקון דבר הנעשה ונתחדש פעם אחת ודי. כי אינו כן, אלא הם ענין עבודת תמיד. כי הצדיקים שכבר נשלמו בזהרא עלאה, הם הולכים ועושים תדיר שמים וארץ חדשים. שז\"ס צדיקים הולכים מחיל אל חיל (סוף ברכות). ומביא ראיה על זה, כי כתוב \u0003השמים החדשים והארץ החדשה אשר אני עושה ולא כתיב אשר אני עשיתי\u0004, הרי שאלו שמים וארץ הולכים ומתחדשים תדיר מחדושי אורייתא של הצדיקים הגמורים. וכן מביא ראיה מהכתוב \u0003לנטוע שמים\u0004, שאם היה זה לפעם אחת, היה צריך להכתב לנטוע השמים, בה' הידיעה. וכיון שכתוב \u0003שמים\u0004, משמע שנוהג תדיר."],[1,"","סו) \u0003א\"ר אלעזר מהו\u0004 וכו': אר\"א, מהו ובצל ידי כסיתיך. אמר לו, בשעה שנמסרה התורה למשה, באו הרבה רבבות מלאכים עליונים לשרוף אותו בשלהבת פיהם, עד שחיפה עליו הקב\"ה. ועתה, שדבר החידוש שבתורה, עולה ומתעטר ועומד לפני הקב\"ה, הוא מחפה על הדבר ההוא, ומכסה על אדם ההוא, שלא יוודע להם אלא להקב\"ה, ולא יקנאו אותו, עד שנעשה מדבר ההוא שמים חדשים וארץ חדשה. ז\"ש ובצל ידי כסיתיך לנטוע שמים וליסוד ארץ. מכאן, שכל דבר המכוסה מן העין עולה לתועלת עליונה. ז\"ש, ובצל ידי כסיתיך. ולמה נתחפה ונתכסה מן העין, היינו בשביל התועלת העליונה, ז\"ש לנטוע שמים וליסוד ארץ. כמו שלמדנו. דהיינו, כדי שיצמח מזה שמים וארץ חדשים."],[1,"ובצל ידי כסיתיך","וכו', הכוונה היא על הלבוש הנ\"ל הנמשך מהרקיע ומלביש ומכסה על קומת המוחין, (כנ\"ל ד\"ה ההיא מלה ע\"ש). אשר הלבוש הזה הוא בחינת \u0003צל\u0004 המכסה על המוחין ומעלימם מעין זר, ואינם ידועים אלא לקב\"ה בלבדו. ומבאר הטעם, שהוא כדי להעלים המדרגות הגדולות האלו ממלאכי השרת כדי שלא יקנאו בו. וענין הקנאה הזו של המלאכים, הוא בהיותם זכי החומר, נמצא כשמסתכלים בצדיק מגלים בו כעין פחיתות, בקנאתם עליו על המדרגה הגבוהה שזכה, ואח\"כ נאחזים המקטרגים באותה הפחיתות שגילו בו המלאכים."],[1,"","ולפיכך, כשמתלבשת המדרגה בהאי לבוש של הרקיע, שהלבוש הזה מודד לו את המדרגה, שלא יקבל ממנו יותר רק לפי מה שהוא לתועלת העליון יתברך. הרי הוא נשמר מקנאת המלאכים, כי אז יכול הצדיק להיות נשמר מלפגום במדרגה בשוה ממש עם המלאכים."],[1,"","וז\"ש, \u0003דכל מלה דסתים מעינא סלקא לתועלתא עלאה\u0004: רומז בזה שהעין רואה, והלב חומד, ואינו יכול להשמר שתהיה מחשבתו נקיה רק לעשות נ\"ר ליצרו, אלא שהוא מקבל גם לתועלת עצמו. אמנם \u0003הסתים מעינא\u0004 דהיינו המלובש בלבוש הרקיע, בטוח הוא שלא יקבל יותר ממה שעולה לתועלת העליון ית'. וזה אמרו \u0003ואמאי אתחפי ואתכסי מעינא, בגין לתועלתא עלאה\u0004 כמבואר."],[2,"","סז) \u0003ולאמר לציון עמי אתה\u0004: ולאמר, היינו לאמר לאלו השערים והדברים המצוינים אלו על אלו, דהיינו לחידושי התורה, \u0003עמי אתה\u0004, אל תקרא עמי אתה, עם ע' פתוחה, אלא עמי אתה, עם עין חרוקה, שפירושו, להיות שותף עמי, מה אני עשיתי שמים וארץ בדברי, כמו שנאמר, בדבר ה' שמים נעשו, אף אתה כך, שבדברי חכמה שלך, עשית שמים וארץ חדשים. אשרי הם העמלים בתורה."],[2,"","פירוש, בחינת הקבלה נקראת \u0003תרעין\u0004, שהם השערים הפתוחים לקבל, ובחינת ההשפעה ע\"י המ\"ן נקראת \u0003מלין\u0004 כנ\"ל. ואומר שהם \u0003מצויינין אלין על אלין\u0004, כלומר, שהם מתלבשים זה תוך זה וע\"י זה הם מצוינים."],[3,"","סח) \u0003ואי תימא דמלה\u0004 וכו': ואם תאמר, שדבר חידוש של כל אדם, ואפילו, שאינו יודע מה שאומר, עושה את זה. בוא וראה, אותו שאין דרכו בסודות התורה, וחידש דברים שאינו יודע אותם לאמיתם כראוי. אותו דבר החידוש עולה, ויוצא אל אותו הדבר, איש תהפוכות לשון שקר, מתוך נקבת התהום הגדול, והוא מדלג חמש מאות פרסאות לקבל את הדבר ההוא, ולוקח אותו, והולך עם הדבר אל הנקבה שלו ועושה בה רקיע שוא, הנקרא תוהו."],[3,"","ביאור הדברים, כבר ידעת שסוד המ\"ן שמעלים הצדיקים כדי לעשות נ\"ר ליוצרם דהיינו \u0003לתועלתא עלאה\u0004, הם נק' בשם \u0003מלין דאורייתא\u0004 שנתדשו, כי הן מתחדשות ע\"י הזווג העליון והזו\"ן מקבלים מוחין חדשים על ידיהם, עד שזוכים עי\"ז לסוד \u0003לנטוע שמים וליסוד ארץ\u0004 וכו' ונעשים שותפים עם הקב\"ה, כי מתחדשים שמים וארץ ע\"י המלין שלהם כנ\"ל."],[3,"","ואומר אבל \u0003ההוא דלאו אורחיה ברזין דאורייתא\u0004 כלומר, שאינו בקי בדרכי ה' לידע לשמור את עצמו מלפגום במדרגות העליונות. והוא אומר בעצמו, שכוונתו היא \u0003לתועלתא עלאה\u0004, והוא אמנם מטעה את עצמו, כי לא ידע כי בנפשו הוא לידע בבירור שאינו מכוון ח\"ו לצרכו עצמו, הנה ענשו גדול מאד, כי נותן כח לקליפות \u0003לקטלא בני נשא\u0004, כמו שמבאר והולך וז\"ש \u0003וחדש מלין דלא ידע על בורייהון כדקא יאות\u0004, דהיינו שמעלה מ\"ן לזווג העליון, ואינו יודע על בוריו בכל הצורך שהוא באמת כן, הנה אז נמצא, דהאי \u0003איש תהפוכות לשון שקר\u0004 דליג ועושק \u0003לההיא מלה\u0004, כמ\"ש והולך."],[3,"","וז\"ש, \u0003איש תהפוכות לשון שקר מגו נוקבא דתהומא רבא\u0004: כי גם בקליפות יש דכר ונוקבא, אשר הדכר נק' \u0003שוא\u0004 והנוקבא נקראת \u0003שקר\u0004. וביאור הדברים, כי הזכר דקליפה אינו כל כך רע כמו הנוקבא, וכשהוא לעצמו אינו מכשיל בני אדם לשקר בשמא דקב\"ה, ואדרבה להיפך, כי מדבר טוב כפי מראית עין, אלא שהוא רע עין, בסו\"ה אל תלחם את לחם רע עין, אכול ושתה יאמר לך ולבו בל עמך (משלי כ\"ג) וכל הנלכד בידו הוא נושא שם ה' לשוא, כי נפרד מהשי\"ת, ואינו יכול לקבל שום שפע. וז\"ס שאמרו רז\"ל כל המתגאה, אומר הקב\"ה: אין אני והוא יכולין לדור במדור אחד (סוטה ה' ע\"א). שבהיות כוונתו לקבלת צרכיו עצמו, להתרברב להתגאות וכדומה, הנה הוא נלכד ברשותו של רע העין, ונמצאת העלאת מ\"ן שהוא מעלה, אינו ממשיך שום שפע מלמעלה, והוא נושא שם ה' לשוא, וע\"כ נק' הזכר דקליפה \u0003שוא\u0004. כי הקב\"ה אינו יכול להדבק באיש ההוא לדור עמו במדור אחד."],[3,"","והנוקבא דקליפה נק' בשם \u0003שקר\u0004. כי אחר שהאיש ההוא נלכד ברשת הזכר הנק' \u0003שוא\u0004, יש לו כח להזדווג עם הנוקבא שלו שהיא קליפה רעה ומרה, המזייפת שמא דקב\"ה, ומשקרת בו, ואז יורדת ומסיתה, ועולה למעלה ומקטרגת, ונוטלת את נשמתו הימנו."],[3,"","וע\"כ נק' \u0003איש תהפוכות\u0004, כי תחילה אכול ושתה יאמר לך, דהיינו שיעלה מ\"ן למעלה להקב\"ה, וימשיך שפע לצורך גבוה, והוא נראה לו כמו שהוא מסטרא דקדושה, ואח\"כ בכח ה\u0003שוא\u0004 שלו מזדווג עם ה\u0003נוקבא דתהומא רבא\u0004, שעם ה\u0003שקר\u0004 שלה הוא נוטל את נשמתו והורגו. וז\"ש \u0003איש תהפוכות לשון שקר מגו נוקבא דתהומא רבא\u0004 כי הוא מתהפך \u0003לשון שקר\u0004 רק מכח ה\u0003נוקבא דתהומא רבא\u0004 דאשתתף בה, ולא מבחינת עצמו."],[3,"","וז\"ש, \u0003ודלג חמש מאה פרסי לקבלא לההיא מלה\u0004: פי' כי הזו\"ן דטומאה אין להם משורשם רק ו\"ק ונקודה לבד, דהיינו רק לעומת ו\"ק ונקודה דזו\"ן דקדושה, ואין להם שום מקום וכח להתאחז בבינה. אמנם ע\"י \u0003ההיא מלה\u0004, דהיינו המ\"ן שהעלה התחתון, נותן כח לזכר דטומאה לדלג על ז\"ת דבינה הנמשכות בזו\"ן דקדושה, שהן בעקרן רק ה' ספירות חג\"ת נ\"ה, הנקראות \u0003חמש מאה פרסי\u0004, כי ספירות הבינה הן במספר מאות כנודע, וז\"ש \u0003ודלג חמש מאה פרסי לקבלא לההיא מלה\u0004 כי תיכף בעת עלית המ\"ן השיג כח לדלג למקום דלאו דיליה, דהיינו לה' ספירות תחתונות חג\"ת נ\"ה דבינה הנקראות חמש מאה פרסי. לקבלא לההיא מלה. דהיינו בחי' המ\"ן, שהעלה האיש \u0003דלא ידע\u0004 על בוריו אם כוונתו לעשות נ\"ר ליוצרו."],[3,"","וז\"ש, \u0003ואזיל בההיא מלה לגו נוקביה ועביד בה רקיעא דשוא דאקרי תהו\u0004 :כלומר, שהוא מזדווג עם הנוקבא שלו \u0003דתהומא רבא\u0004 על המ\"ן הללו, וממשיך לו אורות דקדושה לחלקו ולבנינו, בדומה לשמים חדשים דקדושה הנעשה ע\"י המ\"ן דקדושה כנ\"ל. ואלו שמים שהמשיך בזווגו נק' \u0003רקיעא דשוא\u0004 מבחינת הזכר, ומבחינת השתתפות עם \u0003הנוקבא דתהומא רבא\u0004, נקרא רקיע \u0003דתהו\u0004. כי \u0003תהו\u0004 שם הזכר, והשם של הנקבה הוא תהום וז\"ש \u0003ועביד רקיע דשוא\u0004 מכח בחינתו עצמו, \u0003דאקרי תהו\u0004 מכח השתתפותו עם \u0003תהום\u0004 שהיא הנוקבא."],[4,"","סט) \u0003וטס בההוא רקיעא\u0004 וכו': ואותו איש תהפוכות מעופף ברקיע שוא ההוא, ששת אלפים פרסאות בבת אחת. ואחר שרקיע שוא זה עומד, מיד יוצאת אשת זנונים, ומחזיקה באותו הרקיע שוא, ומשתתפת בו. ומשם היא יוצאת והורגת כמה אלפים ורבבות. כי בשעה שהיא נמצאת באותו הרקיע, יש לה הרשות והיכולת לעוף ולעבור את כל העולם ברגע אחד."],[4,"","פירוש, כי אלו המוחין שנמשכו לו בההוא \u0003רקיעא דשוא\u0004, הם מס\"א שכנגד החכמה דקדושה, שספירותיו הן במספר אלפים. וז\"ש \u0003וטס בההוא רקיעא\u0004 שהוא מעופף ונאחז על ידו, \u0003שיתא אלפי פרסי בזמנא חדא\u0004, בשש הספירות חג\"ת נה\"י דחכמה, המכונות \u0003שיתא אלפי פרסי\u0004, בהיותן מחכמה."],[4,"","וז\"ש, \u0003כיון דהאי רקיעא דשוא קאים, נפקת מיד אשת זנונים ואתקיף בההוא רקיעא דשוא ואשתתפת ביה\u0004: כלומר, אחר שנשלמו השמים החדשים דקליפת הזכר, הנק' רק בשם \u0003שוא\u0004 אז מגלה \u0003הנוקבא דתהומא רבא\u0004 את כחה, וכחה מתקיף את הרקיע, לשקר בשמא דקב\"ה, והיא נמצאת מעופפת ברקיע, ואז נקרא \u0003רקיע דתהו\u0004 כנ\"ל."],[4,"","וז\"ש, \u0003ומתמן, נפקת, וקטלת\u0004 וכו' \u0003בגין דכד קיימת בההוא רקיעא אית לה רשו ויכלתא למהוי טס כל עלמא ברגעא חדא\u0004: כי בהיותה משותפת בההוא רקיעא היא מתחזקת ומתגדלת עוד יותר מקומת הזכר, כי הזכר גדל רק ו\"ק דחכמה, שהם שיתא אלפי פרסאות כנ\"ל, והנוקבא גדלה על ידו בעשר ספירות שלמות, דהיינו עולם שלם, וז\"ש \u0003אית לה רשו ויכלתא למהוי טס כל עלמא\u0004 דהיינו עולם שלם בע\"ס. \u0003ברגעא חדא\u0004 ה\"ס וכמה זעמו רגע. (ברכות ז' ע\"א). וע\"כ כחה גדול לקטלא לבני נשא לאלפים ורבבות. בסו\"ה כי רבים חללים הפילה (משלי ז'), וביאר לנו ר\"ש, כי זה לעומת זה עשה אלהים, וכמו שע\"י המ\"ן דצדיקים נבנים תמיד שמים וארץ חדשים לקדושה, כן ע\"י המ\"ן של אלו דלא ידעון איך למפלח לקב\"ה על בורייהון, הולכים ונבנים שמים וארץ לקליפות."],[5,"","ע) \u0003ועל דא כתיב\u0004 וכו': ועל זה כתוב, הוי מושכי העון בחבלי השוא. \u0003העון\u0004, זהו זכר. וכעבות העגלה חטאה. מהו חטאה. היא הנקבה, דהיינו אשת זנונים הנ\"ל, הנקראת \u0003חטאה\u0004. הוא, החוטא, מושך, אותו הנקרא \u0003עון\u0004, דהיינו את הזכר, בחבלי שוא האלו. ולאחר זה, כעבות העגלה חטאה. שהוא מושך, לאותה הנקבה הנקראת \u0003חטאה\u0004, שהיא מתגברת שם לעוף ולהרוג בני אדם. ועל כן, כי רבים חללים הפילה. מי הפילה. היא אותה \u0003החטאה\u0004 ההורגת בני אדם. ומי גרם לזה. היינו תלמיד חכם שלא הגיע להוראה, ומורה. הרחמן יצילנו."],[5,"","פירוש. כמ\"ש לעיל, שהזכר אינו כל כך רע כמו הנוקבא, כי הוא מדמה עצמו לקדושה, בסו\"ה אכול ושתה יאמר לך ולבו בל עמך (משלי כ\"ג), וע\"כ הוא נקרא \u0003שוא\u0004. אמנם משום זה, כחו גדול ביותר ללכוד בני אדם לרשתו, ואחר שנפל לרשתו בא ומזדווג בנוקביה, ואז \u0003כעבות העגלה חטאה\u0004 שמשכתו לתהומא רבא. וזה שיעור הכתוב \u0003הוי מושכי עון בחבלי השוא\u0004. כי \u0003השוא\u0004, רק קושר אותו בחבלים ולוכד אותו, ואח\"כ הוא מפילו לפני הנוקבא שלו, ואז \u0003כעבות העגלה חטאה\u0004 אשר \u0003החטאה\u0004 מפילתו לתהומא רבא והורגתו. וז\"ש, \u0003דא ההיא חטאה דקטלית ב\"נ\u0004."],[6,"","עא) \u0003אמר ר' שמעון\u0004 וכו': אר\"ש אל החברים. בבקשה מכם, שלא תוציאו מפיכם דבר תורה, שלא ידעתם ולא שמעתם מאילן גדול כראוי. בשביל שלא תהיו גורמים לאותה \u0003חטאה\u0004, להרוג המוני בני אדם חנם. פתחו כולם ואמרו, הרחמן יצילנו, הרחמן יצילנו."],[6,"","פירוש \u0003מלה דאורייתא\u0004 וכו', כלומר, אם אתם יודעים מעצמכם, מוטב,, ואם לא, צריכים אתם לשמוע איך לעבוד את ה' \u0003מאילנא רברבא כדקא יאות\u0004, דהיינו מאדם גדול שאפשר לסמוך עליו. \u0003בגין דלא תהוון גרמין\u0004 וכו'."],[7,"","עב) \u0003תא חזי באורייתא\u0004 וכו': בוא וראה, בתורה ברא הקב\"ה את העולם. והעמידוהו, שכתוב, ואהיה אצלו אמון ואהיה שעשועים יום יום. שסובב על התורה שהיה הקב\"ה משתעשע בה אלפים שנה מטרם שנברא העולם. (כנ\"ל אות כ\"ב) והוא הסתכל בה פעם ושתים ושלש וארבע פעמים, ואח\"כ אמר להם. ולבסוף עשה בה מעשה. ללמד בני אדם שלא יבואו לטעות בה. כמו שאתה אומר, אז ראה ויספרה הכינה וגם חקרה ויאמר לאדם. אשר ראה, הוא פעם א'. ויספרה, פעם ב'. הכינה, פעם ג'. וגם חקרה, פעם ד'. ואח\"כ אמר להם, דהיינו, ויאמר לאדם."],[8,"","עג) \u0003ולקביל ארבע זמנין\u0004 וכו': ונגד ארבע פעמים אלו שכתוב, אז ראה, ויספרה, הכינה, וגם חקרה, ברא הקב\"ה מה שברא. ועד שלא עשה מעשהו, הביא בתחילה ארבע מלים, שכתוב, בראשית, ברא, אלקים, את, הרי ארבע. ואח\"כ כתוב השמים, שהם כנגד ארבע הפעמים שנסתכל הקב\"ה בתורה מטרם שהוציא מעשהו למלאכתו."],[8,"","פירוש. \u0003ולקביל ארבע זמנין אינון\u0004 וכו': אלו ארבעה זמנין ה\"ס חו\"ב תו\"מ: \u0003אז ראה\u0004 הוא חכמה, \u0003ויספרה\u0004 הוא בינה, \u0003הכינה\u0004 הוא ז\"א, \u0003וגם חקרה\u0004 הוא מלכות. ואחר ד' ההתלבשויות האלו, \u0003ברא קב\"ה מה דברא\u0004. וכן רומזות ד' התיבות הראשונות שבתורה, \u0003בראשית\u0004 היא חכמה, \u0003ברא\u0004 היא בינה, \u0003אלהים\u0004 היא ז\"א, \u0003את\u0004 היא מלכות. ואחר ד' התלבשויות אלו, נבראו השמים."],[9,"","עד) \u0003רבי אלעזר הוה\u0004 וכו': ר' אלעזר הלך לראות את ר' יוסי ברבי שמעון בן לקוניא חותנו, ורבי אבא עמו. ואיש אחד היה מחמר אחריהם, דהיינו שהיה מוליך חמוריהם. אמר ר' אבא, נפתח פתחי התורה, שעתה השעה והזמן להתתקן בדרכנו. \u0003טעין\u0004 פירושו דוקר, כי על מדוקרים מתרגם מטענין, (ירמיה ל\"ז) והוא שם מושאל למוליך חמורים, מפני שדרכו לדקור את החמורים במחט, כדי שימהרו ללכת."]],[[0,"","וְעַל זֶה כָּתוּב (ישעיה סו) כִּי כַאֲשֶׁר הַשָּׁמַיִם הַחֲדָשִׁים וְהָאָרֶץ הַחֲדָשָׁה אֲשֶׁר אֲנִי עֹשֶׂה עֹמְדִים לְפָנַי וְגוֹ'. עָשִׂיתִי לֹא כָתוּב, אֶלָּא עוֹשֶׂה. שֶׁעוֹשֶׂה תָמִיד מֵאוֹתָם הַחִדּוּשִׁים וְהַסּוֹדוֹת שֶׁל הַתּוֹרָה. וְעַל זֶה כָּתוּב (שם נא) וָאָשִׂם דְּבָרַי בְּפִיךְ וּבְצֵל יָדִי כִּסִּיתִיךְ לִנְטֹעַ שָׁמַיִם וְלִיסֹד אָרֶץ. לֹא כָתוּב הַשָּׁמַיִם, אֶלָּא שָׁמַיִם."],[1,"","אָמַר רַבִּי אֶלְעָזָר, מַה זֶּה וּבְצֵל יָדִי כִּסִּיתִיךְ אָמַר לוֹ, בְּשָׁעָה שֶׁנִּמְסְרָה הַתּוֹרָה לְמֹשֶׁה, בָּאוּ כַּמָּה רִבּוֹאוֹת שֶׁל מַלְאָכִים עֶלְיוֹנִים לִשְׂרֹף אוֹתוֹ בְּשַׁלְהֶבֶת פִּיהֶם, עַד שֶׁכִּסָּה עָלָיו הַקָּדוֹשׁ- בָּרוּךְ- הוּא. וְכָעֵת שֶׁהַדָּבָר הַזֶּה עוֹלֶה וּמִתְעַטֵּר וְעוֹמֵד לִפְנֵי הַקָּדוֹשׁ- בָּרוּךְ- הוּא, הוּא מְכַסֶּה עַל אוֹתוֹ הַדָּבָר, וּמְכַסֶּה עַל אוֹתוֹ הָאָדָם שֶׁלֹּא יֻכַּר אֲלֵיהֶם אֶלָּא הַקָּדוֹשׁ-בָּרוּךְ-הוּא, וְלֹא יְקַנְּאוּ לוֹ, עַד שֶׁנַּעֲשֶׂה מֵהַדָּבָר (תורה) הַהוּא שָׁמַיִם חֲדָשִׁים וְאֶרֶץ חֲדָשָׁה. זֶהוּ שֶׁכָּתוּב וּבְצֵל יָדִי כִּסִּיתִיךְ לִנְטֹעַ שָׁמַיִם וְלִיסֹד אָרֶץ. מִכָּאן שֶׁכָּל דָּבָר שֶׁנִּסְתָּר מִן הָעַיִן, עוֹלֶה לְתוֹעֶלֶת עֶלְיוֹנָה. זֶהוּ שֶׁכָּתוּב וּבְצֵל יָדִי כִּסִּיתִיךְ. וְלָמָּה נֶעְלָם וּמִתְכַּסֶּה מִן הָעַיִן בִּשְׁבִיל תּוֹעֶלֶת עֶלְיוֹנָה. זֶהוּ שֶׁכָּתוּב לִנְטֹעַ שָׁמַיִם וְלִיסֹד אָרֶץ, כְּמוֹ שֶׁאָמַ רְנוּ."],[2,"","וְלֵאמֹר לְצִיּוֹן עַמִּי אָתָּה. וְלֵאמֹר - לְאוֹתָם הַשְּׁעָרִים וְהַדְּבָרִים הַמְצֻיָּנִים אֵלּוּ עַל אֵלּוּ - עַמִּי אָתָּה. אַל תִּקְרֵי עַמִּי אֶלָּא עִמִּי אָתָּה, לִהְיוֹת שֻׁתָּף עִמִּי. מָה אֲנִי בַּדִּבּוּר שֶׁלִּי עָשִׂיתִי שָׁמַיִם וָאָרֶץ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים לג) בִּדְבַר ה' שָׁמַיִם נַעֲשׂוּ - אַף כָּךְ אַתָּה. אַשְׁרֵי אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה. וְאִם תֹּאמַר שֶׁדִּבּוּר שֶׁל כָּל אָדָם שֶׁלֹּא יוֹדֵעַ עוֹשֶׂה כָּזֶה."],[3,"","בֹּא רְאֵה, אוֹתוֹ שֶׁאֵין דַּרְכּוֹ בְּסוֹדוֹת הַתּוֹרָה וּמְחַדֵּשׁ דְּבָרִים שֶׁאֵינוֹ יוֹדֵעַ עַל בֻּרְיָם כָּרָאוּי, אוֹתוֹ הַדָּבָר עוֹלֶה וְיוֹצֵא לְאוֹתוֹ הַדָּבָר אִישׁ תַּהְפּוּכוֹת לְשׁוֹן שָׁקֶר מִתּוֹךְ נֶקֶב הַתְּהוֹם הַגָּדוֹל, וּמְדַלֵּג חֲמֵשׁ מֵאוֹת פַּרְסָאוֹת לְקַבֵּל אֶת אוֹתוֹ הַדָּבָר. וְנוֹטֵל אוֹתוֹ, וְהוֹלֵךְ עִם אוֹתוֹ הַדָּבָר לְתוֹךְ הַנֶּקֶב שֶׁלּוֹ, וְעוֹשֶׂה בּוֹ רָקִיעַ שֶׁל שָׁוְא שֶׁנִּקְרָא תֹהוּ."],[4,"","וְטָס בְּאוֹתוֹ הָרָקִיעַ אוֹתוֹ אִישׁ תַּהְפּוּכוֹת שֵׁשֶׁת אֲלָפִים פַּרְסָאוֹת בְּפַעַם אַחַת. וְכֵיוָן שֶׁהָרָקִיעַ הַזֶּה שֶׁל שָׁוְא עוֹמֵד, מִיָּד יוֹצֵאת אֵשֶׁת זְנוּנִים וּמִתְחַזֶּקֶת בְּאוֹתוֹ הָרָקִיעַ שֶׁל שָׁוְא (נ\"א: היא) (נ\"א: ואיש תהפוכות) וּמִשְׁתַּתֶּפֶת עִמּוֹ, וּמִשָּׁם יוֹצֵאת וְהוֹרֶגֶת כַּמָּה אֲלָפִים וּרְבָבוֹת. מִשּׁוּם שֶׁכַּאֲשֶׁר הִיא עוֹמֶדֶת בָּרָקִיעַ הַהוּא, יֵשׁ לָהּ רְשׁוּת וִיכֹלֶת לִהְיוֹת טָסָה אֶת כָּל הָעוֹלָם בְּרֶגַע אֶחָד."],[5,"","וְעַל זֶה כָּתוּב (ישעיה ה) הוֹי מֹשְׁכֵי הֶעָון בְּחַבְלֵי הַשָּׁוְא. הֶעָון זֶה הַזָּכָר. וְכַעֲבוֹת הָעֲגָלָה חַטָּאָה, מִי הַחַטָּאָה זוֹ הַנְּקֵבָה שֶׁנִּקְרֵאת חַטָּאָה. הוּא מוֹשֵׁךְ אֶת אוֹתוֹ שֶׁנִּקְרָא עָון בְּאוֹתָם חַבְלֵי הַשָּׁוְא. וְאַחַר כָּךְ כַּעֲבוֹת הָעֲגָלָה חַטָּאָה, אֶת אוֹתָהּ הַנְּקֵבָה שֶׁנִּקְרֵאת חַטָּאָה, שֶׁשָּׁם הִתְגַּבְּרָה לִהְיוֹת טָסָה לַהֲרֹג בְּנֵי אָדָם. וְעַל זֶה (משלי ז) כִּי רַבִּים חֲלָלִים הִפִּילָה. מִי הִפִּילָה זוֹ אוֹתָהּ הַחַטָּאָה שֶׁהוֹרֶגֶת בְּנֵי אָדָם. מִי גָרַם אֶת זֶה תַּלְמִיד הֶחָכָם שֶׁלֹּא הִגִּיעַ לְהוֹרָאָה וּמוֹרֶה. הָרַחֲמָן יַצִּילֵנוּ."],[6,"","אָמַר רַבִּי שִׁמְעוֹן לַחֲבֵרִים, בְּבַקָּשָׁה מִכֶּם שֶׁלֹּא תוֹצִיאוּ מִפִּיכֶם דְּבַר תּוֹרָה שֶׁלֹּא יְדַעְתֶּם וְלֹא שְׁמַעְתֶּם מֵעֵץ גָּדוֹל כָּרָאוּי, כְּדֵי שֶׁלֹּא תִהְיוּ גוֹרְמִים לְאוֹתָהּ הַחַטָּאָה לַהֲרֹג הֲמוֹנֵי בְּנֵי אָדָם לְחִנָּם. פָּתְחוּ כֻלָּם וְאָמְרוּ, הָרַחֲמָן יַצִּילֵנוּ, הָרַחֲמָן יַצִּילֵנוּ."],[7,"","בֹּא רְאֵה, בַּתּוֹרָה בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, וְהִנֵּה בֵּאֲרוּהָ שֶׁכָּתוּב (שם ח) וָאֶהְיֶה אֶצְלוֹ אָמוֹן וָאֶהְיֶה שַׁעֲשׁוּעִים יוֹם יוֹם. וְהוּא הִסְתַּכֵּל בָּהּ פַּעַם וּשְׁתַּיִם וְשָׁלֹשׁ וְאַרְבַּע פְּעָמִים, וְאַחַר כָּךְ אָמַר אוֹתָם, וְאַחַר כָּךְ עָשָׂה בָּהּ מַעֲשֶׂה, לְלַמֵּד אֶת בְּנֵי אָדָם שֶׁלֹּא יָבאוּ לִטְעוֹת בָּהּ, כְּמוֹ שֶׁנֶּאֱמַר (איוב כח) אָז רָאָהּ וַיְסַפְּרָהּ הֱכִינָהּ וְגַם חֲקָרָהּ וַיֹּאמֶר לָאָדָם."],[8,"","וּכְנֶגֶד אַרְבַּע פְּעָמִים הָהֵם שֶׁכָּתוּב, אָז רָאָהּ, וַיְסַפְּרָהּ, הֱכִינָהּ, וְגַם חֲקָרָהּ - בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת מַה שֶּׁבָּרָא. וְטֶרֶם שֶׁהוֹצִיא אֶת הַמַּעֲשֶׂה שֶׁלּוֹ, הִכְנִיס בָּרִאשׁוֹנָה אַרְבַּע תֵּבוֹת, שֶׁכָּתוּב בְּ'רֵאשִׁית בָּ'רָא אֱ'לֹהִים אֵ'ת. הִנֵּה אַרְבַּע. וְאַחַר כָּךְ הַשָּׁמַיִם - הֵם כְּנֶגֶד אַרְבַּע הַפְּעָמִים שֶׁהִסְתַּכֵּל הַקָּדוֹשׁ בָּרוּךְ הוּא בַּתּוֹרָה טֶרֶם יוֹצִיא אֶת מַעֲשֵׂהוּ לִמְלַאכְתּוֹ."],[9,"","רַבִּי אֶלְעָזָר הָיָה הוֹלֵךְ לִרְאוֹת אֶת רַבִּי יוֹסֵי בְּרַבִּי שִׁמְעוֹן בֶּן לָקוֹנְיָא חָמִיו, וְרַבִּי אַבָּא עִמּוֹ, וְהָיָה מְחַמֵּר אִישׁ אֶחָד אַחֲרֵיהֶם. אָמַר רַבִּי אַבָּא, נִפְתַּח פְּתָחִים שֶׁל תּוֹרָה, שֶׁהֲרֵי הַשָּׁעָה וְהַזְּמַן הוּא לְהִתְתַּקֵּן (להסתדר) בְּדַרְכֵּנוּ."]]],[["פָּתַח רִבִּי אֶלְעָזָר וְאָמַר (ויקרא י״ט:ל׳) אֶת שַׁבְּתוֹתַי תִּשְׁמוֹרוּ. תָּא חֲזֵי, בְּשִׁית יוֹמִין בְּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא. וְכָל יוֹמָא וְיוֹמָא גָלֵי עֲבִידְתֵּיהּ וְיָהַב חֵילֵיהּ בְּהַהוּא יוֹמָא. אֵימָתַי גָּלֵי עֲבִידְתֵּיהּ וְיָהַב חֵילֵיהּ. בְּיוֹמָא רְבִיעָאָה. בְּגִין דְּאִנּוּן תְּלַת יוֹמִין קַדְמָאִין כּוּלְהוּ הֲווּ סְתִימִין וְלָא אִתְגָּלוּ, כֵּיוָן דְּאֲתָא יוֹמָא רְבִיעָאָה אַפִּיק עֲבִידְתָּא וְחֵילָא דְּכוּלְהוּ.","דְּהָא אֶשָׁא וּמַיָא וְרוּחָא אַף עַל גַּב דְּאִנּוּן תְּלַת יְסוֹדִין עִלָּאִין, כֻּלְהוּ תַּלְיָין, וְלָא אִתְגְּלִי עֲבִידְתָּא דִלְהוֹן, עַד דְּאַרְעָא גָּלֵי לוֹן, כְּדֵין אִתְיְדַע אוּמְנוּתָא דְּכָל חַד מִנַּיְיהוּ.","וְאִי תֵימָא הָא בְּיוֹמָא תְּלִיתָאָה הֲוָה דִּכְתִיב תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא וּכְתִיב וַתּוֹצֵא הָאָרֶץ (דשא). אֶלָּא הַאי אַף עַל גַּב דִּכְתִיב בְּיוֹמָא תְּלִיתָאָה, רְבִיעָאָה הֲוָה וְאִתְכְּלִיל בְּיוֹמָא תְּלִיתָאָה לְמֶהֱוֵי חַד בְּלָא פִּירוּדָא. וּלְבָתַר יוֹמָא רְבִיעָאָה אִתְגְּלִי עֲבִידְתֵּיהּ לְאַפָּקָא אוֹמָנָא לְאוּמָנוּתֵיהּ דְּכָל חַד וְחַד. בְּגִין דְּיוֹמָא רְבִיעָאָה אִיהוּ רַגְלָא רְבִיעָאָה דְּכֻּרְסְיָיא עִלָּאָה.","וְכָל עֲבִידְתַּיְיהוּ דְּכֻלְהוּ בֵּין יוֹמִין קַדְמָאִין וּבֵין יוֹמִין בַּתְרָאִין הֲווּ תַּלְיָין בְּיוֹמָא דְשַׁבָּתָּא הֲדָא הוּא דִכְתִיב (בראשית ב׳:ב׳) וַיְכַל אֱלֹהִים בַּיּוֹם הַשְּׁבִיעִי, דָּא שַׁבָּת, וְדָא הוּא רַגְלָא רְבִיעָאָה דְּכֻּרְסְיָיא.","וְאִי תֵימָא אִי הָכִי, מַהוּ אֶת שַׁבְּתוֹתַי תִּשְׁמוֹרוּ תְּרֵין. אֶלָּא שַׁבָּת (תרומה קל\"ה ב) דְּמַעֲלֵי שַׁבְּתָא וְשַׁבַּתָּא דְיוֹמָא מַמָּשׁ לֵית לוֹן פִּירוּדָא.","אָמַר (להו) הַהוּא טַיְיעָא דְּהֲוָה טָעִין בַּתְרַיְיהוּ, וּמַהוּ וּמִקְדָּשִׁי תִּירָאוּ. אָמַר לֵיהּ דָּא קִדּוּשָׁא דְשַׁבָּת. אָמַר לֵיהּ וּמַהוּ קִדּוּשָׁא דְּשַׁבָּת. אָמַר לֵיהּ דָּא קִדּוּשָׁא דְּאִתְמַשְּׁכָא (עליה) מִלְּעֵילָא. אָמַר לֵיהּ אִי הָכִי עֲבֵידַת לְשַׁבָּת דְּלָאו אִיהוּ קֹדֶשׁ, אֶלָּא קִדּוּשָׁא דְּשַׁרְיָא עֲלוֹי מִלְּעֵילָא. אָמַר רִבִּי אַבָּא וְהָכִי הוּא (ישעיהו נ״ח:י״ג) וְקָרָאתָ לַשַּׁבָּת עוֹנְג לִקְדוֹשׁ יְיָ מְכוּבָּד, אִדְכַּר שַׁבָּת לְחוּד וּקְדוֹשׁ ה' לְחוּד. אָמַר לֵיהּ אִי הָכִי מַאן קְדוֹשׁ ה'. אָמַר לֵיהּ קְדוּשָׁא דְּנַחֲתָא מִלְּעֵילָא וְשַׁרְיָא עֲלֵיהּ. אָמַר לֵיהּ אִי קְדוּשָׁא דְאִתְמַשְּׁכָא מִלְּעֵילָא אִקְרֵי מְכוּבָּד אִתְחַזֵּי דְּשַׁבָּת לָאו אִיהוּ מְכוּבָּד וּכְתִיב וְכִבַּדְתּוֹ. אָמַר רִבִּי אֶלְעָזָר לְרִבִּי אַבָּא אַנַח לְהַאי גַבְרָא דְּמִלָּה (חדתא) דְחָכְמְתָא אִית בֵּיהּ דְּאֲנַן לָא יְדַעְנָא בָהּ. אָמְרוּ לֵיהּ אֵימָא אַנְתְּ.","פָּתַח וְאָמַר, (ויקרא יט) אֶת שַׁבְּתוֹתַי. אֶת לְאַסְגָּאָה תְּחוּם שַׁבָּת דְּאִיהוּ תְּרֵין אַלְפִין אַמִּין לְכָל סִטְרָא (ויקהל ר\"ז א). וּבְגִין כָּךְ אַסְגֵי אֶת. שַׁבְּתוֹתַי (נ\"א דא) שַׁבָּת עִלָּאָה וְשַׁבָּת תַּתָּאָה דְּאִנּוּן תְּרֵין כְּלִילָן כְּחֲדָא וּסְתִימִין כְּחֲדָא.","אִשְׁתָּאַר שַׁבָּת (יתרו צ\"ב א' בר\"מ) אָחֳרָא דְּלָא אִדְכַּר וְהֲוָה בְּכִסּוּפָא. אָמְרָה קַמֵּיהּ מָארֵי דְעָלְמָא מִיּוֹמָא דְּעַבְדַּת לִי שַׁבָּת אִתְקָרֵינָא וְיוֹמָא לָאו אִיהוּ בְּלָא לֵילְיָא. אָמַר לָהּ בְּרַתִּי שַׁבָּת אַנְתְּ וְשַׁבָּת קָרֵינָא לָךְ, אֲבָל הָא אֲנָא מְעַטֵּר לָךְ בְּעִטְרָא עִלָּאָה יַתִּיר. אַעֲבַר כְּרוֹזָא וְאָמַר מִקְדָּשִׁי תִּירָאוּ. וְדָא שַׁבָּת דְּמַעֲלֵי שַׁבַּתָּא דְּאִיהִי יִרְאָה, וְשַׁרְיָא בָהּ יִרְאָה. וּמָאן אִיהוּ. דְּקוּדְשָׁא בְּרִיךְ הוּא אַכְלִיל וְאָמַר אֲנִי ה'. וְאֲנָא שְׁמַעְנָא מֵאַבָּא דְּאָמַר הָכִי. וְדַיֵּיק אֶת לְאַסְגָּאָה תְּחוּם שַׁבָּת. שַׁבְּתוֹתַי דָּא עִגּוּלָא (רכ\"ט א', תצוה ק\"פ א', ויקהל ר\"ה א) וְרִבּוּעַ דִּלְגוֹ, וְאִנּוּן תְּרֵין. וּלְקֳבֵיל אִנּוּן תְּרֵין אִית תְּרֵי קְדוּשָׁתֵי דְּאִית לָנוּ לְאַדְכָּרָא, חַד וַיְכֻלּוּ, וְחַד קָדוֹשׁ. וַיְכֻלּוּ אִית בֵּיהּ תְּלָתִין וְחֲמֵשׁ תֵּיבִין. וּבִקְדוּשָׁה (ובקידושא) דְּאֲנַן מְקַדְּשִׁין תְּלָתִין וְחֲמֵשׁ תֵּיבִין. וְסָלִיק כֹּלָּא לְשִׁבְעִין שְׁמָהָן דְּקוּדְשָׁא בְּרִיךְ הוּא וּכְנְסֶת יִשְׂרָאֵל אִתְעַטַּר בְּהוּ.","וּבְגִין דְּעִגּוּלָא וְרִבּוּעָא דָא אִנּוּן שַׁבְּתוֹתַי, כְּלִילָן תַּרְוַיְיהוּ בְּשָׁמוֹר דִּכְתִיב תִּשְׁמוֹרוּ. דְּהָא שַׁבָּת עִלָּאָה הָכָא לָא אִתְכְּלִיל בְּשָׁמוֹר אֶלָּא בְּזָכוֹר, דְּהָא מַלְכָּא עִלָּאָה בְּזָכוֹר אִסְתָּיָּים. וְעַל דָּא אִקְרֵי מַלְכָּא דִּשְׁלָמָא דִילֵיהּ, וּשְׁלָמָא דִילֵיהּ זָכוֹר אִיהוּ. וְעַל דָּא לֵית מַחְלוֹקֶת לְעֵילָא.","בְּגִין דִּתְרֵין שְׁלוֹמוֹת לְתַתָּא חַד יַעֲקֹ\"ב וְחַד יוֹסֵ\"ף. וּבְגִין כָּךְ כְּתִיב תְּרֵי זִמְנֵי (ישעיהו נ״ז:י״ט) שָׁלוֹם שָׁלוֹם לָרָחוֹק וְלַקָּרוֹב. לָרָחוֹק דָּא יַעֲקֹב, וְלַקָּרוֹב דָּא יוֹסֵף. לָרָחוֹק כְּמָא דְאַתְּ אָמֵר, (ירמיהו ל״א:ג׳) מֵרָחוֹק יְיָ נִרְאָה לִי (שמות ב׳:ד׳) וַתֵּתַצַּב אֲחוֹתוֹ מֵרָחוֹק. וְלַקָּרוֹב כְּמָא דְאַתְּ אָמֵר, (דברים ל״ב:י״ז) חֲדָשִׁים מִקָּרוֹב בָּאוּ. מֵרָחוֹק דָּא נְקוּדָה עִלָּאָה דְקַיְימָא בְּהֵיכָלֵיהּ."],[[0,"","עה) \u0003פתח ר' אלעזר\u0004 וכו': פתח ר\"א ואמר, את שבתותי תשמורו. בוא וראה, בששת ימים ברא הקב\"ה את העולם. וכל יום ויום גילה מעשהו ונתן באותו יום את כחו. מתי גילה מעשהו ונתן כחו. הוא, ביום הרביעי. בשביל שאותם שלשת ימים הראשונים, היו סתומים כולם ולא נגלו, כיון שבא יום הרביעי הוציא המעשה והכח של כולם."],[0,"","פירוש. \u0003בההוא יומא\u0004, היינו ביום \u0003השבת\u0004. שית יומין הם חג\"ת נה\"י, והם מגלים שלמות מלאכתם וכחם ביום השבת. שהוא מלכות."],[0,"","ומ\"ש, \u0003אימתי גלי עבידתיה ויהב חיליה ביומא רביעאה\u0004 וכו': הנה מקודם לכן אמר, דכל יומא ויומא יהב חיליה \u0003ביום השבת\u0004. וכאן אומר אימתי היה זה רק \u0003ביום רביעי\u0004. ויש להבין זאת. והענין הוא כי המלכות נקראת רביעי ושביעי, \u0003רביעי לאבות\u0004 שהם חג\"ת, \u0003ושביעי לבנין\u0004 שהם נה\"י, וכן אומר ר\"ש (לעיל אות ד'). כי \u0003הנצנים\u0004 שהם חג\"ת \u0003נראו בארץ ביום השלישי ועת הזמיר הגיע דא יום רביעי\u0004. שאז נתמעטה המלכות ועלתה לעיבור ב' ע\"ש. הרי שהמלכות נאצלה מחג\"ת ביום ג', ונתקנה ביום ד', ע\"י נצח דז\"א שהוא יום ד', וע\"כ מבחינה זו היא נקראת \u0003רביעי לאבות\u0004. ואח\"כ אומר שם \u0003בארצנו דא יום שבת דאיהו דוגמת ארץ החיים\u0004, הרי שהמלכות הנקראת \u0003ארץ\u0004 היא בחינת \u0003יום שבת\u0004, והיא \u0003שביעי לבנין\u0004. וענין זה, של רביעי ושביעי, הוא שמתבאר כאן."],[0,"","וזה אמרו \u0003בגין דאינון תלת יומין קדמאין כולהו הוו סתימין ולא אתגלו\u0004, כי כל זמן שהמדרגה היא בחסרון המלכות, נבחנת לסתומה ובלתי נודעת ובהשגתה את המלכות משגת את שלמותה וזה סוד ששת ימי המעשה ושבת, כי לכאורה צריכים ששת ימי המעשה להיות יותר חשובים מיום השבת, שהרי חג\"ת נה\"י שהם ששת ימי המעשה חשובים יותר מהמלכות שהיא יום השבת. אלא הפי' הוא, שכל שבוע הוא מדרגה בפ\"ע שבימות החול היא חסרה המלכות, וע\"כ המדרגה סתומה ואין בה קדושה, כי בחסר המלכות חסר ג\"ר דאורות כנ\"ל, ורק בהתגלות המלכות במדרגה ההיא, דהיינו בביאת יום השבת, אז מתגלה הקדושה בכל המדרגה דהיינו גם בששת ימי המעשה, והקדושה שורה בכל השבוע ההוא ועד\"ז גם בששת ימי בראשית, כאשר נאצלו \u0003ג' יומין קדמאין\u0004 שהם חג\"ת מטרם שנגלתה המלכות הרי היו \u0003סתימין\u0004 בלי גילוי הקדושה שבהם, וכשנאצלה המלכות, שהיא ביום רביעי אז נתגלתה קדושתם של כל ארבעת הימים. וז\"ש \u0003כיון דאתא יומא רביעאה אפיק עבידתא וחילא דכלהו\u0004 דהיינו שנתגלתה הקדושה במלאכה ובכח דכל ארבעת הימים, כי המלכות משלמת המדרגה."],[1,"","עו) \u0003דהא אשא ומיא\u0004 וכו': כי אש ומים ורוח, שהם חג\"ת, וה\"ס שלשת הימים הראשונים, אע\"פ שהם, שלשה יסודות עליונים, דהיינו ג' ספירות חג\"ת, כולם היו תלוים ולא נגלה המעשה שלם עד שהארץ, שה\"ס מלכות, גילתה אותם. אז נודעה מלאכתם של כל אחד ואחד מהם."],[2,"","עז) \u0003ואי תימא הא\u0004 וכו': ואם תאמר, הרי ביום השלישי הוא, שכתוב, תדשא הארץ דשא, וכתוב, ותוצא הארץ. הרי שגילוי מעשה של הארץ, שהוא המלכות, היה ביום השלישי. ומשיב, אלא אע\"פ שזה כתוב ביום השלישי, שה\"ס ת\"ת, יום הרביעי היה, שה\"ס מלכות, ונכלל ביום השלישי, להיות, ת\"ת ומלכות, אחד בלי פרוד. ואחר כך, גילה יום הרביעי מעשהו, להוציא את האומן למלאכתו של כל אחד ואחד, מחג\"ת, משום שיום הרביעי הוא הרגל הרביעית של כסא העליון, שהוא בינה, שד' רגלים שלו הם חג\"ת ומלכות."],[2,"","פירוש. כי בהיות המלכות מגלית קדושת ג' הימים, ע\"כ עלתה ונכללה ביום השלישי, כדי לגלות עליהם היחוד דהיינו \u0003למהוי חד בלא פרודא\u0004."],[2,"","וז\"ש, \u0003ולבתר יומא רביעאה\u0004 וכו', כי ביום רביעי השלימה המלכות על ג' הימים הראשונים בלבד. ולאחר כך יצאו עוד ג' ימים, שהם נצח הוד יסוד, וז\"ש \u0003ולבתר יומא רביעאה, אתגלי עבידתיה לאפקא אומנא לאומנותיה דכל חד וחד\u0004, כי אחר שנתגלתה הקדושה על ג' הימים הראשונים. שהם חג\"ת, הנק' אבות, שהם עיקרו של הז\"א, הנה אז יצא הז\"א שהוא האומן, \u0003לאומנותיה\u0004, ונאצלו בנין, הנק' נצח הוד יסוד, דהיינו ג' הימים האחרונים דששת ימי בראשית. והוא \u0003בגין דיומא רביעאה איהו רגלא רביעאה דכרסייא עלאה\u0004 הז\"א נבחן לכסא אל הבינה, וכמו שאין הכסא נשלם מטרם שנגמרת בו הרגל הרביעית, כן הז\"א אינו נשלם מטרם שנתגלתה בו המלכות ביום הרביעי, ולא היה יכול להאציל את ג' הימים נה\"י זולת אחר השלמתה."],[3,"","עח) \u0003וכל עבידתייהו דכלהו\u0004 וכו': וכל מעשיהם של כולם, בין ג' ימים הראשונים, שהם חג\"ת, ובין של ג' ימים האחרונים, שהם נה\"י, היו תלוים ביום השבת, שהוא המלכות בבחינת הג\"ר וכל שלמותה. זהו שכתוב, ויכל אלקים ביום השביעי. זו היא שבת, וזו היא הרגל הרביעית של הכסא. כלומר ששבת ויום הרביעי שניהם בחי' מלכות, אלא יום הרביעי הוא מלכות הנכללת בז\"א בת\"ת שלו מחזה ולמעלה. ויום השבת ה\"ס מלכות בזווג ז\"א פנים בפנים."],[3,"","פירוש. \u0003וכל עבידתייהו דכלהו\u0004 וכו', כלומר אעפ\"י שג' הימים הראשונים נשלמו ביום הרביעי, מכל מקום לא נשלמו בו לגמרי, \u0003והוו תליין עד יום השבת\u0004, ונמצא כי ביום השבת נשלמו \u0003בין יומין קדמאין\u0004 שהם חג\"ת, \u0003ובין יומין בתראין\u0004 שהם נה\"י, וז\"ש, \u0003ויכל אלהים ביום השביעי את כל מלאכתו אשר עשה\u0004. דהיינו כל ששת הימים, לרבות ג' הימים הראשונים."],[3,"","וז\"ש, \u0003דא שבת ודא הוא רגלא רביעאה דכרסייא\u0004, כלומר, שיום השביעי הוא \u0003שבת\u0004, דהיינו שביעי לבנין, וכן הוא \u0003רגלא רביעאה דכרסייא\u0004, דהיינו שמשלים גם על האבות, והשבת הוא רביעי להם. והטעם שג' הימים חג\"ת לא נגמרו לכל תיקונם ביומא רביעאה, אלא שצריכים ליום השבת שישלים אותם, הוא, מפני שהיה ביום רביעי מיעוט במלכות, הנק' מיעוט הירח, שמשום זה חזרה לעיבור ב', ונתגלתה שלמותה ביום השבת. ונמצא שיום השבת השלים גם על ג' הימים הראשונים."],[4,"","עט) \u0003ואי תימא אי\u0004 וכו': ואם תאמר, אם כן, ששבת היא מלכות, מהו שכתוב, את שבתותי תשמורו, שהן שתים. ומשיב, אלא שבת של ליל שבת שהיא מלכות, ושבת של יום ממש, שהוא ז\"א, המאיר בשבת שהיא מלכות. אין להם פרוד, כי מיוחדים פב\"פ, והם נקראים שתי שבתות."],[4,"","פירוש, שאל כי לפי ההוה אמינא, שב' המלכיות, רביעי ושביעי, שלמות כל אחת בפני עצמה, מובן היטב הכתוב \u0003את שבתותי\u0004 שהם \u0003תרין\u0004, רביעי ושביעי. אבל אחר שתאמר שברביעי לא נשלם אלא רק אחר שנכלל בשביעי, א\"כ הם רק שבת אחת. ולמה אומר הכתוב \u0003את שבתותי, תרין\u0004. ומשיב, שהכוונה היא על בחינת ז\"א ונוקבא המאירים בקדושת השבת, כי יום השבת הוא הזכר ומעלי שבתא היא הנוקבא. והם ב' שבתות הנכללים \u0003בשבתותי\u0004, להיותם ממש \u0003חד בלא פרודא\u0004, וע\"כ נק' גם הז\"א בשם שבת. והבן."],[5,"","פ) \u0003אמר ההוא טייעא\u0004 וכו': אמר אותו מוליך החמורים שהיה מחמר אחריהם, ומהו ומקדשי תיראו, אמר לו, זו היא קדושת השבת. אמר לו, ומהי קדושת השבת. אמר לו זו היא קדושה הנמשכת מלמעלה, מאו\"א. אמר לו, אם כן עשית את השבת שהיא עצמה אינה קדש, אלא הקדושה שורה עליה מלמעלה, מאו\"א. אמר ר' אבא, וכך הוא, שכתוב, וקראת לשבת ענג לקדוש ה' מכובד, הרי שנזכר שבת לבד, וקדוש ה' לבד. אמר לו, א\"כ, מי הוא קדוש ה'. אמר לו, הוא הקדושה היורדת מלמעלה, מאו\"א, ושורה עליה, על השבת. אמר לו אם הקדושה הנמשכת מלמעלה נקראת מכובד, נראה, שהשבת עצמה אינה מכובדת, וכתוב, וכבדתו. הרי שהשבת עצמה היא מכובדת. אמר ר' אלעזר לרבי אבא, עזוב אותו האדם, כי יש בו דבר חכמה, שאנו אין יודעים אותה. אמרו לו, אמור אתה."],[5,"","פירוש. שאל אותו, \u0003ומהו ומקדשי תיראו\u0004, כיון שאתה אומר שסוד השבת הוא בחינת זו\"ן, א\"כ למה קורא אותם הכתוב בשם \u0003מקדשי\u0004, כי רק או\"א בלבדם נק' קדש."],[5,"","וז\"ש, \u0003אדכר שבת לחוד וקדוש ה' לחוד\u0004. הוכיח לו מכאן, כי השבת עצמה היא בחינת זו\"ן \u0003דלאו איהו קדש\u0004 מעצמה, אלא משום שנמשכת לה \u0003קדושא מלעילא\u0004. דהיינו מאו\"א עלאין הנק' \u0003קדש\u0004. ובחי' המשכה מאו\"א נק' \u0003קדוש ה'\u0004, שעליו נאמר \u0003ולקדוש ה' מכובד\u0004."],[6,"","פא) \u0003פתח ואמר את\u0004 וכו': פו\"א, את שבתותי. \u0003את\u0004 בא לרבות תחום שבת, שהוא שני אלפים אמה לכל צד, ומשום זה הוסיף הכתוב, את המלה, א\"ת. \u0003שבתותי\u0004, שהוא לשון רבים, זו היא שבת עליונה ושבת תחתונה, שהן שתים כלולות ביחד וסתומים ביחד."],[6,"","פירוש. \u0003את לאסגאה\u0004 וכו'. כי אעפ\"י דכתיב, אל יצא איש ממקומו ביום השביעי (שמות ט\"ז), הרבה הכתוב במלת \u0003את\u0004 ב' אלפים לכל רוח מחוץ למקומו. \u0003ואת\u0004 ה\"ס המלכות שמזווגה יוצאים המוחין של או\"א המאירים בשבת בתוספת על הארת הזו\"ן. כי או\"א ה\"ס ב' אלפים. וז\"ש \u0003בגין כך אסגי את\u0004 שע\"ז בא \u0003את\u0004 לרבות."],[6,"","וז\"ש, \u0003שבתותי, דא שבת עלאה ושבת תתאה\u0004, שבת עלאה הוא תבונה ושבת תתאה הוא מלכות, נוקבא דז\"א, שהם נק' (לעיל אות ח'). \u0003מ\"י ומ\"ה\u0004, או, \u0003עלמא עלאה ועלמא תתאה\u0004, ע\"ש. \u0003כלילן כחדא\u0004 כי בשבת עולים זו\"ן ומלבישים לאו\"א, נמצאות תבונה ומלכות \u0003כלילן\u0004 זו בזו \u0003כחדא\u0004, כי התחתון העולה לעליון נעשה כמוהו. \u0003סתימין כחדא\u0004 כי עכ\"ז אין המלכות נעשית תבונה ממש בלי הכר ביניהן, משום שאלו המוחין דתבונה אינם מקובלים למלכות רק למעלה במקום התבונה, אבל במקומה עצמה של המלכות למטה אין לה מוחין אלו, ובשיעור הזה נחשבת עוד המלכות לסתימא. ואומר שגם התבונה סובלת מהסתימא של המלכות, כי משום שמוחותיהן \u0003כלילן כחדא\u0004 הן ג\"כ \u0003סתימין כחדא\u0004, ונמצא שאף על פי שהתבונה לפי עצמה בהיותה עתה בשבת פרצוף אחד עם אמא עלאה, אין לה שום סתימא, מ\"מ כיון שמוחותיה מאירים בכללות אחת עם המוחין של המלכות, ע\"כ מורגשת הסתימא של המלכות גם במוחין דתבונה."],[7,"","פב) \u0003אשתאר שבת אחרא\u0004 וכו': נשארה שבת אחרת שלא נזכרה, והיתה בושה. אמרה לפניו: רבון העולם, מיום שעשית אותי אני נקראת, שבת. ואין יום בלא לילה. אמר לה: בתי, שבת את ושבת קראתיך, אבל, הנה אני מעטר אותך בעטרה עליונה ביותר. העביר כרוז ואמר, מקדשי תיראו. וזו היא שבת של ליל שבת, שהיא יראה, ושורה בה יראה. ומי היא. ומשיב היינו שהקב\"ה כלל ביחד ואמר, \u0003אני ה'\u0004. אשר \u0003אני\u0004, ה\"ס המלכות, שה\"ס ליל שבת. ה' ה\"ס ז\"א. ובמלות \u0003אני ה'\u0004, נכללו יחד. ואני שמעתי מאבי שאמר כך, ודייק, שהמלה \u0003את\u0004 הוא לרבות תחום שבת. \u0003שבתותי\u0004, שהוא לשון רבים, היינו העגול, והרבוע שבתוכו, שהם שנים, דהיינו ב' שבתות, וכנגד שנים אלו, יש שתי קדושות, שיש לנו להזכיר, אחת היא ויכולו, ואחת היא קידוש. \u0003ויכולו\u0004, יש בו שלשים וחמש מלים. \u0003ובקידוש\u0004 שאנו מקדשים יש בו שלשים וחמש מלים, ועולים הכל ביחד לשבעים שמות, שהקב\"ה וכנסת ישראל מתעטרים בהם."],[8,"","פג) \u0003ובגין דעגולא ורבועא\u0004 וכו': ומשום שהעגול והרבוע הזה הם \u0003שבתותי\u0004, שתיהן כלולות \u0003בשמור\u0004, שכתוב שבתותי \u0003תשמורו\u0004. אבל שבת העליון לא נכלל בשמור, אלא ב\u0003זכור\u0004, כי מלך העליון, שהוא בינה, הושלם בזכור. וע\"כ נקראת הבינה מלך שהשלום שלו, כי השלום שלו, הוא זכור. ועל כן אין מחלוקת למעלה."],[8,"","פירוש. \u0003אשתאר שבת אחרא\u0004 וכו': ה\"ס המלכות דמלכות, הנק' נקודה אמצעית, שאינה מקבלת מוחין גם ביום השבת, בהיותה סוד המנעולא עצמה, וכל המוחין באים רק בסוד המפתחא, שהיא היסוד דמלכות, (כנ\"ל אות מ\"ב), וכיון שלא קבלה מוחין הוית בכסופא."],[8,"","וז\"ש \u0003אשתאר שבת אחרא דלא אדכר\u0004 דהיינו הנקודה האמצעית שלא נזכרה, שלא קבלה מוחין \u0003והוה בכסופא\u0004 והיתה בבושה. \u0003אמרה קמיה\u0004 וכו', היא טענה, הרי \u0003מיומא דעבדית לי\u0004, דהיינו בתחילת אצילותי בעולם אדם קדמון, \u0003שבת אתקרינא\u0004, היו כל המוחין מושפעין על ידי, כי בא\"ק לא היתה מלכות אחרת רק נקודה אמצעית והיא לא נתמעטה רק בעת צמצום ב', לעולם האצילות."],[8,"","ועוד טענה \u0003ויומא לאו איהו בלא ליליא\u0004. וה\"ס נפלא מאד כי טענה, הרי אפילו ביום הראשון כתוב, ויהי ערב ויהי בקר יום אחד, שהיחוד מתגלה על יום ולילה יחד. וא\"כ למה לא נזכר לילה בשבת בראשית, כי ביום השביעי דמעשה בראשית לא כתוב לילה. \u0003אמר לה\u0004 וכו', הכוונה היא, שהקב\"ה אמר לה, \u0003שבת אנת\u0004 לעתיד באלף השביעי, ביום שכלו שבת \u0003ושבת קרינא לך\u0004, היינו מיומא דעבדית לך, בעולם א\"ק כנ\"ל."],[8,"אבל הא אנא מעטר","וכו', היינו שהקב\"ה העלה אותה, שתשמש בג\"ר של הפרצופין, (כמ\"ש לעיל אות מ\"א), כי היא נתקנה למלכות דאו\"א עלאין, בסוד אוירא דלא אתידע, ע\"ש. ואו\"א עי' נק' קדש קדשין, ונמצאת גם היא בסוד קדש עלאה."],[8,"","וז\"ש \u0003אעבר כרוזא ואמר מקדשי תיראו\u0004 כי בכח תיקונה באו\"א עלאין נעשית בסוד מקדש שה\"ס \u0003מקדשי תיראו\u0004. ונמצא עתה שהרויחה המלכות עטרא עלאה, יותר משהיתה לה בעולם א\"ק, כי שם היתה משמשת בסיום הספירות במקומה, ועתה עלתה לשמש במקום ג\"ר, באו\"א עלאין הנק' קדש קדשין, וז\"ש \u0003הא אנא מעטר לך בעטרא עלאה יתיר\u0004."],[8,"","וז\"ש, \u0003ודא שבת דמעלי שבתא, דאיהי יראה\u0004 וכו', המלכות נק' \u0003יראה\u0004, כי עליה היה הצמצום שלא תקבל למדתה, ואינה משמשת באו\"י מלמעלה למטה לבחינת עצמה אלא רק באו\"ח בלבד, בהיותה מתוקנת במסך ברתת וזיע שלא יעבור האור מהמסך ולמטה. (כנ\"ל אות נ\"ו ד\"ה וכלהו ע\"ש). ועתה בעליתה לקדש עלאה דאו\"א, \u0003שריא בה יראה\u0004 עלאה, כי הוי\"ה עלאה דאו\"א שורה בה, וה\"ס הלילה של יום השבת שנתקנה עתה כטענתה: \u0003ויומא לאו איהו בלא ליליא\u0004. וז\"ש \u0003ודא שבת דמעלי שבתא\u0004. ונכללה מדת לילה גם ביום השבת.. וז\"ש \u0003ומאן איהו\u0004, מאן איהו היראה דשריא בה, \u0003דקב\"ה אכליל ואמר אני ה'\u0004, כי הוי\"ה עלאה דאו\"א נכלל בה ואמר אני הוי\"ה. ובכדי לפרש זה. מביא המאמר ששמע מאביו."],[8,"","וביאור הדברים הוא כי תמונת העגול מורה, שהאור מאיר שם באפן שוה בכל מקום ואין שם בחינת דין כלל שיארע משום זה איזה שינוי במדת ההארה. ותמונת המרובע מורה, שיש שם בחינת דינים, שבסבתם יש להבחין בין ימין לשמאל, ובין מזרח למערב. וע\"כ נבחן הראש שהוא בצורת עיגול כלפי הגוף שהוא ברבוע. כי בג\"ר שהוא הראש אין דינין ובגוף יש דינין, שבסבתם יש בגוף ימין ושמאל פנים ואחור."],[8,"","וכבר ידעת סוד השבת, שהזו\"ן עולים ומלבישים לאו\"א, שהם בחי' \u0003שבת עלאה ושבת תתאה כלילן כחדא\u0004, כנ\"ל. ושבת עלאה שהוא בחינת או\"א, נבחן לבחינת \u0003עגולא\u0004. ושבת תתאה שהיא בחינת זו\"ן שהם בחינת גוף, נבחן לבחינת \u0003רבועא\u0004. וע\"כ בשבת, הזו\"ן שברבועא עולים ונכללים באו\"א שהם בחי' עגולא. וז\"ש \u0003שבתותי, דא עגולא ורבועא דלגאו ואינון תרין\u0004 דע\"כ אומר הכתוב \u0003שבתותי\u0004, לכלול ב' שבתות: שבת עליון שהוא \u0003עגולא, ורבועא\u0004 שבתוכו, שהוא שבת תחתון שעלה ונכלל בו."],[8,"","והנה המוחין דחכמה נק' \u0003ע' שמהן\u0004 או ע' עטרין, כי עין רומזת לחכמה. ומתוך שאין המוחין הללו מתגלים אלא ע\"י עלית השבת התחתון להעליון, נמצאים המוחין מתחלקים על שניהם: חציים לשבת העליון, וחציים לשבת התחתון. ולכן יש \u0003בויכלו ל\"ה תיבין\u0004 שהן חצי המוחין שבשבת העליון, ובקדוש עצמו יש ג\"כ ל\"ה תיבין הרומזות לחצי המוחין שבשבת התחתון. ואלו הם המוחין \u0003שכנסת ישראל\u0004 שהיא המלכות הנק' שבת, \u0003מתעטרא בהו\u0004."],[8,"","וזהו שאומר, \u0003ובגין דעגולא ורבועא דא\u0004, וכו', כלומר, כיון שהעגולא והרבועא כלילן יחד ב\u0003שבתותי\u0004, נמצאים גם המוחין דעגולא בבחי' \u0003שמור\u0004 כמו הרבועא. ואע\"פ ששמור מורה על בחינת דין וגבול, שצריכין להשמר ממנו. ובשבת עלאה, שה\"ס עגולא אין בו דין, כמ\"ש להלן, מ\"מ מתוך התכללותו כחדא בשבת דרבועא, נוהגת גם בעגולא בחינת \u0003שמור\u0004."],[8,"דהא שבת עלאה, הכא לא אתכליל בשמור",": כי שבת עלאה עצמו נכלל ב\u0003זכור\u0004 ולא ב\u0003שמור\u0004, כי מלכא עלאה בזכור אסתיים, ואין בו בחינת דין כלל שיהיה ראוי לומר עליו \u0003שמור\u0004, כי אין שמור נוהג רק בנוקבא. אמנם מבחינת מה ששבת עלאה נכלל בשבת התחתון נוהג \u0003שמור\u0004 בתרוייהו יחד, אבל לא בשבת העליון בפני עצמו."],[8,"ושלמא דיליה זכור איהו ועל דא לית מחלוקת לעילא",": כי מלכא עלאה ה\"ס הבינה דאסתיים בי', שה\"ס מאני דכורא, (כנ\"ל אות י\"ז ע\"ש), שזה מורה שאין שם בחינת \u0003מחלוקת\u0004 כלל, דהיינו בלי משהו דין, כי ע\"כ נק' בשם עגולא. (כנ\"ל ד\"ה ובגין). אבל שבת תחתון ה\"ס מ\"ה, דאסתיים ב\u0003ה'\u0004 וע\"כ אית בה מחלוקת, דהיינו ימין ושמאל, וע\"כ נק' רבועא."],[9,"","פד) \u0003בגין דתרין שלומות\u0004 וכו': כי שני שלומים יש למטה. אחד הוא יעקב. שהוא ת\"ת. ואחד הוא יוסף, שהוא יסוד. ומשום זה כתוב, שתי פעמים שלום: שלום שלום לרחוק ולקרוב. \u0003לרחוק\u0004 זהו יעקב. \u0003ולקרוב\u0004, זהו יוסף. \u0003לרחוק\u0004 הוא כמו שאתה אומר, \u0003מרחוק\u0004 ה' נראה לי. וכן ותתצב אחותו \u0003מרחוק. ולקרוב,\u0004 הוא כמו שאתה אומר, חדשים \u0003מקרוב\u0004 באו."],[9,"","פירוש. \u0003בגין דתרין שלומות לתתא\u0004 וכו', לתתא היינו בזו\"ן, שיש בו בחי' \u0003יעקב\u0004, שהוא ת\"ת, ויש בו בחינת \u0003יוסף\u0004 שהוא יסוד. וזה רומז על ב' בחי' זווג שיש בזו\"ן, כי \u0003שלום\u0004 ה\"ס זווג. כי יש בו זווג עליון להמשכת קומת חכמה, ויש בו זווג תחתון להמשכת חסדים, והעליון ה\"ס \u0003יעקב\u0004 והתחתון ה\"ס \u0003יוסף\u0004."],[9,"","ונתבאר לעיל (אות י\"ד ד\"ה קיימא), שאין ז\"ת יכולות לקבל קומת החכמה בלי חסדים, וע\"כ נבחנת קומת החכמה בזו\"ן שהיא רחוקה מהם, שהרי לא יוכלו לקבל אותה רק ע\"י התלבשות בחסדים וז\"ס \u0003מרחוק ה' נראה לי\u0004, כי קומת החכמה רחוקה ממנו והוא צריך ללבוש בכדי לקבלה."],[9,"","וע\"כ נקראת בחי' \u0003השלום\u0004 של יעקב, בבחינת \u0003רחוק\u0004, והזווג התחתון שהוא \u0003שלום\u0004 של \u0003יוסף\u0004, נק' \u0003קרוב\u0004, כי הוא מקובל לו בלי לבוש, ולא עוד, אלא שע\"י הקומה שלו דחסדים יוכל לקבל גם חכמה. (כנ\"ל אות י\"ד) וז\"ס הכתוב, \u0003שלום שלום לרחוק ולקרוב\u0004, שהם ב' שלומות: ד\u0003יעקב ויוסף\u0004, הנוהגים תמיד בזווג דגדלות של הזו\"ן. ואלו \u0003תרין שלומות\u0004, שהם בזו\"ן הנבחנים לסוד \u0003רבועא\u0004, הרי יש בהם מחלוקת, והם מסתיימים ב\u0003ה'\u0004 שה\"ס נוקבא. משא\"כ \u0003מלכא עלאה\u0004 שה\"ס בינה המסתיימים ב\u0003י'\u0004 שה\"ס דכורא, ואין בהם מחלוקת, ואפילו ענין \u0003רחוק וקרוב\u0004 אינו נוהג בבינה עצמה, בהיותה בחינת ג\"ר, וג\"ר יכולות לקבל חכמה \u0003בקרוב\u0004, כלומר, שאינן צריכות ללבוש החסדים כלל, והן מקבלות חכמה בלי חסדים. וזה שרומז לעיל, \u0003דמלכא עלאה\u0004 הוא מלך שהשלום שלו, ואין בו \u0003ב' שלומות\u0004 כמו בזו\"ן."]],[[0,"","פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (ויקרא יט) אֶת שַׁבְּתֹתַי תִּשְׁמֹרוּ. בֹּא רְאֵה, בְּשִׁשָּׁה יָמִים בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם. וְכָל יוֹם וָיוֹם גִּלָּה אֶת מַעֲשֵׂהוּ, וְנָתַן כֹּחוֹ בַּיּוֹם הַהוּא. מָתַי גִּלָּה אֶת מַעֲשֵׂהוּ וְנָתַן כֹּחוֹ בַּיּוֹם הָרְבִיעִי, מִשּׁוּם שֶׁאוֹתָם שְׁלֹשֶׁת הַיָּמִים הָרִאשׁוֹנִים, כֻּלָּם הָיוּ נִסְתָּרִים וְלֹא הִתְגַּלּוּ. כֵּיוָן שֶׁבָּא הַיּוֹם הָרְבִיעִי, הוֹצִיא אֶת הַמַּעֲשֶׂה וְהַכֹּחַ שֶׁל כֻּלָּם."],[1,"","שֶׁהֲרֵי אֵשׁ וּמַיִם וְרוּחַ, אַף עַל גַּב שֶׁהֵם שְׁלֹשָׁה יְסוֹדוֹת עֶלְיוֹנִים, כֻּלָּם תְּלוּיִים, וְלֹא הִתְגַּלָּה הַמַּעֲשֶׂה שֶׁלָּהֶם עַד שֶׁהָאָרֶץ גִּלְּתָה אוֹתָם, וְאָז נוֹדְעָה הָאָמָּנוּת שֶׁל כָּל אֶחָד מֵהֶם."],[2,"","וְאִם תֹּאמַר, הֲרֵי בַּיּוֹם הַשְּׁלִישִׁי זֶה הָיָה, שֶׁכָּתוּב תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא, וְכָתוּב וַתּוֹצֵא הָאָרֶץ! אֶלָּא זֶה, אַף עַל גַּב שֶׁכָּתוּב בַּיּוֹם הַשְּׁלִישִׁי, זֶה הָיָה רְבִיעִי, וְנִכְלָל בַּיּוֹם הַשְּׁלִישִׁי שֶׁיִּהְיוּ אֶחָד בְּלִי פֵרוּד. וְאַחַר כָּךְ הַיּוֹם הָרְבִיעִי הִתְגַּלָּה מַעֲשֵׂהוּ לְהוֹצִיא אָמָּן לְאָמָּנוּתוֹ שֶׁל כָּל אֶחָד וְאֶחָד. מִשּׁוּם שֶׁהַיּוֹם הָרְבִיעִי הוּא הָרֶגֶל הָרְבִיעִית שֶׁל הַכִּסֵּא הָעֶלְיוֹן."],[3,"","וְכָל מַעֲשֵׂיהֶם שֶׁל כֻּלָּם, בֵּין הַיָּמִים הָרִאשׁוֹנִים וּבֵין הַיָּמִים הָאַחֲרוֹנִים, הָיוּ תְלוּיִים בְּיוֹם הַשַּׁבָּת. זֶהוּ שֶׁכָּתוּב (בראשית ב) וַיְכַל אֱלֹהִים בַּיּוֹם הַשְּׁבִיעִי. זוֹ הַשַּׁבָּת, וְזוֹ הִיא הָרֶגֶל הָרְבִיעִית שֶׁל הַכִּסֵּא."],[4,"","וְאִם תֹּאמַר, אִם כָּךְ, מַה זֶּה אֶת שַׁבְּתֹתַי תִּשְׁמֹרוּ, פַּעֲמַיִם אֶלָּא שַׁבָּת שֶׁל עֶרֶב שַׁבָּת וְהַשַּׁבָּת שֶׁל הַיּוֹם מַמָּשׁ אֵין לָהֶם פֵּרוּד."],[5,"","אָמַר (להם) אוֹתוֹ סוֹחֵר שֶׁהָיָה מְחַמֵּר אַחֲרֵיהֶם, וּמַה זֶּה וּמִקְדָּשִׁי תִּירָאוּ אָמַר לוֹ, זֶה קִדּוּשׁ שֶׁל שַׁבָּת. אָמַר לוֹ, וּמַה זֶּה קִדּוּשׁ שֶׁל שַׁבָּת אָמַר לוֹ, זֶה הַקִּדּוּשׁ שֶׁנִּמְשָׁךְ מִלְמַעְלָה. אָמַר לוֹ, אִם כָּךְ, עָשִׂיתָ שֶׁהַשַּׁבָּת אֵינָהּ קֹדֶשׁ, אֶלָּא קִדּוּשׁ שֶׁשּׁוֹרֶה עָלָיו מִלְמַעְלָה. אָמַר רַבִּי אַבָּא, וְכָךְ זֶה, (ישעיה נח) וְקָרָאתָ לַשַּׁבָּת עֹנֶג לִקְדוֹשׁ ה' מְכֻבָּד. הִזְכִּיר שַׁבָּת לְחוּד וּקְדוֹשׁ ה' לְחוּד. אָמַר לוֹ, אִם כָּךְ, מִי זֶה קְדוֹשׁ ה' אָמַר לוֹ, הַקְּדֻשָּׁה שֶׁיּוֹרֶדֶת מִלְמַעְלָה וְשׁוֹרָה עָלָיו. אָמַר לוֹ, אִם הַקְּדֻשָּׁה שֶׁנִּמְשֶׁכֶת מִלְמַעְלָה נִקְרֵאת מְכֻבָּד, נִרְאֶה שֶׁשַּׁבָּת אֵינוֹ מְכֻבָּד, וְכָתוּב וְכִבַּדְתּוֹ. אָמַר רַבִּי אֶלְעָזָר לְרַבִּי אַבָּא, הַנַּח לוֹ לָאִישׁ הַזֶּה, שֶׁדָּבָר שֶׁל חָכְמָה יֵשׁ בּוֹ שֶׁאֵינֶנּוּ יוֹדְעִים בּוֹ. אָמְרוּ לוֹ, אֱמֹר אַתָּה."],[6,"","פָּתַח וְאָמַר, (ויקרא יט) אֶת שַׁבְּתֹתַי, אֶת - לְרַבּוֹת תְּחוּם שַׁבָּת שֶׁהוּא אַלְפַּיִם אַמּוֹת לְכָל צַד, וּמִשּׁוּם כָּךְ רִבָּה אֶת. שַׁבְּתֹתַי - (נ\"א זו) שַׁבָּת הָעֶלְיוֹנָה וְשַׁבָּת הַתַּחְתּוֹנָה, שֶׁהֵן שְׁתַּיִם כְּלוּלוֹת יַחַד וְנִסְתָּרוֹת יַחַד."],[7,"","נִשְׁאֲרָה שַׁבָּת אַחֶרֶת שֶׁלֹּא נִזְכְּרָה וְהָיְתָה בְּבוּשָׁה. אָמְרָה לְפָנָיו: רִבּוֹן הָעוֹלָם, מִיּוֹם שֶׁעָשִׂיתָ אוֹתִי נִקְרֵאתִי שַׁבָּת, וְהַיּוֹם אֵינוֹ בְּלִי לַיְלָה. אָמַר לָהּ, בִּתִּי, אַתְּ שַׁבָּת, וְשַׁבָּת קָרָאתִי לָךְ, אֲבָל הֲרֵינִי מְעַטֵּר אוֹתָךְ בַּעֲטָרָה יוֹתֵר עֶלְיוֹנָה. הֶעֱבִיר כְּרוּז וְאָמַר מִקְדָּשִׁי תִּירָאוּ. וְזוֹ שַׁבָּת שֶׁל עֶרֶב שַׁבָּת שֶׁהִיא יִרְאָה, וְשׁוֹרָה בָּהּ יִרְאָה. וּמִי הוּא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִכְלִיל וְאָמַר אֲנִי ה' וַאֲנִי שָׁמַעְתִּי מֵאַבָּא שֶׁאָמַר כָּךְ, וְדִיֵּק אֶת - לְרַבּוֹת תְּחוּם שַׁבָּת. שַׁבְּתֹתַי - זֶה הָעִגּוּל וְהָרִבּוּעַ שֶׁבִּפְנִים, וְהֵם שְׁנַיִם. וּכְנֶגֶד אוֹתָם הַשְּׁנַיִם יֵשׁ שְׁתֵּי קְדֻשּׁוֹת שֶׁיֵּשׁ לָנוּ לְהַזְכִּיר, אֶחָד וַיְכֻלּוּ, וְאֶחָד קָדוֹשׁ. וַיְכֻלּוּ יֵשׁ בּוֹ שְׁלֹשִׁים וְחָמֵשׁ תֵּבוֹת, וּבַקִּדּוּשׁ שֶׁאָנוּ מְקַדְּשִׁים יֵשׁ שְׁלֹשִׁים וְחָמֵשׁ תֵּבוֹת, וְהַכֹּל עוֹלֶה לְשִׁבְעִים שֵׁמוֹת שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא וּכְנֶסֶת יִשְׂרָאֵל מִתְעַטְּרִים בָּהֶם."],[8,"","וּמִשּׁוּם שֶׁהָעִגּוּל וְהָרִבּוּעַ הַזֶּה הֵם שַׁבְּתֹתַי, שְׁנֵיהֶם כְּלוּלִים בְּשָׁמוֹר, שֶׁכָּתוּב תִּשְׁמֹרוּ. שֶׁהֲרֵי הַשַּׁבָּת הָעֶלְיוֹנָה כָּאן לֹא נִכְלְלָה בְּשָׁמוֹר, אֶלָּא בְּזָכוֹר, שֶׁהֲרֵי הַמֶּלֶךְ הָעֶלְיוֹן מִסְתַּיֵּם בְּזָכוֹר, וְעַל זֶה נִקְרָא מֶלֶךְ שֶׁהַשָּׁלוֹם שֶׁלּוֹ. וְהַשָּׁלוֹם שֶׁלּוֹ הוּא זָכוֹר, וְעַל כֵּן אֵין מַחֲלֹקֶת לְמַעְלָה."],[9,"","מִשּׁוּם שֶׁשְּׁנֵי שְׁלוֹמוֹת לְמַטָּה - אֶחָד יַעֲקֹ\"ב, וְאֶחָד יוֹסֵ\"ף. וּמִשּׁוּם כָּךְ כָּתוּב פַּעֲמַיִם (ישעיה נז) שָׁלוֹם שָׁלוֹם לָרָחוֹק וְלַקָּרוֹב. לָרָחוֹק - זֶה יַעֲקֹב. וְלַקָּרוֹב - זֶה יוֹסֵף. לָרָחוֹק, כְּמוֹ שֶׁנֶּאֱמַר (ירמיה לא) מֵרָחוֹק ה' נִרְאָה לִי, (שמות ב) וַתֵּתַצַּב אֲחֹתוֹ מֵרָחוֹק. וְלַקָּרוֹב, כְּמוֹ שֶׁנֶּאֱמַר (דברים לב) חֲדָשִׁים מִקָּרוֹב בָּאוּ. מֵרָחוֹק - זוֹ הַנְּקֻדָּה הָעֶלְיוֹנָה שֶׁעוֹמֶדֶת בְּהֵיכָלוֹ."]]],[["וְעַל דָּא כְּתִיב תִּשְׁמוֹרוּ אִתְכְּלִיל בְּשָׁמוֹר. (ואתחנן ר\"ס) וּמִקְדָּשִׁי תִּירָאוּ דָּא נְקוּדָה דְקַיְימָא בְּאֶמְצָעִיתָא דְּאִית לְדַחֲלָא מִנָּהּ יַתִּיר מִכֹּלָּא דְּעָנְשֵׁיהּ מִיתָה. וְהַיְינוּ דִכְתִיב, (שמות ל״א:י״ד) מְחַלֲּלֶיהָ מוֹת יוּמָת. מָאן מְחַלֲּלֶיהָ. מָאן דְּעָאל לְגוֹ חָלָל דְּעִגּוּלָא וְרִבּוּעָא לְאֲתַר דְּהַהוּא דִנְקוּדָה (נקודה) שַׁרְיָא (ביה) וּפָגִים בֵּיהּ מוֹת יוּמָת. וְעַל דָּא כְּתִיב תִּירָאוּ. וְהַהִיא נְקוּדָה אִקְרֵי אֲנִי, וְעֲלָהּ שַׁרְיָא הַהוּא דְּסָתִים עִלָּאָה דְּלָא אִתְגַּלְּיָא וְהַיְינוּ יְיָ וְכֹלָּא חַד. נָחֲתוּ רִבִּי אֶלְעָזָר וְרִבִּי אַבָּא וּנְשָׁקוּהוּ. אָמְרוּ וּמַה כָּל חָכְמְתָא דָא אִית תְּחוֹת יְדָךְ וְאַתְּ טָעִין אַבַּתְרִין. אָמְרוּ לֵיהּ מָאן אַנְתְּ. אָמַר לוֹן לָא תִשְׁאֲלוּן מָאן אֲנָא, אֶלָּא אֲנָא וְאַתּוּן נֵיזֵל וְנִתְעַסֵּק בְּאוֹרַיְיתָא וְכָל חַד יִיִמָא מִלִּין דְּחָכְמְתָא לְאַנְהָרָא אוֹרְחָא.","אָמְרוּ לֵיהּ מָאן יָהַב לָךְ לְמֵיזַל הָכָא וּלְמֶהֱוֵי (ולמהוי) טָעוּן (טעין) בְּחַמְרֵי, אָמַר לוֹן יוּ\"ד עֲבַד קְרָבָא בִּתְרֵין אַתְוָון בְּכָ\"ף וְסַמַ\"ךְ לְאִתְקַשְׁרָא בַּהַדָּאי (נ\"א כחדא). כָּ\"ף לָא בָּעָא לְאִסְתַּלָּקָא וּלְאִתְקַשָּׁרָא בָּתַר (נ\"א באתר) דְּלָא יָכְלָא לְמֶהֱוֵי רִגְעָא חָדָא אֶלָּא בֵּיהּ. סָמֶ\"ךְ לָא בָעָא לְאִסְתַּלָּקָא בְּגִין לְסַעֲדָא לְאִנּוּן דְּנָפְלִין דְּהָא בְּלִי סָמֶ\"ךְ לָא יָכְלִין לְמֶהֱוֵי.","יוּ\"ד אֲתָא לְגַבָּאי יְחִידָאָה נָשִׁיק לִי וְגַפִּיף לִי בָּכָה עִמִּי וְאָמַר לִי בְּרִי מָה אַעֲבִיד לָךְ, אֲבָל הָא אֲנָא אִסְתַּלַּק וְאֲנָא אִתְמְלֵי מִכַּמָּה טָבִין וְאַתְוָון טְמִירִין עִלָּאִין יַקִּירִין, בָּתַר כֵּן אַיְתֵי לְגַבָּךְ וְאֲנָא אֶהֱוֵי סְעִיד לָךְ וְאֶתֶּן לָךְ אַחְסַנְתָּא דִּתְרֵין אַתְוָון עִלָּאִין יַתִּיר מֵאִלֵּין דְּאִסְתַּלָּקוּ דְּאִנּוּן י\"ש יוּ\"ד עִלָּאָה וְשִׁי\"ן עִלָּאָה לְמֶהוֵי לָךְ אוֹצְרִין מַלְיָיא מִכֹּל. וּבְגִין כָּךְ בְּרִי זִיל וְהֱוֵי טְעִין חַמְרֵי. וְעַל דָּא אֲנָא אָזִיל בְּכָךְ.","חָדוּ רִבִּי אֶלְעָזָר וְרִבִּי אַבָּא וּבָכוּ וְאָמְרוּ זִיל רְכִיב וְאֲנַן נַטְעִין אַבַּתְרָךְ. אָמַר לוֹן וְלָא אֲמָרִית לְכוֹן דְּפִּיקוּדָא דְּמַלְכָּא אִיהוּ עַד דְּיֵיתֵי הַהוּא דְטָעַן (דטעין) חַמְרֵי. אָמְרוּ לֵיהּ הָא שְׁמָךְ לָא אָמַרְתְּ לָן, אֲתַר בֵּית מוֹתָבָךְ מַאי הוּא. אָמַר לוֹן אֲתַר בֵּית מוֹתְבִי אִיהוּ טַב וְעַיְילָא לְגַבָּאי, וְאִיהוּ (ריש תיקון כ\"א דף נ\"ב ע\"א ובראשית ל\"ו ע\"ב) מִגְדָּל חַד דְּפָרַח בַּאֲוִירָא רַב וְיַקִּירָא. וְאִנּוּן דְּדַיְירִין בֵּיהּ בְּהַאי מִגְדְּלָא, קוּדְשָׁא בְּרִיךְ הוּא וְחַד מִסְכְּנָא. וְדָא הוּא אֲתַר בֵּית מוֹתְבִי וְגָלֵינָא (נ\"א ועלינא) מִתַּמָּן וְאֲנָא טָעִין חַמְרֵי. אַשְׁגָּחוּ רִבִּי אַבָּא וְרִבִּי אֶלְעָזָר בֵּיהּ וְאַטְעִים לוֹן מִלּוֹי דְּהֲווּ מְתִיקִין כְּמַנָּא וְדוּבְשָׁא. אָמְרוּ לֵיהּ שְׁמָא דְּאֲבוּךְ אִי תֵימָא נַנְשִׁיק עַפְרָא דְרַגְלָךְ. אָמַר לוֹן וְאַמַּאי, לָאו אוֹרַח דִּילִי בְּכָךְ לְאִתְגָאָה בְּאוֹרַיְיתָא.","אֲבָל אַבָּא דִילִי הֲוָה דִיּוּרֵיהּ בְּיַמָּא רַבָּא וְאִיהוּ הֲוָה חַד נוּנָא דְּהֲוָה (תקונים נ\"ב, ובראשית לו ע\"ב) אַסְחַר יַמָּא רַבָּא מִסִּטְרָא דָא לְסִטְרָא דָא, וְהֲוָה רַב וְיַקִּירָא וְעַתִּיק יוֹמִין, עַד דְּהֲוָה בָּלַע כָּל שְׁאָר נוּנִין דְּיַמָּא, וּלְבָתַר אַפִּיק לוֹן חָיִין וְקַיָּמִין מַלְיָין מִכָּל טָבִין דְּעָלְמָא. וְשָׁאַט יַמָּא בְּרִגְעָא חָדָא בְּתוֹקְפֵּיהּ, וְאַפִּיק לִי כְּגִירָא בִּידָא דִגְבַר תָּקִיף, וְטָמִיר לִי בְּהַהוּא אֲתַר דְּאֲמָרִית לְכוּ. וְהוּא תָּב לְאַתְרֵיהּ וְאִגְנִיז בְּהַהוּא יַמָּא.","אַשְׁגַּח רִבִּי אֶלְעָזָר בְּמִלּוֹי. אָמַר לֵיהּ אַנְתְּ הוּא בְּרֵיהּ דְּבוּצִינָא קַדִּישָׁא, אַנְתְּ הוּא בְּרֵיהּ דְּרַב הַמְנוּנָא סָבָא, אַנְתְּ הוּא בְּרֵיהּ דִּנְהִירוּ דְּאוֹרַיְיתָא וְאַנְתְּ טָעִין אַבַּתְרָן. בָּכוּ כְּחֲדָא וּנְשָׁקוּהוּ וְאֲזְלוּ. אָמְרוּ לֵיהּ אִי נִיחָא קַמֵּי מָארָנָא לְאוֹדְעָא לָן שְׁמֵיהּ.","פָּתַח וְאָמַר (שמואל ב כ״ג:כ׳) וּבְנָיָהוּ בֶּן יְהוֹיָדָע. הַאי קְרָא אוֹקְמוּהַ וְשַׁפִּיר אִיהוּ. אֲבָל הַאי קְרָא לְאַחֲזָאָה רָזִין עִלָּאִין דְּאוֹרַיְיתָא הוּא דְּאֲתָא. וּבְנָיָהוּ בֶּן יְהוֹיָדָע, עַל רָזָא דְּחָכְמְתָא קָא אֲתָא מִלָּה סְתִימָא אִיהוּ, וּשְׁמָא גָרִים. בֶּן אִישׁ חַי (ויצא קס\"ד א') דָּא צַדִּיק חַי עָלְמִין. רַב פְּעָלִים, מָארֵי דְּכָל עוֹבָדִין וְכָל חֵילִין עִלָּאִין, בְּגִין דְּכֻלְּהוּ נָפְקִין מִנֵּיהּ. יְיָ צְבָאוֹת אִיהוּ, אוֹת הוּא בְּכָל חַיָילִין דִּידֵיהּ רְשִׁים הוּא וְרַב מִכֹּלָא.","רַב פְּעָלִים אִיהוּ מְקַבְצִאֵל הַאי אִילָנָא רַב וְיַקִּירָא, רַב מִכֹּלָּא. מֵאָן אֲתַר נָפַק, מֵאָן דַּרְגָא אֲתָא, אַהֲדַר קְרָא וְאָמַר מְקַבְצִיאֵל דַּרְגָּא עִלָּאָה סְתִימָאָה דְּעַיִן לא רָאֲתָה וְגו' דַּרְגָּא דְּכוֹלָא בֵּיהּ, וּכְנֵישׁ בְּגַוֵּיהּ מִגּוֹ נְהוֹרָא עִלָּאָה, וּמִנֵּיהּ נָפִיק כֹּלָּא."],[[0,"","פה) \u0003מרחוק דא נקודה\u0004 וכו': מרחוק, זו היא הנקודה העליונה העומדת בהיכלו. ועל זו כתוב, \u0003תשמורו\u0004, שנכללת בשמור. \u0003ומקדשי תיראו\u0004, זו היא הנקודה העומדת באמצע, שיש לפחד מפניה יותר מכל, כי עונשה מיתה. והיינו שכתוב, מחלליה מות יומת. מי הם מחלליה, הוא, מי שנכנס לתוך החלל של העגול והרבוע, למקום שאותה הנקודה שורה, ופוגם אותה, מות יומת. ועל זה כתוב, \u0003תיראו\u0004. והנקודה ההיא נקראת, \u0003אני\u0004. ועליה שורה אותו הסתום העליון שלא נגלה, והיינו \u0003הויה\u0004. ואני והויה, הכל אחד. ירדו ר' אלעזר ור' אבא מחמוריהם, ונשקוהו. אמרו: ומה כל החכמה הזו שישנה תחת ידך, ואתה מחמר אחרינו. אמרו לו, מי אתה. אמר להם, אל תשאלו מי אני, אלא אני ואתם נלך ונעסוק בתורה. וכל אחד יאמר דברי חכמה, להאיר את הדרך."],[0,"","פירוש. \u0003מרחוק דא נקודה\u0004 וכו', ה\"ס \u0003המפתחא\u0004 שממנו מושפעת החכמה דל\"ב נתיבות. (כנ\"ל מ\"ב. ע\"ש. ) וה\"ס ה\u0003ב\u0004, ד\u0003ב\u0004ראשית המכונה \u0003נקודה בהיכליה\u0004, שמשם קומת החכמה לזו\"ן בעת שהזו\"ן עולים ומלבישים לאו\"א עלאין, כי אז נכללים ב' השבתות שבת עליון, ושבת תחתון ביחד, ועליהם נאמר \u0003מרחוק ה' נראה לי\u0004, כי אין הזו\"ן יכולים לקבלה זולת בלבוש החסדים (כנ\"ל בדבור הסמוך)."],[0,"","וז\"ש \u0003מרחוק, דא נקודה עלאה דקיימא בהיכליה\u0004 שאלו החו\"ב הנק' \u0003נקודה בהיכליה\u0004, מכונים שהם מרחוק אל הזו\"ן, וצריך ללבוש החסדים מעלמא תתאה שה\"ס \u0003מ\"ה\u0004 המסתיימים בנוקבא, (כנ\"ל אות ט\"ז ד\"ה בגין) \u0003ועל דא כתיב תשמורו אתכליל בשמור\u0004 כיון שנצרך לזווג התחתון דמ\"ה דאסתיים בנוקבא הנק' \u0003שמור\u0004, הרי גם קומת החכמה נכללה \u0003בשמור\u0004, ולפיכך כתוב עליהם \u0003את שבתותי תשמורו\u0004, וגם השבת העליון הנכלל בזו\"ן, נכלל במדת השמור, ולא בזכור כי הם בהכרח בנוקבא מסתיימים, כדי לקבל קומת החסדים, כמבואר, ורק \u0003מלכא עלאה\u0004, שהוא חו\"ב בפני עצמם, המקבלים חכמה מקרוב, דהיינו בלי לבוש החסדים, הם נבחנים ש\u0003בזכור\u0004 מסתיימים, ונק' \u0003זכור\u0004 ולא \u0003שמור\u0004."],[0,"ומקדשי תיראו, דא נקודה דקיימא באמצעיתא",": הוא בחינת עצם \u0003המנעולא\u0004 שנתקנה באו\"א עלאין בסוד אוירא דלא אתידע, שה\"ס הנקודה האמצעית. המשמשת רק בא\"ק, ולא בעולם האצילות וע\"כ לית השגה תפיסא באו\"א עלאין שהם ג\"ר דבינה, וכל החכמה המושפעת בעולם האצילות היא רק מז\"ת דבינה הנקראות ישסו\"ת, ששם משמש \u0003המפתחא\u0004 הנק' \u0003נקודה בהיכליה\u0004 (כנ\"ל בדיבור הסמוך). ומתוך שנתקנה באו\"א עלאין היא נקראת ומקדשי, (כנ\"ל אות מ\"א ד\"ה וטעם), וע\"כ שריא בה יראה ע\"ש. וז\"ש \u0003ומקדשי תיראו דא נקודה דקיימא באמצעיתא\u0004."],[0,"","וז\"ש, \u0003מאן מחלליה\u0004, וכו': כבר ידעת, ש\u0003עגולא\u0004 הוא או\"א, ו\u0003רבועא\u0004 הוא זו\"ן המלבישים לאו\"א ונכללים \u0003גו עגולא\u0004, והמלכות דאו\"א ה\"ס הנקודה שבתוכם, ויש במלכות הזו ב' בחינות. שהן \u0003מנעולא ומפתחא\u0004, שהמפתחא נק' \u0003נקודה בהיכליה\u0004, והיא רק בחינת יסוד שבמלכות, והיא משמשת רק בישסו\"ת. והמנעולא היא מלכות שבמלכות, שהיא \u0003נקודה אמצעית\u0004 ממש, והיא משמשת רק באו\"א עלאין, (כנ\"ל בדיבור הסמוך). וז\"ש \u0003מאן דעאל לגו חלל דעגולא ורבועא\u0004 כלומר, לבחינת מלכות דאו\"א שהיא \u0003חלל\u0004, דאוירא דילה לא אתידע, \u0003לאתר דההוא נקודה שריא\u0004, כלומר, למקום הנקודה \u0003דאמצעיתא, ופגים ביה\u0004. דהיינו שרוצה להמשיך אור לתוך \u0003החלל\u0004 שלה \u0003מות יומת\u0004 כי אסור להמשיך בה שום אור. \u0003ועל דא כתיב תיראו\u0004 דהיינו \u0003ומקדשי תיראו\u0004 דכתיב, דקאי על \u0003נקודה דאמצעיתא\u0004."],[0,"","וז\"ש, \u0003וההיא נקודה\u0004 וכו', הנקודה בעצם נק' \u0003אני\u0004, ואו\"א הם \u0003הוי\"ה דשריא עלה\u0004 דהאי \u0003נקודה\u0004, כי ע\"כ הם \u0003סתים עלאה דלא אתגליא\u0004, דלית מחשבה תפיסא בהם כלל, וזה \u0003אני הוי\"ה. וכלא חד\u0004 שהם נחשבים לאחד, כי ע\"כ נק' גם הנקודה בשם או\"א, דהיינו \u0003ומקדשי תיראו\u0004, שעצם הנקודה נבחנת לקדש, כמו או\"א, כי הם אחד."],[0,"","וז\"ש, \u0003נחתו רבי אלעזר ורבי אבא ונשקוהו\u0004: בכדי להמשיך ביאור המאמר שלפנינו, מוכרח אני לגלות יותר הענין הזה של ההוא דטעין חמרי. ותדע שהאי \u0003אורחא דאזלי ר' אלעזר ור' אבא\u0004, אינו כפשוטו, אלא ה\"ס אורח צדיקים כאור נגה הולך ואור עד נכון היום (משלי ד'). ואומרו, שהלך לראות את \u0003ר\"י בר\"ש בן לקוניא חמוי\u0004, יש בזה רמז לשיעור המדרגה שהיו עומדים בה אז. כי הז\"א יש לו או\"א של עצמו, שהם או\"א עלאין. גם יש לו או\"א של אשתו, שהם ישסו\"ת. ותחילה משיג הז\"א לאו\"א של הנוקבא שלו שהם ישסו\"ת, דהיינו הנק' מוחין דנשמה. ואח\"כ עולה למדרגה יותר גבוהה ומשיג לאו\"א של עצמו, שהם או\"א עלאין הנק' מוחין דחיה. והנה הצדיקים ההולכים במדרגות הם מרכבה לז\"א. וכיון שההוא \u0003אורחא דאזלי ביה ר' אלעזר ור' אבא\u0004 היה במוחין דנשמה, ע\"כ בא הרמז, שר\"א הלך לראות \u0003לחמוי\u0004, דהיינו לאו\"א של הנוקבא שלו שהיא מוחין דנשמה."],[0,"","והענין ההוא \u0003דטעין חמרי אבתרייהו\u0004 ה\"ס הסיוע לנשמות הצדיקים, הנשלח להן ממרומים בכדי להעלותן ממדרגה למדרגה. כי לולא הסיוע הזה שהקב\"ה שולח לצדיקים, לא היו יכולים לצאת ממדרגתם ולהתעלות יותר למעלה. ולכן שולח הקב\"ה לכל צדיק וצדיק נשמה גבוהה ממרומים, לכל אחד לפי מעלתו ומדרגתו, המסייעת לו בדרכו. והנה בתחילה אין הצדיק מכיר את הנשמה ההיא כלל, ונדמה לו שהיא נשמה נמוכה ביותר שנתלותה עמו בדרכו, והוא נק' עיבור נשמת הצדיק, כלומר, שהנשמה של מעלה עוד לא גמרה הסיוע שלה, וע\"כ אינה ניכרת כלל מי היא. אלא אחר שגמרה כל הסיוע שלה. והביאה את הצדיק למדרגה הרצויה, הנה אז ניכרת אצלו, ורואה את רוממותה, וזה נקרא גילוי נשמת צדיקים."],[0,"","והנה נשמה זו שבאה לסייע לר\"א ור\"א, היתה נשמת \u0003ר' המנונא סבא\u0004, שהיא נשמה מאד נעלה ואין קץ לרוממותה. והיא בחינת אור יחידה. אמנם בתחילה באה אליהם בדרך עיבור ולא הכירו בה יותר רק במדתו של \u0003טעין חמרי\u0004, שפירושו הפשוט הוא, בעל חמורים. שאומנותו היא להעביר נוסעים על חמוריו ממקום למקום, והוא עצמו הולך ברגל לפני חמוריו ומוליכם. וע\"כ נק' \u0003טעין חמרי\u0004, שמוליך חמורים. ובלשון חז\"ל נק' חמרין, שרובן רשעים, והיא הצורה הנמוכה ביותר."],[0,"","וז\"ש רבי אבא \u0003נפתח פתחין דאורייתא, דהא שעתא ועדנא הוא לאתקנא בארחן\u0004, דהיינו לפתוח את צנורות הנשמה ע\"י פתיחת שערי סודות התורה. בכדי שיתקנו בדרך ה' שהולכים בו. וביאר רבי אלעזר הפסוק של \u0003שבתותי תשמורו\u0004. מבחינת המדרגה שהיה עומד בה. דהיינו ממוחין דישסו\"ת, שה\"ס \u0003למחמי לחמוי\u0004, כנ\"ל. וע\"כ ביאר, ששבת עצמה היא בחינת זו\"ן שאינם עוד בבחינת קדש, אלא שהם ממשיכים מקדש, דהיינו מוחין דישסו\"ת, שהזו\"ן ממשיכים ביום השבת. ועל המוחין האלו דרשו את הכתוב \u0003ומקדשי תיראו\u0004. כי החכמה הבאה מבחינת מוחין תתאין דישסו\"ת לזו\"ן, עוד נוהגת בהם יראה. (כנ\"ל במאמר מי ברא אלה אות ז' ד\"ה וזה אמרו), כי הם עוד עומדים לשאלה, וע\"כ יש בקודש ההוא בחינת \u0003יראה\u0004."],[0,"","וכאן סייע אותם ההוא \u0003דטעין חמרי אבתרייהו\u0004, וגילה בהן סוד מוחין דחיה. כי \u0003את שבתותי תשמורו\u0004 ביאר על שבת עליונה ושבת תחתונה הבאים ביחד ע\"י עלית זו\"ן למקום או\"א ונעשים הזו\"ן עצמם קודש בסוד \u0003רבועא בגו עגולא\u0004. ועליהם לא נאמר \u0003יראה\u0004, כי אם \u0003תשמורו\u0004 לבד. כי המוחין דחיה דוחין כל החיצונים, וכל דינין מתעברין מינה ביום השבת, ומבחינה זו אין שם \u0003יראה\u0004, והכתוב \u0003ומקדשי תיראו\u0004, ביאר להם על \u0003נקודה דאמצעיתא\u0004 המשמשת בג\"ר דאו\"א, דהיינו ג\"ר של מוחין דחיה, שבה לית השגה תפיסא כלל, ובה אית \u0003יראה\u0004."],[0,"","ובזה גמרה הנשמה את תפקידה כי הביאה אותם להשגת מוחין דחיה, ואז זכו לגילוי נשמת הצדיק, כי עתה הכירו את ערכה של אותה הנשמה. וע\"כ \u0003נחתו רבי אלעזר ורבי אבא ונשקוהו\u0004 כי השגת המעלה מתבארת בפעולת נשיקה. אמנם באמת עוד לא נגמר תפקידה של הנשמה ההיא, כי עוד היה לה לסייע אותם בהשגת אור היחידה, כמ\"ש לפנינו, אלא כיון שהשגת חיה בלבדה היא מדרגה שלמה בפני עצמה, לפיכך נבחן שהנשמה נתגלתה להם בשיעור זה. וז\"ס שחשבו אותו עתה שהוא \u0003בריה דרב המנונא סבא\u0004 ולא \u0003רב המנונא סבא\u0004 עצמו. והוא כי רב המנונא סבא הוא בחינת יחידה ובנו הוא בחינת חיה. וע\"כ לפי שלא השיגו עתה רק בחי' חיה, ע\"כ עוד טעו בו וחשבו שהוא בנו של רב המנונא. אמנם להלן אחר שהודיע להם סוד הכתוב של בניהו בן יהוידע, שהוא גילוי מדרגת יחידה, אז נגלה אליהם בשלמותו, וראו כי הוא \u0003רב המנונא סבא\u0004 עצמו."],[0,"","וז\"ש, \u0003אמר לון לא תשאלון מאן אנא\u0004:כי הרגישו בעצמם שעדיין אינם מכירים אותו לגמרי, (כנ\"ל בדיבור הסמוך), כי עוד לא נגמר תפקיד סיועה של הנשמה. וע\"כ הפצירו בו שיגלה את שמו. אמנם השיב להם, שלא ישאלו לשמו, כי עוד צריכים לגילוים של רזין דאורייתא, כלומר, שהאורח עוד לא מתוקן לגמרי, וז\"ש להם \u0003אלא אנא ואתון ניזל ונתעסק באורייתא\u0004, כי אתם עוד צריכים לי לסייע אתכם בעסק התורה \u0003וכל חד יימא מלין דחכמתא לאנהרא אורחא\u0004, כי צריכים עוד להאיר את הדרך, כי עדיין לא באנו למחוז חפצנו."],[1,"","פו) \u0003אמרו ליה מאן\u0004 וכו': אמרו לו, מי נתנך ללכת כאן, להיות מוליך חמורים. אמר להם, הי' עשתה מלחמה בשתי אותיות ב\u0003כ'\u0004 וב\u0003ס'\u0004, כדי שיבואו להתקשר עמי. ה\u0003כ'\u0004 לא רצתה להסתלק ממקומה ולהתקשר עמי, מאחר שאינה יכולה להיות רגע אחד אלא בו, בכסא (כנ\"ל אות ל\"א). ה\u0003ס'\u0004 לא רצתה להסתלק ממקומה, משום שצריכה לסמוך את אלו הנופלים (כנ\"ל אות כ\"ח) כי בלי \u0003סמך\u0004 אינם יכולים להיות."],[2,"","פז) \u0003יוד אתא לגבאי\u0004 וכו': היוד באה אלי יחידה. נשקה אותי, וחבקה אותי, ובכתה עמי, ואמרה לי: בני, מה אעשה לך, אבל הנה אני מסתלקת, ומתמלאת מכמה דברים טובים, ואותיות נסתרות עליונות ויקרות, ואח\"כ אבוא אליך, ואני אהיה עוזרת לך. ואתן לך נחלת שתי אותיות, שהן יותר עליונות מאלו שנסתלקו, שהן \u0003י\"ש\u0004, \u0003י'\u0004 עליונה, ו\u0003ש'\u0004 עליונה, שהן יהיו לך אוצרות מלאים מכל. ומשום זה, בני, לך והיה מחמר אחר חמורים. ועל כן אני הולך בכך."],[2,"","פירוש כבר ידעת, שסוד טעין חמרי ה\"ס עיבור נשמת הצדיק, הבאה לסיוע להולך בדרכי ה', לצאת ממדרגתו ולבא למדרגה יותר חשובה, כדוגמת החמרים המסיעים אנשים ממקום למקום על חמוריהם. והנה בעת ההיא גם הצדיק נופל ממדרגתו הקודמת ובא לבחינת עיבור של מדרגה חדשה כמו בחינת הנשמה שבאה לסייע לו. ובחינת עיבור פירושו הסתלקות מוחין. וזה שרצו לדעת ממנו, איך סיבב הקב\"ה שאתה באת בעיבור אלינו, שעי\"ז באנו להסתלקות המוחין. וז\"ש \u0003מאן יהב לך למיזל הכא, למהוי טעין בחמרי\u0004."],[2,"","וז\"ש, \u0003אמר לון, יו\"ד עבד קרבא בתרין אתוון בכ\"ף וסמ\"ך לאתקשרא בהדאי, י'\u0004 ה\"ס חכמה, כנודע. ומדרגת המוחין דנשמה נק' \u0003כס\u0004, מלשון כסא הכבוד. והוא משום שהמוחין דחכמה באים בה בלבוש וכיסוי ואינם מגולים. ובעת הגיע הזמן להשגת המוחין דחיה שהיא \u0003י'\u0004 דהוי\"ה, שהיא המדרגה שבאתי לזכותכם בה, הנה באמת רצתה החכמה לקשר בי גם המוחין ד\u0003כ\"ס\u0004, שהם המוחין דנשמה שהיתה בכם מקודם לכן, וה\u0003י' עבד קרבא\u0004 עמהם, אמנם \u0003כ\"ף לא בעא לאסתלקא ולאתקשרא בתר דלא יכלא למהוי רגעא חדא אלא ביה\u0004, פירוש כי המלכות דעליון המתלבשת בתחתון ה\"ס \u0003כ'\u0004, (כנ\"ל במאמר רב המנונא סבא ד\"ה ולפיכך ע\"ש). ונתבאר שם שבעת שרצתה ה\u0003כ'\u0004 לירד מעל הכסא \u0003אזדעזעא הכסא וכלהו עלמין אזדעזעו למנפל.\u0004 כי כל התקשרות המדרגות זו בזו מראש האצילות עד סוף העשיה היא ע\"י מלכות דעליון המתלבשת בתחתון, וע\"כ אינה יכולה לירד ממקומה דהיינו ממדרגת ישסו\"ת שהיא קומת נשמה, אפילו \u0003רגעא חדא\u0004, כי אי אפשר לעשות הפסקה במדרגות."],[2,"","וה\u0003ס' לא בעא לאסתלקא בגין לסעדא לאינון דנפלין דהא בלי סמך לא יכלין למהוי\u0004, כי סוד ה\u0003ס'\u0004 הוא עצם המוחין שהנשמה מקבלת מחב\"ד חג\"ת דאו\"א, שהם מושפעין לזו\"ן בעת קטנותן, וסומכין אותם שלא יפלו מאצילות לחוץ, (כנ\"ל אות כ\"ח ד\"ה דאית ע\"ש). וע\"כ צריכה להיות בקבע במקומה בלי שינוי. והענין הוא, כי המדרגות קבועות הן, ורק הנשמות מקבלות שינוים בעת הליכתן ממדרגה למדרגה. ולפיכך לא רצו המוחין של הנשמה להתחבר עם ה\u0003י'\u0004 שהיא קומת החכמה ולהתקשר בנשמת \u0003רב המנונא סבא\u0004 בעת ירידתה לסייע לר\"א ור\"א. כי היו צריכים לבנין והמשכת מוחין על הסדר מחדש, החל בעיבור וכו' עד קומת חיה."],[2,"","וז\"ש באות פ\"ז י\u0003וד אתא לגבאי יחידאה\u0004 וכו', כלומר, שבאה אלי בלי המוחין דחב\"ד חג\"ת דאו\"א, הנק' \u0003ס'\u0004 (כנ\"ל בדיבור הסמוך). ונודע שקומת חכמה אינה יכולה להתלבש בלי קומת חסדים הנמשכת מה\u0003ס'\u0004 כנ\"ל. וז\"ש כיון שה\u0003י'\u0004 באה \u0003יחידאה\u0004 בלי קומת חסדים ע\"כ \u0003נשיק לי, וגפיף לי, ובכה עמי, ואמר לי, ברי מה אעביד לך\u0004. כלומר, ש\u0003נשיק\u0004 לו ו\u0003גפיף\u0004 לו כי רצתה להתלבש בלי חסדים, וע\"כ בכתה עמו ואמרה \u0003ברי מה אעביד לך\u0004, הרי אין לי שום תחבולה להתלבש בך."],[2,"","וז\"ש, \u0003אנא אסתלק ואנא אתמלי מכמה טבין ואתוון טמירין\u0004 וכו': כלומר, ע\"כ אני מוכרחת להסתלק עכשיו, ואתה תבא בסוד העיבור, כדי שתבנה מעצמך בכל הבחינות של עיבור יניקה מוחין מחדש, ואז אחזור אליך במוחין שלמים ומלאים מכל. ותדע שמטעם זה המובא כאן, נוהג כך בכל מדרגה חדשה, כי כל אימת שהאדם צריך לקבל מדרגה חדשה, הוא מחויב לבא להסתלקות המוחין הקודמים ולהתחיל מחדש לקנות בחינת נפש הנק' עיבור ואח\"כ יניקה שהוא סוד אור הרוח וכו', כמו שלא היתה לו שום מדרגה מעולם. וז\"ש \u0003ובגין כך ברי, זיל והוי טעין חמרי\u0004 כי בשביל שאי אפשר להמשיך כלום מהמדרגה הקודמת, ע\"כ אתה צריך לבחי' עיבור מחדש, הנק' \u0003טעין חמרי\u0004."],[2,"","וז\"ש, \u0003אחסנתא דתרין\u0004 וכו', ה\"ס המוחין דחיה, הנקרא \u0003אחסנתא\u0004 דאו\"א, וכן נקראים \u0003י\"ש\u0004, כי \u0003י'\u0004 היא חכמה וה\u0003ש'\u0004 היא בינה. שהן ודאי חשובות יותר מאינון המוחין דנשמה שנסתלקו. וה\"ס הכתוב להנחיל אוהבי \u0003י\"ש\u0004 ואוצרותיהם אמלא (משלי ח'). וז\"ש \u0003למהוי לך אוצרין מלייא מכל\u0004. דהיינו בשיעור הכתוב ואוצרותיהם אמלא."],[3,"","פח) \u0003חדו ר' אלעזר\u0004 וכו': שמחו ר\"א ור' אבא, ובכו, ואמרו: לך רכב על החמור ואנחנו נהיה מחמרים אחריך. דהיינו שהוא ירכב, והם יוליכו החמור. אמר להם: ולא אמרתי לכם שהיא פקודת המלך עד שיבוא אותו המוליך חמורים. רומז על המשיח, שנאמר עליו עני ורוכב על החמור. אמרו לו, הנה את שמך לא הגדת לנו, מקום מושבך איפא הוא. אמר להם, מקום מושבי הוא טוב ורב ערך אצלי, והוא מגדל אחד הפורח באויר, הרב והיקר, ואותם הגרים במגדל הזה, הם הקב\"ה ועני אחד. וזה הוא מקום מושבי. והגליתי משם, ואני מחמר אחר חמורים. הסתכלו בו רבי אבא ור' אלעזר, והיו מוטעמים להם דבריו, שהיו מתוקים כמן וכדבש. אמרו לו, אם תאמר לנו שם אביך, ננשק את עפר רגליך. אמר להם ולמה זה, אין דרכי בכך להתגאות בתורה. \u0003עיילא\u0004 הוא מלשון דפליג בעלויא, שפירושו ערך (קדושין מב:)."],[3,"","פירוש. עתה שהכירו גודל מעלתו, לא יכלו לסבול בחינת העיבור שלו לצרכם, וע\"כ אמרו לו, כי עתה שכבר השיגו המוחין, א\"כ די לו, והוא יכול לצאת מבחינת העיבור, ואם אולי יש להם עוד מה להשלים, יוכלו בעצמם להיות בעיבור, ולמה לו לסבול בשבילם. וז\"ש \u0003זיל רכיב ואנן נטעין אבתרך\u0004."],[3,"ולא אמרית לכון וכו' עד דייתי ההוא דטען חמרי",": הכוונה היא במה שאמר להם מקודם לכן, שלא ישאלו לשמו משום שצריכים עוד לגילוים של רזין דאורייתא. ורמז להם כאן עוד, כי הכוונה היא על בחינת יחידה שחסר להם, שה\"ס קבלת פנים של המלך המשיח (כנ\"ל אות פ\"ה ד\"ה ובזה) וזה הרמז \u0003עד דייתי ההוא דטען חמרי\u0004, שמלך המשיח ה\"ס \u0003עני ורוכב על החמור\u0004. (זכריה ט'). וז\"ש \u0003דפקודא דמלכא איהו עד דייתי ההוא דטען חמרי\u0004, כי מצוות המלך היא עליו, לסייע להם עד שיזכו לאור היחידה."],[3,"","וז\"ש, \u0003הא שמך\u0004 וכו': כיון שלא אמרת לנו את שמך, שהוא משום שעוד לא השגנו ממך מה שצריך לנו להשיג כנ\"ל, א\"כ עכ\"פ תוכל לומר לנו \u0003אתר בית מותבך\u0004, דהיינו מקום מדרגתך, שבזה נדע עכ\"פ מה שחסר לנו מלהשיג ממך. \u0003אמר לון אתר בית מותבי איהו טב ועיילא לגבאי\u0004, כלומר, מקום מדרגתי הוא טוב ונשא לגבי המדרגה שאני עומד בה עכשיו. כי עתה גם ממני עצמי הוא נפלא מהשגתי."],[3,"","וז\"ש, \u0003מגדל חד\u0004 וכו': מגדל זה, ה\"ס היכל המשיח, וז\"ש \u0003דדיירין ביה קב\"ה וחד מסכנא\u0004. כי המשיח ה\"ס עני ורוכב על החמור. ומה שמכנהו \u0003רב ויקירא\u0004, הוא, כי סתם מגדל הפורח באויר, הוא בינה. אבל כאן דקאי על היכלו של המשיח, ע\"כ מציין אותו בשם \u0003מגדל חד דפרח באוירא רב ויקירא\u0004. וז\"ש, \u0003ודא הוא אתר בית מותבי וגלינא מתמן ואנא טעין חמרי\u0004: מקום מושבי הוא במגדל, אבל עכשיו הוא נפלא ממני, כמו שאמר מקודם לכן, שהוא \u0003טב ועיילא לגבאי\u0004. כי \u0003גלינא מתמן ואנא טעין חמרי\u0004."],[4,"","פט) \u0003אבל אבא דילי\u0004 וכו': אבל מקום מגורי אבי, היה בים הגדול. והוא היה דג אחד, שהיה מסבב את הים הגדול מעבר לעבר. והיה גדול ויקר, וזקן ושבע ימים, עד שהיה בולע כל שאר דגי הים, והוציאם אחר כך חיים וקיימים ומלאים מכל טוב העולם. ובתקפו היה שט כל הים ברגע אחד. והוציאני, כחץ ביד אדם גבור, והחביאני באותו המקום שאמרתי לכם, דהיינו במגדל הפורח באויר, והוא שב למקומו, ונגנז בים ההוא."],[4,"","ביאור הדברים, הזווג הנעלם, מכונה \u0003חד נונא\u0004, הרומז לשער הנון. \u0003וימא רבא\u0004 הוא המלכות. והנה כל הזווגים שמעתיק דאצילות ולמטה אינם כוללים כל \u0003ימא רבא\u0004, דהיינו לכל ספירותיה של המלכות, אלא רק לט\"ר של המלכות בלבד, והמלכות דמלכות אינה בכלל הזווג. (כנ\"ל אות מ\"ג ד\"ה אגליפו עש\"ה). כי היא נשארת בסוד נתיב דלא ידעו עיט, אמנם בעתיק יומין יש זווג על המלכות הזו גם כן, שהוא יתגלה רק בגמר התיקון."],[4,"","ורב המנונא יצא מהזווג הנעלם ההוא שבעתיק יומין, וע\"כ קורא אותו בשם \u0003אבא דילי\u0004, וז\"ש \u0003אבא דילי הוה דיוריה בימא רבא\u0004 כלומר, שנזדווג עם המלכות הנקראת ימא רבא. ושמא תאמר, הרי כל הפרצופין מזדווגין על המלכות, לזה אומר \u0003ואיהו הוה חד נונא דהוה אסחר ימא רבא מסטרא דא לסטרא דא\u0004 כלומר, שהוא בחינת זווג של שער הנון, שהוא מזדווג עם \u0003ימא רבא\u0004 מכל הבחינות שבה. מכתר עד מלכות, דהיינו \u0003מסטרא דא לסטרא דא\u0004, לרבות גם על המלכות דמלכות. וז\"ש \u0003והוה רב ויקירא ועתיק יומין\u0004 כי הוא נק' בשם \u0003עתיק יומין\u0004. וממנו ולמטה אין הזווג הגדול הזה במציאות."],[4,"","וז\"ש \u0003עד דהוה בלע כל שאר נונין דימא\u0004: כי הזווג הגדול הזה בולע בתוכו כל הזווגים והנשמות שבכל העולמות כולם, כי כולם נכללים ומתבטלים בו כנר בפני האבוקה. ומבחינת התכללות זו, נק' אז כולם בשם נונין."],[4,"","וז\"ש \u0003ולבתר אפיק לון חיין וקיימין מליין מכל טבין דעלמא\u0004: היינו אחר תיקונים גדולים הבאים לאחר הזווג הזה, חוזר ומוליד כל אלו המאורות והנשמות שבלע אותם בעת הזווג, והם חיים וקיימים לנצח, כי כבר נתמלאו \u0003מכל טבין דעלמא\u0004 מכח שבלע אותם ע\"י הזווג הגדול שלו."],[4,"","וז\"ש, \u0003ושאט ימא\u0004 וכו' כי כל הזווגים שמעתיק יומין ולמטה באים בבחינות התלבשות הספירות זו בזו, שהתלבשיות אלו נבחנות כמו הפסקות בדרך הזווג עד שהטפה באה ליסודות דו\"נ. משא\"כ בזווג הגדול הזה דעתיק יומין, הוא בלי שום התלבשות וע\"כ נבחן שהזווג הוא \u0003ברגעא חדא\u0004."],[4,"","וז\"ש \u0003ושאט ימא ברגעא חדא\u0004 בלי שום התלבשות. והוא \u0003בתוקפיה\u0004 כי זה הוא מחמת רוב הגבורות הנכללות בזווג זה. וז\"ש \u0003ואפיק לי כגירא בידא דגבר תקיף\u0004. הוליד אותי כחץ ביד איש גבור. אמנם גבורות אלו אין להן שום דמיון לגבורות הנוהגות בזווגים שלמטה מעתיק יומין, אלא שהן סוד עין לא ראתה אלהים זולתך. כמ\"ש להלן. אמנם ודאי הוא, שאין לידה בלי גבורות. כי זרע שאינו יורה כחץ אינו מוליד (חגיגה ט\"ז). וז\"ש \u0003ואפיק לי כגירא בידא דגבר תקיף\u0004."],[4,"","וז\"ש \u0003וטמיר לי בההוא אתר דאמרית לכו\u0004 היינו \u0003במגדל רב ויקירא, דדיירין ביה קב\"ה וחד מסכנא\u0004 כנ\"ל. \u0003והוא תב לאתריה ואגניז בההוא ימא\u0004 כלומר, לאחר שהוליד אותי וגנז אותי \u0003במגדל רב ויקירא\u0004, חזר לזווג שלו וגניזו במקומו כלפנים."],[5,"","צ) \u0003אשגח ר' אלעזר\u0004 וכו': הסתכל ר' אלעזר בדבריו, אמר לו: אתה הוא בנו של המאור הקדוש, אתה הוא בנו של רב המנונא הזקן, אתה הוא בנו של מאור התורה, ואתה מחמר אחרינו. בכו יחד, ונשקוהו, והלכו. חזרו ואמרו לו, אולי טוב לפני אדוננו להודיענו את שמו."],[5,"","פירוש. כי עוד לא השיגו דבריו הנ\"ל בשלמות, והשגתם היתה עוד רק במוחין דחיה לבד, וע\"כ חשבוהו \u0003לבריה דרב המנונא סבא\u0004, כי רב המנונא עצמו הוא מבחינת המוחין דיחידה. \u0003לאודעא לן שמיה\u0004: היינו לקבל מדרגתו, כי השגת שמו, פירושה השגת מדרגתו. כנ\"ל."],[6,"","צא) \u0003פתח ואמר ובניהו\u0004 וכו': פו\"א, ובניהו בן יהוידע (שמואל ב' כ\"ג) מקרא זה העמידוהו, ויפה הוא. אבל מקרא זה, להראות סודות העליונים של התורה הוא בא. והשם \u0003בניהו בן יהוידע\u0004, לרמז על סוד החכמה הוא בא. דבר סתום הוא מרמז, והשם גרם. \u0003בן איש חי\u0004, זה הוא צדיק חי העולמים. \u0003רב פעלים\u0004, היינו שהוא אדון כל המעשים, וכל צבאות העליונים, כי כולם יוצאים ממנו, הוא נקרא ה' צבאות, להיותו אות בכל הצבאות שלו, מצויין הוא ורב מכל."],[6,"","פירוש. שהכתוב מראה ומגלה כאן רזין עליונים דאורייתא, \u0003ובניהו בן יהוידע על רזא דחכמתא קא אתא\u0004 כי השם הקדוש \u0003יהו-ידע\u0004, ידיעה זו באה \u0003על רזא דחכמתא. מלה סתימא איהו\u0004, הוא רז סתום מאד נעלה. \u0003ושמא גרים\u0004 השם \u0003יהו-ידע\u0004 גורם שיהיה סתום."],[6,"","וביאור הדברים. כי הכתר דאצילות הנק' רדל\"א ועתיק יומין הוא בבחינת מקיף על ה\"פ אצילות א\"א ואו\"א וזו\"ן, והוא נק' רישא דלא ידע ולא אתידע, לא ידע, פירושו שאין שם זווג אפילו במקומו עצמו, ולא אתידע, פירושו, שאין ממנו המשכת מוחין למדרגות שממנו ולמטה. וגם א\"א דאצילות נעלם מהתחתונים. כי ע\"כ הוא נקרא בשם \u0003חכמה סתימאה\u0004. אמנם אינו נבחן ללא ידע כמו רדל\"א, כי יש בו זווג במקומו עצמו, אלא שהוא רק לא אתידע בלבד, שאין ממנו המשכת מוחין למטה. וכל המוחין דאתידע בעולמות בשתא אלפי שני הם רק מבחינת או\"א וישסו\"ת, הנק' חכמה דל\"ב נתיבות, או ל\"ב אלהים דמעשה בראשית."],[6,"","וז\"ס הכתוב (איוב כ\"ח, כ'), והחכמה מאין תבא ואי זה מקום בינה ונעלמה מעיני כל חי וכו' אלהים הבין דרכה והוא ידע את מקומה. וביאר (באדרת האזינו אות ע\"ב) \u0003אלהים הבין דרכה, דרכה ממש. אבל והוא ידע את מקומה מקומה ממש, וכ\"ש דרכה, וכ\"ש ההיא חכמה דסתימא ביה בעתיקא קדישא\u0004. ע\"ש. כוונתם היא, כי הבין דרכה היינו רק החכמה דל\"ב נתיבות, שה\"ס ל\"ב אלהים דמעשה בראשית, וע\"כ אומר \u0003אלהים\u0004 הבין דרכה, ומדגיש הכתוב את החכמה בלשון בינה, כי אומר \u0003הבין דרכה\u0004, משום כי חכמה זו מבחינת עצמותה היא רק בינה, אלא נעשית לחכמה ע\"י עליתה לראש א\"א, שמקבלת מח\"ס ומשפעת למטה. ונמצאת שהחכמה הזו נגלית רק בדרכה של הבינה בעת עליתה לחכמה סתימאה דא\"א, וזה שיעור הכתוב, \u0003אלהים\u0004, שהוא הבינה, \u0003הבין דרכה\u0004 לשפע החכמה, וז\"ש, \u0003דרכה ממש\u0004 רק בחינת דרך אל שפע החכמה, אבל היא עצמה היא בינה ולא חכמה."],[6,"","וסו\"ה \u0003והוא ידע את מקומה\u0004, קאי על א\"א, כי השם הוא מורה על נסתר וסתום מתחתונים, שהוא א\"א הנק' \u0003עתיקא קדישא\u0004. ועליו אומר \u0003שידע\u0004 את \u0003מקומה\u0004 של החכמה דל\"ב נתיבות, להיותו עצם החכמה המשפיע אל הבינה. וז\"ש הזוהר, \u0003מקומה ממש וכ\"ש דרכה\u0004 כי בהיותו מקומה של השפעת החכמה הזו מכ\"ש שיודע את דרכה של החכמה כשהיא מלובשת בבינה. ואומר עוד \u0003וכ\"ש ההיא חכמה דסתימא ביה בעתיקא קדישא\u0004 כלומר, מכ\"ש שהוא ידע בחינת חכמה סתימאה של עצמו. אלא ג\"כ בסוד והוא ידע את מקומה, כי רק בו במקומו ממש, מגולה הזווג הזה, אבל ממנו ולמטה אינו מושפע כלום. הרי שמוחא דא\"א הוא בבחינת ידע במקומו עצמו, אבל הוא בבחינת לא אתידע ממנו ולמטה. ורק מוחין דאו\"א שהם המוחין דל\"ב נתיבות החכמה. הם בבחינת אתידע. בסו\"ה אלהים הבין דרכה. אבל הראש העליון שהוא למעלה מא\"א, דהיינו הראש דעתיק יומין, הוא בבחינת לא ידע ולא אתידע, שאין זווג אפילו במקומו עצמו, ואין ממנו שום התפשטות מוחין לתחתונים."],[6,"","והנה כל זה אמור רק בכללות הנשמות והעולמות. אמנם מבחינת פרטיות הנשמות, יש נשמות גבוהות שזכו להיות מ\"ן לזווג הגדול דההוא רישא דע\"י לאחר פטירתם, ולקבל שם בעולם העליון קומת היחידה הבאה מזווג זה, שהם הנשמות \u0003דבניהו בן יהוידע, ודרב המנונא סבא\u0004 ועוד. ואלו הנשמות הגבוהות מתגלות לצדיקים שבעוה\"ז, וגם הצדיקים זוכים ליאות לאור היחידה המאיר בנשמות הגבוהות ההן."],[6,"","וזה אמרו \u0003ובניהו בן יהוידע על רזא דחכמתא קא אתא\u0004, שהנשמה הזו הנק' בשם \u0003בניהו בן יהוידע\u0004 באה מפנימיות החכמה, דהיינו חכמה דע\"י הנ\"ל. \u0003מלה סתימא איהו\u0004 הארת הנשמה ההיא היא ענין סתום. \u0003ושמא גרים\u0004 כי השם \u0003יהו-ידע\u0004 גרם להארת הנשמה ההיא שתהיה סתומה, כי משמעותו היא, כי \u0003יה\"ו ידע\u0004, אבל לא אתידע לאחרים, וא\"כ הרי נשאר סתום במקומו עצמו. והנה תחילה הוא מבאר איכות הזווג ומעלת קומת האור הגדול היוצא מזווג זה דרישא דע\"י, שזה מתבאר בסו\"ה \u0003בן איש חי רב פעלים מקבצאל\u0004. ואח\"כ מבאר ענין מלה סתימא שבהארת הנשמה ההיא. וזה המתבאר בכתוב והוא הכה שני אריאל מואב עד סוף הפסוק."],[6,"","וז\"ש \u0003בן איש חי\u0004 וכו': פי' כי ידעת שענין הזווג הזה הוא בחינת הזווג של גמר התיקון, וסודו הוא הזווג הכולל לכל הזווגים והקומות שיצאו בזו אחר זו במשך שתא אלפי שני, אשר כל האורות הללו כולם מתקבצים בו בבת אחת, ועד\"ז גם בחינת מ\"ן העולים לזווג הזה כוללת בתוכה כל בחינת היסורים והעונשים שנתגלו בשתא אלפי שני בזה אחר זה. ולפיכך אין קץ לגבהה של הקומה היוצאת מזווג זה, והיא משביתה הקליפות והס\"א לנצח. והיסוד שהוא משפיע המיין דוכרין הכוללים כל האורות שיצאו בשתא אלפי שני, הוא נק' \u0003איש חי רב פעלים\u0004, ובחי' המלכות הכוללת בתוכה כל המ\"ן והיסורין שנגלו בשתא אלפי שני, היא נק' \u0003מקבצאל\u0004."],[6,"","וזה אמרו, \u0003בן איש חי דא צדיק חי עלמין\u0004 כי השם הזה מורה תמיד על היסוד המשפיע לנוקבא, אשר אין לו מקום בית קבול לצורך עצמו, וע\"כ נבחן שאינו חי רק בעלמא, דהיינו בנוקבא בהיותו משפיע אליה. וע\"כ נקרא צדיק חי עלמין. אבל בזווגו זה הוא מצוין בשם \u0003רב פעלים\u0004, שפירושו הוא \u0003מארי דכל עובדין וכל חילין עלאין\u0004, שהוא כולל עתה בהמ\"ד שלו כל המעשים הטובים, וכל המדרגות העליונות שנתגלו בזה אחר זה במשך הזמן דשתא אלפי שני. כי הם כולם נתקבצו בו עתה בבת אחת, ומתחדשים באור העליון ויוצאים ממנו בבת אחת אל הנוקבא, ולכן הוא נקרא בשם \u0003רב פעלים\u0004."],[6,"","וז\"ש \u0003בגין דכלהו נפקי מניה\u0004 שיוצאים כולם בבת אחת אל הנוקבא. \u0003הוי\"ה צבאות איהו, אות הוא בכל חיילין דידיה, רשים הוא ורב מכלא\u0004, כלומר, כי עתה נגלה בו השם הקדוש \u0003ה' צבאות\u0004 בשלמותו הנעלה, שהרי הוא עתה \u0003אות\u0004 בכלהו צבאות שלו להיותו רשום מכל עובדין וחילין \u0003והוא רב מכלא\u0004 והוא מתגדל ועולה בהארתו על כל אלו."],[7,"","צב) \u0003רב פעלים איהו\u0004 וכו': רב פעלים הוא מקבצאל. אילן הגדול והיקר הזה, הגדול מכל, מאיזה מקום יצא. מאיזה מדרגה בא. חזר הכתוב ואמר \u0003מקבצאל\u0004, שהיא מדרגה עליונה וסתומה, שעין לא ראתה וגו'. שהיא מדרגה שהכל בה, והיא מאספת בתוכה מאור העליון, וממנה יוצא הכל."],[7,"","ביאור הדברים, הנוקבא נק' עתה בשם \u0003מקבצאל\u0004, והוא מטעם, כי \u0003רב פעלים איהו מקבצאל\u0004, שהנוקבא מקבצת בתוכה האורות כולם בבת אחת מן היסוד, הנק' משום זה \u0003רב פעלים\u0004. ומבאר: הקומה היוצאת על הזווג הזה נק' \u0003אילנא רב ויקירא\u0004, שהוא נפק מן היסוד, ואתא אל הנוקבא. ואומר שבכדי להראות לנו את איכותה של הקומה הגבוהה הזו מאין היא נפקת ובאה, השיבו הכתוב בשם \u0003מקבצאל\u0004, שהאור העליון מקבץ אותם ביסוד, ומשפעתם לנוקבא. ונקראים שניהם יחד בשם מקבצאל."],[7,"","והוא \u0003דרגא עלאה סתימאה דעין לא ראתה\u0004 וגו' כלומר, שהמדרגה הזאת היוצאת מהזווג הזה, נקראת בשם \u0003עין לא ראתה אלהים זולתך\u0004. ואומר, בהאי \u0003דרגא\u0004 נמצא כל התקון בזמן השלמות האחרונה, וע\"כ הוא נבחן \u0003לדרגא דכולא ביה\u0004, והוא מכח \u0003וכניש בגויה מגו נהורא עלאה כי קבץ בתוכה מכח נהורא עלאה\u0004, לכל טבין ונהורין עלאין, מכל שתא אלפי שני בבת אחת, וחידש אותם באור העליון. ולפיכך \u0003ומניה נפיק כלא\u0004, כי ע\"כ יוצאת ונגלית עתה כל השלמות המקווה."]],[[0,"","וְעַל זֶה כָּתוּב תִּשְׁמֹרוּ, נִכְלָל בְּשָׁמוֹר. וּמִקְדָּשִׁי תִּירָאוּ - זוֹ הַנְּקֻדָּה שֶׁעוֹמֶדֶת בָּאֶמְצַע שֶׁיֵּשׁ לִירָא מִמֶּנָּה יוֹתֵר מִן הַכֹּל שֶׁעָנְשׁוֹ מִיתָה. וְהַיְנוּ מַה שֶּׁכָּתוּב (שמות לא) מְחַלֲלֶיהָ מוֹת יוּמָת. מִי הֵם מְחַלֲלֶיהָ מִי שֶׁנִּכְנָס לְתוֹךְ הֶחָלָל שֶׁל הָעִגּוּל וְהָרִבּוּעַ לַמָּקוֹם שֶׁאוֹתָהּ הַנְּקֻדָּה שׁוֹרָה וּפוֹגֵם בּוֹ - מוֹת יוּמָת. וְעַל זֶה כָּתוּב תִּירָאוּ. וְהַנְּקֻדָּה הַהִיא נִקְרֵאת אֲנִי, וְעָלֶיהָ שׁוֹרֶה אוֹתוֹ הַנִּסְתָּר הָעֶלְיוֹן שֶׁלֹּא הִתְגַּלָּה. וְהַיְנוּ ה', וְהַכֹּל אֶחָד. יָרְדוּ רַבִּי אֶלְעָזָר וְרַבִּי אַבָּא וְנָשְׁקוּ אוֹתוֹ. אָמְרוּ, וּמַה כָּל הַחָכְמָה הַזּוֹ יֵשׁ תַּחַת יָדְךְ וְאַתָּה מְחַמֵּר אַחֲרֵינוּ אָמְרוּ לוֹ, מִי אַתָּה אָמַר לָהֶם, אַל תִּשְׁאֲלוּ מִי אֲנִי, אֶלָּא אֲנִי וְאַתֶּם נֵלֵךְ וְנִתְעַסֵּק בַּתּוֹרָה, וְכָל אֶחָד יֹאמַר דִּבְרֵי חָכְמָה לְהָאִיר אֶת הַדֶּרֶךְ."],[1,"","אָמְרוּ לוֹ, מִי נָתַן לְךְ לָלֶכֶת כָּאן וְלִהְיוֹת מְחַמֵּר בַּחֲמוֹרִים אָמַר לָהֶם, יוֹ\"ד עָשְׂתָה קְרָב עִם שְׁתֵּי אוֹתִיּוֹת, עִם כָּ\"ף וְסָמֶ\"ךְ, לְהִקָּשֵׁר עִמִּי (נ\"א: יחד). כָּ\"ף לֹא רָצְתָה לְהִסְתַּלֵּק וּלְהִקָּשֵׁר מֵאַחַר (נ\"א במקום) שֶׁלֹּא יָכְלָה לִהְיוֹת רֶגַע אֶחָד אֶלָּא עִמּוֹ. סָמֶ\"ךְ לֹא רָצְתָה לְהִסְתַּלֵּק, כְּדֵי לַעְזר לְאוֹתָם הַנּוֹפְלִים, שֶׁהֲרֵי בְּלִי סָמֶ\"ךְ לֹא יְכוֹלִים לִהְיוֹת."],[2,"","יוֹ\"ד בָּאָה אֵלַי יְחִידָה, נָשְׁקָה לִי וְחִבְּקָה אוֹתִי, בָּכְתָה עִמִּי וְאָמְרָה לִי: בְּנִי, מָה אֶעֱשֶׂה לְךְ אֲבָל הֲרֵי אֲנִי מִסְתַּלֶּקֶת, וַאֲנִי מִתְמַלֵּאת מִכַּמָּה טוֹבוֹת וְאוֹתִיּוֹת נִסְתָּרוֹת עֶלְיוֹנוֹת וְנִכְבָּדוֹת. לְאַחַר מִכֵּן אָבא אֵלֶיךְ וְאֶסְעַד אוֹתְךְ, וְאֶתֵּן לְךְ נַחֲלָה שֶׁל שְׁתֵּי אוֹתִיּוֹת עֶלְיוֹנוֹת יוֹתֵר מֵאֵלּוּ שֶׁהִסְתַּלְּקוּ, שֶׁהֵם י\"ש, יוֹ\"ד עֶלְיוֹנָה וְשִׁי\"ן עֶלְיוֹנָה, שֶׁיִּהְיוּ לְךְ אוֹצָרוֹת מְלֵאִים מִכֹּל. וּמִשּׁוּם כָּךְ, בְּנִי, לֵךְ וְתִהְיֶה מְחַמֵּר חֲמוֹרִים, וְעַל כֵּן אֲנִי הוֹלֵךְ בְּכָךְ."],[3,"","שָׂמְחוּ רַבִּי אֶלְעָזָר וְרַבִּי אַבָּא, וּבָכוּ וְאָמְרוּ, לֵךְ רְכַב, וְאָנוּ נְחַמֵּר אַחֲרֶיךְ. אָמַר לָהֶם, וְלֹא אָמַרְתִּי לָכֶם שֶׁמִּצְוַת הַמֶּלֶךְ הִיא עַד שֶׁיָּבֹא אוֹתוֹ מְחַמֵּר עַל הַחֲמוֹרִים אָמְרוּ לוֹ, הֲרֵי שִׁמְךְ לֹא אָמַרְתָּ לָנוּ, מְקוֹם בֵּית מוֹשָׁבְךְ מַה הוּא אָמַר לָהֶם, מְקוֹם בֵּית מוֹשָׁבִי הוּא טוֹב וּמְעֻלֶּה אֶצְלִי, וְהוּא מִגְדָּל אֶחָד שֶׁפּוֹרֵחַ בָּאֲוִיר, גָּדוֹל וְנִכְבָּד. וְאוֹתָם הַדָּרִים בּוֹ בַּמִּגְדָּל הַזֶּה - הַקָּדוֹשׁ בָּרוּךְ הוּא וְעָנִי אֶחָד, וְזֶה הוּא מְקוֹם בֵּית מוֹשָׁבִי. וְגָלִיתִי (נ\"א: ועליתי) מִשָּׁם, וַאֲנִי מְחַמֵּר עַל חֲמוֹרִים. הִסְתַּכְּלוּ בוֹ רַבִּי אַבָּא וְרַבִּי אֶלְעָזָר, וְהִטְעִים לָהֶם אֶת דְּבָרָיו, שֶׁהָיוּ מְתוּקִים כְּמוֹ מָן וּדְבַשׁ. אָמְרוּ לוֹ, שֵׁם אָבִיךְ אִם תֹּאמַר, נְנַשֵּׁק אֶת עֲפַר רַגְלֶיךְ. אָמַר לָהֶם, וְלָמָּה אֵין דַּרְכִּי בְּכָךְ לְהִתְגָּאוֹת בַּתּוֹרָה"],[4,"","אֲבָל אָבִי הָיְתָה דִירָתוֹ בַּיָּם הַגָּדוֹל, וְהוּא הָיָה דָּג אֶחָד שֶׁהָיָה סוֹבֵב אֶת הַיָּם הַגָּדוֹל מִצַּד זֶה לְצַד זֶה, וְהָיָה גָּדוֹל וְנִכְבָּד וְעַתִּיק יָמִים, עַד שֶׁהָיָה בּוֹלֵעַ אֶת כָּל שְׁאָר הַדָּגִים שֶׁל הַיָּם, וְאַחַר כָּךְ מוֹצִיא אוֹתָם חַיִּים וְקַיָּמִים וּמְלֵאִים מִכָּל הַטּוֹבוֹת שֶׁל הָעוֹלָם. וְשָׁט אֶת הַיָּם בְּרֶגַע אֶחָד בְּכֹחוֹ, וְהוֹצִיא אוֹתִי כַּחֵץ בְּיַד אִישׁ גִּבּוֹר, וְהִטְמִין אוֹתִי בְּאוֹתוֹ מָקוֹם שֶׁאָמַרְתִּי לָכֶם, וְהוּא שָׁב לִמְקוֹמוֹ וְנִגְנַז בְּאוֹתוֹ הַיָּם."],[5,"","הִבְחִין רַבִּי אֶלְעָזָר בִּדְבָרָיו. אָמַר לוֹ, אַתָּה הוּא בְּנוֹ שֶׁל הַמָּאוֹר הַקָּדוֹשׁ, אַתָּה הוּא בְּנוֹ שֶׁל רַב הַמְנוּנָא הַזָּקֵן, אַתָּה הוּא בְּנוֹ שֶׁל אוֹר הַתּוֹרָה, וְאַתָּה מְחַמֵּר אַחֲרֵינוּ! בָּכוּ יַחַד וְנָשְׁקוּ לוֹ וְהָלְכוּ. אָמְרוּ לוֹ, הַאִם נוֹחַ לִפְנֵי מוֹרֵנוּ לְהוֹדִיעַ לָנוּ אֶת שְׁמוֹ."],[6,"","פָּתַח וְאָמַר, (שמואל ב כג) וּבְנָיָהוּ בֶן יְהוֹיָדָע. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ, וְהוּא יָפֶה. אֲבָל הַפָּסוּק הַזֶּה בָּא לְהַרְאוֹת סוֹדוֹת עֶלְיוֹנִים שֶׁל הַתּוֹרָה. וּבְנָיָהוּ בֶן יְהוֹיָדָע - עַל סוֹד הַחָכְמָה בָּא הַדָּבָר הַנִּסְתָּר הַהוּא, וְהַשֵּׁם גּוֹרֵם. בֶּן אִישׁ חַי - זֶה צַדִּיק חַי הָעוֹלָמִים. רַב פְּעָלִים - רִבּוֹן כָּל הַמַּעֲשִׂים וְכָל הַכֹּחוֹת הָעֶלְיוֹנִים, מִשּׁוּם שֶׁכֻּלָּם יוֹצְאִים מִמֶּנּוּ, הוּא ה' צְבָאוֹת, אוֹת הוּא בְּכָל צְבָאָיו, רָשׁוּם הוּא וְגָדוֹל מִן הַכֹּל."],[7,"","רַב פְּעָלִים - הוּא מִקַּבְצְאֵל, הָאִילָן הַגָּדוֹל וְהַנִּכְבָּד גָּדוֹל מֵהַכֹּל. מֵאֵיזֶה מָקוֹם יָצָא מֵאֵיזוֹ דַרְגָּה בָּא חָזַר הַכָּתוּב וְאָמַר, מִקַּבְצְאֵל. הַדַּרְגָּה הָעֶלְיוֹנָה הַנִּסְתֶּרֶת שֶׁעַיִן לֹא רָאָתָה וְגוֹ'. הַדַּרְגָּה שֶׁהַכֹּל בָּהּ, וְכוֹנֶסֶת לְתוֹכָהּ מִתּוֹךְ הָאוֹר הָעֶלְיוֹן, וּמִמֶּנָּה יוֹצֵא הַכֹּל."]]],[["וְאִיהוּ הֵיכָלָא קַדִּישָׁא סְתִימָא דְּכָל דַּרְגִּין כְּנִישִׁין וּסְתִימִין בְּגַוֵּיהּ. וּבְגוּפָא דְּהַאי הֵיכָלָא (אילנא) קַיָּימִין, כָּל עָלְמִין וְכָל חַיָּלִין קַדִּישִׁין מִינֵּיהּ אִתְזָנוּ וְקַיְימֵי עַל קִיּוּמֵיהוֹן.","הוּא הִכָּה אֶת שְׁנֵי אֲרִיאֵל מוֹאָב. תְּרֵין מִקְדְּשִׁין הֲווּ קַיָּימִין בְּגִינֵיהּ וְאִתְזְנוּ מִנֵּיהּ מִקְדָּשׁ רִאשׁוֹן וּמִקְדָּשׁ שֵׁנִי, כֵּיוָן דְּאִיהוּ אִסְתַּלַּק, נְגִידוּ דְּהֲוָה נְגִיד מִלְּעֵילָא אִתְמְנַע, כִּבְיָכוֹל הוּא הִכָּה לוֹן וְחָרִיב לוֹן וְשָׁצֵי לוֹן. וְכֻּרְסְיָיא קַדִּישָׁא נָפְלַת הֲדָא הוּא דִכְתִיב (יחזקאל א׳:א׳) וַאֲנִי בְּתוֹךְ הַגּוֹלָה. הַהוּא דַרְגָּא דְּאִקְרֵי אֲנִי, הוּא בְּתוֹךְ הַגּוֹלָה. אַמַּאי. עַל נְהַר כְּבָר. עַל נָהָר דְּנָגִיד וְנָפִיק דְּפָסִיק מֵימוֹי וּמַבּוּעוֹי וְלָא אִנְגִיד כַּד בְּקַדְמִיתָא (כדבקדמיתא).","הֲדָא הוּא דִכְתִיב, (איוב י״ד:י״א) וְנָהָר יֶחרַב וְיָבֵשׁ. יֶחרַב בְּבַיִת רִאשׁוֹן וְיָבֵשׁ בְּבַיִת שֵׁנִי. וּבְגִין כָּךְ הוּא הִכָּה אֶת שְׁנֵי אֲרִיאֵל, מוֹאָב. (ס\"א דהא בקדמיתא) מוֹאָב דְּהֲווּ מֵאָב דְּבִשְׁמַיָא וְאִתְחָרְבוּ וְאִשְׁתֵּצִיאוּ בְּגִינֵיהּ, וְכָל נְהוֹרִין דְּהֲווּ נְהִירִין לְיִשְׂרָאֵל כֻּלְהוּ אִתְחֲשָׁכוּ.","וְתוּ הוּא יָרַד וְהִכָּה אֶת הָאֲרִי. בְּזִמְנִין קַדְמָאִין כַּד הַאי נָהָר הֲוָה מָשִׁיךְ מֵימוֹי לְתַתָּא, הֲווּ קַיָּימִין יִשְׂרָאֵל בִּשְׁלִימוּ, דְּדַבְּחִין דִּבְחִין וְקָרְבְּנִין לְכַפָּרָא עַל נַפְשַׁיְיהוּ, וּכְדֵין הֲוָה נָחִית מִלְּעֵילָא דִּיוּקְנָא דְּחַד אַרְיֵה וְהֲווּ חָמָאן לֵיהּ עַל גַּבֵּי מַדְבְּחָא רָבִיץ עַל טַרְפֵּיהּ, אָכִיל קָרְבְּנִין כִּגְבַר תַּקִּיף. וְכָל כַּלְבִּין הֲווּ מִתְטַמְרִין מִקַּמֵּיהּ וְלָא נַפְקֵי לְבַר.","כֵּיוָן דְגָרְמוּ חוֹבִין אִיהוּ נָחִית לְגוֹ דַּרְגִּין דִּלְתַתָּא וְקָטִיל לְהַהוּא אַרְיֵה, דְּלָא בָעָא לְמֵיהַב לֵיהּ טַרְפֵּיהּ כִּדְבְקַדְמִיתָא, כִּבְיָכוֹל קָטִיל לֵיהּ. הוּא הִכָּה אֶת הָאֲרִי וַדַּאי. לְתוֹךְ הַבּוֹר לְעֵינָהָא דְּסִטְרָא אָחֳרָא בִּישָׁא. כֵּיוָן דְּחָמַאת הָכִי הַהוּא סִטְרָא אָחֳרָא אִתְתַּקְפַת (בר\"מ פ' בהר קי\"א) וְשַׁדְּרַת לְחַד כַּלְבָּא לְמֵיכַל קָרְבְּנִין. וּמַה שְּׁמֵיהּ דְּהַהוּא אַרְיֵ\"ה אוֹרִיאֵ\"ל דְּאַנְפּוֹי אַנְפֵּי אַרְיֵה. וּמַה שְּׁמֵיהּ דְּהַהוּא כַּלְבָּא בְּלַאדָן שְׁמֵיהּ. דְּלָאו אִיהוּ בִּכְלַל אָדָם, אֶלָא כַּלְבָּא וְאַנְפֵּי כַּלְבָּא.","בְּיוֹם הַשֶּׁלֶג בְּיוֹמָא דְּגָרְמוּ חוֹבִין וְדִינָא אִתְדָן לְעֵילָא מֵעִם בֵּי דִינָא עִלָּאָה. וְעַל דָּא כְּתִיב לֹא תִירָא לְבֵיתָהּ מִשָּׁלֶג דָּא דִינָא עִלָּאָה. אַמַּאי בְּגִין דְּכָל בֵּיתָהּ לָבוּשׁ שָׁנִים וְיָכִיל לְמִיסְבַּל אֶשָּׁא תַּקִּיפָא. עַד כָּאן רָזָא דִקְרָא.","מַה כְּתִיב בַּתְרֵיהּ (שמואל ב כ״ג:כ״א) וְהוּא הִכָּה אֶת אִישׁ מִצְרִי אִישׁ מַרְאֶה. הָכָא רָזָא דִקְרָא אֲתָא לְאוֹדָעָא, דִּי בְּכָל זִמְנָא דְיִשְׂרָאֵל חָבוּ אִיהוּ אִסְתַּלַּק וּמְנַע מִנַּיְיהוּ כָּל טָבִין וְכָל נְהוֹרִין דְּהֲווּ נְהִירִין לוֹן. הוּא הִכָּה אֶת אִישׁ מִצְרִי דָּא נְהוֹרָא דְּהַהוּא נְהוֹרָא דְּהֲוָה נָהִיר לוֹן לְיִשְׂרָאֵל. וּמָאן אִיהוּ משֶׁה. דִּכְתִיב, (שמות ב׳:י״ט) וַתֹּאמַרְנָה אִישׁ מִצְרִי הִצִּילָנוּ וְגו'. וְתַמָּן אִתְיְלִיד וְתַמָּן אִתְרַבֵּי וְתַמָּן אִסְתַּלִיק לִנְהוֹרָא עִלָּאָה.","אִישׁ מַרְאֶה כְּמָה דְאַתְּ אָמֵר (במדבר י״ב:ח׳) וּמַרְאֶה וְלֹא בְחִידוֹת. אִישׁ כְּמָא דְאַתְּ אָמֵר, (דברים ל״ג:א׳) אִישׁ הָאֱלהִים. כִּבְיָכוֹל בַּעֲלָהּ דְּהַהוּא מַרְאֶה כְּבוֹד ה'. דְּזָכָה לְאַנְהָגָא דַּרְגָּא דָא בְּכָל רְעוּתֵיהּ בְּאַרְעָא (כ\"א ב) מַה דְּלָא זָכֵי בַּר נָשׁ אָחֳרָא.","וּבְיַד הַמִּצְרִי חֲנִית. דָּא מַטֵּה הָאֱלֹהִים דְּהוּא אִתְמָסַר בִּידֵיהּ כְּמָא דְאַתְּ אָמֵר, (שמות י״ז:ט׳) וּמַטֵּה הָאֱלֹהִים בְּיָדִי. וְדָא אִיהוּ מַטֶּה דְּאִתְבְּרֵי עֶרֶב שַׁבָּת בֵּין הַשְּׁמָשׁוֹת וְחָקוּק בֵּיהּ שְׁמָא קַדִּישָׁא גְלִיפָא קַדִּישָׁא וּבְהַאי חָב בַּסֶּלַע כְּמָא דְאַתְּ אָמֵר, (במדבר כ׳:י״א) וַיַּךְ אֶת הַסֶּלַע בְּמַטֵּהוּ פַּעֲמָיִם. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, משֶׁה לָא יְהָבִית לָךְ מַטֶּה דִילִי לְהַאי, חַיֶּיךָ לֹא יְהֵא בְיָדְךָ מִכָּאן וּלְהָלְאָה.","מִיָּד (כ\"ח ב') וַיֵּרֶד אֵלָיו בַּשֵּׁבֶט בְּדִינָא קַשְׁיָא (שמואל ב כ״ג:כ״א) וַיִּגְזוֹל אֶת הַחֲנִית מִיַּד הַמִּצְרִי. דִּמְהַהִיא שַׁעֲתָא אִתְמְנַע מִנֵּיהּ וְלָא הֲוָה בִּידֵיהּ לְעָלְמִין. וַיַּהַרְגֵהוּ בַּחֲנִיתוֹ. עַל הַהוּא חוֹבָא דִּמְחָא בְּהַהוּא מַטֶּה, מֵת וְלָא עָאל לְאַרְעָא קַדִּישָׁא וְאִתְמְנַע נְהוֹרָא דָא מִיִּשְׂרָאֵל.","(שמואל ב כ״ג:י״ט) מִן הַשְּׁלשִׁים (ק\"ה ב) הֲכִי נִכְבָּד, אִלֵּין שְׁלשִׁים שָׁנָה עִלָּאִין דְּאִיהוּ נָטִיל מִנְהוֹן וְאִנְגִיד לְתַתָּא, וּמִנַּיְיהוּ אִיהוּ הֲוָה נָטִיל וְאִתְקָרֵב. וְאֶל הַשְּׁלשָׁה לֹא בָא, אִנּוּן הֲווּ אַתְיָאן לְגַבֵּיהּ וְיַהֲבֵי לֵיהּ בִּרְעוּתָא דְלִבָּא, וְאִיהוּ לָא הֲוֵי אָתֵי לְגַבֵּיהוֹן.","וְאַף עַל גַּב דְּלָא עָאל בְּמִנְיָינָא וְחוּשְׁבְּנָא (דחושבנא) דִּלְהוֹן, (שמואל ב כ״ג:כ״ג) וַיְשִימֵהוּ דָּוִד אֶל מִשְׁמַעְתּוֹ. דְּלָא אִתְפְּרַשׁ מִלּוּחָא דְלִבֵּיהּ לְעָלְמִין. לֵית פִּירוּדָא לְהוֹן לְעָלְמִין. דָּוִד שָׂם לֵיהּ לִבֵּיהּ וְאִיהוּ לָאו לְדָוִד. בְּגִין דְּתוּשְׁבְּחָן וְשִׁירִין וְרַחֲמִין דְּסִיהֲרָא עָבִיד לְשִׁמְשָׁא, אִיהִי מְשִׁיכַת לֵיהּ לְגַבָּהּ לְמֶהוֵי דִיּוּרֵיהּ בַּהֲדָהּ. וְדָא אִיהוּ וַיְשִׂימֵהוּ דָּוִד אֶל מִשְׁמַעְתּוֹ."],[[0,"","צג) \u0003ואיהו היכלא קדישא\u0004 וכו': והוא ההיכל הקדוש הסתום, שכל המדרגות נאספות וסתומות בו, ובגוף אותו ההיכל נמצאים כל העולמות, וכל הצבאות הקדושים נזונים ממנו, ונמצאים בקיומם."],[0,"","פירוש. קאי על רישא דעתיק יומין עצמו, ואומר, שהוא היכל קדוש וסתום, שכל המדרגות שבכל העולמות מקובצות ונעלמות בתוכו. ומבאר בזה איך נתהווה ונתאפשר הזווג הגדול הזה של גמר התיקון, שיהיה כולל בתוכו כל המדרגות והקומות שיצאו בזו אחר זו בשתא אלפי שני, ולחדשו ולהוציאו בבת אחת כנ\"ל."],[0,"","וז\"ש, כי האי רישא דעתיק יומין \u0003איהו היכלא קדישא סתימא, דכל דרגין כנישין וסתימין בגויה\u0004 כלומר, שבמשך ימי העולם, שהמדרגות הן בעליה וירידה, כי אחר שנתגלתה המדרגה, חוזרת ומסתלקת בסבת חטא התחתונים, הנה בעת הסתלקות המדרגה, אינה נאבדת ח\"ו, אלא עולה למעלה לרישא דעתיק, ונעלמת שם. ובדרך זה הוא הולך ומקבץ בתוכו כל קומה ומדרגה המתגלה בעולמות, והן באות שם בזו אחר זו, ומתקבצות ונעלמות בתוכו, עד הגיע העת של גמר התיקון, ואז מחדש אותן ומוציא אותן בבת אחת."],[0,"","וז\"ש, \u0003וכגופא דהאי היכלא\u0004 וכו': כי האי \u0003היכלא קדישא סתימא\u0004 הנקרא רישא דעתיק יומין הוא נבחן בכל משך שתא אלפי שני, בבחינת לא ידע ולא אתידע, כנ\"ל. וע\"כ הגם שהוא הולך ומקבץ לתוכו כלהו נהורין המתגלים בעולמות, לא נגלה משהו מהם עד גמר התיקון, ונמצאת כל מדרגה ומדרגה אחר העלמתה בסבת פגם התחתונים, כי עלתה לרישא דעתיק ונעלמה שם, כנ\"ל, \u0003דכל דרגין כנישין וסתימין בגויה\u0004. אמנם \u0003גופא\u0004 דעתיק יומין, דהיינו מפה דראש שלו ולמטה, הוא מלובש בכל ה' פרצופי אצילות, ומאיר על ידיהם לכל העולמות, ואין לך הארה קטנה או גדולה זולת הבאה מגופא דעתיק יומין."],[0,"","וז\"ש \u0003ובגופא דהאי היכלא קיימין כל עלמין וכל חיילין קדישין\u0004, כי הגוף דע\"י מתלבש בכל הפרצופין שבאבי\"ע, ונמצאים כל העולמות כולם מלבישים עליו והם קיימין עליו, שכל מציאותם והארתם ממנו באים. \u0003מניה אתזנו וקיימי על קיומיהון.\u0004 הן האורות הבאים להחיות העולמות הנק' מזונות, והן האורות הבאים למוחין דגדלות, כולם הם נמשכין מ\u0003גופא\u0004 דעתיק יומין. וכנגד השפע להחיות העולמות, אומר \u0003ומניה אתזנו\u0004 דהיינו מזונות. וכנגד המוחין דגדלות, אומר \u0003וקיימי על קיומיהון\u0004, כי המוחין מעמידים לכל פרצוף בשיעור הגובה המיוחס לו."],[1,"","צד) \u0003הוא הכה את\u0004 וגו': הוא הכה את שני אריאל מואב. שני מקדשים היו קיימים ונזונים בשבילו, מקדש ראשון ומקדש שני. כיון שהוא נסתלק, נמנעה ההמשכה שהיתה נמשכת למעלה. ונחשב, שכביכול הוא הכה אותם, והחריב אותם, וכלה אותם."],[1,"","פירוש. אחר שהארת גוף דעתיק יומין נסתלקה, השפע שנמשך ממנו מלמעלה נפסק, וע\"כ נחרבו \u0003תרין בתי מקדשין ונמצא כביכול הוא הכה לון וחריב לון ושצי לון\u0004, הנה הדברים האלו עמוקים מאד, כי משמע שבסבת גילוי קומת הזווג הגדול דרישא דעתיק יומין נסתלקה הארת הגוף דע\"י מכל העולמות, כי ע\"כ נחרבו המקדשין, וכל נהורין דהוו נהירין לישראל, כלם אתחשכו, כמ\"ש לפנינו. והדברים נפלאים ביותר."],[1,"","והענין הוא, כי כל התיקונים סובבים רק על בחי\"ד, הנקראת מלכות ונוקבא דז\"א, או פרצוף ב\"ן, כי מכחה היתה שבירת הכלים, וכן חטא דעצה\"ד, שכל עבודת הצדיקים בשתא אלפי שני, הוא לחזור ולתקנה כמו שהיתה מטרם שביה\"כ ומטרם החטא של אדה\"ר, שאח\"ז יתגלה הזווג הגדול הנ\"ל, דרישא דע\"י, המבער את הקליפות והס\"א לנצח, בסוד בלע המות לנצח, וכו' (ישעיה כ\"ה). וכיון שהב\"ן כבר נתתקן לנצח, ואינו צריך עוד לשום תיקונים, הנה אז ישוב הב\"ן להיות ס\"ג, ובזה נגמר כל התיקון."],[1,"","אמנם בינתים, דהיינו אחר הזווג הגדול דעתיק יומין, ומטרם שיבת הב\"ן להיות ס\"ג, יש ענין הסתלקות הארת גופא דעתיק, שבסבת הסתלקותו חרבו ב' בתי מקדשים, דהיינו ב' בחינות המוחין המאירות בב' מקדשין, שהן מוחין דאו\"א עלאין שמאירים בבית ראשון, והמוחין דישסו\"ת שהם מאירים בבית שני. וכלהו נהורין דישראל נחרבו ונסתלקו, כמ\"ש לפנינו, אשר כל אלו החורבנות הם התיקונים האחרונים המשיבים את הב\"ן להיות ס\"ג, שהוא כל הנרצה."],[1,"","ואז יחזרו ויבנו ב' המקדשין בידי שמים, מבחינת המסך דבחי\"ב שהיא בינה דהיינו ע\"ד המסך דס\"ג דא\"ק שמלפני צמצום ב', הנבחן שהוא נקי מכל צמצום, אלא רק מידי שמים, בסוד כי חפץ חסד הוא (סוף מיכה), ואז ב' המקדשין יתקיימו לנצח ויהיה אור הלבנה כאור החמה (ישעיה ל'). דהיינו בינה עלאה, שהיא עתה האור של ז\"א הנק' חמה. ואור החמה יהיה שבעתים כאור שבעת הימים, דהיינו כז\"ת דעתיק יומין, שמהן נמשך האור לאו\"א שהאצילו ז' ימי בראשית. כי ז\"א שהוא החמה ישוב להיות ע\"ב, שבתוכה האור דגופא דעתיק."],[1,"","וטעם הסתלקותו של גופא דעתיק מטרם אלו התיקונים, הוא, כי אין יותר בע\"ס אלא ב' נוקבין, שהן בינה ומלכות, הנק' ס\"ג וב\"ן. ונמצא אחר הזווג הגדול דע\"י שנתבטלה בחי' הב\"ן, הנה נתבטלה עמה גם בחינת מסך דס\"ג. והיה זה מטעם התיקון הנעשה בגופא דעתיק לשתף הבינה והמלכות זו בזו, בסוד שיתוף מדת הדין במדת הרחמים. (כנ\"ל אות ד' ד\"ה אדם ע\"ש) שמכח השיתוף הזה האציל לפרצוף א\"א דאצילות, וכלהו פרצופי אבי\"ע יצאו ונתקיימו רק במלכות הזו המשותפת והממותקת במדת הרחמים שהיא בינה. ולפיכך כיון שנתבטלה בחינת המסך דב\"ן, נתבטל עמה יחד המסך דבחי\"ב שהוא ס\"ג, בהיותם כרוכים יחד כאחד, וכיון שנתבטלו בחינת הנוקבא והמסך, א\"כ נפסק הזווג עם האור העליון, וע\"כ כל הארת הגוף דעתיק, שהיתה על המסך המשותף במדת הרחמים, נסתלקה לגמרי, וממילא נחרבו כל המאורות שממנו ולמטה, הנמשכים מגופא דעתיק."],[1,"","וזה אמרו \u0003הוא הכה את שני אריאל מואב, תרין מקדשין הוו קיימין בגיניה\u0004 וכו' \u0003כיון דאיהו אסתלק, נגידו דהוה נגיד מלעילא אתמנע\u0004, דהיינו כמבואר, כי מתוך שנתבטל הב\"ן מכח הזווג הגדול דע\"י, נתבטל עמו גם הס\"ג, דהיינו גם המסך דבחי\"ב עצמו, וכיון שאין המסך מוכשר לזווג, נפסק ע\"כ האור העליון, שהוא \u0003נגידו דהוה נגיד מלעילא אתמנע\u0004, נגידו, פירושו המשכה והתפשטות האור העליון מעילא לתתא. והוא נפסק מטעם ביטול המסך, כמבואר. הרי, שמסבת הזווג הגדול שנעשה ברישא דע\"י, נפסקה ונתבטלה השפעת האור מגופא דעתיק יומין, כי הזווג של הראש ביטל המסך דב\"ן, וכיון שעד עתה היה המסך דב\"ן מחובר עם המסך דס\"ג בגופא דעתיק יומין כאחד, לכן נתבטל גם המסך דס\"ג, וכיון שאין מסך לזווג דהכאה אין מקום לאור העליון להשפיע שם. כנודע."],[2,"","צה) \u0003וכרסיא קדישא נפלת\u0004 וכו': והכסא הקדוש, שהוא המלכות, נפל. ז\"ש \u0003ואני\u0004 בתוך הגולה, היינו אותה מדרגה הנקראת \u0003אני\u0004, שהיא מלכות, היא בתוך הגולה. למה. על נהר כבר, שפירושו, על הנהר הנמשך ויוצא שמכבר, ועתה כלו מימיו ומבועיו, ואינו נמשך כבתחילה. ז\"ש, ונהר יחרב ויבש, \u0003יחרב\u0004 בבית ראשון, \u0003ויבש\u0004 בבית שני. ומשום זה כתוב, הוא הכה את שני אריאל מואב. \u0003מואב\u0004 פירושו, שהם מהאב שבשמים, ונחרבו וכלו בשבילו, וכל האורות שהיו מאירים לישראל, כולם נחשכו."],[2,"","פירוש. \u0003כרסייא\u0004 מורה על מיתוק המלכות בבינה, שה\"ס כסא הרחמים, שעל ידו מושפעין כל המוחין בשתא אלפי שני, לכלהו פרצופי אבי\"ע. וז\"ש \u0003כרסייא קדישא נפלת\u0004 שמתוך ביטול המסך דב\"ן, נתבטל ונפל גם המסך דס\"ג שה\"ס \u0003כרסייא\u0004, הה\"ד \u0003ואני בתוך הגולה, ההוא דרגא דאקרי אני, הוא בתוך הגולה\u0004. אני ה\"ס מלכות דעליון הנעשה כתר לתחתון, כי אותיות \u0003אני\u0004, הן אותיות \u0003אי\"ן\u0004 שהוא שם הכתר."],[2,"","ונודע שמלכות דעליון זו היא כל הקשר שבין הפרצופין, שכל עליון עושה הזווג על המלכות שלו המוציאה או\"ח המלביש האו\"י דעליון, ואח\"ז יורדת המלכות דעליון, בסוד ע\"ס דאו\"ח שלה, שבתוכם קומת האו\"י, ומתלבשת בתחתון. ונמצא עתה אשר \u0003ההוא דרגא דאקרי אני, הוא בתוך הגולה\u0004, כי נתבטל ממנה הזווג עם האור העליון, ונפסק האור העליון מכלהו פרצופין, וזה אמרו \u0003אמאי, על נהר כבר, על נהר דנגיד ונפיק, דפסיק מימוי ומבועוי\u0004, כי בהיותה מתוקנת במסך, היא נק' נהר דנגיד ונפיק, כלומר, שהאור העליון נמשך על ידה לתחתון, כמו מימי נהר הנמשכים והולכים בלי הפסק."],[2,"","אבל עתה כשנתבטל המסך, נבחנת בחינת הנהר הזה בשם \u0003נהר כבר\u0004, שמכבר היה נהר ולא עתה, כי עתה \u0003פסיק מימוי ומבועוי\u0004, מימוי, היינו האור העליון שהיה נמשך בו. ומבועוי, היינו המסך, שבהיותו מתוקן בה היה נבחן למבוע, כי השפע היה קשור בו ונובע ממנו בלי הפסק. ועתה נפסק כל זה \u0003ולא אנגיד כד בקדמיתא\u0004, שאינו נמשך ממנו האור העליון כמו מקודם. \u0003הה\"ד ונהר יחרב ויבש, יחרב בבית ראשון, ויבש בבית שני\u0004, אמא נק' \u0003בית ראשון\u0004 והתבונה נק' \u0003בית שני\u0004. ועל בית ראשון יאמר \u0003יחרב\u0004, כי בו נפסק הזווג, משום שהמבוע שהוא המסך נחרב. וכיון שאין זווג באמא עלאה, נמצאת התבונה יבשה לגמרי, וע\"כ על התבונה אומר, \u0003ויבש\u0004."],[2,"","וז\"ש, \u0003מואב, דהוו מאב דבשמיא\u0004 וכו': כי שורש המוחין דב' המקדשין הוא מאבא שהוא האב שבשמים, כלומר המאיר לז\"א הנק' שמים, שאורותיו העלו זו\"ן לישסו\"ת במקדש שני, ולאו\"א עלאין במקדש ראשון. שהם נחרבו עתה ונחשכה, \u0003בגיניה\u0004 היינו בגין הפסקת השפע דגופא דעתיק יומין, \u0003וכל נהורין דהוו נהירין לישראל כלהו אתחשכו\u0004, כלומר, לא רק המוחין הגדולים דב' מקדשין נחשכו, אלא כלהו נהורין שהיו מאירים לישראל נחרבו, דהיינו אפילו האורות דו\"ק ואורות דבי\"ע."],[3,"","צו) \u0003ותו, הוא ירד\u0004 וכו': ועוד. הוא ירד והכה את הארי. בזמנים הראשונים, כשהנהר הזה היה מושך מימיו למטה, היו ישראל נמצאים בשלימות, כי היו זובחים זבחים וקרבנות לכפר על נפשותיהם, ואז היתה יורדת מלמעלה דמות של אריה אחד, והיו רואים אותו על המזבח רובץ על טרפו, אוכל הקרבנות כאיש גבור, וכל הכלבים, דהיינו המקטריגים, היו נחבאים מלפניו, ולא יצאו לחוץ. לקטרג."],[3,"","ביאור הדברים, האש של גבוה שהיה רבוץ על המזבח בבית המקדש, אמרו ז\"ל (יומא כא:) שהיה רבוץ כ\u0003אריה\u0004, שהיה שורף את הקרבנות שב\"י מקריבים עליו, וז\"ש \u0003בזמנין קדמאין, כד האי נהר הוה משיך מימוי לתתא, הוו קיימין ישראל בשלימו\u0004, כי מטרם שנתבטלה הארת עתיק, והאורות העליונים, היו נמשכים לישראל, כנהר שמימיו נמשכים ממעלה למטה בלי הפסק, הנה אז היו ישראל בכל שלימותם."],[3,"דדבחין דבחין וקרבנין לכפרא על נפשייהו",", שעם הקרבנות שהיו זובחים, היו מעלים מ\"ן לזווג העליון שעל המסך, ונמשכו מיין דוכרין שהם המוחין, שעי\"ז נתקרבו בדבקות גדולה לאביהם שבשמים, וכל הקלי' ברחו ונתרחקו מהם, שה\"ס \u0003לכפרא על נפשייהו\u0004, כי התרחקות הקליפות מעל הנפשות נבחנת \u0003לכפרה\u0004, בדמיון בגד מוכתם ומלוכלך בכתמים, שע\"י רחיצה מעבירים ומכפרים כל הכתמים מהבגד."],[3,"","וע\"כ נק' \u0003קרבנות\u0004, שמקריבין את ישראל לאביהם שבשמים, וכיון שהיו על שלימותם והיו מעלים מ\"ן רק לעשות נ\"ר ליוצרם, היה המ\"ן עולה עד הבינה, ששם אור החסדים והשפעה בסוד \u0003אריה\u0004, שהוא שם החסד, ונבחן שהאריה של הבינה קבל המע\"ט והמ\"ן שהעלו בני ישראל. וראו איך המ\"ן שלהם הוא בחינת טרף לבינה עלאה, ואור החסדים של בינה נמשך בסוד או\"י על המ\"ן, והיה או\"י רובץ על הטרף, דהיינו המ\"ן, ואוכל אותו."],[3,"","וענין אכילת האריה את הקרבן, הוא, כי עקרו של הקרבן, הוא המ\"ן העולה לחיזוק המסך ולהעלאת או\"ח כנ\"ל. ומכיון ששיעור גודל או\"י נמדד במדת האו\"ח שעולה מעל המסך, הרי נבחן, שהאו\"י נזון מהמ\"ן ומתגדל ומתקיים על ידו, בדוגמת בעל החיים שמתקיים וגדל ע\"י המזונות שאוכל. וכן כל חיותו של החי הגשמי תלויה במזונות שאוכל, שבהפסקתם הוא מת, כן האור העליון תלוי באו\"ח העולה מהמסך, ובהפסק האו\"ח הוא מתבטל מתחתון."],[3,"","וז\"ש \u0003נחית מלעילא דיוקנא דחד אריה\u0004 דהיינו, אור הבינה הנמשך ממעלה למטה בסוד או\"י, הוא \u0003בדיוקנא דאריה\u0004, דהיינו בצורת השפעה כטבע הבינה. \u0003והוו חמאן ליה ע\"ג מדבחא רביץ על טרפיה\u0004 שראו את האו\"י שהוא מתלבש ורובץ תוך האו\"ח העולה מהקרבן, שהוא טרפו ומזונותיו כנ\"ל."],[3,"אכיל קרבנין כגבר תקיף",", שהוא אוכל וגדל ע\"י הקרבנות כאיש גבור, כי לפי שהיו ישראל בשלימות, היתה מדת ההשפעה, שהיא העלאת מ\"ן ואו\"ח, בגבורה גדולה ממטה למעלה, כי קומת האו\"ח נמדדת במדת גדלה של הכאת המסך ברתת וזיע הדוחה האור העליון ממטה למעלה. וכמדת גדלות קומתו של עליית האו\"ח, כן קומת האו\"י הנמשכת בו. וע\"כ אם קומת האו\"ח עולה בגבורה גדולה, נבחן, \u0003שהאריה אכיל קרבנין כגבר תקיף\u0004 בקומה זקופה בגבורה, כי ע\"י הגבורה מתגדלת ועולה קומתו. (עי' כל זה בספרי פתיחה לחכמת הקבלה דף ד' אות י\"ד)."],[3,"","וזהו אמרו \u0003וכל כלבין הוו מתטמרין מקמיה ולא נפקי לבר\u0004, כי הקליפה של הקבלה לעצמה, מכונה בשם כלב. כמ\"ש בזוהר על הכתוב, ולעלוקה שתי בנות הב הב (משלי ל'), דצווחין ככלבא ואמרין הב לן עותרא דעלמא הדין, הב לן עותרא דעלמא דאתי. והיא הקליפה החזקה ביותר, ואחיזתה מתחזקת ביותר כנגד אור היחידה. בסו\"ה הצילה מחרב נפשי מיד כלב יחידתי (תהלים כ\"ב), והיא הלעומת של האריה \u0003דאכיל קרבנין\u0004 הנזכר."],[3,"","כי כמו שהאריה, שה\"ס החסד, הוא כולו להשפיע ולא לקבל כלום, כמ\"ש חז\"ל במדת החסיד, שלי שלך ושלך שלך (אבות פ\"ה), כן קליפת הכלב היא כולה לקבל ולא להשפיע כלום. כמ\"ש בחסידי אומות העולם, שכל חסד דעבדין, לגרמייהו הוא דעבדין (ב\"ב י':). כי הם קשורין בקליפת כלב."],[3,"","וז\"ש, כי בזמן שהיו ישראל שלמים, וזכו לבחינת \u0003אריה, אכיל קרבנין\u0004, הנה אז \u0003כל כלבין הוו מתטמרין מקמיה ולא נפקי לבר\u0004, כי העלו מ\"ן בגבורה גדולה, שבזה נתנו כח למסך שבמלכות לדחות האור העליון ממנו ולמעלה בגבורה גדולה, שמתוך כך נמצאה מדת האו\"ח שהיתה בקומה גבוהה מאד, בסוד \u0003אכיל קרבנין כגבר תקיף\u0004, ולפיכך, גם אלו הקליפות הקשות שהן הכלבים, כולן ברחו ונסתתרו מפחד גבורתו של האריה ההוא, ולא יצאו ממחבואן לחוץ."],[4,"","צז) \u0003כיון דגרמו חובין\u0004 וכו': כיון שגרמו העונות, הוא ירד לתוך המדרגות שלמטה והרג אותו האריה. כי משום שלא רצה לתת לו טרפו כבתחילה, נחשב, כביכול, שהרג אותו, ע\"כ ודאי, הוא הכה את הארי. \u0003לתוך הבור\u0004, היינו לעיניו של צד האחר הרע. כיון שראה זאת אותו צד האחר, התגבר ושלח כלב אחד לאכול את הקרבנות, מעל המזבח, במקום האריה. ואותו האריה מה שמו. אוריאל שמו, שפניו פני אריה. ומה שמו של אותו הכלב. בלאדן שמו. כי בלאדן הוא אותיות בלאדם, שה\u0003ם'\u0004 מתחלפת ב\u0003ן'\u0004. כי אין הוא בכלל אדם, אלא כלב, ופני כלב."],[4,"","פירוש. כי מתוך שנתבטלה בחינת המסכים מב\"ן ומס\"ג כנ\"ל, גם ישראל לתתא לא יכלו להעלות עוד מ\"ן, שהיא מזונותיו של אריה (כנ\"ל בדיבור הסמוך). ונפסק הזווג, והאור העליון שהוא, בחי' \u0003האריה\u0004 נסתלק, ונבחן \u0003כביכול\u0004 כאלו \u0003קטיל\u0004 לההוא \u0003אריה\u0004. כי הוא נתעלה למעלה לשורשו ונעלם מהתחתונים."],[4,"","וז\"ש, \u0003לתוך הבור, לעינהא דסטרא אחרא בישא\u0004: כי שורש הקבלה לעצמו הוא, בעינים, בסוד העין רואה והלב חומד (רש\"י סוף פ' שלח). ובחי' הקבלה הזו נק' \u0003בור\u0004, כי הוא בור ריק ואין בו מים (בראשית ל\"ז), שאין האור העליון נמשך לשם, בסוד אין אני והוא יכולים לדור במדור אחד (סוטה ה')."],[4,"","וז\"ש \u0003הכה את הארי לתוך הבור לעינהא דס\"א בישא\u0004 כי הכאת הארי היתה לעיניהם הרעות דס\"א הנק' בור, שהן בורות נשברות אשר לא יכילו המים. והם יצאו עתה ונגלו ממחבואיהם בשליטה גדולה. \u0003ושדרת לחד כלבא למיכל קרבנין\u0004: כי הלעומת דאריה \u0003אכיל קרבנין\u0004, הוא הכלב הצועק תמיד הב הב, כנ\"ל."],[4,"","וז\"ש, \u0003שמיה דההוא אריה אוריאל, דאנפוי אנפי אריה\u0004: סוד שם \u0003א\"ל\u0004 הוא החסד, שה\"ס ימין, והאריה ההוא, שהוא אור החסד כנ\"ל, נק' \u0003אורי-אל\u0004, כלומר ה\u0003אור\u0004 הנמשך מהשם \u0003א\"ל\u0004. ופניו אל הימין, שה\"ס השפעה, בסו\"ה ופני אריה אל הימין לארבעתם (יחזקאל א')."],[4,"","וז\"ש, \u0003שמיה דההוא כלבא, בלאדן שמיה דלאו איהו בכלל אדם, אלא כלבא\u0004: כי הז\"א נק' אדם בעת שיש בו מוחין מהבינה, שה\"ס \u0003אד\"ם\u0004 בגי' \u0003מ\"ה\u0004. וסוד הבינה הוא השפעה כנ\"ל, שע\"כ אמרו ז\"ל אתם קרואים \u0003אדם\u0004 (יבמות ס\"א. ) ולא אומות העולם קרואים \u0003אדם\u0004, משום דכל חסד דעבדין, לגרמייהו הוא דעבדין (ב\"ב י:). וע\"כ נקרא \u0003בלאדן\u0004 שהם נוטריקון \u0003בל-אדם\u0004 כי מ' מתחלפת בנ'."],[5,"","צח) \u0003ביום השלג ביומא\u0004 וכו': ביום השלג. היינו, ביום שגרמו העונות, שהדין נדון למעלה מן בית הדין העליון. וע\"כ כתוב, לא תירא לביתה משלג, שזה דין העליון, המכונה שלג. למה אינה מתיראת. משום שכל ביתה לבוש שנים, ע\"כ יכלה לסבול אש חזקה. עד כאן הוא סוד הכתוב."],[5,"","פירוש. הדינין שכנגד הזכר נק' \u0003שלג\u0004 וע\"כ נבחנים שנמשכים מ\u0003בי דינא עלאה\u0004. ודינין אלו קשים מאד ברישא אלא שנייחים בסיפא, כי אינם נמתקים רק בסיפא שהוא הנוקבא. וכנגד הדינין הללו אמרה הנוקבא, סמכוני באשישות (שה\"ש ב'), הרומז לב' אשיות, אש של מעלה שהיא הבינה, ואש שלה עצמה."],[5,"","ואז אחר שיש לה ב' אשיות אלו, היא ממתקת את הדינין הקרים ד\u0003שלג\u0004, כי האש שלה מוציאה צינתם. וז\"ש \u0003לא תירא לביתה משלג דא דינא עלאה\u0004, דהיינו הדינין הקשים דדכורא הנק' דינא עלאה, \u0003אמאי, בגין דכל ביתה לבוש שנים\u0004, שנים, ה\"ס ב' אשיות הנ\"ל, ומשום שביתה לבוש בב' אשיות, ע\"כ \u0003לא תירא לביתה משלג\u0004, ואדרבה, השלג מתמתק תוך האשיות שלה,"],[5,"","וזה אמרו \u0003ויכיל למיסבל אשא תקיפא\u0004, שהשלג הזה עוזר לה לסבול את האשיות שלה. ומשמיענו שעתה אחר שנתבטלו המסכים והזווגים דב\"ן ודס\"ג, ונתבטלו ב' האשיות הללו, חזרו הדינין דשלג לתוקפם. \u0003ע\"כ רזא דקרא, מה כתיב בתריה\u0004 וכו': רומזים בזה, כי המובא עד כאן, נגלה תיכף ומיד אחר הזווג דע\"י, אבל המובא בכתוב אח\"ז, הוא מסובב ובא לאחר מכאן."],[6,"","צט) \u0003מה כתיב בתריה\u0004 וכו': מה כתוב אחריו. והוא הכה את איש מצרי איש מראה. כאן בא סוד הכתוב להודיע, שבכל פעם שחטאו ישראל, הוא נסתלק, ומנע מהם כל הטוב וכל האורות שהיו מאירים להם. הוא הכה את איש מצרי, זהו אור, דהיינו אותו האור שהיה מאיר להם לישראל, ומי הוא. הוא משה. שכתוב עליו ותאמרנה איש מצרי הצילנו וגו'. כי שם במצרים נולד, ושם גדל, ושם נתעלה לאור העליון."],[6,"","פירוש. אין כוונת הכתוב על \u0003איש\u0004 ממש, אלא על \u0003נהורא\u0004, כי ביטל והעלים את האור, ונבחן כאלו קטיל יתיה. וז\"ש, \u0003דההוא נהורא דהוה נהיר לון לישראל ומאן איהו, משה\u0004: כלומר, שהוא ביטל את האור הגדול ההוא של הארת \u0003משה\u0004 אל ישראל. ומכנהו \u0003איש מצרי\u0004, משום כי במצרים נולד, ושם נגדל, דכתיב ויגדל משה ויצא אל אחיו, וכו' (שמות ב') ושם זכה לאור העליון, לגאולת ישראל ממצרים."],[7,"","ק) \u0003איש מראה כד\"א\u0004 וכו': איש \u0003מראה\u0004. היינו כמו שאתה אומר, ומראה ולא בחידות. \u0003איש\u0004 הוא כמו שאתה אומר, איש האלקים כביכול, בעלה של אותו מראה כבוד ה'. שהיא מלכות. כי זכה להנהיג מדרגה זו בארץ בכל חפצו, מה שלא זכה לזה איש אחר."],[7,"","פירוש. כי ההפרש בין משה לשאר הנביאים, כי משה היה מרכבה לז\"א, והיה בונה ומשפיע מהז\"א אל הנוקבא, משא\"כ שאר הנביאים היו מרכבה לנוקבא, והם מושפעים מן הנוקבא. וז\"ש \u0003איש האלהים, כביכול, בעלה דההוא מראה\u0004, שהוא הנוקבא, שהיא נק' \u0003כבוד ה'\u0004, ולמה נבחן לבעלה דשכינתא, הוא משום \u0003דזכה לאנהגא דרגא דא\u0004, כי הוא היה מרכבה לז\"א, והיה בונה ומשפיע ומנהיג את דרגא דא, שהיא הנוקבא, \u0003מה דלא זכי בר נש אחרא\u0004, כי יתר כל הנביאים היו מרכבה לנוקבא, והנוקבא היתה משפעת אליהם, ונמצאים הם תחתונים ממנה, ומונהגים על ידיה. הרי ששום איש בעולם לא זכה למדתו של משה."],[8,"","קא) \u0003וביד המצרי חנית\u0004: זו היא מטה האלקים, שהוא נמסר בידו. כמו שאתה אומר, \u0003ומטה האלקים בידי\u0004, וזהו המטה שנברא ערב שבת בין השמשות, וחקוקה בו חקיקה קדושה, השם הקדוש. ובמטה הזה חטא בסלע. כש\"א ויך את הסלע במטהו פעמים, אמר לו הקב\"ה, משה, לא לזה נתתי לך את המטה שלי, חייך, לא יהיה עוד בידך מכאן ולהלאה."],[8,"","ביאור הדברים, בין השמשות, ה\"ס מיתוקה הגדול של המלכות בבינה, עד שאין להבחין בה, אם היא מלכות, או בינה. כי בשבת עולה המלכות לאו\"א, ונעשית בינה, וב\u0003ע\"ש בין השמשות\u0004, אינה עוד בינה ממש, אבל גם אינה ניכרת לבחינת מלכות. וז\"ס עשרת הדברים שנבראו בין השמשות, שאז אין היכר בהם מאין מוצאם, אם מבינה אם ממלכות. כי גם בנוקבא עצמה אין אז היכר."],[8,"","וז\"ס המטה שנברא ע\"ש בין השמשות, ומטעם זה \u0003וחקוק ביה שמא קדישא גליפא קדישא\u0004, חקיקה \u0003דשמא קדישא\u0004, מורה על בחינת בינה, שממנה נמשכה הקדושה. \u0003וגליפא קדישא\u0004, מורה על המלכות שהיא רק גליפא לקבל את \u0003שמא קדישא\u0004. וב' החקיקות הללו היו כלולות במטה כמו בחינה אחת בלי היכר כנ\"ל, מטעם שהוא נברא \u0003ע\"ש בין השמשות\u0004. וע\"כ היה כחו יפה להמשיך להם לישראל כלהו נהורין וכל הנסים והנפלאות, שהם סוד המשכת אורות הבינה במלכות. ועל ידו זכה משה לבינה עלאה, ולבחי' איש האלהים בסוד כלת משה. והוא הנקרא \u0003מטה האלהים\u0004 על שם הבינה. והיא הנקראת חנית בסוד \u0003ו'\u0004 דהוי\"ה המזדווג עם ה\"ת."],[8,"","והנה המלכות נקראת \u0003צור\u0004, ובסוד הבינה נקראת \u0003סלע\u0004. והזווג הפנימי של זו\"ן, דהיינו בעת שעולה לאו\"א, והנוקבא משמשת במאנין דאמא, (כנ\"ל אות י\"ז), מכונה הזווג דהכאה בשם דיבור. והזווג החיצון של זו\"ן דהיינו במקומם עצמם מכונה בשם זווג דהכאה. וז\"ס שבפרשת בשלח (שמות י\"ז) נאמר לו למשה \u0003והכית בצור\u0004 ויצאו ממנו מים וכו'. כי ה\u0003צור\u0004 ה\"ס מלכות שבה נוהגת הכאה. אבל בפרשת חוקת (במדבר כ') נאמר \u0003ודברתם אל הסלע\u0004 וכו', כי הסלע שהוא במקום בינה, מכונה הזווג בשם דיבור. וז\"ס חטאו של משה, כי שמש במטה שלו \u0003פעמיים\u0004, כי מלבד שהכה בו בצור, הכה גם ב\u0003סלע\u0004. והיינו \u0003פעמיים\u0004. ונמצא \u0003חב בסלע\u0004 כי בו אינה נוהגת הכאה אלא \u0003דיבור\u0004. (כמ\"ש בזהר תצא אות ע\"ו)."],[8,"","וז\"ש \u0003ובהאי חב בסלע\u0004, כי מתוך שמטה האלהים לא היה בו היכר אם הוא שייך למלכות או לבינה כנ\"ל, ע\"כ יצא לו לשמש עמו גם בסלע. \u0003כד\"א ויך את הסלע במטהו פעמים\u0004 דהיינו \u0003בצור ובסלע\u0004. כנ\"ל. \u0003אמר לו קב\"ה, משה לא יהבית לך מטה דילי להאי\u0004: לא נתתי לך המטה שלי שתשמש עמו גם בבחינת הסלע.."],[9,"","קב) \u0003מיד וירד אליו\u0004 וגו': מיד וירד אליו בשבט. היינו בדין קשה. ויגזול את החנית מיד המצרי. היינו כי מאותה שעה נמנע ממנו המטה, שהוא החנית, ולא היה עוד בידו לעולם. ויהרגהו בחניתו. היינו, שמשום אותו החטא שהכה את הסלע במטה ההוא, הוא מת, ולא נכנס לארץ הקדושה. ואור זה נמנע מישראל."],[9,"","להבין הדברים, יש לזכור כאן כל המתבאר לעיל (אות צ\"ד ד\"ה וטעם הסתלקותו), כי מכח הזווג הגדול דעתיק יומין לא היה צריך להתבטל רק הב\"ן לבדו, ולא כלל הס\"ג, ואז היה תיכף הב\"ן עולה ונעשה ס\"ג לנצחיות, אלא מתוך שהס\"ג והב\"ן היו דבוקים יחדיו נתבטל גם הס\"ג עם הב\"ן, שע\"כ נחרבו בינתיים המקדשין וכו' ע\"ש. ומאותו הטעם נתבטלה גם הארת משה לבני ישראל, כי הוא עוד חטא ביותר בדבר החיבור של בחינת הב\"ן עם הס\"ג ע\"י הכאת הסלע, כנ\"ל."],[9,"","ולכן \u0003וירד אליו בשבט בדינא קשיא\u0004 כי ביטול הס\"ג נעשה בדינא קשיא, כי באמת אין לו שום חיבור עם הב\"ן, וביטול הב\"ן אינו נוגע אליו כלל. כי ז\"ס הכתוב יודע כמביא למעלה בסבך עץ קרדומות, ועתה פתוחיה יחד בכשיל וכילפות יהלומון (תהלים ע\"ד), כי מחמת העלאת והמתקת המלכות ועליתה אל הבינה, נעשה עתה כמו מביא למעלה בסבך עץ קרדומות, כי גם הס\"ג נתבטל בגלל עליה זו. דהיינו בכשיל וכילפות יהלומון."],[9,"","וז\"ש \u0003ויגזול את החנית מיד המצרי דמההיא שעתא אתמנע מניה ולא הוה בידיה לעלמין\u0004, כי החנית היה שייך באמת לב\"ן כנ\"ל. וע\"כ נתבטלה הארתו \u0003לעלמין\u0004, כי הב\"ן עצמו נתחדש אח\"כ ונעשה ס\"ג לנצחיות, וע\"כ אין עוד ענין לשימוש המטה בבחי' הכאה. וז\"ש \u0003ויהרגהו בחניתו, על ההוא חובא דמחא בההוא מטה מת\u0004. כי לולא נזהר לשמש עמו רק ב\u0003צור\u0004 ולא ב\u0003סלע\u0004, לא היתה בחינת הס\"ג מתבטלת עם הב\"ן, ולא היה \u0003מת\u0004 אלא עולה תכף לבחינת הס\"ג. וז\"ש \u0003ולא עאל לארעא קדישא\u0004, כי ארץ ישראל ה\"ס עלית הב\"ן אל הס\"ג, וע\"כ נק' \u0003ארעא קדישא\u0004, כי המוחין דבינה המאירים אז בה נקראים \u0003קדש\u0004. ובטרם גמר התיקון, שיש עליות וירידות, ע\"כ יש חורבנות וגלויות, אבל בגמר התיקון ישאר הב\"ן בס\"ג לנצחיות שה\"ס ארץ ישראל, כמבואר. ולא תהיה יותר שום גלות."],[10,"","קג) \u0003מן השלשים הכי\u0004 וגו': מן השלשים הכי נכבד, אלו הם שלשים שנה עליונות, שהוא היה לוקח מהן והמשיך למטה, ומהם, הוא היה לוקח והתקרב. ואל השלשה לא בא. הם היו באים אליו ונותנים לו בחפץ לב, והוא לא בא אליהם."],[10,"","פירוש. ג\"ר שהן חב\"ד, נקראות \u0003שלשים\u0004. דהיינו ג' ספירות שכל אחת נכללת מעשר, שהן כלל המוחין המאירים בשתא אלפי שני, ונשמת \u0003בניהו\u0004 הבאה מהזווג הגדול דעתיק יומין, המקבץ מכל אלו הזווגים דשתא אלפי שני בסוד, \u0003רב פעלים ומקבצאל\u0004 בקומה אחת, שהיא בניהו בן יהוידע כנ\"ל. נמצא שהוא מקבל ומתכבד מכל אלו שלשים השנה העלאין."],[10,"","וז\"ש \u0003דאיהו נטיל מנהון ואנגיד לתתא\u0004, שהוא נוטל מהמוחין ד\u0003שלשים\u0004 שנה, ונמשכים אל הנשמה שלו \u0003לתתא\u0004, בסוף כולם. \u0003ומנייהו איהו הוה נטיל ואתקרב\u0004, כי כל הקומה שלו היא רק ממה שלקח וקיבץ מהזווגים שלהם שבאו בזה אחר זה, כנ\"ל. ועכ\"ז \u0003ואל השלשה לא בא אינון הוו אתיאן לגביה, ויהבי ליה ברעותא דלבא, ואיהו לא הוי אתי לגביהון\u0004, כי אע\"פ שהם נתנו לו כל מעלתו הנשגבה \u0003ברעותא דלבא\u0004, עכ\"ז הוא לא יכול לבא אצלם אח\"ז ולקבל עוד מהם. והוא מהטעם הנ\"ל, כי מתוך ביטול המסך דב\"ן נתבטל לו ג\"כ מסך דס\"ג, ונשאר לבלי מסך, וע\"כ לא היה יכול לבא אצלם להעלות מ\"ן ולקבל מהם עוד."],[11,"","קד) \u0003ואע\"ג דלא עאל\u0004 וכו': ואע\"פ שלא נכנס במנין וחשבון שלהם, עם כל זה, וישימהו דוד אל משמעתו, שלא נפרד מלוח לבו לעולם, כי אין להם פירוד לעולם. דוד שם לבו אליו, והוא לא שם לבו לדוד. משום שהתשבחות והשירים והחסד, שהלבנה עושה לשמש, היא מושכת בזה אליה, שיהיה מגורו עמו. וזה הוא, וישימהו דוד אל משמעתו."],[11,"","פירוש. דוד הוא בחינת המלכות, שהיא הרגל הרביעית של ג\"ר. ואומר, דאע\"ג שלא יכול לבא אל שלשים השנה העלאין שהן ג\"ר, מ\"מ \u0003וישימהו דוד אל משמעתו\u0004, שנתדבק בו ולא זז מלוח לבו \u0003לעלמין\u0004. והוא מטעם שכל בחינת השלמות שבמלכות מגולה בו, להיותו מהזווג הגדול דעתיק יומין המשבית כל הקליפות מהשם ב\"ן, בסו\"ה בלע המות לנצח. (כנ\"ל אות צ\"ד ד\"ה והענין הוא, ע\"ש)."],[11,"","וז\"ש, \u0003דוד שם ליה לביה כנ\"ל, דלא אתפרש מלוחא דלביה לעלמין\u0004 כי שלמותו בו. אבל \u0003בניהו בן יהוידע\u0004, לא שם לבו \u0003לדוד\u0004 כי דוד הוא רגל רביעית לג\"ר, וע\"כ כמו שלא יכול לקבל מן ג\"ר, כנ\"ל. כן לא היה יכול לקבל \u0003מדוד\u0004. וע\"כ לא שם אליו לבו."],[11,"דתושבחן ושירין","וכו': ע\"י המ\"ן שהמלכות, הנקראת \u0003סיהרא\u0004, מעלה אל ז\"א, הנק' \u0003שמשא\u0004, ע\"י תשבחות ושירים ורחמים היא נמצאת ממשיכה אליה את הארת נשמת בניהו בן יהוידע, שהיא שלמותה האחרונה כנ\"ל, \u0003למהוי דיוריה בהדה\u0004, שיתדבק בה לנצח."]],[[0,"","וְהוּא הֵיכָל קָדוֹשׁ נִסְתָּר שֶׁכָּל הַדְּרָגוֹת מְקֻבָּצוֹת וְנִסְתָּרוֹת בְּתוֹכוֹ. וּבְגוּף הַהֵיכָל הַזֶּה קַיָּמִים כָּל הָעוֹלָמוֹת, וְכָל הַצְּבָאוֹת הַקְּדוֹשִׁים מִמֶּנּוּ נִזּוֹנִים וְעוֹמְדִים עַל קִיּוּמָם."],[1,"","הוּא הִכָּה אֶת שְׁנֵי אֲרִאֵל מוֹאָב. שְׁנֵי מִקְדָּשִׁים הָיוּ עוֹמְדִים בִּגְלָלוֹ וְנִזּוֹנוּ מִמֶּנּוּ, מִקְדָּשׁ רִאשׁוֹן וּמִקְדָּשׁ שֵׁנִי. כֵּיוָן שֶׁהוּא הִסְתַּלֵּק, נִמְנָע הַשֶּׁפַע שֶׁהָיָה שׁוֹפֵעַ מִלְמַעְלָה. כִּבְיָכוֹל הוּא הִכָּה אוֹתָם וְהֶחֱרִיב אוֹתָם וְהִשְׁמִיד אוֹתָם, וְהַכִּסֵּא הַגָּדוֹל נָפַל. זֶהוּ שֶׁכָּתוּב (יחזקאל א) וַאֲנִי בְתוֹךְ הַגּוֹלָה. הַדַּרְגָּה הַהִיא שֶׁנִּקְרֵאת אֲנִי, הִיא בְתוֹךְ הַגּוֹלָה. לָמָּה עַל נְהַר כְּבָר. עַל נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא שֶׁהִפְסִיק מֵימָיו וּמַעְיְנוֹתָיו וְלֹא מַשְׁפִּיעַ כְּבָרִאשׁוֹנָה."],[2,"","זֶהוּ שֶׁכָּתוּב (איוב יד) וְנָהָר יֶחֱרַב וְיָבֵשׁ. יֶחֱרַב - בְּבַיִת רִאשׁוֹן, וְיָבֵשׁ - בְּבַיִת שֵׁנִי. וּמִשּׁוּם כָּךְ הוּא הִכָּה אֶת שְׁנֵי אֲרִאֵל מוֹאָב. (ס\"א שהרי בראשונה) מוֹאָב, שֶׁהָיוּ מֵאָב שֶׁבַּשָּׁמַיִם, וְנֶחְרְבוּ וְהֻשְׁמְדוּ בִּגְלָלוֹ, וְכָל הָאוֹרוֹת שֶׁהָיוּ מְאִירִים לְיִשְׂרָאֵל, כֻּלָּם נֶחְשְׁכוּ."],[3,"","וְעוֹד, הוּא יָרַד וְהִכָּה אֶת הָאֲרִי. בַּזְּמַנִּים הָרִאשׁוֹנִים כְּשֶׁהַנָּהָר הַזֶּה הָיָה מוֹשֵׁךְ אֶת מֵימָיו לְמַטָּה, הָיוּ יִשְׂרָאֵל עוֹמְדִים בִּשְׁלֵמוּת, שֶׁזּוֹבְחִים זְבָחִים וְקָרְבָּנוֹת לְכַפֵּר עַל נַפְשָׁם, וְאָז הָיָה יוֹרֵד מִלְמַעְלָה דְּמוּת שֶׁל אַרְיֵה אֶחָד, וְהָיוּ רוֹאִים אוֹתוֹ עַל גַּבֵּי הַמִּזְבֵּחַ רוֹבֵץ עַל טַרְפּוֹ, אוֹכֵל קָרְבָּנוֹת כְּמוֹ גֶבֶר חָזָק, וְכָל הַכְּלָבִים הָיוּ מִתְחַבְּאִים מִלְּפָנָיו וְלֹא יוֹצְאִים הַחוּצָה."],[4,"","כֵּיוָן שֶׁגָּרְמוּ הַחֲטָאִים, הוּא יָרַד לְתוֹךְ הַדְּרָגוֹת שֶׁלְּמַטָּה, וְהָרַג אֶת אוֹתוֹ הָאַרְיֵה שֶׁלֹּא רָצָה לָתֵת לוֹ אֶת טַרְפּוֹ כְּבָרִאשׁוֹנָה. כִּבְיָכוֹל הָרַג אוֹתוֹ. הוּא הִכָּה אֶת הָאֲרִי וַדַּאי. לְתוֹךְ הַבּוֹר - לְעֵינֵי הַצַּד הָאַחֵר הָרָע. כֵּיוָן שֶׁרָאֲתָה כָּךְ אוֹתוֹ הַצַּד הָאַחֵר, הִתְגַּבְּרָה וְשָׁלְחָה כֶּלֶב אֶחָד לֶאֱכֹל אֶת הַקָּרְבָּנוֹת. וּמַה שְּׁמוֹ שֶׁל אוֹתוֹ הָאַרְיֵ\"ה אוֹרִיאֵ\"ל, שֶׁפָּנָיו פְּנֵי אַרְיֵה. וּמַה שֵּׁם אוֹתוֹ כֶלֶב בַּלְאֲדָן שְׁמוֹ, שֶׁאֵינוֹ בִּכְלָל שֶׁל אָדָם, אֶלָּא כֶּלֶב וּפְנֵי כֶלֶב."],[5,"","בְּיוֹם הַשָּׁלֶג - בַּיּוֹם שֶׁגָּרְמוּ הַחֲטָאִים וְהַדִּין נִדּוֹן לְמַעְלָה מֵעִם בֵּית הַדִּין הָעֶלְיוֹן. וְעַל זֶה כָּתוּב לֹא תִירָא לְבֵיתָהּ מִשָּׁלֶג. זֶה הַדִּין הָעֶלְיוֹן. לָמָּה מִשּׁוּם שֶׁכָּל בֵּיתָהּ לָבֻשׁ שָׁנִים, וְיָכוֹל לִסְבֹּל אֵשׁ חֲזָקָה. עַד כָּאן סוֹד הַכָּתוּב."],[6,"","מַה כָּתוּב אַחֲרָיו (שמואל ב כג) וְהוּא הִכָּה אֶת אִישׁ מִצְרִי אִישׁ מַרְאֶה. כָּאן סוֹד הַכָּתוּב בָּא לְהוֹדִיעַ, שֶׁבְּכָל פַּעַם שֶׁיִּשְׂרָאֵל חָטְאוּ, הוּא הִסְתַּלֵּק וּמָנַע מֵהֶם כָּל הַטּוֹבוֹת וְכָל הָאוֹרוֹת שֶׁהָיוּ מְאִירִים לָהֶם. הוּא הִכָּה אֶת אִישׁ מִצְרִי - זֶה הָאוֹר שֶׁל הָאוֹר הַהוּא שֶׁהָיָה מֵאִיר לְיִשְׂרָאֵל. וּמִי הוּא מֹשֶׁה, שֶׁכָּתוּב (שמות ב) וַתֹּאמַרְנָה אִישׁ מִצְרִי הִצִּילָנוּ וְגוֹ'. וְשָׁם נוֹלַד, וְשָׁם הִתְגַּדֵּל, וְשָׁם הִתְעַלָּה לְאוֹר עֶלְיוֹן."],[7,"","אִישׁ מַרְאֶה - כְּמוֹ שֶׁנֶּאֱמַר (במדבר יב) וּמַרְאֶה וְלֹא בְחִידוֹת. אִישׁ - כְּמוֹ שֶׁנֶּאֱמַר (דברים לג) אִישׁ הָאֱלֹהִים. כִּבְיָכוֹל בַּעְלָהּ שֶׁל אוֹתוֹ מַרְאֵה כְּבוֹד ה', שֶׁזָּכָה לְהַנְהִיג אֶת הַדַּרְגָּה הַזּוֹ בְּכָל רְצוֹנוֹ בָּאָרֶץ מַה שֶּׁלֹּא זָכָה אִישׁ אַחֵר."],[8,"","וּבְיַד הַמִּצְרִי חֲנִית - זֶה מַטֵּה הָאֱלֹהִים שֶׁנִּמְסַר בְּיָדוֹ, כְּמוֹ שֶׁנֶּאֱמַר (שמות יז) וּמַטֵּה הָאֱלֹהִים בְּיָדִי. וְזֶה הַמַּטֶּה שֶׁנִּבְרָא עֶרֶב שַׁבָּת בֵּין הַשְּׁמָשׁוֹת וְחָקוּק בּוֹ הַשֵּׁם הַקָּדוֹשׁ הֶחָקוּק הַקָּדוֹשׁ, וּבָזֶה חָטָא בַסֶּלַע, כְּמוֹ שֶׁנֶּאֱמַר (במדבר כ) וַיַּךְ אֶת הַסֶּלַע בְּמַטֵּהוּ פַּעֲמָיִם. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: מֹשֶׁה, לֹא לְזֶה נָתַתִּי לְךְ אֶת הַמַּטֶּה שֶׁלִּי, חַיֶּיךְ לֹא יִהְיֶה בְיָדְךְ מִכָּאן וָהָלְאָה."],[9,"","מִיָּד - וַיֵּרֶד אֵלָיו בַּשָּׁבֶט (שמואל ב כג), בַּדִּין הַקָּשֶׁה, וַיִּגְזל אֶת הַחֲנִית מִיַּד הַמִּצְרִי. שֶׁמֵּהַשָּׁעָה הַהִיא נִמְנַע מִמֶּנּוּ וְלֹא הָיָה בְּיָדוֹ לְעוֹלָמִים. וַיַּהַרְגֵהוּ בַּחֲנִיתוֹ - עַל אוֹתוֹ הַחֵטְא שֶׁהִכָּה בַּמַּטֶּה הַהוּא מֵת וְלֹא נִכְנַס לָאָרֶץ הַקְּדוֹשָׁה, וְנִמְנָע הָאוֹר הַזֶּה מִיִּשְׂרָאֵל."],[10,"","(שם) מִן הַשְּׁלֹשִׁים - הֲכִי נִכְבָּד, אֵלּוּ שְׁלֹשִׁים שָׁנָה עֶלְיוֹנִים שֶׁנָּטַל מֵהֶם וְהִשְׁפִּיעַ לְמַטָּה, וּמֵהֶם הוּא הָיָה לוֹקֵחַ וּמִתְקָרֵב. וְאֶל הַשְּׁלֹשָׁה לֹא בָא - הֵם הָיוּ בָּאִים אֵלָיו וְנוֹתְנִים לוֹ בִּרְצוֹן הַלֵּב, וְהוּא לֹא הָיָה בָּא אֲלֵיהֶם."],[11,"","וְאַף עַל גַּב שֶׁלֹּא נִכְנַס בַּמִּנְיָן וְהַחֶשְׁבּוֹן שֶׁלָּהֶם, (שם) וַיְשִׂמֵהוּ דָוִד אֶל מִשְׁמַעְתּוֹ. שֶׁלֹּא נִפְרָד מִלּוּחַ לִבּוֹ לְעוֹלָמִים. אֵין לָהֶם פֵּרוּד לְעוֹלָמִים. דָּוִד שָׂם לִבּוֹ אֵלָיו, וְהוּא לֹא לְדָוִד, מִשּׁוּם שֶׁהַתִּשְׁבָּחוֹת וְהַשִּׁירִים וְהָאֲהָבִים שֶׁהַלְּבָנָה עוֹשָׂה לַשֶּׁמֶשׁ, הִיא מוֹשֶׁכֶת אוֹתוֹ אֵלֶיהָ שֶׁיִּהְיֶה דִיּוּרוֹ עִמָּהּ, וְזֶהוּ וַיְשִׂמֵהוּ דָוִד אֶל מִשְׁמַעְתּוֹ."]]],[["נָפְלוּ רִבִּי אֱלִיעֶזֶר וְרִבִּי אַבָּא קַמֵּיהּ. אַדְהָכִי וְהָכִי לָא חֲמוּ לֵיהּ. קָמוּ וְאִסְתַּכָּלוּ לְכָל סִטְרִין וְלָא חֲמוּ לֵיהּ. יָתְבוּ וּבָכוּ וְלָא יָכִילוּ לְמַלָּלָא דָּא לְדָא. לְבָתַר שַׁעֲתָא אָמַר רִבִּי אַבָּא וַדַּאי הָא דְּתָנֵינָן דְּבְּכָל אָרְחָא דְצַדִּיקַיָיא אָזְלִין וּמִילֵי דְאוֹרַיְיתָא בֵּינַיְיהוּ, דְּאִנּוּן זַכָּאִין דְּהַהוּא עָלְמָא אַתְיָאן לְגַבֵּיהוֹן. וַדַּאי דָּא הוּא רַב הַמְנוּנָא סָבָא דְּאָתָא לְגַבָּן מֵהַהוּא עָלְמָא לְגַלָּאָה לָן מִלִּין אִלֵּין, וְעַד לָא נִשְׁתְּמוֹדַע בֵּיהּ אֲזַל לֵיהּ וְאִתְכַּסֵּי מִינָן. קָמוּ וְהֲווּ בָּעוּ לְמִטְעַן לְחַמְרֵי וְלָא אָזְלוּ, בָּעוּ לְמִטְעַן וְלא אָזְלוּ. דְּחִילוּ וְאַנְחוּ לוֹן לְחַמְרֵי. וְעַד יוֹמָא הֲווּ קָרָאן לְהַהוּא אֲתַר, דּוּךְ דְּחֲמָרֵי.","פָּתַח רִבִּי אֶלְעָזָר (ל\"א ב', מ\"ו א', י\"ח א) וְאָמַר (תהילים ל״א:כ׳) מָה רַב טוּבְךָ אֲשֶׁר צָפַנְתָּ לִירֵאֶיךָ וְגו' כַּמָּה הוּא טָבָא עִלָּאָה וְיַקִּירָא דְּזָמִּין קוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבַּד גַּבֵּי בְּנִי נְשָׁא לְאִנּוּן זַכָּאִין עִלָּאִין דַּחֲלֵי חֶטְאָה דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא כַּד עָאלִין לְהַהוּא עָלְמָא. טוּבְךָ לָא כְּתִיב אֶלָא רַב טוּבְךָ. וּמָאן אִיהוּ (תהילים קמ״ה:ז׳) זֵכֶר רַב טוּבְךָ יַבִּיעוּ. וְדָא אִיהוּ עִנּוּגָא דְּחַיִּין דְּנַגְדִין מֵעָלְמָא דְּאָתֵי לְגַבֵּי חַי עָלְמִין דְּאִיהוּ זֵכֶר רַב טוּבְךָ. וַדַּאי אִיהוּ (ישעיהו ס״ג:ז׳) וְרַב טוּב לְבֵית יִשְׂרָאֵל וְגו'.","תּוּ מָה רַב טוּבְךָ, הָכָא אַגְלִיף רָזָא דְחָכְמְתָא וְכָל רָזִין אִתְכְּלִילוּ הָכָא, מָ\"ה, כְּמָה דְּאִתְמָר. רַב דָּא אִילָנָא רַ\"ב וְתַקִּיף. בְּגִין דְּאִית אִילָנָא אָחֳרָא זוּטָא מִנֵּיהּ, וְדָא הוּא רַב וְאָעִיל לֵיהּ בְּרוּם רְקִיעִין.","טוּבְ\"ךָ דָּא אוֹר דְּאִתְבְּרֵי בְּיוֹמָא קַדְמָאָה. אֲשֶׁר צָפַנְתָּ לִירֵאֶיךָ בְּגִין דְּגָנִיז לֵיהּ לְצַדִּיקַיָּיא בְּהַהוּא עָלְמָא. פָּעַלְתָּ דָּא גַּן עֵדֶן עִלָּאָה. דִּכְתִיב, (שמות ט״ו:י״ז) מָכוֹן לְשִׁבְתְּךָ פָּעַלְתָּ יְיָ, וְדָא הוּא פָּעַלְתָּ לַחוֹסִים בָּךְ.","(בראשית מו ע\"ב) נֶגֶד בְּנֵי אָדָם דָּא גַּן עֵדֶן דִּלְתַתָּא לְגוֹ מְתִיבְתָּא דִרְקִיעָא בְּהַהוּא גַּן עֵדֶן דִּלְעֵילָא. וּפָרְחֵי וְאִסְתַּחְיָין בְּטַלֵּי נַהֲרֵי אֲפַרְסְמוֹנָא דַכְיָא וְנַחֲתֵי וְשָׁרָאן (ושריין) לְתַתָּא.","וּלְזִמְנִין אִתְחֲזוּן נֶגֶד בְּנֵי אָדָם לְמֶעְבַּד לוֹן נִסִּין כְּמַלְאָכִין עִלָּאִין, כְּגַוְונָא דְּחֲזֵינָא הַשְׁתָּא נְהִירוּ דְּבוּצִינָא עִלָּאָה וְלָא זָכִינָא לְאִסְתַּכָּלָא וּלְמִנְדַע רָזִין דְּחָכְמָתָא יַתִּיר.","פָּתַח רִבִּי אַבָּא וְאָמַר (שופטים י״ג:כ״ב) וַיֹּאמֶר מָנוֹחַ אֶל אִשְׁתּוֹ מוֹת נָמוּת כִּי אֱלהִים רָאִינוּ, אַף עַל גַּב דְּמָנוֹחַ לָא הֲוָה יָדַע מַאי עֲבִידְתֵּיהּ, אָמַר הוֹאִיל וּכְתִיב, (שמות ל״ג:כ׳) כִּי לא יִרְאַנִי הָאָדָם וָחָי, וַדַּאי אֲנַן חֲזֵינָן וּבְגִין כָּךְ מוֹת נָמוּת. וְאֲנַן חָמֵינָן וְזָכֵינָן לִנְהוֹרָא דָא דְּהֲוָה אָזִיל בַּהֲדָן וְנִתְקַיֵּים (ואתקיימנא) בְּעָלְמָא. דְּהָא קוּדְשָׁא בְּרִיךְ הוּא שַׁדְּרֵיהּ לְגַבָּן לְאוֹדְעָא לָן רָזִין דְּחָכְמְתָא דְּגָלֵי, זַכָּאָה חוּלְקָנָא.","אֲזְלוּ, מְטוּ לְחַד טוּרָא וְהֲוָה נָטֵי שִׁמְשָׁא. שָׁרוּ עַנְפִין דְּאִילָנָא דְטוּרָא לְאֲקָשָׁא דָּא בְדָא וְאָמְרֵי שִׁירָתָא. עַד דַּהֲווּ אָזְלֵי, שְׁמָעוּ חַד קָלָא תַּקִּיפָא דְּהֲוָה אָמַר בְּנֵי אֱלָהִין קַדִּישִׁין אִנּוּן דְּאִתְבַּדְּרוּ בֵּינֵי חַיָּיא דְהַאי עָלְמָא, אִנּוּן בּוֹצִינֵי בְּנֵי מְתִיבְתָּא, אִתְכַּנְּשׁוּ לְדוּכְתַּיְיהוּ לְאִשְׁתַּעְשְׁעָא בְּמָארֵיכוֹן בְּאוֹרַיְיתָא. דְּחִילוּ אִלֵּין וְקָאִימוּ בְּדוּכְתַּיְיהוּ וְיָתְבֵי. אַדְּהָכִי נָפִיק קָלָא כְּמִלְקַדְּמִין וְאָמַר טִנָּרִין תַּקִיפִין פַּטִּישִׁין רָמְאִין הָא מָארֵי דִּגְוָונִין מְרַקְמָא בְּצִיּוּרִין קָאִים עַל אִצְטְוָונָא, עוּלוּ וְאִתְכַּנְשׁוּ.","בְּהַהִיא שַׁעֲתָא שְׁמָעוּ קָל עַנְפֵי דְאִילָנִין רַב וְתַקִּיף וְהֲווּ אָמְרֵי (תהילים כ״ט:ה׳) קוֹל יְיָ שׁוֹבֵר אֲרָזִים. נָפְלוּ עַל אַנְפַּיְהוּ רִבִּי אֶלְעָזָר וְרִבִּי אַבָּא וּדְחִילוּ סַגְיָא נָפַל עֲלַיְהוּ, קָאמוּ בִּבְהִילוּ וְאֲזְלוּ וְלָא שְׁמָעוּ מִידִי. נָפְקוּ מִן טוּרָא וְאָזְלוּ."],[[0,"","קה) \u0003נפלו ר' אלעזר\u0004 וכו': נפלו ר' אלעזר ור' אבא לפניו, על פניהם. בתוך כך לא ראו אותו. קמו והסתכלו לכל הצדדים, ולא ראו אותו. ישבו ובכו ולא יכלו לדבר זה עם זה. לאחר כך, אמר ר' אבא, ודאי זהו שלמדנו, שתמיד בכל דרך שהצדיקים הולכים ודברי תורה ביניהם, באים אליהם הצדיקים מעולם ההוא. לגלות להם דברי תורה. ודאי זה הוא, מה שרב המנונא סבא בא אלינו מהעולם ההוא, לגלות לנו הדברים האלו. וטרם שהספקנו להכיר אותו, הלך לו ונעלם ממנו. קמו, והיו רוצים להנהיג את החמורים, ולא הלכו, ושוב רצו להנהיגם, ולא הלכו. פחדו, ועזבו את החמורים. ועד היום קוראים למקום ההוא, מקום החמורים."],[0,"","פירוש. כי לא יכלו לסבול את האור הגדול הזה, שנגלה להם בעת גילוי הסודות הללו, ונפלו קמיה. וז\"ש, \u0003נפלו רבי אלעזר\u0004 וכו'."],[0,"","וז\"ש, \u0003אדהכי והכי לא חמו ליה\u0004 כי אחר שזכו לקבל ממנו את מדרגתו הגדולה והנשאה, נעלם מהם תיכף ולא יכלו למצאו ולהשיגו עוד. ולפיכך \u0003יתבו ובכו ולא יכלו למללא דא לדא\u0004 שהיה צערם גדול וישבו ובכו עד ולא יכלו לדבר זה עם זה."],[0,"","וז\"ש, \u0003דא הוא רב המנונא\u0004 וכו', כי עתה הכירו דרגתו, שהוא \u0003רב המנונא סבא\u0004 בעצמו, ולא כמו שחשבו לפני זה שהוא רק \u0003בריה\u0004 דרב המנונא סבא. (עיין לעיל אות צ'). \u0003קמו והוו בעו למטען לחמרי\u0004 וכו' \u0003ואנחו לון לחמרי\u0004: כי ה\u0003חמרי\u0004 הם סוד הכחות שנתנה להם נשמת \u0003רב המנונא סבא\u0004 שיוכלו להעלות מ\"ן להשיג את המדרגות הללו, חיה יחידה, שהשיגו על ידו."],[0,"","שז\"ס שהרכיבם על החמורים והלך לפניהם להאיר להם את אורח הצדיקים. (כנ\"ל אות פ\"ה ד\"ה נחתו. ע\"ש). ועתה אחר שגמר תפקידו ונעלם מהם, היו רוצים שוב לעלות ולרכב על החמורים שלו, כלומר שרצו להעלות מ\"ן מחדש, בכדי לחזור ולהשיגו שנית. אמנם \u0003בעו למטען ולא אזלו\u0004 כי עתה לא היו יכולים לקבל מהם שוב כוח להעלאת מ\"ן. וע\"כ יראו והניחו את החמורים במקום ההוא שרב המנונא סבא פרח מהם. וסימנו את המקום ההוא בשם \u0003דוך דחמרי\u0004 מקום החמורים, דהיינו על המאורע, שלא יכלו עוד לשמש עמהם."],[1,"","קו) \u0003פתח ר' אלעזר\u0004 וכו': פתח ר' אלעזר ואמר, מה רב טובך אשר צפנת ליראיך וגו' (תהלים ל\"א). כמה הוא הטוב העליון והיקר, שעתיד הקב\"ה לעשות לבני אדם, לאותם הצדיקים העליונים יראי חטא העוסקים בתורה, כשהם באים לעולם ההוא. טובך, לא כתוב אלא \u0003רב טובך\u0004, ומי הוא. היינו, זכר רב טובך יביעו וזהו חיי עונג הנמשכים מעולם הבא אל חי העולמים. שהוא נקרא זכר רב טובך. והוא ודאי \u0003ורב טוב\u0004 לבית ישראל וגו'."],[1,"","פירוש. המלה \u0003רב\u0004, מורה תמיד על בחינת גדלות, וכיון שהכתוב מדגיש לומר כאן \u0003רב טובך\u0004 ולא \u0003טובך\u0004 סתם, ע\"כ הוא מורה על \u0003עינוגא דחיין\u0004, דהיינו מוחין דג\"ר. כי עיקרו של הפרצוף והחיים שלו הוא מוחין דו\"ק, המקובל מזווג דאו\"א כדי להחיות העולמות, אמנם יש גם מוחין דתוספת המענגים את החיים, שהם מוחין דג\"ר, והם הנק' \u0003רב טובך ועינוגא דחיין\u0004."],[1,"","וז\"ש, \u0003דנגדין מעלמא דאתי לגבי חיי עלמין\u0004: כי מוחין דג\"ר שהם חכמה נמשכין מהבינה, הנקראת \u0003עלמא דאתי\u0004, ומתלבשים בלבוש יקר דחסדים הבא מזווג היסודות, הנק' \u0003חי עלמין\u0004, ומשם מגיעים המוחין אל הצדיקים \u0003דחלי חטאה\u0004."],[2,"","קז) \u0003תו מה רב\u0004 וכו': עוד, יש לפרש, \u0003מה רב טובך\u0004. שכאן נחקק סוד החכמה, וכל הסודות נכללו כאן. כי \u0003מה\u0004 פירושו כמו שלמדנו, (לעיל אות י\"ט). \u0003רב\u0004 זהו, אילן רב וחזק. שהוא ז\"א. משום שיש אילן אחר הקטן ממנו, דהיינו המלכות, וזה ז\"א, הוא רב. ומביאו ברום הרקיעים."],[2,"","פירוש. שנוסף על זה שביאר את הכתוב על השגת המוחין דג\"ר, יש עוד להבין הכתוב, כי בו נרשמה פנימיות החכמה, וכל הסודות נכללו בפסוק הזה: \u0003רזא דחכמתא\u0004, מורה על זווג עתיק. \u0003וכל רזין\u0004, מורה על גמר כלל התיקון."],[2,"מ\"ה כמא דאתמר, רב דא אילנא רב ותקיף",", מ\"ה היינו עלמא תתאה, \u0003כמה דאתמר\u0004 לעיל (אות ח'). \u0003רב\u0004 מורה על \u0003אילנא רב ותקיף\u0004, היינו ז\"א בעת הלבשתו לפרצוף ע\"ב, ונקרא אז \u0003אילנא רב\u0004, על שם החכמה, ונק' \u0003תקיף\u0004, מבחינת עצמו, אמנם בעת שז\"א במקומו עצמו, נק' \u0003אילנא\u0004 סתם. וז\"ש \u0003בגין דאית אילנא אחרא זוטא מניה\u0004, שהוא המלכות, הנקראת ג\"כ אילן. \u0003ודא הוא רב\u0004, וכשמלביש לקומת ע\"ב נק' \u0003רב, ואעיל ליה ברום רקיעין\u0004 הע\"ב מביא את הז\"א \u0003לרום רקיעין\u0004. כי רומיה דע\"ב מטי עד הכתר הנק' \u0003רום רקיעין\u0004 כי הע\"ב מלביש על פרצוף הכתר. וע\"כ הע\"ב מעלה את הז\"א \u0003לרום רקיעין\u0004."],[3,"","קח) \u0003טובך, דא אור\u0004 וכו', \u0003טובך\u0004, הוא האור שנברא ביום הראשון, של מעשה בראשית. \u0003אשר צפנת ליראיך\u0004, היינו, בשביל שגנזו לצדיקים לעולם ההוא. \u0003פעלת\u0004, זהו גן עדן העליון, שכתוב, מכון לשבתך \u0003פעלת\u0004 ה'. וזהו פעלת לחוסים בך."],[3,"","פירוש. האור שנברא ביום ראשון, הוא האור, שהיה אדם הראשון צופה בו מסוף העולם ועד סופו. וה\"ס ה' פעמים אור הנאמרים ביום ראשון דמעשה בראשית. \u0003לצדיקייא בההוא עלמא\u0004, היינו \u0003בעלמא דאתי\u0004 כי האור הזה נגנז ביסודות שהם צדיק וצדק של או\"א הנק' עלמא דאתי, ואלו צדיק וצדק נק' \u0003יראיך\u0004, ע\"ש כח הגניזו שבהם, ומהם מתקבל האור הזה אל הצדיקים."],[3,"פעלת, דא גן עדן עלאה",": כי מקודם לכן כתוב \u0003אשר צפנת\u0004, שפירושו שהמוחין באים בלבוש יקר דצדיק וצדק בגניזו מכוסים באלו הלבושים. וכאן כתוב \u0003פעלת\u0004, שהמשמעות היא פעולה גלויה בלי הכיסוי האמור, ומביא ראיה מהכתוב \u0003מכון לשבתך פעלת ה'\u0004 דהיינו פעולה שלמה וגלויה."],[3,"","ודרש כי \u0003פעלת\u0004 נאמר על \u0003גן עדן\u0004 העליון, שהוא נפעל ויצא מכלל אלו המוחין הקודמים בכתוב, הנוהגים בכל שתא אלפי שני. ויהיה שיעור הכתוב \u0003מה רב טובך אשר צפנת ליראיך\u0004, שהם המוחין דכלל שתא אלפי שני, אשר כל אלו \u0003פעלת\u0004 ע\"י הזווג הגדול דעתיק יומין, \u0003לחוסים בך\u0004, שממוחין אלו נפעל ויצא ג\"ע העליון, ששם שרויים צדיקים גמורים החוסים בו ית', והיינו אותן הנשמות דבניהו בן יהוידע וכדומה, שזוכות לקבל מהזווג הגדול דעתיק, המקובץ מכל אלו המוחין דשתא אלפי שני. כנ\"ל."],[3,"","ודע. שמקום מנוחתן של הנשמות נקרא \u0003גן עדן\u0004. ויש גן עדן הארץ, הנק' ג\"כ גן העדן התחתון, והוא בחי' ו\"ק, ויש גן עדן עליון שהוא בחינת ג\"ר של ג\"ע. וכל הנשמות שרויות רק בג\"ע התחתון, אלא ברישי ירחי ושבתי עולות לג\"ע העליון ואח\"כ חוזרות למקומן. אלא שיש יחידי סגולה שמקומם הוא בג\"ע העליון. ועליו אמר ר\"ש, ראיתי בני עליה שהם מועטים."],[4,"","קט) \u0003נגד בני אדם\u0004: זהו גן עדן שלמטה, שכל הצדיקים עומדים שם, ברוח המתלבש בלבוש יקר, כאותו האפן והצורה שהיו בעולם הזה. וזה הוא, \u0003נגד בני אדם\u0004, דהיינו, באותה צורה של בני אדם שבעולם הזה. ועומדים שם, ופורחים באויר משם, ועולים לישיבת הרקיע באותו גן העדן של מעלה. ופורחים שמה ומתרחצים בטל נהרות אפרסמון טהור, ויורדים ושורים למטה. בג\"ע התחתון."],[4,"","ביאור הדברים, כי ההבדל העיקרי שיש בין ג\"ר ובין ז\"ת, הן בפרצופין והן בנשמות, הוא, כי ג\"ר יכולות לקבל אור החכמה כמות שהוא, ואינן צריכות שתתלבש להן החכמה בלבוש של אור חסדים. משא\"כ פרצופי ו\"ק, וכן הנשמות הנולדות מזו\"ן שעיקרן ו\"ק, הן אינן יכולות לקבל אור החכמה זולת בדרך התלבשותו באור החסדים."],[4,"","וז\"ש \u0003דא ג\"ע דלתתא, דכל צדיקייא תמן קיימי ברוחא דאתלבש בלבוש יקר, כגוונא ודיוקנא דהאי עלמא\u0004, כי כל הצדיקים שבג\"ע התחתון, הרוחות שלהם מלובשות בלבוש יקר של אור החסדים, כמו נשמות בני אדם שבעוה\"ז, שע\"י \u0003לבוש יקר\u0004 זה הנק' \u0003אוירא\u0004, הן יכולות לעלות לג\"ע העליון ולקבל משם אור החכמה, ואח\"כ חוזרות למקומן לג\"ע התחתון."],[4,"","וז\"ש ו\u0003קיימי תמן\u0004, שעיקר מקומן הקבוע הוא בג\"ע התחתון \u0003ופרחי באוירא וסלקו לגו מתיבתא דרקיעא בההוא ג\"ע דלעילא\u0004, שבכח האי \u0003אוירא\u0004 שהוא אור החסדים הן פורחות ועולות לג\"ע העליון לקבל חכמה \u0003ופרחי ואסתחיין בטלי נהרי אפרסמונא דכיא\u0004, כי אור החכמה שהן מקבלות שם בג\"ע מכונה בשם \u0003י\"ג נהרי דאפרסמונא דכיא\u0004, כי החכמה נקראת \u0003שמן\u0004 והמספר \u0003י\"ג\u0004 מורה על חכמה דל\"ב נתיבות, (כנ\"ל במראות הסולם ד\"ה ועם)"],[4,"","ואח\"כ \u0003ונחתי ושראן לתתא\u0004 דהיינו, שאינן יכולות לשהות שם, ותיכף אחר קבלתן החכמה תוך \u0003לבוש היקר\u0004 שלהן, יורדות מג\"ע העליון למקומן, לג\"ע התחתון. ולפי שהן צריכות לקבל החכמה תוך לבוש החסדים, דוגמת נשמות בני אדם שבעוה\"ז, ע\"כ הכתוב מכנה גם אותן, נגד בני אדם \u0003בההוא דיוקנא דבני אדם דהאי עלמא\u0004, כי הן באותה הצורה כמו בני אדם שבעוה\"ז, כי גם הן צריכות ללבוש החסדים כמותם."],[5,"","קי) \u0003ולזמנין אתחזון נגד\u0004 וכו': ולפעמים, הצדיקים האלו, \u0003נראים נגד בני אדם,\u0004 לעשות להם נסים, כמלאכים עליונים, כעין שראינו עתה אור המאור העליון, ולא זכינו להסתכל ולדעת סודות החכמה יותר."],[5,"","פירוש. הכוונה על נשמות יחידי הסגולה, שבג\"ע העליון, שאע\"פ שמעלתן גבוהה כל כך, עד שאפילו הנשמות שבג\"ע התחתון העולות אליהן ברישי ירחי ושבתי, אינן יכולות לשהות שם אלא יורדות תיכף למקומן, עכ\"ז \u0003ולזמנין אתחזון נגד בני אדם\u0004 שהן יורדות מג\"ע העליון לעוה\"ז ומתראות לבני אדם, כמו מלאכי עליון היורדים לפעמים לעוה\"ז. והיינו \u0003כגוונא דחזינא השתא נהירו דבוצינא עלאה\u0004. כמו שראה עתה האור של המאור העליון, דהיינו לרב המנונא סבא, שירד אליהם מרום מעלתו מג\"ע העליון ונגלה לעיניהם בעוה\"ז."],[5,"","ודורש המקרא \u0003נגד בני אדם\u0004, על ב' משמעויות:"],[5,"","א) על הנשמות שבג\"ע התחתון, שיש להן \u0003דיוקנא דבני אדם\u0004, ופעל להן האורות הנשגבים שבג\"ע העליון, שיכלו לקבל משם בדרך עליה בר\"ח ובשבתות. שאז הן זוכות לקבל פניהן של הנשמות שבג\"ע העליון ולירד שוב למקומן."],[5,"","ב) דורש \u0003נגד בני אדם\u0004, ממש שבעוה\"ז, שהנשמות האלו שבג\"ע העליון יורדות לפעמים לעוה\"ז, כמו מלאכי מרום, ונראות לעיני הצדיקים."],[5,"","וז\"ש, \u0003ולא זכינא לאסתכלא ולמנדע רזין דחכמתא יתיר\u0004: מתאונן על שתיכף נעלם מהם, ומהעת ההיא לא זכה להשיג עוד \u0003רזין דאורייתא\u0004 עד הנה."],[6,"","קיא) \u0003פתח ר' אבא\u0004 וכו': ויאמר מנוח אל אשתו מות נמות כי אלקים ראינו. אף על פי שמנוח לא ידע מה מעשיו, שכתוב, כי לא ידע מנוח כי מלאך ה' הוא. בכל זאת, אמר כיון שכתוב, כי לא יראנו האדם וחי, ואנו ראינו ודאי, ועל כן מות נמות. ואנחנו ראינו וזכינו לאור הזה שהיה הולך אתנו, ובכל זאת נתקיים בעולם, כי הקב\"ה שלחו אלינו, להודיע לנו סודות החכמה שגילה. אשרי חלקנו."],[6,"","פירוש. כי כשנראה מלאך ה' אל מנוח לא היתה השגתו בו שלמה, שהרי לא רצה לגלות לו את שמו, כמ\"ש למה זה, תשאל לשמי והוא פלאי (שופטים י\"ג), ועכ\"ז פחד מהכתוב \u0003לא יראני האדם וחי\u0004. (שמות ל\"ג) ואנן זכינו להשגה השלמה, כי ידענו את שמו, שהוא \u0003רב המנונא סבא\u0004, ואנו חיים וקיימים בעוה\"ז. ומכאן תבין שענין קבלת פניו של מדרגת רב המנונא הוא בחינת הראני נא את כבודך, שבקש משה מהשי\"ת, שעל זה אמר לו השי\"ת, לא תוכל לראות את פני כי לא יראני אדם וחי (שמות ל\"ג), ונמצא שהשגתם גדלה מהשגת משה. ועל זה אמרו חז\"ל נביא הוא דלא קם כמשה אבל חכם קם (סוף ילקוט ראובני). וכן חכם עדיף מנביא (ב\"ב י\"ב. )"],[6,"","ובזה שבחו את עצמם \u0003ואנן חמינן וזכינן לנהורא דא דהוה אזיל בהדן, ונתקיים בעלמא\u0004 כי אנחנו זכינו לנהורא דא שעליו נאמר \u0003לא יראני האדם וחי\u0004, ואנחנו חיים בעוה\"ז. (ועי' בתק\"ז תק' ס\"ט דף קט\"ו ע\"ב)."],[7,"","קיב) \u0003אזלו מטו לחד\u0004 וכו': הלכו. הגיעו להר אחד, כנטות השמש. התחילו דופקים ענפי האילן שבהר זה בזה, ואומרים שירה. בעוד שהיו הולכים שמעו קול אחד חזק שהיה אומר, בני אלקים קדושים, אותם הפזורים בין החיים בעולם הזה, אותם מאורות בני הישיבה, האספו למקומכם להשתעשע עם אדונכם בתורה. הם פחדו, ונשארו עומדים במקומם, וישבו."],[7,"","פירוש. הלכו ובאו להר אחד, ה\"ס ההר, שעליו אמר דוד המלך, מי יעלה בהר ה' ומי יקום במקום קדשו (תהלים כ\"ד). וכשעלו על ההר העריב השמש, רומז שנסתלקו הארתם. והענפים של האילנות קשקשו זה בזה, ובסוד שיחת האילנות, שמעו מהם שירה, בסוד הכתוב אז ירננו כל עצי יער (תהלים צ\"ו)."],[7,"","וז\"ש, \u0003שמעו חד קלא\u0004 וכו', פירוש. שמעו קול חזק אומר להם, שישובו למקומם \u0003לאשתעשעא\u0004 בהשי\"ת ותורתו, דהיינו שירדו מן ההר. וקורא אותה \u0003בני אלהין קדישין\u0004, על שם מדרגתם הנשגבה, אבל רמז להם, שאין בני אדם שבעוה\"ז כדאים לדור עמהם יחד. וזה שרמז להם \u0003אינון דאתבדרו ביני חיי דהאי עלמא\u0004 כלומר, שאין בני העוה\"ז הולמים אותם, כי לא יוכלו לסבול זה את זה."],[7,"","וז\"ש, \u0003דחילו אלין\u0004 וכו', נפלה יראה עליהם, ומ\"מ לא ירדו מההר, אלא קמו ישבו ולא הזיזו עצמם ממקומם."],[8,"","קיג) \u0003אדהכי נפיק קלא\u0004 וכו': בתוך זה, יצא קול כבתחילה, ואמר, סלעים חזקים, פטישים רמים, הנה בעל הצבעים, המרוקם בציורים, עומד על העמוד, הכנסו והאספו. באותה שעה, שמעו קול ענפי האילנות גדול וחזק. והיו אומרים, קול ה' שובר ארזים. נפלו על פניהם רבי אלעזר ורבי אבא. ופחד גדול נפל עליהם. קמו בחפזון והלכו, ולא שמעו מאומה. יצאו מן ההר, והלכו. \u0003אצטוונא\u0004 פירושו עמוד. כי תרגום של העמוד, הוא על אסטוונא. (מ\"ב י\"א- י\"ד)."],[8,"","פירוש. כי לעיל (אות ק\"ה ד\"ה קפו) נתבאר, כי ע\"כ לא יכלו \u0003למטען חמרי\u0004, שפירושו, שלא יכלו להעלות עוד מ\"ן, משום שכבר גמר רב המנונא סבא את תפקידו שהיה לו לסייע אותם, וע\"כ נתבטל כח החמרין שלו, ולא יכלו לשמש עמהם עוד בכדי להעלות מ\"ן ולזכות לדרגין עלאין יותר. ולפיכך אמר ר' אלעזר לעיל, \u0003ולא זכינא לאסתכלא ולמנדע רזין דחכמתא יתיר\u0004."],[8,"","ויש אמנם להבין הטעם מה ענין השגת המוחין לביטול הכח לעלית מ\"ן. והענין הוא, כי אחר שהשיגו קומת היחידה, שהיא גילוי נשמת בניהו בן יהוידע ע\"י רב המנונא סבא, הנה קרה להם כמו שנתבאר בנשמת בניהו בן יהוידע, כי אחר שנתבטל להם המסך דב\"ן נתבטל עמו יחד גם המסך דס\"ג, וע\"כ לא יכלו עוד להעלות מ\"ן, \u0003ואנחי להו לחמרי\u0004. (כנ\"ל אות ק\"ה ד\"ה קמו ע\"ש). ונתבאר שם, שכל ההפסק של הארת הגוף דעתיק היה, כדי להקנות להם כח לברר להם מחדש את מסך דס\"ג, ואז ישוב הב\"ן להיות ס\"ג, ואז יחזרו להעלות מ\"ן מחדש, וילכו שוב מחיל אל חיל ע\"ש."],[8,"","והנה גם בר' אלעזר ור' אבא, מזמן שהניחו החמורים ואזלי להם עד הנה, הספיקו כל ההרפתקאות הנ\"ל עד הנה, שיתברר להם כח, לעלית מ\"ן מחדש, ולהחזיר הב\"ן להיות ס\"ג. וז\"ש, \u0003נפק קלא כמלקדמין ואמר, טנרין תקיפין פטישין רמאין\u0004 כי הקול רמז להם שהם סלעים חזקים ופטישים רמים, כי עמדו בכל הנסיונות הגדולים עד עתה, והם עצרו כח לעמוד בפניהם כסלעים חזקים, גם גברו על כל המכשולים, עד שפיצצו אותם כפטיש גדול היורד מרום גבוה למטה."],[8,"","וגרמו בזה, \u0003הא מארי דגוונין מרקמא בציורין קאים על אצטוונא\u0004, כי הבינה, הנקראת \u0003מארי דגוונין\u0004 בהיותה עצמה בלי גוון כלל אלא כולה רחמים, אמנם כל בחינת הגוונין מתערין ויוצאין הימנה, וע\"י עמידתם כסלע איתן מול כל אלו הנסיונות, נתרקמה עתה הבינה בציורין מחדש, ולפיכך מכנה את הבינה בשם \u0003מארי דגוונין מרקמא בציורין\u0004, כי קבלה כח להתתקן במסך, שעליו יוצאות קומות ומדרגות חדשות הנקראות ציורין והיא \u0003קאים על אצטוונא\u0004, אצטוונא פירושו כסא, כי עתה נתקנה הבינה בסוד הכסא כמקודם. ולפיכך: \u0003עולו ואתכנשו\u0004 הגיעה העת שתכנסו למקומכם בקדש כמלפנים."],[8,"בההיא שעתא שמעו קל ענפי דאילנין רב ותקיף והוו אמרי קול ה' שובר ארזים",": כלומר, יחד עם הקול, שבישר להם שכבר נתקן המסך של הבינה ובחינת הכסא, שמעו גם קול מענפי האילנות שאמרו \u0003קול ה' שובר ארזים\u0004 (תהלים כ\"ט) רומז להם, כי כבר נשברו כל הארזים שהיו להם למעצורים בדרכם לקודש. וז\"ש, \u0003נפקי מן טורא\u0004, כי עצרו עתה כח לצאת מההר ולעשות הילוכם בקודש כמלפנים."]],[[0,"","נָפְלוּ רַבִּי אֶלְעָזָר וְרַבִּי אַבָּא לְפָנָיו. בֵּין כָּךְ וְכָךְ לֹא רָאוּ אוֹתוֹ. קָמוּ וְהִסְתַּכְּלוּ לְכָל הַצְּדָדִים וְלֹא רָאוּ אוֹתוֹ. יָשְׁבוּ וּבָכוּ וְלֹא יָכְלוּ לְדַבֵּר זֶה עִם זֶה. אַחַר שָׁעָה אָמַר רַבִּי אַבָּא, וַדַּאי זֶה שֶׁשָּׁנִינוּ, שֶׁצַּדִּיקִים הוֹלְכִים וְדִבְרֵי תוֹרָה בֵּינֵיהֶם, שֶׁאוֹתָם צַדִּיקִים שֶׁל אוֹתוֹ הָעוֹלָם בָּאִים אֲלֵיהֶם. וַדַּאי זֶה הוּא רַב הַמְנוּנָא הַזָּקֵן שֶׁבָּא אֵלֵינוּ מִן הָעוֹלָם הַהוּא לְגַלּוֹת לָנוּ אֶת הַדְּבָרִים הַלָּלוּ, וְטֶרֶם הִכַּרְנוּהוּ, הָלַךְ לוֹ וְהִתְכַּסָּה מֵעִמָּנוּ. קָמוּ, וְהָיוּ רוֹצִים לִרְכַּב עַל הַחֲמוֹרִים וְלֹא הָלְכוּ. רָצוּ לִרְכַּב וְלֹא הָלְכוּ. פָּחֲדוּ וְהִנִּיחוּ אֶת הַחֲמוֹרִים. וְעַד הַיּוֹם הָיוּ קוֹרְאִים לְאוֹתוֹ הַמָּקוֹם מְקוֹם הַחֲמוֹרִים."],[1,"","פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (תהלים לא) מָה רַב טוּבְךְ אֲשֶׁר צָפַנְתָּ לִּירֵאֶיךְ וְגוֹ'. כַּמָּה הוּא הַטּוֹב הָעֶלְיוֹן וְהַנִּכְבָּד שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת לִבְנֵי אָדָם לְאוֹתָם צַדִּיקִים עֶלְיוֹנִים יִרְאֵי חֵטְא שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה, כְּשֶׁנִּכְנָסִים לְאוֹתוֹ הָעוֹלָם. לֹא כָתוּב טוּבְךְ, אֶלָּא רַב טוּבְךְ. וּמִי הוּא (שם קמה) זֵכֶר רַב טוּבְךְ יַבִּיעוּ. וְזֶהוּ עֹנֶג הַחַיִּים שֶׁשּׁוֹפְעִים מֵהָעוֹלָם הַבָּא לְחַי הָעוֹלָמִים, שֶׁהוּא זֵכֶר רַב טוּבְךְ. וַדַּאי הוּא (ישעיה סג) וְרַב טוּב לְבֵית יִשְׂרָאֵל וְגוֹ'."],[2,"","עוֹד מָה רַב טוּבְךְ, כָּאן נֶחְקָק סוֹד הַחָכְמָה, וְכָל הַסּוֹדוֹת נִכְלְלוּ כָּאן. מָ\"ה - כְּמוֹ שֶׁבֵּאַרְנוּ. רַב - זֶה הָעֵץ גָּדוֹל וְחָזָק, מִשּׁוּם שֶׁיֵּשׁ אִילָן אַחֵר קָטָן מִמֶּנּוּ, וְזֶה הוּא גָּדוֹל וּמַכְנִיסוֹ לְרוּם הָרְקִיעִים."],[3,"","טוּבְ\"ךְ - זֶה הָאוֹר שֶׁנִּבְרָא בַּיּוֹם הָרִאשׁוֹן. אֲשֶׁר צָפַנְתָּ לִּירֵאֶיךְ - מִשּׁוּם שֶׁגָּנַז אוֹתוֹ לַצַּדִּיקִים בְּאוֹתוֹ הָעוֹלָם. פָּעַלְתָּ - זֶה גַּן הָעֵדֶן הָעֶלְיוֹן, שֶׁכָּתוּב (שמות טו) מָכוֹן לְשִׁבְתְּךְ פָּעַלְתָּ ה'. וְזֶהוּ פָּעַלְתָּ לַחוֹסִים בָּךְ."],[4,"","נֶגֶד בְּנֵי אָדָם - זֶה גַּן הָעֵדֶן שֶׁלְּמַטָּה שֶׁכָּל הַצַּדִּיקִים עוֹמְדִים שָׁם בְּרוּחַ, שֶׁנִּתְלַבְּשָׁה בִּלְבוּשׁ יָקָר כְּצוּרָה וּדְיוֹקָן שֶׁל הָעוֹלָם הַזֶּה, וְזֶהוּ נֶגֶד בְּנֵי אָדָם, בְּאוֹתָהּ צוּרָה שֶׁל בְּנֵי אָדָם שֶׁבָּעוֹלָם הַזֶּה, וְנִמְצָאִים שָׁם וּפוֹרְחִים בָּאֲוִיר וְעוֹלִים לְתוֹךְ יְשִׁיבַת הָרָקִיעַ בְּאוֹתוֹ גַּן הָעֵדֶן שֶׁלְּמַעְלָה. וּפוֹרְחִים וְרוֹחֲצִים בְּטַלֵּי נַהֲרוֹת אֲפַרְסְמוֹן טָהוֹר, וְיוֹרְדִים וְשׁוֹרִים לְמַטָּה."],[5,"","וְלִפְעָמִים נִרְאִים נֶגֶד בְּנֵי אָדָם לַעֲשׂוֹת לָהֶם נִסִּים כְּמוֹ מַלְאָכִים עֶלְיוֹנִים, כְּמוֹ שֶׁרָאִינוּ עַכְשָׁו אֶת אוֹר הַמָּאוֹר הָעֶלְיוֹן, וְלֹא זָכִינוּ לְהִסְתַּכֵּל וְלָדַעַת בְּסוֹדוֹת שֶׁל חָכְמָה יוֹתֵר."],[6,"","פָּתַח רַבִּי אַבָּא וְאָמַר, (שופטים יג) וַיֹּאמֶר מָנוֹחַ אֶל אִשְׁתּוֹ מוֹת נָמוּת כִּי אֱלֹהִים רָאִינוּ. אַף עַל גַּב שֶׁמָּנוֹחַ לֹא הָיָה יוֹדֵעַ מַה מַּעֲשֵׂהוּ - אָמַר, הוֹאִיל וְכָתוּב (שמות לג) כִּי לֹא יִרְאַנִי הָאָדָם וָחָי, וַדַּאי אָנוּ רָאִינוּ, וּמִשּׁוּם כָּךְ מוֹת נָמוּת. וְאָנוּ רָאִינוּ וְזָכִינוּ לָאוֹר הַזֶּה שֶׁהָיָה הוֹלֵךְ עִמָּנוּ וְנִתְקַיֵּם בָּעוֹלָם, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שָׁלַח אוֹתוֹ אֵלֵינוּ לְהוֹדִיעֵנוּ סוֹדוֹת שֶׁל הַחָכְמָה שֶׁגִּלָּה, אַשְׁרֵי חֶלְקֵנוּ."],[7,"","הָלְכוּ, הִגִּיעוּ לְהַר אֶחָד וְהָיְתָה הַשֶּׁמֶשׁ נוֹטָה. הִתְחִילוּ עַנְפֵי הָאִילָן שֶׁל הָהָר לְהַקִּישׁ זֶה עִם זֶה וְאָמְרוּ שִׁירָה. בְּעוֹדָם הוֹלְכִים, שָׁמְעוּ קוֹל אֶחָד חָזָק שֶׁהָיָה אוֹמֵר: בְּנֵי אֱלֹהִים קְדוֹשִׁים, אוֹתָם שֶׁהִתְפַּזְּרוּ בֵּין הַחַיִּים שֶׁל הָעוֹלָם הַזֶּה, אוֹתָם מְאוֹרוֹת בְּנֵי הַיְשִׁיבָה, הִתְקַבְּצוּ לִמְקוֹמָם לְהִשְׁתַּעֲשֵׁעַ עִם רִבּוֹנְכֶם בַּתּוֹרָה. פָּחֲדוּ אֵלּוּ וְעָמְדוּ בִמְקוֹמָם וְיָשְׁבוּ. בֵּינְתַיִם יָצָא קוֹל כְּמוֹ מִקֹּדֶם וְאָמַר: סְלָעִים חֲזָקִים פַּטִּישִׁים רָמִים, הִנֵּה בַּעַל הַגְּוָנִים מְרֻקָּם בְּצִיּוּרִים עוֹמֵד עַל כִּסֵּא הַשִּׁלְטוֹן, הִכָּנְסוּ וְהִתְקַבְּצוּ."],[8,"","בַּשָּׁעָה הַהִיא שָׁמְעוּ אֶת קוֹל עַנְפֵי הָאִילָנוֹת חָזָק וְתַקִּיף, וְהָיוּ אוֹמְרִים, (תהלים קט) קוֹל ה' שׁוֹבֵר אֲרָזִים. נָפְלוּ עַל פְּנֵיהֶם רַבִּי אֶלְעָזָר וְרַבִּי אַבָּא וּפַחַד רַב נָפַל עֲלֵיהֶם. קָמוּ בְּחִפָּזוֹן וְהָלְכוּ, וְלֹא שָׁמְעוּ דָבָר. יָצְאוּ מִן הָהָר וְהָלְכוּ."]]],[["כַּד מָטוּ לְבֵי רִבִּי יוֹסֵי בְּרִבִּי שִׁמְעוֹן בֶּן לָקוֹנְיָא חֲמוּ לְרִבִּי שִׁמְעוֹן בֶּן יוֹחָאי תַּמָּן. חָדוּ חָדֵי (חדא), רִבִּי שִׁמְעוֹן אָמַר לוֹן וַדַּאי אָרְחָא דְּנִסִּין וְאָתִין עִלָּאִין קָא עֲבַרְתּוּן, דְּאֲנָא דָמִיכְנָא הַשְׁתָּא וְחָמֵינָא לְכוּ וְלִבְנָיָהוּ בֶּן יְהוֹיָדָע דְּקָא מְשַׁדֵּר לְכוּ תְּרֵין עִטְרִין עַל יְדָא דְּחַד סָבָא לְאַעַטְּרָא לְכוּ. וַדַּאי בְּאָרְחָא דָא קוּדְשָׁא בְּרִיךְ הוּא הֲוָה. תּוּ דַּחֲמֵינָא אַנְפַּיְיכוּ מְשַׁנְיָין. אָמַר רִבִּי יוֹסֵי יָאוֹת אֲמַרְתּוּן דְּחָכָם עָדִיף מִנָּבִיא. אֲתָא רִבִּי אֶלְעָזָר וְשַׁוִּי רֵישֵׁי בֵּין בִּרְכּוֹי דְּאֲבוֹי וְסָח (ליה) עוֹבָדָא.","דָּחִיל רִבִּי שִׁמְעוֹן וּבְכָה אָמַר (חבקוק ג׳:ב׳) יְיָ שָׁמַעְתִּי שִׁמְעֲךָ יָרֵאתִי. הַאי קְרָא חֲבַקּוּק אָמַר (אמרו) בְּשַׁעֲתָא דְּחֲמָא מִיתָתֵיהּ וְאִתְקַיָּים עַל יְדָא דֶאֱלִישָׁע. אַמַּאי אִקְרֵי חֲבַקּוּק. בְּגִין דִּכְתִיב, (מלכים ב ד׳:י״ז) לַמּוֹעֵד הַזֶּה כָּעֵת חַיָּה אַתְּ חוֹבֶקֶת בֵּן. וְדָא בְּרֵיהּ (ברה) דְּשׁוּנַמִּית הֲוָה. וּתְרֵין (בשלח מ\"ה ע\"א) חִבּוּקִין הֲווּ, חַד דְּאִימֵיהּ וְחַד דֶּאֱלִישָׁע. דִּכְתִיב, (מלכים ב ד׳:ל״ד) וַיָּשֶׂם פִּיו עַל פִּיו.","אַשְׁכַּחְנָא בְּסִפְרָא דִּשְׁלֹמֹה מַלְכָּא, שְׁמָא גְלִיפָא דְּשִׁבְעִין וּתְרֵין שְׁמָהָן אַגְלִיף עֲלוֹי בְּתֵבִין. בְּגִין דְּאַתְוָון דְּאַלְפָא בֵּיתָא דְּאַגְלִיף בֵּיהּ אֲבוֹי בְּקַדְמִיתָא כַּד מִית פָּרְחוּ מִנֵּיהּ. וְהַשְׁתָּא דֶּאֱלִישָׁע חָבַק לֵיהּ אַגְלִיף בֵּיהּ כָּל אִנּוּן (בשלח נ\"א ע\"ב) אַתְוָון דְּשִׁבְעִין וּתְרֵין שְׁמָהָן. וְאַתְוָון דְּאִילֵין שִׁבְעִין וּתְרֵין שְׁמָהָן גְּלִיפָן אִנּוּן מָאתָן וְשִׁיתְּסַר אַתְוָון.","וְכֻלְהוּ אַתְוָון אַגְלִיף בְּרוּחֵיהּ (נ\"א בדיבורא) אֱלִישָׁע, בְּגִין לְקַיָּימָא לֵיהּ בְּאַתְוָון דְּשִׁבְעִין וּתְרֵין שְׁמָהָן. וּקְרָא לֵיהּ חֲבַקּוּק. שְׁמָא דְּאַשְׁלִים לְכָל סִטְרִין. אַשְׁלִים לַחֲבוּקִין כִּדְאִתְּמַר. וְאַשְׁלִים לְרָזָא דְּמָאתָן וְשִׁיתְּסַר (פקודי רמ\"ו ע\"ב) אַתְוָון דִּשְׁמָא קַדִּישָׁא. בְּתֵבִין אִתְקַיָּים לְאַהֲדָרָא רוּחֵיהּ, וּבְאַתְוָון אִתְקַיָּים כָּל גּוּפֵיהּ עַל קִיּוּמֵיהּ. וְעַל דָּא אִקְרֵי חֲבַקוּק.","וְאִיהוּ אָמַר (חבקוק ג׳:ב׳) יְיָ שָׁמַעְתִּי שִׁמְעֲךָ יָרֵאתִי, שְׁמַעְנָא מַה דְּהֲוָה לִי דְּאַטְעִימְנָא מֵהַהוּא עָלְמָא וְדָחִילְנָא. שְׁרָא לְמִתְבַּע רַחֲמִין עַל נַפְשֵׁיהּ וְאָמַר (נשא קל\"ח ע\"ב) ה' פָּעָלְךָ דְּעֲבַדְתְּ לִי בְּקֶרֶב שָׁנִים יְהוֹן חַיֵּיהוּ. כְּמוֹ חַיָּיו. וְכָל מָאן דְּאִתְקַשַּׁר בְּאִנּוּן שָׁנִים קַדְמוֹנִיּוֹת חַיִּין אִתְקַשְׁרוּ בֵּיהּ. בְּקֶרֶב שָׁנִים תּוֹדִיעַ לְהַהוּא דַרְגָּא דְּלֵית (בה) חַיִּין כְּלַל.","בָּכָה רִבִּי שִׁמְעוֹן וְאָמַר אוּף אֲנָא מִמַּה דְּשָׁמַעְנָא דָּחִילְנָא לְקוּדְשָׁא בְּרִיךְ הוּא. זָקִיף יְדוֹי עַל רֵישֵׁיהּ וְאָמַר וּמַה רַב הַמְנוּנָא סָבָא נְהִירוּ דְאוֹרַיְיתָא זְכִיתוּן אַתּוּן לְמֶחמֵי אַפִּין בְּאַפִּין וְלָא זָכִינָא בֵּיהּ. נָפַל עַל אַנְפּוֹי וְחֲמָא לֵיהּ מְעַקֵּר טוּרִין מַנְהִיר שְׁרָגִין בְּהֵיכְלָא דְּמַלְכָּא מְשִׁיחָא. אָמַר לֵיהּ רִבִּי בְּהַהוּא עָלְמָא תְּהוֹן שְׁבָבִין מָארֵי אוּלְפְּנִין קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא. מֵהַהוּא יוֹמָא הֲוָה קָרֵי לְרִבִּי אֶלְעָזָר בְּרֵיהּ וּלְרִבִּי אַבָּא (ט' א) פְּנִי\"אֵל כְּמָא דְאַתְּ אָמֵר, (בראשית ל״ב:ל״א) כִּי רָאִיתִי אֱלהִים פָּנִים אֶל פָּנִים.","בְּרֵאשִׁית רִבִּי חִיָּיא פָּתַח (תהילים קי״א:י׳) רֵאשִׁית (י\"א ב) חָכְמָה יִרְאַת יְיָ שֵׂכֶל טוֹב לְכָל עוֹשֵׂיהֶם תְּהִלָּתוֹ עוֹמֶדֶת לָעַד. רֵאשִׁית חָכְמָה, הַאי קְרָא הָכִי מִבָּעֵי לֵיהּ, סוֹף חָכְמָה יִרְאַת ה', בְּגִין דְּיִרְאַת ה' סוֹף חָכְמָה אִיהִי. (נ\"א אלא איהי ראשית) לְעָאלָא לְגוֹ דַרְגָא דְּחָכְמְתָא עִלָּאָה הֲדָא הוּא דִכְתִיב, (תהילים קי״ח:י״ט) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק. זֶה הַשַּׁעַר לַה' וַדַּאי, דְּאִי לָא יֵיעוּל בְּהַאי תַּרְעָא לָא יֵיעוּל לְעָלְמִין. לְמַלְכָּא עִלָּאָה דְּאִיהִי (דאיהו) עִלָּאָה וְטָמִיר וְגָנִיז וְעֲבִיד לֵיהּ תַּרְעִין אִלֵּין עַל אִלֵּין","וּלְסוֹף כָּל תַּרְעִין עֲבַד תַּרְעָא חַד בְּכַמָּה מַנְעוּלִין בְּכַמָּה פִּתְחִין בְּכַמָּה הֵיכָלִין אִלֵּין עַל אִלֵּין. אָמַר כָּל מַאן דְּבָעֵי לְמֵיעַל לְגַבָּאי תַּרְעָא דָא יְהֵא קַדְמָאָה לְגַבָּאי, מָאן דְּיֵעוֹל בְּהַאי תַּרְעָא יֵעוּל. אוּף הָכִי תַּרְעָא קַדְמָאָה לְחָכְמָה עִלָּאָה יִרְאַת ה' אִיהִי. וְדָא אִיהִי רֵאשִׁית","ב, תְּרֵין אִנּוּן דְּמִתְחַבְּרִין כְּחֲדָא, וְאִנּוּן תְּרֵין נְקוּדִין, חַד גְּנִיזָא וּטְמִירָא וְחַד קַיָּימָא בְּאִתְגַּלְּיָא. וּבְגִין דְּלֵית לְהוּ פִּירוּדָא אִקְרוּן רִאשִׁית. חַד וְלָא תְּרֵין. מָאן דְּנָטִיל הַאי נָטִיל הַאי. וְכֹלָא חָד דְּהָא הוּא (שמיה) וּשְׁמֵיהּ חַד דִּכְתִיב, (תהילים פ״ג:י״ט) וְיֵדְעוּ כִּי אַתָּה שִׁמְךָ יְיָ לְבַדֶּךָ."],[[0,"","קיד) \u0003כד מטו לבי\u0004 וכו': כשהגיעו לבית ר' יוסי ברבי שמעון בן לקוניא, ראו שם את ר' שמעון בן יוחאי, ושמחו. שמח ר' שמעון. אמר להם, ודאי עברתם דרך של נסים ואותות עליונים. כי עתה אני ישנתי, וראיתי אתכם ואת בניהו בן יהוידע, שמשלח לכם שתי עטרות, על ידי זקן אחד, לעטר אתכם. ודאי, בדרך זה היה הקב\"ה. עוד, כי אני רואה את פניכם משונים. א\"ר יוסי, יפה אמרתם, שחכם עדיף מנביא. בא ר' אלעזר, ושם ראשו בין ברכי אביו ר' שמעון, וספר לו את המעשה."],[0,"","פירוש. זה רומז לב' ענינים: א) שזכו מחדש והשיגו המוחין דס\"ג, שהם בחינת \u0003חמוי\u0004 דרבי אלעזר (כנ\"ל אות פ\"ה ד\"ה נחתו), הנק' \u0003ר\"י ברשב\"ל\u0004. ב) כי עתה נתחבר להם הס\"ג עם הע\"ב יחד בזווג דלא פסיק. כי אביו של רבי אלעזר שהוא רבי שמעון רומז על מוחין דע\"ב. וז\"ש, \u0003כד מטו לבי ר' יוסי ברשב\"ל חמו לרבי שמעון בן יוחאי תמן\u0004, כי עתה זכו לבחינה הגדולה שהב\"ן שלהם שב להיות ס\"ג ממש לנצחיות, גם בזווג דלא פסיק עם הע\"ב."],[0,"","וז\"ש, \u0003דקא משדר לכון תרין עטרין על ידא דחד סבא\u0004: רמז להם, כי \u0003בניהו בן יהוידע\u0004 שלח להם ע\"י רב המנונא סבא, \u0003תרין עטרין\u0004, א) הם מוחין דיחידה, דהיינו בחינת \u0003בניהו בן יהוידע\u0004 עצמו, ב) בחינת מוחין של ע\"ב ס\"ג החדשים שהשיגו עתה, אשר גם הם נמשכו בכוחו של בניהו בן יהוידע."],[0,"","כלומר, רמז ואמר להם: זה ההמשך של הנסיונות וההרפתקאות שהיו לכם, שעל ידיהם זכיתם למדרגה של עתה, הלא גם הוא המשכה ישרה מהאור הגדול של נשמתו. ונמצא ע\"כ ש\u0003תרין עטרין\u0004 שלח להם בניהו בן יהוידע ע\"י רב המנונא סבא. וזה אמרו \u0003ודאי בארחא דא קב\"ה הוה\u0004 כלומר, אמר להם, שכל אלו הנפילות שארעו לכם אינם ח\"ו פגמים, אלא \u0003קב\"ה\u0004 עצמו הוביל אתכם אל מעלתכם הגבוהה של עתה."],[0,"","וז\"ש, \u0003תו דחמינא אנפייכו משניין\u0004, נוסף על זה שהשגתם, אני רואה את פניכם מזהירות ביותר מכח ה\u0003אורחא דא\u0004 שהלכתם, ואם היה בו איזה פגם ח\"ו, ודאי שלא הייתם זוכים לפנים מאירות כמו שאני רואה אתכם."],[0,"א\"ר יוסי יאות אמריתון דחכם עדיף מנביא",": כי הם חשבו שע\"כ קרו להם כל הני הרפתקאות משום שהזיחו דעתם על משה רבינו, שחשבו על עצמם, חכם עדיף מנביא, כי אמרו \u0003אנן חמינן וזכינן לנהורא דא דהוה אזיל בהדן ונתקיים בעלמא\u0004. (עי' לעיל אות קי\"א) וע\"ז נחם אותם ר\"י, \u0003יאות אמרתון דחכם עדיף מנביא\u0004 כנים דבריכם."],[1,"","קטו) \u0003דחיל רבי שמעון\u0004 וכו': פחד ר' שמעון ובכה, אמר, ה' שמעתי שמעך יראתי. מקרא זה אמר חבקוק, בשעה שראה מיתתו, ואת התחיה שלו על ידי אלישע. למה נקרא חבקוק. הוא בשביל שכתוב, למועד הזה כעת חיה את \u0003חובקת\u0004 בן. כי זה, חבקוק, היה בנו של השונמית. ושני חבוקים היו, אחד של אמו, ואחד של אלישע, שכתוב, וישם פיו על פיו."],[1,"","ביאור הדברים, דלכאורה יש לשאול, איך יתכן שאלישע הנביא ימשיך לשונמית בברכתו זרע שאינו של קיימא. והענין הוא, כי אלישע הנביא היה גדול מכל הנביאים לבר ממשה. (כמ\"ש הזוהר בשלח אות ב'). והוא זכה לבחינת הנשמות מג\"ע העליון, שהב\"ן שלהן היה כבר בתכלית הטהרה והשלמות כמו לע\"ל. ולפיכך בעת שהמשיך לה הבן לא נזהר לקשרו בעלמא דדכורא, כי אמר לה \u0003את חובקת בן\u0004, וקשר את החבוק בסטרא דנוקבא לבדה, ומתוך שהנוקבא שהיא הב\"ן קרובה לקליפות וס\"א, ע\"כ נאחז בו הס\"א ומת."],[1,"","ונמצא שסבת המיתה אינה אלא מטעם רוממותו הנשגבה של הנביא, להיות הב\"ן שלו עצמו כבר נקי מכל אחיזת הס\"א והמיתה, וזה שהתפלא הנביא (מלכים ב' ד' כ\"ז) וה' העלים ממני ולא הגיד לי. כלומר שלא היה לו מקום אפילו להעלות שיתכן שתארע בו מיתה מחמת התקשרותו בב\"ן לבדו. ולפיכך היה צריך לחזור ולהחיותו ולקשרו בעלמא עלאה בסוד תחית המתים כמו שיתבאר לפנינו."],[1,"","וסוד החיבוק הוא, כי עצם הולד הוא הלובן שבו, שמאבא (נדה לא. ), שה\"ס חכמה, כי החכמה נקראת בשם לובן, כנודע, וה\"ס כולם בחכמה עשית (תהלים ק\"ד). אמנם ללבוש חסדים צריך, כי אין מציאות לחכמה בלי לבוש חסדים. וע\"כ צריכים לבחינת האודם דאמא, שה\"ס המסך הממשיך חסדים להלביש החכמה. ונבחן שע\"י החיבוק של החסדים לחכמה נמשך ומתקיים הולד. וז\"ש \u0003ודא בריה דשונמית הוה\u0004 כלומר, החיבוק הזה דחסדים בחכמה, שנעשה על הולד, היה כולו מאמו השונמית, דהיינו מסטרא דב\"ן בלבד."],[1,"","וז\"ש, \u0003ותרין חבוקין הוו, חד דאימיה וחד דאלישע\u0004: כי בעת שהחיה אותו, היה ממשיך לו בחינת לובן ואודם מחדש, ונמצא שאלישע עשה לו חיבוק שני, הרי \u0003שתרין חיבוקין\u0004 היו לו, \u0003חד דאימיה וחד דאלישע\u0004."],[2,"","קטז) \u0003אשכחנא בספרא דשלמה\u0004 וכו': מצאתי בספרו של שלמה המלך, שהשם החקוק של שבעים ושנים שמות, חקק אלישע עליו, על חבקוק, במלים. שכל מלה מצורפת משלש אותיות, (כמ\"ש בזהר פרשת בשלח אות קע\"ג בציור האחרון ע\"ש) משום שאותיות האלף בית שחקק בו אביו בתחילה, פרחו ממנו כשמת, ועתה שאלישע חיבק אותו, חקק בו כל אלו האותיות שבע\"ב שמות. והאותיות החקוקות של אלו ע\"ב שמות, הם מאתים ושש עשרה אותיות. דהיינו ג' אותיות בכל שם."],[2,"","פירוש. כי האותיות שמהן נבנה הולד, הן \u0003רי\"ו\u0004 אותיות, והם בחינת הארת החכמה הנמשכת מישסו\"ת. ואז נבחן הולד שיש בו \u0003רי\"ו\u0004 אותיות שהן בגי' \u0003ראי\"ה\u0004 דהיינו אור העינים שהוא חכמה. ובעת הגדלות שמקבל לבוש דחסדים מעלמא עלאה מאו\"א ורי\"ו מתלבשות בהם, אז נקרא בשם \u0003ע\"ב תבין\u0004, שכל ג' אותיות מהן מתחברות בתיבה אחת, והן \u0003ע\"ב תבין\u0004."],[2,"","ובעת שאין לו חסדים להתלבשות רק מעלמא תתאה, הוא נבחן ל\u0003רי\"ו אתוון\u0004, וכשמשיג הע\"ב דכורא, כלומר את החסדים מעלמא עלאה, מתחברות אז כל ג' אותיות לתיבה אחת, וה\"ס שם \u0003ע\"ב\u0004, וזה אמרו \u0003שמא גליפא דע\"ב שמהן אגליף עלוי בתבין\u0004 כי אלישע בעת שהחיה את בן השונמית, שהוא חבקוק, חקק בו \u0003ע\"ב תבין\u0004 מ\u0003רי\"ו אתוון\u0004, כי המשיך בו החסדים דעלמא עלאה, הנקרא \u0003ע\"ב\u0004 דכורא, המסדרין את \u0003רי\"ו אתוון\u0004 בתיקון קוין של שלש שלש אותיות בכל תיבה, וכשהאותיות מתלבשות בהן ה\"ס שם \u0003ע\"ב\u0004, שהוא מוחין דחכמה בשלמות."],[2,"","אבל מקודם לכן בעת שלא היה לו אלא החסדים דנוקבא, עדיין הם חסרי הצירוף של \u0003ע\"ב תבין\u0004, כלומר, שאין בהם תבין דהיינו כלים להתלבשות חכמה, ונקרא רק בשם \u0003רי\"ו\u0004 אותיות לבד, כי עדיין יש בהם אחיזה לס\"א. וע\"כ לא יכלו המוחין דחכמה להתלבש שם."],[2,"","וז\"ש, \u0003בגין דאתוון דא\"ב\u0004 וכו', כי אלו \u0003רי\"ו אתוון\u0004 שהיו לו לחבקוק מעת לידתו \u0003פרחו\u0004 ונסתלקו \u0003מניה\u0004 בשעת המיתה ולפיכך היה צריך להמשיך לו רי\"ו אתוון וע\"ב שמהן מחדש, וז\"ש \u0003וכלהו אתוון אגליף ברוחיה אלישע, בגין לקיימא ליה באתוון דע\"ב שמהן\u0004, כי היה צריך לחקוק בו רי\"ו אתוון מחדש, בכדי לצרף רי\"ו אתוון לע\"ב תבין, ע\"י החסדים העליונים, שאז נעשים ל\u0003ע\"ב שמהן\u0004."],[3,"","קיז) \u0003וכלהו אתוון אגליף\u0004 וכו': וכל האותיות האלו חקק אלישע, ברוחו של חבקוק, בשביל להחיות אותו באותיות של ע\"ב שמות. וקרא אותו חבקוק. שהוא שם המשלים ומרמז לכל הצדדים, כי משלים ומרמז על שני חבוקים, כמו שאמרתי, ומשלים ומרמז לסוד מאתים ושש עשרה אותיות, של השם הקדוש, כי חבקוק בגי' מאתים ושש עשרה, שמהם נצטרפו ע\"ב שמות כנ\"ל. בע\"ב תיבות החיה והשיב רוחו, וברי\"ו אותיות החיה כל גופו על קיומו. וע\"כ נקרא חבקוק."],[3,"","פירוש. כי \u0003חבקוק\u0004 מורה על \u0003ב' חבוקין\u0004, והיינו \u0003דאשלים לחבוקין\u0004, גם \u0003חבקוק\u0004 בגי' \u0003רי\"ו\u0004, והיינו \u0003אשלים לרזא דרי\"ו אתוון\u0004, והביאור הוא, כי החכמה נקראת \u0003רזא דרי\"ו אתוון\u0004, אמנם צריכים לחבוק, דהיינו להתלבשות חסדים כנ\"ל, ובחבוק הראשון שהיה מסטרא \u0003דאמיה\u0004, עוד לא היתה החכמה יכולה להתגלות ב\u0003רי\"ו אתוון\u0004, כי הס\"א היתה לה אחיזה באודם \u0003דאמיה\u0004, אלא עתה ש\u0003אלישע\u0004 המשיך לו חבוק מחסדים דעלמא עלאה, דאו\"א, נצטרפו האתוון לתבין, ומוחין דחכמה נתלבשו בתבין בקביעות, כי בחסדים דעלמא עלאה אין אחיזה עוד לס\"א."],[3,"","והשם \u0003חבקוק\u0004, מורה על \u0003ב' חבוקין\u0004 שהוא על חבוק \u0003דאמיה\u0004, ועל חבוק הנוסף בו מ\u0003אלישע\u0004, והוא נשלם מ\u0003כל סטרין\u0004, הן מחכמה בכל השלמות, והן מחסדים בכל השלמות, וז\"ש \u0003אשלים לחבוקין, ואשלים לרזא דרי\"ו אתוון\u0004, חבוקין הם החסדים דאו\"א, ו\u0003רזא דרי\"ו\u0004 הוא החכמה."],[3,"","וז\"ש, \u0003בתבין אתקיימא לאהדרא רוחיה, ובאתוון אתקיים כל גופיה על קיומיה\u0004: כי התבין שנצטרפו מ\u0003רי\"ו אתוון\u0004 נעשו ע\"י החבוק הב' של \u0003אלישע\u0004, שע\"י החבוק הזה חזר לתחיה, שהם המשכת החסדים מעלמא עלאה, שאין שם אחיזה לס\"א שהוא המיתה. וב\u0003רזא דרי\"ו אתוון\u0004 נתקיימה בו החכמה, שהיא קיום כל גופו על קיומו, כי מוחין דחכמה משלימים את הגוף בכל השלמות הרצויה."],[3,"","ויש לשאול, הרי \u0003רי\"ו אתוון\u0004 שהיו לו מלידתו \u0003פרחו מניה\u0004 בעת המיתה, וא\"כ למה נקרא \u0003חבקוק\u0004 על שם \u0003ב' חבוקין\u0004 הרי החבוק דאמיה פרח מניה בעת המיתה, ואין בו אלא החבוק של \u0003אלישע\u0004. והענין הוא, כי באמת לא המשיך בו \u0003אלישע\u0004 בעת תחיתו שום דבר חדש מלבד בחינת החבוק שהמשיך לו מאמא עלאה ס\"ג, שבה סוד תחית המתים, אבל \u0003רי\"ו אתוון\u0004 גם בחינת החבוק \u0003דאמיה\u0004 מב\"ן, הנה הן רק חזרו לתחיה, והן אותן רי\"ו ובחינת הב\"ן, מבעת שנולד, דאל\"כ היה כולו נשמה חדשה ולא יתכן לומר בו ענין תחיה."],[3,"","ונמצא שיש לו עתה \u0003ב' חבוקין\u0004 ממש, כי גם חבוק ראשון \u0003דאמיה\u0004 חזר לתחיה, אלא ה\"ס, שהב\"ן עלה והלביש הס\"ג, וכיון שהב\"ן הוא במקום הס\"ג, ע\"כ נבחנים החסדים שהם מעלמא עלאה, ואין בהם אחיזה לס\"א שהוא המיתה. וע\"כ נקרא \u0003חבקוק\u0004 על שם \u0003ב' חבוקין\u0004."],[4,"","קיח) \u0003ואיהו אמר ה'\u0004 וכו': והוא אמר ה' שמעתי שמעך יראתי. שפירושו, שמעתי מה שהיה לי, שטעמתי מעולם ההוא, דהיינו, בעת מיתתו, ומקודם שהחיה אותו אלישע, ויראתי. התחיל לבקש רחמים על נפשו, ואמר, \u0003ה' פעלך\u0004 שעשית לי \u0003בקרב שנים\u0004 יהיו חייו, כי \u0003חייהו\u0004, פירושו כמו חייו. וכל מי שמתקשר באלו שנים קדמוניות שהן ספירות דעתיק, מתקשרים בו החיים. \u0003בקרב שנים תודיע\u0004, היינו להשפיע חיים לאותה מדרגה שאין בה חיים, שהיא מלכות דמלכות כי תודיע פירושו תשפיע."],[4,"","פירוש. שהיראה שלו היא מהזמן שעבר, כי כבר נעשה שלם מכל סטרין ולא שייכת בו עתה יראה, אלא שהיראה שלו היא מהזמן שעבר, דהיינו ממה דהוה לו בעת שנפטר מהעולם. וז\"ש \u0003שמענא מה דהוה לי דאטעימנא מההוא עלמא\u0004, דהיינו לאחר פטירתו, ומקודם שהחיה אותו \u0003אלישע\u0004. ומשם ממשיך גם עתה יראה שתהיה לו לבחינת מסך להעלות מ\"ן. וז\"ש \u0003שרא למתבע רחמין על נפשיה\u0004, דהיינו בכח היראה מהזמן שעבר, התחיל להעלות מ\"ן, שה\"ס בקשת רחמים על עצמו."],[4,"","וכן הוא סוד המסך שלעתיד, בסוד אחר שהב\"ן ישוב להיות ס\"ג, כי אז יהיה כבר בלע המות לנצח (ישעיה כ\"ה), ולא יהיה שום כח שיתכן ליראה ולהחזיק עצמו בטהרה ולהשמר מאיזו אחיזה, וכל בחינת היראה, תהיה אז מכח הזמן שעבר. שרשימותיו ישארו בב\"ן גם אחר שנעשה לס\"ג. והענין הזה הכרח הוא, כי אין תיקון המסך בלי יראה. ועל הסוד הזה אמר להם ר\"ש את הדרוש הזה דחבקוק, ללמדם שגם הם יקבלו יראה מהאי אורחא דנסין ואתין עלאין דעברו ביה, דהיינו כמו חבקוק לפי מדרגתו, שהשתמש ביראה הזו."],[4,"","וז\"ש, \u0003פעלך דעבדת לי בקרב שנים יהון חייהו\u0004: כי היו לו ב' בחינות \u0003שנים, שנים\u0004 מקודם מיתתו, ו\u0003שנים\u0004 לאחר ששב לתחיה, שביניהם היה נפטר בעולם האמת, ועל הזמן ההוא שהיה בההוא עלמא, שהם \u0003בקרב\u0004 ב' בחי' ה\u0003שנים\u0004, אומר, \u0003פעלך\u0004 שעשית לי בהם \u0003יהון חייהו\u0004, כלומר ע\"י שאני זוכר זמן מיתתי ש\u0003בקרב השנים\u0004 אני מתקשר בחיים של עלמא עלאה, שבהם החיה אותי \u0003אלישע\u0004, (כמ\"ש לעיל בסמוך). \u0003שמענא מה דהוה לי דאטעימנא מההוא עלמא ודחילנא\u0004 ע\"ש."],[4,"","והנה הז\"ת דעתיק נקראות \u0003שנים קדמוניות\u0004, והוא מבחינת מה שהמלכות דאדם קדמון מתלבשת בהן, והן \u0003קדמוניות\u0004 מצמצום א', כמו אדם קדמון. והן אינן מאירות בשתא אלפי שני, אלא בגמר התיקון, כי בשתא אלפי שני, מאירות ז\"ת דעתיק מבחינת התיקון דצמצום ב', בסוד ה' זעירא דהבראם, כנודע."],[4,"","אמנם \u0003חבקוק\u0004, מיתתו טהרה אותו לגמרי כמו בגמר התיקון, וע\"כ זכה לאתקשר באינון שנים קדמוניות דעתיק בכח החבוק ותחית המתים שזכה על ידי \u0003אלישע\u0004. וז\"ש \u0003פעלך דעבדת לי בקרב שנים\u0004, דהיינו הטהרה והיראה שזכה \u0003בקרב שנים\u0004 בעת מיתתו, \u0003יהון חייהו\u0004, שמכח היראה הזו, יזכה להתקשר באינון \u0003שנים קדמוניות\u0004 דעתיק, שהחיים האלו הם חיים נצחיים. וז\"ש \u0003וכל מאן דאתקשר באינון שנים קדמוניות חיין אתקשרו ביה\u0004 כי נקשרו בו החיים לנצח."],[4,"","וז\"ש \u0003בקרב שנים תודיע, לההוא דרגא דלית בה חיין כלל\u0004, כי ע\"י הטהרה שזכה בסבת מיתתו קבל הב\"ן את תיקונו השלם, שעלה ונעשה ס\"ג בעת מיתתו כנ\"ל, ואז נמצא לההיא דרגא דלית בה חיין כלל, שהוא המלכות דמלכות, שאין בשבילה שום זווג קודם גמר התיקון (כנ\"ל אות מ\"ג ד\"ה חד), הנה עתה מקבל גם ה\u0003דרגא\u0004 ההיא החיים שלה."],[5,"","קיט) \u0003בכה רבי שמעון\u0004 וכו': בכה ר\"ש ואמר. אף אני יראתי מהקב\"ה ממה ששמעתי. נשא ידיו על ראשו, ואמר, והרי ר' המנונא סבא אור התורה, אתם זכיתם לראותו פנים בפנים, ואני לא זכיתי בו. נפל על פניו. וראה אותו עוקר הרים, ומדליק נרות בהיכל מלך המשיח. אמר לו, רבי, בעולם ההוא תהיו שכנים לראשי הישיבות לפני הקב\"ה. מיום ההוא והלאה, היה קורא לרבי אלעזר בנו ולר' אבא, \u0003פניאל\u0004. כמו שכתוב, כי ראיתי אלקים פנים אל פנים."],[5,"","פירוש. שיבח את עצמו, שגם הוא משמש באותה היראה של חבקוק הנביא, דהיינו מבחינת \u0003ממה דשמענא\u0004, מהזמן שעבר, בסו\"ה \u0003שמעתי שמעך יראתי\u0004 (כמ\"ש לעיל בסמוך בד\"ה שמענא מה דהוה לי ע\"ש)."],[5,"","והנה בהיכל המלך המשיח, כבר מוכנים ומזומנים כל התיקונים הצריכים להתגלות בגמר התיקון עם ביאת המלך המשיח, אף פרט קטן לא יחסר. ואלו הנשמות שבהיכל המלך המשיח, הן כל אלה שכבר זכו לגמר התיקון מבחינת שורש נשמתם עצמם."],[5,"","וז\"ש \u0003וחמא ליה מעקר טורין מנהיר שרגין בהיכלא דמלכא משיחא\u0004, כי \u0003רב המנונא סבא\u0004 הוא מארי דתקונים הללו שבהיכל המשיח, דהיינו \u0003לעקר טורין\u0004 דס\"א, בסוד שנדמה לצדיקים כהר גבוה (סוכה נב. ) והוא \u0003מנהיר שרגין\u0004 דהיינו מתקן את המסך החדש מבחינת הס\"ג להעלאת מ\"ן בגמר התיקון, כי סוד המ\"ן נק' מאורי האש, וה\"ס נר ה' נשמת אדם (משלי כ'). כי אור השמש מורה על ירידת המ\"ד, דוגמת אור השמש היורד אלינו ממעלה למטה. ומאורי אש ה\"ס או\"ח העולה ממטה למעלה, כמו שלהבת העולה מן הנר."],[5,"","וז\"ש שב' התיקונים הללו, להעביר הס\"א, ולהעלות ולאנהיר הנרות \u0003בהיכלא דמלכא משיחא\u0004, הם בידיו \u0003של רב המנונא סבא\u0004, ואלו צדיקים גמורים הצריכים לאלו ב' התיקונים, אינם זוכים בהם כי אם ע\"י גילוי \u0003נשמת רב המנונא סבא\u0004. ובישר לו כי גם הוא ותלמידיו ר\"א ורבי אבא יזכו לאחר פטירתם לשמש שם בהיכל המלך המשיח, ויהיו שכנים לו שם, ויהיו שם \u0003מארי אולפנין\u0004, דהיינו רישי מתיבתא \u0003קמי קב\"ה\u0004."],[6,"","קכ) \u0003בראשית. ר' חייא\u0004 וכו': בראשית. ר\"ח פתח ראשית חכמה יראת ה' שכל טוב לכל עושיהם תהלתו עומדת לעד(תהילים, קיא, י). ראשית חכמה. שואל, מקרא זה היה צריך לומר סוף חכמה יראת ה', כי יראת ה', ה\"ס מלכות; שהיא סוף חכמה. ומשיב, אלא היא, המלכות ראשית להכנס לתוך מדרגת החכמה העליונה. ז\"ש, פתחו לי שערי צדק דהיינו שערי המלכות שנקראת צדק, זה השער לה'. ודאי אם לא יכנס בשער הזה, לא יכנס אל המלך העליון לעולם, כי הוא עליון ונסתר וגנוז, ועשה לו שערים, אלו על אלו."],[6,"","ביאור הדברים. כי מקשה, הרי \u0003יראת ה'\u0004 היא ספירת המלכות שהיא בסיום ע\"ס, וע\"כ היה לומר \u0003סוף חכמה יראת ה'\u0004. ואומר, \u0003למלכא עלאה דאיהי עלאה וטמיר וגניז\u0004 וכו': אין זה משל אלא הוא הנמשל עצמו. פירוש כי בהיותו \u0003מלכא עלאה וטמיר וגניז\u0004 ולית מחשבה תפיסה ביה כלל, לפיכך עביד שערים רבים \u0003אלין על אלין\u0004, אשר בסגולתם עשה האפשרות להתקרב לפניו ית'. וה\"ס הכתוב פתחו לי שערי צדק (תהלים קי\"ח). שהמה השערים שעשה ה' ונתן אפשרות לצדיקים שיבואו לפניו דרך אותם השערים."],[6,"","ואמר, \u0003ולסוף כל תרעין עבד תרעא חד בכמה מנעולין\u0004 וכו', והיינו השער הנק' מלכות דמלכות, שהוא נקודה דסיומא דכלהו שערים עלאין, והשער הזה האחרין הוא השער הראשון \u0003לחכמה עלאה\u0004. כלומר, שאי אפשר לזכות לחכמה העליונה זולת אחר השגת השער הזה האחרון דוקא, כי להשגת \u0003חכמה עלאה\u0004 הוא השער הראשון, ועל סוד זה, כתוב \u0003ראשית חכמה יראת ה'\u0004 (תהלים קי\"א), כי יראת ה' מכונה דוקא השער האחרון, שהוא הראשון לחכמת ה'."],[7,"","קכא) \u0003ולסוף כל תרעין\u0004 וכו': ולסוף כל השערים, עשה שער אחד בכמה מנעולים, בכמה פתחים, בכמה היכלות, אלו על אלו. אמר, כל מי שרוצה להכנס אלי, השער הזה יהיה הראשון, אלי. מי שנכנס, דרך השער הזה יכנס. אף כאן, השער הראשון לחכמה העליונה הוא, יראת ה'. שהיא מלכות. וזה הוא שנקרא ראשית."],[7,"","פירוש. יש להבין היטב מהו \u0003מנעולין\u0004, ומהו \u0003פתחין\u0004, ומהו \u0003היכלין\u0004, ותדע, שהם ג' צורות הבאות בזו אחר זו על חומר אחד. והוא ענין עמוק ביותר, ואתאמץ לבארו לפי היכולת שתספיק להבין באפס מה מדברי הזוהר שלפנינו, ויש לדעת, שהגם שזה ברור דלית מחשבה תפיסא ביה כלל וכלל, הנה האמת היא, כי מחשבת הבריאה היא להנות לנבראיו, ואין שום הנאה מובנת לנברא אם היותו מחויב ח\"ו להיות בפרודא מהבורא ית'. ולא עוד אלא שאמרו חז\"ל נתאוה הקב\"ה לדור בתחתונים."],[7,"","והצד השוה להבין ב' ענינים אלו המכחישים זה את זה, הוא, כי העולם נברא בהפך גמור מהשי\"ת מהקצה אל הקצה בכל מאת הנקודות, כי העוה\"ז נברא בבחינת הרצון לקבל, שהוא צורה הפוכה כלפי השי\"ת, שאין בו מרצון זה אפילו משהו. וז\"ס עייר פרא אדם יולד (איוב י\"א). ומבחינה זו, נמצאים לנו כל עניני ההנהגה מהשגחתו ית' בעוה\"ז בסתירה גמורה לקוטב מחשבה הבריאה, שהיא רק להנות לנבראיו, כי כן הוא לפי הרצון לקבל שבנו שהוא הטעימה, ואמת המידה שלנו."],[7,"","וז\"ס \u0003המנעולין\u0004 שעל השערים. כי באמת כל ריבוי הסתירות נגד יחודו ית' שאנו טועמים בעוה\"ז, אף על פי שמתחילתן הן מפרידות אותנו מהש\"י, הנה בהיותינו מתאמצים לקיים התורה והמצות באהבה בכל נפשנו ומאדנו כמצוה עלינו, דהיינו ע\"מ להשפיע נ\"ר ליוצרנו, וכל אלו כוחות הפירוד אינם משפיעים עלינו לגרוע משהו מאהבת ה' בכל נפשנו ומאדנו אז כל סתירה וסתירה שהתגברנו עליה, נעשית שער להשגת חכמתו ית', כי כל סתירה יש בה סגולה מיוחדת לגלות מדרגה מיוחדת בהשגתו ית'. ואלו הזכאים שזכו לזה נמצאים מהפכים חשוכא לנהורא, ומרירא למתקא, כי כחות הפירוד כולם, הן מבחינת חשכת השכל, והן מבחינת מרירות הגוף, נעשו להם שערים להשגות מדרגות נשגבות, ונעשה החושך לאור גדול, והמר נעשה מתוק."],[7,"","באופן, שבשיעור הזה שהיה להם מקודם לכן כל הנהגות השגחתו ית' לבחינת כחות דפרודא, נתהפכו להם עתה כולם לבחינת כחות דיחודא, ונמצאים מכריעים את כל העולם כולו לכף זכות, כי כל כח וכח משמש להם עתה \u0003לשערי צדק\u0004, שדרכם יבואו לקבל מהש\"י, כל מה שחשב עליהם להנותם במחשבת הבריאה, וזה השער לה' צדיקים יבואו בו (תהלים קי\"ח)."],[7,"","אמנם, מטרם שזוכים להפך בחינת הרצון לקבל שבנו, ע\"י תורה ומצות, לקבלה ע\"מ להשפיע, נמצאים מנעולין חזקים על אותם השערים לה', כי אז יש להם תפקיד הפוך, דהיינו להרחיק אותנו מהש\"י, ע\"כ נקראים אלו הכחות דפרודא בשם \u0003מנעולים\u0004, כי סותמים את שערי ההתקרבות ומרחיקים אותנו מהש\"י. אבל אם אנו מתגברים עליהם, שלא ישפיעו עלינו לצנן אהבתו ית' מלבנו, הנה אז נהפכים \u0003המנעולים\u0004 ונעשים \u0003פתחין\u0004, והחושך נהפך לאור, והמר למתוק כנ\"ל. והוא, משום שעל כל מנעול ומנעול מקבלים אנו מדרגה מיוחדת בהשגחתו ית' ונעשים ל\u0003פתחים\u0004, למדרגות של השגה בו ית', ואלו המדרגות שאנו מקבלים על \u0003הפתחים\u0004 נעשו \u0003להיכלות\u0004 החכמה."],[7,"","הרי איך שה\u0003מנעולים\u0004 ה\u0003פתחין\u0004, וה\u0003היכלין\u0004, הם ג' צורות העוברות על חומר אחד שלנו, דהיינו על הרצון לקבל שבנו, שמטרם שאנו הופכים אותו לקבלה ע\"מ להשפיע נ\"ר ליוצרנו, הופך החומר הזה לפי הטעם שלנו, את האור לחושך, ואת המתוק למר. כי כל הנהגות השגחתו ית' מרחיקות אותנו ממנו, ובעת ההיא נעשה מהרצון לקבל שבנו בחינת \u0003מנעולים\u0004. ואחר תשובתנו שזוכים אנו לקבלה ע\"מ להשפיע, נעשו כל ה\u0003מנעולים\u0004 ל\u0003פתחין\u0004, ואח\"כ נעשו ה\u0003פתחין\u0004 ל\u0003היכלין\u0004 כמבואר. וזכור זאת היטב לכל ההמשך כי לא אכפיל הדברים."],[7,"","ומ\"ש \u0003אמר כל מאן דבעי למיעל לגבאי, תרעא דא יהא קדמאה לגבאי\u0004: כבר ידעת היטב ענין התרעין כמ\"ש בסמוך. וענין \u0003סוף כל תרעין\u0004, פירושו בחינה אחרונה שבהם, שאין עוד שפלה הימנה, ואפשר לכנותה מלכות דמלכות. ואומר שכדי לזכות \u0003בחכמה עלאה\u0004 נעשה זה השער האחרון מכולם, אל השער הראשון להיכל \u0003החכמה עלאה\u0004. כי באמת כל השערים כולם משמשים \u0003לפתחין והיכלין\u0004 של חכמת ה', אמנם \u0003חכמה עלאה\u0004, אי אפשר להשיג זולת בהשגת השער האחרון דוקא, כי \u0003להחכמה עלאה\u0004 הוא הראשון."],[7,"","וז\"ש \u0003ודא איהי ראשית\u0004: היינו \u0003בראשית\u0004 שבו פתח התורה, כי \u0003בראשית\u0004 מורה על \u0003יראת ה'\u0004 מבחינת השער האחרון, שהוא \u0003ראשית\u0004 להשגת \u0003חכמה עלאה\u0004."],[8,"","קכב) \u0003ב', תרין אינון\u0004 וכו': ב' מבראשית, מורה, ששנים הם המתחברים יחד, במלכות, והם שתי נקודות, אחת גנוזה ונסתרת, ואחת נמצאת בגלוי. ומשום שאין להן פירוד, נקראות ראשית, דהיינו רק אחת ולא שתים, כי מי שלוקח את זו, לוקח גם את זו, והכל אחת, כי הוא ושמו אחד, שכתוב, וידעו כי אתה שמך ה' לבדך."],[8,"","ביאור הדברים, תרין נקודין הללו, ה\"ס המיתוק דמדת הדין במדת הרחמים, שמלכות עלתה ונמתקה בבינה, שהיא מדת הרחמים, בסו\"ה ותלכנה שתיהן (רות א'). שה\"ס בינה ומלכות יחדיו, (כמ\"ש בזהר פנחס אות נ\"ח ובכ\"מ). ונמצא המסך שנתקן במלכות כלול משתיהן, וע\"כ יש שם \u0003ב' נקודות\u0004 מחוברין כחדא. וז\"ש \u0003חד גניזא וטמירא, וחד קיימא באתגליא\u0004 כי בחינת הדין שבנקודת המלכות \u0003גניזא וטמירא\u0004, ורק בחינת הרחמים שהיא מנקודת הבינה היא \u0003דקיימא באתגלייא\u0004. כי לולא זה לא היה העולם יכול להתקיים, כמ\"ש חז\"ל בתחילה נברא העולם במדת הדין ראה שאין העולם מתקיים שיתף עמו מדת הרחמים (ב\"ר פ\"א)."],[8,"","וז\"ש, \u0003ובגין דלית להו פרודא אקרון ראשית חד ולא תרין, מאן דנטיל האי נטיל האי\u0004: כלומר, אע\"פ שמדת הדין היא \u0003בגניזא\u0004, אין הפירוש שאין הזווג נעשה עליה, כי אלו ב' הנקודות נעשו אחת ממש, וגם נקודת המלכות מקבלת הזווג עם נקודת הבינה, אלא בחשאי ולא \u0003באתגליא\u0004 ועל זה מורה השם \u0003ראשית\u0004, שהיא לשון יחיד, ששתיהן הן אחת."],[8,"וכלא חד דהא הוא ושמיה חד: הוא","מורה על הבינה, \u0003ושמיה\u0004 מורה על המלכות. ואומר שבסוד \u0003הוא ושמו אחד\u0004 מחויבות שתיהן להיות אחת, כי בהיותן אחת, מקבלת גם המלכות את הזווג העליון יחד עם הבינה, שעי\"ז נמתקת לבסוף גם מדת הדין בפני עצמה בגמר התיקון, אשר ביום ההוא יהיה ה' אחד ושמו אחד."],[8,"","ועל שם מדת הדין הזו הכלולה ב\u0003ב'\u0004 ד\u0003ב\u0004ראשית, היא נקראת \u0003ראשית\u0004 אל החכמה, שתיקונה יהיה בגמר התיקון ואז תתגלה \u0003חכמה עלאה\u0004, ומלאה הארץ דעה את ה' (ישעיה י\"א). כי היא השער האחרון שהוא השער הראשון אל החכמה. וזהו שמביא הכתוב \u0003וידעו\u0004 כי אתה שמך ה' (תהלים פ\"ג). כי אז תתגלה הדעת בכל הארץ."]],[[0,"","כְּשֶׁהִגִּיעוּ לְבֵית רַבִּי יוֹסֵי בֶּן רַבִּי שִׁמְעוֹן בֶּן לָקוֹנְיָא, רָאוּ שָׁם אֶת רַבִּי שִׁמְעוֹן בֶּן יוֹחַאי. שָׂמְחוּ. שָׂמַח רַבִּי שִׁמְעוֹן וְאָמַר לָהֶם, וַדַּאי דֶּרֶךְ שֶׁל נִסִּים וְאוֹתוֹת עֶלְיוֹנִים עֲבַרְתֶּם, שֶׁאֲנִי יָשַׁנְתִּי כָּאן, וְרָאִיתִי אֶתְכֶם וְאֶת בְּנָיָהוּ בֶן יְהוֹיָדָע שֶׁשּׁוֹלֵחַ לָכֶם שְׁתֵּי עֲטָרוֹת עַל יְדֵי זָקֵן אֶחָד לְעַטֶּרְכֶם. וַדַּאי שֶׁבַּדֶּרֶךְ הַזּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה. וְעוֹד, שֶׁרָאִיתִי אֶת פְּנֵיכֶם מְשֻׁנּוֹת. אָמַר רַבִּי יוֹסֵי, יָפֶה אֲמַרְתֶּם, שֶׁחָכָם עָדִיף מִנָּבִיא. בָּא רַבִּי אֶלְעָזָר וְשָׂם אֶת רֹאשׁוֹ בֵּין בִּרְכֵּי אָבִיו וְסִפֵּר (לו) הַמַּעֲשֶׂה."],[1,"","פָּחַד רַבִּי שִׁמְעוֹן וּבָכָה. אָמַר (חבקוק ג) ה' שָׁמַעְתִּי שִׁמְעֲךְ יָרֵאתִי. אֶת הַפָּסוּק הַזֶּה אָמַר חֲבַקּוּק בְּשָׁעָה שֶׁרָאָה מִיתָתוֹ וְהִתְקַיֵּם עַל יְדֵי אֱלִישָׁע. לָמָּה נִקְרָא חֲבַקּוּק מִשּׁוּם שֶׁכָּתוּב (מלכים ב ד) לַמּוֹעֵד הַזֶּה כָּעֵת חַיָּה אַתְּ חֹבֶקֶת בֵּן. וְזֶה הָיָה בְּנָהּ שֶׁל הַשּׁוּנַמִּית. וּשְׁנֵי חִבּוּקִים הָיוּ - אֶחָד שֶׁל אִמּוֹ, וְאֶחָד שֶׁל אֱלִישָׁע, שֶׁכָּתוּב (שם) וַיָּשֶׂם פִּיו עַל פִּיו."],[2,"","מָצָאנוּ בְסִפְרוֹ שֶׁל שְׁלֹמֹה הַמֶּלֶךְ שֵׁם חָקוּק שֶׁשִּׁבְעִים וּשְׁנַיִם שֵׁמוֹת חֲקוּקִים עָלָיו בַּתֵּבוֹת, מִשּׁוּם שֶׁאוֹתִיּוֹת הָא\"ב שֶׁחָקַק בּוֹ אָבִיו בָּרִאשׁוֹנָה, כְּשֶׁמֵּת, פָּרְחוּ מִמֶּנּוּ. וְכָעֵת כְּשֶׁאֱלִישָׁע חִבֵּק אוֹתוֹ, חָקַק בּוֹ כָּל אוֹתָן הָאוֹתִיּוֹת שֶׁל שִׁבְעִים וּשְׁנַיִם הַשֵּׁמוֹת, וְהָאוֹתִיּוֹת שֶׁל שִׁבְעִים וּשְׁנַיִם הַשֵּׁמוֹת הַלָּלוּ הַחֲקוּקִים הֵם מָאתַיִם וְשֵׁשׁ עֶשְׂרֵה אוֹתִיּוֹת."],[3,"","וְאֶת כָּל הָאוֹתִיּוֹת חָקַק בְּרוּחוֹ (נ\"א בדבור) אֱלִישָׁע, כְּדֵי לְהַעֲמִידוֹ בָּאוֹתִיּוֹת שֶׁל שִׁבְעִים וּשְׁנַיִם שֵׁמוֹת. וְקָרָא לוֹ חֲבַקּוּק, הַשֵּׁם שֶׁמַּשְׁלִים אֶת כָּל הַצְּדָדִים, מַשְׁלִים אֶת הַחִבּוּקִים, כַּמְבֹאָר. וְהִשְׁלִים לַסּוֹד שֶׁל מָאתַיִם וְשֵׁשׁ עֶשְׂרֵה הָאוֹתִיּוֹת שֶׁל הַשֵּׁם הַקָּדוֹשׁ. בַּתֵּבוֹת הִתְקַיֵּם לְהַחֲזִיר אֶת רוּחוֹ, וּבָאוֹתִיּוֹת הִתְקַיֵּם כָּל גּוּפוֹ עַל קִיּוּמוֹ, וְעַל כֵּן נִקְרָא חֲבַקּוּק."],[4,"","וְהוּא אָמַר (חבקוק ג) ה' שָׁמַעְתִּי שִׁמְעֲךְ יָרֵאתִי. שָׁמַעְתִּי מַה שֶּׁהָיָה לִי שֶׁטָּעַמְתִּי מֵהָעוֹלָם הַהוּא וּפָחַדְתִּי. הִתְחִיל לְבַקֵּשׁ רַחֲמִים עַל נַפְשׁוֹ וְאָמַר, ה', פָּעָלְךְ שֶׁעָשִׂיתָ לִי, בְּקֶרֶב שָׁנִים יִהְיוּ חַיֵּיהוּ. כְּמוֹ חַיָּיו. וְכָל מִי שֶׁנִּקְשָׁר בְּאוֹתָן הַשָּׁנִים הַקַּדְמוֹנִיּוֹת, הַחַיִּים נִקְשָׁרִים בּוֹ. בְּקֶרֶב שָׁנִים תּוֹדִיעַ לְאוֹתָהּ הַדַּרְגָּה שֶׁאֵין בָּהּ חַיִּים כְּלָל."],[5,"","בָּכָה רַבִּי שִׁמְעוֹן וְאָמַר, אַף אֲנִי מִמַּה שֶּׁשָּׁמַעְתִּי פָּחַדְתִּי מֵהַקָּדוֹשׁ בָּרוּךְ הוּא. הֵרִים יָדוֹ עַל רֹאשׁוֹ וְאָמַר, וּמָה רַב הַמְנוּנָא הַזָּקֵן, אוֹר הַתּוֹרָה, אַתֶּם זְכִיתֶם לִרְאוֹת פָּנִים בְּפָנִים, וְלֹא זָכִיתִי בוֹ. נָפַל עַל פָּנָיו וְרָאָה אוֹתוֹ עוֹקֵר הָרִים מֵאִיר נֵרוֹת בְּהֵיכַל מֶלֶךְ הַמָּשִׁיחַ. אָמַר לוֹ, רַבִּי, בְּאוֹתוֹ הָעוֹלָם תִּהְיוּ שְׁכֵנִים בַּעֲלֵי הוֹרָאָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. מֵהַיּוֹם הַהוּא הָיָה קוֹרֵא לְרַבִּי אֶלְעָזָר בְּנוֹ וּלְרַבִּי אַבָּא פְּנִיאֵ\"ל, כְּמוֹ שֶׁנֶּאֱמַר (בראשית לב) כִּי רָאִיתִי אֱלֹהִים פָּנִים אֶל פָּנִים."],[6,"","בְּרֵאשִׁית, רַבִּי חִיָּיא פָּתַח, (תהלים קיא) רֵאשִׁית חָכְמָה יִרְאַת ה' שֵׂכֶל טוֹב לְכָל עֹשֵׂיהֶם תְּהִלָּתוֹ עֹמֶדֶת לָעַד. רֵאשִׁית חָכְמָה, פָּסוּק זֶה כָּךְ צָרִיךְ לִכְתֹּב: סוֹף חָכְמָה יִרְאַת ה', בִּגְלַל שֶׁיִּרְאַת ה' הִיא סוֹף חָכְמָה. (נ\"א: אלא היא ראשית) לְהִכָּנֵס לְתוֹךְ הַדַּרְגָּה שֶׁל חָכְמָה עֶלְיוֹנָה. זֶהוּ שֶׁכָּתוּב (שם קיח) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק. זֶה הַשַּׁעַר לַה', וַדַּאי. שֶׁאִם לֹא יִכָּנֵס בְּשַׁעַר זֶה, לֹא יִכָּנֵס לְעוֹלָמִים. (משל) לְמֶלֶךְ עֶלְיוֹן שֶׁהוּא עֶלְיוֹן נִסְתָּר וְגָנוּז, וְעָשָׂה לוֹ שְׁעָרִים אֵלֶּה עַל אֵלֶּה,"],[7,"","וּבְסוֹף כָּל הַשְּׁעָרִים עָשָׂה שַׁעַר אֶחָד בְּכַמָּה מַנְעוּלִים, בְּכַמָּה פְתָחִים, בְּכַמָּה הֵיכָלוֹת אֵלֶּה עַל אֵלֶּה, וְאָמַר: כָּל מִי שֶׁרוֹצֶה לְהִכָּנֵס אֵלַי - שַׁעַר זֶה יִהְיֶה רִאשׁוֹן לְגַבַּי. מִי שֶׁיִּכָּנֵס בְּשַׁעַר זֶה - יִכָּנֵס. גַּם כָּךְ שַׁעַר רִאשׁוֹן לְחָכְמָה עֶלְיוֹנָה, יִרְאַת ה' הִיא. וְזוֹהִי רֵאשִׁית."],[8,"","ב, שְׁנַיִם הֵם שֶׁמִּתְחַבְּרִים כְּאֶחָד, וְאֵלֶּה שְׁתֵּי נְקֻדּוֹת - אֶחָד גָּנוּז וְנִסְתָּר, וְאֶחָד עוֹמֵד בְּהִתְגַּלּוּת. וּבִגְלַל שֶׁאֵין לָהֶם פֵּרוּד נִקְרָאִים רֵאשִׁית, אֶחָד וְלֹא שְׁנַיִם. מִי שֶׁנּוֹטֵל זֶה נוֹטֵל זֶה, וְהַכֹּל אֶחָד. שֶׁהֲרֵי הוּא וּשְׁמוֹ אֶחָד, שֶׁכָּתוּב (שם פג) וְיֵדְעוּ כִּי אַתָּה ה' שִׁמְךְ לְבַדֶּךְ."]]],[["אַמַּאי אִקְרֵי יִרְאַת ה', בְּגִין דְּאִיהוּ אִילָנָא דְּטוֹב וְרָע, זָכֵי בַּר נָשׁ הָא טוֹב וְאִי לָא זָכֵי הָא (הוא) רָע. וְעַל דָּא שָׁרֵי בְּהַאי אֲתַר יִרְאָה. וְדָא תַּרְעָא לְעָאלָא לְכָל טוּבָא דְעָלְמָא. שֵׂכֶל טוֹב אִלֵּין תְּרֵין תַּרְעִין דְּאִנּוּן כְּחֲדָא. רִבִּי יוֹסֵי אָמַר שֵׂכֶל טוֹב דָּא אִילָנָא דְחַיֵּי דְּאִיהוּ שֵׂכֶל טוֹב בְּלָא רָע כְּלָל. וְעַל דְּלָא שַׁרְיָא בֵּיהּ רָע אִיהוּ שֵׂכֶל טוֹב בְּלָא רָע.","לְכָל עוֹשֵׂיהֶם, אִלֵּין חַסְדֵּי דָוִד (ויחי רי\"ט ע\"א) הַנֶּאֱמָנִים תַּמְכִין אוֹרַיְיתָא. וְאִנּוּן דְּתָמְכִין אוֹרַיְיתָא כִּבְיָכוֹל אִנּוּן עָבְדִין. כָּל אִנּוּן דְּלָעָאן בְּאוֹרַיְיתָא לֵית בְּהוּ עֲשִׂיָּה בְּעוֹד דְּלָעָאן בָּהּ. אִנּוּן דְּתָמְכִין לוֹן אִית בְּהוּ עֲשִׂיָּה. וּבְחֵילָא דָא כְּתִיב תְּהִלָּתוֹ עוֹמֶדֶת לָעַד וְקַיְימָא כּוּרְסְיָיא עַל קִיּוּמֵיהּ כְּדְקָא יְאוּת.","רִבִּי שִׁמְעוֹן הֲוָה יָתִיב וְלָעֵי בְּאוֹרַיְיתָא בְּלֵילְיָא (אמור צ\"ח א) דְּכַלָּה אִתְחַבְּרַת בְּבַעֲלָהּ. דְּתָנִינָן כָּל אִנּוּן חַבְרַיָא דִּבְנֵי הֵיכָלָא דְּכַלָּה אִצְטְרִיכוּ בְּהַהִיא לֵילְיָא דְּכַלָּה אִזְדַּמְנַת לְמֶהֱוֵי לְיוֹמָא אַחֲרָא גּוֹ חוּפָּה בְּבַעֲלָהּ לְמֶהוֵי עִמָּהּ כָּל הַהוּא לֵילְיָא, וּלְמֶחֱדֵי עִמָּהּ בְּתִקּוּנָהָא דְאִיהִי אִתְתַּקָּנַת לְמִלְעֵי בְּאוֹרַיְיתָא מִתּוֹרָה לִנְבִיאִים וּמִנְבִיאִים לִכְתוּבִים וּבְמִדְרָשׁוֹת דִּקְרָאֵי וּבְרָזֵי דְחָכְמְתָא. בְּגִין דְּאִלֵּין אִנּוּן תִּיקּוּנִין דִּילָהּ וְתַכְשִׁיטָהָא. וְאִיהִי וְעוּלֵמְתָהָא עָאלַת וְקַיְימַת עַל רֵישֵׁיהוֹן וְאִתְתַּקָּנַת בְּהוּ וְחָדַת בְּהוּ כָּל הַהוּא לֵילְיָא. וּלְיוֹמָא אָחֳרָא לָא עָאלַת לַחוּפָּה אֶלָּא בַּהֲדַיְיהוּ. וְאִלֵּין אִקְרוּן בְּנֵי חוּפָּתָא. וְכֵיוָן דְּעָאלַת לְחוּפָּתָא קוּדְשָׁא בְּרִיךְ הוּא שָׁאִיל עֲלַיְיהוּ וּמְבָרֵךְ לוֹן וּמְעַטֵּר לוֹן בְּעִטְּרָהָא דְּכַלָּה. זַכָּאָה חוּלַקְהוֹן.","וְהֲוָה רִבִּי שִׁמְעוֹן וְכֻלְהוּ חַבְרַיָיא (בהדיה) מְרַנְּנִין בְּרִנָּה דְאוֹרַיְיתָא וּמְחַדְּשָׁן מִלִּין דְאוֹרַיְיתָא כָּל חַד וְחַד מִנַּיְיהוּ. וְהֲוָה חָדֵי רִבִּי שִׁמְעוֹן וְכָל שְׁאָר חַבְרַיָיא. אָמַר לוֹן רִבִּי שִׁמְעוֹן, בָּנַי זַכָּאָה חוּלַקְכוֹן בְּגִין דִּלְמָחָר לָא תֵיעוּל כַּלָּה לַחוּפָּה אֶלָּא בַּהֲדַיְיכוּ. בְּגִין דְּכֻלְהוּ דִּמְתַקְנִין תִּקּוּנָהָא בְּהַאי לֵילְיָא וְחָדָאן בָּהּ כֻּלְהוּ יְהוֹן רְשִׁימִין וּכְתִיבִין בְּסִפְרָא דְדֻכְרָנַיָא וְקוּדְשָׁא בְּרִיךְ הוּא מְבָרֵךְ לוֹן בְּשִׁבְעִין בִּרְכָאן וְעִטְּרִין דְּעָלְמָא עִלָּאָה.","פָּתַח רִבִּי שִׁמְעוֹן וְאָמַר (תהילים י״ט:ב׳) (תרומה קל\"ו ב) הַשָּׁמַיִם מְסַפְּרִים כְּבוֹד אֵל וְגו' קְרָא דָא הָא אוֹקִימְנָא לֵיהּ. אֲבָל בְּזִמְנָא דָא דְּכַלָּה אִתְעָרָא לְמֵיעַל לַחוּפָּה בְּיוֹמָא דְמָחָר אִתְתַּקָּנַת וְאִתְנְהִירַת בְּקִישׁוּטָהָא בַּהֲדֵי חַבְרַיָיא דְּחָדָאן עִמָּהּ כָּל הַהִיא לֵילְיָא וְאִיהִי חָדַאת עִמְּהוֹן.","וּבְיוֹמָא דְּמָחָר כַּמָּה אוּכְלוּסִין (כמה) חַיָּילִין וּמַשִּׁרְיָין מִתְכַּנְשִׁין בַּהֲדָהּ. וְאִיהִי וְכֻלְהוּ מְחַכָּאן לְכָל חַד וְחַד דִּתְקִינוּ לָהּ בְּהַאי לֵילְיָא. כֵּיוָן דְּמִתְחַבְּרָן כְּחֲדָא וְאִיהִי חָמַאת לְבַעְלָהּ מַה כְּתִיב הַשָּׁמַיִם מְסַפְּרִים כְּבוֹד אֵל. הַשָּׁמַיִם דָּא חָתָן דְּעָאל לַחוּפָּה. מְסַפְּרִים, מְנַהֲרִין כְּזוֹהֲרָא דְּסַפִּיר, דְּנָהִיר וְזָהִיר מִסְיָיפֵי עָלְמָא וְעַד סְיָיפֵי עָלְמָא.","כְּבוֹד אֵל, דָּא כְּבוֹד כַּלָּה דְּאִקְרֵי אֵל, דִּכְתִיב, (תהלים ז) אֵל זוֹעֵם בְּכָל יוֹם. בְּכָל יוֹמֵי שַׁתָּא אִקְרֵי אֵל, וְהַשְׁתָּא דְּהָא עָאלַת לַחוּפָּה אִקְרֵי כָּבוֹד, וְאִקְרֵי אֵל. יְקָר עַל יְקָר. נְהִירוּ עַל נְהִירוּ. וְשָׁלְטָנוּ עַל שָׁלְטָנוּ.","כְּדֵין בְּהַהִיא שַׁעֲתָא דְּשָׁמַיִם עָאל לַחוּפָּה וְאָתֵי וְנָהִיר לָהּ, כָּל אִנּוּן חַבְרַיָּיא דְּאַתְקִינוּ לָהּ כֻּלְהוּ אִתְפָּרְשֵׁי (אתפרשו) בִּשְׁמָהָן תַּמָּן הֲדָא הוּא דִכְתִיב, (תהילים י״ט:ב׳) וּמַעֲשֵׂה יָדָיו מַגִּיד הָרָקִיעַ. מַעֲשֵׂה יָדָיו, אִלֵּין אִנּוּן מָארֵי קַיָּימָא דִּבְרִית בַּהֲדֵי כַלָה, וְאִנּוּן מָארֵי קַיָימָא דִבְרִית אִקְרוּן מַעֲשֵׂה יָדָיו, כְּמָא דְאַתְּ אָמֵר, (תהילים צ׳:י״ז) וּמַעֲשֵׂה יָדֵינוּ כּוֹנְנֵהוּ דָּא בְּרִית קַיָּימָא דְּחֲתִים בְּבִשְׂרָא דְּבַר נָשׁ.","רַב הַמְנוּנָא סָבָא אָמַר הָכִי (קהלת ה׳:ה׳) אַל תִּתֵּן אֶת פִּיךָ לַחֲטִיא אֶת בְּשָׂרֶךָ, דְּלָא יָהִיב בַּר נָשׁ פּוּמֵיהּ לְמֵיתֵי לְהִרְהוּרָא בִּישָׁא, וִיהֵא גָרִים לְמֶחטֵי לְהַהִיא בְּשַׂר קֹדֶשׁ דְּחֲתִים בֵּיהּ בְּרִית קַדִּישָׁא. דְּאִילּוּ עָבִיד כֵּן מָשְׁכִין לֵיהּ לְגֵּיהִנֹּם. וְהַהוּא דִּמְמוּנֶה עַל גֵּיהִנֹּם דוּמ\"ה שְׁמֵיהּ. וְכַמָּה רִבּוֹא דְּמַלְאֲכֵי חַבָּלָה בַּהֲדֵיהּ. וְקָאִים עַל פִּתְחָא דְּגֵיהִנֹּם, וְכָל אִנּוּן דְּנָטְרוּ בְּרִית קַדִּישָׁא בְּהַאי עָלְמָא, לֵית לֵיהּ רְשׁוּ לְמִקְרַב בְּהוּ.","דָּוִד מַלְכָּא בְּשַׁעְתָּא דְּאִירַע לֵיהּ הַהוּא עוֹבָדָא דָּחִיל. בְּהַהִיא שַׁעֲתָא סָלִיק דוּמ\"ה קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא וְאָמַר לֵיהּ מָארֵי דְּעָלְמָא כְּתִיב בַּתּוֹרָה (ויקרא כ׳:י׳) וְאִישׁ אֲשֶׁר יִנְאַף אֶת אֵשֶׁת אִישׁ. וּכְתִיב וְאֶל אֵשֶׁת עֲמִיתְךָ וְגו'. דָּוִד דְּקִלְקֵל בְּרִית בְּעֶרְוָה מַהוּ. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא דָּוִד זַכָּאָה הוּא, וּבְרִית קַדִּישָׁא עַל תִּקּוּנֵיהּ קַיְימָא, דְּהָא גְּלֵי קָדָמַי דְּאִזְדַּמְּנַת לֵיהּ בַּת שֶׁבַע מִיּוֹמָא דְאִתְבְּרֵי עָלְמָא."],[[0,"","קכג) \u0003אמאי אקרי יראת\u0004 וכו': למה נקראת המלכות, יראת ה'. ומשיב, משום שהמלכות היא אילן של טוב ורע, זכה האדם, הנה טוב. ואם לא זכה, הנה רע, ועל כן שורה באותו מקום יראה. והיא השער, לבא לכל טוב שבעולם. \u0003שכל טוב\u0004, הוא אלו ב' שערים דהיינו ב' הנקודות, שהם כאחד. ר' יוסי אמר, \u0003שכל טוב\u0004, זהו עץ החיים, שהוא שכל טוב בלא רע כלל, ובשביל שאין רע שורה בו, הוא שכל טוב, בלי רע."],[0,"","פירוש. מבאר למה נק' השער האחרון בשם \u0003יראת ה'\u0004, שכתוב עליה \u0003ראשית חכמה יראת ה'\u0004. הוא, כי ה\"ס עצה\"ד שחטא בו אדם הראשון, כי על נקודה דא עונשיה במיתה, והיראה הגדולה היא שלא לפגמה. ובגמר התיקון כשהנקודה הזו תתוקן כולה בכל השלמות, יתקיים בלע המות לנצח. וע\"כ נק' \u0003יראת\u0004. וז\"ש \u0003ועל דא שרי בהאי אתר יראה\u0004."],[0,"","וז\"ש, \u0003ודא תרעא לעאלא לכל טובא דעלמא\u0004: כי גילוי \u0003החכמה עלאה\u0004 הוא כל טוב העולם, הנכלל במחשבת הבריאה. וכיון ש\u0003יראת ה'\u0004 היא השער הראשון ל\u0003חכמה עלאה\u0004, נמצא שהוא השער \u0003לכל טובא דעלמא\u0004."],[0,"","וז\"ש \u0003שכל טוב אלין תרין תרעין דאינון כחדא\u0004: היינו \u0003ב' הנקודות\u0004 יחדיו כמות שהן כלולות ב\u0003ב'\u0004 ד\u0003ב\u0004ראשית. ומה שאינו אומר \u0003ב' נקודות\u0004, אלא \u0003ב' תרעין\u0004, הוא, כי הכוונה היא לאחר תיקון הב\"ן, שאז נק' אלו \u0003ב' נקודות\u0004 בשם \u0003ב' תרעין\u0004, כי אז שתיהן טוב בלא רע כלל, וע\"כ יתכן הכתוב \u0003שכל טוב\u0004. משא\"כ מטרם גמר התיקון, הרי הן נק' עצה\"ד \u0003טוב ורע\u0004. כנ\"ל."],[0,"ר' יוסי אמר","וכו'. רבי יוסי אינו חולק על רבי חייא, אלא משמעות דורשין איכא בינייהו. כי רבי חייא מבאר המקרא על אחר תיקון הב\"ן, שאז נעשו ב' הנקודות ב' תרעין, כנ\"ל ואין בהם \u0003רע\u0004, והם \u0003שכל טוב בלא רע כלל\u0004. ורבי יוסי מבאר המקרא מטרם גמר התיקון, שאז הן בחינת עצה\"ד \u0003טוב ורע\u0004, וע\"כ אומר \u0003שכל טוב דא אילנא דחיי\u0004, שהוא ז\"א במוחין דאמא הנק' \u0003עץ החיים\u0004 שהוא כולו טוב בלא רע כלל גם מטרם גמר התיקון. משא\"כ \u0003ב' הנקודות\u0004 הם בבחינת \u0003טוב ורע\u0004, מטרם גמר התיקון, שבסיבתם נק' המלכות אילנא דטוב ורע. כנ\"ל."],[1,"","קכד) \u0003לכל עושיהם. אלין\u0004 וכו': לכל עושיהם, אלו הם חסדי דוד הנאמנים, מחזיקי התורה. ואלו המחזיקים את התורה, הם כביכול העושים אותה. כל אלו העוסקים בתורה, אין בהם עשיה בעוד שהם עוסקים בה, אבל אלו שמחזיקים אותה, יש בהם עשיה. ובכח זה מתקיים הכתוב, תהלתו עומדת לעד. והכסא עומד על קיומו כראוי."],[1,"","ביאור הדברים, כי ביאר לעיל, ששער זה דיראת ה', שהוא אחרון השערים, הוא השער הא' לחכמה עלאה, ונמצא \u0003אינון דלעאן באורייתא\u0004, שהם כבר תיקנו השער האחרון, ונעשו להם ב' הנקודות לב' תרעין, שהם שכל טוב בלא רע, הרי נבחן שב\u0003אינון דלעאן באורייתא לית בהו עשיה\u0004, שהיא בחינת \u0003עצה\"ד טו\"ר\u0004. אבל אינון שעוד לא זכו לגמר התיקון, שהם נק' \u0003תמכין אורייתא\u0004, בהם \u0003אית עשיה\u0004, שהיא \u0003טו\"ר\u0004, כי עוד לא תיקנו החטא ד\u0003עצה\"ד\u0004."],[1,"","וזה אמרו, \u0003ואינון דתמכין אורייתא כביכול אינון עבדין\u0004, כי נתבאר לעיל באורך, איך כל אלו הכחות דפרודא מתהפכין ונעשין לשערים, וכל מנעול נעשה לפתח, וכל פתח להיכל החכמה, שעל ידיהם מתגלות ובאות כל המדרגות הנשגבות הנכללות במחשבת הבריאה להנות לנבראיו ע\"ש."],[1,"","נמצא כי כל החכמה וכל התורה אינה באה לכלל גילוי, זולת ע\"י ה\u0003תמכין דאורייתא, דאית בהו עשיה\u0004, דהיינו שנוהג בהם ענין טוב ורע, ומשום זה נק' \u0003תמכין דאורייתא\u0004, כי רק על ידיהם היא נגלית, והכתוב קורא אותם \u0003עושיהם\u0004, כי המה כביכול, כמו עושיהם של התורה, כי לולא ההסתרות שלהם, שע\"י התגברותם עליהם נהפכו לשערים, לא היתה באה התורה לכלל גילוי, וז\"ש \u0003ואינון דתמכין אורייתא כביכול, אינון דעבדין\u0004 כלומר, שנחשבים \u0003כביכול\u0004 לעושיה, המגלים אותה."],[1,"","ומה שאומר כביכול, הוא כי התורה קדמה לעולם (פסחים נד. ), וודאי הוא, שהקב\"ה עשה אותה, אלא מתוך שלולא המע\"ט של ה\u0003תמכין דאורייתא\u0004 לא היתה באה לעולם לכלל גילוי, ע\"כ נחשבים המה לעובדים ועושים את התורה."],[1,"","וז\"ש, \u0003ובחילא דא כתיב תהלתו עומדת לעד\u0004: כלומר, \u0003בחילא\u0004 של ה\u0003תמכין\u0004 ד\u0003אורייתא\u0004, נמצאת \u0003תהלתו\u0004 שהיא כל החכמה וכל התורה \u0003עומדת לעד\u0004, לנצח, דהיינו לרבות גם לאחר גמר התיקון, כי גם אז יהיו צריכים \u0003ליראת ה'\u0004, ולאחר תיקון עצה\"ד לא יהיה להם מאין ליקח \u0003יראת ה'\u0004 זולת מהזמן שעבר. דהיינו מבחינת ה\u0003תמכין דאורייתא\u0004 (עיין לעיל אות קי\"ח) ונמצא שהם מעמידים תהלת ה' לעד ולנצח נצחים. וז\"ש \u0003וקיימא כורסייא על קיומיה כדקא יאות\u0004 שבזה מתקיים \u0003כסא\u0004 הן \u0003כדקא יאות\u0004 לנצח."],[2,"","קכה) \u0003רבי שמעון הוה\u0004 וכו': ר\"ש היה יושב ועוסק בתורה, בלילה שבו הכלה, שהיא מלכות, מתחברת בבעלה. שלמדנו, כל החברים שהם בני היכל הכלה, צריכים באותו הלילה, שלמחרתו ביום השבועות, הכלה נועדת להיות תחת החופה עם בעלה, להיות עמה כל אותו הלילה, ולשמוח עמה בתקוניה שהיא מתתקנת בהם, דהיינו, לעסוק בתורה, ומתורה לנביאים, ומנביאים לכתובים, ובדרשות המקראות, ובסודי החכמה. משום שאלו הם התקונים שלה ותכשיטיה. והיא, הכלה, ועלמותיה, באה ועומדת על ראשיהם, ומתתקנת בהם, ושמחה בהם כל אותו הלילה. ולמחרת, ביום השבועות, אינה באה לחופה אלא עמהם. ואלו, החברים העוסקים כל הלילה בתורה, נקראים בני החופה. וכיון שבאה לחופה הקב\"ה שואל עליהם, ומברך אותם, ומעטר אותם בעטרותיה של הכלה. אשרי חלקם."],[2,"","ביאור הדברים, יש בזה ב' פירושים ושניהם עולים בקנה אחד: א) כי ימי הגלות נק' \u0003לילה\u0004, כי הוא הזמן של הסתרת פניו מבני ישראל, ואז שולטים כל כוחות דפרודא על עובדי ה', ועם כל זה, דוקא בעת ההיא מתחברת הכלה בבעלה, ע\"י התורה והמצות של הצדיקים הנקראים בעת ההיא בשם \u0003תמכין דאורייתא\u0004, וכל המדרגות הנשגבות הנקראות \u0003רזין דאורייתא\u0004 מתגלות על ידיהם, כי ע\"כ הם נק' \u0003עושיהם\u0004, שהם \u0003כביכול\u0004 העושים של התורה. (כנ\"ל אות קכ\"ד). ונמצא שימי הגלות נקראים \u0003ליליא דכלה אתחברת בבעלה. וכל אינון חבריא דבני היכלא דכלה\u0004, הם ה\u0003תמכין דאורייתא\u0004."],[2,"","ולאחר \u0003גמר התיקון\u0004 והגאולה השלימה, שה\"ס הכתוב, והיה יום אחד הוא יודע לה' לא יום ולא לילה והיה לעת ערב יהיה אור (זכריה י\"ד). הוא שאומר \u0003דכלה אזדמנת למהוי ליומא אחרא גו חופה בבעלה\u0004. כי אז ישוב הב\"ן להיות ס\"ג והמ\"ה יהיה ע\"ב. וע\"ב נבחן \u0003ליומא אחרא\u0004, ולחופה חדשה."],[2,"","והצדיקים בעת ההיא נקראים \u0003בני חופתא\u0004, שה\"ס ה\u0003לעאן דאורייתא\u0004 שאין בהם \u0003עשיה\u0004, כי אז נאמר ומלאה הארץ דעה את ה' (ישעיה י\"א) ולהיות הצדיקים הללו ע\"י מעשיהם הטובים יעלו הב\"ן להיות ס\"ג, מכח המשכתם היראה מזמן שעבר, נבחנים שהם עושים את החופה החדשה הזו, וע\"כ נקראים \u0003בני חופתא\u0004."],[2,"","והפירוש הב' הוא. אשר ליל שבועות נק' \u0003ליליא דכלה אתחברת בבעלה\u0004. כי אז הוא \u0003אזדמנת למהוי ביומא אחרא גו חופה בבעלה\u0004, דהיינו ביום השבועות, שהוא יום קבלת התורה. אמנם הוא ענין אחד ממש עם הביאור הא' הנ\"ל. כי ביום קבלת התורה היה כבר בחינת גמר התיקון, בסוד בלע המות לנצח ומחה ה' אלקים דמעה מעל כל פנים (ישעיה כ\"ה) כמו שדרשו חז\"ל על הפסוק חרות על הלוחות (שמות ל\"ב), אל תקרי חרות אלא חירות, כי באה חירות ממלאך המות (שמו\"ר פמ\"א)."],[2,"","אלא מחמת חטא העגל חזרו וקלקלו את התיקון. הרי שענין יום קבלת התורה הוא ענין אחד עם גמר התיקון. ונמצא שבלילה קודם קבלת התורה, נגמרו בה כל הזווגים שבימי הסתרה, וע\"כ נבחן הלילה ההוא \u0003לליליא דכלה אתחברת בבעלה, ואזדמנת למהוי ליומא אחרא גו חופה בבעלה\u0004, שהוא חג השבועות שבו נגמר התיקון בחירות ממלאך המות, שהוא הזמן שהצדיקים ע\"י מעשיהם הטובים עושים חופה חדשה לכלה."],[2,"","והנה נוח לי יותר להמשיך הביאור בדרך הפירוש הא', והמעיין מדעתו יוכל להעתיק הדברים על יום השבועות, כי ענין אחד הוא."],[2,"","וז\"ש, \u0003כל אינון חבריא\u0004 וכו' אלו ה\u0003תמכין דאורייתא\u0004 הנק' בני היכלא דכלה (כנ\"ל בדיבור הסמוך) הם צריכים להיות דבוקים בשכינה הקדושה הנק' \u0003כלה בכל ההוא ליליא\u0004 של הגלות, כי אז בימי הגלות היא מתתקנת ע\"י ה\u0003תמכין דאורייתא\u0004 בכל אלו המע\"ט והתורה ומצוות שהם עושים, עד לטהר אותה מבחינת טו\"ר, ותהיה מזומנת לאינון \u0003דמלעי באורייתא\u0004 שאין בהם מבחינת \u0003עשיה\u0004 כלל, אלא היא כולה \u0003טוב בלא רע\u0004. (כנ\"ל אות קכ\"ג ד\"ה שכל עש\"ה)."],[2,"","ולפיכך צריכים ה\u0003תמכין דאורייתא\u0004, שהם \u0003בני היכלא דכלה\u0004 לשמוח עמה על התיקון הגדול הזה שנעשה בכלה על ידיהם. וז\"ש \u0003ולמחדי עמה בתקונהא דאיהי אתתקנת למלעי באורייתא\u0004, דהיינו בתיקונים הבאים לפנינו \u0003מתורה לנביאים\u0004 וכו'. שצריכים לעשותם בשמחה."],[2,"","והנה נתבאר שכל המדרגות וגילוי רזין דאורייתא, שהם בנין השכינה לגמר תיקונה, כל אלו נעשים רק ע\"י ה\u0003תמכין\u0004 ד\u0003אורייתא\u0004 בימי הגלות. ולפיכך כל אלו המדרגות והקומות היוצאות בזמן הגלות, נקראות \u0003תקונהא\u0004 דכלה \u0003ותכשיטהא דילה\u0004 ואלו הם שהולך ומפרט, \u0003מתורה לנביאים\u0004 וכו': כי חג\"ת ה\"ס תורה, ונו\"ה ה\"ס \u0003נביאים\u0004, והמלכות עצמה ה\"ס \u0003כתובים\u0004, והמוחין דו\"ק שממשיכין לה ה\"ס \u0003מדרשות דקראי\u0004. והמוחין דג\"ר שממשיכין לה ה\"ס \u0003רזי דחכמתא\u0004. כי כל אלו התיקונים, צריכים להמשיכם לכלה \u0003בההיא ליליא\u0004, שבהם נגמרת ה\u0003כלה\u0004 לגמר התיקון, שה\"ס יומא דחופה."],[2,"","וז\"ש, \u0003ואיהי ועולמתהא\u0004 וכו', המלאכים שבהם מלובשים הכלים דאחורים דמלכות דמצב הא', הן נקראות עלמות המשמשות לשכינה, ואומר, שהשכינה \u0003קיימת על רישיהון, דאינון תמכין דאורייתא\u0004, בסוד ועל ראשי שכינת אל."],[2,"","ועמה יחד \u0003העלמות\u0004 המשמשות אותה, והיא שמחה עמהם בהיותה מתקנת והולכת על ידיהן. וז\"ש \u0003וחדת בהו כל ההוא ליליא\u0004, דהיינו בכל משך זמן התיקונים הנק' \u0003ליליא\u0004. (ועי' בז\"ח שה\"ש אות קנ\"ט). וז\"ש, \u0003וליומא אחרא\u0004 וכו', שביום גמר התיקון שהוא \u0003יום החופה\u0004, לא תוכל להכנס לחופה אלא באלין \u0003התמכין דאורייתא\u0004 שבנו ותיקנו אותה בכל הצורך \u0003מתורה לנביאים\u0004 וכו' כנ\"ל, ולכן נק' \u0003בני חופתא\u0004."],[2,"","וז\"ש \u0003וכיון דעאלת\u0004 וכו', כבר ידעת, שגמר התיקון לא יביא עמו שום דבר חדש, אלא ע\"י האור העליון דעתיק יומין יתקבצו כל המ\"ן ומ\"ד וכל הזווגין וכל המדרגות שיצאו בשתא אלפי שני בזה אחר זה לזווג אחד ולקומה אחת \u0003רב ויקירא\u0004, ועי\"ז יתתקן הכל. (כנ\"ל אות צ\"א ד\"ה בן) ואז תכנס הכלה לחופה."],[2,"","וז\"ש \u0003קב\"ה שאיל עלייהו\u0004, דהיינו על כל אחד ואחד, שהעלה פעם מ\"ן לזווג עליון, כי כביכול יושב ומחכה עד שיתקבצו כולם, ונמצא שואל ומחכה על כל אחד ואחד. ואחר שמתקבצים, נעשה אז הזווג ד\u0003רב פעלים ומקבצאל\u0004 כנ\"ל, \u0003ומברך לון ומעטר לון\u0004, שמתברכים ומתעטרים כולם בבת אחת, ואז נגמר התיקון הנק' \u0003עטרהא דכלה\u0004."],[3,"","קכו) \u0003והוה ר' שמעון\u0004 וכו': והיה ר\"ש וכל החברים מרננים ברננת התורה, וכל אחד ואחד מהם היה מחדש דברי תורה, ורבי שמעון היה שמח. וכן כל שאר החברים. אמר להם רבי שמעון: בני, אשרי חלקכם, כי למחר לא תבא הכלה אל החופה, אלא עמכם, משום שכל אלו המתקנים תקוני הכלה בלילה הזה, ושמחים בה, כולם יהיו רשומים וכתובים בספר הזכרון, והקב\"ה מברך אותם בשבעים ברכות ועטרות מהעולם העליון."],[3,"","ביאור הדברים, ספר הזכרון (המובא במלאכי ג' ט\"ז). דכתיב אמרתם שוא עבוד אלהים וגו'. נבנו עושי רשעה גם בחנו אלהים וימלטו אז נדברו יראי ה' איש אל רעהו ויקשב ה' וישמע ויכתב ספר זכרון לפניו ליראי ה' ולחושבי שמו. והיו לי אמר ה' צבאות ליום אשר אני עשה סגולה וגו'. ויש להבין הדברים, בעת שאמרו איש אל רעהו ונדברו ביניהם דברים בזויים כאלו, שוא עבוד אלהים ומה בצע כי שמרנו משמרתו וגו' יאמר עליהם הנביא אז נדברו יראי ה'איש אל רעהו, ולא עוד אלא שנכתבים בספר הזכרון, לפניו ליראי ה' ולחושבי שמו."],[3,"","והענין הוא, כי לעת קץ, כאשר יתגלה הזווג הגדול דעתיק יומין בסוד \u0003רב פעלים ומקבצאל\u0004, יתגלה אור גדול בכל העולמות, שעי\"ז ישוב כל בשר בתשובה שלמה מאהבה, ונודע מ\"ש חז\"ל (יומא פו:) שהזוכה לתשובה מאהבה זדונות נעשים לו כזכיות, וזה שאמר הנביא, על אלו הרשעים שאמרו, ונדברו ביניהם חירוף וגידוף, לומר, שוא עבוד אלהים ומה בצע כי שמרנו משמרתו: אשר ביום הגדול, דגמר התיקון, שיתגלה האור של תשובה מאהבה, הנה גם הזדונות האלו, שאין עוד גרוע מהם, יתהפכו ג\"כ לזכיות, ויחשבו אלו המדברים, ליראי ה'."],[3,"","והיינו בגמר התיקון, כמו שמסיק הנביא, והיו לי אמר ה' צבאות ליום אשר אני עושה סגולה וגו', דהיינו ביום גמר התיקון. ולפיכך יש בהכרח ספר זכרון בפניו על הזדונות והפשעים הנעשים בעולם, שהרי הוא צריך להם ליום שהוא עושה סגולה, כי אז יהפכו להיות זכיות ויצטרפו וישלימו קומת האור של גמר התיקון."],[3,"","וזה שכתוב, ויכתב ספר זכרון לפניו ליראי ה' ולחושבי שמו, והיו לי, אמר ה' צבאות, ליום אשר אני עושה סגולה. כי אז אני צריך להם, כדי להשלים הקומה. וזה שהנביא מסיים, וחמלתי עליהם כאשר יחמול איש על בנו העובד אותו. כי אז יהיו יקרים לי וחביבים לי כמו שהיו מהעובדים אותי."],[3,"","וזהו אמרו, \u0003כלהו יהון רשימין וכתיבין בספרא דדכרניא\u0004, הוא בא לרבות שאפילו הזדונות שעשו יהיו אז \u0003רשימין וכתיבין\u0004 בספר הזכרון. ויכתוב אותם הקב\"ה כאילו היו זכויות, וכאילו היו עובדים אותו בהם. דהיינו כמו שאמר הנביא."],[3,"","והנה המספר שבעים מורה על מוחין דחכמה וג\"ר, שהמה נק' \u0003עטרין\u0004. וסוד ברכה, הוא על אור החסדים, (כנ\"ל אות ל\"ז), שהעולם נברא ב\u0003ב'\u0004 שה\"ס ברכה, דהיינו עולם חסד יבנה (תהלים פ\"ט). עש\"ה. והוא בחינת ו\"ק. ואומר שבגמר התיקון גם אור החסדים יהיה בבחינת \u0003ע' עטרין\u0004 כמו החכמה, כי המ\"ה וב\"ן יעלו לע\"ב ס\"ג, וז\"ש \u0003וקב\"ה מברך לון בשבעין ברכאן ועטרין דעלמא עלאה\u0004, דע\"ב ס\"ג. וע\"כ נבחנים אז גם \u0003ברכאן\u0004 במספר \u0003שבעין\u0004."],[4,"","קכז) \u0003פתח ר' שמעון\u0004 וכו': פתח ר\"ש, ואמר, השמים מספרים כבוד אל וגו'. מקרא זה כבר העמדתי אותו, אבל בזמן הזה, שהכלה מתעוררת להכנס לחופה, למחר, היא מתתקנת, ומאירה בקישוטיה עם החברים ששמחו עמה כל אותו הלילה, והיא שמחה עמהם."],[5,"","קכח) \u0003וביומא דמחר כמה\u0004 וכו': ולמחר, כמה המונים, צבאות, ומחנות, מתאספים אליה, והיא, וכולם, כל אלו הצבאות והמחנות, מחכים לכל אחד ואחד מאלו שתקנו אותה בעסק התורה, בלילה הזה. כיון שנתחברו יחד, ז\"א ומלכות, והיא, המלכות, רואה את בעלה, ז\"א, מה כתוב, השמים מספרים כבוד אל. \u0003השמים\u0004, זהו החתן הנכנס לחופה. שהוא ז\"א הנקרא שמים. \u0003מספרים\u0004, היינו שמאירים כזוהר הספיר, המאיר ומזהיר מסוף העולם ועד סוף העולם."],[5,"","ביאור הדברים, יום גמר התיקון נק' \u0003יומא דמחר\u0004, כמ\"ש חז\"ל היום לעשותם ולמחר לקבל שכרם (עירובין כב. ). \u0003אוכלוסין\u0004 הם עמא דארעא בלתי עובדי ה' \u0003חיילין\u0004 הם עובדי ה' \u0003ומשריין\u0004 מורה על המחנות העליונים שהם מלאכים המלוים את הנשמות, בסו\"ה כי מלאכיו יצוה לך לשמרך בכל דרכך וכו' (תהלים צ\"א). ואומרו \u0003ואיהי וכלהו מחכאן לכל חד וחד\u0004, כבר נתבאר (לעיל אות קכ\"ה ד\"ה והנה ע\"ש). כי כמו דקב\"ה שאיל על כל חד וחד, כן השכינה מחכאת על כל חד וחד."],[5,"","וז\"ש \u0003כיון דמתחברן כחדא ואיהי חמאת לבעלה\u0004 וכו': כי לא תוכל לראות בעלה מטרם שיתקבצו כולם כנ\"ל. ותלויים זה בזה."],[5,"השמים דא חתן דעאל לחופה",": הוא דורש זאת על גמר התיקון, שעליו נאמר והיה אור הלבנה כאור החמה וגו' (ישעיה ל') ואומר \u0003השמים דא חתן דעאל לחופה\u0004. כי קב\"ה נק' \u0003שמים\u0004, ולעת גמר התיקון נק' \u0003חתן\u0004, בסוד הכתוב וכמשוש חתן על כלה ישיש עליך אלהיך. (ישעיה ס\"ב). פי' כי בכל מקום דכתיב וירד ה', הוא ענין של דין או גבורה כי מורה על ירידה ממעלתו ומרוממותו ית' באשר עוז וחדוה במקומו."],[5,"","אמנם בגמר התיקון שכל הפגמים והזדונות יתהפכו לזכיות כי אז יתברר שכל הירידות לא היו אלא עליות, נקרא הקב\"ה בשם \u0003חתן\u0004. והשכינה הקדושה נק' בשם \u0003כלה\u0004, כלה היא מלשון גמר התיקון, מלשון ויהי ביום \u0003כלת\u0004 משה להקים את המשכן (במדבר ז'), דהיינו שגמר כל מלאכת המשכן והקמתו. והמלה חתן מורה ג\"כ על ירידה, כי על רד מתרגמינן חות וכמ\"ש חז\"ל נחית דרגא ונסיב איתתא (יבמות ס\"ג. ), אמנם ירידה זו גדולה היא מכל העליות הקודמות, בהיותה לקראת הכלה, שהיא השכינה בעת גמר התיקון הנקראת אז \u0003כלה\u0004."],[5,"וחופה",", היא כינוס וקיבוץ של כל האו\"ח שיצא ע\"י המ\"ן שהעלו הצדיקים בכל אלו הזווגין דקב\"ה ושכינתיה, שנתגלו בזה אחר זה בכל הימים והזמנים דשתא אלפי שני, כי כולם נעשו עתה לאור גדול אחד של או\"ח העולה וחופף על קב\"ה ושכינתיה, הנקראים עתה \u0003חתן וכלה\u0004, שהאו\"ח חופף ממעל להם כמו \u0003חופה\u0004. ולפיכך נק' אז הצדיקים \u0003בני חופתא\u0004, כי כל אחד ואחד יש לו חלק בחופה זו, בשיעור המ\"ן שהעלה למסך שבמלכות לעלית או\"ח. וז\"ש \u0003השמים דא חתן דעאל לחופה\u0004. היינו לומר, שהכונה היא על העת של גמר התיקון, שאז נקרא קב\"ה \u0003חתן\u0004, והוא נכנס אז לחופתו."],[5,"","וז\"ש, \u0003מספרים מנהרין\u0004 וכו'. \u0003מספרים\u0004, ה\"ס הזווג הגדול שיהיה לעתיד, שהוא מלשון אשה מספרת עם בעלה (ברכות ג. ) וספיר הוא שם השכינה הק', מלשון ותחת רגליו כמעשה לבנת הספיר (שמות כ\"ד). \u0003זוהרא דספיר\u0004 היינו האו\"ח שהיא מעלה מתתא לעילא, ונהיר, פירושו אור ישר, \u0003וזהיר\u0004, פירושו אור חוזר. ואומר, שע\"י הזווג הגדול הזה הנעשה בגמר התיקון, שהוא קבוץ מכל הזווגין, הנה האו\"י והאו\"ח שבזווג הזה נהיר וזהיר מסוף העולם עד סופו, שז\"ס \u0003השמים מספרים\u0004."],[6,"","קכט) \u0003כבוד אל, דא\u0004 וכו': כבוד \u0003אל\u0004, זה הוא כבוד הכלה, דהיינו המלכות, שנקראת \u0003אל\u0004. שכתוב, אל זועם בכל יום. בכל ימי השנה היא נקראת אל, ועתה, בחג השבועות, שכבר נכנסה לחופה, היא נקראת \u0003כבוד\u0004, ונקראת אל. שזה מורה, יקר על יקר, אורה על אורה, וממשלה על ממשלה."],[6,"","פירוש. כי השם \u0003אל\u0004 הוא שם החסד הגדול, והנה הכתוב אומר, א\"ל זועם בכל יום, ונמצא לכאורה, שהוא להיפך מהחסד. והענין הוא, כי ה\"ס ויהי ערב ויהי בוקר יום אחד (בראשית א') כי השכינה הקדושה ה\"ס המאור הקטן לממשלת הלילה (שם), והיא נקראת יראת שמים, כי הצדיקים צריכים להעלות מ\"ן ע\"י אתערותא דלתתא שלהם, ולתקן אותה בסוד המסך המעלה או\"ח, ואז נמשך השפע מעילא לתתא, ולא זולת, כנודע."],[6,"","וז\"ס והאלהים עשה שיראו מלפניו (קהלת ג'). כי לא יתכן אתערותא דלתתא ולהעלות מ\"ן בלי יראה, וז\"ס שהיא שולטת בלילה, כי ע\"י חסרון האור שהוא בחינת לילה, הכוללת כל הדינין והיסורים, שהם ההיפך ממדת יום שהוא חסד, יש יראה מלפניו, ולולא היראה לא היתה נגלית מדת היום והבוקר."],[6,"","וז\"ס ויהי ערב ויהי בוקר יום אחד, כי גם הלילה נכנס בבוקר, כי לולא הלילה לא היה בוקר, ואי אפשר בלאו הכי. וז\"ס \u0003ואל זועם בכל יום\u0004, כי מדת החסד הנקרא \u0003אל\u0004 אינה מתגלית זולת ע\"י הלילה שהוא בחינת \u0003זועם\u0004. וע\"כ נבחן הזעם ג\"כ לחסד, כי אי אפשר שיתגלה החסד בדרך אחר, ומבחינה זו נקראת גם השכינה הקדושה בשם \u0003א\"ל\u0004."],[6,"","וזה אמרו \u0003כבוד אל, כבוד דא כלה דאקרי א\"ל\u0004, דהיינו מבחינת מה דכתיב \u0003ואל זועם בכל יום\u0004, שפירושו, שאי אפשר להיות יום בלי הזעם דלילה, \u0003בכל יומא שתא אקרי א\"ל\u0004, כי כן הוא בששת ימי המעשה, שנאמר בכל אחד מהם ויהי ערב ויהי בוקר יום אחד או יום שני וכו'. ונמצא שהלילה נכנס תחת השם של היום. וע\"כ נק' אז בששת ימי המעשה וכן בשתא אלפי שני, בשם \u0003א\"ל\u0004 שהוא שם החסד."],[6,"","וז\"ש, \u0003והשתא דהא\u0004 וכו' כי בזווג הגדול דגמר התיקון, יהיה אור הלבנה כאור החמה, בסו\"ה והיה לעת ערב יהיה אור (זכריה י\"ד). ונמצאות המדרגות שלה נכפלות, כי גם בשתא אלפי שני, בבחינת אור הלבנה היתה בסוד ויהי ערב ויהי בוקר, \u0003והשתא\u0004 שהיא עצמה גדלה כמו החמה, שהיא ז\"א הנקרא \u0003כבוד\u0004, הרי יש לה כבוד על כבוד, כי נעשית עכשיו לעצם הכבוד כי גדלה כז\"א."],[6,"","וכבוד מתרגמינן \u0003יקר\u0004. וז\"ש \u0003יקר על יקר\u0004. וכן \u0003נהירו על נהירו\u0004, כי גם בשתא אלפי שני, היתה נכללת באור בוקר, בסוד ויהי ערב ויהי בוקר יום אחד, אבל עתה כשהיא גדלה כחמה, נעשית לעצם האור, ונמצא שיש לה \u0003נהירו\u0004 עצמית \u0003על נהירו\u0004 בהתכללות שהיתה לה מקודם לכן."],[6,"","וכן \u0003שלטנו על שלטנו\u0004, כי בשתא אלפי שני היתה לה שלטנו, שהיא ממשלה, רק בבחינת המאור הקטן לממשלת הלילה, ועתה נתוסף לה גם \u0003שלטנו\u0004 דיום, כי גדלה כאור החמה שהיא לממשלת היום. ומשמיענו בזה, שלא תטעה לומר, שבעת שגדלה להיות כאור החמה מתבטלות ח\"ו המדרגות שלה עצמה, שהיו לה מעת שתא אלפי שני, שאינו כן, אלא רק תוספת יש כאן על מדרגותיה עצמה, באופן שיש לה \u0003יקר על יקר\u0004 וכו'."],[7,"","קל) \u0003כדין בההיא שעתא\u0004 וכו': אז, באותה שעה שהשמים, שהם ז\"א, נכנס לחופה, ובא ומאיר לה, כל אלו החברים שהתקינו אותה, בעסק התורה בלילה, כולם נודעים שם בשמותיהם, זהו שכתוב, ומעשה ידיו מגיד הרקיע. \u0003מעשה ידיו\u0004, אלו הם בעלי אות ברית, שנקראים מעשה ידיו. כמו שאתה אומר, ומעשה ידינו כוננהו. שהוא אות ברית החתום בבשרו של אדם."],[7,"","פירוש, \u0003חברייא\u0004 התמכין דאורייתא, דאית בה עשיה שהיא טו\"ר, ואומר כי אפילו אותם החלקים שהיו עדיין בחינת הרע שלהם בלי תיקון, הנה גם הם \u0003אתפרשי בשמהן\u0004 דקדושה. וז\"ש \u0003הה\"ד ומעשה ידיו מגיד הרקיע\u0004. כי \u0003הרקיע\u0004 ה\"ס \u0003ספר הזכרון\u0004, כמ\"ש להלן, שה\"ס אור הזווג הגדול המביאים לתשובה מאהבה, שזדונות נעשו להם כזכויות (יומא פו:), ואפילו אלו שנתנו פה לדבר סרה, יאמר עליהם, אז נדברו יראי ה' איש אל רעהו וכו' (כנ\"ל אות קכ\"ו ע\"ש)."],[7,"","ונמצא שהעשיה הזו שהיא התמכין דאורייתא, שבה טו\"ר, אשר לזוכה הוי טוב, ולבלתי זוכה הוי רע, הנה עתה עלתה העשיה כולה להיות קודש, ונעשתה לבחינת \u0003מעשה ידיו\u0004 של הקב\"ה. שהרי גם על אלין דלא זכו \u0003מגיד הרקיע\u0004 עליהם, אז נדברו יראי ה' איש אל רעהו כנ\"ל. ונמצא דכלהו חברייא לא עשו רק עבודת הקדש, כי אתקינו לה לחופה, \u0003וכלהו אתפרשי בשמהן\u0004."],[7,"","וז\"ש, \u0003כד\"א ומעשה ידינו כוננהו\u0004: ולכאורה הראיה היא לסתור, שהכתוב אומר \u0003מעשה ידינו\u0004 ולא \u0003מעשה ידיו\u0004. אמנם אינו מביא ראיה מהכתוב רק ש\u0003ברית קיימא\u0004 נקרא \u0003מעשה ידינו\u0004, כי כוננהו הוא בחינת היסוד המכונן ומיסד לכל הבנין, ותיקון היסוד הוא ברית מילה, ומכאן שברית קיימא נקראת \u0003מעשה ידינו\u0004. כי אנחנו מסירים הערלה מעל היסוד, והוא \u0003מעשה ידינו\u0004."],[7,"","וזה הוא רק מקודם גמר התיקון, אבל בגמר התיקון, יתגלה הכל \u0003למעשה ידיו\u0004 של הקב\"ה, והוא עצמו יהיה מעביר הערלה. וז\"ש \u0003אינון מארי קיימא דברית אקרון מעשה ידיו,\u0004 כי אז הקב\"ה עצמו יעביר הערלה, שז\"ס \u0003מעשה ידיו מגיד הרקיע\u0004, ומביא ראיה על תיקון הברית שנקראת עתה \u0003מעשה ידינו\u0004 מהכתוב \u0003מעשה ידינו כוננהו\u0004."],[8,"","קלא) \u0003רב המנונא סבא\u0004 וכו': רב המנונא הזקן, אמר כך. אל תתן את פיך לחטיא את בשרך. היינו שלא יתן האדם את פיו, לגרום, לבוא להרהור רע, ויהיה גורם להחטיא את בשר הקדש ההוא שחתום בו ברית קדוש. שאם הוא עושה כן, מושכים אותו לגיהנם. ואותו הממונה שעל הגיהנם, דומה שמו, וכמה רבבות מלאכי חבלה הם עמו, ועומד על פתח הגיהנם, וכל אלו ששמרו ברית הקדוש בעולם הזה, אין לו רשות לקרב אליהם."],[8,"","ומ\"ש \u0003למיתי להרהורא בישא\u0004. פירושו, אזהרה היא שכל אדם ישמור את הפה שלו, שהוא ענין העלאת מ\"ן ע\"י תורה ותפלה, שיהיה בתכלית הטהרה. כי אם תהיה בו איזו אחיזה לס\"א, אז יקבל הס\"א המ\"ן שלו, ובכח זה יביאהו להרהורים על הש\"י, דהיינו מחשבות זרות ח\"ו, ואז \u0003ויהא גרים למחטי לההיא בשר קדש דחתים ביה ברית קדישא\u0004, כי ע\"י ההרהורים נמצא מושך ערלה על ברית קודש, והנשמה הקדושה נופלת בשבי לידי הס\"א, ואז הס\"א מושך הנשמה שלו לגיהנם. והוא בדרך שאמר רבי אלעזר (לעיל אות ס\"ח), דמהא מלה אתעבידת רקיעא דשוא דאקרי תהו, ונופל ליד לילית ע\"ש. אמנם כאן מדבר מפגם ברית קדש ביחוד."],[8,"","ואומרו \u0003למחטי לההיא בשר קדש דחתים ביה ברית קדישא\u0004, הכוונה על הנשמה הקדושה, שהיא נקשרת ונשמרת ע\"י ברית קדש כמ\"ש בזוהר (לך לך אות ת\"י), ומבשרי אחזה אלוה, מאי ומבשרי, ומעצמי מבעי ליה. אלא מבשרי ממש וכו', דתניא בכל זמנא דאתרשים בר נש בהאי רשימא קדישא דהאי את, מניה חמי לקב\"ה, מניה ממש, ונשמתא קדישא אתאחידת ביה. ואי לא זכי דלא נטיר להאי את, מה כתיב, מנשמת אלוה יאבדו, ע\"ש."],[8,"","וז\"ש כאן \u0003ויהא גרים למחטי לההיא בשר קדש\u0004, דהיינו, שמכח ההרהורים חוזרת הערלה שהיא הס\"א לנגוע בברית הקודש, שעי\"ז מסתלקת תיכף נשמת אלוה ממנו. וז\"ס שצעק העץ רשע אל תגע בי, (כמ\"ש בזהר בראשית דף רסג: בהשמטות, ובאבות דר\"נ פ\"א). כי העץ הוא היסוד, ועטרת היסוד ה\"ס עץ הדעת טוב ורע, (כמ\"ש בעה\"ח שער מ\"ג פ\"ג, ובספרי בית שער הכוונות דף מ\"ה ד\"ה ובחטא)."],[8,"","וז\"ש, \u0003וההוא דממונה על גיהנם דומה שמיה\u0004: ונק' \u0003דומה\u0004 מלשון דממה, כי נוטל ממנו נשמת החיים ומשאירו בדממה שהיא מיתה. ועוד אפשר לפרש, משום שהוא המלאך המביא את ההרהורים אל החוטא, ועושה מחשבותיו של הקב\"ה \u0003דומה\u0004 למחשבות של ילוד אשה. כי כל זמן שהאדם מבין שלא מחשבותיו מחשבותינו ולא דרכיו דרכינו, דהיינו דלית מחשבה תפיסא ביה כלל לא במחשבותיו ולא בהנהגתו, הרי לא יצויר כלל אצלו שיעלה על הדעת ח\"ו איזה הרהור אחריו ית',"],[8,"","אלא בסבת חטא נמצא מלאך \u0003דומה\u0004 מזדקק אליו, ומביא בו רוח שטות, לומר שילוד אשה דומה להשי\"ת בדעת ובשכל, ואז כבר מוכשר לכל מיני הרהורים ומושכו לגיהנם. הרי שכל כחו הוא בשם \u0003דומה\u0004, וז\"ס מי כמוך בעל גבורות ומי \u0003דומה\u0004 לך מלך ממית ומחיה. שבהכשל בדומה לך ח\"ו נמצאת המיתה, ובהבנה שאין דומה לו, נמצאים החיים. וז\"ש \u0003וכמה רבוא מלאכי חבלה בהדיה, וקאים על פתחא דגיהנם\u0004, כי ההרהורים שהוא מביא לאדם הם \u0003כמה רבוא\u0004 לאין קץ, וכל אלו הם על פתחא של \u0003גיהנם\u0004, כלומר, הוא הפתח שדרך בו מושכין את האדם לגיהנם, אך אינו הגיהנם עצמו."],[8,"","וז\"ש \u0003וכל אינון דנטרי ברית קדישא בהאי עלמא לית ליה רשו למקרב בהו\u0004: כלומר, אע\"פ שאינם נקיים לגמרי ועוד יש בהם בחינת עשיה טו\"ר, מ\"מ אם הם שומרי ברית הקדש. באופן שלא יבא פעם לידי הרהור, אין למלאך \u0003דומ\"ה\u0004 רשות למשכו לגיהנם."],[9,"","קלב) \u0003דוד מלכא בשעתא\u0004 וכו': דוד המלך, בשעה שקרה לו אותו מעשה, פחד. באותה שעה עלה דומה לפני הקב\"ה, ואמר לו, רבונו של העולם, כתוב בתורה, ואיש אשר ינאף את אשת איש. וכתוב, ואל אשת עמיתך וגו'. דוד, שחלל בריתו בערוה, מהו. אמר לו הקב\"ה, דוד צדיק הוא, וברית הקדוש על תקונו עומד, כי גלוי לפני, שבת שבע מוכנת לו מיום שנברא העולם."],[9,"","פירוש. אע\"פ שלא חטא, כמ\"ש חז\"ל כל האומר דוד חטא אינו אלא טועה (שבת נו. ) מ\"מ נפלה עליו יראה כמו שהיה חוטא ממש. ומפרש, שהיה זה מטעם קטרוגו של \u0003דומה\u0004. כמ\"ש לפנינו. \u0003כתיב בתורה ואיש אשר ינאף\u0004 וגו', \u0003וכתיב\u0004 וכו', מביא ב' כתובים אחד לעונש ואחד לאזהרה."],[9,"","וז\"ש, \u0003וברית קדישא\u0004 וכו', כי השיב לו, שלא היה לו ל\u0003דוד\u0004 הרהור עבירה, כי \u0003בת שבע\u0004 בת זוגיה היא מעת בריאת העולם (סנהדרין קז. ), וכיון שכן לא קלקל בריתו ח\"ו, \u0003וברית קדישא על תקוניה קיימא\u0004. וכד תאב לדידיה תאב. והטעם דנטיל לה אוריה מקודם לדוד, מפרש בזוהר (אחרי אות שצ\"ה), דנטל לה אוריה ברחמי, אע\"פ דלא הוית דיליה ע\"ש,"],[9,"","ויש להבין זה. שהרי דכר ונוקבא הם תרי פלגי גופא, וא\"כ אם הוא בחינת פלג גופא של דוד המלך, איך לקחה אוריה שאין לו שום שייכות עמה. והענין הוא, כי \u0003בת שבע\u0004 היא באמת נוקביה ד\u0003דוד\u0004 מיום בריאת העולם. כי דוד הוא הדכר שבמלכות, ובת שבע היא הנוקבא שבמלכות. אלא, כמו שבעת תיקון המלכות לאצילות העולמות, היה שם בחינת עלית המלכות לבינה, בכדי להמתיקה במדת הרחמים, כן היתה בת שבע צריכה למיתוק הזה בג\"ר, שבלי מיתוק זה לא היתה ראויה כלל להוליד נשמת שלמה המלך."],[9,"","ואוריה החתי היה נשמה גבוהה מאד, כי היה כולו מבחינת ג\"ר, ושמו מוכיח עליו, \u0003אור-יה\u0004, כי לא היה בו מבחינת ו\"ק שהוא \u0003ו\"ה\u0004 כלום. ולפיכך בכדי להמתיק את בת שבע במדת הרחמים, לקחה אוריה שהוא בחינת ג\"ר, ונמתקה על ידו, ואח\"כ היתה ראויה למלכות ישראל. וז\"ש \u0003דנטל לה אוריה ברחמי\u0004, דהיינו בכדי להמתיקה ברחמים, שהוא בשם \u0003י\"ה שבאוריה\u0004. וע\"כ נטל לה אע\"ג דלא הוית דיליה. ועוד יתבאר להלן."]],[[0,"","לָמָּה נִקְרָא יִרְאַת ה' בִּגְלַל שֶׁהוּא עֵץ שֶׁל טוֹב וָרָע. זָכָה בֶּן הָאָדָם - הִנֵּה טוֹב. וְאִם לֹא זָכָה - הִנֵּה רָע. וְלָכֵן שׁוֹרָה בְּמָקוֹם זֶה יִרְאָה, וְזֶה שַׁעַר לְהִכָּנֵס לְכָל טוּב שֶׁבָּעוֹלָם. שֵׂכֶל טוֹב - אֵלֶּה שְׁנֵי שְׁעָרִים שֶׁהֵם כְּאֶחָד. רַבִּי יוֹסֵי אָמַר, שֵׂכֶל טוֹב - זֶה עֵץ הַחַיִּים, שֶׁהוּא שֵׂכֶל טוֹב בְּלִי רָע כְּלָל. וְעַל שֶׁלֹּא שׁוֹרֶה בּוֹ רָע הוּא שֵׂכֶל טוֹב בְּלֹא רָע."],[1,"","לְכָל עֹשֵׂיהֶם - אֵלּוּ חַסְדֵי דָוִד הַנֶּאֱמָנִים, תּוֹמְכֵי הַתּוֹרָה. וְאוֹתָם תּוֹמְכֵי הַתּוֹרָה כִּבְיָכוֹל הֵם עוֹשִׂים. כָּל אֵלּוּ שֶׁעוֹסְקִים בַּתּוֹרָה אֵין בָּהֶם עֲשִׂיָּה בְּעוֹד שֶׁעוֹסְקִים בָּהּ. אוֹתָם שֶׁתּוֹמְכִים בָּהֶם יֵשׁ בָּהֶם עֲשִׂיָּה, וּבְכֹחַ זֶה כָּתוּב תְּהִלָּתוֹ עֹמֶדֶת לָעַד, וְעוֹמֵד הַכִּסֵּא עַל עָמְדוֹ כָּרָאוּי."],[2,"","רַבִּי שִׁמְעוֹן הָיָה יוֹשֵׁב וְעוֹסֵק בַּתּוֹרָה בַּלַּיְלָה שֶׁהַכַּלָּה מִתְחַבֶּרֶת בְּבַעְלָהּ. שֶׁשָּׁנִינוּ, כָּל אוֹתָם הַחֲבֵרִים בְּנֵי הֵיכַל הַכַּלָּה, הִצְטָרְכוּ בְּאוֹתוֹ לַיְלָה שֶׁהַכַּלָּה עֲתִידָה לִהְיוֹת לַמָּחֳרָת בְּתוֹךְ הַחֻפָּה עִם בַּעְלָהּ לִהְיוֹת עִמָּהּ כָּל אוֹתוֹ הַלַּיְלָה, וְלִשְׂמֹחַ עִמָּהּ בְּתִקּוּנֶיהָ שֶׁהִיא מִתְתַּקֶּנֶת לַעֲסֹק בַּתּוֹרָה, מִתּוֹרָה לִנְבִיאִים, וּמִנְּבִיאִים לִכְתוּבִים, וּבִדְרָשׁוֹת הַפְּסוּקִים וּבְסוֹדוֹת הַחָכְמָה, בִּגְלַל שֶׁאֵלּוּ הֵם תִּקּוּנֶיהָ וְתַכְשִׁיטֶיהָ, וְהִיא וְעַלְמוֹתֶיהָ נִכְנֶסֶת וְעוֹמֶדֶת עַל רָאשֵׁיהֶם וּמִתְתַּקֶּנֶת בָּהֶם, וּשְׂמֵחָה בָהֶם כָּל אוֹתוֹ הַלַּיְלָה, וְלַמָּחֳרָת לֹא נִכְנֶסֶת לַחֻפָּה אֶלָּא יַחַד אִתָּם. וְאֵלֶּה נִקְרָאִים בְּנֵי הַחֻפָּה. וְכֵיוָן שֶׁנִּכְנֶסֶת לַחֻפָּה, הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹאֵל עֲלֵיהֶם וּמְבָרֵךְ אוֹתָם, וּמְעַטֵּר אוֹתָם בַּעֲטֶרֶת הַכַּלָּה. אַשְׁרֵי חֶלְקָם."],[3,"","וְהָיָה רַבִּי שִׁמְעוֹן וְכָל הַחֲבֵרִים מְרַנְּנִים בְּרִנַּת הַתּוֹרָה וּמְחַדְּשִׁים דִּבְרֵי תוֹרָה כָּל אֶחָד וְאֶחָד מֵהֶם, וְהָיָה שָׂמֵחַ רַבִּי שִׁמְעוֹן וְכָל שְׁאָר הַחֲבֵרִים. אָמַר לָהֶם רַבִּי שִׁמְעוֹן, בָּנַי, אַשְׁרֵי חֶלְקְכֶם, בִּגְלַל שֶׁמָּחָר לֹא תִכָּנֵס הַכַּלָּה לַחֻפָּה אֶלָּא יַחַד אִתְּכֶם. בִּגְלַל שֶׁכֻּלָּם שֶׁמְּתַקְנִים תִּקּוּנֶיהָ בַּלַּיְלָה הַזֶּה וּשְׂמֵחִים בָּהּ, כֻּלָּם יִהְיוּ רְשׁוּמִים וּכְתוּבִים בְּסֵפֶר הַזִּכְרוֹנוֹת, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְבָרְכָם בְּשִׁבְעִים בְּרָכוֹת וַעֲטָרוֹת שֶׁל עוֹלָם הָעֶלְיוֹן."],[4,"","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (תהלים יט) הַשָּׁמַיִם מְסַפְּרִים כְּבוֹד אֵל וְכוּ'. פָּסוּק זֶה הֲרֵי הֶעֱמַדְנוּהוּ. אֲבָל בִּזְמַן זֶה שֶׁהַכַּלָּה מִתְעוֹרֶרֶת לְהִכָּנֵס לַחֻפָּה, לַמָּחֳרָת מִתְתַּקֶּנֶת וּמְאִירָה בְּקִשּׁוּטֶיהָ יַחַד עִם הַחֲבֵרִים שֶׁשָּׂמְחוּ עִמָּהּ כָּל אוֹתוֹ הַלַּיְלָה, וְהִיא שְׂמֵחָה אִתָּם."],[5,"","וְלַמָּחֳרָת כַּמָּה אוּכְלוּסִים, צְבָאוֹת וּמֶרְכָּבוֹת חֲיָלוֹת וּמַחֲנוֹת אִתָּהּ, וְהִיא וְכֻלָּם מְחַכִּים לְכָל אֶחָד וְאֶחָד שֶׁתִּקְּנוּ אוֹתָהּ בַּלַּיְלָה הַזֶּה. כֵּיוָן שֶׁמִּתְחַבְּרִים כְּאֶחָד וְהִיא רוֹאָה אֶת בַּעְלָהּ, מַה כָּתוּב הַשָּׁמַיִם מְסַפְּרִים כְּבוֹד אֵל. הַשָּׁמַיִם - זֶה הֶחָתָן שֶׁנִּכְנָס לַחֻפָּה. מְסַפְּרִים - מְאִירִים כְּזֹהַר הַסַּפִּיר שֶׁמֵּאִיר וְזוֹהֵר מִסּוֹף הָעוֹלָם וְעַד סוֹף הָעוֹלָם."],[6,"","כְּבוֹד אֵל - זֶה כְּבוֹד כַּלָּה שֶׁנִּקְרָא אֵל, שֶׁכָּתוּב (תהלים ז) וְאֵל זוֹעֵם בְּכָל יוֹם. בְּכָל יְמֵי הַשָּׁנָה נִקְרָא אֵל, וְכָעֵת כְּשֶׁהֲרֵי נִכְנֶסֶת לַחֻפָּה, נִקְרָא כָּבוֹד וְנִקְרָא אֵל. כָּבוֹד עַל כָּבוֹד. אוֹר עַל אוֹר. שִׁלְטוֹן עַל שִׁלְטוֹן."],[7,"","וְאָז בְּאוֹתָהּ שָׁעָה שֶׁהַשָּׁמַיִם נִכְנָס לַחֻפָּה וּבָא וּמֵאִיר לָהּ, כָּל אוֹתָם הַחֲבֵרִים שֶׁהִתְקִינוּ אוֹתָהּ, כֻּלָּם מִתְפָּרְשִׁים בִּשְׁמוֹתָם שָׁם, וְזֶהוּ שֶׁכָּתוּב וּמַעֲשֵׂה יָדָיו מַגִּיד הָרָקִיעַ. מַעֲשֵׂה יָדָיו - אֵלֶּה אוֹתָם בַּעֲלֵי קִיּוּם הַבְּרִית יַחַד עִם הַכַּלָּה. וְאוֹתָם בַּעֲלֵי קִיּוּם הַבְּרִית נִקְרָאִים מַעֲשֵׂה יָדָיו, כְּמוֹ שֶׁנֶּאֱמַר וּמַעֲשֵׂה יָדֵינוּ כּוֹנְנֵהוּ, זוֹ בְּרִית הַקַּיֶּמֶת שֶׁחֲתוּמָה בִּבְשַׂר בֶּן הָאָדָם."],[8,"","רַב הַמְנוּנָא הַזָּקֵן אָמַר כָּךְ, (קהלת ה) אַל תִּתֵּן אֶת פִּיךְ לַחֲטִיא אֶת בְּשָׂרֶךְ - שֶׁלֹּא יִתֵּן בֶּן אָדָם אֶת פִּיו לְהָבִיא לְהִרְהוּר רַע וְיִגְרֹם לְהַחֲטִיא אוֹתוֹ בְּשַׂר קֹדֶשׁ שֶׁחָתוּם בּוֹ בְּרִית הַקֹּדֶשׁ, שֶׁאִם עוֹשֶׂה כָּךְ, מוֹשְׁכִים אוֹתוֹ לַגֵּיהִנֹּם. וְאוֹתוֹ מְמֻנֶּה עַל הַגֵּיהִנֹּם דּוּמָ\"ה שְׁמוֹ, וְכַמָּה רִבּוֹאוֹת שֶׁל מַלְאֲכֵי חַבָּלָה יַחַד אִתּוֹ, וְעוֹמֵד עַל פֶּתַח הַגֵּיהִנֹּם, וְכָל אוֹתָם שֶׁשָּׁמְרוּ בְּרִית הַקֹּדֶשׁ בָּעוֹלָם הַזֶּה אֵין לוֹ רְשׁוּת לִקְרַב אֲלֵיהֶם."],[9,"","דָּוִד הַמֶּלֶךְ, בְּשָׁעָה שֶׁקָּרָה לוֹ אוֹתוֹ מַעֲשֶׂה, פָּחַד. בְּאוֹתָהּ שָׁעָה עָלָה דוּמָ\"ה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאָמַר לוֹ: רִבּוֹן הָעוֹלָם, כָּתוּב בַּתּוֹרָה (ויקרא כ) וְאִישׁ אֲשֶׁר יִנְאַף אֶת אֵשֶׁת אִישׁ, וְכָתוּב (שם יח) וְאֶל אֵשֶׁת עֲמִיתְךְ וְכוּ'. דָּוִד שֶׁקִּלְקֵל בְּרִית בְּעֶרְוָה מַהוּ (מה דינו) אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: דָּוִד צַדִּיק הוּא, וּבְרִית הַקֹּדֶשׁ עַל תִּקּוּנוֹ עוֹמֵד, שֶׁהֲרֵי לְפָנַי גָּלוּי שֶׁמְּזֻמֶּנֶת לוֹ בַּת שֶׁבַע מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם."]]],[["אָמַר לֵיהּ אִי קַמָּךְ גָּלֵי קַמֵּיהּ לָא גָלֵי. אָמַר לֵיהּ וְתוּ בְּהֶתֵּירָא הֲוָה מַה דְּהֲוָה. דְּהָא כָּל אִנּוּן דְּעָאלוּ לִקְרָבָא לָא עָאל חַד מִנַּיְיהוּ עַד דְּאַפְטַר בְּגֵט לְאִנְתְּתֵיהּ. אָמַר לֵיהּ אִי הָכִי הֲוָה לֵיהּ לְאוֹרְכָא תְּלַת יַרְחֵי וְלָא אוֹרִיךְ. אָמַר לֵיהּ בְּמַאי אוֹקִים מִלָּה בְּאֲתַר דְּחַיְישִׁינָן דְּהִיא מְעוּבֶּרֶת, וְגָלֵי קֳדָמַי דְאוּרִיָּה לָא קָרִיב בָּהּ לְעָלְמִין דְּהָא שְׁמִי חָתִים בְּגַוֵּיהּ לְסַהֲדוּתָא. כְּתִיב אוּרִיָּה וּכְתִיב אוּרִיָּהוּ שְׁמִי חָתוּם בַּהֲדֵיהּ (בהדייהו) דְּלָא שִׁמֵּשׁ בָּהּ לְעָלְמִין.","אָמַר לֵיהּ, מָארֵי דְעָלְמָא הָא מָה דְּאֲמָרִית אִי קַמָּךְ גָּלֵי דְלָא שְׁכִיב בַּהֲדָהּ אוּרִיָּה, קַמֵּיהּ מִי גָלֵי, הֲוָה לֵיהּ לְאוֹרְכָא לָהּ תְּלַת יַרְחֵי. וְתוּ אִי יָדַע דְּלָא שְׁכִיב בַּהֲדָהּ לְעָלְמִין אַמַּאי שָׁדַר לָהּ דָּוִד וּפְקֵיד עֲלֵיהּ לְשַׁמָּשָׁא בְּאִנְתְּתֵיהּ דִּכְתִיב, (שמואל ב י״א:ח׳) רֵד לְבֵיתְךָ וּרְחַץ רַגְלֶיךָ.","אָמַר לֵיהּ וַדַּאי לָא יָדַע, אֲבָל יַתִּיר מִתְּלַת יַרְחֵי אוֹרִיךְ דְּהָא אַרְבַּע יַרְחֵי הֲווּ. דְּהָכִי תָּנִינָן בַּחֲמִשָּׁה וְעֶשְׂרִים דְּנִיסָן אַעֲבַר דָּוִד כָּרוֹזָא בְּכָל יִשְׂרָאֵל, וְהֲווּ עִם יוֹאָב בְּשִׁבְעָה יוֹמִין דְּסִיוָן וְאֲזְלוּ וְחֲבָּלוּ אַרְעָא דִבְנִי עַמּוֹן. סִיוָן וְתַמּוּז וְאָב וְאֱלוּל אִשְׁתָּהוּ שָׁם. וּבְאַרְבָּעָה וְעֶשְׂרִים בֶּאֱלוּל הֲוָה מַה דְּהֲוָה מִבַּת שֶׁבַע. וּבְיוֹמָא דְכִפּוּרֵי מָחַל לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, הַהוּא חוֹבָה. וְאִית דְּאַמְרֵי בְּז' בְּאֲדָר אַעֲבַר כָּרוֹזָא וְאִתְכַּנָּשׁוּ בְּחֲמֵיסַר דְּאִיָּיר, וּבְחֲמֵיסַר בֶּאֱלוּל הֲוָה מַה דְּהֲוָה מִבַּת שֶׁבַע, וּבְיוֹמָא דְכִפּוּרָא אִתְבְּשַׂר (שמואל ב י״ב:י״ג) גַּם יְיָ הֶעֱבִיר חַטָּאתְךָ לֹא תָמוּת. מַאי לא תָמוּת, לא תָמוּת בִּידָא דְדוּמָה.","אָמַר דּוּמָה מָארֵי דְעָלְמָא הָא מִלָּה חֲדָא אִית לִי גַּבֵּיהּ דְּאִיהוּ אַפְתַּח פּוּמֵיהּ וְאָמַר (שמואל ב י״ב:ה׳) חַי יְיָ כִּי בֶּן מָוְת הָאִישׁ הָעוֹשֶׂה זֹאת וְאִיהוּ דָּן לְנַפְשֵׁיהּ טְרוֹנְיָיא אִית לִי עֲלֵיהּ. אָמַר לֵיהּ, לֵית לָךְ רְשׁוּ דְּהָא אוֹדֵי לְגַבָּאי וְאָמַר חָטָאתִי לַה' וְאַף עַל גַּב דְּלָא חָב. אֲבָל בַּמֶּה דְחָטָא בְּאוּרִיָּה עוֹנָשָׁא כְּתָבִית עֲלֵיהּ וְקִבֵּל. מִיָּד אַהֲדַר דּוּמָ\"ה לְאַתְרֵיהּ בְּפַחֵי נֶפֶשׁ.","וְעַל דָּא אָמַר דָּוִד (תהילים צ״ד:י״ז) לוּלֵי (צ\"ד א') יְיָ עֶזְרָתָה לִי כִּמְעַט שָׁכְנָה דּוּמָה נַפְשִׁי. לוּלֵי ה' עֶזְרָתָה לִי דְּהֲוָה אַפּוֹטְרוֹפָּא דִילִי. כִּמְעַט שָׁכְנָה וְגו'. מַהוּ כִּמְעַט, כְּחוּטָא דַּקִּיק כְּשִׁיעוּרָא דְּאִית בֵּינִי וּבֵין סִטְרָא אָחֳרָא, כְּהַהוּא שִׁעוּרָא הֲוַת דְּלָא שָׁכְנָה דּוּמָה נַפְשִׁי.","וּבְגִין כָּךְ בָּעֵי לְאִסְתַּמְרָא בַּר נָשׁ דְּלָא יֵימָא מִלָּה כְּדָוִד. בְּגִין דְּלָא יָכִיל לְמֵימַר לְדוּמָה (קהלת ה) כִּי שְׁגָגָה הִיא, כְּמָה דְּהֲוָה לְדָוִד וְנָצַח לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא בְּדִינָא. לָמָּה יִקְצוֹף הָאֱלֹהִים עַל קוֹלֶךְ עַל הַהוּא קוֹל דְּאִיהוּ אָמַר. וְחִבֵּל אֶת מַעֲשֵׂה יָדֶיךָ דָּא בְּשַׂר קֹדֶשׁ בְּרִית קַדִּישָׁא דְּפָגִים וְאִתְמְשַׁךְ בְּגֵּיהִנֹּם עַל יְדָא דְדוּמָה.","וּבְגִין כָּךְ (תהילים י״ט:ב׳) וּמַעֲשֵׂה יָדָיו מַגִּיד הָרָקִיעַ אִלֵּין אִנּוּן חַבְרַיָּיא דְּאִתְחַבָּרוּ בְּכַלָּה דָא וּמָארֵי קַיָּימָא דִילָהּ. מַגִּיד וְרָשִׁים כָּל חַד וְחַד. מָאן הָרָקִיעַ. דָּא אִיהוּ (ל\"ד א) הָרָקִיעַ דְּבֵיהּ חַמָּה וּלְבָנָה וְכֹכְבַיָא וּמַזָּלֵי, וְדָא אִיהוּ סֵפֶר (יתרו דף ע\"א) זִכָּרוּן. אִיהוּ מַגִּיד וְרָשִׁים לְהוּ וּכְתִיב לְהוּ לְמֶהֱוֵי בְּנִי הֵיכָלָא וּלְמֶעְבַּד רְעוּתְהוֹן תָּדִיר.","(תהילים י״ט:ג׳) יוֹם לְיוֹם יַבִּיעַ אוֹמֶר, יוֹמָא קַדִּישָׁא מֵאִנּוּן יוֹמִין עִלָּאִין דְּמַלְכָּא מְשַׁבְּחִין לוֹן לְחַבְרַיָיא וְאָמְרִין הַהִיא מִלָּה דְּאָמַר כָּל חַד לְחַבְרֵיהּ. יוֹמָא לְיוֹמָא יַבִּיעַ הַהוּא אוֹמֶר וּמְשַׁבַּח לֵיהּ. וְלַיְלָה לְלַיְלָה כָּל דַּרְגָא דְּאַשְׁלִים (נ\"א דשליט) בְּלֵילְיָא מְשַׁבַּח דָּא לְדָא הַהוּא דַּעַת דְּכָל חַד מְחַבְרֵיהּ, וּבִשְׁלִימוּ (ס\"א וברחימו) סַגֵּי אִתְעֲבִידוּ לוֹן חַבְרִין וּרְחִימִין.","אֵין אוֹמֶר וְאֵין דְּבָרִים בִּשְׁאָר מִילִין דְּעָלְמָא. דְּלָא אִשְׁתַּמְעוּ קַמֵּי מַלְכָּא קַדִּישָׁא וְלָא בָּעֵי לְמִשְׁמַע לוֹן. אֲבָל הָנֵי מִילֵי בְּכָל הָאָרֶץ יָצָא קַוָם. עַבְדֵי מְשִׁיחָא אִנּוּן מִלִּין מְדוִֹרִי עִלָּאֵי וּמְדוֹרֵי תַּתָּאֵי (לעיל דף ה' ב'), מֵאִלִּין אִתְעֲבִידוּ רְקִיעִין וּמֵאִלֵּין אֶרֶץ מֵהַהִיא תּוּשְׁבַּחְתָּא. וְאִי תֵימָא דְּאִנּוּן מִלִּין בְּאֲתַר חָד. מְשַׁטְּטָא בְּעָלְמָא בִּקְצֵה תֵבֵל מִלֵּיהֶם."],[[0,"","קלג) \u0003אמר ליה אי\u0004 וכו': אמר לו דומה, אם לפניך גלוי, לפניו לא גלוי. אמר לו הקב\"ה, ועוד, כל מה שהיה בהתר היה. לפי שכל היוצאים למלחמה, אף אחד מהם אינו יוצא עד שיתן גט לאשתו. אמר לו, אם כן, היה לו לחכות שלשה חדשים, ולא המתין, אמר לו, במה הדבר אמור, רק במקום שאנו יראים אולי היא מעוברת, וגלוי לפני, שאוריה. מעולם לא קרב אליה, כי שמי חתום בו לעדות, שכתוב \u0003אוריה\u0004, שהוא אותיות אור י\"ה. וכתוב \u0003אוריהו\u0004, שהוא אותיות אור יה\"ו. שחתום בו שמי, לעדות, שלא שמש בה מעולם."],[0,"","ביאור הדברים, יש להבין מה ענין השם \u0003י\"ה שבאוריה\u0004 להעיד עליו שלא נגע ב\u0003בת שבע לעלמין\u0004. והנה זה מבואר בכתוב (שמואל ב' י\"ב) במשל של נתן הנביא, כי מדמה את \u0003דוד\u0004 לעשיר ו\u0003אוריה\u0004 לרש, ו\u0003בת שבע\u0004 לכבשת הרש, ואת הס\"א ל\u0003הלך\u0004. ואומר, ש\u0003לרש אין כל כי אם כבשה אחת קטנה\u0004 וכו'. וסודם של הדברים, כי אוריה היה מבחינת ג\"ר בחסרון ו\"ק, כדיוק של הזוהר \u0003כתיב אוריה וכתיב אוריהו\u0004, כי (בירמיה כ\"ו) כתיב השם הזה \u0003אוריהו\u0004 ב\u0003יה\"ו\u0004 ש\u0003י\"ה\u0004 הם ג\"ר וה\u0003ו'\u0004 הוא ו\"ק אבל כאן כתוב רק \u0003אוריה\u0004 בלי ו', והוא להורות שלא היה בו מבחינת ו\"ק כלום, אלא חכמה בחוסר חסדים."],[0,"","ולפיכך נבחן לרש בלי כל, כי האור דחסדים מרומז \u0003בכל\u0004, וז\"ש \u0003כי אם כבשה אחת קטנה אשר קנה ויחיה\u0004, שהיא בת שבע שקנה אותה, ומורה בזה שאינו מבחינת חלק נשמתו אלא רק קנה אותה, בכדי להחיות אותה ולתקנה ברחמים, שזהו \u0003אשר קנה ויחיה\u0004, ואומר עוד \u0003ותגדל עמו ועם בניו יחדיו\u0004. זה מורה שהשפיע לה הגדלות שלו כמו לבניו. דהיינו בדרך ש\u0003מפתו תאכל ומכוסו תשתה ובחיקו תשכב\u0004, אמנם בל נטעה ונחשוב כי גם קרב אליה, ע\"כ מסיים ותהי לו \u0003כבת\u0004, ולא לאשה,"],[0,"","הרי שהכתוב מעיד שאוריה לא קרב אליה. אלא שהזוהר מפרש הטעם למה לא קרב אליה, וע\"כ אומר \u0003כתיב אוריה וכתיב אוריהו, שמי חתום בהדיה דלא שמש בה לעלמין\u0004, דהיינו השם \u0003י\"ה\u0004 בלי \u0003ו'\u0004, שזה מורה שהוא חסר בחינת חסדים, שהיא \u0003ו',\u0004 וע\"כ לא יכול לקרב אליה, כי אין זווג בלי אור דחסדים. ונמצא שם \u0003י\"ה\u0004 דחתים בשמיה מעיד עליו שלא היה ראוי כלל להזדווג עמה."],[1,"","קלד) \u0003אמר ליה מארי\u0004 וכו': אמר לו, רבונו של עולם, הנה זה מה שאמרתי, אם לפניך גלוי שאוריה לא שכב עמה, לפניו מי גלוי, היה לו לחכות שלשה חדשים. ועוד, אם תאמר, שדוד ידע שלא שכב עמה מעולם, למה שלח אותו דוד וצוה אותו לשמש באשתו, שכתוב, רד לביתך ורחץ רגליך."],[2,"","קלה) \u0003אמר ליה ודאי\u0004 וכו': אמר לו, ודאי לא ידע, אבל חיכה יותר משלשה חדשים, כי ארבעה חדשים היו. שלמדנו, בחמשה ועשרים בניסן העביר דוד כרוז בכל ישראל ללכת למלחמה. והיו עם יואב בז' בסיון, והלכו והשחיתו ארץ בני עמון. וסיון תמוז אב ואלול נתעכבו שם. ובכ\"ד באלול היה מה שהיה בבת שבע. וביום הכפורים מחל לו הקב\"ה אותו העון. ויש אומרים, בז' באדר העביר הכרוז, ונתאספו בט\"ו באייר, ובחמשה עשר באלול היה מה שהיה מבת שבע, וביום הכפורים נתבשר, גם ה' העביר חטאתך לא תמות. מהו לא תמות. היינו לא תמות ביד דומה."],[2,"","ביאור הדברים, כי \u0003דומה\u0004 הוא הממונה על גילוי עריות, וחטא זה נתכפר לו ביה\"כ ונמצא שלא ימות \u0003בידא דדומה\u0004. אמנם מיתתו היתה מחמת החטא של אוריה, שהרגו בחרב בני עמון. כמו שהעיד עליו הכתוב (מלכים א' ט\"ו) אשר עשה דוד את הישר בעיני ה' ולא סר מכל אשר צוהו כל ימי חייו רק בדבר אוריה החתי. וז\"ש \u0003לא תמות בידא דדומה\u0004, שהוא הממונה על גילוי עריות. רק בדבר \u0003אוריה החתי\u0004."],[3,"","קלו) \u0003אמר דומה מארי\u0004 וכו': אמר דומה: רבונו של עולם, דבר אחד יש לי אצלו. כי הוא פתח פיו ואמר, חי ה' כי בן מות האיש העושה זאת. והוא דן את עצמו למות, ע\"כ כח יש לי עליו להמיתו. אמר לו אין לך רשות להמיתו, כי הודה לפני ואמר, חטאתי לה', ואע\"פ שלא חטא. אבל במה שחטא בהריגת אוריה, כתבתי עליו עונש, וקבלו. מיד שב דומה למקומו במפח נפש. \u0003טרוניא\u0004 הוא מלשון, אין הקב\"ה בא בטרוניא עם בריותיו (פסיקתא רבתי, כי תשא) שפירושו בזרוע, בכח."],[3,"","ביאור הדברים, כי הנה נתבאר לעיל, בסוד מצות המילה שקשורה באות ברית השם אלוה (כנ\"ל אות קל\"א עש\"ה) והנה ב\u0003ה'\u0004 זו דשם אלוה, שהיא המלכות כלולות ב' נקודות דין ורחמים, (כנ\"ל במאמר ב' נקודין) וכל תיקון הברית הוא שכח הדין יהיה גניזא וטמירא והרחמים באתגליא, ואז שורה עליו השם אלוה. כי אע\"פ שישנה שם גם המלכות, שעליה היה הצמצום הא', שהוא בחינת הדין, שממנה יונקים כל החיצונים, עכ\"ז כיון שהיא טמירא ונעלמה, ורק מדת הרחמים שמבינה היא באתגליא, אין כח לחיצונים להאחז בה. כמ\"ש לעיל \u0003וכל אינון דנטרו ברית קדישא בהאי עלמא לית ליה רשו למקרב בהו\u0004."],[3,"","אבל המקלקל הברית, נמצא מגלה בחינת הדין שבמלכות, דהיינו ב\u0003ה'\u0004 דאלוה, ותיכף מתקרבין לה כל החיצונים לינק ממנה, כי היא חלקם וכל חיותם, וע\"כ תיכף מסתלקת הנשמה הק' שהיא השם אלוה, בסו\"ה מנשמת אלוה יאבדו (איוב ד')."],[3,"","והנה דוד עצמו היה מבחינת מלכות זו הממותקת במדת הרחמים, וע\"כ היה צריך לשמירה יתירה, שלא יתגלה בו מבחינת הדין שבמלכות. וע\"כ בזה שאמר, \u0003חי ה' כי בן מות האיש העושה זאת\u0004. שדן דינא שהמקלקל ברית ליתן כבשת הרש לפני ההלך. שהוא הס\"א, דינו במיתה, נתגלה בו עצמו בחי' הדין לפני הס\"א, שהוא המלאך \u0003דומה\u0004, ורצה ע\"כ להאחז בנשמת דוד, כי ע\"י דיבורים אלו נתגלה כח הדין הגנוז וטמיר בו."],[3,"","וז\"ש המלאך דומה \u0003הא מלה חדא אית לי גביה, דאיהו אפתח פומיה ואמר, חי ה' כי בן מות האיש העושה זאת. ואיהו דן לנפשיה\u0004, דהיינו ע\"י הדיבורים, שדן המקלקל ברית למיתה, נמצא \u0003דן לנפשיה\u0004, כי נגלה בזה הדין הטמיר והגניז שבנפשיה, וע\"כ \u0003טרונייא אית לי עליה\u0004, יש לי שליטה עליו לינק מנשמתו."],[3,"","וז\"ש, \u0003אמר ליה לית לך רשו, דהא אודי לגבאי ואמר חטאתי לה' ואע\"ג דלא חב\u0004: כבר נתבאר שע\"י הדיבורים שאמר ודן דינא \u0003אנפשיה\u0004, גילה בחינת הדין לפני הס\"א, כמו הפוגם בריתו, ורצה המלאך דומה להאחז בנשמתו ולמשכה לגיהנם. כנ\"ל בסמוך. ואמר קב\"ה דכבר התוודה ועשה תשובה על גילוי עריות \u0003אע\"ג דלא חב\u0004 כלל בזה כנ\"ל, וע\"כ מועילה לו תשובה זו על מה ש\u0003דן לנפשיה\u0004, וע\"כ \u0003לית לך רשו למקרב לגביה\u0004."],[3,"","וז\"ש, \u0003אבל מה דחטא באוריה עונשא כתבית עליה וקבל\u0004: כלומר, \u0003אבל בחטא\u0004 שהרג את \u0003אוריה\u0004 בחרב בני עמון, הנה כבר קבל עונשיה ממני, ואין לך עסק בזה, כי אתה ממונה רק על גילוי עריות בלבד. \u0003מיד אהדר דומה לאתריה בפחי נפש\u0004. דהיינו, לפתחא דגיהנם, שהוא אתריה כנ\"ל."],[4,"","קלז) \u0003ועל דא אמר\u0004 וכו': ועל זה אמר דוד. לולי ה' עזרתה לי כמעט שכנה \u0003דומה\u0004 נפשי. לולי ה' עזרתה לי, היינו, לולי שנעשה שומר ומשגיח עלי, כלפי המלאך דומה. כמעט שכנה וגו', מהו כמעט. היינו כשיעור חוט דק שיש ביני ובין הצד האחר, כשיעור ההוא היה, שלא שכנה \u0003דומה\u0004 נפשי. היינו עם המלאך דומה בגיהנם. \u0003אפוטרופוס\u0004, היינו שומר ומשגיח, כי תרגום ויפקד פקידים, הוא, וימני אפוטרופוס (בראשית מ\"א ל\"ד)."],[4,"","ביאור הדברים, דוד ה\"ס מלכות, שעליה כתוב רגליה יורדות מות (משלי ה'). כי היא בחינת הסיום דקדושה, שממנה מתקיימים הס\"א והקליפות, בסו\"ה ומלכותו בכל משלה (תהלים ק\"ג). אמנם כשהמלכות בתיקונה במדת הרחמים, על דרך שאמר רבי חייא לעיל (אות קכ\"ב) כי אז נבחנת לב' נקודין, שהם נקודת הדין מעצמה, ונקודת הרחמים שקבלה מבינה, והדין שבה גניזא וטמירא, ורק הרחמים שבה קיימא באתגליא ע\"ש."],[4,"","וע\"י התיקון הזה אין לו לס\"א מהארת המלכות אלא נהירו דקיק בלבד, שהוא רק בחינת שורש מספיק לקיום הקליפות, אבל אין להם שום כח של התפשטות. ושורש זה נק' ג\"כ בשם \u0003חוטא דקיק\u0004, שפירושו שורש דק לחטאים. ע\"ד שאמרו חז\"ל בתחילה דומה לחוט של עכביש, ואח\"כ נעשה כעבותות העגלה (סוכה נ\"ב. ) ומכונה בשם \u0003דקיק\u0004, על היות הדין טמיר וגניז בנקודת הרחמים כנ\"ל."],[4,"","אבל הפוגם בריתו גורם שתתגלה נקודת הדין שבמלכות, ואז מתקרבות הקליפות אליה ויונקות ממנה שפע מרובה, ומקבלות כח להתפשטות גדולה. והאיש העושה זאת מאבד בידים את נשמתו, בסו\"ה מנשמת אלוה יאבדו (איוב ד'), וכשזוכה ועושה תשובה, חוזר ומתקן את המלכות בתיקון דמדת הרחמים, שע\"כ נק' בשם תשובה שהיא אותיות \u0003תשוב ה'\u0004 דהיינו שמשיבה למקומה למדת הרחמים, וכח הדין חוזר ונגנז בה בפנימיותה, בסוד נהירו \u0003דקיק\u0004 בלבד."],[4,"","וזה אמרו \u0003לולי ה' עזרתה לי דהוה אפוטרופא דילי\u0004. דהיינו, שקבל תשובתי, ודחה למלאך דומה לאתריה, כנ\"ל, כי חזר והשיב המלכות למקומה למדת הרחמים ולא השאיר ממדת הדין רק נהירו דקיק, \u0003כמעט, כחוטא דקיק, כשיעורא דאית ביני ובין הס\"א\u0004. דהיינו, רק כאותו השיעור המועט המוכרח להשאר בין המלכות לס\"א, כדי ליתן לה בחינת קיום בהארה מועטת, הנק' \u0003חוטא דקיק, כההוא שיעורא הות דלא שכנה דומה נפשי\u0004, הנה זה השיעור הציל אותי שלא נפלתי ביד המלאך \u0003דומה\u0004, כלומר, כי לולא חזר כח הדין שבמלכות להיות כשיעור \u0003חוטא דקיק\u0004, כבר שכנתי בידו של \u0003דומה\u0004."],[5,"","קלח) \u0003ובג\"כ בעי לאסתמרא\u0004 וכו': ומשום זה צריך האדם להשמר שלא יאמר דבר כדוד, משום שאינו יכול לומר למלאך דומה, כי שגגה הוא (קהלת ה') כמו שהיה לדוד, שנצחו הקב\"ה בדין. למה יקצוף אלקים על קולך (שם) היינו על אותו הקול שאמר. וחבל את מעשה ידיך, היינו בשר קדש, שהוא ברית קדש שפגם, ונמשך לגיהנם על ידי דומה."],[5,"","ביאור הדברים, יש ב' בחינות של תשובה: א) תשובה מיראה, שזדונות נעשים לו כשגגות. ב) תשובה מאהבה, שזדונות נעשים לו כזכויות (יומא פו:). והביאור הוא, כי מטרם גמר התיקון, כל עוד שצריכים כח הדין בעולם, בסו\"ה והאלהים עשה שיראו מלפניו (קהלת ג'), נמצאת המלכות מחוייבת לקיים את הס\"א עכ\"פ בשיעור דנהירו דקיק, כדי שלא יתבטלו הקליפות והס\"א. וע\"כ כל תיקונה של המלכות הוא בסוד ב' נקודין, רחמים ודין, אלא שהדין הוא גניז וטמיר והרחמים באתגליא, כי ע\"כ אית בה יראה בסוד אילנא דטוב ורע, זכי בר נש הא טוב, לא זכי הא רע. (כנ\"ל במאמר ב' נקודין)"],[5,"","ונמצאת התשובה שאנו עושין במשך שתא אלפי שני, אינה אלא תשובה מיראה, שזדונות נעשים לו כשגגות, כי ע\"י התשובה אנו מחזירים המלכות למדת הרחמים, והדין שבה נגנז לשיעור נהירו דקיק, וחוטא דקיק, כי המלכות עדיין מוכרחה להשאר במדת היראה, וע\"כ נקראת תשובה מיראה."],[5,"","והאי \u0003חוטא דקיק\u0004 המוכרח להשאר, נק' בשם שגגות, כי השוגג לפי עצמו אינו חטא, אלא השגגות מביאות את האדם לעבירות במזיד, כי אין אדם חוטא במזיד מטרם שנכשל מקודם באיזו שגגה. והנה כן הוא האי חוטא דקיק הנשאר במלכות, כי אע\"פ שנשאר כן אינו חטא, אמנם בסבת הדין הנעלם הזה אנו באים לידי זדונות, וז\"ס שאמרו חז\"ל מתחילה הוא כחוט השערה, דהיינו כהאי \u0003חוטא דקיק\u0004, ואח\"כ אם אין משמרים הברית כראוי נעשה כעבותות העגלה, כי מתגלה מדת הדין שבמלכות."],[5,"","וז\"ס דדומה יתיב אפתחא דגיהנם. שהוא כח חוטא דקיק, שהוא רק פתח, בסוד שמתחילה הוא כחוט השערה. ולפיכך נק' תשובתנו זו רק כמו שנתכפרו עונותינו ונעשו לשגגות, כי נשאר החוטא דקיק, שיש בידו להביאנו לידי מזיד. וענין בחינה ב' של תשובה שהיא מאהבה, שזדונות נעשים לזכויות (עיין לעיל אות קכ\"ו)."],[5,"","וזה אמרו \u0003ובגין כך בעי לאסתמרא בר נש דלא יימא מלה, כדוד\u0004. דהיינו, שלא יאמר \u0003מלה\u0004, הגורמת לגלות מדת הדין שבמלכות כמו שעשה דוד, \u0003בגין דלא יכיל למימר לדומה, כי שגגה היא\u0004, כי אינו בטוח שיוכל תיכף לחזור בתשובה שיתכפר לו העון לשגגה \u0003כמה דהוה לדוד, ונצח ליה קב\"ה בדינא\u0004."],[5,"","כי דוד שעשה הישר בעיני ה' כל ימי חייו, ולא היה לו שום חטא מימיו זולת בדבר אוריה, ע\"כ נעשה לו הקב\"ה \u0003אפטרופא\u0004 דיליה, ועזרו תיכף לחזור בתשובה, ונעשה לו העון כשגגה, כמ\"ש \u0003לולי ה' עזרתה לי כמעט שכנה דומה נפשי\u0004, אבל שאר בני אדם צריכים לפחד, שלא יוכלו לומר לפני המלאך \u0003כי שגגה היא\u0004, ויפלו בידי \u0003דומה\u0004 לגיהנם."],[5,"וחבל את מעשה ידיך דא בשר קדש, ברית קדישא דפגים, ואתמשך בגיהנם על ידא דדומה",": כי תיקון \u0003הברית קדש\u0004 נק' \u0003מעשה ידינו\u0004, כמ\"ש \u0003ומעשה ידינו כוננהו\u0004, וסוד הנשמה הקדושה נקראת בשר קדש, בסו\"ה ומבשרי אחזה אלוה (איוב י\"ט, כנ\"ל אות קל\"א). שע\"י גילוי הדין שבמלכות מתקלקל תיקון הברית, והנשמה נמשכת לגיהנם ביד דומה כנ\"ל."],[5,"","המלים \u0003בגין כך\u0004, סובבות על כל המאמר דרב המנונא סבא שהביא לפנינו, שאחר שמתבאר בו היטב ענין תיקון הברית, הן בשכרו והן בענשו, ואשר משום זה נקרא תיקון הברית \u0003מעשה ידינו\u0004, הוא חוזר כאן לענינו, בביאור ענין גמר התיקון להאי יומא, שהשמים הוא החתן שנכנס לחופתו עם הכלה, (כנ\"ל בביאור הכתוב השמים מספרים כבוד אל),"],[5,"","ואומר, \u0003ובגין כך\u0004, אומר הכתוב בגמר התיקון \u0003ומעשה ידיו מגיד הרקיע\u0004, כי אז יתגלה שכל אלו התקונים אינם \u0003מעשה ידינו\u0004, אלא \u0003מעשה ידיו\u0004, וזה \u0003מגיד הרקיע\u0004, שעליו נעשה הזווג הגדול בסוד רב פעלים ומקבצאל, (כנ\"ל אות צ\"ב), \u0003ומגיד\u0004, הוא ענין גילוי המשכת השפע."],[5,"","ודע, שזה כל ההפרש שיש בין עוה\"ז שמלפני התיקון אל גמר התיקון. כי מטרם גמר התיקון נקראת המלכות בשם אילנא טוב ורע כנ\"ל, שפירושו, כי המלכות היא סוד הנהגתו ית' שבעוה\"ז, וכל עוד שהמקבלים לא באו לידי השלמה, שיוכלו לקבל שלמות הטבתו, שחשב עלינו במחשבת הבריאה, מוכרחה ההנהגה להיות בדרך טוב ורע, ושכר ועונש. כי כלי קבלה שלנו מלוכלכים עוד בקבלה עצמית המצומצמת מאוד במדתה, וגם מפרידה אותנו מהבורא ית'."],[5,"","והטבה שלימה, בשיעור הגדול שחשב עלינו, איננה, אלא בבחינת השפעה, שהיא תענוג בלי שום גבול וצמצום, משא\"כ הקבלה לעצמו, הוא מוגבל ומצומצם מאד, כי השביעה מכבה תיכף התענוג. וז\"ס הכתוב כל פעל ה' למענהו (משלי ט\"ז), דהיינו שכל הפעולות הנוהגות בעולם לא נבראו מתחילתן אלא להשפיע נ\"ר אליו. ולפיכך נמצאים בני אדם משמשים בעסקי העולם בהיפך גמור ממה שנבראו מתחילתם, שהרי הקב\"ה אומר כל העולם בשבילי נברא, דהיינו כל פעל ה' למענהו (משלי ט\"ז), וכן כל הנקרא בשמי לכבודי בראתיו (ישעיה מ\"ג)."],[5,"","ואנו אומרים ההיפך ממש מקצה אל הקצה, כי אנו אומרים כל העולם אך בשבילנו נברא, ואנו רוצים לבלוע כל טוב העולם לבטננו להנאותינו, ולכבודינו. ולפיכך אין פלא מה שאין אנו ראויים עוד לקבל הטבתו השלמה. וע\"כ מוטעמת לנו השגחתו ית' בבחינת טוב ורע, דהיינו בבחינת הנהגת שכר ועונש, כי זה תלוי בזה, ששכר ועונש מסובב מטוב ורע. כי כיון שאנו משתמשים בכלי הקבלה בהיפך ממה שנבראו, הרי אנו מרגישים בהכרח בפעולות שבהנהגה, שהם בחינת רע בעדנו."],[5,"","כי חוק הוא זה, שלא יוכל הנברא לקבל רע מאתו ית' בגלוי, כי הוא פגם ח\"ו בכבודו ית' שהנברא ישיגו כפועל רעות, כי אין זה מתאים לפועל השלם. וע\"כ בעת שהאדם מרגיש רע, הנה באותו שיעור שורה עליו כפירה על השגחתו ח\"ו, ונעלם ממנו הפועל ית', שהוא העונש היותר גדול שבעולם."],[5,"","הרי שהרגשת טוב ורע בהשגחתו מסבבת עמה הרגשת שכר ועונש, כי המתאמץ שלא להתפרד מאמונתו ית' אע\"פ שטועם רע בהשגחה, יש לו שכר, ואם ח\"ו לא יעלה לו להתאמץ, יש לו עונש, כי נפרד מאמונתו ית'. ונמצא, שאע\"פ שהוא לבדו עשה ועושה ויעשה לכל המעשים כולם, מ\"מ נשאר זה נסתר ממרגישי טו\"ר, כי בשעת הרע ניתן כח לס\"א להעלים השגחתו ואמונתו, ובאים לידי העונש הגדול דפרודא, ונעשים מלאים הרהורים של כפירה. וכשחוזרים בתשובה, נמצאים כנגד זה שהם מקבלים שכר, ויכולים שוב להדבק בו ית'."],[5,"","אמנם מכח הנהגת שכר ועונש עצמה, הכין ה' שסוף כל סוף אנו זוכים על ידה לגמר התיקון, דהיינו שכל בני אדם ישיגו הכלים של הקבלה המתוקנים על מנת להשפיע נ\"ר ליוצרם, בשיעור הכתוב כל פעל ה' למענהו (משלי ט\"ו), כמו שנבראו מתחילתם כנ\"ל."],[5,"","ואז יתגלה הזווג הגדול דעתיק יומין, ואנו באים לידי תשובה מאהבה, וכל הזדונות יהפכו לזכויות, וכל הרעות לטובות גדולות, ואז תתגלה השגחתו הפרטית בעולם כולו, דהיינו שכולם יראו, כי הוא לבדו עשה ועושה ויעשה כל אלו המעשים והפעולות שמקודם לכן, כי עתה אחר שכבר נהפכו הרע והעונש לטובות ולזכויות, תנתן האפשרות להשיג פועלם, כי כבר מתאימים הם למעשה ידיו ית', כי עתה ישבחו ויברכו אותו על אלו הרעות והעונשים המדומים בשעתם."],[5,"","וזהו עיקר הקוטב של המאמר, כי עד עתה היו גם התיקונים נחשבים ל\u0003מעשה ידינו\u0004, כי ע\"כ קבלנו עליהם שכר ועונש, אמנם בזווג הגדול של גמר התיקון יתגלה שהן התיקונים והן העונשים כולם הם רק \u0003מעשה ידיו\u0004 כנ\"ל. וזה אמרו \u0003ומעשה ידיו מגיד הרקיע\u0004 כי הזווג הגדול שעל הרקיע יגיד, שהכל הוא \u0003מעשה ידיו\u0004, והוא לבדו עשה ועושה ויעשה לכל המעשים כולם."],[6,"","קלט) \u0003ובג\"כ ומעשה ידיו\u0004 וגו': ומשום זה, \u0003ומעשה ידיו מגיד הרקיע\u0004. אלו הם החברים שנתחברו בכלה זו, שהיא המלכות, ע\"י עסק התורה בליל שבועות (כנ\"ל אות ק\"ל) \u0003ובעלי אות ברית שלה\u0004 הנקראים מעשה ידיו (כמ\"ש שם). \u0003מגיד\u0004 ורושם כל אחד ואחד (כמ\"ש שם). מי הוא הרקיע. זה הוא הרקיע, שבו החמה והלבנה והכוכבים והמזלות, והוא נקרא ספר הזכרון, הוא המגיד, והרושם אותם, והכותב אותם, שיהיו בני ההיכל שלו, ושיעשה רצונם תמיד."],[6,"","ביאור הדברים, יסוד דז\"א, שבו נעשה הזווג לגילוי כל הקומות ודרגין עלאין, שהן \u0003חמה ולבנה וככביא ומזלי\u0004, הוא נקרא רקיע. כמ\"ש (בזוהר בראשית אות ת\"ב), \u0003ויתן אותם ברקיע השמים, וכד כלהון קיימין ביה, כדין חדוותא דא עם דא, כדין סיהרא אזעירת נהורא מקמי שמשא, כל מה דנטיל בגין לאנהרא לה הה\"ד להאיר על הארץ\u0004."],[6,"","פירוש, כל המאורות העלאין ניתנו \u0003ברקיע השמים\u0004, שהוא יסוד דז\"א, \u0003וכלהון קימין ביה\u0004, והוא מזדווג \u0003בחדוותא\u0004 עם הנוקבא הנקראת \u0003ארץ\u0004 ונותן לה כל אלו המאורות. שז\"ס \u0003להאיר על הארץ\u0004. ואז נבחן שהמלכות קטנה מן השמש שהיא ז\"א. אבל בגמר התיקון. \u0003רב יצחק אמר כתיב, והיה אור הלבנה כאור החמה, ואור החמה יהיה שבעתים באור שבעת הימים\u0004 וכו'. דהיינו שאז לא תהיה המלכות קטנה מז\"א, אלא תגדל כמו הז\"א בששת ימי בראשית, והז\"א עצמו יעלה שבעתים כששת ימי בראשית."],[6,"","ושואל שם רבי יהודה \u0003ואימתי יהא דא, בזמנא דכתיב בלע המות לנצח, וכדין כתיב ביום ההוא יהיה ה' אחד ושמו אחד\u0004 ע\"ש. פי' כי הרקיע, שהוא ז\"א, הוא \u0003הוי\"ה\u0004, הנקרא \u0003שמש\u0004, \u0003ושמו\u0004 הוא הנוקבא המקבלת ממנו, הנקראת \u0003לבנה\u0004, ובשתא אלפי שני המקבלים מששת ימי בראשית לא נגלה להם כי הוא ושמו אחד, כי הלבנה קטנה מהשמש שהוא ז\"א הנקרא \u0003הוי\"ה\u0004. וענין קטנותה הוא, שהמלכות מתוקנת בסוד עשיה דאית בה טוב ורע שכר ועונש, (כמ\"ש לעיל באורך בדיבור הסמוך עש\"ה), ויש הבדל גדול בין: הוא, אל שמו, כי בשמו, שהוא המלכות באים הזווגים בזה אחר זה זמנין בחבורא וזמנין בפרודא ע\"ש."],[6,"","אבל בגמר התיקון, דהיינו, \u0003בזמנא דכתיב בלע המות לנצח\u0004, הנה אז \u0003יהיה הוי\"ה אחד ושמו אחד\u0004, כי \u0003שמו\u0004 שהוא הנוקבא תשוב כאור הז\"א ממש, דהיינו כולו טוב בלי רע כלל. ותתגלה בה השגחה פרטית כנ\"ל. שז\"ס והיה אור הלבנה כאור החמה."],[6,"","וע\"כ בעת ההיא תקרא הנוקבא בשם \u0003ספר זכרון\u0004. כי המלכות נקראת \u0003ספר\u0004, בהיות כל מעשי בני העולם נרשמים בה. ויסוד דז\"א נקרא \u0003זכרון\u0004, כי הוא זוכר מעשי עולם וחוקר כל יצורי קדם, שממנו מושפעים כולם, כנ\"ל בסו\"ה להאיר אל הארץ. ובשתא אלפי שני מטרם גמר התיקון, הרי \u0003ספר\u0004 לבד ו\u0003זכרון\u0004 לבד דהיינו לזמנין בחבורא ולזמנין בפרודא. אבל בגמר התיקון, אינון תרין דרגין נעשות אחת, בסוד הוי\"ה אחד ושמו אחד, ואז נקראת המלכות עצמה \u0003ספר זכרון\u0004, כי הם אחד ממש, שהרי אור הלבנה נעשה כאור החמה. (ועי' בזוהר ויקהל אות ק')."],[6,"","וזהו אמרו \u0003מאן הרקיע, דא איהו הרקיע דביה חמה ולבנה וככביא ומזלי\u0004. דהיינו, יסוד הז\"א שבו יוצאים כל המאורות שבעולם, וביה קיימין, והוא המשפיע אותם אל המלכות, בעת שהיא קטנה ממנו ואינה עוד בבחינת ה' אחד ושמו אחד, \u0003ודא איהו ספר זכרון\u0004, והוא עצמו יהיה ג\"כ בחינת המלכות של גמר התיקון, שתהיה נקראת משום זה, \u0003ספר זכרון\u0004. כי אז תקבל המלכות כל בחינת הז\"א, וזה \u0003הרקיע\u0004 הנקרא \u0003זכרון\u0004, יקרא אז \u0003ספר זכרון\u0004, דהיינו בחינת מלכות עצמה, הנקראת \u0003ספר\u0004, וה\u0003זכרון\u0004 שהוא \u0003הרקיע\u0004, יהיה עמה אחד ממש, בסו\"ה ביום ההוא יהיה ה' אחד ושמו אחד."],[7,"","קמ) \u0003יום ליום יביע אומר\u0004: פירושו, יום קדוש מאלו ימים העליונים של המלך, דהיינו הספירות של ז\"א הנקראות ימים, משבחים את החברים, שעסקו בתורה בליל שבועות, ואומרים כל אחד לחבירו, אותו הדבר שאמר, וז\"ש, \u0003יום ליום יביע\u0004 אותו אומר, ומשבח אותו. \u0003ולילה ללילה\u0004, היינו כל מדרגה השולטת בלילה, היינו הספירות של המלכות השולטת בלילה, משבחים זה לזה, אותה הדעת שכל אחד מקבל מחבירו. וברוב שלמות הם נעשו להם חברים ואוהבים."],[7,"","ביאור הדברים, אחר שביאר, שמעשה ידיו מגיד הרקיע, הוא \u0003ספר הזכרון\u0004 הכתוב במלאכי, הולך ומבאר הכתובים שלאחריו על דרך שפרט הנביא שם את הכתוב בספר הזכרון. כי אומר שם (מלאכי ג' י\"ד) אמרתם שוא עבוד אלהים, ומה בצע כי שמרנו משמרתו וכי הלכנו קדרנית מפני ה' צבאות וכו' אז נדברו יראי ה' איש אל רעהו, ויקשב ה' וישמע, ויכתב \u0003ספר זכרון\u0004 לפניו, ליראי ה' ולחושבי שמו, והיו לי אמר ה' צבאות ליום אשר אני עושה סגולה, וחמלתי עליהם כאשר יחמול איש על בנו העובד אותו."],[7,"","והנך מוצא \u0003דההיא מלה דאמר כל חד לחבריה\u0004, שוא עבוד אלהים ומה בצע כי שמרנו משמרתו וכו', נכתבים \u0003בספר הזכרון\u0004 ליראי ה' ולחושבי שמו, כי ה' יחמול עליהם כאשר יחמול איש על בנו העובד אותו, דהיינו רק ליום אשר אני עושה סגולה, שהוא יום גמר התיקון."],[7,"","וביאור הדברים, כי מטרם גמר התיקון, דהיינו מטרם שהכשרנו את כלי הקבלה שלנו, לקבל רק ע\"מ להשפיע נ\"ר ליוצרנו ולא לטובת עצמנו, נקראת המלכות בשם \u0003אילנא דטוב ורע\u0004, כי המלכות היא הנהגת העולם לפי מעשה בני אדם, וכיון שאין אנו מוכשרים לקבל כל העונג והטוב שחשב השי\"ת בעדנו במחשבת הבריאה, מטעם האמור לעיל בדיבור הסמוך, ע\"כ מוכרחים לקבל הנהגת טוב ורע מהמלכות, שהנהגה זו מכשירה אותנו סוף כל סוף לתקן כלי הקבלה שלנו ע\"מ להשפיע, ולזכות לעונג ולטוב שחשב בעדנו. וכבר הארכנו בזה בסמוך (בד\"ה ובגין כך מעשה ידיו עש\"ה)."],[7,"","ונתבאר שם כי הרגשתנו הטו\"ר מסבבת ג\"כ ענין שכר ועונש, כי הרגשת הרע גורמת פרודא מאמונתו ית' ע\"ש. ונמצא שאם האדם מתאמץ בעת הרגשתו הרעה שלא לפגום אמונתו מחמת זה, ויוכל לשמור התורה והמצוות בשלמות, הרי הוא מקבל שכר. ואם חלילה אינו עומד בנסיון ומקבל פרודא, הוא מתמלא בהרהורים רעים כמ\"ש שם."],[7,"","ונודע כי על הרהורים אלו אמרו חז\"ל (עיין קידושין מ. ), שהקב\"ה מעניש עליהם כמו על מעשה, שע\"ז כתוב למען תפוש את בית ישראל בלבם. גם נודע שצדקת הצדיק לא תצילנו ביום פשעו, אכן זה רק בתוהה על הראשונות. אמנם לפעמים מתגברים ההרהורים על האדם, עד שתוהה ח\"ו על ריבוי המעשים הטובים שעשה, ואומר מה בצע כי שמרנו משמרתו וכי הלכנו קדורנית מפני ה' צבאות, כי אז נעשה רשע גמור, שהרי הוא תוהה על הראשונות, והוא מאבד כל המע\"ט שעשה בהרהור רע זה. כמ\"ש צדקת הצדיק לא תצילנו ביום פשעו. ועכ\"ז מועילה תשובה. אבל אז נחשב כמתחיל לעבוד ה' מחדש, וכקטן שנולד דמי, שהרי כל צדקתו מימים שעברו חלפה ואינה."],[7,"","והנה הנהגת טוב ורע גורמת לנו הרבה פעמים עליות וירידות כנ\"ל, כל אחד לפי מה שהוא. ותדע שכל עליה נחשבת משום זה ליום בפני עצמו, כי מסבת הירידה הגדולה, שהיתה לו בינתים, בהיותו תוהה על הראשונות, נמצא בעת עליה, שהוא כקטן שנולד כנ\"ל. הרי שבכל עליה הוא כמתחיל מחדש לעבוד את ה', וע\"כ נחשבת כל עליה ליום מיוחד. ועד\"ז כל ירידה נחשבת ללילה מיוחד."],[7,"","וזה אמרו \u0003יום ליום יביע אומר, יומא קדישא מאינון יומין עלאין דמלכא\u0004. דהיינו, בכל עליה שהיתה לו לאדם שנתדבק אז \u0003ביומין עלאין\u0004 של הקב\"ה \u0003משבחין לון לחברייא ואמרין ההיא מלה דאמר כל חד לחבריה\u0004. כי ע\"י הזווג הגדול שבגמר התיקון יזכו לתשובה מאהבה, כי יגמרו תיקון כלי הקבלה, שיהיו רק ע\"מ להשפיע נ\"ר להשי\"ת, ויתגלה לנו בזווג הזה כל הטוב והעונג הגדול של מחשבת הבריאה, ואז נראה בעליל, כי כל אלו העונשים שהיו בימי הירידה עד שבאנו להרהורים לתהות על הראשונות, הם היו המטהרים אותנו, וגורמים ישרים לכל האושר והטוב, שהגיע לנו בעת גמר התיקון, כי לולא אותם העונשים הנוראים לא באנו לעולם לעונג ולטוב הזה, ואז הזדונות האלו נמצאים נהפכים לזכויות ממש."],[7,"","וז\"ש \u0003יום ליום יביע אומר\u0004, שכל עליה ועליה שמטרם גמר התיקון, היא יום אחד \u0003מאינון יומין עלאין דמלכא\u0004, משבחין לון לחברייא. ונמצא עתה שהוא חוזר ומתגלה בכל הדרת שלמותו השייכת לאותו יום ומשבח לחברייא התמכין דאורייתא, עם \u0003ההיא מלה דאמר כל חד לחבריה\u0004, שהוא שוא עבוד אלהים ומה בצע כי שמרנו משמרתו, שהביאם אז לעונשים גדולים, כי עתה נהפכו לזכויות, שהרי כל שלמותו ואשרו של אותו יום לא היו יכולים להתגלות עתה באותו פאר והדר לולא העונשים ההם, וע\"כ נחשבו דוברי המלות ההן, ליראי ה' ולחושבי שמו, כמו המע\"ט האמיתים, וע\"כ נאמר גם עליהם, וחמלתי עליהם כאשר יחמול איש על בנו העובד אותו."],[7,"","וז\"ש \u0003יומא ליומא יביע ההוא אומר ומשבח ליה\u0004. כי כל הלילות האלו, שהם הירידות, היסורים והעונשים, שהפסיקו את דבקות ה', עד שנעשו ימים מרובים בזה אחר זה, הנה עתה אחר שגם הלילות והחושך שבינתים נעשו גם הם לזכויות ולמעשים טובים, ולילה כיום יאיר וחשכה כאורה, שוב אין הפסקות בינתים, ונמצאים מתחברים כל השתא אלפי שני ליום אחד גדול בלבד, ונמצאות כל הזווגים שיצאו בזה אחר זה, וגילו עליות ומדרגות נפרדות כל אחת מחברתה כנ\"ל, נתקבצו עתה לקומת זווג אחד רם ונשא המאיר מסוף העולם עד סופו. וז\"ס \u0003יומא ליומא יביע אומר\u0004, כי המלה ההיא הנ\"ל שהפסיקה בין \u0003יומא ליומא\u0004 נעשית עתה לשבח גדול, \u0003ומשבח ליה\u0004 כי נעשה לזכות. וע\"כ נעשו כולם יום אחד לה'."],[7,"","וז\"ש \u0003ולילה ללילה כל דרגא דאשלים בליליא, משבח דא לדא, ההוא דעת דכל חד מחבריה\u0004: כי כל אלו המלים והיסורים, הנק' לילות, שבסבתם נעשו המדרגות פסקי פסקי בזה אחר זה, הנה עתה אחר שגם הם כיום יאירו, משום שנתקבצו כולם ונעשו לבית קבול אחד לדעת הגדולה הממלאת כל הארץ דעה את ה', נמצא שכל לילה בפני עצמו היה נשאר בחשכה אם לא היה בא עתה בקיבוץ אחד עם כל הלילות. כי כל לילה מקבל חלקו \u0003בדעת\u0004 רק מתוך החיבור עם שאר הלילות. וע\"כ כל לילה נבחן כי \u0003יחוה דעת\u0004 לחברו כי לא היה מוכשר ל\u0003הדעת\u0004 אלא בצירוף עם חברו,"],[7,"","וז\"ש \u0003כל דרגא דאשלים בליליא\u0004, דהיינו כל לילה שנשלם עתה להיות בית קבול לדעת ה', \u0003משבח דא לדא\u0004, נמצא שכל אחד משבח לחברו משום \u0003ההוא דעת דכל חד\u0004, שחלק הדעת שקבל כל אחד, הוא \u0003מחבריה\u0004, על ידי החיבור עם חברו הלילה, כי לא היה מקבלו אם לא בצירוף עם חברו, כי רק כולם יחד בקיבוץ נעשו ראויים לקבל הדעת הגדולה הזו. וזה אמרו \u0003ובשלימו סגי, אתעבידו לון חברין ורחימין\u0004, שבשלמות הגדולה שקבלו יחד, נעשו כל הלילות לרעים אהובים זה לזה."],[8,"","קמא) \u0003אין אומר ואין דברים\u0004: היינו אומר ודברים משאר דברי העולם, שאינם נשמעים לפני המלך הקדוש, ואינו רוצה לשמוע אותם. אבל אלו הדברים בכל הארץ יצא קום. היינו שאלו הדברים עושים קו מדרי מעלה ודרי מטה. מאלו הדברים נעשים רקיעים, ומאלו הדברים מאותה התשבחה נעשה ארץ. ואם תאמר שאותם הדברים משוטטים בעולם במקום אחד. אומר הכתוב, ובקצה תבל מליהם."],[8,"","ביאור הדברים, כי עד כאן דברנו מהעונשים והיסורים הנוראים ביותר, דהיינו הפירודא מאמונתו יתברך, ואומר כי גם העונשים והיסורים מ\u0003שאר מילין דעלמא\u0004, דהיינו מעבירות פרטיות ומיסורי גיהנם והיסורין הגופניים, וכדומה הממלאים כל העולם הזה, הנה גם הם מתקבצים ונכללים בזווג הגדול הזה, בסו\"ה והיה כאשר שש ה' עליכם להיטיב אתכם ולהרבות אתכם כן ישיש ה' עליכם להאביד אתכם ולהשמיד אתכם וגו' (דברים כ\"ח) כי כולם מתקבצים ונעשים לאור גדול ונהפכים לששון ולחדוה רבה."],[8,"","וז\"ש \u0003אין אומר ואין דברים בשאר מילין דעלמא\u0004, שהם כל יסורי העולם הזה, \u0003דלא אשתמעו קמי מלכא\u0004, בההפכם לששון ולחדוה \u0003ולא בעי למשמע לון\u0004, שלא יתאוה לשמוע אותם, כי מתוך ההפכם לששון ולחדוה, הרי \u0003מלכא קדישא\u0004 יחזור אחריהם ויתאוה לשמוע אותם. כלומר שזכר כל צער וכאב מהימים שעברו יגרום עתה בגמר התיקון חדוה ועונג רב. בסו\"ה בימים ההם ובעת ההיא יבוקש את עון ישראל ואיננו (ירמיה נ'). כי בעת שיהפכו לזכויות, יעלו כל כך נייחא דרוחא עד שיבוקשו העונות מימים שעברו, בכדי להתבדח עליהם, ולא ימצאו. כלומר, שידמה לנו כי אינם נמצאים עוד בצורתם האמיתית, כמו שהיו בימים שעברו, וז\"ש \u0003ולא בעי למשמע לון\u0004 דהיינו שאין אומר ואין דיבור שלא יחזור עליהם ברצון וחשק גדול לשמוע אותם, מפאת היותם עתה כולם לאורות קדושים ונאמנים."],[8,"","והנה הקומה הגדולה הזו העולה בזווג הגדול מכל הנשמות ומכל המעשים הטובים והרעים יחדיו שבגמר התיקון, נבחנת כמו קו ועמוד אור, המאיר מסוף העולם ועד סופו, שה\"ס היחוד הגדול בסו\"ה יהיה ה' אחד ושמו אחד (זכריה י\"ד). וזה אמרו \u0003הני מילי\u0004 היינו \u0003מילין דעלמא\u0004 הנ\"ל בדיבור הסמוך. \u0003בכל הארץ יצא קום\u0004 כי הקומה היוצאת על \u0003הני מילי\u0004, שהם כל מיני יסורים ועונשים, מאירה מסוף העולם ועד סופו. דהיינו בכל הארץ."],[8,"","ואמרו, \u0003מדורי עלאי ומדורי תתאי\u0004. הוא ענין מאד נשגב ואתאמץ לבארו לפי האפשרות. כי יש לדעת, שאין סדר הזמנים בנצח כמו בעוה\"ז, ונמצא, שבעת שחשב הש\"י לברוא העולם, הרי כבר נבראו אצלו ית' כל הנשמות עם כל התנהגותן עד הגמרן בכל השלמות הנרצה מהן, כדי לקבל כל העונג והטוב שחשב עליהן להנהותן, כי אצלו ית', היהיה משמש לו כמו ההוה, ואין עתיד ועבר נוהגים בו."],[8,"","ובזה תבין מ\"ש חז\"ל (סנהדרין ל\"ח:) הראה לו הקב\"ה לאדה\"ר דור דור ודורשיו וכו' וכן למשה (כמ\"ש בזוהר פ' לך אות של\"א, ויחי אות שס\"ט). שלכאורה תמוה, כיון שעוד לא נבראו איך הראה אותם. אלא כמ\"ש, שכל הנשמות וכל התנהגותן עד לגמר התיקון, כבר הן יצאו לפניו במציאות. והן נמצאות כולן בסוד גן העדן העליון. ומשם הן יורדות ובאות בהתלבשות הגופים בעוה\"ז, כל אחת ואחת בשעתה, ומשם הראה הקב\"ה אותן לאדה\"ר ולמשה ולכל הכדאים לזה. והוא ענין ארוך לאו כל מוחא סביל דא, (וכבר הרחבתי בזה בספרי פנים מסבירות ענף א')."],[8,"","וז\"ס מ\"ש בזוהר (תרומה אות קס\"ג) \u0003כגוונא דאינון מתיחדין לעילא ברזא דאחד אוף הכי איהי אתיחדת לתתא ברזא דאחד\u0004 כי קומת הזווג הגדול שבגמר התיקון, בסו\"ה יהיה ה' אחד ושמו אחד, הנה כבר יצאה לעילא קומה זו, מכל הנשמות ומכל מעשים שבעולם, שיבראו עד גמר התיקון, דהיינו מבחינת נצחיותו ית', שכל העתיד משמש לו כהוה, ונמצא עמוד האור הזה המאיר מסוף העולם ועד סופו שיאיר בגמר התיקון, כבר הוא עומד כן בגן העדן העליון ומאיר לפניו, כמו שיתגלה לנו בגמר התיקון."],[8,"","וזה שאומר שם, \u0003חד לקבל חד קודשא בריך הוא אחד\u0004, כי לעת גמר התיקון יאירו ב' הקומות \u0003חד לקבל חד\u0004, ואז יהיה ה' אחד ושמו אחד. וזה אמרו, \u0003עבדי משיחא אינון מילין, מדורי עלאי ומדורי תתאי\u0004, משיחא פי' קו, המאיר \u0003מדורי עלאי ומדורי תתאי\u0004, דהיינו חד לקבל חד, כי אותה הקומה מאירה \u0003מדורי עלאי\u0004, שהם הנשמות כולן הנמצאות בגן העדן העליון. ומאירה \u0003מדורי תתאי\u0004, שהם כל הנשמות אחר עברן בפועל בהתלבשות הגוף בעוה\"ז ובאו לגמר התיקון. כלומר שאותם ב' הקומות מאירות בגמר התיקון יחד, ואז מתגלה יחודו ית' בסוד ה' אחד ושמו אחד."],[8,"","והנה משמיענו לבל נטעה לחשוב, שעמוד אור זה המאיר בג\"ע העליון, נמשך ומאיר בגמר התיקון בעוה\"ז. לזה אומר שאינו כן. אלא \u0003מאלין אתעבידו רקיעין\u0004, כי קומה זו יוצאת על היסוד דז\"א הנקרא רקיע, (כנ\"ל אות קל\"ח), ולפיכך יש עדיין ההבחן הזה שבכל הזווגים, אשר הקומה יוצאת תחילה מהרקיע ולמעלה, ואח\"כ היא מאירה אל המקבלים מרקיע ולמטה, אשר הקומה היוצאת מרקיע ולמעלה נקראת \u0003שמים\u0004, והקומה המקובלת מרקיע ולמטה נקראת \u0003ארץ\u0004."],[8,"","וזה אמרו שבעת שקו האור מתיחד \u0003מדורי עלאי ומדורי תתאי\u0004, נשאר עוד ההבחן מג\"ע העליון אל דרי העולם הזה, כי קומת הזווג היוצאת מהרקיע ולמעלה מקבלים דרי ג\"ע העליון, כי \u0003מאלין אתעבידו רקיעין\u0004, דהיינו שמים חדשים לדרי מעלה. ורק הזוהר הנמשך מהרקיע ולמטה, הוא המקובל \u0003למדורי תתאי\u0004. ונקרא ארץ חדשה (כנ\"ל אות ס\"ד ד\"ה שאר ע\"ש). וזה שמסיים \u0003מההיא תושבחתא\u0004, כלומר, שדרי מטה משיגין רק בחינת \u0003תושבחתא\u0004 והזוהר הנמשך משמים לארץ."],[8,"","וז\"ש, \u0003ואי תימא דאינון מלין באתר חד\u0004, מאחר שנתבאר שהזווג נעשה כדרך כל הזווגים, שמהרקיע ולמעלה נמשך אל מהרקיע ולמטה, א\"כ אפשר לטעות ולומר שהוא רק בחינת קו דק העולה בסוד מקום אחד, כמו שנזכר במעשה בראשית, יקוו המים אל מקום אחד דהיינו רק לפנימיות העולמות, המגיע רק לישראל בלבד, ולא לחיצוניות העולמות. (עי' בזוהר בראשית א' אות רי\"ח). ואומר שאינו כן, אלא \u0003משטטא בעלמא\u0004, שהאור משוטט וממלא את העולם, מסוף העולם עד סופו, דהיינו \u0003בקצה תבל מליהם\u0004, כלומר, אפילו לחיצוניות העולמות, שמגיע גם לאומות העולם, בסו\"ה ומלאה הארץ דעה את ה' (ישעיה י\"א)."]],[[0,"","אָמַר לוֹ: אִם לְפָנֶיךְ גָּלוּי - לְפָנָיו לֹא גָלוּי! אָמַר לוֹ: וְעוֹד בְּהֶתֵּר הָיָה מַה שֶּׁהָיָה, שֶׁהֲרֵי כָּל אֵלּוּ שֶׁעוֹלִים לַקְּרָב, לֹא עוֹלֶה אֶחָד מֵהֶם עַד שֶׁפּוֹטֵר אִשְׁתּוֹ בְּגֵט. אָמַר לוֹ: אִם כָּךְ, הָיָה לוֹ לְחַכּוֹת שְׁלֹשָׁה חֳדָשִׁים, וְלֹא חִכָּה. אָמַר לוֹ: בַּמָּה עוֹמֵד הַדָּבָר בְּמָקוֹם שֶׁחוֹשְׁשִׁים שֶׁהִיא מְעֻבֶּרֶת, וְגָלוּי לְפָנַי שֶׁאוּרִיָּה לֹא קָרַב אֵלֶיהָ מֵעוֹלָם, שֶׁהֲרֵי שְׁמִי חָתוּם בְּתוֹכוֹ לְעֵדוּת. כָּתוּב אוּרִיָּה, וְכָתוּב אוּרִיָּהוּ. שְׁמִי חָתוּם עִמּוֹ, שֶׁלֹּא שִׁמֵּשׁ בָּהּ לְעוֹלָמִים."],[1,"","אָמַר לוֹ: רִבּוֹן הָעוֹלָם, זֶה מַה שֶּׁאָמַרְתָּ - אִם לְפָנֶיךְ גָּלוּי שֶׁאוּרִיָּה לֹא שָׁכַב עִמָּהּ, לְפָנָיו הַאִם גָּלוּי הָיָה לוֹ לְחַכּוֹת לָהּ שְׁלֹשָׁה חֳדָשִׁים. וְעוֹד, אִם יָדַע שֶׁמֵּעוֹלָם לֹא שָׁכַב עִמָּהּ, אָז לָמָּה שָׁלַח לוֹ דָּוִד וְצִוָּה עָלָיו לְשַׁמֵּשׁ עִם אִשְׁתּוֹ, שֶׁכָּתוּב (שמואל ב יא) רֵד לְבֵיתְךְ וּרְחַץ רַגְלֶיךְ."],[2,"","אָמַר לוֹ: וַדַּאי לֹא יָדַע, אֲבָל חִכָּה יוֹתֵר מִשְּׁלֹשָׁה חֳדָשִׁים, שֶׁהֲרֵי אַרְבָּעָה חֳדָשִׁים הָיוּ, שֶׁכָּךְ לָמַדְנוּ, בְּעֶשְׂרִים וַחֲמִשָּׁה בְּנִיסָן הֶעֱבִיר דָּוִד כְּרוּז בְּכָל יִשְׂרָאֵל, וְהָיוּ עִם יוֹאָב בְּשִׁבְעָה יָמִים שֶׁבְּסִיוָן, וְהָלְכוּ וְהִשְׁחִיתוּ אֶרֶץ בְּנֵי עַמּוֹן. שָׁהוּ שָׁם סִיוָן תַּמּוּז אָב וֶאֱלוּל, וּבְעֶשְׂרִים וְאַרְבָּעָה בֶּאֱלוּל הָיָה מַה שֶּׁהָיָה עִם בַּת שֶׁבַע, וּבְיוֹם הַכִּפּוּרִים מָחַל לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתוֹ חֵטְא. וְיֵשׁ אוֹמְרִים בְּשִׁבְעָה בַּאֲדָר הָעֳבַר כְּרוּז, וְהִתְכַּנְּסוּ בַּחֲמִשָּׁה עָשָׂר בְּאִיָּר, וּבַחֲמִשָּׁה עָשָׂר בֶּאֱלוּל הָיָה מַה שֶּׁהָיָה עִם בַּת שֶׁבַע, וּבְיוֹם הַכִּפּוּרִים הִתְבַּשֵּׂר (שם יב) גַּם ה' הֶעֱבִיר חַטָּאתְךְ לֹא תָמוּת. מַה זֶּה לֹא תָמוּת לֹא תָמוּת בְּיַד דּוּמָה."],[3,"","אָמַר דּוּמָה: רִבּוֹן הָעוֹלָם, הֲרֵי דָּבָר אֶחָד יֵשׁ לִי אֵלָיו, שֶׁהוּא פָּתַח פִּיו וְאָמַר (שם) חַי ה' כִּי בֶן מָוֶת הָאִישׁ הָעֹשֶׂה זֹאת, וְהוּא דָן אֶת נַפְשׁוֹ. טְרוּנְיָא יֵשׁ לִי עָלָיו. אָמַר לוֹ: אֵין לְךְ רְשׁוּת, שֶׁהֲרֵי הוֹדָה לְפָנַי וְאָמַר חָטָאתִי לַה', אַף עַל פִּי שֶׁלֹּא חָטָא. אֲבָל בְּמַה שֶּׁחָטָא בְּאוּרִיָּה, עֹנֶשׁ כָּתַבְתִּי עָלָיו וְקִבֵּל. מִיָּד חָזַר דּוּמָה לִמְקוֹמוֹ בְּפַחֵי נֶפֶשׁ."],[4,"","וְעַל זֶה אָמַר דָּוִד, (תהלים צד) לוּלֵי ה' עֶזְרָתָה לִּי כִּמְעַט שָׁכְנָה דוּמָה נַפְשִׁי. לוּלֵי ה' עֶזְרָתָה לִּי שֶׁהָיָה אֶפּוֹטְרוֹפּוֹס שֶׁלִּי, כִּמְעַט שָׁכְנָה וְכוּ'. מַה זֶּה כִּמְעַט כְּמוֹ חוּט דַּק כְּמוֹ הַשִּׁעוּר שֶׁיֵּשׁ בֵּינִי וּבֵין הַצַּד הָאַחֵר, כְּאוֹתוֹ שִׁעוּר הָיָה שֶׁלֹּא שָׁכְנָה דוּמָה נַפְשִׁי."],[5,"","וְלָכֵן צָרִיךְ בֶּן אָדָם לְהִשָּׁמֵר שֶׁלֹּא יֹאמַר דָּבָר בְּדָוִד, בִּגְלַל שֶׁלֹּא יוּכַל לוֹמַר לְדוּמָה (קהלת ה) כִּי שְׁגָגָה הִיא, כְּמוֹ שֶׁהָיָה לְדָוִד וְנִצַּח אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בַּדִּין. לָמָּה יִקְצֹף הָאֱלֹהִים עַל קוֹלֶךְ - עַל אוֹתוֹ קוֹל שֶׁהוּא אָמַר, וְחִבֵּל אֶת מַעֲשֵׂה יָדֶיךְ - זֶה בְּשַׂר קֹדֶשׁ בְּרִית הַקָּדוֹשׁ שֶׁפָּגַם וְנִמְשָׁךְ בַּגֵּיהִנֹּם עַל יְדֵי דוּמָה."],[6,"","וּבִגְלַל זֶה (תהלים יט) וּמַעֲשֵׂה יָדָיו מַגִּיד הָרָקִיעַ. אֵלּוּ אוֹתָם הַחֲבֵרִים שֶׁהִתְחַבְּרוּ עִם הַכַּלָּה הַזּוֹ וּבַעֲלֵי בְרִיתָהּ, מַגִּיד וְרוֹשֵׁם כָּל אֶחָד וְאֶחָד. מִי הָרָקִיעַ זֶהוּ הָרָקִיעַ שֶׁבּוֹ חַמָּה וּלְבָנָה וְכוֹכָבִים וּמַזָּלוֹת, וְזֶהוּ סֵפֶר זִכָּרוֹן, הוּא מַגִּיד וְרוֹשֵׁם אוֹתָם וְכוֹתֵב אוֹתָם לִהְיוֹת בְּנֵי הַהֵיכָל וְלַעֲשׂוֹת רְצוֹנָם תָּמִיד."],[7,"","(שם) יוֹם לְיוֹם יַבִּיעַ אֹמֶר - יוֹם קָדוֹשׁ מֵאוֹתָם יָמִים עֶלְיוֹנִים שֶׁל הַמֶּלֶךְ, מְשַׁבְּחִים אוֹתָם הַחֲבֵרִים וְאוֹמְרִים אוֹתוֹ דָבָר שֶׁאָמַר כָּל אֶחָד לַחֲבֵרוֹ. יוֹם לְיוֹם יַבִּיעַ אוֹתוֹ אֹמֶר וּמְשַׁבְּחוֹ, וְלַיְלָה לְּלַיְלָה - כָּל דַּרְגָּה שֶׁמֻּשְׁלֶמֶת (נ\"א: ששולטת) בַּלַּיְלָה מְשַׁבֵּחַ זֶה לָזֶה אוֹתוֹ דַעַת שֶׁל כָּל אֶחָד מֵחֲבֵרוֹ, וּבִשְׁלֵמוּת (ס\"א ובאהבה) רַבָּה נַעֲשִׂים לָהֶם חֲבֵרִים וְאוֹהֲבִים."],[8,"","אֵין אֹמֶר וְאֵין דְּבָרִים - בִּשְׁאָר דִּבְרֵי הָעוֹלָם, שֶׁלֹּא נִשְׁמָעִים לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ וְלֹא צָרִיךְ לְשָׁמְעָם. אֲבָל הַדְּבָרִים הַלָּלוּ, בְּכָל הָאָרֶץ יָצָא קַוָּם. עוֹשִׂים מְדִידָה, אוֹתָם דְּבָרִים מָדוֹרִים עֶלְיוֹנִים וּמָדוֹרִים תַּחְתּוֹנִים, מֵאֵלֶּה נַעֲשִׂים רְקִיעִים, וּמֵאֵלֶּה הָאָרֶץ, מֵאוֹתוֹ הַשֶּׁבַח. וְאִם תֹּאמַר שֶׁאוֹתָם דְּבָרִים בְּמָקוֹם אֶחָד מְשׁוֹטְטִים בָּעוֹלָם - בִּקְצֵה תֵבֵל מִלֵּיהֶם."]]],[["וְכֵיוָן דְּאִתְעֲבִידָא (דאתאביד) רְקִיעִין מִנְהוֹן, מָאן שַׁרְיָא בְהוֹן. הָדַר וְאָמַר לַשֶּׁמֶשׁ שָׂם אֹהֶל בָּהֶם. הַהוּא שִׁמְשָׁא קַדִּישָׁא שָׁוֵי מְדוֹרֵיהּ וּמִשְׁכָּנֵיהּ בְּהוּ וְאִתְעַטַּר בְּהוּ.","כֵּיוָן דְּשָׁרֵי בְּאִנּוּן רְקִיעִין וְאִתְעַטַּר בְּהוּ, כְּדֵין וְהוּא כְּחָתָן יוֹצֵא מֵחֻפָּתוֹ. חָדֵי וְרָהִיט בְּאִנּוּן רְקִיעִין. נָפַק מִנַּיְיהוּ וְעָאל וְרָהִיט גּוֹ מִגְדְּלָא חָדָא אָחֳרָא בְּאֲתַר אָחֳרָא. מִקְצֵה הַשָּׁמַיִם מוֹצָאוֹ, וַדַּאי מֵעָלְמָא עִלָּאָה נָפִיק וְאַתְיָא (ואתא) דְּאִיהוּ (לעיל א' ב) קְצֵה הַשָּׁמַיִם לְעֵילָא. וּתְקוּפָתוֹ (על קצותם), מָאן תְּקוּפָתוֹ, דָּא קְצֵה הַשָּׁמַיִם לְתַתָּא דְּאִיהִי תְּקוּפַת הַשָּׁנָה דְּאַסְחְרָא לְכָל סָיְיפִין. וְאִתְקַשְׁרַת מִן הַשָּׁמַיִם עַד רְקִיעָא דָּא. וְאֵין נִסְתָּר מֵחַמָּתוֹ דְּהַהִיא תְּקוּפָה דָא וּתְקוּפָה דְּשִׁמְשָׁא דְּאַסְחַר בְּכָל סִטְרָא.","וְאֵין נִסְתָּר לֵית דְּאִתְכַּסֵּי מִנֵּיהּ מִכָּל דַּרְגִּין עִלָּאִין דְּהֲווּ כֻּלְהוּ מְסַחֲרָן וְאַתְיָין לְגַבֵּיהּ וְכָל חַד וְחַד לֵית מַאן דְּיִתְכַּסֵּי מִינֵיהּ. מֵחַמָּתוֹ בְּשַׁעְתָּא דְּאִתְחַמֵם וְתָב (ותאיב) לְגַבַּיְיהוּ בִּתְּיוּבְתָּא (בתיאובתא) שְׁלִים. כָּל שְׁבָחָא דָא וְכָל עִלּוּיָא דָא בְּגִין אוֹרַיְיתָא הוּא דִּכְתִיב, (תהילים י״ט:ח׳) תּוֹרַת ה' תְּמִימָה.","שִׁית זִמְנִין כְּתִיב הָכָא ה', וְשִׁית קְרָאֵי מִן הַשָּׁמַיִם מְסַפְּרִים עַד תּוֹרַת יְיָ תְּמִימָה וְעַל רָזָא דָא כְּתִיב בְּרֵאשִׁית הָא שִׁית אַתְוָון. בָּרָא אֱלהִים אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ, הָא שִׁית תֵּבִין. קְרָאֵי אַחֲרָנִין לָקֳבֵל שִׁית זִמְנִין ה' שִׁית קְרָאֵי בְּגִין שִׁית אַתְוָון דְּהָכָא. שִׁית שְׁמָהָן בְּגִין שִׁית תֵּבִין דְּהָכָא.","עַד דְּהֲווּ יַתְבֵי עָאלוּ רִבִּי אֶלְעָזָר בְּרֵיהּ וְרִבִּי אַבָּא. אָמַר לוֹן וַדַּאי אַנְפֵּי שְׁכִינְתָּא אַתְיָין, וְעַל (ז ב) דָּא פְּנִי\"אֵל קָרֵינָא לְכוּ, דְּהָא חֲמִיתּוּן אַנְפֵּי שְׁכִינְתָּא אַפִּין בְּאַפִּין. וְהַשְׁתָּא דְּקָא יְדַעְתּוּן וְגָלֵי לְכוּ קְרָא דְוּבְנָיָהוּ בֶּן יְהוֹיָדָע, וַדַּאי דְּמִלָּה דְּעַתִּיקָא קַדִּישָׁא אִיהוּ וּקְרָא דְּאֲבַּתְרֵיהּ. וְהַהוּא דְּסָתִים מִכֹּלָא אָמְרוּ.","וְהַאי קְרָא אִיהוּ בְּאֲתַר אָחֳרָא כְּגַוְונָא דָא. פָּתַח וְאָמַר (דבריהימים א יא) וְהוּא הִכָּה אֶת הָאִישׁ הַמִּצְרִי אִישׁ מִדָּה חָמֵשׁ בָּאַמָּה, וְכֹלָא רָזָא חָדָא אִיהוּ, מֵהַאי (ס\"א האי) מִצְרִי, הַהוּא דְּאִשְׁתְּמוֹדָע, (שמות י״א:ג׳) גָּדוֹל מְאֹד בְּאֶרֶץ מִצְרַיִם בְּעֵינֵי עַבְדֵי וְגו' רַב וְיַקִּירָא כְּמָה דְגָלֵי הַהוּא סָבָא.","וְהַאי קְרָא בִּמְתִיבְתָּא עִלָּאָה אִתְּמָר. אִישׁ מִדָּה כֹּלָּא חַד. (שמואל ב כג) אִישׁ מַרְאֶה וְאִישׁ מִדָּה כֹּלָּא חַד. בְּגִין (לעיל ה' ע\"ב) דְּאִיהוּ שַׁבָּת וּתְחוּמָא דִּכְתִיב, (במדבר ל״ה:ה׳) וּמַדּוֹתֶם מִחוּץ לָעִיר, וּכְתִיב, (ויקרא י״ט:ל״ה) לא תַעֲשׂוּ עָוֶל בַּמִּשְׁפָּט בַּמִּדָּה. וְעַל דָּא אִישׁ מִדָּה אִיהוּ. וְאִיהוּ מַמָּשׁ אִישׁ מִדָּה אִיהוּ אָרְכֵּיהּ מִסְּיָיפֵי עָלְמָא וְעַד סְיָיפֵי עָלְמָא. אָדָם הָרִאשׁוֹן הָכִי הֲוָה. וְאִי תֵימָא הָא כְּתִיב חָמֵשׁ בָּאַמָּה. אִנּוּן חָמֵשׁ בָּאַמָּה מִסְּיָיפֵי עָלְמָא עַד סְיָיפֵי עָלְמָא הֲוָה.","(דברי הימים א י״א:כ״ג) וּבְיַד הַמִּצְרִי חֲנִית כְּמָא דְאַתְּ אָמֵר כִּמְנוֹר אוֹרְגִים, דָּא מַטֵּה הָאֱלֹהִים דְּהֲוָה בִּידֵיהּ חָקִיק בִּשְׁמָא גְּלִיפָא מְפָרַשׁ בִּנְהִירוּ דְּצֵרוּפֵי אַתְוָון דְּהֲוָה גָּלִיף בְּצַלְאֵל וּמְתִיבְתָּא דִילֵיהּ דְּאִקְרֵי אוֹרֵג דִּכְתִיב, (שמות ל״ה:ל״ה) מִלֵּא אוֹתָם וְגו' חָרָשׁ וְחשֵׁב וְרוֹקֵם וְגו'. וְהַהוּא מַטֶּה הֲוָה נָהִיר שְׁמָא גְּלִיפָא בְּכָל סִטְרִין בִּנְהִירוּ דְּחֲכִימִין דְּהֲווּ מְגַלְּפִין שְׁמָא מְפָרַשׁ (פקודי ר\"ס א) בְּאַרְבְּעִין וּתְרֵין גּווָֹנֵי. וּקְרָא מִכָּאן וּלְהָלְאָה כְּמָה דְּאָמַר זַכָּאָה חוּלָקֵיהּ.","תִּיבוּ יַקִּרִין תִּיבוּ וּנְחַדֵּשׁ תִּקּוּן דְּכַלָּה בְּהַאי לֵילְיָא. דְּכָל מָאן דְּאִשְׁתַּתַּף בַּהֲדָהּ בְּהַאי לֵילְיָא יְהֵא נְטִיר עֵילָא וְתַתָּא כָּל הַהִיא שַׁתָּא וְיַפֵּיק שַׁתָּא בִּשְׁלָם. עֲלַיְיהוּ כְּתִיב (תהילים ל״ה:ה׳) חוֹנֶה מַלְאַךְ יְיָ סָבִיב לִירֵאָיו וַיְחַלְּצֵם טַעֲמוּ וּרְאוּ כִּי טוֹב יְיָ:","פָּתַח רִבִּי שִׁמְעוֹן וְאָמַר בְּרֵאשִׁית בָּרָא אֱלהִים. הַאי קְרָא אִית לְאִסְתַּכְּלָא בֵּיהּ. דְּכָל מַאן דְּאָמַר אִית אֱלָהָא אָחֳרָא אִשְׁתְּצֵי מֵעָלְמִין. כְּמָה דְּאִתְּמַר (ירמיהו י׳:י״א) כִּדְנָה תֵמְרוּן לְהוֹם אֱלָהָא (אלהיא) דִי שְׁמַיָא וְאַרְקָא לָא עֲבַדוּ יֵאבַדוּ מֵאַרְעָא וּמִן תְּחוֹת שְׁמַיָּא אֵלֶּה. בְּגִין דְּלֵית אֱלָהָא אָחֳרָא בַּר קוּדְשָׁא בְרִיךְ הוּא בִּלְחוֹדוֹי."],[[0,"","קמב) \u0003וכיון דאתעבידא\u0004 וכו': וכיון שנעשו מהם רקיעים מי שורה בהם. חזר ואמר, לשמש שם אהל בהם. אותו השמש הקדוש, שהוא ז\"א, שם מדורו ומשכנו בהם, ונתעטר בהם."],[0,"","פירוש. שואל מאחר שאומר שהעמודא דנהורא יוצא מהרקיע ולמעלה, ומהרקיע ולמטה לא נמשך רק תושבחתא מנהון, א\"כ יש לשאול, מאן משמש בהאי עמודא דנהורא. וז\"ש \u0003מאן שריא בהון\u0004. ומשיב כי הז\"א הנקרא \u0003שמשא\u0004 הוא המתעטר ושם \u0003משכניה\u0004 בעמודא דנהורא הזה. כי הוא מתעטר בהאי עמודא כמו תחת חופה, כי \u0003אהל\u0004 פירשו חופה ממעל לו, וזהו \u0003לשמש שם אהל בהם\u0004."],[1,"","קמג) \u0003כיון דשרי באינון\u0004 וכו': כיון, שז\"א, שורה באותם הרקיעים, ומתעטר בהם, אז, והוא כחתן יוצא מחופתו, הוא שמח ורץ ברקיעים אלו, ויוצא מהם, ונכנס ורץ לתוך מגדל אחר אחד, במקום אחר. מקצה השמים מוצאו. ודאי מעולם העליון יוצא ובא, שהוא קצה השמים למעלה, דהיינו בינה. \u0003ותקופתו\u0004, מי הוא תקופתו. הוא קצה השמים למטה, דהיינו מלכות. שהיא תקופת השנה הסובבת לכל הסיומים, ונקשרה מן השמים עד הרקיע הזה."],[1,"","פירוש. רומז כאן לסוד גדול ונורא, והוא יציאת החמה מנרתיקה, דהיינו מחופתה, כי אחר שנעשה הזווג הגדול \u0003באינון רקיעין\u0004, בסוד החופה, הוא יוצא מאינון הרקיעין \u0003למגדלא חדא אחרא באתר אחרא\u0004 דהיינו, במקום המלכות, הנקראת מגדול עוז שם ה'. כי אז עולה המלכות למעלה ומתיחדת עמו ברזא דאחד."],[1,"","והנה סיום המלכות נק' \u0003תקופת השנה\u0004, שמטרם התיקון היו נאחזות שם הקליפות הנקראות קץ הימים. (כמ\"ש בזוהר בא אות ל\"א). ועתה אחר גמר התיקון צריכים עוד לתקן הבחינה הזאת במיוחד, וזה נעשה ע\"י יציאת החמה מנרתיקה, בסו\"ה \u0003והוא כחתן יוצא מחופתו\u0004, ומאיר ובא \u0003במגדלא חדא\u0004 שהוא המלכות כנ\"ל, ואז ישיש כגבור לרוץ אורח, כי הוא רץ בהאי מגדלא \u0003ותקופתו על קצותם\u0004, כי הוא מאיר \u0003מקצה השמים לעילא\u0004 עד כל הסיומין שבמלכות, כדי לתקן האי \u0003תקופת השנה דקצה השמים דלתתא\u0004."],[1,"","וז\"ש \u0003דאסחרא לכל סייפין\u0004, סייפין פירושו סופין, דהיינו סיומין, כי תיקון זה גומר לתקן כל בחינות הסיומין שיש במלכות. ובזה \u0003אתקשרת מן השמים עד רקיעא דא\u0004, כלומר, שהמלכות מקבלת הארת \u0003קצה השמים\u0004 מלעילא עד \u0003רקיעא דא\u0004 של הז\"א."],[2,"","קמד) \u0003ואין נסתר מחמתו\u0004: היינו, שאין נסתר מחמתו מאותה תקופה, שהיא תקופת השנה הנ\"ל, ומתקופת השמש הסובב בכל צד. \u0003ואין נסתר\u0004, פירושו, שאין מי מכל המדרגות העליונות שתסתר ממנו, שהיו כולן סובבות ובאות אליו, וכל אחת ואחת אין מי שתסתר ממנו. \u0003מחמתו\u0004, פירושו, שמתחמם ושב אליהם אל החברים בשעה שהם בתשובה שלמה. כל השבח הזה, וכל הערך הזה, הוא בשביל התורה שעסקו. שכתוב, תורת ה' תמימה. \u0003עלויא\u0004 פירושו ערך, מלשון, דפליג בעלויא (קדושין מ\"ב)."],[2,"","פירוש, כי לאחר הזווג הגדול הזה נעשה כיסוי והעלם לכלהו נהורין עלאין (כנ\"ל אות צ\"ד עש\"ה). וע\"כ צריכין לזווג החדש הזה בהאי \u0003מגדלא חדא\u0004 בסוד \u0003ותקופתו על קצותם\u0004, שהוא חוזר ומגלה כל נהורין עלאין \u0003דאתכסי\u0004 בסבת ביטול הב\"ן מטרם עליתו לס\"ג כנ\"ל ע\"ש."],[2,"","וז\"ש \u0003ואין נסתר מחמתו דההיא תקופה דא ותקופה דשמשא דאסחר בכל סטרא\u0004, כי הזווג הזה דתקופת השמש עם תקופת השנה הנ\"ל, מתקן את הסייפין דמלכות מכל סטרא, דהיינו מכל הבחינות, עד שהוא מספיק לתיקון השלם, שיעלה הב\"ן וישוב להיות ס\"ג. שהוא תיקון שלם מכל הבחינות, אשר אחר זה \u0003ואין נסתר, לית דאתכסי מניה מכל דרגין עלאין\u0004 כי כלהו דרגין ונהורין עלאין חוזרים להתגלות בתכלית הגילוי \u0003דהוו כלהו מסחרין ואתיין לגביה וכל חד וחד לית מאן דיתכסי מניה\u0004 כי כלהו דרגין ונהורין חוזרים ובאים לו לאט לאט עד שאין דבר נעלם ממנו."],[2,"","וז\"ש, \u0003מחמתו, בשעתא דאתחמם ותב לגבייהו בתיובתא שלים\u0004: כלומר, שאין גילוי האמור נעשה ברגע אחד, כי תקופת השמש הולכת ומאירה עד שיתחמם בשיעור מספיק \u0003לתיובתא שלים\u0004, ע\"ד שאמרו חז\"ל שהרשעים נידונים בו וצדיקים מתרפאים הימנו. ואז זוכים לגילוי הגדול האמור."],[3,"","קמה) \u0003שית זמנין כתיב\u0004 וכו': שש פעמים כתוב כאן הויה, וששה פסוקים הם מן השמים מספרים עד תורת ה' תמימה (תהלים י\"ט) ועל סוד זה כתוב, \u0003בראשית\u0004, שבו שש אותיות. \u0003ברא אלקים את השמים ואת הארץ\u0004, הן שש מלים. המקראות האחרים, שמן תורת ה' תמימה עד הנחמדים מזהב הם רק כנגד שש פעמים הויה שכתוב בהם, אבל ששה הכתובים עצמם אינם נדרשים. ששת המקראות שמן השמים מספרים עד תורת ה' תמימה, הם בשביל שש אותיות שבכאן, שבמלה בראשית. וששת השמות, הם בשביל שש המלים שבכאן, שהם ברא אלקים את השמים ואת הארץ."],[3,"","ביאור הדברים, נודע שכל דרגא הנגלית בעולמות, הנה תחילה באה בבחינת אותיות, שאז עדיין לא נודעה. ואח\"כ באה בצירופי תיבות, ואז נודעת המדרגה מה שיש בה. ע\"ד שנתבאר לעיל בסוד רי\"ו אותיות, וע\"ב תיבין. (אות קט\"ז) וז\"ס \u0003שית אתוון\u0004 שבמלת \u0003בראשית\u0004 שהן כבר כוללות כל מציאות שמים וארץ בסוד שית אתוון שבהם, אלא עוד לא נודעו, כי ע\"כ מרומזין רק באתוון בלי שום צירופי מילים. ואח\"כ יש \u0003שית תבין\u0004 שהם: \u0003ברא, אלהים, את, השמים, ואת, הארץ\u0004. וכאן באה לכלל גילוי מה שכלול במלת \u0003בראשית\u0004, כי הם השמים והארץ ומלואם."],[3,"","ועד\"ז יש להבין את ה\u0003שית קראי\u0004 שיש מן \u0003השמים מספרים\u0004 עד \u0003תורת ה' תמימה\u0004, שהוא עדיין תחילת הגילוי של גמר התיקון דהיינו עוד בבחינת אותיות, ע\"ד ה\u0003שית אתוון\u0004 שבמלה \u0003בראשית\u0004. והגילוי הגמור של גמר התיקון מתחיל מ\u0003תורת ה' תמימה\u0004 ולהלן, שיש שם \u0003שית שמהן\u0004, שכל שם מורה על השגה, להורות שרק אחר התיובתא שלימתא, בסו\"ה \u0003ואין נסתר מחמתו\u0004, אז מתגלים כל צירופי התבין שהיו בזווג הגדול בגמר התיקון, דהיינו ה\u0003שית שמהן\u0004."],[3,"","וזה אמרו \u0003ועל רזא דא כתיב בראשית, הא שית אתוון. ברא אלהים את השמים ואת הארץ, הא שית תבין\u0004. על סוד השית קראי ושית שמהן הנ\"ל, כתוב בתורה שית \u0003אתוון\u0004 בבראשית, ששם שמים וארץ נעלמים. ובשית תבין באו לידי גילוי, דהיינו \u0003ברא, אלהים, את, השמים, ואת, הארץ\u0004. כן השית קראי שמ\u0003השמים מספרים עד תורת ה' תמימה\u0004 עוד לא נגלה הזווג הגדול דגמר התיקון על בוריו, אלא אח\"כ, אחר הכתוב \u0003אין נסתר מחמתו\u0004, נגלו \u0003שית שמהן\u0004, אשר ב\u0003שית שמהן\u0004 אלו בא כל הגילוי הגדול של גמר התיקון על בוריו ושלימותו."],[3,"","וז\"ש \u0003קראי אחרנין לקבל שית זמנין ה'\u0004. דהיינו \u0003שית שמהן\u0004 הוי\"ה, כי הפסוקים הכתובים אחרי ואין נסתר מחמתו עד סוף המזמור רומזים כנגד ה\u0003שית שמהן\u0004 שכתוב בהם. ונמצא אשר \u0003שית קראי בגין שית אתוון דהכא, שית שמהן בגין שית תבין דהכא,\u0004 דהיינו כמבואר, ש\u0003שית קראי\u0004 מן \u0003השמים מספרים עד תורת ה' תמימה\u0004, הם כמו \u0003שית אתוון דבראשית\u0004 שאינן מגולות בשלמות. ו\u0003שית שמהן\u0004 שבכתובים מ\u0003תורת ה' תמימה\u0004 עד הסוף הם כמו שית תבין, \u0003ברא אלהים את השמים ואת הארץ\u0004, שכאן באו על שלמותם. ובא להשמיענו, שב\u0003שית קראי\u0004 עוד לא נודעה מדרגתם, והם כמו \u0003שית אתוון\u0004 ד\u0003בראשית\u0004, אלא אחר ה\u0003שית קראי\u0004, ב\u0003קראי אחרנין\u0004 שבהם \u0003שית שמהן\u0004, אז באו לגילוי הנרצה."],[4,"","קמו) \u0003עד דהוו יתבי\u0004 וכו': בעוד שהיו יושבים, נכנסו רבי אלעזר בנו ור' אבא. אמר להם, ודאי פני השכינה באו, ועל כן קראתי אתכם פניא\"ל (כנ\"ל. אות קי\"ט) שהוא אותיות פני אל. כי ראיתם פני השכינה פנים בפנים, ועתה, שאתם יודעים, וגילה לכם המקרא של בניהו בן יהוידע, ודאי שהוא דבר של עתיקא קדישא, שה\"ס הכתר, וכן המקרא שלאחריו, והוא הכה את האיש המצרי. ואותו הסתום מכל, אמרו שהוא עתיקא קדישא."],[4,"","פירוש. סובב על הענין ההוא דטעין חמרי שגילה להם לרבי אלעזר ור\"א את נשמת \u0003בניהו בן יהוידע\u0004, שקרא ר\"ש להם משום זה בשם פניאל, (לעיל אות קי\"ט), שנשמת \u0003בניהו בן יהוידע\u0004, היא ממש קומה זו העתידה להגלות בגמר התיקון, כמ\"ש שם, וע\"כ קרה גם להם ענין הכיסוי והעלם לכלהו נהורין עלאין (כנ\"ל אות קי\"ג) כמ\"ש כאן בזווג דתקופת השמש בתקופת השנה, עד דמטי לר\"ש בן לקוניא וחמי לר\"ש תמן, שאז זכו שוב לכלהו נהורין כמ\"ש שם."],[4,"","וז\"ש להם ר\"ש כאן \u0003והשתא דקא ידעתון וגלי לכו קרא דובניהו בן יהוידע\u0004, כי רמז להם שהם כבר זכו ל\u0003שית קראי\u0004 דהשמים מספרים, והם כבר ב\u0003שית שמהן\u0004 דבקראי אחרנין, כי כבר נודע להם בגלוי נשמת \u0003בניהו בן יהוידע\u0004. כי בזמן שהשיגו נשמת בניהו בן יהוידע ע\"י \u0003ההוא טייעא\u0004, עוד לא היתה השגתם נודעת, כי היו אז בסוד \u0003שית קראי\u0004, כי ע\"כ עבר עליהם האי אורחא דנסין ואתוון. אבל עתה נודעת להם נשמת בניהו בגלוי. וזה אמרו \u0003והשתא דקא ידעתון וגלי לכו קרא דובניהו בן יהוידע\u0004."],[4,"","וזה אמרו \u0003ודאי דמלה דעתיקא קדישא איהו וקרא דאבתריה\u0004, כי נשמת \u0003בניהו בן יהוידע\u0004 ה\"ס \u0003מלה דעתיקא\u0004, דהיינו הזווג הגדול דעתיק יומין, שזה \u0003ידעתון\u0004 גם אז, אבל עתה נודע לכם כי גם \u0003קרא דאבתריה, שהוא הכה את שני אריאל מואב\u0004 וגו' \u0003והוא הכה את האיש המצרי\u0004 וגו', שכל אלו קראי הם ג\"כ מלה דעתיקא. \u0003וההוא דסתים מכלא אמרו\u0004, דהיינו עתיק יומין שהוא \u0003סתים מכלא\u0004."],[5,"","קמז) \u0003והאי קרא איהו\u0004 וכו': והמקרא הזה, והוא הכה את האיש המצרי, הוא מתבאר במקום אחר, דהיינו במדרגה אחרת, באופן הזה. פתח ואמר. והוא הכה את האיש המצרי איש מדה חמש באמה. והכל הוא סוד אחד. המצרי הזה, הוא אותו הנודע, שעליו כתוב, גדול מאד בארץ מצרים בעיני עבדי וגו'. כי הוא גדול ויקר, כמו שגילה הזקן ההוא (לעיל אות צ\"ט)."],[5,"","פירוש. האי קרא שביארו רב המנונא סבא, דהיינו \u0003והוא הכה את איש מצרי איש מראה\u0004 וכו', הוא מתבאר במדרגה אחרת באופן אחר, דהיינו ע\"פ הלשון שבדברי הימים, כמ\"ש והולך."],[5,"והוא הכה את האיש המצרי","וכו' \u0003וכלא רזא חדא איהו\u0004: ב' הכתובים הם סוד אחד, כי (בשמואל ב' כ\"ג) כתוב \u0003והוא הכה את איש מצרי איש מראה\u0004, וכאן בדברי הימים כתיב, \u0003והוא הכה את האיש המצרי איש מדה חמש באמה\u0004, הנה שניהם סוד אחד, וקאי על משה, וענין שינוי הלשון, מבאר לפנינו."],[6,"","קמח) \u0003והאי קרא במתיבתא\u0004 וכו: והמקרא הזה, נשנה בישיבה העליונה. איש מדה, הכל אחד. איש מראה ואיש מדה, הכל אחד. משום שהוא שבת ותחום שבת. שכתוב, ומדותם מחוץ לעיר. וכתוב לא תעשו עול במשפט במדה. ועל כן איש מדה הוא. והוא ממש איש מדה, ארכו הוא מסוף העולם ועד סוף העולם. כן היה אדם הראשון. ואם תאמר, הרי כתוב, חמש באמה. חמש באמה אלו, מסוף העולם עד סוף העולם היו."],[6,"","פירוש. הוא מתיבתא דקב\"ה, שעל בני מתיבתא זו אמר ר\"ש ראיתי בני עליה והם מועטים (סוכה מ\"ה:), ויש מתיבתא תתאה, והוא מתיבתא דמט\"ט. ואומר, ש\u0003האי קרא\u0004 שביארו הסבא, נתבאר \u0003במתיבתא עלאה\u0004. לפי שמבאר לפנינו."],[6,"","והנה \u0003איש מראה\u0004 הוא המדרגה דמשה, שעליו נאמר, ולא קם עוד נביא בישראל כמשה (דברים ל\"ד), שה\"ס ומראה ולא בחידות (במדבר י\"ב). \u0003ואיש מדה\u0004, קאי ג\"כ על סוד המראה, אלא בסוד המדה דהאי מראה. כי סוד המדה דהאי מראה הוא מסוף העולם עד סופו."],[6,"","ומראה ומדה דומים לשבת ותחום שבת, שתחום שבת הוא קצה המדה דשבת. אלא בשתא אלפי שני, מדת התחום שבת מצומצמת רק על אלפים אמה. ואחר גמר התיקון יהיה תחום שבת מסוף העולם עד סופו. שהוא סוד והיה ה' למלך על כל הארץ (זכריה י\"ד)."],[6,"","וז\"ש, \u0003איש מראה ואיש מדה כלא חד בגין דאיהו שבת ותחומא. דכתיב ומדותם מחוץ לעיר, וכתיב לא תעשו עול במשפט במדה\u0004. הרי שענין מדה הוא קצה הגבול של הדבר, כן \u0003איש מדה\u0004 מורה על קצה הגבול של שבת לאחר גמר התיקון, שהוא מסוף העולם ועד סופו. וז\"ש, \u0003ואיהו ממש איש מדה\u0004: איש מדה פירושו בעלה דהאי מדה ממש. כלומר, שאין המדה שולטת עליו, אלא הוא השולט על המדה ועושה אותה ע\"פ חשקו וחפצו."],[6,"","וז\"ש \u0003אדם הראשון הכי הוה\u0004: היינו מקודם שחטא בעצה\"ד, שהיה ארכו מסוף העולם עד סופו (חגיגה י\"ב. ) ומאיר מסוף העולם עד סופו, כמדת תחום השבת שלאחר גמר התיקון."],[6,"אינון חמש באמה מסייפי עלמא עד סייפי עלמא הוה",": כי אלו \u0003חמש באמה\u0004 ה\"ס ע\"ס, אשר עיקרן הן רק כח\"ב תו\"מ (כנ\"ל במראות הסולם אות א' ד\"ה אמנם) שלאחר גמר התיקון הן יתפשטו מסוף העולם עד סופו."],[7,"","קמט) \u0003וביד המצרי חנית\u0004: הוא כמו שאתה אומר כמנור אורגים, שזהו מטה האלקים שהיה בידו, המפותח בשם החקוק והמפורש בהארת צירופי האותיות, שחקק בצלאל והישיבה שלו, שנקראת אורג, שכתוב, מלא אותם וגו'. חרש וחושב וגו' ובשש \u0003וארג\u0004. והמטה ההוא היה מאיר בו השם החקוק בכל הצדדים, בהארת החכמים שהיו חוקקים את השם המפורש בארבעים ושתים בחינות. והמקרא שמכאן והלאה הוא כמו שביאר הזקן לעיל. אשרי חלקו."],[7,"","פירוש. סוד הצירופים של האותיות לשמות הקדושים נקראים מעשי \u0003אורג\u0004, בדומה לאורג האורג החוטים לבגד, כן מצטרפות ומתחברות האותיות לתבות של שמות הקדושים, שפירושן השגות קדושות. ואומר שב\u0003מטה האלהים\u0004 שהיה ביד משה, \u0003חקיק\u0004, אותם צירופי האותיות של השם המפורש, דחקיק \u0003בצלאל ומתיבתא דיליה\u0004 במלאכת המשכן, ולזה נקרא \u0003מטה האלהים\u0004 בשם \u0003מנור אורגים\u0004, על שם \u0003בצלאל\u0004 הנקרא \u0003אורג, ומנור\u0004 כמו מאור, ואורג הוא \u0003בצלאל\u0004. לרמז שהמאור של צרופי אתוון דשם המפורש היה בבחינת המאור של השם המפורש דחקיק בצלאל. וז\"ש, \u0003בנהירו דצרופי אתוון דהוה גליף בצלאל\u0004, וכו'."],[7,"","והנה מטרם גמר התיקון לא היה המטה מאיר מכל סטרין, שהרי היה בו הפרש בין מטה אלהים למטה משה, ובמטה משה כתוב, שלח ידך ואחוז בזנבו, ויהי למטה בכפו. הרי שלא היה מאיר מכל סטרין. אמנם לאחר גמר התיקון, הוא מאיר מכל סטרין."],[7,"","וז\"ש \u0003וההוא מטה הוה נהיר שמא גליפא בכל סטרין, בנהירו דחכימין דהוו מגלפין שמא מפרש במ\"ב גווני\u0004. כי השם המפורש, שהיה חקוק במטה היה מאיר \u0003בכל סטרין\u0004, דהיינו בבחינת בלע המות לנצח (ישעיה כ\"ה) כנ\"ל. וע\"כ היה מאיר מכל הצדדים בשוה, והאור של השם שהיה חקוק במטה, היה בסוד נהירו דחוכמתא דשם מ\"ב."],[8,"","קנ) \u0003תיבו יקרין תיבו\u0004 וכו': שבו יקרים, שבו ונחדש תקון הכלה בלילה זה, שכל מי שמתחבר עמה בלילה הזה, יהיה נשמר, כל אותה השנה, למעלה ולמטה, ויוציא שנתו בשלום. עליהם כתוב, חונה מלאך ה' סביב ליראיו ויחלצם טעמו וראו כי טוב ה'."],[8,"","יש בזה ב' פירושים ששניהם יחד אמיתיים. (עיין לעיל אות קכ\"ה) וכן הוא בפירוש של \u0003ויפיק שתא בשלם\u0004. ולפי הפירוש הא' המובא שם הוא כפשוטו, שמתוך שיום מתן תורה הוא בחינת הארה של גמר התיקון, דבלע המות לנצח וחירות ממלאך המות. ע\"כ ראוי להתאמץ להמשיך האור הזה בשעתו ביום השבועות, כי בטבע המאורות שחוזרים ומתחדשים במועדם, ויהיה מובטח גם עתה \u0003דיפיק שתא בשלם\u0004, ותהיה לו חירות ממלאך המות."],[8,"","ולפי הפירוש הב' אשר שם, דקאי על הזמן של גמר התיקון ממש, יהיה כאן הפי' של \u0003ויפיק שתא בשלם\u0004, כי המלכות נקראת שנה, ומתוך התחדשות המאורות של התמכין דאורייתא, לאחר גמר התיקון, הנה יהיה מובטח לתקן השנה שהיא המלכות בכל השלימות. כי בחינת התחדשות המאורות של התמכין דאורייתא נקראת תיקון ליליא דכלה, שהיא המלכות הנקראת שנה, כמ\"ש שם. ועי\"ז \u0003יפיק שתא בשלם\u0004, יוציא השנה בשלום, בכל השלמות, כמבואר."],[9,"","קנא) \u0003פתח ר\"ש ואמר\u0004 וכו': פתח ר' שמעון ואמר, בראשית ברא אלקים. מקרא זו, יש להסתכל בו. כי כל מי שאומר שיש אל אחר, נאבד מן העולם. כמו שנאמר, כדנה תאמרון להום, אלהא די שמיא וארקא לא עבדו, יאבדו מארעא ומן תחות שמיא אלה, משום שאין אל אחר חוץ מהקב\"ה בלבדו."],[9,"","ביאור הדברים, סובב על מה שאמר \u0003תיבו ונחדש תיקון דכלה\u0004, וע\"כ פתח לבאר היטב קרא דבראשית ברא אלקים, שהוא השורש לכל תיקוני הכלה במשך שתא אלפי שני, וסמך על מה שפירש לעיל (אות י\"ד) דאלקים הוא אלהים עלאה, שהוא בינה. ונקרא אלהים בסוד \u0003מ\"י\u0004 ברא \u0003אל\"ה\u0004, וכמה דאשתתף מ\"י באל\"ה הכי הוא שמא דאשתתף תדיר, וברזא דא אתקיים עלמא עש\"ה."],[9,"","ועם זה ביאר כאן, \u0003אלהא די שמיא\u0004 וכו', כי הקב\"ה הוא הבינה דאקרי \u0003אלהים\u0004 בסוד שיתוף \u0003מ\"י\u0004 ב\u0003אל\"ה\u0004 על ידי התלבשות אור החכמה בלבוש יקר דנהיר מחסדים כנ\"ל, דברזא דא אתקיים עלמא. וע\"כ \u0003אלהיא די שמיא וארקא לא עבדו\u0004, אשר לא יכלו ליתן קיום לעולם, דהיינו אלהים אחרים, המפרידים \u0003אל\"ה\u0004 מ\u0003מ\"י\u0004, הם מוכרחים בהחלט להאבד \u0003מן תחות שמיא\u0004 דא דאתתקן בחיבור \u0003אלה\u0004 ב\u0003מ\"י\u0004. כי מכחם לא יכול להיות קיום לעולם, אלא חורבן. וע\"כ מדגיש הכתוב \u0003ומן תחות שמיא אל\"ה\u0004. וז\"ש \u0003והאי קרא איהו תרגום בר ממלה דסוף קרא\u0004, דהיינו אל\"ה, שהוא להורות על ענין חיבור \u0003מ\"י אל\"ה\u0004 הנ\"ל. כמ\"ש והולך."]],[[0,"","וְכֵיוָן שֶׁנַּעֲשִׂים מֵהֶם רְקִיעִים, מִי שׁוֹרֶה בָהֶם חָזַר וְאָמַר, לַשֶּׁמֶשׁ שָׂם אֹהֶל בָּהֶם. אוֹתוֹ שֶׁמֶשׁ, קָדוֹשׁ שָׂם מְדוֹרוֹ וּמִשְׁכָּנוֹ בָהֶם וּמִתְעַטֵּר בָּהֶם."],[1,"","כֵּיוָן שֶׁשּׁוֹרֶה בְּאוֹתָם רְקִיעִים וּמִתְעַטֵּר בָּהֶם, אֲזַי - וְהוּא כְּחָתָן יֹצֵא מֵחֻפָּתוֹ. שָׂמֵחַ וְרָץ בְּאוֹתָם רְקִיעִים. יוֹצֵא מֵהֶם וְרָץ לְתוֹךְ מִגְדָּל אֶחָד אַחֵר בְּמָקוֹם אַחֵר. מִקְצֵה הַשָּׁמַיִם מוֹצָאוֹ - וַדַּאי מֵעוֹלָם עֶלְיוֹן יוֹצֵא וּבָא, שֶׁהוּא קְצֵה הַשָּׁמַיִם לְמַעְלָה. וּתְקוּפָתוֹ - מִי זֶה תְּקוּפָתוֹ זֶה קְצֵה הַשָּׁמַיִם לְמַטָּה, שֶׁהִיא תְקוּפַת הַשָּׁנָה שֶׁסּוֹבֶבֶת אֶת כָּל הָאֵיבָרִים, וּמִתְקַשֶּׁרֶת מִן הַשָּׁמַיִם עַד רָקִיעַ זֶה. וְאֵין נִסְתָּר מֵחַמָּתוֹ - שֶׁאוֹתָהּ תְּקוּפָה זוֹ וּתְקוּפַת הַשֶּׁמֶשׁ שֶׁמְּסוֹבֵב בְּכָל צַד."],[2,"","וְאֵין נִסְתָּר - אֵין מִי שֶׁמִּתְכַּסֶּה מִמֶּנּוּ מִכָּל הַדְּרָגוֹת הָעֶלְיוֹנוֹת שֶׁהָיוּ כֻלָּם מַקִּיפוֹת וּבָאוֹת אֵלָיו, וְכָל אֶחָד וְאֶחָד אֵין מִי שֶׁמִּתְכַּסֶּה מִמֶּנּוּ. מֵחַמָּתוֹ - בְּשָׁעָה שֶׁמִּתְחַמֵּם וְשָׁב (ומשתוקק) לְגַבֵּיהֶם בִּתְשׁוּבָה (בתשוקה) שְׁלֵמָה, כָּל הַשֶּׁבַח הַזֶּה וְכָל הָעִלּוּי הַזֶּה בִּגְלַל הַתּוֹרָה הוּא, שֶׁכָּתוּב תּוֹרַת ה' תְּמִימָה."],[3,"","שֵׁשׁ פְּעָמִים כָּתוּב כָּאן ה', וְשִׁשָּׁה פְסוּקִים מִן \"הַשָּׁמַיִם מְסַפְּרִים\" עַד \"תּוֹרַת ה' תְּמִימָה\". וְעַל סוֹד זֶה כָּתוּב בְּרֵאשִׁית - הֲרֵי שֵׁשׁ אוֹתִיּוֹת. בָּרָא אֱלֹהִים אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ - הֲרֵי שֵׁשׁ תֵּבוֹת. פְּסוּקִים אֲחֵרִים כְּנֶגֶד שֵׁשׁ פְּעָמִים ה'. שִׁשָּׁה פְסוּקִים בִּגְלַל שֵׁשׁ אוֹתִיּוֹת שֶׁל כָּאן. שִׁשָּׁה שֵׁמוֹת בִּגְלַל שֵׁשׁ תֵּבוֹת שֶׁל כָּאן."],[4,"","בְּעוֹדָם יוֹשְׁבִים, נִכְנְסוּ רַבִּי אֶלְעָזָר בְּנוֹ וְרַבִּי אַבָּא. אָמַר לָהֶם, וַדַּאי פְּנֵי הַשְּׁכִינָה בָּאוּ, וְלָכֵן קָרָאנוּ לָכֶם פְּנִיאֵ\"ל, שֶׁהֲרֵי רְאִיתֶם אֶת הַשְּׁכִינָה פָּנִים בְּפָנִים. וְעַכְשָׁו שֶׁיְּדַעְתֶּם וְגִלָּה לָכֶם הַכָּתוּב שֶׁל \"וּבְנָיָהוּ בֶן יְהוֹיָדָע\" - וַדַּאי שֶׁדָּבָר עַתִּיק קָדוֹשׁ הוּא וְהַפָּסוּק שֶׁלְּאַחֲרָיו. וְאוֹתוֹ הַסָּתוּם מֵהַכֹּל אֲמָרו."],[5,"","וּפָסוּק זֶה הוּא בְּמָקוֹם אַחֵר כְּגוֹן זֶה. פָּתַח וְאָמַר, (דברי הימים א יא) וְהוּא הִכָּה אֶת הָאִישׁ הַמִּצְרִי אִישׁ מִדָּה חָמֵשׁ בָּאַמָּה. וְהַכֹּל סוֹד אֶחָד הוּא. מִי הַמִּצְרִי אוֹתוֹ הַיָּדוּעַ, (שמות יא) גָּדוֹל מְאֹד בְּאֶרֶץ מִצְרַיִם בְּעֵינֵי עַבְדֵי וְגוֹ', גָּדוֹל וְנִכְבָּד כְּמוֹ שֶׁגִּלָּה אוֹתוֹ זָקֵן (רב המנונא)."],[6,"","וּפָסוּק זֶה מִתְבָּאֵר בַּיְשִׁיבָה הָעֶלְיוֹנָה. אִישׁ מִדָּה הַכֹּל אֶחָד. (שמואל ב כג) אִישׁ מַרְאֶה וְאִישׁ מִדָּה הַכֹּל אֶחָד. בִּגְלַל שֶׁהוּא שַׁבָּת וּתְחוּם, שֶׁכָּתוּב (במדבר לה) וּמַדּתֶם מִחוּץ לָעִיר, וְכָתוּב (ויקרא יט) לֹא תַעֲשׂוּ עָוֶל בַּמִּשְׁפָּט בַּמִּדָּה. וְעַל זֶה אִישׁ מִדָּה הוּא, וְהוּא מַמָּשׁ אִישׁ מִדָּה הוּא, אָרְכּוֹ מִסּוֹף הָעוֹלָם וְעַד סוֹף הָעוֹלָם. אָדָם הָרִאשׁוֹן כָּךְ הָיָה. וְאִם תֹּאמַר, הֲרֵי כָּתוּב חָמֵשׁ בָּאַמָּה אוֹתָם חָמֵשׁ בָּאַמָּה הָיוּ מִסּוֹף הָעוֹלָם וְעַד סוֹף הָעוֹלָם."],[7,"","(דברי הימים א יא) וּבְיַד הַמִּצְרִי חֲנִית, כְּמוֹ שֶׁנֶּאֱמַר כִּמְנוֹר אֹרְגִים - זֶה מַטֵּה הָאֱלֹהִים שֶׁהָיָה בְּיָדוֹ חָקוּק בְּשֵׁם גָּלוּף מְפֹרָשׁ בְּאוֹר שֶׁל צֵרוּפֵי אוֹתִיּוֹת שֶׁהָיָה חוֹקֵק בְּצַלְאֵל וִישִׁיבָתוֹ, שֶׁנִּקְרָא אוֹרֵג, שֶׁכָּתוּב (שמות לה) מִלֵּא אֹתָם וְגוֹ' חָרָשׁ וְחֹשֵׁב וְרֹקֵם וְגוֹ'. וְאוֹתוֹ מַטֶּה הָיָה מֵאִיר שֵׁם חָקוּק בְּכָל הַצְּדָדִים בָּאוֹר שֶׁהַחֲכָמִים שֶׁהָיוּ חוֹקְקִים שֵׁם הַמְפֹרָשׁ בְּאַרְבָּעִים וּשְׁנַיִם אֳפָנִים. וְהַפָּסוּק מִכָּאן וָהָלְאָה כְּמוֹ שֶׁאָמַר. אַשְׁרֵי חֶלְקוֹ."],[8,"","שְׁבוּ נִכְבָּדִים, שְׁבוּ וּנְחַדֵּשׁ תִּקּוּן הַכַּלָּה בַּלַּיְלָה הַזֶּה. שֶׁכָּל מִי שֶׁמִּשְׁתַּתֵּף יַחַד אִתָּהּ בַּלַּיְלָה הַזֶּה, יִהְיֶה שָׁמוּר לְמַעְלָה וּלְמַטָּה כָּל הַשָּׁנָה הַהִיא וְיוֹצִיא שְׁנָתוֹ בְשָׁלוֹם. עֲלֵיהֶם כָּתוּב (תהלים לד) חוֹנֶה מַלְאַךְ ה' סָבִיב לִירֵאָיו וַיְחַלְּצֵם טַעֲמוּ וּרְאוּ כִּי טוֹב ה'."],[9,"","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, בְּרֵאשִׁית בָּרָא אֱלֹהִים. בְּפָסוּק זֶה יֵשׁ לְהִסְתַּכֵּל, שֶׁכָּל מִי שֶׁאוֹמֵר יֵשׁ אֱלוֹהַּ אַחֵר, מֻשְׁמָד מֵהָעוֹלָמוֹת, כְּמוֹ שֶׁנֶּאֱמַר (ירמיה י) כָּךְ תֹּאמְרוּ לָהֶם: אֱלֹהֵי הַשָּׁמַיִם וְאַרְקָא לֹא עָשׂוּ, יאבְדוּ מֵהָאָרֶץ וּמִתַּחַת הַשָּׁמַיִם אֵלֶּה. בִּגְלַל שֶׁאֵין אֱלוֹהַּ אַחֵר חוּץ מִן הַקָּדוֹשׁ בָּרוּךְ הוּא בִּלְבַדּוֹ."]]],[["וְהַאי קְרָא אִיהוּ תַּרְגּוּם בַּר מִמִּלָּה דְּסוֹף קְרָא. אִי תֵימָא בְּגִין דְּמַלְאָכִין קַדִּישִׁין לָא נִזְקָקִין לְתַרְגּוּם (נ\"ח ע\"ה א) וְלָא אִשְׁתְּמוֹדְעָן בֵּיהּ, מִלָה דָא יָאוֹת הִיא לְמֵימַר בְּלִישְׁנָא קַדִּישָׁא בְּגִין דְּיִשְׁמְעוּן מַלְאָכִין קַדִּישִׁין וִיהוֹן נִזְקָקִין לְאוֹדָאָה עַל דָּא. אֶלָּא וַדַּאי בְּגִין כָּךְ כְּתִיב תַּרְגּוּם דְּלָא נִזְקָקִין בֵּיהּ מַלְאָכִין קַדִּישִׁין לָא (ולא) יְקַנְאוּן בְּבַר נָשׁ לְאַבְאָשָׁא לֵיהּ, בְּגִין דִּבְהַאי קְרָא בִּכְלָלָא אִנּוּן מַלְאָכִין קַדִּישִׁין, דְּהָא אִנּוּן אֱלהִים אִקְרוּן וּבִכְלָלָא דְּאֱלהִים הֲווּ, וְאִנּוּן לָא עֲבַדוּ שְׁמַיָּא וְאַרְקָא.","וְאַרְקָא, וְאַרְעָא מִבָּעֵי לֵיהּ. אֶלָּא בְּגִין (קכ\"ו א) דְאַרְקָא אִיהִי חָדָא מֵאִנּוּן שְׁבַע אַרְעִין דִּלְתַתָּא. וּבְהַהוּא אֲתַר אִית בְּנִי בְּנוֹי דְּקַיִן. לְבָתַר דְּאִתְתָּרַךְ מֵעַל אַפֵּי אַרְעָא (כ\"ד ב) נָחִית לְתַמָּן וְעֲבִיד תּוֹלָדוֹת וְאִשְׁתַּבַּשׁ תַּמָּן דְּלָא יָדַע כְּלוּם. וְאִיהוּ אַרְעָא כְּפֵילָא דְּאִתְכְּפַל מֵחֲשׁוֹכָא וּנְהוֹרָא.","וְאִית תַּמָּן תְּרֵין מְמַנָּן שַׁלִּיטִין דִּי שָׁלְטִין דָּא בַּחֲשׁוֹכָא וְדָא בִּנְהוֹרָא. וְתַמָּן קִטְרוּגָא דָּא בְדָא. וְשַׁעֲתָא דְּנָחִית לְתַמָּן קַיִן, אִשְׁתְּתָפוּ דָּא בְדָא וְאִשְׁתְּלִימוּ כְּחֲדָא. וְכֹלָּא חָזֵי דְּאִנּוּן תּוֹלְדוֹת דְּקַיִן. וְעַל דָּא אִנּוּן בִּתְרֵין רֵאשִׁין כִּתְרֵין חֵיוָון, בַּר דְּכַד הַהוּא נְהוֹרָא שָׁלִיט נָצַח דִּילֵיהּ וְנָצַח עַל אָחֳרָא. וְעַל דָּא אִתְכְּלִילוּ דִי בַּחֲשׁוֹכָא בִּנְהוֹרָא וְהֲווּ חַד.","אִנּוּן תְּרֵין מְמַנָּן עַפְרִירָא וְקַסְטִימוֹן. וְדִיּוּקְנָא דִּלְהוֹן כִּדִיוּקְנָא דְּמַלְאָכִין קַדִּישִׁין בְּשִׁית גַּדְפִין. חַד דִּיוּקְנָא כְּתוֹרָ\"א, וְחַד דִּיוּקְנָא כְּנִשְׁרָ\"א. וְכַד מִתְחַבְּרָן אִתְעֲבִידוּ דִּיוּקְנָא דְּאָדָם.","כַּד אִנּוּן בְּחֲשׁוֹכָא מִתְהַפְּכִין לִדְּיוֹקְנָא דְנָחָשׁ בִּתְרֵין רֵאשִׁין וְאָזְלִין כְּחִוְיָא וְטָאסִין גּוֹ תְהוֹמָא וְאִסְתַּחְיָין בְּיַמָּא רַבָּא. כַּד מָטָאן לְשַׁלְשְׁלָאָה דְּעַזָּ\"א וַעֲזָאֵ\"ל מַרְגִּיזִין לוֹן וּמִתְעָרֵי לוֹן. וְאִנּוּן מְדַלְגִּין גּוֹ טוּרֵי חֲשׁוֹכָן וְחָשְׁבֵי דְּקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לְמִתְבַּע לוֹן דִּינָא.","וְאִלֵּין תְּרֵין מְמַנָּן שָׁאטִין בְּיַמָּא רַבָּא וּפָרְחִין מִתַּמָּן וְאָזְלִין בְּלֵילְיָא לְגַבֵּי (י\"ט ב', נ\"ה ב) נַעֲמָה אִמְהוֹן דְּשֵׁדִין דְּטָעוֹ אֲבַתְרָהָא דָּחֲלִין קַדְמָאִין וְחָשְׁבִין לְמִקְרַב לְגַבָּהּ. וְאִיהִי דְּלִיגַת שִׁתִּין אַלְפִין פַּרְסִין וְאִתְעֲבִידַת בְּכַמָּה צִיּוּרִין לְגַבֵּי בְּנֵי נְשָׁא בְּגִין דְּיִטְעוּן בְּנֵי נְשָׁא אֲבַתְרָהּ.","וְאִלֵּין תְּרֵין מְמַנָּן פַּרְחִין וּמְשַׁטְּטָן בְּכָל עָלְמָא וְאַהַדְּרָן לְאַתְרַיְיהוּ. וְאִנּוּן מִתְעָרִין לְאִנּוּן בְּנֵי בְּנוֹי דְּקַיִּן בְּרוּחָא דְיִצְרִין בִּישִׁין לְמֶעְבַּד תּוֹלָדוֹת.","שְׁמַיָּא דְּשָׁלְטִין תַּמָּן לָאו כְּהָנִי. וְלָא אוֹלִידַת אַרְעָא בְּחֵילָא דִלְהוֹן זְרוֹעָא (שלח קע\"ב א) וְחַצְדָא כְּהָנֵי. וְלָא אֲהַדְּרָן אֶלָּא בְּכַמָּה שְׁנִין וְזִמְנִין. וְאִנּוּן אֱלָהָא (אלהיא) דִי שְׁמַיָא וְאַרְקָא לָא עֲבַדוּ. יֵאבַדוּ מֵאַרְעָא עִילָּאָה דְתֵבֵל, דְּלָא יִשְׁלְטוּן בָּהּ וְלָא יְשָׁטְטוּן בָּהּ וְלָא יְהוֹן גָּרְמִין לִבְנִי נָשָׁא לְאִסְתָּאֳבָא מִמִקְרֵה לֵילְיָא. וְעַל דָּא יֵאבַדוּ מֵאַרְעָא וּמִן תְּחוֹת שְׁמַיָא דְּאִתְעֲבִידוּ (לעיל דף ג' א) בִּשְׁמָא דְּאֵלֶּה כְּמָה (ב א) דְּאִתְּמָר.","וְעַל דָּא הַאי קְרָא תַּרְגּוּם דְּלָא יַחְשְׁבוּן מַלְאֲכֵי עִלָּאֵי דְּעֲלַיְיהוּ אָמְרִין, וְלָא יְקַטְרְגוּ לָן. וְעַל דָּא רָזָא דְּאֵלֶּה כְּמָה דְּאִתְּמָר אִיהוּ מִלָּה קַדִּישָׁא דְּלָא אִתְחַלַּף בַּתַּרְגּוּם.","אָמַר לֵיהּ רִבִּי אֶלְעָזָר, הַאי קְרָא דִּכְתִיב, (ירמיהו י׳:ז׳) מִי (שמות צ\"ה ע\"ב) לא יִרָאֲךָ מֶלֶךְ הַגּוֹיִם כִּי לְךָ יָאָתָה, מַאי שְׁבָחָא אִיהוּ. אָמַר לֵיהּ אֶלְעָזָר בְּרִי, הַאי קְרָא בְּכַמָּה דוּכְתֵּי אִתְּמָר, אֲבָל וַדַּאי לָאו אִיהוּ (נ\"א הכי) דִּכְתִיב, (ירמיהו י׳:ז׳) כִּי בְכָל חַכְמֵי הַגּוֹיִם וּבְכָל מַלְכוּתָם דְּהָא אֲתָא לְמִפְתַּח פּוּמָא דְחַיָּיבִין דְּחָשְׁבִין דְּקוּדְשָׁא בְּרִיךְ הוּא לָא יְדַע הִרְהוּרִין וּמַחְשָׁבִין דִּילְהוֹן. וּבְגִין כָּךְ אִית לְאוֹדָעָא שְׁטוּתָא דִלְהוֹן. דְּזִמְנָא חָדָא אֲתָא פִּילוֹסוֹפָא חָדָא דְּאוּמוֹת הָעוֹלָם לְגַבָּאי, אָמַר לִי אַתּוּן אָמְרִין דֶּאֱלָהֲכוֹן שַׁלִּיט בְּכָל רוּמֵי שְׁמַיָא. כֻּלְהוּן חַיָּילִין וּמַשִּׁרְיָין לָא אִדַּבְּקָן וְלָא יָדְעֵי אֲתַר דִּילֵיהּ. הַאי קְרָא לָא אַסְגֵּי יְקָרֵיהּ כָּל כָּךְ. דִּכְתִיב כִּי בְכָל חַכְמֵי הַגּוֹיִם וּבְכָל מַלְכוּתָם מֵאֵין כָּמוֹךָ. מַאי שִׁיקּוּלָא דָא לִבְנֵי נָשָׁא דִּי לֵית לוֹן קִיּוּמָא."],[[0,"","קנב) \u0003והאי קרא איהו\u0004 וכו': ומקרא זה הוא תרגום חוץ מהמלה אלה, שבסוף המקרא. אם תאמר, שהוא משום שהמלאכים הקדושים אינם מקשיבים לתרגום, דהיינו ללשון ארמי, ואינם מכירים אותו. א\"כ להיפך, היה צריך לומר דבר זה בלשון הקדש, בשביל שישמעו מלאכים הקדושים, ויהיו מקשיבים, כדי להודות על זה. ומשיב, אלא ודאי, משום זה כתוב תרגום, בשביל שהמלאכים הקדושים אינם מקשיבים לו, ולא יקנאו את האדם להרע לו. כי במקרא הזה גם המלאכים הקדושים בכלל, כי גם הם נקראים אלהים, והם בכלל אלהים, והם לא עשו השמים והארץ."],[0,"","ביאור הדברים, כי יש להבין זאת, הרי לשון התרגום קרובה ללשון הקודש, ומ\"מ אין המלאכים נזקקים לה ואינם יודעים אותה, ולשאר לשונות אומות העולם המה נזקקים ויודעים. והענין הוא, כי לשון התרגום ה\"ס אחורים דלשון הקודש, דהיינו בחי' ו\"ק של לשון הקודש, כי ו\"ק נקראים אחורים ותרדמה, בלי מוחין שהם ג\"ר. וע\"כ התרגום הוא באמת קרוב מאד ללשון הקודש, אלא שיש כאן ענין אחר שבסבתו אין המלאכים נזקקים לה. והוא, כי סוד לשון הקודש הוא הלשון המכריעה באמצע דהיינו לשון המאזנים המכריעה את כף הזכויות על החובות ומחזיר הכל לקדושה. וע\"כ נקראת לשון הקדש."],[0,"","וסוד המאזנים תבין עם מ\"ש לעיל (אות ט\"ז). \u0003שמיא וחיליהון במ\"ה אתבריאו\u0004 וכו', \u0003ובראשית ברא אלהים, דא אלהים עלאה, דהא מ\"ה לא הוי הכי ולא אתבני. אלא בשעתא דאתמשכן אתוון אלין אל\"ה מלעילא לתתא, ואמא אוזיפת לברתא מאנהא\u0004 וכו' \u0003אלה אזכרה אדכרנא בפומאי, ושפיכנא דמעאי ברעות נפשי, בגין לאמשכא אתוון אלין\u0004 אל\"ה, \u0003וכדין אדדם מעילא עד בית אלהים, למהוי אלהים\u0004 וכו', עש\"ה בפירוש הסולם."],[0,"","הרי אשר בשמים וארץ שנבראו ב\u0003מ\"ה\u0004, אין שמא ד\u0003אלהים\u0004 מתגלה בהם, זולת בהמשכת אתוון \u0003אל\"ה\u0004 מאמא עלאה ע\"י מ\"ן ומע\"ט, כמ\"ש \u0003אל\"ה אזכרה אדכרנא בפומאי ושפיכנא דמעאי\u0004 וכו', וז\"ס שהמוחין דג\"ר הנקראים אלקים אינם בקביעות בשמים ובארץ שהם זו\"ן. כי בעת שמעלים מ\"ן מלתתא נעשה \u0003מ\"ה\u0004 ל\u0003מ\"י\u0004, ואתוון \u0003אל\"ה\u0004 מתחברות ב\u0003מ\"י\u0004, ואתעביד שמא אלהים, שהם המוחין בשמים וארץ. ואם התחתונים מקלקלים מעשיהם מסתלקים המוחין מזו\"ן, ונשארים בכתר וחכמה דכלים וברוח נפש דאורות, הנק' \u0003מ\"י\u0004 או \u0003מ\"ה\u0004, ואתוון \u0003אל\"ה\u0004 נופלות לקליפות. כי \u0003מ\"י\u0004 ה\"ס גלגלתא ועינים, ו\u0003אל\"ה\u0004 ה\"ס אח\"פ (כמ\"ש לעיל עש\"ה)."],[0,"","הרי שכל התיקון תלוי בחיבורא דאתוון \u0003אל\"ה\u0004 ב\u0003מ\"י\u0004 ע\"י מ\"ן, וע\"כ נקרא תקון זה לשון הקודש, שה\"ס לשון המאזנים המכריעה באמצע, שעל ידו נמשכים המוחין הנקראים קודש. כי ממשיך שמא קדישא דאלהים לזו\"ן, ומכריע אתוון אל\"ה לכף זכות דקדושה. ונק' מאזנים מלשון אזן, כי אורות אח\"פ נקראים על שם בחינה עליונה שבהם שהיא אזן."],[0,"","ולעומתו יש לשון \u0003תרגום\u0004, כי בעת שאין התחתונים מעלים מ\"ן בטהרה, נבחן שהם רוצים להאחז רק באתוון \u0003אל\"ה\u0004 לבדן, ולא לחברן בשם \u0003מ\"י\u0004 שהוא הבינה, ואז נגלין האחורים דזו\"ן שה\"ס \u0003מ\"ה\u0004 כנ\"ל, וחוזרים שמים וארץ שהם זו\"ן לבחינת ו\"ק. והוא לשון תרגום, ובזה תבין אשר \u0003תרדמ\"ה\u0004 בגי' \u0003תרגום\u0004, והוא אותיות \u0003תרד מ\"ה\u0004, כי ע\"י לשון זה, שאינה בטהרה על דרך \u0003אדכרנא בפומאי\u0004 וכו', הנה אז מתגלים האחורים שה\"ס \u0003מ\"ה\u0004, וז\"ס \u0003תרד מ\"ה\u0004. ונמצא יורדים המאזנים ובאים לכף חובה."],[0,"","וכ\"ז הוא בנוגע לזו\"ן שהם שמים וארץ ד\u0003במ\"ה אתבריאו\u0004. כי הם יצאו מבחי' הזווג דיסודות הנקרא \u0003מ\"ה\u0004 כנ\"ל. אבל המלאכים הקדושים, הם יצאו מזווג דנשיקין דאו\"א, ואין בהם מבחינת \u0003מ\"ה\u0004 ולא כלום, אלא רק בחינת \u0003מ\"י\u0004 לבדה, שהיא עלמא עלאה בינה. אשר מצד אחד הם נמצאים משום זה תמיד רק בו\"ק בלא ג\"ר, אמנם מצד הב' גם ו\"ק שלהם הם אור חסדים דבינה עלאה \u0003מ\"י\u0004, החשובים כג\"ר ממש, ואינם צריכים לחכמה, כמו אמא עלאה, וע\"כ הם קדושים כי ג\"ר נקראות קודש כנודע."],[0,"","ולפיכך, אין המלאכים מתפעלים כלל מלשון התרגום המגלה בחינת \u0003מ\"ה\u0004 בזו\"ן ומחזירתם בו\"ק, מב' טעמים: א) שאפי' בעת שיש להם לזו\"ן ג\"ר מלשון הקודש, אינם מקבלים ממנו הג\"ר בהיותם חפצים רק באור חסדים כמו אמא עלאה. ב) כי גילוי האחורים ד\u0003מ\"ה\u0004 אינו נוגע להם, כי אין בהם מבחינת מ\"ה ולא כלום."],[0,"","וז\"ס \u0003דמלאכין קדישין לא נזקקין לתרגום ולא אשתמודען ביה\u0004, אינם נזקקים, משום שאינם מפסידים כלום מחמתו, ואינם מרויחים מהסתלקותו, כי הם רק בבחי' ו\"ק בלאו הכי. \u0003ולא אשתמודען ביה\u0004, כי אין בהם מבחינת מ\"ה הזה ולא כלום. (ועי\"ז תבין מ\"ש בזה להלן בזהר לך לך מן אות רפ\"ט עד אות רצ\"ה)."],[0,"ולא יקנאון בבר נש לאבאשא ליה","וכו' כי עיקר הפסוק הזה הוא מקלל אלהים אחרים המפריעים לגילוי מוחין דג\"ר מחכמה, שע\"כ הם צריכים להאבד מארעא ומתחות שמיא אל\"ה. ולפי שגם המלאכים אין להם בחינת ג\"ר דחכמה, אלא ג\"ר דחסדים לבד, הרי ירגישו מחמת זה בזיון לדרגתם, ויקנאו אותנו על היותינו מחשיבים את עצמנו כל כך."],[0,"","וז\"ש \u0003דהא אינון אלהים אקרון, ובכללא דאלקים הוו, ואינון לא עברו שמיא וארקא\u0004 כי נק' אלהים בהיותם נמשכים מאמא הנקראת אלהים, וע\"כ המה \u0003בכללא דאלהים. ואינון לא עבדו שמיא וארקא\u0004, כי גם הם אינם יכולים לקיים שמים וארץ בג\"ר דחכמה, ואין קיום לשמים וארץ לישובא דבני אדם בזרע וקציר רק על ידי המוחין דג\"ר דחכמה, הרי שגם המה \u0003לא עבדו שמיא וארקא\u0004."],[1,"","קנג) \u0003וארקא, וארעא מבעי\u0004 וכו' שואל, הכתוב אומר וארקא, וארעא היה צריך לומר. ומשיב, משום שארקא הוא אחת משבע הארצות שלמטה. ובמקום זה יש בני בניו של קין, כי לאחר שנגרש מעל פני הארץ, ירד שמה ועשה תולדות, ודעתו נתבלבלה שם, שלא ידע מאומה. והיא ארץ מכופלת, שנכפלה מחשך ואור. \u0003אשתבש\u0004 פירושו מבולבל, כי על שריגים מתרגם שבשין (בראשית מ' י\"ב) ובשביל ששריגי הגפן מבולבלים ומסוכסכים זה בזה ע\"כ הושאל ללשון בלבול וסכסוך."],[1,"","פירוש. ז\"ת נכללות זו מזו, ויש בכל אחת ז\"ס חג\"ת נהי\"מ, ונמצאות גם במלכות. ז\"ס, וכן בארץ התחתונה יש ז' ארצות, שהן: \u0003ארץ, אדמה, ארקא, גיא, נשיה, ציה, תבל\u0004. והארץ שלנו היא \u0003תבל\u0004, שהיא העליונה מז' הארצות. ו\u0003ארקא\u0004 היא הג' מז' הארצות."],[1,"","והנה הנשמות דקין והבל נמשכו מהשם \u0003אלהים\u0004, אלא מסבת הזוהמא דאטיל נחש בחוה, יצאה תחילה נשמת קין מאתוון ד\u0003אל\"ה\u0004, ואחר כך יצא הבל מאתוון \u0003מ\"י\u0004. והיו צריכים להתכלל זה בזה ברחימותא, ואז היה שורה השם \u0003אלהים\u0004 על שניהם יחד, כמו דאשתתף \u0003מ\"י\u0004 ב\u0003אל\"ה\u0004 תדיר בסוד השם \u0003אלהים\u0004 כנ\"ל. אמנם כח הזוהמא דחויא שיצא עם נשמת קין, גרם לו לקטרג על אחיו הבל שה\"ס \u0003מ\"י\u0004 דאלהים, עד ויקם עליו ויהרגהו, כי גרם להסתלקות אתוון \u0003מ\"י\u0004 מן אלה, שז\"ס הריגת הבל. ו\u0003אל\"ה\u0004, שהוא בחינת עצמו נפל לקליפות."],[1,"","וז\"ש \u0003דאתתרך מעל אפי ארעא\u0004, כי נפל מארץ דקדושה, \u0003נחית לתמן\u0004 לארקא שהיא מקום הקליפות. \u0003ועביד תולדות ואשתבש תמן דלא ידע כלום\u0004, כי עביד תולדות בשליטת הקליפות, וע\"כ \u0003אשתבש\u0004 לשון הקדש בפיו אל לשון תרגום, \u0003דלא ידע כלום\u0004, כי אבד בחינת הדעת, כי הקליפות מחוסרי דעת. כי אין להן אלא מוחין דחו\"ב בלי דעת."],[1,"","וענין הריגתו את הבל, הוא כמ\"ש (לעיל אות קנ\"ב), שרק בכח מ\"ן בטהרה ממשיכים \u0003מ\"י\u0004 אל זו\"ן, ואח\"כ ממשיכים אתוון \u0003אל\"ה\u0004 ואשתלים שמא דאלהים גם בזו\"ן כמו באו\"א. ואז גם הנוקבא מסתימת במאנין דדכורא כמו אמא. בסוד נפקת \u0003ה'\u0004 ועאלת י\u0003'\u0004, (כנ\"ל אות י\"ז)."],[1,"","ואין הפירוש כי ה\u0003ה'\u0004 של \u0003מ\"ה\u0004 דנוקבא מסתלקת לגמרי, אלא שה\u0003ה'\u0004 נכנסה בפנימיות הנוקבא בטמירו, וה\u0003י'\u0004 ד\u0003מ\"י\u0004 נתגלתה כלפי חוץ. ובאופן זה שורה שמא קדישא דאלהים גם בזו\"ן שהם בחינת שמים וארץ. אמנם קין העלה מ\"ן שלא בטהרה, ורצה להגביר אותיות \u0003אל\"ה\u0004 של בחינת עצמו להנות עצמו, וה\"ס \u0003ויקם קין על הבל אחיו\u0004, כי הקים עצמו למעלה בשליטה על ה\u0003מ\"י\u0004 שהוא הבל אחיו, ואז נתגלו תיכף האחורים של הנוקבא, שהיא ה\u0003ה'\u0004 ד\u0003מ\"ה\u0004 שהיתה בגניזו, והשם \u0003מ\"י\u0004 נסתלק מהנוקבא, ונמצא משום זה שגם נשמת הבל שהיתה נמשכת מה\u0003מ\"י\u0004 של הנוקבא, שגם היא נסתלקה למעלה, וע\"כ \u0003ויהרגהו\u0004."],[1,"","וז\"ס שאומר הזוהר (בראשית ב' אות שמ\"א), בשעתא דקטיל קין להבל וכו' והוה נשיך ליה בשיניה כחויא ע\"ש. והיינו כנ\"ל, כי הזוהמא דנחש היתה בו, שמשום זה היה רוצה להגביר אתוון ד\u0003אל\"ה\u0004 ולבטל את ה\u0003מ\"י\u0004 ולהכניעו תחתיו, וע\"כ גילה האחורים שהם \u0003מ\"ה\u0004 בנוקבא ונסתלק ה\u0003מ\"י\u0004 ממנה וע\"כ פרחה נשמת הבל הנמשכת ממנה, \u0003ויהרגהו\u0004. וקין עצמו שהוא \u0003אל\"ה\u0004 נפל לרשות הקליפות, שהם \u0003ארקא\u0004. הנקראת בכתוב \u0003ארץ נוד\u0004, כמ\"ש וישב בארץ נוד (בראשית ד')."],[1,"","וז\"ש, \u0003ארעא כפילא דאתכפל מחשוכא ונהורא. ואית תמן תרין ממנן\u0004: כי אור וחושך משמשים שם בערבוביא בלי תחומין ביניהם, מטעם שיש שם שני ממונים השולטים בשוה על הארץ הזו, האחד ממונה על החושך והוא משרה שם את החושך, והשני ממונה על האור והוא משרה שם האור."],[2,"","קנד) \u0003ואית תמן תרין\u0004 וכו': ויש שם שני ממונים שליטים, השולטים, זה בחשך וזה באור, והיו עוינים זה את זה. ובשעה שירד שמה קין, נתחברו זה בזה, ונשלמו יחד. וראו הכל שהם תולדות קין. ועל כן, שני ראשים להם כשני נחשים, חוץ מבעת שאותו הממונה שעל האור שולט, הוא מנצח על שלו, דהיינו על האור, ומנצח על האחר. דהיינו על הממונה שעל החשך. ולפיכך, נכללו אותם שבחשך באותם שבאור, והיו אחד."],[2,"","ביאור הדברים, ובכדי להבין זה, צריכים להעמיק יותר בענין קין והבל. וכבר נתבאר (לעיל אות י\"ד) ביציאת שמא קדישא אלהים, אשר תחילה עולות אתוון \u0003אל\"ה\u0004 ומתחברות ב\u0003מ\"י\u0004 בבחינת סתים בשמא, מטעם היותן מחוסרי חסדים, והקדש שהוא חכמה, אינו יכול להתלבש בהם בלי לבוש של חסדים, והם ע\"כ סתומין בשמא דאלהים. ואח\"כ נעשה זווג ב' ב\u0003מ\"י\u0004 להמשיך חסדים, אשר עתה מתלבשת החכמה בחסדים ואשתלים שמא דאלהים. וכמ\"ש שם שה\"ס \u0003מ\"י ברא אל\"ה\u0004, כי ברא נהורא לנהוריה דהיינו לבוש יקר דחסדים ואתלבש בהו ואתחברו אל\"ה במ\"י ואשתלים אלהים."],[2,"","והפירוש הוא כי במ\"י שהוא בינה, יש ג\"ר הנקראות או\"א עלאין והן נתקנו בסוד אוירא דכיא, בסוד חפץ חסד הוא, ואינן מקבלות חכמה. ורק ז\"ת ד\u0003מ\"י\u0004 הנקראות ישסו\"ת הן המקבלות חכמה. ולכן בתחילת עלית אתוון דאלה ל\u0003מ\"י\u0004 הן עולות לז\"ת ד\u0003מ\"י\u0004 המקבלות חכמה, ואז הן סתומות בשמא דאלהים כנ\"ל. אלא אח\"ז נעשה זווג הב' דג\"ר ד\u0003מ\"י\u0004 שהן אוירא דכיא, הן משפיעות הלבוש היקר דנהיר ל\u0003אל\"ה\u0004, ואז נשלמו בשמא קדישא \u0003אלהים\u0004."],[2,"","ונשמת קין היתה מבחינת \u0003אל\"ה\u0004 בעוד שהן סתים בשמא, וע\"כ הקדושה שהיא החכמה היתה סתומה עליו מטעם חסרון לבוש דחסדים. והנה לא די שלא העלה מ\"ן להמשיך ה\u0003מ\"י\u0004 דחסדים, אלא עוד שרצה להמשיך חכמה מבחינת או\"א עלאין, ובזה הרג את הבל, כי גילה האחורים דנוקבא דז\"א כנ\"ל. והוא עצמו הפיל נשמתו לקליפות שהן \u0003אל\"ה\u0004. שמקום קליפות אלו הוא ב\u0003ארקא\u0004."],[2,"","וענין ב' ממונים אשר שם הם מבחי' ה\u0003אל\"ה\u0004 דקליפות, כי \u0003זה לעומת זה עשה אלהים\u0004. כי נתבאר לעיל שבנוקבא יש אחורים ד\u0003מ\"ה\u0004 בגניזו, ובחינת \u0003מ\"י\u0004 באתגליא, ואז יכולה להאיר אל הנשמות בשמא קדישא דאלהים, בתכלית השלמות. כי אז החכמה דאתוון \u0003אל\"ה\u0004 שקבלו מז\"ת ד\u0003מ\"י\u0004, מתלבשות בחסדים דג\"ר ד\u0003מ\"י\u0004, ונגלה שמא קדישא."],[2,"","אמנם בסטרא אחרא, שכל יניקתן הוא מאחורים דקדושה, שהוא \u0003מ\"ה\u0004, נמצאות בהן אתוון \u0003אל\"ה\u0004 בב' ליקויים: א) שהן מחוסרי חסדים לגמרי. ב) כי אפילו שהחכמה שב\u0003אל\"ה\u0004 אינה יכולה להתלבש שם מחמת חסרון החסדים ד\u0003מ\"י\u0004, וע\"כ הן שרויות בחושך ולא באור."],[2,"","והוא הזכר ד\u0003אל\"ה\u0004 דקליפה, כי הכלים שלו הם כלים דחכמה שהם \u0003אל\"ה\u0004, אבל ריקנים מחכמה מטעם חוסר חסדים ד\u0003מ\"י\u0004, באופן שכולו חושך, הן מחכמה והן מחסדים. אבל מעלתו גדולה בכח הכלים שלו, שהם היו ראויים לחכמה אם היה אפשר לו לקבל לבוש חסדים. והנוקבא של \u0003אל\"ה\u0004 דקליפה, היא מאחורים של ה\u0003מ\"ה\u0004 דנוקבא דקדושה, שהיא כלי של חסדים, אבל בקליפה היא פגומה מאד, שהיא שורש דפרודא המזייפת בשמא דמלכא, ויש לה הרבה שמות הטומאה לפי הקלקולים שלה, אמנם יש לה נהורא דקיק מכח הכלים שלה שהם מאחורים ד\u0003מ\"ה\u0004, שהם בשורשם כלים דחסדים."],[2,"","ותדע, שאלו הזכר והנקבה ד\u0003אל\"ה\u0004 דקליפה, הם ב' הממונים שבארץ ארקא: הזכר הוא הממונה על החושך והנקבה היא הממונה על האור אשר שם. וע\"כ הם מקטרגים זה לזה להיותם הפוכים זה מזה, כי הזכר, להיות בו הכלים הריקים דחכמה מאתוון ד\u0003אל\"ה\u0004, הוא שונא לכח הזיוף והפרודא שיש בכלים דנוקבא שלו, והוא בוחר יותר בחושך שבו. והנקבה שיש לה נהירו דקיק מחסדים, אינה חושקת כלל באור חכמה, ומכ\"ש לחושך דזכר, וע\"כ מקטרגת בו ובורחת ממנו."],[2,"","וז\"ש \u0003תרין ממנן שליטין די שלטין דא בחשוכא ודא בנהורא ותמן קטרוגא דא בדא\u0004 כי הזכר שולט בחושך, והנוקבא באור, והם מקטרגין ושונאים זה את זה. ומתוך שהם נפרדים זה מזה, אינם יכולים להתפשט כלל ואין בהם כח להזיק."],[2,"","אלא אחר שחטא קין והפיל אתוון \u0003אל\"ה\u0004 דקדושה שבנשמתו אל הקליפות ההן שב\u0003ארקא\u0004, נתלבשו אז אתוון \u0003אל\"ה\u0004 שלו, הסתומות ג\"כ מחסדים. בתוך הנהורא דנוקבא ד\u0003אל\"ה\u0004 דקליפה, שבזה החיה ניצוצין קטנים שנשארו בכלים ד\u0003אל\"ה\u0004 דקין מבחינת החכמה, כי האור דקליפה בישא החיה אותם בדוגמת אור חסדים דקדושה, שמתוך כך גם הזכר ד\u0003אל\"ה\u0004 דקליפה נזדווג עם הנוקבא הזו שהלבישה \u0003אל\"ה\u0004 דקין, כי גם לו אותם הכלים דקין. וע\"י זווג זה הוליד קין תולדות, שהם מניצוצי חכמה שנשארו באתוון \u0003אל\"ה\u0004 שלו המעורבים בכלים ד\u0003אל\"ה\u0004 דזכר דקליפה, שהן נתלבשו באור של הנוקבא בישא דקליפה."],[2,"","וזה אמרו \u0003ושעתא דנחית לתמן קין אשתתפו דא בדא ואשתלימו כחדא\u0004, כי ניצוצי חכמה שנשארו ב\u0003אל\"ה\u0004 דקין נתלבשו באור הנקבה דקליפה, שעי\"ז חשק בה גם הזכר דקליפה כדי לקבל ולהנות מניצוצי החכמה ד\u0003אל\"ה\u0004 דקין, ונזדווגו זה בזה, דהיינו שנשתתפו \u0003כחדא\u0004, ונשלמו זה מזה \u0003כחדא\u0004, וז\"ש \u0003וכלא חזי דאינון תולדות דקין\u0004, שע\"י הזווג הזה יצאו תולדות, שהם בחינת התלבשות ניצוצין ד\u0003אל\"ה\u0004 דקין בנהורא דקליפה, ונמצאו שנגלו עי\"ז ניצוצי חכמה דנשמת קין וכולם ראו שהם \u0003תולדות דקין\u0004 שנולדו ע\"י הזווג הרע הזה."],[2,"ועל דא אינון בתרין ראשין כתרין חיוון",": כי מתוך שיצאו מחיבור הזכר והנקבה ד\u0003אל\"ה\u0004 דקליפה, שהם משורשם הפוכים זה מזה כנ\"ל, ע\"כ התולדות שהוליד קין בעזרתו, יש להם אותם ב' הראשים של אלו ב' הקליפות, שהאחד נוטה לחושך דכלים דחכמה, והשני נוטה לנהורא שבכלים דטומאה של הנוקבא דקליפה."],[2,"","ואמרו, \u0003כתרין חיוון\u0004, הם הלעומת דב' חיות שבמרכבה שהם \u0003שור ונשר\u0004, כמ\"ש להלן."],[2,"","והנה מה שאומר שיש להם ב' ראשים, היינו רק בעת שליטת הזכר, שהיא שליטת החושך, כי ע\"י התלבשותו בנהורא דנוקבא כדי להנות מניצוצי חכמה דקין כנ\"ל, נמצא שהוא מקיים גם שליטת הנוקבא שלו בעל כרחו, כי צריך לנהורא דילה, וע\"כ יש אז להתולדות ב' ראשים, זה מושך לכאן וזה מושך לכאן."],[2,"","מה שאין כן הנוקבא דקליפה, שהיא אינה צריכה כלל לזכר שלה, שהרי אינו נותן לה מאומה, כי כולו חושך כנ\"ל. ולפיכך בעת שהנוקבא שולטת ורוצה לנצח בטומאה שלה הרי יש לה שליטה שלמה, ואינה משאירה מבחינת הזכר כלום, ואז גם התולדות דקין ב' הראשים שלהם חוזרים להיות אחד."],[2,"","וזהו אמרו \u0003בר דכד ההוא נהורא שליט נצח דיליה ונצח על אחרא\u0004, היינו בעת שהנוקבא דקליפות שולטת, שהיא בעלת האור, ומתחזקת לנצח על הזכר, שהוא הממונה אחרא, ו\u0003נצח דליה\u0004, ונצח הכח שלו, וגם \u0003נצח על אחרא\u0004, ונצח ג\"כ על הממונה האחר, שהוא הזכר. כי היא מנצחת את הזכר תחת שליטתה לגמרי, \u0003ועל דא אתכלילו די בחשוכא בנהורא והוו חד\u0004, ומשום זה נכללה שליטת הזכר שהוא החושך תוך שליטת הנקבה שהיא האור, ונעשו ב' הראשים אחד."],[3,"","קנה) \u0003אנון תרין ממנן\u0004 וכו': אלו ב' ממונים, נקראים, עפרירא וקסטימון, והצורה שלהם, הוא כצורותיהם של מלאכים הקדושים, בשש כנפים. אחד הוא בצורת שור, ואחד בצורת נשר. וכשמתחברים נעשו לצורת אדם."],[3,"","פירוש. הזכר נקרא \u0003קסטימון\u0004, והוא נגזר מלשון \u0003קוסטי\u0004 שפירושו חורבן. ונקרא כן להיותו חושך ואינו ראוי לישובא דבני אדם. והנקבה נקראת \u0003עפרירא\u0004, והוא מלשון \u0003עפר\u0004, שפירושו שאינו ראוי לזריעה. ונקראת כן, להורות שהגם שיש בה אור כנ\"ל, עכ\"ז אינו מספיק לזריעה וקצירה ליזון בו בני אדם."],[3,"","ואומר שצורתם הוא כצורת המלאכים בעלי שש כנפים. והוא להיותם הלעומת של המלאכים העליונים שיש להם שש כנפים כנגד ה\u0003ו'\u0004 ד\u0003הוי\"ה\u0004. ולאפוקי מחיות הקודש, שאין להן אלא ד' כנפים, כנגד אותיות דשם \u0003אדנ\"י\u0004. ובא להורות על הגובה של הקליפות, הללו, שהן הלעומת דמלאכי קודש העליונים."],[3,"","והנה הזכר \u0003קסטימון, דיוקנא כתורא\u0004 שהוא לבושא קדמאה דאתלבש בה ס\"א. כמ\"ש בזוהר (פר' תשא אות נ\"ז), שאומר שם שמשמרי היין \u0003נפק חד ערעורא מקטרגא, מזיקא קדמאה, ואיהו ברזא דיוקנא דאדם, כד קריב לגו קדשא. כיון דאתעבר מתמן, ובעי לנחתא לתתא, בעי לאתלבשא בלבושא, לנזקא עלמא, ונחית היא ורתיכוי. ולבושא קדמאה דקא נקיט, תבנית שור דיוקנא דשור. וקדמאה לנזקין מאינון ארבע, שור איהו\u0004."],[3,"","פירוש, כי המוחין העליונים נקראים יין המשמח אלהים ואנשים, ויש בסופן בחינת סיגים, המכונים \u0003שמרי היין\u0004, ומפסולת זו יוצא המזיק הראשון לעולם, שבעודו דבוק בקדושה דהיינו בשמרים, יש לו \u0003דיוקנא דאדם\u0004, אלא כשהוא יורד להזיק לבני אדם הוא מתלבש ב\u0003דיוקנא דשור\u0004. וע\"כ השור הוא הראשון מארבעה אבות נזיקין."],[3,"","וזה שאומר כאן ש\u0003קסטימון\u0004 זה הוא בחינת המזיק שיש לו \u0003דיוקנא דשור\u0004, להורות שהוא שורש כל המזיקין הנקראים \u0003שור\u0004 דקליפה, והוא בחינת הסיגים של המוחין העליונים דשמא קדישא אלהים, דהיינו כנ\"ל, שהוא בחינת \u0003אל\"ה\u0004 דקליפה שהוא כנגד אל\"ה של שמא דאלהים, להיותו סיגים ושמרים העומדים מתחתיהם, וע\"כ בהיותו עוד מחובר בקדושה היה לו \u0003דיוקנא דאדם\u0004, כי מוחין אלו דאלהים ה\"ס \u0003צל\"ם\u0004 אדם, שעליו אומר הכתוב ב\u0003צל\"ם אלהי\"ם\u0004 עשה את האדם, אמנם בהפרדו מהקדושה וירד למקומו ל\u0003ארקא\u0004 הנ\"ל, נתלבש בלבושא דשור."],[3,"","והנקבה שלו שב\u0003ארקא\u0004, יש לה \u0003דיוקנא דנשר\u0004, והוא על שם תפקידה לנשר נשמות דבני אדם הנופלות תחת שליטתה, כי \u0003נשר\u0004 הוא מלשון נשירת עלין מהאילן, כי מתפקידה לשוטט בעולם ולהביא בני אדם למקרה לילה, דהיינו לפגום ברית קדש שבסבת הפגם הזה נושרות, הנשמות מבני אדם. (כנ\"ל אות קל\"א) ואומר \u0003וכד מתחברן אתעבידו דיוקנא דאדם\u0004 כלומר, אם חוזרים ומתחברים בקדושה להיות שמה בבחינת שמרים תחת היין, הם חוזרים להיות ב\u0003דיוקנא דאדם\u0004, כמו שהיו מטרם שירדו ל\u0003ארקא\u0004, ונעשו למזיקים, (כמו שאומר בזוהר תשא הנ\"ל. ועיין בזוהר נשא אות של\"ו). 1"],[4,"","קנו) \u0003כד אינון בחשוכא\u0004 וכו': כשהם בחשך הם מתהפכים לצורת נחש בשני ראשים. והולכים כנחש. ומעופפים בתוך התהום, ורוחצים בים הגדול. כשמגיעים לשלשלת של עזא ועזאל, הם מרגיזים אותם, ומעוררים אותם, והם מדלגים תוך הרי חשך, וחושבים שהקב\"ה רוצה לקרוא אותם לדין."],[4,"","פירוש. סובב על הדברים דלעיל שאומר \u0003דכד ההוא נהורא שליט ונצח דיליה ונצח על אחרא, ועל דא אתכלילו די בחשוכא, בנהורא, והוו חד\u0004, שבעת שליטת הנוקבא שהיא \u0003נהורא\u0004, חוזרים \u0003השני ראשין\u0004 להיות ראש אחד כנ\"ל. ואומר כאן אבל \u0003כד אינון בחשוכא\u0004, דהיינו בעת שליטת הזכר הנקרא \u0003קמטימון, מתהפכין לדיוקנא דנחש בתרין ראשין\u0004, כי הזכר אינו יכול לבטל שליטת הנוקבא, בהיותו צריך להתלבש באור שלה, (כמ\"ש לעיל), וע\"כ הם כנחש בב' ראשין. \u0003ואזלין כחויא\u0004 כלומר, שהולכין להזיק בדרך הנחש, דהיינו באותו דרך שהנחש פיתה את חוה לאכול מעצה\"ד."],[4,"","והנה מכח הראש של הנוקבא דקליפה, נמצאים \u0003טאסין גו תהומא\u0004, ששם שורש הקליפות הנקרא \u0003תהום\u0004, שהוא ירידה שאין למטה הימנה, בסוה\"כ יעלו שמים ירדו תהומות (תהלים ק\"ז). ומכח הראש של הזכר דקליפה נמצאים \u0003אסתחיין בימא רבא\u0004, שהוא החכמה דקליפה, כי \u0003ים\u0004 הוא שם החכמה. ותדע, שמשום זה נקראת \u0003ארקא\u0004 בשם ארץ נוד, להיותם מתנדנדים תמיד מחמת ב' הראשים של הממונים הללו: פעם עולים בים הגדול ופעם יורדים תהומות."],[4,"","והנה ביאור מלאכים אלו \u0003עזא ועזאל\u0004 הוא ענין ארוך מאד, וכבר ביארתי קצתו בספרי בית שער לכונות (דף ס\"ג ד\"ה זו\"ן ובהמשך שם). וכאן אתאמץ לבאר לפי הצורך. ותדע, כי \u0003עזא ועזאל\u0004 הם מהמלאכים הגבוהים ביותר, כי תמצא שגם אחר נפילתם מהשמים לעוה\"ז, להרי החושך, ונקשרו בשלשלאות של ברזל, היה בלעם משיג על ידם כל מדרגת נבואתו, שעליהם נאמר אשר מחזה שדי יחזה, דהיינו בכח השגתו לאלו המלאכים. הנקרא נופל וגלוי עינים. כי \u0003עזא\u0004 נקרא נופל ע\"ש נפילתו משמים לארץ. \u0003ועזאל\u0004 נקרא וגלוי עינים, בערך \u0003עזא\u0004 דקב\"ה זריק חושך באנפוהי, (כמ\"ש כל זה בזוהר בלק אות תט\"ז)."],[4,"","ושמא תאמר שמדרגת נבואתו של בלעם היא דבר קטן, הנה אמרו חז\"ל ולא קם נביא עוד בישראל כמשה, בישראל הוא דלא קם אבל באומות העולם קם ומנו בלעם (במדבר רבה פרק י\"ד)."],[4,"","והנה סבת נפילתם משמים לארץ, ביארו בזוהר בכמה מקומות שהוא מכח שקטרגו על האדם בעת הבריאה. אמנם יש להבין הלא הרבה מלאכים קטרגו אז כמ\"ש במדרשות חז\"ל, ולמה הפיל הקב\"ה רק \u0003לעזא ועזאל\u0004 בלבד."],[4,"","ואמנם בזוהר בלק (מן אות תט\"ז עד אות תכ\"ה) נמצא שם ביאור מלא על ענין זה. וז\"ל שם. \u0003בשעתא דסליק ברעותיה דקב\"ה למברי אנשא, קרא לכתות כתות דמלאכי עלאה ואותיב לון קמיה, אמר לון מעינא למברי אדם\u0004. וכו'. \u0003אמרו קמיה מה אנוש כי תזכרנו\u0004 (תהלים ח'), \u0003מה טיבו דבר נש דא. אמר לון בר נש דיהא בצלמא דידן, דיהא חכמתא דיליה, עלאה מחכמתכון\u0004. פירוש הדברים, כי בעת שעלה ברצון הקב\"ה לברוא האדם, קרא כתות כתות מלאכי עליון, והושיבם לפניו ואמר להם רוצה אני לברוא אדם, אמרו המלאכים לפניו, \u0003מה אנוש כי תזכרנו\u0004, מה טיבו של האדם הזה שאתה רוצה לבוראו. אמר להם, האדם יהיה בצלמנו, ותהיה חכמתו למעלה מחכמתכם."],[4,"","כי נשמת האדם היא כלולה מכלהו מלאכים ומדרגות העליונים, כמו שגופו כולל כל בריות העולם הזה, ולפיכך בעת בריאת נשמתו של האדם קרא לכלהו \u0003מלאכי עלאה\u0004 שיכללו את עצמם בנשמת האדם. שז\"ס נעשה אדם בצלמנו כדמותנו (בראשית א'). ששיתף כל המלאכים שיכללו בצל\"ם ודמות האדם. ושאלו הם, לקב\"ה מה טיבו של בר נש זה, כלומר, מה נרויח ממנו ע\"י התכללותנו בו."],[4,"","והשיב להם \u0003בר נש דיהא בצלמא דידן דיהא חכמתא דיליה עלאה מחכמתכון\u0004. שהבטיח להם, שזה האדם שיתכלל מהצלם שלנו תהיה חכמתו גדולה מחכמתכם. ונמצא שתרויחו גם אתם ההשגה גדולה ההיא שחסרה לכם עתה. והיינו כמ\"ש חז\"ל, על הפסוק, כעת יאמר ליעקב ולישראל מה פעל אל (במדבר כ\"ג), אשר לע\"ל ישאלו המלאכים מישראל מה שלא ידעו עצמם, כי מעלת ישראל תהיה אז גדולה מהמלאכים וע\"כ נשתתפו כולם ונכללו בצלמו של האדם."],[4,"","ואומר עוד שם \u0003כיון דברא אדם וחטא, ונפק בדימוס קמיה, אתו עזא ועזאל אמרון קמיה, פתחון פה אית לן גבך, הא בר נש דעבדת חטי קמך. אמר להו אלמלי תהוון שכיחי גבייהו\u0004 וכו' (\u0003יתיר הויתון חבין מיניה\u0004 וכו') \u0003מה עבד קב\"ה אפיל לון מדרגא קדישא דלהון מן שמיא\u0004 וכו', \u0003בתר דאפיל לון קב\"ה מאתר קדישא דלהון, טעו בתר נשי עלמא, ואטעו עלמא\u0004. ביאור הדברים כמו שנברא האדם וחטא, ויצא חייב לפניו, באו \u0003עזא ועזאל\u0004 אמרו לפניו פתחון פה יש לנו אצלך, הרי האדם שעשית חטא לפניך וכו' מה עשה הקב\"ה, הפילם מהמדרגה הקדושה שלהם, מן השמים וכו'. אחר שהפילם הקב\"ה מהמקום הקדוש שלהם, טעו אחר נשי העלם, והטעו בני העולם."],[4,"","כי תראה שלא כל המלאכים באו להתלונן קמי קב\"ה אחר חטאו של אדם, רק \u0003עזא ועזאל\u0004 לבדם. וזה מטעם שידעו שיעשה תשובה. אך \u0003עזא ועזאל\u0004 ידעו כי זה הפגם שהשיגו מחמת חטאו של אדם, לא יתוקן כלל מחמת תשובתו. ולא עוד אלא שמוטב היה להם שלא יעשה תשובה כל עיקר, ולפיכך רק הם שהתלוננו על חטאו של אדם, כי כלפיהם הוא מעוות שלא יוכל להתקן וחסרון שלא יוכל להמנות."],[4,"","והענין הוא, כי שבירת הכלים וחטאו של אדם הראשון הם ענין אחד, אלא שמבחינת מציאות העולמות נקרא שבירת הכלים, ומבחינת הנשמות הוא הנעשה בחטאו של אדם. ונודע ששבירת הכלים שלטה בשמונה מלכים, שהם מלך הדעת וז\"ת חג\"ת נהי\"ם, אשר בכל מלך מהם מ' בחינות, שהן ע\"ס שבכל ספירה ד' בחינות חו\"ב תו\"מ. ונמצא שמונה פעמים מ' הם ש\"כ בחינות. ונק' ש\"כ ניצוצין דאזדריקו לכל עבר בעת שבירת הכלים."],[4,"","וענין התשובה הוא שע\"י עלית מ\"ן אנו מעלים ניצוצין אלו מן הקליפות בחזרה למקומם לאצילות. כמו שהיו מטרם החטא של אדם הראשון. אמנם אין כח בידינו לברר את המלכויות שבח' המלכים האלו כי פגמם למעלה מכחנו לגמרי, וע\"כ אין אנו רשאין לברר רק רפ\"ח ניצוצין עם תשובתנו, שהם רק ט' פעמים ל\"ב, אבל ל\"ב הבחינות של המלכויות שבהם, אסור אפילו לנגוע בהם, והוא הנקרא \u0003ל\"ב האבן\u0004."],[4,"","ומכח זה נגנזו ג\"ר דאו\"א, הנקראות או\"א הפנימיים. כי אלו ל\"ב הניצוצין שייכים להם להשלמת עה\"ס שלהם, וכל עוד שהם חסרים מהם אין להם זווג. אמנם אחר שיגמר הבירור של כל רפ\"ח הניצוצין, ימצא ל\"ב האב\"ן הנ\"ל מתברר מאליו, ואינו צריך למעשה ידינו, ואז נאמר והסירותי את ל\"ב האבן מבשרכם (יחזקאל ל\"ו). ואז ישיגו או\"א הפנימיים את המוחין שלהם. שזה יהיה בגמר התיקון. אבל לפני גמר התיקון, לא יוכלו אלו אחורים דאו\"א לקבל שום תיקון ע\"י תשובתנו."],[4,"","ותדע שאלו המלאכים עזא ועזאל הם מבחינת אחורים דאו\"א הנ\"ל שנתבטלו בעת שביה\"כ, והנה קודם החטא של אדה\"ר חזרו ונתקנו במדה מרובה, ואחר חטאו של אדה\"ר חזרו לביטולם, ואין להם עוד תקנה קודם גמר התיקון. ולפיכך התלוננו עזא ועזאל קמי קב\"ה על המוחין שלהם שהפסידו מחמת חטאו של אדם, כי ראו שאין להם שום תקוה שיוכל האדם לתקן אותם ע\"י תשובתו."],[4,"","ולא עוד כי ראו שאדה\"ר ע\"י תשובתו יפיל אותם עוד יותר מדרגתם. כי כל התשובה צריכה להיות רק על רפ\"ח ניצוצין, ולא לנגוע בל\"ב האב\"ן השייכים לתיקון או\"א הפנימים, שאליהם מתיחסים המוחין של המלאכים ההם כנ\"ל. וכל ענין התשובה והעלאת מ\"ן, הוא להסיר הפסולת הזו, דהיינו הל\"ב ניצוצין, מן האוכל שהם הרפ\"ח, ונמצא שמורידים עוד יותר בחינת \u0003עזא ועזאל\u0004 בהסרת הפסולת, שהיא ל\"ב האבן, מן הקדושה לגמרי. ולפיכך קטרגו ומנעו את האדם מעשות תשובה, כי התשובה מורידתם עוד יותר. כי ל\"ב הניצוצין הללו שייכים לבנינם."],[4,"","וכיון שראה הקב\"ה שקטרוגם זה יחליש את האדם מלעשות תשובה. לפיכך אמר להם \u0003אלמלי תהוון שכיחי גבייהו יתיר הויתון חבין מיניה\u0004, אמר להם, כי אדם הראשון לא קלקל אותם כלל בחטאו, כי הגם שיש להם מעלה וקדושה בהיותם בשמים, ששם אין אחיזה לקליפות, הנה אין זה שלימות גמורה בעוד שאינם יכולים להמצא בעוה\"ז שלנו במקום הקליפות, וע\"כ אמר להם הקב\"ה, הרי לא הפסדתם כלום בחטאו של אדם, כי בלאו הכי אינכם טובים ממנו, שהרי כל מעלתכם היא רק מחמת שהמקום גורם."],[4,"","והנה דיבורו של הקב\"ה הוא מעשה, ותיכף נפלו משמים לארץ שלנו. והנה \u0003בתר דאפיל לון קב\"ה מאתר קדישא דלהון טעו בתר נשי עלמא, ואטעו עלמא\u0004 כלומר, שכיון שבאו להאי עלמא התחילו לברר מל\"ב האב\"ן הכלול בבנות האדם. שז\"ס ויראו בני האלהים את בנות האדם כי טובות הנה ויקחו להם לנשים מכל אשר בחרו (בראשית ו'), כי לא רצו להפריד הפסולת דל\"ב האבן ולבחור רק ברפ\"ח, אלא שלקחו מכל אשר בחרו, דהיינו גם את ל\"ב האבן, ואז נכשלו גם הם בנוקבא לילית הרשעה, ורצו להטעות העולם במעשיהם הרעים האלו, כי לא רצו שהאדם יחזור בתשובה, שזהו בנגוד לשורשם כנ\"ל."],[4,"מה עביד קב\"ה חמא דאטעיין עלמא, קשר לון בשלשלאי דפרזלא בטורא דחשוכא",", כי ראה הקב\"ה שאם יהיה להם כח לחזור לשמים אחר חטאם זה, יכשלו כל בני האדם אחריהם ולא יוכלו לעשות תשובה, כי שליטתם תהיה רבה מאד. וע\"כ אע\"פ ששורשם גבוה, נתן רשות לשורש הקליפות הנקרא \u0003ברזל\u0004, בסוה\"כ כל כלי ברזל לא נשמע בבית בהבנותו (מלכים ו'). וכיון שקליפה זו נדבקה בהם נקשרו בה כמו בשלשלאות של ברזל, בתוך הרי חושך, ולא יוכלו לעלות משם טרם גמר התיקון, ודי בזה כי כבר הארכתי כאן יותר מדאי ולהלן אבאר עוד."],[4,"","וזה אמרו כאן \u0003כד מטאן לשלשלאה דעזא ועזאל\u0004, כי אחר ד\u0003אסתחיין בימא רבא\u0004 שהוא חכמה דקליפות קבלו כח להתחבר עם \u0003עזא ועזאל\u0004 שבהרי חושך למילף מנייהו חכמתא, ועוררו אותם שישפיעו להם מהחכמה שלהם. \u0003מרגיזין להון ומתערי לון\u0004, ההתעוררות דבחי\"ד שהוא גדלות הקבלה, מכונה בשם כעס והתרגזות, ע\"ד שאמרו ז\"ל כל גרגרן כועס, \u0003ואינון מדלגין גו טורי חשוכן והשבי דקב\"ה בעי למתבע לון דינא\u0004 כי לא יכלו לעלות לשורשם לקבל בעדם חכמה מחמת שלשלאות הברזל שעליהם,"],[4,"","ולפיכך נבחן שהיו קופצים כלפי מעלה ונופלים חזרה, שמחמת זה העמיקו להם מקומם תוך הרי חושך, וחשבי דקב\"ה רוצה לחדש עליהם כח הדין מחמת הקפיצות שלהם לקבל משורשם, וע\"כ פסקו מלדלג עוד. ועם כל זה \u0003ואלין תרין ממנן שאטין בימא רבא\u0004, כלומר, אע\"פ שלמעשה לא יכלו להשפיע להם כלום, כי רק דלגו ונפלו כנ\"ל, עכ\"ז היה מספיק בעד ב' הממונים לקבל מהם חכמה, עד \u0003דשאטין בימא רבא\u0004 כי עתה היה להם כח לשוט שם בים החכמה דקליפה, מה שמקודם, לא היה להם כח אלא להתרחץ שם בלבד, והטעם הוא כי כל ענין הקליפות הללו הגבוהות אין בהן מעשה, וכל הפעולות שלהן נגמרו רק במחשבה ורצון בלבד, שהוא מחמת היותן הכחות דפרודא, ובטרם יספיקו לבא לכלל מעשה נמצאת הקדושה מסתלקת משם, וע\"כ לא יצויר זה לעולם שיבואו לכלל מעשה. וז\"ס כאן שהיא בחינת ע\"ז, הקב\"ה מעניש ג\"כ על המחשבה והרצון בלבד, בסוה\"כ למען תפוש את בית ישראל בלבם (יחזקאל י\"ד), שאמרו חז\"ל, שהאדם נענש על הרהור ע\"ז שבלב כמו על מעשה. ולפיכך הספיקו הקפיצות ד\u0003עזא ועזאל\u0004 לקבלת החכמה שלהם, אע\"פ שלמעשה לא נתנו להם כלום."],[5,"","קנז) \u0003ואלין תרין ממנן\u0004 וכו': ואלו שני הממונים, שוחים בים הגדול, ופורחים משם, והולכים בלילה אל נעמה אם השדים, שטעו אחריה בני אלהים הראשונים (בראשית ו'), וחושבים לקרב אליה, והיא מדלגת ששים אלף פרסאות, והיא נעשית ומתהפכת לכמה צורות לבני אדם, בשביל שיטעו אחריה בני אדם."],[5,"","פירוש. כי אחר שקבלו כח מ\u0003עזא ועזאל\u0004, יכלו גם להזדווג עם \u0003נעמה\u0004, שגם המלאכים הראשונים, \u0003עזא ועזאל\u0004 טעו אבתרה. ומגו זווגא דא, ילדה \u0003נעמה\u0004 כל הרוחין בישין ושדין דעלמא, (כמ\"ש בזוהר בראשית א' אות ק\"ב). וז\"ש \u0003דטעו אבתרהא דחלין קדמאין\u0004, שהם \u0003עזא ועזאל\u0004 הנקראים \u0003דחלין\u0004, שפירושן בני אלהים הכתוב במקרא (בראשית ו'). ויש להבין הדבר, כיון שמלאכי מעלה היו, איך באו לכלל טעות לזנות עם \u0003נעמה\u0004, וכן למה הולידה \u0003נעמה\u0004 ע\"י זה רק \u0003שדין ורוחין\u0004 ולא אנשים."],[5,"","והענין הוא בקיצור, כי ידעת שעלמא עלאה שהוא או\"א נברא ב\u0003י'\u0004, שהיא בחינת דכורא, ואין בהם מבחי\"ד ולא כלום. אבל הזו\"ן שהם עלמא תתאה, נבראו ב\u0003ה'\u0004, הכלולה גם מבחי\"ד (כנ\"ל אות מ\"ח). גם ידעת שאו\"א שה\"ס בינה עומדים תמיד בחשק אחר אור חסדים, כי כן יצאה הבינה מתחילתה בד' הבחינות דאו\"י. אבל הזו\"ן צריכים לאור חכמה דוקא, כי כך נאצל הז\"א דאו\"י בהארת חכמה בחסדים אלו. (עיין בספרי תלמוד ע\"ס דף ו' ד\"ה וטעם)."],[5,"","והנה מזווג או\"א יצאי המלאכים, הנמצאים גם בסיומא די' כמוהם, וחושקים רק אחר חסדים ולא אחר חכמה כמוהם. ונשמות בני אדם יצאו מעלמא תתאה זו\"ן, ונמצאות הנשמות בסיום ה\u0003ה'\u0004, שעליה היה הצמצום שלא לקבל חכמה מחמת הבחי\"ד הכלולה בה, וכן יש להן צורך וחשק אחר חכמה כמו הזו\"ן להיותן נמשכות מהם."],[5,"","והנה אדם הראשון בעת שנולד מהזו\"ן היו הזו\"ן מלבישין לעלמא עלאה או\"א, ונסתיימו גם הם ב\u0003י'\u0004, אלא ה\u0003ה'\u0004 היתה גנוזה באחורים שלהם. וע\"כ היתה מעלת אדה\"ר גדולה מאד. כי בהיותו בהזו\"ן בעלמא עלאה, ונסתיים ב\u0003י'\u0004, היתה מדרגתו כמלאכי מעלה הנולדים מאו\"א, ועם זה היה מקבל חכמה עלאה להיותו מבחינת זו\"ן. והיה שורה עליו שמא דאלהים. שהוא חכמה, בשלימות דעלמא עלאה, כי בבחינת ה\u0003י'\u0004 אין שם צמצום ובחי\"ד כלום. ומבחינה זו הוליד קין והבל קין מ\u0003אל\"ה\u0004, והבל מן \u0003מ\"י\u0004, כנ\"ל, ובשניהם לא היתה מגולה ה\"ת אלא ה\u0003י'\u0004 לבדה, וכיון שכן היו בהם חכמה עלאה, ועיקר נושא החכמה הוא אל\"ה, שהוא ז\"ת דבינה, דהיינו נשמת קין."],[5,"","אמנם קין התקנא בתאומה היתירה הגנוזה ב\u0003מ\"י\u0004, כי ב\u0003י'\u0004 זאת נמצאת בטמירו ה\"ת כנ\"ל, וקין רצה להזדווג עמה שפי' שרצה להמשיך החכמה שלו לבחי\"ד זו הגנוזה בנשמת הבל. ובזה הרגו להבל, כי אחר שנתגלתה ה\"ת נגלה עמה גם הצמצום שעליה, שאסורה לקבל מאור העליון, וע\"כ נסתלק שמא דאלהים משניהם. אלא ה\u0003מ\"י\u0004 שהוא הג\"ר נסתלק למעלה, ונבחן בזה שהרגו להבל. ו\u0003אל\"ה\u0004 דקין, להיותו בחינת ז\"ת, הוא נפל למקום הקליפות, שהוא \u0003ארקא\u0004 כנ\"ל. וכבר נתבאר שאע\"פ שנפל לקליפות מ\"מ נשארו בכלים מבחינת ניצוצין מועטין של החכמה, ומכ\"ש הבנות שלו שלא נפגמו כל כך, היו בהן עוד יותר ניצוצין מהבינה."],[5,"","ובזה תבין ש\u0003נעמה\u0004 זו שהיא מבנות קין היתה יפה מאד מכל בנות האדם, כי עיקר החטא היה בזכרים דקין ולא בנקבות, שהן קרקע עולם (סנהדרין ע\"ד:), ולפיכך אחר שהפיל הקב\"ה ל\u0003עזא ועזאל\u0004 לעוה\"ז שנברא ב\u0003ה'\u0004, וראו את \u0003נעמה\u0004 נתעורר בהם חשק גדול חדש, שלא היה מעולם, דהיינו החשק אחר אור החכמה, כי הם משורשם אין להם חשק אלא אחר חסדים בלבד כנ\"ל, רק הראיה ד\u0003נעמה\u0004 הולידה בהם חשק חדש זה להמשיך חכמה."],[5,"","ומתוך שמבנינם עצמם אין להם כלל בחינת ה\"ת המצומצמת, וגם בבנין \u0003נעמה\u0004 לא היתה הה\"ת מגולה להיותה נמשכת מ\u0003אל\"ה\u0004 דקין, לכן \u0003טעו\u0004 בה שהיא ראויה לקבלת חכמה ונזדווגו עמה. והיתה הטעות שלהם בב' דברים, א) אע\"פ שאין בהם בחינת ה\"ת מבנינם עצמם, מ\"מ המקום גורם, כיון שהם בעוה\"ז כבר ה\"ת שולטת עליהם, והיו אסורים להמשיך אור החכמה. ב) מה שחשבו שגם בבנין \u0003נעמה\u0004 אין ה\"ת, כי באמת היתה בה ה\"ת בגניזו. ולפיכך יצאו מזווגם זה כל השדין ורוחין מזיקי העולם."],[5,"","ובזה תבין מ\"ש חז\"ל, שהשדין חציים כמלאכי השרת וחציים כבני אדם (חגיגה ט\"ז. ). כי מצד אביהם \u0003עזא ועזאל\u0004 הם כמלאכים, ומצד אמם \u0003נעמה\u0004 הם כבני אדם. אמנם לא יכלה להוליד אנשים, מחמת שלא היה בה זרע אנשים אלא ממלאכים. ומה שהם מזיקים, הוא להיותם נולדים מזנות דפרודא היותר גדול שבעולם, וע\"כ מוליכים עמהם זוהמתם להזיק בכל אשר ימצאו."],[5,"","וז\"ש \u0003ואזלין בליליא לגבי נעמה אמהון דשדין, דטעו אבתרהא דחלין קדמאין\u0004, כי אחר שקבלו כח מאלו המלאכים שזנו תחילה עם \u0003נעמה\u0004 זו, יכלו גם הם לילך לזנות עמה כמוהם. ומ\"ש \u0003דאזלין בליליא\u0004 הוא כי כח החכמה דקליפות אינו שולט אלא בחושך ובלילה, שהוא בעת שליטת הדינים, וכל מחמת שרשם שהם \u0003עזא ועזאל\u0004 שנקשרו בהרי חושך."],[5,"וחשבין למקרב לגבה, ואיהי דליגת שתין אלפין פרסין","וכו': כי אחר שזנו עמה, קפצה ששים אלף פרסאות, שפירושו, שהעלתה צחנה עד שרצתה לבטל הפרסא שעל גבי ו\"ק דא\"א, אשר כל ספירה שלו נבחנת ברבוא, ונמצאים ו\"ק שלו שש אלף פרסאות. אמנם אינו אומר שקרבו לגבה. אלא רק \u0003וחשבין למקרב לגבה\u0004, וכן אינו אומר, ששטית \u0003שתין אלפין פרסין\u0004, אלא רק ו\u0003דליגת שתין אלפין פרסין\u0004, שהפירוש הוא, כי רק דלגה, אבל נפלה תיכף בחזרה למטה ולא נגעה בהם. והוא מטעם הנ\"ל, אשר בקליפות הגבוהות הללו אין שום מעשה נוהג ח\"ו בהם, וכל פגמן הוא רק במחשבה ורצון בלבד (כנ\"ל בדיבור הסמוך)."],[5,"","אמנם עכ\"ז כבר יש לה די כח \u0003דיטעון בני נשא אבתרה\u0004, כי הגם שאינה גורמת לאדם מעשה בפועל, אלא רק מחשבה ורצון כמותה, אבל הקב\"ה מעניש כאן על המחשבה כמו על מעשה, בסוה\"כ למען תפוש את בית ישראל בלבם (יחזקאל י\"ד) כנ\"ל. ומ\"ש \u0003ואתעבידת בכמה ציורין לגבי בני נשא\u0004 היינו הן מבחינת גילוי עריות והן מבחינת שפיכת דמים (כמ\"ש להלן בזוהר בראשית [ב]אות שנ\"ד), והיא אתמנת על ליליא באסכרה דרביי וכו', דהיא אתמנת לחייכא עם בני נשא, ע\"ש."],[6,"","קנח) \u0003ואלין תרין ממנן\u0004 וכו': ואלו שני הממונים, פורחים ומשוטטים בכל העולם, וחוזרים למקומם. והם מעוררים את בני בניו של קין, ברוח של יצרים הרעים, לעשות תולדות."],[6,"","פירוש. \u0003ומשטטן בכל עלמא\u0004: היינו להזיק בני אדם, כי גרמין לבני נשא לאסתאבא במקרה לילה כמ\"ש להלן."],[6,"","וז\"ש, \u0003ואהדרן לאתרייהו ואינון מתערין לאינון בני בנוי\u0004 וכו' \u0003למעבד תולדות\u0004: כי אחר שמחטיאים בני העולם הזה, חוזרים למקום הקבוע שלהם שהוא \u0003ארקא\u0004, ומעוררים שם בני בניהם דקין למעבד תולדות בזוהמתם כנ\"ל, ומשמיענו כי מלבד שהם מחטיאין בני קין ב\u0003ארקא\u0004, הם גם משוטטין בארץ שלנו שהיא \u0003תבל\u0004, והם מחטיאים גם יושבי הארץ הזאת."],[7,"","קנט) \u0003שמיא דשלטין תמן\u0004 וכו': השמים השולטים שם אינם כאלו השמים שלנו, ואין הארץ מולידה בכחם, זרע וקציר כאלו שלנו, ואין הזרעים חוזרים לצמוח, אלא בכמה שנים וזמנים. והם שנאמר עליהם, \u0003אלהיא די שמיא וארקא לא עבדו יאבדו מארעא\u0004, העליונה הנקראת תבל, שלא ישלטו בה, ולא ישוטטו בה, ולא יהיו גורמים לבני אדם להטמא ממקרה לילה. ועל כן \u0003יאבדו מארעא ומן תחות שמיא\u0004 שנעשו בהשם \u0003אל\"ה\u0004, (עי' לעיל אות י\"ד) כמו שלמדנו."],[7,"","פירוש. כי השמים שלנו מקבלים מז\"א, שיש לו מוחין דהולדה, וע\"כ הארץ שלנו המקבלת בנוקבא שלו, היא מקבלת זרע וקציר. אבל שמים ד\u0003ארקא\u0004 אין להם מוחין דהולדה בסבת שליטת הקליפות אשר שם, וע\"כ \u0003ולא אולידת ארעא בחילא דלהון זרועא וחצדא כהני\u0004, שאין כח בארץ לקבל זרע להוציא תבואות וקציר כנהוג בארצנו \u0003ולא אהדרן אלא בכמה שנין וזמנין\u0004 כי לא יצמח הזרע שמזריעין שם אלא רק בכמה שנים וזמנים."],[7,"","ומ\"ש, \u0003ואינון אלהא די שמיא וארקא לא עבדו\u0004 וכו': קאי על אותם ב' הממונים \u0003עפרירון וקסטימון\u0004, שהם \u0003אלהא די שמיא וארקא לא עבדו\u0004, כלומר, שלא יכלו לתקן ה\u0003שמיא וארקא\u0004 שתהא ראויה להוציא פירות, ע\"כ אין להם רשות לשוטט ולהחטיא אנשים בארץ שלנו שהיא \u0003תבל\u0004. כי בהמצאם כאן, הם מחבלים גם את ארצנו להיות כמו \u0003שמים וארקא\u0004 שלהם."],[7,"","וז\"ש \u0003יאבדו מארעא עלאה דתבל\u0004, שיאבדו מהארץ שלנו הנקראת \u0003תבל\u0004, שלא ישלטו בה, ולא ישוטטו בה, ולא יגרמו לאנשים שיטמאו במקרה לילה. כי על ידי השוטטות שלהם ב\u0003תבל\u0004 שלנו גורמים למחטי \u0003בני נשא במקרה ליליא\u0004, שהוא הקללה הרובצת על \u0003ארקא\u0004 מחמת שליטתם שם."],[7,"","ומתחת השמים שלנו שנעשו בשם \u0003אל\"ה\u0004, כי השמים שלנו מקבלים מזו\"ן המתוקנים \u0003בשמא דאל\"ה כמא דאתמר\u0004, דהיינו בסוד \u0003בראשית ברא אלהים\u0004, ש\u0003מ\"י\u0004 אשתתף ב\u0003אל\"ה\u0004, וע\"כ הארץ שלנו מתוקנת ג\"כ בקדושה עלאה. כי ברזא דא אתקיים עלמא. (כנ\"ל אות ט\"ו). וע\"כ אין רשות לאלו ב' הממונים לשוטט כאן."],[8,"","קס) \u0003ועל דא האי\u0004 וכו': ועל כן מקרא זה תרגום, שלא יחשבו מלאכים העליונים שעליהם אומרים זה, ולא יהיו עוינים לנו. ועל כן סוד המלה \u0003אלה\u0004, הוא כמו שאמרנו, שהיא מלה קדושה שאינה מחולפת בתרגום."],[8,"","פירוש. כי כל המקרא כתוב בלשון תרגום לבד מהמלה אל\"ה, דאומר \u0003יאבדו מארעא ומן תחות שמיא אל\"ה\u0004. ואמר הטעם כי מלה דא אין לה תרגום. והוא כי חיבור \u0003אל\"ה\u0004 ב\u0003מ\"י\u0004 ממשיך מוחין עלאין דחכמה כנ\"ל, ואם ח\"ו פוגמין באתוון ד\u0003אל\"ה\u0004 כמו קין, הרי אלו נופלין בקליפות, ואפילו קדושת ה\u0003תרגום\u0004 לא נשארת בהם. באופן שלא תצויר בהם בחינת \u0003תרגום\u0004, שהיא בחינת ו\"ק דקדושה. (עי' לעיל אות קנ\"ב)."],[9,"","קסא) \u0003אמר ליה רבי אלעזר\u0004 וכו': א\"ל ר\"א, מקרא הזה שכתוב, מי לא ייראך מלך הגוים כי לך יאתה. איזה שבח הוא זה. אמר לו ר\"ש: אלעזר בני, מקרא זה נאמר בכמה מקומות. אבל ודאי אין הוא כך כמשמעותו הפשוטה, שכתוב, כי בכל חכמי הגוים ובכל מלכותם מאין כמוך, שזה בא לתת פתחון פה לרשעים, לאותם, שחושבים שהקב\"ה אינו יודע את ההרהורים והמחשבות שלהם. ובשביל זה יש להודיע השטות שלהם. כי פעם אחת בא אלי פילוסוף אחד של אומות העולם. אמר לי, אתם אומרים שאלקיכם מושל בכל רום השמים, וכל הצבאות והמחנות אינם משיגים ואינם יודעים המקום שלו, הנה המקרא הזה, אינו מרבה כבודו כל כך. שכתוב, כי בכל חכמי הגוים ובכל מלכותם מאין כמוך, מהי ההשואה הזו, לבני אדם שאין להם קיום."],[9,"","פירוש. והוא ע\"ד הכתוב, ואמרו איכה ידע אל ויש דעה בעליון, הנה אלה רשעים ושלוי עולם השגו חיל (תהלים ע\"ג). כמו שמביא לפנינו דברי הפילוסופא. האי פילוסופא היה אחד גדול מחכמי הגוים, ובא לפני ר\"ש לבזות את חכמת ישראל ועבודתנו באמונה שלימה, שהיא בתמימות גדולה בגין דלית מחשבה תפיסא ביה כלל. וחכם זה היה מהפילוסופים האומרים שעיקר עבודת ה' היא להשיג אותו, כי לדעתם הם משיגים אותו, ובא להתלוצץ עלינו."],[9,"","וז\"ש, \u0003דאלהכון שליט בכל רומי שמיא\u0004, כלומר, שהוא מרומם מכל שכל אנושי, והוא שליט ברוממותו זו, וצוה לכם לעבוד לפניו באמונה ותמימות, ולא להרהר בו כלל. משום ד\u0003כלהון חיילין ומשריין לא אדבקן\u0004, שלא לבד ששכל אנושי אינו משיגו אלא אפילו החיילות והמלאכים העליונים לא ישיגוהו כלל \u0003ולא ידעי אתר דיליה\u0004, שאפילו מקומו אינם משיגים, דהיינו כמו\"ש, שאומרים, \u0003ברוך כבוד ה' ממקומו\u0004, משום שאינם יודעים היכן מקומו."],[9,"","וע\"ז בא להקשות כדלהלן, \u0003האי קרא לא אסגי יקריה כל כך\u0004 פסוק זה אינו מרבה כבודו כל כך. \u0003דכתיב כי בכל חכמי הגוים ובכל מלכותם מאין כמוך\u0004, אם הנבואה באה לשבח אלהי ישראל, שהוא יותר חשוב מהאלהים שמשיגים חכמי הגוים ע\"פ כחם האנושי עצמם וחכמתם \u0003לא אסגי יקריה כל כך\u0004, הרי שבח זה אינו מרבה לו כבוד כל כך, כי \u0003מאי שקולא דא לבני נשא די לית לון קיימא\u0004, איזה משקל והשואה היא מהבורא ית' לבני תמותה, ונמצא כאן זלזול גדול לאלהיכם, להעריכו בערך חכמי הגוים בני התמותה."]],[[0,"","וּפָסוּק זֶה הוּא תַרְגּוּם, חוּץ מִמִּלַּת סוֹף הַפָּסוּק (אלה). אִם תֹּאמַר בִּגְלַל שֶׁמַּלְאָכִים קְדוֹשִׁים לֹא נִזְקָקִים לְתַרְגּוּם וְלֹא מַכִּירִים אוֹתוֹ, אָז מִלָּה זוֹ רְאוּיָה הִיא לְהֵאָמֵר בִּלְשׁוֹן הַקֹּדֶשׁ כְּדֵי שֶׁיִּשְׁמְעוּ מַלְאָכִים קְדוֹשִׁים וְיִהְיוּ זְקוּקִים לְהוֹדוֹת עַל זֶה, אֶלָּא וַדַּאי מִשּׁוּם כָּךְ כָּתוּב תַּרְגּוּם, שֶׁלֹּא נִזְקָקִים לוֹ הַמַּלְאָכִים הַקְּדוֹשִׁים וְלֹא יְקַנְּאוּ בְּבֶן אָדָם לְהַזִּיק לוֹ, בִּגְלַל שֶׁבְּפָסוּק זֶה בִּכְלָל הֵם מַלְאָכִים קְדוֹשִׁים, שֶׁהֲרֵי הֵם נִקְרָאִים אֱלֹהִים, וְהֵם בִּכְלָל שֶׁל אֱלֹהִים, וְהֵם לֹא עָשׂוּ שָׁמַיִם וָאָרֶץ."],[1,"","וְאַרְקָא, הָיָה צָרִיךְ לִכְתֹּב וְאַרְעָא (ארץ)! אֶלָּא בִּגְלַל שֶׁאַרְקָא הִיא אַחַת מֵאוֹתָן שֶׁבַע אֲרָצוֹת שֶׁלְּמַטָּה, וּבְאוֹתוֹ מָקוֹם יֶשְׁנָם בְּנֵי בָנָיו שֶׁל קַיִן. לְאַחַר שֶׁגֹּרַשׁ מֵעַל פְּנֵי הָאָרֶץ, יָרַד שָׁם וְעָשָׂה תוֹלָדוֹת, וְהִשְׁתַּבֵּשׁ שָׁם, שֶׁלֹּא יָדַע כְּלוּם. וְהִיא אֶרֶץ כְּפוּלָה שֶׁנִּכְפְּלָה מֵחֹשֶׁךְ וְאוֹר."],[2,"","וְשָׁם שְׁנֵי מְמֻנִּים שַׁלִּיטִים שֶׁשּׁוֹלְטִים - זֶה בַּחֹשֶׁךְ וְזֶה בָּאוֹר. וְשָׁם קִטְרוּג זֶה בָּזֶה. וּבְשָׁעָה שֶׁיָּרַד לְשָׁם קַיִן, הִשְׁתַּתְּפוּ זֶה עִם זֶה וְהִשְׁלִימוּ כְּאֶחָד, וְהַכֹּל רוֹאִים שֶׁהֵם תּוֹלְדוֹת קַיִן. וְעַל זֶה הֵם בִּשְׁנֵי רָאשִׁים כְּמוֹ שְׁתֵּי חַיּוֹת, פְּרָט שֶׁכְּשֶׁאוֹתוֹ אוֹר שׁוֹלֵט - מְנַצֵּחַ שֶׁלּוֹ וּמְנַצֵּחַ עַל הָאַחֵר. וְעַל זֶה נִכְלְלוּ שֶׁבַּחֹשֶׁךְ בָּאוֹר וְנִהְיִים אֶחָד."],[3,"","הֵם שְׁנֵי מְמֻנִּים, עַפְרִירָא וְקַסְטִימוֹן, וּדְמוּתָם כִּדְמוּת מַלְאָכִים קְדוֹשִׁים בְּשֵׁשׁ כְּנָפַיִם, אֶחָד דְּמוּתוֹ כְּמוֹ שׁוֹ\"ר, וְאֶחָד דְּמוּתוֹ כְּמוֹ נֶשֶׁ\"ר, וּכְשֶׁמִּתְחַבְּרִים נַעֲשִׂים דְּמוּת אָדָם."],[4,"","כְּשֶׁהֵם בַּחֹשֶׁךְ, מִתְהַפְּכִים לִדְמוּת שֶׁל נָחָשׁ בִּשְׁנֵי רָאשִׁים, וְהוֹלְכִים כְּנָחָשׁ, וְטָסִים לְתוֹךְ הַתְּהוֹם וְרוֹחֲצִים בַּיָּם הַגָּדוֹל. כְּשֶׁמַּגִּיעִים לְשַׁלְשֶׁלֶת עֲזָ\"א וַעֲזָאֵ\"ל, מַרְגִּיזִים אוֹתָם וּמְעוֹרְרִים אוֹתָם, וְהֵם מְדַלְּגִים לְתוֹךְ הָרֵי הַחֹשֶׁךְ, וְחוֹשְׁבִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לִתְבֹּעַ לָהֶם דִּין."],[5,"","וּשְׁנֵי מְמֻנִּים אֵלּוּ שָׁטִים בַּיָּם הַגָּדוֹל, וּפוֹרְחִים מִשָּׁם, וְהוֹלְכִים בַּלַּיְלָה לְנַעֲמָה, אֵם הַשֵּׁדִים, שֶׁטָּעוּ אַחֲרֶיהָ יְרֵאִים רִאשׁוֹנִים וְחָשְׁבוּ לְהִתְקָרֵב אֵלֶיהָ. וְהִיא מְדַלֶּגֶת שִׁשִּׁים אֶלֶף פַּרְסָאוֹת, וְנַעֲשֵׂית בְּכַמָּה צִיּוּרִים לְגַבֵּי בְּנֵי אָדָם כְּדֵי שֶׁיִּטְעוּ אַחֲרֶיהָ בְּנֵי אָדָם."],[6,"","וּשְׁנֵי מְמֻנִּים אֵלֶּה פּוֹרְחִים וּמְשׁוֹטְטִים בְּכָל הָעוֹלָם וְחוֹזְרִים לִמְקוֹמָם, וְהֵם מְעוֹרְרִים לְאוֹתָם בְּנֵי בָנָיו שֶׁל קַיִן בְּרוּחַ שֶׁל יְצָרִים רָעִים לַעֲשׂוֹת תּוֹלָדוֹת."],[7,"","הַשָּׁמַיִם שֶׁשָּׁם הֵם שׁוֹלְטִים אֵינָם כָּאֵלֶּה, וְהָאָרֶץ לֹא מוֹלִידָה בְּכֹחָם שֶׁלָּהֶם זֶרַע וְקָצִיר כְּמוֹ אֵלֶּה, וְלֹא חוֹזְרִים אֶלָּא בְּכַמָּה שָׁנִים וּזְמַנִּים. וְהֵם אֱלֹהֵי הַשָּׁמַיִם וְאַרְקָא לֹא עָשׂוּ. יֹאבְדוּ מֵאֶרֶץ עֶלְיוֹנָה שֶׁל תֵּבֵל, שֶׁלֹּא יִשְׁלְטוּ בָהּ וְלֹא יְשׁוֹטְטוּ בָהּ, וְלֹא יִגְרְמוּ לִבְנֵי אָדָם לְהִטָּמֵא מִמִּקְרֵה לַיְלָה. וְעַל זֶה יֹאבְדוּ מֵהָאָרֶץ וּמִתַּחַת הַשָּׁמַיִם, שֶׁנַּעֲשׂוּ בַשֵּׁם שֶׁל אֵלֶּה, כְּמוֹ שֶׁנִּתְבָּאֵר."],[8,"","וְלָכֵן פָּסוּק זֶה הוּא תַרְגּוּם, שֶׁלֹּא יַחְשְׁבוּ מַלְאָכִים עֶלְיוֹנִים שֶׁעֲלֵיהֶם אוֹמְרִים, וְלֹא יְקַטְרְגוּ לָנוּ. וְעַל זֶה הַסּוֹד שֶׁל \"אֵלֶּה\" כְּמוֹ שֶׁנִּתְבָּאֵר, הוּא דָּבָר קָדוֹשׁ שֶׁלֹּא מִתְחַלֵּף בַּתַּרְגּוּם."],[9,"","אָמַר לוֹ רַבִּי אֶלְעָזָר, פָּסוּק זֶה שֶׁכָּתוּב (ירמיה י) מִי לֹא יִרָאֲךְ מֶלֶךְ הַגּוֹיִם כִּי לְךְ יָאָתָה, אֵיזֶה שֶׁבַח הוּא אָמַר לוֹ, אֶלְעָזָר בְּנִי, פָּסוּק זֶה נֶאֱמַר בְּכַמָּה מְקוֹמוֹת, אֲבָל וַדַּאי הוּא לֹא (כך), שֶׁכָּתוּב כִּי בְכָל חַכְמֵי הַגּוֹיִם וּבְכָל מַלְכוּתָם. שֶׁהֲרֵי בָּא לִפְתֹּחַ פֵּה הָרְשָׁעִים שֶׁחוֹשְׁבִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא יוֹדֵעַ הִרְהוּרֵיהֶם וּמַחְשְׁבוֹתֵיהֶם, וְלָכֵן יֵשׁ לְהוֹדִיעַ אֶת שְׁטוּתָם. שֶׁפַּעַם אַחַת בָּא אֵלַי פִּילוֹסוֹף אֶחָד מֵאֻמּוֹת הָעוֹלָם, אָמַר לִי: אַתֶּם אוֹמְרִים שֶׁאֱלֹהֵיכֶם שׁוֹלֵט בְּכָל רוּמֵי הַשָּׁמַיִם כָּל הַצְּבָאוֹת וְהַמֶּרְכָּבוֹת לֹא מַשִּׂיגִים וְלֹא יוֹדְעִים אֶת מְקוֹמוֹ. פָּסוּק זֶה לֹא מַגְדִּיל אֶת כְּבוֹדוֹ כָּל כָּךְ, שֶׁכָּתוּב כִּי בְכָל חַכְמֵי הַגּוֹיִם וּבְכָל מַלְכוּתָם מֵאֵין כָּמוֹךְ. מַה שִּׁקּוּל זֶה לִבְנֵי אָדָם שֶׁאֵין לָהֶם קִיּוּם."]]],[["וְתוּ דְּאַתּוּן אָמְרִין (דברים לה) וְלא קָם נָבִיא עוֹד בְּיִשְׂרָאֵל כְּמשֶׁה, בְּיִשְׂרָאֵל לֹא קָם אֲבָל בְּאוּמוֹת הָעוֹלָם קָם. אוּף הָכִי אֲנָא אֵימָא בְּכָל חַכְמֵי הַגּוֹיִם אֵין כָּמוֹהוּ, אֲבָל בְּחַכְמֵי יִשְׂרָאֵל אִית. אִי הָכִי אֱלָהָא דְאִית בְּחַכְמֵי יִשְׂרָאֵל כְּוָותֵיהּ לָאו אִיהוּ עִלָּאָה שַׁלִּיטָא. אִסְתַּכַּל בַּקְּרָא וְתִשְׁכַּח דְּדַיִּיקְנָא כְּדְקָא יְאוּת.","אֲמִינָא לֵיהּ וַדַּאי שַׁפִּיר קָא אֲמַרְתְּ. מָאן מְחַיֶּה מֵתִים אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי, אֲתָא אֵלִיָּהוּ וְאֱלִישָׁע וְאַחֲיוּ מֵתַיָיא. מָאן מוֹרִיד גְּשָׁמִים אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי אֲתָא אֵלִיָּהוּ וּמְנַע לוֹן וּנְחִית לוֹן בִּצְלוֹתֵיהּ. מָאן עֲבַד שְׁמַיָּא וְאַרְעָא אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי, אֲתָא אַבְרָהָם אִתְקַיָימוּ בְּקִיּוּמוֹהִי בְּגִינֵיהּ.","מָאן מַנְהִיג שִׁמְשָׁא אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא, אֲתָא יְהוֹשֻׁעַ וְשָׁכִיךְ לֵיהּ וּפַקִּיד לֵיהּ דְּיֵקוּם עַל קִיּוּמֵיהּ וְאִשְׁתְּכַך וּכְתִיב, (יהושע י׳:י״ג) וַיִּדּוֹם הַשֶּׁמֶשׁ וְיָרֵחַ עָמָד. קוּדְשָׁא בְּרִיךְ הוּא גּוֹזֵר גְּזַר דִּין אוּף הָכִי משֶׁה גָּזִיר גְּזַר דִּין וְאִתְקַיָּימוּ. וְתוּ דְּקוּדְשָׁא בְּרִיךְ הוּא גּוֹזֵר גִּזְרִין וְצַדִּיקַיָּא דְּיִשְׂרָאֵל מְבַטְּלִין לוֹ דִּכְתִיב, (שמואל ב כ״ג:ג׳) צַדִּיק מוֹשֵׁל יִרְאַת אֱלהִים. וְתוּ דְּאִיהוּ פַּקִּיד לוֹן לְמְהַךְ בְּאוֹרְחוֹי מַמָּשׁ לְאִתְדְּמָא לֵיהּ בְּכֹלָּא. אֲזַל הַהוּא פִּילוֹסוֹפָא וְאִתְגָיָּיר בִּכְפַר שְׁחָלַיִם וְקָרוּן לֵיהּ יוֹסֵי קְטִינָאָה. וְאוֹלִיף אוֹרַיְיתָא סַגְיָא. וְאִיהוּ בֵּין חַכִּימִין וְזַכָּאִין דְּהַהוּא אֲתַר.","הַשְׁתָּא אִית לְאִסְתַּכְּלָא בַּקְּרָא וְהָא כְּתִיב, (ישעיהו מ׳:י״ז) כָּל הַגּוֹיִם כְּאַיִן נֶגְדוֹ. מַאי רִבּוּיָא הָכָא. אֶלָּא מִי לא יִרָאֲךָ מֶלֶךְ הַגּוֹיִם וְכִי מֶלֶךְ הַגּוֹיִם אִיהוּ וְלָאו מֶלֶךְ יִשְׂרָאֵל. אֶלָּא בְּכָל אֲתַר קוּדְשָׁא בְּרִיךְ הוּא בָּעָא לְאִשְׁתַּבָּחָא בְּיִשְׂרָאֵל, וְלָא אִתְקְרֵי אֶלָא עַל יִשְׂרָאֵל בִּלְחוֹדוֹי. דִּכְתִיב, (שמות ה׳:ג׳) אֱלֹהֵי יִשְׂרָאֵל אֱלֹהֵי הָעִבְרִים, וּכְתִיב, (ישעיהו מ״ד:ו׳) כֹּה אָמַר יְיָ מֶלֶךְ יִשְׂרָאֵל. מֶלֶךְ יִשְׂרָאֵל וַדַּאי. אָמְרוּ אוּמוֹת הָעוֹלָם פַּטְרוֹן אָחֳרָן אִית לָן בִּשְׁמַיָא דְּהָא מַלְכֵיכוֹן לָא שָׁלִיט אֶלָא עֲלַיְיכוּ בִּלְחוֹדֵיכוֹן וְעֲלָנָא לָא שָׁלִיט.","אֲתָא קְרָא וְאָמַר מִי לֹא יִרָאֲךָ מֶלֶךְ הַגּוֹיִם (נ\"א מלכא עילאה לרדאה לון ולאלקאה לון ולמעבד בהון רעותיה. כי לך יאתה לדחלא מנך לעילא ותתא. כי בכל חכמי הגוים) אִלֵּין שַׁלִּיטִין רַבְרְבָן דִּי מְמַנָּן עֲלַיְיהוּ. וּבְכָל מַלְכוּתָם בְּהַהוּא מָלְכוּ דִּלְעֵילָא. דְּהָא אַרְבַּע מַלְכְּוָון שַׁלִּיטִין אִית לְעֵילָא וְשָׁלְטִין בִּרְעוּתֵיהּ עַל כָּל שְׁאָר עַמִּין. וְעִם כָּל דָּא לֵית בְּהוּ דְּיַעֲבִיד אֲפִלּוּ מִלָּה זְעֵירָא אֶלָּא כְּמָה דְּפָּקִּיד לוֹן דִּכְתִיב, (דניאל ד׳:ל״ב) וּכְמִצְבְּיֵה עָבִיד בְּחֵיל שְׁמַיָא וְדָיְירֵי אַרְעָא. חַכְמֵי הַגּוֹיִם אִנּוּן מְמַנָּן וְרַבְרְבָן דִּלְעֵילָא דְּחָכְמְתָא דִּלְהוֹן מִנַּיְיהוּ הֲוָה. בְּכָל מַלְכוּתָם מַלְכוּתָא דְּשָׁלִיט כְּמָה דְאִתְּמָר. וְדָא הוּא קְרָא כִּפְשָׁטֵיהּ.","אֲבָל בְּכָל חַכְמֵי הַגּוֹיִם וּבְכָל מַלְכוּתָם. הַאי אַשְׁכַּחְנָא בְּסִפְרֵי קַדְמָאֵי, דְּאִנּוּן מַשִּׁרְיָין וְחַיָילִין אַף עַל גַּב דְּאִתְפַּקְּדָן עַל מִלִּין דְּעָלְמָא וּפַקִּיד לְכָל חַד לְמֶעְבַּד עֲבִידְתָּא, מָאן הוּא (סתימא קדישא ולא כרעותיה) דְּיַעֲבִיד שׁוּם חַד מִנַּיְיהוּ כָּמוֹךָ. בְּגִין דְּאַנְתְּ רָשִׁים בְּעִילוּיָא, וְאַתְּ רָשִׁים בְּעוֹבָדָךְ מִכֻּלְּהוּ. וְדָא הוּא מֵאֵין כָּמוֹךָ יְיָ, מָאן הוּא סְתִימָאָה קַדִּישָׁא דְּיַעֲבִיד וְלֶהֱוֵי כָּמוֹךָ עֵילָא וְתַתָּא. וִיהֵא דָּמֵי לָךְ (בכל) (בכולא), עוֹבָדָא דְמַלְכָּא קַדִּישָׁא שָׁמַיִם וָאָרֶץ, אֲבָל אִנּוּן (ישעיה מה) תֹּהוּ וַחֲמוּדֵיהֶם בַּל יוֹעִילוּ. בְּקוּדְשָׁא בְּרִיךְ הוּא כְּתִיב בְּרֵאשִׁית בָּרָא אֱלֹהִים וְגו', בְּמַלְכוּתָם כְּתִיב וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ.","אָמַר רִבִּי שִׁמְעוֹן לְחַבְרַיָיא בְּנֵי הִלּוּלָא דָא, כָּל חַד מִנְּכוֹן יְקַשֵּׁט קִשּׁוּטָא חַד לְכַּלָּה. אָמַר לְרִבִּי אֶלְעָזָר בְּרֵיהּ. אֶלְּעָזָר הַב נְבַזְבְּזָא חַד לְכַּלָּה דְּהָא לְמָחָר אִסְתַּכַּל (קודשא בריך הוא) (נ\"א בה) כַּד יֵעוּל לַחוּפָּה בְּאִנּוּן שִׁירִין וּשְׁבָחִין דְּיַהֲבוּ לָהּ בְּנֵי הֵיכָלָא לְקַיְּימָא קַמֵּיהּ.","פָּתַח רִבִּי אֶלְעָזָר וְאָמַר (שיר השירים ג׳:ו׳) מִי (קע\"ו ב) זֹאת עוֹלָה מִן הַמִּדְבָּר וְגו', מִי זֹאת, כְּלָלָא דִּתְרֵין קִדּוּשִׁין (קדישין) דִּתְרֵין עָלְמִין בְּחִבּוּרָא חֲדָא וְקִשּׁוּרָא חֲדָא. עוֹלָה מַמָּשׁ לְמֶהוֵי קֹדֶשׁ קָדָשִׁין. דְּהָא קֹדֶשׁ קָדָשִׁין מִ\"י. וְאִתְחַבְּרָא בְּזֹא\"ת. בְּגִין לְמֶהֱוֵי (זאת) עוֹלָה דְּאִיהִי קֹדֶשׁ קָדָשִׁין. מִן הַמִּדְבָּר דְּהָא מִן הַמִּדְבָּר יָרְתָא לְמֶהֱוֵי כַלָּה וּלְמֵיעַל לְחֻפָּה."],[[0,"","קסב) \u0003ותו דאתון אמרין\u0004 וכו': ועוד. שאתם אומרים על הכתוב, ולא קם נביא עוד בישראל כמשה, בישראל לא קם אבל באומות העולם קם. אף אני אומר כך: בכל חכמי הגוים אין כמוהו, אבל בחכמי ישראל יש כמוהו. וא\"כ, אלקים שיש כמוהו בחכמי ישראל, אין הוא אלקים עליון שליט. הסתכל במקרא ותמצא שדייקתי כראוי."],[0,"","פירוש. כאן דיבר בלשון חכמה. כמ\"ש \u0003אסתכל בקרא ותשכח דדייקנא כדקא יאות\u0004. והוא, כי הבין שיתרצו לו קושיתו בנקל, שהפירוש הוא כי \u0003בכל חכמי הגוים ובכל מלכותם\u0004 אין מי שישיג אותך, כי \u0003מאין כמוך\u0004 הוא על דרך \u0003אלמלא ידעתיו הייתיו\u0004, ולפי שחכמי הגויים מתפארים שמשיגים אותו הם נבחנים משום זה \u0003כמוהו\u0004, ולכן אומר הכתוב ששקר דברו ואינם כמוהו, כי אינם משיגים אותו אלא הם מטעים את עצמם."],[0,"","ולפיכך החכים קושיתו לשאול, שלפי\"ז משמע, שרק \u0003בחכמי הגוים אין כמוהו, אבל בחכמי ישראל אית כמוהו\u0004, דהיינו שמשיגים אותו, א\"כ אלהא דאית בבני ישראל כוותיה לאו איהו \u0003עלאה שליטא\u0004. אלהים שיש בבני ישראל כמוהו אינו אלהים שליט ומרומם. כלומר, שלפי\"ז איך אתם אומרים שאלהי ישראל לית מחשבה תפיסא ביה כלל ושליט על עבדיו בכח האמונה ברוממותו ית' כנ\"ל בתחילת דברו שאמר \u0003אתון אמרין דאלהכון שליט בכל רומי שמיא\u0004, והרי הכתוב אומר שב\u0003חכמי ישראל\u0004 אית כמוהו, שהפירוש הוא, שיש חכמי ישראל שמשיגין אותו. הרי שהכתוב סותר אתכם."],[1,"","קסג) \u0003אמינא ליה ודאי\u0004 וכו': אמרתי לו, ודאי יפה אמרת, שיש בישראל כמוהו, כי מי מחיה מתים, הלא הקב\"ה לבדו, באו אליהו ואלישע והחיו מתים. מי מוריד גשמים, הלא הקב\"ה לבדו, בא אליהו ומנע אותם והוריד אותם בתפלתו. מי עשה שמים וארץ, הלא הקב\"ה לבדו, בא אברהם, ונתקיימו שמים וארץ בקיומם, בשבילו."],[1,"","פירוש. ר\"ש תירץ לו, כי זהו ודאי אמת כמו שאמרת, שבישראל אית כמוהו, \u0003ודאי שפיר קא אמרת\u0004, ועם זה אינו סותר כלל את אמונתנו התמימה דלית מחשבה תפיסא בו כלל וכלל, ואיהו \u0003שליט בכל רומי שמיא\u0004, דהיינו שגם המלאכים העליונים אינם משיגים אותו \u0003ולא ידעי אתר דיליה\u0004, אמנם כלפי זה נתן לנו תורה ומצוות שע\"י העסק בתורה ומצוות לשמה, זוכים ישראל להדבק בו ממש, ושכינתו יתברך מתלבשת בהם עד שהם עושים אותם המעשים שהבורא ית' עושה, שהם מחיים מתים ומורידים גשמים, ומקיימים שמים וארץ, וכו' ומבחינה זו הרי הם כמוהו ממש, שה\"ס ממעשיך הכרנוך, אבל כל זה משיגים רק מבחינת אמונה שלמה ותמימה שאינם מעלים הרהור כלל וכלל כדי להשיג אותו בחכמתם. כדרך חכמי הגוים."],[2,"","קסד) \u0003מאן מנהיג שמשא\u0004 וכו': מי מנהיג השמש, הלא רק הקב\"ה, בא יהושע והשתיק אותו וצוהו שיעמוד על עמדו, ונשתתק. שכתוב, וידום השמש וירח עמד. הקב\"ה גוזר דין, אף משה כך, גזר דין ונתקיים. ועוד, שהקב\"ה גוזר גזרות וצדיקי ישראל מבטלים אותם, שכתוב, צדיק מושל יראת אלקים. ועוד, שהקב\"ה צוה אותם ללכת בדרכיו ממש להדמות לו בכל. הלך אותו הפילוסוף ונתגייר בכפר שחליים. וקראוהו, יוסי הקטן, ולמד הרבה תורה, והוא בין החכמים והצדיקים שבאותו המקום."],[2,"","פירוש. שמא תאמר סוף סוף הם ממעטים כח אמונתם התמימה משום זה, בהיותם זוכים להיות כמוהו ממש, אמנם המה עושים זאת משום שצוה אותם לעשות כן ולהשיגו מכח מעשיו \u0003דאיהו פקיד לון למהך באורחוי ממש\u0004 שה\"ס הכתוב והלכת בדרכיו (דברים כ\"א), ומצוות המלך המה עושים, כדי \u0003לאתדמא ליה בכלא\u0004, והנה הפלוסוף נתפעל מאמת זו עד שהלך ונתגייר וקבל עליו עול תורה ומצוות."],[3,"","קסה) \u0003השתא אית לאסתכלא\u0004 וכו': עתה יש להסתכל במקרא. והרי כתוב, כל הגוים כאין נגדו, איזה יתרון יש כאן. ומשיב, אלא, מי לא ייראך מלך הגוים, וכי מלך הגוים הוא ולא מלך ישראל. אלא בכל מקום רוצה הקב\"ה להשתבח בישראל, ואינו נקרא אלא על ישראל לבד, שכתוב, אלקי ישראל. אלקי העברים. וכתוב, כה אמר ה' מלך ישראל. מלך ישראל ודאי. אמרו אומות העולם מגין אחר יש לנו בשמים. כי מלככם אינו שולט אלא עליכם לבד, ועלינו אינו שולט."],[3,"","פירוש. השתא, היינו בהאי ליליא דכלה אזדמנת למיעל לחופה, דהוה ביה ר\"ש, ובעי לקשט עתה קשוטא לכלה כנ\"ל, יש להסתכל מחדש בהאי קרא, ד\u0003מי לא ייראך מלך הגוים\u0004, ולפרשהו בדרך קישוטא דכלה. וחוזר על תחילת הכתוב, שנאמר מי לא ייראך מלך הגוים \u0003מאי רבויא הכא\u0004 איזה רבותא יש כאן. \u0003והא כתיב כל הגוים כאין נגדו\u0004 ומה משמיענו כאן. וז\"ש \u0003פטרון אחרן אית לן בשמיא\u0004: כי האומות מונין את ישראל לומר, שיש להם מגין ומנהיג טוב בשמים הנותן להם חכמה ושררה. ומלך ישראל אינו שולט עליהם."],[4,"","קסו) \u0003אתא קרא ואמר\u0004 וכו': בא הכתוב ואמר, \u0003מי לא ייראך מלך הגוים\u0004. היינו מלך עליון עליהם, לרדות בהם, ולהכות בהם, ולעשות בהם כרצונו. \u0003כי לך יאתה\u0004, לירא ממך למעלה ולמטה. \u0003כי בכל חכמי הגוים\u0004, אלו הם השליטים והשרים שלמעלה, הממונים עליהם. \u0003ובכל מלכותם\u0004, היינו באותה מלכות שלמעלה. כי ארבע מלכיות שליטות יש למעלה, ושולטים ברצונו של הקב\"ה, על כל שאר העמים. ועם כל זה אין בהם מי שיעשה אפילו דבר קטן, אלא כמו שצוה אותם. שכתוב, וכמצביה עביד בחיל שמיא ודיירי ארעא. \u0003חכמי הגוים\u0004, הם הממונים והשרים שלמעלה, שחכמת הגוים מהם הוא. \u0003בכל מלכותם\u0004, היינו מלכות השולטת עליהם כאמור. וזהו פשוטו של המקרא."],[4,"","ביאור הדברים, כי המקרא הזה מבאר איך הכלה מזדמנת בימי הגלות למיעל לחופה בגמר התיקון. והוא כי כל כחם של הגוים לכבוש אותנו בגלות תחת שליטתם, הוא ע\"י החכמה והמלכות שלהם, שהם הממנין העלאין שבשמים דקליפות, המשפיעים להם חכמה ושררה, שע\"י חכמתם מביאים אותנו לידי הרהורים רעים, לרצות להבינו ית' מכל הבחינות: אותו ודרכיו ומחשבותיו בלי שום יראה ושום התחשבות ברוממות מלכותו ית', שע\"י הרהורים רעים אלה, אנו מתרוקנים מכל שפע קדושה והשפע עובר למלכות שלהם, בסוד לא נתמלאה צור אלא מחרבנה של ירושלים, שבזה משיגים כח לרדות בנו ולהלקות אותנו, ולהכריחנו לעשות רצונם. שז\"ס ד' המלכויות המשעבדות אותנו בד' גלויות, המרומזות בד' בחינות חו\"ב תו\"מ שלהם, המרומזות בצלם של נבוכדנצר, \u0003ראשה די דהב טב, חדוהי ודרעוהי די כסף, מעוהי וירכתה די נחש, שקוהי די פרזל, רגלוהי מנהון די פרזל, ומנהון די חסף\u0004, (דניאל ב'). ובעת שליטת הצלם הזה הם מתלוצצים עלינו, שיש להם \u0003פטרון אחרן בשמיא\u0004 וכו'."],[4,"","אמנם כל זה ה\"ס ואלהים עשה שיראו מלפניו (קהלת ד'). כי השכינה נקראת יראת שמים, זה רומז שאין לנו שום מציאות להדבק בו ית' לנצחיות זולת ע\"י יראה גדולה מרוממותו ית', לקבל עלינו עול תורה ומצוות באמונה שלמה וטהורה, מבלי להרהר ח\"ו אחר מדותיו ית', בכל פנים שבעולם שלא יסתר ממנו, כי אז אנו נדבקים בו ית' לנצחיות בקשר כל ימוט, ואז גם ה' יתן הטוב בכל אשר חשב להנות אותנו במחשבת הבריאה, ואנו זוכים לגאולה השלימה ולגמר התיקון. אבל מטרם זה כל המשתכר הוא משתכר אל צרור נקוב (חגי א' ו') כי הס\"א יש לו תמיד כח לעשוק השפע שאנו מקבלים בכח ההרהורים הרעים שמביא בנו, בסוד לא נתמלאה צור אלא מחרבנה של ירושלים."],[4,"","אמנם גם עונשים אלו אינם לרעתנו, אלא להכשיר אותנו ליראתו ית', ע\"י ריבוי הנסיונות שהגלות מביאה עלינו, עד שאנו זוכים לקבל אמונתו בשלמות וביראת הרוממות, ואז נאמר, זכר חסדו ואמונתו לבית ישראל ראו כל אפסי ארץ את ישועת אלהינו (תהלים צ\"ח), כי לעת הקץ יזכור ה' לנו כל חסדיו עם שלמות אמונתו בבת אחת."],[4,"","כי אחר שקבלנו כח לקבל אמונתו בשלמות, תבנה ירושלים מחורבנה של צור, כי כל החסדים והשפע שהמלכויות דס\"א גזלו מאתנו בימי הגלות כנ\"ל, ישובו לנו, אחר שלימות אמונתנו, בכל מילואן, אף משהו לא יחסר. ואז, ראו כל אפסי ארץ את ישועת אלהינו. כי יראו כל האומות שגם עד עתה היו רק שומרי חנם על השפע שלנו, בכדי להחזירם לנו בעת הרצויה, ונמצא ששלט אדם באדם, הוא לרע לו, (קהלת ח' ט') כי קושי השעבוד ששלטו בנו בעת ששלט אדם בליעל באדם דקדושה, לא היה אלא להרע לאדם בליעל, כי מחמת זה מהרנו לבא לאמונתו ית', ולגבות ממנו כל הגזל שעשק מאתנו."],[4,"","ועל העת ההיא אמר הנביא, \u0003מי לא יראך מלך הגוים\u0004, כי עתה אחר שנתגלה כי מלך הגוים אתה \u0003לרדאה לון ולאלקאה לון ולמעבד בהון רעותיה\u0004, לרדותם ולהלקותם ולעשות בהם כרצונו, כי מה שנדמה מקודם לכן שהם רודים בנו, נגלה עתה ההפך, שהם היו רק משמשים ועבדים שלנו. בכדי להביאנו לאמונה שלמה. ומה שנדמה מקודם שהם מלקים אותנו, נגלה עתה ההיפך כי לקו בעצמם, כי עי\"ז מהרו אותנו לבוא לידי השלמות, ומהרו לעצמם את סופם המר כנ\"ל. ובמקום שנדמה שהם מרדו בו ית' ועושים חפצם ורצונם לדכא אותנו למילוי תאותם הרעה ואין דין ואין דיין ח\"ו, נגלה עתה כי עשו רק רצונו ית'. להביאנו אל השלמות. ובזה נתברר כי \u0003מלך הגוים\u0004 אתה מתחילה ועד סוף, שהרי משלת עליהם והכרחת אותם לעשות רצונך תמיד כמלך על עבדיו. ועתה נגלית יראת רוממותך בכל הגוים, וזה שאומר, \u0003מי לא יראך מלך הגוים\u0004."],[4,"בכל חכמי הגוים","שכתוב, הכוונה היא, על השליטים והשרים הממונים עליהם. והם הממונים \u0003עפרירון וקסטימון\u0004 שבארקא, וכן \u0003עזא ועזאל\u0004 וכו' שמהם שואבים חכמי הגוים את חכמתם ומציקים להם לישראל."],[4,"ובכל מלכותם","וכו' \u0003ארבע מלכוון שליטין אית לעילא ושלטין ברעותיה על כל שאר עמין\u0004: ד' מלכויות אלו מרומזות בצלם דחזי נבוכדנצר א) \u0003ראשה די דהב טב\u0004 ב) \u0003חדוהי ודרעוהי די כסף\u0004, ג) \u0003מעוהי וירכתה די נחש,\u0004 ד) \u0003שקוהי די פרזל, רגלוהי מנהון די פרזל ומנהון די חסף\u0004. וד' הללו הן חו\"ב תו\"מ דקליפות, והן שולטות על כל ע' האומות שבעולם."],[4,"","ועם כל זה, אין בהם מי שיעשה אפילו דבר קטן מעצמם, אלא רק כמו שצוית להם. והיינו כמ\"ש לעיל באורך, כי לעת קץ יתגלה, שכל הרידוים והמכות שבכחם הרחיקו את ישראל מאביהם שבשמים, לא היו בזה אלא משמשים נאמנים לקרבם לאביהם שבשמים, באופן שלא עשו משהו אלא כמו שפקדת עליהם לעשות עש\"ה."],[4,"","והיינו כמ\"ש \u0003וכמצביה עביד בחיל שמיא ודיירי ארעא\u0004. דהיינו כדי להביאנו לאמונה שלמה לזכות לקבל כל חסדיו בסו\"ה זכר חסדו ואמונתו לבית ישראל ראו כל אפסי ארץ את ישועת אלהינו, ואז נשבר הצלם, כמ\"ש חזה הוית עד די אתגזרת אבן די לא בידין ומחת לצלמא על רגלוהי די פרזלא וחספא וכו' ונשא המון רוחא וכל אתר לא השתכח להון, ואבנא די מחת לצלמא הות לטור רב ומלאת כל ארעא (דניאל ב'). כי האמונה הקדושה נקראת אבן דלא בידין, ואחר שזכר חסדו ואמונתו, הנה אז נגזרה האי אבן דלא בידין, ומחת לצלמא על רגלוהי, וכו' ונעשה כעור מן עדרי קיט ונשאם הרוח ואינם, ולא נודע מקומם אים. וראו כל אפסי ארץ את ישועת אלהינו. והאי אבנא נעשתה לטור רב ומלאת כל ארעא, ומלאה הארץ דעה את ה', כמים לים מכסים (ישעיה י\"א)."],[5,"","קסז) \u0003אבל בכל חכמי\u0004 וגו': אבל בכל חכמי הגוים ובכל מלכותם, מצאתי זה בספרי הראשונים. אשר הם, המחנות והצבאות שלמעלה, ואע\"פ שהפקדו על עניני העולם, וצוה לכל אחד לעשות עבודתו, מי הוא שיעשה, אף אחד מהם, כמוך. משום שאתה רשום בערכך, ואתה רשום במעשיך מכולם. וזה הוא \u0003מאין כמוך ה'\u0004. מי הוא הסתום הקדוש למעלה ולמטה שיעשה ויהיה כמוך, ויהיה דומה לך, בכל מעשה המלך הקדוש שבשמים ובארץ. אבל הם תהו, וחמודיהם כל יועילו. בהקב\"ה כתוב, בראשית ברא אלקים וגו'. במלכותם כתוב, והארץ היתה תהו ובהו."],[6,"","קסח) \u0003א\"ר שמעון\u0004 וכו': א\"ר שמעון לחברים. בני החתונה הזאת, כל אחד מכם יקשט קשוט אחד לכלה. אמר לר' אלעזר בנו, אלעזר, הן מתנה אחת לכלה, כי למחר יסתכל, ז\"א, כשיכנס לחופה, באלו שירים ושבחות שנתנו לה בני ההיכל, שתעמוד לפניו."],[7,"","קסט) \u0003פתח ר' אלעזר\u0004 וכו': פתח ר\"א ואמר, מי זאת עולה מן המדבר וגו'. \u0003מי זאת\u0004, הוא כלל של שתי קדושות, של שני עולמות, שהם בינה ומלכות, בחבור אחד וקשר אחד. \u0003עולה\u0004, שעולה ממש להיות קדש קדשים, כי \u0003מי\u0004, שהיא בינה, היא קדש קדשים, ונתחברה \u0003בזאת\u0004, שהיא מלכות, בשביל שהמלכות תהיה עולה, שהוא קדש קדשים. \u0003מן המדבר\u0004, היינו כי מן המדבר ירשה זאת, להיות כלה ולהכנס לחופה."],[7,"","פירוש. הכתוב \u0003מי זאת עולה מן המדבר מתרפקת על דודה\u0004 (שיר השירים ח' ה') המדובר הוא בגמר התיקון בשעתא דכלה עאלת לחופה, כמ\"ש להלן."],[7,"","ומפרש \u0003מי זאת\u0004 על הבינה שנקראת מי, ועל המלכות שנקראת \u0003זאת\u0004, ואומר שאז יהיה \u0003מי זאת\u0004 בכללא חדא, \u0003כללא דתרין קדושין\u0004, כי מטרם גמר התיקון נקראת רק הבינה \u0003קדש\u0004, והמלכות העולה אל הבינה מקודשת רק בקדושת הבינה, אבל אז תהיה גם המלכות עצמה קדושה כמו הבינה, ותהיה \u0003מי זאת עולה כללא דתרין קדושין\u0004. משום \u0003דתרין עלמין בחבורא חדא וקשורא חדא\u0004."],[7,"","קשורה היינו הצרורא דחיי, שהוא הסיום של המלכות והמסך המעלה או\"ח ומקשר כל הספירות כאחת, שהיא תסתיים אז בבחינת \u0003י'\u0004 בשוה עם הבינה לנצחיות, שזהו נק' \u0003קשורא חדא. וחבורא חדא\u0004 היינו כי קומת האור של המלכות תהיה מחוברת בקומת הבינה כאחת ממש. כי אז \u0003עולה ממש למהוי קדש קדשין\u0004, שהמלכות עצמה עולה להיות קדש קדשים ממש כמו הבינה,"],[7,"","ואומרו \u0003עולה ממש\u0004, היינו כמו קרבן עולה, שהוא קדשי קדשים. כי \u0003מ\"י\u0004 שה\"ס או\"א הוא קדשי קדשים, והוא נתחבר ב\u0003זאת\u0004 שהיא המלכות, כדי שתהיה המלכות בבחינת עולה שהיא קדשי קדשים. כי אז נעשה חיבור ה\u0003מ\"י\u0004 ב\u0003זאת\u0004 כדי לעשות ה\u0003זאת\u0004 עצמה \u0003לקדש קדשין\u0004. וכיון שכן, הרי אי אפשר עוד שיהיה איזה מיעוט במלכות, אחר שקדושתה עצמה היא \u0003קדש קדשין\u0004 כמו הבינה, וע\"כ בלע המות לנצח."],[7,"","ומ\"ש \u0003דהא מן המדבר ירתא למהוי כלה ולמיעל לחופה\u0004: מדבר היינו מקום נחש שרף ועקרב וכו' וכבר נתבאר לעיל (אות קכ\"ד), אשר בחינת התמכין דאורייתא הם נבחנים בעיקר לעושי התורה עשיה, ונמצא שהזווג הגדול הזה דגמר התיקון נעשה \u0003מן המדבר דוקא\u0004."]],[[0,"","וְעוֹד, שֶׁאַתֶּם אוֹמְרִים (דברים לד) וְלֹא קָם נָבִיא עוֹד בְּיִשְׂרָאֵל כְּמֹשֶׁה, בְּיִשְׂרָאֵל לֹא קָם - אֲבָל בְּאֻמּוֹת הָעוֹלָם קָם. גַּם כָּךְ אֲנִי אוֹמֵר, בְּכָל חַכְמֵי הַגּוֹיִם אֵין כָּמוֹהוּ - אֲבָל בְּחַכְמֵי יִשְׂרָאֵל יֵשׁ. אִם כָּךְ, אֱלוֹהַּ שֶׁיֵּשׁ בְּחַכְמֵי יִשְׂרָאֵל כָּמוֹהוּ, אֵינוֹ הָאֱלוֹהַּ הַשַּׁלִּיט. עַיֵּן בַּפָּסוּק וְתִמְצָא שֶׁדִּיַּקְתִּי כָּרָאוּי."],[1,"","אָמַרְתִּי לוֹ: וַדַּאי יָפֶה אָמַרְתָּ. מִי מְחַיֵּה מֵתִים אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ. בָּא אֵלִיָּהוּ וֶאֱלִישָׁע וְהֶחֱיוּ מֵתִים. מִי מוֹרִיד גְּשָׁמִים אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ. בָּא אֵלִיָּהוּ וּמָנַע אוֹתָם, וְהוֹרִידָם בִּתְפִלָּתוֹ. מִי עָשָׂה שָׁמַיִם וָאָרֶץ אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ. בָּא אַבְרָהָם וְהִתְקַיְּמוּ בְעָמְדָם בִּגְלָלוֹ."],[2,"","מִי מַנְהִיג אֶת הַשֶּׁמֶשׁ אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא. בָּא יְהוֹשֻׁעַ וְהִשְׁתִּיקוֹ וְצִוָּהוּ שֶׁיַּעֲמֹד עַל עָמְדוֹ וְשָׁקַט, וְכָתוּב (יהושע י) וַיִּדּם הַשֶּׁמֶשׁ וְיָרֵחַ עָמָד. הַקָּדוֹשׁ בָּרוּךְ הוּא גּוֹזֵר גְּזַר דִּין - גַּם כָּךְ מֹשֶׁה גָּזַר גְּזַר דִּין וְהִתְקַיֵּם. וְעוֹד, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא גּוֹזֵר גְּזֵרוֹת - וְצַדִּיקֵי יִשְׂרָאֵל מְבַטְּלִים אוֹתָם, שֶׁכָּתוּב (שמואל ב כג) צַדִּיק מוֹשֵׁל יִרְאַת אֱלֹהִים. וְעוֹד, שֶׁהוּא מְצַוֶּה אוֹתָם לָלֶכֶת בִּדְרָכָיו מַמָּשׁ לְהִתְדַּמּוֹת לוֹ בַּכֹּל. הָלַךְ אוֹתוֹ פִּילוֹסוֹף וְהִתְגַּיֵּר בִּכְפַר שַׁחֲלַיִם, וְקָרְאוּ לוֹ יוֹסֵי קְטִינָאָה, וְלָמַד תּוֹרָה הַרְבֵּה, וְהוּא בֵּין חַכְמֵי וְצַדִּיקֵי אוֹתוֹ מָקוֹם."],[3,"","כָּעֵת יֵשׁ לְהִסְתַּכֵּל בַּפָּסוּק, וַהֲרֵי כָּתוּב (ישעיה מ) כָּל הַגּוֹיִם כְּאַיִן נֶגְדּוֹ, מָה הָרִבּוּי כָּאן אֶלָּא, מִי לֹא יִרָאֲךְ מֶלֶךְ הַגּוֹיִם, וְכִי מֶלֶךְ הַגּוֹיִם הוּא, וְלֹא מֶלֶךְ יִשְׂרָאֵל אֶלָּא בְּכָל מָקוֹם הַקָּדוֹשׁ בָּרוּךְ הוּא רָצָה לְהִשְׁתַּבֵּחַ בְּיִשְׂרָאֵל, וְלֹא נִקְרָא - רַק עַל יִשְׂרָאֵל לְבַדָּם, שֶׁכָּתוּב (שמות ה) אֱלֹהֵי יִשְׂרָאֵל אֱלֹהֵי הָעִבְרִים. וְכָתוּב כֹּה אָמַר ה' מֶלֶךְ יִשְׂרָאֵל. מֶלֶךְ יִשְׂרָאֵל בְּוַדַּאי. אָמְרוּ אֻמּוֹת הָעוֹלָם: פַּטְרוֹן אַחֵר לָנוּ בַּשָּׁמַיִם, שֶׁהֲרֵי מַלְכְּכֶם לֹא שׁוֹלֵט אֶלָּא עֲלֵיכֶם לְבַדְּכֶם, וְעָלֵינוּ אֵינוֹ שׁוֹלֵט."],[4,"","בָּא הַפָּסוּק וְאָמַר, מִי לֹא יִרָאֲךְ מֶלֶךְ הַגּוֹיִם (נ\"א: המלך העליון לרדות בהם ולהלקותם ולעשות בהם רצונו, כי לך יאתה, לירא ממך למעלה ולמטה, כי בכל חכמי הגוים) - אֵלֶּה שַׁלִּיטִים גְּדוֹלִים הַמְמֻנִּים עֲלֵיהֶם. וּבְכָל מַלְכוּתָם - בַּמַּלְכוּת הַהִיא שֶׁלְּמַעְלָה, שֶׁהֲרֵי אַרְבַּע מַלְכֻיּוֹת שׁוֹלְטוֹת יֵשׁ לְמַעְלָה, וְשׁוֹלְטוֹת בִּרְצוֹנוֹ עַל כָּל שְׁאָר הָעַמִּים, וְעִם כָּל זֶה אֵין בָּהֶם שֶׁיַּעֲשֶׂה אֲפִלּוּ דָּבָר קָטָן אֶלָּא כְּמוֹ שֶׁצִּוָּה אוֹתָם, כְּמוֹ שֶׁכָּתוּב (דניאל ד) וְכִרְצוֹנוֹ עוֹשֶׂה בִּצְבָא הַשָּׁמַיִם וּבְדַיָּרֵי הָאָרֶץ. חַכְמֵי הַגּוֹיִם - אוֹתָם הַמְמֻנִּים וְהַגְּדוֹלִים שֶׁלְּמַעְלָה שֶׁחָכְמָתָם הִיא מֵהֶם. וּבְכָל מַלְכוּתָם - הַמַּלְכוּת הַשַּׁלֶּטֶת, כְּמוֹ שֶׁנֶּאֱמַר. וְזֶה הַמִּקְרָא כִּפְשׁוּטוֹ."],[5,"","אֲבָל בְּכָל חַכְמֵי הַגּוֹיִם וּבְכָל מַלְכוּתָם - אֶת זֶה מָצָאנוּ בְּסִפְרֵי הָרִאשׁוֹנִים, שֶׁאוֹתָן מֶרְכָּבוֹת וּצְבָאוֹת, אַף עַל גַּב שֶׁנִּתְמַנּוּ עַל דִּבְרֵי הָעוֹלָם וּמִנָּה לְכָל אֶחָד לַעֲשׂוֹת פְּעֻלָּתוֹ, מִיהוּ (נסתר קדוש ולא כרצונו) שֶׁיַּעֲשֶׂה שׁוּם אֶחָד מֵהֶם כָּמוֹךְ בִּגְלַל שֶׁאַתָּה רָשׁוּם בְּעִלּוּי, וְאַתָּה רָשׁוּם בְּמַעַשְׂךְ מִכֻּלָּם. וְזֶהוּ מֵאֵין כָּמוֹךְ ה'. מִיהוּ נִסְתָּר קָדוֹשׁ שֶׁיַּעֲשֶׂה וְיִהְיֶה כָמוֹךְ לְמַעְלָה וּלְמַטָּה וְיִהְיֶה דוֹמֶה לְךְ בַּכֹּל מַעֲשֵׂה הַמֶּלֶךְ הַקָּדוֹשׁ, שָׁמַיִם וָאָרֶץ. אֲבָל הֵם (ישעיה מד) תֹּהוּ וַחֲמוּדֵיהֶם בַּל יוֹעִילוּ. בַּקָּדוֹשׁ-בָּרוּךְ-הוּא כָּתוּב בְּרֵאשִׁית בָּרָא אֱלֹהִים וְכוּ', בְּמַלְכוּתָם כָּתוּב וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ."],[6,"","אָמַר רַבִּי שִׁמְעוֹן לַחֲבֵרִים, בְּנֵי הִלּוּלָא זוֹ, כָּל אֶחָד מִכֶּם יְקַשֵּׁט קִשּׁוּט אֶחָד לַכַּלָּה. אָמַר לְרַבִּי אֶלְעָזָר בְּנוֹ, אֶלְעָזָר, תֵּן מַתָּנָה אַחַת לַכַּלָּה, שֶׁהֲרֵי מָחָר יִסְתַּכֵּל (הקדוש ברוך הוא) (נ\"א: בה) כְּשֶׁיִּכָּנֵס לַחֻפָּה בְּאוֹתָם שִׁירִים וּשְׁבָחִים (אצעדות וצמידים) שֶׁנּוֹתְנִים לָהּ בְּנֵי הַהֵיכָל לַעֲמֹד לְפָנָיו."],[7,"","פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (שיר ג) מִי זאת עֹלָה מִן הַמִּדְבָּר וְגוֹ'. מִי זאת - הַכְּלָל שֶׁל שְׁנֵי קְדוֹשִׁים שֶׁל שְׁנֵי עוֹלָמוֹת בְּחִבּוּר אֶחָד וְקֶשֶׁר אֶחָד - עֹלָה מַמָּשׁ לִהְיוֹת קֹדֶשׁ קָדָשִׁים. שֶׁהֲרֵי קֹדֶשׁ קָדָשִׁים מִ\"י, וּמִתְחַבֵּר עִם זא\"ת כְּדֵי לִהְיוֹת עוֹלָה, שֶׁהִיא קֹדֶשׁ קָדָשִׁים. מִן הַמִּדְבָּר - שֶׁהֲרֵי מִן הַמִּדְבָּר יָרְשָׁה לִהְיוֹת כַּלָּה וּלְהִכָּנֵס לַחֻפָּה. וְעוֹד, מִן הַמִּדְבָּר הִיא עוֹלָה, כְּמוֹ שֶׁנֶּאֱמַר (שיר ד) וּמִדְבָּרֵךְ נָאוֶה. בְּאוֹתוֹ מִדְבָּר שֶׁל לַחַשׁ בַּשְּׂפָתַיִם הִיא עוֹלָה."]]],[["תּוּ מִן הַמִּדְבָּר אִיהִי עוֹלָה כְּמָא דְאַתְּ אָמֵר, (שיר השירים ד׳:ג׳) וּמִדְבָּרֵךְ נָאוֶה בְּהַהוּא מִדְבָּר דִּלְחִישׁוּ בְּשִׂפְוָון אִיהִי עוֹלָה. וְתָנִינָן מַאי דִכְתִיב, (שמואל א ד׳:ח׳) הָאֱלֹהִים הָאַדִּירִים הָאֵלֶּה אֵלֶּה הֵם הָאֱלהִים הַמַּכִּים אֶת מִצְרַיִם בְּכָל מַכָּה בַּמִּדְבָּר. וְכִי כָּל דְּעֲבַד לוֹן קוּדְשָׁא בְּרִיךְ הוּא בַּמִּדְבָּר הֲוָה, וְהָא בְּיִשּׁוּבָא הֲוָה. אֶלָּא בַּמִּדְבָּר, בְּדִבּוּרָא, כְּמָא דְאַתְּ אָמֵר, (שיר השירים ד׳:ג׳) וּמִדְבָּרֵךְ נָאוֶה. וּכְתִיב, (תהילים ע״ה:ז׳) מִמִּדְבַּר הָרִים. אוּף הָכִי עוֹלָה מִן הַמִּדְבָּר, מִן הַמִּדְבָּר וַדַּאי. בְּהַהִיא מִלָּה דְּפוּמָא אִיהִי סַלְקָא וְאָעֳלַת בֵּין גַּדְפֵי דְּאִמָּא, וּלְבָתַר בְּדִבּוּרָא נַחְתָא וְשַׁרְיָא עַל רֵישַׁיְהוּ דְּעַמָּא קַדִּישָׁא.","הֵיךָ סַלְקָא בְּדִבּוּרָא. דְּהָא בְּשֵׁירוּתָא כַּד בַּר נָשׁ קָאִים בְּצַפְרָא אִית לֵיהּ לְבָרְכָא לְמָארֵיהּ. בְּשַׁעְתָּא דְּפָקַח עֵינוֹי הֵיךְ מְבָרֵךְ. הָכִי הֲווּ עַבְדֵי חֲסִידֵי קַדְמָאֵי, נַטְלָא דְמַיָיא הֲווּ יַהֲבֵי קָמַייְהוּ, וּבְזִמְנָא דְּאִתְעָרוּ בְּלֵילְיָא אַסְחָן יְדַיְיהוּ. וְקָיְימֵי וְלָעָאן בְּאוֹרַיְיתָא וּמְבָרְכֵי עַל קְרִיאָתָהּ (וכו'). תַּרְנְגוֹלָא קָרֵי וּכְדֵין פַּלְגוּת לֵילְיָא מַמָּשׁ, וּכְדֵין קוּדְשָׁא בְּרִיךְ הוּא (ס' ב) אִשְׁתַּכַּח עִם צַדִּיקַיָיא בְּגִנְתָא דְעֵדֶן, וְאַסִּיר לְבָרְכָא בִּידַיִן מְסוֹאָבוֹת וּמְזְהָמוֹת. (ומברכין). וְכֵן כָּל שַׁעֲתָא.","בְּגִין דִּבְשַׁעֲתָא דְּבַר נָשׁ נָאִים, רוּחֵיהּ פָּרְחָא מִנֵּיהּ. וּבְשַׁעֲתָא דְּרוּחֵיהּ פָּרְחָא מִנֵּיהּ, רוּחָא מְסָאָבָא זַמִּין וְשָׁרְיָא עַל יְדוֹי וּמְסָאַב לוֹן וְאַסִּיר לְבָרְכָא בְּהוּ בְּלָא נְטִילָה. וְאִי תֵימָא אִי הָכִי הָא בִּימָמָא דְּלָא נָאִים וְלָא פָּרַח רוּחֵיהּ מִנֵּיהּ וְלָא שַׁרְיָא עֲלֵיהּ רוּחָא מְסָאֲבָא וְכַד עָאל לְבֵית הַכִּסֵּא לָא יְבָרֵךְ וְלָא יִקְרָא בַּתּוֹרָה אֲפִלּוּ מִלָּה חָדָא עַד דְּיִסְחֵי יְדוֹי. וְאִי תֵימָא בְּגִין דִּמְלוּכְלָכִים אִנּוּן, לָאו הָכִי הוּא, בַּמֶּה אִתְלַכְלְכוּ.","אֶלָּא וַוי לִבְנֵי עָלְמָא דְּלָא מַשְׁגִּיחִין וְלָא יַדְעִין בְּיִקְרָא דְמָארֵיהוֹן וְלָא יָדְעֵי עַל מַה קָּיְימָא עָלְמָא. רוּחָא חֲדָא אִית בְּכָל בֵּית הַכִּסֵּא דְּעָלְמָא דְּשַׁרְיָא תַּמָּן וְאִתְהַנִּי מֵהַהוּא לִכְלוּכָא וְטִנּוּפָא וּמִיָּד שָׁרֵי עַל אִנּוּן אֶצְבְּעָן דִּידוֹי דְּבַר נָשׁ.","פָּתַח רִבִּי שִׁמְעוֹן וְאָמַר כָּל מָאן דְּחָדֵי בְּאִנּוּן מוֹעֲדַיָּא וְלָא יָהִיב חוּלָקֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, הַהוּא רַע עַיִן שָׂטָן שׂוֹנֵא אוֹתוֹ וְקָא מְקַטְרֵג לֵיהּ וְסָלִיק לֵיהּ מֵעָלְמָא וְכַמָּה עָקוּ עַל עָקוּ מְסַבֵּב לֵיהּ.","חוּלָקֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, לְמֶחדֵי לְמִסְכְּנֵי כְּפוּם מַה דְּיָכִיל לְמֶעְבַּד. בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא בְּיוֹמַיָּיא אִלֵּין אָתֵי לְמֶחמֵי לְאִנּוּן מָאנִין תְּבִירִין דִּילֵיהּ, וְעָאל עָלַיְיהוּ וְחָמֵי דְּלָא אִית לְהוֹן לְמֵחֱדֵי, וּבְכֵי עָלַיְיהוּ. סָלִיק לְעֵילָא (ובעי) לְחָרְבָּא עָלְמָא.","אֲתָאן בְּנֵי מְתִיבְתָּא קַמֵּיהּ וְאָמְרֵי רִבּוֹן עָלְמָא, רַחוּם וְחַנּוּן אִתְקְרִיאַת יִתְגַּלְגְּלוּן רַחֲמָךְ עַל בְּנָךְ. אָמַר לוֹן וְכִי (בני) עָלְמָא לָא (ידעין דלא) עָבְדִית לֵיהּ אֶלָּא עַל חֶסֶ\"ד דִּכְתִיב, (תהילים פ״ט:ג׳) אָמַרְתִּי עוֹלָם חֶסֶד יִבָּנֶה, וְעָלְמָא עַל דָּא קָיְימָא. אָמְרֵי קַמֵּיהּ מַלְאֲכֵי עִלָּאֵי, רִבּוֹן עָלְמָא הָא פְּלַנְיָא דְּאָכִיל וְרָוֵי וְיָכִיל לְמֶעְבַּד טִיבוּ עִם מִסְכְּנִי וְלָא יָהִיב לוֹן מִידִי. אָתֵי הַהוּא מְקַטְרְגָא וּתְבַע רְשׁוּ וּרְדַף אֲבַתְרֵיהּ דְּהַהוּא בַּר נָשׁ.","מָאן לָן בְּעָלְמָא גָּדוֹל מֵאַבְרָהָם דְּעֲבַד טִיבוּ לְכָל בִּרְיָין. בְּיוֹמָא דְּעֲבַד מִשְׁתְּיָיא, מַה כְּתִיב, (בראשית כ״א:ח׳) וַיִּגְדַּל הַיֶּלֶד וַיִּגָּמַל, וַיַּעַשׂ אַבְרָהָם מִשְׁתֶּה גָדוֹל בְּיוֹם הִגָּמֵל אֶת יִצְחָק. עֲבַד אַבְרָהָם מִשְׁתְּיָיא וּקְרָא לְכָל רַבְרְבֵי דָרָא לְהַהִיא סְעוּדָתָא. וְתָנִינָן בְּכָל סְעוּדָתָא דְחֶדְוָה, הַהוּא מְקַטְרְגָא אָזִיל וְחָמֵי אִי הַהוּא בַּר נָשׁ אַקְדִּים טִיבוּ לְמִסְכְּנֵי, וּמִסְכְּנֵי בְּבֵיתָא, הַהוּא מְקַטְרְגָא אִתְפְּרַשׁ מֵהַהוּא בֵּיתָא וְלָא עָאל תַּמָּן, וְאִי לָאו עָאל תַּמָּן. וְחָמֵי עִרְבּוּבְיָא דְּחֶדְוָה בְּלָא מִסְכְּנִי וּבְלָא טִיבוּ דְאַקְדִּים לְמִסְכְּנֵי, סָלִיק לְעֵילָא וּמְקַטְרְגָא עֲלֵיהּ.","אַבְרָהָם כֵּיוָן דְּזָמִּין לְרַבְרְבֵי דָרָא, נָחַת מְקַטְרְגָא וְקָם עַל פִּתְחָא כְּגַוְונָא דְמִסְכְּנָא וְלָא הֲוָה מָאן דְּאַשְׁגַּח בֵּיהּ. אַבְרָהָם הֲוָה מְשַׁמֵשׁ לְאִנּוּן מַלְכִין וְרַבְרְבִין. שָרָה אוֹנִיקַת בְּנִין לְכֻלְּהוּ, דְּלָא הֲווֹ מְהֵמְנִין כַּד אִיהִי אוֹלִידַת אֶלָּא אָמְרוּ אֲסוּפִי הוּא וּמִן שׁוּקָא אַיְתִיאוּ לֵיהּ. בְּגִין כָּךְ אַתְיָין בְּנַיְיהוּ בַּהֲדַיְיהוּ וְנַטְלַת לוֹן שָׂרָה וְאוֹנִיקַת לוֹן קָמַיְיהוּ. הֲדָא הוּא דִכְתִיב, (בראשית כ״א:ז׳) מִי מִלֵּל לְאַבְרָהָם הֵנִיקָה בָנִים שָׂרָה, בָּנִים וַדַּאי. וְהַהוּא מְקַטְרְגָא עַל פִּתְחָא. אָמְרָה (שרה) צְחוֹק עָשָׂה לִי אֱלהִים. מִיָּד סָלִיק הַהוּא מְקַטְרְגָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא וְאָמַר לֵיהּ רִבּוֹן עָלְמָא אַתְּ אֲמַרְתְּ אַבְרָהָם אוֹהֲבִי, (הא אברהם) עֲבַד סְעוּדְתָּא וְלָא יָהַב לָךְ מִידִי, וְלָאו לְמִסְכְּנִי, וְלָא קָרִיב קָדָמָךְ אֲפִילּוּ יוֹנָה חַד. וְתוּ אָמְרַת שָׂרָה דְּחַיְיכַת בָּהּ."],[[0,"","קע) \u0003תו. מן המדבר\u0004 וגו': עוד. מן המדבר היא עולה, כמ\"ש ומדברך נאוה. דהיינו במדבר ההוא של לחש השפתים, היא עולה. כי מדבר, פירושו דבור. ולמדנו מהו שכתוב, האלקים האדירים האלה אלה הם האלקים המכים את מצרים בכל מכה במדבר וכי כל מה שעשה להם הקב\"ה היה במדבר, הלא בישוב היה. אלא במדבר, פירושו, בדבור. כש\"א ומדברך נאוה, וכתוב ממדבר הרים. אף עולה מן המדבר כך, מן המדבר ודאי, דהיינו באותו הדבר של הפה, היא, המלכות, עולה, ונכנסת בין כנפים של האם, שהיא בינה. ולאחר כך, ע\"י דבור היא המלכות יורדת ושורה על ראשי העם הקדוש."],[0,"","ביאור הדברים, כי מטרם גמר התיקון, בעוד שהמלכות נקראת \u0003אילנא דטוב ורע\u0004, הנה כל תיקונה נעשה ע\"י המ\"ן, שהצדיקים מעלים על ידיהן את המלכות לבינה, וע\"י עליה זו נעשית המלכות לשעתה קדושה כבינה. ומ\"ן אלו ה\"ס תפלה בלחש, כי המלכות ה\"ס דבור, ואי אפשר שתהיה בבחינת דיבור טוב בלי רע כלל, רק בעת שהקול שבדיבור הוא מבחינת הבינה, שז\"ס יחוד קול ודיבור, שהם זווג זו\"ן בגדלות."],[0,"","כי הז\"א מקבל קול דאמא ומשפיע בדיבור של המלכות, ואז הדיבור כולו טוב בלי רע כל, ומקבלת המוחין דקודש. אכן בלי המיתוק הזה מהקול דבינה, הנה הקול של המלכות בבחינת טו\"ר כנ\"ל, ויש בה אחיזה לקליפות, ואינה יכולה לקבל מהקודש. ולפיכך נבחנת עלית המ\"ן, שהצדיקים מעלים, בתפלה, שהם ב\u0003לחישו דשפוון\u0004, כלומר, דיבור בלי קול. בסוה\"כ, רק שפתיה נעות וקולה לא ישמע (שמואל א' ב') כי אז אין שום אחיזה במ\"ן שמעלים, ויכולים להעלות גם את המלכות עד הבינה, כדי שתקבל הקול מהבינה, ואז נעשית בנין קדוש ומקבלת מוחין בזווג קול ודיבור, וקדושת הדיבור שלה \u0003שריא על רישייהו\u0004 של הצדיקים שתיקנו אותם כן."],[0,"","וז\"ש \u0003מן המדבר איהי עולה, כד\"א ומדברך נאוה\u0004, כי הכלה אזדמנת עתה לזווג הגדול \u0003למיעל לחופה\u0004 ע\"י עלית מ\"ן של הצדיקים, בסוד \u0003מדברך נאוה\u0004, שהמשיכו בדיבור, שהיא המלכות, את הקול מאמא, ועי\"ז נעשית מדברה של המלכות נאוה ויפה כבינה. כי כל אלו הזווגים שנעשו מקודם בזה אחר זה, נתקבצו עתה לזווג הגדול לעאלא לה לחופה, ונמצא \u0003בההוא מדבר דלחישו בשפוון איהי עולה\u0004 שעל ידי המ\"ן שהעלו מקודם לכן ב\u0003לחישו בשפוון\u0004 דהיינו, בדיבור בלי קול, כי הקול שלה היה עדיין בבחינת טו\"ר כנ\"ל, והמשיכו בה הקול דאמא, הנה מכל אלו המע\"ט נעשה עתה הזווג הגדול לעאלא לה גו חופה, כי עתה נעשה גם קולה עצמה טוב בלי רע כלל, ונעשית \u0003קדש קדשין\u0004 כמו אמא."],[0,"","והנה הדיבור בלחש נבחן ל\u0003מלה דפומא\u0004, כלומר, בלי הצירוף של חיך וגרון ולשון ושנים, אלא רק ע\"י מוצא השפתים ו\u0003פומא\u0004. שיהיה בבחינת קולה לא ישמע כנ\"ל, וז\"ש \u0003בההיא מלה דפומא איהי סלקא\u0004, שכן דרך העלאת מ\"ן, ואז ו\u0003עאלת בין גדפי דאמא\u0004, והיא עולה בין כנפי הבינה. כלומר שמקבלת קול כנפים דאמא לתוך הדיבורים שלה \u0003ולבתר בדבורא נחתא ושריא על רישיהו דעמא קדישא\u0004, ואח\"כ בדיבור שמקבלת, היא יורדת ושורה על ראשי העם קדוש. כי אחר שקבלה הקול דמדת הרחמים דאמא, נעשה \u0003קדש\u0004 כמותה, וקדושתה חוזרת לאלו שתיקנו אותה, ונקראים גם הם עם קדוש כמוה. כי הדיבור שלה הוא עתה קדוש כמו אמא. וז\"ש \u0003בדבורא נחתא\u0004 וכו'."],[1,"","קעא) \u0003איך סלקא בדבורא\u0004 וכו': שואל, איך עולה המלכות בדבור. ומשיב, כי בתחילה, כשאדם קם בבקר, יש לו לברך לאדונו, בשעה שהוא פוקח את עיניו. איך הוא מברך. כך היו עושים החסידים הראשונים. כלי עם מים היו נותנים לפניהם, ובשעה שהיו מתעוררים בלילה, היו רוחצים את ידיהם, ועומדים ועוסקים בתורה, ומברכים על קריאתה. בשעה שתרנגול קורא, ואז חצות לילה ממש, נמצא אז הקב\"ה עם הצדיקים בגן עדן. ואסור לברך בבקר עם ידים טמאות ומזוהמות. וכן בכל שעה."],[1,"","ביאור הדברים, מקשה, כיון דאמרת דתחילת תיקונה של המלכות צריך להיות ב\u0003לחשיו בשפוון\u0004, א\"כ איך תיכף בשעת היקיצה מהשנה אנו מברכים בקול, והיה צריך לברך בלחש כדי להמשיך תחילה הקול מאמא שהוא להעלות המלכות \u0003בדבורא\u0004 בקול דאמא."],[1,"","ומשיב ש\u0003חסידי קדמאי\u0004 תקנו אותו התיקון הנ\"ל בדרך עובדא, כי ענין עלית המ\"ן הוא או בעובדא או במלולא כמ\"ש בזוהר (בחוקותי אות ה'). וע\"כ כיון שבעת שנתו של אדם מסתלק רוחא דקודשא, ורוחא דמסאבא דנחש הקדמוני שורה עליו כי השינה היא א' מששים למיתה. כנודע (ברכות נ\"ז:), והמיתה היא מטומאת הנחש הקדמוני, לכן בעת הקיצו משנתו, עוד לא נתפרש האי רוחא בישא ממנו לגמרי והוא נמצא עוד שורה על ראשי אצבעות הידים שלו, והוא מטעם, כי כל הקדוש ביותר נדבק בו הס\"א ביותר, ואצבעות ידים הן קדושות ביותר משאר הגוף, כי שם מקום השראת החכמה, בסו\"ה וכל אשה חכמת לב בידיה טוו וכו' (שמות ל\"ה), וע\"כ אין הס\"א דבחינת המיתה פורשת משם גם לאחר הקיצה."],[1,"","והוא צריך לעובדא, והוא נטילת ידים, ויש להכין ב' כלים: עליון הנקרא \u0003נטלא\u0004, וכלי תחתון לקבל הזוהמא. והכלי העליון הנקרא \u0003נטלא\u0004, רומז על כלי הבינה, שהס\"א בורח מפני אור הבינה, ונמצא שרחיצת האצבעות ממימי הבינה מבריחין הס\"א משם, ונטהרת המלכות מבחינת הרע שבה, ונשארת טוב, ואז אפשר לעסוק בתורה ולברך על התורה. באופן, שזה העובדא של רחיצת הידים דומה להעלאת מ\"ן ב\u0003לחישו בשפוון\u0004, ל\u0003גדפי דאמא\u0004. ומיושבת בזה הקושיא שהקשה."],[1,"","והנה בעת שהתרנגול קורא, אז הוא חצות לילה ממש. והוא סוה\"כ, את המאור הגדול לממשלת היום ואת המאור הקטן לממשלת הלילה וגו' (בראשית א'). כי השכינה הקדושה נתמעטה בסוד המאור הקטן והתלבשה בקליפות, בסו\"ה ורגליה יורדות מות (משלי ה') דהיינו אילנא דטוב ורע \u0003זכי בר נש הא טוב ואי לא זכי הא רע\u0004, (כנ\"ל אות קכ\"ג ע\"ש). הרי שיש בה ב' פלגין: טוב, ורע, דהיינו פלגא לזכי בה, ופלגא ללא זכי בה."],[1,"","ולפיכך גם ממשלתה שהיא הלילה, נחלקה אחריה ג\"כ לב' פלגין, שפלגא דלילה הראשון הוא מבחינת לא זכי ורע, בסו\"ה תשת חושך ויהי לילה בו תרמוש כל חיתו יער (תהלים ק\"ה). ופלגא דלילה השני הוא מבחינת זכי וטוב. והנה התיקון הראשון לפלגא דטוב, נעשה בנקודת חצות לילה ממש, כי אז מקבלת המלכות את הקול דבינה, דהיינו שהמלכות עולה ונמתקת תוך המלכות דאמא, והדין שבתוך המלכות נעשה דין קדוש מסטרא דטוב בלי רע כלל. והפירוש הוא, שהדין הזה נופל ושורה על הס\"א והוא נעשה רחמים על ישראל."],[1,"","ובזה תבין מ\"ש בזוהר (שלח דף ק\"ג אות רס\"ז) \u0003מבתר פלגא ליליא, שלהובא דעמודא דיצחק נפיק ובטש בהאי תרנגולא דאקרי גבר כגוונא דגבר אחרא עילאה עליה\u0004, יצחק ה\"ס בינה. \u0003ושלהובא דעמודא דיצחק\u0004, ה\"ס דין של הבינה. והמלאך גבריאל נקרא \u0003תרנגולא\u0004 דהיינו \u0003גבר\u0004, שרומז על מדת גבורה, שהוא המשמש ל\u0003גבר עלאה\u0004 מניה, שהוא המלכות דאצילות, סוד המאור הקטן. ואומר, שהדין דבינה \u0003בטש\u0004 תחות כנפים דגבריאל, ונמצאת המלכות מקבלת אז על ידו את הקול דבינה."],[1,"","וז\"ש עו\"ש, (אות רס\"ח) \u0003ובשעתא דאיהו קרי כל תרנגולין דהאי עלמא קראן, ונפיק מניה שלהובא אחרא ומטי לון תחות גדפייהו וקראן\u0004, שבשעה שגבריאל משמיע קול הבינה ל\u0003גבר עלאה\u0004 דהיינו למלכות, הנה אז יוצאת השלהבת מגבריאל \u0003ומטי\u0004 לכל התרנגולים של העוה\"ז, שהם בחינת הדינים שבחלל העוה\"ז, וכולם קוראים רק בהאי קול הנמתק במדת הרחמים מבינה."],[1,"","באופן שבחינת הקול שהיא הדין של המלכות כבר אינה שולטת במחצית הלילה השניה, ומקומה לקח הקול דבינה, שע\"ז מורה קריאת התרנגולים דעוה\"ז. וז\"ש כאן \u0003תרנגולא קרי וכדין פלגות ליליא ממש\u0004 כי קול התרנגול רומז שכבר נתקבל קול הבינה אל המלכות כנ\"ל, ונמצא שאז היא ממש נקודת החצות, שממנה מתחיל \u0003פלגא דליליא\u0004 שהוא טוב בלי רע כלל כנ\"ל."],[1,"","ואחר שהמלכות מקבלת קול הבינה, הצדיקים מעלים מ\"ן ע\"י התורה שעוסקים אחר חצות לילה, והם מעלים אותה עד הגבורות המשמחות דאמא עלאה, ואז נאמר ותקם בעוד לילה (משלי ל\"א), כי היא מתגלית אז בכל הדרה ותפארתה, כי כן דרך המלכות הקדושה להתגלות רק בלילה כמ\"ש בזוהר (פנחס דף רס\"ו, וכן בסבא דמשפטים דף ז' אות ט\"ו). \u0003ואיהי אזלת ביממא ואתגליא בליליא ופלגא בצפרא\u0004."],[1,"","וענין התגלותה הוא רק בגן עדן, דהיינו לאלו הצדיקים המתקנים אותה כן, עם עסק תורתם שלומדים אחר חצות לילה. (כמ\"ש בזוהר לך לך דף קכ\"ג). וזה אמרו כאן \u0003קב\"ה אשתכח עם צדיקייא בגנתא דעדן\u0004. כי השכינה הקדושה נתקנת אז בסוד ג\"ע, בהיותה משתקייא מנחל עדנים שה\"ס חכמה, ומשתעשעת עם הצדיקים שנכללו בה בסוד המ\"ן."],[1,"","וז\"ש, \u0003ואסיר לברכא בידין מסואבות ומזוהמות וכן כל שעתא\u0004: כבר נתבאר זה (לעיל ד\"ה ומשיב), כי הרי רוח מסאבא דנחש הקדמוני נשאר שורה על אצבעותיו של האדם גם אחר שנעור משנתו, ואין זוהמא זו עוברת רק ע\"י רחיצה מכלי ע\"ש. ואומר דכן הוא בכל \u0003שעתא\u0004, דלאו דוקא אחר השינה, אלא כל זוהמא ולכלוכא הוא מקום אחיזה לס\"א ואסור לברכא רק אחר רחיצה במים."],[2,"","קעב) \u0003בגין דבשעתא\u0004 וכו': משום שבשעה שהאדם ישן, רוחו פורח ממנו. ובשעה שהרוח פורח ממנו רוח הטומאה מוכן לו, ושורה על ידיו, ומטמא אותם. ואסור לברך בהן בלא נטילת ידים, ואם תאמר, אם כן, הנה ביום שאינו ישן, ואין הרוח פורח ממנו, ורוח הטומאה אינו שורה עליו, ובכל זאת, כשנכנס לבית הכסא, לא יברך ולא יקרא בתורה אפילו מלה אחת, עד שרוחץ ידיו. ואם תאמר משום שהן מלוכלכות, אין הוא כן, כי במה נתלכלכו."],[3,"","קעג) \u0003אלא ווי לבני\u0004 וכו': אלא אוי להם לבני העולם, שאינם משגיחים ואינם יודעים את כבוד רבונם, ואינם יודעים על מה העולם עומד. הנה רוח אחד יש בכל בית כסא שבעולם, השורה שם ונהנה מאותו הגועל והצואה, ומיד הוא שורה על אותן אצבעות ידיו של האדם."],[4,"","קעד) \u0003פתח ר' שמעון\u0004 וכו': פתח ר\"ש, ואמר, מי ששמח במועדים ואינו נותן חלקו להקב\"ה, אותו רע עין, השטן, שונא אותו ומשטין עליו, ומעבירו מן העולם. וכמה צרות על צרות מסבב לו."],[4,"","ביאור הדברים, כבר נתבאר לעיל (אות ס\"ח ד\"ה איש תהפוכות), כי יש בקליפות דכר ונוקבא, והזכר אינו כל כך רע כמו הנוקבא, והוא אינו מכשיל בני אדם לשקר בשמא דקב\"ה, אלא אדרבה מעוררו לעשות מצוות, אלא שלא בטהרה על מנת להשפיע נ\"ר ליוצרו, רק בעירוב להנאת עצמו, שז\"ס אל תלחם את לחם רע עין וגו', אכול ושתה יאמר לך ולבו בל עמו (משלי כ\"ג)."],[4,"","כי על ידי כך שאין כוונתו להשפיע, נמצאת המצוה בלי טעם ובלי אהבה ויראה, דהיינו בלא לב. אמנם כיון שכבר משך את האדם לרשתו, יש לו כח אח\"ז להזדווג עם הנוקבא שלו דתהומא רבא, שהיא קליפה רעה ומרה, המזייפת בשמא דקב\"ה, ואז נוטלת נשמתו הימנו עש\"ה. וזה אמרו \u0003ההוא רע עין שטן שונא אותו וקא מקטרג ליה וסליק ליה מעלמא\u0004 כי אחר שהכשילו במצות שמחת יו\"ט שלא יהיה להשפיע נ\"ר ליוצרו, כי זה נראה מתוך שאוכל לבדו ואינו מהנה לעניים, הנה אח\"כ מזדווג עם הנוקבא שלו ונוטל נשמתו."],[5,"","קעה) \u0003חולקיה דקב\"ה למחדי\u0004 וכו': חלקו של הקב\"ה הוא, לשמח את העניים, כפי מה שיכול לעשות. כי בימים האלו, במועדים, הקב\"ה בא לראות את אלו כלים השבורים שלו. ונכנס אליהם, ורואה, שאין להם במה לשמוח. ובוכה עליהם, ועולה למעלה להחריב העולם."],[5,"","הנה כדי להבין מאמר זה, וענין הקטרוג דמלאכי עלאי, צריכים להבין מקודם מדרש חז\"ל (מ\"ר פ\"ו) שבעת בריאת העולם, כשאמר למלאכים נעשה אדם בצלמנו, הנה חסד אמר יברא, מפני שהוא גומל חסדים. אמת אמר אל יברא מפני שכולו שקרים, צדק אמר יברא, מפני שעושה צדקות, ושלום אמר אל יברא, מפני שכולו קטטה, מה עשה הקב\"ה נטל האמת והשליכו לארץ, הה\"ד ותשלך אמת ארצה (דניאל ח') ע\"ש."],[5,"","פירוש, כי נודעו דברי חז\"ל, שלעולם יעסוק אדם בתורה ובמצות אע\"פ שלא לשמה שמתוך שלא לשמה בא לשמה (פסחים נ:) כי האדם מתוך שפלותו אי אפשר לו לעסוק תיכף בהתחלה במצותיו ית' כדי להשפיע נ\"ר ליוצרו, כי ועייר פרא אדם יולד (איוב י\"א) ואי אפשר לו מטבעו לעשות איזו תנועה אם לא לטובת עצמו, לכן הוא מוכרח מתחילה לעסוק במצות שלא לשמה, דהיינו מתוך תועלת עצמו, אבל עכ\"ז ממשיך שפע קדושה תוך מעשי המצות, אשר ע\"י השפע שממשיך, סופו לבא לעסוק במצות לשמה, דהיינו בכדי לעשות נ\"ר ליוצרו."],[5,"","וזה שקטרג האמת על בריאת האדם, שאמר שכולו שקרים. כי נתרעם, איך אפשר לברוא אדם כזה מלכתחילה שיעסוק בתורה ומצות בשקר גמור, דהיינו שלא לשמה. אבל חסד אמר יברא, מפני שהוא גומל חסד, כי מצות גמילות חסדים שעושה, שהוא בהכרח מעשה מבוררת להשפיע, הנה על ידיה נמצא מתתקן לאט לאט, עד שיוכל לעסוק בכל המצות ע\"מ להשפיע. וא\"כ, הוא בטוח בסופו להגיע למטרתו לעסוק לשמה, וע\"כ טען החסד, שיש לבראו."],[5,"","וכן השלום קטרג שכולו קטטה, כיון שאי אפשר לו לעסוק במצות ע\"מ להשפיע, אלא עם עירוב של הנאת עצמו, הנה ע\"י זה נמצא תמיד בקטטה עם השי\"ת, כי נדמה לו שהוא צדיק גמור, ואינו מרגיש כלל בחסרונותיו, דהיינו שאינו מרגיש שכל עסקו בתורה ומצות הוא שלא לשמה, והולך ומתרעם ח\"ו על השי\"ת, שאין מטיבין עמו כמו שצריכין להטיב עם צדיק גמור. ונמצא פוסח על ב' הסעיפים, פעם הוא בשלום עמו ית' ופעם הוא במחלוקת ח\"ו, ולכן טען השלום שאינו כדאי להבראות."],[5,"","אבל צדק אמר יברא, שהוא עושה צדקות, כי מחמת מצות צדקה לעניים שעושה. נמצא לאט לאט מתקרב אל מדת השפעה עד שבא לעסוק לשמה, ויזכה לשלום תמידי עם השי\"ת, וע\"כ יברא. ואחר שנשמעו טענותיהם של אלו ואלו, הסכים הקב\"ה עם מלאכי חסד וצדק, והשליך אמת ארצה. כלומר שהתיר לעסוק במצות מלכתחילה שלא לשמה אע\"פ שהוא שקר, ונמצא השליך אמת לארץ, והוא מטעם שקבל טענת חסד וצדק. שע\"י מצות גמילות חסדים ומצות צדקה למסכני, סופו לבא לאמת, דהיינו לעבוד את הש\"י רק בכדי לעשות נ\"ר אליו. כי סופו לבא לשמה, ואז תעלה האמת מן הארץ."],[5,"","והנה גם ז\"ס שבירת הכלים, שהיתה קודם בריאת העולם, כי ע\"י שבירת הכלים דקדושה ונפילתם לבי\"ע דפרודא, נפלו עמהם ניצוצין דקדושה לקליפות, שמהם באו עניני תענוגות ואהבות מכל המינים לרשותם של הקליפות שהם מעבירים אותן לקבלת האדם ולהנאתו. והם גורמים בזה לכל מיני עברות כמו גנבה גזלה ורציחה. אמנם יחד עם זה נתן לנו תורה ומצות אשר אפילו אם מתחיל לעסוק בהם עוד מתוך שלא לשמה, דהיינו להנאתו עצמו למלאות תאותיו השפלות, כפי כחות שבירת הכלים, הנה סופו יבא על ידם לשמה, ויזכה למטרת הבריאה, דהיינו לקבל כל הנועם והטוב שבמחשבת הבריאה בכדי להשפיע לו נ\"ר כנ\"ל."],[5,"","וזה אמרו \u0003קב\"ה ביומייא אלין אתי למחמי לאינון מאנין תבירין דיליה\u0004, כי בימים טובים, שהאדם מקיים מצות שמחת יו\"ט מרוב השפע שנתן לו השי\"ת, הנה אז הולך הקב\"ה לראות את הכלים הנשברים שלו, שעל ידיהם ניתנת לאדם הזדמנות לעסוק במצות שלא לשמה כנ\"ל, והולך לראות כמה גמרו את תפקידם להביא את האדם לידי לשמה."],[5,"וחמי דלא אית להון למחרי ובכי עלייהו",". ורואה שאין להם, \u0003למאנין תבירין\u0004, במה לשמוח, והוא בוכה עליהם. כי רואה שלא נברר עוד מהם כלום, דהיינו שלא הביאו את האדם כלל לידי לשמה, אלא שעוסק בשמחת יו\"ט רק להנאת עצמו לבדו, הנה אז \u0003בכי עלייהו\u0004, כלומר, שכביכול מתחרט עליהם על מה ששיבר אותם, כי לא שיבר אותם, וכן לא השליך האמת ארצה, אלא לטובת האדם שיוכל להתחיל לעבוד שלא לשמה, ואח\"כ יבוא לשמה, וכשהוא רואה שהאדם עוד לא זז משהו מתאותו עצמו, א\"כ שבר אותם בחנם, ובוכה עלייהו."],[5,"סליק לעילא לחרבא עלמא",", כביכול עולה אז לסלק השפע מהעולם ולהחריב העולם, כי בעת שאין השלא לשמה ראוי להביא האדם לשמה, נמצא שהשפע עצמו הוא לרע לו, כי הוא נטבע על ידו יותר תוך קליפת הקבלה. וא\"כ מוטב בשביל האדם להפסיק לו השפע ולהחריבה לגמרי."],[6,"","קעו) \u0003אתאן בני מתיבתא\u0004 וכו': באים לפניו בני הישיבה, ואומרים, רבון העולם, רחום וחנון אתה נקרא, יתגלגלו רחמיך על בניך. אמר להם: וכי לא עשיתי את העולם אלא על חסד, שכתוב, אמרתי עולם חסד יבנה. והעולם עומד על זה. ואם אינם עושים חסד עם העניים אחריב את העולם. אומרים המלאכים העליונים לפניו: רבון העולם, הנה פלוני, שאכל ושתה לרויה, ויכול לעשות חסד עם העניים, ולא נתן להם כלום. בא המשטין, ולוקח רשות, ורודף אחרי האדם ההוא."],[6,"","פירוש. הנשמות העליונות הנקראות \u0003בני מתיבתא\u0004, מתחילות אז להתפלל על התחתונים שלא יפסיק השפע מהם ויש לו לרחם על בניו, כי מלמדים זכות לפניו ית', ואומרים כיון שעושים מצותיו באמונה, הם נקראים בנים למקום, וע\"כ ראוים לרחמים כרחם אב על בנים. והשיב להם הקב\"ה, הלא לא בניתי העולם אלא על ה\u0003חסד\u0004, דכתיב וכו', והעולם רק על \u0003חסד\u0004 עומד."],[6,"","כלומר כי לא יגיע להם שום תיקון ע\"י השפע בעת שאין מהנים למסכנא, כי בריאת העולם היתה על מה שהסכמתי למלאכי חסד, שע\"י עשית חסד איש לרעהו יתקיים עלמא, ויבואו לידי לשמה, ועתה שאינם עושים חסד, לא יצמח מזה שום תיקון."],[6,"","ואז אמרו לפניו מלאכי עליון: רבונו של עולם, הרי פלוני שאכל ושבע, והוא יכול לעשות חסד עם עניים, ואינו נותן להם כלום. פירוש, כי אז גם המלאכים העליונים התחילו עתה לקטרג על הבריאה דהיינו מלאכי חסד וצדקה וכל אלו שהסכימו לבריאה, כי לא הסכימו לבריאה בדרך זה של שלא לשמה אלא כדי שיעשה חסד וצדקה ויבואו על ידם לידי לשמה, ועתה שאינם עושים זאת, ואינם ראוים לבוא לשמה, הם מתחרטים על הסכמתם ומקטרגים על האדם. ואז \u0003אתי ההוא מקטרגא ותבע רשו ורדף אבתריה דההוא בר נש\u0004, כי אחר שנתברר שאין האדם ראוי לבוא עוד לשמה עם המצות שלו, אז ניתנת רשות למקטרג לעשות את שלו."],[7,"","קעז) \u0003מאן לן בעלמא\u0004 וכו': מי לנו בעולם גדול מאברהם, שעשה חסד לכל הבריות. ביום שעשה משתה מה כתוב, ויגדל הילד ויגמל ויעש אברהם משתה גדול ביום הגמל את יצחק. עשה אברהם משתה וקרא לכל גדולי הדור לאותה הסעודה. ולמדנו בכל סעודה של שמחה, הולך ורואה אותו המשטין: אם האדם ההוא הקדים לעשות חסד עם העניים, ואם יש עניים בבית, המשטין נפרד מאותו הבית, ואינו נכנס שמה. ואם לא, המשטין נכנס שמה, והוא רואה הערוב של השמחה בלא עניים, ובלי שהקדים חסד לעניים, עולה למעלה ומשטין עליו."],[8,"","קעח) \u0003אברהם, כיון דזמין\u0004 וכו': אברהם כיון שהועיד לגדולי הדור, ירד המשטין וקם על הפתח כעין עני. ולא היה מי שיביט עליו, אברהם היה משמש את המלכים והשרים, שרה הניקה הבנים מכולם, משום שלא היו מאמינים כאשר ילדה, אלא אמרו שיצחק הוא אסופי, שמן השוק הביאו אותו. משום זה הביאו את בניהם עמהם, ושרה לקחה אותם, והניקה אותם לפניהם. ז\"ש מי מלל לאברהם הניקה בנים שרה. והיה צריך לומר הניקה בן, שרה, אלא בנים ודאי, דהיינו בניהם של כל האורחים. ואותו המשטין עמד בפתח. אמרה שרה צחוק עשה לי אלקים. מיד עלה המשטין לפני הקב\"ה, ואמר לו: רבון העולם, אתה אמרת אברהם אוהבי, הנה עשה סעודה ולא נתן לך מאומה, ולא לעניים, ולא הקריב לפניך אפילו יונה אחת. ועוד, הנה שרה אומרת, שצחקת בה."],[8,"","יש להבין זה, הרי הוא שנצטיין בעיקר בהכנסת אורחים ובחסד, וכל יומוי הוה קאים בפרשת אורחין, לזמן אושפיזין (כמ\"ש בזוהר אמור דף קע\"א אות רע\"ט). ואיך אפשר שיהיה נכשל בדבר זה, שלא ליתן צדקה למסכנא. ועוד למה הטריח עצמו המקטרג להתחפש כמו מסכנא, שאין דרכו בזה לגבי אחרים. אמנם כאן אינו כפשוטו, ויש בזה סוד גדול, שאינו נוהג אלא בקדישין עליונין."],[8,"","ועיין בזוהר (פקודי דף ק\"ו אות שכ\"ט). וז\"ל, \u0003אמר ר\"ש אע\"ג\u0004 וכו' \u0003ורוח מסאבא בעי לאכפייא ליה בכל סטרין. תא ואימא לך רזא חדא ולא אתייהיב לגלאה בר לאינון קדישי עליונין\u0004 וכו' \u0003דבעינן גו רזא דתפילין לאצנעא חד שערא דעגלא דיפוק לבר ויתחזי\u0004, וכו' \u0003וההוא שערא בעי לעאלא ליה בגו קדושה עלאה דילן\u0004 וכו' \u0003כדין לא יקטרג ליה ולא יכיל לאבאשא ליה לעילא ותתא. דהא דוכתא יהיב ליה. ואי ההוא חולקא לא יהבין ליה בהאי קדושה, יכיל לאבאשא ליה לתתא וסליק מקטרגא ליה לעילא\u0004. וכו'."],[8,"","פירוש, כי מטרם גמר התיקון אי אפשר להעביר הס\"א לגמרי, ואפילו הצדיקים והקדושים העליונים, וכמה שהצדיק נזהר לעשות המצוה בטהרה, הנה נשאר עוד כח לס\"א לקטרג עליו, ולהראות מקום חסרון במצוה. ולפיכך הכין השי\"ת בשביל הצדיקים אופן אחר להכניע ולסתום פה המקטרג. והוא, ליתן חלק מועט מהקדושה אל המקטרג הזה שנשאר, שבשביל זה נסתם פיו של המקטרג, ואינו רוצה לקטרג עליו כדי שלא יאבד חלקו מהקדושה שיש לו מאותה מצוה. שה\"ס השערה שאנו נותנים בתפילין. וה\"ס שעיר המשתלח, וה\"ס פרה אדומה. עש\"ה. ועוד תמצא ענין זה בזוהר (אמור דף פ\"ח)."],[8,"","וז\"ש כאן \u0003נחת מקטרגא וקם על פתחא בגוונא דמסכנא ולא הוה מאן דאשגח ביה\u0004. כי לכל העניים ודאי שהאכיל אותם מסעודתו כדרכו בהכנסת אורחים תמיד, רק האי מקטרגא הנ\"ל, שאינו מועיל שום טהרה להעבירו זולת להנות אותו מעט מהקדושה כנ\"ל, שהיה כאן בבחינת המסכנא, כי רצה לקבל חלקו מהקדושה. אבל אברהם לא רצה להנות לס\"א אף משהו מהקדושה, אלא שרצה להכניעו בכחו ולדחותו לגמרי, ולפיכך עלה וקטרג כמ\"ש להלן. וז\"ש הזוהר \u0003נחת מקטרגא כגוונא דמסכנא\u0004, שלא היה עני ממש אלא המדובר הוא במקטרג שהתחפש כמו עני, ותבע להנות אותו מסעודתו של אברהם כמבואר. אבל אברהם הרגיש בו שהוא מבחינת הס\"א, וע\"כ לא רצה ליתן לו כלום."],[8,"","וז\"ש, \u0003אפילו יונה חד\u0004 כי יש בזה רמז נכבד, כי בסדר הקרבנות באים רק שני בני יונה, כנגד ב' נקודות הכלולות יחד במלכות הממותקת במדת הרחמים, שיש בה דין ורחמים יחד, והדין שבה גניזא וטמירא, והרחמים שבה קיימא באתגליא, (כנ\"ל אות קכ\"ב) כי לולא המיתוק הזה לא היה העולם יכול להתקיים כנ\"ל. וע\"כ אין להקריב רק ב' בני יונה, ותדע, שסוד \u0003יונה חד\u0004 ה\"ס היונה ששלח נח מן התיבה ולא יספה שוב אליו עוד (בראשית ח') כי \u0003יונה חד\u0004 רומזת למדת הדין שבמלכות בלי מיתוק במדת הרחמים, וכיון שנח לא יכול לתקן בה שום תיקון ע\"כ לא יספה לשוב אליו עוד. (עי' בזוהר שלח דף נ\"ב)."],[8,"","וכבר נתבאר ענין המקטרג שתבע חלקו מסעודתיה דאברהם ביום הגמל את בנו, שהוא ענין תיקון חסרון, אשר אי אפשר לתקנו מטרם גמר התיקון בדרך אחר, (כנ\"ל בדיבור הסמוך) ותדע, שה\"ס מדת הדין שבמלכות, שאין העולם יכול להתקיים בה, והיא צריכה להיות גניזא וטמירא, שהיא ג\"כ סוד היונה, אשר לא יספה לשוב אל נח כנ\"ל. אמנם אברהם היה יכול לתקנה, והיה מוטל עליו לתקנה, דהיינו בדרך למיהב מידי למקטרג למסתם פומיה, (כנ\"ל בדיבור הסמוך). וכיון שלא נתן לו למקטרג כלום, לכן עלה וקטרג."],[8,"","וז\"ש \u0003ולא יהיב לך מידי, ולאו למסכני\u0004, כי קטרג שבכל סעודתו זו לא תיקן כלום למדת הדין שבמלכות, שהיא נקראת מסכנא, דלית לה מגרמה ולא מידי, והוא אמנם חולקא דקב\"ה, כי היא עצם המלכות נוקבא דז\"א, שהוא קב\"ה. שהרי לא המתיק אותה במדת הרחמים אלא לצורך קיום העולם, וע\"כ המוחין הנמשכים ע\"י מדת הרחמים, נבחנים כמו חלק של בני העולם, שעל ידי זה יתקנו גם עצם המלכות שהיא חולקא דקב\"ה לבדו."],[8,"","וכיון שע\"י הנס הגדול ד\u0003הניקה בנים שרה\u0004 המשיך אברהם כל המוחין שבמדת הרחמים, כבר היה סיפק בידו לתקן גם בחינת המסכנא שבמלכות, שהיא חולקא דקב\"ה, לכן קטרג \u0003ולא יהיב לך מידי\u0004 היינו חולקיה דקב\"ה. \u0003ולאו למסכנא\u0004 היינו חלקה של עצם המלכות שהיא במסכנותא, שאין בני העולם יכולים לתקן בה, \u0003ולא קריב קדמך אפילו יונה חד\u0004 היינו היונה, שנח לא היה יכול לתקן אותה כנ\"ל."],[8,"ותו אמרת שרה דחייכת בה",", כי שרה ה\"ס בינה ומדת הרחמים המאירה במלכות, ובאמירתה, \u0003צחוק עשה לי אלהים כל השומע יצחק לי\u0004 המשיכה בזה אור שלם ומיתוק גדול מאד, עד שלא נראתה עוד כל בחינת חסרון בעצם מדת המלכות, ונעשה חשש גדול שמא לא תשאר מחמת זה שום תשומת לב לתקן את עצם המלכות. והוא דומה לסוה\"כ פן ישלח וגו' מעץ החיים ואכל וחי לעולם (בראשית ג'), דהיינו שלא ירגיש עוד בעצמו שום חסרון ולא יהיה מוכרח לתקן את הפגם שבעץ הדעת."]],[[0,"","וְשָׁנִינוּ, מַהוּ שֶׁכָּתוּב (שמואל א ד) הָאֱלֹהִים הָאֵלֶּה אֵלֶּה הֵם הָאֱלֹהִים הַמַּכִּים אֶת מִצְרַיִם בְּכָל מַכָּה בַּמִּדְבָּר, וְכִי כָּל מַה שֶּׁעָשָׂה לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא בַּמִּדְבָּר הָיָה וַהֲרֵי בַּיִּשּׁוּב זֶה הָיָה! אֶלָּא בַּמִּדְבָּר - בְּדִבּוּר, כְּמוֹ שֶׁנֶּאֱמַר (שיר ד) וּמִדְבָּרֵךְ נָאוֶה, וְכָתוּב (תהלים עה) מִמִּדְבַּר הָרִים. גַּם כָּךְ עֹלָה מִן הַמִּדְבָּר - מִן הַמִּדְבָּר וַדַּאי. בְּאוֹתוֹ דָּבָר שֶׁל הַפֶּה הִיא עוֹלָה וְנִכְנֶסֶת בֵּין כַּנְפֵי הָאִמָּא, וְאַחַר כָּךְ בַּדִּבּוּר יוֹרֶדֶת וְשׁוֹרָה עַל רָאשֵׁי הָעָם הַקָּדוֹשׁ."],[1,"","אֵיךְ עוֹלָה בְּדִבּוּר שֶׁהֲרֵי בַּהַתְחָלָה, כְּשֶׁבֶּן אָדָם קָם בַּבֹּקֶר, יֵשׁ לוֹ לְבָרֵךְ לְרִבּוֹנוֹ בְּשָׁעָה שֶׁפָּקַח עֵינָיו. אֵיךְ מְבָרֵךְ כָּךְ הָיוּ עוֹשִׂים חֲסִידִים רִאשׁוֹנִים: נַטְלָה שֶׁל מַיִם הָיו נוֹתְנִים לִפְנֵיהֶם, וּבִזְמַן שֶׁמִּתְעוֹרְרִים בַּלַּיְלָה, רוֹחֲצִים יְדֵיהֶם, וְעוֹמְדִים וְעוֹסְקִים בַּתּוֹרָה וּמְבָרְכִים עַל קְרִיאָתָהּ. וּכְשֶׁהַתַּרְנְגוֹל קוֹרֵא, אָז חֲצוֹת הַלַּיְלָה מַמָּשׁ, וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא נִמְצָא עִם הַצַּדִּיקִים בְּגַן עֵדֶן. וְאָסוּר לְבָרֵךְ בְּיָדַיִם טְמֵאוֹת וּמְזֹהָמוֹת, (ומברכים), וְכָךְ כָּל שָׁעָה."],[2,"","בִּגְלַל שֶׁבְּשָׁעָה שֶׁבֶּן אָדָם יָשֵׁן, רוּחוֹ פּוֹרַחַת מִמֶּנּוּ. וּבְשָׁעָה שֶׁרוּחוֹ פּוֹרַחַת מִמֶּנּוּ, רוּחַ טֻמְאָה מְזֻמֶּנֶת וְשׁוֹרָה עַל יָדָיו וּמְטַמֵּאת אוֹתָם, וְאָסוּר לְבָרֵךְ בָּהֶם לְלֹא נְטִילָה. וְאִם תֹּאמַר, אִם כָּךְ, הֲרֵי בַּיּוֹם כְּשֶׁאֵינֶנּוּ יָשֵׁן וְרוּחוֹ לֹא פוֹרַחַת מִמֶּנּוּ וְלֹא שׁוֹרָה עָלָיו רוּחַ טֻמְאָה, וּכְשֶׁנִּכְנָס לְבֵית הַכִּסֵּא לֹא יְבָרֵךְ וְלֹא יִקְרָא בַתּוֹרָה אֲפִלּוּ דָבָר אֶחָד עַד שֶׁיִּרְחַץ יָדָיו! וְאִם תֹּאמַר בִּגְלַל שֶׁהֵם מְלֻכְלָכִים - לֹא כָּךְ הוּא, בַּמָּה הִתְלַכְלְכוּ"],[3,"","אֶלָּא אוֹי לִבְנֵי הָעוֹלָם שֶׁלֹּא מַשְׁגִּיחִים וְלֹא יוֹדְעִים עַל כְּבוֹד רִבּוֹנָם וְלֹא יוֹדְעִים עַל מָה עוֹמֵד הָעוֹלָם. יֵשׁ רוּחַ אֶחָד בְּכָל בֵּית כִּסֵּא שֶׁבָּעוֹלָם שֶׁשָּׁם שׁוֹרֶה וְנֶהֱנֶה מֵאוֹתוֹ לִכְלוּךְ וְטִנֹּפֶת, וּמִיָּד שׁוֹרֶה עַל אוֹתָן אֶצְבְּעוֹת יְדֵי הַבֶּן אָדָם."],[4,"","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, כָּל מִי שֶׁשָּׂמֵחַ בְּאוֹתָם הַמּוֹעֲדִים וְלֹא נוֹתֵן חֵלֶק לַקָּדוֹשׁ-בָּרוּךְ-הוּא, אוֹתוֹ רַע עַיִן, שָׂטָן שׂוֹנֵא אוֹתוֹ וּמְקַטְרֵג עָלָיו וּמְסַלְּקוֹ מֵהָעוֹלָם, וְכַמָּה צָרוֹת עַל צָרוֹת מְסוֹבֵב לוֹ."],[5,"","חֵלֶק הַקָּדוֹשׁ בָּרוּךְ הוּא לְשַׂמֵּחַ עֲנִיִּים כְּפִי מַה שֶּׁיָּכוֹל לַעֲשׂוֹת. בִּגְלַל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בְּיָמִים אֵלּוּ בָּא לִרְאוֹת אוֹתָם כֵּלִים שְׁבוּרִים שֶׁלּוֹ, וְנִכְנָס עֲלֵיהֶם, וְרוֹאֶה שֶׁאֵין לָהֶם לִשְׂמֹחַ, וּבוֹכֶה עֲלֵיהֶם. עוֹלֶה לְמַעְלָה וְרוֹצֶה לְהַחֲרִיב אֶת הָעוֹלָם,"],[6,"","בָּאִים בְּנֵי הַיְשִׁיבָה לְפָנָיו וְאוֹמְרִים: רִבּוֹן הָעוֹלָם, רַחוּם וְחַנּוּן נִקְרֵאתָ, יִתְגַּלְגְּלוּ רַחֲמֶיךְ עַל בָּנֶיךְ! אָמַר לָהֶם: וְכִי הָעוֹלָם לֹא עֲשִׂיתִיהוּ אֶלָּא עַל חֶסֶד, שֶׁכָּתוּב (תהלים פט) אָמַרְתִּי עוֹלָם חֶסֶד יִבָּנֶה, וְהָעוֹלָם עַל זֶה קַיָּם. אוֹמְרִים לְפָנָיו הַמַּלְאָכִים הָעֶלְיוֹנִים: רִבּוֹן הָעוֹלָם, הֲרֵי פְּלוֹנִי שֶׁאָכַל וְשָׁתָה וְיָכוֹל לַעֲשׂוֹת חֶסֶד עִם הָעֲנִיִּים וְלֹא נָתַן לָהֶם דָּבָר. בָּא אוֹתוֹ מְקַטְרֵג וּמְבַקֵּשׁ רְשׁוּת, וְרוֹדֵף אַחַר אוֹתוֹ אִישׁ."],[7,"","מִי לָנוּ בָּעוֹלָם גָּדוֹל מֵאַבְרָהָם שֶׁעָשָׂה חֶסֶד לְכָל הַבְּרִיּוֹת. בַּיּוֹם שֶׁעָשָׂה מִשְׁתֶּה מַה כָּתוּב (בראשית כא) וַיִּגְדַּל הַיֶּלֶד וַיִּגָּמַל וַיַּעַשׂ אַבְרָהָם מִשְׁתֶּה גָדוֹל בְּיוֹם הִגָּמֵל אֶת יִצְחָק. עָשָׂה אַבְרָהָם מִשְׁתֶּה וְקָרָא לְכָל גְּדוֹלֵי הַדּוֹר לְאוֹתָהּ סְעוּדָה. וְלָמַדְנוּ, בְּכָל סְעוּדַת שִׂמְחָה אוֹתוֹ מְקַטְרֵג הוֹלֵךְ וְרוֹאֶה. אִם אוֹתוֹ אָדָם הִקְדִּים חֶסֶד לַעֲנִיִּים וְהָעֲנִיִּים בַּבַּיִת - אוֹתוֹ מְקַטְרֵג נִפְרָד מֵאוֹתוֹ בַּיִת וְלֹא נִכְנָס שָׁם. וְאִם לֹא - נִכְנָס לְשָׁם וְרוֹאֶה עִרְבּוּבְיָה שֶׁל שִׂמְחָה בְּלִי עֲנִיִּים וּבְלִי חֶסֶד שֶׁהִקְדִּים לָעֲנִיִּים, עוֹלֶה לְמַעְלָה וּמְקַטְרֵג עָלָיו."],[8,"","כֵּיוָן שֶׁהִזְמִין אַבְרָהָם אֶת גְּדוֹלֵי הַדּוֹר, יָרַד הַמְקַטְרֵג וְעָמַד עַל הַפֶּתַח כְּמוֹ עָנִי, וְלֹא הָיָה מִי שֶׁיַּשְׁגִּיחַ בּוֹ. אַבְרָהָם הָיָה מְשַׁמֵּשׁ אֶת אוֹתָם הַמְּלָכִים וְהַגְּדוֹלִים. שָׂרָה הֵינִיקָה בָנִים לְכֻלָּם, שֶׁלֹּא הָיוּ מַאֲמִינִים כְּשֶׁהוֹלִידָה, אֶלָּא אָמְרוּ, אֲסוּפִי הוּא, וְהֵבִיאוּ אוֹתוֹ מִן הַשּׁוּק. מִשּׁוּם כָּךְ הֵבִיאוּ אֶת בְּנֵיהֶם עִמָּם, וְנָטְלָה אוֹתָם שָׂרָה וְהֵינִיקָה אוֹתָם לִפְנֵיהֶם. זֶהוּ שֶׁכָּתוּב (שם) מִי מִלֵּל לְאַבְרָהָם הֵינִיקָה בָנִים שָׂרָה. בָּנִים וַדַּאי. וְהַמְקַטְרֵג הַהוּא עַל הַפֶּתַח. אָמְרָה שָׂרָה, צְחֹק עָשָׂה לִי אֱלֹהִים. מִיָּד עָלָה הַמְקַטְרֵג הַהוּא לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאָמַר לוֹ: רִבּוֹן הָעוֹלָם, אַתָּה אָמַרְתָּ אַבְרָהָם אוֹהֲבִי, עָשָׂה סְעוּדָה וְלֹא נָתַן לְךְ דָּבָר וְלֹא לָעֲנִיִּים, וְלֹא הִקְרִיב לְפָנֶיךְ אֲפִלּוּ יוֹנָה אַחַת. וְעוֹד, אָמְרָה שָׂרָה שֶׁצָּחַקְתָּ בָּהּ."]]],[["אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא מָאן בְּעָלְמָא כְּאַבְרָהָם. וְלֹא זָז מִתַּמָּן, עַד דְּבִלְבֵּל כָּל הַהִיא חֶדְוָה, וּפַקִּיד קוּדְשָׁא בְּרִיךְ הוּא לְמִקְרַב לְיִצְחָק קָרְבְּנָא, וְאִתְגְּזַר עַל שָׂרָה דְּתָמוּת עַל צַעֲרָא דִּבְרָהּ. כָּל הַהוּא צַעֲרָא גָּרִים, דְּלָא יָהִיב מִידִי לְמִסְכְּנֵי.","פָּתַח רִבִּי שִׁמְעוֹן וְאָמַר מַאי דִכְתִיב, (ישעיהו ל״ח:ב׳) וַיַּסֵּב חִזְקִיָּהוּ פָּנָיו אֶל הַקִּיר וַיִּתְפַּלֵּל אֶל ה'. תָּא חֲזֵי, כַּמָּה הוּא חֵילָא תַּקִּיפָא דְאוֹרַיְיתָא, וְכַמָּה הוּא עִלָּאָה עַל כֹּלָא. דְּכָל מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא לָא דָּחִיל מֵעִילָּאֵי וּמִתַּתָּאֵי. וְלֹא דָּחִיל מִמַּרְעִין בִּישִׁין דְּעַלְמָא. בְּגִין דְּאִיהוּ אָחִיד בְּאִילָנָא דְחַיֵּי וְיַלִּיף מִינֵּיהּ בְּכָל יוֹמָא.","דְּהָא אוֹרַיְיתָא תּוֹלִיף לְבַר נָשׁ לְמֵיזַל בְּאֹרַח קְשׁוֹט. תּוֹלִיף לֵיהּ עֵיטָא הֵיךְ יָתוּב קַמֵּי מָארֵיהּ לְבַטְלָא הַהִיא גְּזֵרָה. דְּאָפִילּוּ אִתְגְּזַר עֲלֵיהּ דְּלָא יִתְבַּטֵּל הַאי גְּזֵרָה, מִיָּד אִתְבַּטֵּל וְאִסְתָּלַּק מִנֵּיהּ וְלָא שַׁרְיָא עֲלֵיהּ דְּבַר נָשׁ בְּהַאי עַלְמָא. וּבְגִין כָּךְ בָּעֵי לֵיהּ לְבַר נָשׁ לְאִשְׁתַּדְּלָא בְּאוֹרַיְתָא יְמָמָא וְלֵילֵי וְלָא יִתְעַדֵי מִינָהּ הֲדָא הוּא דִכְתִיב (יהושע א׳:ח׳) וְהָגִיתָ בוֹ יוֹמָם וָלַיְלָה. וְאִי אִתְעַדֵּי מִינָּהּ דְּאוֹרַיְיתָא אוֹ אִתְפְּרַשׁ מִינָהּ כְּאִלּוּ אִתְפְּרַשׁ מֵאִילָנָא דְחַיֵּי.","תָּא חֲזֵי, עֵיטָא לְבַר נָשׁ, כַּד אִיהוּ סָלִיק בְּלֵילְיָא עַל עַרְסֵיהּ בָּעֵי לְקַבְּלָא עֲלֵיהּ מַלְכוּתָא דִּלְעֵילָא בְּלִבָּא שְׁלִים וּלְאַקְדְּמָא לְמִמְסַר קַמֵּיהּ פִּקְדוֹנָא דְּנַפְשֵׁיהּ (בראשית י\"ט ע\"ב) וּמִיָּד אִשְׁתְּזִיב מִכָּל מַרְעִין בִּישִׁין וּמִכָּל רוּחִין בִּישִׁין וְלָא שָׁלְטִין עֲלֵיהּ.","וּבְצַפְרָא קָם מֵעַרְסֵיהּ בָּעֵי לְבָרְכָא לְמָארֵיהּ וּלְמֵיעַל לְבֵיתֵיהּ וּלְמִסְגַּד קַמֵּי הֵיכָלֵיהּ בִּדְחִילוּ סַגְּיָא, וּבָתַר כֵּן יִצְלֵי צְלוֹתֵיהּ וְיִסַּב עֵיטָא מֵאִנּוּן אֲבָהָן קַדִּישִׁין דִּכְתִיב, (תהילים ה׳:ח׳) וַאֲנִי בְּרֹב חַסְדְּךָ אָבוֹא בֵיתֶךָ אֶשְׁתַּחֲוֶה אֶל הֵיכַל קָדְשְׁךָ בְּיִרְאָתֶךָ.","הָכִי אוּקְמוּהָ לָא לִבָּעֵי לֵיהּ לְבַר נָשׁ לְעָאֳלָא לְבֵי כְּנִישְׁתָּא אֶלָּא אִי אַמְלִיךְ בְּקַדְמִיתָא בְּאַבְרָהָם יִצְחָק וְיַעֲקֹב, בְּגִין דְּאִנּוּן תְּקִינוּ צְלוֹתָא לְקָמֵי קוּדְשָׁא בְּרִיךְ הוּא. הֲדָא הוּא דִכְתִיב וַאֲנִי בְּרוֹב חַסְדֶּךָ אָבוֹא בֵיתֶךָ, דָּא אַבְרָהָם. אֶשְׁתַּחֲוֶה אֶל הֵיכַל קָדְשֶׁךָ, דָּא יִצְחָק. בְּיִרְאָתֶךָ, דָּא יַעֲקֹב. וּבָעֵי לְאַכְלָלָא לוֹן בְּרֵישָׁא, וּבָתַר כֵּן יֵיעוּל לְבֵי כְּנִשְׁתָּא וִיצַלֵּי צְלוֹתֵיהּ. כְּדֵין כְּתִיב, (ישעיהו מ״ט:ג׳) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאָר.","רִבִּי פִּינְחָס הֲוָה שְׁכִיחַ קַמֵּי דְּרִבִּי רְחוּמָאִי בְּכֵיף יַמָּא דְּגִנוֹסָר. וּבַר נַשׁ רַב וּקְשִׁישָׁא דְיוֹמִין הֲוָה וְעֵינוֹי אִסְתַּלָּקוּ מִלְּמֶחמֵי. אָמַר לְרִבִּי פִּינְחָס וַדַּאי שְׁמַעְנָא דְּיוֹחָאִי חַבְרָנָא אִית לֵיהּ מַרְגָּלִית אֶבֶן טָבָא, וְאִסְתַּכְּלִית בִּנְהוֹרָא דְּהַהִיא מַרְגָּלִית נָפְקָא כִּנְהִירוּ דְּשִׁמְשָׁא מִנַּרְתְּקָהּ וְנָהֲרָא כָּל עָלְמָא.","וְהַהוּא נְהוֹרָא קָאִים מִשְׁמַיָּא לְאַרְעָא וְנָהִיר כָּל עָלְמָא עַד דְּיָתִיב עַתִּיק יוֹמִין וְיָתִיב עַל כֻּרְסְיָיא כְּדְקָא יְאוּת. וְהַהוּא נְהוֹרָא כָּלִיל כֹּלָּא בְּבֵיתָךְ. וּמִנְּהוֹרָא דְּאִתְכְּלִיל בְּבֵיתָךְ. נָפַק נְהִירוּ דַּקִּיק וּזְעֵיר וְנָפִיק לְבַר וְנָהִיר כָּל עָלְמָא, זַכָּאָה חוּלָקָךְ. פּוֹק בְּרִי, פּוֹק, זִיל אַבַּתְרֵיהּ דְּהַהִיא מַרְגָּלִית דְּנָהִיר עָלְמָא, דְּהָא שַׁעֲתָא קָיְימָא לָךְ.","נָפַק מִקַּמֵּיהּ וְקָאִים לְמֵיעַל בְּהַהִיא אַרְבָּא וּתְרֵין גּוּבְרִין בַּהֲדֵיהּ. חָמָא תְּרֵין צִפֳּרִין דְּהֲווּ אַתְיָין וְטָסִין עַל יַמָּא, רָמָּא לוֹן קָלָא וְאָמַר צִפֳּרִין צִפֳּרִין דְּאַתּוּן טָאסִין עַל יַמָּא, חֲמֵיתוּן דּוּךְ דְּבַר יוֹחָאִי תַּמָּן, אִשְׁתָּהֵי פּוּרְתָא אָמַר, צִפֳּרִין צִפֳּרִין זִילוּ וְאֲתִיבוּ לִי. פָּרְחוּ וְאֲזִילוּ, עָאלוּ בְּיַמָּא וְאָזְלֵי לְהוֹן.","עַד דְּנָפַק, הָא אִנּוּן צִפֳּרִין אַתְיָין וּבְפוּמָא דְּחָדָא מִנַיְיהוּ פִּתְקָא חָדָא וּכְתִיב בְּגַוָּוהּ דְּהָא בַּר יוֹחָאִי נָפַק מִן מְעַרְתָּא (הוא) וְרִבִּי אֶלְעָזָר בְּרֵיהּ. אֲזַל לְגַבֵּיהּ וְאַשְׁכַּח לֵיהּ מְשַׁנְיָא וְגוּפֵיהּ מַלְיָא חֲלוּדִין. בָּכָה בַּהֲדֵיהּ וְאָמַר וַוי דַּחֲמִיתִיךְ בְּכָךְ. אָמַר זַכָּאָה חוּלָקִי דַּחֲמֵית לִי בְּכָךְ דְּאִלְמָלֵא לָא חֲמִיתָא לִי בְּכָךְ לָא הֲוֵינָא בְּכָךְ פָּתַח רִבִּי שִׁמְעוֹן בְּפִקּוּדֵי אוֹרַיְיתָא. וְאָמַר פִּקּוּדֵי אוֹרַיְיתָא דְּיָהַב קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל כֻּלְהוּ בְּאוֹרַיְיתָא בְּאֹרַח כְּלַל כְּתִיבֵי:"],[[0,"","קעט) \u0003אמר ליה קב\"ה\u0004 וכו': א\"ל הקב\"ה, מי בעולם כאברהם. והמשטין לא מש משם עד שבלל כל אותה השמחה. והקב\"ה צוה להקריב את יצחק לקרבן. ונגזר על שרה שתמות על צער בנה. כל הצער ההוא, גרם, מה שלא נתן משהו לעניים."],[0,"","פירוש. כי עקדת יצחק היתה לתקן עצם המלכות, מה שלא תיקן עם המשתה הגדול ביום הגמל את יצחק. ומיתת שרה היתה מסבת האורות הגדולים שהמשיכה בסוה\"כ \u0003צחוק עשה לי אלהים\u0004 וגו' (בראשית כ\"א), שהם הפריעו לתיקון המלכות כנ\"ל."],[1,"","קפ) \u0003פתח רבי שמעון\u0004 וכו': פתח ר\"ש ואמר, מה שכתוב, ויסב חזקיהו פניו אל הקיר ויתפלל אל ה'. בוא וראה, כמה חזק כח התורה, וכמה היא עליונה על הכל. כי כל מי שעוסק בתורה, אינו ירא מעליונים ומתחתונים, ואינו ירא מחליים רעים שבעולם, מפני שהוא אחוז בעץ החיים, ולומד ממנו בכל יום."],[2,"","קפא) \u0003דהא אורייתא תוליף\u0004 וכו': כי התורה מלמדת את האדם ללכת בדרך אמת, מלמדת לו עצה איך ישוב לפני אדונו לבטל הגזירה. כי אפילו נגזר עליו שהגזירה לא תתבטל, היא מתבטלת מיד ונעברת ממנו, ואינה שורה על האדם בעולם הזה. ומשום זה, צריך האדם לעסוק בתורה יום ולילה, ולא יסור ממנה. ז\"ש, והגית בו יומם ולילה. ואם הוא סר מן התורה, או נפרד ממנה, הוא כאלו נפרד מעץ החיים."],[2,"","ביאור הדברים, הנה פתח בתפילה, בפסוק \u0003ויסב חזקיהו פניו אל הקיר\u0004, ומפרשו רק באורייתא. והענין הוא כמ\"ש במקום אחר (זוהר ואתחנן דף ד' אות י\"א) שע\"כ נתקבלה תפילתו משום שלא היה דבר חוצץ בינו ובין הקיר, שה\"ס השכינה הקדושה."],[2,"","וע\"ז אומר כאן, שעצה זו עלתה לו רק בכח התורה, שהשיג על ידה לבא לתשובה שלמה, עד שלא היה דבר חוצץ בינו ובין השכינה הקדושה, וע\"כ נתבטלה הגזירה שנגזרה עליו מיתה. וע\"כ מסיים \u0003ובגין כך\u0004 כיון שאנו רואים שכח התורה גדול כל כך עד לבטל גזירת מות, \u0003בעי ליה לב\"נ לאשתדלא באורייתא יממא ולילי. ולא יתעדי מינה\u0004."],[3,"","קפב) \u0003ת\"ח עיטא לבר\u0004 וכו': בוא וראה, עצה לאדם: כשהוא עולה בלילה על מטתו צריך לקבל עליו מלכות שלמעלה, בלב שלם, ולהקדים למסור אליו פקדון נפשו, ומיד הוא ניצל מכל חליים רעים ומכל הרוחות הרעות, שאינן שולטות עליו."],[3,"","ביאור הדברים, כי קרא ה', לאור יום, דהיינו אור הדביקות והקדושה, שאנו משיגים מהש\"י. וזהו ממשלת היום, ולחושך קרא לילה, דהיינו הכחות דפרודא המפרידות אותנו מאורו ית', הוא ממשלת הלילה. ולפיכך אנו ישנים בלילה, שהוא חלק א' מששים במיתה שהוא ממשלת הס\"א. ומתוך ב' הממשלות האלו אין אנו יכולים להדבק בו ית' לנצח, כי אנו מפסיקין דבקותו ית' מכח ממשלת הלילה החוזרת ובאה עלינו תמיד והמפסקת אותנו מעבדותו ית'."],[3,"","ולתקן זה, נותן לנו ר\"ש עצה, שבכל לילה טרם שהולך לישון, \u0003בעי לקבלא עליה מלכותא דלעילא בלבא שלים\u0004, כי בעת שהלילה מתוקן כמו במעשה בראשית, דכתיב, ויהי ערב ויהי בוקר יום אחד, שפירושו, שלילה ויום מיוחדים שניהם לגוף אחד ויום אחד, הנה אז נקראת הלילה ממשלת המלכות, ושום קלי' לא תתערבה עמה."],[3,"","וע\"כ גם האדם צריך לקבל עליו מלכות עליונה זו בלב שלם, בלי שום חציצה בינו ובין המלכות, כלומר, שיקבל עליו מלכות שמים בין לחיי ובין למותא, ושום דבר שבעולם לא יזיזוהו להרחיקו ח\"ו במשהו מהמלכות העליונה, דהיינו בסו\"ה ואהבת את ה' אלקיך בכל לבבך ובכל נפשך ובכל מאדך (דברים ו'), ואם קבל זה עליו בלב שלם, נמצא בטוח בעצמו שכבר לא יצוייר יותר שום דבר חוצץ בינו למקום ית'."],[3,"","וע\"כ נבחן בזה שנתקדם \u0003לממסר פקדונא דנפשיה\u0004, כי הקדים למסור נפשו בידו של הקב\"ה, דהיינו לקיים מצותיו בכל השלמות עד למסירות נפש, וע\"כ כשישן ורוחו מסתלק, אינו טועם עוד בזה א' מששים ממיתה, שהוא כח הס\"ם, אלא רק בחינת מסירת נפש בדרך מצוה, כי כבר אין כח מיתה שולט עליו. באשר שהכניסו לכח מס\"נ של מצוה."],[3,"","וכשעושה כן. שוב אין ממשלת הלילה יכולה לפגום אותו, ולהפסיקו מנועם עבודתו ית', כי אצלו כבר הערב והבוקר יום אחד, ואין הלילה אלא חלק מהיום ממש. וע\"כ \u0003ומיד אשתזיב מכל מרעין בישין ומכל רוחין בישין, ולא שלטין עליה\u0004, כי הלילה שלו כבר יצא מרשות הס\"א, שהרי לא יצוייר לו עוד, שום דבר חוצץ בינו ובין השכינה הקדושה, ואין עוד כחות הס\"א והדין שולטים עליו."],[4,"","קפג) \u0003ובצפרא, קם מערסיה\u0004 וכו': ובבוקר כשהוא קם ממטתו, הוא צריך לברך לאדונו ולהכנס לביתו, ולהשתחוות לפני היכלו ביראה גדולה. ואחר כך יתפלל תפלתו. ויקח עצה מן האבות הקדושים שכתוב, ואני ברוב חסדך אבא ביתך אשתחוה אל היכל קדשך ביראתך."],[4,"","פירוש. הוא תרגום של הפסוק ואני ברוב חסדך אבא ביתך אשתחוה אל היכל קדשך ביראתך. \u0003ואני ברוב חסדך\u0004 הוא ל\u0003ברכא למאריה\u0004, על החסד שעשה עמו. \u0003אבא ביתך\u0004, הוא \u0003ולמיעל לביתיה. אשתחוה אל היכל קדשך\u0004, הוא \u0003ולמסגד קמי היכליה. ביראתך\u0004, הוא \u0003בדחילו סגיא. ובתר כן יצלי צלותיה\u0004. וטעם הדבר הולך ומבאר לפנינו."],[4,"","וז\"ש, \u0003ויסב עיטא\u0004 וכו', כי התפלה שאנו מתפללין, היא תיקון השכינה הקדושה, להמשיך לה שפע למלאותה מכל חסרונותיה. כי ע\"כ כל הבקשות הן בלשון רבים, כמו וחננו דעה וכו' השיבנו אבינו וכו'. כי התפילה היא בעד כלל ישראל, שכל שיש בשכינה הקדושה, יש בכלל ישראל. והחסר בה, חסר בכלל ישראל, ונמצא כשאנו מתפללין בעד כלל ישראל, אנו מתפללין לצורך השכינה הקדושה, כי היינו הך."],[4,"","ונמצא שקודם התפילה אנו צריכים להסתכל בחסרונות שבה, כדי שנדע מה שצריך לתקן בה ולמלאותה, אמנם כל הדורות של כלל ישראל כלולין בשכינה הקדושה, ואלו התיקונים שקבלה מהדורות שקדמו לנו אין אנו צריכים עוד לתקן בה, אלא שאנו צריכים להשלים עליהם, דהיינו לתקן מה שנשאר חסר בה אחר תיקונם."],[4,"","והנה האבות הקדושים הם הכולל של כלל ישראל, כי הם ג' השרשים של כל ששים רבוא נשמות ישראל מכל דור ודור עד לגמר התיקון, וכל ההמשכות והשפעות. שכלל ישראל ממשיכים ומקבלים בכל הדורות, מקובלים תחילה אל האבות הקדושים, ומהם מגיע השפע אל כלל ישראל שבאותו הדור שהמשיכו השפע. כי כן הסדר הרוחני, ששום ענף אינו יכול לקבל כלום רק דרך שרשו, ועיקר ההארה נשאר בשורש ורק חלק ממנו נמשך לענף. ולפיכך נמצא, שכל התיקונים שכבר נתקנו בשכינה הקדושה, הם עומדים וקיימים בנשמות אבותינו הקדושים."],[4,"","וזה אמרו \u0003לא לבעי ליה לבר נש לעאלא לבי כנישתא אלא אי אמליך בקדמיתא באברהם יצחק ויעקב\u0004, כמבואר, שכל ענין תפילתנו היא רק להשלים מה שחסר עוד בשכינה אחר התיקונים שכבר נעשו בה עד עתה. לכן צריכים מקודם לדעת ולהמשיך בשכינה הקדושה את כל התיקונים שכבר תיקנו בה, ואז נדע מה שצריך עוד להוסיף עליהם."],[4,"","וז\"ש שאין לאדם ליכנס לבית הכנסת מטרם שאילת עצה באבות הקדושים, כי צריכים להמלך בהם לידע מה שצריך עוד לתקן, וזה יתכן, רק אחר המשכתנו בשכינה הקדושה כל מה שהאבות הקדושים כבר תיקנו בה, ואז נראה מה שעוד חסר בה, וז\"ש \u0003בגין דאינון תקינו צלותא\u0004, כי הם תיקנו ה\u0003צלותא\u0004, שהיא השכינה הקדושה שתיקון אברהם, נקרא \u0003שחרית\u0004, דיצחק \u0003מנחה\u0004, ודיעקב, \u0003ערבית\u0004, וכיון שכן, אנו צריכים מקודם להמשיך כל שיעור התיקון, שכבר תיקנו הם ב\u0003צלותא\u0004, ואז נדע מה שיש עוד להתפלל ולתקן מה שחסר בה."],[5,"","קפד) \u0003הכי אוקמוה\u0004 וכו': והעמידוהו כך. שאדם אינו צריך להכנס לבית הכנסת, אלא אם נמלך מתחילה, דהיינו שמקבל רשות, באברהם יצחק ויעקב, משום שהם תקנו התפילה לפני הקב\"ה. ז\"ש, ואני ברוב \u0003חסדך אבא ביתך\u0004, זהו \u0003אברהם\u0004, שהוא חסד. אשתחוה אל \u0003היכל\u0004 קדשך, זהו \u0003יצחק\u0004. שמצדו נקראת המלכות היכל. \u0003ביראתיך\u0004, זהו \u0003יעקב\u0004. שה\"ס ת\"ת הנקרא נורא. וצריך להכלל בהם תחילה, ואח\"כ יכנס לבית הכנסת ויתפלל תפלתו. אז כתוב, ויאמר לי עבדי אתה ישראל אשר בך אתפאר."],[5,"","הנה הולך ומבאר כאן ג' תיקונים כוללים שנעשו בשכינה הקדושה ע\"י האבות: אשר \u0003אברהם\u0004 תיקן אותה בבחינת \u0003בית\u0004, שפירושו דירת קבע, באופן שהאדם יוכל להדבק בה בתמידות כמו שהוא בביתו בתמידות, ו\u0003יצחק\u0004 הוסיף תיקון, ותיקן אותה בבחינת \u0003היכל הקדש\u0004, שפירושו, שהמלך שוכן בה בקביעות כי המלך נמצא תמיד בהיכלו."],[5,"","ו\u0003יעקב\u0004 הוסיף תיקון, ותיקן אותה בבחינת \u0003יראה\u0004, שהוא ענין \u0003תרעא לדרתא\u0004, דהיינו בחינת פתח, הן לבחינת בית שבה והן לבחינת היכל הקודש שבה, בסוה\"כ מה נורא המקום הזה וזה שער השמים (בראשית י\"א). ואחר שהאדם נכלל כבר בג' התיקונים ההם של האבות בשלימות, אז אפשר לו לדעת כל השיעור שכבר נתקן בשכינה הקדושה, ואז \u0003ייעול לבי כנישתא ויצלי צלותיה\u0004, לתקן בשכינה מה שעוד חסר בה."],[5,"","וביאור הדברים, כי אברהם הוא שורש החסד שבנשמות ישראל, כי הוא תיקן השכינה הקדושה לבחינת בית קבול לאור החסד, וקבלה החסדים בעד כל נשמות ישראל בכל מלואן. ואם היה נשאר כן, היו כל ישראל דבקים בהשי\"ת דבקות תמידית, והשכינה הקדושה היתה בית מלכות המלא כל טוב ועונג, ולא היה שום איש רוצה להפרד ממנה אפילו לרגע."],[5,"","אמנם כל תיקונו של אברהם היה, בסוד שעשה בית קבול שלם, לבלי שום אפשרות של פגם, לאור החסדים, דהיינו שהעלה אותה לבחינת השפעה ונ\"ר ליוצרנו ית', ולא לקבל להנאת עצמנו כלום, כי זהו המדה ובית הקבול של אור החסד. כמ\"ש חז\"ל על מדת האומר שלי שלך ושלך שלך חסיד (אבות פ\"ה), שאינו דורש להנאת עצמו אף משהו."],[5,"","וכיון שכל הצמצומים וכל אחיזת הס\"א הוא רק בבחינת הקבלה לעצמו, נמצא שהסיר בזה כל חלאת הקליפות והס\"א לגמרי, ונתקנה השכינה בתכלית הטהרה. אמנם עוד לא היתה נגמרת בזה מחשבת הבריאה כי מחשבת הבריאה היתה בעיקר, להנות לנבראיו אשר מדת ההנאה תלויה ושקולה רק בשעור החשק לקבל, שלפי גדלות החשק לקבל, כן מדת התענוג מהקבלה."],[5,"","וע\"כ אחר שכבר נתקנה השכינה רק בכלי של השפעה בלי קבלה לעצמו כלום, שהוא ענין הסתלקות מלקבל ממנו ית', ורק להשפיע אליו לבד, וא\"כ לא הגיע עוד מזה שום תיקון למחשבת הבריאה השורשית שאינה באה רק בגדלות החשק לקבל."],[5,"","וז\"ס \u0003אברהם הוליד את יצחק\u0004, כי אחר שיצחק מצא השכינה בתכלית השלימות והמילוי מאור החסד ע\"י התיקונים של אברהם הרגיש את החסרון שיש בשכינה, שעוד אינה ראויה לקבל כל הכלול במחשבת הבריאה כנ\"ל, ע\"כ הלך ותיקן אותה לבית קבול, באופן שתהיה ראויה לקבל כל השלימות הנרצה והכלולה במחשבת הבריאה, דהיינו שעורר גם את החשק לקבל ממנו ית', אלא רק בבחינת קבלה ע\"מ להשפיע, שפירושו, שחושק מאד לקבל ורק מטעם שהמשפיע רוצה כן, ולולא שהמשפיע היה רוצה כן, לא היה בו שום רצון של משהו לקבל ממנו."],[5,"","ונודע שקבלה ע\"מ להשפיע נחשבת להשפעה ממש, ונמצא שאין עוד לס\"א שום אחיזה ברצון לקבלה הזו. וע\"כ נתקנה על ידו השכינה הקדושה בכל השלימות הגדולה האחרונה, כי עתה היא ראויה לקבל כל הנועם והרוך מכל מה שחשב הש\"י להנות לנבראיו, בעת שעלו במחשבה לבראם."],[5,"","ולפיכך נקראת עתה השכינה הקדושה בבחינת היכל קדשו ית', כי עתה שוכן בה המלך בכל הדרו ותפארתו כמו מלך בהיכלו. אמנם מבחינת תיקונו של אברהם היא נקראת רק בית, כלומר בית המלכות, כי עוד לא היה ניכר שם כל כבודו והדרו, כי אין כבודו של מלך ניכר אלא בהיכלו המיוחד לו,"],[5,"","ונבחן בזה, שיצחק תיקן כל הגבורות שבנשמות ישראל, שפירושו, מיתוק כל הדינים שבהנהגתו ית': כי כל הצמצומים והיסורים והעונשים הבאים בעולם אינם אלא כדי לתקן את כלי הקבלה של הנשמות, שיהיו ראוים לקבל כל הטוב הכלול במחשבת הבריאה, ומתוך שיצחק כבר תיקן בשעתו את השכינה בשלימות הזו, הרי נתקנו בזה כל הגבורות, כי באו כבר למטרה הרצויה להם."],[5,"","אמנם גם תיקונו לא נשאר כן, והוא כי העולם עוד לא היה מוכשר לגמר התיקון, וע\"כ יצא ממנו עשו הרשע, שהוא קלקל את תקונו, ולא עמד בו להיות מקבל רק ע\"מ להשפיע, כמו שתיקן יצחק, אלא שנכשל בקבלה לעצמו, כלומר שגם בעת שנגלה לו שאין המשפיע רוצה שיקבל, רצה ג\"כ לקבל מטעם הנאת עצמו, וע\"כ נאחזו בו הס\"א והקליפות בסוד אדמוני ואיש שעיר. ועי\"כ הוריד שוב רגלי המלכות לקליפות, בסוד ורגליה יורדות מות."],[5,"","וכיון שראה יעקב את הקלקול של עשו הרשע, הלך ותיקן את השכינה הקדושה במדת היראה. שה\"ס וידו אוחזת בעקב עשו (בראשית כ\"ה), שאמרו בזוהר דהאי \u0003י'\u0004 דשדי עשו לעקבוי, ארמה יעקב לרישיה. כלומר כיון שראה יעקב את הקלקול של עשו בהאי \u0003י'\u0004 שה\"ס השכינה, תיקן את עצמו ביראה גדולה עד שהעלה את השכינה לבחינת עטרה על רישיה. ועי\"ז נאחז בב' התיקונים של אברהם ויצחק בבת אחת, ולא יצא ממנו שום פסול."],[5,"","אמנם תיקון זה אינו עוד גמר תיקון, כי היראה דומה לבחינת יראת חטא שהרי עקבו של עשו גרם לו היראה ההיא, מבלי לחטוא כמותו, אבל בגמר התיקון, הוא, אחר שיתבטל עקבו של עשו, בסו\"ה בלע המות לנצח, שהיראה תהיה אז, רק \u0003בגין דאיהו רב ושליט\u0004. והנה יעקב לעצמו ודאי השיג גם היראה האמיתית הזו, אלא מבחינת כלל ישראל נשאר תיקון זה לכל הדורות אחריו עד גמר התיקון."],[5,"","וזהו אמרו \u0003ואני ברוב חסדך אבא ביתך, דא אברהם\u0004, כי \u0003אברהם\u0004 תיקן אותה בבחינת בית המלכות המלא מכל טוב, באור החסד כנ\"ל. \u0003אשתחוה אל היכל קדשך, דא יצחק\u0004, כי \u0003יצחק\u0004 תיקן אותה בבחינת היכל הקדש להדר כבוד המלך. כראוי לו ית' כנ\"ל, \u0003ביראתך, דא יעקב\u0004, כי \u0003יעקב\u0004 תיקן אותה במדת היראה, ועי\"ז תיקן אותה לבית קבול לכל התיקונים של אברהם ויצחק יחד, כנ\"ל."],[5,"ובעי לאכללא לון ברישא",", כי איך ידע מה שנשאר לתקן עוד לשכינה, אם לא יכלל את עצמו בכל אלו ג' התיקונים, שכבר תיקנו בה האבות הקדושים, דהיינו שיקבל על עצמו להתנהג על פי תיקוניהם הנ\"ל. וזה נבחן שנכלל במדתם כנ\"ל."],[5,"","ורק אחר שנכלל בכל אלו ג' תיקונים של אבותינו הקדושים, יתחיל לתקן אותה ממקום שהניח לנו \u0003יעקב\u0004 אבינו, דהיינו להעלות היראה למדת הרוממות בגין דאיהו רב ושליט, \u0003ובתר כן ייעול לבי כנישתא ויצלי צלותיה\u0004, דהיינו שיתפלל וימשיך בה האורות העליונים עם יראת הרוממות להביאה לגמר התיקון. \u0003כדין כתיב ויאמר לי עבדי אתה ישראל אשר בך אתפאר\u0004."],[6,"","קפה) \u0003רבי פנחס הוה\u0004 וכו': ר\"פ היה רגיל לפני רבי רחומאי בשפת הים של כנרת. ואדם גדול ושבע ימים היה, ועיניו כהו מראות. אמר לרבי פנחס, שמעתי בודאי שיוחאי חברנו יש לו מרגלית, אבן טובה, דהיינו בן, והסתכלתי באור המרגלית ההיא, שהוא יוצא כהארת השמש מנדנה, ומאיר את כל העולם."],[6,"","ביאור הדברים, המלכות בכל תיקוניה, נקראת \u0003אבן טוב\u0004 ונקראת \u0003מרגלית\u0004, ואומר \u0003דיוחאי חברנא אית ליה מרגלית אבן טבא\u0004. שכבר זכה במלכות בכל תיקוניה וקישוטיה, והסתכל ברוח הקודש באור של ה\u0003מרגלית\u0004, שהיא מאירה כאור השמש ביציאתה מנרתיקה, שה\"ס תיקון העתיד של המלכות, שתהיה אור הלבנה כאור החמה, שאז היא מאירה כל העולם כולו."],[6,"","והנה אחר שאור המלכות נעשה לאור החמה, ועלה עד השמים שיאה, הנה האירה מהשמים עד לארץ בעמודא חדא דנהורא לכל העולם כולו, והיה מאיר והולך עד שהספיק רשב\"י לתקן כרסייא ד\u0003עתיק יומין כדקא יאות\u0004. והרמז הוא, שכבר זכה לב' הגלויים שבגמר התקון שהם \u0003שית קראי ושית שמהן\u0004 (הנ\"ל אות קמ\"ה) כי \u0003נהורא קאים משמיא לארעא\u0004 וכו' ה\"ס \u0003שית קראי, ועד דיתיב עתיק יומין ויתיב על כרסייא כדקא יאות\u0004, ה\"ס \u0003שית שמהן\u0004 עש\"ה."],[7,"","קפו) \u0003וההוא נהורא\u0004 וכו': ואותו האור עומד מן השמים עד הארץ, ומאיר כל העולם, עד שיבא עתיק יומין, שהוא הכתר, וישב על הכסא כראוי, דהיינו עד גמר התקון. ואותו האור כלול כולו בביתך, דהיינו בבתו, כי בתו של ר' פנחס היתה אשת ר\"ש בן יוחאי, ומן האור שנכלל בביתך יוצא אור דק וקטן, שהוא בן בתו, ר' אלעזר, ויוצא לחוץ ומאיר את כל העולם. אשרי חלקך. צא בני, צא. לך אחרי אותה המרגלית המאירה את העולם. כי השעה עומדת לך."],[7,"","פירוש. כי ברתיה דרבי פנחס בן יאיר היתה אשתו של ר\"ש ונמצא רבי שמעון כליל בביתו של רפב\"י. הכוונה היא על רבי אלעזר שיצא מה\u0003נהורא דאתכליל\u0004 בבית רפב\"י, שהוא ר\"ש ואשתו, אשר הוא יצא והאיר כל העולם כולו."],[8,"","קפז) \u0003נפק מקמיה וקאים\u0004 וכו': יצא מלפניו ועמד להכנס באניה. והיו עמו שני אנשים. ראה שתי צפרים, שהיו באות ועפות על הים. הרים קולו ואמר, צפרים צפרים, הרי אתן מעופפות על הים, הראיתם את המקום שבן יוחאי שמה. חיכה מעט, אמר, צפרים צפרים, לכנה והשבנה לי. עפו והלכו. נכנסו בים והלכו להן."],[8,"","פירוש. כי ר\"ש ברח מפני המלכות שצותה להורגו, ונסתתר הוא ובנו במערתא חדא (כדאיתא שבת ל\"ג:) ולא ידעו איפה הוא. וע\"כ יצא רפב\"י לבקשו באיי הים."],[9,"","קפח) \u0003עד דנפק הא\u0004 וכו': מטרם שיצא לאניה, והנה באו הצפרים, ובפיה של אחת מהן מכתב אחד, וכתוב בתוכו, אשר ר' שמעון בן יוחאי יצא מן המערה עם ר' אלעזר בנו. הלך ר' פנחס אליו. ומצא אותו שנשתנה, וגופו מלא נקבים ופצעים, מרוב הישיבה במערה. בכה עמו, ואמר אוי שראיתיך בכך. אמר לו ר\"ש, אשרי חלקי, שראית אותי בכך, כי אם לא ראית אותי בכך, לא הייתי כך. \u0003חלודין\u0004, הוא מלשון שמחלידין את הקרקע (ב\"ב י\"ט:) שפירושו שעושים נקבים בקרקע. פתח ר' שמעון במצות התורה ואמר, מצות התורה שנתן הקב\"ה לישראל, כתובות כולן בתורה בדרך כלל."],[9,"","פירוש. כי מרוב שנים שישב במערה היה מוכרח לישב שם תוך החול, כדי לכסות ערומו ולעסוק בתורה, ונחלד בשרו מחמת זה. בכה עליו ואמר. אוי לי שראיתיך בכך. ענה לו ר\"ש, אשרי חלקי אשר ראיתני בכך, שאלמלא לא ראיתני בכך, לא הייתי בכך, כלומר, שלא הייתי זוכה לגילוי רזין דאורייתא, כי כל רוממות חכמתו הגדולה זכה באותם י\"ג שנים שהיה מוסתר במערה."],[9,"פתח ר\"ש","וכו': כל המצות שבתורה שנתן הקב\"ה לישראל הן כתובות כולן בדרך כלל בפסוק \u0003בראשית ברא אלהים\u0004 עד המאמר \u0003ויהי אור\u0004. כמ\"ש והולך, שהוא מצות ה\u0003יראה\u0004 ועונשה, ובה כלולות כל המצות שבתורה."]],[[0,"","אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: מִי בָּעוֹלָם כְּאַבְרָהָם וְלֹא זָז מִשָּׁם עַד שֶׁבִּלְבֵּל כָּל אוֹתָהּ שִׂמְחָה, וְצִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַקְרִיב אֶת יִצְחָק קָרְבָּן, וְנִגְזַר עַל שָׂרָה שֶׁתָּמוּת עַל צַעַר בְּנָהּ. כָּל אוֹתוֹ הַצַּעַר גָּרַם שֶׁלֹּא נָתַן דָּבָר לָעֲנִיִּים."],[1,"","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, מַהוּ שֶּׁכָּתוּב (ישעיה לח) וַיָּסֵב חִזְקִיָּהוּ פָּנָיו אֶל הַקִּיר וַיִּתְפַּלֵּל אֶל ה' - בֹּא תִרְאֶה כַּמָּה הוּא הַכֹּחַ הֶחָזָק שֶׁל הַתּוֹרָה וְכַמָּה הוּא עֶלְיוֹן עַל הַכֹּל. שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, לֹא פוֹחֵד מֵעֶלְיוֹנִים וְתַחְתּוֹנִים, וְלֹא פוֹחֵד מֵחֳלָאִים רָעִים שֶׁל הָעוֹלָם, מִשּׁוּם שֶׁהוּא אָחוּז בְּעֵץ הַחַיִּים וְלוֹמֵד מִמֶּנּוּ בְּכָל יוֹם."],[2,"","שֶׁהֲרֵי הַתּוֹרָה מְלַמֶּדֶת אָדָם לָלֶכֶת בְּדֶרֶךְ אֱמֶת, תְּלַמֵּד אוֹתוֹ עֵצָה אֵיךְ יָשׁוּב לִפְנֵי רִבּוֹנוֹ לְבַטֵּל אֶת אוֹתָהּ הַגְּזֵרָה. שֶׁאֲפִלּוּ אִם נִגְזָר עָלָיו שֶׁלֹּא תִתְבַּטֵּל הַגְּזֵרָה הַזּוֹ - מִיָּד מִתְבַּטֶּלֶת וּמִסְתַּלֶּקֶת מִמֶּנּוּ וְלֹא שׁוֹרָה עַל הָאָדָם בָּעוֹלָם הַזֶּה. וּמִשּׁוּם כָּךְ צָרִיךְ הָאָדָם לְהִשְׁתַּדֵּל בַּתּוֹרָה יָמִים וְלֵילוֹת וְלֹא יָסוּר מִמֶּנָּה. זֶהוּ שֶׁכָּתוּב (יהושע א) וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה. וְאִם סָר מִן הַתּוֹרָה אוֹ נִפְרָד מִמֶּנָּה, כְּאִלּוּ נִפְרָד מֵעֵץ הַחַיִּים."],[3,"","בֹּא רְאֵה עֵצָה לָאָדָם - כְּשֶׁהוּא עוֹלֶה בַלַּיְלָה עַל מִטָּתוֹ, צָרִיךְ לְקַבֵּל עָלָיו אֶת הַמַּלְכוּת שֶׁלְּמַעְלָה בְּלֵב שָׁלֵם וּלְהַקְדִּים לִמְסֹר לְפָנָיו אֶת פִּקְדוֹן נַפְשׁוֹ, וּמִיָּד נִצּוֹל מִכָּל הַמַּחֲלוֹת הָרָעוֹת וּמִכָּל הָרוּחוֹת הָרָעוֹת וְלֹא שׁוֹלְטִים עָלָיו."],[4,"","וּבַבֹּקֶר, כְּשֶׁקָּם מִמִּטָּתוֹ, צָרִיךְ לְבָרֵךְ לְרִבּוֹנוֹ, וּלְהִכָּנֵס לְבֵיתוֹ, וּלְהִשְׁתַּחֲווֹת לִפְנֵי הֵיכָלוֹ בְּיִרְאָה רַבָּה, וְאַחַר כָּךְ יִתְפַּלֵּל תְּפִלָּתוֹ. וְיִקַּח עֵצָה מֵאוֹתָם הָאָבוֹת הַקְּדוֹשִׁים, שֶׁכָּתוּב (תהלים ה) וַאֲנִי בְּרֹב חַסְדְּךְ אָבוֹא בֵיתֶךְ אֶשְׁתַּחֲוֶה אֶל הֵיכַל קָדְשְׁךְ בְּיִרְאָתֶךְ."],[5,"","כָּךָ פֵּרְשׁוּהָ, שֶׁלֹּא צָרִיךְ לָאָדָם לְהִכָּנֵס לְבֵית הַכְּנֶסֶת אֶלָּא אִם נִמְלַךְ בָּרִאשׁוֹנָה בְּאַבְרָהָם יִצְחָק וְיַעֲקֹב, מִשּׁוּם שֶׁהֵם תִּקְּנוּ הַתְּפִלָּה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. זֶהוּ שֶׁכָּתוּב וַאֲנִי בְּרֹב חַסְדְּךְ אָבוֹא בֵיתֶךְ - זֶה אַבְרָהָם. אֶשְׁתַּחֲוֶה אֶל הֵיכַל קָדְשְׁךְ - זֶה יִצְחָק. בְּיִרְאָתֶךְ - זֶה יַעֲקֹב. וְצָרִיךְ לְהַכְלִילָם בָּרֹאשׁ, וְאַחַר כָּךְ יִכָּנֵס לְבֵית הַכְּנֶסֶת וְיִתְפַּלֵּל תְּפִלָּתוֹ. אָז כָּתוּב (ישעיה מט) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר."],[6,"","רַבִּי פִּינְחָס הָיָה מָצוּי לִפְנֵי רַבִּי רְחוּמַאי בְּחוֹף יָם כִּנֶּרֶת, וְאָדָם גָּדוֹל וּקְשִׁישׁ יָמִים הָיָה, וְעֵינָיו פָּסְקוּ מִלִּרְאוֹת. אָמַר לְרַבִּי פִּינְחָס, וַדַּאי שָׁמַעְתִּי שֶׁלְּיוֹחַאי חֲבֵרֵנוּ יֵשׁ מַרְגָּלִית אֶבֶן טוֹבָה, וְהִסְתַּכַּלְתִּי בְּאוֹר הַמַּרְגָּלִית הַהִיא שֶׁיּוֹצֵא כְּאוֹר הַשֶּׁמֶשׁ מִנַּרְתִּיקָהּ וְהֵאִירָה אֶת כָּל הָעוֹלָם, וְאוֹתוֹ הָאוֹר עָמַד מִן הַשָּׁמַיִם לָאָרֶץ וְהֵאִיר אֶת כָּל הָעוֹלָם עַד שֶׁיָּשַׁב עַתִּיק הַיָּמִים וְיָשַׁב עַל הַכִּסֵּא כָּרָאוּי."],[7,"","וְהָאוֹר הַהוּא כָּלַל הַכֹּל בְּבֵיתְךְ, וּמֵהָאוֹר שֶׁנִּכְלַל בְּבֵיתְךְ יָצָא אוֹר דַּק וְקָטָן, וְיָצָא הַחוּצָה וְהֵאִיר אֶת כָּל הָעוֹלָם. אַשְׁרֵי חֶלְקְךְ. צֵא, בְּנִי, צֵא, וְלֵךְ אַחַר הַמַּרְגָּלִית הַהִיא שֶׁמְּאִירָה אֶת כָּל הָעוֹלָם, שֶׁהֲרֵי הַשָּׁעָה עוֹמֶדֶת לְךְ."],[8,"","יָצָא מִלְּפָנָיו וְעָמַד לְהִכָּנֵס לָאֳנִיָּה הַהִיא, וּשְׁנֵי גְבָרִים עִמּוֹ. רָאָה שְׁתֵּי צִפֳּרִים שֶׁהָיוּ בָּאוֹת וְטָסוֹת עַל הַיָּם. הֵרִים לָהֶם קוֹל וְאָמַר: צִפֳּרִים צִפֳּרִים, שֶׁאַתֶּן טָסוֹת עַל הַיָּם, הַרְאִיתֶם אֶת הַמָּקוֹם שֶׁשָּׁם בַּר יוֹחַאי הִשְׁתַּהָה מְעַט, אָמַר: צִפֳּרִים צִפֳּרִים, לְכוּ וְהָשִׁיבוּ אוֹתִי. פָּרְחוּ וְהָלְכוּ. נִכְנְסוּ לַיָּם וְהָלְכוּ לָהֶן. עַד שֶׁיָּצָא, הִנֵּה אוֹתָן צִפֳּרִים בָּאוֹת, וּבְפִי אַחַת מֵהֶן פִּתְקָה אַחַת, וְכָתוּב בְּתוֹכָהּ שֶׁהִנֵּה בַּר יוֹחַאי יָצָא מִן הַמְּעָרָה וְרַבִּי אֶלְעָזָר בְּנוֹ. הָלָךְ אֵלָיו, וּמָצָא אוֹתוֹ מְשֻׁנֶּה, וְגוּפוֹ מָלֵא חֲלֻדִּים. בָּכָה עִמּוֹ וְאָמַר: וַי שֶׁרְאִיתִיךְ בְּכָךְ. אָמַר: אַשְׁרֵי חֶלְקִי שֶׁרָאִיתָ אוֹתִי בְּכָךְ. שֶׁאִלְמָלֵא לֹא רָאִיתִי אוֹתִי בְּכָךְ, לֹא הָיִיתִי בְּכָךְ."],[9,"","פָּתַח רַבִּי שִׁמְעוֹן בְּמִצְווֹת הַתּוֹרָה וְאָמַר, מִצְווֹת הַתּוֹרָה שֶׁנָּתַן הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל, כֻּלָּן כְּתוּבוֹת בַּתּוֹרָה בְּדֶרֶךְ כְּלָל."]]],[["בְּרִאשִׁית בָּרָא אֱלֹהִים. הֲדָא הִיא פִּקּוּדָא קַדְמָאָ\"ה דְּכֹלָּא. וְאִקְרֵי פִּקּוּדָא דָא יִרְאַת ה' דְּאִקְרֵי רֵאשִׁית. דִּכְתִיב, (תהילים קי״א:י׳) רֵאשִׁית חָכְמָה יִרְאַת יְיָ. (משלי א׳:ז׳) יִרְאַת יְיָ רֵאשִׁית דַּעַת. בְּגִין דְּמִלָּה דָא רֵאשִׁית אִקְרֵי. וְדָא אִיהִי תַּרְעָא לְאָעָלָא גוֹ מְהֵימְנוּתָא. וְעַל פִּקּוּדָא דָא אִתְקְיַּים כָּל עָלְמָא.","יִרְאָה אִתְפְּרַשׁ לִתְלַת סִטְרִין. תְּרֵין מִנַּיְיהוּ לֵית בְּהוּ עִיקָרָא כְּדְקָא יְאוּת, וְחַד עִיקָּרָא דְּיִרְאָה. אִית בַּר נַשׁ דְּדָחִיל מקוּדְשָׁא בְּרִיךְ הוּא בְּגִין דְּיֵיחוֹן בְּנוֹהִּי וְלָא יְמוּתוּן. אוֹ דָּחִיל מֵעוֹנְשָׁא דְּגוּפֵיהּ אוֹ דְּמָמוֹנֵיהּ. וְעַל דָּא דָּחִיל לֵיהּ תָּדִיר. אִשְׁתְּכַח יִרְאָה דְּאִיהוּ דָּחִיל לְקוּדְשָׁא בְּרִיךְ הוּא לָא שָׁוֵי לְעִקְּרָא. אִית בַּר נָשׁ דְּדָחִיל מִן קוּדְשָׁא בְּרִיךְ הוּא בְּגִין דְּדָחִיל מֵעוֹנָשָׁא דְּהַהוּא עָלְמָא וְעוֹנָשָׁא דְּגֵיהִנֹּם. תְּרֵין אִלֵּין לָאו עִיקָּרָא דְּיִרְאָה אִנּוּן וְשָׁרְשָׁא דִילֵיהּ.","יִרְאָ\"ה דְּאִיהִי עִקָּרָא, לְמִדְחַל בַּר נָשׁ לְמָארֵיהּ בְּגִין דְּאִיהוּ רַב וְשַׁלִּיט עִקָּרָא וְשָׁרְשָׁא דְּכָל עָלְמִין וְכֹלָּא קַמֵּיהּ כְּלָא חֲשִׁיבִין. כְּמָה דְּאִתְּמָר (דניאל ד׳:ל״ב) וְכָל דָּיְירֵי אַרְעָא כְּלָא חֲשִׁיבִין. וּלְשַׁוְאָה רְעוּתֵיהּ בְּהַהוּא אֲתַר דְּאִקְרֵי (נ\"א ב) יִרְאָה.","בָּכָה רִבִּי שִׁמְעוֹן וְאָמַר וַוי אִי אֵימָא וַוי אִי לָא אֵימָא. אִי אֵימָא יִנְדְּעוּן חַיָּיבִין הֵיךְ יִפְלְחוּן לְמָארֵיהוֹן. אִי לָא אֵימָא יֹאבְדוּן חַבְרַיָּיא מִלָּה דָא. בְּאֲתַר דְּיִרְאָה קַדִּישָׁא שָׁרֵי, מִלְּרַע אִית יִרְאָה רָעָה דְּלָקֵי וּמָחֵי וּמְקַטְרֵג וְאִיהִי רְצוּעָה לְאַלְקָאָה חַיָּיבַיָּא.","וּמָאן דְּדָחִיל בְּגִין עוֹנֶשׁ דְּמַלְקְיוּתָא וְקִטְרוּגָא כְּמָה דְאִתְּמָר. לָא שַׁרְיָא עֲלֵיהּ הַהִיא יִרְאַת ה' דְּאִיקְרֵי יִרְאַת ה' לְחַיִּים. אֶלָּא מָאן שַׁרְיָא עֲלֵיהּ הַהִיא יִרְאָה רָעָה. וְאִשְׁתְּכַח דְּשַׁרְיָא עֲלֵיהּ הַהִיא רְצוּעָה יִרְאָה רָעָה וְלא יִרְאַת ה'.","וּבְגִין כַּךְ אֲתַר דְּאִקְרֵי יִרְאַת ה' רֵאשִׁית דַּעַת אִקְרֵי. וְעַל דָא אִתְכְּלִיל הָכָא פִּקּוּדָא דָּא. וְדָא עִקָּרָא וִיסוֹדָא לְכָל שְׁאָר פִּקּוּדִין דְּאוֹרַיְיתָא. מָאן דְּנָטִיר יִרְאָה (דא) נָטִיר כֹּלָּא. לָא נָטִיר יִרְאָה לָא נָטִיר פִּקּוּדֵי אוֹרַיְיתָא, דְּהָא דָא תַּרְעָא דְכֹלָּא.","וּבְגִין כַּךְ כְּתִיב בְּרֵאשִׁית דְּאִיהִי יִרְאָה, בָּרָא אֱלהִים אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ. דְּמָאן דְּעֲבַר עַל דָּא עֲבַר עַל פִּקּוּדֵי דְאוֹרַיְיתָא. וְעוֹנְשָׁא דְּמָאן דְּעֲבַר עַל דָּא הַאי רְצוּעָה רָעָה אַלְקֵי לֵיהּ. וְהַיְינוּ וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ וְחשֶׁךְ עַל פְּנֵי תְהוֹם וְרוּחַ אֱלֹהִים. הָא אִלֵּין אַרְבַּע עוֹנָשִׁין לְאַעֲנָשָׁא בְּהוֹן חַיָּיבַיָּא.","תֹּהוּ דָּא חֶנֶק, דִּכְתִיב, (ישעיה לה) קַו תֹּהוּ (זכריה ב׳:ה׳) חֶבֶל מִדָּה. בֹּהוּ דָּא סְקִילָה, אַבְנִין דִּמְשׁוּקָעִין גּוֹ תְּהוֹמָא רַבָּא לְעוֹנְשָׁא דְּחַיָּיבַיָּא. וְחשֶׁךְ דָּא שְׂרֵיפָה, דִּכְתִיב, (דברים ה׳:כ׳) וַיְהִי כְּשָׁמְעֲכֶם אֶת הַקּוֹל מִתּוֹךְ הַחשֶׁךְ (דברים ד׳:י״א) וְהָהָר בּוֹעֵר בָּאֵשׁ עַד לֵב הַשָּׁמַיִם חשֶׁךְ כו'. וְדָא אֶשָּׁא תַּקִּיפָא דְּעַל רֵישֵׁיהוֹן דְּחַיָּיבַיָּא שָׁרֵי לְאוֹקְדָא לוֹן.","וְרוּחַ דָּא הֶרֶג בְּסַיָּיף. רוּחַ סְעָרָה חַרְבָּא מְשַׁנְּנָא הִיא מְלַהֲטָא בֵּיהּ. כְּמָא דְאַתְּ אָמֵר, (בראשית ג׳:כ״ד) וְאֶת לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת וְאִקְרֵי רוּחַ. הַאי עוֹנָשָׁא לְמַאן דְּיַעֲבַר עַל פִּקּוּדֵי אוֹרַיְיתָא. וּכְתִיב לְבָתַר יִרְאָה, רֵאשִׁית, דְּאִיהִי כְּלָלָא דְּכֹלָּא. מִכָּאן וָהָלְאָה שְׁאָר פִּקּוּדִין דְּאוֹרַיְיתָא.","פִּקּוּדָא תִּנְיָינָא דָּא אִיהִי פִּקּוּדָא. דְּפִקּוּדָא דְּיִרְאָה אִתְאַחֲדַת בָּהּ וְלָא נַפְקָא מִינָהּ לְעָלְמִין. וְאִיהִי אַהֲבָ\"ה. לְמִרְחַם בַּר נָשׁ לְמָארֵיהּ רְחִימוּ שְׁלִים. וּמָאן אִיהוּ רְחִימוּ שְׁלִים. דָּא אַהֲבָה רַבָּה דִּכְתִיב, (בראשית י״ז:א׳) הִתְהַלֵּךְ לְפָנַי וֶהְיֵה תָמִים שְׁלִים בִּרְחִימוּתָא. וְדָא הוּא דִכְתִיב וַיֹּאמֶר אֱלהִים יְהִי אוֹר דָּא רְחִימוּ שְׁלֵימוּתָא דְּאִקְרֵי (פקודי רנ\"ד ב) אַהֲבָה רַבָּה. וְהָכָא אִיהוּ פִּקּוּדָא לְמִרְחַם בַּר נָשׁ לְמָארֵיהּ כְּדְקָא יְאוּת.","אָמַר רִבִּי אֶלְעָזָר, אַבָּא, רְחִימְתָּא בִּשְׁלִימוּ אֲנָא שְׁמַעְנָא בֵּיהּ. אָמַר לֵיהּ אֵימָא בְּרִי קַמֵּי דְּרִבִּי פִּינְחָס דְּהָא אִיהוּ בְּהַאי דַרְגָא קָאִים. אָמַר רִבִּי אֶלְעָזָר אַהֲבָה רַבָּה הַיְינוּ אַהֲבָה שְׁלֵימְתָּא בִּשְׁלִימוּ דִּתְרֵין סִטְרִין, וְאִי לָא אִתְכְּלִיל בִּתְרֵין סִטְרִין לָאו אִיהוּ אַהֲבָה כְּדְקָא יָאוֹת בִּשְׁלִימוּ."],[[0,"","קפט) \u0003בראשית ברא אלקים\u0004: זו היא המצוה הראשונה לכולן, ומצוה זו נקראת יראת ה', הנקראת ראשית. שכתוב ראשית חכמה יראת ה'. יראת ה' ראשית דעת משום שדבר זה, יראה, נקרא ראשית. וזה הוא שער להכנס אל האמונה. ועל מצוה זו מתקיים כל העולם."],[0,"","פירוש. הוקשה לו, כי כאן חושב המקרא את היראה שהיא \u0003ראשית\u0004 אל ה\u0003חכמה\u0004, וכאן שהיא \u0003ראשית\u0004 אל ה\u0003דעת\u0004. ואומר, מפני שהיראה היא ראשית לכל ספירה וספירה שאי אפשר להשיג שום ספירה זולת ע\"י השגת היראה תחילה."],[0,"","וז\"ש, \u0003תרעא לעאלא גו מהימנותא\u0004: כי אי אפשר להשיג אמונה שלימה זולת מתוך יראתו ית', וכפי שיעור היראה כן שיעור השראת האמונה. וע\"כ \u0003ועל פקודא דא אתקיים כל עלמא\u0004. כי אין העולם מתקיים אלא על תורה ומצות, כמ\"ש אם לא בריתי יומם ולילה חוקות שמים וארץ לא שמתי (ירמיה ג'). וכיון שה\u0003יראה\u0004 היא \u0003ראשית\u0004 ושער לכל מצוה להיותה השער לאמונה, נמצא שעל ה\u0003יראה\u0004 מתקיים כל העולם, וז\"ש הכתוב \u0003בראשית ברא אלהים את השמים ואת הארץ\u0004. שעם ה\u0003יראה\u0004 הנקראת \u0003ראשית\u0004 שכל מצות כלולות בה \u0003ברא אלהים את השמים ואת הארץ\u0004. ולולא היראה לא היה בורא אלהים כלום."],[1,"","קצ) \u0003יראה אתפרש לתלת\u0004 וכו': היראה מפורשת לשלש בחינות, שתים מהן, אין בהן שורש כראוי, ואחת היא שורש היראה. יש אדם שירא מהקב\"ה בשביל שיחיו בניו ולא ימותו, או ירא מעונש גופו או מעונש כספו, ועל כן הוא ירא אותו תמיד. נמצא, שהיראה שהוא ירא מהקב\"ה, לא שם אותה לשורש כי תועלת עצמו היא השורש, והיראה היא תולדה ממנה. ויש אדם הירא מפני הקב\"ה, משום שירא מעונש העולם ההוא ומעונש של הגיהנם. שתי מיני יראות האלו, דהיינו היראה מעונש עוה\"ז, והיראה מעונש עוה\"ב, אינן עיקר היראה ושורשה."],[2,"","קצא) \u0003יראה דאיהי עיקרא\u0004 וכו': היראה שהיא עיקר הוא שאדם יירא מפני אדונו, משום שהוא רב ושליט, העיקר והשורש של כל העולמות, והכל נחשב כאין לפניו. כמו שכתוב, וכל דיירי ארעא כלא חשיבין. וישים חפצו באותו המקום שנקרא יראה."],[2,"","ביאור הדברים, מלמדנו שיש ג' אופנים ביראת ה', שרק אחד מהם נחשב ליראה אמיתית. א) שמתירא מהקב\"ה ושומר מצותיו כדי שיחיו בניו ויהיה נשמר מעונש גופו או ממונו, דהיינו יראה מעונשים שבעוה\"ז. ב) שמתירא גם מעונשים של גיהנם. ואלו השתים אינן יראה אמיתית, כי אינו מקיים היראה מטעם מצות ה', אלא מטעם תועלת עצמו, ונמצא שתועלת עצמו הוא השורש, והיראה היא ענף ומסובבת מתועלת עצמו,"],[2,"","אלא \u0003יראה דאיהי עקרא, למדחל בר נש למאריה בגין דאיהו רב ושליט, עקרא ושרשא דכל עלמין, וכלא קמיה כלא חשיבין\u0004, דהיינו שיירא מהשי\"ת משום שהוא גדול ומושל בכל. הוא גדול משום שהוא השורש, שממנו מתפשטים כל העולמות, וגדלותו מתראה על מעשיו, והוא מושל בכל משום שכל העולמות שברא הן העליונים והן התחתונים, נחשבים לפניו כלא כלום, שאינם מוסיפים משהו על מהותו יתברך."],[2,"","וז\"ש, \u0003ולשואה רעותיה בההוא אתר דאקרי יראה\u0004: שישים לבו ומאויו באותו מקום הנקרא יראה, שיהיה דבוק ביראתו יתברך ברצון ובחשק המותאם והראוי למצות המלך."],[3,"","קצב) \u0003בכה רבי שמעון\u0004 וכו': בכה ר\"ש ואמר, אוי אם אומר אוי אם לא אומר. אם אומר, ידעו הרשעים איך לעבוד לאדונם. ואם לא אומר יאבדו החברים את הדבר הזה. כי במקום שהיראה הקדושה שורה יש כנגדה למטה יראה רעה, שמכה והולמת ומשטינה, והיא רצועה להכות את הרשעים. דהיינו להענישם על עונותיהם. וע\"כ ירא מלגלות, כדי שלא ידעו הרשעים איך להפטר מן העונש. כי עונשם הוא טהרתם."],[3,"","ביאור הדברים, רומז בזה, שאינו יכול לגלות במקום הזה את דבריו במילואם, מפני שמתירא שלא להזיק את הרשעים. והוא כי בא לגלות כאן איך להתדבק בעץ החיים, ולא לנגוע לעולם באילנא דמותא, שזה יכשר רק לאותם שכבר תיקנו בחינת עץ הדעת טו\"ר. אבל הרשעים שעוד לא תיקנו את החטא של עצה\"ד טו\"ר, אסור להם לידע זה, כי הם צריכים לעמול מקודם בכל העבודות, עד שיתקנו את החטא דעצה\"ד."],[3,"","ותמצא כזה גם בכתוב פן ישלח ידו ולקח גם מעץ החיים ואכל וחי לעולם (בראשית ג'). שאחר שחטא אדם בעצה\"ד גורש מג\"ע, מחשש שמא יתדבק בעץ החיים ויחיה לעולם, ונמצא הפגם שעשה בעצה\"ד ישאר לעלם בלי תיקון. ולפיכך, בכדי שלא יאבד מהצדיקים הזכאים לידע דבר זה, גילה הדבר בדרך רמז."],[4,"","קצג) \u0003ומאן דדחיל בגין\u0004 וכו': ומי שירא מפני עונש הכאה ושיטנה, כאמור, אינה שורה עליו אותה יראת ה', הנקראת יראת ה' לחיים. אלא מה שורה עליו. היא אותה יראה רעה. ונמצא ששורה עליו אותה הרצועה, היראה הרעה, ולא יראת ה'."],[5,"","קצד) \u0003ובג\"כ אתר דאקרי\u0004 וכו': ומשום זה, המקום שנקרא יראת ה' נקרא ראשית דעת. וע\"כ נכללה כאן מצוה זו. וזו היא השורש והיסוד לכל שאר מצות התורה. מי ששומר את היראה הוא שומר הכל. ומי שאינו שומר את היראה, אינו שומר מצות התורה, כי זו, היראה, השער לכל."],[5,"","פירוש. סובב על מה שהביא לעיל שפעם אומר הכתוב \u0003ראשית חכמה יראת ה'\u0004, ופעם \u0003יראת ה' ראשית דעת\u0004. וביאר \u0003באתר דיראה קדישא שרי, מלרע אית יראה רעה דלקי ומחי ומקטרג\u0004 וכו', כלומר, שבסיום היראה הקדושה הנקראת \u0003יראת ה' לחיים\u0004, יש שם \u0003יראה רעה דלקי ומחי ומקטרג ואיהי רצועה לאלקאה\u0004, וה\"ס ורגליה יורדות מות. אשר המקיים מצות היראה מטעם \u0003דאיהו רב ושליט\u0004, נמצא מתדבק ב\u0003יראת ה' לחיים\u0004."],[5,"","ואותם המתיראים מטעם עונש דמלקיותא ולא מטעם מצוה, עליהם נאמר, מגורת רשע היא תבואנה (משלי ח') כי היראה דסיומא שולטת עליו ומלקי ליה. ומבחינה זו, שהסיום של היראה שוכנת ב\u0003רצועה רעה\u0004 לאלקי לחייבא, נקראת גם היראה העליונה הקדושה בשם \u0003ראשית דעת יראת ה'\u0004, להורות שיש להדבק רק בבחינת הראשית שלה שהיא \u0003יראת ה' לחיים\u0004. ולהשמר מ\u0003היראה\u0004 ד\u0003מלרע\u0004, שהיא הרצועה בישא. ועי\"ז נתקן החטא דעצה\"ד."],[6,"","קצה) \u0003ובג\"כ כתיב בראשית\u0004 וכו': ומשום זה כתוב, \u0003בראשית\u0004, שהוא יראה, ברא אלקים את השמים ואת הארץ. כי מי שעובר על זו, עובר על כל מצות התורה. וענשו של מי שעובר על זו, הוא, שרצועה הרעה הזו דהיינו, היראה הרעה, מכה אותו. והיינו, והארץ היתה תהו ובהו וחשך על פני תהום ורוח אלקים. הרי אלו ארבעה עונשים להעניש בהם את הרשעים."],[7,"","קצו) \u0003תהו דא חנק\u0004 וכו': \u0003תהו\u0004, זה חנק, שכתוב קו תהו (ישעיה ל\"ד) חבל מדה (זכריה ב'). \u0003בהו\u0004, זו סקילה, היינו אבנים המשוקעות בתוך תהום הגדול, בשביל עונש הרשעים. \u0003וחשך\u0004, זו שרפה, שכתוב, ויהי כשמעכם את הקול מתוך החשך וההר בוער באש עד לב השמים חשך וגו'. וזו היא אש חזקה, שעל ראש רשעים יחול (ירמיה כ\"ג) לשרוף אותם."],[7,"","ביאור הדברים, כי אותם שאינם מקיימים יראת ה' מטעם מצות המלך, אלא מטעם יראת עונש, נלכדים בקליפות \u0003תהו\u0004, שתמהים למה אינם מבינים מחשבותיו ודבריו ית', וקליפה זו נבחנת לחבל מחנק על צוארו של האדם המפסיק לו אויר דקדושה לנשימת חייו. וז\"ש \u0003דכתיב קו תהו, חבל מדה\u0004, מקרא א' כתוב \u0003קו תהו\u0004, ומקרא ב' \u0003חבל מדה\u0004, ובא זה ולמד על זה, אשר פירושו של קו תהו הוא \u0003חבל מדה\u0004, כי לפי הקו והשיעור של תמיהתו כן מדת החבל שהס\"א משליך על צוארו וחונק אותו. והסה\"כ \u0003מושכי העון בחבלי השוא\u0004 (ישעיה ה')."],[7,"","וז\"ש, \u0003בהו דא סקילה\u0004, אחרי שכבר ניצוד ע\"י הס\"א בחבל על צוארו, כבר יש להן כח לעשות בו כחפצן, או לסלקו או לשרפו או להרגו בסייף, כמ\"ש והולך. ו\u0003סקילה\u0004 פירושו שמרוצצין את גלגלתו ע\"י תאוות רעות ומחשבות רעות ומושכים אותו לתהומא רבא להענישו \u0003וחשך דא שריפה\u0004 וכו' \u0003שרי לאוקדא לון\u0004 שס\"א מסבב אותו באש חזק ההולך ושורף החיות דקדושה מהם."],[8,"","קצז) \u0003ורוח דא הרג\u0004 וכו': \u0003ורוח\u0004 זהו הרג בחרב. כי רוח סערה היא חרב שנונה, הלוהטת בו. כמו שאתה אומר, ואת להט החרב המתהפכת, ונקראת רוח. זה הוא עונש למי שעובר על מצות התורה, שכתוב אחר יראה, הנקראת ראשית, שהיא כלל הכל. כי אחר בראשית שהיא יראה, נאמר תהו ובהו וחשך ורוח, שהם עונש ד' מיתות, מכאן ולהלאה, שאר מצות התורה."],[8,"","פירוש. כי הס\"א שולח בו \u0003רוח סערה\u0004, שהוא כמו חרב שנונה המפרידה ראשו מגופו ופסקיה לחיותיה."],[8,"","וז\"ש, \u0003האי עונשא\u0004 וכו' \u0003וכתיב לבתר יראה ראשית, דאיהי כללא דכלא\u0004: סובב על הנ\"ל, שכל המצות שבתורה כלולות בב' הפסוקים הראשונים, מ\u0003בראשית\u0004 עד \u0003ויאמר אלהים יהי אור\u0004."],[8,"","ואומר, \u0003דהאי עונשא\u0004 הנזכר שהוא ד' מיתות המרומזות ב\u0003תהו, בהו, חשך, ורוח\u0004, הן כתובות אחר \u0003יראה ראשית\u0004 המרומז בכתוב \u0003בראשית ברא אלהים\u0004, ונמצא שהפסוק הא' הוא \u0003יראה ראשית\u0004, דהיינו עיקר ה\u0003יראה\u0004 שהיא \u0003לחיים\u0004, והפסוק הב' הוא העונש למי שאינו דבוק ב\u0003יראה ראשית\u0004, והם \u0003כללא דכלא\u0004, להיותם השער לאמונתו יתברך כנ\"ל. ונמצא שכל המצות שבתורה כלולות בה. \u0003מכאן והלאה שאר פקודין דאורייתא\u0004 מה\u0003פסוק ויאמר אלהים יהי אור\u0004 ואילך, דהיינו כל המצות שבתורה, הן פרטים כולן של מצות ה\u0003יראה\u0004."],[9,"","קצח) \u0003פקודא תניינא\u0004 וכו': המצוה השניה, זו היא מצוה שמצות היראה מתאחזת בה ואינה יוצאת ממנה לעולם, והיא \u0003אהבה\u0004, שיאהב אדם את אדונו אהבה שלמה. ומה היא אהבה שלמה. זו היא אהבה רבה, שכתוב, התהלך לפני והיה תמים, תמים, פירושו שלם באהבה. וזהו שכתוב, ויאמר אלקים יהי אור, זו היא אהבה שלמה הנקראת אהבה רבה. וכאן היא מצוה, שיאהב אדם את אדונו כראוי."],[9,"","ביאור הדברים, כי יש \u0003אהבה\u0004 התלויה בדבר, דהיינו שבאה מרוב טובה שהשפיע לו השי\"ת, שעי\"ז נתדבק בו ית' בלב ונפש. והנה אע\"פ שדבוק בו ית' בתכלית השלימות מ\"מ נחשבת ל\u0003אהבה\u0004 בלתי שלימה. וזה שדרשו רז\"ל (ב\"ר פ\"ל) על הפסוק את האלהים התהלך נח, אשר נח היה צריך סעד לתמכו, כי היה נסעד ברוב טובה שהשפיע לו השי\"ת."],[9,"","אמנם אברהם לא היה צריך סעד לתמכו, כמ\"ש \u0003התהלך לפני והיה תמים\u0004. כי \u0003התהלך לפני\u0004, פירושו בלי סעד, אלא \u0003לפני\u0004, ואע\"פ שלא תדע אם אבא אחריך לסעדך. וז\"ש \u0003רחימו שלים, דא אהבה רבה, דכתיב התהלך לפני והיה תמים\u0004, דהיינו שלא יהיה נצרך שום סעד לתמכו, כמו שנאמר אצל אברהם התהלך לפני, \u0003והיה תמים שלים ברחימותא\u0004, שאע\"פ שאיני נותן לך כלום, מ\"מ תהיה אהבתך שלימה להדבק בי בכל לב ונפש."],[10,"","קצט) \u0003אמר רבי אלעזר\u0004 וכו': אר\"א: אבי, אהבה בשלמות אני שמעתי פירושה. אמר לו: אמור בני לפני רבי פנחס, כי הוא נמצא באותה המדרגה. אמר רבי אלעזר, אהבה רבה, היינו אהבה שלמה שהיא בשלמות משני הצדדים, ואם לא נתכללה בשני הצדדים, אין היא אהבה בשלמות כראוי."],[10,"","פירוש. שאמר לו לפרש בחינת אהבה רבה \u0003קמיה דרבי פנחס\u0004 משום שהוא כבר השיג מדת \u0003אהבה רבה\u0004 כהלכתה, ויבין היטב מה שיאמר."],[10,"","וז\"ש, \u0003אהבה שלימתא בשלימו דתרין סטרין\u0004: כמ\"ש להלן, \u0003בין בדינא ובין בטיבו\u0004, ואפילו הוא נוטל את נשמתך תהיה אהבתך בו ית' בשלמות הגמורה, כמו בעת שנותן לך כל טוב שבעולם."]],[[0,"","בְּרֵאשִׁית בָּרָא אֱלֹהִים. זוֹהִי הַמִּצְוָה הָרִאשׁוֹנָה שֶׁל הַכֹּל. וְנִקְרֵאת מִצְוָה זוֹ יִרְאַת ה', שֶׁנִּקְרֵאת רֵאשִׁית, שֶׁכָּתוּב (תהלים קיא) רֵאשִׁית חָכְמָה יִרְאַת ה'. (משלי א) יִרְאַת ה' רֵאשִׁית דַּעַת. מִשּׁוּם שֶׁדָּבָר זֶה נִקְרָא רֵאשִׁית, וְזֶה הַשַּׁעַר לְהִכָּנֵס לְתוֹךְ הָאֱמוּנָה, וְעַל הַמִּצְוָה הַזּוֹ מִתְקַיֵּם כָּל הָעוֹלָם."],[1,"","הַיִּרְאָה נִפְרֶדֶת לִשְׁלֹשָׁה צְדָדִים, שְׁנַיִם מֵהֶם אֵין בָּהֶם עִקָּר כָּרָאוּי, וְאֶחָד עִקָּר שֶׁל יִרְאָה. יֵשׁ אָדָם שֶׁיָּרֵא מֵהַקָּדוֹשׁ בָּרוּךְ הוּא כְּדֵי שֶׁיִּחְיוּ בָנָיו וְלֹא יָמוּתוּ, אוֹ שֶׁיָּרֵא מֵעֹנֶשׁ שֶׁל גּוּפוֹ אוֹ שֶׁל מָמוֹנוֹ, וְעַל כֵּן יָרֵא מִמֶּנּוּ תָּמִיד. נִמְצֵאת הַיִּרְאָה שֶׁהוּא יָרֵא מִן הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא שָׂם אוֹתָהּ לְעִקָּר. יֵשׁ אָדָם שֶׁפּוֹחֵד מִן הַקָּדוֹשׁ בָּרוּךְ הוּא מִשּׁוּם שֶׁפּוֹחֵד מֵעֹנֶשׁ אוֹתוֹ הָעוֹלָם וּמֵעֹנֶשׁ הַגֵּיהִנֹּם. שְׁנֵי אֵלֶּה לֹא עִקָּר שֶׁל יִרְאָה הֵם וְהַשֹּׁרֶשׁ שֶׁלּוֹ."],[2,"","הַיִּרְאָ\"ה שֶׁהִיא עִקָּר, שֶׁאָדָם יִירָא מֵרִבּוֹנוֹ מִשּׁוּם שֶׁהוּא גָדוֹל וְשַׁלִּיט, עִקַּר וְשֹׁרֶשׁ שֶׁל כָּל הָעוֹלָמוֹת, וְהַכֹּל לְפָנָיו כְּלֹא חֲשׁוּבִים, כְּמוֹ שֶׁנֶּאֱמַר (דניאל ד) וְכָל דַּיָּרֵי הָאָרֶץ כְּאֵינָם חֲשׁוּבִים, וְלָשִׂים אֶת רְצוֹנוֹ בְּאוֹתוֹ הַמָּקוֹם שֶׁנִּקְרָא יִרְאָה."],[3,"","בָּכָה רַבִּי שִׁמְעוֹן וְאָמַר, אוֹי אִם אֹמַר, וְאוֹי אִם לֹא אֹמַר. אִם אֹמַר - יֵדְעוּ הָרְשָׁעִים אֵיךְ יַעַבְדוּ אֶת רִבּוֹנָם. אִם לֹא אֹמַר - יְאַבְּדוּ הַחֲבֵרִים אֶת הַדָּבָר הַזֶּה. בְּמָקוֹם שֶׁשּׁוֹרָה יִרְאָה קְדוֹשָׁה, מִלְּפָנֶיהָ יֵשׁ יִרְאָה רָעָה שֶׁמַּלְקָה וּמַכָּה וּמְקַטְרֶגֶת, וְהִיא הָרְצוּעָה לְהַלְקוֹת אֶת הָרְשָׁעִים,"],[4,"","וּמִי שֶׁפּוֹחֵד בִּגְלַל עֹנֶשׁ הַמַּלְקוֹת וְהַקִּטְרוּג כְּמוֹ שֶׁנִּתְבָּאֵר, לֹא שׁוֹרָה עָלָיו אוֹתָהּ יִרְאַת ה' שֶׁנִּקְרֵאת יִרְאַת ה' לְחַיִּים. אֶלָּא מִי שׁוֹרָה עָלָיו הַיִּרְאָה הָרָעָה הַהִיא. וְנִמְצָא שֶׁשּׁוֹרָה עָלָיו הָרְצוּעָה הַהִיא, יִרְאָה רָעָה וְלֹא יִרְאַת ה'."],[5,"","וּמִשּׁוּם כָּךְ הַמָּקוֹם שֶׁנִּקְרָא יִרְאַת ה' נִקְרָא רֵאשִׁית דַּעַת, וְעַל כֵּן נִכְלֶלֶת כָּאן הַמִּצְוָה הַזּוֹ, וְזֶה הָעִקָּר וְהַיְסוֹד לְכָל שְׁאָר הַמִּצְווֹת שֶׁל הַתּוֹרָה. מִי שֶׁשּׁוֹמֵר הַיִּרְאָה הַזּוֹ - שׁוֹמֵר הַכֹּל. לֹא שׁוֹמֵר יִרְאָה - לֹא שׁוֹמֵר אֶת מִצְווֹת הַתּוֹרָה, שֶׁהֲרֵי זֶה הַשַּׁעַר שֶׁל הַכֹּל."],[6,"","וּמִשּׁוּם כָּךְ כָּתוּב בְּרֵאשִׁית, שֶׁהִיא יִרְאָה, בָּרָא אֱלֹהִים אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ. שֶׁמִּי שֶׁעוֹבֵר עַל זֶה, עוֹבֵר עַל מִצְווֹת הַתּוֹרָה. וְעָנְשׁוֹ שֶׁל מִי שֶׁעוֹבֵר עַל זֶה - הָרְצוּעָה הָרָעָה הַזּוֹ מַלְקָה אוֹתוֹ, וְהַיְנוּ וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ וְחֹשֶׁךְ עַל פְּנֵי תְהוֹם וְרוּחַ אֱלֹהִים. הִנֵּה אֵלּוּ אַרְבָּעָה עֳנָשִׁים לְהַעֲנִישׁ בָּהֶם אֶת הָרְשָׁעִים."],[7,"","תֹּהוּ - זֶה חֶנֶק, שֶׁכָּתוּב (ישעיה לד) קַו תֹּהוּ, (זכריה ב) חֶבֶל מִדָּה. בֹּהוּ - זוֹ סְקִילָה, אֲבָנִים הַמְשֻׁקָּעוֹת בְּתוֹךְ הַתְּהוֹם הַגָּדוֹל לַעֲנֹשׁ אֶת הָרְשָׁעִים. וְחֹשֶׁךְ - זוֹ שְׂרֵפָה, שֶׁכָּתוּב (דברים ה) וַיְהִי כְּשָׁמְעֲכֶם אֶת הַקּוֹל מִתּוֹךְ הַחֹשֶׁךְ, (שם ד) וְהָהָר בֹּעֵר בָּאֵשׁ עַד לֵב הַשָּׁמַיִם חֹשֶׁךְ וְכוּ'. וְזוֹ הָאֵשׁ הַחֲזָקָה שֶׁעַל רָאשֵׁי הָרְשָׁעִים מַתְחִילָה לִשְׂרֹף אוֹתָם."],[8,"","וְרוּחַ - זֶה הֶרֶג בְּסַיִף. רוּחַ סְעָרָה, חֶרֶב שְׁנוּנָה מְלַהֶטֶת בּוֹ, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ג) וְאֶת לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת, וְנִקְרֵאת רוּחַ. הָעֹנֶשׁ הַזֶּה לְמִי שֶׁיַּעֲבֹר עַל מִצְווֹת הַתּוֹרָה. וְאַחַר כָּתוּב יִרְאָה רֵאשִׁית, שֶׁהִיא הַכְּלָל שֶׁל הַכֹּל. מִכָּאן וָהָלְאָה שְׁאָר מִצְווֹת הַתּוֹרָה."],[9,"","מִצְוָה שְׁנִיָּה - זוֹהִי מִצְוָה שֶׁמִּצְוָה שֶׁל יִרְאָה נֶאֶחְזָה בָּהּ וְלֹא יוֹצֵאת מִמֶּנָּה לְעוֹלָמִים, וְהִיא אַהֲבָ\"ה. שֶׁאָדָם יאהַב אֶת רִבּוֹנוֹ אַהֲבָה שְׁלֵמָה. וּמַה הִיא אַהֲבָה שְׁלֵמָה זוֹ אַהֲבָה רַבָּה, שֶׁכָּתוּב (שם יז) הִתְהַלֵּךְ לְפָנַי וֶהְיֵה תָמִים, שָׁלֵם בְּאַהֲבָה. וְזֶהוּ שֶׁכָּתוּב וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר. זוֹ אַהֲבָה שְׁלֵמָה שֶׁנִּקְרֵאת אַהֲבָה רַבָּה. וְכָאן הִיא הַמִּצְוָה שֶׁאָדָם יֹאהַב אֶת רִבּוֹנוֹ כָּרָאוּי."],[10,"","אָמַר רַבִּי אֶלְעָזָר, אַבָּא, אַהֲבָה בִּשְׁלֵמוּת אֲנִי שָׁמַעְתִּי בָּזֶה. אָמַר לוֹ, אֱמֹר, בְּנִי, לִפְנֵי רַבִּי פִּינְחָס, שֶׁהֲרֵי הוּא עוֹמֵד בַּדַּרְגָּה הַזּוֹ. אָמַר רַבִּי אֶלְעָזָר, אַהֲבָה רַבָּה הַיְנוּ אַהֲבָה שְׁלֵמָה בִּשְׁלֵמוּת שֶׁל שְׁנֵי צְדָדִים, וְאִם אֵין נִכְלֶלֶת בִּשְׁנֵי צְדָדִים - אֵינָהּ אַהֲבָה כָּרָאוּי בִּשְׁלֵמוּת."]]],[["וְעַל דָּא תָּנִינָן בִּתְרֵין סִטְרִין אִתְפְּרַשׁ אַהֲבָה רְחִימוּ דְּקוּדְשָׁא בְּרִיךְ הוּא. אִית מָאן דְּרָחִים לֵיהּ מִגּוֹ דְּאִית לֵיהּ עוּתָרָא, אוֹרְכָּא דְּיוֹמִין, בְּנִין סַחֲרָנֵיהּ, שַׁלִּיט עַל שַׂנְאוֹי, אָרְחוֹי מִתְתַּקְּנָן לֵיהּ, וּמִגוֹ כָּךְ רָחִים לֵיהּ. וְאִי לְהַאי יְהֵא בְּהִפּוּכָא וִיהַדַּר עֲלֵיהּ קוּדְשָׁא בְּרִיךְ הוּא גִּלְגּוּלָא דְּדִינָא קַשְׁיָא, יְהֵא שַׂנְיָא לֵיהּ וְלָא יִרְחֵם לֵיהּ כְּלָל. וּבְגִין כָּךְ רְחִימוּ דָא לָאו אִיהוּ אַהֲבָה דְּאִית לֵיהּ עִקָּרָא.","רְחִימוּ דְּאִקְרֵי שְׁלִים הַהוּא דְּהֲוֵי בִּתְרֵין סִטְרִין בֵּין בְּדִינָא בֵּין בְּטִיבוּ. וְתִקּוּנָא דְּאָרְחוֹי דְּרָחִים לֵיהּ לְמָארֵיהּ כְּמָה דִּתְנֵינָן אֲפִלּוּ הוּא נָטִיל נִשְׁמָתָךְ מִינָךְ. דָּא אִיהוּ רְחִימוּ שְׁלִים דְּהֲוֵי בִּתְרִין סִטְרִין (יז ע\"ב). וְעַל דָּא אוֹר דְּמַעֲשֵׂה בְרֵאשִׁית נָפַק וּלְבָתַר אִגְנִיז. כַּד אִגְנִיז נָפַק דִּינָא קַשְׁיָא וְאִתְכְּלִילוּ תְּרֵין סִטְרִין כְּחֲדָא לְמֶהֱוֵי שְׁלִימוּ דָּא אַהֲבָה כְּדְקָא יְאוּת.","נָטְלֵיהּ רִבִּי שִׁמְעוֹן וּנְשָׁקֵיהּ. אֲתָא רִבִּי פִּינְחָס וּנְשָׁקֵיהּ וּבֵרָכֵיהּ וְאָמַר בְּוַדַּאי קוּדְשָׁא בְּרִיךְ הוּא שַׁדְּרַנִי הָכָא. דָּא הוּא (לעיל דף י\"א ע\"א) נְהִירוּ דַּקִּיק דְּאָמְרוּ לִי דְּאִתְכְּלִיל בְּבֵיתָאִי וּלְבָתַר נָהִיר כָּל עָלְמָא. אָמַר רִבִּי אֶלְעָזָר וַדַּאי לָא אִיצְטְרִיךְ לְאִתְנְשֵׁי יִרְאָ\"ה בְּכָל פִּקּוּדִין, כָּל שְׁכֵּן בְּפִקּוּדָא דָא אִצְטְרִיךְ יִרְאָה לְאִתְדַּבְּקָא בְּהַאי. הֵיךְ אִתְדַּבְּקָא. אַהֲבָה אִיהִי בְּסִטְרָא חַד טַב כְּמָה דְּאִתְּמָר דְּיָהַב עוּתְרָא וְטַב אוֹרְכָּא דְחַיֵּי בְּנֵי מְזוֹנֵי, כְּדֵין אִיצְטְרִיךְ לְאַתְעָרָא יִרְאָה וּלְמִדְחַל דְּלָא יִגְרוֹם חוֹבָא. וְעַל דָּא כְּתִיב, (משלי כ״ח:י״ד) אַשְׁרֵי אָדָם מְפַחֵד תָּמִיד, בְּגִין דְּהָא כָּלִיל יִרְאָ\"ה בְּאַהֲבָ\"ה.","וְהָכִי אִצְטְרִיךְ בְּסִטְרָא אָחֳרָא דְּדִינָא קַשְׁיָא לְאַתְעָרָא בֵּיהּ יִרְאָה. כַּד חָמֵי דְּדִינָא קַשְׁיָא שַׁרְיָא עֲלוֹי, כְּדֵין יִתְעַר יִרְאָה וְיִדְחַל לְמָארֵיהּ כְּדְקָא יְאוּת וְלָא יַקְשֶׁה לִבֵּיהּ. וְעַל דָּא כְּתִיב, (משלי כ״ח:י״ד) וּמַקְשֶׁה לִבּוֹ יִפּוֹל בְּרָעָה. בְּהַהוּא סִטְרָא אָחֳרָא דְּאִקְרֵי רָעָה. אִשְׁתְּכַח יִרְאָה דְּאִתְאַחֲדַת בִּתְרֵין סִטְרִין וְאִתְכְּלִילַת מִנַּיְיהוּ. וְדָא אִיהוּ אַהֲבָה שְׁלֵימָתָא כְּדְקָא יְאוּת.","פִּקּוּדָא תְּלִיתָאָה לְמִנְדַע דְּאִית אֱלָהָא רַבְרְבָא וְשַׁלִּיטָאָה בְּעָלְמָא. וּלְיַיחֲדָא לֵיהּ בְּכָל יוֹמָא יִחוּדָא כְּדְקָא יָאוֹת בְּאִנּוּן שִׁית סִטְרִין עִלָאִין. וּלְמֶעְבַּד לוֹן יִחוּדָא חֲדָא בְּשִׁית תֵּבִין דִּשְׁמַע יִשְׂרָאֵל וּלְכַוְּונָא רְעוּתָא לְעֵילָא בַּהֲדַיְיהוּ. וְעַל דָּא אֶחָד אִצְטְרִיךְ לְאַרְכָּא לֵיהּ (נ\"א כשית) בְּשִׁית תֵּבִין.","וְדָא הוּא דִכְתִיב יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם אֶל מָקוֹם אֶחָד. יִתְכַּנְּשׁוּן דַּרְגִּין דִּתְחוֹת שְׁמַיָא לְאִתְאַחֲדָא בֵּיהּ (יראה) לְמֶהֱוֵי בִּשְׁלִימוּ לְשִׁית סִטְרִין כְּדְקָא יְאוּת. וְעִם כָּל דָּא בְּהַהוּא יִחוּדָא אִצְטְרִיךְ לְקַשְׁרָא בֵּיהּ יִרְאָה דְּאִצְטְרִיךְ לְאַרְכָּא בְּדָלֶ\"ת דְּאֶחָד. דְּדָלֶ\"ת דְּאֶחָד גְּדוֹלָה. וְהַיְינוּ דִּכְתִיב וְתֵרָאֶה הַיַּבָּשָׁה דְּתִתְחֲזֵי וְתִתְקַשֵּׁר דָלֶ\"ת דְּאִיהוּ יַבָּשָׁה בְּהַהוּא יִחוּדָא.","וּלְבָתַר דְּאִתְקַשַּׁר תַּמָּן לְעֵילָא אִיצְטְרִיךְ לְקַשְּׁרָא לָהּ לְתַתָּא בְּאֻכְלוּסָהָא בְּשִׁית סִטְרִין אָחֳרָנִין דִּלְתַתָּא, בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. דְּאִית בֵּיהּ שִׁית תֵּבִין אָחֳרָנִין דְּיִחוּדָא. כְּדֵין מַה דְּהֲוַת יַבָּשָׁה אִתְעֲבִידַת אֶרֶץ לְמֶעְבַּד פֵּירִין וְאִיבִּין וּלְנָטְעָא אִילָנִין.","וְהַיְינוּ דִּכְתִיב וַיִּקְרָא אֱלֹהִים לַיַּבָּשָׁה אֶרֶץ בְּהַהוּא יִחוּדָא דִּלְתַתָּא אַרְעָא רַעֲוָא שְׁלִים כְּדְקָא יְאוּת. וְעַל דָּא כִּי טוֹב, כִּי טוֹב תְּרֵי זִמְנֵי. חַד יִחוּדָא עִלָאָה וְחַד יִחוּדָא תַּתָּאָה. כֵּיוָן דְּאִתְאֲחִיד בִּתְרֵין סִטְרִין מִכָּאן וּלְהָלְאָה תַּדְּשֵׁא הָאָרֶץ דֶּשֶׁא. אִתְתַּקָּנַת לְמֶעְבַּד פֵּירִין וְאִיבִּין כְּדְקָא יְאוּת.","פִּקּוּדָא רְבִיעָאָה לְמִנְדַע דְה' הוּא הָאֱלהִים, כְּמָא דְאַתְּ אָמֵר, (דברים ד׳:ל״ט) וְיָדַעְתָּ הַיּוֹם וַהֲשֵׁבוֹתָ אֶל לְבָבֶךָ כִּי יְיָ הוּא הָאֱלֹהִים. וּלְאִתְכְּלָלָא שְׁמָא דֶּאֱלֹהִים בִּשְׁמָא דְּיְיָ. לְמִנְדַע דְּאִנּוּן חַד וְלֵית בְּהוּ פִּרוּדָא.","וְהַיְנוּ רָזָא דִכְתִיב יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמָיִם לְהָאִיר עַל הָאָרֶץ. לְמֶהוֵי תְּרֵין שְׁמָהָן חַד בְּלָא פִּרוּדָא כְּלָל. לְאִתְכְּלָלָא מְאֹרֹת חָסֵר בִּשְׁמָא דְּשָׁמַיִם (נ\"א דרשים) דְּאִנּוּן חַד וְלֵית בְּהוּ פִּרוּדָא. נְהוֹרָא אוּכְמָא בִּנְהוֹרָא חִיוְורָא לֵית בְּהוּ פִּרוּדָא וְכֹלָא חַד. וְדָא הוּא עֲנָנָא חִיוְורָא דִימָמָא וְעֲנָנָא דְאֶשְׁתָּא בְּלֵילְיָא. (כמה דאמרו חברייא) מִדַּת יוֹם וּמִדַת לַיְלָה. וּלְאִתְתַּקַּן דָּא בְּדָא לְאַנְהָרָא כְּמָה דְאִתְּמָר לְהָאִיר עַל הָאָרֶץ."],[[0,"","ר) \u0003ועל דא תנינן\u0004 וכו': וע\"כ למדנו, בשני צדדים מפורשת האהבה להקב\"ה, יש מי שאוהב אותו בשביל שיש לו עושר, אריכות ימים, בנים סביב לו, מושל על שונאיו, דרכיו יכונו לו, ומתוך כך אוהב אותו. ואם יהיה לזה ההפך, והקב\"ה יחזור עליו הגלגל בדין קשה, יהיה שונא אותו, ולא יאהב אותו כלל. ומשום זה אהבה זו אינה אהבה שיש לה יסוד."],[0,"","פירוש. שמתוך ששורש אהבתו מיוסד על דבר משהו, נמצא, אם בטל הדבר, בטלה האהבה."],[1,"","רא) \u0003רחימו דאקרי שלים\u0004 וכו': האהבה שנקראת שלמה, היא, אותה האהבה שהיא בשני צדדים, בין בדין, בין בחסד והצלחת דרכיו. שיאהב את הקב\"ה, כמו שלמדנו, אפילו הוא לוקח ממך את נשמתך, זו היא אהבה שלמה שהיא בשני צדדים, בחסד ובדין. ועל כן, האור של מעשה בראשית יצא, ואחר כך נגנז, וכשנגנז יצא דין הקשה, ונכללו ב' הצדדים, חסד ודין, יחד, שיהיו שלמות. זו היא אהבה כראוי."],[1,"","פירוש. כי האור שנברא בששת ימי בראשית, דהיינו במאמר יהי אור, חזר ונגנז, כמ\"ש (בראשית א' דף רפ\"א אות שנ\"ב). \u0003יהי אור לעוה\"ז ויהי אור לעוה\"ב\u0004 כי נגנז האור מעוה\"ז והוא מתגלה רק לצדיקים לעוה\"ב,"],[1,"","ולמה נגנז, והוא \u0003כד אגנז נפק דינא קשיא\u0004, שעם גניזת האור יצא דין קשה בעוה\"ז, שעי\"ז \u0003ואתכלילו תרין סטרין כחדא, למהוי שלימו\u0004, שניתן מקום להתכללות ב' הקצוות כאחת, כי עתה תצויר האפשרות לגלות שלימות אהבתו גם בשעה שנוטל את נפשו ממנו, וניתן מקום להשלמת ה\u0003אהבה\u0004. באופן שאם לא היה נגנז, והדין הקשה לא היה נגלה, היתה \u0003אהבה רבה\u0004 זו חסרה מהצדיקים, ולא היתה לה שום אפשרות לבוא פעם לכלל גילוי."],[2,"","רב) \u0003נטליה ר' שמעון\u0004 וכו': לקחו ר' שמעון ונשקו. בא רבי פנחס ונשקו וברכו. ואמר, בודאי הקב\"ה שלחני כאן, זה הוא אור הדק שאמרו לי שנכלל בביתי, ולאחר כך יאיר כל העולם. (לעיל אות קפ\"ו) א\"ר אלעזר, ודאי, היראה אינה צריכה להשכח בכל המצות, כל שכן במצוה זו, האהבה, צריכה היראה להתדבק בה. ואיך היא מתדבקת. היינו, כי האהבה היא טוב מצד אחד, כאמור, בשעה שנותן לו עושר וטוב, אריכות ימים בנים ומזון, ואז צריכים לעורר היראה, ולירא שלא יגרום החטא, ויתהפך עליו הגלגל. ועל זה כתוב, אשרי אדם מפחד תמיד, כי היראה כלולה באהבה."],[3,"","רג) \u0003והכי אצטריך בסטרא\u0004 וכו': וכך צריך לעורר היראה בצד האחר של דין קשה. כי כשרואה שדין קשה שורה עליו, יעורר אז היראה ויירא מפני אדונו כראוי ולא יקשה לבו. ועל זה כתוב ומקשה לבו יפול ברעה. דהיינו שיפול בצד האחר ההוא שנקרא רעה. נמצאת היראה שנתאחזה בשני הצדדים, בצד הטוב והאהבה, ובצד דין הקשה, ונכללת מהם. ואם היראה נכללת בצד הטוב והאהבה, היא אהבה השלמה כראוי."],[3,"","ביאור הדברים, כי היראה היא מצוה הכוללת כל המצות שבתורה להיותה השער לאמונתו ית', שלפי התעוררות יראתו כן שורה בו האמונה בהשגחתו ית' כנ\"ל, וע\"כ \u0003לא אצטריך לאתנשי יראה בכל פקודין\u0004, אין לשכוח ה\u0003יראה\u0004 בכל מצוה ומצוה \u0003כל שכן בפקודא דא\u0004, וכ\"ש במצות ה\u0003אהבה\u0004 שצריכים לעורר עמה ה\u0003יראה\u0004, כי במצות האהבה, היראה מתיחדת בה ממש כנ\"ל. וע\"כ צריכין לעורר היראה ב\u0003ב'\u0004 ה\u0003סטרין\u0004 של ה\u0003אהבה\u0004, הן ב\u0003אהבה בעת טיבו ותקונא דארחוי\u0004, והן בה\u0003אהבה\u0004 בעת \u0003דינא קשיא\u0004, כמ\"ש והולך."],[3,"","וז\"ש, \u0003אצטריך יראה לאתדבקא בהאי היך אתדבקת אהבה\u0004: מורה שלא נטעה בדבריו במה שאמר ש\u0003אהבה\u0004 שלים הוא בעת שנוטל נפשו, דהיינו בעת \u0003דינא קשיא\u0004, ונחשוב שהכוונה היא שלא לפחוד כלום מפני הדין הקשה, רק להתדבק באהבתו במסירות נפש בלי שום \u0003יראה\u0004. וזהו שמסיים ד\u0003אצטריך יראה לאתדבקא בהאי היך אתדבקת אהבה\u0004, שגם את \u0003יראה\u0004 צריך לעורר בעת ההיא כמו שמעורר את \u0003רחימו שלים\u0004."],[3,"","והנה חוזר על \u0003ב' הסטרין\u0004 של ה\u0003אהבה\u0004 שמביא לעיל, דהיינו \u0003בין בדינא ובין בטיבו ותקונא דארחוי\u0004, ואומר שצריכים לעורר ה\u0003יראה בב'\u0004 ה\u0003סטרין\u0004 של ה\u0003אהבה\u0004, שבעת ה\u0003טיבו ותיקונא דארחוי\u0004, צריך לעורר יראה מפניו ית' שמא יגרום החטא ויתקרר מאהבתו ית', ונמצא בזה שכולל ה\u0003יראה\u0004 ב\u0003אהבה\u0004. וכן בסטרא הב' של ה\u0003אהבה\u0004 בעת \u0003דינא קשיא\u0004 יעורר יראה ממנו ית', ולא יקשה לבו ויסיח דעתו מן הדין, ונמצא בזה, שגם כאן כולל ה\u0003יראה\u0004 ב\u0003אהבה\u0004, ואם נוהג כן נמצא תמיד ב\u0003אהבה\u0004 שלימה כראוי להיות."],[3,"","ועל התכללות ה\u0003יראה\u0004 ב\u0003אהבה\u0004 בסטרא ד\u0003טיבו\u0004 מביא הפסוק \u0003אשרי אדם מפחד תמיד\u0004, ודורש את המלה \u0003תמיד\u0004, שמשמע אפילו בעת שהשי\"ת עושה טובות עמו צריך ג\"כ לפחד ממנו, והיינו שמא יגרום החטא. ועל התכללות ה\u0003יראה\u0004 ב\u0003אהבה\u0004 בסטרא ד\u0003דינא\u0004, מביא הכתוב \u0003מקשה לבו יפול ברעה\u0004, שהמשמעות היא שאין להקשות לבו בעת הדין משום טעם שבעולם, כי אז יפול ל\u0003ס\"א דאקרי רעה\u0004. אלא שצריכים, אז לעורר ביותר את \u0003היראה\u0004 לירא מפניו, ולכלול ה\u0003יראה\u0004 ב\u0003אהבה\u0004 שלים שלו שבעת ההיא. אמנם הן היראה הראשונה והן היראה השניה אינן ח\"ו לתועלת עצמו, אלא רק מפחד שמא ימעט בעשית נ\"ר ליוצרו והבן היטב."],[3,"","והנה נתבארו היטב ב' הפקודין הראשונות ש\u0003פקודא קדמאה\u0004 היא ה\u0003יראה\u0004 והיא כללא של כל התורה ומצות, והיא \u0003בראשית\u0004 ומתבארת בפסוק הראשון. והיא \u0003בראשית ברא אלהים את השמים ואת הארץ\u0004. כלומר, שה\u0003יראה\u0004 שהיא \u0003ראשית\u0004, ממנה יצאו \u0003השמים והארץ\u0004 שהם זו\"ן וענפיהם שהם בי\"ע. והפסוק הב' הוא פירוש ענשה, שהם ד' מיתות: תהו הוא \u0003חנק\u0004, בהו \u0003סקילה\u0004, חושך \u0003שריפה\u0004 ורוח \u0003הרג\u0004."],[3,"","ו\u0003פקודא תנינא\u0004, היא \u0003אהבה\u0004, והיא מתבארת בכתוב \u0003ויאמר אלהים יהי אור\u0004 וכו'. ויש בה \u0003ב' סטרין\u0004: סטרא א' היא, ב\u0003עותרא, ובארכא דיומין\u0004 וכו'. סטרא ב' היא \u0003בכל נפשך ובכל מאדך\u0004. דהיינו בעת שנוטל ה\u0003נפש\u0004 וה\u0003מאד\u0004 שלך תהיה ה\u0003אהבה\u0004 שלימה, כמו בעת שנותן לך \u0003עותרא ואורכא דיומין\u0004 וכו', אשר בכדי לגלות \u0003אהבה\u0004 זו, נגנז האור דמעשה בראשית \u0003וכד אגניז נפק דינא קשיא\u0004 כנ\"ל, גם צריכין לאכללא ה\u0003יראה\u0004 ב\u0003אהבה\u0004 ב\u0003ב' הסטרין\u0004 שלה: בסטרא א' צריכין לירא שלא יגרום החטא ותתמעט אהבתו, ובסטרא ב' צריכין לירא מפני הגניזו, שהוא הדין שהש\"י דן אותו, וזהו לפי פשוטן של דברי הזוהר."],[3,"","אמנם כדי להמשיך בשאר הפקודין, צריכין לבאר הדברים בעמקות יתירה, בדרגין עלאין דאצילות."],[3,"","ודע, כי ד' האותיות דשם \u0003הוי\"ה\u0004 שהן חו\"ב תו\"מ, נקראות בדברי הזהר בשם \u0003יראה, אהבה, תורה, ומצוה\u0004. ה\u0003י'\u0004 שהיא חכמה נקראת \u0003יראה\u0004, \u0003ה'\u0004 ראשונה שהיא \u0003בינה\u0004 נקראת \u0003אהבה\u0004. ה\u0003ו'\u0004 נקראת \u0003תורה\u0004. \u0003ה'\u0004 תתאה נקראת \u0003מצוה\u0004. (כמ\"ש בזוהר בראשית בהשמטות דפו\"י דף רס\"ה ע\"א ובזוהר נשא י' אות ל\"ז)."],[3,"","וז\"ש \u0003בראשית\u0004 וכו' \u0003פקודא קדמאה\u0004 וכו' \u0003פקודא דא יראת ה' דאקרי ראשית\u0004. פי' כי פרצוף א\"א הוא הכלל דכל עולם האצילות המאיר לכל העולמות דרך הלבושין שלו, הנקראים או\"א וישסו\"ת וזו\"ן. והוא נקרא ג\"כ בשם חכמה סתימאה, משום שהחכמה שלו נסתמה בראשו עצמו, ואיני משפיע ממנה כלום לעולמות, ורק הבינה דא\"א מאירה לעולמות,"],[3,"","ולפיכך בינה זו נקראת \u0003ראשית\u0004, להיותה הראשית והשורש לכל העולמות, ונקראת \u0003יראת ה'\u0004, דהיינו יראת הרוממות, \u0003בגין דאיהו רב ושליט עקרא ושרשא\u0004 וכו' \u0003וכלא קמיה כלא חשיבין\u0004. וממנה יצאו הזו\"ן הנקראים \u0003שמים וארץ\u0004, וזה שעור הכתוב. \u0003בראשית\u0004, עם \u0003יראה, ברא אלהים שמים וארץ\u0004, שהם זו\"ן."],[3,"","וז\"ש \u0003דכתיב ראשית חכמה יראת ה', יראת ה' ראשית דעת, בגין דמלה דא ראשית אקרי\u0004, כי המוחין הם חב\"ד, אמנם החכמה של המוחין, אינה חכמה ממש דא\"א, אלא רק בינה דא\"א כנ\"ל, כי הבינה דא\"א כשעולה לראש דא\"א, היא חוזרת שם להיות חכמה, ומשפעת חכמה לפרצופין. ונמצא שהבינה שהיא \u0003יראה\u0004 היא ראשית אל החכמה, וז\"ש, \u0003ראשית חכמה יראת ה'\u0004. וכן היא \u0003ראשית\u0004 אל הדעת, כי הדעת ה\"ס שורשי הזו\"ן, שהם מעלים אותה לראש דא\"א לקבל חכמה, וע\"כ גם הזו\"ן מקבלים חכמה ממנה. וז\"ש \u0003יראת ה' ראשית דעת\u0004. ודברי הזוהר שמכאן ואילך, הם כמ\"ש לעיל."],[3,"","וז\"ש, \u0003פקודא תניינא דא איהי פקודא, דפקודא דיראה אתאחדת בה, ולא נפקא מינה לעלמין, ואיהי אהבה\u0004, כי החכמה נקראת \u0003אהבה\u0004, כי ה\u0003י'\u0004 ד\u0003הוי\"ה\u0004 ה\"ס עצם הבינה, דהיינו ג\"ר שבה, והן או\"א עלאין, והן בחינת אוירא דכיא, ואור החכמה סתים בהן, כנ\"ל אות ז' ד\"ה וז\"ש דהאי) ומקום גילוי אור החכמה הוא מז\"ת דבינה. הנקראות ישסו\"ת, שהם \u0003ה'\u0004 ראשונה ד\u0003הוי\"ה\u0004, וע\"כ הם נקראים \u0003אהבה\u0004, והוא \u0003פקודא תניינא\u0004 בתר ה\u0003יראה\u0004, משום שחכמה זו אינה מקובלת מחכמה דא\"א עצמה אלא מהבינה שהיא יראה כנ\"ל."],[3,"","ואומר ד\u0003יראה אתאחדת בה ולא נפקא מינה לעלמין\u0004, שהבינה מיוחדת תמיד בחכמה ואינה נפרדת ממנה לעולם. ובכל מקום שיש בינה נמצאת עמה בהכרח גם חכמה, כי חכמה ובינה דבוקות תמיד זו בזו, ולא תמצא לעולם חכמה בלי בינה או בינה בלי חכמה."],[3,"","ומשמיענו בזה, שאע\"פ שאמר כי \u0003פקודא קדמאה\u0004 היא \u0003יראה\u0004, דהיינו בינה, אל תטעה שהיא בינה בלי חכמה, וכן ב\u0003פקודא תניינא\u0004 שהיא \u0003אהבה\u0004, דהיינו חכמה, אל תטעה שהיא חכמה בלי בינה, אלא שיש חכמה גם ב\u0003פקודא קדמאה\u0004, ויש בינה גם ב\u0003פקודא תניינא\u0004, כי חו\"ב כלולות ובאות יחד ואינן נפרדות לעולם אלא אנו מכנים אותן לפי השליטה, כי ב\u0003פקודא קדמאה\u0004 שהיא או\"א עלאין, וג\"ר דבינה, שהן עצם הבינה, הנה עיקר השליטה היא בינה, וע\"כ קוראים לה \u0003יראה\u0004, וכאן ב\u0003פקודא תניינא\u0004 עיקר השליטה היא חכמה, ע\"כ אנו קוראים לה \u0003אהבה\u0004. וזכור זה ואל תשכח."],[3,"","וז\"ש \u0003ומאן איהו רחימו שלים דא אהבה רבה\u0004 וכו', \u0003ודא הוא דכתיב ויאמר אלהים יהי אור\u0004, פירוש, כי \u0003בראשית\u0004 מאמר סתים איהי, ועיקר גילוי של \u0003בראשית\u0004 מתחיל במאמר \u0003יהי אור\u0004, שה\"ס עלית הבינה, שהוא \u0003ראשית\u0004, אל הראש דא\"א, שחוזרת שם לבחינת חכמה כנ\"ל. ואז נקראת חכמה בינה יחד בשם \u0003אהבה רבה\u0004, וז\"ס המאמר \u0003יהי אור\u0004, כי הבינה עלתה לא\"א ומשפעת אור אל כל העולמות, בסוד \u0003אהבה רבה\u0004, שהיא חכמה ובינה."],[3,"","וז\"ש \u0003בתרין סטרין אתפרש אהבה רחימו דקב\"ה, אית מאן דרחים ליה מגו דאית ליה עותרא, אורכא דיומין וכו'\u0004 דרחים ליה למאריה, כמה דתנינן, אפילו הוא נטיל נשמתך וכו' \u0003וע\"ד אור דמעשה בראשית נפק ולבתר אגניז, כד אגניז נפק דינא קשיא\u0004, פירוש, כי אומר להלן (בראשית א' דף רפ\"א אות שנ\"ב). \u0003יהי אור לעולם הזה ויהי אור לעולם הבא\u0004, פירוש, כי ראה שאין העולם הזה כדאי להשתמש בו עמד וגנזו בעוה\"ב, שהוא למעלה מפרסא מגו מעוהי דא\"א, ששם הוא בחינת עולם הבא, דהיינו במקום עמידת או\"א עלאין ג\"ר דבינה, המסתיימות בחזה דא\"א, ששם הפרסא המבדלת בין מים עליונים, שהם או\"א עלאין, ובין מים תחתונים, שהם ישסו\"ת וזו\"ן. כי מחזה ולמטה דא\"א נחשך האור ואינו מאיר עוד, וישסו\"ת העומדים מחזה עד הטבור דא\"א, שהם ז\"ת דבינה כנ\"ל, הנה האור גנוז שם ואינו מאיר בהם."],[3,"","ונמצא שהבינה נחלקה ל\u0003ב' סטרין\u0004, כי ג\"ר שבה, שהן או\"א עלאין העומדים למעלה מחזה דא\"א בסוד מים עליונים, הרי האור מגולה בהם, והזוכה למדרגת או\"א עלאין נמצא שיש לו עושר ואריכות ימים, ובנים כשתילי זיתים מסבבים לשולחנו, ושולט על שונאיו, ואורחוי מתתקנן ליה, וכל אשר יעשה יצליח. אמנם ז\"ת דבינה העומדות למטה מחזה דא\"א בסוד מים תחתונים, כבר האור נגנז מהן, ואותם המקבלים מהן, צריכים לאהוב את השי\"ת בבחינת, אפילו הוא נוטל את נפשך. וז\"ס ב' סטרין ד\u0003אהבה\u0004, שהן ג\"ר וז\"ת דבינה מבחינת הימין שבה דהיינו \u0003אהבה\u0004. וזה נעשה ע\"י גניזת האור דמעשה בראשית. והזוכה להיות שלם באהבתו ית' הן בבחינת \u0003אהבה\u0004 דאו\"א עלאין והן בבחינת \u0003אהבה\u0004 שבישסו\"ת, \u0003דא אהבה כדקא יאות\u0004."],[3,"","ואומר שצריך להכליל את ה\u0003יראה\u0004 בב' סטרין הללו של \u0003אהבה\u0004, כי בסטרא דאו\"א עלאין \u0003אצטריך לאתערא יראה ולמדחל, דלא יגרום חובא\u0004. ועד\"ז בסטרא דאהבה דישסו\"ת \u0003יתער יראה וידחל למאריה כדקא יאות ולא יקשה לביה\u0004, דהיינו כי חכמה ובינה שהן \u0003אהבה\u0004 ו\u0003יראה\u0004, דבוקות תדיר זו בזו, ולפיכך יש להכליל בחינת הבינה, שהיא \u0003יראה\u0004, הן בג\"ר דבינה שהן או\"א, והן בז\"ת דבינה שהן ישסו\"ת."],[3,"","ואז \u0003אשתכח יראה דאתאחדת בתרין סטרין ואתכלילת מנייהו, ודא איהו אהבה שלימתא כדקא יאות\u0004. ויש כאן שתים שהם ארבע, כי אין \u0003אהבה\u0004 אלא ב\u0003ב' סטרין\u0004, שהם ג\"ר וז\"ת דבינה, ואין \u0003אהבה\u0004 שלים בכל אחד מב' סטרין אלא אם יש בכל אחד מהם \u0003יראה\u0004. כי לא תצוייר כלל חכמה בלי בינה, שהיא \u0003אהבה\u0004 בלי \u0003יראה\u0004."],[4,"","רד) \u0003פקודא תליתאה\u0004 וכו': המצוה השלישית, היא, לדעת שיש אלקים גדול ושליט בעולם. וליחדו בכל יום יחוד כראוי, בששה קצוות העליונים, חג\"ת נה\"י דז\"א, ולעשותם יחוד אחד בשש מלים של שמע ישראל, ולכוין הרצון עמהם למעלה. ועל כן צריכים להאריך במלה \u0003אחד\u0004 כשיעור שש מלים."],[4,"","ביאור הדברים, אומר ב' דברים, א) שצריכים \u0003למנדע\u0004 וכו', ב) \u0003וליחדא ליה\u0004 וכו'. כי תחילה צריכים \u0003למנדע\u0004 לדעת אותם \u0003ב' סטרין\u0004 שיש ב\u0003אהבה\u0004 שהם או\"א עלאין, וישסו\"ת כנ\"ל, \u0003דאית אלהא רברבא\u0004 היינו או\"א עלאין שהוא רב וגדול בחסדים. \u0003ושליטאה בעלמא\u0004, היינו ישסו\"ת, דאקרי שליט, שמורה על הדינין שמתערים מהם, שהאור נגנז מהם ונפק \u0003דינא קשיא\u0004 (כנ\"ל בדבור הסמוך). כי השם שליט ומושל מורה על דינין."],[4,"","והפירוש הוא שיש לדעת \u0003ב' סטרין\u0004 אלו ד\u0003אהבה\u0004, ולכלול בכל אחת מהם \u0003יראה\u0004 כנ\"ל, ויקבל אהבתו ית' הן \u0003בטיבו ותיקונא דארחוי\u0004, והן ב\u0003דינא\u0004, כי אז נחשב ל\u0003אהבה\u0004 שלימא ולא זולת. ואח\"כ צריכים \u0003ליחדא ליה בכל יומא יחודא כדקא יאות באינון שית סטרין עלאין\u0004, דהיינו להעלות מ\"ן לזו\"ן, וזו\"ן לישסו\"ת, ואז עולים ישסו\"ת וזו\"ן ומתיחדים כאחד עם \u0003שית סטרין עלאין\u0004 שהם או\"א, הנקראים \u0003שית סטרין\u0004 עליונים, להיותם מלבישים ו\"ק דא\"א, שע\"י היחוד הזה מתעלים ישסו\"ת במקום או\"א למעלה מפרסא דא\"א, ששם סוד מים עליונים, ואין האור נגנז מהם, וכשישסו\"ת מתמלאים באור אז הם משפיעים לזו\"ן, וזו\"ן לכל העולמות ומתגלים החסדים בעולמות. וזהו סוד \u0003קריאת שמע\u0004, כמ\"ש לפנינו."],[4,"","והנה שית תבין ד\u0003שמע ישראל\u0004 הן שית סטרין דזו\"ן, ואומר שצריכין ליחד את שית סטרין דזו\"ן, שיתחברו כאחד עם ה\u0003שית סטרין עלאין\u0004 שהם או\"א וישסו\"ת (כנ\"ל בדבור הסמוך). וצריכים \u0003לכוונא רעותא לעילא בהדייהו\u0004, דהיינו לכוון רצונו והנר\"ן שלו שיתכללו עמהם בבחינת מ\"ן."],[4,"","ולפיכך, דהיינו, כדי למעבד \u0003יחודא\u0004 בו\"ק דז\"א, שהם \u0003שית תבין דשמע\u0004, צריכין להאריך ב\u0003אחד\u0004, שצריכין להמשיך החכמה במלת \u0003אחד\u0004, כי אור החכמה הנמשך מא\"ס ב\"ה אל ו\"ק עלאין, שהם או\"א וישסו\"ת, מיחד את ו\"ק דז\"א באור א\"ס ב\"ה, כי \u0003אחד\u0004 בגימטריא \u0003י\"ג\u0004 הרומז על המשכת אור החכמה (כנ\"ל במראות הסולם ד\"ה ועתה נבאר ע\"ש). וע\"כ צריכין לכוון ב\u0003אחד\u0004, המשכת החכמה אל ו\"ק דז\"א."],[4,"","אמנם ביחוד הזה אין הכוונה להמשיך ג\"ר לז\"א, אלא רק להגדיל את ו\"ק דז\"א לבד ע\"י התכללותם בו\"ק עלאין. וז\"ש \u0003אחד אית לארכא ליה בשית תבין\u0004, לארכא פירושו המשכת חכמה, ב\u0003שית תבין\u0004, היינו תוך ו\"ק דז\"א, שבזה נעשים ו\"ק שלו ו\"ק דגדלות, כי \u0003שית תבין\u0004 דשמע, הן נגד ו\"ק דז\"א. וע\"י היחוד הזה המגדילו בו\"ק דגדלות, אפשר לאח\"ז להמשיך גם בחינת ג\"ר אל ז\"א."],[5,"","רה) \u0003ודא הוא דכתיב\u0004 וכו': וזה הוא שכתוב, יקוו המים מתחת השמים אל מקום אחד. שפירושו, תתכנסנה המדרגות שמתחת השמים אל מקום אחד, להיות בשלמות לששה קצוות כראוי. ועם כל זה, ביחוד הזה, דשמע ישראל, צריך לקשר בו היראה, שצריך להאריך ב\u0003ד'\u0004 דאחד. כי ע\"כ ה\u0003ד'\u0004 דאחד גדולה. והיינו שכתוב, ותראה \u0003היבשה\u0004, שתראה ותתקשר ה\u0003ד'\u0004, שהיא יבשה, באותו היחוד."],[5,"","כבר נתבאר בדיבור הסמוך שיחוד דשמע הוא להמשיך ו\"ק דגדלות וז\"ש, \u0003ודא הוא דכתיב יקוו המים מתחת השמים אל מקום אחד. יתכנשון דרגין דתחות שמיא לאתאחדא ביה למהוי בשלימו לשית סטרין כדקא יאות\u0004, כי \u0003מקום אחד\u0004 הוא ו\"ק עלאין, ששם מאיר אור א\"ס ב\"ה באור החכמה, ואומר שיתכללו \u0003דרגין דתחות שמיא\u0004, שהן \u0003שית סטרין\u0004 דז\"א, שהם \u0003תחות\u0004 הבינה הנקראים שמים בערכו של הז\"א, \u0003אל מקום אחד\u0004, שהם \u0003שית סטרין עלאין כדי לאתאחדא ביה למהוי בשלימו לשית סטרין כדקא יאות\u0004, שיקבלו גם הם אור החכמה, ויתיחדו ו\"ק דז\"א כראוי. אבל רק \u0003בשלימו לשית סטרין\u0004, דהיינו לגדלות ו\"ק בלבד כנ\"ל."],[5,"","וז\"ש, \u0003ועם כל דא בההוא יחודא אצטריך לקשרא ביה יראה דאצטריך לארכא בדל\"ת דאחד\u0004: היינו \u0003היראה\u0004 תתאה, כי אמר לעיל (אות ר\"א). \u0003רחימו דאקרי שלים, ההוא דהוה בתרין סטרין, בין בדינא ובין בטיבו\u0004 וכו', \u0003וע\"ד אור דמעשה בראשית נפק ולבתר אגניז כד אגניז נפק דינא קשיא ואתכלילו תרין סטרין כחדא למהוי שלימו, דא אהבה, כדקא יאות\u0004. לאח\"ז (באות ר\"ב) אומר שגם ב\u0003אהבה\u0004 זו צריכים לעורר בה \u0003יראה\u0004 (עיין בסולם אות ר\"ב ע\"ש כל ההמשך)."],[5,"","ונתבאר שם שיש ב' בחינות \u0003אהבה ויראה, שאהבה ויראה\u0004 עלאין, נקראות או\"א עלאין, ו\u0003אהבה\u0004 ו\u0003יראה\u0004 תתאין נקראות ישסו\"ת. ואין השלימות מקובלת אלא ע\"י ב' הבחינות יחד, ולפיכך נעשית גניזת האור בישסו\"ת, כדי לגלות \u0003אהבה\u0004 תתאה, שהיא אפילו בעת שנוטל את נפשך, גם צריכה ה\u0003יראה\u0004 לאתדבקא בהאי \u0003אהבה\u0004 תתאה \u0003וידחל למאריה כדקא יאות ולא יקשה לביה\u0004, ואז יש לו \u0003אהבה\u0004 ו\u0003יראה\u0004 בשלימות. והוא מתדבק באו\"א עלאין ובישסו\"ת, ומקבל כל הנועם והטוב שבהם."],[5,"","וזה שאומר כאן ביחוד דק\"ש, כי אחר שהעלה את הזו\"ן וכלל אותם ב\u0003שית סטרין\u0004 עלאין להמשיך את ה\u0003אהבה רבה\u0004 בזו\"ן במלת \u0003אחד\u0004, שה\"ס האור שנברא ביום א' במאמר ד\u0003ויאמר אלהים יהי אור\u0004, (כנ\"ל אות קצ\"ח). הנה \u0003ועם כל דא, בההוא יחודא אצטריך לקשרא ביה יראה\u0004, כי צריך ג\"כ לגלות ולהמשיך בחינת גניזת האור הזה שנעשה בישסו\"ת כדי להשתלם גם ב\u0003אהבה\u0004 ו\u0003יראה\u0004 תתאין, כי בלאו הכי לא נקרא שלימות כנ\"ל. וז\"ש כאן \u0003דאצטריך לארכא בד' דאחד, דד' דאחד גדולה\u0004, כי אתוון רברבן הן בתבונה, וע\"כ ה\u0003ד' דאחד גדולה\u0004 שהיא רומזת על מקום הגניזו של האור שנעשה בנה\"י דתבונה, וע\"כ צריכים להאריך בה, ולכוון בגניזו אשר בה, והיינו כדי לאתדבקא גם ב\u0003אהבה ויראה\u0004 תתאין, כמ\"ש והולך."],[5,"","וז\"ש, \u0003ותראה היבשה, דתתחזי ותתקשר דל\"ת דאיהו יבשה בההוא יחודא\u0004: כי אין שלימות ב\u0003אהבה\u0004 ו\u0003יראה עלאין\u0004 שנמשכו ב\u0003שית תבין\u0004 דק\"ש ע\"י מלת \u0003אחד\u0004, שה\"ס \u0003יהי אור\u0004, זולת ע\"י \u0003אהבה\u0004 ו\u0003יראה\u0004 תתאין המתגלות ע\"י גניזת האור בנה\"י דתבונה, הנק' \u0003ד'\u0004 כנ\"ל, וע\"כ, אחר \u0003יקוו המים אל מקום אחד\u0004, שה\"ס המשכת אור החכמה אל ה\u0003שית דרגין\u0004 דז\"א, שהם \u0003תחות שמיא\u0004, כתוב \u0003ותראה היבשה\u0004, שסובב על ה\u0003ד'\u0004 ד\u0003אחד\u0004 שצריכין \u0003לארכא ליה\u0004 ולכוון שהיא נעשית \u0003יבשה\u0004 על ידי גניזת האור, והוא כדי \u0003דתתחזי ותתקשר ד' דאיהו יבשה בההוא יחודא\u0004 שתתראה ותתקשר האי \u0003ד'\u0004, שה\"ס התבונה, \u0003בההוא יחודא\u0004 דאור שבאו\"א עלאין, שנמשכו בו\"ק דזו\"ן, כדי להשלים ה\u0003אהבה\u0004 ב\u0003תרין סטרין\u0004 כמבואר."],[6,"","רו) \u0003ולבתר דאתקשר תמן\u0004 וכו': ואחר שנתקשרה שם המלכות למעלה, בו\"ק דז\"א, צריך לקשר אותה למטה בהמוניה, דהיינו בששה קצוות אחרים שלמטה במלכות. והיינו ברוך שם כבוד מלכותו לעולם ועד, שיש בו שש מלים אחרות של היחוד, ואז, מה שהיתה יבשה נעשה ארץ, לעשות פירות ואבים, ולנטוע אילנות."],[6,"","ביאור הדברים, אחר היחוד העליון שבק\"ש, שנקשרה ה\u0003ד'\u0004 ד\u0003אחד\u0004 למעלה באו\"א, צריכים לקשר לה ל\u0003ד'\u0004 ד\u0003אחד\u0004 בו\"ק אחרים שלמטה, דהיינו ב\u0003שית סטרין\u0004 של הנוקבא דז\"א, שהיא רחל העומדת מחזה ולמטה דז\"א, שבה כלולין כל הששים רבוא נשמות ישראל הנקראות \u0003אכלוסהא\u0004 של הנוקבא, דהיינו ההמונים שלה."],[6,"","ואומר, שאחר שנכלל ז\"א בבחינת האור של או\"א עלאין, וגם נתגלה בו בחינת הגניזו של התבונה שה\"ס \u0003ותראה היבשה\u0004 של ה\u0003ד'\u0004, צריכין להמשיך את ב' הבחינות האלו אל הנוקבא דז\"א שמחזה ולמטה שלו, שה\"ס \u0003שית תבין\u0004 של \u0003ברוך, שם, כבוד, מלכותו, לעולם, ועד\u0004. כי \u0003שית תבין\u0004 אלו הם נגד \u0003שית סטרין\u0004, חג\"ת נה\"י, של הנוקבא דז\"א. וז\"ש \u0003בשכמל\"ו\u0004, דאית ביה שית תבין אחרנין דיחודא."],[6,"","וז\"ש, \u0003כדין מה דהות יבשה אתעבידת ארץ למעבד פירין ואיבין\u0004: פירוש כי אמר לעיל (באות ר\"א) שבכדי לגלות \u0003רחימו שלים\u0004 ב\u0003תרין סטרין\u0004, ע\"כ \u0003נפק\u0004 האור \u0003ולבתר אגניז, וכד אגנז נפק דינא קשיא, ואתכלילו תרין סטרין כחדא\u0004. הרי שבגניזו לבדה עוד לא נשלמה ה\u0003אהבה\u0004 ב\u0003תרין סטרין\u0004, אלא רק ע\"י \u0003דינא קשיא\u0004 דנפק אחר הגניזו."],[6,"","ולפיכך מטרם ד\u0003נפק דינא קשיא\u0004, היתה ה\u0003ד'\u0004 ד\u0003אחד\u0004 בבחינת \u0003יבשה\u0004 בלבד, בלי שום תועלת ולא כלום, כי יצאה מכלל האור ע\"י הגניזו וגם בחינת היראה לא נשלמה בה, כדי שתתקן ב\u0003אהבה\u0004 ויראה תתאין המשלימות ל\u0003אהבה\u0004 ול\u0003יראה\u0004 עלאין, כי עוד לא נגלה ה\u0003דינא קשיא\u0004, שהיא העיקר המגלה את ה\u0003אהבה\u0004 וה\u0003יראה\u0004 תתאין, כנ\"ל."],[6,"","והנה אותו הדינא קשיא, מקום מציאתו הוא, בעקבים דלאה שבמקום הראש רחל. כי ב' נוקבין יש לו לז\"א, א) מחזה ולמעלה, ונקראת לאה. ב) מחזה ולמטה ונקראת רחל. ונמצאות עקבים דלאה המסתיימות בחזה דז\"א הן נוגעות בראש רחל העומדת מחזה ולמטה דז\"א. ומציאות ה\u0003דינא\u0004 קשיא הוא בסיום עקבים דלאה הנוגעות בתוך הראש דרחל, ולפיכך, אין פעולת ה\u0003דינא קשיא\u0004 רק ברחל, כי אין שום מסך ודין יכולים לגלות שליטתו רק ממקום מציאותו ולמטה. ונמצא שאין בחינת הגניזו נשלמת לבחינת מדרגת \u0003אהבה\u0004 ו\u0003יראה\u0004 תתאין רק אחר שנמשכת למקום רחל, ששם פועל ה\u0003דינא קשיא\u0004."],[6,"","וז\"ש \u0003כדין, מה דהות יבשה אתעבידת ארץ למעבד פירין ואיבין ולנטעא אילנין\u0004, כי אותה ה\u0003ד'\u0004 ד\u0003אחד\u0004, שבמקומה מטרם שנגלה ה\u0003דינא קשיא\u0004, היתה \u0003יבשה\u0004 ומקום חורבא שאינה ראויה לישוב, הנה עתה אחר שנמשכה לו\"ק דרחל שמחזה ולמטה דז\"א, נעשתה לארץ מוציאה פירות הראויה לנטיעת אילנות, דהיינו למקום ישוב כלומר, כי נגלה בה בחינת \u0003אהבה\u0004 ויראה תתאין בשלימות, המשלמת לאהבה ול\u0003יראה\u0004 עלאין, שתהיה הרחימו ב\u0003תרין סטרין\u0004, אשר רק בדרך זה מתגלה כל הנועם והטוב שבאו\"א עלאין כנ\"ל."],[6,"","וז\"ש, \u0003והיינו דכתיב ויקרא אלהים ליבשה ארץ, בההוא יחודא דלתתא, ארעא רעוא שלים כדקא יאות\u0004. ארץ, היא מלשון רצון, וז\"ש הכתוב \u0003ויקרא אלהים ליבשה ארץ\u0004, שהמשיך את בחינת ה\u0003ד'\u0004 ד\u0003אחד\u0004 אל הנוקבא דז\"א ל\u0003שית סטרין שלה\u0004, ששם כבר מגולה פעולת ה\u0003דינא קשיא\u0004, ואז ה\u0003ד'\u0004 שהיתה ה\u0003יבשה\u0004 וחורבא, נעשתה בנוקבא דז\"א ע\"י זווגה עמו, לבחינת ארץ מוציאה פירות ומקום ישוב, ובזה קרא אלהים ליבשה \u0003ארץ רעוא שלים כדקא יאות\u0004, כי נגלה בה הרצון השלם כראוי, דהיינו \u0003רחימו שלים\u0004."],[7,"","רז) \u0003והיינו דכתיב ויקרא\u0004 וגו': והיינו שכתוב, ויקרא אלקים \u0003ליבשה\u0004 ארץ. שהוא באותו היחוד שלמטה, בבשכמל\"ו, שנעשית ארץ, שהוא רצון שלם כראוי. כי ארץ היא לשון רצון. וע\"כ כתוב, כי טוב כי טוב שתי פעמים, אחד ליחוד עליון ואחד ליחוד תחתון. כיון שנתאחדה המלכות בשני הצדדים, בו\"ק דז\"א ובו\"ק שלה, הנה מכאן ולהלאה, תדשא הארץ דשא. כי נתתקנה לעשות פירות ואבים כראוי."],[7,"","פירוש. \u0003יחודא עלאה\u0004, היינו יחוד ד\u0003שית תבין\u0004 ד\u0003ק\"ש\u0004 שהוא ב\u0003שית סטרין\u0004 רברבין עלאין דאו\"א, המתבאר בכתוב, \u0003יקוו המים מתחת השמים אל מקום אח\"ד\u0004, אשר יחוד זה ממשיך האור שנברא ביום א' מ\u0003שית סטרין\u0004 דאו\"א עלאין אל ו\"ק דז\"א כנ\"ל. וזהו \u0003כי טוב\u0004 הא' הנאמר ביום ג' דמעשה בראשית."],[7,"","ו\u0003יחודא תתאה\u0004, היינו יחוד ד\u0003שית תבין\u0004, ד\u0003ברוך, שם, כבוד, מלכותו, לעולם, ועד\u0004, שהוא השלמת ה\u0003ד'\u0004 ד\u0003אחד\u0004, שאין לה שלימות, של כלום זולת ב\u0003שית סטרין\u0004 של הנוקבא דז\"א כנ\"ל, שזה מתבאר בכתוב \u0003ויקרא אלהים ליבשה ארץ\u0004, ובכתוב \u0003תדשא הארץ דשא\u0004 וגו', כי בו\"ק דנוקבא נעשתה ה\u0003יבשה\u0004, לבחינת ארץ שמוציאה פירות, ועל היחוד הזה של ו\"ק דנוקבא נאמר פעם שניה \u0003כי טוב\u0004."],[7,"","ונמצא \u0003כי טוב\u0004 הא' הוא ליחוד העליון. ו\u0003כי טוב\u0004 הב' הוא ליחוד התחתון, וז\"ש \u0003כיון דאתאחד בתרין סטרין\u0004, דהיינו, \u0003תרין סטרין של אהבה\u0004, ע\"י \u0003יחודא עלאה ויחודא תתאה. מכאן והלאה תדשא הארץ דשא, אתתקנת למעבד פירין ואיבין כדקא יאות\u0004 כי ה\u0003יחודא תתאה\u0004 השלים ה\u0003אהבה לתרין סטרין\u0004, ונמשכים האורות דאו\"א עלאין אל ו\"ק דנוקבא, ומשפעת \u0003פירין ואיבין לאכלוסהא\u0004 דילה, שהם ששים רבוא נשמות ישראל, כראוי להיות."],[8,"","רח) \u0003פקודא רביעאה\u0004 וכו': המצוה הרביעית היא, לדעת כי ה' הוא האלקים. כמו שאתה אומר, וידעת היום והשבות אל לבבך כי הויה הוא האלקים. דהיינו שהשם אלקים יהיה נכלל בשם הויה, לדעת שהם אחד, ואין בהם פירוד."],[8,"","פירוש. \u0003הוי\"ה\u0004 הוא ז\"א, ו\u0003אלהים\u0004 הוא הנוקבא דז\"א. ואומר שצריכים ליחד הז\"א והנוקבא, שיהיו אחד בלי שום \u0003פרודא\u0004 ביניהם. כלומר שיתכלל \u0003שמא דאלהים\u0004 שהוא הנוקבא \u0003בשמא דהוי\"ה\u0004 שהוא הז\"א, וגם הנוקבא תהיה בחינת \u0003הוי\"ה\u0004. כמו שמבאר לפנינו. והיחוד הזה ה\"ס המשכת ג\"ר אל זו\"ן. כי היחוד של ק\"ש המבואר ב\u0003פקודא תליתאה\u0004, היה להמשכת ו\"ק מאו\"א אל זו\"ן, ויחוד המתבאר כאן, הוא להמשכת ג\"ר מאו\"א אל זו\"ן. וזה הכלל, שהמשכת כל מדרגה שתהיה, אי אפשר להמשיכה כולה בבת אחת, אלא תחילה צריכים להמשיך ו\"ק של אותה מדרגה, ואח\"כ ג\"ר."],[9,"","רט) \u0003והיינו רזא דכתיב\u0004 וכו': והיינו סוד הכתוב, יהי מארת ברקיע השמים להאיר על הארץ. שפירושו שיהיו שני השמות, הויה אלקים, אחד בלא פרוד כלל, שיהיה נכלל מארת חסר ו' שהיא המלכות הנקראת אלקים, בשם השמים שהוא ז\"א הנקרא הויה, כי הם אחד ואין בהם פרוד. אור שחור, שהוא מלכות, באור לבן, שהוא ז\"א, אין בהם פרוד, והכל אחד. וזה הוא ענן הלבן של היום, וענן האש של הלילה, דהיינו מדת יום ז\"א, ומדת לילה, מלכות, שיתתקנו זה בזה ביחוד אחד, להאיר. כמו שנאמר, להאיר על הארץ."],[9,"","ביאור הדברים, הנוקבא נקראת \u0003מארת חסר ו'\u0004, המורה על מיעוט הירח, כמ\"ש חז\"ל תחילה היו ב' המאורות גדולים בקומה שוה, וקטרג הירח, אין ב' מלכים משתמשים בכתר אחד. ואמר לה הקב\"ה לכי ומעטי את עצמך (חולין ס:). ואז ירדו ט\"ס תחתוניות שלה לעולם הבריאה, והיא נתמעטה לנקודה תחת היסוד דז\"א. ואומר שצריכים להכליל את המלכות אחר שנתמעטה, \u0003בשמא דשמים\u0004, שהיא ז\"א, דהיינו להגדילה בחזרה, שתהיה בקומה שוה עם הז\"א פב\"פ, שצריכים להעלות בחזרה את הנוקבא מעולם הבריאה אל האצילות, ולתקן את הפירוד, שנעשה בין הז\"א ובין הנוקבא בעת מעוט הירח."],[9,"","והנה ענין מיעוט הירח הוא, כי שלט עליה הדינא קשיא שבעקבים דלאה, ועי\"ז נתמעטה עד לבחינת נקודה, וט\"ס תחתונות שלה נפלו לבריאה, והנה על ידי היחוד דק\"ש (הנ\"ל בפקודא תליתאה) נבנתה הנוקבא, בו\"ק. בסוד \u0003יחודא תתאה דבשכמל\"ו\u0004, והוא משום שע\"י כח הדין שבה תיקנה את ה\u0003ד'\u0004 ד\u0003אחד\u0004, שהיתה \u0003יבשה\u0004 וחורבה, לבחינת \u0003ארץ\u0004 מוציאה \u0003פירין ואיבין\u0004 (כנ\"ל עש\"ה)."],[9,"","ונבחן עתה, אשר בחינה \u0003אוכמא\u0004 שבנוקבא, שהיא כח הדין שבה, שהפיל אותה עד לנקודה, נתעלה עתה לבחינת אור ממש, שהרי בכח הדין דוקא נבנתה ה\u0003ד'\u0004 ד\u0003אחד\u0004, להיות בחינת ישובא הארץ מוציאה פירות, ולולא כח הדין שבנוקבא היתה ה\u0003ד'\u0004 ד\u0003אחד\u0004 שהיא התבונה, נשארת בבחינה \u0003יבשה\u0004 וחורבא. הרי שכח הדין שבה נעשה אור ממש. ונקרא \u0003נהורא אוכמא\u0004, משום שה\u0003אוכמא\u0004 היה הגורם אל האור הזה. וגם נבחנת לאור ו\"ק, שהוא אור דחסדים."],[9,"","ולפיכך אפשר עתה להמשיך גם \u0003נהורא חיוורא\u0004 אל ו\"ק דנוקבא, שפירושו אור חכמה שהוא ג\"ר, כי לבן פירושו חכמה. והוא על ידי שמעלים את הזו\"ן להיכל או\"א עלאין. כי עתה יכולה גם הנוקבא דז\"א להתכלל באו\"א כמו הז\"א, שהרי כח הדין שבה נתהפך להיות אור ממש. ואע\"פ שהיא \u0003נהורא אוכמא\u0004, אין זה חוצץ כלל שלא תוכל להכלל באו\"א עלאין, משום \u0003דנהורא אוכמא בנהורא חוורא לית בהו פרודא וכלא חד\u0004, כי בהיותה בחינת \u0003נהורא\u0004 יכולה להכלל ב\u0003נהורא\u0004 דאו\"א, כי אור באור הוא מין במינו ונחשבים לאחד, וענין ה\u0003אוכמא\u0004, שהוא הגורם לאור שלה אינו חוצץ ואינו משפיל אותה עתה כלום, שהרי הוא הגורם לכל מעלתה, שבלעדיו לא היתה לבחינת אור."],[9,"","וז\"ש, \u0003ודא הוא עננא חוורא דיממא ועננא דאשתא בליליא, מדת יום ומדת לילה\u0004: כלומר, שע\"י היחוד הזה דהתכללות זו\"ן באו\"א, שז\"א נכלל שם באבא עלאה, והנוקבא באמא עלאה, נעשה הז\"א לבחינת \u0003עננא חוורא\u0004 לאור היום, והנוקבא \u0003לעננא דאשתא\u0004 לאור הלילה, דהיינו \u0003מדת יום ומדת לילה\u0004, המיוחדות זו בזו בסוד \u0003ויהי ערב ויהי בקר יום אחד\u0004, וז\"ש \u0003ולאתתקן דא בדא לאנהרא, כמה דאתמר להאיר על הארץ\u0004, ש\u0003מדת יום\u0004 נכללת ב\u0003מדת\u0004 ה\u0003לילה\u0004, שהיא הנוקבא, בסוד \u0003יום אחד\u0004, ונתקנים זה בזה להאיר על הארץ, אל ה\u0003אכלוסהא\u0004 של הנוקבא שבג' עלמין בי\"ע."]],[[0,"","וְעַל כֵּן שָׁנִינוּ, לִשְׁנֵי צְדָדִים נִפְרֶדֶת הָאַהֲבָה, אַהֲבַת הַקָּדוֹשׁ בָּרוּךְ הוּא. יֵשׁ מִי שֶׁאוֹהֵב אוֹתוֹ מִתּוֹךְ שֶׁיֵּשׁ לוֹ עֹשֶׁר, אֹרֶךְ יָמִים, בָּנִים סְבִיבוֹ, שׁוֹלֵט עַל שׂוֹנְאָיו, דְּרָכָיו מְתֻקָּנוֹת לוֹ, וּמִתּוֹךְ כָּךְ אוֹהֵב אוֹתוֹ. וְאִם לָזֶה יִתְהַפֵּךְ וְיַחֲזִיר עָלָיו הַקָּדוֹשׁ בָּרוּךְ הוּא גִּלְגּוּל שֶׁל דִּין קָשֶׁה - יִשְׂנָא אוֹתוֹ וְלֹא יֹאהַב אוֹתוֹ כְּלָל, וּבִגְלַל כָּךְ אַהֲבָה זוֹ אֵינָהּ אַהֲבָה שֶׁיֵּשׁ לָהּ עִקָּר."],[1,"","אַהֲבָה שֶׁנִּקְרֵאת שְׁלֵמָה, הַהוּא שֶׁהָיָה בִּשְׁנֵי הַצְּדָדִים - בֵּין בְּדִין בֵּין בְּחֶסֶד. וְתִקּוּן דַּרְכּוֹ שֶׁאוֹהֵב אֶת רִבּוֹנוֹ, כְּמוֹ שֶׁשָּׁנִינוּ, אֲפִלּוּ שֶׁנּוֹטֵל אֶת נִשְׁמָתְךְ מִמְּךְ. זוֹ הִיא אַהֲבָה שְׁלֵמָה בִּשְׁנֵי צְדָדִים. וְעַל כֵּן הָאוֹר שֶׁל מַעֲשֵׂה בְרֵאשִׁית יָצָא וְאַחַר כָּךְ נִגְנַז. כְּשֶׁנִּגְנַז, יָצָא דִין קָשֶׁה, וְנִכְלְלוּ שְׁנֵי הַצְּדָדִים יַחַד, שֶׁתִּהְיֶה שְׁלֵמוּת הָאַהֲבָה כָּרָאוּי."],[2,"","נְטָלוֹ רַבִּי שִׁמְעוֹן וּנְשָׁקוֹ. בָּא רַבִּי פִּינְחָס וּנְשָׁקוֹ וּבֵרְכוֹ, וְאָמַר, בְּוַדַּאי הַקָּדוֹשׁ בָּרוּךְ הוּא שְׁלָחַנִי לְכָאן. זֶה הוּא אוֹר קָטָן שֶׁאָמְרוּ לִי שֶׁנִּכְלָל בְּבֵיתִי וְאַחַר כָּךְ מֵאִיר לְכָל הָעוֹלָם. אָמַר רַבִּי אֶלְעָזָר, בְּוַדַּאי לֹא צָרִיךְ לִשְׁכֹּחַ יִרְאָ\"ה בְּכָל הַמִּצְווֹת, כָּל שֶׁכֵּן בַּמִּצְוָה הַזּוֹ צָרִיךְ יִרְאָה לְהִתְדַּבֵּק בָּזֶה. אֵיךְ מִתְדַּבֵּק הָאַהֲבָה הִיא בְּצַד אֶחָד טוֹב, כְּמוֹ שֶׁנִּתְבָּאֵר שֶׁנּוֹתֵן עֹשֶׁר וְטוֹב, אֹרֶךְ שֶׁל חַיִּים, בָּנִים וּמְזוֹנוֹת, אָז צָרִיךְ לְעוֹרֵר יִרְאָה וְלִפְחֹד שֶׁלֹּא יִגְרֹם הַחֵטְא. וְעַל זֶה כָּתוּב (משלי כח) אַשְׁרֵי אָדָם מְפַחֵד תָּמִיד, מִשּׁוּם שֶׁזֶּה כּוֹלֵל יִרְאָ\"ה בְּאַהֲבָ\"ה."],[3,"","וְכָךָ צָרִיךְ בַּצַּד הָאַחֵר שֶׁל הַדִּין הַקָּשֶׁה לְעוֹרֵר בּוֹ יִרְאָה. כְּשֶׁרוֹאֶה שֶׁהַדִּין הַקָּשֶׁה שׁוֹרֶה עָלָיו, אָז יְעוֹרֵר יִרְאָה וְיִפְחַד מֵרִבּוֹנוֹ כָּרָאוּי וְלֹא יַקְשֶׁה לִבּוֹ. וְעַל זֶה כָּתוּב (שם) וּמַקְשֶׁה לִבּוֹ יִפּוֹל בְּרָעָה, בְּאוֹתוֹ הַצַּד הָאַחֵר שֶׁנִּקְרָא רָעָה. נִמְצֵאת שֶׁיִּרְאָה שֶׁנֶּאֶחְזָה בִּשְׁנֵי צְדָדִים וְנִכְלֶלֶת מֵהֶם, וְזוֹהִי אַהֲבָה שְׁלֵמָה כָּרָאוּי."],[4,"","מִצְוָה שְׁלִישִׁית - לָדַעַת שֶׁיֵּשׁ אֱלוֹהַּ גָּדוֹל וְשַׁלִּיט בָּעוֹלָם, וּלְיַחֵד אוֹתוֹ בְּכָל יוֹם יִחוּד כָּרָאוּי בְּאוֹתָם שֵׁשֶׁת הַצְּדָדִים הָעֶלְיוֹנִים, וְלַעֲשׂוֹת אוֹתָם יִחוּד אֶחָד בְּשֵׁשׁ הַתֵּבוֹת שֶׁל שְׁמַע יִשְׂרָאֵל וּלְכַוֵּן רָצוֹן לְמַעְלָה עִמָּהֶם. וְעַל כֵּן צָרִיךְ \"אֶחָד\" לְהַאֲרִיךְ אוֹתוֹ (נ\"א: בשש) בְּשֵׁשׁ תֵּבוֹת,"],[5,"","וְזֶהוּ שֶׁכָּתוּב יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם אֶל מָקוֹם אֶחָד. יִתְכַּנְּסוּ הַדְּרָגוֹת שֶׁתַּחַת הַשָּׁמַיִם שֶׁתֵּאָחֵז בָּהֶן יִרְאָה לִהְיוֹת בִּשְׁלֵמוּת לְשִׁשָּׁה צְדָדִים כָּרָאוּי. וְעִם כָּל זֶה, בְּאוֹתוֹ הַיִּחוּד צָרִיךְ לִקְשֹׁר בּוֹ יִרְאָה, שֶׁצָּרִיךְ לְהַאֲרִיךְ בַּדָּלֶ\"ת שֶׁל אֶחָד, שֶׁדָּלֶ\"ת שֶׁל אֶחָד גְּדוֹלָה. וְהַיְנוּ שֶׁכָּתוּב וְתֵרָאֶה הַיַּבָּשָׁה, שֶׁתֵּרָאֶה וְתִתְקַשֵּׁר דָּלֶ\"ת, שֶׁהִיא יַבָּשָׁה, בְּאוֹתוֹ הַיִּחוּד."],[6,"","וְאַחַר שֶׁנִּקְשְׁרָה שָׁם לְמַעְלָה, צָרִיךְ לִקְשֹׁר אוֹתָהּ לְמַטָּה עִם אוּכְלוּסֶיהָ בְּשִׁשָּׁה צְדָדִים הָאֲחֵרִים שֶׁלְּמַטָּה, בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד, שֶׁיֵּשׁ בּוֹ שֵׁשׁ תֵּבוֹת אֲחֵרוֹת שֶׁל הַיִּחוּד. וְאָז, מַה שֶּׁהָיְתָה יַבָּשָׁה, נֶעֶשְׂתָה אֶרֶץ לַעֲשׂוֹת פֵּרוֹת וְאִבִּים וְלִנְטֹעַ אִילָנוֹת."],[7,"","וְהַיְנוּ מַה שֶּׁכָּתוּב וַיִּקְרָא אֱלֹהִים לַיַּבָּשָׁה אֶרֶץ, בְּאוֹתוֹ הַיִּחוּד שֶׁלְּמַטָּה אֶרֶץ, רָצוֹן שָׁלֵם כָּרָאוּי. וְעַל כֵּן כִּי טוֹב כִּי טוֹב פַּעֲמַיִם. יִחוּד אֶחָד עֶלְיוֹן וְיִחוּד אֶחָד תַּחְתּוֹן. כֵּיוָן שֶׁנֶּאֱחָז בִּשְׁנֵי צְדָדִים, מִכָּאן וָהָלְאָה תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא. הִתְתַּקְּנָה לַעֲשׂוֹת פֵּרוֹת וְאִבִּים כָּרָאוּי."],[8,"","מִצְוָה רְבִיעִית - לָדַעַת שֶׁה' הוּא הָאֱלֹהִים, כְּמוֹ שֶׁנֶּאֱמַר (דברים ד) וְיָדַעְתָּ הַיּוֹם וַהֲשֵׁבֹתָ אֶל לְבָבֶךְ כִּי ה' הוּא הָאֱלֹהִים. וְשֶׁיִּכָּלֵל הַשֵּׁם שֶׁל אֱלֹהִים בַּשֵּׁם שֶׁל יי', לָדַעַת שֶׁהֵם אֶחָד וְאֵין בָּהֶם פֵּרוּד."],[9,"","וְהַיְנוּ סוֹד הַכָּתוּב יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמַיִם לְהָאִיר עַל הָאָרֶץ, שֶׁיִּהְיוּ שְׁנֵי הַשֵּׁמוֹת אֶחָד בְּלִי פֵרוּד כְּלָל, שֶׁיִּכָּלֵל מְאֹרֹת חָסֵר בַּשֵּׁם שֶׁל שָׁמַיִם (נ\"א: שרשום) שֶׁהֵם אֶחָד וְאֵין בָּהֶם פֵּרוּד. אוֹר שָׁחֹר בְּאוֹר לָבָן אֵין בָּהֶם פֵּרוּד, וְהַכֹּל (דבר) אֶחָד. וְזֶה הוּא עָנָן הַלָּבָן שֶׁל הַיּוֹם וְעָנָן שֶׁל אֵשׁ בַּלַּיְלָה, מִדַּת יוֹם וּמִדַּת לַיְלָה, וְיִתְתַּקְנוּ זֶה עִם זֶה לְהָאִיר, כְּמוֹ שֶׁנֶּאֱמַר לְהָאִיר עַל הָאָרֶץ."]]],[["וְדָא חוֹבָה דְהַהוּא נָחָשׁ קַדְמָאָה חִבַּר לְתַתָּא וְאִתְפְּרַשׁ לְעֵילָא. וּבְגִין כָּךְ גָּרַם מַה דְּגָרַם לְעָלְמָא. בְּגִין דְּאִצְטְרִיךְ לְאַפְרָשָׁא לְתַתָּא וּלְחַבְּרָא לְעֵילָא. וּנְהוֹרָא אוּכְמָא אִצְטְרִיךְ לְאִתְאַחֲדָא לְעֵילָא בְּחִבּוּרָא חֲדָא. וּלְאִתְאַחֲדָא לְבָתַר בְּאֻכְלוּסָהָא בְּיִחוּדָהָא וּלְאַפְרָשָׁא לָהּ מִסִּטְרָא בִּישָׁא.","וְעִם כָּל דָּא אִצְטְרִיךְ לְמִנְדַע דֶּאֱלהִים יְיָ כֹּלָא חַד בְּלָא פִּירוּדָא. ה' הוּא הָאֱלהִים. וְכַד יִנְדַע בַּר נָשׁ דְּכֹלָּא חַד וְלָא יַשְׁוֵי פִּירוּדָא, אֲפִילּוּ הַהִיא סִטְרָא אָחֳרָא יִסְתְּלַק מֵעַל עָלְמָא וְלָא אִתְמְשַׁךְ לְתַתָּא.","וְהַיְינוּ רָזָא דִכְתִיב וְהָיוּ לִמְאוֹרוֹת. הָא קְלִיפָּה בָּתַר מוֹחָא סַלְקָא. מוֹחָא אוֹר. סִטְרָא אָחֳרָא מָוֶת. אוֹר בְּחִבּוּר דְּאַתְוָון. מָוֶת בְּפִּירוּדָא. וְכַד הַאי אוֹר אִסְתַּלַּק מִתַּמָּן, מִתְחַבָּרָא בְאַתְוָון מָוֶת דְּפִּירוּדָא.","מֵאִלֵּין אַתְוָון שָׁרִיאַת חַוָה וְגָרְמַת בִּישָׁא עַל עָלְמָא. כְּמָה דִכְתִיב, (בראשית ג׳:ו׳) וַתֵּרֶא הָאִשָּׁה כִּי טוֹב אֲהַדְּרַת אַתְוָון לְמַפְרֵעַ אִשְׁתָּאַר מ\"ו וְאִנּוּן אֲזְלוּ וּנְטָלוּ אוֹת תי\"ו בַּהֲדַיְיהוּ וְגָרְמַת מוֹתָא עַל עָלְמָא כְּמָה דִכְתִיב וַתֵּרֶא.","אָמַר רִבִּי אֶלְעָזָר, אַבָּא, הָא אוֹלִיפְנָא מ\"ם אִשְׁתָּאָרַת יְחִידָאָה, וָא\"ו דְּאִיהוּ חַיִּין תָּדִיר אִתְהַפָּכַת וְאֲזָלַת (פנחס רל\"ו ע\"א) וּנְטָלַת תי\"ו דִּכְתִיב וַתִּקַּח וַתִּתֵּן וְאִשְׁתְּלִים תֵּיבָה דָא וְאִתְחַבְּרוּ אַתְוָון. אָמַר לֵיהּ בְּרִיךְ אַנְתְּ בְּרִי וְהָא אוֹקִימְנָא מִלָּה דָא.","פִּקּוּדָא חֲמִישָׁאָה כְּתִיב, (בראשית מ\"ו ע\"ב) יִשְׁרְצוּ הַמַּיִם שֶׁרֶץ נֶפֶשׁ חַיָה. בְּהַאי קְרָא אִית תְּלַת פִּקּוּדִין. חַד לְמִלְעֵי בְּאוֹרַיְיתָא. וְחַד לְאִתְעֲסָקָא בִּפְרִיָּה וּרְבִיָּה. וְחַד לְמִגְזַר לִתְמַנְיָיא יוֹמִין וּלְאַעֲבָרָא מִתַּמָּן עָרְלָתָא. לְמִלְעֵי בְּאוֹרַיְיתָא וּלְאִשְׁתַּדָּלָא בָהּ וּלְאַפָּשָׁא לָהּ בְּכָל יוֹמָא לְתַקְּנָא נַפְשֵׁיהּ וְרוּחֵיהּ.","דְּכֵיוָן דְּבַר נָשׁ אִתְעַסַּק בְּאוֹרַיְיתָא (נח ס\"ב ע\"א) אִתְתַּקַּן (ש\"כ ע\"א) בְּנִשְׁמָתָא אָחֳרָא קַדִּישָׁא. דִּכְתִיב שֶׁרֶץ נֶפֶשׁ חַיָּה. נֶפֶשׁ דְּהַהִיא חַיָּה קַדִּישָׁא. דְּכַד בַּר נָשׁ לָא אִתְעַסַּק בְּאוֹרַיְיתָא לֵית לֵיהּ נַפְשָׁא קַדִּישָׁא. קְדוּשָׁא דִּלְעֵילָא לָא שַׁרְיָא עֲלוֹי. וְכַד אִשְׁתַּדַּל בְּאוֹרַיְיתָא, בְּהַהוּא רְחִישׁוּ דְּרָחִישׁ בָּהּ זָכֵי לְהַהִיא נֶפֶשׁ חַיָּה, וּלְמֶהֱדַר כְּמַלְאָכִין קַדִּישִׁין.","דִּכְתִיב, (תהילים ק״ג:כ׳) בָּרְכוּ יְיָ מַלְאָכָיו, אִלֵּין אִנּוּן דְּמִתְעַסְּקִין בְּאוֹרַיְיתָא דְּאִקְרוּן מַלְאָכָיו בְּאַרְעָא. וְדָא הוּא דִכְתִיב וְעוֹף יְעוֹפֵף עַל הָאָרֶץ. הַאי בְּהַאי עָלְמָא. בְּהַהוּא עָלְמָא תָּנִינָן דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבַּד לוֹן גַּדְפִין כְּנִשְׁרִין וּלְאַשָּׁטָא בְּכָל עָלְמָא דִּכְתִיב, (ישעיהו מ׳:ל״א) וְקּוֵֹי יְיָ יַחֲלִיפוּ כֹחַ יַעֲלוּ אֵבָר כַּנְּשָׁרִים.","וְהַיְנוּ דִכְתִיב וְעוֹף יְעוֹפֵף עַל הָאָרֶץ דָּא אוֹרַיְיתָא דְּאִקְרֵי מַיִם יִשְׁרְצוּן וְיִפְקוּן רִחֲשָׁא דְּנֶפֶשׁ חַיָּה מֵאֲתַר דְּהַהִיא חַיָּה יִמְשְׁכוּן לָהּ לְתַתָּא כְּמָה דְאִתְּמָר. וְעַל דָּא אָמַר דָּוִד (וישב קי\"ב ע\"ב) (תהילים נ״א:י״ב) לֵב טָהוֹר בְּרָא לִי אֱלהִים, לְמִלְעֵי בְּאוֹרַיְיתָא, וּכְדֵין וְרוּחַ נָכוֹן חַדֵּשׁ בְּקִרְבִּי:","פִּקּוּדָא שְׁתִיתָאָה לְאִתְעַסְּקָא בִּפְרִיָּה וּרְבִיָּה. דְּכָל מָאן דְּאִתְעַסַּק בִּפְרִיָּה וּרְבִיָּה, גָּרִים (וישב קפ\"ו ע\"ב) לְהַהוּא נָהָר לְמֶהוֵי נְבִיעַ תָּדִיר וְלָא יִפָּסְקוּן מֵימוֹי. וְיַמָּא אִתְמַלְיָיא בְּכָל סִטְרִין. (קנ\"ב א) וְנִשְׁמָתִין חַדְתִּין מִתְחַדְּשָׁן וְנָפְקִין מֵהַהוּא אִילָנָא. וְחֵילִין סַגִּיאִין אִתְרַבִּיאוּ לְעֵילָא בַּהֲדֵי אִנּוּן נִשְׁמָתִין. הֲדָא הוּא דִכְתִיב, (בראשית א׳:כ׳) יִשְׁרְצוּ הַמַּיִם שֶׁרֶץ נֶפֶשׁ חַיָּה, דָּא בְּרִית קַיָּימָא קַדִּישָׁא נְהָר דְּנָגִיד וְנָפִיק, וּמַיָא דִילֵיהּ אִתְרַבִּיאוּ וְרַחֲשִׁין רִחֲשָׁא וְרִבּוּיָא דְּנִשְׁמָתֵיה לְהַהִיא חַיָּה.","וּבְאִנּוּן נִשְׁמְתִין דְּעָאלִין בְּהַהִיא חַיָּה נַפְקֵי כַּמָּה עוֹפֵי דְּפָרְחָן וְטָאסָן כָּל עָלְמָא. וְכַד נִשְׁמְתָא נָפְקָא לְהַאי עָלְמָא הַהוּא עוֹפָא דְּפָרַח וְנָפַק בַּהֲדֵי הַאי נִשְׁמְתָא מֵהַהוּא אִילָנָא נָפַק עִמֵיהּ. כַּמָּה נָפְקָן בְּכָל נִשְׁמְתָא וְנִשְׁמְתָא. (קס\"א ב', כ\"א, מ\"א ב) תְּרֵין, חַד מִימִינָא וְחַד מִשְּׂמָאלָא. אִי זָכֵי אִנּוּן נָטְרִין לֵיהּ דִּכְתִיב, (תהילים צ״א:י״א) כִּי מַלְאָכָיו יְצַוֶּה לָךְ. וְאִי לָא אִנּוּן מְקַטְרְגֵי עֲלֵיהּ. אָמַר רִבִּי פִּינְחָס תְּלָתָא אִנּוּן דְּקַיְימֵי אַפּוֹטְרוֹפְּסִין עֲלֵיה דְּבַּר נָשׁ כַּד זָכֵי. דִּכְתִיב, (איוב ל״ג:כ״ג) אִם יֵשׁ עָלָיו מַלְאָךְ מֵלִיץ אֶחָד מִנִּי אָלֶף לְהַגִּיד לְאָדָם יָשְׁרוֹ. אִם יֵשׁ עָלָיו מַלְאָךְ הָא חַד. מֵלִיץ תְּרֵי. אֶחָד מִנִּי אָלֶף לְהַגִּיד לְאָדָם יָשְׁרוֹ הָא תְּלַת."],[[0,"","רי) \u0003ודא חובא דההוא\u0004 וכו'. וזהו חטא הנחש הקדמוני, שמחבר למטה ונפרד למעלה, ומשום זה גרם מה שגרם אל העולם. כי צריכים להפריד למטה ולחבר למעלה, ואור השחור, שהוא המלכות, צריך ליחדו למעלה, בז\"א, בחבור אחד, שתתאחד אחר כך בצבאיה ביחודה, ולהפרידה מצד הרע."],[0,"","פירוש. כי היחוד של המשכת ג\"ר לזו\"ן, הוא רק על ידי שמעלים אותן למקום או\"א שלמעלה מחזה דא\"א, שהז\"א נכלל באבא והנקבא באמא, ואז מתיחדים שניהם, והז\"א משפיע ג\"ר מאבא אל הנוקבא המלבשת לאמא. אבל למטה מחזה דא\"א, ששם עמידתם של הזו\"ן בקביעות, אסור לעשות היחוד דהמשכת ג\"ר לנוקבא. והטעם הוא ענין ארוך, ואומר, שזה הוא החטא של עצה\"ד, אשר ה\u0003נחש\u0004 הקדמוני הביא על ידו מיתה לעולם. כי הסית את אדם וחוה לעשות יחוד זה לתתא במקום זו\"ן, שלמטה מחזה דא\"א שעי\"ז פגם גם לעילא, שמחמת זה נפסק הזווג גם באו\"א עלאין,"],[0,"","וז\"ש \u0003ודא חובא דנחש קדמאה, חבר לתתא ואתפרש לעילא, ובגין כך גרם מה דגרם לעלמא\u0004, כי חבר את הזו\"ן להשפעת ג\"ר בנוקבא \u0003לתתא\u0004 במקומן, שעם זה \u0003גרם מה\u0004 דגרם לבני העולם, דהיינו שהביא עליהם מיתה, והוא משום ד\u0003אתפרש לעילא\u0004, שזה גרם להפסק הזווג באו\"א, שמשם נמשכים החיים לבני העולם,"],[0,"","כי בעת שהס\"א מתקרב לינק מהזווג שלמטה מחזה דזו\"ן, ששם מקום אחיזתן, נפסק תיכף הזווג העליון דאו\"א, כי הם מתפרשים תיכף מלהשפיע זה בזה כדי שלא ירד השפע לס\"א. וכל זה היה \u0003דאצטריך לאפרשא לתתא ולחברא לעילא\u0004, כי צריכין להשמר \u0003לאפרשא\u0004 לזו\"ן \u0003לתתא\u0004 במקומם, שלא יזדווגו שם למטה בהמשכת ג\"ר, ו\u0003לחברא\u0004 אותם רק \u0003לעילא\u0004, דהיינו במקום או\"א עצמם."],[0,"","וז\"ש, \u0003ונהורא אוכמא אצטריך לאתאחדא לעילא בחבורא חדא\u0004: כי \u0003נהורא אוכמא\u0004, שהיא הנוקבא דז\"א, צריכין להעלותה עם הז\"א \u0003לעילא לנהורא חוורא\u0004, דהיינו לאו\"א, ולחבר הזו\"ן שם \u0003בחבורא חדא\u0004, וז\"א משפיע שפע ג\"ר מאבא אל הנוקבא. ואחר זה חוזרת הנוקבא עם השפע שקבלה אל מקומה למטה, ששם נמצאות נר\"ן דנשמות ישראל בבחינת מ\"ן,"],[0,"ולאתאחדא לבתר באכלוסהא ביחודהא",", והיא מתיחדת עם נשמות בני ישראל, הנקראות \u0003אכלוסהא\u0004 של הנוקבא, ביחוד אחד, ומשפעת להם משפע שקבלה למעלה במקום או\"א. \u0003ולאפרשא לה מסטרא בישא\u0004, כי ע\"י זה שנמנעים לחבר את הזו\"ן במקומם \u0003לתתא\u0004, מפרישים לנוקבא \u0003מסטרא בישא\u0004, שאין הס\"א יכול להנות מהשפע. אמנם אם מחברים לזו\"ן \u0003לתתא\u0004, אז יכול הס\"א לקבל את השפע, וע\"כ מתפרשן או\"א \u0003לעילא\u0004 ומפסיקין את הזווג שלהם כנ\"ל."],[1,"","ריא) \u0003ועם כל דא אצטריך\u0004 וכו': ועם כל זה צרך לדעת אשר \u0003אלקים הויה\u0004, הכל אחד בלא פרוד. הויה הוא האלקים. וכשהאדם ידע שהכל אחד, ולא ישים פרוד אז אפילו הצד האחר יסתלק מן העולם, ולא יהיה נמשך למטה."],[1,"","פירוש. עם כל זה, שיש פחד כל כך, שלא יעורר הזווג דזו\"ן במקומם, אין להמנע מחמת זה מעשות היחוד כהלכתו, דהיינו במקום או\"א, אלא \u0003למנדע דאלהים הוי\"ה כלא חד בלא פרודא\u0004, אלא שצריכים להמשיך יחוד הזו\"ן במקום או\"א, כדי ליחד הז\"א עם הנוקבא כאחד בלי פרודא,"],[1,"וכד ינדע בר נש דכלא חד ולא ישוי פרודא אפילו ההיא סטרא אחרא יסתלק מעל עלמא ולא אתמשך לתתא",", כי אם יתעצם האדם להעלות מ\"ן ולהעלות הזו\"ן ליחדם במקום או\"א כהלכתו, הנה לא לבד שלא יאחז ה\u0003ס\"א\u0004 בשפע, אלא עוד גורם זה להעביר את הס\"א שלא תוכל לשלוט בעולם."],[2,"","ריב) \u0003והיינו רזא דכתיב\u0004 וכו': והיינו סוד הכתוב, והיו \u0003למאורות\u0004, שהוא אותיות אור מות, כי הקליפה הולכת אחר המוח. המוח \u0003אור\u0004, הצד האחר \u0003מות\u0004. אור הוא בחבור, האותיות במ\u0003אור\u0004ות, מות הוא באותיות נפרדות ב\u0003מ\u0004אור\u0003ות\u0004, וכש\u0003אור\u0004 זה מסתלק משם, מתחברות אותיות הפרוד \u0003מות\u0004. כלומר, כשתקח אותיות אור מתוך המלה \u0003מ\u0004אור\u0003ות\u0004 מצטרפות האותיות מות."],[2,"","פירוש. זסו\"ה והיו למאורות. אשר הקליפה עולה ובאה אחרי המוח. מוח הוא \"אור\" הסטרא אחרא היא \"מות\" \u0003אור\u0004 הוא בחיבור האותיות, \u0003מות\u0004 הוא בפירוד האותיות. פירוש: כח הדין שבמלכות הוא שורש למציאות הס\"א והקליפות, בסו\"ה ומלכותו בכל משלה. והנה ע\"י היחוד של הזו\"ן באו\"א להמשכת ו\"ק וג\"ר, נמצא כח הדין שבמלכות מתהפך להיות לבחינת \u0003נהורא אוכמא\u0004 ע\"י המשכת ו\"ק ב\u0003יחודא תתאה\u0004 דק\"ש כנ\"ל, ואח\"כ מעלים אותה שנית אל או\"א, ו\u0003נהורא אוכמא\u0004 של המלכות מתיחד ב\u0003נהורא חוורא\u0004 דאו\"א עלאין כנ\"ל."],[2,"","ולפיכך נרמז היחוד הזה בכתוב, והיו למאורות, שהוא אותיות \u0003אור-מות, אור בחבור דאתוון\u0004, שע\"י המשכת ו\"ק וג\"ר לנקבא ב\u0003חבורא חדא\u0004 עם הז\"א במקום או\"א, הנה כמו שנתהפך כח הדין שבנוקבא להיות \u0003אור\u0004 ממש, כן נתבטלו כל הכחות של הס\"א והקליפות הנמשכות מכח הדין הזה, ונמצא \u0003קליפה בתר מוחא סלקא\u0004, שהקליפה מתבטלת מכח המוחין דנוקבא, כיון ששורשו של ס\"א, שהיא כח הדין שבנוקבא, נתבטל ב\u0003מוחא\u0004 דנוקבא ונעשה ל\u0003אור\u0004, הנה בהכרח שגם כח הקליפה נתבטל,"],[2,"","ונמצא \u0003אור בחבורא דאתוון מות בפרודא\u0004 שע\"י החבור דזו\"ן, שכח הדין נעשה ל\u0003אור\u0004, נפרדו \u0003אתוון\u0004 ד\u0003מות\u0004 שהן הס\"א, כלומר שנתבטלו תוך ה\u0003אור\u0004 ונעשה הצירוף \u0003מאורות אור\u0004 באמצע ב\u0003חבור\u0004, ו\u0003מות\u0004 בפרודא, ה\u0003מ'\u0004 בתחילת התיבה, ו\u0003ות'\u0004 בסוף התיבה."],[2,"","אבל \u0003וכד האי אור אסתלק מתמן מתחברא באתוון מות דפרודא\u0004, כלומר, בעת שאינו עושה את היחוד במקום או\"א, אלא במקום זו\"ן לתתא, הנה \u0003האי אור אסתלק מתמן\u0004, כי תיכף נפרשים או\"א לעילא מזווגם ונפסק ה\u0003אור\u0004, ויוצאת המלה \u0003אור\u0004 מן \u0003מאורות\u0004, ונמצאת \u0003מתחברא באתוון מות\u0004, כי אחר יציאת \u0003אור\u0004 מהמלה \u0003מאורות\u0004 נשאר שם המלה \u0003מות\u0004, כי האותיות \u0003אור\u0004 כבר יצאו מהתיבה, ואינן מפסיקות עוד להפריד את האותיות \u0003מות\u0004. וזהו רומז על \u0003חובא דההוא נחש קדמאה שחבר לתתא\u0004 במקום זו\"ן, וע\"כ \u0003אתפרש לעילא\u0004 לאו\"א, כי נפסק זווגם מחמת זה והביא ה\u0003מות\u0004 לעולם."],[3,"","ריג) \u0003מאלין אתוון שריאת\u0004 וכו': מאלו האותיות התחילה חוה, וגרמה רעה לעולם. כמו שכתוב, \u0003ותרא\u0004 האשה כי טוב החזירה האותיות של \u0003מאורות\u0004 לאחור, שלקחה משם אותיות ותרא, ונשאר במלה \u0003מ\u0004א\u0003ו\u0004רות \u0003מ\"ו\u0004. והן הלכו ולקחו האות \u0003ת'\u0004 עמהן, ונעשה הצירוף \u0003מות\u0004. וגרמה מות לעולם. כמו שכתוב."],[3,"","פירוש. מהיחוד המתבאר ב\u0003אתוון דיהי מאורות\u0004 שהן המשכת ג\"ר לזו\"ן. שהמיחדם לעילא במקום או\"א ממשיך אור ב\u0003חבורא\u0004, שהוא מפריד \u0003אתוון\u0004 ד\u0003מות\u0004 בהתפשטותו לתוכן, ונעשה הצירוף \u0003מאורו\"ת\u0004, ואם מיחדים את זו\"ן לתתא במקומם, חוזר ומסתלק אור מהצירוף מאורות, ונשאר שם \u0003מות\u0004 ב\u0003חבור דאתוון\u0004, (כנ\"ל בדבור הסמוך)."],[3,"","ואומר \u0003מאלין אתוון שריאת חוה\u0004, כי תחלת חטאה של חוה בעצה\"ד מתחיל מן \u0003ותרא האשה כי טוב\u0004, רומז ש\u0003חוה\u0004 משכה לה אתוון \u0003ותרא\u0004 מן המלה \u0003מאורות\u0004, דהיינו ששמעה בעצת הנחש לחבר זו\"ן למטה במקומם, ופגמה בזה את הצירוף של \u0003מאורו\"ת\u0004, ואז \u0003אהדרת אתוון למפרע\u0004, כי מתוך שחברה \u0003לתתא\u0004 גרמה לאפרשא או\"א \u0003לעילא\u0004 ונתפרדו \u0003אתוון\u0004 של הצירוף או\"ר המפרידות ומבטלים צירוף \u0003מו\"ת\u0004, שבסוד המלה, \u0003מאורו\"ת\u0004, ועשתה הצירוף של \u0003ותרא\u0004, ש\u0003אתוון אור\u0004 מפוזרות בה \u0003למפרע\u0004, מתוך ה\u0003ת'\u0004 שנתמצעה ביניהן, אשר \u0003ת'\u0004 זו היא בחינת הנוקבא דס\"א הנקראת \u0003מו\"ת\u0004, שנתקרבה אל ה\u0003אור\u0004 לקבל ולינק ממנו."],[3,"","כי בס\"א הנקראת \u0003מות\u0004, יש דכר ונוקבא \u0003ס\"ם\u0004 ו\u0003לילית\u0004. שהאות \u0003מ'\u0004 היא הדכר של \u0003מו\"ת\u0004 הנקרא \u0003ס\"ם\u0004, והאות \u0003ת'\u0004 היא הנוקבא שלו הנקראת \u0003לילית\u0004. וע\"י ששמעה בעצת הנחש לחבר מ\u0003לתתא\u0004, תיכף נתקרבה הנוקבא ד\u0003מו\"ת\u0004 לינק מהשפע, ונתפזרו \u0003אתוון\u0004 ד\u0003אור למפרע\u0004, כצירוף של \u0003ותרא\u0004, כי ה\u0003ת'\u0004 נתמצעה תוך ה\u0003אור\u0004 ופיזרה אותן."],[3,"","ואחר ש\u0003חוה\u0004 משכה לה אתוון \u0003ותרא\u0004 ממאורות, \u0003אשתאר מ\"ו\u0004 מהצירוף \u0003מאורו\"ת\u0004, שהן הדכר הנקרא \u0003מ'\u0004 ד\u0003מ\u0004ות, ובחינת היסוד הנקראת \u0003ו'\u0004 של מ\u0003ו\u0004ת. \u0003ואינון אזלו ונטלו אות ת' בהדייהו\u0004, שהדכר ד\u0003מו\"ת\u0004 שהוא \u0003מ\"ו\u0004 שנשאר מ\u0003מ\u0004אור\u0003ו\u0004ת אזלו אל הנוקבא שהיא \u0003ת'\u0004 דמו\u0003ת\u0004, ונזדווגו שניהם והביאו \u0003מו\"ת\u0004 על העולם, \u0003כמה דכתיב ותרא\u0004, כי הדכר דס\"א שהוא \u0003מ\"ו\u0004 נזדווג ב\u0003ת'\u0004 של ו\u0003ת\u0004רא, שכבר היתה ב\u0003חוה\u0004. וז\"ס ביאת הנחש על חוה והטיל בה זוהמא, שע\"י שמיעתה לעצת הנחש נכנסה בה ה\u0003ת'\u0004 שהפרידה ופזרה לאתוון ד\u0003או\"ר\u0004 ועשתה בראיה שלה את הצירוף של אתוון \u0003ותרא\u0004, ואח\"כ בא הדכר דס\"א שהוא \u0003מ\"ו\u0004 ונזדווג עם \u0003ת'\u0004 זו, שכבר היתה בה בחוה. ונתגלה ה\u0003מו\"ת\u0004 בעולם."],[4,"","ריד) \u0003ותרא א\"ר אלעזר\u0004 וכו': ותרא: אמר ר' אלעזר, אבי, הנה למדתי, אחר שחוה לקחה אותיות ותרא מן מאורות, לא נשאר מ\"ו, אלא שנשארה ה\u0003מ'\u0004 יחידה, משום שה\u0003ו'\u0004 שהיא תמיד אות של חיים, נתהפכה, למות, שהלכה ולקחה עמה ה\u0003ת'\u0004, שכתוב \u0003ות\u0004קח \u0003ות\u0004תן, ונשלמה מלה זו ונתחברו האותיות, מות. אמר לו ברוך אתה בני. והרי העמדנו דבר הזה."],[4,"","פירוש. ר\"א השיב אותו הרי למדנו שה\u0003מ'\u0004 נשארה יחידה כלומר, בלי \u0003ו'\u0004 שהיא יסוד, כי ל\u0003ס\"ם\u0004 שהוא דכר של \u0003מו\"ת\u0004 לא היה בחינת יסוד, כי אל אחר אסתרס, אלא ה\u0003ו'\u0004 שהיא חיים תמיד, דהיינו יסוד של הקדושה, נתהפך מהקדושה אל הקליפה, ונעשה יסוד אל הדכר של \u0003מות\u0004, ואחרי כן, דהיינו אחר שהרויח בחינת יסוד מהקדושה, הלכה \u0003ו'\u0004 ונזדווגה עם ה\u0003ת'\u0004 ואז \u0003ואתחברו אתוון\u0004, נתחבר ה\u0003מ'\u0004 עם ה\u0003ת'\u0004, ע\"י ה\u0003ו'\u0004 שעשק מהקדושה."],[4,"","ומביא ראיה מהכתובים של החטא דעצה\"ד, שמתחילים בחיבור \u0003ו' ת', דכתיב ו'תקח ו'תתן\u0004, כי יציאת ה\u0003ו'\u0004 לס\"א נולדה ע\"י החטא דעצה\"ד עצמו, מה שלא היה לה מקודם לכן. והודה ר\"ש לדבריו, \u0003ואמר ליה בריך אנת ברי\u0004 וכו'."],[5,"","רטו) \u0003פקודא חמישאה\u0004 וכו': המצוה החמישית. כתוב, ישרצו המים שרץ נפש חיה. במקרא הזה יש שלש מצות, אחת, לעסוק בתורה, אחת, לעסוק בפריה ורביה, ואחת, למול לשמונה ימים ולהעביר משם את הערלה. וצריך לעסוק בתורה ולעמול בה בכל יום, לתקן נפשו ורוחו."],[5,"","פירוש. כי ד' \u0003פקודין\u0004 הקודמים, הנמשכים מד' הימים הראשונים דמעשה בראשית, באו לתקן את המדרגות בעולם האצילות עצמו, שהן ד' המדרגות חו\"ב וזו\"ן שבעולם האצילות כנ\"ל, אשר \u0003פקודא קדמאה\u0004 הנמשך ממלת \u0003בראשית\u0004 ה\"ס \u0003יראה\u0004, דהיינו בינה עלאה, שה\"ס יראה \u0003בגין דאיהו רב ושליט\u0004, והיינו רק בחינת ג\"ר של הבינה, שנתקנה לאבא ואמא עלאין המלבישין לא\"א מפה עד החזה שלו, הנקראות \u0003י'\u0004 דהוי\"ה."],[5,"ופקודא תניינא",", הנמשך מהמאמר \u0003יהי אור\u0004, הוא לתקון ז\"ת דבינה, בסוד \u0003אהבה רבה שלימתא\u0004, הנקראות ישראל סבא ותבונה, שמבחינת הקביעות הן מלבישות לא\"א מחזה עד הטבור שלו, דהיינו למטה מהפרסא שבגוי מעוהי דא\"א. אמנם במאמר \u0003יהי אור\u0004 הנאמר בהן, עלו ונעשו פרצוף אחד עם או\"א שלמעלה מחזה דא\"א, ומשם לראש דא\"א, והבינה חזרה שם להיות חכמה. שה\"ס \u0003אהבה רבה\u0004, וה\"ס \u0003ה'\u0004 ד\u0003ה\u0004וי\"ה, ומהם מושפעין כל המוחין לזו\"ן."],[5,"","אבל מאו\"א עלאין עצמם, שהם ג\"ר דבינה אין זו\"ן יכולים לקבל מוחין, כי הם נתקנו בעצמם בסוד אוירא דכיא, שהוא אור חסדים בסוד כי חפץ חסד הוא. ומשום זה הם נקראים \u0003יראה\u0004, כי סוד \u0003אהבה רבה\u0004 שהם מוחין דהארת חכמה אינם מושפעים מהם לזו\"ן, אלא רק מז\"ת דבינה הנקראות ישסו\"ת,"],[5,"","אמנם בחינת ה\u0003אהבה רבה\u0004 שבישסו\"ת אינה מגולה רק מבחינת מחזה ולמעלה דישסו\"ת, שהם עומדים אז למעלה מפרסא דבגוי מעוהי דא\"א, אמנם מחזה ולמטה דישסו\"ת העומדים למטה מפרסא דאו\"א, נעשה שם בחינת הגניזו של אור החכמה, שה\"ס \u0003ויהי אור\u0004 לעולם הבא, שהם ישסו\"ת שלמעלה מפרסא, אבל ישסו\"ת השניים שלמטה מפרסא הנה האור נגנז בהם. ובחינת התבונה שבהם נעשית בסוד \u0003יבשה.\u0004"],[5,"ופקודא תליתאה",", הנמשך מב' המאמרות שביום ג', שהם \u0003יקוו המים מתחת השמים אל מקום אחד ותראה היבשה.\u0004 ומ\u0003תדשא הארץ דשא\u0004 וכו', הם לתיקון מוחין דו\"ק לזו\"ן, ש\u0003יחודא עלאה\u0004 נמשך מהמאמר \u0003יקוו המים\u0004 והוא לז\"א. \u0003ויחודא תתאה\u0004 נמשך אל ו\"ק דנוקבא מהמאמר \u0003תדשא הארץ דשא.\u0004"],[5,"ופקודא רביעאה",", הנמשך מהמאמר ד\u0003יהי מאורות\u0004, הוא לתקון ג\"ר בז\"א ונוקבא. הרי שעד יום חמישי כבר נתקנו כל התיקונים הצריכים לאו\"א וישסו\"ת וזו\"ן דאצילות, עד שהזו\"ן קבלו ג\"ר שבהם ונעשו ראויים לזווג פב\"פ בקומה שוה, וע\"כ מכאן ואילך, באים שאר הפקודין, שהם תיקונים הצריכים להמשיך מזווג הזו\"ן פב\"פ."],[5,"","וזה אמרו \u0003פקודא חמישאה, כתיב ישרצו המים שרץ נפש חיה, בהאי קרא אית תלת פקודין\u0004, כי עתה צריכין להמשיך השלימות מסוד זווג זו\"ן פב\"פ, שהא' הוא להמשיך משם נשמה קדושה, שגם האדם עצמו יזכה לזווג טהור וקדוש, שזה נעשה ע\"י עסק התורה, והב' הוא להוליד נשמתין קדישין והג' לתיקון ברית קיימא ע\"י חיתוך ופריעה. כמו שמבאר והולך."],[5,"","וז\"ש, \u0003למלעי באורייתא ולאשתדלא בה ולאפשא לה\u0004 וכו': \u0003למלעי\u0004 היינו להגות בפה אע\"פ שלא ידע, בסו\"ה חיים הם למוצאיהם, למי שמוציא אותם בפה. שעי\"ז קונה נפש קדושה, \u0003ולאשתדלא בה\u0004, היינו להשתדל ולעשות כל מה שבכחו כדי להשיג אותה ולהבינה, שעי\"ז קונה רוח קדוש, \u0003ולאפשא לה\u0004, היינו אחר שזכה לתקן \u0003נפשיה ורוחיה\u0004, לא יסתפק בזה, רק צריך להרבות אותה תמיד, בסוד מעלין בקודש ואין מורידין ועי\"ז זוכה לנשמה קדושה.."],[5,"","וז\"ש \u0003ולאפשא לה בכל יומא לתקנא נפשיה ורוחיה\u0004 להרבות בתורה בכל יום בכדי לתקן נפשו ורוחו. כי עי\"ז שמרבה בתורה בכל יום ומוסיף תיקון לנפשו ורוחו הוא זוכה לנשמה קדושה. \u0003דכיון דבר נש אתעסק באורייתא אתתקן בנשמתא אחרא קדישא\u0004, שמכיון שהאדם עוסק בתורה הוא מתתקן בנשמה קדושה אחרת, כי המרבה בעסק התורה, מלבד שזכה בנפש ורוח. הוא זוכה ומתתקן גם בנשמה קדושה."],[6,"","רטז) \u0003דכיון דבר נש\u0004 וכו': מכיון שהאדם עוסק בתורה, הוא מתתקן בנשמה אחרת קדושה, שכתוב, שרץ נפש חיה. שפירושו, נפש מחיה ההיא הקדושה, שהיא המלכות, כי כשהאדם אינו עוסק בתורה, אין לו נפש קדושה, הקדושה שלמעלה אינה שורה עליו, וכשהוא עוסק בתורה, באותו הרחש שדובב בה, זוכה לנפש חיה ההיא, ולהיות כמלאכים הקדושים."],[6,"","פירוש, חיה ה\"ס הנוקבא דז\"א בעת שהיא בגדלות פב\"פ עם הז\"א, כי אז נקרא הז\"א \u0003עץ החיים\u0004, והנוקבא \u0003חיה\u0004. ועי\"ז שהאדם מעלה מ\"ן ע\"י עסקו בתורה לשמה, ומזווג לזו\"ן פב\"פ, הוא ממשיך מזווגם נפש קדושה. וז\"ש \u0003נפש דההיא חיה קדישא\u0004, שהיא הנוקבא דז\"א. והאדם משיג זה רק ע\"י העלאת מ\"ן בעסק התורה, ונמצא \u0003דכד בר נש לא אתעסק באורייתא לית ליה נפשא קדישא\u0004, כי אין לו חלק בזווג קב\"ה ושכינתיה, שהרי לא העלה מ\"ן לייחד אותם."],[6,"","וזה שיעור הכתוב, \u0003ישרצו המים שרץ נפש חיה\u0004. כי התורה נקראת \u0003מים\u0004, וע\"י שמריץ מ\"ן ע\"י התורה זוכה ל\u0003נפשא קדישא\u0004, מ\u0003חיה\u0004 עלאה. ותדע, כי אין האדם זוכה להדבק בהקב\"ה מטרם שישיג נפש רוח נשמה מ\u0003חיה\u0004 עלאה קדישא (כמ\"ש בזוהר ויקרא דף קמד אות תלד). דנפש אתקשר ברוח ורוח בנשמה, ונשמה בקב\"ה."],[7,"","ריז) \u0003דכתיב ברכו\u0004 וגו': שכתוב, ברכו ה' מלאכיו. אלו הם העוסקים בתורה, שנקראים מלאכיו בארץ. וזהו שכתוב, ועוף יעופף על הארץ. זה הוא בעולם הזה. ובעולם ההוא, למדנו, שעתיד הקב\"ה לעשות להם כנפים כנשרים, לשוטט בכל העולם. שכתוב, וקוי ה' יחליפו כח יעלו אבר כנשרים."],[7,"","פירוש, כי כתוב, \u0003ברכו ה' מלאכיו גבורי כח עושי דברו לשמוע בקול דברו\u0004, ופירשו חז\"ל, עושי והדר לשמוע. כלומר שמדרך האדם שלא יוכל לעשות שום שליחות בטרם שישמע מה שהמשלח אומר אליו. משא\"כ המלאכים, עושים את שליחותם מטרם שישמעו ויבינו מה שהשי\"ת צוה אותם. והטעם כי רצון השי\"ת שולט עליהם ואין בהם שום דבר חוצץ שלא ימשכו אחר רצון השי\"ת, וע\"כ הם נמשכים אחר השי\"ת. כצל הנמשך אחר האדם, ונמצא משום זה אשר עשייתם קדמה לשמיעתם."],[7,"","ואומר \u0003דאינון דמתעסקין באורייתא\u0004 וממשיכים \u0003נפש קדישא\u0004 נמצא החומר שלהם, אע\"פ שהוא מארץ, הוא מתהפך להיות כמלאכי מרום, ועשייתם קדמה לשמיעתם, שעושים מצותיו ית' בכל השלימות מטרם שמשיגים מה שעושים. להיותם נמשכים גם הם אחר הש\"י כצל הנמשך אחר האדם, ותוכל לדמות זה כמו שתמצא, שבעת שהרוח מעלה משהו אבק לעיני האדם, הריהו סוגר מהר את עפעפיו מטרם שמחשבתו תרגיש זאת, ותמצא בזה תמיד, אשר עשייתו שהוא עצימת עיניו, מוקדמים לרגש מחשבתו באבק המתקרב."],[7,"","וז\"ש \u0003מלאכיו אלין אינון דמתעסקין באורייתא, דאקרון מלאכיו בארעא\u0004, כי אע\"פ שהם בארץ, נעשה גופם כמלאכי מרום, ועשייתם קדמה לשמיעתם, דהיינו שאינם נמלכים בשכלם כדי לעשות מצותיו ית' בשלימות, אלא עושים המצוה בכל שלימותה מטרם שיספיקו להרגיש במחשבתם מה שעושים, כדוגמת עצימת העפעפים המוקדם להמליך במחשבה, ולפיכך הם נבחנים למלאכים בארץ."],[7,"","וז\"ש \u0003גדפין כנשרין, ולאשטא בכל עלמא דכתיב וקוי ה'\u0004 וכו': עתיד הקב\"ה לעשות להם כנפים כנשרים לשוטט בכל העולם. כי כל עוד שבר נש לא זכה לנפש קדושה, שולטים עליו הס\"א, בסוה\"כ \u0003ואת נפש אויבך יקלענה בתוך כף הקלע\u0004 (שמואל א' כה) שפירשוהו (בזוהר ויקרא אות תכה) \u0003דאזלן ושטאן בעלמא, ולא אשכחן אתר לנייחא, לאתקשרא ביה, ואסתאבן בגו סטרא דמסאבותא\u0004, וכו' \u0003דהא בקדושה לא עייל ולא אתכליל\u0004."],[7,"","פירוש, כי אי אפשר להדבק בהשי\"ת ולקיים מצותיו כראוי, רק אחר שמאמין בשמותיו של הקב\"ה שהוא טוב ומיטיב לכל ורחום וחנון וכו', ואלו, שעוד לא זכו לנפש דקדושה, הרי גם הס\"א עוד שולטת עליהם ונמצא \u0003דאזלן ושטאן בעלמא ולא אשכחן אתר לנייחא\u0004 שבעת שמחשבותיהם משוטטות בעולם, ורואים ההנהגה של הש\"י בבני העולם, שלפי דעתם אינה כל כך טובה כפי שצריכה להיות ע\"פ שמותיו הקדושים, נמצאים פוגמים ח\"ו בשמותיו הקדושים, \u0003ולא אשכחן אתר לנייחא\u0004, שאינם מוצאים מקום מנוחה שיוכלו להאמין בשמותיו ית', \u0003לאתקשרא בי'\u0004, ולפיכך \u0003ואסתאבן בגו סטרא דמסאבותא\u0004 ונטמאים בתוך סטרא דטומאה, כלומר, שבאים ח\"ו לכפירה בו ית', וכל זה הוא \u0003דהא בקדושה לא עייל ולא אתכליל\u0004 שהרי לא נכנס בקדושה, ולא נכלל בה. כי לא זכה בנפש דקדושה, ואינו עושה פעולות להכלל בקדושה."],[7,"","אמנם \u0003אינון דמתעסקין באורייתא\u0004 והמשיכו נפש קדישא, הנה מתהפך גופם להיות כמלאכים, שזוכים להקדים עשיה לשמיעה כמוהם, וע\"כ עליהם כתוב, ועוף יעופף על הארץ, \u0003דזמין קב\"ה למעבד לון גדפין כנשרין ולאשטא בכל עלמא\u0004 שעתיד הקב\"ה לעשות להם כנפים כנשרים וישוטטו בכל העולם. פירוש, כי הם משוטטים במחשבותיהם בכל העולם כולו ורואים הנהגתו ית', ועכ\"ז לא לבד שאינם נכשלים \u0003בסטרא דמסאבותא\u0004, אלא שעוד הם מקבלים כח להעלות מ\"ן ולהגדיל כחם תמיד \u0003דכתיב וקוי ה' יחליפו כח יעלו אבר כנשרים\u0004, כי עי\"ז מעלים \u0003אבר כנשרים\u0004, לשוטט בכל מקרי בני העולם, והם מחליפים כח תמיד, ומעלים מ\"ן בכח אמונתם ביחודו ית' וממשיכים תמיד רוח קדישא מלעילא."],[8,"","ריח) \u0003והיינו דכתיב ועוף\u0004 וגו': וזהו שכתוב, ועוף יעופף על הארץ. כי התורה שנקראת מים ישרצו ויוציאו רחש של נפש חיה, ממקומה של חיה ההיא, שהיא המלכות, ימשכו אותה למטה. כמו שלמדנו. ועל זה אמר דוד, לב טהור ברא לי אלקים, לעסוק בתורה, ואז, ורוח נכון חדש בקרבי."],[8,"","פירוש, כי חוזר לבאר שיעור הכתוב. \u0003ישרצו המים שרץ נפש חיה\u0004. ואומר ש\u0003מים\u0004 זו \u0003תורה, ישרצון\u0004, פירושו, שיוציאו נפש חיה, \u0003מאתר דההיא חיה ימשכון לה לתתא\u0004, שימשכו הנפש הזו מנוקבא עלאה, שהיא נקראת חיה, וממנה ימשכוה לעולם הזה."],[8,"ועל דא אמר דוד לב טהור ברא לי אלהים, למלעי באורייתא","שביקש שיתן לו השי\"ת לב טהור לעסוק בתורה ולהעלות מ\"ן \u0003וכדין ורוח נכון חדש בקרבי\u0004, ואז יזכה להמשיך רוח נכון ויוכל להדבק בו ית'."],[9,"","ריט) \u0003פקודא שתיתאה\u0004 וכו': המצוה הששית היא, לעסוק בפריה ורביה. כי כל מי שעוסק בפריה ורביה, גורם לאותו הנהר, יסוד דז\"א, שיהיה נובע תמיד. ומימיו לא יחדלו, והים, שהוא המלכות, מתמלא מכל הצדדים, ונשמות חדשות מתחדשות ויוצאות מאותו האילן, וצבאות רבים מתרבים למעלה עם אותן הנשמות כדי לשומרן. ז\"ש, ישרצו המים שרץ נפש חיה. זהו אות ברית קדש, הנהר הנמשך ויוצא, והמים שלו מתרבים ורוחשים רחש, ורבוי נשמות, לחיה ההיא."],[9,"","פירוש. כי באתערותא דלתתא אתער לעילא וגורם זווג קב\"ה ושכינתיה, ואז ה\u0003נהר\u0004, שהיא יסוד דז\"א, \u0003נביע תדיר\u0004 במיין דכרין \u0003ולא יפסקון מימוי\u0004 מלהשפיע בנוקבא ו\u0003ימא\u0004 שהיא הנוקבא דז\"א \u0003אתמליא בכל סטרין\u0004 מתמלא בכל הצדדים, דהיינו הן מסטרא של הזווג להחיות העולמות, והן מסטרא דהולדות נשמות ונשמות חדשות מתחדשות ויוצאות מעץ ההוא כלומר, לא נשמות חדשות ממש, אלא נשמות ישנות שכבר היו באדם הראשון ונשרו ממנו מחמת החטא דעצה\"ד, הן חוזרות ומתחדשות ע\"י \u0003האי אילנא\u0004, שהוא ז\"א, ונקראים משום זה נשמות חדשות."],[9,"","וז\"ש \u0003ונשמתין חדתין מתחדשן\u0004. כי נשמות חדשות ממש אינן באות לעולם רק אחר גמר התיקון של החטא דעצה\"ד. וצבאות רבים נאצלים למעלה עם הנשמות האלו. כי עם כל נשמה \u0003נפקין כמה מלאכין\u0004 כמ\"ש להלן. וכמן כן בזווגים דלהחיות העולמות יוצאים גם כן מלאכים."],[9,"","וז\"ש, \u0003ברית קיימא קדישא נהר\u0004 וכו', פירוש, כי \u0003שרץ נפש חיה\u0004 רומז על יסוד דז\"א הנקרא \u0003ברית קיימא\u0004 והוא \u0003נהר דנגיד\u0004, שהוא בחינת הנהר הנמשך ויוצא מז\"א, המלביש לאו\"א הנקרא עדן, להשקות את הגן, שהוא הנוקבא שלו. \u0003ומיא דיליה אתרביאו ורחשין רחשא\u0004 היינו מזווגים דבחינת ו\"ק הנקראים \u0003רחשין\u0004, שהוא תרגומו של \u0003ישרצו שרץ\u0004. ומבחינת זווגים דג\"ר להולדת נשמות, אומר \u0003וריביא דנשמתין לההיא חיה\u0004 והיא הנקראת \u0003נפש חיה\u0004 בכתוב."],[10,"","רכ) \u0003ובאינון נשמתין דעאלין\u0004 וכו': ועם אלו הנשמות הנכנסות באותה החיה, שהיא המלכות, יוצאים כמה עופות, דהיינו מלאכים, הפורחים ומשוטטים בכל העולם. וכשנשמה יוצאת לעולם הזה, העוף ההוא, שפרח ויצא עם הנשמה הזו מאותו האילן, יוצא עמו. כמה מלאכים יוצאים עם כל נשמה ונשמה. שנים, אחד מימין ואחד משמאל. אם זוכה הם שומרים אותו. שכתוב, כי מלאכיו יצוה לך לשמרך. ואם לא, הם משטינים עליו. אמר רבי פנחס, שלשה מלאכים הם, הנמצאים מגינים על האדם, כשהוא זוכה. שכתוב, אם יש עליו מלאך מליץ אחד מני אלף להגיד לאדם ישרו: אם יש עליו \u0003מלאך\u0004, הרי אחד. \u0003מליץ\u0004, הרי שנים. \u0003אחד\u0004 מני אלף להגיד לאדם ישרו הרי שלשה."]],[[0,"","וְזְהִוּ הַחֵטְא שֶׁל הַנָּחָשׁ הַקַּדְמוֹנִי הַהוּא - חִבֵּר לְמַטָּה וְהִפְרִיד לְמַעְלָה, וּמִשּׁוּם כָּךְ גָּרַם מַה שֶּׁגָּרַם לָעוֹלָם, מִשּׁוּם שֶׁצָּרִיךְ לְהַפְרִיד לְמַטָּה וּלְחַבֵּר לְמַעְלָה. וְאוֹר שָׁחֹר צָרִיךְ לְהֵאָחֵז לְמַעְלָה בְּחִבּוּר אֶחָד, וּלְהֵאָחֵז אַחַר כָּךְ בְּאוּכְלוּסֶיהָ בְּיִחוּדָהּ וּלְהַפְרִיד אוֹתָהּ מִן הַצַּד הָרָע."],[1,"","וְעִם כָּל זֶה צָרִיךְ לָדַעַת שֶׁאֱלֹהִים ה' הַכֹּל אֶחָד בְּלִי פֵרוּד. ה' הוּא הָאֱלֹהִים. וּכְשֶׁיֵּדַע אָדָם שֶׁהַכֹּל אֶחָד וְלֹא יָשִׂים פֵּרוּד, אֲפִלּוּ אוֹתוֹ הַצַּד הָאַחֵר יִסְתַּלֵּק מִן הָעוֹלָם וְלֹא יִמָּשֵׁךְ לְמַטָּה."],[2,"","וְהַיְנוּ סוֹד הַכָּתוּב וְהָיוּ לִמְאֹרוֹת. שֶׁהִנֵּה הַקְּלִפָּה עוֹלָה אַחַר הַמֹּחַ. הַמֹּחַ אוֹר. הַצַּד הָאַחֵר מָוֶת. אוֹר בְּחִבּוּר שֶׁל אוֹתִיּוֹת. מָוֶת בְּפֵרוּד. וּכְשֶׁהָאוֹר הַזֶּה מִסְתַּלֵּק מִשָּׁם, מִתְחַבֵּר בְּאוֹתִיּוֹת מָוֶת שֶׁל פֵּרוּד."],[3,"","מֵהָאוֹתִיּוֹת הַלָּלוּ הִתְחִילָה חַוָּה וְגָרְמָה רַע עַל הָעוֹלָם, כַּכָּתוּב (בראשית ג) וַתֵּרֶא הָאִשָּׁה כִּי טוֹב. הֶחֱזִירָה הָאוֹתִיּוֹת לְמַפְרֵעַ וְנִשְׁאַר מ\"ו, וְהֵם הָלְכוּ וְנָטְלוּ הָאוֹת תָּי\"ו עִמָּם, וְגָרְמָה מָוֶת עַל הָעוֹלָם, כְּמוֹ שֶׁכָּתוּב וַתֵּרֶא."],[4,"","אָמַר רַבִּי אֶלְעָזָר, אַבָּא, הֲרֵי לָמַדְנוּ מֵ\"ם נִשְׁאֲרָה יְחִידָה. וָא\"ו שֶׁהִיא חַיִּים, תָּמִיד מִתְהַפֶּכֶת וְהוֹלֶכֶת וְנוֹטֶלֶת תָּי\"ו, שֶׁכָּתוּב וַתִּקַּח וַתִּתֵּן. וְנִשְׁלְמָה הַתֵּבָה הַזּוֹ וְהִתְחַבְּרוּ הָאוֹתִיּוֹת. אָמַר לוֹ, בָּרוּךְ אַתָּה בְּנִי, וַהֲרֵי בֵּאַרְנוּ הַדָּבָר הַזֶּה."],[5,"","מִצְוָה חֲמִישִׁית - כָּתוּב יִשְׁרְצוּ הַמַּיִם שֶׁרֶץ נֶפֶשׁ חַיָּה. בַּפָּסוּק הַזֶּה יֵשׁ שָׁלֹשׁ מִצְווֹת: אַחַת לַעֲסֹק בַּתּוֹרָה, וְאַחַת לְהִתְעַסֵּק בִּפְרִיָּה וּרְבִיָּה, וְאַחַת לָמוּל לִשְׁמוֹנָה יָמִים וּלְהַעֲבִיר מִשָּׁם הָעָרְלָה. לַעֲסֹק בַּתּוֹרָה וּלְהִשְׁתַּדֵּל בָּהּ וּלְהַגְדִּילָהּ בְּכָל יוֹם לְתַקֵּן אֶת נַפְשׁוֹ וְרוּחוֹ."],[6,"","שֶׁכֵּיוָן שֶׁאָדָם מִתְעַסֵּק בַּתּוֹרָה, הוּא נִתְקָן בִּנְשָׁמָה אַחֶרֶת קְדוֹשָׁה, שֶׁכָּתוּב שֶׁרֶץ נֶפֶשׁ חַיָּה. הַנֶּפֶשׁ שֶׁל הַחַיָּה הַקְּדוֹשָׁה הַהִיא. שֶׁכַּאֲשֶׁר אֵין אָדָם מִתְעַסֵּק בַּתּוֹרָה, אֵין לוֹ נֶפֶשׁ קְדוֹשָׁה, וְהַקְּדֻשָּׁה שֶׁלְּמַעְלָה אֵינָהּ שׁוֹרָה עָלָיו. וְכַאֲשֶׁר מִשְׁתַּדֵּל בַּתּוֹרָה, בְּאוֹתוֹ הַדִּבּוּר שֶׁהוּא מְבָרֵר בָּהּ, הוּא זוֹכֶה לְנֶפֶשׁ הַחַיָּה הַהִיא וְלִהְיוֹת כְּמוֹ מַלְאָכִים קְדוֹשִׁים,"],[7,"","שֶׁכָּתוּב (תהלים קג) בָּרְכוּ ה' מַלְאָכָיו. אֵלּוּ הֵם שֶׁמִּתְעַסְּקִים בַּתּוֹרָה שֶׁנִּקְרָאִים מַלְאָכָיו בָּאָרֶץ. וְזְהִוּ שֶׁכָּתוּב וְעוֹף יְעוֹפֵף עַל הָאָרֶץ. זֶה בָּעוֹלָם הַזֶּה. וּבְאוֹתוֹ הָעוֹלָם שָׁנִינוּ, שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת לָהֶם כְּנָפַיִם כִּנְשָׁרִים וְשֶׁיָּשׁוּטוּ בְּכָל הָעוֹלָם, שֶׁכָּתוּב (ישעיה מ) וְקוֹיֵ ה' יַחֲלִיפוּ כֹחַ יַעֲלוּ אֵבֶר כַּנְּשָׁרִים."],[8,"","וְהַיְנוּ מַה שֶּׁכָּתוּב וְעוֹף יְעוֹפֵף עַל הָאָרֶץ - זוֹ הַתּוֹרָה שֶׁנִּקְרֵאת מַיִם, יִשְׁרְצוּ וְיוֹצִיאוּ שֶׁרֶץ שֶׁל נֶפֶשׁ חַיָּה מֵהַמָּקוֹם שֶׁל הַחַיָּה הַהִיא יִמְשְׁכוּ אוֹתָהּ לְמַטָּה, כְּמוֹ שֶׁנִּתְבָּאֵר. וְעַל כֵּן אָמַר דָּוִד (תהלים נא) לֵב טָהוֹר בְּרָא לִי אֱלֹהִים, לַעֲסֹק בַּתּוֹרָה, וְאָז - וְרוּחַ נָכוֹן חַדֵּשׁ בְּקִרְבִּי."],[9,"","מִצְוָה שִׁשִּׁית - לְהִתְעַסֵּק בִּפְרִיָּה וּרְבִיָּה. שֶׁכָּל מִי שֶׁמִּתְעַסֵּק בִּפְרִיָּה וּרְבִיָּה, גּוֹרֵם לַנָּהָר הַהוּא לִהְיוֹת נוֹבֵעַ תָּמִיד וְלֹא יִפָּסְקוּ מֵימָיו. וְהַיָּם מִתְמַלֵּא בְּכָל הַצְּדָדִים. וּנְשָׁמוֹת חֲדָשׁוֹת מִתְחַדְּשׁוֹת וְיוֹצְאוֹת מֵאוֹתוֹ הָאִילָן, וּצְבָאוֹת רַבִּים מִתְגַּדְּלִים לְמַעְלָה עִם אוֹתָם הַנְּשָׁמוֹת. זֶהוּ שֶׁכָּתוּב (בראשית א) יִשְׁרְצוּ הַמַּיִם שֶׁרֶץ נֶפֶשׁ חַיָּה. זוֹ בְּרִית הַקֹּדֶשׁ, הַנָּהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא, וְהַמַּיִם שֶׁלּוֹ מִתְרַבִּים וְשׁוֹרְצִים שֶׁרֶץ וְהִתְרַבּוּת שֶׁל נִשְׁמָתוֹ לַחַיָּה הַהִיא."],[10,"","וּבְאוֹתָן הַנְּשָׁמוֹת שֶׁנִּכְנָסוֹת לַחַיָּה הַהִיא, יוֹצְאִים כַּמָּה עוֹפוֹת שֶׁפּוֹרְחִים וְטָסִים בְּכָל הָעוֹלָם. וְכַאֲשֶׁר הַנְּשָׁמָה יוֹצֵאת אֶל הָעוֹלָם הַזֶּה, הָעוֹף הַהוּא שֶׁפּוֹרֵחַ וְיוֹצֵא עִם הַנְּשָׁמָה הַזּוֹ, מֵאוֹתוֹ הָעֵץ יוֹצֵא עִמּוֹ. כַּמָּה יוֹצְאִים עִם כָּל נְשָׁמָה וּנְשָׁמָה שְׁנַיִם, אֶחָד מִיָּמִין וְאֶחָד מִשְּׂמֹאל. אִם הוּא זוֹכֶה - הֵם שׁוֹמְרִים אוֹתוֹ, שֶׁכָּתוּב (תהלים צא) כִּי מַלְאָכָיו יְצַוֶּה לָּךְ. וְאִם לֹא - הֵם מְקַטְרְגִים עָלָיו. אָמַר רַבִּי פִּינְחָס, שְׁלֹשָׁה הֵם שֶׁעוֹמְדִים אֶפּוֹטְרוֹפּוֹסִים עַל הָאָדָם כְּשֶׁהוּא זוֹכֶה, שֶׁכָּתוּב (איוב לג) אִם יֵשׁ עָלָיו מַלְאָךְ מֵלִיץ אֶחָד מִנִּי אָלֶף לְהַגִּיד לְאָדָם יָשְׁרוֹ. אִם יֵשׁ עָלָיו מַלְאָךְ הִנֵּה אֶחָד. מֵלִיץ - שְׁנַיִם. אֶחָד מִנִּי אָלֶף לְהַגִּיד לְאָדָם יָשְׁרוֹ - הִנֵּה שְׁלֹשָׁה."]]],[["אָמַר רִבִּי שִׁמְעוֹן, חָמֵשׁ, דִּכְתִיב יַתִּיר, וַיְחֻנֶּנוּ וַיֹּאמֶר. וַיְחֻנֶּנּוּ חַד. וַיֹּאמֶר תְּרֵין. אָמַר לֵיהּ לָאו הָכִי, אֶלָּא וַיְחֻנֶּנּוּ דָּא קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי, דְּהָא לֵית רְשׁוּ לְאָחֳרָא אֶלָּא לֵיהּ. אָמַר לֵיהּ שַׁפִּיר קָא אֲמַרְתְּ.","וּמָאן דְּאִתְמְנַע מִפְּרִיָּה וּרְבִיָּה כִּבְיָכוֹל אַזְעִיר דִּיוּקְנָא דְּכָלִיל כָּל דִּיוּקְנִין. וְגָרִים לְהַהוּא נָהָר דְּלָא נַגְדִין מֵימוֹי וּפָגִים קְיָימָא קַדִּישָׁא בְּכָל סִטְרִין. וְעֲלֵיהּ כְּתִיב, (ישעיהו ס״ו:כ״ד) וְיָצְאוּ וְרָאוּ בְּפִגְרֵי הָאֲנָשִׁים הַפּוֹשְׁעִים בִּי. בִּי וַדַּאי דָּא לְגוּפָא. וְנִשְׁמְתֵיהּ לָא עָיִיל לְפַרְגּוֹדָא (דמלכא) כְּלָל וְאִטְרִיד מֵהַהוּא עָלְמָא,","פִּקּוּדָא שְׁבִיעָאָה לְמִגְזַר לִתְמַנְיָא יוֹמִין וּלְאַעֲבָרָא זוּהֲמָא דְּעָרְלְתָא, בְּגִין דְּהַהִיא חַיָּה אִיהִי דַרְגָא תְּמִינָאָה לְכָל דַּרְגִּין, וְהַהִיא נֶפֶשׁ דְּפָרְחָא מִינָהּ אִצְטְרִיכָא לְאִתְחֲזָאָה קַמָּהּ לִתְמַנְיָא יוֹמִין כְּמָה דְאִיהִי (בראשית ל\"ג א) דַרְגָּא תְּמִינָאָה.","וּכְדֵין אִתְחַזֵּי וַדַּאי דְּאִיהִי נְפֶשׁ חַיָּה. נֶפֶשׁ דְּהַהִיא חַיָּה קַדִּישָׁא וְלָא מִסִּטְרָא אָחֳרָא. וְדָא אִיהוּ יִשְׁרְצוּ הַמַּיִם. בְּסִפְרָא דַּחֲנוֹךְ יִתְרַשְׁמוּן מַיָא דְזַרְעָא קַדִּישָׁא רְשִׁימוּ דְּנֶפֶשׁ חַיָּה. וְדָא רְשִׁימוּ דְּאָת יוּ\"ד דְּאִתְרְשִׁים בְּבִשְׂרָא קַדִּישָׁא מִכָּל שְׁאָר רְשׁוּמִין דְּעָלְמָא.","וְעוֹף יְעוֹפֵף עַל הָאָרֶץ. דָּא אֵלִיָּהוּ דְּטָאס כָּל עָלְמָא בְּאַרְבַּע טָאסִין לְמֶהֱוֵי תַּמָּן בְּהַהוּא גְזִירוּ דִּקְיָימָא קַדִּישָׁא. וְאִצְטְרִיךְ לְתַקְּנָא לֵיהּ כּוּרְסַיָּיא וּלְאַדְכְּרָא בְּפוּמֵיהּ דָּא (לך לך צ\"ג ע\"א) כֻּרְסְיָיא דְּאֵלִיָּה\"וּ. וְאִי לָאו לָא שָׁארֵי תַּמָּן.","וַיִּבְרָא אֱלהִים אֶת הַתַּנִּינִים הַגְּדוֹלִים. תְּרֵין אִלֵּין עָרְלָה וּפְרִיעָה. גְּזִירוּ דְּעָרְלָה וּפְרִיעָה לְבָתַר. וְאִנּוּן דְּכַר וְנוּקְבָא. וְאֶת כָּל נֶפֶשׁ הַחַיָּה הָרוֹמֶשֶׂת, דָּא רְשִׁימוּ דְּאָ\"ת קַיָּימָא קַדִּישָׁא דְּאִיהִי נֶפֶשׁ חַיָּה קַדִּישָׁא כִּדְקָאֲמָרָן. אֲשֶׁר שָׁרְצוּ הַמַּיִם מַיִין עִלָּאִין דְּאִתְמָשְׁכוּ לְגַבָּהּ דְּאָת רְשִׁימוּ דָּא.","וּבְגִין דָא אִתְרְשִׁימוּ יִשְׂרָאֵל בִּרְשִׁימוּ קַדִּישָׁא וְדַכְיוּ לְתַתָּא, כְּגַוְונָא דְּאִנּוּן רְשִׁימִין קַדִּישִׁין, לְאִשְׁתְּמוֹדְעָא בֵּין סְטַר קַדִּישָׁא לְסִטְרָא אָחֳרָא דִמְסָאֲבוּ. אוּף יִשְׂרָאֵל רְשִׁימִין לְאִשְׁתְּמוֹדְעָא בֵּין (סטר) קִדּוּשָׁא, לְעַמִּין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת דְּאַתְיָין מִסִּטְרָא אָחֳרָא דִמְסָאֲבָא כְּמָה דְּאִתְּמָר. וּכְמָה דְּרָשִׁים לוֹן הָכִי רָשִׁים בְּעִירֵי וְעוֹפֵי דִלְהוֹן לִבְעִירֵי וְעוֹפֵי דְעַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. זַכָּאָה חוּלַקְהוֹן דְּיִשְׂרָאֵל:","פִּקּוּדָא תְּמִינָאָה לְמִרְחַם גִּיּוֹרָא (על) דְּעָאל לְמִגְזַר גַּרְמֵיהּ (יתרו ע' ע\"א) וּלְאָעֳלָא תְּחוֹת גַּדְפוֹי דִשְׁכִינְתָּא. וְאִיהִי אָעִילָא לוֹן תְּחוֹת גַּדְפָהָא לְאִנּוּן דְּמִתְפָּרְשָׁן מִסִּטְרָא אָחֳרָא מְסָאֳבָא וּמִתְקָרְבִין לְגַבָּהּ. דִּכְתִיב תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ.","וְאִי תֵימָא דְּהַאי נֶפֶשׁ חַיָּה דִכְלִילָא בְּיִשְׂרָאֵל לְכֹלָּא הִיא אִזְדַּמְּנַת. הֲדַר וְאָמַר לְמִינָהּ. כַּמָּה אַכְּסַדְּרִין וְאִדְרִין דָּא לְגוֹ מִן דָּא אִית לָהּ לְהַאי אֶרֶץ דְּאִיהִי חַיָּה תְּחוֹת גַּדְפָהָא.","גַּדְפָא יְמִינָא אִית לָהּ תְּרֵין אַכְּסַדְּרִין. וּמֵהַאי גַּדְּפָא אִתְפָּרְשָׁן לִתְרִין אוּמִין (משפטים צ\"ה ע\"א) אָחֳרָנִין דְּאִנּוּן קְרֵיבִין בְּיִחוּדָא (נ\"א ביחוסא) לְיִשְׂרָאֵל לְאָעֳלָא לוֹן לְגוֹ אַכְּסַדְּרִין אִלֵּין. וּתְחוֹת גַּדְפָא שְׂמָאלָא אִית תְּרֵין אַכְּסַדְּרִין אָחֳרָנִין וּמִתְפָּרְשָׁן לִתְרֵין אוּמִין אָחֳרָנִין דְּאִנּוּן עַמּוֹן וּמוֹאָב. וְכֻלְהוֹן אִקְּרוּן נֶפֶשׁ חַיָּה.","וְכַמָּה אִדְרִין סְתִימִין אָחֳרָנִין וְהֵיכָלִין אָחֳרָנִין בְּכָל גַּדְפָא וְגַדְפָא. וּמִנַּיְיהוּ נָפְקוּ רוּחִין לְאַפְרָשָׁא (שלח לך קס\"ח ע\"א) לְכָל אִנּוּן גִּיּוֹרִין דְּמִתְגַּיְּירִין. וְאִקְרוּן נֶפֶשׁ חַיָּה, אֲבָל לְמִינָהּ. וְכֻלְּהוּ עָאלִין תְּחוֹת גַּדְפוֹי דִּשְׁכִינְתָּא וְלָא יַתִּיר.","אֲבָל נִשְׁמְתָא דְיִשְׂרָאֵל נָפְקָא מִגּוֹ גּוּפָא דְּהַהוּא אִילָנָא, וּמִתַּמָּן פָּרְחִין נִשְׁמְתִין לְגוֹ הַאי אֶרֶץ גּוֹ מְעָהָא לְגוֹ לְגוֹ. וְרָזָא (מלאכי ג׳:י״ב) כִּי תִהְיוּ אַתֶּם אֶרֶץ חֵפֶץ. וְעַל דָּא יִשְׂרָאֵל בֵּן יַקִּיר דְּהָמוּ מְעָהָא עֲלֵיהּ וְאִקְרוּן (ישעיהו מ״ו:ג׳) הָעֲמוּסִים מִנִּי בָּטֶן וְלָא מְגַדְּפִין לְבַר. וְתוּ גִּיּוֹרִין לֵית לוֹן חוּלָקָא בְּאִילָנָא עִלָּאָה כָּל שְׁכֵּן בְּגוּפָא דִּילֵיהּ. אֲבָל חוּלָקָא דִלְהוֹן בְּגַדְפִין אִיהוּ וְלָא יַתִּיר. וְגִיּוֹרָא תְּחוֹת גַּדְפֵי שְׁכִינְתָּא וְלָא יַתִּיר (לך לך צ\"ו ע\"א) גֵּירֵי הַצֶּדֶק אִנּוּן דְּתַמָּן שָׁרָאן וְאִתְאַחֲדָן וְלָא לְגוֹ כְּמָה דְּאִתְּמָר. וּבְגִין כָּךְ תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ. וּלְמָאן, בְּהֵמָה וָרֶמֶשׁ וְחַיְתוֹ אֶרֶץ לְמִינָהּ כֻּלְהוּ שָׁאֲבִין נֶפֶשׁ מֵהַהִיא חַיָּה, אֲבָל כָּל חַד לְמִינָהּ כְּדְקָא חָזֵי לָהּ:"],[[0,"","רכא) \u0003א\"ר שמעון\u0004 וכו': א\"ר שמעון, חמשה מלאכים הם, כי כתוב עוד, ויחננו ויאמר: ויחננו, אחד. ויאמר, שנים. הרי חמשה. אמר לו, אינו כן, אלא \u0003ויחננו\u0004, זה הקב\"ה לבדו, ולא מלאך, כי אין רשות לאחר לחונן אותו, אלא הוא בעצמו. אמר לו, יפה אמרת."],[0,"","פירוש. יחד עם הנשמות נולדים ויוצאים כמה מלאכים הנקראים \u0003עופין\u0004, שהמלאכים ההם מסייעים הנשמות להכרעת כף הזכות, או להיפך שהם מקטרגים עליהן ודוחים אותן לכף חובה. כמ\"ש והולך. וז\"ש \u0003דפרחן וטאסן כל עלמא\u0004 שהם פורחים ומשוטטים בכל העולם, ורואים השגחתו יתברך על בני העולם כולו, איך הם מושגחים ממנו ית', ומודיעים לה לנשמה, ואם הנשמה זוכה היא מכריעה את עצמה ואת כל העולם כולו לכף זכות, ואם אינה זוכה, מכריעה את עצמה ואת כל העולם כולו לכף חובה. וז\"ש \u0003כמה נפקן בכל נשמתא ונשמתא\u0004."],[0,"","והנה רבי פינחס אינו חולק על ר\"ש, שאומר שרק \u0003תרין עופין\u0004, נולדים עם הנשמה. אלא אומר כי כל זמן שאין לו אלא אלו \u0003תרין עופין\u0004, אי אפשר לו להכריע את עצמו לכף זכות לגמרי, אלא הוא מטולטל מדין לרחמי ומרחמי לדין. אלא ע\"י מעשים טובים נולד לו מלאך שלישי, ואז זוכה להכריע לכף זכות. וז\"ש \u0003תלתא אינון\u0004 וכו' \u0003כד זכי\u0004 שלא יוכל לזכות זולת ע\"י שלשה מלאכים."],[1,"","רכב) \u0003ומאן דאתמנע\u0004 וכו': ומי שנמנע מפריה ורביה, מקטין כביכול את הצורה הכוללת כל הצורות, שהיא צורת אדם, וגורם לאותו הנהר, ליסוד דז\"א, שמימיו אינם נמשכים, ופוגם ברית הקדוש בכל הצדדים. ועליו כתוב, ויצאו וראו בפגרי האנשים הפושעים בי. בי ודאי. וזהו אמור לגוף, ונשמתו אינה נכנסת למסך כלל. דהיינו למחיצתו של הקב\"ה. וגורש מהעולם ההוא."],[1,"","ביאור הדברים המלכות נקראת \u0003דיוקנא דכליל כל דיוקנין\u0004, כי כל הצורות של הנר\"ן דצדיקים ומלאכים דג' העולמות בי\"ע נמשכות על ידיה, שהם חייליה וצבאיה, ולכן מי שאינו עוסק \u0003בפריה ורביה\u0004, נמצא שהוא ממעט דמות המלכות, ומעכבה מלהוציא כל חייליה וצבאיה. כי ע\"י אתערותא דלתתא יוצא כנגדה אתערותא דלעילא, וגורם לזווג קב\"ה ושכינתיה, להוליד נר\"ן ומלאכים בבי\"ע. כמ\"ש לעיל."],[1,"","וז\"ש \u0003וגרים לההוא נהר דלא נגדין מימוי\u0004 שגורם ליסוד דז\"א שלא ישפיע מיין דוכרין לשכינה הקדושה. ופוגם בברית הקודש בכל הבחינות שלו. כי הוא מעכב ב' בחינות הזווגים, הן מסטרא דו\"ק והן מסטרא דג\"ר. \u0003ועליה כתיב ויצאו וראו בפגרי האנשים הפושעים בי\u0004, כי מצות \u0003פריה ורביה\u0004 מגדילה לנשמתו בתמידות, ועי\"ז מנצח גם את גופו לנצח, שיעמוד בתחית המתים, ומי שאינו עוסק ב\u0003פריה ורביה\u0004 נמצא עושה את גופו כמו \u0003פגר\u0004, שעליו נאמר ויצאו וראו בפגרי וגו'. שנשמתו לא תוכל להכנס למחיצתו של הקב\"ה והוא נדחה מהעולם הבא."],[2,"","רכג) \u0003פקודא שביעאה\u0004 וכו': המצוה השביעית היא, להמול לשמונה ימים, ולהעביר זוהמת הערלה, משום שאותה החיה, שהיא מלכות, היא המדרגה השמינית לכל המדרגות, דהיינו כשמתחילים מבינה, ואותה הנפש העפה ממנה צריכה להראות לפניה לשמונה ימים, כמו שהיא המדרגה השמינית."],[2,"","פירוש. שאין הנוקבא דז\"א נקראת \u0003חיה\u0004 זולת על ידי עליתה והלבשתה את הבינה, שהיא דרגא תמינאה של ע\"ס מתתא לעילא, ונקראת גם המלכות שהיא נוקבא דז\"א בשם שמיני, כי עלתה שמונה מדרגות, שממנה עד הבינה, ורק אז נקראת גם היא \u0003חיה\u0004 כמו הבינה."],[2,"","והנה נפש האדם שנולדה מן הנוקבא דז\"א שנק' \u0003חיה\u0004, ונקראת שמינית, צריכה להראות לפני הנוקבא עם התקונים של מילה ופריעה, ביום השמיני ללידה שלה, ואז נראה וניכר בודאי, שהיא נפש מאותה חיה קדושה, ולא מצד אחר. כי אז, בכח המילה והפריעה נדחה ס\"א לגמרי \u0003מההיא נפש\u0004 אדם, והיא יכולה לקבל שלימות אורותיה של החיה ההיא. \u0003ודא איהו ישרצו המים\u0004. ובזה מקבלת המיין דוכרין עלאין מזו\"ן ומשתלמת במים האלו."],[3,"","רכד) \u0003וכדין אתחזי ודאי\u0004 וכו': ואז נראה ודאי שהיא נפש חיה. דהיינו נפש של אותה החיה הקדושה, שהיא מלכות, ולא מצד האחר. וזה הוא ישרצו המים, שפירש בספרו של חנוך, יתרשמו מי זרע הקדוש ברושם של נפש חיה. וזה הוא הרושם של אות \u0003י'\u0004, הנרשם בבשר קדש, יותר מכל שאר רשימות העולם."],[3,"","פירוש. כי מבאר הכתוב \u0003ישרצו המים שרץ נפש חיה\u0004, מלשון התרשמות והצטיירות, שע\"י המילה והפריעה, מצטיירין ומתרשמין המיין דוכרין עלאין המושפעים לנפש אדם, \u0003ברשימו\u0004 וציור של הנוקבא הנקראת \u0003נפש חיה\u0004."],[3,"","והנה עלמא עלאה בינה נרשם ונחתם עם \u0003י'\u0004, ועלמא תתאה מלכות נרשם ונחתם עם \u0003ה'\u0004, ובעת שהמלכות שהיא הנוקבא עולה ומלבשת על עלמא עלאה בינה, \u0003כדין נפקת ה'\u0004 ממנה, \u0003ואעילת י'\u0004 כמו הבינה. (כמ\"ש לעיל סוף אות י\"ז, ע\"ש בסולם)."],[3,"","וז\"ש \u0003ודא רשימו דאת י' דאתרשים בבשרא קדישא מכל שאר רשומין דעלמא\u0004 כי ע\"י מילה ופריעה מתעברים גם מהאדם כל \u0003הרשימין דעלמא\u0004 דין שהם מבחינת \u0003ה', ורשימו דאת י'\u0004 באה במקומה, כמו שנעשה בנוקבא שעלתה לבינה כנ\"ל, וכיון שבשר הקודש של היסוד נחתם ב\u0003י'\u0004 יכול גם האדם לקבל \u0003נפש חיה\u0004 שלימה מהנוקבא \u0003קדישא\u0004."],[4,"","רכה) \u0003ועוף יעופף\u0004 וכו': ועוף יעופף על הארץ. זה הוא אליהו, העף כל העולם בארבע עפיפות, כדי להיות שם באותה ברית מילה הקדושה. וצריך לתקן לו כסא, ולהזכיר בפיו, \u0003זה כסא של אליהו\u0004. ואם לא, אינו שורה שם."],[4,"","ביאור הדברים, כי יש להבין, דכאן דריש המקרא \u0003ועוף יעופף\u0004 על \u0003אליהו דטאס כל עלמא בארבע טאסין\u0004, ולהלן (פרשת בראשית א' דף שי\"ד אות ת\"ז) דריש המקרא שלאחריו, ואת כל עוף כנף למינהו, על מלאכין דטאסין ושאטין עלמא בשית טאסין."],[4,"","והענין הוא, כי כאן דריש בעיקר סיומא דקרא, דכתיב \u0003על הארץ\u0004, שאין לפרשו אל מלאכים עליונים, כי הם אינם בארץ, וע\"כ הכרח הוא שהוא \u0003אליהו\u0004. (כמ\"ש להלן בראשית ב' דף ק\"ז אות קס\"ו), \u0003יעופף על הארץ דא אליהו דאשתכח תדיר בארעא ולא מסטרא דאבא ואמא אשתכח, דאיהו בד' טאסין\u0004. פירוש כי המלאכים הם \u0003מסטרא דאו\"א\u0004, וע\"כ הם רק נמצאים בשמים, ויש להם ו\"ק חג\"ת נה\"י, וע\"כ כשבאים לארץ לעשות שליחותם טאסין \u0003בשית טאסין\u0004, כי הם מתלבשים בשש ספירות."],[4,"","אבל \u0003אליהו\u0004 אינו \u0003מסטרא דאו\"א\u0004 אלא מסטרא דמלכות וז\"ס \u0003אשתכח תדיר בארעא\u0004, ולפי שהמלכות אין לה אלא ד' ספירות מז\"א, שהן תנה\"י שמחזה ולמטה שלו, ע\"כ הוא \u0003טאס כל ארעא\u0004 רק \u0003בד' טאסין\u0004 דהיינו בהתלבשות ד' הספירות תנה\"י. וכיון שהכתוב אומר \u0003ועוף יעופף על הארץ\u0004 הרי שאינו קאי על מלאכים אלא על \u0003אליהו\u0004 שהוא בארץ. משא\"כ המקרא \u0003ואת כל עוף כנף למינהו\u0004, שלא נזכר שם \u0003על הארץ\u0004, קאי על המלאכים שהם \u0003מסטרא דאו\"א, דטאסין עלמא בשית טאסין\u0004."],[4,"למהוי תמן בההוא גזירו דקיימא קדישא","(להלן פרשת לך לך דף קכ\"ט אות שפ\"ח). אומר הטעם כי משום שאמר אליהו \u0003קנא קנאתי לה' כי עזבו בריתך בני ישראל\u0004 וגו' \u0003א\"ל חייך בכל אתר דהאי רשימא קדישא ירשמון ליה בני בבשרהון אנת תזדמן תמן, ופומא דאסהיד דישראל עזבו הוא יסהיד דישראל מקיימין האי קיימא. והא תנינן, על מה אתענש אליהו קמי קב\"ה, על דאמר דלטורא על בנוי\u0004. עכ\"ל."],[4,"","וח\"ו להבין הדברים לפי פשוטן ש\u0003אליהו\u0004 נתחייב להיות על כל ברית מילה בבני ישראל מטעם עונש על שאמר \u0003דלטורא\u0004 על ישראל. ועוד, איך אמר כאן לפנינו שצריכין להזמין אותו \u0003ולאדכרא בפומיה דא כורסייא דאליהו, ואי לאו לא שארי תמן\u0004. ואם ח\"ו הוא מוכרח להיות על הברית מילה מטעם עונש, הלא הוא מוכרח להיות \u0003תמן\u0004. ועוד למה צריך לסהדותא ד\u0003אליהו\u0004 שיעיד לפניו שבנ\"י מקיימים ברית מילה, וכי אין הכל גלוי לפניו ית'. אלא סוד גדול ונורא הסתירו כאן תחת מתק לשונם כדרכם תמיד."],[4,"","והענין תבין עם המובא בזוהר (שלח לך דף ל\"ט אות קי\"ז). \u0003פתח רבי אילעי\u0004 וכו' \u0003באברהם כתיב התהלך לפני והיה תמים, יעקב דאשתלים יתיר כתיב יעקב איש תם, אמאי אקרי איש תם בגין דלא אשתאר ביה פסולת כלל, דהא פריעה הוה ביה\u0004 וכו', \u0003אתר דפריעה שארי איהו שור דיוקנא דשמאלא דכורסיא דיליה, וההוא שור אקרי שור תם\u0004 וכו', \u0003בגין דאית שור מועד בסטר ערלה פריעה, וכמה גרדיני נימוסין נפקין מניה עד דרגא בתרייתא דאקרי שאיה\u0004 וכו', \u0003ודא בחבורא דחמור בישא\u0004 וכו' \u0003ויעקב איש תם בעלה דההוא תם\u0004, ע\"ש."],[4,"","ביאור הדברים כי ד' קליפות הן: רוח סערה, ענן גדול, אש מתלקחת, ונוגה לו סביב. וג' הראשונות הן קליפות טמאות כולן, אבל קליפת הנוגה חציה טוב וחציה רע, ובעת שג' הקליפות דבוקות בה נעשית כולה רע. ובעת שנפרדת מהן ומתדבקת בקדושה היא נעשית כולה טוב. ומקומן של ד' קליפות אלו הן בסיום הפרצוף, שהוא בסיום היסוד, שיש שם ב' עורות זה על זה, העור הא' נקרא \u0003ערלה\u0004, ובו כלולות ג' הקליפות הטמאות: רוח סערה וענן גדול ואש מתלקחת, והעור הב' נקרא עור ה\u0003פריעה\u0004, שהיא בחינת קליפת נוגה, שחציה טוב וחציה רע."],[4,"","והנה אדם הראשון נולד מהול, כי ג' הקליפות הטמאות לא היתה להן שום אחיזה בו, ולא היה בו אלא קליפת הנוגה לבד, שהיא עור ה\u0003פריעה\u0004, והיתה גם היא כולה טוב, להיותה נבדלת מג' הקליפות הטמאות, ונתדבקה בקדושה. אלא בחטא דעצה\"ד בפיתוי הנחש, הכלול מג' הקליפות הטמאות, משך עליו את העור הב' שהוא ה\u0003ערלה\u0004 כמ\"ש חז\"ל (סנהדרין לח:) אדה\"ר מושך בערלתו היה."],[4,"","וז\"ס הכתוב \u0003והועד בבעליו ולא ישמרנו\u0004 וגו' \u0003השור יסקל וגם בעליו יומת\u0004 (שמות כא), כי בעת שהערלה קפצה עליו ונתחברה ביסוד שלו תיכף פרחה ממנו הנשמה דאצילות ונפל לעשיה ונגזרה עליו מיתה. וז\"ס זוהר הנ\"ל, \u0003דאית שור מועד בסטר ערלה פריעה\u0004 כי מחמת שהועד שלא לאכול מעצה\"ד ולא נשמר ואכל ע\"כ קפצה עליו הערלה כנ\"ל. ונטמאו ב' העורות יחד, כי גם עור ה\u0003פריעה\u0004 שהוא נוגה, נטמא גם הוא מכח חיבורו ודבקותו בערלה, שהן ג' הטמאות. אמנם יש הפרש ביניהם, כי עור הפריעה נקרא \u0003שור תם\u0004, ולא \u0003מועד\u0004, מטעם היותה בקדושה גמורה מטרם חטא דעצה\"ד, והוא נטמא רק ע\"י הערלה שנתדבקה בו."],[4,"","ולפיכך יש ב' תקונים מיוחדים מילה ופריעה, כי ב\u0003שור המועד\u0004 נאמר \u0003השור יסקל\u0004 וכן הערלה צריכים להעביר ולחתוך מהקדושה ולזרוק אותה לעפר. אבל ב\u0003שור תם\u0004 נאמר, \u0003וחצו את כספו\u0004 וכן עור הפריעה יש להניחו בקדושה מחובר ליסוד, אלא שצריכים לחצות ולקרוע אותה לכאן ולכאן, שבזה מתגלים המוחין בחזרה אל הפרצוף, ונגלה בשר קודש."],[4,"","וז\"ש שם \u0003ובהאי שור עביד פריעה, ואעבר זוהמא דפסולת כלא\u0004 כי ע\"י שחוצים העור לכאן ולכאן מסביב היסוד, מתבטלת והולכת כל הזוהמא שקבל עור \u0003הפריעה\u0004 מכח חיבורו הקודם ב\u0003ערלה\u0004, והמוחין שנסתלקו מחמת הערלה יכולים לחזור ולהתגלות."],[4,"","אמנם אין זה מספיק עוד להחזיר כל המוחין שנסתלקו מאדה\"ר מחמת החטא דעצה\"ד, שהרי כתוב \u0003וגם בעליו יומת\u0004 אע\"ג ש\u0003יסקל השור\u0004. והוא מטעם כחו הגדול של \u0003שור המועד\u0004, שה\"ס הס\"מ המקטרג, מכח הכתוב \u0003והועד בבעליו ולא ישמרנו\u0004."],[4,"","וכדי לתקן זה נטל \u0003אליהו\u0004 אותו \u0003הדלטורא\u0004 של הס\"מ על עצמו, וקטרג על בני ישראל, במקום הס\"מ כמ\"ש \u0003כי עזבו בריתך בני ישראל\u0004, ונמצא בזה, שסתם פיו של הס\"מ ונתבטל שליחותו של הס\"מ, משום ש\u0003אליהו\u0004 קבל על עצמו את שליחותו, ואז יש לו כח גם להעשות סנגור אח\"כ, בעת שהוא רואה שבני ישראל מקיימים ברית."],[4,"","וזה אמרו (להלן לך לך דף קכ\"ט אות שפ\"ח), הטעם ש\u0003אליהו\u0004 צריך להיות בכל ברית מילה, משום \u0003ופומא דאסהיד דישראל עזבו, הוא יסהיד דישראל מקיימין האי קיימא\u0004, כיון שהוא נטל על עצמו כח הקטרוג של הס\"ם על בני ישראל, לאמר דישראל עזבו ברית בסו\"ה \u0003והועד בבעליו ולא ישמרנו\u0004, הנה משום זה יש לו כח להעיד גם כן שמקיימים הברית, ואז מתעבר כחו של ה\u0003שור המועד\u0004 לגמרי, וכל המוחין שנסתלקו בסבת \u0003שור המועד\u0004 יכולים לחזור ולהתגלות. והבן היטב. ועוד יתבאר להלן."],[4,"","וז\"ש, \u0003ואצטריך לתקנא ליה כורסייא\u0004: דהיינו מלבד כסא הסנדק שעליו נעשים ה\u0003מילה והפריעה\u0004, יש לתקן עוד כסא ב' לצורך \u0003אליהו\u0004. ויש להבין למה אינו מספיק כסא אחד לשניהם. והענין הוא כי סוד הכסא בכל מקום, הוא תחילת התיקון להשראת עליון בתחתון. וכבר נתבאר לעיל (בדיבור הסמוך), שענין המוחין המתגלים על ידי המילה והפריעה, וענין סהדותא של \u0003אליהו\u0004 על קיום הברית הם ב' דברים מיוחדים, כי שיעור המוחין המתגלים ע\"י ה\u0003פריעה\u0004 הם מבחינת \u0003שור תם, שלא נודע כי שור נגח הוא\u0004, שה\"ס החזרת הנוגה לקדושה ע\"י \u0003וחצו את כספו\u0004 ע\"ש."],[4,"","וענין סהדותא של \u0003אליהו\u0004 הוא להעביר את רעתו של \u0003שור מועד\u0004, שהוא כחם של ג' הקליפות הטמאות עצמן ולהסתים פיהם שלא יכלו לקטרג. ולפיכך צריכים לב' כסאות: הא' הוא כסא ה' והיינו הכסא של הסנדק, שהוא להשראת עצם המוחין ע\"י המילה והפריעה. והב' הוא להשראת הארת \u0003אליהו\u0004, הסותם פיהן של הקליפות שלא יוכלו לקטרג, והוא \u0003כסא אליהו\u0004."],[4,"ולאדכרא בפומיה דא כרסייא דאליהו ואי לאו לא שארי תמן",": ויש להבין מהו החוב הגדול הזה להזכיר בפה, \u0003דא כרסייא דאליהו\u0004, עד שאם אין מזכירין בפה, אע\"פ שהכינו לו כסא לא יבא שם. והענין הוא, כי מובא בזוהר (תשא דף ט\"ו אות מ\"ו), על הכתוב מה לך פה אליהו, שה\"ס פומיה דאליהו, וברית קיימא פה ה' איהו ע\"ש. הרי שיש הפרש בין ברית קיימא שהיא המוחין המתגלים ע\"י מילה ופריעה בסוד פה ה', ובין הפה של אליהו עצמו."],[4,"","ובכדי להבין זה, יש להעמיק יותר בענין סתימת פה של \u0003השור המועד\u0004, שלא יקטרג על ישראל אחר החזרת המוחין ע\"י מילה ופריעה. כי מלבד סהדותא ד\u0003אליהו\u0004 הנ\"ל צריכים עוד לתיקון מיוחד הנעשה ע\"י זריקת הערלה אל עפרא. כמ\"ש בזוהר (פקודי דף רי\"ב, אות תרצ\"א), \u0003בזמנא דאתגזר בר נש לתמניא יומין ושראת עליה שבת, מלכות קדישא, ההיא ערלה דגזרין ושדאן לה לבר, כדין קיימא ההוא ס\"א, וחמא דהאי איהו חולקים מקרבנא דא, כדין אתבר ולא יכיל לשלטאה ולקטרגא עלוי, וסליק ואתעביד סניגוריא על ישראל קמי קב\"ה\u0004, ע\"כ. בעת שהאדם נימול לח' ימים, שכבר עבר עליו יום השבת שה\"ס מלכות במוחין דאו\"א הנקראת קודש, הנה ערלה ההיא שחותכין ומשליכין אותה לחוץ, רואה אותה הס\"א שנותנין לה חלק מאותו הקרבן של ברית המילה. וע\"י מתנה זו היא מתהפכת מקטיגור להיות סניגור על ישראל לפני הקב\"ה."],[4,"","וביאור הדברים. כי מטבע הרוחניים שנכללים זה בזה, וכיון שהערלה היתה פעם דבוקה ביסוד, נמצא שבעת שחותכין אותה מהיסוד נוטלת עמה חלק מהקדושה, וכיון שאנו משליכין את הערלה אל החיצונים, הרי הם יונקים עי\"ז איזו נהירו מהמוחין המתגלים ע\"י מילה ופריעה. וע\"כ אינם רוצים עוד לקטרג על ישראל ולהשבית את המוחין האלו, כי גם הם יפסידו את חלקם שלוקחים מאלו המוחין, וע\"כ נעשים סניגור על ישראל, דהיינו לקיים בהם המוחין."],[4,"","ולפיכך אין \u0003אליהו\u0004 סובל תיקון זה, כי אע\"פ שהם פוסקין מלקטרג על ישראל, אמנם הם לוקחים בעד זה חלק מהקדושה, ובכדי לתקן זה, נטל \u0003אליהו\u0004 כל הקטרוג על עצמו, ואינו רוצה כלל לפייס אותם ע\"י נתינת חלק מקרבנא דקדושה, לפיכך אע\"פ שהס\"א כבר פסקה מלקטרג והיא נעשית סניגור, הרי \u0003אליהו\u0004 עצמו מקטרג עוד, כדי לעקור כחו של הס\"א לגמרי ולהפרידו מהקדושה, ולפיכך צריכים לפה של \u0003אליהו\u0004 נוסף על \u0003פה ה'\u0004 שמתגלה ע\"י המילה והפריעה המשאיר חלק מהקרבן לס\"א, כי \u0003פי אליהו\u0004 עוקר את הס\"א לגמרי, בסוד \u0003ופומא דאסהיד דישראל עזבו ברית, הוא יסהיד דישראל מקיימי ברית\u0004, (כנ\"ל בדיבור הסמוך)."],[4,"","וזה שצריכים \u0003לאדכרא בפומיה, דא כרסייא דאליהו\u0004 דהיינו שצריכים להזכיר ולהמשיך בחינת \u0003פומיה דאליהו\u0004 על \u0003כרסייא\u0004 שלו ולא יסתפק ב\u0003פה ה'\u0004 המסלק ג\"כ את הקטיגור ומהפכו לסניגור, שהרי נשאר מחויב ליתן חלק לס\"א כנ\"ל. אבל על ידי פומיה דאליהו הוא מסלק את הקטיגור, ואינו צריך ליתן לו שום פיוס על זה."],[4,"","ואם האדם אינו מתאמץ להמשיך ב\u0003פומיה\u0004, את ה\u0003פה דאליהו\u0004 על \u0003כרסייא\u0004 שלו \u0003לא שארי תמן\u0004. כי צריכים להמשיך אותו. ואין תימה איך אפשר ש\u0003פומיה דאליהו\u0004 יתקן יותר מ\u0003פה ה'\u0004, כי ז\"ס \u0003אשר ברא אלהים לעשות\u0004, כי השי\"ת התחיל הבריאה באופן שיכול האדם במע\"ט שלו לגמרה."],[5,"","רכו) \u0003ויברא אלקים את\u0004 וגו': ויברא אלקים את התנינים הגדולים. תנינים הם שנים, ואלו הם ערלה ופריעה, דהיינו כריתת הערלה, ואחר כך פריעה. והם זכר ונקבה. ואת כל נפש חיה הרומשת. זה הוא הרושם של אות ברית קדש, שהוא נפש חיה קדושה, כמו שאמרנו. אשר שרצו המים, היינו מים העליונים, שנמשכו אליו, לאות רושם הזה."],[5,"","פירוש. \u0003התנינים\u0004 הם לויתן ובת זוגו, וכנגדם הם \u0003ערלה ופריעה\u0004, שהם נחש בריח ונחש עקלתון, זכר ונקבה, כי \u0003ערלה\u0004 היא נחש בריח, זכר, שצריכין להעבירו ולהשליכו לעפר. ופריעה היא תיקון להעביר את רעת נחש העקלתון, שהיא הנקבה."],[5,"","והנה הכתוב, ואת כל החיה הרומשת, רומז על הרשימו דאות ברית קודש, כי ע\"י הפריעה שחוצים את עור \u0003הפריעה\u0004 לכאן ולכאן על היסוד, מתגלה הרשימו ד\u0003י'\u0004 שהיא בחינת סיומא דעלמא עלאה הנקרא \u0003חיה\u0004, (כנ\"ל אות י\"ז, ועי' לעיל אות רכ\"ד). וע\"כ נקרא \u0003רשימו דנפש חיה קדישא\u0004, שעליו אומר הכתוב \u0003ואת כל נפש החיה הרומשת\u0004."],[5,"","וז\"ש, \u0003מיין עלאין דאתמשכו לגבה דאת רשימו דא\u0004, היינו ה\u0003מיין\u0004 דוכרין דעלמא עלאה, או\"א עלאין הנקראים \u0003חיה\u0004, שהם נמשכים רק על רשימו ד\u0003י'\u0004 (כנ\"ל באות י\"ז) נפקת \u0003ה'\u0004 ואעלת \u0003י'\u0004 ע\"ש."],[6,"","רכז) \u0003ובגין דא אתרשימו\u0004 וכו': ומשום זה נרשמו ישראל ברושם קדוש וטהור למטה. כמו שהרשימות הקדושות שלמעלה, הם כדי להכיר בין צד קדוש לצד האחר, כך ישראל רשומים, כדי להכיר בין קדושת ישראל לעמים עכו\"ם הבאים מצד האחר. כמו שלמדנו. וכמו שרשם את ישראל, כך רשם את הבהמות והעופות שלהם, להבדיל ביניהם, לבין הבהמות והעופות של העמים עכו\"ם. אשרי חלקם של ישראל."],[6,"","פירוש. כן נרשמו בהמות ועופות שלהם, כי יחס האדם אל שאר הבריות שבעולם הוא כיחס הכלל אל הפרטים שלו, כי האדם כולל בגופו כל בריות העולם בכללא חדא, וכל בריה ובריה היא פרט אחד העומד בפני עצמו שנתפרט מצורת האדם. ולפיכך כמו שנבדלו ישראל מאומות העולם מבחינת האדם שבהם, הנה אותו החילוק נוהג ג\"כ בפרטים שלהם, שהם \u0003בעירי ועופי\u0004. ומה דנקט דוקא \u0003בעירי ועופי\u0004 הוא משום שהכתוב מזכיר אותם, אבל הוא הדין בשאר בריות הנפרטים מישראל ומאומות העולם."],[7,"","רכח) \u0003פקודא תמינאה\u0004 וכו': המצוה השמינית היא, לאהוב את הגר הבא להמול ולהכנס תחת כנפי השכינה. והיא, המלכות, מכנסת תחת כנפיה אותם המפרידים עצמם מצד האחר הטמא, ומתקרבים אליה, שכתוב, תוצא הארץ נפש חיה למינה."],[7,"","ענין כנפי השכינה הוא ענין ארוך ועמוק מאד, אבל אבארו לפי הצורך להבין המאמר שלפנינו. כי המלכות שהיא הנוקבא דז\"א נקראת \u0003שכינה\u0004 מבחינת הגילוי שאינה מסתלקת מאתנו, אפילו בזמן שאנחנו רחוקים ממנה ביותר בסוד \u0003בכל מקום שגלו שכינה עמהם\u0004 ובסוד \u0003השוכן אתם בתוך טומאותם\u0004. ומבחינה זו נקרא הז\"א \u0003שוכן\u0004 והנוקבא \u0003שכינה\u0004. ואין גילוי זה רק בזמן היות הזו\"ן פב\"פ בקומה שוה, כי אז הארת הזווג גדולה מאד עד שמתגלה היחוד גם על המקומות הרחוקים ביותר והמצומצמים ביותר."],[7,"","ונודע, שבנין הגדלות של זו\"ן אינו בא בבת אחת, אלא תחילה נבנה הקטנות דזו\"ן במוחין דו\"ק, ואח\"ז ממשיכין הגדלות, וזה נוהג בכל המדרגות של הזו\"ן. ולא עוד, אלא אפילו בעת שיש לו לזו\"ן מוחין דגדלות, אין המוחין דקטנות בטלים ח\"ו, כי גם הם צריכים לסייע אל הזווג של מוחין דגדלות, והם נקראים אז בשם \u0003כנפי השכינה\u0004."],[7,"","והסוה\"כ \u0003והיו הכרובים פורשי כנפים למעלה סככים בכנפיהם על הכפרת\u0004, (שמות כ\"ה) ועיקר תשמישם הוא לפרוש כנפיהם ולכסות על הארת הזווג דגדלות באופן שגם הרחוקים ביותר יוכלו לקבל מאור הזווג ולא יגיע עי\"ז משהו אל הקליפות. כי אותם שאינם בטהרה הגמורה נדחים תמיד מאור הקדושה מפחד שלא יעבירו השפע אל הקליפות, אמנם עתה ע\"י הכיסוי של הכנפים יש שמירה גדולה אל השפע, עד שאפילו הקרובים ביותר לקליפות, לא יוכלו להכשל ולהוריד השפע לקליפות, כי הכנפים מגינות עליהן."],[7,"","ולפיכך הבא להתגייר ולמול, מאחר שגופו בא מבחינת \u0003ערלה\u0004, שאבותיו לא עמדו על הר סיני ולא פסקה מהם זוהמת הנחש, מ\"מ יש לנו כח להעלותו לקדושה עליונה. דהיינו ע\"י העלאת מ\"ן לזווג הגדול דזו\"ן פב\"פ, ששם שולטים \u0003כנפי השכינה\u0004, שפורשים כנפיהם ומכסים על אור הזווג כנ\"ל, ואז אנו יכולים ג\"כ להעלות שמה נפש הגר, ומתקדש באור הזווג הזה,"],[7,"","ואע\"פ שאינו טהור לגמרי, יכול בעת הזה לקבל מהארת הזווג, כי הכנפים מגינים עליו שלא יעבור ח\"ו השפע אל הקליפות אע\"פ שהוא קרוב אליהן. ומה שאומר תחת כנפי השכינה, הוא משום שאינם יכולים לקבל רק מאור המלכות בלבד, ורק מהכנפים שלה, דהיינו חיצוניות המלכות, אבל לא מ\u0003גופא דשכינתא\u0004, ומכ\"ש מז\"א עצמו, כמ\"ש והולך."],[7,"","ואומר \u0003ואיהי אעילא לון תחות גדפהא\u0004 וכו'. ואין לשאול כי מקודם לכן אומר, \u0003ולעאלא תחות גדפוי דשכינתא\u0004, משמע שאנו צריכים להעלות הגר תחת כנפי השכינה וכאן אומר, \u0003ואיהי אעילא לון תחות גדפהא\u0004, משמע שהשכינה עצמה מעלה אותם אליה."],[7,"","והענין הוא, כי אי אפשר לקרב את נפש הגר, רק בעת זווג דגדלות, כי רק אז כנפי השכינה סוככים על הארת הזווג כנ\"ל, וע\"כ אנו צריכים מקודם להעלות מ\"ן לעורר הזווג דגדלות הזה, ולהמשיך הארת הזווג לנשמתנו, אשר אז השכינה פורשת כנפיה וסוככת על אור הזווג, ומכניסה אליה תחת כנפיה, את נפש הגר. ונמצא שמתחילה אנו מעלים את נפש הגר ע\"י המ\"ן שלנו, ואחר שעלה, השכינה מקבלתו תחת כנפיה."],[8,"","רכט) \u0003ואי תימא דהאי\u0004 וכו': ואם תאמר, שנפש חיה זו הכלולה בישראל, היא נועדת לכל. חזר ואמר, למינה. דהיינו לישראל ולא לגרים. כמה מסדרונות וחדרים זה לפנים מזה, יש לה לארץ הזו, שהיא נקראת חיה, תחת כנפיה."],[8,"","פירוש, נתבאר שאי אפשר להעלות את נפש הגר אלא בעת שאנו מעלים מ\"ן לזווג דגדלות ואנו ממשיכים לעצמנו הארת נשמה מהזווג הזה, אשר אז נוהגת פרישת כנפי השכינה ששם מתעלה נפש הגר, ומקבל גם הוא מאור הזווג כנ\"ל."],[8,"","ולזה אומר, \u0003ואי תימא דהאי נפש חיה דכלילא בישראל לכלא היא אזדמנת\u0004 שמא תאמר שגם הגר מקבל מאותו אור הזווג ד\u0003נפש חיה\u0004 שישראל המשיכו להארת נשמתם \u0003הדר ואמר למינה\u0004 שהגרים מקבלים מהארת הזווג השייך למין שלהם, דהיינו רק מבחינת החיצוניות של הזווג, ולא מפנימיות השייך רק לישראל."],[8,"","והנה כבר ידעת שה\u0003גדפין\u0004 הם בחינת הו\"ק מעת קטנות, המשמשים גם בעת הזווג דגדלות לכסות על אור הזווג. ובו\"ק יש חג\"ת נה\"י, והחג\"ת נקראים \u0003אדרין\u0004, שפירושו חדרים לשבת בהם. והנה\"י נקראים \u0003אכסדרין\u0004, שהם רק בית שער וכניסה אל החדרים, ובהם עצמם אין ענין לשבת שם, כי אינם משמשים אלא כניסה ויציאה בלבד."],[8,"","והטעם הוא כי עיקר החג\"ת הוא ת\"ת קו אמצעי שלהם, שהוא כלי גמור ובית קבול לאור חסדים. ועיקר נה\"י הוא יסוד קו אמצעי, שאין בו בית קבול לעצמו ולא כלום, ואינו משמש אלא אורחא למעברא ביה, וכן להעלות או\"ח, כנודע. וע\"כ נקראים הנה\"י בשם \u0003אכסדרין\u0004 לבד."],[8,"","ואומר \u0003כמה אכסדרין ואדרין\u0004 וכו' \u0003תחות גדפהא\u0004 כי צריכה להכניס \u0003תחות גדפהא\u0004 שלה גרים מע' אומות, וע\"כ מוכנים להם \u0003כמה אדרין\u0004 בחג\"ת ד\u0003גדפין\u0004, \u0003וכמה אכסדרין\u0004 בנה\"י ד\u0003גדפין\u0004. שבחינת נפשין מקבלים מ\u0003אכסדרין\u0004, ובחינת רוחין מ\u0003אדרין\u0004."],[9,"","רל) \u0003גדפא ימינא אית\u0004 וכו': הכנף הימנית, של המלכות, יש לה שני מסדרונות, שהם מתחלקים מכנף זו לשתי אומות אחרות, הקרובות לישראל ביחוד, להכניסם לתוך אלו המסדרונות. ותחת הכנף השמאלית יש שני מסדרונות אחרים, שמתחלקים לשתי אומות אחרות, שהם עמון ומואב. וכולם נקראים נפש חיה."],[9,"","פירוש. הנה מקודם לכן אומר, שיש \u0003כמה אכסדרין\u0004, וכאן אומר רק ב' ב\u0003ימינא\u0004 וב' ב\u0003שמאלא\u0004, הענין הוא כי כאן מדבר רק על הכוללים לבד, שיש \u0003תרין אכסדרין\u0004 בימין כוללים לבחינת האומות השייכות לימין, וכן יש ב' \u0003אכסדרין\u0004 כוללים בשמאל לאומות השייכות לשמאל."],[9,"","ואומר שיש \u0003ב' אומות\u0004 מסטרא דימינא כוללות לכל האומות שמסטרא דימין, שהן מתיחסות ל\u0003ב' אכסדרין\u0004 הכוללים שב\u0003גדפא ימינא\u0004, ולא פירש הזוהר מי הם. וכן יש ב' אומות מסטרא דשמאלא כוללות לכל האומות שמסטרא דשמאלא, שהן \u0003עמון ומואב\u0004, והן מתיחסות ל\u0003ב' אכסדרין\u0004 הכוללים שב\u0003גדפא שמאלא\u0004."],[9,"","וז\"ש, \u0003וכלהון אקרון נפש חיה\u0004, כל נפשות הגרים הבאות מכל האומות נקראות בשם \u0003נפש חיה\u0004. וזה משום שאינם יכולים לקבל רק מזווג דגדלות דזו\"ן, שאז הזו\"ן הם במקום או\"א עלאין, ואז נקראת המלכות \u0003נפש חיה\u0004, מטעם היות בה מאור או\"א שהוא \u0003אור חיה\u0004. וכיון שנפשות הגרים מקבלות מה\u0003גדפין\u0004 ד\u0003נפש חיה\u0004, נקראות גם הן \u0003נפש חיה\u0004."],[10,"","רלא) \u0003וכמה אדרין סתימין\u0004 וכו': וכמה חדרים סתומים אחרים, והיכלות אחרים, בכל כנף וכנף. ומהם יוצאים רוחות, להתחלק לכל אלו הגרים המתגיירים, ונקראים נפש חיה. אבל למינה. וכולם נכנסים תחת כנפי השכינה, ולא יותר."],[10,"","פירוש, כי כל \u0003גדפא\u0004 כלול מו\"ק שהם חג\"ת נה\"י, הנקראים \u0003אדרין\u0004 ו\u0003אכסדרין\u0004, אשר לכל אומה ואומה חדר מיוחד בחג\"ת, ו\u0003אכסדרא\u0004 מיוחדת בנה\"י, שמ\u0003אכסדרין\u0004 מקבלת כל אחת בחינת \u0003נפש\u0004, ו\u0003מאדרין\u0004 מקבלת כל אחת בחינת רוח. ומה שאומר \u0003אדרין סתימין\u0004, הוא משום שהחג\"ת דו\"ק הם בחינת חסדים מכוסים, שהם \u0003סתימין\u0004 מהארת חכמה, כנודע, וע\"כ מכנה אותם בשם \u0003סתימין\u0004."],[11,"","רלב) \u0003אבל נשמתא דישראל\u0004 וכו': אבל הנשמה של ישראל יוצאת מתוך גופו של אותו האילן, שהוא ז\"א, ומשם נשמות עפות לתוך ארץ הזו, שהיא המלכות, לתוך מעיה לפני ולפנים. והסוד הוא, כי תהיו אתם ארץ חפץ. (מלאכי ג') ועל כן ישראל, הוא, בן יקיר שמעיה המו עליו, ונקראים העמוסים מני בטן ולא מן הכנפים, שהן לחוץ מגוף. ועוד, הגרים אין להם חלק באילן העליון, שהוא ז\"א, וכל שכן בגוף שלו, אבל חלקם הוא בכנפים של המלכות, ולא יותר. והגר הוא תחת כנפי השכינה, ולא יותר. גרי הצדק הם אותם השורים ומתאחזים שם, ולא בפנים, כאמור. ומשום זה, כתוב, תוצא הארץ נפש חיה למינה. ולמי. בהמה ורמש וחיתו ארץ למינה. הכל שואבים נפש מאותה החיה, אבל כל אחד למינו כראוי לו."],[11,"","פירוש, הז\"א נקרא \u0003אילנא\u0004 דהיינו עץ החיים, והנוקבא נקראת ארץ החיים, דהיינו בעת הגדלות, בזמן שהם מלבישין לאו\"א עלאין, שהם מוחין דחיה. ואומר \u0003נשמתא דישראל נפקא מגו גופא דההוא אילנא\u0004 היינו מבחינת פנימיות ז\"א, \u0003ומתמן פרחין נשמתין לגו האי ארץ גו מעהא לגו לגו\u0004, שע\"י זווג \u0003דההוא אילנא\u0004 שהוא ז\"א, \u0003בארץ\u0004 החיים שהיא הנוקבא, הז\"א משפיע \u0003נשמות ישראל\u0004 לנוקבא אל פנימיות פנימיותה, וממנה מקבלים \u0003ישראל\u0004 הנשמה שלהם, ולא כגרים שאינם מקבלים רק מהנוקבא לבדה, ורק מהחיצוניות של הנוקבא מה\u0003גדפין\u0004 שלה, ולא מן \u0003לגו לגו\u0004, שפירושו פנימי פנימיות."],[11,"","והענין הוא, כי הנוקבא יש לה ג' פרצופין מלובשין זה בתוך זה, הנקראים עיבור, יניקה, מוחין, שפרצוף המוחין מלובש תוך פרצוף היניקה, ופרצוף היניקה מלובש תוך פרצוף העיבור, ודייק ש\u0003ישראל\u0004 מקבלים מפנימי דפנימי של הנוקבא, דהיינו מפרצוף המוחין."],[11,"","וז\"ש, \u0003בן יקיר\u0004 וכו', וע\"כ נקראים ישראל בן יקיר, שהמו מעיה לו, ונקראים העמוסים מני בטן, ולא מהכנפים שהן חיצוניות שלה, פירוש, הנה\"י דנוקבא מכונים בשם \u0003בטן\u0004, מפאת ששם מקום העיבור והגידול של נשמות ישראל, אמנם אין המדובר בבחינת נה\"י של ב' הפרצופין החיצונים הנקראים עיבור ויניקה, שהם בחינת \u0003גדפין\u0004, אלא המדובר הוא בנה\"י של פרצוף המוחין, שהם בחינת בני מעים,"],[11,"","וז\"ס הכתוב \u0003הבן יקיר לי אפרים אם ילד שעשועים כי מדי דברי בו זכור אזכרנו עוד על כן המו מעי לו\u0004 וגו' (ירמיה ל\"א), שמתוך שנשמות ישראל הן מפנימיות המלכות הנקראת בני מעים, ע\"כ אומר \u0003המו מעי לו\u0004, וע\"כ קורא אותן הכתוב \u0003העמוסים מני בטן\u0004. שכל אלו הן בחינת נה\"י דפרצוף המוחין, ולא \u0003מגדפין דלבר\u0004, ולא מנה\"י דב' פרצופין החיצונים שהן בחינת \u0003גדפין\u0004."],[11,"","וז\"ש, \u0003ותו גיורין לית\u0004 וכו', ועוד, כי הגרים אין להם חלק באילן העליון, ומכ\"ש בגוף שלו. אלא חלקם הוא רק בכנפים ולא יותר, והיינו רק מתחת \u0003כנפי\u0004 השכינה ולא יותר, ולכן נקראים גירי צדק כי השכינה נקראת צדק, ותחת כנפיה הם שוכנים, ובה הם מתייחדים, ואין להם חלק מלמעלה, מהשכינה."],[11,"","וז\"ש, \u0003ולמאן בהמה ורמש וחיתו ארץ\u0004 וכו': כל מי שיש לו \u0003נפש\u0004 מבחינת \u0003בהמה ורמש וחיתו ארץ\u0004, מקבל אותה רק \u0003מנפש דההיא חיה\u0004, שהיא המלכות בזווג דגדלות פב\"פ עם הז\"א, ועם כל זה \u0003כל חד למינה כדקא חזי לה\u0004 דהיינו רק מבחינת ה\u0003גדפין\u0004, ולא מפנימיות של הארת הזווג הגדול הזה."]],[[0,"","אָמַר רַבִּי שִׁמְעוֹן חֲמִשָּׁה, שֶׁכָּתוּב יוֹתֵר, וַיְחֻנֶּנּוּ וַיֹּאמֶר. וַיְחֻנֶּנּוּ - אֶחָד. וַיֹּאמֶר - שְׁנַיִם. אָמַר לוֹ, לֹא כָּכָה, אֶלָּא וַיְחֻנֶּנּוּ זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ, שֶׁהֲרֵי אֵין רְשׁוּת לְאַחֵר אֶלָּא לוֹ. אָמַר לוֹ, יָפֶה אָמַרְתָּ."],[1,"","וּמִי שֶׁנִּמְנָע מִפְּרִיָּה וּרְבִיָּה, כִּכְיָכוֹל מַמְעִיט אֶת הַדְּמוּת שֶׁכּוֹלֶלֶת אֶת כָּל הַדְּמֻיּוֹת, וְגוֹרֵם לְאוֹתוֹ הַנָּהָר שֶׁאֵין שׁוֹפְעִים מֵימָיו, וּפוֹגֵם אֶת הַבְּרִית הַקָּדוֹשׁ בְּכָל הַצְּדָדִים, וְעָלָיו כָּתוּב (ישעיה סו) וְיָצְאוּ וְרָאוּ בְּפִגְרֵי הָאֲנָשִׁים הַפֹּשְׁעִים בִּי. בִּי וַדַּאי זֶה לַגּוּף, וְאֵין נִשְׁמָתוֹ נִכְנֶסֶת לַפַּרְגּוֹד כְּלָל, וְהוּא נִטְרָד מֵאוֹתוֹ הָעוֹלָם."],[2,"","מִצְוָה שְׁבִיעִית - לָמוּל לִשְׁמֹנָה יָמִים וּלְהַעֲבִיר אֶת זֻהֲמַת הָעָרְלָה, מִשּׁוּם שֶׁהַחַיָּה הַהִיא הִיא הַדַּרְגָּה הַשְּׁמִינִית לְכָל הַדְּרָגוֹת, וְהַנֶּפֶשׁ הַהִיא שֶׁפּוֹרַחַת מִמֶּנָּה צְרִיכָה לְהֵרָאוֹת לְפָנֶיהָ לִשְׁמֹנָה יָמִים כְּמוֹ שֶׁהִיא דַרְגָּה שְׁמִינִית."],[3,"","וְאָז וַדַּאי נִרְאֶה שֶׁהִיא נֶפֶשׁ חַיָּה. הַנֶּפֶשׁ שֶׁל הַחַיָּה הַהִיא הַקְּדוֹשָׁה, וְלֹא מִן הַצַּד הָאַחֵר. וְזֶהוּ יִשְׁרְצוּ הַמַּיִם. בְּסִפְרוֹ שֶׁל חֲנוֹךְ יֵרָשְׁמוּ הַמַּיִם שֶׁל זֶרַע קֹדֶשׁ רֹשֶׁם שֶׁל נֶפֶשׁ חַיָּה. וְזֶה הָרֹשֶׁם שֶׁל הָאוֹת יוֹ\"ד שֶׁנִּרְשָׁם בִּבְשַׂר הַקֹּדֶשׁ מִכָּל שְׁאָר הָרִשּׁוּמִים שֶׁל הָעוֹלָם."],[4,"","וְעוֹף יְעוֹפֵף עַל הָאָרֶץ - זֶה אֵלִיָּהוּ שֶׁטָּס אֶת כָּל הָעוֹלָם בְּאַרְבַּע טִיסוֹת לִהְיוֹת שָׁם בְּאוֹתָהּ הַמִּילָה שֶׁל בְּרִית הַקֹּדֶשׁ. וְצָרִיךְ לְסַדֵּר לוֹ כִּסֵּא, וּלְהַזְכִּיר בְּפִיו: זֶה הַכִּסֵּא שֶׁל אֵלִיָּה\"וּ. וְאִם לֹא - אֵינוֹ שׁוֹרֶה שָׁם."],[5,"","וַיִּבְרָא אֱלֹהִים אֶת הַתַּנִּינִם הַגְּדלִים - שְׁנֵי אֵלֶּה עָרְלָה וּפְרִיעָה. הַמִּילָה שֶׁל הָעָרְלָה, וְאַחַר כָּךְ הַפְּרִיעָה. וְהֵם זָכָר וּנְקֵבָה. וְאֵת כָּל נֶפֶשׁ הַחַיָּה הָרֹמֶשֶׂת - זֶה הָרֹשֶׁם שֶׁל אוֹת בְּרִית הַקֹּדֶשׁ, שֶׁהִיא הַנֶּפֶשׁ חַיָּה הַקְּדוֹשָׁה כְּפִי שֶׁאָמַרְנוּ. אֲשֶׁר שָׁרְצוּ הַמַּיִם - הַמַּיִם הָעֶלְיוֹנִים שֶׁנִּמְשְׁכוּ אֵלֶיהָ שֶׁל אוֹת הָרֹשֶׁם הַזּוֹ."],[6,"","וּבִגְלַל זֶה נִרְשְׁמוּ יִשְׂרָאֵל בְּרֹשֶׁם קָדוֹשׁ וְטָהוֹר לְמַטָּה. כְּדֻגְמַת אוֹתָם רְשׁוּמִים קְדוֹשִׁים, לְהַכִּיר בֵּין צַד הַקְּדֻשָּׁה לַצַּד הָאַחֵר שֶׁל הַטֻּמְאָה, אַף יִשְׂרָאֵל רְשׁוּמִים לְהַכִּיר בֵּין צַד הַקְּדֻשָּׁה לְעַמִּים עַכּוּ\"ם, שֶׁבָּאִים מִצַּד הָאַחֵר שֶׁל טֻמְאָה, כְּמוֹ שֶׁנִּתְבָּאֵר. וּכְמוֹ שֶׁרוֹשֵׁם אוֹתָם, כָּךְ רוֹשֵׁם הַבְּהֵמוֹת וְהָעוֹפוֹת שֶׁלָּהֶם לִבְהֵמוֹת וְעוֹפוֹת שֶׁל הָעַמִּים עַכּוּ\"ם. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל."],[7,"","מִצְוָה שְׁמִינִית - לֶאֱהֹב אֶת הַגֵּר שֶׁנִּכְנָס לָמוּל אֶת עַצְמוֹ וּלְהִכָּנֵס תַּחַת כַּנְפֵי הַשְּׁכִינָה. וְהִיא מַכְנִיסָה אוֹתָם תַּחַת כְּנָפֶיהָ לְאוֹתָם שֶׁנִּפְרָדִים מִצַּד הַטֻּמְאָה הָאַחֵר וּמִתְקָרְבִים אֵלֶיהָ, שֶׁכָּתוּב תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ."],[8,"","וְאִם תֹּאמַר שֶׁנֶּפֶשׁ הַחַיָּה הַזּוֹ שֶׁכְּלוּלָה בְּיִשְׂרָאֵל הִיא מְזֻמֶּנֶת לַכֹּל - חָזַר וְאָמַר לְמִינָהּ. כַּמָּה אַכְסַדְרָאוֹת וַחֲדָרִים זֶה לִפְנִים מִזֶּה יֵשׁ לָאָרֶץ הַזּוֹ שֶׁהִיא חַיָּה. תַּחַת כְּנָפֶיהָ."],[9,"","כָּנָף יָמִין, יֵשׁ לָהּ שְׁתֵּי אַכְסַדְרָאוֹת. וּמֵהַכָּנָף הַזּוֹ נִפְרָדִים לִשְׁתֵּי אֻמּוֹת אֲחֵרוֹת שֶׁהֵן קְרוֹבוֹת בְּיִחוּד לְיִשְׂרָאֵל לְהַכְנִיסָם לְתוֹךְ הָאַכְסַדְרָאוֹת הַלָּלוּ. וְתַחַת כָּנָף שְׂמֹאל יֵשׁ שְׁתֵּי אַכְסַדְרָאוֹת אֲחֵרוֹת, וְנִפְרָדִים לִשְׁתֵּי אֻמּוֹת אֲחֵרוֹת, שֶׁהֵם עַמּוֹן וּמוֹאָב. וְכֻלָּם נִקְרָאִים נֶפֶשׁ חַיָּה."],[10,"","וְכַמָּה חֲדָרִים סְתוּמִים אֲחֵרִים וְהֵיכָלוֹת אֲחֵרִים בְּכָל כָּנָף וְכָנָף, וּמֵהֶם יוֹצְאוֹת רוּחוֹת לְהַפְרִיד לְכָל אוֹתָם הַגֵּרִים שֶׁמִּתְגַּיְּרִים, וְנִקְרָאִים נֶפֶשׁ חַיָּה, אֲבָל לְמִינָהּ. וְכֻלָּם נִכְנָסִים תַּחַת כַּנְפֵי הַשְּׁכִינָה וְלֹא יוֹתֵר."],[11,"","אֲבָל נִשְׁמַת יִשְׂרָאֵל יוֹצֵאת מִתּוֹךְ הַגּוּף שֶׁל הָאִילָן הַהוּא, וּמִשָּׁם פּוֹרְחוֹת הַנְּשָׁמוֹת לְתוֹךְ הָאָרֶץ הַזּוֹ לְתוֹךְ מֵעֶיהָ לִפְנַי וְלִפְנִים, וְהַסּוֹד - (מלאכי ג) כִּי תִהְיוּ אַתֶּם אֶרֶץ חֵפֶץ. וְעַל זֶה יִשְׂרָאֵל בֵּן יַקִּיר שֶׁהָמוּ מֵעֶיהָ עָלָיו, וְנִקְרָאִים (ישעיה מו) הָעֲמֻסִים מִנִּי בֶטֶן, וְלֹא מֵהַכְּנָפַיִם הַחוּצָה. וְעוֹד, לַגֵּרִים אֵין חֵלֶק בָּאִילָן הָעֶלְיוֹן, וְכָל שֶׁכֵּן בַּגּוּף שֶׁלּוֹ. אֲבָל הַחֵלֶק שֶׁלָּהֶם הוּא בַּכְּנָפַיִם וְלֹא יוֹתֵר, וְהַגֵּר תַּחַת כַּנְפֵי הַשְּׁכִינָה וְלֹא יוֹתֵר. גֵּרֵי הַצֶּדֶק הֵם שֶׁשּׁוֹרִים שָׁם וְנֶאֱחָזִים, וְלֹא לִפְנִים, כְּמוֹ שֶׁנִּתְבָּאֵר. וּמִשּׁוּם כָּךְ תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ. וּלְמִי בְּהֵמָה וָרֶמֶשׂ וְחַיְתוֹ אֶרֶץ לְמִינָהּ. כֻּלָּם שׁוֹאֲבִים נֶפֶשׁ מֵהַחַיָּה הַהִיא, אֲבָל כָּל אֶחָד לְמִינָהּ כָּרָאוּי לָהּ."]]],[["פִּקּוּדָא תְּשִׁיעָאָה לְמֵיחַן לְמִסְכְּנֵי וּלְמֵיהַב לוֹן טַרְפָּא. דִּכְתִיב נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ. נַעֲשֶׂה אָדָ\"ם, מְשׁוּתָּפָא כְּלַל דְּכַר וְנוּקְבָא. בְּצַלְמֵנוּ, עֲתִירֵי. כִּדְמוּתֵנוּ, מִסְכְּנֵי.","דְּהָא מִסִּטְרָא דִּדְכוּרָא עֲתִירֵי, וּמִסִּטְרָא דְּנוּקְבָא מִסְכְּנֵי. כְּמָה דְאִנּוּן בְּשׁוּתְּפָא חֲדָא. וְחָס דָּא עַל דָּא, וְיָהִיב דָּא לְדָא וְגָמִיל לֵיהּ טִיבוּ, הָכִי אִצְטְרִיךְ בַּר נָשׁ לְתַתָּא לְמֶהֱוֵי עֲתִירָא וּמִסְכְּנָא בְּחִבּוּרָא חֲדָא, וּלְמֵיהַב דָּא לְדָא וּלְגָמְלָאָה טוּבָא דָּא לְדָא.","וְיִרְדוּ בִדְגַת הַיָּם וְגו' רָזָא דְנָן חֲמֵינָן בְּסִפְרָא דִּשְׁלֹמֹה מַלְכָּא, דְּכָל מָאן דְחָס עַל מִסְכְּנֵי בִּרְעוּתָא דְלִבָּא, לָא מִשְׁתַּנִי דִיוּקְנֵיהּ לְעָלָם מִדִּיּוֹקְנָא דְּאָדָם הָרִאשׁוֹן. וְכֵיוָן דְּדִיוֹקְנָא דְּאָדָ\"ם אִתְרְשִׁים בֵּיהּ, שַׁלִּיט עַל כָּל בְּרִיָּין דְּעָלְמָא בְּהַהוּא דִּיוּקְנָא. הֲדָא הוּא דִכְתִיב, (בראשית ט׳:ב׳) וּמוֹרַאֲכֶם וְחִתְּכֶם יִהְיֶה עַל כָּל חַיַּת הָאָרֶץ וְגו' כֻּלְהוּ זָעִין וְדָחֲלִין מֵהַהוּא דִיוּקְנָא דְּאִתְרְשִׁים בֵּיהּ, בְּגִין דְּדָא הוּא פִּקּוּדָא מַעַלְיָא לְאִסְתַּלָּקָא בַּר נָשׁ בְּדִיוֹקְנֵיהּ דְּאָדָם עַל כָּל שְׁאָר פִּקּוּדִין.","מְנָא לָן מִנְבוּכַדְנֶצַר (חייבא). אַף עַל גַּב דְּחָלַם הַהוּא חֶלְמָא, כָּל זִמְנָא דְּהֲוָה מֵיחַן לְמִסְכְּנֵי לָא שָׁרָא עֲלֵיהּ חֶלְמֵיהּ. כֵּיוָן דְּאַטִיל עֵינָא בִישָׁא דְּלָא לְמֵיחַן לְמִסְכְּנֵי, מַה כְּתִיב, (דניאל ד׳:כ״ח) עוֹד מִלְּתָא בְּפוּם מַלְכָּא וְגו', מִיָּד אִשְׁתְּנֵי דִּיוּקְנֵיהּ וְאַטְרִיד מִן בְּנֵי נְשָׁא. וּבְגִין כָּךְ נַעֲשֶׂה אָדָם. כְּתִיב הָכָא עֲשִׂיָה, וּכְתִיב הָתָם (רות ב׳:י״ט) שֵׁם הָאִישׁ אֲשֶׁר עָשִׂיתִי עִמּוֹ הַיּוֹם בּוֹעַז.","פִּקּוּדָא עֲשִׂירָאָה לְאֲנָחָא תְּפִלִּין וּלְאַשְׁלָמָא גַרְמֵיהּ בְּדִיּוּקְנָא עִלָּאָה. דִּכְתִיב, (בראשית א׳:כ״ז) וַיִּבְרָא אֱלהִים אֶת הָאָדָם בְּצַלְמוֹ. פָּתַח וְאָמַר (שיר השירים ז׳:ו׳) רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל הַאי קְרָא אוֹקִימְנָא וְאִתְּמַר. אֲבָל רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל, דָּא רֵישָׁא עִלָּאָה תְּפִלִּין דְּרֵישָׁא, שְׁמָא דְמַלְכָּא עִלָאָה קַדִּישָׁא ידוד בְּאָתְוָון רְשִׁימִין, כָּל אָת וְאָת פַּרְשָׁתָא חָדָא, שְׁמָא קַדִּישָׁא גְּלִיפָא בְּסִדּוּרָא דְּאָתְוָון כְּדְקָא יְאוּת. וּתְנַן (דברים כ״ח:י׳) כִּי שֵׁם ה' נִקְרָא עָלֶיךָ וְיָרְאוּ מִמֶּךָּ, אִלֵּין תְּפִלִּין דְּרֵישָׁא, דְּאִנּוּן שְׁמָא קַדִּישָׁא בְּסִדּוּרָא דְּאָתְווֹי.","פַּרְשְׁתָא קַדְמָאָה (שמות י״ג:ב׳) קַדֶּשׁ לִי כָל בְּכֹר. דָּא י דְּאִיהִי קֹדֶשׁ. בּוּכְרָא דְּכָל קוּדְשִׁין עִלָּאִין. פֶּטֶר כָּל רֶחֶם, בְּהַהוּא שְׁבִיל דַּקִּיק דְּנָחַת מִן יוּ\"ד דְּאִיהוּ אַפְתַּח רַחֲמָא (רחמה) לְמֶעְבַּד פֵּירִין וְאִבִּין כְּדְקָא יָאוֹת. וְאִיהוּ קֹדֶשׁ עִלָּאָה.","פַּרְשְׁתָא תִּנְיָינָא (שמות יג) וְהָיָה כִי יְבִיאֲךָ. דָּא ה הֵיכָלָא. דְּאִתְפַּתַּח רַחֲמָא (רחמה) דִילָהּ מִגּוֹ יוּ\"ד בְּחַמְשִׁין פִּתְחִין אַכְּסַדְּרָאִין וְאִדְּרִין סְתִימִין דְּבֵיהּ. דְּהַהוּא פֶּטֶר דְּעֲבִיד יו\"ד בְּהַאי הֵיכָלָא לְמִשְׁמַע בָּהּ קָלָא דִי נָפְקָא מִגּוֹ שׁוֹפָר דָּא. בְּגִין דְּשׁוֹפָר דָּא הוּא סָתִים בְּכָל סִטְרִין, וְאָתָא יוּ\"ד וּפְתַח לֵיהּ לְאַפָּקָא מִינֵּיהּ קָלָא. וְכֵיוָן דְּאַפְתַּח לֵיהּ תָּקַע לֵיהּ וְאַפִּיק מִנֵּיהּ קָלָא לְאַפָּקָא עַבְדִין לְחֵירוּ.","וּבִתְקִיעוּ דְשׁוֹפָרָא דָא נָפְקוּ יִשְׂרָאֵל מִמִּצְרָיִם. וְכָךְ זָמִּין זִימְנָא אָחֳרָא לְסוֹף יוֹמַיָא. וְכָל פּוּרְקָנָא מֵהַאי שׁוֹפָר אַתְיָא. וּבְגִין כָּךְ אִית בָּהּ יְצִיאַת מִצְרַיִם בְּפַרְשָׁתָא דָא. דְּהָא מֵהַאי שׁוֹפָר אָתֵי בְּחֵילָא דְּיוּ\"ד דְּפָתַח רַחֲמָא דִּילָהּ וְאַפִּיק קָלֵיהּ לְפוּרְקָנָא דְעַבְדִין. וְדָא ה אָת תִּנְיָינָא דִּשְׁמָא קַדִּישָׁא.","פַּרְשְׁתָא תְּלִיתָאָה רָזָא דְיִחוּדָא (דברים ו) דִּשְׁמַע יִשְׂרָאֵל. דָּא וָא\"ו דְּכָלִיל כֹּלָּא, וּבֵיהּ יִחוּדָא דְכֹלָּא. וּבֵיהּ אִתְיַיחֲדָן וְהוּא נָטִיל כֹּלָּא. פַּרְשְׁתָא רְבִיעָאָה (דברים ה) וְהָיָה אִם שָׁמוֹעַ, כְּלִילוּ דִּתְרֵין סִטְרִין דְּאִתְאַחֲדַת בְּהוּ כְּנֶסֶת יִשְׂרָאֵל גְּבוּרָה דִּלְתַתָּא. וְדָא ה בַּתְרָאָה דְּנָטְלָא לוֹן וְאִתְכְּלֵילַת מִנְּהוֹן."],[[0,"","רלג) \u0003פקודא תשיעאה\u0004 וכו': המצוה התשיעית היא, לחון את העניים, ולתת להם טרף. שכתוב, נעשה אדם בצלמנו כדמותנו. נעשה אדם הוא בשיתוף, מפני שהוא כולל זכר ונקבה. בצלמנו, היינו עשירים. כדמותנו, היינו העניים."],[1,"","רלד) \u0003דהא מסטרא דדכורא\u0004 וכו': כי מצד הזכר הם העשירים. ומצד הנקבה הם העניים. וכמו שהם בחיבור אחד, וחסים זה על זה, ונותנים זה לזה, וגומלים לו חסד. כך האדם למטה צריך להיות, העשיר והעני בחבור אחד, שיתנו זה לזה ויגמלו חסד זה עם זה."],[2,"","רלה) \u0003וירדו בדגת הים\u0004 וגו': סוד זה ראינו בספרו של שלמה המלך. שכל מי שמרחם על העני בחפץ לב, אין צורתו משתנה מצורת אדם הראשון, לעולם. וכיון שנרשמה בו צורת אדם, הוא שולט על כל בריות העולם על ידי צורה ההיא. ז\"ש, ומוראכם וחתכם יהיה על כל חית הארץ וגו'. כולם זעים ומפחדים מאותה הצורה שנרשמה בו. כיון שמצוה זו, לחון את העניים, היא מצוה משובחת על כל שאר המצות, להתעלות בן אדם, בצורתו של אדם הראשון."],[3,"","רלו) \u0003מנלן מנבוכדנצר\u0004 וכו': מאין לנו זה. מנבוכדנצר, אע\"פ שחלם אותו החלום, כל זמן שהיה חונן עניים לא נתקיים בו החלום. כיון שהטיל עין רעה שלא לחון את העניים, מה כתוב, עוד מלתא בפום מלכא וגו'. מיד נשתנתה צורתו, ונרחק מן בני אדם. ומשום זה כתוב, \u0003נעשה\u0004 אדם. כתוב כאן עשיה, וכתוב שם שם האיש אשר \u0003עשיתי\u0004 עמו היום בועז, שעשיתי פירושו צדקה, אף כאן נעשה, פירושו צדקה."],[3,"","ביאור המאמר, יש להבין הדברים, אם אמנם מבואר בכתוב בריאת \u0003דכר ונוקבא\u0004 דהיינו \u0003עתירי ומסכני\u0004, אבל אין כאן רמז כלל שה\u0003עתירי\u0004 צריכים לרחם על \u0003מסכני\u0004 ולפרנסם, כי אומר שהמקרא הזה הוא \u0003פקודא למיחן למסכני\u0004 וכו'. אכן יש כאן עמקות גדולה מאד. כי משונה מאמר זה מכל המאמרים הקודמים, כי בכולם תמצא מאמר לחוד ועשיה לחוד, כמו \u0003ויאמר אלהים יהי אור, ויהי אור. ויאמר אלהים יהי רקיע\u0004 וגו' \u0003ויעש אלהים את הרקיע\u0004. וכן \u0003ויאמר אלהים יקוו המים\u0004 וגו' \u0003ויהי כן\u0004."],[3,"","וכן בכולם לא תמצא שהעשיה תהיה מעורבת במאמר, והטעם (כמ\"ש הזהר להלן), שהבריאה יצאה בסוד או\"א, שאבא אמר ואמא עושה. שאבא השפיע השפע לאמא ואחר שהשפע נתרשם בגבולים שבאמא יצא השפע לפועל, ודומה כמו כח ופועל, כי מבחינת אבא לבד לא יכולה שום בריאה לצאת אל הפועל ממש, משום שאין בה שום גבול שיציירו הפעולות באיזו צורה שהיא, כנודע, ולפיכך יש מאמר מאבא, שה\"ס ההשפעה לאמא, וכיון שעודו בבחינת ה\u0003כח\u0004 לא יתכן שיאמר בו לשון \u0003עשיה\u0004, אלא לשון \u0003יהי\u0004. אבל במאמר דבריאת אדם כתיב במאמר עצמו לשון \u0003עשיה\u0004, שהרי כתיב \u0003ויאמר אלהים נעשה אדם\u0004. ועוד שינוי גדול יש כאן, כי כתיב \u0003נעשה\u0004 לשון רבים, ולא כתיב \u0003אעשה אדם\u0004."],[3,"","והענין הוא כי קודם בריאת עולם התיקון היה שבירת הכלים בז\"ת דעולם הנקודים, כמ\"ש ז\"ל ברא עולמות והחריבן עד שברא עולם זה ואמר דין הניין לי. (ב\"ר פ\"ג ז') והנה ע\"י שבירת הכלים שהיתה בז\"ס חג\"ת נהי\"ם דנקודים, נתערבה הקדושה בקליפות, ואח\"כ נתגלה השם \u0003מ\"ה\u0004 והוציא ד' העולמות אבי\"ע בדרך התיקון שז\"ס שאמר דין הניין לי, כי בירר את הנצוצין קדישין מן הקליפות וכפי הבירור של הקדושה כן נבראו העולמות וכל מה שבהם."],[3,"","וז\"ס מה שתמצא בכל מעשה בראשית ענין הבדלה ובירורים, כמו ויבדל אלהים בין האור ובין החושך, וכן בין מים למים, וכן בין מים ליבשה, וכן ענין למינהו הנאמר בתדשא הארץ דשא וכו', וכן בין ממשלת היום ובין ממשלת לילה, וכן ענין יציאת נפש חיה מן המים ומן הארץ"],[3,"","שכל זה יורה ענין בירור הקדושה מן הקליפות והטוב מהרע, וכל מה שנברר נעשה לבחינת מציאות קיימת לפי הראוי לו בקדושה. וז\"ס שכל מעשה בראשית כלול ביום הראשון במאמר ד\u0003יהי אור\u0004, כי שם היתה הבדלה כוללת בין האור ובין החושך, כי בדרך כלל נקראת הקדושה \u0003אור\u0004 והקליפות \u0003חושך\u0004, כי כל שאר התוארים של הקדושה והקליפות, אינם אל פרטים וענפים של \u0003אור\u0004 ו\u0003חושך\u0004."],[3,"","והנה מבחינה זו של הבדלה בין האור ובין החושך, שעל פיה נתבררו כל בריות בראשית, עדיין אין התיקון שלם, כי מבחינה זו היתה נשארת כל בחינת הרע והחושך כדבר שאין צורך בו, שאין זה מותאם כלל לשלימותו ית', כי אין התיקון נגמר אלא בסוד הכתוב גם חשך לא יחשיך ממך וגו' כחשיכה כאורה (תהלים קל\"א). וכדי לתקן זה נברא ה\u0003אדם\u0004, שהוא כולל הכל, מתכלית הרע עד תכלית הטוב, ויהיה על ידו גמר התיקון בשלימות הנרצית, דהיינו שיהפוך הרע להיות טוב והמר למתוק וחשך כאור תהיה ובלע המות לנצח, והיה ה' למלך על כל הארץ."],[3,"","ולפיכך יצא מאמר זה דבריאת האדם בשינוי גדול משאר המאמרות, שהיו לשאר בריות בראשית, כי כאן נתערבה העשיה במאמר עצמו, והוא משום שמאמר זה הוא מאמא ולא מאבא, ואמרה \u0003נעשה אדם\u0004, שיורה לשון משותפת, כי היא נשתתפה עם המלכות דאצילות כדי לברוא את האדם. פירוש, כי המלכות דאצילות כוללת הכל בסוד הכתוב ומלכותו בכל משלה, כי היא מפרנסת ונותנת קיום גם לכחות הרע, שלולא כן לא היה לרע שום כח להמצא. שז\"ס ורגליה יורדת מות, כי הקליפות מקבלות ממנה נהירו דקיק כדי קיומם, שז\"ס שהמלכות נקראת עשיה, להיותה מתפשטת ושולטת בכל העשיה כולה, וכן נקראת חושך כי היא מאירה נהירו דקיק כדי לקיים החושך והרע, כנ\"ל."],[3,"","ועל פי זה תבין שבעת שאמא נכללה בעצמה במלכות בשתופא חדא, נתערבה בה עצמה בחינת עשיה וחושך. וז\"ס \u0003נעשה אדם בצלמנו כדמותנו\u0004, כי ה\u0003אור\u0004 נקרא \u0003צלם\u0004, ו\u0003החושך\u0004 נקרא \u0003דמות\u0004 (כמ\"ש בזהר להלן). כי אחר שאמא נשתתפה במלכות נעשו בה עצמה ב' הכוחות \u0003צלם ודמות\u0004, אשר על פיהם בראה את האדם שיהיה כולל גם הוא מב' הכחות צלם ודמות, וע\"כ \u0003אמרה בצלמנו וכדמותנו\u0004. ואחר שידעת כל זה יתבארו היטב דברי הזוהר שלפנינו."],[3,"","וז\"ש \u0003נעשה אדם, בשותפא\u0004 כלומר, לשון נעשה יורה משותף, \u0003כלל דכר ונוקבא\u0004 יורה שאמא עצמה נכללת מדכר ונוקבא. כי אעפ\"י שאמא היא בחינת עלמא דדכורא, ואין בה בחינת נוקבא כלל, היא השתתפה עתה עם המלכות שהיא נוקבא, כנ\"ל. \u0003בצלמנו עתירי כדמותנו מסכני, דהא מסטרא דדכורא עתירי ומסטרא דנוקבא מסכני\u0004 כי זכר ה\"ס אור ועשירות, ונוקבא ה\"ס חושך ועניות."],[3,"","וכיון שאמרה בצלמנו וכדמותנו, הרי שנמצא בה עצמה ענין החושך והעניות, שהוא מחמת השתתפותה עם המלכות לצורך בריאת האדם, ויצא גם האדם כלול \u0003מעתירי ומסכני\u0004 דהיינו מאור וחושך, שעי\"כ יגמר על ידו כל התיקון, והמלכות תתפשט בקדושתה על כל הארץ, \u0003ויהיה ה' אחד ושמו אחד\u0004, כי החושך שבמלכות יתהפך אז לאור גמור כמו הזכר שהוא הוי\"ה, ויהיה הוא אחד ושמו אחד. ואז יקוים \u0003אפס כי לא יהיה בך אביון\u0004."],[3,"","וזה אמרו \u0003כמה דאינון בשותפא חדא וחס דא על דא, ויהיב דא לדא, וגמיל ליה טיבו, הכי אצטריך בר נש לתתא למהוי עתירא ומסכנא בחבורא חדא, ולמיהב דא לדא, ולגמלאה טובא דא לדא\u0004 כמו שהצלם והדמות הנכללים באמא הם \u0003בשותפא חדא\u0004 מחמת שאמא חסה על הדמות שהיא המלכות, כדי לתקן כל בחינת החושך שבה, ואמא עלאה מיעטה את עצמה ונתנה מחלקה אל המלכות, שהיא עניה, ו\u0003גמיל לה חסד\u0004. כן האדם שנברא על ידה בצלם ודמות, צריך לרחם ולחוס על \u0003מסכני\u0004, שהם בחינת הדמות שבו, להיות עמהם בחיבור אחד, ולפרנסם בכל מה שחסר להם, ולגמול עמהם חסד. וע\"י קיום מצוה זו, ימשיך על עצמו הצלם והדמות דאמא שנברא בו, שה\"ס כל המוחין עלאין, שזכה בהם אדה\"ר בעת שנברא בצלם ובדמות האלה."],[3,"","ואז \u0003וירדו ברגת הים\u0004 וגו' \u0003דכל מאן דחס על מסכני ברעותא דלבא לא משתני דיוקניה לעלם מדיוקנא דאדם הראשון, וכיון דדיוקנא דאדם אתרשים ביה, שליט על כל בריין דעלמא בההא דיוקנא\u0004 וירדו בדגת הים וגו' כל מי שהוא מרחם על העני בלב שלם, לא ישונה לעולם צלמו מצלמו של אדה\"ר. כי ע\"י מצוה זו זוכה לאותו צלם ודמות של אדם, דהיינו לכל אלו המוחין וזהרא עלאה דאצילות שזכה אדה\"ר, שהוא שלט בכחם \u0003על כל בריין דעלמא\u0004, כלומר, שלא היה שום כח מכחות הרע שלא נכנע לפניו \u0003כלהו זעין ודחלין מההוא דיוקנא דאתרשים ביה\u0004 כולם חרדים ויראים מהצלם ההוא שנרשם בו. כי ביטל כל כוחות הרע והחושך ולא היתה להם שום תקומה לפניו, כי שם ה' נקרא עליו, שה\"ס \u0003צלם אלהים\u0004 כנ\"ל."],[3,"","ומביא ראיה \u0003מנבוכדנצר\u0004, שלא היתה לו שום מצוה ועם כל זה אחר שנגזרה עליו הגזרה, בחלום ופתרון דדניאל, אמר לו דניאל \u0003וחטאך בצדקה פרוק\u0004, וכן עשה, \u0003וכל זמנא דהוה מיחן למסכני לא שרא עליה חלמיה, כיון דאטיל עינא בישא דלא למיחן למסכני מה כתיב, עוד מלתא בפום מלכא\u0004 וגו' \u0003מיד אשתני דיוקניה ואטריד מן בני נשא\u0004 כל זמן שהיה מרחם על העניים לא היתה חלה עליו גזרת החלום כיון שהטיל עין הרע שלא לרחם על העניים, מה כתיב עוד מלתא בפום מלכא וגו' מיד נשתנתה צורתו ונטרד מן האנשים. הרי שמצוה זו גדולה מכל המצות שבתורה, שהיא לבדה יכולה לבטל מהאדם כל מיני גזרות רעות שנגזרו עליו."],[3,"","וז\"ש (באות רל\"ו), \u0003כתיב הכא עשיה\u0004 וכו', ויליף גזרה שוה, מה עשיתי שבבועז הוא צדקה אף נעשה שבכאן הוא צדקה. כלומר לשון \u0003נעשה\u0004 הנאמרה בבריאת האדם מורה על מצות צדקה, כי אמא עשתה צדקה עם המלכות ונכללה בה, כנ\"ל. ומביא ראיה מ\u0003רות\u0004, שאמרה, \u0003שם האיש אשר עשיתי עמו\u0004, כי לכאורה אין לו פירוש, כי מה עשתה עמו, הלא רק קבלה ממנו, אמנם עם הפירוש הנ\"ל אשר עשיה הוא לשון חבור של \u0003עתירי ומסכני\u0004 צודק לשון עשיה עם \u0003בועז\u0004, כי נשתתפו שניהם בחבורא חדא ע\"י הצדקה"],[4,"","רלז) \u0003פקודא עשיראה\u0004 וכו': המצוה העשירית היא, להניח תפלין, ולהשלים עצמו בצורה העליונה. שכתוב, ויברא אלקים את האדם בצלמו. פתח ואמר, ראשך עליך ככרמל. מקרא זה העמדנו ונשנה. אבל ראשך עליך ככרמל, זהו ראש העליון, תפלין של ראש, של מלך העליון הקדוש \u0003הוי\"ה\u0004 באותיות רשומות. כל אות ואות, שבשם הוי\"ה, היא פרשה אחת בתפילין, וכך השם הקדוש חקוק בפרשיות התפילין, בסדר האותיות כראוי. ולמדנו. כי שם ה' נקרא עליך ויראו ממך, אלו הם תפלין של ראש, שהם השם הקדוש, לפי סדר האותיות."],[4,"","ביאור הדברים, כי \u0003בפקודא למיחן למסכני\u0004 הנ\"ל, נעשה רק התחלה להמשכת \u0003דיוקנא עלאה\u0004, שה\"ס \u0003צלם אלהים\u0004, כמ\"ש לעיל, שע\"י פקודא דלמיחן למסכני, נכללה אמא במלכות בסוד \u0003נעשה אדם בצלמנו כדמותנו\u0004, ותדע שה\"ס \u0003אמא אוזיפת לברתא מאנהא\u0004 (כמ\"ש לעיל באות י\"ז) שע\"י התכללות המלכות באמא, נפלו אתוון \u0003אל\"ה\u0004 למקום הזו\"ן, ולא נשאר באמא כי אם אתוון ד\u0003מ\"י\u0004 בלבד ונבחן שאתוון \u0003אל\"ה\u0004 דאו\"א ירדו לבחינת זו\"ן, דהיינו שבחינת אבא שבהם לקח הז\"א, ובחינת אמא שבהם לקחה הנוקבא, ונעשים לבחינת זו\"ן ממש, כי העליון היורד לתחתון נעשה כמוהו."],[4,"","ועל ידיהם הרויחו הזו\"ן בחינת הקטנות של \u0003צל\"ם אלהים\u0004, כלומר, ו\"ק בלי ראש, משום שגם אמא עצמה הפסידה בחינת הג\"ר שלה ע\"י השתתפות זו, כי נפלו ממנה ג' הכלים \u0003אל\"ה\u0004 שהם בינה וז\"א ומלכות של הע\"ס שלה, ולא נשארו בה כי אם ב' אתוון \u0003מ\"י\u0004, שהן כתר וחכמה דע\"ס שלה ונודע, שחסר ג' תחתונות דכלים חסר ג' ראשונות דאורות, ולא נשאר בהכלים ד\u0003מ\"י\u0004 שלה, אלא אורות דרוח נפש לבד, אור הרוח בכלי דכתר, ואור הנפש בכלי דחכמה."],[4,"","וע\"כ לא היתה יכולה להשפיע לזו\"ן רק ו\"ק בלי ראש. ואם כן עוד לא נשלם הזו\"ן \u0003בדיוקנא עלאה\u0004 שהם מוחין דג\"ר הנק' \u0003צל\"ם אלהים\u0004. וז\"ש \u0003לאנחא תפילין ולאשלמא גרמיה בדיוקנא עלאה\u0004 שע\"י \u0003פקודא דתפילין\u0004 ממשיכין הג\"ר להזו\"ן, שהם השלמת צלם עלאה."],[4,"","ולא יקשה לך, הרי כאן המדובר הוא מהאדם התחתון, והזו\"ן כבר נשלמו בהכרח, כי לא יכלו להוליד נר\"ן אל האדם התחתון טרם שיעלו בעצמם למקום או\"א, ויגדלו במוחין שלהם כמוהם, וא\"כ איך אנו אומרים שאפילו אמא עודנה בקטנות."],[4,"","אכן, תדע, כי בעת שהזו\"ן משיגים המוחין דאו\"א, נמצאים מלבישים לאו\"א והם כמוהם ממש, כי התחתון העולה לעליון נעשה כמוהו ממש. וא\"כ כל מה שאנו מבחינים עתה באו\"א, הכוונה היא על זו\"ן שנעשו לאו\"א. כי כל אותם הדרכים הנוהגים באו\"א ללידת מוחין דזו\"ן דאצילות, נוהגים כן בדיוק גמור בזו\"ן שנעשו לאו\"א, בעת שהם מולידים המוחין, שהם הנר\"ן, לאדם התחתון, בלי הפרש של כלום. ולפיכך אין צורך לשנות את השמות כלל, ומכנים עתה לזו\"ן בשם או\"א, ולנר\"ן דאדם התחתון בשם זו\"ן. וזכור זה להלן בכל ההמשך."],[4,"","וז\"ש, \u0003דכתיב ויברא אלהים את האדם בצלמו\u0004: סוד \u0003הצל\"ם\u0004 הוא ענין ארוך מאד, אמנם אבארו כאן לפי הנחיצות להבין הדברים שלפנינו. וצריך שתזכור כל המתבאר לעיל במראות הסולם (אות ב' בענין המספר י\"ג שיש בספירות עד אות ד') עש\"ה, כי אין להכפיל דברים בכדי."],[4,"","ותראה שם שליחידה חיה אין כלים, ורק לנר\"ן יש כלים בינה וזו\"ן, ואפילו כשאנו אומרים במפורש כלי דכתר, הכוונה היא לבינה וזו\"ן דכתר. והבינה וזו\"ן מתחלקים לע\"ס ע\"י תיקון קוין, שג' קוין דבינה הם חב\"ד, ודז\"א הם חג\"ת, ודנוקבא הם נהי\"ם, ומספר זה נוהג לאור דחסדים. אמנם להשפעת הארת החכמה, נחלקה הבינה לב' בחינות: או\"א וישסו\"ת, שהם חב\"ד חג\"ת, אשר עם הז\"ת דזו\"ן הם י\"ג ספירות, שז\"ס הגימטריא \u0003אח\"ד\u0004 שהוא י\"ג, הרומז לשמא שלים."],[4,"","ושורש הדברים, כי הכתר והחכמה נסתמו בח\"ס דא\"א, ורק הבינה שלו מאירה כל המוחין דאצילות, והיא נחלקה לאו\"א וישסו\"ת דאצילות, שהג\"ר שלה מאירים באו\"א והו\"ק שלה בישסו\"ת, וב' בחינות הבינה הללו נקראות \u0003ם' ל'\u0004 ד\u0003צל\"ם\u0004, שאו\"א נקראים \u0003מ'\u0004 ד\u0003צל\"ם\u0004, ונקראים כן בסוד עזקא דכיא, כי ה\u0003ם'\u0004 היא כמו עזקא סגורה הסוגרת המוחין סביב סביב. וישסו\"ת נקראים \u0003ל'\u0004 ד\u0003צל\"ם\u0004, ונקראים כן, כי ה\u0003ל'\u0004 מגבהת ראשה למעלה כמו מגדל, שראש זה רומז על מוחין דג\"ר, וה\"ס הכתוב, מגדל עוז שם ה' בו ירוץ צדיק ונשגב. כי הישסו\"ת ה\"ס מגדל, והז\"א נקרא צדיק הרץ במגדל הזה ונשגב מאד."],[4,"","באופן שאו\"א הם בסוד עזקא הסוגרת המוחין, ואור החכמה לא יתגלה בהם לרוב גבהם, כי אור החכמה שבהם, הוא בחינת חכמה סתימאה עצמה, שנעלמה מכל פרצופי אצילות, וע\"כ אינה מתגלית בהם, ואין בהם רק אור חסדים לבד, הנקרא אוירא דכיא, כי אויר ה\"ס אור הרוח. ונקרא ג\"כ אויר סתום, כי ה\u0003י'\u0004 לא נפיק מאויר שלהם לעולם."],[4,"","אבל הישסו\"ת, להיותם רק בחינת הז\"ת דבינה, שה\"ס בחינת זו\"ן הכלולים בבינה, אינם נקראים אויר סתום, כי בעת השפעת מוחין דגדלות לזו\"ן ה\u0003י'\u0004 נפיק מאויר שלהם ונעשו אור, שפירושו חכמה ומוחין דג\"ר. ומסבה זו נקרא הישסו\"ת מגדל הפורח באויר, כי מגדל פירושו גדלות דג\"ר, ומשום שאין מוחין אלו קבועים בזו\"ן נמצא שהזו\"ן בעת הקטנות, הוא משום שנכנסה ה\u0003י'\u0004 באור ונעשה אויר, ולעת גדלות חוזרת ויוצאת ה\u0003י'\u0004 מהאויר ונעשה אור, ע\"כ נבחן כמו מגדל פורח מחמת התיקון שבו בסוד אויר. והז\"א נקרא \u0003צ'\u0004 ד\u0003צל\"ם\u0004, כי הוא הצדיק הרץ במגדל ונשגב כנ\"ל."],[4,"","ונתבארו היטב ג' האותיות \u0003צל\"ם\u0004, בסוד ז\"א שהוא \u0003צ'\u0004, וישסו\"ת שהם \u0003ל'\u0004, ואו\"א שהם \u0003ם'\u0004. והם סוד חכמה בינה דעת, כי או\"א הם חכמה, המסוגרים בעזקא דכיא, להיותם בבחינת ח\"ס. וישסו\"ת הם בינה, אמנם בעת עליתה לראש א\"א, יוצאת ה\u0003י'\u0004 מאויר שלה ומשפעת חכמה, בסוד מגדל הפורח באויר. וז\"א הוא הרץ במגדל הזה דהיינו שהוא המקבל של המוחין האלה וה\"ס דעת. וזכור היטב כל זה, שהם משרשי החכמה, ולא יארע בדרכים אלו שום שינוי לעולם, ולפיכך נקראים המוחין תמיד בשם \u0003צל\"ם\u0004."],[4,"","ומה שאמרנו שחב\"ד הם ג' אותיות \u0003ם' ל' צ'\u0004 ד\u0003צל\"ם\u0004, אין לערבם עם ג' הקוים שבמוחין הנק' חב\"ד, כי אלו החב\"ד ד\u0003צל\"ם\u0004 אינם בבחינת ג' קוין, אלא שהם ג' פרצופין שלמים המתלבשים זה בתוך זה, כי החכמה שהיא \u0003ם'\u0004 דצלם, ה\"ס או\"א המתלבשים מחזה ולמטה תוך הבינה שהיא ישסו\"ת ו\u0003ל'\u0004 ד\u0003צל\"ם\u0004. והישסו\"ת מתלבשים מחזה ולמטה תוך הדעת שהוא הז\"א, הנקרא \u0003צ'\u0004 ד\u0003צל\"ם\u0004."],[4,"","וזה אמרו \u0003ולאשלמא גרמיה בדיוקנא עלאה דכתיב ויברא אלהים את האדם בצלמו\u0004, שע\"י ה\u0003תפילין\u0004 ממשיכים מוחין דג\"ר בסדר אותיות ה\u0003צל\"ם\u0004 המובא בכתוב \u0003ויברא אלהים את האדם בצלמו\u0004, שה\"ס \u0003הזהרא עלאה\u0004 דאצילות שקבל אז אדה\"ר בעת שנברא ואנו ממשיכים אותם מקודם אל הזו\"ן, ומשם משפיעים אלו המוחין גם עלינו. וסדר אותיות ה\u0003צל\"ם\u0004 מתבאר בד' הפרשיות של ה\u0003תפילין\u0004 כמ\"ש לפנינו."],[4,"","וז\"ש, \u0003תפילין דרישא שמא דמלכא עלאה קדישא יהו\"ה באתוון רשימין\u0004: תפילין של ראש הוא שמו של המלך העליון הקדוש, הוי\"ה באותיות רשומות. התפילין מכונים \u0003כרמל\u0004, כי \u0003כרמל\u0004 פירושו \u0003כר מלא\u0004 מכל טוב, וז\"ס הכתוב \u0003ראשך עליך ככרמל\u0004 דהיינו שראש עלאה דז\"א וכן דנוקבא בעת שמלובשים ב\u0003תפילין דרישא\u0004, שהם המוחין עלאין ד\u0003צל\"ם\u0004, הם דומים \u0003ככרמל, ככר מלא\u0004 מכל טוב. ומוחין אלו נקראים \u0003שמא דמלכא עלאה קדישא\u0004, דהיינו ד' אותיות \u0003הוי\"ה\u0004 כסדר האותיות שלהן \u0003י' ה' ו' ה'\u0004. ומה שמדגיש \u0003הוי\"ה באתוון רשימין\u0004, היינו שכל אות ואות רשומה בפרצוף בפני עצמה, והוא משום שבכל פרצוף יש ד' אותיות \u0003הוי\"ה\u0004 שהן ע\"ס. ע\"כ אומר שהכוונה היא על \u0003אתוון רשימין\u0004 דהיינו שכל אחת היא פרצוף שלם בפ\"ע."],[4,"","וז\"ש \u0003כל את ואת פרשתא חדא\u0004 וכו' \u0003גליפא בסדורא דאתוון כדקא יאות\u0004: כל אות ואות של השם הוי\"ה היא פרשה אחת מארבע הפרשיות שבתפילין, השם הקדוש חקוק בהן כסדרן של האותיות כראוי. פרשה, פירושה פרצוף שלם בפני עצמו, ואומר, שכל אות ואות דשם \u0003הוי\"ה\u0004 נעשה בסוד המוחין לפרצוף שלם בפ\"ע ומסודרות בבתים \u0003בסדורא דאתוון כדקא יאות\u0004, דהיינו בסדר \u0003י' ה' ו' ה'\u0004. וה\"ס \u0003תפילין דרש\"י\u0004, כי ה\u0003תפילין דר\"ת\u0004 מסודרות בבתים בסדר הר\"ת היוצא מהפסוק, כי אם בזאת יתהלל המתהלל השכל וידוע אותי דהיינו י' ה' ה' ו'. כנודע."],[5,"","רלח) \u0003פרשתא קדמאה קדש\u0004 וכו': הפרשה הראשונה שבתפילין, היא קדש לי כל בכור היא \u0003י'\u0004 דהוי\"ה, שהיא \u0003קדש\u0004, דהיינו חכמה, שהיא הבכור של כל \u0003קדשים\u0004 העליונים. היא, פטר כל רחם, על ידי אותו שביל הדק היורד מן ה\u0003י'\u0004, שהוא הפותח את הרחם לעשות פירות ואבים כראוי. והוא קדש העליון."],[5,"","פירוש. היינו או\"א \u0003עילאין\u0004, הרמוזין באות יוד דשם \u0003הוי\"ה\u0004, שה\u0003י'\u0004 רומזת לאבא, והמלוי דיוד שהוא ו\"ד רומז לאמא. ופרצוף דאו\"א נקרא \u0003קדש\u0004, ונקרא \u0003בכור\u0004 משום שאין שום פרצוף מישסו\"ת וזו\"ן דאצילות נקראים \u0003קדש\u0004, אלא א\"כ הם מקבלים הקדושה מאו\"א עלאין."],[5,"","וז\"ש \u0003בוכרא דכל קודשין עלאין\u0004 שהוא \u0003הבכור\u0004 לכל פרצופין \u0003קדישין\u0004 דאצילות, כי הקדושה שבפרצופי אצילות מאו\"א נמשכת. והטעם הוא כי אור החכמה נקראת קדש, וכבר נתבאר שאו\"א הם \u0003ם' דצל\"ם\u0004, והם חכמה דאצילות משום שחכמה סתימאה מתלבשת ומתעלמת בהם."],[5,"","ועכ\"ז הם עצמם נבחנים רק לבחינת אוירא דכיא, דהיינו אור חסדים, משום שחכמה זו נסתמה ברישא דא\"א, ואין הפרצופין יכולים לקבל חכמה, רק מבינה החוזרת להיות חכמה בעת שעולה לרישא דא\"א, ומתיחדת שם עם החכמה סתימאה ע\"י או\"א, ואז נקראת הבינה ג\"כ בשם חכמה, וחכמה זו נקראת בשם חכמה דל\"ב נתיבות. הרי שאפילו הבינה החוזרת להיות חכמה הנקראת \u0003קדש\u0004 אין זה אלא מחמת שמקבלת מחכמה סתימאה שבאו\"א ע\"י עליתה לא\"א. ומכ\"ש שאר פרצופי אצילות המקבלים רק מבינה זו שחזרה להיות חכמה. ויתבאר עוד לפנינו."],[5,"","וז\"ש, \u0003שביל דקיק דנחת מן י' דאיהו אפתח רחמא למעבד פירין ואבין\u0004: פותח כל רחם, עם אותו שביל הדק היורד מה\u0003י'\u0004 שהוא פותח הרחם לעשות פירות ואבים. פירוש כי נבחן בה\u0003י'\u0004 ג' בחינות: \u0003רישא, גזעא, ושבילא\u0004 הקוץ העליון שבה נקרא \u0003רישא\u0004, הרומז לבחינת א\"א הנעלם ומלובש באו\"א, (כנ\"ל בדיבור הסמוך). וגופה של \u0003י'\u0004 נקראת \u0003גזעא\u0004 הרומז לפרצוף או\"א עצמם. והקוץ התחתון של ה\u0003י'\u0004 נקרא \u0003שבילא\u0004, הרומז על יסודות דאו\"א שהם בסיום פרצוף שלהם, והיא נקראת \u0003שביל דקיק\u0004."],[5,"","אמנם עיקר השם \u0003שביל\u0004 הוא רק על יסוד דאבא, כי יסוד דאמא נק' \u0003נתיב\u0004, בסוד האי שביל בהאי נתיב יתיב, והסו\"ה ושבילך במים רבים. כי החסדים בעת שהם בשפע גדול נקראים מים רבים, שע\"י זווג זה ד\u0003שביל ונתיב\u0004 שהוא זווג דלא פסיק לעלמין, משפיעים מים רבים בלי הפסק לעולמות. ומטרם שנתקנו פרצוף או\"א בחבורא ד\u0003שביל ונתיב\u0004 לא היה מושפע שום שפע אל העולמות."],[5,"","וז\"ש, \u0003פטר כל רחם, בההוא שביל דקיק דנחת מן י'\u0004 הנתיב דאמא נקרא \u0003רחם\u0004 שכל הרחמים משם מושפעים, שמטרם שנתקנו או\"א בחבור דשביל ונתיב היתה סתומה, ולא נפתחה רק ע\"י \u0003השביל דקיק\u0004 דאבא, וע\"כ נקרא השביל דקיק, \u0003פטר כל רחם. דאיהו אפתח רחמא, למעבד פירין ואבין כדקא יאות\u0004 כי \u0003פטר\u0004 פירושו פותח, ומעת שנתחבר בה \u0003שביל דקיק\u0004 דאבא משפעת אמא \u0003פירין ואבין\u0004 בשפע גדול \u0003כדקא יאות\u0004, בסו\"ה ושבילך במים רבים."],[6,"","רלט) \u0003פרשתא תניינא והיה\u0004 וכו': הפרשה השניה, היא והיה כי יביאך, היא \u0003ה'\u0004 דהויה, שהיא בינה, שהיא ההיכל, שנפתח רחמה על ידי ה\u0003י'\u0004, בחמשים פתחים ומסדרונות וחדרים סתומים שבו. אותה הפתיחה שעשתה ה\u0003י'\u0004 בהיכל הזה, היא כדי לשמוע בו את הקול היוצא מתוך השופר הזה, שהיא בינה. משום ששופר זה, הוא סתום מכל הצדדים, ובאה ה\u0003י'\u0004 ופתחה אותו, להוציא ממנו קול. וכיון שפתחה אותו, תקעה בו, והוציאה ממנו קול להוציא עבדים לחרות."],[6,"","פירוש, כי \u0003ה'\u0004 דשם \u0003הוי\"ה\u0004 רומזת על פרצוף ישסו\"ת, שה\"ס \u0003ל' דצל\"ם\u0004, הנקרא מגדל הפורח באויר והוא \u0003היכלא דאתפתח\u0004 וכו' \u0003בחמשין פתחין\u0004, כי או\"א נבחנים לאויר סתום דלא אתפתח, שהם בסוד \u0003ם'\u0004 ד\u0003צל\"ם\u0004, הרומזת לעזקא המקפת מוחין שלהם, וה\u0003י'\u0004 לא נפיק מאויר שלהם באופן שישפיעו אור החכמה, אשר ע\"כ אינם משפיעים אלא אוירא דכיא לבד, שהוא אור חסדים כנ\"ל, אבל הישסו\"ת שה\"ס \u0003ל'\u0004 ד\u0003צל\"ם\u0004, ובחינת בינה הם נבחנים ל\u0003היכלא דאתפתח\u0004 וכו' \u0003בחמשין פתחין\u0004 ומשפיעים חכמה לזו\"ן ע\"י עליתם לראש א\"א ששם הבינה מתהפכת להיות חכמה כנ\"ל."],[6,"","ובינה זו נקראת \u0003חמשין\u0004 שערי בינה, כי בה ה' ספירות כח\"ב זו\"ן שבכל אחת מהן עשר ספירות, והן חמשים. וכל ספירה וספירה מהחמשים מתחלקת \u0003לאדרין ואכסדראין\u0004, שבחינת חג\"ת שבספירה נקראת \u0003אדרין\u0004, שפירושו חדרים, ובחינת נה\"י שבהן נקראת \u0003אכסדרין\u0004, שמורה, שאין בה בחינת כלי קבלה לעצמם הם, אלא רק לבחינת הוצאה והכנסה אל החדרים, (כנ\"ל אות רכ\"ט)."],[6,"","וזה אמרו \u0003והיה כי יביאך דא ה', היכלא דאתפתח רחמא דילה\u0004 כי פרשה ב' ד\u0003תפילין\u0004 שהיא \u0003והיה כי יביאך\u0004 רומזת על \u0003ה'\u0004 דשם \u0003הוי\"ה\u0004, שהוא פרצוף ישסו\"ת דאצילות, אשר \u0003רחמא דילה\u0004 אתפתח להשפיע חכמה לזו\"ן כנ\"ל. ומ\"ש \u0003מגו י'\u0004 יתבאר לפנינו."],[6,"","וז\"ש, \u0003למשמע בה קלא\u0004 וכו', הפתיחה ההיא עשה ה\u0003י'\u0004 בהיכל ההיא, כדי לשמוע בה הקול היוצא מתוך שופר הזה, משום ששופר הזה סתים מכל הצדדים. פירוש, כי כבר נתבאר לעיל, שבעת שהישסו\"ת שהיא בינה נשתתפה בהמלכות, ירדו ג' ספירות \u0003אל\"ה\u0004, שהם בינה וזו\"ן דגופא דישסו\"ת, אל מקום הזו\"ן דאצילות, ולא נשאר בהישסו\"ת, אלא ב' אתוון \u0003מ\"י\u0004. ואח\"כ ע\"י העלאת מ\"ן חוזרת להוריד ה\"ת מנקבי עינים שלה למקום הפה, כמו שהיתה מטרם השיתוף, ואז חוזרים ועולים אליה ג' אתוון \u0003אל\"ה ואשתלים\u0004 שוב \u0003שמא דאלהים\u0004 (כנ\"ל אות י\"ד עש\"ה)."],[6,"","ועם \u0003אל\"ה\u0004 אלו שעלו אל הבינה בחזרה עולים גם הזו\"ן, (כנ\"ל אות י\"ז ד\"ה ואימא אוזיפת עש\"ה) גם נתבאר (לעיל אות י\"ד ד\"ה קיימא ולא קיימא). שאע\"פ שהג' אתוון \u0003אל\"ה\u0004 כבר עלו ונתחברו אל הבינה, \u0003ואשתלים שמא דאלהים\u0004, מ\"מ נבחן עוד שהשם \u0003אלהים עמיק וסתים בשמא\u0004, משום שאין שם אלא אור החכמה לבד, ואין הארת החכמה יכולה להתקבל ל\u0003אל\"ה\u0004 זולת ע\"י לבוש של חסדים. עש\"ה. ולפיכך נבחן, שאלו אתוון \u0003אל\"ה\u0004 הם בחי' \u0003שופר\u0004, שבתוכו מלובשים הזו\"ן, שעלו עמהם אל הבינה, הנבחנים לקול, והוא משום שהם המעלים עמהם את הזו\"ן לבינה מכח היותם כלולים בהם מעת קטנות, ונמצאים נושאים בתוכם את הז\"א, כמ\"ש שם."],[6,"","וזה אמרו \u0003דההוא פטר דעביד י' בהאי היכלא למשמע בה קלא די נפקא מגו שופר דא\u0004, שפתיחה ההוא עשאה היוד בהיכל הזה, כדי לשמוע בה הקול היוצא מהשופר הזה. כי ה\u0003י'\u0004 שהם או\"א עלאין, הם המשפיעים הארה עליונה להוריד ה\"ת מנקבי עינים דישסו\"ת בחזרה אל הפה שלהם, ומעלים את הג' אתוון \u0003אל\"ה\u0004 שהיו במקום הזו\"ן, ומחברים אותם שוב אל הבינה, כמו שהיו מטרם השתתפותם עם המלכות, ונמצא שה\u0003י'\u0004 פתחה את ההיכל דישסו\"ת בכדי להשפיע מוחין לז\"א, מתוך \u0003השופר\u0004, שהם אתוון \u0003אל\"ה\u0004 שהעלתה, כי גם הזו\"ן עולים עם אתוון \u0003אל\"ה\u0004 ההם אל הבינה ומקבלים שם חכמה,"],[6,"","וז\"ש \u0003למשמע בה קלא\u0004 דהיינו להאציל הז\"א עם המוחין דגדלות הנקרא \u0003קול\u0004, ואצילותו נבחן להשמעת \u0003קול. בגין דשופר דא סתים בכל סטרין\u0004, משום ששופר הזה סתום מכל הצדדים, דהיינו הן מחסדים והן מחכמה. כי אלו אתוון \u0003אל\"ה\u0004 הנקראים \u0003שופר\u0004 המה נופלים במקום זו\"ן, והם סתימין שם הן מג\"ר והן מאור חסדים וע\"כ הם צריכים ב' תקונים: א)להעלותם ולחברם בבינה שישיגו בחינת הג\"ר שלהם, שהוא אור החכמה. ב) להשפיע בהם אור חסדים שיהיה לבוש להחכמה."],[6,"","וז\"ש, \u0003ואתא יוד ופתח ליה לאפקא מניה קלא\u0004 היינו תיקון הא', שהיוד ממשיך הארה עליונה אל ה\u0003ה'\u0004 שהיא היכלא דישסו\"ת, המורידה ה\"ת למקומה, ומעלה ג' אתוון \u0003אל\"ה\u0004 עם הזו\"ן שבתוכם ומחברם אל הבינה, ומשיגים על ידי זה הארת החכמה, שהוא גם מוחין אל הז\"א שעלה עם האתוון \u0003אל\"ה\u0004. אמנם הארת החכמה עודנה סתומה ואינה מאירה, מטעם חסרון חסדים כנ\"ל, וע\"כ נבחן שעוד לא יצא ה\u0003קול\u0004, דהיינו שעוד לא נולד הז\"א, וז\"ש \u0003לאפקא מניה קלא\u0004 להוציא ממנו אח\"כ, ע\"י תיקון ב', את ה\u0003קול\u0004. ועתה עוד לא יצא."],[6,"","ואחר כך \u0003וכיון דאפתח ליה תקע ליה, ואפיק מניה קלא, לאפקא עבדין לחירו\u0004 היינו התיקון הב' הנ\"ל, כי אחר שפתח ההיכל, דהיינו שחיבר אתוון \u0003אל\"ה\u0004 עם זו\"ן בחזרה לבינה, והשיגו שם אור חכמה, \u0003תקע ליה\u0004 היינו ש\u0003היוד\u0004 תקעה אויר תוך ה\u0003שופר\u0004, כי אויר פירושו אור חסדים, וכיון שה\u0003שופר\u0004, שהוא אתוון \u0003אל\"ה\u0004, קבלו גם אויר, שהוא אור חסדים \u0003ואפיק מניה קלא\u0004 הוציא והוליד את הז\"א שנק' \u0003קול\u0004, והוציאו בשלימות למקומו. כי ע\"י לבוש החסדים דתקעה ה\u0003י'\u0004 יכולה החכמה להתלבש בו ולהתקבל אל הז\"א. וע\"כ המוחין האלו אשר השיג הז\"א, הנק' \u0003קול\u0004, הוא מוציא את העבדים לחרות, כלומר שהז\"א משפיע הארתו לעולמות, ובני ישראל זוכים אז במוחין דג\"ר הנקראים חרות."],[7,"","רמ) \u0003ובתקיעו דשופרא דא\u0004 וכו': ובתקיעת השופר הזה יצאו ישראל ממצרים. וכך עתיד, לתקוע בשופר, בפעם אחרת באחרית הימים. וכל גאולה באה משופר הזה, שהוא בינה. ומשום זה, יש בה בפרשה זו, יציאת מצרים, משום שמשופר הזה באה, בכח ה\u0003י'\u0004 שפתח רחמה, והוציא קולה לגאולת העבדים. וזו היא \u0003ה'\u0004, אות שניה משם הקדוש."],[7,"","פירוש, כי כל המוחין המושפעים לזו\"ן באים \u0003מהאי שופר\u0004, שהם אתוון \u0003אל\"ה\u0004 הנ\"ל. גם אלו המוחין הגדולים שקבל הז\"א להוציא ישראל ממצרים היו \u0003מהאי שופר\u0004 על הדרך הנ\"ל, וכן המוחין שיתגלו באחרית הימים לגאולה השלימה יהיו \u0003מהאי שופר\u0004 ע\"ד הנ\"ל,"],[7,"ובגין כך אית בה יציאת מצרים בפרשתא דא","ומשום זה יש בפרשה הזו יציאת מצרים. היינו בפרשת \u0003והיה כי יביאך\u0004 שבתפילין, \u0003דהא מהאי שופר אתי\u0004 כי המוחין שנתגלו ליציאת מצרים באו מ\u0003השופר\u0004 הזה שבישסו\"ת, דהיינו \u0003בחילא דיוד דפתח רחמא דילה\u0004 בכח או\"א הנק' \u0003י'\u0004 דהוי\"ה, שפתח הרחם דישסו\"ת שהם אתוון אל\"ה, כנ\"ל,"],[7,"ואפיק קליה","והוציא קולו. שהוא הז\"א הנק' \u0003קול\u0004, ע\"י השגת המוחין הללו, \u0003לפורקנא דעבדין\u0004 לגאולת העבדים. שהם מספיקים להוציא ישראל מעבדות לחרות. ודע שאין ז\"א ונוקבא נקראים \u0003קול ודיבור\u0004 רק בהשגת המוחין דחיה, ולא בשאר המדרגות הפחותות ממדרגת חיה, ומהמוחין דחיה באות כל הגאולות. כמבואר."],[8,"","רמא) \u0003פרשתא תליתאה רזא\u0004 וכו': הפרשה השלישית, היא, סוד היחוד של שמע ישראל, שהוא \u0003ו'\u0004 דהויה, הכוללת הכל, שהוא ז\"א, ובו יחוד הכל, שבו מתיחדים, והוא לוקח הכל. הפרשה הרביעית היא, והיה אם שמוע, שהיא כללות שני הצדדים, חסד וגבורה, שכנסת ישראל, שהיא הגבורה שלמטה, שהיא המלכות, נתאחדת בהם. וזו היא \u0003ה'\u0004 אחרונה דהויה, הלוקחת אותם ונכללת מהם."],[8,"","פירוש, כי פרשה ג' דתפילין שהיא \u0003שמע ישראל\u0004, היא פרצוף ז\"א הנק' \u0003ואו\u0004 דהוי\"ה \u0003דכליל כלא\u0004 שהוא הכולל לכל אלו ד' הפרשיות שבתפילין, כי אע\"פ שב' הפרשיות הראשונות \u0003קדש, והיה כי יביאך\u0004 הם או\"א וישסו\"ת, הנק' חו\"ב, אין הפירוש שהם או\"א וישסו\"ת עצמם, אלא הם או\"א וישסו\"ת המתלבשים בראש הזו\"ן, בסוד חכמה בינה שבמוחין דז\"א, המכונים \u0003ם' ל'\u0004 דצלם דז\"א."],[8,"","וכן פרשה רביעית \u0003והיה אם שמוע\u0004, שאומר להלן שהיא הנוקבא דז\"א, אין הפירוש על הנוקבא עצמה, אלא רק בחינת הנוקבא הכלולה בז\"א, שהיא נקראת בו בשם מוח הגבורה של הז\"א. כי ג' מוחין הם בז\"א הנק' חכמה בינה דעת, והם מכונים \u0003ם' ל' צ'\u0004 דצלם הז\"א. והם חו\"ב תו\"מ שבמוחין דז\"א. כי בדעת שהיא \u0003צ'\u0004 יש חסד וגבורה, והחסד שבדעת נבחן לבחינת ז\"א עצמו, והגבורה שבדעת נבחנת להתכללות הנוקבא. והם ד' פרשיות שבתפילין."],[8,"","הרי שהז\"א שהוא \u0003ואו\u0004 דהוי\"ה \u0003כליל כלא\u0004, לכל ד' הפרשיות. \u0003וביה יחודא דכלא\u0004 שכל היחודים האמורים באו\"א וישסו\"ת הם רק בז\"א, כלומר לצורך ז\"א לבד. כי הפרצופין הקודמים לז\"א הם תמיד ביחוד, ואינם צריכים למ\"ן מהתחתונים ליחד אותם, וכל היחודים שאנו עושים ע\"י מ\"ן בפרצופין העליונים אינם כלום לצרכם עצמם, אלא לצורך הז\"א."],[8,"וביה אתייחדן","שאין יחוד לחכמה ובינה בשביל התחתונים, שהבינה תחזור להיות חכמה, אלא ע\"י עלית הז\"א להם למ\"ן. כי בעת שהז\"א עולה למ\"ן אל הבינה, אז עולה הבינה לראש דא\"א ומקבלת חכמה להשפיע לז\"א. אבל לא לצורך עצמה, כי הבינה מטבעה בע\"ס דאו\"י, הוא אור החסדים לבד, בסו\"ה כי חפץ חסד הוא. ואין לה ענין לעלות לראש א\"א להזדווג שם עם החכמה, אלא הז\"א העולה אל הבינה, מעורר אותה להשפיע חכמה בשבילו."],[8,"","הרי שאין הבינה מתיחדת עם החכמה אלא בכח הז\"א ובשביל הז\"א, וז\"ש \u0003וביה אתייחדן. והוא נטיל כלא\u0004 והז\"א נוטל הכל. כי גם אור החכמה שהבינה נוטלת בעד הז\"א, אינו מתגלה כלל במקום הבינה, אלא רק במקום הז\"א מחזה ולמטה, כמ\"ש במקומו. הרי שהז\"א הוא הנוטל לכל המוחין הללו, ולא העליונים ממנו."],[8,"","וז\"ש, \u0003והיה אם שמוע, כלילו דתרין סטרין דאתאחדת בהו כנסת ישראל, גבורה דלתתא\u0004: כי פרשת \u0003שמע\u0004 ה\"ס הז\"א \u0003ואו\u0004 דהוי\"ה, וה\"ס \u0003היחוד העליון\u0004 (המובא לעיל אות ר\"ז בפקודא תליתאה) שבו מגולה סוד האהבה בסטרא דטיבו לבד, (כמ\"ש באות ר\"ה בד\"ה ועם כל דא. ע\"ש). שזהו פרשת \u0003ואהבת\u0004, שכולה אהבה ואין בפרשה זו בחינת דין כלל."],[8,"","אבל פרשה רביעאה \u0003והיה אם שמוע\u0004, היא בחינת \u0003ה\"ת\u0004 דהוי\"ה שהיא הנוקבא דז\"א הכלולה בו, כנ\"ל, שהיא גבורה שבדעת דז\"א, ובה מתגלית האהבה בתרין סטרין \u0003הן בסטרא דטיבו והן בסטרא דדינא קשיא\u0004, (כמ\"ש באות ר\"ו בד\"ה כדין מה דהוית יבשה אתעבידת ארץ, עש\"ה). וע\"כ יש בפרשת \u0003והיה אם שמוע\u0004 הן \u0003אהבה מסטרא דטיבו\u0004 עד הפסוק \u0003השמרו לכם, והן סטרא דדינא קשיא\u0004 מן השמרו לכם והלאה."],[8,"","וז\"ש \u0003והיה אם שמוע כלילו דב' סטרין\u0004 שיש בה סטרא דטיבו וסטרא דדינא קשיא \u0003דאתאחדת בהו כנסת ישראל\u0004 שהוא \u0003היחודא תתאה דבשכמל\"ו\u0004 שהנוקבא דז\"א הנקראת כנסת ישראל מתיחדת בהו, (כנ\"ל בד\"ה מה דהוית יבשה אתעבידת ארץ)."],[8,"גבורה דלתתא","כלומר אין זו הנוקבא עצמה ממש, אלא גבורה שלמטה, שבמוח הדעת, כנ\"ל. ודא \u0003ה' בתראה דנטלא לון ואתכלילת מנהון\u0004 כי הגבורה שבדעת היא \u0003ה'\u0004 תתאה דשם הוי\"ה, שהיא נוטלת כל המוחין שב\u0003יחודא עלאה דשמע ישראל\u0004 ונכללת מהם. כי רק בה נשלמים המוחין, כי בה המקום לגלות \u0003האהבה בתרין סטרין\u0004, משום שבחינת דינא קשיא המשלים לאהבה אינה נמצאת למעלה ממנה. כנ\"ל."],[8,"ועל דא ראשך עליך ככרמל אלין תפילין דרישא","וע\"כ הכתוב \u0003ראשך עליך ככרמל\u0004 רומז על תפילין של ראש. כי אחר שהז\"א מתלבש בכל אלו ד' המוחין המרומזין בד' הפרשיות, שהם ג' אותיות צל\"ם, כנ\"ל, נבחן שראשו כמו \u0003כרמל\u0004, נוטריקון \u0003כר מלא\u0004, מכל טוב."]],[[0,"","מִצְוָה תְּשִׁיעִית - לָחֹן אֶת הָעֲנִיִּים וְלָתֵת לָהֶם טֶרֶף, שֶׁכָּתוּב נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ. נַעֲשֶׂה אָדָ\"ם - מְשֻׁתָּף, כְּלָל שֶׁל זָכָר וּנְקֵבָה. בְּצַלְמֵנוּ - עֲשִׁירִים. כִּדְמוּתֵנוּ - עֲנִיִּים."],[1,"","שֶׁהֲרֵי מִצַּד הַזָּכָר עֲשִׁירִים, וּמִצַּד הַנְּקֵבָה עֲנִיִּים. כְּמוֹ שֶׁהֵם בְּשֻׁתָּפוּת אַחַת וְזֶה חָס עַל זֶה, וְזֶה נוֹתֵן לָזֶה וְגוֹמֵל לוֹ חֶסֶד, כָּךְ צָרִיךְ אָדָם לְמַטָּה שֶׁיִּהְיוּ עָשִׁיר וְעָנִי בְּחִבּוּר אֶחָד, וְלָתֵת זֶה לָזֶה וְלִגְמֹל חֶסֶד זֶה לָזֶה."],[2,"","וְיִרְדּוּ בִדְגַת הַיָּם וְגוֹ' - הַסּוֹד שֶׁלָּנוּ רָאִינוּ בְּסִפְרוֹ שֶׁל שְׁלֹמֹה הַמֶּלֶךְ, שֶׁכָּל מִי שֶׁחָס עַל הָעֲנִיִּים בִּרְצוֹן הַלֵּב, לֹא מִשְׁתַּנָּה דְמוּתוֹ לְעוֹלָם מִדְּמוּתוֹ שֶׁל אָדָם הָרִאשׁוֹן. וְכֵיוָן שֶׁדְּמוּתוֹ שֶׁל אָדָ\"ם נִרְשְׁמָה בּוֹ, הוּא שׁוֹלֵט עַל כָּל הַבְּרִיּוֹת שֶׁל הָעוֹלָם בְּאוֹתָהּ הַדְּמוּת. זֶהוּ שֶׁכָּתוּב (בראשית ט) וּמוֹרַאֲכֶם וְחִתְּכֶם יִהְיֶה עַל כָּל חַיַּת הָאָרֶץ וְגוֹ'. כֻּלָּם זָעִים וּפוֹחֲדִים מֵאוֹתָהּ הַדְּמוּת שֶׁנִּרְשְׁמָה בּוֹ, מִשּׁוּם שֶׁזּוֹ הִיא מִצְוָה מְעֻלָּה שֶׁיִּתְעַלֶּה בֶּן אָדָם בִּדְמוּתוֹ שֶׁל אָדָם עַל כָּל שְׁאָר הַמִּצְווֹת."],[3,"","מִנַּיִן לָנוּ מִנְּבוּכַדְנֶצַּר (הרשע). אַף עַל גַּב שֶׁחָלַם אֶת הַחֲלוֹם הַהוּא - כָּל זְמַן שֶׁהָיָה מְרַחֵם עַל הָעֲנִיִּים, לֹא שָׁרָה עָלָיו חֲלוֹמוֹ. כֵּיוָן שֶׁהִטִּיל עַיִן רָעָה שֶׁלֹּא לְרַחֵם עַל עֲנִיִּים, מַה כָּתוּב (דניאל ד) עוֹד הַדָּבָר בְּפִי הַמֶּלֶךְ וְגוֹ'. מִיָּד הִשְׁתַּנְּתָה דְמוּתוֹ וְנִטְרַד מִבְּנֵי הָאָדָם. וּמִשּׁוּם כָּךְ נַעֲשֶׂה אָדָם. כָּתוּב כָּאן עֲשִׂיָּה, וְכָתוּב שָׁם (רות ב) שֵׁם הָאִישׁ אֲשֶׁר עָשִׂיתִי עִמּוֹ הַיּוֹם בֹּעַז."],[4,"","מִצְוָה עֲשִׂירִית - לְהַנִּיחַ תְּפִלִּין וּלְהַשְׁלִים אֶת עַצְמוֹ בַּדְּמוּת הָעֶלְיוֹנָה, שֶׁכָּתוּב (בראשית א) וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ. פָּתַח וְאָמַר, (שיר ז) רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל. הַפָּסוּק הַזֶּה הֶעֱמַדְנוּהוּ וְנִתְבָּאֵר. אֲבָל רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל - זֶה הָרֹאשׁ הָעֶלְיוֹן, תְּפִלִּין שֶׁל רֹאשׁ, שְׁמוֹ שֶׁל הַמֶּלֶךְ הַקָּדוֹשׁ יהוה בְּאוֹתִיּוֹת רְשׁוּמוֹת, וְכָל אוֹת וְאוֹת פָּרָשָׁה אַחַת, הַשֵּׁם הַקָּדוֹשׁ חָקוּק בְּסִדּוּר שֶׁל הָאוֹתִיּוֹת כָּרָאוּי. וְשָׁנִינוּ, (דברים כח) כִּי שֵׁם ה' נִקְרָא עָלֶיךְ וְיָרְאוּ מִמֶּךָּ - אֵלּוּ תְפִלִּין שֶׁל רֹאשׁ, שֶׁהֵם שֵׁם קָדוֹשׁ בְּסִדּוּר שֶׁל אוֹתִיּוֹתָיו."],[5,"","פָּרָשָׁה רִאשׁוֹנָה - (שמות יג) קַדֶּשׁ לִי כָל בְּכוֹר, זוֹ י' שֶׁהִיא קֹדֶשׁ, הַבְּכוֹר שֶׁל כָּל הַקְּדָשִׁים הָעֶלְיוֹנִים. פֶּטֶר כָּל רֶחֶם - בַּשְּׁבִיל הַדַּק הַהוּא שֶׁיּוֹרֵד מִיּוֹ\"ד, שֶׁהוּא פּוֹתֵחַ אֶת רַחְמָהּ לַעֲשׂוֹת פֵּרוֹת וְאִבִּים כָּרָאוּי, וְהוּא קֹדֶשׁ עֶלְיוֹן."],[6,"","הַפָּרָשָׁה הַשְּׁנִיָּה - (שם) וְהָיָה כִּי יְבִאֲךְ, זוֹ ה' הַהֵיכָל שֶׁנִּפְתָּח רַחְמָהּ מִתּוֹךְ יוֹ\"ד בַּחֲמִשִּׁים פְּתָחִים, אַכְסַדְרָאוֹת וַחֲדָרִים הַנִּסְתָּרִים שֶׁבּוֹ. שֶׁהַפֶּטֶר הַהוּא שֶׁעָשָׂה יוֹ\"ד בַּהֵיכָל הַזֶּה לִשְׁמֹעַ בָּהּ קוֹל שֶׁיּוֹצֵא מִתּוֹךְ הַשּׁוֹפָר הַזֶּה, מִשּׁוּם שֶׁהַשּׁוֹפָר הַזֶּה הוּא נִסְתָּר בְּכָל הַצְּדָדִים, וּבָא יוֹ\"ד וּפָתַח אוֹתוֹ לְהוֹצִיא מִמֶּנּוּ קוֹל. וְכֵיוָן שֶׁפָּתַח אוֹתוֹ, תָּקַע לוֹ וְהוֹצִיא מִמֶּנּוּ קוֹל לְהוֹצִיא עֲבָדִים לַחֵרוּת."],[7,"","וּבִתְקִיעַת הַשּׁוֹפָר הַזֶּה יָצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, וְכָךְ עָתִיד בְּפַעַם אַחֶרֶת בְּסוֹף הַיָּמִים. וְכָל גְּאֻלָּה בָּאָה מִן הַשּׁוֹפָר הַזֶּה, וּמִשּׁוּם כָּךְ יֵשׁ יְצִיאַת מִצְרַיִם בַּפָּרָשָׁה הַזּוֹ, שֶׁהֲרֵי מֵהַשּׁוֹפָר הַזֶּה בָּא בַּכֹּחַ שֶׁל יוֹ\"ד שֶׁפּוֹתֵחַ רַחְמָהּ וּמוֹצִיא קוֹלוֹ לִגְאֻלַּת הָעֲבָדִים. וְזוֹ ה, הָאוֹת הַשְּׁנִיָּה שֶׁל הַשֵּׁם הַקָּדוֹשׁ."],[8,"","פָּרָשָׁה שְׁלִישִׁית - סוֹד הַיִּחוּד שֶׁל שְׁמַע יִשְׂרָאֵל (דברים ו). זוֹ וָא\"ו שֶׁכּוֹלֶלֶת הַכֹּל וּבָהּ הַיִּחוּד שֶׁל הַכֹּל, וּבוֹ מִתְיַחֲדִים וְהוּא נוֹטֵל הַכֹּל. הַפָּרָשָׁה הָרְבִיעִית - (שם ה) וְהָיָה אִם שָׁמוֹעַ, כְּלָלוּת שֶׁל שְׁנֵי צְדָדִים שֶׁנֶּאֱחֶזֶת בָּהֶם כְּנֶסֶת יִשְׂרָאֵל, הַגְּבוּרָה שֶׁלְּמַטָּה. וְזוֹ ה' הָאַחֲרוֹנָה שֶׁנּוֹטֶלֶת אוֹתָם וְנִכְלֶלֶת מֵהֶם."]]],[["וּתְפִלִּין אַתְוָון דִּשְׁמָא קַדִּישָׁא אִנּוּן מַמָּשׁ. וְעַל דָּא רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל אִלֵּין תְּפִלִּין (בא מ\"ג א', ואתחנן רס\"ד א) דְּרֵישָׁא). (שיר השירים ז׳:ו׳) וְדַלַּת רֹאשֵׁךְ הַהִיא תְּפִלָּה שֶׁל יַד דְּאִיהִי מִסְכְּנָא לְגַבֵּי עֵילָא אוּף הָכִי שְׁלִימוּ אִית לָהּ כְּגַוְונָא דִּלְעֵילָא.","(שיר השירים ז׳:ו׳) מֶלֶךְ אָסוּר בָּרְהָטִים קָשִׁיר אִיהוּ וְאָחִיד בְּאִנּוּן בָּתֵּי לְאִתְאַחֲדָא בְּהַהוּא שְׁמָא קַדִּישָׁא כְּדְקָא יְאוּת. וְעַל דָּא מָאן דְּאִתְתַּקַּן בְּהוּ אִיהוּ הֲוִי בְּצֶלֶם אֱלֹהִים. מָה אֱלהִים אִתְיַחֲדָא בֵּיהּ שְׁמָא קַדִּישָׁא, אַף הוּא אִתְיַחַד בֵּיהּ שְׁמָא קַדִּישָׁא כְּדְקָא יְאוּת. זָכָר וּנְקֵבָה בָּרָא אוֹתָם. תְּפִלִּין דְּרֵישָׁא וּתְפִלָּה שֶׁל יַד וְכֹלָא חָד.","פִּקּוּדָא חַדְסַר לְעַשְׂרָא מַעַשְׂרָא דְאַרְעָא. הָכָא אִית תְּרֵין פִּקּוּדִין. חַד לְעַשְׂרָא מַעַשְׂרָא דְאַרְעָא. וְחַד בִּכּוּרֵי דְּפֵירֵי אִילָנָא. דִּכְתִיב (בראשית א׳:כ״ט) הִנֵּה נָתַתִי לָכֶם אֶת כָּל עֵשֶׂב זוֹרֵעַ זֶרַע אֲשֶׁר עַל פְּנֵי כָל הָאָרֶץ. כְּתִיב הָכָא הִנֵּה נָתַתִּי. וּכְתִיב הָתָם (במדבר י״ח:כ״א) וְלִבְנֵי לֵוִי הִנֵּה נָתַתִּי אֶת כָּל מַעֲשֵׂר בְּיִשְׂרָאֵל. וּכְתִיב, (ויקרא כ״ז:ל׳) וְכָל מַעֲשַׂר הָאָרֶץ מִזֶּרַע הָאָרֶץ מִפְּרִי הָעֵץ לַה' הוּא.","פִּקּוּדָא תְּרֵיסַר לְאַיְיתָאָה בִּכּוּרֵי דְאִילָנָא דִּכְתִיב, (בראשית א׳:כ״ט) וְאֶת כָּל הָעֵץ אֲשֶׁר בּוֹ פְּרִי עֵץ זוֹרֵעַ זָרַע. כָּל מָאן דְּאִתְחַזֵּי לִי, לְכוֹן אֲסִירָא לְמֵיכַל. אַתִּיר לוֹן וְיָהַב לוֹן כָּל מַעַשְׂרָא דִילֵיהּ וּבִכּוּרִין דְּאִילָנִין. נָתַתִּי לָכֶם, לָכֶם וְלא לְדָרִין דְּבַתְרֵיכוֹן.","פִּקּוּדָא תְּלֵיסַר. לְמֶעְבַּד פּוּרְקָנָא לִבְרֵיהּ לְקַשְׁרָא לֵיהּ בַּחַיִּין. דִּתְרֵין מְמַנָּן נִינְהוּ חַד דְּחַיִּין וְחַד דְּמוֹתָא וְקַיָּימִין עֲלֵיהּ דְּבַּר נָשׁ, וְכַד יִפְרוֹק בַּר נָשׁ לִבְרֵיהּ, מִידָא דְהַהוּא מוֹתָא פָּרִיק לֵיהּ, וְלָא יָכִיל לְשַׁלְטָאָה עֲלֵיהּ. וְרָזָא דָא וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה בִּכְלַל. וְהִנֵּה טוֹב דָּא מַלְאַךְ חַיִּים. מְאֹד דָּא מַלְאַךְ הַמָּוֶת. וְעַל דָּא בְּהַהוּא פּוּרְקָנָא אִתְקַיֵּים דָּא דְּחַיִּים וְאִתְחַלָּשׁ הַהוּא דְּמָוֶת. בְּפוּרְקָנָא דָא קָנֵי לֵיהּ חַיִּים כְּמָה דְּאִתְמָּר. וְהַהוּא סִטְרָא בִּישָׁא שְׁבַק לֵיהּ וְלָא אָחִיד בֵּיהּ:","פִּקּוּדָא אַרְבֵּיסַר לְנַטְרָא יוֹמָא דְשַׁבַּתָּא, דְּאִיהוּ יוֹמָא דְנַיְיחָא מִכָּל עוֹבָדֵי בְּרֵאשִׁית. הָכָא כְּלִילָן תְּרֵין פִּקּוּדִין. חַד נְטִירָא דְּיוֹם הַשַּׁבָּת. וְחַד לְקַדְשָׁא הַהוּא יוֹמָא בְּקִדּוּשֵׁיהּ. לְנַטְרָא יוֹמָא דְּשַׁבַּתָּא כְּמָא דְּאַדְכַּרְנָא וְאַתְעַרְנָא עֲלַיְיהּוּ דְּאִיהוּ יוֹמָא דְנַיְיחָא לְעָלְמִין. וְכָל עֲבִידָן בֵּיהּ אִשְׁתַּכְלְלוּ וְאִתְעֲבִידוּ עַד דְּאִתְקַדַּשׁ יוֹמָא.","כֵּיוָן דְּאִתְקַדַּשׁ יוֹמָא אִשְׁתָּאַר בְּרִיאָה דְרוּחִין דְּלָא אִתְבְּרֵי לוֹן גּוּפָא. וְכִי לָא הֲוָה יָדַע קוּדְשָׁא בְּרִיךְ הוּא לְאַעְכָּבָא לְקַדְּשָׁא יוֹמָא עַד דְּיִתְבְּרוּן גּוּפִין לְהָנִי רוּחִין. אֶלָא אִילָנָא דְדַעַת טוֹב וְרָע אַתְעַר הַהוּא סִטְרָא אָחֳרָא דְרַע וּבָעָא לְאִתְתַּקְּפָא בְּעָלְמָא וְאִתְפָּרְשׁוּ כַּמָּה רוּחִין בְּכַמָּה זַיְינִין לְאִתְתַּקְּפָא בְּעָלְמָא בְּגוּפִין.","כֵּיוָן דְּחֲמָא קוּדְשָׁא בְּרִיךְ הוּא כָּךְ, אַתְעַר מִגּוֹ אִילָנָא דְחַיֵּי נְשִׁיבָא דְרוּחָא וּבָטַשׁ בְּאִילָנָא אָחֳרָא וְאַתְעַר סִטְרָא אָחֳרָא דְטוֹב וְאִתְקַדַּשׁ יוֹמָא. דְּהָא בְּרִיאוּ דְּגוּפִין וְאִתְעָרוּ דְרוּחִין בְּסִטְרָא דְטוֹב אִיהוּ בְּהַאי לֵילְיָא, וְלָא בְּסִטְרָא אָחֳרָא.","וְאִלְמָלֵא אַקְדִּים סִטְרָא אָחֳרָא בְּהַאי לֵילְיָא עַד דְּלָא יַקְדִּים סִטְרָא דְטוֹב, לָא יָכִיל עָלְמָא לְמֵיקַם קַמַּיְיהוּ אֲפִילּוּ רִגְעָא חָדָא. אֲבָל אַסְוָותָא אַקְדִּים קוּדְשָׁא בְּרִיךְ הוּא דְּדָלִיג קַמֵּיהּ קִדּוּשָׁא דְיוֹמָא וְאַקְדִּים קַמֵּי סִטְרָא אָחֳרָא וְאִתְקְיַּים עָלְמָא. וּמַה דְּחֲשִׁיב סִטְרָא אָחֳרָא לְאִתְבְּנֵי בְּעָלְמָא לְאִתְתַּקְּפָא, אִתְבְּנֵי בְּהַאי לֵילְיָא סִטְרָא דְטוֹב וְאִתְתַּקַּף וְאִתְבְּנוּן גּוּפִין וְרוּחִין קַדִּישִׁין בְּהַאי לֵילְיָא מִסִּטְרָא דְטוֹב. וּבְגִין כָּךְ עוֹנָתָן דְּחַכִּימִין דְּיָדְעֵי דָא מִשַּׁבָּת לְשַׁבָּת."],[[0,"","רמב) \u0003ותפילין אתוון דשמא\u0004 וכו': והתפלין הן אותיות השם הקדוש ממש. וע\"כ, ראשך עליך ככרמל, הוא, אלו התפילין של ראש. ודלת ראשך, היא אותה תפלה של יד, שהיא מלכות, שהיא עניה כלפי מעלה, ז\"א, וגם כן יש לה שלמות כעין של מעלה."],[0,"","פירוש, המלכות ה\"ס תפלה של יד, ואיהי \u0003מסכנא לגבי עילא\u0004 שהיא עניה כלפי עלמא עלאה. שהרי עלמא עילאה בינה אשתתפא בה, (כנ\"ל בפקודא תשיעאה), בכדי להשלימה, \u0003אוף הכי שלימו אית לה כגוונא דלעילא\u0004 אעפ\"כ, יש לה שלימות כעין של מעלה. כי היא מקבלת עתה כל אותה שלימות של עלמא עילאה בינה. והיינו ע\"י יחודא תתאה דבשכמל\"ו שנתבאר לעיל בפרשה רביעאה דז\"א, וכיון שאינה נוק' שבגופו דז\"א, אלא שהיא נוקבא דז\"א הנפרדת, ע\"כ היא נוטלת ממנו כל ד' הפרשיות שהם חו\"ב חו\"ג דז\"א, להיותה פרצוף נבדל ושלם, אלא שהם בבית אחד, ולא בד' בתים מיוחדים כמו התפילין דז\"א."],[0,"","והטעם הוא, כי פרשה ה\"ס האור, והבית שלה ה\"ס הכלי. ונודע שמכל זווג נמשך אור וכלי. ולפיכך הז\"א, שד' הפרשיות, שהם ד' המוחין שלו חו\"ב חו\"ג, נמשכים לו בארבעה זווגים, יש לו ג\"כ ד' בתים, לכל פרשה בית מיוחד. אבל הנוק', שבה עצמה אין שום זווג, אלא שמקבלת כל ד' המוחין, שהן ד' הפרשיות, בזווג אחד מן הז\"א, לכן אין לה, אלא בית אחד לכל ד' הפרשיות."],[1,"","רמג) \u0003מלך אסור ברהטים\u0004: היינו שהוא קשור ואחוז באותם הבתים של התפילין, כדי להתאחד באותו השם הקדוש כראוי. ועל כן, מי שהוא מתתקן בהן, הוא נמצא בצלם אלקים. מה אלקים, מתיחד בו השם הקדוש, אף הוא מתיחד בו השם הקדוש כראוי. זכר ונקבה ברא אותם. היינו תפילין של ראש ותפלה של יד. והכל אחד."],[1,"מלך אסור ברהטים",", פירושו, שהז\"א קשור ומאוחד בבתים האלו. פירוש כי הבתים שבהם מונחים הפרשיות נקראים \u0003רהטים\u0004, כי \u0003רהטים\u0004 הם שקתות המים שהצאן שותה מהם, וכן המוחין שהם מימי החכמה ומימי החסדים קשורים ומכוסים בכלים שלהם שהם הבתים, וע\"כ מכונים הבתים בשם רהטים"],[1,"","וז\"ש \u0003קשיר איהו ואחיד באינון בתי לאתאחדא בההוא שמא קדישא כדקא יאות הוא קשור\u0004 ואחוז בבתים האלו, כדי להתיחד בשם הקדוש כראוי. כי סוד הבתים הם בחינת תנה\"י דתבונה, הנקרא \u0003ד'\u0004 גדולה דאחד, שעליה נאמר \u0003ותראה היבשה\u0004 (כנ\"ל בפקודא תליתאה). ונתבאר שם שע\"י שנגלה בז\"א האי יבשה, הוא יכול אח\"כ להשפיע את המוחין לנוקבא בסוד \u0003מה דהוית יבשה אתעבידת ארץ למעבד פירין ואבין ולנטעא אילנין\u0004, הרי שאלמלא הבתים שלו, שהם מבחינת היבשה הזו, לא היה יכול הז\"א לתת המוחין לנוקבא שלו."],[1,"","וז\"ש \u0003קשיר איהו ואחיד באינון בתי\u0004 שהז\"א קשור ואחוז בבתים של הפרשיות הבאות מבחינת היבשה \u0003לאתאחדא בההוא שמא קדישא כדקא יאות\u0004 כדי שיוכל להתיחד ולהשפיע לשמא קדישא שהיא הנוקבא, כדקא יאות, בסוד הגילוי \u0003דמה דהוית יבשה אתעבידת ארץ למעבד פירין\u0004 וכו' עש\"ה. וז\"ס \u0003מלך אסור ברהטים\u0004."],[1,"","וז\"ש \u0003ועל דא מאן דאתתקן בהו איהו הוה בצלם אלהים\u0004: וע\"כ מי שנתקן בד' הפרשיות הללו, יש לו \u0003צלם אלקים\u0004. דהיינו האדם התחתון המניח תפילין, הוא ממשיך המוחין חו\"ב חו\"ג מהזו\"ן שהם נק' \u0003צל\"ם\u0004. כי חו\"ב נקראים \u0003ם' ל'\u0004. וחו\"ג נקראים \u0003צ'\u0004. שז\"ס צלם אלקים. \u0003מה אלקים אתיחדא ביה שמא קדישא אף הוא אתיחד ביה שמא קדישא כדקא יאות\u0004 מה אלהים שהוא הבינה נתייחד בה השם הקדוש שהוא הנוקבא, כן נתייחד בו באדם השם הקדוש כראוי דהיינו כמ\"ש לעיל."],[1,"","וז\"ש, \u0003זכר ונקבה ברא אותם, תפילין דרישא ותפלה של יד וכלא חד\u0004: הכתוב זכר ונקבה ברא אותם, קאי אל תפילין של ראש ועל תפילין של יד, והכל אחד. פירוש כי \u0003ויברא אלהים את האדם בצלמו\u0004, היינו המוחין חו\"ב חו\"ג הנק' צל\"ם כנ\"ל. ויש בהם זכר ונקבה שהם צל\"ם דז\"א וצלם דנוקבא, הנקראים תפילין של ראש ותפילין של יד."],[2,"","רמד) \u0003פקודא חדסר\u0004 וכו': המצוה האחת עשרה, היא לעשר מעשר הארץ. כאן יש ב' מצות, אחת לעשר מעשר הארץ. ואחת, להביא ביכורי פירות האילן, שכתוב, הנה נתתי לכם את כל עשב זורע זרע אשר על פני כל הארץ. כתוב כאן הנה \u0003נתתי\u0004, וכתוב שם ולבני לוי הנה \u0003נתתי\u0004 את כל מעשר בישראל, וכתוב, וכל מעשר הארץ מזרע הארץ מפרי העץ לה' הוא."],[2,"","פירוש. דורש המקרא \u0003הנה נתתי לכם את כל עשב זורע זרע\u0004 על \u0003מעשר הארץ\u0004 שהותר לאדם הראשון, ואת המקרא \u0003ואת כל העץ אשר בו פרי העץ זורע זרע,\u0004 על \u0003בכורי דאילנא\u0004 שהותרו לאדם הראשון, (כדלהלן בפקודא תריסר). ויש להבין א\"כ איזה ענין יש למקראות אלו לחייב אותנו במעשר ובכורים להפריש לה' ולא לאכול אותם. שהוא ההיפוך מהמשמעות."],[2,"","אמנם יש כאן ענין עמוק כי ענין האכילה ה\"ס בירור הנצוצין הקדישין מתוך הקליפות, שעל ידי האכילה מתחברין הנצוצין הקדישין שבמאכל אל נפש האדם לבשר מבשרו, והפסולת שבמאכל יוצאת לחוץ מגופו. עד שבמשך שני חייו הולך ומלקט כל הנצוצין הקדישין השייכין להשלים את נפש האדם, שבלעדם הוא חסר שלימותו. והנה בזוהר (לך לך דף ק\"א אות ש') אומר, כי לאדם הראשון לא ניתן לאכול בשר, דכתיב \u0003הנה נתתי לכם את כל עשב זורע זרע\u0004 וגו' \u0003לכם יהיה לאכלה\u0004, ודריש ולא יתיר מזה. דהיינו ולא בשר. אלא \u0003כיון דחטא ויצה\"ר אשתאיב בגופא דיליה\u0004 נאמר לנח \u0003כירק עשב נתתי לכם את כל\u0004, דהיינו אפילו בשר. ע\"ש."],[2,"","וביאור הדברים, כי אדה\"ר נברא בשלימות גדולה, וכבר נבררה בו כל השלימות הראויה מצד בחינת בעלי חיים כמ\"ש \u0003ויצר ה' אלהים מן האדמה כל חית השדה\u0004 וגו' \u0003וכל אשר יקרא לו האדם נפש חיה הוא שמו\u0004, שפירושו, שהשיג כל שם ושם מבעלי חיים על מתכונתו, כי היו כבר נבררים לו בכל שלימותם, (כמ\"ש בתקוני זוהר תיקון נ\"ז ע\"ש) ולפיכך לא ניתנו לו בעלי חיים לברורים ע\"י אכילה, כי כבר היו נבררים לו ע\"י המאציל. ורק הדומם והצומח היו חסרי הברור, וע\"כ נתנו לו רק תבואת הארץ לאכול ולברר אותם ללקט מתוכם נצוצין קדישין החסרים להשלמתו. אלא אחר חטא עה\"ד, חזרו ונתקלקלו כל הברורים. וכמו שאברי נשמתו נשרו ונפלו לקליפות, כן נתקלקל עמו כל בעל חיים וצריכים לברור מחדש. ולפיכך נתנו לנח גם בעלי חיים לאכול ולברר אותם, וכן לדורות אחריו."],[2,"","והנה אדה\"ר נברא \u0003בצל\"ם אלהים\u0004, שהם המוחין הנ\"ל (המבוארים בפקודא עשיראה) בסוד \u0003ד' פרשיות התפילין\u0004. והם נשמה שלו, אמנם אחר שנולד בבחינת הנשמה הקדושה הזו, זכה ע\"י מעשים טובים לברר ולהעלות מ\"ן ולהשיג בחינת חי\"ה, ואח\"כ ביום השבת גם לבחינת יחידה (כי לא אבד הזהרא עלאה רק אחר השבת כנודע) ולפיכך הותרו לו \u0003המעשר והבכורים\u0004, ואדרבה ע\"י האכילה של \u0003המעשר והבכורים\u0004 זכה לברר ולהעלות מ\"ן, עד שזכה לחיה ויחידה."],[2,"","אמנם אחר החטא דעצה\"ד שחזרו ונתקלקלו כל הברורים ואשתאיב יצה\"ר בגופא. נאסר לנו \u0003המעשר והבכורים\u0004 מחמת יצה\"ר שבנו, מחשש שלא נפגם בקדושה עלאה שבהם, אלא שאנו מחוייבים ליתנם לכהנים וללוים, וכשאנו מקיימים עכ\"פ את המצות האלו \u0003דמעשר ובכורים\u0004 כמצוה עלינו, יהיה לנו כח להעלות מ\"ן ולהמשיך בחינת מוחין דחיה \u0003ביום השבת\u0004, על דרך שאדה\"ר המשיך ע\"י אכילתו בעצמו את \u0003המעשר והבכורים\u0004."],[2,"","וזה אמרו \u0003פקודא חדסר לעשרא מעשרא דארעא\u0004 כי אחר שהמשכנו בחינת אור נשמה ע\"י הנחת \u0003תפילין\u0004, יש לנו להעלות מ\"ן ע\"י ב' פקודין \u0003מעשר ובכורים\u0004, בכדי להמשיך מוחין דחיה. ונתבאר שאדה\"ר המשיך המוחין דחיה ע\"י אכילתו ה\u0003מעשר והבכורים\u0004 בעצמו, אבל אנחנו שאין אנו רשאים לאכול אותם מחמת היצה\"ר שבגוף שלנו, ניתנה לנו במקומו המצוה, ליתן אותם לכהנים וללוים, וע\"י זה ניתן גם לנו הכח להמשיך המוחין ההם. וזה שמביא ראיה שהכתוב מדבר ב\u0003מעשר ובכורים\u0004 דוקא, משום \u0003דכתיב הכא והנה נתתי\u0004 וגו' וכתיב \u0003ולבני לוי הנה נתתי\u0004, וכמו ששם מדבר במעשר כן הכא באדה\"ר מדבר במעשר. וכן יליף \u0003מפרי העץ לה'\u0004."],[3,"","רמה) \u0003פקודא תריסר\u0004 וכו': המצוה השתים עשרה, היא, להביא בכורי האילן, שכתוב, ואת כל העץ אשר בו פרי עץ זורע זרע. כל מה שראוי לי, אסור לכם לאכול. התיר להם ונתן להם כל המעשר שלו ובכורי האילן. שכתוב, נתתי \u0003לכם\u0004. לכם, ולא לדורות שאחריכם."],[3,"","ביאור הדברים, סובב על הפסוק שסיים בו את הפקודא חדסר, שהוא דכתיב \u0003וכל מעשר הארץ מזרע הארץ מפרי העץ לה' הוא\u0004, ואומר, כי הכא כתיב \u0003ואת כל העץ אשר בו פרי עץ זורע זרע\u0004, ויליף גזרה שוה משם, מה התם \u0003בכורים\u0004 אף כאן \u0003בכורים\u0004."],[3,"","ואומר \u0003כל מאן דאתחזי לי, לכון אסירא למיכל\u0004 כלומר דלאו דוקא \u0003מעשר\u0004 אלא גם לרבות \u0003בכורים\u0004 מפסוק הזה \u0003מפרי העץ לה' הוא\u0004, כי \u0003לה' הוא\u0004 משמע כל מה \u0003דאתחזי לי\u0004 דהיינו גם \u0003בכורי העץ\u0004, ומכאן הגזרה שוה שגם הכתוב דהכא \u0003ואת כל העץ אשר בו פרי עץ זורע זרע\u0004, מיירי ג\"כ ב\u0003בכורים\u0004. וז\"ש \u0003אתיר לון ויהיב לון כל מעשרא דיליה ובכורין דאילנין\u0004 התיר להם ונתן להם כל המעשר שלו ובכורי אילנות. כי יליף מג\"ש שהכתובים מיירי רק ב\u0003מעשר ובבכורים\u0004 כמבואר."],[3,"","ואל תתמה במה שהכתוב מ\u0003פרי העץ לה' הוא\u0004, נאמר בפקודא חדסר, ולא בפקודא דהכא. כי באמת כן ערבבם הזהר יחד תיכף בתחילת פקודא חדסר, שאומר שם \u0003הכא אית תרין פקודין\u0004. אלא שהמדפיס חלק אותם לשנים, ונמצא שחתך אותם באמצע, והניח הפסוק ד\u0003בכורים\u0004 בפקודא חדסר, והוא פשוט."],[3,"","ועוד דייק שהכתוב מדבר ב\u0003מעשר\u0004 וב\u0003בכורים\u0004, משום שכתוב \u0003נתתי לכם\u0004 דמשמע \u0003ולא לדרין דבתריכון\u0004 רק לכם נתתי לאכול ולא לדורות שלאחריכם. וא\"כ אי אפשר לומר שהכתוב מדבר בתבואת הארץ סתם, המותרת גם לנו לאכול, אלא שמדבר רק במה שאסור לנו לאכול מתבואת הארץ, שהוא בהכרח ה\u0003מעשר\u0004 וה\u0003בכורים\u0004."],[4,"","רמו) \u0003פקודא תליסר\u0004 וכו': המצוה השלש עשרה, היא לעשות פדיון לבנו לקשר אותו בחיים. כי שני ממונים הם, אחד על החיים, ואחד על המות. והם עומדים על האדם. וכשאדם פודה את בנו, פודה אותו מיד אותו הממונה על המות, ואינו יכול לשלוט עליו. וזה סוד, וירא אלקים את כל אשר עשה. זהו בכלל. \u0003והנה טוב\u0004, זהו מלאך החיים. \u0003מאד\u0004, זהו מלאך המות. ועל כן, באותו הפדיון מתקיים המלאך של חיים, ונחלש המלאך של מות. בפדיון זה קונה לו חיים, כאמור, ואותו הצד הרע עוזב אותו, ואינו נאחז בו."],[4,"","פירוש. יליף זה מהכתוב \u0003וירא אלהים את כל אשר עשה והנה טוב מאד\u0004, אשר \u0003והנה טוב, הוא מלאך חיים, מאד\u0004, זה \u0003מלאך המות\u0004. כי אז ביום הששי דמעשה בראשית, בסוד \u0003ה'\u0004 ד\u0003ה\u0004ששי, נתעלו העולמות מאד, שהז\"א עלה במקום א\"א והנוקבא במקום או\"א, והשיג אדה\"ר אז המוחין דחיה בשלימות שע\"י זה נתבטל כחו של מלאך המות, ולא עוד אלא שנמתק בבחינת \u0003מאד\u0004, כמו שיהיה בגמר התיקון בעת בלע המות לנצח, שע\"ז בא הרמז, \u0003והנה טוב דא מלאך חיים, מאד דא מלאך המות\u0004."],[4,"","אכן עתה אחר החטא דעצה\"ד, אין העולמות מתעלים כל כך בשעה ה' דערב שבת בסוד \u0003ה'\u0004 ד\u0003ה\u0004ששי, וע\"כ אנו צריכים למצוה מיוחדת, להמשיך לנו הכנה וכח לקבל אור החיה עכ\"פ ביום השבת, והיא המצוה דפדיון בכור אדם, משום \u0003בההוא פורקנא אתקיים דא דחיים, ואתחלש ההוא דמות\u0004 בפדיון זה מתקיים מלאך החיים ונחלש מלאך המות. דהיינו בדומה שנעשה אז לאדה\"ר ע\"י המאציל עצמו, בסוד \u0003ה'\u0004 ד\u0003ה\u0004ששי, שנעשה מלאך המות טוב מאד, כן סגולת מצוה זו דפדיון בכור."],[4,"","אלא לא לגמרי כמו אז, שלא היה לו למלאך המות אז שום כח, כי עתה אפשר ע\"י מצות פדיון בכור רק להחלישו בלבד, ולא להעבירו לגמרי. \u0003בפורקנא דא קני ליה חיים כמה דאתמר, וההוא סטרא בישא שבק ליה ולא אחיד ביה\u0004 כי בפדיון זה קונה לו החיים כמו שאמרו, והכח הרע ההוא עוזב אותו ואינו נאחז בו עוד. כלומר, אחר שנטהר לגמרי על ידי מצוה זו, ואין עוד שום אחיזה בו לכחות הרע, אז יכול לקנות לו החיים שה\"ס מוחין דחיה דיום השבת, כי כבר הוא טהור לגמרי מסטרא בישא דאשתאיב בגוף מחמת החטא דעצה\"ד, וע\"כ יש לו הכנה לקבל המוחין דיום השבת."],[5,"","רמז) \u0003פקודא ארביסר\u0004 וכו': המצוה הארבע עשרה, היא, לשמור את יום השבת, שהוא יום המנוחה מכל מעשה בראשית. כאן כלולות שתי מצות אחת, שמירת יום השבת. ואחת לקשור יום ההוא בקדושתו. כלומר להמשיך המוחין דחכמה הנקראים קדש, לשמור את יום השבת, היינו כמו שזכרתי והעירותי עליו, שהוא יום המנוחה לעולמות, וכל המעשים נשתכללו בו, ונעשו מטרם שנתקדש היום."],[5,"","פירוש, כי ביום השבת עולה הז\"א לא\"א והנוק' לאו\"א ובי\"ע עולים לישסו\"ת וזו\"ן דאצילות, ונמצאים נר\"ן של האדם עולים עמהם לאצילות והם מקבלים שם אור החיה. ולפיכך יש \u0003ב' פקודין חד לנטרא יומא דשבתא\u0004, דהיינו שלא יכשל בעשית מלאכה והוצאה מרשות לרשות וכו', כי אחר שהעולמות נפרדו לגמרי מהקליפות, עלינו להשמר שלא נגרום לקליפות כח לחזור ולהתערב ביום ההוא, אשר העושה מלאכה בו גורם שוב להתערבות הקליפות בקדושה. ופקודא ב' הוא \u0003לקשרא ההוא יומא בקדושיה\u0004 כראוי, דהיינו ע\"י תענוג שבת ממשיכים אור האצילות לנר\"ן שלנו, ואור האצילות הוא אור החכמה הנקרא \u0003קדש\u0004, ואנו מתקדשים על ידו."],[5,"","וז\"ש, \u0003לנטרא יומא דשבתא\u0004 וכו'. פירוש, כל הטרחות והמלאכות רמוזים בעבודות ובמלחמות עם הס\"א, המפרידים אותנו מלהתדבק בו ית'. וזה הכלל שבאתר דאית טרחותא תמן אית ס\"א. כי ע\"י המלחמות והטרחות אנו מבררים הנצוצין קדישין המובלעין תוך הס\"א, שכל ברור וברור נבחן למלאכה מיוחדת, שמתחילה נעשו כל הברורים האלו ע\"י המאציל עצמו, שהם כל המלאכות של הבורא ית' המובאים בששת ימי בראשית, וכאשר נגמרו כל הברורים כולם, נבחן שהם נשתכללו ובאו על תכליתם, ואז נתקדש השבת, שהוא יום המנוחה, שהרי כלה המלאכה ואין עוד מה לתקן. והבן זה (ועי' בזוהר חדש יתרו דף כ\"ה אות צ\"ז צ\"ח)."],[5,"","לכן סוד \u0003יום השבת\u0004 שהוא \u0003יום המנוחה\u0004 לכל העולמות, כי בכל שבת חוזרת ובאה אותה השלימות שהיתה בשבת בראשית, בסוד יום המנוחה, דהיינו שנפרדו כל הקליפות ונתקעו בתהומא רבא, והעולמות עולים לאצילות, שה\"ס היחוד הגמור. וצריכים אנו להמשיך קדושה זו, והוא נמשך לנו ע\"י ב' הפקודין \u0003זכירה ושמירה\u0004."],[6,"","רמח) \u0003כיון דאתקדש יומא\u0004 וכו': כיון שנתקדש היום, נשארה בריאת הרוחות שלא נברא להם גוף. שואל, וכי לא היה יודע הקב\"ה לעכב מלקדש היום, עד שיבראו גופים לאותם הרוחות. ומשיב, אלא עץ הדעת טוב ורע, היה מעורר את הצד האחר הרע, ובקש להתגבר בעולם. ונבדלו ויצאו הרבה רוחות בהרבה כלי זיין להתחזק ולהתלבש בגופים בעולם."],[6,"","פירוש, כיון שנתקדש היום, נשארה הבריאה של הרוחות, שעוד לא נבראו להן גופות. כלומר, נתקדש היום טרם שהספיק הקב\"ה לברוא גופות בשביל הרוחות הללו. וה\"ס \u0003אשר ברא אלהים לעשות\u0004 הנאמר ביום השבת, כי אומר \u0003אשר בו שבת מכל מלאכתו אשר ברא אלהים לעשות\u0004, שלכאורה אין לו פירוש, אם באמת גמר כל מלאכתו בתכלית הנרצה, א\"כ לא ברא לנו כלום \u0003לעשות\u0004, כי הכל כבר עשה וגמר מעצמו."],[6,"","אלא הסוד הוא שהשי\"ת עשה כל הברורים וגמר כל המלאכות, באופן שתהיה לנו האפשרות \u0003לעשות\u0004, דהיינו שנוכל לעשות ולגמור אותם על ידי העבודה שלנו בתורה ומצות. וענין השביתה נאמר רק על מה ששייך למלאכת המאציל. ומשמיענו הכתוב, כי השי\"ת כבר \u0003שבת מכל מלאכתו\u0004, עד כי לא חסר משהו מצדו ית', וכל זה \u0003אשר ברא אלהים\u0004 וגמר, הוא מאפשר גם לנו \u0003לעשות\u0004 ולגמור אותם מצדנו."],[6,"","וזה אמרו \u0003אשתאר בריאה דרוחין דלא אתברי לון גופא\u0004 שנשארו רוחות שלא הספיק הש\"י לעשות להן גופין עד שקדש השבת, ונשארו \u0003רוחין ערטילאין בלי גופא\u0004 והרוחות האלו בלי הגופין, הן הקליפות והמזיקין המביאים את האדם לידי חטא, (כמ\"ש להלן) ובכונה הניחם, כי עי\"ז נשארו לנו כח הבחירה ומקום עבודה בתורה ומצוות."],[6,"","ומקשה, וכי לא ידע הקב\"ה להתעכב מלקדש היום עד אחר שיבראו גופין לאותן הרוחות. ומתרץ, \u0003אלא אילנא דדעת טוב ורע אתער ההוא סטרא אחרא דרע ובעא לאתתקפא בעלמא\u0004, אלא עץ הדעת טו\"ר היה מעורר הסטרא אחרא ההוא של הרע, ובקש להתגבר בעולם. פירוש, כי המלכות נקראת עצה\"ד טוב ורע, (כנ\"ל אות קכ\"ג), \u0003זכי הא טוב לא זכי הא רע\u0004, ע\"ש הטעם. וכיון שחטא האדם בעצה\"ד, ונעשה לא זכי, ע\"כ נתעוררה בחינת הרע שבאילנא דדעת טו\"ר, ורצה הרע להתתקף בעולם. כלומר שרצה להתגבר על הטוב ולהתאחז בעולם, באופן שהטוב לא יוכל לעולם לנצח אותו."],[6,"","ואז \u0003ואתפרשו כמה רוחין בכמה זיינין לאתתקפא בעלמא בגופין\u0004 ויצאו להם כמה רוחות בכמה מיני כלי זיין בכדי להתתקף בעולם ולהתלבש בגופים. פירוש, ב' נקודין נתחברו במלכות, האחת ממותקת בבחינה בינה מדת הרחמים, והשניה היא מדת הדין שבמלכות עצמה. וכשהמלכות מתוקנת בקדושה כראוי להיות, אז נקודה דמדת הדין גניזא וטמירא, ונקודה דמדת הרחמים קיימא באתגליא (כנ\"ל אות קכ\"ג ובהסולם ע\"ש). ואז זכי האדם \u0003והא טוב\u0004. ואם חוטא האדם ופוגם בה, אז מתגלה מדת הדין שבמלכות, וניתן הכח לבעלי ההזק והחורבן לשלוט עליו, \u0003והא רע\u0004."],[6,"","ואם זוכה ונקודה דרחמים שולטת באתגליא, הוא זוכה להעלות במעשיו את המלכות עד הבינה עלאה, ומתגלים עליו הרחמים והמוחין עלאין. ואם אינו זוכה ומגלה מדת הדין שבה, הנה לא רק שפוגם במלכות, אלא פוגם גם בנקודת הבינה שנתחברה עם המלכות, כי הפכה מרחמים לדין מחמת התגלות הדין שבמלכות, כי כל המגולה היא השולטת."],[6,"","ולפיכך אחר החטא דעצה\"ד, הנה נתגלה כח הדין שבמלכות, שאז פגם גם בנקודת הבינה שבה, שהפכה למדת הדין, אשר נקודה זו דבינה היא כל אפשרות התיקון שיש במלכות, שמצדה היא נקראת \u0003טוב\u0004 בעת שנקודת הבינה באתגליא כנ\"ל, ועתה אחר שנפגמה גם נקודת הבינה ונהפכה לדין, חשב הסטרא אחרא, שעתה הגיעה שעתו להתגבר בעולם ולהתלבש בגופין של בני אדם דהיינו של אדה\"ר ובניו, כלומר, שגוף דס\"א יירש מקומו של הגוף דאדה\"ר, ולא תצויר עוד שום בחינת תיקון המלכות מסטרא דטוב. כי ראה שגם נקודת הבינה שבמלכות נתהפכה והיתה למדת הדין, ולא יצוייר שום תיקון עוד."],[6,"","וז\"ש, \u0003ואתפרשו כמה רוחין בכמה זיינין לאתתקפא בעלמא בגופין\u0004 הרבה רוחות יצאו להתתקף בעולם בכמה מיני כלי זיין, דהיינו כחות החורבן, להתלבש בגופין של בני אדם בעולם הזה ולשלוט כאן בקביעות, כי חשבו שאין מציל מידם, מחמת הפגם שעשה האדם בחטאו, בנקודת הרחמים שבמלכות כנ\"ל."],[7,"","רמט) \u0003כיון דחמא קב\"ה\u0004 וכו': כיון שהקב\"ה ראה את זה, העיר נשיבת הרוח מתוך עץ החיים שהוא ז\"א, ודפק בעץ אחר, שהוא המלכות, ונתעורר הצד האחר הטוב, ונתקדש היום. כי בריאת הגופים והתעוררות הרוחות בלילה הזה, של שבת, הן בצד הטוב, ולא בצד האחר."],[7,"","פירוש. כיון שראה הקב\"ה ששורת הדין הוא עם הס\"א, ויש להם כח להתלבש בגופין בעולם, אשר אז ימנע לגמרי בחינת תיקון עוד, (כנ\"ל בדיבור הסמוך) הנה אז \u0003אתער מגו אילנא דחיי נשיבו דרוחא\u0004 העיר נשיבת רוח החיים מתוך עץ החיים \u0003ובטש באילנא אחרא\u0004 ונזדווג עם העץ האחר, דהיינו עם המלכות, שהשפיע לה נשיבת רוח חיים, \u0003ואתער סטרא אחרא דטוב\u0004 ושוב נתעורר במלכות הצד השני שבה, דטוב, דהיינו כמו שהיה לפני החטא דאדה\"ר, בסוד \u0003זכי הא טוב\u0004, כנ\"ל. \u0003ואתקדש יומא\u0004 ונמשכה קדושת השבת בעולם."],[7,"","כלומר, שאע\"פ שמשורת הדין היה כח לס\"א להתלבש בגופין, עשה הקב\"ה לפנים משורת הדין, ולא השגיח כלל בפגם שעשה אדה\"ר, והזו\"ן, שהם \u0003עץ החיים ועץ הדעת טוב\u0004, נזדווגו יחד כלפני החטא, והמשיכו קדושת המוחין דיום השבת בעולם. וז\"ס שאמרו (זהר בראשית ב' דף צ\"ה אות קמ\"ח) \u0003שהאור ששימש בששת ימי בראשית לא נגנז רק לאחר השבת\u0004. וע\"י פעולה זו שנמשך יום השבת בעולם נתבטלה זממת הס\"א, להתלבש בגופין של בני אדם בעוה\"ז, ונשארו בבחי' רוחות בלי גופים. וע\"כ היה יכול האדם לעשות תשובה."],[7,"","כי בריאת הגופין והתעוררות הרוחות בלילה הזה הוא מהצד הטוב, ולא מהסטרא אחרא. כי פעולת הקב\"ה קיימת לנצחיות וכמו שבשבת בראשית לא השגיח כלל במה שכבר נפגם האדם בחטא דעצה\"ד, והזו\"ן נזדווגו, וקידש היום כמו לפני החטא, כי ביטל כל שליטתם דס\"א אע\"פ שהיה להם כח לשלוט, כנ\"ל, כן בכל השבתות דשתא אלפי שני, אע\"פ שהאדם עוד מלא מזוהמא דחוייא, כי עוד לא תיקן את החטא דעצה\"ד, מ\"מ כשהוא מזדווג ב\u0003ליל שבת\u0004, אין שום שליטה לכחות הרע עליו, והוא ממשיך בזווגו את הגוף והרוח של הולד הנולד, כאילו לא היה בו שום פגם מעצה\"ד, דהיינו כאילו כבר תיקן בעצמו את החטא דעצה\"ד."],[7,"","וזה אמרו \u0003דהא בריאו דגופין ואתערו דרוחין בסטרא דטוב איהו בהאי ליליא\u0004 כי אע\"פ שהאדם עצמו עוד לא זכי, אין בהאי לילה שום שליטה לס\"א עליו, ויוכל להמשיך גופין ורוחין, ע\"י זווגו, מסטרא דעץ הדעת טוב, ולא מס\"א, שהוא כח התיקון שהיה ב\u0003שבת בראשית\u0004, שהקב\"ה לא השגיח כלל ברע שהמשיך עליו אדה\"ר כנ\"ל."],[8,"","רנ) \u0003ואלמלא אקדים\u0004 וכו': ואם היה מקדים הצד האחר בלילה הזה, מטרם שיקדים הצד הטוב, לא היה יכול העולם לעמוד בפניהם אפילו רגע אחד, אבל הקב\"ה הקדים רפואה, וקדוש היום דלג לפניו, והקדים לבא לפני הצד האחר, ונתקיים העולם. ומה שחשב הצד האחר להבנות בעולם להתחזק, נבנה בלילה הזה הצד הטוב ונתחזק, שנבנו גופים ורוחות קדושים, בלילה הזה, מצד הטוב. ומשום זה עונתם של חכמים, היודעים זה, הוא משבת לשבת."]],[[0,"","וְהַתְּפִלִּין הֵם מַמָּשׁ אוֹתִיּוֹת הַשֵּׁם הַקָּדוֹשׁ. וְעַל כֵּן, רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל - אֵלּוּ תְּפִלִּין שֶׁל רֹאשׁ. וְדַלַּת רֹאשֵׁךְ - הַתְּפִלָּה הַהִיא שֶׁל יָד, שֶׁהִיא עֲנִיָּה כְּלַפֵּי מַעְלָה, אַף כָּךְ שְׁלֵמוּת יֵשׁ לָהּ כְּמוֹ שֶׁלְּמַעְלָה."],[1,"","מֶלֶךָ אָסוּר בָּרְהָטִים - הוּא קָשׁוּר וְאָחוּז בְּאוֹתָם הַבָּתִּים לְהֵאָחֵז בַּשֵּׁם הַקָּדוֹשׁ הַהוּא כָּרָאוּי. וְעַל כֵּן מִי שֶׁמִּתְתַּקֵּן בָּהֶם הוּא בְּצֶלֶם אֱלֹהִים. מָה בֵּאלֹהִים מִתְיַחֵד בּוֹ הַשֵּׁם הַקָּדוֹשׁ, אַף הוּא מִתְיַחֵד בּוֹ הַשֵּׁם הַקָּדוֹשׁ כָּרָאוּי. זָכָר וּנְקֵבָה בָּרָא אֹתָם. תְּפִלִּין שֶׁל רֹאשׁ וּתְפִלָּה שֶׁל יָד, וְהַכֹּל אֶחָד."],[2,"","מִצְוָה אַחַת עֶשְׂרֵה - לְעַשֵּׂר מַעְשַׂר הָאָרֶץ. כָּאן יֵשׁ שְׁתֵּי מִצְווֹת - אַחַת לְעַשֵּׂר מַעֲשֵׂר שֶׁל הָאָרֶץ, וְאַחַת בִּכּוּרִים שֶׁל פֵּרוֹת הָאִילָן, שֶׁכָּתוּב (בראשית א) הִנֵּה נָתַתִּי לָכֶם אֶת כָּל עֵשֶׂב זרֵעַ זֶרַע אֲשֶׁר עַל פְּנֵי כָל הָאָרֶץ. כָּתוּב כָּאן הִנֵּה נָתַתִּי, וְכָתוּב שָׁם (במדבר יח) וְלִבְנֵי לֵוִי הִנֵּה נָתַתִּי כָּל מַעֲשֵׂר בְּיִשְׂרָאֵל, וְכָתוּב (ויקרא כז) וְכָל מַעְשַׂר הָאָרֶץ מִזֶּרַע הָאָרֶץ מִפְּרִי הָעֵץ לַה' הוּא."],[3,"","מִצְוָה שְׁתֵּים עֶשְׂרֵה - לְהָבִיא בִּכּוּרֵי הָאִילָן, שֶׁכָּתוּב (בראשית א) וְאֶת כָּל הָעֵץ אֲשֶׁר בּוֹ פְרִי עֵץ זֹרֵעַ זָרַע. כָּל מַה שֶּׁרָאוּי לִי, לָכֶם אָסוּר לְמַאֲכָל. הִתִּיר לָהֶם וְנָתַן לָהֶם כָּל הַמַּעֲשֵׂר שֶׁלּוֹ וּבִכּוּרֵי הָאִילָנוֹת. נָתַתִּי לָכֶם - לָכֶם וְלֹא לַדּוֹרוֹת שֶׁאַחֲ רֵיכֶם."],[4,"","מִצְוָה שְׁלֹשׁ עֶשְׂרֵה - לַעֲשׂוֹת פִּדְיוֹן לִבְנוֹ לִקְשֹׁר אוֹתוֹ בַּחַיִּים. שֶׁשְּׁנֵי מְמֻנִּים הֵם, אֶחָד שֶׁל חַיִּים וְאֶחָד שֶׁל מָוֶת, וְעוֹמְדִים עַל הָאָדָם. וּכְשֶׁיִּפְדֶּה הָאִישׁ אֶת בְּנוֹ, מִיָּד הַמָּוֶת הַהוּא הוּא פּוֹדֶה אוֹתוֹ, וְלֹא יָכוֹל לִשְׁלֹט עָלָיו. וְזֶה סוֹד שֶׁל וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה, בִּכְלָל, וְהִנֵּה טוֹב - זֶה מַלְאַךְ חַיִּים, מְאֹד - זֶה מַלְאַךְ הַמָּוֶת. וְעַל כֵּן בַּפִּדְיוֹן הַהוּא מִתְקַיֵּם זֶה שֶׁל חַיִּים, וְנֶחְלָשׁ אוֹתוֹ שֶׁל הַמָּוֶת. בַּפִּדְיוֹן הַזֶּה קוֹנֶה לוֹ חַיִּים, כְּמוֹ שֶׁנִּתְבָּאֵר. וְאוֹתוֹ הַצַּד הָרָע עוֹזֵב אוֹתוֹ וְלֹא אוֹחֵז בּוֹ."],[5,"","מִצְוָה אַרְבַּע עֶשְׂרֵה - לִשְׁמֹר אֶת יוֹם הַשַּׁבָּת, שֶׁהוּא יוֹם הַמְּנוּחָה מִכָּל מַעֲשֵׂה בְרֵאשִׁית. כָּאן כְּלוּלוֹת שְׁתֵּי מִצְווֹת - אַחַת שְׁמִירַת יוֹם הַשַּׁבָּת, וְאַחַת לְקַדֵּשׁ אוֹתוֹ הַיּוֹם בְּקִדּוּשׁוֹ. לִשְׁמֹר אֶת יוֹם הַשַּׁבָּת, כְּמוֹ שֶׁהִזְכַּרְנוּ וְהֵעַרְנוּ עָלָיו, שֶׁהוּא יוֹם שֶׁל מְנוּחָה לָעוֹלָמוֹת, וְכָל הַמַּעֲשִׂים נִשְׁתַּכְלְלוּ בוֹ וְנַעֲשׂוּ עַד שֶׁהִתְקַדֵּשׁ הַיּוֹם."],[6,"","כֵּיוָן שֶׁהִתְקַדֵּשׁ הַיּוֹם, נִשְׁאֲרָה בְּרִיאָה שֶׁל רוּחוֹת שֶׁלֹּא נִבְרְאוּ לָהֶם גּוּפוֹת. וְכִי לֹא יָדַע הַקָּדוֹשׁ בָּרוּךְ הוּא לְעַכֵּב לְקַדֵּשׁ אֶת הַיּוֹם עַד שֶׁיִּבָּרְאוּ גוּפוֹת לָרוּחוֹת הַלָּלוּ אֶלָּא עֵץ הַדַּעַת טוֹב וָרָע עוֹרֵר אֶת אוֹתוֹ הַצַּד הָאַחֵר שֶׁל הָרָע וְרָצָה לְהִתְחַזֵּק בָּעוֹלָם, וְנִפְרְדוּ כַּמָּה רוּחוֹת בְּכַמָּה מִינִים לְהִתְחַזֵּק בָּעוֹלָם בְּגוּפוֹת."],[7,"","כֵּיוָן שֶׁרָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא כָּךְ, נִתְעוֹרֵר מִתּוֹךְ עֵץ הַחַיִּים נְשִׁיבַת רוּחַ וְהִכָּה בְּאִילָן אַחֵר, וְהִתְעוֹרֵר צַד אַחֵר שֶׁל טוֹב וְהִתְקַדֵּשׁ הַיּוֹם. שֶׁהֲרֵי בְּרִיאַת גּוּפוֹת וְהִתְעוֹרְרוּת רוּחוֹת בַּצַּד הַטּוֹב הִיא בַּלַּיְלָה הַזֶּה, וְלֹא בַּצַּד הָאַחֵר."],[8,"","וְאִלְמָלֵא הִקְדִּים הַצַּד הָאַחֵר בַּלַּיְלָה הַזֶּה טֶרֶם שֶׁיַּקְדִּים צַד הַטּוֹב, לֹא יָכוֹל הָעוֹלָם לַעֲמֹד לִפְנֵיהֶם אֲפִלּוּ רֶגַע אֶחָד. אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא הִקְדִּים רְפוּאָה - שֶׁדִּלֵּג לְפָנָיו קִדּוּשׁ הַיּוֹם, וְהִקְדִּים לִפְנֵי הַצַּד הָאַחֵר, וְהִתְקַיֵּם הָעוֹלָם. וּמַה שֶּׁחָשַׁב הַצַּד הָאַחֵר לְהִבָּנוֹת בָּעוֹלָם לְהִתְחַזֵּק, נִבְנָה בַּלַּיְלָה הַזֶּה צַד הַטּוֹב וְהִתְחַזֵּק, וְנִבְנוּ גוּפוֹת וְרוּחוֹת קְדוֹשׁוֹת בַּלַּיְלָה הַזֶּה מִצַּד הַטּוֹב. וּמִשּׁוּם כָּךְ עוֹנָתָן שֶׁל חֲכָמִים שֶׁיּוֹדְעִים אֶת זֶה מִשַּׁבָּת לְשַׁבָּת."]]],[["דְּהָא כְּדֵין חָמַאת דָּא סִטְרָא אָחֳרָא דְּכַמָּה דְאִיהִי חֲשִׁיבַת לְמֶעְבַּד, עֲבִידֵי (עביד) סִטְרָא דִקְדוּשָׁה. אָזְלָא וּמְשַׁטְּטָא בְּכַמָּה חַיָּילִין וְסִטְרִין דִּילָהּ וְחָמַאת כָּל אִנּוּן דְּקָא מְשַׁמְשֵׁי עַרְסַיְיהוּ בְּגִלּוּיָא דְגוּפֵיהוֹן לִנְהוֹרָא דְּבוּצִינָא, וְכָל אִנּוּן בְּנִין דְּנָפְקִין מִתַּמָּן הֲווּ נִכְפִין דְּשָׁרוּ עֲלַיְיהוּ רוּחִין מֵהַהוּא סִטְרָא אָחֳרָא. וְאִנּוּן רוּחִין עַרְטִילָאִין דְּחַיָּיבַיָא דְּאִקְרוּן מַזִּיקִין וְשָׁרִיאַת בְּהוּ לִילִי\"ת וּקְטִילַת לוֹן.","כֵּיוָן דְּאִתְקַדַּשׁ יוֹמָא וְשָׁלְטָא קְדוּשָׁה עַל עָלְמָא, הַהוּא סִטְרָא אָחֳרָא אַזְעִירַת גַּרְמָהּ וְאִטַּמְרַת כָּל לֵילְיָא דְשַׁבַּתָּא וְיוֹמָא דְשַׁבַּתָּא, בַּר מִן אַסִימוֹ\"ן וְכָל כַּת דִּילֵיהּ דְּאַזְלֵי עַל שְׁרַגֵּי בִּטְמִירוּ לְמֶחמֵי עַל גִּלּוּיֵי דְּשִׁמּוּשָׁא, וּלְבָתַר אִטַּמְּרוּן גּוֹ נוּקְבָא דִּתְהוֹמָא רַבָּא. כֵּיוָן דְּנָפַק שַׁבַּתָּא, כַּמָּה חַיָּילִין וּמַשִּׁרְיָין פָּרְחִין וּמְשַׁטְּטִין בְּעָלְמָא, וְעַל דָּא אִתְקַן שִׁיר שֶׁל פְּגָעִים דְּלָא יִשְׁלְטוּן עַל עַמָּא קַדִּישָׁא.","לְאָן אֲתַר מְשַׁטְּטֵי בְּהַהוּא לֵילְיָא. כַּד נַפְקֵי בִּבְהִילוּ וְחָשְׁבִין לְשַׁלְּטָאָה בְּעָלְמָא עַל עַמָּא קַדִּישָׁא וְחָמָאן לוֹן בִּצְלוֹתָא וְאָמְרִין שִׁירָתָא דָא, וּבְשֵׁירוּתָא מַבְדְּלֵי בִּצְלוֹתָא וּמַבְדְּלֵי עַל הַכּוֹס, פַּרְחֵי מִתַּמָּן וְאָזְלֵי וּמְשָׁטְטֵי וּמָטָאן לְגוֹ מַדְבְּרָא. רַחֲמָנָא לְשֵׁיזְבָן מִנַּיְיהוּ וּמִסִטְרָן (ומסטרא) בִּישָׁא.","אָמְרוּ רַבּוֹתֵינוּ ז\"ל תְּלָתָא אִנּוּן גַּרְמִין בִּישָׁא לְגַרְמַיְיהוּ. חַד מָאן דְּלַיִּיט גַּרְמֵיהּ. תִּנְיָינָא מָאן דְּזָרַק נַהֲמָא אוֹ פֵּרוּרִין דְּאִית בְּהוּ כַּזַּיִת. תְּלִיתָאָה מָאן דְּאוֹקִיד שְׁרַגָּא בְּמִפְקָא דְּשַׁבַּתָּא עַד לָא מָטוּ יִשְׂרָאֵל לְקִדּוּשָׁא דְסִדְרָא דְּגָרִים לְנוּרָא דְּגֵיהִנֹּם לְאַדְלָקָא בְּהַאי נוּרָא עַד לָא מָטָא זִמְנַיְיהוּ.","דְּחַד דּוּכְתָּא אִית בַּגִּיהִנָּם לְאִנּוּן דְּקָא מְחַלְּלֵי שַׁבָּתוֹת, וְאִנּוּן דַּעֲנוּשִׁין בַּגֵיהִנֹּם לַייטִין לֵיהּ לְהַהוּא דְּאוֹקִיד שְׁרַגָּא עַד לָא מָטָא זִמְנֵיהּ, וְאַמְרִי לֵיהּ (ישעיהו כ״ב:י״ז) הִנֵּה יְיָ מְטַלְטֶלְךָ טַלְטֵלָה גָּבֶר וְגו' (ישעיהו כ״ב:י״ח) צָנוֹף יִצְנָפְךָ צְנֵפָה כַּדּוּר אֶל אֶרֶץ רַחֲבַת יָדָיִם.","בְּגִין דְּלָאו יָאוֹת הוּא לְאַדְלָקָא נוּרָא כַּד נָפִיק שַׁבַּתָּא עַד דְּמַבְדְּלֵי יִשְׂרָאֵל בִּצְלוֹתָא וּמַבְדְּלֵי עַל כַּסָּא. בְּגִין דְּעַד הַהוּא זִמְנָא שַׁבָּת הוּא, וּקְדוּשָׁה דְשַׁבָּת שָׁלִיט עֲלָנָא. וּבְשַׁעֲתָא דְמַבְדִּילִין עַל כַּסָּא כָּל אִנּוּן חַיָּילִין וְכָל אִנּוּן מַשִּׁרְיָין דְּאִתְמְנָן עַל יוֹמֵי דְחוֹל, כָּל חַד וְחַד יָתִיב לְאַתְרֵיהּ וּפוּלְחָנֵיהּ דְּאִתְמְנֵי עֲלֵיהּ.","בְּגִין דְּכַד עָאל שַׁבַּתָּא וְאִתְקַדַּשׁ יוֹמָא, קֹדֶשׁ אִתְעַר וְשַׁלִּיט בְּעָלְמָא, וְחוֹל אִתְעַדֵּי מִשּׁוּלְטָנוּתָא דִילֵיהּ, עַד שַׁעֲתָא דְּנָפִיק שַׁבַּתָּא לָא תַיְיבִין לְאַתְרַיְיהוּ. וְאַף עַל גַּב דְּנָפִיק שַׁבַּתָּא לָא תַיְיבִין לְאַתְרַייהוּ עַד זִמְנָא דְאָמְרֵי יִשְׂרָאֵל בָּרוּך אַתָּה יְיָ הַמַּבְדִּיל בֵּין קֹדֶשׁ לְחוֹל. כְּדֵין קֹדֶשׁ אִסְתַּלַּק, וּמַשִּׁרְיָין דְּאִתְמַנִיאוּ עַל יוֹמֵי דְחוֹל מִתְעָרִין וְתַיְיבִין לְאַתְרַייהוּ כָּל חַד וְחַד עַל מַטְרֵיהּ דְּאִתְפְּקַד עֲלֵיהּ.","וְעִם כָּל דָּא לָא שָׁלְטִין עַד דִּיהוֹן נְהוֹרִין מֵרָזָא דִשְׁרַגָא. וְכֻלְהוֹן אִקְרוּן מְאוֹרֵי הָאֵשׁ בְּגִין (דמנהורא דנורא דנגדא) (נ\"א דמרזא דעמודא דנורא) וּמִיסוֹדָא דְנוּרָא אָתְיָאן כֻּלְהוּ וְשָׁלְטִין עַל עַלְמָא תַּתָּאָה. וְכָל דָּא כַּד בַּר נָשׁ אַדְלִיק שְׁרַגָּא עַד לָא שְׁלִימוּ יִשְׂרָאֵל קִדּוּשָׁא דְסִדְרָא.","אֲבָל אִי אִיהוּ מַמְתִּין עַד דְּיַשְׁלִימוּ קִדּוּשָׁא דְסִדְרָא, אִנּוּן חַיָּיבִין דְּגֵיהִנֹּם מַצְדִיקִין עֲלַיְיהוּ דִינָא דְּקוּדְשָׁא בְּרִיךְ הוּא, וְאִנּוּן מְקַיְּימֵי עַל הַהוּא בַּר נָשׁ כָּל בִּרְכָאן דְּקָא אָמְרֵי צִבּוּרָא (בראשית כ״ז:כ״ח) וְיִתֶּן לְךָ הָאֱלֹהִים מִטַּל הַשָּׁמַיִם (דברים כ״ח:ג׳) בָּרוּךְ אַתָּה בָּעִיר וּבָרוּךְ אַתָּה בַּשָּׂדֶה וְגו'. (תהילים מ״א:ב׳) אַשְׁרֵי מַשְׂכִּיל אֶל דָּל בְּיוֹם רָעָה יְמַלְטֵהוּ יְיָ. בְּיוֹם רָע מִבָּעֵי לֵיהּ, מַאי בְּיוֹם רָעָה. יוֹמָא דְּשָׁלְטָא הַהִיא רָעָה לְמֵיסַב נִשְׁמְתֵיהּ.","אַשְׁרֵי מַשְׂכִּיל אֶל דָּל דָּא הוּא שְׁכִיב מְרַע לְאַסָּאָה לֵיהּ מֵחוֹבוֹי גַּבֵּי קוּדְשָׁא בְּרִיךְ הוּא. דָבָר אֲחַר דָּא יוֹמָא דְדִינָא שָׁרְיָא עַל עָלְמָא אִשְׁתְּזִיב מִנֵּיהּ כְּמָה דְאִתְּמָר בְּיוֹם רָעָה יְמַלְטֵהוּ יְיָ. יוֹמָא דְאִתְמָסַר דִּינָא לְהַהוּא רָעָה לְשַׁלְטָאָה עַל עָלְמָא (חסר):"],[[0,"","רנא) \u0003דהא כדין חמאת\u0004 וכו': כי אז, כשראה זה הצד האחר, אשר כמו שהוא רצה לעשות עשה הצד של הקדושה. הוא הולך ומשוטט בכמה חיילות וצדדים שלו, ורואה כל אלו המשמשים מטתם כשהם ערומים, לאור הנר. ולפיכך, כל הבנים הנולדים משם, הם נכפים, משום ששורים עליהם הרוחות מאותו צד האחר. והם הרוחות הערומים של הרשעים, הנקראים מזיקים, ולילית שורה עליהם והורגת אותם."],[1,"","רנב) \u0003כיון דאתקדש יומא\u0004 וכו': כיון שנתקדש היום, והקדושה שולטת על העולם, אותו הצד האחר מקטין את עצמו, ומסתתר בכל ליל השבת ובכל יום השבת. חוץ מן אסימון וכל הכת שלו, שהולכים על הנרות בסתר, לראות את גילוי התשמיש, ולאחר כך הם מסתתרים בתוך נקב תהום רבה. כיון שיצאה השבת, כמה צבאות ומחנות עפים ומשוטטים בעולם. ועל כן נתתקן שיר של פגעים, דהיינו יושב בסתר, שלא ישלטו על עם הקדוש."],[1,"","ביאור המאמר, כי משורת הדין היה הס\"א ביכולת להתלבש בגופין, כנ\"ל, ואלמלי הספיקו להתלבש בגופין, הנה אז היתה הארץ ניתנת ביד רשע, וכל הגופין והתולדות שהיו באים לעולם היו כולם מבחינת הרע דס\"א, ולא היה להם כח להתקן בסטרא דטוב לעולם. וז\"ש \u0003ואלמלא אקדים ס\"א בהאי ליליא, עד דלא יקדים סטרא דטוב, לא יכיל עלמא למיקם קמייהו אפילו רגעא חדא\u0004 כי היתה זוהמתם שולטת על כל התולדות שבעולם, ולא היתה אפשרות להאחז בסטרא דטוב אפילו רגע אחד."],[1,"אבל אסוותא אקדים קב\"ה","אבל הקב\"ה הקדים רפואה לזה, וזהו \u0003דדליג קמיה קדושא דיומא ואקדים קמי ס\"א\u0004 כי דלגה קדושת השבת וקידמה את הס\"א, ונגלה אור השביתה והמנוחה בעולמות, המכניע ומפיל את הס\"א וכל הקליפות לנוקבא דתהומא רבא, \u0003ואתקיים עלמא\u0004 כי עי\"ז נעשתה הזדמנות להוליד גופין ורוחין מ\u0003סטרא דטוב\u0004 בזווגא דלילה דשבתא, ואתקיים עלמא באופן הנרצה."],[1,"","ומה שאומר \u0003דדליג קמיה\u0004 הוא כי כל דבר הבא שלא כסדר מערכת העולמות נקרא בשם דילוג. ומתוך שקדושת השבת באה על ידי אתערותא דלעילא בלבדה, כי האדם עוד לא עשה שום תשובה ותיקון שיהיה ראוי לזה, אלא המאציל עצמו הקדים רפואה לתיקון העולם, לפיכך מכונה זה בשם \u0003דילוג\u0004."],[1,"","וז\"ש (באות ר\"נ) \u0003ומה דחשיב\u0004 וכו': ומה שחשב הס\"א להבנות בעולם ולהתגבר, נבנה בלילה הזה הצד הטוב ונתגבר. כי לילה זה אחר הפגם דעץ הדעת היה שייך משורת הדין רק לבנין הס\"א בכל תוקפו, וכן חשב הס\"א, אמנם היה להיפך, כי מקומו לקחה הקדושה, כי \u0003ואתבנון גופין ורוחין קדישין בהאי ליליא מסטרא דטוב\u0004, ונבנו גופות ורוחות קדושות בלילה הזה מהצד הטוב. כי נעשתה הכנה, שכל המזדווג בהאי לילה הוא ממשיך גופין ורוחין מ\u0003סטרא דטוב\u0004 שאין בהם שום אחיזה לס\"א. דהיינו בהיפך ממש מה שחשב הס\"א."],[1,"","וז\"ש, \u0003ובגין כך עונתן דחכימין דידעי דא משבת לשבת דהא כדין\u0004 וכו': ומשום זה, עונתם של חכמים היודעים זאת, הוא משבת לשבת. כי אז הגופין והרוחין נבנין מסטרא דטוב כנ\"ל, \u0003דהא כדין חמאת דא ס\"א דכמה דאיהי חשיבת למעבד, עבידי סטרא דקדושה\u0004 שהרי אז, כיון שהס\"א רואה זה, שמה שהוא חשב לעשות הקדים ועשה הצד הטוב. כי הוא חשב להבנות ולהתתקף בהאי לילה דשבתא, ולבסוף נבנה הסטרא דקדושה. \u0003אזלא ומשטטא בכמה חיילין וסטרין דילה\u0004 הס\"א הולך ומשוטט בכמה מחנות וצדדים רעים שלה, \u0003וחמאת כל אינון דקא משמשי ערסייהו בגלויא דגופיהון לנהורא דבוצינא\u0004 ורואה כל אלו המשמשים מטותיהם לאור הנר בגילוי הגוף \u0003וכל אינון בנין דנפקין מתמן הוו נכפין\u0004 וכל הבנים הנולדים מהם נלקים בחולי נופל \u0003דשרו עלייהו רוחין מההוא ס\"א, ואינון רוחין ערטילאין דחייביא דאקרון מזיקין\u0004 והס\"א משרה על אלו הבנים רוחות רעות שהם רוחות רשעים הנקראים מזיקין שמחמתם \u0003ושריאת בהון לילית, וקטילת לון\u0004 לילית שורה עליהם והורגתם."],[1,"","אבל כיון \u0003דאתקדש יומא ושלטא קדושה על עלמא\u0004 בעת שמתקדש היום וקדושת השבת שולטת בעולם \u0003ההוא ס\"א אזעירת גרמה ואטמרת כל ליליא דשבתא ויומא דשבתא\u0004 ההוא ס\"א ממעט עצמו ומסתתר בכל הלילה דשבת ויום השבת. וע\"כ אז עונתם של החכמים. \u0003בר מן אסימון וכל כת דיליה דאזלי על שרגי בטמירו למחמי על גילויי דשמושא\u0004 חוץ מן המזיק הנקרא אסימון וכל המחנה שלו, ההולכים עם נרות בסתר לראות בגילוי התשמיש \u0003ולבתר אטמרון גו נוקבא דתהומא רבא\u0004 ואחר זה הם מסתתרים בנוקבא דתהומא רבא. כי אסימון זה אע\"פ שיש לו כח לראות בתשמיש לאור הנר גם בשבת, אמנם אין לו כח להזיק בשבת, אלא מחויב תכף לחזור לנוקבא דתהומא רבא, ורק אחר השבת הוא יכול להזיק."],[1,"","וביאור הדברים. כי ר\"ש הרגיש כאן קושיא על המאמר ד\u0003עונתן דחכימין משבת לשבת\u0004, שהרי בכל יומי בחצות לילה הקב\"ה מטייל עם הצדיקים בג\"ע, \u0003וזווגא אשתכח לחכימי\u0004, ולאו דוקא בלילי דשבת. וקושיא זו הקשה בזהר (ויקהל דף ס\"ה אות קצ\"ד ע\"ש) ולתרץ זה האריך כאן לבאר ההבדל שיש בין זווג דשבת לזווג דחול בענין התשמיש לאור הנר."],[1,"","שלפי פשוטן של הדברים ההפרש הוא, שבלילות חול יש כח לס\"א להלקות הבנים הילודים בחולי נופל, וכן לילית יש לה כח להמיתם. משא\"כ בלילות שבת, הגם שיש מזיק אסימון וכת דיליה שיש לו כח גם בשבת לראות בהם, אבל אין לו כח אז להזיקם רק אחר השבת ויש לזה תיקון גם כן, דהיינו ב\u0003הבדלה דצלותא ובהבדלה על הכוס\u0004, ואז מתבטל כחו של המזיק הזה לגמרי, כמ\"ש להלן. הרי שיש הבדל גדול בין זווגא דליל שבת ללילות חול בחצות לילה."],[1,"","וסודם של הדברים, כי יש \u0003מאורי אור\u0004 שהוא ז\"א, וה\"ס \u0003יחודא עלאה\u0004. ויש \u0003מאורי אש\u0004, שהיא הנוקבא דז\"א(כנ\"ל אות ר\"ט ע\"ש) וה\"ס \u0003יחודא תתאה\u0004 . וג' בחינות יש ב\u0003שלהובא דילה\u0004: הא' הוא \u0003נהורא חוורא\u0004, הב' \u0003נהורא תכלתא\u0004 שמתחת הנהורא חוורא, הג' הוא \u0003דבר גס\u0004 כמו \u0003חלב ושמן ופתילה\u0004 שבו נאחז הנהורא תכלתא. והאי נהורא תכלא, ה\"ס \u0003אש אוכלא אש, דאכיל ושצי כל מה דשריא תחותיה\u0004, כי הוא בחינת הדין שבה, וע\"כ אוכל ומכלה כל מה שמתחתיה, כי היא אוכלת החלב והפתילה שמתאחזת בהם. \u0003נהורא חוורא\u0004 ה\"ס הרחמים שבה, כי לבן הוא רחמים."],[1,"","וז\"ס \u0003המשמש מטתו לאור הנר הוו בניו נכפין\u0004, וכן לילית יכולה להמיתם משום דנהורא תכלא של הנר, שהוא מדת הדין, שורה שם, ויש כח לס\"א להתאחז בזווג, כי ע\"י מדת הדין מתגלים גופיהון, דהיינו בחינת זוהמא דחויא שיש בגופים של המשמשים, ומוצא מין את מינו וניעור."],[1,"","באופן, דמה שהותר הזווג בחצות לילה, היינו דוקא בחושך, שאין שם אור כי אז נאמר במלכות \u0003ותקם בעוד לילה\u0004, והרחמים מתגלים. אבל אם יש שם אור הנר, גורם זה, שתתגלה הזוהמא בגופין והס\"א נאחז בזווג. וז\"ש \u0003וחמאת כל אינון דקא משמשי ערסייא בגילויא דגופיהון לנהורא דבוצינא\u0004 כי ע\"י אור הנר רואה הס\"א גילוי הזוהמא שבגופיהון, ומקטרגת עליהם ונאחז בזווגם, כמבואר."],[1,"","אמנם בליל שבת כל דינין מתעברין מינה, ונהורא דתכלתא מתהפכא ג\"כ לנהורא חוורא, שלפי\"ז היה מותר לשמש גם לאור הנר, ולא עוד אלא אפילו הזוהמא שבגוף האדם נמצאת מתעלמת לגמרי מכח קדושת השבת, ואין פחד עוד מפני גילוי הגוף לאור הנר."],[1,"","לזה אומר \u0003בר מן אסימון וכל כת דיליה דאזלי על שרגי מטמירו למחמי על גילויי דשמושא\u0004 כי אפילו בשבת שנהורא תכלא נעשה לחוורא, ואין שם דין כלל, מ\"מ הכרח הוא שאור הנר צריך לדבר גס להאחז בו, שהיא בחינת דין בהכרח, כי דבר גס הוא עכור ורומז על דינים, אלא בשבת אין צורת דין ניכרת בו, והוא נבחן כמטבע שאין עליו צורה, ולא נודע מה הוא וע\"כ נק' מזיק זה הנרמז בדבר הגס שאור הנר אחוז בו, בשם אסימון, שפירושו מטבע בלי צורה."],[1,"","וז\"ש \u0003דאזלי על שרגי בטמירו\u0004 כי הוא סוד הדבר הגס הנמשך בסתר עם הנר, כי הנר לא היה דולק זולתו כנ\"ל, וע\"כ הוא הרואה גילוי הזווג שעי\"ז הוא יכול להזיקו אחר יציאת השבת. והן אמת שמטעם גילוי דגופיהון אין חשש בליל שבת, כי זוהמא דגוף אינו ניכר בשבת, אמנם אחר השבת יש לו כח לגלות צורת הרע שבו ולהזיקו. (ועיין בזוהר בראשית ב' דף ק\"נ)."],[1,"","ומ\"ש \u0003כיון דנפק שבתא כמה חיילין\u0004 וכו'. פירוש. אע\"פ שבשבת אין אסימון וכת דיליה יכולים להזיק, כי אז אין בו עוד שום צורה של רע, אבל לאחר השבת, הוא והכת דיליה קונים בחזרה את צורתם, ועולים \u0003מתהומא רבא\u0004 אל הישוב, ופורחים ועולים מתהומא רבא ומשוטטים בעולם ויכולים להזיק. וע\"כ נתקן \u0003שיר של פגעים\u0004, שהוא \u0003יושב בסתר עליון\u0004 וגו' שע\"י תשובה ותפלה זו ד\u0003יושב בסתר\u0004 נצולים מהם."],[2,"","רנג) \u0003לאן אתר משטטי\u0004 וכו': לאיזה מקום הם משוטטים באותו ליל מוצאי שבת. הנה כשהם יוצאים בחפזון, וחושבים לשלוט בעולם על עם הקדוש, ורואים אותם עומדים בתפלה ואומרים שירה זו, דהיינו יושב בסתר עליון, ובתחילה מבדילים בתוך התפלה, ואחר כך מבדילים על הכוס, הם עפים משם, והולכים ומשוטטים ומגיעים לתוך המדבר. הרחמן יצילנו מהם ומצד הרע."],[2,"","פירוש. הוא שואל רק על \u0003מוצאי שבת\u0004, ולא על כל לילות החול, כי במוצאי שבת עוד שורה רשימו מקדושת השבת, וע\"כ שואל כיון דכד נפיק שבתא פורחין ועולים מתהומא רבא, לאן אתר הם פורחין. ואומר \u0003כד נפקי בבהילו וחשבין לשלטאה בעלמא\u0004, כשיוצאים מתהומא רבא במהירות וחושבים לשלוט בעולם, \u0003על עמא קדישא\u0004 על ישראל. \u0003וחמאן לון בצלותא ואמרין שירתא דא\u0004 ורואים אותם עומדים בתפלה ואומרים שיר זה של יושב בסתר, \u0003ובשירותא מבדלי בצלותא ומבדלי על הכוס\u0004, ובתחילה הם אומרים הבדלה בתפלה והבדלה על היין, \u0003פרחי מתמן ואזלי ומשטטי ומטאן לגו מדברא\u0004, הם מסתלקים ופורחים מהם והולכים ומשוטטים ומגיעים לתוך המדבר, דהיינו למקום שאין שם ישוב בני אדם, ובני אדם ניצולים מהם."],[2,"","ונמצא ג' בחינות מקומות לס\"א: כי בשבת הם בנוקבא דתהומא רבא, ואין להם כח להזיק כלל. ובמוצאי שבת ע\"י תפלה והבדלה, הם תוך המדבר במקום שאין אדם שם, ונמצא להם כח להזיק אלא שנדחין ממקום ישוב. ובשאר לילות הם נמצאים גם במקום ישוב."],[3,"","רנד) \u0003תלתא אינון גרמין\u0004 וכו': שלשה הם הגורמים רעה לעצמם: אחד מי שמקלל את עצמו. השני, מי שזורק לחם או פירורים שיש בהם כזית. השלישי, מי שמדליק את הנר במוצאי שבת מטרם שבאו ישראל לקדושא דסדרא, שבתוך ואתה קדוש, הנה באותו האש הוא גורם להדליק אש הגיהנם עד שלא הגיע זמנם."],[4,"","רנה) \u0003דחד דוכתא אית\u0004 וכו': כי מקום אחד יש בגיהנם לאותם שמחללים שבתות. ואותם הנענשים בגיהנם מקללים למי שהדליק הנר מטרם שהגיע זמנו, ואמרים לו, הנה ה' מטלטלך טלטלה גבר וגו'. צנוף יצנפך צנפה כדור אל ארץ רחבת ידים."],[4,"","פירוש. יש מזיק אחד הנקרא \u0003רע עין\u0004, והוא אוהב קללה, בסו\"ה \u0003ויאהב קללה ותבואהו ולא חפץ בברכה\u0004 (תהלים קט) וכשאדם מקלל עצמו, נותן בזה כח להאי רע עין האוהב קללה, ושולט עליו, ונמצא גורם רעה לעצמו."],[4,"","וז\"ש, \u0003מאן דזרק נהמא או פרורין דאית בהו כזית\u0004: כי אין לך דבר בעוה\"ז שלא יהיה לו שורש חשוב למעלה, ומכ\"ש לחם, שבו תלויים חייו של האדם, הרי יש לו שורש חשוב מאד למעלה, ולפיכך המזלזל בלחמו גורם פגם בשורש חייו למעלה. וזה מובן לכל אדם רק בסעודה שיש בה שביעה הנותנת לו חיים. אמנם בלחם ופרורין שאין בהם אלא כזית, יש בני אדם המזלזלים בהם וזורקים אותם, משום שאין בהם בחינת שביעה, אמנם כיון שהחמירו חז\"ל לברך ברכת המזון, גם על כזית, ע\"כ יש להחשיבם כמו סעודה שיש בה שביעה, ואסור לזלזל בהם. והמזלזל בהם גורם רעה לעצמו."],[4,"","והענין הוא, כי אמרו חז\"ל (ברכות כ':) אמרו מה\"ש לפני הקב\"ה רבש\"ע כתוב בתורתך אשר לא ישא פנים ולא יקח שחד, והלא אתה נושא פנים לישראל דכתיב ישא ה' פניו אליך, אמר להם וכי לא אשא פנים לישראל שכתבתי להם בתורה, ואכלת ושבעת וברכת את ה' אלהיך, והם מדקדקים על עצמם עד כזית ועד כביצה. הרי שבזכות הדקדוק על כזית, להחשיבו סעודה שיש בה שביעה זוכים שהש\"י נושא לנו פנים אע\"פ שאין אנו כדאים, נמצא כי אלו המזלזלים בפרורין דאית בהו כזית, ואינם מחשיבים אותם בסעודה שיש בה שביעה, אינם זוכים לנשיאת פנים מהש\"י, וגורמים רעה לעצמם (עי' בזוהר ברע\"מ פנחס דף רל\"א אות ת\"ר)."],[4,"","וז\"ש, \u0003מאן דאוקיד שרגא\u0004 וכו': מי שהדליק נר במוצאי שבת טרם שהגיעו ישראל לקדושה דסדרא גורם להדליק אש של גיהנם באותה האש. כי עד האי זמנא שבת הוא, וקדושה דשבת שליט עלנא (כמ\"ש להלן), ואין אש הגיהנם שולטת עוד, כמו בשבת. \u0003ומאן דאוקיד שרגא קודם קדושא דסדרא\u0004, נבחן כמחלל שבת, כי הוא מדליק אש הגיהנם לפני זמנה, וע\"כ גורם רעה לעצמו, \u0003דחד דוכתא אית בגיהנם לאינון דקא מחללי שבתות\u0004, כי חילול שבת הוא החמור ביותר, כי יש בגיהנם מקום מיוחד לענוש מחללי השבת. ועוד \u0003ואינון דענושין בגיהנם לייטין ליה\u0004 והנדונים בגיהנם מקללים אותו על מה שגרם במעשיו להדליק אש הגיהנם קודם זמנה."],[5,"","רנו) \u0003בגין דלאו יאות\u0004 וכו': משום שאינו ראוי להדליק את הנר כשיוצא השבת, מטרם שישראל מבדילים בתפלה, ומבדילים על הכוס, כי עד הזמן ההוא, שבת הוא, וקדושת השבת שולטת עלינו, ובשעת שמבדילים על הכוס, כל אלו הצבאות וכל אלו המחנות הממונים על ימי החול, כל אחד ואחד שב למקומו ולעבודתו שהוא ממונה עליה."],[5,"","פירוש. עיקר האיסור הוא רק עד קדושה דסדרא כנ\"ל, אמנם צריך להזהר שלא ידליק נר עד לאחר הבדלה, כי עד ההוא זמנא נחשב עוד לשבת. אמנם ודאי שמותר להדליק נר לצורך \u0003הבדלה ובורא מאורי האש\u0004. וזה פשוט."],[6,"","רנז) \u0003בגין דכד עאל\u0004 וכו: כי כשנכנסה השבת ונתקדש היום, נתעורר הקדש ושולט בעולם, והחול הוסר משליטתו, ועד השעה שהשבת יוצא אינם שבים למקומם. ואף על פי שיוצא השבת, אינם חוזרים למקומם, עד השעה שאומרים ישראל, בא\"י המבדיל בין קדש לחול. אז הקודש מסתלק, והמחנות שנתמנו על ימי החול, מתעוררים וחוזרים למקומם, כל אחד ואחד על משמרתו אשר הפקד עליו."],[7,"","רנח) \u0003ועם כל דא\u0004 וכו': ועם כל זה אינם שולטים עד שיהיו אורות מסוד אור הנר, שכולם נקראים מאורי האש, משום שמסוד עמוד האש, ומיסוד האש, באים כולם, ושולטים על העולם התחתון. וכל זה כשאדם מדליק את הנר מטרם שגמרו ישראל קדושא דסדרא."],[7,"","פירוש. המלכות נקראת עמודא דנורא (כנ\"ל אות ר\"ט), ואלו כחות שבאור הנר, הם דינים (כנ\"ל ד\"ה ובגין כך עונתן, ע\"ש). ולפיכך אין להם כח לפעול הדינים מטרם שמדליקים את הנר."],[8,"","רנט) \u0003אבל אי איהו\u0004 וכו': אבל אם הוא מחכה, עד שיגמרו קדושא דסדרא, אותם הרשעים שבגיהנם מצדיקים עליהם את הדין של הקב\"ה, והם מקיימים על האדם ההוא, את כל הברכות שאומרים הצבור, דהיינו, ויתן לך האלקים מטל השמים. ברוך אתה בעיר וברוך אתה בשדה וגו'."],[8,"","פירוש. ע\"י אמירת \u0003קדושא דסדרא\u0004 ממשיכים הארה גדולה, שנצולים על ידה מדינה של גיהנם. וכיון שהרשעים שבגיהנם רואים זה, הם מתחרטים על מעשיהם הרעים ומצדיקים עליהם הדין של הקב\"ה, שראוים לעונש שלהם. ומתוך דבר נש ההוא גרם שיצדיקו הדין שלהם ולקדוש שם שמים, נמצאים מקיימים בבר נש ההוא כל הברכות הנאמרות במוצאי שבת בצבור בפסוקים של \u0003ויתן לך האלהים\u0004 וגו'."],[9,"","רס) \u0003אשרי משכיל\u0004 וגו': אשרי משכיל אל דל ביום רעה ימלטהו ה'. היה צריך לומר, ביום רע, מהו ביום רעה. ומשיב, היינו ביום שאותה \u0003רעה\u0004 שולטת לקחת נשמתו. אשרי משכיל אל דל, דל הוא חולה מסוכן, שמשכיל, לרפאהו מחטאיו לפני הקב\"ה. פירוש אחר. זהו יום שהדין שורה בו על העולם, ומשכיל להנצל ממנו, כמו שנאמר, ביום \u0003רעה\u0004 ימלטהו ה'. דהיינו ביום שנמסר הדין \u0003לרעה\u0004 ההיא לשלוט על העולם, ימלטהו ה'."],[9,"","פירוש. מקשה שהיה לו לכתוב לומר ביום רע ימלטהו ה', ולמה אומר ביום רעה, שהוא לשון נקבה. אלא שהכתוב רומז שליטת הקליפה הנקראת רעה הנוטלת נשמתו של אדם. והמשכיל אל דל שפירושו שמדבר לחולה לשוב בתשובה, הרי הקב\"ה ממלט אותו משליטת הקליפה שנק' רעה."],[9,"","והזהר מביא כאן זה משום שאומר לעיל תלתא אינון דגרמין בישא על נפשיה, שגורמים לעצמם רעה. ולכן מביא כאן עצה לזה, \u0003שישכיל אל דל\u0004, שידבר על לב חולה שישוב בתשובה \u0003וירפאהו ה'\u0004, ובשכר זה ימלטהו ה' מיום רעה, דגרם לנפשיה. \u0003דבר אחר דא יומא דדינא שריא על עלמא אשתזיב מיניה\u0004 שאפילו יומא דדינא שריא על כל העולם \u0003ימלטהו ה'\u0004, בשכר שהשכיל אל החולה להחזירהו בתשובה. כי \u0003יום רעה\u0004 פירושו \u0003יומא דאתמסר דינא לההוא רעה לשלטאה על עלמא\u0004 ביום שכבר נמסר הדין לההוא ממונה הנקרא רעה שישלוט על העולם, ועם כל זה אותו שישכיל אל החולה להחזירהו בתשובה \u0003ימלטהו ה' מההוא רעה\u0004. וההפרש מב' הפרושים הוא, כי לפירוש הא' קאי רק על יחיד שגרם לעצמו רעה. ולפירוש הב' קאי גם על הרעה שנגזר על כל העולם, וגם אז \u0003ימלטהו ה'\u0004 בזכות המצוה הנ\"ל."]],[[0,"","שֶׁהֲרֵי אָז רוֹאָה אֶת זֶה הַצַּד הָאַחֵר, שֶׁכְּמוֹ שֶׁהִיא חָשְׁבָה לַעֲשׂוֹת - עָשְׂתָה צַד שֶׁל הַקְּדֻשָּׁה. הוֹלֶכֶת וּמְשׁוֹטֶטֶת בְּכַמָּה צְבָאוֹת וְהַצְּדָדִים שֶׁלָּהּ, וְרוֹאָה אֶת כָּל אוֹתָם שֶׁמְּשַׁמְּשִׁים אֶת מִטָּתָם בְּגִלּוּי שֶׁל גּוּפָם לְאוֹר הַנֵּר, וְכָל אוֹתָם הַבָּנִים שֶׁיּוֹצְאִים מִשָּׁם הֵם נִכְפִּים, שֶׁהָיוּ שְׁרוּיִים עֲלֵיהֶם רוּחוֹת מֵהַצַּד הָאַחֵר הַהוּא. וְאוֹתָם הָרוּחוֹת הָעַרְטִילָאִיּוֹת שֶׁל הָרְשָׁעִים שֶׁנִּקְרָאִים מַזִּיקִים, וְשׁוֹרָה בָהֶם לִילִי\"ת וְהוֹרֶגֶת אוֹתָם."],[1,"","כֵּיוָן שֶׁהִתְקַדֵּשׁ הַיּוֹם וְהַקְּדֻשָּׁה שׁוֹלֶטֶת עַל הָעוֹלָם, אוֹתוֹ הַצַּד הָאַחֵר מַקְטִין עַצְמוֹ וְנִטְמָן כָּל לֵיל שַׁבָּת וְיוֹם הַשַּׁבָּת, פְּרָט לְאָסִימוֹ\"ן, וְכָל הַכַּת שֶׁלּוֹ שֶׁהוֹלְכִים עַל הַנֵּרוֹת בַּסֵּתֶר לִרְאוֹת אֶת הַגִּלּוּיִים שֶׁל הַתַּשְׁמִישִׁים, וְאַחַר כָּךְ נִטְמָנִים בְּתוֹךְ נֶקֶב הַתְּהוֹם הַגָּדוֹל. כֵּיוָן שֶׁיָּצְאָה הַשַּׁבָּת, כַּמָּה צְבָאוֹת וּמַחֲנוֹת פּוֹרְחִים וּמְשׁוֹטְטִים בָּעוֹלָם, וְעַל כֵּן תֻּקַּן שִׁיר שֶׁל פְּגָעִים שֶׁלֹּא יִשְׁלְטוּ עַל הָעָם הַקָּדוֹשׁ."],[2,"","לְאֵיזֶה מָקוֹם מְשׁוֹטְטִים בַּלַּיְלָה הַהוּא כְּשֶׁיּוֹצְאִים בְּחִפָּזוֹן וְחוֹשְׁבִים לִשְׁלֹט בָּעוֹלָם עַל הָעָם הַקָּדוֹשׁ, וְרוֹאִים אוֹתָם בַּתְּפִלָּה וְאוֹמְרִים אֶת הַשִּׁירָה הַזּוֹ, וּבְרֵאשִׁית מַבְדִּילִים בַּתְּפִלָּה וּמַבְדִּילִים עַל הַכּוֹס, פּוֹרְחִים מִשָּׁם וְהוֹלְכִים וּמְשׁוֹטְטִים וּמַגִּיעִים לְתוֹךְ הַמִּדְבָּר. הָרַחֲמָן יַצִּילֵנוּ מֵהֶם וּמֵהַצְּדָדִים הָרָעִים."],[3,"","אָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה, שְׁלֹשָׁה הֵם שֶׁגּוֹרְמִים רָעָה לְעַצְמָם: אֶחָד - מִי שֶׁמְּקַלֵּל אֶת עַצְמוֹ. הַשֵּׁנִי - מִי שֶׁזּוֹרֵק לֶחֶם אוֹ פֵרוּרִים שֶׁיֵּשׁ בָּהֶם כַּזַּיִת. הַשְּׁלִישִׁי - מִי שֶׁמַּדְלִיק נֵר בְּמוֹצָאֵי שַׁבָּת בְּטֶרֶם שֶׁמַּגִּיעִים יִשְׂרָאֵל לִקְדֻשָּׁה דְסִדְרָא, שֶׁגּוֹרֵם לְאֵשׁ הַגֵּיהִנֹּם לְהִדָּלֵק בָּאֵשׁ הַזּוֹ טֶרֶם שֶׁהִגִּיעַ זְמַנָּם."],[4,"","שֶׁמָּקוֹם אֶחָד יֵשׁ בַּגֵּיהִנֹּם לְאוֹתָם שֶׁמְּחַלְלִים שַׁבָּתוֹת, וְאוֹתָם שֶׁעֲנוּשִׁים בַּגֵּיהִנֹּם מְקַלְלִים אֶת אוֹתוֹ שֶׁהִדְלִיק נֵר טֶרֶם שֶׁהִגִּיעַ זְמַנּוֹ, וְאוֹמְרִים לוֹ: (ישעיה כב) הִנֵּה ה' מְטַלְטֶלְךְ טַלְטֵלָה גָּבֶר וְגוֹ', (שם) צָנוֹף יִצְנָפְךְ צְנֵפָה כַּדּוּר אֶל אֶרֶץ רַחֲבַת יָדָיִם."],[5,"","מִשּׁוּם שֶׁאֵין רָאוּי הוּא לְהַדְלִיק אֵשׁ כְּשֶׁיּוֹצֵאת שַׁבָּת עַד שֶׁיִּשְׂרָאֵל מַבְדִּילִים בַּתְּפִלָּה וּמַבְדִּילִים עַל הַכּוֹס, מִשּׁוּם שֶׁעַד אוֹתוֹ הַזְּמַן שַׁבָּת הִיא, וּקְדֻשַּׁת הַשַּׁבָּת שׁוֹלֶטֶת עָלֵינוּ. וּבְשָׁעָה שֶׁמַּבְדִּילִים עַל הַכּוֹס, כָּל אוֹתָם הַחֲיָלוֹת וְכָל אוֹתָם הַמַּחֲנוֹת שֶׁהִתְמַנּוּ עַל יְמוֹת הַחֹל, כָּל אֶחָד וְאֶחָד יָשׁוּב לִמְקוֹמוֹ וְלַעֲבוֹדָתוֹ שֶׁהִתְמַנָּה עָלֶיהָ."],[6,"","מִשּׁוּם שֶׁכְּשֶׁנִּכְנְסָה שַׁבָּת וְהִתְקַדֵּשׁ הַיּוֹם, הַקֹּדֶשׁ מִתְעוֹרֵר וְשׁוֹלֵט בָּעוֹלָם, וְהַחֹל מִתְבַּטֵּל שִׁלְטוֹנוֹ, עַד הַשָּׁעָה שֶׁיּוֹצֵאת הַשַּׁבָּת לֹא שָׁבִים לִמְקוֹמָם. וְאַף עַל גַּב שֶׁיּוֹצֵאת שַׁבָּת, לֹא שָׁבִים לִמְקוֹמָם עַד הַזְּמַן שֶׁיִּשְׂרָאֵל אוֹמְרִים בָּרוּךְ אַתָּה יי' הַמַּבְדִּיל בֵּין קֹדֶשׁ לְחֹל. אָז הַקֹּדֶשׁ מִסְתַּלֵּק, וְהַמַּחֲנוֹת שֶׁהִתְמַנּוּ עַל יְמוֹת הַחֹל מִתְעוֹרְרִים וְשָׁבִים לִמְקוֹמָם, כָּל אֶחָד וְאֶחָד עַל מִשְׁמַרְתּוֹ שֶׁהֻפְקַד עָלֶיהָ."],[7,"","וְעִם כָּל זֶה לֹא שׁוֹלְטִים עַד שֶׁיִּהְיוּ אוֹרוֹת מִסּוֹד הַנֵּר. וְכֻלָּם נִקְרָאִים מְאוֹרֵי הָאֵשׁ, מִשּׁוּם (שמאור האש ששופע) (נ\"א שמסוד עמוד האש) וּמִיסוֹד הָאֵשׁ בָּאִים כֻּלָּם וְשׁוֹלְטִים עַל הָעוֹלָם הַתַּחְתּוֹן. וְכָל זֶה כְּשֶׁאָדָם מַדְלִיק נֵר טֶרֶם הִשְׁלִימוּ יִשְׂרָאֵל אֶת הַקְּדֻשָּׁה דְּסִדְרָא."],[8,"","אֲבָל אִם הוּא מַמְתִּין עַד שֶׁיַּשְׁלִימוּ קְדֻשָּׁה דְסִדְרָא, אוֹתָם הָרְשָׁעִים שֶׁבַּגֵּיהִנֹּם מַצְדִּיקִים עֲלֵיהֶם אֶת דִּינוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהֵם מְקַיְּמִים עַל אוֹתוֹ הָאִישׁ כָּל הַבְּרָכוֹת שֶׁאוֹמְרִים הַצִּבּוּר (בראשית כז) וְיִתֶּן לְךְ הָאֱלֹהִים מִטַּל הַשָּׁמַיִם (דברים כח) בָּרוּךְ אַתָּה בָּעִיר וּבָרוּךְ אַתָּה בַּשָּׂדֶה וְגוֹ'. (תהלים מא) אַשְׁרֵי מַשְׂכִּיל אֶל דָּל בְּיוֹם רָעָה יְמַלְּטֵהוּ ה'. בְּיוֹם רַע הָיָה צָרִיךְ לִהְיוֹת, מַה זֶּה בְּיוֹם רָעָה הַיּוֹם שֶׁשּׁוֹלֶטֶת הָרָעָה הַהִיא לָקַחַת אֶת נִשְׁמָתוֹ."],[9,"","אַשְׁרֵי מַשְׂכִּיל אֶל דָּל - זֶהוּ שְׁכִיב מְרַע לְרַפְּאוֹ מֵחֶטְאוֹ אֵצֶל הַקָּדוֹשׁ בָּרוּךְ הוּא. דָּבָר אַחֵר - זֶה הַיּוֹם שֶׁהַדִּין שׁוֹרֶה עַל הָעוֹלָם, נִצּוֹל מִמֶּנּוּ, כְּמוֹ שֶׁנֶּאֱמַר בְּיוֹם רָעָה יְמַלְּטֵהוּ ה'. הַיּוֹם שֶׁנִּמְסָר הַדִּין לְאוֹתָהּ רָעָה לִשְׁלֹט עַל הָעוֹלָם."]]]]};
